/* takken-data-original.js — ORIG_QUESTIONS 等 · from 解説あり */
// ===== ORIGINAL MOCK TEST DATA =====
const ORIG_QUESTIONS = {
1:[
  {id:10001,unit:'r_ishi',level:1,field:'rights',text:'未成年者が法定代理人の同意なく行った売買契約の効力として正しいものはどれか。',opts:['当初から無効である','法定代理人が取り消すことができる','相手方が取り消すことができる','誰も取り消すことができない'],ans:1,exp:'未成年者が同意なく行った契約は「取り消しうる行為」で、未成年者本人または法定代理人（親等）が取り消せます（民法5条2項）。当初から無効ではなく、取り消されるまでは有効です。追認すれば確定的に有効になります。',"kaisetsu":{"topic": "未成年者の行為：取消しうる行為・取消権者は本人または法定代理人", "basis": {"text": "未成年者が法定代理人の同意なく行った法律行為は「取消しうる行為」です（民法5条2項）。当初から無効ではなく、取消しがされるまでは一応有効な状態です。", "example": "17歳のAが親の同意なく高価な時計を購入した場合、その売買契約はAの親（法定代理人）が取り消すことができます。取り消すと遡って無効になります。"}, "reason": {"text": "未成年者は判断能力が不十分なため保護が必要です。ただし「無効」にすると取引の安定が損なわれるため、取り消されるまでは有効・取消しで遡及無効となる柔軟な仕組みにしています。取消権者は本人または法定代理人に限定されます。"}, "svg": "<svg viewBox=\"0 0 620 275\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">未成年者の行為の効果</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"275\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">行為の効果</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消しうる行為（無効ではない）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消権者</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人・法定代理人（民法120条1項）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消後の効果</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遡って無効（民法121条）</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定的に有効になる</text><rect x=\"10\" y=\"225\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">例外（取消不可）</text><text x=\"445\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">日常行為・権利取得・義務免除等（民法5条1項ただし書）</text></svg>", "choices": [{"label": "当初から無効である", "reason": "無効は最初から効力が生じませんが、未成年者の行為は取消しがなされるまで有効として扱われます（民法5条2項）。", "caution": "無効＝最初から効力なし、取消し＝取り消されるまで有効。この区別は必須です。"}, {"label": "相手方が取り消すことができる", "reason": "取消権は未成年者本人・法定代理人のみにあります（民法120条1項）。相手方には取消権がありません。", "caution": "相手方は「催告権（確答を求める権利）」を持ちますが、取消権は持ちません。"}, {"label": "誰も取り消すことができない", "reason": "未成年者本人・法定代理人（親権者・後見人）が取り消せます（民法5条2項・120条1項）。誰も取り消せないというのは誤りです。", "caution": ""}], "summary": {"head": ["主体", "取消権の有無", "備考"], "rows": [["本人（未成年者）", "あり", "能力回復後も可"], ["法定代理人", "あり", "親権者・後見人"], ["相手方", "なし", "催告権のみ"], ["追認権者", "—", "本人・法定代理人"]]}}},
  {id:10002,unit:'r_bukken',level:1,field:'rights',text:'土地の売買でAがBに売った後Cにも売った二重売買の場合、所有権を取得できるのは誰か。',opts:['先に契約したB','後から契約したC','先に登記を備えた方','価格が高い方'],ans:2,exp:'不動産の二重売買では先に登記（法務局での正式な記録）を備えた者が所有権を取得できます（民法177条）。契約の締結時期や価格は関係ありません。',"kaisetsu":{"topic": "二重売買：先に登記を備えた者が所有権を取得", "basis": {"text": "不動産の物権変動（所有権移転等）は登記をしなければ第三者に対抗できません（民法177条）。二重売買では先に登記を備えた者が所有権を取得します。契約の先後は関係ありません。", "example": "AがBに土地を売り、その後同じ土地をCにも売った。Cが先に登記を備えれば、Bより先に契約していてもCが所有者となります。"}, "reason": {"text": "民法177条は「不動産に関する物権の得喪及び変更は、その登記をしなければ第三者に対抗することができない」と定めます。ただし背信的悪意者（不当な目的で登記を取得した者）には対抗できます（判例）。不法占拠者には登記なく対抗できます（判例）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">二重売買の解決</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先契約・後登記（B）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">所有権を取得できない</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">後契約・先登記（C）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">所有権を取得できる</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">背信的悪意者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記があっても保護なし（判例）</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不法占拠者</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記なく対抗可（判例）</text></svg>", "choices": [{"label": "先に契約したB", "reason": "契約の先後ではなく登記の先後で優劣が決まります（民法177条）。先に契約しても登記が遅ければ所有権を取得できません。", "caution": "「契約が先＝勝ち」ではなく「登記が先＝勝ち」が原則です。"}, {"label": "後から契約したC", "reason": "Cが後から契約しても先に登記を備えれば所有権を取得できます（民法177条）。", "caution": ""}, {"label": "先に登記を備えた方", "reason": "正解です。二重売買では先に登記を備えた者が所有権を取得します（民法177条）。", "caution": ""}, {"label": "価格が高い方", "reason": "価格の大小は所有権の帰属に全く関係ありません。", "caution": ""}], "summary": {"head": ["場面", "結論"], "rows": [["二重売買", "先に登記した者が所有権取得"], ["背信的悪意者", "登記があっても保護なし"], ["不法占拠者", "登記なく対抗可"]]}}},
  {id:10003,unit:'r_tanpo',level:1,field:'rights',text:'抵当権について正しいものはどれか。',opts:['目的物の占有を抵当権者に移す必要がある','設定者は目的物を使い続けることができる','登記がなければ当事者間でも効力が生じない','農地にも常に自由に設定できる'],ans:1,exp:'抵当権は「非占有担保物権」で、設定者（借主）はそのまま住み続けたり使い続けたりできます（民法369条）。占有を移す必要はありません。登記は第三者対抗要件であり、当事者間では登記なくても成立します。',"kaisetsu":{"topic": "抵当権：非占有担保・設定者は使用継続可・登記は対抗要件", "basis": {"text": "抵当権は「非占有担保物権」です。設定者（担保に入れる不動産の所有者）は目的物を占有・使用し続けることができます（民法369条）。住宅ローンの担保として自宅を抵当に入れても、返済中は住み続けられます。", "example": "Aが自宅を担保（抵当権設定）にしてBから1,000万円を借りた。AはBに鍵を渡す必要はなく、ローンを返済している間は自宅に住み続けることができます。"}, "reason": {"text": "抵当権は当事者間の合意で成立し、登記は第三者への対抗要件です（民法177条）。当事者間では登記なしでも有効に成立します。農地への抵当権設定自体は、通常、農地法3条の許可対象ではありませんです（農地法3条）。ただし抵当権実行により所有権移転が生じる段階では、農地法上の許可等が問題になります。"}, "svg": "<svg viewBox=\"0 0 620 275\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">抵当権のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"275\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">性質</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非占有担保（設定者が使用継続可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">成立要件</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">当事者間の合意（書面）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">対抗要件</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記（第三者への主張に必要）</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農地への設定</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会の許可が必要</text><rect x=\"10\" y=\"225\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">実行方法</text><text x=\"445\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">競売または担保不動産収益執行</text></svg>", "choices": [{"label": "目的物の占有を抵当権者に移す必要がある", "reason": "抵当権は非占有担保なので占有を移す必要はありません。占有が必要なのは質権です。", "caution": "「抵当権→占有不要（設定者が使用継続）」「質権→占有必要（質権者が占有）」という対比を覚えてください。"}, {"label": "設定者は目的物を使い続けることができる", "reason": "正解です。抵当権は非占有担保であり、設定者はローン返済中も不動産を使用し続けることができます（民法369条）。", "caution": ""}, {"label": "登記がなければ当事者間でも効力が生じない", "reason": "抵当権は当事者間の合意で成立し、登記は第三者への対抗要件です（民法177条）。当事者間では登記なしでも有効です。", "caution": "「登記→対抗要件（第三者への主張に必要）」「効力発生要件（成立に必要）ではない」が物権法の基本原則です。"}, {"label": "農地にも常に自由に設定できる", "reason": "農地への抵当権設定自体は、通常、農地法3条の許可対象ではありませんです（農地法3条）。「常に自由に」は誤りです。", "caution": ""}], "summary": {"head": ["項目", "内容"], "rows": [["性質", "非占有担保（設定者が使用継続）"], ["成立", "当事者の合意"], ["対抗要件", "登記"], ["農地への設定", "農業委員会の許可が必要"]]}}},
  {id:10004,unit:'r_souzoku',level:1,field:'rights',text:'相続で配偶者Bと子C・Dがいる場合、配偶者Bの法定相続分はいくらか。',opts:['3分の1','3分の2','2分の1','4分の3'],ans:2,exp:'配偶者と子が相続人の場合、配偶者の法定相続分は2分の1で、子全体で残りの2分の1を均等に分けます（民法900条）。',"kaisetsu":{"topic": "法定相続分：配偶者+子は各1/2", "basis": {"text": "配偶者と子が相続人の場合、配偶者の法定相続分は2分の1、子全体で残りの2分の1を均等に分けます（民法900条1号）。", "example": "Aが死亡し、配偶者Bと子C・Dが相続人となった。配偶者Bが1/2、子C・Dが1/4ずつとなります（子2人で1/2を均等分割）。"}, "reason": {"text": "法定相続分の3パターン：①配偶者+子→各1/2　②配偶者+直系尊属（父母等）→2/3：1/3　③配偶者+兄弟姉妹→3/4：1/4。この3つを確実に覚えることが重要です。兄弟姉妹に遺留分はありません（民法1042条）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">法定相続分</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">相続人の組み合わせ</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">配偶者</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">その他</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者＋子</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1/2</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1/2（子で均等分割）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者＋直系尊属（父母等）</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2/3</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1/3</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者＋兄弟姉妹</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3/4</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1/4</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">子のみ（配偶者なし）</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">—</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全部（均等分割）</text></svg>", "choices": [{"label": "3分の1", "reason": "配偶者+子の場合、配偶者の相続分は1/2です。1/3は配偶者+直系尊属（父母等）の場合の直系尊属の相続分です。", "caution": "組み合わせと数字を正確に覚えてください。"}, {"label": "3分の2", "reason": "2/3は配偶者+直系尊属の場合の配偶者の相続分です。配偶者+子の場合は1/2が正解です。", "caution": ""}, {"label": "2分の1", "reason": "正解です。配偶者と子が相続人の場合、配偶者の法定相続分は1/2です（民法900条1号）。", "caution": ""}, {"label": "4分の3", "reason": "3/4は配偶者+兄弟姉妹の場合の配偶者の相続分です。配偶者+子の場合は1/2が正解です。", "caution": ""}], "summary": {"head": ["組み合わせ", "配偶者の相続分"], "rows": [["配偶者+子", "1/2"], ["配偶者+直系尊属", "2/3"], ["配偶者+兄弟姉妹", "3/4"], ["子のみ（配偶者なし）", "全部"]]}}},
  {id:10005,unit:'l_menkyo',level:1,field:'law',text:'宅地建物取引業の免許について正しいものはどれか。',opts:['有効期間は3年である','1都道府県内のみに事務所があれば都道府県知事の免許が必要','法人は免許を取得できない','更新申請は期間満了後でも受け付ける'],ans:1,exp:'1つの都道府県内にのみ事務所がある場合は都道府県知事の免許が必要です（宅建業法3条）。免許の有効期間は5年です。法人も免許を取得できます。',"kaisetsu":{"topic": "宅建業免許：1都道府県は知事免許・有効期間5年・更新は90日前〜30日前", "basis": {"text": "1つの都道府県内のみに事務所を設置する場合はその都道府県知事の免許が必要です（宅建業法3条1項）。2以上の都道府県に事務所がある場合は国土交通大臣の免許が必要です。", "example": "東京都のみに事務所があるA社→東京都知事免許。東京都と大阪府に事務所があるB社→国土交通大臣免許。"}, "reason": {"text": "免許の有効期間は5年です（宅建業法3条2項）。更新申請は有効期間満了の90日前から30日前の間に行います。法人（株式会社等）も免許を取得できます（個人限定ではない）。2以上の都道府県に事務所を追加する場合は、届出では済まず大臣免許への変更が必要です。"}, "svg": "<svg viewBox=\"0 0 620 275\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"275\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県のみ</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">国土交通大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">更新申請</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">満了90日前〜30日前</text><rect x=\"10\" y=\"225\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取得者</text><text x=\"445\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">個人・法人どちらも可</text></svg>", "choices": [{"label": "有効期間は3年である", "reason": "宅建業の免許の有効期間は5年です（宅建業法3条2項）。3年は誤りです。", "caution": "「宅建業免許→5年」「宅建士証→5年」どちらも5年です。"}, {"label": "1都道府県内のみに事務所があれば都道府県知事の免許が必要", "reason": "正解です。1都道府県内のみに事務所がある場合は当該都道府県知事の免許が必要です（宅建業法3条1項）。", "caution": ""}, {"label": "法人は免許を取得できない", "reason": "法人（株式会社・合同会社等）も宅建業の免許を取得できます。個人に限定されていません。", "caution": ""}, {"label": "更新申請は期間満了後でも受け付ける", "reason": "更新申請は有効期間満了の90日前から30日前の間に行わなければなりません。期間満了後の申請は受け付けられません。", "caution": ""}], "summary": {"head": ["項目", "内容"], "rows": [["1都道府県", "知事免許"], ["2以上の都道府県", "大臣免許"], ["有効期間", "5年"], ["更新申請", "満了90日前〜30日前"]]}}},
  {id:10006,unit:'l_jusetsu',level:1,field:'law',text:'重要事項説明（35条書面）を行えるのは誰か。',opts:['宅建業者の代表者なら誰でも','宅建士の資格を持つ者','宅建業者に雇用された者なら誰でも','弁護士'],ans:1,exp:'重要事項説明は「宅建士」が宅建士証を提示して行わなければなりません（宅建業法35条）。代表者や一般従業員が行うことはできません。',"kaisetsu":{"topic": "重要事項説明：宅建士が宅建士証を提示して行う", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示した上で行わなければなりません（宅建業法35条1項・4項）。宅建士の資格を持つ者のみが説明できます。代表者・一般従業員・弁護士であっても宅建士でなければ説明できません。", "example": "A不動産（宅建業者）の営業担当Bが重要事項説明をする場合、BはB自身の宅建士証を相手方に提示してから説明を行う必要があります。"}, "reason": {"text": "2021年の法改正でIT重説（テレビ会議等によるオンライン説明）が可能になりました（相手方の承諾が必要）。相手方が宅建業者の場合は説明を省略できますが書面の交付は省略できません（宅建業法35条6項）。宅建士証の提示は求められなくても自発的に行う義務があります。"}, "svg": "<svg viewBox=\"0 0 620 275\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"275\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士（宅建士証の提示が必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主への交付は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">IT重説</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方承諾があれば可（2021年改正）</text><rect x=\"10\" y=\"225\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">押印</text><text x=\"445\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（記名のみ・2021年改正）</text></svg>", "choices": [{"label": "宅建業者の代表者なら誰でも", "reason": "代表者であっても宅建士でなければ重要事項説明はできません。宅建士のみが説明できます。", "caution": "「重要事項説明→宅建士のみが説明可」が絶対のルールです。"}, {"label": "宅建士の資格を持つ者", "reason": "正解です。重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条1項・4項）。", "caution": ""}, {"label": "宅建業者に雇用された者なら誰でも", "reason": "宅建業者に雇用されていても宅建士でなければ重要事項説明はできません。", "caution": ""}, {"label": "弁護士", "reason": "弁護士であっても宅建士でなければ宅建業法上の重要事項説明はできません。", "caution": ""}], "summary": {"head": ["項目", "内容"], "rows": [["説明できる者", "宅建士のみ（宅建士証の提示必須）"], ["交付先", "買主・借主（売主・貸主は不要）"], ["相手方が業者", "説明省略可・書面交付は必要"], ["IT重説", "相手方承諾で可"]]}}},
  {id:10007,unit:'l_cooling',level:1,field:'law',text:'クーリングオフができる期間として正しいものはどれか。',opts:['契約締結後3日以内','告知を受けた日から8日以内','告知を受けた日から14日以内','引渡しを受けるまでいつでも'],ans:1,exp:'クーリングオフは告知を受けた日から8日以内に書面で行う必要があります（宅建業法37条の2）。告知がなければ期間が始まりません。',"kaisetsu":{"topic": "クーリングオフ：告知日から8日以内・書面（発信主義）", "basis": {"text": "クーリングオフによる解除は「告知を受けた日から8日以内に書面で」行わなければなりません（宅建業法37条の2第1項）。書面を発送した時点で解除の効力が生じます（発信主義）。", "example": "買主AがX書面（クーリングオフ告知書面）を受け取った日が7月1日。7月8日（8日目）までに書面を発送すれば有効にクーリングオフできます。"}, "reason": {"text": "8日間の起算点は「クーリングオフについての告知を受けた日」です。「契約締結日」ではありません。告知がなければ期間が始まらないため永久にクーリングオフできる状態が続きます。引渡しを受けかつ代金全額を支払った後はクーリングオフできません（同条1項但書）。"}, "svg": "<svg viewBox=\"0 0 620 315\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">クーリングオフのポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"315\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">方法</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面のみ（口頭不可）・発信主義</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">告知を受けた日から8日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">起算点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">「告知日」（契約締結日ではない）</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">告知がない場合</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間が始まらない（永久にOF可）</text><rect x=\"10\" y=\"225\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除不可</text><text x=\"445\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡し＋代金全額支払い後（両方必要）</text><rect x=\"10\" y=\"265\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"290\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除後</text><text x=\"445\" y=\"290\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者は費用控除なしで全額返還</text></svg>", "choices": [{"label": "契約締結後3日以内", "reason": "期間は8日間で起算点は「告知日」です。「契約締結後3日」は誤りです。", "caution": "「告知日から8日以内」を確実に覚えてください。"}, {"label": "告知を受けた日から8日以内", "reason": "正解です。クーリングオフは告知を受けた日から8日以内に書面で行います（宅建業法37条の2第1項）。", "caution": ""}, {"label": "告知を受けた日から14日以内", "reason": "8日以内が正解です。14日は誤りです。", "caution": ""}, {"label": "引渡しを受けるまでいつでも", "reason": "引渡しを受けかつ代金全額を支払った後はクーリングオフできません。また8日間の期間制限もあります。", "caution": "「引渡し」と「代金全額支払い」の両方が揃った時に解除不可となります。片方だけでは解除できます。"}], "summary": {"head": ["項目", "内容"], "rows": [["期間", "告知日から8日以内"], ["方法", "書面（発信主義）"], ["解除不可の条件", "引渡し＋全額支払い後（両方必要）"], ["解除後", "業者は全額返還（費用控除不可）"]]}}},
  {id:10008,unit:'l_baikai',level:1,field:'law',text:'専任媒介契約の有効期間の上限として正しいものはどれか。',opts:['1か月','2か月','3か月','6か月'],ans:2,exp:'専任媒介・専属専任媒介の有効期間の上限は3か月です（宅建業法34条の2）。',"kaisetsu":{"topic": "専任媒介契約の有効期間：最長3か月・依頼者からの申し出で更新可", "basis": {"text": "専任媒介契約および専属専任媒介契約の有効期間の上限は3か月です（宅建業法34条の2第3項）。3か月を超える期間を定めても3か月とみなされます。", "example": "売主AがB不動産と専任媒介契約を結ぶ場合、契約期間は最長3か月です。Aの申し出により更新できますが、B不動産（業者側）から申し出て更新することはできません。"}, "reason": {"text": "有効期間の更新は依頼者（売主等）からの申し出のみ可能で、業者側から申し出て更新することはできません（宅建業法34条の2第4項）。一般媒介契約には有効期間の法的制限はありません。専任媒介はレインズへの登録が「契約日から7日以内」、専属専任媒介は「5日以内」です（宅建業法34条の2第5項・6項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の有効期間と義務</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">有効期間</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">レインズ登録</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">業務報告</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般媒介</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">制限なし</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">規定なし</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専任媒介</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">最長3か月</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間に1回以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専属専任媒介</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">最長3か月</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1週間に1回以上</text></svg>", "choices": [{"label": "1か月", "reason": "専任媒介の有効期間の上限は3か月です（宅建業法34条の2第3項）。1か月は誤りです。", "caution": ""}, {"label": "2か月", "reason": "上限は3か月です。2か月は誤りです。", "caution": ""}, {"label": "3か月", "reason": "正解です。専任媒介契約の有効期間の上限は3か月です（宅建業法34条の2第3項）。", "caution": ""}, {"label": "6か月", "reason": "上限は3か月です。6か月は誤りです。", "caution": "「一般媒介→制限なし」「専任・専属専任→最長3か月」という区別を覚えてください。"}], "summary": {"head": ["種類", "有効期間", "レインズ登録"], "rows": [["一般", "制限なし", "不要"], ["専任", "最長3か月", "7日以内"], ["専属専任", "最長3か月", "5日以内"]]}}},
  {id:10009,unit:'k_kenchiku',level:1,field:'limit',text:'建ぺい率の説明として正しいものはどれか。',opts:['敷地面積に対する延べ床面積の割合','敷地面積に対する建築面積（1階部分）の割合','道路幅員に対する建物高さの割合','容積率と同じ意味'],ans:1,exp:'建ぺい率は「敷地面積に対する建築面積（建物の真上から見た面積）の割合」です。延べ床面積との割合は容積率です。',"kaisetsu":{"topic": "建ぺい率：敷地面積に対する建築面積の割合", "basis": {"text": "建ぺい率とは「敷地面積に対する建築面積（建物を真上から見た投影面積・1階部分の面積）の割合」です（建築基準法53条）。「延べ床面積の割合」は容積率です。", "example": "敷地面積100㎡・建ぺい率60%の土地では、1階部分の面積（建築面積）は最大60㎡まで建てられます。"}, "reason": {"text": "建ぺい率＝建築面積÷敷地面積、容積率＝延べ床面積÷敷地面積。前面道路の幅員12m未満の場合は、容積率が道路幅員×法定乗数（住居系0.4・その他0.6）と指定値の小さい方となります（建築基準法52条2項）。"}, "svg": "<svg viewBox=\"0 0 620 155\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建ぺい率と容積率の違い</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">用語</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">計算式</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"155\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">意味</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"155\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物の水平投影面積（1階部分）の割合</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全階の床面積合計の割合</text></svg>", "choices": [{"label": "敷地面積に対する建築面積（1階部分）の割合", "reason": "正解です。建ぺい率は建築面積（建物を真上から見た投影面積）を敷地面積で割った割合です（建築基準法53条）。", "caution": ""}, {"label": "敷地面積に対する延べ床面積の割合", "reason": "延べ床面積÷敷地面積は「容積率」です。建ぺい率は建築面積（1階部分）を使います。", "caution": "「建ぺい率→建築面積」「容積率→延べ床面積」を確実に区別してください。"}, {"label": "道路幅員に対する建物高さの割合", "reason": "道路幅員と建物高さの関係は「道路斜線制限」で、建ぺい率とは別の概念です。", "caution": ""}, {"label": "容積率と同じ意味", "reason": "建ぺい率と容積率は計算式も意味も異なります。", "caution": ""}], "summary": {"head": ["用語", "計算式"], "rows": [["建ぺい率", "建築面積÷敷地面積"], ["容積率", "延べ床面積÷敷地面積"]]}}},
  {id:10010,unit:'k_nochi',level:1,field:'limit',text:'農地を農地のまま第三者に売る場合に必要なものはどれか。',opts:['都道府県知事の許可','農業委員会の許可','市町村長への届出のみ','何も必要ない'],ans:1,exp:'農地を農地のまま売買（権利移動）する場合は農地法3条の規定により農業委員会の許可が必要です。',"kaisetsu":{"topic": "農地法3条：農地を農地のまま売買→農業委員会の許可", "basis": {"text": "農地を農地のまま第三者に売買・贈与・賃貸等（権利移動）する場合は農地法3条の農業委員会の許可が必要です（農地法3条1項）。", "example": "農業者Aが農業者Bに農地を売却する場合→農地法3条の農業委員会の許可が必要。農地を宅地等に転用してBに売却する場合→農地法5条の都道府県知事等の許可が必要。"}, "reason": {"text": "農地法3条：権利移動（農地→農地）・許可権者は農業委員会。農地法4条：自己転用（農地→農地以外）・許可権者は都道府県知事等。農地法5条：転用目的の権利移動・許可権者は都道府県知事等。市街化区域内の農地の4条・5条は農業委員会への届出のみでOKです。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">市街化区域</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">特例なし（許可必要）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ（許可不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ（許可不要）</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条の3</text><text x=\"227\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続等による取得</text><text x=\"372\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ（許可不要）</text><text x=\"517\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">—</text></svg>", "choices": [{"label": "農業委員会の許可", "reason": "正解です。農地を農地のまま第三者に権利移動（売買・贈与・賃貸等）する場合は農地法3条の農業委員会の許可が必要です。", "caution": ""}, {"label": "都道府県知事の許可", "reason": "都道府県知事等の許可が必要なのは農地転用（4条・5条）の場合です。農地を農地のまま売買する（3条）の場合は農業委員会が許可権者です。", "caution": "「3条→農業委員会」「4条・5条→都道府県知事等」の対比で覚えてください。"}, {"label": "市町村長への届出のみ", "reason": "農地の権利移動（3条）は農業委員会の許可が必要です。市街化区域内の転用（4・5条）は農業委員会への届出のみで済みますが、3条には届出特例がありません。", "caution": ""}, {"label": "何も必要ない", "reason": "農地法3条の許可なく行った農地売買は無効です（農地法3条8項）。許可は必須です。", "caution": ""}], "summary": {"head": ["条文", "行為", "許可権者"], "rows": [["3条", "権利移動（農地→農地）", "農業委員会"], ["4条", "自己転用", "都道府県知事等"], ["5条", "転用目的の権利移動", "都道府県知事等"]]}}},
  {id:10011,unit:'r_saikensoron',level:1,field:'rights',text:'保証契約の成立要件として正しいものはどれか。',opts:['公正証書で作成しなければならない','書面または電磁的記録によらなければ効力が生じない','口頭でも成立する','主債務者の同意が必要'],ans:1,exp:'保証契約は書面（または電磁的記録）によらなければ効力が生じません（民法446条2項）。口頭の保証契約は無効です。',"kaisetsu":{"topic": "保証契約の成立要件：書面（または電磁的記録）が必要", "basis": {"text": "保証契約は書面または電磁的記録によって行わなければ効力が生じません（民法446条2項・3項）。口頭での保証の約束は無効です。", "example": "AがBの銀行ローンの保証人になることを口頭で約束した場合、その保証契約は無効です。後日Bがローンを返済しなくても、口頭だけでは保証契約が成立しないためAは保証債務を負いません（民法446条2項）。"}, "reason": {"text": "保証契約の書面要件は2004年の民法改正で導入されました（軽率な保証を防ぐため）。連帯保証人には催告の抗弁権・検索の抗弁権がありません（民法454条）。個人の根保証契約（不特定の債務を保証）には極度額（上限金額）を書面で定めなければなりません（民法465条の2）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">保証のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約の方式</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面または電磁的記録が必要（口頭は無効）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証人</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">催告・検索の抗弁権なし（民法454条）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">普通保証人</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">催告・検索の抗弁権あり</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">個人の根保証</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">極度額の書面による定めが必要（民法465条の2）</text></svg>", "choices": [{"label": "口頭の約束でも成立する", "reason": "保証契約は書面または電磁的記録が必要です（民法446条2項）。口頭の約束は無効です。", "caution": "「保証契約→書面必須・口頭は無効」は2004年改正で導入された重要なルールです。"}, {"label": "書面または電磁的記録によらなければ効力が生じない", "reason": "正解です。保証契約は書面または電磁的記録によらなければ効力が生じません（民法446条2項・3項）。", "caution": ""}, {"label": "公正証書によらなければ成立しない", "reason": "書面であれば公正証書でなくてもよいです。普通の契約書（私文書）でも有効です。", "caution": "事業用定期借地権の設定は公正証書が必須ですが、保証契約は公正証書不要です。"}, {"label": "保証人が成年者である必要がある", "reason": "成年者である必要はありません。ただし制限行為能力者が保証人になる場合は、その行為の効力の問題（取消し等）が生じます。", "caution": ""}], "summary": {"head": ["項目", "内容"], "rows": [["保証契約の方式", "書面または電磁的記録が必要"], ["連帯保証", "催告・検索の抗弁権なし"], ["普通保証", "催告・検索の抗弁権あり"], ["個人の根保証", "極度額の書面が必要"]]}}},
  {id:10012,unit:'l_takkenshi',level:1,field:'law',text:'宅建業者の事務所の専任宅建士の割合として正しいものはどれか。',opts:['業務従事者3名に1名以上','業務従事者5名に1名以上','業務従事者10名に1名以上','全員が宅建士'],ans:1,exp:'事務所には業務に従事する者5名につき1名以上の専任の宅建士が必要です（宅建業法31条の3）。',"kaisetsu":{"topic": "専任宅建士の設置基準：業務従事者5人に1人以上", "basis": {"text": "宅建業者の事務所には、業務に従事する者5人に対して1人以上の専任の宅建士を置かなければなりません（宅建業法31条の3第1項）。主たる事務所も従たる事務所も同じ割合（5:1）が基準です。", "example": "従業者が12人いる事務所では、12÷5＝2.4→切り上げで3名以上の専任宅建士が必要。専任宅建士が不足した場合は2週間以内に補充しなければなりません。"}, "reason": {"text": "専任の宅建士は常勤・専従が必要で、複数の宅建業者の専任を兼任することはできません（1社にのみ専任）。不足時は2週間以内に補充義務があります（宅建業法31条の3第3項）。申込みを受け付けたり契約を締結する案内所にも専任宅建士の配置が必要です（同条1項）。"}, "svg": "<svg viewBox=\"0 0 620 275\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">専任宅建士のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"275\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">設置基準</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務従事者5人に1人以上（主従同じ）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">常勤要件</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">常勤・専従が必要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">兼任</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">複数業者の専任は不可（1社専属）</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">案内所</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">申込み受付の場合は配置必要</text><rect x=\"10\" y=\"225\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不足補充</text><text x=\"445\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間以内</text></svg>", "choices": [{"label": "業務従事者5名に1名以上", "reason": "正解です。事務所には業務に従事する者5人に対して1人以上の専任宅建士を置く必要があります（宅建業法31条の3第1項）。", "caution": ""}, {"label": "業務従事者3名に1名以上", "reason": "3名に1名以上は誤りです。正しくは5名に1名以上です。", "caution": ""}, {"label": "事務所に1名いればよい", "reason": "業務従事者の人数に応じた設置が必要です。5名ごとに1名以上が必要なので、10名の事務所では2名以上が必要です。", "caution": ""}, {"label": "主たる事務所に5名に1名、従たる事務所は規定なし", "reason": "主たる事務所・従たる事務所どちらも同じく業務従事者5名に1名以上の専任宅建士が必要です。", "caution": "主従の区別なく同じ基準が適用されます。"}], "summary": {"head": ["項目", "内容"], "rows": [["設置基準", "業務従事者5人に1人以上"], ["主従の事務所", "同じ基準（5:1）"], ["兼任", "1社専属（兼任不可）"], ["不足補充", "2週間以内"]]}}},
  {id:10013,unit:'k_toshi',level:1,field:'limit',text:'市街化区域の説明として正しいものはどれか。',opts:['すでに農地として整備された区域','すでに市街地を形成している区域またはおおむね10年以内に優先的・計画的に市街化を図る区域','将来も絶対に開発しない区域','商業地域のみが含まれる区域'],ans:1,exp:'市街化区域は「すでに市街地を形成している区域」と「おおむね10年以内に優先的・計画的に市街化を図るべき区域」から構成されます（都市計画法7条）。',"kaisetsu":{"topic": "市街化区域：すでに市街地を形成している区域または10年以内に優先的に市街化を図る区域", "basis": {"text": "市街化区域は「すでに市街地を形成している区域」および「おおむね10年以内に優先的かつ計画的に市街化を図るべき区域」です（都市計画法7条1項）。", "example": "東京23区の多くは既成市街地として市街化区域に指定されています。また23区周辺の新興住宅地も「10年以内に市街化を図る」として市街化区域に指定されることがあります。"}, "reason": {"text": "市街化調整区域は「市街化を抑制すべき区域」です（都市計画法7条2項）。市街化区域には少なくとも用途地域を定めなければなりません（同法13条1項7号）。市街化区域内での開発行為は1,000㎡以上から開発許可が必要です（同法29条1項1号）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">市街化区域と市街化調整区域</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">区域</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">定義</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">特徴</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地＋10年以内に市街化する区域</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">用途地域を定めること必須</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化調整区域</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化を抑制すべき区域</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可は原則全て必要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非線引き区域</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域でも調整区域でもない区域</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都市計画区域だが線引きなし</text></svg>", "choices": [{"label": "すでに市街地を形成している区域またはおおむね10年以内に優先的に市街化を図るべき区域", "reason": "正解です。都市計画法7条1項の定義です。", "caution": "「おおむね10年以内」という部分が重要です。「5年以内」や「15年以内」と混同しないようにしてください。"}, {"label": "市街化を抑制すべき区域", "reason": "「市街化を抑制すべき区域」は市街化調整区域の定義です（都市計画法7条2項）。", "caution": "市街化区域と市街化調整区域の定義を逆にしないようにしてください。"}, {"label": "すでに農地として利用されている区域", "reason": "農地の利用状況は市街化区域の定義とは直接関係ありません。市街化区域内に農地が含まれることもあります。", "caution": ""}, {"label": "人口が5万人以上の都市が所在する区域", "reason": "人口規模は市街化区域の定義の要素ではありません。", "caution": ""}], "summary": {"head": ["区域", "定義"], "rows": [["市街化区域", "既成市街地＋10年以内に市街化する区域"], ["市街化調整区域", "市街化を抑制すべき区域"]]}}},
  {id:10014,unit:'t_kotei',level:1,field:'tax',text:'固定資産税を課す権者として正しいものはどれか。',opts:['国','都道府県','市町村（東京23区は都）','固定資産評価委員会'],ans:2,exp:'固定資産税は市町村が課す地方税です（東京23区は都）（地方税法343条）。国税ではありません。',"kaisetsu":{"topic": "固定資産税：市町村（東京23区は都）が課す地方税", "basis": {"text": "固定資産税は市町村が課す地方税です（地方税法343条）。ただし東京23区内の固定資産税は都（東京都）が課します。賦課期日は毎年1月1日です（地方税法359条）。", "example": "大阪市に土地を持つAは、大阪市から固定資産税の納税通知書が届きます。東京都渋谷区に土地を持つBは、東京都から固定資産税の納税通知書が届きます（23区は都が課税）。"}, "reason": {"text": "評価替えは3年ごと（基準年度）に行われます（地方税法381条等）。標準税率は1.4%で市町村は条例で変更できます。住宅用地の特例：小規模住宅用地（200㎡以下の部分）は課税標準が1/6、一般住宅用地（200㎡超の部分）は1/3に軽減されます（地方税法349条の3の2）。"}, "svg": "<svg viewBox=\"0 0 620 315\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">固定資産税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"315\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市町村（東京23区は都）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賦課期日</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">評価替え</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年ごと（基準年度）</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">標準税率</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1.4%（条例で変更可）</text><rect x=\"10\" y=\"225\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅用地（200㎡以下）</text><text x=\"445\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税標準が1/6に軽減</text><rect x=\"10\" y=\"265\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"290\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅用地（200㎡超の部分）</text><text x=\"445\" y=\"290\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税標準が1/3に軽減</text></svg>", "choices": [{"label": "国（国土交通省）", "reason": "固定資産税は国税ではなく地方税（市町村税）です。国土交通省は課税しません。", "caution": "「固定資産税→市町村税（地方税）」「登録免許税→国税」を区別してください。"}, {"label": "都道府県", "reason": "固定資産税は都道府県税ではなく市町村税です。ただし東京23区は例外として都が課税します。", "caution": ""}, {"label": "市町村（東京23区は都）", "reason": "正解です。固定資産税は市町村税で、東京23区内は特例として都が課税します（地方税法343条）。", "caution": ""}, {"label": "法務局", "reason": "法務局は登記機関であり課税機関ではありません。", "caution": ""}], "summary": {"head": ["項目", "内容"], "rows": [["課税主体", "市町村（東京23区は都）"], ["賦課期日", "毎年1月1日"], ["評価替え", "3年ごと"], ["住宅用地（200㎡以下）", "課税標準1/6"]]}}},
  {id:10015,unit:'r_jiko',level:1,field:'rights',text:'一般の債権の消滅時効期間（2020年改正後）として正しいものはどれか。',opts:['権利行使できると知った時から1年','権利行使できると知った時から3年','権利行使できると知った時から5年','権利行使できる時から5年'],ans:2,exp:'改正民法では、一般の債権の消滅時効は「権利行使できると知った時から5年」または「権利行使できる時から10年」のいずれか早い方で完成します（民法166条）。',"kaisetsu":{"topic": "消滅時効期間（2020年改正後）：知った時から5年または行使可能時から10年", "basis": {"text": "2020年の民法改正により、一般の債権の消滅時効は「権利を行使できることを知った時から5年」または「権利を行使できる時から10年」のいずれか早い方で完成します（民法166条1項）。", "example": "AがBにお金を貸した（権利行使可能）。AがBに請求できることを知っていれば知った時から5年で時効完成。AがBへの請求権を知らなくても、貸した時（権利行使可能時）から10年で時効完成。"}, "reason": {"text": "2020年改正前は「一般の債権は行使できる時から10年」でしたが、改正で「主観的起算点から5年」が加わり短縮されました。人の生命・身体の侵害による損害賠償請求権は知った時から5年・行為時から20年です（民法724条の2）。時効は援用して初めて効力が発生します（民法145条）。"}, "svg": "<svg viewBox=\"0 0 620 275\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間（2020年改正後）</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">時効期間</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"275\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">適用</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"275\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般の債権</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観的）</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般の債権</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">損害・加害者を知った時</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不法行為</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">損害・加害者を知った時</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人身の不法行為</text><rect x=\"10\" y=\"225\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不法行為の時</text><text x=\"299\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">20年</text><text x=\"492\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不法行為（人身は20年）</text></svg>", "choices": [{"label": "権利を行使できる時から10年", "reason": "客観的起算点（権利行使可能時）からの10年も正しいですが、これに加えて「知った時から5年」も適用されます。どちらか早い方が正解です（本問は選択肢2が正解）。", "caution": ""}, {"label": "権利行使できると知った時から5年", "reason": "正解です。2020年改正により「権利行使できることを知った時から5年」が追加されました（民法166条1項1号）。客観的起算点（行使可能時）から10年との短い方が適用されます。", "caution": ""}, {"label": "権利を行使できる時から3年", "reason": "3年は不法行為の短期時効期間です（知った時から3年）。一般の債権の時効期間は5年または10年です。", "caution": ""}, {"label": "権利を行使できる時から20年", "reason": "20年は人の生命・身体への侵害による損害賠償の長期時効です。一般の債権は5年または10年が正しいです。", "caution": ""}], "summary": {"head": ["債権の種類", "時効期間"], "rows": [["一般の債権", "知った時から5年 または 行使可能時から10年"], ["不法行為（一般）", "知った時から3年 または 行為時から20年"], ["不法行為（人身）", "知った時から5年 または 行為時から20年"]]}}},
  {id:10016,unit:'l_37jo',level:1,field:'law',text:'37条書面の必要的記載事項として正しいものはどれか。',opts:['売主の固定資産税の金額','引渡しの時期','近隣施設の状況','隣地所有者の名前'],ans:1,exp:'37条書面の必要的記載事項には「物件の特定・代金・引渡し時期・移転登記申請時期」などが含まれます（宅建業法37条1項）。',"kaisetsu":{"topic": "37条書面の必要的記載事項：引渡しの時期", "basis": {"text": "37条書面（契約書）の必要的記載事項には「宅地または建物の引渡しの時期」が含まれます（宅建業法37条1項4号）。必ず記載しなければならない事項です。", "example": "売主Aと買主Bの売買契約において、引渡し時期（例：代金全額支払い後1週間以内）は37条書面に必ず記載します。"}, "reason": {"text": "必要的記載事項（常に記載）：当事者・物件・代金・引渡し時期・移転登記申請時期等。任意的記載事項（定めがあれば記載）：代金以外の金銭の授受・手付金の額・損害賠償予定額・解約手付等。2021年改正で宅建士の押印は不要になり記名のみで足ります（宅建業法37条3項）。"}, "svg": "<svg viewBox=\"0 0 620 155\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面の記載事項</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">区分</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">例</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"155\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">ポイント</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"155\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載事項</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">当事者・物件・代金・引渡時期・移転登記申請時期</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">常に記載が必須</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">任意的記載事項</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金以外の金銭・損賠予定額・解約手付等</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">定めがある場合に記載</text></svg>", "choices": [{"label": "引渡しの時期", "reason": "正解です。引渡しの時期は37条書面の必要的記載事項です（宅建業法37条1項4号）。必ず記載しなければなりません。", "caution": ""}, {"label": "手付金の額", "reason": "手付金の額は任意的記載事項です（定めがある場合に記載）。必ず記載が必要な必要的記載事項ではありません。", "caution": "「引渡し時期・移転登記申請時期→必要的」「手付金・損賠予定額→任意的」の区別を覚えてください。"}, {"label": "売主の住所", "reason": "当事者（氏名・住所）は必要的記載事項ですが、「売主の住所」という選択肢単体では不完全です。本問の正解は選択肢1（引渡しの時期）です。", "caution": ""}, {"label": "物件の評価額", "reason": "物件の評価額は37条書面の記載事項ではありません。", "caution": ""}], "summary": {"head": ["区分", "例"], "rows": [["必要的記載事項", "引渡時期・移転登記申請時期・代金等"], ["任意的記載事項", "手付金・損賠予定額等（定めがあれば記載）"]]}}},
  {id:10017,unit:'k_kenchiku',level:1,field:'limit',text:'前面道路幅員が12m未満の場合の容積率の扱いとして正しいものはどれか。',opts:['都市計画の容積率のみ適用','都市計画の容積率と道路幅員×法定乗数の大きい方','都市計画の容積率と道路幅員×法定乗数の小さい方','制限なし'],ans:2,exp:'前面道路が12m未満の場合、都市計画の容積率と「道路幅員×0.4（住居系）」を比較して小さい方が上限として適用されます（建築基準法52条2項）。',"kaisetsu":{"topic": "容積率：前面道路12m未満は指定値と道路幅×乗数の小さい方", "basis": {"text": "前面道路の幅員が12m未満の場合、容積率の上限は「都市計画で定めた指定容積率」と「前面道路幅員×法定乗数」の小さい方が適用されます（建築基準法52条2項）。", "example": "指定容積率200%の住居系地域で前面道路幅員6m。6m×0.4（住居系の乗数）×100＝240%。指定値200%の方が小さいので容積率の上限は200%。前面道路8m×0.4×100＝320%で指定値200%の方が小さいので200%。"}, "reason": {"text": "法定乗数：住居系用途地域は0.4、その他の用途地域（商業・工業等）は0.6。前面道路幅員12m以上の場合は指定容積率のみが適用されます。容積率算定では住宅の地下室（住宅床面積の1/3まで）・EV昇降路・共用廊下等は除外できます（建築基準法52条3項等）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">容積率のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条件</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">適用ルール</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m以上</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">指定容積率をそのまま適用</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満（住居系）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">道路幅×0.4と指定値の小さい方</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満（その他）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">道路幅×0.6と指定値の小さい方</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅の地下室</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅床面積の1/3まで算定から除外</text></svg>", "choices": [{"label": "指定容積率のみが適用される", "reason": "前面道路が12m未満の場合、指定容積率のみではなく「指定値と道路幅×乗数の小さい方」が適用されます。", "caution": "「12m以上→指定容積率のみ」「12m未満→小さい方が上限」という区切りを覚えてください。"}, {"label": "都市計画の容積率と道路幅員×法定乗数のうち小さい方", "reason": "正解です。前面道路が12m未満の場合、指定容積率と前面道路幅員×法定乗数の小さい方が上限です（建築基準法52条2項）。", "caution": ""}, {"label": "道路幅員×法定乗数のみが適用される", "reason": "指定容積率も考慮します。2つの値の小さい方が上限です。", "caution": ""}, {"label": "前面道路の幅員に関わらず指定容積率が適用される", "reason": "前面道路が12m未満の場合は道路幅に応じた制限が加わります。", "caution": ""}], "summary": {"head": ["前面道路幅員", "適用ルール"], "rows": [["12m以上", "指定容積率"], ["12m未満（住居系）", "道路幅×0.4と指定値の小さい方"], ["12m未満（その他）", "道路幅×0.6と指定値の小さい方"]]}}},
  {id:10018,unit:'t_shutoku',level:1,field:'tax',text:'不動産取得税について正しいものはどれか。',opts:['国が課す国税','相続による取得にも課される','都道府県が課す地方税','毎年課される'],ans:2,exp:'不動産取得税は都道府県が課す地方税です（地方税法73条の2）。相続による取得は非課税。一度の取得に一度だけ課される税です。',"kaisetsu":{"topic": "不動産取得税：都道府県が課す地方税・相続は非課税・取得時に1回", "basis": {"text": "不動産取得税は都道府県が課す地方税です（地方税法73条の2）。不動産を取得した時に1回だけ課税されます（固定資産税のように毎年ではない）。相続・法人の合併等による取得は非課税です。", "example": "AがBから土地を購入した→不動産取得税が課税される（都道府県から納税通知が来る）。AがBの土地を相続した→非課税（相続は取得税がかからない）。"}, "reason": {"text": "原則税率は4%ですが、住宅および住宅用地は3%（軽減税率）。また新築住宅等には一定の控除があります。納付方式は普通徴収（都道府県が税額を計算して通知）で、納税者が自ら申告する必要はありません。固定資産税（市町村税・毎年課税）との混同に注意。"}, "svg": "<svg viewBox=\"0 0 620 275\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産取得税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"275\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税のタイミング</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取得時に1回のみ（毎年ではない）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税の取得</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続・法人合併等</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">税率</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4%（住宅・土地は3%）</text><rect x=\"10\" y=\"225\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">納付方式</text><text x=\"445\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">普通徴収（都道府県からの通知）</text></svg>", "choices": [{"label": "国土交通省が課す国税", "reason": "不動産取得税は国税ではなく都道府県税（地方税）です。", "caution": "「不動産取得税→都道府県税」「登録免許税→国税」を区別してください。"}, {"label": "都道府県が課す地方税", "reason": "正解です。不動産取得税は都道府県が課す地方税です（地方税法73条の2）。", "caution": ""}, {"label": "市町村が課す地方税", "reason": "市町村が課す地方税は固定資産税・都市計画税・軽自動車税等です。不動産取得税は都道府県税です。", "caution": "「固定資産税→市町村税」「不動産取得税→都道府県税」の対比を覚えてください。"}, {"label": "相続で取得した場合も課税される", "reason": "相続による不動産の取得は非課税です（地方税法73条の7第1号）。「相続も課税」は誤りです。", "caution": ""}], "summary": {"head": ["項目", "内容"], "rows": [["課税主体", "都道府県（地方税）"], ["課税", "取得時に1回のみ"], ["非課税", "相続・法人合併等"], ["税率", "4%（住宅・土地は3%）"]]}}},
  {id:10019,unit:'r_ishi',level:1,field:'rights',text:'詐欺による取消しと善意無過失の第三者の関係として正しいものはどれか。',opts:['誰に対しても取消しを主張できる','善意かつ無過失の第三者には取消しを対抗できない','強迫と同様に誰にでも対抗できる','取消しはできず無効を主張するしかない'],ans:1,exp:'詐欺による取消しは「善意かつ無過失の第三者」には対抗できません（民法96条3項）。強迫による取消しはたとえ善意の第三者に対しても対抗できます。',"kaisetsu":{"topic": "詐欺取消しと第三者：善意無過失の第三者には対抗不可", "basis": {"text": "詐欺による意思表示の取消しは、善意かつ無過失の第三者に対抗できません（民法96条3項）。詐欺による取消しを知らず（善意）かつ知らないことについて過失がない（無過失）第三者は保護されます。", "example": "AがBに詐欺されてC（A所有の土地）の売買契約を結んだ。BがCに土地を転売した後、AがBとの契約を取り消した。CがBの詐欺を知らず（善意）かつ過失もなければ、AはCに「取り消したから土地を返せ」と言えません。"}, "reason": {"text": "詐欺の被害者にも「騙された隙がある」として取引の安全を重視し、善意無過失の第三者を保護します。強迫は被害者に全く落ち度がないため、第三者保護より被害者救済を優先します。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">取消しと第三者保護の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">善意の第三者</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">善意無過失の第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺取消し</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保護あり</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保護あり（対抗不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫取消し</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保護なし（対抗可）</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保護なし（対抗可）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤取消し</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保護あり</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保護あり（対抗不可）</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示の無効</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保護あり（民法94条2項）</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">—</text></svg>", "choices": [{"label": "誰に対しても取消しを主張できる", "reason": "詐欺取消しは善意かつ無過失の第三者には対抗できません（民法96条3項）。強迫と異なり第三者保護があります。", "caution": "詐欺＝善意無過失の第三者保護あり。強迫＝第三者保護なし（誰にでも対抗可）。"}, {"label": "強迫と同様に誰にでも対抗できる", "reason": "詐欺と強迫は第三者保護の扱いが異なります。詐欺は善意無過失の第三者に対抗できませんが、強迫は誰にでも対抗できます。", "caution": ""}, {"label": "取消しはできず無効を主張するしかない", "reason": "詐欺による意思表示は取消しが認められています（民法96条1項）。無効ではなく取消しです。", "caution": "詐欺による意思表示＝取消しうる行為（無効ではない）。"}], "summary": {"head": ["種類", "取消し", "善意無過失の第三者"], "rows": [["詐欺", "取消しうる", "対抗できない"], ["強迫", "取消しうる", "対抗できる（第三者保護なし）"], ["通謀虚偽表示", "無効", "善意の第三者保護あり"]]}}},
  {id:10020,unit:'l_menkyo',level:1,field:'law',text:'宅建業の免許の有効期間として正しいものはどれか。',opts:['2年','3年','5年','10年'],ans:2,exp:'宅建業の免許の有効期間は5年です（宅建業法3条2項）。更新申請は有効期間満了の90日前から30日前の間に行う必要があります。',"kaisetsu":{"topic": "宅建業免許の有効期間：5年", "basis": {"text": "宅建業の免許の有効期間は5年です（宅建業法3条2項）。更新申請は有効期間満了の90日前から30日前の間に行います。", "example": "令和3年4月1日にA社が免許を取得した場合、有効期間は令和8年3月31日まで。更新申請は令和8年1月1日（90日前）から令和8年2月29日（30日前）の間に行います。"}, "reason": {"text": "更新申請をしなかった場合、免許は失効します。更新申請をしたが審査中に有効期間が満了した場合は、審査結果が出るまで従前の免許の効力が継続します（宅建業法3条4項）。宅建士証の有効期間も5年です（宅建業法22条の2第4項）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許の有効期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">更新申請の時期</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">満了の90日前〜30日前</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">更新申請中の効力</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">審査結果が出るまで従前の免許が継続</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士証の有効期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（同じ）</text></svg>", "choices": [{"label": "3年", "reason": "宅建業の免許の有効期間は5年です（宅建業法3条2項）。3年は誤りです。", "caution": ""}, {"label": "5年", "reason": "正解です。宅建業の免許の有効期間は5年です（宅建業法3条2項）。", "caution": ""}, {"label": "10年", "reason": "10年は誤りです。5年が正解です。", "caution": ""}, {"label": "有効期間の定めはない", "reason": "宅建業の免許には5年という有効期間があります。更新手続きが必要です。", "caution": ""}], "summary": {"head": ["項目", "内容"], "rows": [["有効期間", "5年"], ["更新申請", "満了90日前〜30日前"], ["宅建士証の有効期間", "5年（同じ）"]]}}},
  {id:10021,unit:'r_souzoku',level:1,field:'rights',text:"Aが死亡し、子BとCが相続人の場合、Bが相続を放棄した場合のCの相続分はどうなるか。",opts:["2分の1のまま変わらない", "3分の2に増える", "全部を相続する", "放棄できない"],ans:2,exp:`相続人の一人が放棄した場合、その放棄した相続人は最初から相続人でなかったものとみなされます（民法939条）。BとCの2人のうちBが放棄すれば、Cが単独相続人となり全部を相続します。`,"kaisetsu":{"topic": "相続放棄：放棄した者の子は代襲相続不可", "basis": {"text": "相続放棄をした者はその相続に関して最初から相続人でなかったとみなされます（民法939条）。そのため放棄した者の子（孫等）は代襲相続できません。", "example": "Aが死亡し子BとCが相続人。BがA死亡を知った時から3か月以内に家庭裁判所に放棄の申述。BはAの相続人でなかったとみなされるため、Bの子（Aの孫）は代襲相続できません。Cが全部を相続します。"}, "reason": {"text": "代襲相続ができるケース：被相続人の子が「死亡・欠格・廃除」の場合（民法887条2項）。できないケース：「相続放棄」の場合。放棄は自分の意思で相続しないことを選んだ結果なので子への代襲は認められません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続放棄のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄した者の扱い</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">最初から相続人でなかったとみなす（民法939条）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄した者の子</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代襲相続不可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代襲相続が認められる場合</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">被相続人の子の死亡・欠格・廃除</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続開始を知った時から3か月以内に家裁へ申述</text></svg>", "choices": [{"label": "2分の1のまま変わらない", "reason": "Bが放棄すればBは最初から相続人でなかったとみなされます。Cのみが相続人となるため、Cが全部を相続します。", "caution": ""}, {"label": "3分の2に増える", "reason": "3分の2という相続分は、配偶者+直系尊属（父母）の組み合わせの場合の配偶者の相続分です。本問では配偶者はおらず子2名（BとC）が相続人で、Bが放棄すればCが単独相続人となります。", "caution": ""}, {"label": "全部を相続する", "reason": "正解です。Bが放棄した場合、Bは最初から相続人でなかったとみなされ（民法939条）、Cが単独相続人として全部を相続します。", "caution": ""}, {"label": "放棄できない", "reason": "相続放棄は相続開始を知った時から3か月以内に家庭裁判所に申述することで有効にできます（民法915条・938条）。放棄できないというのは誤りです。", "caution": ""}], "summary": {"head": ["状況", "結果"], "rows": [["Bが相続放棄", "Bは最初から相続人でなかったとみなされる"], ["Bの子の代襲相続", "不可"], ["Cの相続分", "全部（単独相続人）"]]}}},
  {id:10022,unit:'r_shakuchi',level:1,field:'rights',text:"借地権の存続期間（普通借地権）として正しいものはどれか。",opts:["10年以上", "20年以上", "30年以上", "50年以上"],ans:2,exp:`普通借地権の存続期間は30年以上です（借地借家法3条）。30年未満の定めをしても30年となります。`,"kaisetsu":{"topic": "普通借地権の存続期間：最短30年・30年未満の定めは30年とみなす", "basis": {"text": "普通借地権の存続期間は30年以上です（借地借家法3条）。30年未満の期間を定めた場合や期間の定めをしない場合は30年とみなされます。", "example": "AがBの土地を借りて建物を建てる場合、「契約期間15年」と合意しても15年の定めは無効となり、法律上30年の借地権となります。"}, "reason": {"text": "定期借地権（更新なし）との違い：普通借地権は更新があり（正当事由がなければ更新される）、存続期間は最初の設定時は30年以上ですが、更新後は1回目は20年以上・その後は10年以上です（借地借家法4条・5条）。定期借地権の一般定期借地権（借地借家法22条）は50年以上で更新なし。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">借地権の種類と存続期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">最低期間</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">更新</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">方式</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">普通借地権</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30年以上（更新後は20年・10年以上）</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当事由なければ更新あり</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面不要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般定期借地権</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">50年以上</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">なし（再契約は可）</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事業用定期借地権</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年以上50年未満</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">なし</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公正証書必須</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物譲渡特約付き</text><text x=\"227\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30年以上</text><text x=\"372\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">なし（建物所有権が地主に移転）</text><text x=\"517\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面</text></svg>", "choices": [{"label": "20年以上", "reason": "普通借地権の最初の存続期間は30年以上です。20年は普通借地権更新後の2回目以降の最低期間です。", "caution": "「最初→30年以上」「1回目更新後→20年以上」「その後の更新→10年以上」という段階的な理解が必要です。"}, {"label": "30年以上", "reason": "正解です。普通借地権の存続期間は30年以上です（借地借家法3条）。30年未満の定めは30年とみなされます。", "caution": ""}, {"label": "50年以上", "reason": "50年以上は一般定期借地権の最低期間です（借地借家法22条）。普通借地権は30年以上が正解です。", "caution": ""}, {"label": "特に制限はない", "reason": "借地借家法3条で30年以上という制限が定められています。30年未満の定めは無効（30年とみなされる）です。", "caution": ""}], "summary": {"head": ["種類", "最低期間"], "rows": [["普通借地権", "30年以上（最初）"], ["一般定期借地権", "50年以上"], ["事業用定期借地権", "10年以上50年未満"]]}}},
  {id:10023,unit:'r_bukken',level:1,field:'rights',text:"物権と債権の違いとして正しいものはどれか。",opts:["物権は特定人に対する権利で、債権は物に対する権利", "物権は物に対する権利で、債権は特定人に対する権利", "物権も債権も同じ内容の権利", "物権には排他性がなく、債権には排他性がある"],ans:1,exp:`物権は物に対する権利で排他性があります（一物一権主義）。債権は特定人（債務者）に対して一定の行為を請求できる権利で、排他性はなく同一内容の債権が複数成立します。`,"kaisetsu":{"topic": "物権と債権の違い：物権は排他性あり・債権は排他性なし", "basis": {"text": "物権は物に対する権利で、特定の物について排他的に支配できる権利です（一物一権主義）。債権は特定人（債務者）に対して一定の行為（給付）を請求できる権利で、排他性はなく同一内容の債権が複数成立します。", "example": "同一の土地に所有権が2つ存在することはできません（物権の排他性）。しかし同一の貸金債権が2つ成立することはあります（AがBとCの両方にお金を貸す等）。"}, "reason": {"text": "物権は全員に主張できる「絶対権」・債権は特定の相手にのみ主張できる「相対権」という対比も重要です。登記制度は物権変動の対抗要件として機能します。物権法定主義（民法175条）：物権は法律で定められたもの以外は勝手に作れません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">物権と債権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">物権</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">債権</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">排他性</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">あり（一物一権主義）</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">なし（複数成立可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">主張できる相手</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員（絶対権）</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">特定の相手（相対権）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">対抗要件</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">—（債権は対抗要件不要）</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定主義</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">物権法定主義あり</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自由（契約自由の原則）</text></svg>", "choices": [{"label": "物権は物に対する権利で、債権は特定人に対して給付を請求できる権利", "reason": "正解です。物権は物に対する支配権（排他性あり）、債権は特定人（債務者）に対する請求権（排他性なし）です。", "caution": ""}, {"label": "物権と債権はいずれも特定人に対する権利である", "reason": "物権は特定人に対する権利ではなく、物に対する権利（全員に主張できる絶対権）です。", "caution": ""}, {"label": "同一の物について同一内容の物権が複数成立する", "reason": "物権には排他性があり（一物一権主義）、同一の物に同一内容の物権が複数成立することはできません（例：同じ土地に所有権が2つは不可）。", "caution": ""}, {"label": "債権には物権と同様の排他性がある", "reason": "債権には排他性はなく、同一内容の債権が複数成立することができます。", "caution": ""}], "summary": {"head": ["性質", "物権", "債権"], "rows": [["排他性", "あり（一物一権主義）", "なし（複数成立可）"], ["主張できる相手", "全員（絶対権）", "特定人（相対権）"]]}}},
  {id:10024,unit:'l_hoshu',level:1,field:'law',text:"宅建業者が依頼者から受け取れる売買の媒介報酬の上限（代金400万円超の場合）として正しいものはどれか（消費税別）。",opts:["代金の2%+6万円", "代金の3%+6万円", "代金の4%+2万円", "代金の5%"],ans:1,exp:`売買代金が400万円を超える場合の報酬上限は「代金の3%+6万円」です（宅建業法46条・告示）。これは一方の依頼者から受け取れる上限であり、双方から受け取る場合は合計でこの2倍が上限です。`,"kaisetsu":{"topic": "売買媒介報酬の上限：代金400万超は代金×3%+6万円（一方から）", "basis": {"text": "売買代金が400万円を超える場合、一方の依頼者から受け取れる報酬の上限は「代金×3%+6万円（税別）」です（宅建業法46条・告示）。", "example": "代金1,000万円の売買を媒介した場合。一方からの上限＝1,000万×3%+6万=36万円（税別）。売主・買主の双方から受け取る場合の合計上限＝36万×2=72万円。"}, "reason": {"text": "3段階の計算式：200万円以下→×5%、200万超400万以下→×4%+2万、400万超→×3%+6万（速算式）。賃貸の媒介報酬は売買とは異なり、居住用・非居住用ともに借賃1か月分が双方合計の上限です。依頼者の承諾があっても上限を超えることはできません（強行規定）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">売買媒介報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">代金の範囲</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">一方からの上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">200万円以下</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">200万超400万以下</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×4%+2万円</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">400万円超</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万円（速算式）</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">双方合計</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一方の上限×2</text></svg>", "choices": [{"label": "代金の3%+6万円", "reason": "正解です。代金400万円超の場合の報酬上限は「代金×3%+6万円（税別）」です（宅建業法告示）。", "caution": ""}, {"label": "代金の5%", "reason": "代金×5%は代金200万円以下の場合の上限です。400万円超は×3%+6万円（速算式）です。", "caution": "3段階の計算式を覚えてください。"}, {"label": "代金の2%+4万円", "reason": "このような計算式はありません。400万超は代金×3%+6万円が正解です。", "caution": ""}, {"label": "代金の10%", "reason": "10%という上限はありません。400万超は代金×3%+6万円が正解です。", "caution": ""}], "summary": {"head": ["代金範囲", "一方からの上限"], "rows": [["200万以下", "×5%"], ["200万超400万以下", "×4%+2万"], ["400万超", "×3%+6万（速算式）"], ["双方合計", "一方上限×2"]]}}},
  {id:10025,unit:'l_kantoku',level:1,field:'law',text:"宅建業者の事務所に掲示しなければならないものとして正しいものはどれか。",opts:["宅建士全員の顔写真", "業者票と報酬額", "近隣地図", "営業時間表"],ans:1,exp:`宅建業者は全ての事務所に「宅地建物取引業者票（業者票）」と「報酬額表」を掲示しなければなりません（宅建業法50条）。`,"kaisetsu":{"topic": "宅建業者の事務所の掲示義務：業者票と報酬額", "basis": {"text": "宅建業者は全ての事務所に「宅地建物取引業者票（業者票）」と「報酬額表」を掲示しなければなりません（宅建業法50条1項・46条4項）。", "example": "A不動産（本店・支店2か所）の場合、本店・支店の全3か所に業者票と報酬額表を掲示する義務があります。本店だけでは義務違反です。"}, "reason": {"text": "業者票の記載事項：免許証番号・免許有効期間・商号・代表者名・主たる事務所の所在地・専任宅建士の氏名等（顔写真は不要）。案内所等にも標識（業者票）の掲示は必要ですが、報酬額表は事務所のみで足ります。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">掲示が必要な場所と内容</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場所</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">業者票</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">報酬額表</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">主たる事務所（本店）</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従たる事務所（支店）</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">案内所（土地定着・申込み受付）</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（標識）</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">案内所（土地非定着）</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（標識）</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "業者票と報酬額", "reason": "正解です。宅建業者は全ての事務所に業者票と報酬額表を掲示する義務があります（宅建業法50条・46条4項）。", "caution": ""}, {"label": "業者票のみ", "reason": "業者票だけでなく報酬額表も掲示が必要です。両方セットで義務付けられています。", "caution": ""}, {"label": "報酬額のみ", "reason": "報酬額表だけでなく業者票も掲示が必要です。両方が義務です。", "caution": ""}, {"label": "主たる事務所のみに掲示すればよい", "reason": "主たる事務所のみではなく、全ての事務所（従たる事務所も含む）に掲示が必要です。", "caution": ""}], "summary": {"head": ["項目", "内容"], "rows": [["業者票（業者票）", "全事務所に掲示義務"], ["報酬額表", "全事務所に掲示義務"], ["案内所", "業者票は必要・報酬額表は不要"]]}}},
  {id:10026,unit:'k_kenchiku',level:1,field:'limit',text:"建築基準法の接道義務として正しいものはどれか。",opts:["幅員2メートル以上の道路に2メートル以上接しなければならない", "幅員4メートル以上の道路に2メートル以上接しなければならない", "幅員6メートル以上の道路に3メートル以上接しなければならない", "道路への接道は不要"],ans:1,exp:`建築物の敷地は幅員4メートル以上の道路に2メートル以上接しなければなりません（建築基準法43条1項）。これを接道義務（接道要件）といいます。`,"kaisetsu":{"topic": "接道義務：幅員4m以上の道路に2m以上接することが必要", "basis": {"text": "建築物の敷地は「幅員4m以上の道路に2m以上接していること」が必要です（建築基準法43条1項）。これを接道義務といいます。消防車や救急車が通れる道路への接続を確保するためです。", "example": "4m幅の前面道路に面した200㎡の敷地。接道幅が1.5mしかない場合は接道義務を満たさず、原則として建物を建てられません（例外：建築審査会の同意による特例・43条2項）。"}, "reason": {"text": "道路の定義（建築基準法42条）：幅員4m以上の道路。ただし建築基準法施行前から存在する幅員4m未満の道で特定行政庁が指定したもの（2項道路・みなし道路）は4mとみなします。その場合は道路中心線から2m後退（セットバック）が必要です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">接道義務のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">接道の基準</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">幅員4m以上の道路に2m以上接すること</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2項道路（みなし道路）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">幅員4m未満でも特定行政庁指定があれば道路とみなす</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">セットバック</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2項道路の場合は中心線から2m後退が必要</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">例外</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築審査会の同意で例外的に建築可（43条2項）</text></svg>", "choices": [{"label": "幅員4メートル以上の道路に2メートル以上接すること", "reason": "正解です。建築物の敷地は幅員4m以上の道路に2m以上接する必要があります（建築基準法43条1項）。", "caution": ""}, {"label": "幅員6メートル以上の道路に2メートル以上接すること", "reason": "6mは誤りです。正しくは4m以上の道路です。", "caution": ""}, {"label": "幅員4メートル以上の道路に1メートル以上接すること", "reason": "1mは誤りです。正しくは2m以上です。", "caution": "「4m以上の道路に2m以上接する」という数字のセットを正確に覚えてください。"}, {"label": "道路に接していなくても建築できる", "reason": "接道義務が原則です。接道しない敷地では建物を建てられません（例外あり）。", "caution": ""}], "summary": {"head": ["項目", "内容"], "rows": [["接道の基準", "幅員4m以上の道路に2m以上接すること"], ["2項道路", "4m未満でも道路とみなす（セットバック必要）"]]}}},
  {id:10027,unit:'t_joto',level:1,field:'tax',text:"居住用財産を売却した際の3000万円特別控除の適用条件として正しいものはどれか。",opts:["売却年の前年まで居住していればよい", "現に居住している家屋または居住しなくなった日から3年後の年末までに売却", "居住期間が10年以上必要", "毎年適用できる"],ans:1,exp:`3000万円特別控除は現に居住している家屋、または居住しなくなった日から3年後の年末までに売却した場合に適用されます（租税特別措置法35条）。居住期間の制限はありません。`,"kaisetsu":{"topic": "3,000万円特別控除：居住しなくなった日から3年後の年末までの譲渡が対象", "basis": {"text": "居住用財産の3,000万円特別控除は、現に居住している家屋またはその家屋に「居住しなくなった日から3年を経過する日の属する年の12月31日まで」に譲渡した場合に適用されます（租税特別措置法35条1項）。", "example": "Aが自宅を離れたのが2021年6月1日。2024年（3年経過する年）の12月31日までに売却すれば3,000万円控除が適用可能。居住期間の制限はありません（3か月でも10年でも対象）。"}, "reason": {"text": "適用できない場合：①前年・前々年に3,000万円控除を適用した場合（3年に1回の制限）②配偶者・直系血族・生計を一にする親族等への譲渡③仮住まいのために一時的に居住した家屋。長期（5年超）の軽減税率（14%）と併用可能です。"}, "svg": "<svg viewBox=\"0 0 620 275\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">3,000万円特別控除のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"275\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">適用期限</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転居後3年が経過する年の12月31日まで</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">居住期間の制限</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">なし（短期でも可）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">回数制限</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前年・前々年に未適用</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">適用除外</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者・直系血族等への譲渡</text><rect x=\"10\" y=\"225\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">長期軽減税率との併用</text><text x=\"445\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text></svg>", "choices": [{"label": "現に居住している家屋または居住しなくなった日から3年後の年末までに売却", "reason": "正解です。現在居住中の家屋または居住しなくなった日から3年が経過する年の12月31日までの譲渡が対象です（租税特別措置法35条1項）。", "caution": ""}, {"label": "居住期間が10年以上の家屋のみ対象", "reason": "居住期間に制限はありません。3か月でも対象になります（ただし一時的な居住は除く）。", "caution": "居住期間10年以上が要件なのは「居住用財産の買換え特例」等別の特例です。"}, {"label": "転居後1年以内の売却のみ対象", "reason": "1年ではなく「3年が経過する年の12月31日まで」が正しい期限です。", "caution": ""}, {"label": "配偶者への売却でも適用される", "reason": "配偶者・直系血族等への譲渡には適用されません（租税特別措置法35条2項2号）。", "caution": ""}], "summary": {"head": ["項目", "内容"], "rows": [["適用期限", "転居後3年経過する年末まで"], ["居住期間", "制限なし"], ["回数制限", "3年に1回"], ["適用除外", "配偶者・直系血族等への譲渡"]]}}},
  {id:10028,unit:'r_baibai',level:1,field:'rights',text:"民法の原則として、契約の成立に必要なものはどれか。",opts:["書面の作成", "公証人の認証", "申込みと承諾の意思表示の合致", "第三者の立会い"],ans:2,exp:`契約は申込みと承諾の意思表示が合致したときに成立します（民法522条）。原則として書面は不要であり、口頭でも成立します（例外：保証契約・定期借地権等は書面が必要）。`,"kaisetsu":{"topic": "契約の成立：申込みと承諾の意思表示の合致", "basis": {"text": "契約は申込みと承諾の意思表示が合致したときに成立します（民法522条）。原則として書面は不要であり、口頭でも成立します。", "example": "Aが「この土地を1,000万円で売ります」（申込み）、Bが「わかりました、買います」（承諾）と言った時点で口頭の売買契約が成立します。"}, "reason": {"text": "書面が必要な例外：保証契約（民法446条2項）・定期借地権の一部（借地借家法22条等）・定期建物賃貸借（借地借家法38条1項）等。電子メール等の電磁的記録による契約も認められています（民法522条2項）。宅建業法上の37条書面は契約成立後に交付する書面で、契約成立の要件ではありません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">契約成立のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">成立要件</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">申込みと承諾の意思表示の合致</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面不要（口頭でも成立）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面が必要な例外</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約・定期借地権の一部・定期建物賃貸借等</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">電子契約</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">電磁的記録による合意も有効</text></svg>", "choices": [{"label": "書面による合意が必要である", "reason": "原則として書面は不要です（民法522条）。口頭の合意でも契約は成立します。", "caution": "保証契約・定期借地権等の例外はありますが、原則は口頭でも成立です。"}, {"label": "申込みと承諾の意思表示の合致", "reason": "正解です。契約は申込みと承諾の意思表示が合致した時に成立します（民法522条）。", "caution": ""}, {"label": "公証人の認証が必要である", "reason": "公証人の認証は一般的な契約成立の要件ではありません。公正証書が必要なのは事業用定期借地権等の特定の契約のみです。", "caution": ""}, {"label": "2人以上の証人が必要である", "reason": "証人は契約成立の要件ではありません。", "caution": ""}], "summary": {"head": ["項目", "内容"], "rows": [["成立要件", "申込みと承諾の意思表示の合致"], ["原則", "書面不要（口頭でも成立）"], ["例外（書面必要）", "保証契約・定期借地権等"]]}}},
  {id:10029,unit:'l_cooling',level:1,field:'law',text:"宅建業法で定める手付の性質について正しいものはどれか。",opts:["手付は必ず違約手付でなければならない", "宅建業者が自ら売主の場合、手付は解約手付の性質を持つ", "手付金は返還されない", "手付の最低額は代金の5%"],ans:1,exp:`宅建業者が自ら売主の場合、手付は解約手付とみなされます（宅建業法39条2項）。買主は手付を放棄して、業者は手付の倍額を返すことで契約を解除できます。`,"kaisetsu":{"topic": "宅建業者が自ら売主の場合の手付：解約手付として機能", "basis": {"text": "宅建業者が自ら売主として宅建業者以外の者に売却する場合、交付された手付は解約手付とみなされます（宅建業法39条2項）。買主は手付を放棄して、業者は受領した手付の倍額を返還することで解除できます。", "example": "宅建業者Aが一般消費者Bに土地を売却し、B から手付金100万円を受け取った。Aが解除する場合は200万円（倍額）をBに現実に提供して解除できます。"}, "reason": {"text": "手付の上限は代金の20%です（宅建業法39条1項）。手付解除は「相手方が履行に着手した後」はできません（宅建業法39条2項）。これは8種制限（宅建業者が売主の場合の特別ルール）の1つです。業者間取引（売主・買主とも業者）には8種制限は適用されません（宅建業法78条2項）。"}, "svg": "<svg viewBox=\"0 0 620 315\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業者自ら売主の手付のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"315\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">手付の性質</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解約手付として機能（民法では推定だが業法では強制）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">手付の上限</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金の20%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主による解除</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">手付を放棄</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者（売主）による解除</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">受領した手付の倍額を現実に提供</text><rect x=\"10\" y=\"225\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除できない時期</text><text x=\"445\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が履行に着手した後</text><rect x=\"10\" y=\"265\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"290\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">適用対象</text><text x=\"445\" y=\"290\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売主が業者・買主が一般消費者の場合</text></svg>", "choices": [{"label": "宅建業者が自ら売主の場合、手付は解約手付とみなされる", "reason": "正解です。宅建業者が自ら売主の場合、手付は解約手付とみなされます（宅建業法39条2項）。", "caution": ""}, {"label": "手付の性質は当事者が自由に決められる", "reason": "宅建業者が自ら売主の場合は法律上解約手付として機能します（宅建業法39条2項）。当事者が「証約手付のみ」と定めても無効です。", "caution": ""}, {"label": "手付は代金の30%まで受け取れる", "reason": "宅建業者が自ら売主の場合の手付の上限は代金の20%です（宅建業法39条1項）。30%は誤りです。", "caution": ""}, {"label": "業者間取引でも8種制限が適用される", "reason": "売主・買主ともに宅建業者の取引（業者間取引）には8種制限は適用されません（宅建業法78条2項）。", "caution": ""}], "summary": {"head": ["項目", "内容"], "rows": [["手付の性質", "解約手付として機能"], ["手付の上限", "代金の20%"], ["買主による解除", "手付を放棄"], ["業者による解除", "受領した手付の倍額を現実提供"], ["適用対象", "売主業者・買主一般消費者のみ"]]}}},
  {id:10030,unit:'k_toshi',level:1,field:'limit',text:"都市計画区域と準都市計画区域の違いとして正しいものはどれか。",opts:["準都市計画区域では建築規制が一切ない", "準都市計画区域は都市計画区域外の一定地域に指定される", "両者に違いはない", "準都市計画区域は農業専用地域に指定される"],ans:1,exp:`準都市計画区域は都市計画区域外の地域のうち、相当数の建築物の建築等が行われ無秩序な土地利用を防ぐ必要がある地域に指定されます（都市計画法5条の2）。`,"kaisetsu":{"topic": "準都市計画区域：都市計画区域外の一定地域に指定される", "basis": {"text": "準都市計画区域は都市計画区域外の地域のうち、相当数の建築物の建築等が行われ、または行われると見込まれる地域で、無秩序な土地利用を防ぐ必要がある地域に指定されます（都市計画法5条の2）。", "example": "幹線道路沿いの都市計画区域外の土地で、大型ショッピングモールや住宅が無秩序に建設されるのを防ぐために準都市計画区域に指定されることがあります。"}, "reason": {"text": "準都市計画区域にも用途地域等を定めることができます（都市計画法8条1項）。ただし市街化区域・市街化調整区域の区域区分（線引き）は定められません。建築基準法・農地法等の規制は準都市計画区域にも適用されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画区域と準都市計画区域</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">区域</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場所</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">特徴</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都市計画区域</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都市として一体の区域</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域・調整区域等を含む</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">準都市計画区域</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都市計画区域外の一定地域</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無秩序な土地利用を防ぐ必要がある地域</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都市計画区域外</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">上記以外の区域</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築基準法の一部のみ適用</text></svg>", "choices": [{"label": "準都市計画区域は都市計画区域外の一定地域に指定される", "reason": "正解です。準都市計画区域は都市計画区域外の地域で無秩序な土地利用を防ぐ必要がある地域に指定されます（都市計画法5条の2）。", "caution": ""}, {"label": "準都市計画区域は都市計画区域内に指定される", "reason": "準都市計画区域は都市計画区域外の地域に指定されます。都市計画区域内ではありません。", "caution": ""}, {"label": "準都市計画区域では建築基準法は適用されない", "reason": "準都市計画区域にも建築基準法は適用されます。", "caution": ""}, {"label": "準都市計画区域には市街化区域と市街化調整区域の区分がある", "reason": "市街化区域・市街化調整区域の区域区分（線引き）は都市計画区域内のみに適用されます。準都市計画区域には区域区分は設けられません。", "caution": ""}], "summary": {"head": ["区域", "場所"], "rows": [["都市計画区域", "都市としての区域（線引きあり）"], ["準都市計画区域", "都市計画区域外で無秩序な土地利用を防ぐ必要がある地域"]]}}},
  {id:10031,unit:'r_bukken',level:1,field:'rights',text:"Aが所有する土地にBが無断で建物を建てた。AのBに対する請求として誤っているものはどれか。",opts:["建物の収去（取り壊し）請求", "土地の明渡し請求", "損害賠償請求", "土地の売却を強制する請求"],ans:3,exp:`土地所有者Aは、不法占拠者Bに対して建物の収去・土地明渡し・損害賠償を請求できます。しかし、土地を強制的に売却させる権利（売却強制）はありません。`,"kaisetsu":{"topic": "物権的請求権：土地所有者は不法占拠者に建物収去・土地明渡し・損害賠償を請求できる", "basis": {"text": "土地所有者は不法占拠者に対して①建物の収去②土地の明渡し③損害賠償を請求できます。しかし不法占拠者に土地を強制的に売却させる権利（売却強制）は認められていません。", "example": "Aの土地にBが無断で建物を建てた。AはBに対して建物を壊して（収去）土地を明け渡すことを請求できます。また不法占拠による損害賠償も請求できます。"}, "reason": {"text": "物権的請求権の種類：①返還請求権（物を返せ）②妨害排除請求権（妨害をやめろ）③妨害予防請求権（妨害のおそれを除去せよ）。故意・過失は不要で、現在占有していることが要件です。不法占拠者には登記なく所有権を主張できます（判例）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">物権的請求権の種類</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">請求権</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">要件</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">返還請求権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">物の返還・土地明渡しを求める</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">現在の占有者に（故意過失不要）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">妨害排除請求権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">妨害の除去を求める</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">現に妨害されている</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">妨害予防請求権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">妨害のおそれを除去</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">妨害の危険がある</text></svg>", "choices": [{"label": "建物の収去を請求できる", "reason": "正解の一つです（ただし本問は「誤っているもの」を問う問題で正解は選択肢3）。建物の収去請求は認められます。", "caution": ""}, {"label": "土地の明渡しを請求できる", "reason": "土地の明渡し請求は認められます。本問の正解は「土地の売却を強制する請求（選択肢3）」です。", "caution": ""}, {"label": "土地の売却を強制する請求", "reason": "正解（誤り）です。土地所有者は不法占拠者に土地を強制的に売却させる権利はありません。", "caution": ""}, {"label": "損害賠償を請求できる", "reason": "不法占拠による損害賠償請求は認められます（不法行為・民法709条）。", "caution": ""}], "summary": {"head": ["請求", "認められるか"], "rows": [["建物収去請求", "認められる"], ["土地明渡し請求", "認められる"], ["損害賠償請求", "認められる"], ["売却強制", "認められない"]]}}},
  {id:10032,unit:'t_inshi',level:1,field:'tax',text:"印紙税の課税文書に該当するものはどれか。",opts:["口頭での売買の約束", "不動産の売買契約書", "電子メールでの売買合意", "業者への売却の依頼"],ans:1,exp:`不動産の売買契約書は印紙税の課税文書に該当します（印紙税法別表第一）。口頭での合意や電子メールは文書ではないため課税されません。電子的な契約書も原則として課税対象外です。`,"kaisetsu":{"topic": "印紙税：不動産売買契約書は課税文書・電子契約は非課税", "basis": {"text": "不動産の売買契約書（第1号文書）は印紙税の課税文書です（印紙税法別表第一）。印紙を貼付して消印する必要があります。電子的な契約書（電磁的記録）は「文書」に当たらないため課税されません。", "example": "A・B間で土地の売買契約書（紙）を作成した場合→印紙税が課税されます。電子メールで売買合意した場合→印紙税は課税されません（電磁的記録のため）。"}, "reason": {"text": "記載金額が1万円未満のものは非課税です。契約書が複数作成される場合は、当事者がそれぞれ保有する各通すべてに印紙が必要です。電子契約書（PDF等）が課税されないため、近年電子契約が増加しています。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">印紙税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税文書（不動産）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買契約書・賃貸借契約書等（第1号文書）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">電子契約</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税対象外（文書でないため）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1万円未満の記載金額</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">複数部数</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各通に印紙が必要</text></svg>", "choices": [{"label": "不動産の売買契約書", "reason": "正解です。不動産の売買契約書は印紙税の課税文書（第1号文書）に該当します（印紙税法別表第一）。", "caution": ""}, {"label": "口頭での売買合意", "reason": "口頭での合意は文書ではないので印紙税の課税対象外です。", "caution": ""}, {"label": "電子メールによる売買合意", "reason": "電子メールは電磁的記録であり課税文書に当たらないため印紙税は課税されません。", "caution": ""}, {"label": "不動産売買に関する見積書", "reason": "見積書は課税文書に該当しません（不動産売買契約書とは異なります）。", "caution": ""}], "summary": {"head": ["文書の種類", "課税/非課税"], "rows": [["不動産の売買契約書", "課税文書"], ["電子契約（電磁的記録）", "非課税"], ["口頭での合意", "非課税"], ["記載金額1万円未満", "非課税"]]}}},
  {id:10033,unit:'l_37jo',level:1,field:'law',text:"宅建業者が宅地の売買を媒介する際の義務として正しいものはどれか。",opts:["必ず公正証書で契約書を作成する", "売買契約成立後、遅滞なく37条書面を交付する", "相手方に弁護士を紹介する", "2週間以内に登記申請を行う"],ans:1,exp:`宅建業者は売買契約成立後、遅滞なく37条書面（契約書面）を作成して当事者に交付しなければなりません（宅建業法37条）。公正証書での作成は義務ではありません。`,"kaisetsu":{"topic": "37条書面：売買契約成立後・遅滞なく・双方に交付", "basis": {"text": "宅建業者は売買契約が成立した後、遅滞なく37条書面を作成して当事者（売主・買主の双方）に交付しなければなりません（宅建業法37条1項）。「遅滞なく」とはできるだけ速やかに、という意味です。", "example": "A不動産がBとCの売買を媒介した。売買契約が成立した日に、A不動産は売主BとC双方に37条書面を交付しなければなりません（公正証書でなくてよい）。"}, "reason": {"text": "37条書面の特徴：①全取引（売買・交換・賃貸借）で交付義務②双方当事者に交付（売買なら売主・買主の双方）③宅建士の記名が必要（押印は2021年改正で不要）④電磁的記録による交付も可能（相手方の承諾が必要）。35条書面（契約前）と混同しないこと。"}, "svg": "<svg viewBox=\"0 0 620 275\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"275\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付時期</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">契約成立後、遅滞なく</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">契約の双方当事者</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要・2021年改正）</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公正証書</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（書面でよい）</text><rect x=\"10\" y=\"225\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">電磁的記録</text><text x=\"445\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方の承諾があれば可</text></svg>", "choices": [{"label": "売買契約成立後、遅滞なく37条書面を交付しなければならない", "reason": "正解です。37条書面は契約成立後遅滞なく交付が義務です（宅建業法37条1項）。", "caution": ""}, {"label": "37条書面は公正証書で作成しなければならない", "reason": "37条書面は書面（私文書）で足り、公正証書の作成は不要です。", "caution": "公正証書が必要なのは事業用定期借地権等の特定の契約です。"}, {"label": "37条書面は売主のみに交付すればよい", "reason": "37条書面は売主・買主双方（契約当事者）に交付が必要です。「売主のみ」は誤りです。", "caution": ""}, {"label": "37条書面の交付は任意である", "reason": "37条書面の交付は義務です（宅建業法37条1項）。任意ではありません。", "caution": ""}], "summary": {"head": ["項目", "内容"], "rows": [["交付時期", "契約成立後、遅滞なく"], ["交付先", "双方当事者（売主・買主等）"], ["宅建士の関与", "記名（押印不要）"], ["公正証書", "不要"]]}}},
  {id:10034,unit:'r_ishi',level:1,field:'rights',text:"民法上の「意思能力」がない状態でした法律行為の効力として正しいものはどれか。",opts:["取り消すことができる", "無効である", "有効だが後で追認が必要", "相手方が選択できる"],ans:1,exp:`意思能力を欠く状態でした法律行為は無効です（民法3条の2）。制限行為能力者の行為は「取り消しうる行為」ですが、意思能力のない者の行為は当然無効となります。`,"kaisetsu":{"topic": "意思能力のない者の法律行為：当然無効", "basis": {"text": "意思能力（自分の行為の法的結果を弁識できる能力）を欠く状態でした法律行為は無効です（民法3条の2）。「取り消しうる行為」ではなく「当然無効」です。", "example": "重度の認知症で判断能力が全くない状態のAが自宅を売却した場合、その売買契約は意思能力の欠如により当然無効です（成年後見人が取り消す必要もない）。"}, "reason": {"text": "意思能力の欠如による無効と制限行為能力による取消しの違いが重要です。意思能力がない＝当然無効（最初から効力なし）。制限行為能力者（未成年者・成年被後見人等）の行為＝取消しうる行為（取消すまでは有効）。2017年の民法改正で明文化されました（民法3条の2）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思能力と制限行為能力の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">状態</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">根拠</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">意思能力を欠く（重度の認知症等）</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">当然無効（最初から効力なし）</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">民法3条の2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">未成年者（同意なし）</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消しうる行為（取り消すまで有効）</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">民法5条2項</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">成年被後見人（日用品以外）</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消しうる行為</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">民法9条</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">被保佐人（重要行為・同意なし）</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消しうる行為</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">民法13条</text></svg>", "choices": [{"label": "無効である", "reason": "正解です。意思能力を欠く状態でした法律行為は無効です（民法3条の2）。", "caution": ""}, {"label": "取り消しうる行為である", "reason": "意思能力の欠如による行為は「取り消しうる行為」ではなく「当然無効」です。制限行為能力者の行為と混同しないように。", "caution": "「意思能力なし→無効」「制限行為能力者→取消しうる行為」の区別が重要です。"}, {"label": "相手方が取り消すことができる", "reason": "意思能力の欠如による行為は取消しではなく無効なので、誰が取り消す、という問題ではありません。", "caution": ""}, {"label": "追認すれば有効になる", "reason": "無効な行為は追認しても有効にはなりません。取消しうる行為は追認で有効になりますが、無効な行為とは異なります。", "caution": ""}], "summary": {"head": ["状態", "効果"], "rows": [["意思能力を欠く", "当然無効"], ["制限行為能力者の行為", "取消しうる行為（追認で有効）"]]}}},
  {id:10035,unit:'r_ishi',level:1,field:'rights',text:"強迫による意思表示の取消しについて正しいものはどれか。",opts:["善意の第三者にも対抗できる", "善意無過失の第三者には対抗できない", "取消しはできず損害賠償のみ請求できる", "強迫者以外には取消しを主張できない"],ans:0,exp:`強迫による意思表示の取消しは、善意の第三者に対しても対抗できます（民法96条3項の反対解釈）。詐欺は善意無過失の第三者に対抗できませんが、強迫はより保護が強くすべての第三者に対抗できます。`,"kaisetsu":{"topic": "強迫による取消し：善意の第三者にも対抗できる", "basis": {"text": "強迫による意思表示の取消しは、善意の第三者に対しても対抗できます（民法96条3項の反対解釈）。詐欺の場合は善意無過失の第三者に対抗できませんが、強迫の場合は第三者保護がありません。", "example": "Aが強迫されてBに不動産を売却した後、BがCに転売した。Aが強迫を理由に取り消した場合、CがAの強迫を知らない（善意）であっても、AはCに取消しを対抗できます。"}, "reason": {"text": "強迫の場合に第三者保護がない理由：強迫を受けた被害者を手厚く保護するため（詐欺より重大な意思の自由の侵害）。比較：詐欺→善意無過失の第三者は保護される（民法96条3項）。通謀虚偽表示→善意の第三者は保護される（民法94条2項）。強迫→第三者は保護されない（民法96条3項の反対解釈）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">取消しと第三者保護の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">善意の第三者</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">善意無過失の第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺取消し</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保護される</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保護される（対抗不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫取消し</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保護されない（対抗可）</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保護されない（対抗可）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤取消し</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保護される</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保護される（対抗不可）</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保護される（94条2項）</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">—</text></svg>", "choices": [{"label": "善意の第三者にも対抗できる", "reason": "正解です。強迫による取消しは善意の第三者にも対抗できます（民法96条3項の反対解釈）。", "caution": ""}, {"label": "善意の第三者には対抗できない", "reason": "強迫の場合は善意の第三者にも対抗できます（第三者保護なし）。「対抗できない」は詐欺の場合の説明です。", "caution": "「詐欺→善意無過失は保護」「強迫→第三者は保護なし」の対比を確実に覚えてください。"}, {"label": "第三者が登記を備えていれば対抗できない", "reason": "強迫取消しの場合は登記の有無にかかわらず第三者に対抗できます。", "caution": ""}, {"label": "強迫による取消しは6か月以内にしなければならない", "reason": "取消権の時効消滅は「追認できる時から5年」または「行為の時から20年」です（民法126条）。6か月は誤りです。", "caution": ""}], "summary": {"head": ["種類", "第三者保護"], "rows": [["詐欺取消し", "善意無過失の第三者は保護"], ["強迫取消し", "第三者は保護なし（全員に対抗可）"]]}}},
  {id:10036,unit:'r_dairi',level:1,field:'rights',text:"任意代理と法定代理の違いとして正しいものはどれか。",opts:["任意代理は本人の死亡で終了するが、法定代理は終了しない", "任意代理は本人の意思で設定され、法定代理は法律の規定で設定される", "任意代理のみ復代理人を選任できる", "法定代理には顕名が不要"],ans:1,exp:`任意代理は本人の授権行為（委任等）によって設定され、法定代理は法律の規定（親権・後見等）によって設定されます。どちらも顕名が必要です。`,"kaisetsu":{"topic": "任意代理と法定代理：任意代理は授権行為・法定代理は法律の規定", "basis": {"text": "任意代理は本人の授権行為（委任等）によって設定されます。法定代理は法律の規定（親権・後見等）によって設定されます。どちらも代理人が顕名（本人のためにすることを示すこと）して行動します（民法99条1項）。", "example": "Aが「この土地の売買についてBを代理人に任命します」という委任→任意代理。親CがD（未成年の子）の法定代理人として行動→法定代理（法律の規定による）。"}, "reason": {"text": "任意代理人の代理権消滅事由：①本人の死亡②代理人の死亡③代理人の後見開始④代理人の破産手続開始⑤本人・代理人間の基本的な法律関係（委任等）の終了（民法111条）。法定代理権の消滅は各法律の規定による（例：子が成年に達したら親権終了）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">任意代理と法定代理の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">区分</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">任意代理</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">法定代理</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">設定</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人の授権行為（委任等）</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法律の規定（親権・後見等）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理権の範囲</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">授権の範囲内</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法律の定める範囲内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">復代理人選任</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則不可（許諾等があれば可）</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">常に選任可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理権消滅</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人死亡・代理人死亡等</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各法律の規定による</text></svg>", "choices": [{"label": "任意代理は本人の意思で設定され、法定代理は法律の規定による", "reason": "正解です。任意代理は本人の授権行為（委任等）、法定代理は法律の規定（親権・後見等）によって設定されます。", "caution": ""}, {"label": "任意代理は法律の規定によって設定される", "reason": "法律の規定によって設定されるのは法定代理です。任意代理は本人の授権行為によります。", "caution": ""}, {"label": "法定代理は本人の意思で設定される", "reason": "本人の意思（授権行為）によって設定されるのは任意代理です。法定代理は法律の規定によります。", "caution": ""}, {"label": "任意代理と法定代理では、顕名の要否が異なる", "reason": "任意代理・法定代理のいずれも顕名が必要です（民法99条1項）。顕名の要否は同じです。", "caution": ""}], "summary": {"head": ["区分", "任意代理", "法定代理"], "rows": [["設定", "授権行為（委任等）", "法律の規定（親権・後見等）"], ["復代理", "原則不可", "常に選任可"]]}}},
  {id:10037,unit:'r_jiko',level:1,field:'rights',text:"取得時効の成立に必要な占有の態様として正しいものはどれか。",opts:["隠れた占有でも成立する", "自主占有（所有の意思をもって）かつ平穏・公然・継続が必要", "占有開始が善意の場合は5年で成立する", "占有は断続的でもよい"],ans:1,exp:`取得時効が成立するためには、所有の意思をもって（自主占有）、平穏かつ公然に、継続して占有することが必要です（民法162条）。善意無過失の場合は10年、悪意または有過失の場合は20年です。`,"kaisetsu":{"topic": "取得時効の要件：自主占有・平穏・公然・継続して占有", "basis": {"text": "取得時効が成立するためには「所有の意思をもって（自主占有）、平穏かつ公然に、継続して占有すること」が必要です（民法162条）。善意無過失の場合は10年、悪意または過失がある場合は20年で時効が完成します。", "example": "Aが他人Bの土地を「自分の土地だと思って」（善意・無過失）平穏に占有し続けた。10年経過で取得時効が完成し、Aは所有権を取得できます（援用が必要）。"}, "reason": {"text": "自主占有とは「所有の意思をもって占有すること」です。賃借人・使用借人の占有は自主占有ではなく（他主占有）取得時効の対象にはなりません。占有の途中で承継があった場合は占有期間を通算できます（民法187条1項）。"}, "svg": "<svg viewBox=\"0 0 620 315\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">取得時効の要件と期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">要件</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"315\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自主占有</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">所有の意思をもって占有（賃借人等は不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">平穏・公然</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">暴力・隠秘でない占有</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">継続</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">中断なく占有が続いていること</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失の場合</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年で時効完成</text><rect x=\"10\" y=\"225\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">悪意または過失がある場合</text><text x=\"445\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">20年で時効完成</text><rect x=\"10\" y=\"265\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"290\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">援用</text><text x=\"445\" y=\"290\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">時効を援用して初めて効力が発生</text></svg>", "choices": [{"label": "自主占有（所有の意思をもって）かつ平穏・公然に継続して占有すること", "reason": "正解です。取得時効の成立には自主占有・平穏・公然・継続が必要です（民法162条）。", "caution": ""}, {"label": "他主占有でも取得時効は成立する", "reason": "賃借人等の他主占有（他人のものとして占有）では取得時効は成立しません。自主占有が必要です。", "caution": ""}, {"label": "占有が中断されても時効期間が継続する", "reason": "占有の中断（例：裁判上の請求・差押え等）があると時効は更新されてゼロからリスタートします。", "caution": ""}, {"label": "意識的に隠して占有することでも取得時効は成立する", "reason": "隠秘（秘密にして）の占有は「公然」という要件を満たさないため取得時効は成立しません。", "caution": ""}], "summary": {"head": ["要件", "内容"], "rows": [["自主占有", "所有の意思をもって占有"], ["平穏・公然", "暴力・隠秘でない"], ["継続", "中断なく継続"], ["期間", "善意無過失→10年、悪意または過失→20年"]]}}},
  {id:10038,unit:'r_bukken',level:1,field:'rights',text:"不動産の登記の効力として正しいものはどれか。",opts:["登記があれば必ず所有権が認められる", "登記は物権変動の対抗要件であり権利の存在を推定させる", "登記がなければ当事者間でも権利は生じない", "登記には絶対的な公信力がある"],ans:1,exp:`不動産登記は物権変動の対抗要件です（民法177条）。登記があれば権利の存在が推定されますが（民法188条の類推）、公信力はなく登記を信頼して取引しても保護されないことがあります。`,"kaisetsu":{"topic": "不動産登記の効力：対抗要件・推定力あり・公信力なし", "basis": {"text": "不動産登記は物権変動の「対抗要件」です（民法177条）。登記があれば権利の存在が「推定」されますが（民法188条の類推）、「公信力」はありません。つまり登記を信頼して取引しても保護されないことがあります。", "example": "登記名義はAだが実際の所有者はBの場合。Cが登記を信頼してAから購入しても、Bが真の所有者なら保護されない可能性があります（公信力なし）。"}, "reason": {"text": "推定力：登記があれば権利が存在するものと推定される（反証可能）。公信力：登記を信頼した取引者を保護する効力（日本の不動産登記にはない）。動産の即時取得（民法192条）は公信力に類似した保護ですが、不動産に即時取得は適用されません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産登記の効力</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効力</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">あるか</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">対抗要件</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">物権変動を第三者に主張するために必要</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">あり（民法177条）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">推定力</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記があれば権利の存在が推定される</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">あり（事実上）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公信力</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記を信頼した取引者を保護</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">なし（日本は公信力なし）</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">形成力</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記によって権利が生まれる</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">なし（対抗要件のみ）</text></svg>", "choices": [{"label": "登記は物権変動の対抗要件であり権利の存在を推定させる", "reason": "正解です。登記は対抗要件であり、登記があれば権利の存在が推定されます。ただし公信力はありません。", "caution": ""}, {"label": "登記は物権変動の効力発生要件である", "reason": "登記は対抗要件（第三者への主張に必要）であり、効力発生要件（成立に必要）ではありません。当事者間では登記なしでも物権変動は成立します。", "caution": ""}, {"label": "登記を信頼して取引した者は常に保護される（公信力あり）", "reason": "日本の不動産登記には公信力がないため、登記を信頼した取引者が常に保護されるとは限りません。", "caution": ""}, {"label": "登記がなければ当事者間でも物権変動の効力が生じない", "reason": "当事者間では登記なしでも物権変動（所有権移転等）は成立します。登記は第三者への対抗要件です。", "caution": ""}], "summary": {"head": ["効力", "あるか"], "rows": [["対抗要件", "あり"], ["推定力", "あり（事実上）"], ["公信力", "なし（日本の不動産登記）"]]}}},
  {id:10039,unit:'r_tanpo',level:1,field:'rights',text:"先取特権に関して正しいものはどれか。",opts:["先取特権は当事者の合意で設定する担保物権である", "先取特権は法律の規定によって当然に発生する担保物権である", "先取特権は登記がなければ第三者に対抗できない", "先取特権は動産にのみ成立する"],ans:1,exp:`先取特権は法律が定めた一定の事由が生じると当然に発生する法定担保物権です（民法303条）。合意で設定する必要はなく、法律の要件を満たせば自動的に生じます。`,"kaisetsu":{"topic": "先取特権：法律の規定によって当然に発生する法定担保物権", "basis": {"text": "先取特権は法律が定めた一定の事由が生じると当然に発生する「法定担保物権」です（民法303条）。合意（契約）で設定する必要はなく、法律の要件を満たせば自動的に生じます。", "example": "Aの会社で働くBへの未払い賃金（雇用関係の先取特権）。BはA会社の財産全般について先取特権を持ち、一般債権者に優先して賃金を回収できます（契約や登記なしに当然成立）。"}, "reason": {"text": "先取特権の種類：①一般の先取特権（全財産に及ぶ：共益費用・雇用関係・葬式費用・日用品供給）②動産先取特権（特定の動産に及ぶ：不動産の賃貸等）③不動産先取特権（特定の不動産に及ぶ：不動産工事・不動産売買等）。優先弁済権あり（抵当権等との優先順位は法律で規定）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">先取特権のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">性質</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保物権（合意不要・当然発生）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">優先弁済権</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">あり（一般債権者に優先）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">種類（主なもの）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般・動産・不動産先取特権</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公示方法</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記（不動産先取特権）または目的物の占有（動産）</text></svg>", "choices": [{"label": "先取特権は法律の規定によって当然に発生する", "reason": "正解です。先取特権は法定担保物権で、法律の要件を満たせば合意なしに当然に成立します（民法303条）。", "caution": ""}, {"label": "先取特権は当事者間の合意によって設定される", "reason": "合意で設定するのは「約定担保物権（抵当権・質権）」です。先取特権は合意不要の法定担保物権です。", "caution": "「先取特権→法定担保物権（合意不要）」「抵当権・質権→約定担保物権（合意で設定）」の区別を覚えてください。"}, {"label": "先取特権に優先弁済権はない", "reason": "先取特権には優先弁済権があります（法定担保物権の重要な機能）。一般債権者に優先して弁済を受けることができます。", "caution": ""}, {"label": "先取特権は登記なければ発生しない", "reason": "先取特権は法律の要件を満たせば登記なしに当然発生します（登記は対抗要件・公示手段であり成立要件ではありません）。", "caution": ""}], "summary": {"head": ["項目", "内容"], "rows": [["性質", "法定担保物権（合意不要）"], ["優先弁済権", "あり"], ["代表例", "未払い賃金（雇用関係の先取特権）"]]}}},
  {id:10040,unit:'r_saikensoron',level:1,field:'rights',text:"債務不履行に基づく損害賠償請求の要件として不要なものはどれか。",opts:["債務不履行（履行遅滞・不能・不完全履行）の事実", "損害の発生", "債務不履行と損害の因果関係", "債務者の故意・過失（帰責事由）が常に必要"],ans:3,exp:`2020年民法改正後、損害賠償請求に債務者の帰責事由は必ずしも必要ではありません（民法415条1項ただし書き）。ただし「契約その他の債務の発生原因及び取引上の社会通念に照らして」責めに帰することができないときは免責されます。`,"kaisetsu":{"topic": "債務不履行による損害賠償：2020年改正で帰責事由は常に必要ではない", "basis": {"text": "2020年の民法改正後、債務不履行に基づく損害賠償請求に債務者の故意・過失（帰責事由）は「常に必要」ではありません（民法415条1項ただし書）。債務者が「契約その他の債務の発生原因及び取引上の社会通念に照らして責めに帰することができない事由」によることを証明すれば免責されます。", "example": "AがBに物を売る契約をしたが、天災（地震等）によって物が滅失した場合。Bは帰責事由（故意・過失）がないことを証明して損害賠償を免れることができます。"}, "reason": {"text": "2020年改正前：故意または過失がある場合に損害賠償責任（帰責事由必要）。2020年改正後：「帰責事由がない場合」には免責（逆から見れば帰責事由があれば責任）という構成。実質的には大きな変化はないが、規定の文言が変わりました。帰責事由（故意・過失）は損害賠償の要件であることに変わりはありません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">2020年改正後の損害賠償請求</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債務者の帰責事由がある場合に損害賠償責任</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">免責</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">契約等の趣旨から帰責事由がない場合</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">帰責事由の証明</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債務者側が帰責事由のないことを証明</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">天災等</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通常は帰責事由なしとして免責可能</text></svg>", "choices": [{"label": "債権者の損害が発生していることが必要", "reason": "正解の一つです（本問の正解は選択肢3「帰責事由が常に必要」）。損害の発生は損害賠償請求の要件です。", "caution": ""}, {"label": "債務不履行が存在することが必要", "reason": "正解の一つです。債務不履行（履行しない・遅れる・不完全な履行）の存在は要件です。", "caution": ""}, {"label": "債務者の故意・過失（帰責事由）が常に必要である", "reason": "正解（「誤っているもの」として）。2020年改正後、帰責事由は「常に必要」ではなく、帰責事由がないことを証明すれば免責されます（民法415条1項ただし書）。", "caution": "「帰責事由が常に必要」というのは改正前の考え方です。"}, {"label": "債務不履行と損害の間に因果関係が必要", "reason": "正解の一つです。因果関係（債務不履行があったから損害が生じた）は損害賠償の要件です。", "caution": ""}], "summary": {"head": ["要件", "必要か"], "rows": [["債務不履行", "必要"], ["損害の発生", "必要"], ["因果関係", "必要"], ["帰責事由", "免責される場合あり（常に必要ではない）"]]}}},
  {id:10041,unit:'r_baibai',level:1,field:'rights',text:"売買契約において買主が代金を支払わない場合、売主が取れる手段として誤っているものはどれか。",opts:["履行の強制（支払いを求める訴訟）", "相当期間を定めた催告後の解除", "損害賠償請求", "即時に契約を無効とする申告"],ans:3,exp:`売買契約を無効にする申告という手続きは民法上存在しません。売主が取れる手段は履行請求（強制）・解除・損害賠償請求です（民法541条・542条・415条）。`,"kaisetsu":{"topic": "売買代金不払い時の売主の手段：履行請求・解除・損害賠償（即時の無効申告は不可）", "basis": {"text": "売主が取れる手段は①履行請求（強制的に代金を払わせる）②解除（相当期間を定めた催告後）③損害賠償の請求です（民法541条・415条）。「即時に契約を無効とする申告」という手続きは民法上存在しません。", "example": "AがBに土地を売ったが、BがAに代金を支払わない。AはBに対して催告（相当期間を定めた支払いの要求）をし、期間内に支払わなければ解除できます。"}, "reason": {"text": "解除の原則手続き：①相当の期間を定めて催告→②期間内に不履行→③解除の意思表示。例外として無催告解除が認められる場合（明らかに履行しない意思表示・全部不能等）もあります（民法542条）。売主の手段：①代金支払いを求める訴訟②代金不払いを理由とした解除③損害賠償請求。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">売主が取れる手段</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">手段</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">根拠</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">履行請求</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金支払いを強制的に求める</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">民法414条</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">催告解除</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相当期間を定めた催告後に解除</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">民法541条</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無催告解除</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">明らかに履行しない等の場合</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">民法542条</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">損害賠償</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">損害の賠償を求める</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">民法415条</text></svg>", "choices": [{"label": "相当の期間を定めて催告し、それでも支払われなければ解除できる", "reason": "正解の一つです（本問の正解は選択肢3「即時の無効申告」）。催告後の解除は正しい手段です（民法541条）。", "caution": ""}, {"label": "損害賠償を請求できる", "reason": "損害賠償請求も認められます。本問の正解は選択肢3（誤っているもの）です。", "caution": ""}, {"label": "即時に契約を無効とする申告ができる", "reason": "正解（誤りとして）。「契約を無効とする申告」という手続きは民法上存在しません。解除・無効は要件や手続きが定められており、「即時の無効申告」はできません。", "caution": ""}, {"label": "代金の支払いを求める訴訟を提起できる", "reason": "代金支払いを求める訴訟（履行請求）は認められます。本問の正解は選択肢3です。", "caution": ""}], "summary": {"head": ["手段", "可否"], "rows": [["履行請求（代金を払わせる）", "可"], ["催告後の解除", "可"], ["損害賠償請求", "可"], ["即時の無効申告", "不可（そのような手続きはない）"]]}}},
  {id:10042,unit:'r_chinshaku',level:1,field:'rights',text:"建物賃貸借の期間と更新に関して正しいものはどれか。",opts:["賃貸借の期間は最長20年", "建物賃貸借は期間の定めがない場合でも自動的に解約される", "期間満了後も賃借人が使用継続し貸主が異議を述べなければ同条件で更新とみなされる", "賃貸借に期間の定めは必須"],ans:2,exp:`期間満了後も賃借人が使用収益を継続し、賃貸人がこれを知りながら異議を述べない場合は、従前と同一条件で更新したものとみなされます（民法619条1項）。`,"kaisetsu":{"topic": "建物賃貸借の法定更新：借主が使用継続+貸主が異議を述べない場合", "basis": {"text": "建物の賃貸借で期間が満了した後も借主が使用を継続し、賃貸人がこれを知りながら異議を述べない場合は、従前と同一の条件で更新したものとみなされます（民法619条1項・借地借家法26条）。これを「法定更新」といいます。", "example": "賃貸期間2年の賃貸借が終了後もBが継続居住し、AがAを知りながら異議を述べなかった場合、賃貸借は自動更新されます（法定更新）。ただし更新後は期間の定めのない賃貸借となります。"}, "reason": {"text": "借地借家法の建物賃貸借では、期間満了の1年前〜6か月前に更新拒絶の通知が必要で、かつ「正当事由」がなければ更新を拒絶できません（借地借家法26条・28条）。法定更新後の賃貸借は期間の定めのないものとなります。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建物賃貸借の更新のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定更新の条件</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借主が使用継続＋貸主が知りながら異議を述べない</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">更新拒絶の要件</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1年前〜6か月前の通知＋正当事由</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定更新後の期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間の定めのない賃貸借（合意更新の場合は有期も可）</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間の定めのない賃貸借の解約</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解約申入れ後6か月で終了</text></svg>", "choices": [{"label": "期間満了と同時に賃貸借は終了する", "reason": "借主が使用継続し貸主が異議を述べない場合は法定更新されます。当然に終了するわけではありません。", "caution": ""}, {"label": "期間満了後も賃借人が使用継続し貸主が異議を述べない場合は自動更新とみなす", "reason": "正解です。借主の使用継続＋貸主の沈黙（異議なし）で法定更新されます（民法619条1項・借地借家法26条）。", "caution": ""}, {"label": "期間満了後は貸主の許可がなければ居住できない", "reason": "法定更新のルールにより、自動更新が認められるため、明示的な許可なしに居住継続が認められます。", "caution": ""}, {"label": "期間満了後6か月間は居住できるが、その後は退去しなければならない", "reason": "6か月という期間制限はありません。法定更新によって引き続き居住できます。", "caution": ""}], "summary": {"head": ["状況", "結論"], "rows": [["借主が使用継続＋貸主が異議なし", "法定更新（従前と同一条件）"], ["更新拒絶", "1年前〜6か月前の通知＋正当事由が必要"], ["法定更新後の期間", "期間の定めのない賃貸借"]]}}},
  {id:10043,unit:'r_souzoku',level:1,field:'rights',text:"遺留分の割合として正しいものはどれか（相続人が配偶者のみの場合）。",opts:["法定相続分の4分の1", "法定相続分の2分の1", "法定相続分の3分の1", "遺留分はない"],ans:1,exp:`相続人が配偶者のみの場合、遺留分は法定相続分（全部）の2分の1、つまり財産全体の2分の1です（民法1042条1項）。直系尊属のみが相続人の場合は3分の1です。`,"kaisetsu":{"topic": "遺留分：配偶者のみが相続人の場合は財産全体の1/2", "basis": {"text": "相続人が配偶者のみの場合、遺留分は「法定相続分（全部）×1/2」つまり財産全体の1/2です（民法1042条1項1号）。直系尊属のみが相続人の場合の遺留分は財産全体の1/3です（民法1042条1項2号）。", "example": "Aが死亡し相続人が配偶者Bのみ。Aが「全財産をCに遺贈する」という遺言を残していた。BはAの財産の1/2を遺留分として確保できます（遺留分侵害額請求）。"}, "reason": {"text": "遺留分の計算：①相続人が直系尊属のみ→財産全体の1/3②その他（配偶者・子等）→財産全体の1/2。兄弟姉妹には遺留分がありません（民法1042条）。遺留分侵害額請求権は相続開始および侵害を知った時から1年、相続開始から10年で消滅します（民法1048条）。"}, "svg": "<svg viewBox=\"0 0 620 275\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">遺留分の計算</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">相続人の組み合わせ</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">遺留分の合計</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"275\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">各人の遺留分</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"275\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者のみ</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">財産の1/2</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">子のみ</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">財産の1/2</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">子で均等分割（合計1/2）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者＋子</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">財産の1/2</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者1/4・子1/4（2人なら1/8ずつ）</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系尊属のみ</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">財産の1/3</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">—</text><rect x=\"10\" y=\"225\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">兄弟姉妹</text><text x=\"299\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">なし</text><text x=\"492\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分なし</text></svg>", "choices": [{"label": "法定相続分の2分の1（財産全体の2分の1）", "reason": "正解です。相続人が配偶者のみの場合、遺留分は法定相続分（全部）の1/2、つまり財産全体の1/2です（民法1042条1項1号）。", "caution": ""}, {"label": "法定相続分の3分の1", "reason": "法定相続分の1/3（財産全体の1/3）は直系尊属のみが相続人の場合の遺留分です。配偶者のみの場合は1/2が正解です。", "caution": ""}, {"label": "法定相続分の4分の1", "reason": "1/4は誤りです。配偶者のみの場合は法定相続分（全部）の1/2が遺留分です。", "caution": ""}, {"label": "配偶者には遺留分がない", "reason": "配偶者には遺留分があります。遺留分がないのは兄弟姉妹のみです（民法1042条）。", "caution": ""}], "summary": {"head": ["相続人", "遺留分"], "rows": [["配偶者のみ", "財産全体の1/2"], ["子のみ", "財産全体の1/2"], ["直系尊属のみ", "財産全体の1/3"], ["兄弟姉妹", "なし（遺留分なし）"]]}}},
  {id:10044,unit:'r_fuhoko',level:1,field:'rights',text:"使用者責任（民法715条）が成立する要件として誤っているものはどれか。",opts:["被用者が事業の執行について第三者に損害を加えたこと", "使用者と被用者の使用関係", "損害の発生", "使用者が被用者の選任・監督について過失があること"],ans:3,exp:`使用者責任では使用者は「相当の注意をしたこと」「注意をしても損害が生じたこと」を証明すれば免責されます。つまり過失は推定され、使用者側が無過失を立証する必要があります（民法715条1項ただし書き）。`,"kaisetsu":{"topic": "使用者責任：過失は推定・免責の立証は使用者側・被用者への求償は信義則上制限", "basis": {"text": "使用者責任（民法715条）では、使用者の過失（選任・監督の不注意）が「推定」されます。使用者が「相当の注意をした」または「注意をしても損害が生じた」ことを立証すれば免責されます（民法715条1項ただし書）。", "example": "A社の従業員Bが業務中に車で事故を起こしCに損害を与えた場合。A社は被害者Cに損害賠償責任を負います。A社はBへの選任・監督について相当の注意をしたことを立証できれば免責されますが、実際には認められにくいです。"}, "reason": {"text": "使用者が被害者に賠償した後、被用者（Bこの場合）に求償（立替分の返還請求）できますが、信義則上求償額が制限されます（全額求償は認められにくい）。法人の従業員の不法行為でも、「職務を行うにつき」という要件が必要です（民法715条1項）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">使用者責任のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">成立要件</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">被用者が職務遂行上の不法行為を行った</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">免責</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">使用者が選任・監督に相当の注意をしたことを証明すれば可（実際は困難）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">使用者の求償</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">被用者への求償は信義則上制限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">両罰的処理</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">使用者・被用者の双方が責任を負う場合がある</text></svg>", "choices": [{"label": "使用者は故意があれば責任を負う", "reason": "使用者責任は使用者自身の故意や過失ではなく、被用者の不法行為を理由とする責任です（代位責任）。使用者の故意の有無は直接の要件ではありません。", "caution": ""}, {"label": "使用者が相当の注意をすれば免責される", "reason": "正解の一つです（本問の正解は「過失が常に必要」の選択肢3）。使用者は相当の注意を立証すれば免責されます（ただし実際には認められにくい）。", "caution": ""}, {"label": "使用者が被用者の選任・監督について過失があることが常に必要", "reason": "正解（誤りとして）。使用者の過失は「推定」されます。使用者側が無過失を立証して免責されます（過失が常に必要というのは誤り）。", "caution": ""}, {"label": "使用者が賠償した後、被用者に求償できる", "reason": "使用者は被用者への求償ができます（民法715条3項）。ただし信義則上求償額が制限されます。", "caution": ""}], "summary": {"head": ["項目", "内容"], "rows": [["使用者の免責", "相当の注意を立証すれば可（実際は困難）"], ["求償", "被用者への求償可（信義則上制限あり）"]]}}},
  {id:10045,unit:'r_shakuchi',level:1,field:'rights',text:"借地権の対抗要件として正しいものはどれか。",opts:["借地権の登記のみ", "借地上の建物の登記（自己名義）でも可", "地主の承認書の備え付け", "建物の建築確認済証の保管"],ans:1,exp:`借地権は借地権自体の登記のほか、借地上の建物について借地権者名義の登記（表示登記でも可）を備えることで第三者に対抗できます（借地借家法10条）。`,"kaisetsu":{"topic": "借地権の対抗要件：土地の登記または借地上の建物の登記（自己名義）でも可", "basis": {"text": "借地権の対抗要件は①借地権の登記（土地について）または②借地上の建物について借地権者名義の登記を備えることで第三者に対抗できます（借地借家法10条1項）。建物の表示登記でも有効です（保存登記不要）。", "example": "AがBの土地を借りてC建物（自己名義の表示登記あり）を建てた。Bが土地をCに売却しても、AはCに借地権を対抗できます（建物の表示登記があるため）。"}, "reason": {"text": "「自己名義」が要件です（他人名義では不可）。建物の登記は「表示登記（建物の物理的情報の登記）」でも足ります（所有権保存登記（権利に関する登記）でなくても可）。建物が滅失した後は掲示による対抗（一定期間）が認められます（借地借家法10条2項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">借地権の対抗要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対抗要件</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">要件</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">注意点</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借地権の登記（土地）</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">土地登記簿に借地権が記録されていること</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">実務上は少ない</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借地上の建物の登記</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借地権者名義（自己名義）で登記</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表示登記で足りる</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物滅失後</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">掲示による対抗（一定期間）</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借地借家法10条2項</text></svg>", "choices": [{"label": "借地上の建物の登記（自己名義）でも可", "reason": "正解です。借地上の建物について借地権者名義の登記を備えることで、借地権を第三者に対抗できます（借地借家法10条1項）。表示登記でも有効です。", "caution": ""}, {"label": "借地権の登記が唯一の対抗要件である", "reason": "借地権の登記だけでなく、借地上の建物の自己名義登記でも対抗できます。", "caution": ""}, {"label": "口頭での借地契約でも常に対抗できる", "reason": "口頭での借地契約では登記等の対抗要件を備えられないため、第三者に対抗できない可能性があります。", "caution": ""}, {"label": "他人名義の建物登記でも対抗できる", "reason": "「自己名義」が要件です。他人名義の建物登記では借地権を対抗できません。", "caution": ""}], "summary": {"head": ["対抗要件", "内容"], "rows": [["土地の借地権登記", "土地登記簿への記録"], ["借地上の建物の自己名義登記", "表示登記でも足りる"], ["建物滅失後", "掲示による対抗（一定期間）"]]}}},
  {id:10046,unit:'r_kukku',level:1,field:'rights',text:"マンションの管理規約の設定に必要な決議として正しいものはどれか。",opts:["区分所有者及び議決権の各過半数", "区分所有者及び議決権の各3分の2以上", "区分所有者及び議決権の各4分の3以上", "全区分所有者の同意"],ans:2,exp:`管理規約の設定・変更・廃止には区分所有者及び議決権の各4分の3以上の多数による集会の決議が必要です（区分所有法31条1項）。`,"kaisetsu":{"topic": "管理規約の設定・変更：区分所有者・議決権の各3/4以上の特別決議", "basis": {"text": "マンション（区分所有建物）の管理規約の設定・変更・廃止には、区分所有者および議決権の各4分の3以上の多数による集会の決議が必要です（区分所有法31条1項）。", "example": "100戸のマンションで管理規約を変更したい場合、区分所有者75人以上かつ議決権75以上の賛成が必要です（少数の反対者がいても過半数を超えれば変更不可という制度）。"}, "reason": {"text": "区分所有法の決議要件：①普通決議→区分所有者・議決権の各過半数（通常の管理行為）②特別決議→3/4以上（重大変更・規約変更等）③建替え決議→4/5以上。4/5以上は最も重い決議要件で建替えに必要です（区分所有法62条1項）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">区分所有法の決議要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">事項</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">決議要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通常管理（普通決議）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">区分所有者・議決権の各過半数</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">共用部分の重大変更</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">区分所有者・議決権の各3/4以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">規約の設定・変更・廃止</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">区分所有者・議決権の各3/4以上</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建替え決議</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">区分所有者・議決権の各4/5以上</text></svg>", "choices": [{"label": "区分所有者及び議決権の各過半数", "reason": "過半数は普通決議（通常管理）の要件です。規約の設定・変更・廃止は特別決議（3/4以上）が必要です。", "caution": ""}, {"label": "区分所有者及び議決権の各4分の3以上", "reason": "正解です。管理規約の設定・変更・廃止には区分所有者および議決権の各3/4以上の特別決議が必要です（区分所有法31条1項）。", "caution": ""}, {"label": "区分所有者及び議決権の各5分の4以上", "reason": "4/5以上は「建替え決議」の要件です（区分所有法62条1項）。規約変更は3/4以上が正解です。", "caution": ""}, {"label": "全区分所有者の同意", "reason": "全員同意は区分所有法上の要件として定められていません（全員合意があれば当然に可ですが）。", "caution": ""}], "summary": {"head": ["事項", "要件"], "rows": [["普通決議", "過半数"], ["規約変更・重大変更", "3/4以上"], ["建替え", "4/5以上"]]}}},
  {id:10047,unit:'r_touki',level:1,field:'rights',text:"不動産登記の申請方法として正しいものはどれか。",opts:["必ず登記所の窓口に出頭して申請しなければならない", "書面申請またはオンライン申請ができる", "代理人による申請はできない", "申請は売主のみが行う"],ans:1,exp:`不動産登記の申請は、登記所の窓口への書面申請のほかオンライン申請（電子申請）も認められています（不動産登記法18条）。代理人による申請も可能です。`,"kaisetsu":{"topic": "不動産登記の申請方法：書面申請またはオンライン申請が可能", "basis": {"text": "不動産登記の申請は、登記所の窓口への書面申請のほか、オンライン申請（電子申請）も認められています（不動産登記法18条）。代理人（司法書士等）による申請も可能です。", "example": "A司法書士がB（売主）とC（買主）から依頼を受け、所有権移転登記を申請する場合、法務局の窓口への書面申請またはオンライン申請（電子申請）が可能です。"}, "reason": {"text": "権利に関する登記は原則として「登記権利者（利益を受ける側）と登記義務者（不利益を受ける側）の共同申請」が必要です（不動産登記法60条）。例外として単独申請が認められる場合もあります（相続・確定判決等）。法務局が職権で登記することは原則ありません（表題登記は所有者に申請義務あり）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産登記申請の方法</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">申請方法</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面申請</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記所（法務局）の窓口に申請書を提出</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">オンライン申請</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">電子申請（不動産登記法18条）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理申請</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">司法書士等に委任して申請可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">共同申請（原則）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記権利者と登記義務者が共同で申請</text></svg>", "choices": [{"label": "書面申請またはオンライン申請ができる", "reason": "正解です。不動産登記は書面申請またはオンライン申請が認められています（不動産登記法18条）。", "caution": ""}, {"label": "書面申請のみが認められる", "reason": "オンライン申請（電子申請）も認められています（不動産登記法18条）。「書面申請のみ」は誤りです。", "caution": ""}, {"label": "法務局が職権で全て行う", "reason": "法務局が職権で登記することは原則ありません。当事者の申請が必要です（一部例外あり）。", "caution": ""}, {"label": "申請は本人のみが行える", "reason": "代理人（司法書士等）による申請も認められています（不動産登記法17条等）。", "caution": ""}], "summary": {"head": ["申請方法", "認められるか"], "rows": [["書面申請", "可"], ["オンライン申請", "可（不動産登記法18条）"], ["代理申請", "可（司法書士等）"]]}}},
  {id:10048,unit:'r_sorin',level:1,field:'rights',text:"境界線上に設けた塀の費用負担として民法が定める原則はどれか。",opts:["すべて先に建てた者の負担", "隣地所有者との共同費用負担", "すべて新しく建てた者の負担", "話し合いで自由に決める"],ans:1,exp:`境界線上に設けた境界標・囲障等（塀・垣根等）は、相隣者が共同の費用で設置・保存するのが原則です（民法225条）。`,"kaisetsu":{"topic": "境界線上の塀の費用：相隣者が共同負担が原則", "basis": {"text": "境界線上に塀・囲障等を設ける場合、相隣者が共同の費用で設置・保存するのが原則です（民法225条）。一方が単独で費用を負担する必要はなく、原則として折半（半分ずつ）です。", "example": "隣接するAとBの土地の境界に塀を設置する場合、費用はAとBが折半（50%ずつ）するのが民法の原則です（ただし特約で変更可）。"}, "reason": {"text": "境界線（筆界）の確認：土地の境界については当事者が合意して確定します。境界確定の訴えも可能です。境界標（コンクリート杭・金属標等）の維持費用も相隣者の共同負担が原則です（民法224条）。境界から50cm以上建物を離す規定は異なる慣習・条例で変更可（民法234条・236条）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相隣関係のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">事項</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">原則</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">変更可否</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">境界線上の塀の費用</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相隣者の共同負担（折半）</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">特約で変更可</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">境界標の維持費用</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相隣者の共同負担</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">特約で変更可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物の境界からの距離</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">50cm以上</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">慣習・条例で変更可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">竹木の根の越境</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自ら切除可</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">—</text></svg>", "choices": [{"label": "隣地所有者との共同費用負担", "reason": "正解です。境界線上の塀等の費用は相隣者（隣地所有者）との共同負担（折半）が原則です（民法225条）。", "caution": ""}, {"label": "塀を設置したい方が全額負担する", "reason": "一方的な全額負担は民法の原則ではありません。相隣者の共同負担が原則です。", "caution": ""}, {"label": "境界に近い方の土地所有者が全額負担する", "reason": "距離は関係ありません。相隣者の共同負担が原則です。", "caution": ""}, {"label": "費用負担の規定はない", "reason": "民法225条で共同負担の規定があります。「規定なし」は誤りです。", "caution": ""}], "summary": {"head": ["事項", "原則"], "rows": [["境界線上の塀の費用", "相隣者の共同負担（折半）"], ["建物の境界からの距離", "50cm以上（慣習・条例で変更可）"], ["竹木の根の越境", "自ら切除可"]]}}},
  {id:10049,unit:'l_menkyo',level:1,field:'law',text:"宅建業者が廃業した場合の免許の失効について正しいものはどれか。",opts:["廃業と同時に免許は失効し届出は不要", "廃業後30日以内に免許権者に届け出なければならない", "廃業しても免許有効期間内は有効", "免許権者の取消処分が必要"],ans:1,exp:`宅建業者が廃業した場合、廃業の日から30日以内に免許権者に届け出なければなりません（宅建業法11条1項5号）。届出があった日に免許は失効します。`,"kaisetsu":{"topic": "宅建業者の廃業：廃業後30日以内に免許権者に届出", "basis": {"text": "宅建業者が廃業した場合、廃業の日から30日以内に免許権者（都道府県知事または国土交通大臣）に届け出なければなりません（宅建業法11条1項5号）。届出があった日から免許は失効します。", "example": "知事免許を持つA不動産が廃業した場合、廃業後30日以内に都道府県知事に届け出る義務があります。届け出をしなかった場合は罰則の対象となります。"}, "reason": {"text": "廃業の届出義務者：法人の場合は役員（代表者等）。個人の場合は本人（または相続人）。死亡の場合は相続人が「知った日から30日以内」に届け出が必要（宅建業法11条1項1号）。合併による消滅の場合は消滅した会社の代表者等が30日以内に届け出（同条1項2号）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">免許の失効に関する届出</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">事由</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">届出義務者</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">期限</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">廃業</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法人：役員等・個人：本人</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">廃業後30日以内</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">死亡（個人業者）</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続人</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">死亡を知った日から30日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合併消滅</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">消滅会社の代表者等</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">消滅後30日以内</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">破産</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">破産管財人</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開始決定後30日以内</text></svg>", "choices": [{"label": "廃業後30日以内に免許権者に届け出なければならない", "reason": "正解です。廃業後30日以内に免許権者への届出が義務です（宅建業法11条1項5号）。", "caution": ""}, {"label": "廃業後直ちに免許は失効する", "reason": "廃業届の提出があった日から免許が失効します（宅建業法11条2項）。届出前に自動的に失効するわけではありません。", "caution": ""}, {"label": "廃業後1か月以内に届け出ればよい", "reason": "「1か月以内」ではなく「30日以内」が正しい期限です（月によって日数が異なるため）。", "caution": ""}, {"label": "廃業した場合の届出義務はない", "reason": "廃業後30日以内の届出は義務です（宅建業法11条1項5号）。届出をしないと罰則の対象となります。", "caution": ""}], "summary": {"head": ["事由", "期限"], "rows": [["廃業", "廃業後30日以内"], ["死亡", "知った日から30日以内"], ["合併消滅", "消滅後30日以内"]]}}},
  {id:10050,unit:'l_takkenshi',level:1,field:'law',text:"宅建士の登録の移転について正しいものはどれか。",opts:["勤務先が変われば自動的に登録が移転する", "登録の移転は任意であり義務ではない", "登録の移転は任意だが、勤務先の都道府県に移転することが望ましい", "登録の移転は免許権者の許可が必要"],ans:2,exp:`宅建士の登録の移転は義務ではなく任意です（宅建業法19条の2）。勤務先の所在する都道府県知事に移転することができますが、しなくても違法ではありません。`,"kaisetsu":{"topic": "宅建士の登録移転：任意・勤務先の都道府県知事への移転が可能", "basis": {"text": "宅建士の登録の移転は任意（義務ではありません）（宅建業法19条の2）。勤務先が他の都道府県になった場合などに、現在登録している都道府県知事から勤務先の都道府県知事へ登録を移転することができます。", "example": "東京都知事に登録しているAが大阪府の宅建業者に転職した場合、Aは任意で大阪府知事に登録を移転できます（しなくても違法ではない）。"}, "reason": {"text": "登録移転の手続き：現在の登録知事（例：東京都知事）を経由して移転先の知事（例：大阪府知事）に申請します（直接申請は不可）。登録移転中は宅建士証の交付を受けられません（新しい宅建士証が交付されるまで）。住所・氏名等の変更は変更登録が必要で「遅滞なく」届出が義務です（宅建業法20条）。"}, "svg": "<svg viewBox=\"0 0 620 275\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建士の登録移転のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"275\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">移転の任意性</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">任意（義務ではない）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">移転の手続き</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">現在の知事を経由して移転先の知事に申請</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直接申請</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可（現在の知事経由が必要）</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">移転中の宅建士証</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">新しい宅建士証が交付されるまで業務制限あり</text><rect x=\"10\" y=\"225\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住所・氏名等の変更</text><text x=\"445\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">変更登録が必要（遅滞なく）</text></svg>", "choices": [{"label": "登録の移転は義務であり、転居の際は必ず行わなければならない", "reason": "登録の移転は任意です。転居しても移転しなくても違法ではありません。", "caution": ""}, {"label": "登録の移転は任意だが、勤務先の都道府県知事への移転が可能", "reason": "正解です。登録の移転は任意で、勤務先の都道府県知事への移転が可能です（宅建業法19条の2）。", "caution": ""}, {"label": "登録の移転は転勤の際にのみ認められる", "reason": "転勤（勤務先変更）に限らず、任意で移転申請することが可能です。", "caution": ""}, {"label": "登録の移転には移転先の知事への直接申請が必要", "reason": "現在登録している知事を経由して移転先の知事に申請します。移転先への直接申請は不可です。", "caution": ""}], "summary": {"head": ["項目", "内容"], "rows": [["移転の任意性", "任意（義務ではない）"], ["手続き", "現在の知事経由"], ["住所・氏名等の変更", "変更登録が必要（遅滞なく）"]]}}},
  {id:10051,unit:'l_hosho',level:1,field:'law',text:"営業保証金の供託先として正しいものはどれか。",opts:["免許権者（知事または国交大臣）", "主たる事務所の最寄りの供託所", "法務局本局のみ", "財務省"],ans:1,exp:`営業保証金は主たる事務所の最寄りの供託所（法務局等）に供託しなければなりません（宅建業法25条1項）。`,"kaisetsu":{"topic": "営業保証金・保証協会：主1,000万・従500万/営業保証金vs分担金60万・30万", "basis": {"text": "営業保証金は主1,000万・従500万（宅建業法25条）。保証協会の分担金は主60万・従30万（同法64条の9）。還付対象は業者以外の取引した者。加入は任意。不足補充は通知後2週間以内。", "example": ""}, "reason": {"text": "営業保証金は主たる事務所の最寄りの供託所（法務局等）に供託します（宅建業法25条1項）。免許権者や財務省に供託するのではありません。供託後に免許権者への届出が必要です（同条4項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">営業保証金と弁済業務保証金</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">営業保証金</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">弁済業務保証金（分担金）</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">主たる事務所</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000万円</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">60万円</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従たる事務所/所</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">500万円</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">還付対象</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者以外</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者以外</text></svg>", "choices": [{"label": "免許権者（知事または国交大臣）", "reason": "営業保証金は免許権者ではなく、主たる事務所の最寄りの供託所に供託します（宅建業法25条1項）。", "caution": "営業保証金の供託先＝主たる事務所の最寄りの供託所（法務局等）。"}, {"label": "法務局本局のみ", "reason": "最寄りの供託所（法務局・地方法務局・支局等）であればよく、本局のみとは限りません（宅建業法25条1項）。", "caution": ""}, {"label": "財務省", "reason": "財務省は供託所ではありません（宅建業法25条1項）。", "caution": ""}], "summary": {"head": ["営業保証金の供託", "内容"], "rows": [["供託先", "主たる事務所の最寄りの供託所（法務局等）"], ["供託額（主たる事務所）", "1000万円"], ["供託額（従たる事務所）", "1か所あたり500万円"], ["届出", "供託後に免許権者への届出が必要（宅建業法25条4項）"]]}}},
  {id:10052,unit:'l_baikai',level:1,field:'law',text:"一般媒介契約と専任媒介契約の最大の違いはどれか。",opts:["報酬の上限額が異なる", "一般媒介は複数の業者に依頼できるが、専任媒介は1社のみ", "一般媒介の有効期間は6か月", "専任媒介はレインズ登録が不要"],ans:1,exp:`一般媒介は依頼者が複数の宅建業者に同時に依頼できますが、専任媒介・専属専任媒介は1社のみに限定されます（宅建業法34条の2）。`,"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任の有効期間は最長3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。レインズ登録は専任7日以内・専属専任5日以内。業務報告は専任2週間に1回・専属専任1週間に1回。", "example": ""}, "reason": {"text": "一般媒介契約は複数の宅建業者に同時に依頼できますが、専任媒介・専属専任媒介は1社のみに依頼します（宅建業法34条の2）。報酬上限は媒介契約の種類によらず同じです。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">自己発見</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">レインズ</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専任</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専属専任</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text></svg>", "choices": [{"label": "報酬の上限額が異なる", "reason": "媒介契約の種類（一般・専任・専属専任）によって報酬の上限額は変わりません（宅建業法46条）。", "caution": "報酬上限は媒介契約の種類に関わらず同じ。"}, {"label": "一般媒介の有効期間は6か月", "reason": "一般媒介契約の有効期間には法定の上限規定はありません（宅建業法34条の2）。専任・専属専任は3か月が上限です（同条3項）。", "caution": "一般媒介：有効期間の法定上限なし。専任・専属専任：3か月が上限。"}, {"label": "専任媒介はレインズ登録が不要", "reason": "専任媒介契約ではレインズへの登録義務があります（宅建業法34条の2第5項：7日以内）。「不要」は誤りです。", "caution": ""}], "summary": {"head": ["媒介契約の比較", "一般媒介", "専任媒介", "専属専任媒介"], "rows": [["複数業者への依頼", "可", "不可", "不可"], ["自己発見取引", "可", "可", "不可"], ["有効期間上限", "なし", "3か月", "3か月"], ["レインズ登録", "義務なし", "7日以内", "5日以内"], ["業務報告", "義務なし", "2週間に1回", "1週間に1回"]]}}},
  {id:10053,unit:'l_jusetsu',level:1,field:'law',text:"重要事項説明のIT重説（テレビ会議等）について正しいものはどれか。",opts:["IT重説はどの取引でも自由に使える", "相手方が承諾し、映像・音声の双方向通信が確保された場合に利用できる", "IT重説では宅建士証の提示は省略できる", "IT重説で説明した場合は書面交付が不要"],ans:1,exp:`IT重説は相手方の承諾があり、映像・音声を双方向でリアルタイム通信できる環境が整っている場合に利用できます。宅建士証の画面越しの提示と書面（電磁的方法可）の交付は引き続き必要です。`,"kaisetsu":{"topic": "重要事項説明：宅建士が説明・買主への交付・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主（貸主）は不要。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能。", "example": ""}, "reason": {"text": "IT重説（テレビ会議等による重要事項説明）は相手方が承諾し、映像・音声の双方向通信が確保されている場合に利用できます（宅建業法35条・国土交通省ガイドライン）。宅建士証の提示は画面越しに行い、書面交付義務も残ります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士のみ（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "IT重説はどの取引でも自由に使える", "reason": "相手方の承諾と一定の通信環境が必要です（国土交通省ガイドライン）。「自由に使える」は誤りです。", "caution": "IT重説：相手方承諾＋双方向通信確保が要件。"}, {"label": "IT重説では宅建士証の提示は省略できる", "reason": "IT重説でも宅建士証の提示義務があります（宅建業法35条4項）。画面上での確認等で対応します。", "caution": ""}, {"label": "IT重説で説明した場合は書面交付が不要", "reason": "IT重説でも35条書面の交付義務は残ります（宅建業法35条1項）。電子交付の場合は相手方の承諾が必要です。", "caution": ""}], "summary": {"head": ["IT重説の要件", "内容"], "rows": [["相手方の承諾", "必要"], ["通信環境", "映像・音声の双方向通信が確保されていること"], ["宅建士証の提示", "画面越しに確認できること"], ["書面交付", "必要（電子交付の場合は別途承諾要）"]]}}},
  {id:10054,unit:'l_37jo',level:1,field:'law',text:"37条書面に記載が不要なものはどれか。",opts:["物件の特定に必要な事項（所在・地番等）", "代金の額", "近隣施設（学校・病院等）の情報", "引渡しの時期"],ans:2,exp:`37条書面の必要的記載事項は物件特定・代金・引渡時期・移転登記申請時期等です（宅建業法37条）。近隣施設の情報は37条書面の記載事項ではありません（重要事項説明でも必須ではない）。`,"kaisetsu":{"topic": "37条書面：全取引で交付・記名（押印不要）・移転登記申請時期は必要的記載事項", "basis": {"text": "37条書面は全取引で契約の双方当事者に交付が義務（宅建業法37条）。引渡し時期・移転登記申請時期は必要的記載事項。2021年改正で押印は不要、記名のみで足ります。", "example": ""}, "reason": {"text": "37条書面（契約書面）の記載事項は宅建業法37条1項に列挙されています。近隣施設（学校・病院等）の情報は重要事項説明書（35条書面）でも37条書面でも必須記載事項ではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付義務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全取引・双方当事者</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡時期・移転登記申請時期等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要）</text></svg>", "choices": [{"label": "物件の特定に必要な事項（所在・地番等）", "reason": "物件の特定に必要な事項は37条書面の必要的記載事項です（宅建業法37条1項1号）。", "caution": ""}, {"label": "代金の額", "reason": "代金の額は37条書面の必要的記載事項です（宅建業法37条1項2号）。", "caution": ""}, {"label": "引渡しの時期", "reason": "引渡しの時期は37条書面の必要的記載事項です（宅建業法37条1項4号）。", "caution": ""}], "summary": {"head": ["37条書面の主な記載事項", "必要的/任意的"], "rows": [["当事者の氏名・住所", "必要的"], ["物件の特定", "必要的"], ["代金の額・支払時期・方法", "必要的"], ["引渡し時期", "必要的"], ["移転登記申請時期", "必要的"], ["契約解除の定め", "任意的（定めがある場合）"], ["危険負担・瑕疵担保の定め", "任意的"]]}}},
  {id:10055,unit:'l_cooling',level:1,field:'law',text:"クーリングオフができない場所として正しいものはどれか。",opts:["買主の自宅", "買主の勤務先（買主が申し出た場合）", "買主が指定した喫茶店", "宅建業者の事務所"],ans:3,exp:`宅建業者の事務所で申し込んだ場合はクーリングオフができません（宅建業法37条の2）。買主の自宅・勤務先（買主から申し出た場合）・買主が指定した場所では申し込みがあればクーリングオフが可能です。`,"kaisetsu":{"topic": "クーリングオフ：告知日から8日以内・書面で・事務所では不可・全額返還", "basis": {"text": "クーリングオフは告知を受けた日から8日以内に書面で行います（宅建業法37条の2）。事務所・モデルルーム等での申込みはクーリングオフ不可。解除後業者は全額返還（費用控除不可）。", "example": ""}, "reason": {"text": "クーリングオフができない「事務所等」の最も典型的な場所は宅建業者の事務所です（宅建業法37条の2第1項1号・施行規則16条の5）。事務所での申込み・契約は慎重な判断が期待できるためクーリングオフの対象外です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">クーリングオフのポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">告知日から8日以内</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">方法</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面（発信主義）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所での申込み</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">クーリングオフ不可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除後</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全額返還</text></svg>", "choices": [{"label": "買主の自宅", "reason": "買主が自ら申し出た場合を除き、自宅での申込みはクーリングオフができます（宅建業法37条の2第1項1号・施行規則16条の5）。", "caution": "自宅・勤務先：買主が自ら申し出た場合はクーリングオフ不可。業者が指定した場合は可。"}, {"label": "買主の勤務先（買主が申し出た場合）", "reason": "買主が自ら申し出た勤務先での申込みはクーリングオフができません（施行規則16条の5第3号）。設問では「買主が申し出た場合」なのでクーリングオフ不可の場所です。", "caution": ""}, {"label": "買主が指定した喫茶店", "reason": "買主が指定した喫茶店（飲食店等の公共の場所）での申込みはクーリングオフができます（施行規則16条の5は飲食店等を「事務所等」に含めない）。", "caution": ""}], "summary": {"head": ["クーリングオフができない「事務所等」", "根拠"], "rows": [["宅建業者の事務所", "施行規則16条の5第1号"], ["専任の宅建士設置の継続的業務施設（モデルルーム等）", "施行規則16条の5第2号"], ["買主が自ら申し出た自宅・勤務先", "施行規則16条の5第3号"], ["売主業者の依頼を受けた他の宅建業者の事務所等", "施行規則16条の5第4号"]]}}},
  {id:10056,unit:'l_hoshu',level:1,field:'law',text:"土地付建物の売買（代金3000万円）を媒介した場合、一方の依頼者から受け取れる報酬の上限はいくらか（消費税別）。",opts:["90万円", "96万円", "105万円", "150万円"],ans:1,exp:`代金400万円超の売買報酬は「代金×3%+6万円」が上限です。3000万円×3%+6万円=96万円（税別）が一方から受け取れる上限です（宅建業法46条・告示）。`,"kaisetsu":{"topic": "報酬：売買は代金×3%+6万（400万超）・賃貸は借賃1か月・上限超過は不可", "basis": {"text": "売買（400万超）の一方からの上限は代金×3%+6万。双方合計は一方上限×2。賃貸（居住用・非居住用とも）は借賃1か月分。低廉な空家等（800万円以下）は、媒介報酬について原則の報酬額を超えて30万円（税別）まで受領できる場合があります（依頼者への説明・合意が必要）。", "example": ""}, "reason": {"text": "売買代金3000万円（400万円超）の媒介報酬上限は速算式「代金×3%＋6万円」で計算します（国土交通省告示）。3000万円×3%＋6万円＝90万円＋6万円＝96万円（税別）が一方の依頼者からの上限です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対象</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（400万超）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万（一方）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（200万以下）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸（双方合計）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借賃1か月分</text></svg>", "choices": [{"label": "90万円", "reason": "3000万円×3%＝90万円ですが、速算式は「×3%＋6万円」です（告示）。6万円を加算した96万円が上限です。", "caution": "速算式：代金×3%＋6万円（400万円超の場合）。"}, {"label": "105万円", "reason": "計算が異なります。3000万円×3%＋6万円＝96万円が正しい計算結果です（告示）。", "caution": ""}, {"label": "150万円", "reason": "150万円は3000万円×5%です。400万円超の速算式は3%＋6万円です（告示）。", "caution": ""}], "summary": {"head": ["報酬計算の速算式（400万円超・税別）", "計算"], "rows": [["計算式", "代金×3%＋6万円"], ["3000万円の例", "3000万円×3%＋6万円＝96万円"], ["一方から受領可能", "上記金額（消費税別）"], ["双方から合計", "上記×2（最大）"]]}}},
  {id:10057,unit:'l_kantoku',level:1,field:'law',text:"宅建業法上の指示処分について正しいものはどれか。",opts:["指示処分は免許取消処分の前段階として必ず行われる", "指示処分は必要に応じて業務停止処分・免許取消処分と独立して行うことができる", "指示処分を受けると即時に業務が停止される", "指示処分は国交大臣のみが行える"],ans:1,exp:`指示処分は業務停止処分・免許取消処分と独立して行うことができます（宅建業法65条）。指示処分を受けても業務は継続できます。なお都道府県知事も管轄内の業者に指示処分を行えます。`,"kaisetsu":{"topic": "監督処分：業務停止最長1年・大臣は全業者に指示可・指示違反→業務停止", "basis": {"text": "業務停止の最長期間は1年（宅建業法65条2項）。大臣は全業者（知事免許含む）に指示処分を行う権限があります。指示処分違反→業務停止、業務停止違反→免許取消という段階があります。", "example": ""}, "reason": {"text": "指示処分は業務停止処分・免許取消処分とは独立して行うことができます（宅建業法65条1項）。軽微な違反に対して指示処分のみを行うことも、指示処分と業務停止処分を同時に行うことも可能です。免許取消の前段階として必ず指示処分が要求されるわけではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">監督処分のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">処分</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">最長1年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣の権限</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全業者に指示可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">指示処分違反</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止の対象</text></svg>", "choices": [{"label": "指示処分は免許取消処分の前段階として必ず行われる", "reason": "指示処分は免許取消処分の前段階として必須ではありません（宅建業法65条1項）。各処分は独立して行うことができます。", "caution": "指示処分は独立した処分。免許取消の前段階として必須ではない。"}, {"label": "指示処分を受けると即時に業務が停止される", "reason": "指示処分は業務の適正運営のための措置を命じる処分であり、業務停止ではありません（宅建業法65条1項）。業務が即時停止されるのは業務停止処分です（同条2項）。", "caution": ""}, {"label": "指示処分は国交大臣のみが行える", "reason": "指示処分は免許を与えた国土交通大臣または都道府県知事が行えます（宅建業法65条1項）。大臣のみではありません。", "caution": ""}], "summary": {"head": ["宅建業者への監督処分の種類（宅建業法65条〜66条）", "内容"], "rows": [["指示処分", "業務適正化のための措置を命じる（宅建業法65条1項）"], ["業務停止処分", "1年以内の業務停止（宅建業法65条2項）"], ["免許取消処分", "任意的・必要的の2種類（宅建業法66条）"], ["独立性", "各処分は独立して行うことができる"]]}}},
  {id:10058,unit:'l_sonota',level:1,field:'law',text:"住宅瑕疵担保責任保険に関して正しいものはどれか。",opts:["保険に加入した場合、保険期間中に瑕疵が発見されれば保険金が支払われる", "保険は宅建業者が加入するが、保険金は宅建業者のみが受け取れる", "保険期間は3年", "保険は任意加入"],ans:0,exp:`住宅瑕疵担保責任保険に加入した場合、保険期間内（10年）に瑕疵が発見されれば保険金が支払われます（住宅瑕疵担保履行法）。保険金は修補費用等に充てられ、一定条件下で買主も直接請求できます。`,"kaisetsu":{"topic": "宅建業者のその他の業務：従業者証明書・帳簿・業務処理原則", "basis": {"text": "全従業者に従業者証明書の交付が必要で業務中は常時携帯（宅建業法48条）。帳簿は事務所ごとに5年保存（自ら売主の新築住宅は10年）（同法49条）。宅建業者は信義誠実の原則に従って業務を行う必要があります（同法31条）。", "example": ""}, "reason": {"text": "住宅瑕疵担保責任保険（住宅瑕疵担保履行法）は宅建業者が自ら売主として新築住宅を販売する場合に加入義務があります。保険期間は10年で、保険期間中に瑕疵が発見されれば保険金が支払われます。保険金は宅建業者と買主の両方が受け取れる場合があります（宅建業者が倒産等した場合は買主が直接請求できます）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業者のその他の義務</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従業者証明書</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全従業者に交付・業務中携帯</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">帳簿</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所ごと・5年保存（新築自ら売主は10年）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務処理原則</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">信義誠実の原則</text></svg>", "choices": [{"label": "保険は宅建業者が加入するが保険金は宅建業者のみが受け取れる", "reason": "宅建業者が倒産等した場合は買主が直接保険金を請求できます（住宅瑕疵担保履行法17条）。宅建業者のみではありません。", "caution": "保険金：宅建業者が倒産等の場合は買主が直接請求可（住宅瑕疵担保履行法17条）。"}, {"label": "保険期間は3年", "reason": "保険期間は10年です（住宅瑕疵担保履行法・品確法95条1項）。3年ではありません。", "caution": "住宅瑕疵担保責任保険の保険期間：10年。"}, {"label": "保険は任意加入", "reason": "宅建業者が自ら売主として新築住宅を販売する場合は保険加入または供託のいずれかが義務です（住宅瑕疵担保履行法11条）。「任意」は誤りです。", "caution": ""}], "summary": {"head": ["住宅瑕疵担保責任保険", "内容"], "rows": [["義務", "宅建業者自ら売主の新築住宅売買"], ["保険期間", "10年"], ["加入先", "国土交通大臣指定の住宅瑕疵担保責任保険法人"], ["保険金", "原則宅建業者が請求・倒産等の場合は買主が直接請求可"]]}}},
  {id:10059,unit:'k_toshi',level:1,field:'limit',text:"都市計画区域の指定権者として正しいものはどれか。",opts:["市町村長", "都道府県知事（一部は国交大臣）", "国土交通大臣のみ", "固定資産評価委員会"],ans:1,exp:`都市計画区域は都道府県が指定します（都市計画法5条）。ただし2以上の都府県にわたる区域は国土交通大臣が指定します。`,"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域の1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "都市計画区域の指定は原則として都道府県知事が行います（都市計画法5条1項）。ただし複数の都府県にまたがる都市計画区域の指定は国土交通大臣が行います（同条3項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "市町村長", "reason": "市町村長ではなく都道府県知事（一部は国交大臣）が指定します（都市計画法5条1項・3項）。", "caution": "都市計画区域の指定：都道府県知事（複数都府県にまたがる場合は大臣）。"}, {"label": "国土交通大臣のみ", "reason": "原則は都道府県知事です（都市計画法5条1項）。大臣が指定するのは複数の都府県にまたがる場合のみです（同条3項）。", "caution": ""}, {"label": "固定資産評価委員会", "reason": "固定資産評価委員会は都市計画区域の指定とは無関係です（都市計画法5条）。", "caution": ""}], "summary": {"head": ["都市計画区域の指定（都市計画法5条）", "指定権者"], "rows": [["1都道府県内のみ", "都道府県知事"], ["複数の都府県にまたがる", "国土交通大臣"], ["準都市計画区域", "都道府県知事（都市計画法5条の2）"]]}}},
  {id:10060,unit:'k_kenchiku',level:1,field:'limit',text:"建築確認が不要な場合として正しいものはどれか。",opts:["木造2階建て住宅の新築", "鉄筋コンクリート造の増築（面積10平方メートル以下・防火地域外）", "都市計画区域内での10平方メートル超の増築", "特殊建築物（病院等）への用途変更"],ans:1,exp:`防火地域・準防火地域以外での10平方メートル以内の増築は建築確認が不要です（建築基準法6条2項）。新築・特殊建築物への用途変更・一定規模以上の増改築は確認申請が必要です。`,"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・用途制限・道路斜線", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。防火地域の耐火建築物は隣地境界線に外壁を接して建築可（同法65条）。", "example": ""}, "reason": {"text": "建築確認が不要な場合として、防火地域・準防火地域外での10㎡以下の増築・改築・移転があります（建築基準法6条2項）。鉄筋コンクリート造でも防火地域外で10㎡以下なら確認不要です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">防火地域の耐火建築物</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">隣地境界線に接して建築可</text></svg>", "choices": [{"label": "木造2階建て住宅の新築", "reason": "都市計画区域内での新築は規模にかかわらず建築確認が必要です（建築基準法6条1項4号）。", "caution": "防火地域外・10㎡以下の増築：確認不要（建築基準法6条2項）。"}, {"label": "都市計画区域内での10平方メートル超の増築", "reason": "都市計画区域内での10㎡超の増築は建築確認が必要です（建築基準法6条1項・2項）。", "caution": ""}, {"label": "特殊建築物（病院等）への用途変更", "reason": "特殊建築物の用途に供する部分が200㎡超になる用途変更は建築確認が必要です（建築基準法87条1項）。", "caution": ""}], "summary": {"head": ["建築確認が不要な場合（建築基準法6条2項）", "内容"], "rows": [["防火地域外・10㎡以下の増築等", "確認不要"], ["維持修繕・模様替えでない塗装", "確認不要"], ["農業用温室等", "一定の例外"], ["確認が必要な例", "新築・10㎡超の増築・大規模修繕・用途変更等"]]}}},
  {id:10061,unit:'k_nochi',level:1,field:'limit',text:"農地を農地以外の用途に転用して売買する場合（農地法5条）の許可権者として正しいものはどれか。",opts:["農業委員会", "都道府県知事（一定の場合は農林水産大臣）", "市町村長", "国土交通大臣"],ans:1,exp:`農地の転用目的の権利移動（農地法5条）の許可権者は都道府県知事です（4ヘクタール超等は農林水産大臣）。農地のままの権利移動（3条）は農業委員会が許可権者です。`,"kaisetsu":{"topic": "農地法：3条は農業委員会・4・5条は都道府県知事・市街化区域は届出のみ", "basis": {"text": "農地法3条の許可権者は農業委員会。4・5条は都道府県知事等。市街化区域の農地転用（4・5条）は農業委員会への届出のみOK。相続は許可不要・3か月以内の農業委員会への届出が必要。", "example": ""}, "reason": {"text": "農地を農地以外に転用して売買する場合（農地法5条）の許可権者は都道府県知事です（農地法5条1項）。4ヘクタール超は農林水産大臣の許可が必要です（同条1項但書）。農業委員会は農地法3条の許可権者です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text></svg>", "choices": [{"label": "農業委員会", "reason": "農業委員会は農地法3条（農地のまま権利移動）の許可権者です（農地法3条1項）。4条・5条は都道府県知事です。", "caution": "農地法3条＝農業委員会。農地法4条・5条＝都道府県知事（4ha超は農林水産大臣）。"}, {"label": "市町村長", "reason": "農地法4条・5条の許可権者は市町村長ではありません（農地法4条1項）。", "caution": ""}, {"label": "国土交通大臣", "reason": "農地法4条・5条の許可権者は国交大臣ではありません（農地法4条1項）。", "caution": ""}], "summary": {"head": ["農地法の許可権者", "内容"], "rows": [["農地法3条（農地のまま権利移動）", "農業委員会"], ["農地法4条（自己転用）", "都道府県知事（4ha超は農林水産大臣）"], ["農地法5条（転用目的の権利移動）", "都道府県知事（4ha超は農林水産大臣）"], ["市街化区域内の農地（4条・5条）", "農業委員会への届出（許可不要）"]]}}},
  {id:10062,unit:'k_kokudo',level:1,field:'limit',text:"国土利用計画法の事前届出（監視区域）について正しいものはどれか。",opts:["全国どこでも事前届出が必要", "都道府県知事が指定した監視区域内での取引が対象", "事前届出は取引後2週間以内に行う", "届出の審査期間中も取引を進められる"],ans:1,exp:`事前届出制は都道府県知事が指定した「監視区域」内での一定規模以上の土地取引に適用されます（国土利用計画法27条の4）。届出後、審査期間（6週間以内）は契約締結ができません。`,"kaisetsu":{"topic": "国土利用計画法：事後届出は2週間以内・市街化区域は2,000㎡以上・規制区域は許可制", "basis": {"text": "事後届出は契約締結後2週間以内（国土利用計画法23条）。市街化区域は2,000㎡以上・市街化調整区域は5,000㎡以上・都市計画区域外は10,000㎡以上。届出義務者は買主のみ。規制区域は許可制。", "example": ""}, "reason": {"text": "国土利用計画法の事前届出（監視区域）は都道府県知事が指定した監視区域内での取引が対象です（国土利用計画法27条の6・27条の7）。審査期間中は契約できません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">国土利用計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">区域</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">基準面積</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2,000㎡以上</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化調整区域</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都市計画区域外</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10,000㎡以上</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">規制区域</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">許可制（届出ではない）</text></svg>", "choices": [{"label": "全国どこでも事前届出が必要", "reason": "事前届出は監視区域・注視区域内での取引が対象です（国土利用計画法27条の6・27条の7）。全国一律ではありません。", "caution": "事前届出：監視区域・注視区域内での取引が対象（国土利用計画法27条の6・27条の7）。"}, {"label": "事前届出は取引後2週間以内に行う", "reason": "事前届出は取引「前」に行うものです（国土利用計画法27条の6第1項）。事後ではありません。", "caution": ""}, {"label": "届出の審査期間中も取引を進められる", "reason": "監視区域内では届出後6週間は契約できません（国土利用計画法27条の6第1項）。", "caution": ""}], "summary": {"head": ["事前届出制（国土利用計画法27条の6）", "内容"], "rows": [["対象", "監視区域・注視区域内での一定規模以上の取引"], ["届出時期", "取引「前」"], ["審査期間", "6週間（契約不可）"]]}}},
  {id:10063,unit:'k_kukaku',level:1,field:'limit',text:"土地区画整理事業の施行者として含まれないものはどれか。",opts:["個人", "土地区画整理組合", "都道府県・市町村", "外国法人"],ans:3,exp:`土地区画整理事業の施行者は個人・組合・区画整理会社・地方公共団体・国土交通大臣・機構等です（土地区画整理法3条）。外国法人は施行者となれません。`,"kaisetsu":{"topic": "土地区画整理法：換地は公告翌日確定・仮換地は従前地使用不可・組合は2/3以上", "basis": {"text": "換地処分の公告翌日から換地が確定します（土地区画整理法104条）。仮換地の指定後は従前地を使用できなくなります（同法99条）。組合設立には土地所有者・借地権者の各2/3以上の同意が必要です。", "example": ""}, "reason": {"text": "土地区画整理事業の施行者は個人・土地区画整理組合・区画整理会社・市町村・都道府県・国土交通大臣・独立行政法人等です（土地区画整理法3条〜7条）。外国法人は施行者として認められていません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">土地区画整理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">換地の確定</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公告の翌日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮換地指定後</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従前地は使用不可（所有権は残る）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">組合設立</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各2/3以上の同意</text></svg>", "choices": [{"label": "個人", "reason": "個人も施行者になれます（土地区画整理法3条1項）。", "caution": ""}, {"label": "土地区画整理組合", "reason": "組合も施行者になれます（土地区画整理法3条2項）。", "caution": ""}, {"label": "都道府県・市町村", "reason": "都道府県・市町村も施行者になれます（土地区画整理法3条4項・5項）。", "caution": ""}], "summary": {"head": ["土地区画整理事業の施行者", "内容"], "rows": [["個人・組合・会社", "可"], ["市町村・都道府県", "可"], ["外国法人", "認められていない"]]}}},
  {id:10064,unit:'t_joto',level:1,field:'tax',text:"不動産を譲渡した場合の所得の種類として正しいものはどれか。",opts:["給与所得", "事業所得", "譲渡所得", "一時所得"],ans:2,exp:`土地・建物等の不動産を譲渡した場合の所得は「譲渡所得」に分類され、他の所得と分離して課税される申告分離課税方式が適用されます（租税特別措置法31条・32条）。`,"kaisetsu":{"topic": "譲渡所得：分離課税・長期は20%・3,000万円控除は3年に1回", "basis": {"text": "土地・建物の譲渡所得は分離課税。長期（5年超）は合計20%（所得税15%+住民税5%）。短期（5年以下）は39%（所得税30%+住民税9%）。3,000万円特別控除は前年・前々年に適用があれば使えません（3年に1回）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">譲渡所得のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税方式</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">分離課税</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">長期（5年超）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計20%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">短期（5年以下）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計39%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3,000万円控除</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年に1回の制限</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10065,unit:'t_shutoku',level:1,field:'tax',text:"不動産取得税の課税標準となるものはどれか。",opts:["取得時の購入価格", "固定資産税評価額", "地価公示価格", "相続税評価額"],ans:1,exp:`不動産取得税の課税標準は固定資産税評価額です（地方税法73条の13）。購入価格や相続税評価額ではありません。`,"kaisetsu":{"topic": "不動産取得税：都道府県が課す地方税・相続は非課税・1回だけ課税", "basis": {"text": "不動産取得税は都道府県が課す地方税（地方税法73条の2）。相続・法人の合併等は非課税。一度の取得に一度だけ課税（毎年ではない）。標準税率は4%（住宅・土地は3%の軽減あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産取得税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税の頻度</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取得時に1回のみ</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">標準税率</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4%（住宅・土地は3%）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10066,unit:'t_kotei',level:1,field:'tax',text:"固定資産税の小規模住宅用地の特例について正しいものはどれか。",opts:["200平方メートル以下の住宅用地は課税標準が6分の1になる", "200平方メートル超の部分は課税標準が3分の1になる", "小規模住宅用地の特例は建物にのみ適用される", "空き家でも住宅用地の特例は適用される"],ans:0,exp:`小規模住宅用地（200平方メートル以下の部分）は固定資産税の課税標準が評価額の6分の1となる特例があります（地方税法349条の3の2）。200平方メートル超の一般住宅用地は3分の1です。`,"kaisetsu":{"topic": "固定資産税：市町村が課す地方税・賦課期日は1月1日・評価替えは3年ごと", "basis": {"text": "固定資産税は市町村（東京23区は都）が課す地方税（地方税法343条）。賦課期日は毎年1月1日。評価替えは3年ごと（基準年度）。住宅用地の特例：200㎡以下は課税標準1/6、超過部分は1/3。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">固定資産税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市町村（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賦課期日</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">評価替え</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年ごと</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅用地（200㎡以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税標準1/6</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10067,unit:'t_toroku',level:1,field:'tax',text:"登録免許税の課税標準（所有権移転登記・売買の場合）として正しいものはどれか。",opts:["売買価格", "固定資産税評価額", "地価公示価格", "路線価"],ans:1,exp:`売買による所有権移転登記の課税標準は固定資産税評価額です（登録免許税法10条）。相続・贈与・交換等によっても固定資産税評価額が課税標準となります。`,"kaisetsu":{"topic": "登録免許税：所有権移転登記等に課税・国税・税率は課税標準×一定率", "basis": {"text": "登録免許税は不動産の所有権移転登記等に課税される国税（登録免許税法1条）。税率は課税標準（通常は固定資産税評価額）×一定率で計算します。相続による所有権移転登記は0.4%、売買は2%が原則税率（軽減措置あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">登録免許税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">国（国税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税対象</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">所有権移転登記等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">0.4%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2%（軽減措置あり）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10068,unit:'r_baibai',level:1,field:'rights',text:'売主の契約不適合責任（民法上）において、買主が責任を追及するために必要な通知の期限として正しいものはどれか。',opts:['引渡しから1年以内に損害賠償請求をしなければならない','不適合を知った時から1年以内に売主へ通知しなければならない','契約締結から5年以内に請求しなければならない','特約がない限り期限はない'],ans:1,exp:`民法566条により、買主は「不適合を知った時から1年以内」に売主へ通知しなければ契約不適合責任を追及できなくなります。通知後の訴訟は別途消滅時効の範囲内で行えます。`,"kaisetsu":{"topic": "売買：同時履行の抗弁権・解除は原則催告が必要・契約不適合責任", "basis": {"text": "売買では代金と引渡しは同時履行の関係（民法533条）。解除は原則として相当の期間を定めた催告後に行います（民法541条）。契約不適合責任の通知は知った時から1年以内（民法566条）。", "example": ""}, "reason": {"text": "2020年民法改正後、契約不適合責任において種類・品質の不適合を理由に権利行使するには、買主が不適合を知った時から1年以内に売主へ通知しなければなりません（民法566条）。通知さえすれば1年内に訴訟提起しなくても権利は保全されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">売買のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">同時履行</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金と引渡しは同時履行</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則として催告が必要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">契約不適合の通知</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から1年以内</text></svg>", "choices": [{"label": "引渡しから1年以内に損害賠償請求をしなければならない", "reason": "通知の期限は「引渡しから1年」ではなく「不適合を知った時から1年」です（民法566条）。また「損害賠償請求」ではなく「通知」が要件です。", "caution": "起算点は「知った時」。要件は「通知」（請求ではない）。"}, {"label": "契約締結から5年以内に請求しなければならない", "reason": "5年は消滅時効期間（民法166条）です。通知の期限（民法566条）とは異なります。", "caution": ""}, {"label": "特約がない限り期限はない", "reason": "民法566条により種類・品質の不適合は不適合を知った時から1年以内の通知が必要です。特約がなくても期限があります。", "caution": ""}], "summary": {"head": ["契約不適合の権利行使期間", "内容"], "rows": [["種類・品質の不適合", "不適合を知った時から1年以内に通知（民法566条）"], ["数量・権利の不適合", "通知期限なし（一般消滅時効のみ）"], ["消滅時効", "知った時から5年・引渡しから10年（民法166条）"], ["宅建業者の特則", "引渡しから2年以上とする特約は有効（宅建業法40条）"]]}}},
  {id:10069,unit:'r_chinshaku',level:1,field:'rights',text:'建物賃貸借における通常損耗の原状回復義務について正しいものはどれか。',opts:['通常損耗も賃借人が原状回復しなければならない','通常損耗の原状回復費用は賃貸人が負担する','特約があっても通常損耗を賃借人に負担させることはできない','原状回復の範囲は賃貸人が自由に決定できる'],ans:1,exp:`通常の使用による損耗（通常損耗）の原状回復費用は賃貸人が負担します（民法621条・判例）。ただし一定の条件を満たす特約があれば賃借人に負担させることが認められる場合もあります。`,"kaisetsu":{"topic": "賃貸借：通常損耗は原状回復に含まれない・有益費は終了時に請求・賃料増額は正当事由が必要", "basis": {"text": "賃貸借終了時の原状回復義務に通常使用による損耗（壁の日焼け等）は含まれません（民法621条）。必要費は直ちに、有益費は終了時の請求が原則。更新拒絶には正当事由が必要（借地借家法28条）。", "example": ""}, "reason": {"text": "原状回復とは賃借人が借りた状態に戻すことですが、通常損耗（経年劣化・通常の使用による損耗）は賃貸人負担が原則です（民法621条・国交省ガイドライン）。これは通常損耗分はすでに賃料に含まれているという考え方に基づきます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">賃貸借のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通常損耗</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原状回復に含まれない</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要費</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直ちに請求可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有益費</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸借終了時に請求</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">更新拒絶</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当事由が必要</text></svg>", "choices": [{"label": "通常損耗も賃借人が原状回復しなければならない", "reason": "通常損耗の原状回復費用は賃貸人負担が原則です（民法621条）。賃借人の故意・過失・善管注意義務違反による損傷のみが賃借人負担です。", "caution": "通常損耗＝賃貸人負担。賃借人の故意・過失による損傷＝賃借人負担。"}, {"label": "特約があっても通常損耗を賃借人に負担させることはできない", "reason": "賃借人が明確に認識した上で合意した特約であれば、通常損耗を賃借人に負担させることは有効です（判例・ガイドライン）。", "caution": ""}, {"label": "原状回復の範囲は賃貸人が自由に決定できる", "reason": "原状回復の範囲は法令・判例・ガイドラインにより一定のルールがあり、賃貸人が自由に決定できるわけではありません（民法621条）。", "caution": ""}], "summary": {"head": ["損耗の種類", "負担者"], "rows": [["通常損耗・経年劣化", "賃貸人負担（賃料に含まれる）"], ["賃借人の故意・過失による損傷", "賃借人負担"], ["善管注意義務違反（手入れ怠り等）", "賃借人負担"], ["特約での変更", "明確な合意があれば賃借人負担も有効"]]}}},
  {id:10070,unit:'r_souzoku',level:1,field:'rights',text:'配偶者と子1人が共同相続する場合の法定相続分として正しいものはどれか。',opts:['配偶者1/2・子1/2','配偶者2/3・子1/3','配偶者3/4・子1/4','配偶者が全部相続する'],ans:0,exp:`配偶者と子が共同相続する場合の法定相続分は配偶者1/2・子1/2です（民法900条1号）。子が複数の場合は子の取分1/2を均等に分割します。`,"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2・遺産分割は全員合意", "basis": {"text": "配偶者と子は各1/2（民法900条）。放棄は3か月以内に家裁へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2（民法1042条）。兄弟姉妹に遺留分はなし。遺産分割協議は全員合意が必要。", "example": ""}, "reason": {"text": "配偶者と子が相続人の場合、配偶者1/2・子全体で1/2が法定相続分です（民法900条1号）。子が1人なら子は1/2、複数なら均等分割します。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "配偶者2/3・子1/3", "reason": "配偶者と直系尊属（父母等）が相続人の場合の割合です（民法900条2号）。子がいる場合は配偶者1/2・子1/2です。", "caution": "相続人の組合せで割合が変わります：子→1/2、直系尊属→2/3、兄弟姉妹→3/4。"}, {"label": "配偶者3/4・子1/4", "reason": "配偶者と兄弟姉妹が相続人の場合の割合です（民法900条4号）。子がいる場合は配偶者1/2・子1/2です。", "caution": ""}, {"label": "配偶者が全部相続する", "reason": "配偶者のみが相続人の場合は全部相続しますが、子がいる場合は子と分けます（民法900条1号）。", "caution": ""}], "summary": {"head": ["相続人の組合せ", "配偶者", "その他"], "rows": [["配偶者＋子", "1/2", "子全体で1/2（均等分割）"], ["配偶者＋直系尊属", "2/3", "直系尊属全体で1/3"], ["配偶者＋兄弟姉妹", "3/4", "兄弟姉妹全体で1/4"], ["配偶者のみ", "全部", "—"]]}}},
  {id:10071,unit:'r_fuhoko',level:1,field:'rights',text:'不法行為による損害賠償請求権の消滅時効として正しいものはどれか。',opts:['損害及び加害者を知った時から1年','損害及び加害者を知った時から3年（人の生命・身体の侵害は5年）','不法行為時から5年','損害及び加害者を知った時から5年'],ans:1,exp:`不法行為の損害賠償請求権は原則「損害及び加害者を知った時から3年」で時効消滅します（民法724条1号）。ただし人の生命・身体を害する不法行為は「知った時から5年」です（民法724条の2）。`,"kaisetsu":{"topic": "不法行為：故意または過失が必要・使用者責任・工作物責任", "basis": {"text": "不法行為は故意または過失が必要です（民法709条）。使用者は被用者の職務上の不法行為について責任を負います（民法715条）。工作物の所有者は無過失責任（占有者が免責された場合）（民法717条）。", "example": ""}, "reason": {"text": "不法行為による損害賠償請求権の消滅時効は「損害および加害者を知った時から3年」（人の生命・身体侵害は5年）または「不法行為時から20年」のいずれか早い方で消滅します（民法724条・724条の2）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不法行為のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般不法行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">故意または過失が必要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">使用者責任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">被用者への求償可（信義則上制限）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">工作物の所有者責任</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無過失責任（占有者が免責された場合）</text></svg>", "choices": [{"label": "損害及び加害者を知った時から1年", "reason": "不法行為の消滅時効は知った時から「3年」です（民法724条1号）。1年は誤りです。", "caution": "不法行為の消滅時効：知った時から3年（人身は5年）・不法行為時から20年。"}, {"label": "不法行為時から5年", "reason": "不法行為時（客観的起算点）からの時効期間は「20年」です（民法724条2号）。5年は一般債権の主観的起算点の期間（民法166条）です。", "caution": ""}, {"label": "損害及び加害者を知った時から5年", "reason": "5年は一般の債権の主観的起算点からの時効期間（民法166条1項1号）です。不法行為は「3年」です（民法724条1号）。", "caution": ""}], "summary": {"head": ["不法行為の消滅時効", "期間"], "rows": [["主観的起算点（損害・加害者を知った時）", "3年（民法724条1号）"], ["人の生命・身体侵害", "5年（民法724条の2）"], ["客観的起算点（不法行為時）", "20年（民法724条2号）"], ["適用", "いずれか早い方で消滅"]]}}},
  {id:10072,unit:'r_shakuchi',level:1,field:'rights',text:'借地権の最低存続期間として正しいものはどれか。',opts:['20年','30年','50年','期間の定めなし'],ans:1,exp:`借地権の存続期間は最低30年です（借地借家法3条）。これより短い期間を定めても30年となります。更新後は最初が20年、2回目以降は10年ごととなります。`,"kaisetsu":{"topic": "借地権：最短30年・建物登記で対抗・建物滅失でも消滅せず・定期借地権は3種類", "basis": {"text": "普通借地権の最短存続期間は30年（借地借家法3条）。借地上の建物の自己名義登記が対抗要件（同法10条）。建物が滅失しても借地権は消滅しません。定期借地権は①一般（50年以上）②事業用（10〜50年未満）③建物譲渡特約（30年以上）の3種類。", "example": ""}, "reason": {"text": "借地権（建物所有を目的とする地上権・土地賃借権）の存続期間は30年が最低です（借地借家法3条）。当事者がこれより短い期間を定めても30年とみなされます（同条ただし書）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">借地権のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">最短存続期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">対抗要件</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借地上の建物の自己名義登記</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物滅失</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借地権は消滅しない</text></svg>", "choices": [{"label": "20年", "reason": "借地権の最低存続期間は30年です（借地借家法3条）。20年ではありません。", "caution": "借地権の最低存続期間＝30年（借地借家法3条）。"}, {"label": "50年", "reason": "50年は一般定期借地権の最低存続期間です（借地借家法22条）。普通借地権の最低期間は30年です（同法3条）。", "caution": "定期借地権（一般）＝50年以上。普通借地権＝30年以上（最低）。"}, {"label": "期間の定めなし", "reason": "借地権には最低存続期間（30年）があります（借地借家法3条）。期間の定めなしは認められません。", "caution": ""}], "summary": {"head": ["借地権の種類", "存続期間"], "rows": [["普通借地権", "30年以上（最低30年・借地借家法3条）"], ["一般定期借地権", "50年以上（借地借家法22条）"], ["事業用定期借地権", "10年以上50年未満（借地借家法23条）"], ["建物譲渡特約付借地権", "30年以上（借地借家法24条）"]]}}},
  {id:10073,unit:'r_kukku',level:1,field:'rights',text:'区分所有建物の共用部分の重大変更（形状・効用の著しい変更）の決議要件として正しいものはどれか。',opts:['区分所有者及び議決権の各過半数','区分所有者及び議決権の各3/4以上の多数','区分所有者及び議決権の各4/5以上の多数','区分所有者全員の同意'],ans:1,exp:`共用部分の重大変更は区分所有者及び議決権の各3/4以上の多数決が必要です（区分所有法17条1項）。形状・効用を著しく変えない軽微変更は普通決議（過半数）で可能です。`,"kaisetsu":{"topic": "区分所有法：重大変更は3/4以上・建替えは4/5以上・管理組合法人は30人以上", "basis": {"text": "共用部分の重大変更は区分所有者・議決権の各3/4以上の特別決議が必要（区分所有法17条）。建替えは4/5以上（同法62条）。管理組合法人の設立は3/4以上かつ区分所有者30人以上（同法47条）。専有部分と共有持分は分離処分不可（同法15条）。", "example": ""}, "reason": {"text": "共用部分の重大変更（形状・効用の著しい変更）は区分所有者および議決権の各3/4以上の多数決が必要です（区分所有法17条1項）。軽微変更（形状・効用の著しい変更を伴わない変更）は過半数で足ります。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">区分所有法の決議要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">事項</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">普通決議</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">過半数</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">重大変更・規約変更</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3/4以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">管理組合法人</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3/4以上（30人以上）</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建替え</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4/5以上</text></svg>", "choices": [{"label": "区分所有者及び議決権の各過半数", "reason": "過半数は軽微変更（通常の管理行為）の決議要件です（区分所有法18条1項）。重大変更は3/4以上が必要です（同法17条1項）。", "caution": "重大変更＝3/4以上。軽微変更＝過半数。"}, {"label": "区分所有者及び議決権の各4/5以上の多数", "reason": "4/5以上は建替え決議の要件です（区分所有法62条1項）。重大変更は3/4以上です（同法17条1項）。", "caution": ""}, {"label": "区分所有者全員の同意", "reason": "全員同意は不要です。重大変更は3/4以上で足ります（区分所有法17条1項）。", "caution": ""}], "summary": {"head": ["区分所有法の決議要件", "内容"], "rows": [["軽微変更（通常管理）", "過半数（区分所有法18条1項）"], ["重大変更（形状・効用の著しい変更）", "3/4以上（区分所有法17条1項）"], ["規約の設定・変更・廃止", "3/4以上（区分所有法31条1項）"], ["建替え決議", "4/5以上（区分所有法62条1項）"]]}}},
  {id:10074,unit:'r_touki',level:1,field:'rights',text:'不動産登記における仮登記の効力として正しいものはどれか。',opts:['仮登記だけで第三者に物権変動を対抗できる','仮登記は本登記の順位保全効を持つ','仮登記後は当該不動産の取引が禁止される','仮登記は2年で自動的に失効する'],ans:1,exp:`仮登記は本登記の順位保全効を持ちます（不動産登記法105条）。本登記がされると仮登記の順位が遡及し、仮登記後に登記した第三者に対抗できます。`,"kaisetsu":{"topic": "不動産登記：権利登記は共同申請・仮登記は順位保全・建物滅失は1か月以内", "basis": {"text": "権利に関する登記は原則として登記権利者と登記義務者が共同申請します（不動産登記法60条）。仮登記は順位保全機能があるが完全な対抗力は本登記後です。建物滅失登記の申請義務は1か月以内（同法57条）。", "example": ""}, "reason": {"text": "仮登記は本登記申請に必要な書類が揃わない場合等に利用し、本登記の順位を保全します（不動産登記法105条）。本登記後は仮登記の日付で順位が確定するため、仮登記後に行われた他の登記より優先されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産登記のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利登記</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則として共同申請</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮登記</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">順位保全（対抗力は本登記後）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物滅失登記</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1か月以内</text></svg>", "choices": [{"label": "仮登記だけで第三者に物権変動を対抗できる", "reason": "仮登記単独では対抗力はありません。本登記後に初めて仮登記の日時で対抗力が生じます（不動産登記法106条）。", "caution": "仮登記＝順位保全のみ。対抗力は本登記後に発生します。"}, {"label": "仮登記後は当該不動産の取引が禁止される", "reason": "仮登記があっても不動産の処分自体は禁止されません。ただし仮登記後に行われた登記は本登記後に劣後します。", "caution": ""}, {"label": "仮登記は2年で自動的に失効する", "reason": "仮登記に有効期限はありません。本登記に移行するまで存続します。", "caution": ""}], "summary": {"head": ["仮登記の種類", "利用場面"], "rows": [["1号仮登記", "登記申請に必要な添付書類が不足している場合"], ["2号仮登記（条件付・予約）", "権利変動が条件付・始期付または将来の請求権保全"], ["共通の効果", "本登記後に仮登記の順位で効力発生（中間処分は抹消）"]]}}},
  {id:10075,unit:'l_menkyo',level:1,field:'law',text:'宅地建物取引業の免許の有効期間として正しいものはどれか。',opts:['1年','3年','5年','10年'],ans:2,exp:`宅建業の免許の有効期間は5年です（宅建業法3条2項）。引き続き業を営む場合は有効期間満了の90日前から30日前までに更新申請を行う必要があります。`,"kaisetsu":{"topic": "宅建業免許：知事・大臣免許の区別・有効期間5年・欠格事由は5年", "basis": {"text": "1都道府県→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間。2020年改正で成年被後見人の欠格条項は廃止。", "example": ""}, "reason": {"text": "宅地建物取引業の免許の有効期間は5年です（宅建業法3条2項）。期間満了の90日前から30日前までの間に更新申請が必要です（同条3項）。有効期間・更新申請時期の数字は頻出です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（2020年改正で成年被後見人は廃止）</text></svg>", "choices": [{"label": "1年", "reason": "免許の有効期間は5年です（宅建業法3条2項）。1年ではありません。", "caution": "宅建業の免許：有効期間5年、更新申請は満了の90日前〜30日前（宅建業法3条）。"}, {"label": "3年", "reason": "免許の有効期間は5年です（宅建業法3条2項）。3年ではありません。専任媒介契約の上限期間3か月と混同しないようにしましょう。", "caution": ""}, {"label": "10年", "reason": "免許の有効期間は5年です（宅建業法3条2項）。10年ではありません。", "caution": ""}], "summary": {"head": ["宅建業の免許", "内容"], "rows": [["有効期間", "5年（宅建業法3条2項）"], ["更新申請時期", "満了の90日前から30日前まで"], ["更新しない場合", "期間満了で免許失効"], ["宅建士証の有効期間", "同じく5年（宅建業法22条の2第1項）"]]}}},
  {id:10076,unit:'l_takkenshi',level:1,field:'law',text:'宅地建物取引士証の有効期間として正しいものはどれか。',opts:['3年','5年','7年','10年'],ans:1,exp:`宅建士証の有効期間は5年です（宅建業法22条の2第3項）。更新時には交付申請前6ヶ月以内に行われた法定講習の受講が必要です。`,"kaisetsu":{"topic": "専任宅建士：5人に1人以上・兼任不可・2週間以内に補充", "basis": {"text": "事務所には業務従事者5人に1人以上の専任宅建士が必要（宅建業法31条の3）。1社専属で複数業者の兼任は不可。不足時は2週間以内に補充が必要。案内所（申込み受付）にも専任宅建士が必要。", "example": ""}, "reason": {"text": "宅地建物取引士証の有効期間は5年です（宅建業法22条の2第1項）。更新には有効期間満了前に法定講習（都道府県知事が指定する講習）を受講し、申請する必要があります（同条2項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">専任宅建士のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">設置基準</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5人に1人以上</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">兼任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可（1社専属）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不足補充</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間以内</text></svg>", "choices": [{"label": "3年", "reason": "宅建士証の有効期間は5年です（宅建業法22条の2第1項）。3年ではありません。", "caution": "宅建士証の有効期間＝5年（宅建業法22条の2第1項）。宅建業の免許と同じ5年です。"}, {"label": "7年", "reason": "宅建士証の有効期間は5年です（宅建業法22条の2第1項）。7年ではありません。", "caution": ""}, {"label": "10年", "reason": "宅建士証の有効期間は5年です（宅建業法22条の2第1項）。10年ではありません。", "caution": ""}], "summary": {"head": ["宅建士証", "内容"], "rows": [["有効期間", "5年（宅建業法22条の2第1項）"], ["更新申請", "有効期間満了前に法定講習受講後申請"], ["交付申請時期", "試験合格から1年以内は講習不要。1年超は講習が必要"], ["返納義務", "事務禁止処分・登録消除時等"]]}}},
  {id:10077,unit:'l_baikai',level:1,field:'law',text:'媒介契約の種類のうち、依頼者が他の宅建業者に重ねて依頼できるものはどれか。',opts:['専属専任媒介契約','専任媒介契約','一般媒介契約','いずれも重ねて依頼できない'],ans:2,exp:`一般媒介契約は依頼者が複数の宅建業者に重ねて依頼することができます（宅建業法34条の2）。専任・専属専任媒介契約では他業者への依頼が禁じられます。`,"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任の有効期間は最長3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。レインズ登録は専任7日以内・専属専任5日以内。業務報告は専任2週間に1回・専属専任1週間に1回。", "example": ""}, "reason": {"text": "複数の宅建業者に重ねて依頼できるのは一般媒介契約のみです（宅建業法34条の2第1項3号）。専任媒介・専属専任媒介は1社のみへの依頼が要件です（同条1項4号・同条3項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">自己発見</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">レインズ</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専任</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専属専任</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text></svg>", "choices": [{"label": "専属専任媒介契約", "reason": "専属専任媒介は1社のみへの依頼が条件で、他業者への重ねた依頼はできません（宅建業法34条の2第3項）。", "caution": "一般媒介＝複数業者に依頼可。専任・専属専任＝1社のみ。"}, {"label": "専任媒介契約", "reason": "専任媒介は1社のみへの依頼が条件で、他業者への重ねた依頼はできません（宅建業法34条の2第1項4号）。", "caution": ""}, {"label": "いずれも重ねて依頼できない", "reason": "一般媒介契約では複数業者への重ねた依頼ができます（宅建業法34条の2第1項3号）。「いずれも不可」は誤りです。", "caution": ""}], "summary": {"head": ["媒介契約と依頼先", "内容"], "rows": [["一般媒介", "複数の宅建業者に依頼可"], ["専任媒介", "1社のみ（他業者への依頼禁止）"], ["専属専任媒介", "1社のみ（自己発見取引も禁止）"]]}}},
  {id:10078,unit:'l_hoshu',level:1,field:'law',text:'宅建業者が受領できる報酬の限度額を定める権限を持つのはどれか。',opts:['宅建業法の条文に直接規定されている','国土交通大臣が告示で定める','都道府県知事が条例で定める','業者間の自由合意で決まる'],ans:1,exp:`報酬の限度額は国土交通大臣が告示で定めます（宅建業法46条1項）。業者はこの告示を超えて報酬を受領することはできません。`,"kaisetsu":{"topic": "報酬：売買は代金×3%+6万（400万超）・賃貸は借賃1か月・上限超過は不可", "basis": {"text": "売買（400万超）の一方からの上限は代金×3%+6万。双方合計は一方上限×2。賃貸（居住用・非居住用とも）は借賃1か月分。低廉な空家等（800万円以下）は、媒介報酬について原則の報酬額を超えて30万円（税別）まで受領できる場合があります（依頼者への説明・合意が必要）。", "example": ""}, "reason": {"text": "宅建業者が受領できる報酬の限度額は国土交通大臣が告示で定めます（宅建業法46条1項・2項）。告示で定められた限度額を超えて報酬を受け取ることは禁止されています（同条3項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対象</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（400万超）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万（一方）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（200万以下）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸（双方合計）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借賃1か月分</text></svg>", "choices": [{"label": "宅建業法の条文に直接規定されている", "reason": "宅建業法46条は大臣告示に委任しており、限度額の具体的数値は告示で定められています（宅建業法46条2項）。", "caution": "報酬限度額：国土交通大臣告示で定める（宅建業法46条2項）。"}, {"label": "都道府県知事が条例で定める", "reason": "報酬限度額は都道府県条例ではなく国土交通大臣告示で定めます（宅建業法46条2項）。", "caution": ""}, {"label": "業者間の自由合意で決まる", "reason": "報酬限度額は強行規定（告示）であり、依頼者の合意があっても超えることはできません（宅建業法46条3項）。", "caution": ""}], "summary": {"head": ["報酬規制の根拠", "内容"], "rows": [["宅建業法46条", "報酬の限度額を大臣告示で定めることを規定"], ["国土交通省告示", "具体的な限度額（速算式等）を規定"], ["強行規定", "依頼者の合意があっても上限超は禁止"], ["違反の効果", "宅建業法違反→指示・業務停止処分等"]]}}},
  {id:10079,unit:'k_toshi',level:1,field:'limit',text:'市街化区域と市街化調整区域の区分（線引き）を決定する権限を持つのはどれか。',opts:['市町村','都道府県（政令指定都市は市）','国土交通大臣','都市計画審議会'],ans:1,exp:`市街化区域と市街化調整区域の区分（線引き）は都道府県が決定します（都市計画法7条）。政令指定都市は市が定めることができます。`,"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域の1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "市街化区域と市街化調整区域の区分（線引き）は都道府県が都市計画として定めます（都市計画法7条1項・15条1項）。政令指定都市は市が定めます（同法87条の2）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "市町村", "reason": "線引きは原則として都道府県が定めます（都市計画法15条1項）。政令指定都市は例外です（同法87条の2）。", "caution": "線引き：都道府県（政令指定都市は市）が決定（都市計画法7条・15条）。"}, {"label": "国土交通大臣", "reason": "線引きは都道府県が定めます（都市計画法15条1項）。国交大臣が直接決定するものではありません。", "caution": ""}, {"label": "都市計画審議会", "reason": "都市計画審議会は諮問機関であり、線引きを決定するのは都道府県です（都市計画法15条1項）。", "caution": ""}], "summary": {"head": ["市街化区域・市街化調整区域の線引き", "決定者"], "rows": [["原則", "都道府県が都市計画として決定（都市計画法15条1項）"], ["政令指定都市", "市が決定（都市計画法87条の2）"], ["義務的線引き", "大都市圏等の特定区域（都市計画法7条1項）"], ["任意線引き", "それ以外の区域（任意で線引き可能）"]]}}},
  {id:10080,unit:'k_toshi',level:1,field:'limit',text:'市街化区域内での開発行為において、開発許可が不要となる規模の上限として正しいものはどれか。',opts:['100平方メートル未満','500平方メートル未満','1,000平方メートル未満','3,000平方メートル未満'],ans:2,exp:`市街化区域内での開発行為で開発許可が不要となる上限面積は1,000平方メートル未満です（都市計画法29条1項1号）。なお三大都市圏の一部特定市では500平方メートル未満が基準となる場合があります。`,"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域の1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "市街化区域内での開発行為には原則として開発許可が必要ですが、規模が1000㎡未満（三大都市圏の特定区域は500㎡未満）の場合は許可不要です（都市計画法29条1項1号・都市計画法施行令19条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "100平方メートル未満", "reason": "市街化区域での許可不要基準は1000㎡未満です（都市計画法施行令19条1項）。100㎡は誤りです。", "caution": "市街化区域の開発許可不要基準：1000㎡未満（施行令19条1項）。"}, {"label": "500平方メートル未満", "reason": "500㎡未満は三大都市圏の特定区域の基準です（都市計画法施行令19条2項）。一般的な市街化区域の基準は1000㎡未満です。", "caution": ""}, {"label": "3,000平方メートル未満", "reason": "3000㎡未満という基準は現行法では一般的な市街化区域の基準ではありません（都市計画法施行令19条1項）。", "caution": ""}], "summary": {"head": ["開発許可不要の規模基準（都市計画法施行令19条）", "基準"], "rows": [["市街化区域（一般）", "1000㎡未満"], ["三大都市圏の特定区域", "500㎡未満"], ["市街化調整区域", "規模にかかわらず原則許可が必要"], ["非線引き区域", "3000㎡未満（施行令19条1項）"]]}}},
  {id:10081,unit:'k_kenchiku',level:1,field:'limit',text:'建ぺい率の定義として正しいものはどれか。',opts:['延べ面積を敷地面積で割った割合','建築面積を敷地面積で割った割合','建物の高さを隣地境界距離で割った割合','床面積合計を建築面積で割った割合'],ans:1,exp:`建ぺい率は建築面積（建物を真上から見た水平投影面積）を敷地面積で割った値で、敷地に対する建物の平面的な広がりを示します（建築基準法53条）。延べ面積÷敷地面積は容積率です。`,"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・用途制限・道路斜線", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。防火地域の耐火建築物は隣地境界線に外壁を接して建築可（同法65条）。", "example": ""}, "reason": {"text": "建ぺい率は建築面積（建物の水平投影面積）を敷地面積で割った割合です（建築基準法53条）。延べ面積（全階の床面積合計）を使うのは容積率の計算です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">防火地域の耐火建築物</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">隣地境界線に接して建築可</text></svg>", "choices": [{"label": "延べ面積を敷地面積で割った割合", "reason": "延べ面積÷敷地面積は容積率の計算です（建築基準法52条）。建ぺい率は建築面積÷敷地面積です（同法53条）。", "caution": "建ぺい率＝建築面積÷敷地面積。容積率＝延べ面積÷敷地面積。"}, {"label": "建物の高さを隣地境界距離で割った割合", "reason": "建物の高さ÷隣地境界距離は斜線制限の計算に関連しますが、建ぺい率の定義ではありません（建築基準法53条）。", "caution": ""}, {"label": "床面積合計を建築面積で割った割合", "reason": "延べ面積÷建築面積は階数の概算には使えますが、建ぺい率の定義ではありません（建築基準法53条）。", "caution": ""}], "summary": {"head": ["建ぺい率と容積率の定義", "計算式"], "rows": [["建ぺい率", "建築面積÷敷地面積（建築基準法53条）"], ["容積率", "延べ面積÷敷地面積（建築基準法52条）"], ["建築面積", "建物の水平投影面積（1階部分の面積等）"], ["延べ面積", "各階の床面積の合計"]]}}},
  {id:10082,unit:'k_nochi',level:1,field:'limit',text:'農地を相続により取得する場合の農地法3条の許可の要否として正しいものはどれか。',opts:['都道府県知事の許可が必要','農業委員会の許可が必要','許可は不要で農業委員会への届出が必要','届出も許可も一切不要'],ans:2,exp:`農地の相続取得は農地法3条の許可は不要ですが（農地法3条1項ただし書）、取得後は農業委員会への届出が必要です（農地法3条の3）。`,"kaisetsu":{"topic": "農地法：3条は農業委員会・4・5条は都道府県知事・市街化区域は届出のみ", "basis": {"text": "農地法3条の許可権者は農業委員会。4・5条は都道府県知事等。市街化区域の農地転用（4・5条）は農業委員会への届出のみOK。相続は許可不要・3か月以内の農業委員会への届出が必要。", "example": ""}, "reason": {"text": "相続による農地の取得は農地法3条の許可不要ですが（農地法3条1項）、取得後に農業委員会への届出が必要です（農地法3条の3第1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text></svg>", "choices": [{"label": "都道府県知事の許可が必要", "reason": "相続による農地取得に都道府県知事の許可は不要です（農地法3条1項）。届出のみです（同法3条の3第1項）。", "caution": "相続による農地取得：農地法3条の許可不要→農業委員会への届出が必要（農地法3条の3第1項）。"}, {"label": "農業委員会の許可が必要", "reason": "相続は農地法3条の許可不要です（農地法3条1項）。届出が必要です（同法3条の3第1項）。", "caution": ""}, {"label": "届出も許可も一切不要", "reason": "農業委員会への届出が必要です（農地法3条の3第1項）。「一切不要」は誤りです。", "caution": ""}], "summary": {"head": ["相続と農地法", "内容"], "rows": [["相続による農地取得", "農地法3条の許可不要"], ["届出", "農業委員会への届出が必要（農地法3条の3第1項）"], ["贈与", "農業委員会の許可が必要（農地法3条1項）"]]}}},
  {id:10083,unit:'k_kokudo',level:1,field:'limit',text:'国土利用計画法の事後届出制において、市街化区域内で届出が必要となる面積要件はどれか。',opts:['500平方メートル以上','1,000平方メートル以上','2,000平方メートル以上','5,000平方メートル以上'],ans:2,exp:`市街化区域内の土地取引で事後届出が必要となる面積要件は2,000平方メートル以上です（国土利用計画法23条）。市街化調整区域等は5,000平方メートル以上、その他の区域は10,000平方メートル以上です。`,"kaisetsu":{"topic": "国土利用計画法：事後届出は2週間以内・市街化区域は2,000㎡以上・規制区域は許可制", "basis": {"text": "事後届出は契約締結後2週間以内（国土利用計画法23条）。市街化区域は2,000㎡以上・市街化調整区域は5,000㎡以上・都市計画区域外は10,000㎡以上。届出義務者は買主のみ。規制区域は許可制。", "example": ""}, "reason": {"text": "国土利用計画法の事後届出制において市街化区域内では2000㎡以上の土地取引に届出が必要です（国土利用計画法23条1項・施行令17条）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">国土利用計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">区域</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">基準面積</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2,000㎡以上</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化調整区域</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都市計画区域外</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10,000㎡以上</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">規制区域</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">許可制（届出ではない）</text></svg>", "choices": [{"label": "500平方メートル以上", "reason": "市街化区域内の基準は2000㎡以上です（国土利用計画法施行令17条）。", "caution": "市街化区域内の事後届出基準：2000㎡以上（国土利用計画法施行令17条）。"}, {"label": "1,000平方メートル以上", "reason": "市街化区域内の基準は2000㎡以上です（国土利用計画法施行令17条）。", "caution": ""}, {"label": "5,000平方メートル以上", "reason": "市街化区域内の基準は2000㎡以上です（国土利用計画法施行令17条）。", "caution": ""}], "summary": {"head": ["事後届出の面積基準（国土利用計画法施行令17条）", "基準"], "rows": [["市街化区域", "2000㎡以上"], ["非線引き都市計画区域・準都市計画区域", "5000㎡以上"], ["都市計画区域外", "10000㎡以上"]]}}},
  {id:10084,unit:'t_kinyu',level:1,field:'tax',text:'住宅金融支援機構が提供するフラット35の仕組みとして正しいものはどれか。',opts:['機構が直接個人へ長期固定金利で融資する','民間金融機関が実行した住宅ローン債権を機構が買い取る証券化支援による長期固定金利ローン','変動金利のみ取り扱う住宅ローン','新築住宅のみを対象とした住宅ローン'],ans:1,exp:`フラット35は民間金融機関が実行した住宅ローンを住宅金融支援機構が買い取ることで成り立つ長期固定金利の住宅ローンです。中古住宅も対象で、機構が直接融資するものではありません。`,"kaisetsu":{"topic": "住宅金融支援機構・フラット35：証券化支援が主業務・全期間固定・各機関が金利設定", "basis": {"text": "住宅金融支援機構はフラット35（民間住宅ローンの証券化支援）が主業務。フラット35は全期間固定金利のみで変動金利の選択はできません。金利は各民間金融機関が独自に設定。返済期間は15年以上35年以下。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">フラット35のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">主な業務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">民間住宅ローンの証券化支援</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">金利</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全期間固定・各金融機関が設定</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">返済期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">15年以上35年以下</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">申込み先</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">民間金融機関</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10085,unit:'t_tokei',level:1,field:'tax',text:'建物の構造に関する説明として正しいものはどれか。',opts:['鉄骨造（S造）は鉄骨をコンクリートで包んだ構造である','鉄筋コンクリート造（RC造）は耐久性・耐火性・耐震性に優れる','鉄骨鉄筋コンクリート造（SRC造）は木造より耐震性が低い','木造は法律上宅地建物取引の構造として不適格とされる'],ans:1,exp:`鉄筋コンクリート造（RC造）は鉄筋の引張力とコンクリートの圧縮力を組み合わせた構造で耐久性・耐火性・耐震性に優れます。鉄骨造（S造）はコンクリートを使用せず鉄骨のみで構成します。`,"kaisetsu":{"topic": "不動産統計・土地・建物の知識", "basis": {"text": "住宅着工戸数は近年80万戸前後。首都圏マンション価格は上昇傾向。J-REITの運用資産は拡大傾向。中古住宅流通は活発化。台地は宅地に適しており、干拓地は水害リスクが高いです。扇状地は比較的安定した地盤です。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産統計・土地の特性</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">近年の傾向</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅着工戸数</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">80万戸前後</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">首都圏マンション価格</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">上昇傾向</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">J-REIT</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">拡大傾向</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">干拓地</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">水害リスク高</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10086,unit:'r_sorin',level:1,field:'rights',text:'共有物の管理行為（保存・管理・変更）のうち、共有者全員の同意が必要なものはどれか。',opts:['保存行為','管理行為（利用・改良）','変更行為（処分・重要な変更）','いずれも持分過半数でよい'],ans:2,exp:`変更行為（処分・重要な変更）は共有者全員の同意が必要です（民法251条）。管理行為（利用・改良）は持分価格の過半数で決定でき、保存行為は各共有者が単独でできます。`,"kaisetsu":{"topic": "相隣関係：竹木の根は自ら切除可・枝は原則所有者に・境界から50cmは慣習で変更可", "basis": {"text": "竹木の根が境界を越えたら自ら切除可（民法233条2項）。枝は原則として所有者に切除させます。建物の境界からの距離（50cm）は慣習・条例で変更可（民法234条・236条）。袋地通行権は有償が原則（民法212条）。", "example": ""}, "reason": {"text": "共有物の管理は行為の重大性に応じて必要な同意が異なります（民法251条・252条）。変更行為（処分・重要な変更）は全員の同意、管理行為は持分の過半数、保存行為は各共有者が単独で行えます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相隣関係のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">事項</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">ルール</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">竹木の根（越境）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自ら切除可</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">竹木の枝（越境）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則：所有者に切除させる</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">境界距離（50cm）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">慣習・条例で変更可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">袋地通行権</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有償が原則</text></svg>", "choices": [{"label": "保存行為", "reason": "保存行為（不法占拠者への明渡し請求・修繕等）は各共有者が単独で行えます（民法252条5項）。全員の同意は不要です。", "caution": "保存行為＝単独可。管理行為＝持分過半数。変更行為＝全員同意。"}, {"label": "管理行為（利用・改良）", "reason": "管理行為は持分の価格の過半数で決定できます（民法252条1項）。全員同意は不要です。", "caution": ""}, {"label": "いずれも持分過半数でよい", "reason": "変更行為（処分・重要な変更）は全員の同意が必要です（民法251条1項）。持分過半数では足りません。", "caution": ""}], "summary": {"head": ["共有物の行為", "必要な同意"], "rows": [["保存行為", "各共有者が単独可（民法252条5項）"], ["管理行為（利用・改良）", "持分の価格の過半数（民法252条1項）"], ["変更行為（重要な変更・処分）", "共有者全員の同意（民法251条1項）"], ["軽微な変更（形状等）", "持分の価格の過半数（民法251条1項ただし書）"]]}}},
  {id:10087,unit:'l_37jo',level:1,field:'law',text:'37条書面（契約書面）を交付すべき相手として正しいものはどれか。',opts:['売主のみ','買主のみ','売主と買主の双方','媒介した宅建業者のみ'],ans:2,exp:`37条書面は宅地建物取引の各当事者（売主・買主の双方）に交付しなければなりません（宅建業法37条1項）。`,"kaisetsu":{"topic": "37条書面：全取引で交付・記名（押印不要）・移転登記申請時期は必要的記載事項", "basis": {"text": "37条書面は全取引で契約の双方当事者に交付が義務（宅建業法37条）。引渡し時期・移転登記申請時期は必要的記載事項。2021年改正で押印は不要、記名のみで足ります。", "example": ""}, "reason": {"text": "37条書面は売買契約においては売主・買主の双方に交付しなければなりません（宅建業法37条1項）。賃貸借においては賃貸人・賃借人双方に交付します。媒介業者は依頼者だけでなく相手方にも交付します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付義務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全取引・双方当事者</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡時期・移転登記申請時期等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要）</text></svg>", "choices": [{"label": "売主のみ", "reason": "37条書面は売主・買主の双方に交付しなければなりません（宅建業法37条1項）。売主のみでは不足です。", "caution": "37条書面：売主・買主双方に交付（宅建業法37条1項）。"}, {"label": "買主のみ", "reason": "買主のみでは不足です。売主・買主双方に交付しなければなりません（宅建業法37条1項）。", "caution": ""}, {"label": "媒介した宅建業者のみ", "reason": "宅建業者は交付を行う側であり、交付を受ける側ではありません（宅建業法37条1項）。", "caution": ""}], "summary": {"head": ["37条書面の交付先（宅建業法37条1項）", "交付対象"], "rows": [["売買", "売主・買主の双方"], ["賃貸借", "賃貸人・賃借人の双方"], ["交換", "双方の当事者"], ["宅建業者間", "宅建業者間でも交付義務あり"]]}}},
  {id:10088,unit:'l_hosho',level:1,field:'law',text:'保証協会の社員となった宅建業者の営業保証金供託義務の扱いとして正しいものはどれか。',opts:['引き続き営業保証金を供託しなければならない','営業保証金の供託義務が免除される','営業保証金を半額にして供託する必要がある','保証協会から指示がある場合のみ免除される'],ans:1,exp:`保証協会の社員となった宅建業者は営業保証金の供託義務が免除されます（宅建業法64条の13）。代わりに弁済業務保証金分担金を保証協会に納付します。`,"kaisetsu":{"topic": "営業保証金・保証協会：主1,000万・従500万/営業保証金vs分担金60万・30万", "basis": {"text": "営業保証金は主1,000万・従500万（宅建業法25条）。保証協会の分担金は主60万・従30万（同法64条の9）。還付対象は業者以外の取引した者。加入は任意。不足補充は通知後2週間以内。", "example": ""}, "reason": {"text": "宅地建物取引業保証協会（保証協会）に加入した宅建業者（社員）は、営業保証金の供託義務が免除されます（宅建業法64条の15）。代わりに弁済業務保証金分担金を保証協会に納付します（主たる事務所60万円・従たる事務所1か所あたり30万円・宅建業法64条の9）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">営業保証金と弁済業務保証金</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">営業保証金</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">弁済業務保証金（分担金）</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">主たる事務所</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000万円</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">60万円</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従たる事務所/所</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">500万円</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">還付対象</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者以外</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者以外</text></svg>", "choices": [{"label": "引き続き営業保証金を供託しなければならない", "reason": "保証協会の社員は営業保証金の供託義務が免除されます（宅建業法64条の15）。両方は不要です。", "caution": "保証協会加入→営業保証金供託義務免除（宅建業法64条の15）。"}, {"label": "営業保証金を半額にして供託する必要がある", "reason": "保証協会の社員は営業保証金の供託義務が全額免除されます（宅建業法64条の15）。半額でも不要です。", "caution": ""}, {"label": "保証協会から指示がある場合のみ免除される", "reason": "保証協会に加入（社員となった）時点で当然に免除されます（宅建業法64条の15）。指示は不要です。", "caution": ""}], "summary": {"head": ["営業保証金vs弁済業務保証金分担金", "内容"], "rows": [["営業保証金", "主たる事務所1000万円＋従たる事務所500万円×数"], ["弁済業務保証金分担金", "主たる事務所60万円＋従たる事務所30万円×数"], ["保証協会加入", "営業保証金の供託義務が免除される"], ["還付上限", "営業保証金に相当する額が上限"]]}}},
  {id:10089,unit:'l_kantoku',level:1,field:'law',text:'宅建業者に対する業務停止処分の最長期間として正しいものはどれか。',opts:['3ヶ月','6ヶ月','1年','2年'],ans:2,exp:`宅建業者の業務停止処分の期間は最長1年です（宅建業法65条2項）。業務停止中は宅建業に係る業務を行うことができません。`,"kaisetsu":{"topic": "監督処分：業務停止最長1年・大臣は全業者に指示可・指示違反→業務停止", "basis": {"text": "業務停止の最長期間は1年（宅建業法65条2項）。大臣は全業者（知事免許含む）に指示処分を行う権限があります。指示処分違反→業務停止、業務停止違反→免許取消という段階があります。", "example": ""}, "reason": {"text": "宅建業者に対する業務停止処分の最長期間は1年です（宅建業法65条2項）。1年を超える業務停止は認められません。宅建士に対する事務禁止処分（最長1年）と同じ期間です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">監督処分のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">処分</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">最長1年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣の権限</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全業者に指示可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">指示処分違反</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止の対象</text></svg>", "choices": [{"label": "3ヶ月", "reason": "業務停止処分の最長期間は1年です（宅建業法65条2項）。3か月ではありません。", "caution": "業務停止処分の最長期間：1年（宅建業法65条2項）。"}, {"label": "6ヶ月", "reason": "業務停止処分の最長期間は1年です（宅建業法65条2項）。6か月ではありません。", "caution": ""}, {"label": "2年", "reason": "業務停止処分の最長期間は1年です（宅建業法65条2項）。2年ではありません。", "caution": ""}], "summary": {"head": ["宅建業者の業務停止処分（宅建業法65条2項）", "内容"], "rows": [["最長期間", "1年"], ["違反の場合", "業務停止処分違反→必要的免許取消（宅建業法66条1項9号）"], ["宅建士との比較", "宅建士の事務禁止処分も最長1年（宅建業法68条）"]]}}},
  {id:10090,unit:'k_kukaku',level:1,field:'limit',text:'土地区画整理事業における「換地」の意味として正しいものはどれか。',opts:['事業後に権利者へ割り当てる、従前の宅地に対応した新たな宅地','土地を買収して公共施設用地にすること','地主に金銭で補償すること','土地の地目のみを変更すること'],ans:0,exp:`換地とは土地区画整理事業において従前の宅地に代わる宅地を権利者に割り当てることです（土地区画整理法91条）。換地の位置・形状・面積は従前地と異なります。`,"kaisetsu":{"topic": "土地区画整理法：換地は公告翌日確定・仮換地は従前地使用不可・組合は2/3以上", "basis": {"text": "換地処分の公告翌日から換地が確定します（土地区画整理法104条）。仮換地の指定後は従前地を使用できなくなります（同法99条）。組合設立には土地所有者・借地権者の各2/3以上の同意が必要です。", "example": ""}, "reason": {"text": "換地とは土地区画整理事業後に権利者へ割り当てる、従前の宅地に対応した新たな宅地のことです（土地区画整理法2条4項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">土地区画整理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">換地の確定</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公告の翌日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮換地指定後</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従前地は使用不可（所有権は残る）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">組合設立</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各2/3以上の同意</text></svg>", "choices": [{"label": "土地を買収して公共施設用地にすること", "reason": "公共施設用地の確保は換地ではありません（土地区画整理法2条4項）。", "caution": "換地：従前の宅地に対応した新たな宅地（土地区画整理法2条4項）。"}, {"label": "地主に金銭で補償すること", "reason": "金銭補償は清算金の概念であり換地ではありません（土地区画整理法94条）。", "caution": ""}, {"label": "土地の地目のみを変更すること", "reason": "地目変更だけでは換地ではありません（土地区画整理法2条4項）。", "caution": ""}], "summary": {"head": ["換地の概念", "内容"], "rows": [["換地", "従前の宅地に対応して割り当てる新たな宅地"], ["清算金", "換地と従前地の価値差を金銭で調整"]]}}},
  {id:10091,unit:'r_ishi',level:1,field:'rights',text:'錯誤による意思表示の取消しが認められる要件として正しいものはどれか（民法95条）。',opts:['軽微な動機の錯誤でも取り消せる','表意者に重大な過失がある場合でも原則取り消せる','法律行為の目的及び取引上の社会通念に照らして重要な錯誤が必要','相手方が善意であれば取り消せない'],ans:2,exp:`錯誤取消しには「法律行為の目的及び取引上の社会通念に照らして重要な錯誤」が必要です（民法95条1項）。表意者に重大な過失がある場合は原則として取消しができません（同条3項）。`,"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失保護）・通謀虚偽表示（無効・善意保護）。", "example": ""}, "reason": {"text": "錯誤に重大な過失がある場合は取消しを認めると、不注意な者を過度に保護し取引の安全が損なわれます。原則として重過失ある表意者は保護されませんが、相手方が悪意・重過失の場合は例外です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "軽微な動機の錯誤でも取り消せる", "reason": "錯誤取消しは法律行為の目的および取引上の社会通念に照らして重要な錯誤に限られます（民法95条1項）。軽微な錯誤は対象外です。", "caution": ""}, {"label": "表意者に重大な過失がある場合でも原則取り消せる", "reason": "表意者に重大な過失がある場合、原則として錯誤取消しを主張できません（民法95条3項）。例外は相手方が悪意または重過失の場合等です。", "caution": "「重過失があっても取り消せる」は誤り。重過失がある場合は原則として取消し不可です。"}, {"label": "相手方が善意であれば取り消せない", "reason": "錯誤取消しは相手方の善意・悪意ではなく、表意者の過失の有無が要件です。相手方が善意でも、表意者に重過失がなければ取り消せます。", "caution": ""}], "summary": {"head": ["錯誤の種類", "要件", "取消しの可否"], "rows": [["法律行為の内容の錯誤", "重要な錯誤", "可（重過失なければ）"], ["動機の錯誤", "動機が表示・法律行為の内容とされた", "可（要件充足時）"], ["表意者に重大な過失", "—", "原則不可"], ["相手方が悪意・重過失", "—", "例外的に取消し可"]]}}},
  {id:10092,unit:'r_dairi',level:1,field:'rights',text:'代理権の濫用（民法107条）とはどのような行為か。正しいものはどれか。',opts:['代理人が本人のためでなく自己または第三者の利益のために代理権を行使した場合','代理人が代理権の範囲を超えて行為した場合','代理人が複数の相手方と同時に契約した場合','代理人が無権代理行為をした場合'],ans:0,exp:`代理権の濫用は代理人が自己または第三者の利益のために（本人のためでなく）代理権を行使した場合です。相手方がその目的を知りまたは知ることができた場合は無権代理とみなされます（民法107条）。`,"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護します。", "example": ""}, "reason": {"text": "代理権の濫用（民法107条）とは、代理人が外形上は代理権の範囲内で行動しながら、本人のためではなく自己または第三者の利益を図る目的で代理権を行使することです。相手方が悪意または有過失の場合、本人はその効果を否定できます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "代理人が代理権の範囲を超えて行為した場合", "reason": "代理権の範囲を超えた行為は「権限外行為の無権代理」または「越権表見代理（民法110条）」の問題です。代理権の濫用とは異なります。", "caution": "代理権濫用（範囲内・目的が不正）と越権行為（範囲外）を区別しましょう。"}, {"label": "代理人が複数の相手方と同時に契約した場合", "reason": "複数の相手方と同時に契約することは、代理権の濫用の定義ではありません。問題の有無は状況によります。", "caution": ""}, {"label": "代理人が無権代理行為をした場合", "reason": "無権代理は代理権がない状態での行為であり、代理権の濫用（代理権はあるが目的が不正）とは異なります。", "caution": ""}], "summary": {"head": ["類型", "内容", "効果"], "rows": [["代理権濫用（民法107条）", "代理権の範囲内・目的が不正", "相手方悪意・有過失なら本人は否定可"], ["越権行為（民法110条）", "代理権の範囲外", "表見代理が成立する場合あり"], ["無権代理（民法113条）", "代理権なし", "本人の追認がなければ無効"]]}}},
  {id:10093,unit:'l_kokoku',level:1,field:'law',text:'宅建業者が広告において必ず明示しなければならない事項はどれか。',opts:['広告費用の内訳','取引態様（売主・代理・媒介の別）','担当宅建士の氏名','広告媒体の種類'],ans:1,exp:`宅建業者は広告をする際に取引態様（売主・代理・媒介の別）を明示しなければなりません（宅建業法34条1項）。誇大広告も禁止されており（宅建業法32条）、違反は行政処分の対象です。`,"kaisetsu":{"topic": "宅建業者の広告：開発許可後に広告可・誇大広告は全媒体禁止・取引態様は広告時と注文時両方", "basis": {"text": "開発許可・建築確認後（工事中でも）広告できます（宅建業法33条）。誇大広告禁止は全媒体・全対象者に適用（同法32条）。取引態様は広告時と注文受領時の両方で明示が必要（同法34条）。", "example": ""}, "reason": {"text": "宅建業者は広告をするとき、取引態様（自ら売主・代理・媒介の別）を必ず明示しなければなりません（宅建業法34条1項）。広告費の内訳・担当宅建士の氏名・広告媒体の種類は広告の必須明示事項ではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">広告規制のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">広告開始時期</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築確認・開発許可後</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誇大広告禁止</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">媒体・対象問わず</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取引態様の明示</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">広告時と注文時の両方</text></svg>", "choices": [{"label": "広告費用の内訳", "reason": "広告費用の内訳は宅建業法上の広告の必須明示事項ではありません（宅建業法34条1項）。", "caution": "広告の必須明示事項：取引態様（宅建業法34条1項）。"}, {"label": "担当宅建士の氏名", "reason": "担当宅建士の氏名は広告の必須明示事項ではありません（宅建業法34条1項）。", "caution": ""}, {"label": "広告媒体の種類", "reason": "広告媒体の種類は広告の必須明示事項ではありません（宅建業法34条1項）。", "caution": ""}], "summary": {"head": ["広告の取引態様明示（宅建業法34条1項）", "内容"], "rows": [["明示する事項", "取引態様の別（売主・代理・媒介）"], ["明示の時期", "広告時と注文（申込み）受領時"], ["明示方法", "書面・電磁的方法・口頭等"], ["違反", "行政処分の対象"]]}}},
  {id:10094,unit:'r_saikensoron',level:1,field:'rights',text:'保証契約の効力発生要件として正しいものはどれか。',opts:['口頭の合意のみで有効','書面（または電磁的記録）によらなければ効力が生じない','公正証書によらなければならない','保証人が認印を押印した書面で足りる'],ans:1,exp:`保証契約は書面（または電磁的記録）によらなければ効力が生じません（民法446条2項）。主たる債務が無効・取消しの場合は保証も無効となります（付従性）。`,"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要（民法446条2項）。連帯保証人は催告・検索の抗弁権なし（民法454条）。債権譲渡の第三者対抗は確定日付ある証書による通知・承諾（民法467条2項）。相殺の絶対的効力：弁済・更改・相殺。", "example": ""}, "reason": {"text": "保証契約は書面または電磁的記録によらなければ効力が生じません（民法446条2項・3項）。口頭だけの保証契約は無効です。2020年改正で電磁的記録も有効とされました。これは安易な保証を防ぐための規定です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">催告・検索の抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text></svg>", "choices": [{"label": "口頭の合意のみで有効", "reason": "保証契約は書面または電磁的記録によらなければ効力が生じません（民法446条2項）。口頭のみでは無効です。", "caution": "保証契約は書面（または電磁的記録）が必要（民法446条2項）。口頭では無効。"}, {"label": "公正証書によらなければならない", "reason": "保証契約に公正証書は不要です（民法446条2項）。書面または電磁的記録で足ります。", "caution": ""}, {"label": "保証人が認印を押印した書面で足りる", "reason": "押印は保証契約の成立要件ではありません（民法446条2項）。署名がある書面であれば足ります。", "caution": ""}], "summary": {"head": ["保証契約の成立要件", "内容"], "rows": [["書面", "書面または電磁的記録が必要（民法446条2項）"], ["口頭", "無効"], ["押印", "必須ではないが実務上は押印が通常"], ["個人根保証", "極度額の定めが必要（民法465条の2）"]]}}},
  {id:10095,unit:'k_mori',level:1,field:'limit',text:'盛土規制法（宅地造成及び特定盛土等規制法）における宅地造成工事規制区域内での工事の許可権者として正しいものはどれか。',opts:['市町村長','都道府県知事（または政令市長等）','国土交通大臣','農業委員会'],ans:1,exp:`宅地造成工事規制区域内で一定規模以上の宅地造成等工事を行う場合は都道府県知事（政令市では市長等）の許可が必要です（盛土規制法12条）。`,"kaisetsu":{"topic": "盛土規制法・宅地造成：盛土は1m超・切土は2m超・特定盛土等規制区域", "basis": {"text": "盛土で高さ1mを超える崖を生じる場合は許可が必要（盛土規制法）。切土は2mを超える崖で許可が必要。特定盛土等規制区域内の一定規模以上の盛土等は許可が必要です。農地・森林も規制対象に含まれます。", "example": ""}, "reason": {"text": "盛土規制法（宅地造成及び特定盛土等規制法）の宅地造成工事規制区域内での工事の許可権者は都道府県知事（または政令市・中核市等の長）です（宅地造成及び特定盛土等規制法12条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">盛土規制法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">工事種別</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可が必要な規模</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">切土</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">高さ2mを超える崖</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">盛土</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">高さ1mを超える崖</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">面積</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">500㎡超の宅地造成</text></svg>", "choices": [{"label": "市町村長", "reason": "許可権者は都道府県知事（または指定都市等の長）です（宅地造成及び特定盛土等規制法12条1項）。", "caution": "盛土規制法の許可権者：都道府県知事（または指定都市等の長）（宅地造成及び特定盛土等規制法12条1項）。"}, {"label": "国土交通大臣", "reason": "許可権者は都道府県知事（または指定都市等の長）です（宅地造成及び特定盛土等規制法12条1項）。", "caution": ""}, {"label": "農業委員会", "reason": "農業委員会は盛土規制法とは無関係です（宅地造成及び特定盛土等規制法12条1項）。", "caution": ""}], "summary": {"head": ["宅地造成工事の許可（宅地造成及び特定盛土等規制法12条）", "内容"], "rows": [["許可権者", "都道府県知事（または指定都市等の長）"], ["申請時期", "工事着手前"]]}}},
  {id:10096,unit:'l_sonota',level:1,field:'law',text:'住宅瑕疵担保履行法において自ら売主となる宅建業者が新築住宅を売却する場合に義務付けられる資力確保措置として正しいものはどれか。',opts:['保険加入のみ義務付けられる','供託のみ義務付けられる','保険加入か供託のいずれかを選択して行う','任意の措置で義務ではない'],ans:2,exp:`自ら売主となる宅建業者は新築住宅（竣工から1年以内かつ未居住）を売却する場合、住宅瑕疵担保責任保険への加入か保証金の供託のいずれかを義務付けられます（住宅瑕疵担保履行法11条）。`,"kaisetsu":{"topic": "宅建業者のその他の業務：従業者証明書・帳簿・業務処理原則", "basis": {"text": "全従業者に従業者証明書の交付が必要で業務中は常時携帯（宅建業法48条）。帳簿は事務所ごとに5年保存（自ら売主の新築住宅は10年）（同法49条）。宅建業者は信義誠実の原則に従って業務を行う必要があります（同法31条）。", "example": ""}, "reason": {"text": "住宅瑕疵担保履行法は宅建業者が自ら売主として新築住宅を販売する場合に、①住宅瑕疵担保保証金の供託または②住宅瑕疵担保責任保険への加入のいずれかを選択して行うことを義務付けています（住宅瑕疵担保履行法11条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業者のその他の義務</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従業者証明書</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全従業者に交付・業務中携帯</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">帳簿</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所ごと・5年保存（新築自ら売主は10年）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務処理原則</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">信義誠実の原則</text></svg>", "choices": [{"label": "保険加入のみ義務付けられる", "reason": "保険加入か供託のいずれかを選択します（住宅瑕疵担保履行法11条）。保険のみが義務ではありません。", "caution": "保険加入または供託のいずれかを選択（住宅瑕疵担保履行法11条）。"}, {"label": "供託のみ義務付けられる", "reason": "保険加入か供託のいずれかを選択します（住宅瑕疵担保履行法11条）。供託のみが義務ではありません。", "caution": ""}, {"label": "任意の措置で義務ではない", "reason": "義務です（住宅瑕疵担保履行法11条）。「任意」は誤りです。", "caution": ""}], "summary": {"head": ["住宅瑕疵担保履行法の資力確保義務（住宅瑕疵担保履行法11条）", "内容"], "rows": [["対象", "宅建業者が自ら売主として新築住宅を販売"], ["方法①", "住宅瑕疵担保保証金の供託"], ["方法②", "住宅瑕疵担保責任保険への加入"], ["選択", "いずれか一方でよい"]]}}},
  {id:10097,unit:'t_inshi',level:1,field:'tax',text:'不動産売買契約書に貼付する収入印紙の金額はどのように決まるか。正しいものはどれか。',opts:['固定資産税評価額をもとに計算する','売買金額（記載金額）に応じた印紙税法の税額表による','登録免許税と同額になる','当事者が自由に決定できる'],ans:1,exp:`不動産売買契約書の印紙税額は売買金額（記載金額）に応じた印紙税法別表第一の税額表によります。例えば記載金額1,000万円超5,000万円以下の契約書は2万円（軽減税率適用時は1万円）です。`,"kaisetsu":{"topic": "印紙税：売買・賃貸借契約書は課税文書・電子契約は非課税・1万円未満は非課税", "basis": {"text": "不動産の売買契約書・賃貸借契約書は印紙税の課税文書（第1号文書）。電子契約は課税対象外（文書でないため）。1万円未満の記載金額は非課税。複数当事者が保有する各通に課税。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">印紙税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買・賃貸借契約書</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税文書（第1号）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">電子契約</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1万円未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10098,unit:'r_souzoku',level:1,field:'rights',text:'遺留分を持つ相続人として正しいものはどれか。',opts:['すべての法定相続人','配偶者・子・直系尊属のみ（兄弟姉妹を除く）','配偶者のみ','子と直系尊属のみ（配偶者を除く）'],ans:1,exp:`遺留分権利者は配偶者・子（代襲相続人を含む）・直系尊属です（民法1042条）。兄弟姉妹には遺留分がありません。`,"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2・遺産分割は全員合意", "basis": {"text": "配偶者と子は各1/2（民法900条）。放棄は3か月以内に家裁へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2（民法1042条）。兄弟姉妹に遺留分はなし。遺産分割協議は全員合意が必要。", "example": ""}, "reason": {"text": "遺留分は配偶者・子（代襲相続人含む）・直系尊属に認められます（民法1042条）。兄弟姉妹には遺留分がありません。これは兄弟姉妹は被相続人と生活基盤を共にしていないことが多く保護の必要性が低いためです。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "すべての法定相続人", "reason": "兄弟姉妹は法定相続人ですが遺留分はありません（民法1042条）。「すべての法定相続人」は誤りです。", "caution": "兄弟姉妹＝法定相続人だが遺留分なし。"}, {"label": "配偶者のみ", "reason": "配偶者だけでなく子・直系尊属にも遺留分があります（民法1042条）。", "caution": ""}, {"label": "子と直系尊属のみ（配偶者を除く）", "reason": "配偶者にも遺留分があります（民法1042条）。", "caution": ""}], "summary": {"head": ["相続人", "遺留分", "割合（全体）"], "rows": [["配偶者", "あり", "相続財産の1/2"], ["子", "あり", "相続財産の1/2"], ["直系尊属のみ", "あり", "相続財産の1/3"], ["兄弟姉妹", "なし", "—"]]}}},
  {id:10099,unit:'r_sorin',level:1,field:'rights',text:'袋地（公道に至らない土地）の所有者の他の土地の通行権（囲繞地通行権）について正しいものはどれか。',opts:['通行権は無償で行使できる','損害が最も少ない方法・場所で通行でき、償金を支払わなければならない','好きな場所を自由に通行できる','隣接地所有者の同意が必要'],ans:1,exp:`袋地の所有者は公道に至るために損害が最も少ない方法・場所で他の土地を通行でき、償金の支払いが必要です（民法211条・212条）。ただし分割によって生じた袋地の場合は償金なしで通行できます（民法213条）。`,"kaisetsu":{"topic": "相隣関係：竹木の根は自ら切除可・枝は原則所有者に・境界から50cmは慣習で変更可", "basis": {"text": "竹木の根が境界を越えたら自ら切除可（民法233条2項）。枝は原則として所有者に切除させます。建物の境界からの距離（50cm）は慣習・条例で変更可（民法234条・236条）。袋地通行権は有償が原則（民法212条）。", "example": ""}, "reason": {"text": "袋地（公道に至らない土地）の所有者は囲繞地（袋地を囲む土地）を通行できますが（民法210条1項）、損害が最も少ない方法・場所で通行し、通常は通行損害に対して償金を支払わなければなりません（民法212条）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相隣関係のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">事項</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">ルール</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">竹木の根（越境）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自ら切除可</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">竹木の枝（越境）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則：所有者に切除させる</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">境界距離（50cm）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">慣習・条例で変更可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">袋地通行権</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有償が原則</text></svg>", "choices": [{"label": "通行権は無償で行使できる", "reason": "囲繞地通行権の行使には原則として損害に対する償金が必要です（民法212条）。「無償」は誤りです。", "caution": "囲繞地通行権の行使：損害の最少の方法・場所＋原則償金（民法212条）。"}, {"label": "好きな場所を自由に通行できる", "reason": "損害が最も少ない方法・場所で通行しなければなりません（民法211条1項）。自由に選べるわけではありません。", "caution": ""}, {"label": "隣接地所有者の同意が必要", "reason": "囲繞地通行権は法律上当然に認められる権利であり（民法210条1項）、隣地所有者の同意は不要です。", "caution": ""}], "summary": {"head": ["囲繞地通行権（民法210条〜213条）", "内容"], "rows": [["根拠", "民法210条1項（法律上当然に発生）"], ["通行の方法", "損害が最も少ない方法・場所"], ["償金", "原則必要（民法212条）"], ["分割による袋地", "分割した他の土地のみ通行可・償金不要（民法213条）"]]}}},
  {id:10100,unit:'r_ishi',level:1,field:'rights',text:'心裡留保（冗談など、真意でない意思表示）の原則的な効力として正しいものはどれか。',opts:['常に無効','有効だが表意者は取り消せる','原則有効。相手方が悪意または有過失の場合のみ無効','常に有効で取り消しも無効主張も不可'],ans:2,exp:`心裡留保は原則として有効です（民法93条1項）。ただし相手方が表意者の真意でないことを知っていた（悪意）または知ることができた（有過失）場合は無効となります。`,"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失保護）・通謀虚偽表示（無効・善意保護）。", "example": ""}, "reason": {"text": "心裡留保（冗談など内心と異なる意思表示）は表示行為を信頼した相手方を保護するため原則有効とします。ただし相手方が真意を知っていた（悪意）または知れた（有過失）場合は相手方の信頼保護の必要がないため無効になります。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "常に無効", "reason": "心裡留保は原則として有効です（民法93条1項）。相手方が悪意または有過失の場合のみ無効となります。", "caution": "「常に無効」は誤り。原則有効が心裡留保の基本ルールです。"}, {"label": "有効だが表意者は取り消せる", "reason": "心裡留保は取消しではなく無効の問題です。相手方が悪意・有過失の場合は「無効」であり、「取消し」ではありません（民法93条1項）。", "caution": "心裡留保の効果は「無効」であり「取消し」ではありません。"}, {"label": "常に有効で取り消しも無効主張も不可", "reason": "相手方が悪意（真意を知っていた）または有過失（知ることができた）の場合は無効となります（民法93条1項ただし書）。", "caution": ""}], "summary": {"head": ["相手方の状態", "意思表示の効力"], "rows": [["善意かつ無過失", "有効"], ["悪意（真意を知っていた）", "無効"], ["有過失（知ることができた）", "無効"]]}}},
  {id:10101,unit:'r_dairi',level:1,field:'rights',text:'自己契約・双方代理として禁止されていないものはどれか。',opts:['代理人が本人の売主・買主双方の代理人となること','代理人が本人の相手方となって自ら売買すること','本人があらかじめ許諾した場合の自己契約','いかなる場合も全て禁止'],ans:2,exp:`自己契約・双方代理は原則禁止ですが（民法108条）、本人があらかじめ許諾した場合と、単に債務を履行する行為は禁止から除外されます。`,"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護します。", "example": ""}, "reason": {"text": "自己契約・双方代理は本人の利益を損なうおそれがあるため原則禁止です（民法108条1項）。しかし本人があらかじめ許諾した場合は本人自身が不利益リスクを承知しているため例外的に許容されます。また債務の履行（すでに確定した内容の実行）も利益相反のおそれが少ないため許容されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "代理人が本人の売主・買主双方の代理人となること", "reason": "双方代理は原則禁止です（民法108条1項）。一方の利益を優先すると他方に不利益が生じるおそれがあるためです。ただし本人があらかじめ許諾した場合は例外です。", "caution": "双方代理の原則禁止と例外（本人の許諾）を押さえましょう。"}, {"label": "代理人が本人の相手方となって自ら売買すること", "reason": "自己契約も原則禁止です（民法108条1項）。代理人が相手方になると利益が相反するためです。本人の許諾がある場合は例外です。", "caution": ""}, {"label": "いかなる場合も全て禁止", "reason": "本人があらかじめ許諾した自己契約・双方代理は例外的に有効です（民法108条1項ただし書）。また債務の履行も許容されます。「全て禁止」は誤りです。", "caution": ""}], "summary": {"head": ["行為", "原則", "例外"], "rows": [["自己契約", "禁止（民法108条1項）", "本人の許諾・債務の履行"], ["双方代理", "禁止（民法108条1項）", "本人の許諾・債務の履行"], ["代理権濫用", "有効だが相手方悪意なら否定可", "民法107条"]]}}},
  {id:10102,unit:'r_jiko',level:1,field:'rights',text:'消滅時効の援用権者として正しいものはどれか。',opts:['時効の利益を受ける当事者本人のみ','債権者のみ','時効完成により直接利益を受ける者（保証人・物上保証人等を含む）','裁判所が職権で援用できる'],ans:2,exp:`消滅時効は援用しなければ裁判上で効力を主張できません（民法145条）。援用できるのは時効の完成により直接利益を受ける当事者で、主債務者だけでなく保証人・物上保証人・担保不動産の第三取得者なども含まれます。`,"kaisetsu":{"topic": "消滅時効：知った時から5年または行使可能時から10年", "basis": {"text": "消滅時効は「知った時から5年」または「行使可能時から10年」のいずれか早い方で完成します（民法166条）。時効は援用して初めて効力が発生します（民法145条）。承認は更新事由です（民法152条）。", "example": ""}, "reason": {"text": "消滅時効の援用は「時効によって直接利益を受ける者」が行えます（民法145条・判例）。保証人は主債務が時効消滅すれば保証債務も消滅するため直接利益を受けます。また物上保証人・第三取得者も同様です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">期間</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人身損害</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年または20年</text></svg>", "choices": [{"label": "時効の利益を受ける当事者本人のみ", "reason": "当事者本人以外にも、時効完成により直接利益を受ける者（保証人・物上保証人・第三取得者等）が援用できます（民法145条・判例）。", "caution": ""}, {"label": "債権者のみ", "reason": "消滅時効の援用権者は債権者ではなく、時効の完成により直接利益を受ける者（債務者・保証人等）です。", "caution": ""}, {"label": "裁判所が職権で援用できる", "reason": "裁判所は時効を職権で援用する権限はありません（民法145条）。当事者の援用が必要です。", "caution": ""}], "summary": {"head": ["時効の援用権者（判例）", "理由"], "rows": [["主たる債務者", "当然に援用可"], ["保証人", "主債務消滅→保証債務も消滅する直接利益あり"], ["物上保証人", "被担保債権消滅→担保物の負担が消える直接利益あり"], ["第三取得者", "被担保債権消滅→担保物の負担が消える直接利益あり"], ["後順位抵当権者", "先順位消滅→順位が昇進する直接利益あり"]]}}},
  {id:10103,unit:'r_bukken',level:1,field:'rights',text:'物権的請求権のうち、不法占拠者に対して占有の排除を求める権利はどれか。',opts:['物権的返還請求権','物権的妨害排除請求権','物権的妨害予防請求権','損害賠償請求権'],ans:1,exp:`物権的妨害排除請求権は、物権が継続的に侵害されている状態（不法占拠など）に対して、その侵害状態の除去を求める権利です。物権的返還請求権は占有自体を奪われた場合に返還を求めるものです。`,"kaisetsu":{"topic": "物権変動：登記が対抗要件・不法占拠者には登記不要", "basis": {"text": "不動産の物権変動は登記が第三者への対抗要件です（民法177条）。不法占拠者には登記なく対抗できます（判例）。建物賃借権は引渡しが対抗要件です（借地借家法31条）。", "example": ""}, "reason": {"text": "物権が侵害された場合、物権者は侵害の態様に応じて3種類の物権的請求権を行使できます。返還・妨害排除・妨害予防の3種を場面ごとに使い分けることが重要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">物権変動の対抗要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対抗要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">二重譲渡</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先に登記した者が優先</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不法占拠者</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記不要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物賃借権</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡し</text></svg>", "choices": [{"label": "物権的返還請求権", "reason": "物権的返還請求権は不法に占有を奪われた場合に「物の返還」を求める権利です。「占有の排除」とは異なり、占有そのものを取り戻すための請求権です。", "caution": "返還請求権＝物を返せ／妨害排除請求権＝邪魔をやめろ。"}, {"label": "物権的妨害予防請求権", "reason": "物権的妨害予防請求権は将来の妨害のおそれがある場合に予防措置を求める権利です。現在進行中の不法占拠には妨害排除請求権を使います。", "caution": ""}, {"label": "損害賠償請求権", "reason": "損害賠償請求権は不法行為に基づく債権的な請求権（民法709条）です。物権的請求権とは別の権利で、両方を同時に行使することも可能です。", "caution": ""}], "summary": {"head": ["物権的請求権", "内容", "典型場面"], "rows": [["返還請求権", "物の返還を請求", "不法占拠・奪取"], ["妨害排除請求権", "妨害の除去を請求", "占有以外の現在の妨害"], ["妨害予防請求権", "妨害のおそれの除去を請求", "将来の侵害のおそれ"]]}}},
  {id:10104,unit:'r_touki',level:1,field:'rights',text:'不動産の物権変動を第三者に対抗するために必要なものはどれか。',opts:['売買契約書','引渡し','登記','当事者間の合意'],ans:2,exp:`不動産の物権変動は登記がなければ第三者に対抗できません（民法177条）。売買契約書や引渡し・合意だけでは第三者への対抗要件を満たしません。`,"kaisetsu":{"topic": "不動産登記：権利登記は共同申請・仮登記は順位保全・建物滅失は1か月以内", "basis": {"text": "権利に関する登記は原則として登記権利者と登記義務者が共同申請します（不動産登記法60条）。仮登記は順位保全機能があるが完全な対抗力は本登記後です。建物滅失登記の申請義務は1か月以内（同法57条）。", "example": ""}, "reason": {"text": "不動産物権変動の対抗要件は登記です（民法177条）。当事者間では登記なしに物権変動が生じますが、第三者に対抗するには登記が必要です。これにより誰でも登記簿を確認すれば権利関係がわかる公示制度が実現されています。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産登記のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利登記</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則として共同申請</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮登記</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">順位保全（対抗力は本登記後）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物滅失登記</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1か月以内</text></svg>", "choices": [{"label": "売買契約書", "reason": "売買契約書は当事者間の契約を証明しますが、第三者への対抗要件ではありません。対抗要件は登記です（民法177条）。", "caution": ""}, {"label": "引渡し", "reason": "引渡しは動産物権変動の対抗要件（民法178条）です。不動産には引渡しではなく登記が必要です。", "caution": "不動産＝登記、動産＝引渡し。"}, {"label": "当事者間の合意", "reason": "当事者間の合意（契約）は当事者を拘束しますが、第三者への対抗には登記が必要です（民法177条）。", "caution": ""}], "summary": {"head": ["目的物", "対抗要件", "根拠"], "rows": [["不動産", "登記", "民法177条"], ["動産", "引渡し", "民法178条"], ["建物賃借権", "建物の引渡し", "借地借家法31条"], ["借地権（建物所有）", "建物の登記", "借地借家法10条"]]}}},
  {id:10105,unit:'r_chinshaku',level:1,field:'rights',text:'民法上の賃貸借の存続期間の上限として正しいものはどれか。',opts:['20年','30年','50年','制限なし'],ans:2,exp:`民法上の賃貸借の存続期間は最長50年です（民法604条、2020年改正）。従前は20年でしたが改正により50年に延長されました。なお借地借家法が適用される場合は同法の規定が優先します。`,"kaisetsu":{"topic": "賃貸借：通常損耗は原状回復に含まれない・有益費は終了時に請求・賃料増額は正当事由が必要", "basis": {"text": "賃貸借終了時の原状回復義務に通常使用による損耗（壁の日焼け等）は含まれません（民法621条）。必要費は直ちに、有益費は終了時の請求が原則。更新拒絶には正当事由が必要（借地借家法28条）。", "example": ""}, "reason": {"text": "2020年民法改正により賃貸借の存続期間の上限は50年となりました（民法604条1項）。改正前は20年が上限でしたが、長期の事業用賃貸借等のニーズに対応するため50年に延長されました。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">賃貸借のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通常損耗</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原状回復に含まれない</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要費</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直ちに請求可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有益費</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸借終了時に請求</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">更新拒絶</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当事由が必要</text></svg>", "choices": [{"label": "20年", "reason": "改正前は20年が上限でしたが、2020年改正後は50年が上限です（民法604条1項）。", "caution": "2020年改正：賃貸借の存続期間の上限が20年→50年に変更されました。"}, {"label": "30年", "reason": "30年は借地権の最低存続期間（借地借家法3条）です。賃貸借の存続期間の上限は50年です（民法604条1項）。", "caution": ""}, {"label": "制限なし", "reason": "賃貸借の存続期間には50年の上限があります（民法604条1項）。上限を超える期間を定めた場合は50年に短縮されます（同条2項）。", "caution": ""}], "summary": {"head": ["賃貸借の存続期間", "内容"], "rows": [["上限", "50年（民法604条1項）"], ["上限超の定め", "50年に短縮（民法604条2項）"], ["借地権の最低存続期間", "30年（借地借家法3条）"], ["改正前の上限", "20年（2020年改正で50年に延長）"]]}}},
  {id:10106,unit:'r_baibai',level:1,field:'rights',text:'売買契約における手付の性質として、当事者間で特に定めがない場合の推定として正しいものはどれか。',opts:['証約手付','解約手付','違約手付','損害賠償額の予定'],ans:1,exp:`手付は特段の合意がない場合、解約手付と推定されます（民法557条）。買主は手付を放棄し、売主は手付の倍額を返還することで契約を解除できます（相手方が履行に着手するまで）。`,"kaisetsu":{"topic": "売買：同時履行の抗弁権・解除は原則催告が必要・契約不適合責任", "basis": {"text": "売買では代金と引渡しは同時履行の関係（民法533条）。解除は原則として相当の期間を定めた催告後に行います（民法541条）。契約不適合責任の通知は知った時から1年以内（民法566条）。", "example": ""}, "reason": {"text": "手付の性質について当事者間で特に定めがない場合、解約手付と推定されます（民法557条1項）。解約手付とは買主は手付放棄、売主は手付倍返しで解除できる機能を持つ手付です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">売買のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">同時履行</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金と引渡しは同時履行</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則として催告が必要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">契約不適合の通知</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から1年以内</text></svg>", "choices": [{"label": "証約手付", "reason": "証約手付とは契約成立の証拠として交付される手付ですが、特に定めがない場合の推定は解約手付です（民法557条1項）。", "caution": ""}, {"label": "違約手付", "reason": "違約手付は違約した場合に没収・倍返しとなる手付ですが、特に定めがない場合の推定は解約手付です（民法557条1項）。", "caution": ""}, {"label": "損害賠償額の予定", "reason": "損害賠償額の予定は別途合意が必要です（民法420条）。手付は特別の定めがなければ解約手付と推定されます（民法557条1項）。", "caution": ""}], "summary": {"head": ["手付の種類", "内容"], "rows": [["証約手付", "契約成立の証拠"], ["解約手付（推定）", "買主：放棄、売主：倍返しで解除可（民法557条）"], ["違約手付", "違約の場合に没収・倍返し"], ["定めがない場合", "解約手付と推定（民法557条1項）"]]}}},
  {id:10107,unit:'r_souzoku',level:1,field:'rights',text:'配偶者と子が1人いる場合の法定相続分として正しいものはどれか。',opts:['配偶者1/2・子1/2','配偶者2/3・子1/3','配偶者3/4・子1/4','配偶者と子が均等'],ans:0,exp:`配偶者と子が相続人の場合、配偶者が1/2・子が1/2です（民法900条）。子が複数いる場合はその1/2を均等に分けます。`,"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2・遺産分割は全員合意", "basis": {"text": "配偶者と子は各1/2（民法900条）。放棄は3か月以内に家裁へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2（民法1042条）。兄弟姉妹に遺留分はなし。遺産分割協議は全員合意が必要。", "example": ""}, "reason": {"text": "配偶者と子1人が相続人の場合、配偶者1/2・子1/2が法定相続分です（民法900条1号）。子が複数の場合は子の1/2を均等分割します。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "配偶者2/3・子1/3", "reason": "配偶者と直系尊属が相続人の場合の割合です（民法900条2号）。子がいる場合は配偶者1/2です。", "caution": ""}, {"label": "配偶者3/4・子1/4", "reason": "配偶者と兄弟姉妹が相続人の場合の割合です（民法900条4号）。", "caution": ""}, {"label": "配偶者と子が均等", "reason": "配偶者と子が均等（1/2ずつ）というのは結果的に子1人なら同じですが、複数の子がいる場合は配偶者1/2・子全体1/2を均等分割するため「均等」とは言えません。", "caution": ""}], "summary": {"head": ["子の人数", "配偶者", "子"], "rows": [["子1人", "1/2", "1/2"], ["子2人", "1/2", "各1/4"], ["子3人", "1/2", "各1/6"]]}}},
  {id:10108,unit:'r_fuhoko',level:1,field:'rights',text:'使用者責任が成立する要件として正しいものはどれか。',opts:['被用者が故意による不法行為を行うこと','被用者が事業の執行中に第三者に損害を加えること','使用者が直接加害行為を行うこと','被用者と使用者の間に親族関係があること'],ans:1,exp:`使用者責任（民法715条）は、被用者が使用者の事業の執行について第三者に損害を与えた場合に成立します。使用者は選任・監督に相当の注意をしたことを証明すれば免責されますが、実務上免責は認められにくい傾向があります。`,"kaisetsu":{"topic": "不法行為：故意または過失が必要・使用者責任・工作物責任", "basis": {"text": "不法行為は故意または過失が必要です（民法709条）。使用者は被用者の職務上の不法行為について責任を負います（民法715条）。工作物の所有者は無過失責任（占有者が免責された場合）（民法717条）。", "example": ""}, "reason": {"text": "使用者責任（民法715条1項）は被用者が「事業の執行につき」第三者に損害を与えた場合に使用者が負う責任です。故意・過失を問わず成立します。使用者は選任・監督に相当の注意をしたことを証明すれば免責されます（同条1項ただし書）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不法行為のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般不法行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">故意または過失が必要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">使用者責任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">被用者への求償可（信義則上制限）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">工作物の所有者責任</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無過失責任（占有者が免責された場合）</text></svg>", "choices": [{"label": "被用者が故意による不法行為を行うこと", "reason": "故意だけでなく過失による不法行為でも使用者責任は成立します（民法715条1項）。故意のみに限定されません。", "caution": ""}, {"label": "使用者が直接加害行為を行うこと", "reason": "使用者責任は被用者の行為について使用者が責任を負う制度です（民法715条1項）。使用者自身の直接加害は不要です。", "caution": ""}, {"label": "被用者と使用者の間に親族関係があること", "reason": "親族関係は使用者責任の要件ではありません（民法715条1項）。雇用等の使用関係があれば足ります。", "caution": ""}], "summary": {"head": ["使用者責任の要件（民法715条）", "内容"], "rows": [["①使用関係", "雇用等の使用関係（実質的な指揮命令関係）"], ["②事業の執行につき", "客観的外形から事業の執行と判断できること"], ["③不法行為の成立", "被用者の行為が不法行為の要件を満たすこと"], ["免責", "使用者が選任・監督に相当の注意をしたことを証明（実務上ほぼ認められない）"]]}}},
  {id:10109,unit:'r_tanpo',level:1,field:'rights',text:'抵当権の効力が及ぶ範囲として原則正しいものはどれか。',opts:['抵当地上の建物にも当然に及ぶ','抵当不動産の付加一体物（増築部分等）に及ぶ','抵当不動産の果実（賃料等）には一切及ばない','動産には及ばない'],ans:1,exp:`抵当権は抵当不動産の付加一体物（増築部分・庭木等）に効力が及びます（民法370条）。ただし抵当地上の建物は別個の不動産として抵当権の効力は原則及びません。賃料等の果実については被担保債権の不履行後は差押えを経て効力が及びます。`,"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権（民法369条）。質権は占有の移転が必要。先取特権は法定担保物権（当然に成立）。農地への抵当権設定自体は、通常、農地法3条の許可対象ではありません。", "example": ""}, "reason": {"text": "抵当権の効力は抵当不動産の付加一体物に及びます（民法370条）。増築部分・庭石等の従物は付加一体物として抵当権の効力が及びます。果実（賃料等）には原則として差押え前は抵当権の効力が及びませんが、差押え後は法定果実に及びます（民法371条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "抵当地上の建物にも当然に及ぶ", "reason": "土地の抵当権は原則として建物には及びません（民法370条但書）。土地と建物は別個の不動産です。一括競売（民法389条）で競売はできますが、建物代金からの優先弁済は受けられません。", "caution": "土地と建物は別個の不動産。土地の抵当権は建物に及ばない（原則）。"}, {"label": "抵当不動産の果実（賃料等）には一切及ばない", "reason": "差押え後は法定果実（賃料等）に抵当権の効力が及びます（民法371条）。「一切及ばない」は誤りです。", "caution": "差押え前：果実に及ばない。差押え後：法定果実に及ぶ（民法371条）。"}, {"label": "動産には及ばない", "reason": "抵当不動産に付属する動産（例：建物備え付けの昇降機等）は付加一体物として抵当権の効力が及ぶ場合があります（民法370条）。", "caution": ""}], "summary": {"head": ["抵当権の効力の範囲", "内容"], "rows": [["付加一体物", "及ぶ（増築部分・庭石・従物等・民法370条）"], ["土地上の建物", "及ばない（原則・民法370条但書）"], ["果実（差押え前）", "及ばない"], ["果実（差押え後）", "法定果実（賃料等）に及ぶ（民法371条）"]]}}},
  {id:10110,unit:'l_menkyo',level:1,field:'law',text:'宅地建物取引業を営むために必要な免許として正しいものはどれか。',opts:['1つの都道府県内のみで営業する場合は市長の許可','複数の都道府県にまたがる場合は国土交通大臣の免許','すべての場合で国土交通大臣の免許','免許は不要で届出のみでよい'],ans:1,exp:`宅地建物取引業を営む場合、1つの都道府県内にのみ事務所を設ける場合は都道府県知事免許、2以上の都道府県に事務所を設ける場合は国土交通大臣免許が必要です（宅建業法3条）。`,"kaisetsu":{"topic": "宅建業免許：知事・大臣免許の区別・有効期間5年・欠格事由は5年", "basis": {"text": "1都道府県→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間。2020年改正で成年被後見人の欠格条項は廃止。", "example": ""}, "reason": {"text": "2以上の都道府県に事務所を設置する場合は国土交通大臣の免許、1つの都道府県内のみに事務所を設置する場合は都道府県知事の免許が必要です（宅建業法3条1項）。市長の許可や届出のみという制度はありません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（2020年改正で成年被後見人は廃止）</text></svg>", "choices": [{"label": "1つの都道府県内のみで営業する場合は市長の許可", "reason": "1都道府県内のみの場合は都道府県知事の免許です（宅建業法3条1項）。市長の許可という制度はありません。", "caution": "1都道府県のみ＝知事免許。2都道府県以上＝大臣免許（宅建業法3条1項）。"}, {"label": "すべての場合で国土交通大臣の免許", "reason": "1都道府県内のみであれば知事免許で足ります（宅建業法3条1項）。大臣免許は2以上の都道府県にまたがる場合のみです。", "caution": ""}, {"label": "免許は不要で届出のみでよい", "reason": "宅建業を営むには免許が必要です（宅建業法3条1項）。届出のみという制度はありません。", "caution": ""}], "summary": {"head": ["免許の種類（宅建業法3条1項）", "条件"], "rows": [["都道府県知事免許", "1つの都道府県内のみに事務所"], ["国土交通大臣免許", "2以上の都道府県に事務所"], ["免許換え", "事務所が増えて大臣免許が必要になった場合等に必要"]]}}},
  {id:10111,unit:'l_takkenshi',level:1,field:'law',text:'宅地建物取引士の登録を受けることができる者として正しいものはどれか。',opts:['宅建試験合格者であれば誰でも即日登録できる','試験合格後、宅建業に2年以上従事した実務経験者','未成年者は登録不可','業務禁止処分中の者も登録できる'],ans:1,exp:`宅建士の登録には試験合格後に2年以上の実務経験（または国土交通大臣が指定する登録実務講習の修了）が必要です（宅建業法18条）。未成年者でも法定代理人の同意があれば登録できます。`,"kaisetsu":{"topic": "専任宅建士：5人に1人以上・兼任不可・2週間以内に補充", "basis": {"text": "事務所には業務従事者5人に1人以上の専任宅建士が必要（宅建業法31条の3）。1社専属で複数業者の兼任は不可。不足時は2週間以内に補充が必要。案内所（申込み受付）にも専任宅建士が必要。", "example": ""}, "reason": {"text": "宅建士の登録には宅建試験合格後に2年以上の宅建業実務経験が必要です（宅建業法18条1項）。実務経験2年未満の場合は登録実務講習（宅建業法18条1項ただし書）を修了することで登録できます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">専任宅建士のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">設置基準</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5人に1人以上</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">兼任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可（1社専属）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不足補充</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間以内</text></svg>", "choices": [{"label": "宅建試験合格者であれば誰でも即日登録できる", "reason": "試験合格だけでは登録できません。2年以上の実務経験または登録実務講習の修了が必要です（宅建業法18条1項）。", "caution": "宅建士登録：合格＋2年の実務経験（または登録実務講習修了）（宅建業法18条1項）。"}, {"label": "未成年者は登録不可", "reason": "宅建業法の欠格事由に未成年者という規定は2021年改正後にはありません（宅建業法18条1項参照）。未成年者でも欠格事由に該当しなければ登録可能です。", "caution": ""}, {"label": "業務禁止処分中の者も登録できる", "reason": "業務禁止（事務禁止）処分中の者は欠格事由に該当し、処分期間中は登録できません（宅建業法18条1項6号）。", "caution": ""}], "summary": {"head": ["宅建士登録の要件（宅建業法18条）", "内容"], "rows": [["試験合格", "宅建試験への合格"], ["実務経験", "2年以上の宅建業実務経験（または登録実務講習修了）"], ["欠格事由", "拘禁刑以上の刑の執行中等は登録不可"], ["登録先", "都道府県知事（都道府県単位）"]]}}},
  {id:10112,unit:'l_baikai',level:1,field:'law',text:'媒介契約の種類として誤っているものはどれか。',opts:['一般媒介契約','専任媒介契約','専属専任媒介契約','優先媒介契約'],ans:3,exp:`媒介契約の種類は一般媒介契約・専任媒介契約・専属専任媒介契約の3種類です（宅建業法34条の2）。「優先媒介契約」という種類はありません。`,"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任の有効期間は最長3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。レインズ登録は専任7日以内・専属専任5日以内。業務報告は専任2週間に1回・専属専任1週間に1回。", "example": ""}, "reason": {"text": "宅建業法上の媒介契約は①一般媒介契約、②専任媒介契約、③専属専任媒介契約の3種類です（宅建業法34条の2）。「優先媒介契約」という種類は存在しません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">自己発見</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">レインズ</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専任</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専属専任</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text></svg>", "choices": [{"label": "一般媒介契約", "reason": "一般媒介契約は3種類の正しい媒介契約の一つです（宅建業法34条の2第1項3号）。誤りではありません。", "caution": ""}, {"label": "専任媒介契約", "reason": "専任媒介契約は3種類の正しい媒介契約の一つです（宅建業法34条の2第1項4号）。誤りではありません。", "caution": ""}, {"label": "専属専任媒介契約", "reason": "専属専任媒介契約は3種類の正しい媒介契約の一つです（宅建業法34条の2第3項）。誤りではありません。", "caution": ""}], "summary": {"head": ["媒介契約の3種類（宅建業法34条の2）", "特徴"], "rows": [["一般媒介", "複数業者・自己発見可・レインズ登録不要"], ["専任媒介", "1社・自己発見可・7日以内レインズ登録"], ["専属専任媒介", "1社・自己発見不可・5日以内レインズ登録"]]}}},
  {id:10113,unit:'l_hoshu',level:1,field:'law',text:'売買の媒介における宅建業者の報酬限度額の基準となる金額はどれか。',opts:['売買代金の3%＋6万円の合計（税別）','売買代金の5%（税別）','売買代金の200万円以下部分は5%、200万超400万以下は4%、400万超は3%（税別）で算出した合計額','売主・買主それぞれから売買代金の3%＋6万円'],ans:2,exp:`売買媒介報酬の上限は、200万円以下の部分は5%、200万円超400万円以下の部分は4%、400万円超の部分は3%を乗じた額の合計です（報酬告示）。400万円超の場合は売買代金×3%＋6万円（税別）という速算式が使えます。`,"kaisetsu":{"topic": "報酬：売買は代金×3%+6万（400万超）・賃貸は借賃1か月・上限超過は不可", "basis": {"text": "売買（400万超）の一方からの上限は代金×3%+6万。双方合計は一方上限×2。賃貸（居住用・非居住用とも）は借賃1か月分。低廉な空家等（800万円以下）は、媒介報酬について原則の報酬額を超えて30万円（税別）まで受領できる場合があります（依頼者への説明・合意が必要）。", "example": ""}, "reason": {"text": "売買媒介の報酬限度額は代金を3段階に分けて計算します（告示）。200万円以下の部分は5%、200万超400万以下の部分は4%、400万超の部分は3%（税別）の合計額が上限です。400万超の場合は速算式「代金×3%＋6万円」でも同じ結果になります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対象</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（400万超）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万（一方）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（200万以下）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸（双方合計）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借賃1か月分</text></svg>", "choices": [{"label": "売買代金の3%＋6万円の合計（税別）", "reason": "3%＋6万円は400万円超の場合の速算式ですが（告示）、200万円以下・200万超400万以下の場合は段階的な計算が必要です。「全体に3%＋6万円」は誤りです。", "caution": "400万円超は速算式3%＋6万円。400万円以下は段階計算が必要。"}, {"label": "売買代金の5%（税別）", "reason": "5%は200万円以下の部分に適用される率です（告示）。400万円超の物件全体に5%を掛けるのは誤りです。", "caution": ""}, {"label": "売主・買主それぞれから売買代金の3%＋6万円", "reason": "一方の依頼者からの上限が代金×3%＋6万円（400万超の速算式）であり、双方合計では最大2倍になります。「それぞれから」は上限計算の方法として誤りではありませんが、選択肢3が正確な計算方法の説明です。", "caution": ""}], "summary": {"head": ["売買媒介の報酬限度額（告示）", "計算方法"], "rows": [["200万円以下の部分", "×5%"], ["200万超400万以下の部分", "×4%"], ["400万超の部分", "×3%"], ["速算式（400万超）", "代金×3%＋6万円（税別）"]]}}},
  {id:10114,unit:'l_37jo',level:1,field:'law',text:'37条書面（契約書面）に必ず記載しなければならない事項はどれか。',opts:['ローンのあっせんに関する事項','移転登記の申請時期','瑕疵担保責任の内容','天災その他不可抗力による損害の負担に関する定め'],ans:1,exp:`37条書面の必要的記載事項には移転登記の申請時期（宅建業法37条1項5号）が含まれます。ローンあっせん・瑕疵担保・天災損害負担は定めがある場合の任意的記載事項です。`,"kaisetsu":{"topic": "37条書面：全取引で交付・記名（押印不要）・移転登記申請時期は必要的記載事項", "basis": {"text": "37条書面は全取引で契約の双方当事者に交付が義務（宅建業法37条）。引渡し時期・移転登記申請時期は必要的記載事項。2021年改正で押印は不要、記名のみで足ります。", "example": ""}, "reason": {"text": "移転登記の申請時期は37条書面の必要的記載事項（必ず記載）です（宅建業法37条1項5号）。融資あっせん・瑕疵担保責任の内容・天災不可抗力による損害負担は、定めがある場合のみ記載する任意的記載事項です（同条1項8号〜11号）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付義務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全取引・双方当事者</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡時期・移転登記申請時期等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要）</text></svg>", "choices": [{"label": "ローンのあっせんに関する事項", "reason": "融資のあっせんは定めがある場合に記載する任意的記載事項です（宅建業法37条1項8号）。必要的記載事項ではありません。", "caution": "移転登記申請時期：必要的記載事項。融資あっせん・瑕疵担保等：任意的記載事項。"}, {"label": "瑕疵担保責任の内容", "reason": "瑕疵担保責任（契約不適合責任）の内容は定めがある場合の任意的記載事項です（宅建業法37条1項11号）。", "caution": ""}, {"label": "天災その他不可抗力による損害の負担に関する定め", "reason": "天災等による損害負担は定めがある場合の任意的記載事項です（宅建業法37条1項10号）。", "caution": ""}], "summary": {"head": ["37条書面の必要的記載事項（宅建業法37条1項）", "内容"], "rows": [["当事者の氏名・住所", "1号"], ["物件の特定", "1号"], ["代金・支払時期・方法", "2号"], ["引渡し時期", "4号"], ["移転登記申請時期", "5号"]]}}},
  {id:10115,unit:'l_jusetsu',level:1,field:'law',text:'重要事項の説明を行うことができる者として正しいものはどれか。',opts:['宅建業者の代表者であれば誰でも','宅地建物取引士証を提示した宅建士','仲介業者の事務員','行政書士'],ans:1,exp:`重要事項の説明は、宅地建物取引士が取引士証を提示して行わなければなりません（宅建業法35条）。宅建士資格がない者は説明できません。`,"kaisetsu":{"topic": "重要事項説明：宅建士が説明・買主への交付・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主（貸主）は不要。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能。", "example": ""}, "reason": {"text": "重要事項説明（宅建業法35条）は宅地建物取引士が行わなければなりません（同条1項）。説明の際は宅建士証を提示しなければなりません（同条4項）。宅建業者の代表者や事務員でも宅建士でなければ説明できません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士のみ（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "宅建業者の代表者であれば誰でも", "reason": "代表者であっても宅建士でなければ重要事項説明はできません（宅建業法35条1項）。", "caution": "重要事項説明：宅建士証を提示した宅建士のみが行える（宅建業法35条1項・4項）。"}, {"label": "仲介業者の事務員", "reason": "事務員が宅建士でなければ重要事項説明はできません（宅建業法35条1項）。", "caution": ""}, {"label": "行政書士", "reason": "行政書士は宅建業法上の宅建士ではなく、重要事項説明を行う権限はありません（宅建業法35条1項）。", "caution": ""}], "summary": {"head": ["重要事項説明の実施者（宅建業法35条）", "内容"], "rows": [["実施者", "宅建士のみ"], ["宅建士証の提示", "説明の際に必須（同条4項）"], ["宅建業者間取引", "説明は省略可・書面交付は必要（同条6項）"], ["名義貸し", "禁止（宅建業法68条）"]]}}},
  {id:10116,unit:'l_hosho',level:1,field:'law',text:'宅建業者が自ら売主として未完成物件を売却する場合、手付金等の保全措置が必要となる基準額として正しいものはどれか。',opts:['受領した手付金等が代金の5%超または1000万円超','受領した手付金等が代金の10%超または1000万円超','受領した手付金等が代金の20%超または1000万円超','受領した手付金等が50万円超'],ans:0,exp:`未完成物件の場合、受領した手付金等が代金の5%超または1000万円を超える場合に保全措置が必要です（宅建業法41条）。完成物件は10%超または1000万円超が基準です。`,"kaisetsu":{"topic": "営業保証金・保証協会：主1,000万・従500万/営業保証金vs分担金60万・30万", "basis": {"text": "営業保証金は主1,000万・従500万（宅建業法25条）。保証協会の分担金は主60万・従30万（同法64条の9）。還付対象は業者以外の取引した者。加入は任意。不足補充は通知後2週間以内。", "example": ""}, "reason": {"text": "宅建業者が自ら売主として未完成物件の手付金等を受領する場合、代金の5%超または1000万円超の場合は保全措置が必要です（宅建業法41条1項）。完成物件は10%超または1000万円超が基準です（同法41条の2第1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">営業保証金と弁済業務保証金</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">営業保証金</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">弁済業務保証金（分担金）</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">主たる事務所</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000万円</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">60万円</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従たる事務所/所</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">500万円</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">還付対象</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者以外</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者以外</text></svg>", "choices": [{"label": "受領した手付金等が代金の10%超または1000万円超", "reason": "10%超は完成物件の基準です（宅建業法41条の2第1項）。未完成物件は5%超が基準です（同法41条1項）。", "caution": "未完成物件：5%超または1000万円超→保全措置必要。完成物件：10%超または1000万円超。"}, {"label": "受領した手付金等が代金の20%超または1000万円超", "reason": "20%は手付金の上限額（宅建業法39条）です。保全措置の基準は未完成5%・完成10%です。", "caution": ""}, {"label": "受領した手付金等が50万円超", "reason": "50万円という基準はありません（宅建業法41条1項）。", "caution": ""}], "summary": {"head": ["手付金等の保全措置基準", "閾値"], "rows": [["未完成物件（宅建業法41条）", "代金の5%超または1000万円超"], ["完成物件（宅建業法41条の2）", "代金の10%超または1000万円超"], ["保全措置の方法", "銀行等の保証・保証保険・手付金等寄託契約等"]]}}},
  {id:10117,unit:'l_cooling',level:1,field:'law',text:'クーリングオフが適用される取引場所として正しいものはどれか。',opts:['宅建業者の事務所','買主が自ら申し出た自宅','テント張りの案内所','買主が指定したファミリーレストラン'],ans:2,exp:`クーリングオフが適用される場所は、宅建業者の事務所・土地に定着した案内所（申込みの撤回等ができない旨の説明と書面を交付した場所）以外の場所です（宅建業法37条の2）。テント張りの案内所や喫茶店はクーリングオフ可能な場所です。`,"kaisetsu":{"topic": "クーリングオフ：告知日から8日以内・書面で・事務所では不可・全額返還", "basis": {"text": "クーリングオフは告知を受けた日から8日以内に書面で行います（宅建業法37条の2）。事務所・モデルルーム等での申込みはクーリングオフ不可。解除後業者は全額返還（費用控除不可）。", "example": ""}, "reason": {"text": "テント張りの案内所は施行規則16条の5の「事務所等」に該当しないため（継続的業務施設でないため）、そこでの申込み・契約はクーリングオフの対象となります（宅建業法37条の2・施行規則16条の5）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">クーリングオフのポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">告知日から8日以内</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">方法</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面（発信主義）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所での申込み</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">クーリングオフ不可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除後</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全額返還</text></svg>", "choices": [{"label": "宅建業者の事務所", "reason": "事務所での申込みはクーリングオフができません（施行規則16条の5第1号）。", "caution": ""}, {"label": "買主が自ら申し出た自宅", "reason": "買主が自ら申し出た自宅での申込みはクーリングオフができません（施行規則16条の5第3号）。", "caution": ""}, {"label": "買主が指定したファミリーレストラン", "reason": "買主が指定したファミリーレストランは「事務所等」ではないためクーリングオフができます。ただし設問の正解はテント張りの案内所（継続的施設でない）です。", "caution": "テント張りの案内所：継続的業務施設でないのでクーリングオフ可。"}], "summary": {"head": ["クーリングオフの対象か否か", "判断"], "rows": [["事務所", "不可（事務所等）"], ["専任宅建士置いたモデルルーム・案内所", "不可（事務所等）"], ["テント張り等の継続的施設でない案内所", "可（事務所等でない）"], ["買主指定の喫茶店・レストラン", "可（事務所等でない）"]]}}},
  {id:10118,unit:'l_kokoku',level:1,field:'law',text:'宅建業法上の誇大広告の禁止に関して正しいものはどれか。',opts:['故意による誇大広告のみが禁止','著しく事実に相違する表示や実際よりも有利と誤認させる表示が禁止','インターネット広告には適用されない','誇大広告による行政処分はない'],ans:1,exp:`宅建業法32条は、著しく事実に相違する表示または実際のものより著しく優良・有利と誤認させるような表示を禁止しています。故意・過失を問わず、また媒体を問いません。違反した場合は指示・業務停止処分の対象となります。`,"kaisetsu":{"topic": "宅建業者の広告：開発許可後に広告可・誇大広告は全媒体禁止・取引態様は広告時と注文時両方", "basis": {"text": "開発許可・建築確認後（工事中でも）広告できます（宅建業法33条）。誇大広告禁止は全媒体・全対象者に適用（同法32条）。取引態様は広告時と注文受領時の両方で明示が必要（同法34条）。", "example": ""}, "reason": {"text": "誇大広告の禁止（宅建業法32条）は著しく事実に相違する表示や実際よりも有利と誤認させる表示を禁止しています。故意・過失を問わず禁止され、新聞・テレビ・インターネット等あらゆる媒体が対象です。違反した場合は業務停止処分等の行政処分の対象となります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">広告規制のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">広告開始時期</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築確認・開発許可後</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誇大広告禁止</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">媒体・対象問わず</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取引態様の明示</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">広告時と注文時の両方</text></svg>", "choices": [{"label": "故意による誇大広告のみが禁止", "reason": "故意・過失を問わず誇大広告は禁止されています（宅建業法32条）。", "caution": "誇大広告禁止：故意・過失を問わず（宅建業法32条）。"}, {"label": "インターネット広告には適用されない", "reason": "インターネット広告にも誇大広告禁止規定は適用されます（宅建業法32条）。「適用されない」は誤りです。", "caution": ""}, {"label": "誇大広告による行政処分はない", "reason": "誇大広告禁止違反は業務停止処分等の行政処分の対象となります（宅建業法65条2項）。", "caution": ""}], "summary": {"head": ["誇大広告の禁止（宅建業法32条）", "内容"], "rows": [["禁止内容", "著しく事実に相違する表示・実際より有利と誤認させる表示"], ["適用媒体", "新聞・テレビ・インターネット等すべて"], ["故意・過失", "問わない"], ["違反", "業務停止処分等の行政処分"]]}}},
  {id:10119,unit:'l_kantoku',level:1,field:'law',text:'宅建業者に対する業務停止処分の期間として正しいものはどれか。',opts:['最長3ヶ月','最長6ヶ月','最長1年','期間制限なし'],ans:1,exp:`宅建業者に対する業務停止処分の期間は1年以内です（宅建業法65条2項）。指示処分よりも重く、免許取消処分よりも軽い処分です。`,"kaisetsu":{"topic": "監督処分：業務停止最長1年・大臣は全業者に指示可・指示違反→業務停止", "basis": {"text": "業務停止の最長期間は1年（宅建業法65条2項）。大臣は全業者（知事免許含む）に指示処分を行う権限があります。指示処分違反→業務停止、業務停止違反→免許取消という段階があります。", "example": ""}, "reason": {"text": "宅建業者に対する業務停止処分の最長期間は1年です（宅建業法65条2項）。6か月は誤りです。専任媒介の有効期間上限（3か月）等と混同しないようにしましょう。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">監督処分のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">処分</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">最長1年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣の権限</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全業者に指示可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">指示処分違反</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止の対象</text></svg>", "choices": [{"label": "最長3ヶ月", "reason": "業務停止処分の最長期間は1年です（宅建業法65条2項）。3か月ではありません。", "caution": "業務停止処分の最長：1年（宅建業法65条2項）。"}, {"label": "最長1年", "reason": "1年が正しい最長期間です（宅建業法65条2項）。選択肢3が正解です。", "caution": ""}, {"label": "期間制限なし", "reason": "1年という上限があります（宅建業法65条2項）。期間制限なしではありません。", "caution": ""}], "summary": {"head": ["業務停止処分の期間", "内容"], "rows": [["最長期間", "1年（宅建業法65条2項）"], ["最短期間", "法定なし（実務上は1か月等）"], ["違反", "業務停止中の業務→必要的免許取消（宅建業法66条1項9号）"]]}}},
  {id:10120,unit:'l_menkyo',level:1,field:'law',text:'宅建業の免許の欠格事由として正しいものはどれか。',opts:['成年被後見人または被保佐人','宅建業に関して不正を行い免許取消から3年が経過すれば常に免許を取得できる','拘禁刑以上の刑の執行終了から5年未満','精神的な病気を持つ者'],ans:2,exp:`宅建業免許の欠格事由（宅建業法5条）には、拘禁刑以上の刑に処せられ、その刑の執行終了等から5年を経過しない者が含まれます。また、宅建業に関し不正・不誠実な行為をして免許取消しを受けた者も、取消しの日から5年を経過しない間は欠格事由に該当します。`,"kaisetsu":{"topic": "宅建業免許：知事・大臣免許の区別・有効期間5年・欠格事由は5年", "basis": {"text": "1都道府県→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間。2020年改正で成年被後見人の欠格条項は廃止。", "example": ""}, "reason": {"text": "宅建業の免許の欠格事由は宅建業法5条に列挙されています。拘禁刑以上の刑に処せられ、その執行終了等から5年を経過しない者は欠格事由に該当します。免許取消し後の欠格期間も基本は5年であり、「3年経過」で当然に欠格が消えるわけではありません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（2020年改正で成年被後見人は廃止）</text></svg>", "choices": [{"label": "成年被後見人または被保佐人", "reason": "2021年の法改正により成年被後見人・被保佐人は一律に欠格事由とされなくなりました。個別の能力等で判断されます（宅建業法5条改正）。", "caution": "2021年改正：成年被後見人・被保佐人は一律欠格事由から除外。"}, {"label": "拘禁刑以上の刑の執行終了から5年未満", "reason": "拘禁刑以上の刑（宅建業法違反等・その他の犯罪）の執行終了から5年未満は欠格事由です（宅建業法5条1項5号等）。ただし宅建業法違反による罰金刑も5年未満は欠格事由です。", "caution": ""}, {"label": "精神的な病気を持つ者", "reason": "精神的な病気（精神疾患）を持つこと自体は欠格事由ではありません（2021年改正後）。", "caution": ""}], "summary": {"head": ["主な欠格事由（宅建業法5条1項）", "内容"], "rows": [["不正取得・業務停止違反等で取消", "取消から5年未満"], ["拘禁刑以上の刑", "刑の執行終了等から5年未満"], ["宅建業法・背任・暴力団関連の罰金", "罰金から5年未満"], ["暴力団員等", "暴力団員・暴力団関係者"]]}}},
  {id:10121,unit:'l_sonota',level:1,field:'law',text:'宅建業者の営業保証金の供託額として正しいものはどれか。',opts:['主たる事務所1000万円・従たる事務所ごと500万円','主たる事務所500万円・従たる事務所ごと300万円','主たる事務所2000万円・従たる事務所ごと1000万円','一律1000万円'],ans:0,exp:`営業保証金は主たる事務所につき1000万円、従たる事務所1カ所につき500万円を法務局等に供託しなければなりません（宅建業法25条）。`,"kaisetsu":{"topic": "宅建業者のその他の業務：従業者証明書・帳簿・業務処理原則", "basis": {"text": "全従業者に従業者証明書の交付が必要で業務中は常時携帯（宅建業法48条）。帳簿は事務所ごとに5年保存（自ら売主の新築住宅は10年）（同法49条）。宅建業者は信義誠実の原則に従って業務を行う必要があります（同法31条）。", "example": ""}, "reason": {"text": "営業保証金は主たる事務所につき1000万円、従たる事務所1か所あたり500万円を供託します（宅建業法施行令2条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業者のその他の義務</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従業者証明書</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全従業者に交付・業務中携帯</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">帳簿</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所ごと・5年保存（新築自ら売主は10年）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務処理原則</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">信義誠実の原則</text></svg>", "choices": [{"label": "主たる事務所500万円・従たる事務所ごと300万円", "reason": "主たる事務所は1000万円、従たる事務所は500万円です（宅建業法施行令2条1項）。", "caution": "営業保証金：主たる事務所1000万円・従たる事務所500万円（宅建業法施行令2条1項）。"}, {"label": "主たる事務所2000万円・従たる事務所ごと1000万円", "reason": "主たる事務所は1000万円、従たる事務所は500万円です（宅建業法施行令2条1項）。", "caution": ""}, {"label": "一律1000万円", "reason": "事務所の数に応じて増加します（宅建業法施行令2条1項）。一律ではありません。", "caution": ""}], "summary": {"head": ["営業保証金の額（宅建業法施行令2条1項）", "金額"], "rows": [["主たる事務所", "1000万円"], ["従たる事務所（1か所）", "500万円"], ["保証協会加入時", "営業保証金不要（弁済業務保証金分担金を納付）"]]}}},
  {id:10122,unit:'k_toshi',level:1,field:'limit',text:'用途地域として定められていないものはどれか。',opts:['第一種低層住居専用地域','近隣商業地域','工業専用地域','農業専用地域'],ans:3,exp:`用途地域は都市計画法で定められた13種類で構成されており（住居系8・商業系2・工業系3）、「農業専用地域」という用途地域は存在しません。農業に関連するものとして農業振興地域や農用地区域があります。`,"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域の1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "都市計画法上の用途地域は13種類あります（都市計画法9条）。「農業専用地域」は用途地域の種類ではありません。農業に関する地域区分は農業振興地域整備法等による農用地区域等です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "第一種低層住居専用地域", "reason": "第一種低層住居専用地域は13種類の用途地域の一つです（都市計画法9条1項）。", "caution": ""}, {"label": "近隣商業地域", "reason": "近隣商業地域は13種類の用途地域の一つです（都市計画法9条8項）。", "caution": ""}, {"label": "工業専用地域", "reason": "工業専用地域は13種類の用途地域の一つです（都市計画法9条12項）。", "caution": ""}], "summary": {"head": ["13種類の用途地域（都市計画法9条）", "区分"], "rows": [["住居系（8種）", "第1・2種低層住居専用、第1・2種中高層住居専用、第1・2種住居、準住居、田園住居"], ["商業系（2種）", "近隣商業、商業"], ["工業系（3種）", "準工業、工業、工業専用"], ["存在しない", "農業専用地域（用途地域ではない）"]]}}},
  {id:10123,unit:'k_kenchiku',level:1,field:'limit',text:'建蔽率（建ぺい率）の説明として正しいものはどれか。',opts:['敷地面積に対する延べ床面積の割合','敷地面積に対する建築面積の割合','建築面積に対する延べ床面積の割合','道路幅員に基づく制限'],ans:1,exp:`建蔽率は敷地面積に対する建築面積（建物の投影面積）の割合です（建築基準法53条）。なお延べ床面積に対する割合は容積率と呼ばれます。`,"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・用途制限・道路斜線", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。防火地域の耐火建築物は隣地境界線に外壁を接して建築可（同法65条）。", "example": ""}, "reason": {"text": "建ぺい率は敷地面積に対する建築面積（建物の水平投影面積）の割合です（建築基準法53条）。延べ床面積（全階の床面積合計）を使うのは容積率の計算です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">防火地域の耐火建築物</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">隣地境界線に接して建築可</text></svg>", "choices": [{"label": "敷地面積に対する延べ床面積の割合", "reason": "延べ床面積÷敷地面積は容積率の計算です（建築基準法52条）。建ぺい率は建築面積÷敷地面積です（同法53条）。", "caution": ""}, {"label": "建築面積に対する延べ床面積の割合", "reason": "建築面積に対する延べ床面積の割合は建ぺい率ではありません（建築基準法53条）。", "caution": ""}, {"label": "道路幅員に基づく制限", "reason": "道路幅員に基づく制限は容積率の規制（前面道路幅員×係数・建築基準法52条2項）であり、建ぺい率の定義ではありません。", "caution": ""}], "summary": {"head": ["建ぺい率の計算（建築基準法53条）", "内容"], "rows": [["定義", "建築面積÷敷地面積"], ["建築面積", "建物の水平投影面積（最大投影部分）"], ["制限値", "用途地域等により30%〜80%"], ["緩和", "防火地域内耐火建築物：10%加算・角地：10%加算"]]}}},
  {id:10124,unit:'k_nochi',level:1,field:'limit',text:'農地法3条の許可が必要な行為として正しいものはどれか。',opts:['農地を農地のまま売買する','農地を宅地に転用する','農地を農地以外のものにするために売買する','相続による農地の取得'],ans:0,exp:`農地法3条は農地を農地のまま権利移動（売買・贈与・賃借等）する場合に農業委員会の許可を要します。農地を転用する売買は5条許可、農地のまま転用するのは4条許可です。相続は許可不要（届出が必要）。`,"kaisetsu":{"topic": "農地法：3条は農業委員会・4・5条は都道府県知事・市街化区域は届出のみ", "basis": {"text": "農地法3条の許可権者は農業委員会。4・5条は都道府県知事等。市街化区域の農地転用（4・5条）は農業委員会への届出のみOK。相続は許可不要・3か月以内の農業委員会への届出が必要。", "example": ""}, "reason": {"text": "農地を農地のまま売買（権利移動）する場合は農地法3条の農業委員会の許可が必要です（農地法3条1項）。転用は4条・5条の問題です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text></svg>", "choices": [{"label": "農地を宅地に転用する", "reason": "農地を宅地に転用するのは農地法4条（自己転用）の問題です（農地法4条1項）。農地法3条は農地のまま権利移動する場合の規定です。", "caution": ""}, {"label": "農地を農地以外のものにするために売買する", "reason": "転用目的の権利移動は農地法5条の許可が必要です（農地法5条1項）。農地法3条ではありません。", "caution": "農地法3条＝農地のまま権利移動。農地法4条＝自己転用。農地法5条＝転用目的の権利移動。"}, {"label": "相続による農地の取得", "reason": "相続は農地法3条の許可不要です（農地法3条1項）。届出のみです（同法3条の3第1項）。", "caution": ""}], "summary": {"head": ["農地法3条・4条・5条の適用場面", "内容"], "rows": [["農地法3条", "農地のまま権利移動（農業委員会の許可）"], ["農地法4条", "農地の自己転用（知事等の許可）"], ["農地法5条", "転用目的の権利移動（知事等の許可）"], ["相続", "3条の許可不要（届出のみ）"]]}}},
  {id:10125,unit:'k_kokudo',level:1,field:'limit',text:'国土利用計画法の事後届出が必要となる市街化区域内の面積基準として正しいものはどれか。',opts:['500㎡以上','1000㎡以上','2000㎡以上','5000㎡以上'],ans:2,exp:`市街化区域内では2000㎡以上の土地の権利移動が事後届出の対象です（国土利用計画法23条）。市街化調整区域・非線引区域は5000㎡以上、都市計画区域外は10000㎡以上が基準です。`,"kaisetsu":{"topic": "国土利用計画法：事後届出は2週間以内・市街化区域は2,000㎡以上・規制区域は許可制", "basis": {"text": "事後届出は契約締結後2週間以内（国土利用計画法23条）。市街化区域は2,000㎡以上・市街化調整区域は5,000㎡以上・都市計画区域外は10,000㎡以上。届出義務者は買主のみ。規制区域は許可制。", "example": ""}, "reason": {"text": "国土利用計画法の事後届出（土地売買等の契約）において市街化区域内では2000㎡以上の取引に届出が必要です（国土利用計画法23条1項・施行令17条）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">国土利用計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">区域</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">基準面積</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2,000㎡以上</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化調整区域</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都市計画区域外</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10,000㎡以上</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">規制区域</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">許可制（届出ではない）</text></svg>", "choices": [{"label": "500㎡以上", "reason": "市街化区域内の基準は2000㎡以上です（国土利用計画法施行令17条）。", "caution": ""}, {"label": "1000㎡以上", "reason": "1000㎡は誤りです。市街化区域は2000㎡以上です（国土利用計画法施行令17条）。", "caution": "市街化区域：2000㎡以上（国土利用計画法施行令17条）。"}, {"label": "5000㎡以上", "reason": "5000㎡は非線引き都市計画区域の基準です（国土利用計画法施行令17条）。市街化区域は2000㎡以上です。", "caution": ""}], "summary": {"head": ["事後届出の面積基準", "基準"], "rows": [["市街化区域", "2000㎡以上"], ["非線引き・準都市計画区域", "5000㎡以上"], ["都市計画区域外", "10000㎡以上"]]}}},
  {id:10126,unit:'k_kukaku',level:1,field:'limit',text:'土地区画整理事業における換地として正しいものはどれか。',opts:['従前の宅地に代わる新たな宅地を権利者に割り当てること','土地区画整理区域外の土地を取得すること','建物のみを取得すること','現金で補償を受けること'],ans:0,exp:`換地とは、土地区画整理事業において従前の宅地に代えて与えられる新たな宅地のことです（土地区画整理法2条6項）。区画整理後の整備された土地が従前の権利者に割り当てられます。`,"kaisetsu":{"topic": "土地区画整理法：換地は公告翌日確定・仮換地は従前地使用不可・組合は2/3以上", "basis": {"text": "換地処分の公告翌日から換地が確定します（土地区画整理法104条）。仮換地の指定後は従前地を使用できなくなります（同法99条）。組合設立には土地所有者・借地権者の各2/3以上の同意が必要です。", "example": ""}, "reason": {"text": "換地とは土地区画整理事業後に従前の宅地に代わる新たな宅地を権利者に割り当てることです（土地区画整理法2条4項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">土地区画整理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">換地の確定</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公告の翌日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮換地指定後</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従前地は使用不可（所有権は残る）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">組合設立</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各2/3以上の同意</text></svg>", "choices": [{"label": "土地区画整理区域外の土地を取得すること", "reason": "換地は区域内の宅地の割当てです（土地区画整理法2条4項）。", "caution": "換地：従前の宅地に対応した区域内の新たな宅地（土地区画整理法2条4項）。"}, {"label": "建物のみを取得すること", "reason": "換地は建物ではなく土地の割当てです（土地区画整理法2条4項）。", "caution": ""}, {"label": "現金で補償を受けること", "reason": "現金補償は清算金です（土地区画整理法94条）。換地は宅地の割当てです（同法2条4項）。", "caution": ""}], "summary": {"head": ["換地と清算金の違い", "内容"], "rows": [["換地", "新たな宅地の割当て（土地区画整理法2条4項）"], ["清算金", "換地と従前地の価値差の金銭調整（同法94条）"]]}}},
  {id:10127,unit:'k_kenchiku',level:1,field:'limit',text:'容積率の算定にあたって延べ床面積から除外されるものとして正しいものはどれか。',opts:['地下室（住宅用途に限り延べ面積の1/3まで）','バルコニー','屋上テラス','駐車場（延べ面積の1/5まで）'],ans:3,exp:`自動車車庫等の床面積は当該建築物の各階の床面積の合計の1/5を限度として容積率算定の基礎となる延べ面積から除外されます（建築基準法52条3項）。住宅地下室は要件を満たせば1/3まで除外されます。`,"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・用途制限・道路斜線", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。防火地域の耐火建築物は隣地境界線に外壁を接して建築可（同法65条）。", "example": ""}, "reason": {"text": "容積率の算定にあたって延べ面積から除外できるものとして、駐車場（延べ面積の1/5まで・建築基準法52条3項）があります。地下室は住宅用途に限り延べ面積の1/3まで除外できますが（同条3項）、設問の正解は駐車場です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">防火地域の耐火建築物</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">隣地境界線に接して建築可</text></svg>", "choices": [{"label": "地下室（住宅用途に限り延べ面積の1/3まで）", "reason": "地下室も住宅用途に限り延べ面積の1/3まで除外できます（建築基準法52条3項）。設問の正解は駐車場（1/5まで）です。", "caution": ""}, {"label": "バルコニー", "reason": "バルコニーは容積率の計算から除外される規定はありません（ただし1m以内の部分は床面積に不算入）。", "caution": ""}, {"label": "屋上テラス", "reason": "屋上テラスは容積率の計算から除外される特別規定はありません（建築基準法52条3項）。", "caution": ""}], "summary": {"head": ["容積率から除外できる部分（建築基準法52条3項）", "上限"], "rows": [["駐車場（自動車車庫）", "延べ面積の1/5まで"], ["住宅の地下室", "延べ面積の1/3まで（住宅用途限定）"], ["共同住宅の共用廊下・階段", "全部除外"], ["宅配ボックス", "一定面積まで除外（2018年改正）"]]}}},
  {id:10128,unit:'k_toshi',level:1,field:'limit',text:'開発許可の申請先として正しいものはどれか。',opts:['市区町村長','都道府県知事（または指定都市等の長）','国土交通大臣','農業委員会'],ans:1,exp:`開発許可は都道府県知事（指定都市・中核市等では当該市の長）に申請します（都市計画法29条）。`,"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域の1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "開発許可の申請先は都道府県知事（または政令市・中核市等の指定都市の長）です（都市計画法29条1項・34条の2）。市区町村長や国交大臣ではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "市区町村長", "reason": "開発許可の申請先は原則として都道府県知事です（都市計画法29条1項）。市区町村長ではありません（指定都市は例外）。", "caution": "開発許可の申請先：都道府県知事（または指定都市等の長）。"}, {"label": "国土交通大臣", "reason": "開発許可は都道府県知事（または指定都市等の長）に申請します（都市計画法29条1項）。大臣ではありません。", "caution": ""}, {"label": "農業委員会", "reason": "農業委員会は農地転用許可等の機関であり、開発許可とは異なります（都市計画法29条）。", "caution": ""}], "summary": {"head": ["開発許可の申請先（都市計画法29条）", "権限者"], "rows": [["原則", "都道府県知事"], ["政令指定都市", "市長"], ["中核市・施行時特例市等", "市長（都市計画法34条の2等）"]]}}},
  {id:10129,unit:'t_kinyu',level:1,field:'tax',text:'住宅ローン控除（住宅借入金等特別控除）の控除期間として一般住宅の場合に正しいものはどれか。',opts:['5年','10年','13年','20年'],ans:2,exp:`住宅ローン控除の控除期間は新築・取得の場合に最長13年間です（租税特別措置法41条）。なお一般的な中古住宅取得の場合は10年間となります。`,"kaisetsu":{"topic": "住宅金融支援機構・フラット35：証券化支援が主業務・全期間固定・各機関が金利設定", "basis": {"text": "住宅金融支援機構はフラット35（民間住宅ローンの証券化支援）が主業務。フラット35は全期間固定金利のみで変動金利の選択はできません。金利は各民間金融機関が独自に設定。返済期間は15年以上35年以下。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">フラット35のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">主な業務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">民間住宅ローンの証券化支援</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">金利</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全期間固定・各金融機関が設定</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">返済期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">15年以上35年以下</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">申込み先</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">民間金融機関</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10130,unit:'t_tokei',level:1,field:'tax',text:'地価公示における標準地の価格（公示価格）の基準日として正しいものはどれか。',opts:['毎年1月1日','毎年3月31日','毎年4月1日','毎年7月1日'],ans:0,exp:`地価公示の価格は毎年1月1日を基準日として調査・公表されます（地価公示法2条）。なお基準地価（都道府県地価調査）の基準日は7月1日です。`,"kaisetsu":{"topic": "不動産統計・土地・建物の知識", "basis": {"text": "住宅着工戸数は近年80万戸前後。首都圏マンション価格は上昇傾向。J-REITの運用資産は拡大傾向。中古住宅流通は活発化。台地は宅地に適しており、干拓地は水害リスクが高いです。扇状地は比較的安定した地盤です。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産統計・土地の特性</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">近年の傾向</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅着工戸数</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">80万戸前後</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">首都圏マンション価格</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">上昇傾向</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">J-REIT</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">拡大傾向</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">干拓地</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">水害リスク高</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10131,unit:'t_inshi',level:1,field:'tax',text:'印紙税が課税される文書として正しいものはどれか。',opts:['不動産の売買契約書','単なる見積書','委任状','領収書（5万円未満）'],ans:0,exp:`不動産の売買契約書は印紙税の課税文書（第1号文書）です（印紙税法別表第一）。見積書・委任状は原則非課税で、領収書は5万円未満は非課税です。`,"kaisetsu":{"topic": "印紙税：売買・賃貸借契約書は課税文書・電子契約は非課税・1万円未満は非課税", "basis": {"text": "不動産の売買契約書・賃貸借契約書は印紙税の課税文書（第1号文書）。電子契約は課税対象外（文書でないため）。1万円未満の記載金額は非課税。複数当事者が保有する各通に課税。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">印紙税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買・賃貸借契約書</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税文書（第1号）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">電子契約</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1万円未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10132,unit:'t_shutoku',level:1,field:'tax',text:'不動産取得税の課税主体として正しいものはどれか。',opts:['国（国税）','市区町村','都道府県','所在地の特別区'],ans:2,exp:`不動産取得税は都道府県が課する地方税です（地方税法73条の2）。固定資産税・都市計画税は市区町村税、登録免許税・印紙税・所得税は国税です。`,"kaisetsu":{"topic": "不動産取得税：都道府県が課す地方税・相続は非課税・1回だけ課税", "basis": {"text": "不動産取得税は都道府県が課す地方税（地方税法73条の2）。相続・法人の合併等は非課税。一度の取得に一度だけ課税（毎年ではない）。標準税率は4%（住宅・土地は3%の軽減あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産取得税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税の頻度</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取得時に1回のみ</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">標準税率</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4%（住宅・土地は3%）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10133,unit:'t_shutoku',level:1,field:'tax',text:'不動産取得税の非課税となる取得として正しいものはどれか。',opts:['贈与による取得','交換による取得','相続による取得','競売による取得'],ans:2,exp:`相続・合併・会社分割等の一定の場合は不動産取得税が非課税となります（地方税法73条の7）。贈与・交換・競売は課税対象です。`,"kaisetsu":{"topic": "不動産取得税：都道府県が課す地方税・相続は非課税・1回だけ課税", "basis": {"text": "不動産取得税は都道府県が課す地方税（地方税法73条の2）。相続・法人の合併等は非課税。一度の取得に一度だけ課税（毎年ではない）。標準税率は4%（住宅・土地は3%の軽減あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産取得税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税の頻度</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取得時に1回のみ</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">標準税率</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4%（住宅・土地は3%）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},

  {id:10134,unit:'r_ishi',level:1,field:'rights',text:'Aがフリマサイトで冗談として「高級腕時計を100円で売ります」と投稿しBが「購入します」と応答した。相手方Bが冗談と知らず知ることもできなかった場合の法律上の効果として正しいものはどれか。',opts:['常に契約は成立しない','相手方が善意かつ無過失なら意思表示は有効で契約が成立する','Aが冗談と認めれば常に無効','相手方は常に保護されない'],ans:1,exp:`心裡留保（民法93条）では、相手方が表意者の真意（冗談）を知らず、かつ知ることができなかった場合は意思表示は有効です。相手方が善意かつ無過失なら契約は成立します。`,"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失保護）・通謀虚偽表示（無効・善意保護）。", "example": ""}, "reason": {"text": "心裡留保において相手方が善意かつ無過失であれば意思表示は有効です。表示行為を信頼した相手方を保護する民法の基本原則（意思表示の外観への信頼保護）です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "常に契約は成立しない", "reason": "心裡留保は原則として有効です。相手方Bが善意かつ無過失であれば「高級腕時計100円」の売買契約も有効に成立します（民法93条1項）。", "caution": ""}, {"label": "Aが冗談と認めれば常に無効", "reason": "Aが後から「冗談だった」と認めても、それだけでは無効になりません。相手方Bが善意無過失であれば有効のままです。", "caution": "表意者の事後的な申告で当然に無効にはなりません。"}, {"label": "相手方は常に保護されない", "reason": "相手方Bが善意かつ無過失であれば保護されます（民法93条1項）。「常に保護されない」は誤りです。", "caution": ""}], "summary": {"head": ["相手方の状態", "効力"], "rows": [["善意かつ無過失", "有効（相手方保護）"], ["悪意", "無効"], ["善意だが過失あり", "無効"]]}}},
  {id:10135,unit:'r_dairi',level:1,field:'rights',text:'本人Aが代理権を与えた後にAが死亡した場合、代理権はどうなるか。',opts:['代理権は消滅しない','代理権は消滅する（民法111条1項1号）','代理権はAの相続人が引き継ぐ','代理権は一時停止する'],ans:1,exp:`本人（A）が死亡すると任意代理権は消滅します（民法111条1項1号）。代理権は本人の死亡によって当然に消滅し、相続人に引き継がれません。`,"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護します。", "example": ""}, "reason": {"text": "任意代理権は本人の死亡により消滅します（民法111条1項1号）。代理権は本人との信頼関係に基づく権限であり、本人が死亡するとその基礎が失われるためです。代理権消滅後の行為は無権代理になります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "代理権は消滅しない", "reason": "本人の死亡は代理権の消滅事由です（民法111条1項1号）。死亡後も代理権が継続するという主張は誤りです。", "caution": "本人死亡→代理権消滅（民法111条1項1号）。"}, {"label": "代理権はAの相続人が引き継ぐ", "reason": "代理権は相続の対象となりません。本人が死亡した時点で代理権は消滅し、相続人には承継されません（民法111条1項1号）。", "caution": ""}, {"label": "代理権は一時停止する", "reason": "本人の死亡は代理権の「消滅」事由であり「一時停止」ではありません（民法111条1項1号）。", "caution": ""}], "summary": {"head": ["代理権の消滅事由", "根拠"], "rows": [["本人の死亡", "民法111条1項1号"], ["本人の破産手続開始", "民法111条1項2号"], ["代理人の死亡", "民法111条1項3号"], ["代理人の後見開始・破産", "民法111条1項3号"]]}}},
  {id:10136,unit:'r_jiko',level:1,field:'rights',text:'裁判上の請求による消滅時効の「更新」はどの時点で生じるか。',opts:['訴状を裁判所に提出した時','裁判所が訴状を受理した時','確定判決等によって権利が確定した時','相手方に訴状が送達された時'],ans:2,exp:`裁判上の請求による時効の更新は、確定判決等によって権利が確定した時点に生じます（民法147条2項）。請求中は時効の完成が猶予され、権利確定後に新たな時効が起算されます。`,"kaisetsu":{"topic": "消滅時効：知った時から5年または行使可能時から10年", "basis": {"text": "消滅時効は「知った時から5年」または「行使可能時から10年」のいずれか早い方で完成します（民法166条）。時効は援用して初めて効力が発生します（民法145条）。承認は更新事由です（民法152条）。", "example": ""}, "reason": {"text": "2020年改正後の民法では、裁判上の請求による時効の「更新」は確定判決等により権利が確定した時点で生じます（民法147条2項）。訴え提起時は「完成猶予」が生じるに過ぎません。この区別が重要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">期間</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人身損害</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年または20年</text></svg>", "choices": [{"label": "訴状を裁判所に提出した時", "reason": "訴状提出時は時効の「完成猶予」が生じますが（民法147条1項）、「更新」は確定判決等の時点です（同条2項）。", "caution": "訴え提起→完成猶予、確定判決→更新。この区別が重要です。"}, {"label": "裁判所が訴状を受理した時", "reason": "訴状受理時は完成猶予が生じますが、更新は確定判決等の時点です（民法147条2項）。", "caution": ""}, {"label": "相手方に訴状が送達された時", "reason": "訴状送達時は手続上の意義がありますが、時効の更新は確定判決等の時点です（民法147条2項）。", "caution": ""}], "summary": {"head": ["時効の完成猶予と更新", "内容"], "rows": [["完成猶予", "時効完成を一時的に阻止（完成猶予事由が終了するまで）"], ["更新", "時効期間が新たにゼロからスタート"], ["裁判上の請求", "訴提起→完成猶予、確定判決→更新（民法147条）"], ["承認", "更新のみ（民法152条）"], ["催告", "完成猶予のみ・6か月（民法150条）"]]}}},
  {id:10137,unit:'r_souzoku',level:1,field:'rights',text:'相続の承認・放棄を選択するための熟慮期間として正しいものはどれか。',opts:['相続開始を知った日から1ヶ月以内','自己のために相続の開始があったことを知った時から3ヶ月以内','相続開始から6ヶ月以内','期間の制限はない'],ans:1,exp:`相続人は自己のために相続の開始があったことを知った時から3ヶ月以内（熟慮期間）に、単純承認・限定承認・放棄のいずれかを選択しなければなりません（民法915条）。`,"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2・遺産分割は全員合意", "basis": {"text": "配偶者と子は各1/2（民法900条）。放棄は3か月以内に家裁へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2（民法1042条）。兄弟姉妹に遺留分はなし。遺産分割協議は全員合意が必要。", "example": ""}, "reason": {"text": "相続の承認・放棄の熟慮期間は「自己のために相続の開始があったことを知った時」から3か月以内です（民法915条1項）。家庭裁判所に申請して延長も可能です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "相続開始を知った日から1ヶ月以内", "reason": "熟慮期間は3か月以内です（民法915条1項）。1か月ではありません。", "caution": "熟慮期間は3か月。1か月ではありません。"}, {"label": "相続開始から6ヶ月以内", "reason": "熟慮期間は相続の開始があったことを知った時から3か月以内です（民法915条1項）。6か月ではありません。", "caution": ""}, {"label": "期間の制限はない", "reason": "熟慮期間は3か月という期間制限があります（民法915条1項）。期限内に手続きしなければ単純承認したとみなされます（民法921条2号）。", "caution": ""}], "summary": {"head": ["熟慮期間", "内容"], "rows": [["期間", "3か月（民法915条1項）"], ["起算点", "自己のために相続の開始があったことを知った時"], ["延長", "家庭裁判所への申請で延長可"], ["期間内無手続き", "単純承認とみなす（民法921条2号）"]]}}},
  {id:10138,unit:'r_baibai',level:1,field:'rights',text:'売買契約において手付が交付された場合の解約手付の効果として正しいものはどれか。',opts:['売主は手付を返還するだけで解除できる','買主は手付を放棄し、売主は手付の倍額を現実に提供して解除できる（相手方の履行着手前まで）','手付があっても解除権はない','相手方が履行完了後も解除できる'],ans:1,exp:`解約手付として手付が交付された場合、買主は手付を放棄し、売主は手付の倍額を現実に提供して解除できます（民法557条1項）。ただし相手方が「履行に着手」した後は解除できません。`,"kaisetsu":{"topic": "売買：同時履行の抗弁権・解除は原則催告が必要・契約不適合責任", "basis": {"text": "売買では代金と引渡しは同時履行の関係（民法533条）。解除は原則として相当の期間を定めた催告後に行います（民法541条）。契約不適合責任の通知は知った時から1年以内（民法566条）。", "example": ""}, "reason": {"text": "解約手付が交付された場合、買主は手付を放棄し、売主は手付の倍額を現実に提供することで解除できます（民法557条1項）。ただし相手方が「履行に着手」した後は解除できません（同条1項ただし書）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">売買のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">同時履行</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金と引渡しは同時履行</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則として催告が必要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">契約不適合の通知</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から1年以内</text></svg>", "choices": [{"label": "売主は手付を返還するだけで解除できる", "reason": "売主が解除するには手付の「倍額を現実に提供」する必要があります（民法557条1項）。返還のみでは足りません。", "caution": "売主の解除＝手付の倍額を現実提供（単なる返還では不可）。"}, {"label": "手付があっても解除権はない", "reason": "解約手付があれば相手方の履行着手前まで解除できます（民法557条1項）。「解除権はない」は誤りです。", "caution": ""}, {"label": "相手方が履行完了後も解除できる", "reason": "相手方が「履行に着手」した後は解約手付による解除はできません（民法557条1項ただし書）。履行完了後も解除できるとするのは誤りです。", "caution": ""}], "summary": {"head": ["解約手付による解除", "内容"], "rows": [["買主から解除", "手付放棄（民法557条1項）"], ["売主から解除", "手付の倍額を現実に提供（民法557条1項）"], ["解除の限界", "相手方の履行着手後は解除不可（民法557条1項ただし書）"], ["履行着手の例", "残代金の準備・受領のための準備等"]]}}},
  {id:10139,unit:'r_chinshaku',level:1,field:'rights',text:'建物賃貸借における敷金の返還時期として正しいものはどれか。',opts:['賃貸借終了と同時に返還される','賃貸借終了後、建物の明渡しを受けた後に未払賃料等を控除した残額を返還する','賃貸借終了の3ヶ月後に返還される','賃貸人の裁量で決まる'],ans:1,exp:`敷金は、賃貸借が終了し建物の明渡しを受けた後に、未払賃料等の債務を控除した残額を返還しなければなりません（民法622条の2第1項）。`,"kaisetsu":{"topic": "賃貸借：通常損耗は原状回復に含まれない・有益費は終了時に請求・賃料増額は正当事由が必要", "basis": {"text": "賃貸借終了時の原状回復義務に通常使用による損耗（壁の日焼け等）は含まれません（民法621条）。必要費は直ちに、有益費は終了時の請求が原則。更新拒絶には正当事由が必要（借地借家法28条）。", "example": ""}, "reason": {"text": "敷金は賃貸借終了後に建物の明渡しを受けた後、未払い賃料等を控除した残額を返還します（民法622条の2第1項）。明渡しが先行し、その後に敷金精算が行われます。明渡しと同時返還は不要です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">賃貸借のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通常損耗</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原状回復に含まれない</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要費</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直ちに請求可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有益費</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸借終了時に請求</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">更新拒絶</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当事由が必要</text></svg>", "choices": [{"label": "賃貸借終了と同時に返還される", "reason": "敷金の返還は賃貸借終了と同時ではなく、建物の明渡し後に行われます（民法622条の2第1項）。明渡しが先行します。", "caution": "賃貸借終了≠敷金返還。明渡し後に返還されます。"}, {"label": "賃貸借終了の3ヶ月後に返還される", "reason": "3か月後という規定はありません。明渡しを受けた後、合理的な期間内に精算して返還します（民法622条の2第1項）。", "caution": ""}, {"label": "賃貸人の裁量で決まる", "reason": "敷金の返還時期は賃貸人の裁量ではなく、民法622条の2第1項により明渡し後とされています。", "caution": ""}], "summary": {"head": ["敷金の返還", "内容"], "rows": [["返還時期", "明渡し後（民法622条の2第1項）"], ["返還額", "敷金額－未払い賃料等の控除額"], ["返還義務", "当然に生じる（特約で変更可能な範囲あり）"], ["原状回復との関係", "明渡し後に敷金精算・原状回復費用を差し引く"]]}}},
  {id:10140,unit:'r_fuhoko',level:1,field:'rights',text:'不法行為（民法709条）の成立要件として正しいものはどれか。',opts:['故意のみが要件で過失では成立しない','故意または過失・権利・法益の侵害・損害の発生・因果関係の4要件が必要','損害が発生すれば故意・過失は不要','被害者が損害を証明する必要はない'],ans:1,exp:`不法行為の成立には①故意または過失②他人の権利・法益の侵害③損害の発生④因果関係の4要件が必要です（民法709条）。被害者側がこれらの要件を立証する必要があります。`,"kaisetsu":{"topic": "不法行為：故意または過失が必要・使用者責任・工作物責任", "basis": {"text": "不法行為は故意または過失が必要です（民法709条）。使用者は被用者の職務上の不法行為について責任を負います（民法715条）。工作物の所有者は無過失責任（占有者が免責された場合）（民法717条）。", "example": ""}, "reason": {"text": "不法行為（民法709条）は①故意または過失、②権利または法律上保護される利益の侵害、③損害の発生、④因果関係の4要件が必要です。これらを被害者が証明する必要があります（過失の証明責任は被害者側）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不法行為のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般不法行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">故意または過失が必要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">使用者責任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">被用者への求償可（信義則上制限）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">工作物の所有者責任</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無過失責任（占有者が免責された場合）</text></svg>", "choices": [{"label": "故意のみが要件で過失では成立しない", "reason": "故意または過失のいずれかがあれば不法行為は成立します（民法709条）。過失でも成立します。", "caution": "故意または過失→不法行為成立。過失だけでも成立します。"}, {"label": "損害が発生すれば故意・過失は不要", "reason": "損害の発生だけでなく故意または過失も要件です（民法709条）。無過失では不法行為は成立しません（製造物責任等の特別法を除く）。", "caution": ""}, {"label": "被害者が損害を証明する必要はない", "reason": "損害賠償請求をする被害者が損害の発生・因果関係等を証明する必要があります（民法709条・挙証責任の原則）。", "caution": ""}], "summary": {"head": ["不法行為の成立要件（民法709条）", "内容"], "rows": [["①故意または過失", "加害行為に故意または過失があること"], ["②権利・法益の侵害", "他人の権利または法律上保護される利益を侵害"], ["③損害の発生", "財産的・精神的損害"], ["④因果関係", "行為と損害の間の相当因果関係"]]}}},
  {id:10141,unit:'r_shakuchi',level:1,field:'rights',text:'普通建物賃貸借（一般の借家契約）における賃貸人からの更新拒絶・解約申入れの要件として正しいものはどれか。',opts:['3ヶ月前の予告のみで解約できる','正当事由が必要（借地借家法28条）','賃借人の同意があれば正当事由は不要','期間満了で自動終了する'],ans:1,exp:`普通建物賃貸借では賃貸人が更新を拒絶したり解約を申し入れたりする場合、「正当事由」がなければ認められません（借地借家法28条）。正当事由の有無は個別の事情で総合的に判断されます。`,"kaisetsu":{"topic": "借地権：最短30年・建物登記で対抗・建物滅失でも消滅せず・定期借地権は3種類", "basis": {"text": "普通借地権の最短存続期間は30年（借地借家法3条）。借地上の建物の自己名義登記が対抗要件（同法10条）。建物が滅失しても借地権は消滅しません。定期借地権は①一般（50年以上）②事業用（10〜50年未満）③建物譲渡特約（30年以上）の3種類。", "example": ""}, "reason": {"text": "普通建物賃貸借において賃貸人が更新を拒絶・解約申入れするには正当事由が必要です（借地借家法28条）。正当事由は賃貸人・賃借人双方の事情（自己使用の必要性・建物状況・立退料等）を総合考慮して判断されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">借地権のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">最短存続期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">対抗要件</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借地上の建物の自己名義登記</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物滅失</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借地権は消滅しない</text></svg>", "choices": [{"label": "3ヶ月前の予告のみで解約できる", "reason": "普通借家では正当事由が必要です（借地借家法28条）。予告期間だけでは解約できません（6か月前通知も必要・同法26条1項）。", "caution": "普通借家の更新拒絶：6か月前通知＋正当事由が必要（借地借家法26条・28条）。"}, {"label": "賃借人の同意があれば正当事由は不要", "reason": "正当事由の要否は法律上の要件であり（借地借家法28条）、賃借人の同意の有無で変わるものではありません。", "caution": ""}, {"label": "期間満了で自動終了する", "reason": "普通借家では正当事由がなければ期間満了後も法定更新されます（借地借家法26条1項）。自動終了はしません。", "caution": ""}], "summary": {"head": ["普通借家の更新", "内容"], "rows": [["法定更新", "期間満了後も賃借人が使用継続→賃貸人が遅滞なく異議なければ更新（借地借家法26条1項）"], ["更新拒絶の要件", "①6か月前通知②正当事由（借地借家法26条1項・28条）"], ["正当事由の考慮要素", "賃貸人・賃借人の必要性・建物状況・立退料"]]}}},
  {id:10142,unit:'r_kukku',level:1,field:'rights',text:'区分所有建物において「専有部分」となるものはどれか。',opts:['構造上独立し独立して住居等として利用できる部分（各居室部分）','建物の共用廊下','エレベーター','外壁'],ans:0,exp:`専有部分は「構造上区分された数個の部分」で「独立して住居・店舗・事務所等の用途に供することができるもの」です（区分所有法1条）。廊下・エレベーター・外壁等は共用部分です。`,"kaisetsu":{"topic": "区分所有法：重大変更は3/4以上・建替えは4/5以上・管理組合法人は30人以上", "basis": {"text": "共用部分の重大変更は区分所有者・議決権の各3/4以上の特別決議が必要（区分所有法17条）。建替えは4/5以上（同法62条）。管理組合法人の設立は3/4以上かつ区分所有者30人以上（同法47条）。専有部分と共有持分は分離処分不可（同法15条）。", "example": ""}, "reason": {"text": "専有部分とは構造上区分され独立して居住・店舗等として利用できる建物の部分です（区分所有法2条3項）。廊下・エレベーター・外壁等は法定共用部分として区分所有者全員の共有になります（同法11条）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">区分所有法の決議要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">事項</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">普通決議</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">過半数</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">重大変更・規約変更</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3/4以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">管理組合法人</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3/4以上（30人以上）</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建替え</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4/5以上</text></svg>", "choices": [{"label": "建物の共用廊下", "reason": "共用廊下は法定共用部分です（区分所有法11条1項）。専有部分にはなりません。", "caution": "廊下・EV・外壁・屋上等＝共用部分（専有部分になれない）。"}, {"label": "エレベーター", "reason": "エレベーターは法定共用部分です（区分所有法11条1項）。専有部分にはなりません。", "caution": ""}, {"label": "外壁", "reason": "外壁は法定共用部分です（区分所有法11条1項）。専有部分にはなりません。", "caution": ""}], "summary": {"head": ["区分の種類", "内容・例"], "rows": [["専有部分", "構造上・利用上独立した部分（各住戸・区分所有法2条3項）"], ["法定共用部分", "廊下・EV・外壁・屋上・基礎（区分所有法11条）"], ["規約共用部分", "規約で共用部分と定めた部分（管理人室等）"]]}}},
  {id:10143,unit:'r_touki',level:1,field:'rights',text:'不動産登記において単独で申請できるものはどれか。',opts:['売買による所有権移転登記','相続による所有権移転登記','贈与による所有権移転登記','抵当権設定登記'],ans:1,exp:`相続による所有権移転登記は相続人が単独で申請できます（不動産登記法63条2項）。売買・贈与・抵当権設定は権利者と義務者の共同申請が原則です（同法60条）。`,"kaisetsu":{"topic": "不動産登記：権利登記は共同申請・仮登記は順位保全・建物滅失は1か月以内", "basis": {"text": "権利に関する登記は原則として登記権利者と登記義務者が共同申請します（不動産登記法60条）。仮登記は順位保全機能があるが完全な対抗力は本登記後です。建物滅失登記の申請義務は1か月以内（同法57条）。", "example": ""}, "reason": {"text": "登記申請は原則として登記権利者と登記義務者が共同で行います（不動産登記法60条）。しかし相続の場合は登記義務者（被相続人）がすでに死亡しているため、相続人が単独で申請できます（同法63条2項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産登記のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利登記</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則として共同申請</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮登記</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">順位保全（対抗力は本登記後）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物滅失登記</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1か月以内</text></svg>", "choices": [{"label": "売買による所有権移転登記", "reason": "売買による所有権移転登記は買主（登記権利者）と売主（登記義務者）が共同で申請します（不動産登記法60条）。単独申請はできません。", "caution": ""}, {"label": "贈与による所有権移転登記", "reason": "贈与による所有権移転登記も受贈者（権利者）と贈与者（義務者）の共同申請が必要です（不動産登記法60条）。", "caution": ""}, {"label": "抵当権設定登記", "reason": "抵当権設定登記は抵当権者（権利者）と抵当権設定者（義務者）の共同申請が必要です。", "caution": ""}], "summary": {"head": ["登記の種類", "申請方法"], "rows": [["売買・贈与・抵当権設定", "共同申請（権利者＋義務者）"], ["相続による所有権移転", "単独申請（相続人のみ）"], ["法人の合併", "単独申請（存続法人のみ）"], ["判決による登記", "単独申請（勝訴当事者のみ）"]]}}},
  {id:10144,unit:'l_menkyo',level:1,field:'law',text:'宅建業者の事務所に置かなければならない専任宅建士の割合として正しいものはどれか。',opts:['従業者の5人に1人以上の割合','従業者の3人に1人以上の割合','従業者の10人に1人以上の割合','1事務所に最低1人'],ans:0,exp:`宅建業者の事務所には従業者5人に1人以上の割合で専任の宅建士を置かなければなりません（宅建業法31条の3第1項）。`,"kaisetsu":{"topic": "宅建業免許：知事・大臣免許の区別・有効期間5年・欠格事由は5年", "basis": {"text": "1都道府県→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間。2020年改正で成年被後見人の欠格条項は廃止。", "example": ""}, "reason": {"text": "事務所ごとに業務に従事する者5名につき1名以上の割合で専任の宅建士を設置しなければなりません（宅建業法31条の3第1項）。従業者数÷5が必要な専任宅建士の最低数の目安です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（2020年改正で成年被後見人は廃止）</text></svg>", "choices": [{"label": "従業者の3人に1人以上の割合", "reason": "専任宅建士の設置割合は5名に1名以上です（宅建業法31条の3第1項）。3名に1名は誤りです。", "caution": "専任宅建士：従業者5名に1名以上（宅建業法31条の3第1項）。"}, {"label": "従業者の10人に1人以上の割合", "reason": "10名に1名は緩すぎます。5名に1名以上が正しい割合です（宅建業法31条の3第1項）。", "caution": ""}, {"label": "1事務所に最低1人", "reason": "1事務所に最低1人は正しいですが、業務従事者が6名以上の場合は2名以上が必要になります（宅建業法31条の3第1項）。", "caution": ""}], "summary": {"head": ["専任宅建士の設置（宅建業法31条の3）", "内容"], "rows": [["割合", "業務従事者5名に1名以上"], ["計算例", "10名→2名以上、11名→3名以上"], ["不足した場合", "2週間以内に補充が必要"], ["案内所等", "1名以上の専任宅建士が必要"]]}}},
  {id:10145,unit:'l_takkenshi',level:1,field:'law',text:'宅建士が氏名・住所を変更した場合の手続きとして正しいものはどれか。',opts:['変更は届出不要','遅滞なく（変更後おおむね30日以内を目安に）登録を受けた都道府県知事に変更登録を申請する','変更後1年以内に申請すれば足りる','変更は雇用している宅建業者を通じて申請する'],ans:1,exp:`宅建士は氏名・住所等の登録事項に変更が生じた場合、遅滞なく登録を受けた都道府県知事に変更の登録を申請しなければなりません（宅建業法20条）。`,"kaisetsu":{"topic": "専任宅建士：5人に1人以上・兼任不可・2週間以内に補充", "basis": {"text": "事務所には業務従事者5人に1人以上の専任宅建士が必要（宅建業法31条の3）。1社専属で複数業者の兼任は不可。不足時は2週間以内に補充が必要。案内所（申込み受付）にも専任宅建士が必要。", "example": ""}, "reason": {"text": "宅建士が氏名や住所等の登録事項に変更があった場合は遅滞なく登録を受けた都道府県知事に変更登録を申請しなければなりません（宅建業法20条）。変更登録は宅建士自身が直接申請します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">専任宅建士のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">設置基準</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5人に1人以上</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">兼任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可（1社専属）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不足補充</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間以内</text></svg>", "choices": [{"label": "変更は届出不要", "reason": "変更登録は義務です（宅建業法20条）。「不要」は誤りです。", "caution": "変更登録：遅滞なく申請義務（宅建業法20条）。"}, {"label": "変更後1年以内に申請すれば足りる", "reason": "「遅滞なく」申請が必要です（宅建業法20条）。1年以内という規定はなく、速やかに申請しなければなりません。", "caution": ""}, {"label": "変更は雇用している宅建業者を通じて申請する", "reason": "変更登録は宅建士本人が直接都道府県知事に申請します（宅建業法20条）。宅建業者を通じる必要はありません。", "caution": ""}], "summary": {"head": ["宅建士の変更登録（宅建業法20条）", "内容"], "rows": [["対象", "氏名・住所等の登録事項の変更"], ["申請者", "宅建士本人"], ["申請先", "登録を受けた都道府県知事"], ["時期", "遅滞なく"]]}}},
  {id:10146,unit:'l_baikai',level:1,field:'law',text:'一般媒介契約において法的に義務付けられていないものはどれか。',opts:['媒介契約締結時の書面交付','2週間に1回以上の業務報告（法定の頻度）','取引態様の明示','媒介契約書への記名押印'],ans:1,exp:`2週間に1回以上の業務処理状況の報告義務は専任媒介・専属専任媒介契約にのみ課されます（宅建業法34条の2第8項・9項）。一般媒介契約では法定の報告頻度義務はありません。`,"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任の有効期間は最長3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。レインズ登録は専任7日以内・専属専任5日以内。業務報告は専任2週間に1回・専属専任1週間に1回。", "example": ""}, "reason": {"text": "一般媒介契約では宅建業者に定期的な業務報告義務（法定の頻度）はありません（宅建業法34条の2）。専任媒介は2週間に1回以上、専属専任媒介は1週間に1回以上の報告義務があります（同条9項・10項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">自己発見</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">レインズ</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専任</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専属専任</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text></svg>", "choices": [{"label": "媒介契約締結時の書面交付", "reason": "媒介契約締結後、遅滞なく34条の2書面を交付する義務があります（宅建業法34条の2第1項）。義務ではないという説明は誤りです。", "caution": ""}, {"label": "取引態様の明示", "reason": "広告や取引の申込みを受けた際に取引態様を明示する義務があります（宅建業法34条1項）。義務ではないという説明は誤りです。", "caution": ""}, {"label": "媒介契約書への記名押印", "reason": "34条の2書面への宅建業者の記名・押印は義務です（宅建業法34条の2第1項）。義務ではないという説明は誤りです。", "caution": ""}], "summary": {"head": ["業務報告義務の比較", "頻度"], "rows": [["一般媒介", "法定の業務報告義務なし"], ["専任媒介", "2週間に1回以上（宅建業法34条の2第9項）"], ["専属専任媒介", "1週間に1回以上（宅建業法34条の2第10項）"]]}}},
  {id:10147,unit:'l_hoshu',level:1,field:'law',text:'宅建業者が建物賃貸借の媒介をした場合（依頼者から承諾を得た場合）の報酬上限として正しいものはどれか。',opts:['借賃の2ヶ月分（消費税別）','貸主・借主から合計して借賃の1ヶ月分（消費税別）が上限','借賃の3ヶ月分が上限','報酬は自由に決められる'],ans:1,exp:`建物賃貸借の媒介報酬は貸主・借主の双方から合計して借賃の1ヶ月分（消費税別）が上限です（国土交通省告示）。依頼者の承諾があれば一方から1ヶ月分を受領することも可能です。`,"kaisetsu":{"topic": "報酬：売買は代金×3%+6万（400万超）・賃貸は借賃1か月・上限超過は不可", "basis": {"text": "売買（400万超）の一方からの上限は代金×3%+6万。双方合計は一方上限×2。賃貸（居住用・非居住用とも）は借賃1か月分。低廉な空家等（800万円以下）は、媒介報酬について原則の報酬額を超えて30万円（税別）まで受領できる場合があります（依頼者への説明・合意が必要）。", "example": ""}, "reason": {"text": "建物賃貸借の媒介報酬は、依頼者の双方から合計して借賃の1か月分（税別）が上限です（告示）。依頼者の一方から0.5か月分超を受け取るには相手方の承諾が必要です。依頼者の承諾があれば一方から1か月分まで受け取れます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対象</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（400万超）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万（一方）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（200万以下）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸（双方合計）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借賃1か月分</text></svg>", "choices": [{"label": "借賃の2ヶ月分（消費税別）", "reason": "建物賃貸借媒介の報酬上限は双方合計で1か月分です（告示）。2か月分は誤りです。", "caution": "建物賃貸借媒介の報酬：双方合計で借賃1か月分（告示）。"}, {"label": "借賃の3ヶ月分が上限", "reason": "3か月分は誤りです（告示）。双方合計で1か月分が上限です。", "caution": ""}, {"label": "報酬は自由に決められる", "reason": "報酬は告示により上限が定められており（宅建業法46条）、自由に決めることはできません。", "caution": ""}], "summary": {"head": ["建物賃貸借の媒介報酬（告示）", "上限"], "rows": [["双方合計", "借賃の1か月分（税別）"], ["一方から原則", "0.5か月分まで"], ["一方から（承諾あり）", "1か月分まで（相手方の承諾必要）"], ["居住用以外", "同じく双方合計で1か月分"]]}}},
  {id:10148,unit:'l_37jo',level:1,field:'law',text:'37条書面の「定めがある場合のみ記載する」任意的記載事項として正しいものはどれか。',opts:['当事者の氏名（名称）・住所','宅地建物の引渡し時期','代金・借賃の額','契約解除に関する事項'],ans:3,exp:`37条書面の必要的記載事項に当事者の氏名・住所、引渡し時期、代金額等があります。「契約解除に関する事項」「損害賠償額の予定・違約金に関する事項」等は定めがある場合のみ記載する任意的記載事項です（宅建業法37条1項各号・2項各号）。`,"kaisetsu":{"topic": "37条書面：全取引で交付・記名（押印不要）・移転登記申請時期は必要的記載事項", "basis": {"text": "37条書面は全取引で契約の双方当事者に交付が義務（宅建業法37条）。引渡し時期・移転登記申請時期は必要的記載事項。2021年改正で押印は不要、記名のみで足ります。", "example": ""}, "reason": {"text": "37条書面の任意的記載事項は「定めがある場合に」記載する事項です（宅建業法37条1項7号〜11号）。契約解除に関する事項（違約金・解除条件等）は定めがある場合のみ記載します（同条1項7号）。当事者の氏名・引渡し時期・代金の額は必要的記載事項です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付義務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全取引・双方当事者</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡時期・移転登記申請時期等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要）</text></svg>", "choices": [{"label": "当事者の氏名（名称）・住所", "reason": "当事者の氏名・住所は必要的記載事項です（宅建業法37条1項1号）。任意的ではありません。", "caution": "当事者の氏名・住所、代金、引渡し時期、移転登記時期：必要的記載事項。"}, {"label": "宅地建物の引渡し時期", "reason": "引渡し時期は必要的記載事項です（宅建業法37条1項4号）。任意的ではありません。", "caution": ""}, {"label": "代金・借賃の額", "reason": "代金の額は必要的記載事項です（宅建業法37条1項2号）。任意的ではありません。", "caution": ""}], "summary": {"head": ["37条書面の任意的記載事項（定めがある場合）", "根拠"], "rows": [["契約解除の定め", "宅建業法37条1項7号"], ["損害賠償額の予定・違約金", "宅建業法37条1項8号（準じた解釈）"], ["融資あっせんの定め", "宅建業法37条1項8号"], ["天災等による損害負担", "宅建業法37条1項10号"], ["瑕疵担保（契約不適合）の定め", "宅建業法37条1項11号"]]}}},
  {id:10149,unit:'l_hosho',level:1,field:'law',text:'宅建業者の営業保証金の額（主たる事務所のみの場合）として正しいものはどれか。',opts:['100万円','500万円','1,000万円','2,000万円'],ans:2,exp:`営業保証金の額は主たる事務所につき1,000万円、従たる事務所1ヶ所あたり500万円です（宅建業法25条2項）。保証協会社員は弁済業務保証金分担金（主たる事務所60万円等）を納付し、営業保証金の供託義務が免除されます。`,"kaisetsu":{"topic": "営業保証金・保証協会：主1,000万・従500万/営業保証金vs分担金60万・30万", "basis": {"text": "営業保証金は主1,000万・従500万（宅建業法25条）。保証協会の分担金は主60万・従30万（同法64条の9）。還付対象は業者以外の取引した者。加入は任意。不足補充は通知後2週間以内。", "example": ""}, "reason": {"text": "営業保証金の額は主たる事務所につき1000万円です（宅建業法25条1項・施行令2条1項1号）。従たる事務所は1か所あたり500万円です（同施行令2条1項2号）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">営業保証金と弁済業務保証金</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">営業保証金</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">弁済業務保証金（分担金）</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">主たる事務所</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000万円</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">60万円</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従たる事務所/所</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">500万円</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">還付対象</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者以外</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者以外</text></svg>", "choices": [{"label": "100万円", "reason": "主たる事務所の営業保証金は1000万円です（宅建業法施行令2条1項1号）。100万円ではありません。", "caution": "主たる事務所の営業保証金＝1000万円。従たる事務所＝500万円（1か所あたり）。"}, {"label": "500万円", "reason": "500万円は従たる事務所（1か所あたり）の営業保証金額です（宅建業法施行令2条1項2号）。主たる事務所は1000万円です。", "caution": ""}, {"label": "2,000万円", "reason": "主たる事務所の営業保証金は1000万円です（宅建業法施行令2条1項1号）。2000万円ではありません。", "caution": ""}], "summary": {"head": ["営業保証金の額", "金額"], "rows": [["主たる事務所", "1000万円"], ["従たる事務所（1か所あたり）", "500万円"], ["保証協会加入の場合", "営業保証金不要（弁済業務保証金分担金を納付）"]]}}},
  {id:10150,unit:'l_cooling',level:1,field:'law',text:'クーリングオフが適用されない（解除できない）場合として正しいものはどれか。',opts:['業者の案内所での申込み','業者が指定した喫茶店での申込み','買主が自ら申し出た自宅または勤務先での申込み','届出のない展示会場での申込み'],ans:2,exp:`買主が自ら申し出た「自宅または勤務先」での申込み・契約はクーリングオフができません（宅建業法施行規則16条の5第2号）。業者訪問の自宅・業者指定の喫茶店等はクーリングオフできます。`,"kaisetsu":{"topic": "クーリングオフ：告知日から8日以内・書面で・事務所では不可・全額返還", "basis": {"text": "クーリングオフは告知を受けた日から8日以内に書面で行います（宅建業法37条の2）。事務所・モデルルーム等での申込みはクーリングオフ不可。解除後業者は全額返還（費用控除不可）。", "example": ""}, "reason": {"text": "買主が自ら申し出た自宅または勤務先での申込み・契約はクーリングオフの対象外です（宅建業法施行規則16条の5第3号）。買主自身が申し出た場所での申込みは慎重な判断の機会があるためです。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">クーリングオフのポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">告知日から8日以内</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">方法</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面（発信主義）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所での申込み</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">クーリングオフ不可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除後</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全額返還</text></svg>", "choices": [{"label": "業者の案内所での申込み", "reason": "業者の案内所（継続的業務施設でないもの等）での申込みはクーリングオフができます（施行規則16条の5）。「できない」は誤りです。", "caution": ""}, {"label": "業者が指定した喫茶店での申込み", "reason": "業者が指定した喫茶店での申込みはクーリングオフができます（施行規則16条の5は喫茶店等を事務所等に含まない）。", "caution": ""}, {"label": "届出のない展示会場での申込み", "reason": "届出のない展示会場は「事務所等」に該当しないためクーリングオフができます（施行規則16条の5）。", "caution": ""}], "summary": {"head": ["クーリングオフの可否", "場所"], "rows": [["業者の事務所", "不可"], ["買主が自ら申し出た自宅・勤務先", "不可（施行規則16条の5第3号）"], ["業者が指定した喫茶店", "可"], ["届出のない展示会場・テント張り", "可"]]}}},
  {id:10151,unit:'l_jusetsu',level:1,field:'law',text:'重要事項説明を行う時期として正しいものはどれか。',opts:['契約締結後に行えばよい','契約締結前（契約が成立するまでの間）に行わなければならない','引渡し前に行えばよい','媒介契約締結時に行わなければならない'],ans:1,exp:`重要事項説明は契約が成立するまでの間に行わなければなりません（宅建業法35条1項）。契約締結前に相手方が重要事項を理解したうえで判断できるようにするためです。`,"kaisetsu":{"topic": "重要事項説明：宅建士が説明・買主への交付・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主（貸主）は不要。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能。", "example": ""}, "reason": {"text": "重要事項説明は必ず契約締結前（契約が成立するまでの間）に行わなければなりません（宅建業法35条1項）。買主・借主が契約内容を十分に理解した上で契約するかどうかを判断できるようにするためです。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士のみ（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "契約締結後に行えばよい", "reason": "重要事項説明は契約締結前に行わなければなりません（宅建業法35条1項）。締結後では遅すぎます。", "caution": "重要事項説明：契約締結前（宅建業法35条1項）。"}, {"label": "引渡し前に行えばよい", "reason": "引渡し前では不十分です。契約締結前に行わなければなりません（宅建業法35条1項）。", "caution": ""}, {"label": "媒介契約締結時に行わなければならない", "reason": "重要事項説明は媒介契約時ではなく売買・賃貸借等の契約締結前に行います（宅建業法35条1項）。", "caution": ""}], "summary": {"head": ["重要事項説明の時期", "内容"], "rows": [["時期", "契約締結前（宅建業法35条1項）"], ["媒介契約", "別途締結（重要事項説明とは別）"], ["37条書面", "契約締結後に交付"], ["IT重説", "要件を満たせば可（国土交通省ガイドライン）"]]}}},
  {id:10152,unit:'l_kantoku',level:1,field:'law',text:'宅建業法違反をした宅建業者に対する指示処分・業務停止処分の権限を持つのはどれか。',opts:['警察署長','検察庁','免許を与えた国土交通大臣または都道府県知事','市区町村長'],ans:2,exp:`宅建業法違反に対する指示処分・業務停止処分・免許取消し処分は、免許権者である国土交通大臣または都道府県知事が行います（宅建業法65条）。`,"kaisetsu":{"topic": "監督処分：業務停止最長1年・大臣は全業者に指示可・指示違反→業務停止", "basis": {"text": "業務停止の最長期間は1年（宅建業法65条2項）。大臣は全業者（知事免許含む）に指示処分を行う権限があります。指示処分違反→業務停止、業務停止違反→免許取消という段階があります。", "example": ""}, "reason": {"text": "宅建業者への指示処分・業務停止処分の権限は、免許を与えた国土交通大臣または都道府県知事が持ちます（宅建業法65条1項・2項）。警察・検察・市区町村は権限を持ちません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">監督処分のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">処分</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">最長1年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣の権限</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全業者に指示可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">指示処分違反</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止の対象</text></svg>", "choices": [{"label": "警察署長", "reason": "警察署長には宅建業者への行政処分（指示・業務停止等）の権限はありません（宅建業法65条1項）。", "caution": ""}, {"label": "検察庁", "reason": "検察庁は刑事訴追機関であり、行政処分（指示・業務停止等）の権限はありません（宅建業法65条1項）。", "caution": ""}, {"label": "市区町村長", "reason": "市区町村長には宅建業者への行政処分の権限はありません（宅建業法65条1項）。", "caution": ""}], "summary": {"head": ["監督処分の権限者（宅建業法65条）", "内容"], "rows": [["国土交通大臣", "大臣免許業者への処分"], ["都道府県知事", "知事免許業者への処分。大臣免許業者に対しても一定の処分可"], ["相互通報", "処分した場合は相手方に通知義務"]]}}},
  {id:10153,unit:'k_toshi',level:1,field:'limit',text:'用途地域のうち、住居の環境保護が最も厳格な地域はどれか。',opts:['第1種中高層住居専用地域','第1種低層住居専用地域','第2種住居地域','準住居地域'],ans:1,exp:`第1種低層住居専用地域は低層住宅の良好な住環境を保護する地域で、建築できる建物の用途が最も厳しく制限されています（都市計画法9条1項・建築基準法48条・別表第二）。`,"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域の1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "第一種低層住居専用地域は住居の環境保護が最も厳格な用途地域で、低層住宅（高さ10m・12m制限）の良好な環境を保護します（都市計画法9条1項）。小規模な店舗や公益施設を除き、ほぼ住宅専用です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "第1種中高層住居専用地域", "reason": "第1種中高層住居専用地域は中高層住宅のための地域ですが、第1種低層住居専用地域より制限が緩やかです（都市計画法9条3項）。", "caution": "最も厳格：第1種低層住居専用地域。"}, {"label": "第2種住居地域", "reason": "第2種住居地域は住居・商業・工業の混在を許容する地域で、第1種低層住居専用地域より制限が緩やかです（都市計画法9条6項）。", "caution": ""}, {"label": "準住居地域", "reason": "準住居地域は幹線道路沿道等で住居・商業・工業が混在する地域です（都市計画法9条7項）。", "caution": ""}], "summary": {"head": ["住居系用途地域（厳格な順）", "特徴"], "rows": [["第1種低層住居専用地域", "最も厳格。低層住宅専用（高さ10m・12m制限）"], ["第2種低層住居専用地域", "小規模店舗可"], ["第1種中高層住居専用地域", "中高層住宅中心"], ["第2種中高層住居専用地域", "店舗・事務所も一部可"]]}}},
  {id:10154,unit:'k_kenchiku',level:1,field:'limit',text:'建築基準法の「接道義務」として正しいものはどれか。',opts:['建築物の敷地は幅員4m以上の道路に1m以上接しなければならない','建築物の敷地は幅員4m以上の道路に2m以上接しなければならない（原則）','建築物の敷地は幅員6m以上の道路に接しなければならない','接道義務に例外はない'],ans:1,exp:`建築物の敷地は原則として幅員4m以上の道路に2m以上接していなければなりません（建築基準法43条）。いわゆる「2項道路」（幅員4m未満で特定行政庁が指定した道路）の場合はセットバックが必要です。`,"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・用途制限・道路斜線", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。防火地域の耐火建築物は隣地境界線に外壁を接して建築可（同法65条）。", "example": ""}, "reason": {"text": "接道義務とは、建築物の敷地は幅員4m以上の道路に2m以上接しなければならないという規定です（建築基準法43条1項）。緊急車両の通行・防火等のための最低限の要件です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">防火地域の耐火建築物</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">隣地境界線に接して建築可</text></svg>", "choices": [{"label": "建築物の敷地は幅員4m以上の道路に1m以上接しなければならない", "reason": "接道義務は2m以上接することが原則です（建築基準法43条1項）。1mでは不足です。", "caution": "接道義務：幅員4m以上の道路に2m以上接すること（建築基準法43条1項）。"}, {"label": "建築物の敷地は幅員6m以上の道路に接しなければならない", "reason": "道路幅員の要件は4m以上です（建築基準法43条1項）。6mではありません。", "caution": ""}, {"label": "接道義務に例外はない", "reason": "特定行政庁が建築審査会の同意を得て許可した場合は接道義務の例外があります（建築基準法43条2項）。", "caution": ""}], "summary": {"head": ["接道義務（建築基準法43条1項）", "内容"], "rows": [["道路幅員", "4m以上"], ["接道長さ", "2m以上"], ["例外", "特定行政庁が建築審査会の同意を得て許可"], ["2項道路", "幅員4m未満でも特例で道路扱い→セットバック義務"]]}}},
  {id:10155,unit:'k_nochi',level:1,field:'limit',text:'農地法2条の「農地」は何を基準に判断するか。正しいものはどれか。',opts:['登記地目が「田」または「畑」の土地','現に耕作の目的に供されている土地（現況主義）','農業委員会が農地と認定した土地のみ','農地台帳に登録された土地'],ans:1,exp:`農地法上の「農地」は「耕作の目的に供されている土地」であり（農地法2条1項）、登記地目ではなく現況で判断します。地目が農地でも現に宅地として利用されていれば農地法の農地ではありません。`,"kaisetsu":{"topic": "農地法：3条は農業委員会・4・5条は都道府県知事・市街化区域は届出のみ", "basis": {"text": "農地法3条の許可権者は農業委員会。4・5条は都道府県知事等。市街化区域の農地転用（4・5条）は農業委員会への届出のみOK。相続は許可不要・3か月以内の農業委員会への届出が必要。", "example": ""}, "reason": {"text": "農地法上の「農地」とは現に耕作の目的に供されている土地です（農地法2条1項）。登記地目ではなく現況（現在の状態）で判断します（現況主義）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text></svg>", "choices": [{"label": "登記地目が「田」または「畑」の土地", "reason": "登記地目ではなく現況で判断します（農地法2条1項）。現に耕作に使われていれば農地です。", "caution": "農地の判断基準＝現況（現況主義・農地法2条1項）。登記地目ではない。"}, {"label": "農業委員会が農地と認定した土地のみ", "reason": "農業委員会の認定ではなく現況（現在の耕作目的での使用）で判断します（農地法2条1項）。", "caution": ""}, {"label": "農地台帳に登録された土地", "reason": "農地台帳への登録の有無ではなく現況で判断します（農地法2条1項）。", "caution": ""}], "summary": {"head": ["農地の定義（農地法2条1項）", "内容"], "rows": [["定義", "現に耕作の目的に供されている土地"], ["判断基準", "現況主義（登記地目・課税地目は関係ない）"], ["採草放牧地", "耕作には使われていないが牧草の採取等に使う土地（農地と別に規制）"]]}}},
  {id:10156,unit:'k_kokudo',level:1,field:'limit',text:'国土利用計画法の事後届出をすべき者として正しいものはどれか。',opts:['売主（土地を譲渡した者）','買主（土地を取得した者）','売主と買主の双方','仲介した宅建業者'],ans:1,exp:`事後届出の義務者は土地を取得した者（買主・権利取得者）です（国土利用計画法23条1項）。売主ではありません。取引後2週間以内に市町村経由で都道府県知事に届け出ます。`,"kaisetsu":{"topic": "国土利用計画法：事後届出は2週間以内・市街化区域は2,000㎡以上・規制区域は許可制", "basis": {"text": "事後届出は契約締結後2週間以内（国土利用計画法23条）。市街化区域は2,000㎡以上・市街化調整区域は5,000㎡以上・都市計画区域外は10,000㎡以上。届出義務者は買主のみ。規制区域は許可制。", "example": ""}, "reason": {"text": "国土利用計画法の事後届出をすべき者は権利を取得した者（買主）です（国土利用計画法23条1項）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">国土利用計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">区域</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">基準面積</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2,000㎡以上</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化調整区域</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都市計画区域外</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10,000㎡以上</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">規制区域</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">許可制（届出ではない）</text></svg>", "choices": [{"label": "売主（土地を譲渡した者）", "reason": "届出義務者は権利取得者（買主）です（国土利用計画法23条1項）。売主ではありません。", "caution": "事後届出：買主（権利取得者）が届け出る（国土利用計画法23条1項）。"}, {"label": "売主と買主の双方", "reason": "届出義務は買主のみです（国土利用計画法23条1項）。", "caution": ""}, {"label": "仲介した宅建業者", "reason": "宅建業者は届出義務者ではありません（国土利用計画法23条1項）。", "caution": ""}], "summary": {"head": ["事後届出の義務者（国土利用計画法23条1項）", "内容"], "rows": [["届出義務者", "権利取得者（買主等）"], ["届出期限", "契約締結後3週間以内"]]}}},
  {id:10157,unit:'k_kukaku',level:1,field:'limit',text:'土地区画整理組合の設立の認可権者として正しいものはどれか。',opts:['市町村長','都道府県知事','国土交通大臣','農業委員会'],ans:1,exp:`土地区画整理組合の設立は都道府県知事の認可が必要です（土地区画整理法14条1項）。組合設立には施行地区内の宅地所有者等の3分の2以上の同意も必要です（同法18条）。`,"kaisetsu":{"topic": "土地区画整理法：換地は公告翌日確定・仮換地は従前地使用不可・組合は2/3以上", "basis": {"text": "換地処分の公告翌日から換地が確定します（土地区画整理法104条）。仮換地の指定後は従前地を使用できなくなります（同法99条）。組合設立には土地所有者・借地権者の各2/3以上の同意が必要です。", "example": ""}, "reason": {"text": "土地区画整理組合の設立には都道府県知事の認可が必要です（土地区画整理法14条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">土地区画整理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">換地の確定</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公告の翌日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮換地指定後</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従前地は使用不可（所有権は残る）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">組合設立</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各2/3以上の同意</text></svg>", "choices": [{"label": "市町村長", "reason": "土地区画整理組合の設立認可権者は市町村長ではなく都道府県知事です（土地区画整理法14条1項）。", "caution": "土地区画整理組合の設立認可：都道府県知事（土地区画整理法14条1項）。"}, {"label": "国土交通大臣", "reason": "組合設立の認可は都道府県知事が行います（土地区画整理法14条1項）。", "caution": ""}, {"label": "農業委員会", "reason": "農業委員会は土地区画整理組合と無関係です（土地区画整理法14条1項）。", "caution": ""}], "summary": {"head": ["土地区画整理組合（土地区画整理法14条）", "内容"], "rows": [["設立認可", "都道府県知事"], ["設立要件", "各3分の2以上の同意＋7人以上"], ["法的性格", "法人（土地区画整理法22条）"]]}}},
  {id:10158,unit:'k_mori',level:1,field:'limit',text:'盛土規制法上「宅地造成」に含まれる工事として正しいものはどれか。',opts:['除草作業','切土で高さ2mを超えるがけを生じさせる工事','農地から農地への転換工事','建物の建替えのみを目的とする工事'],ans:1,exp:`宅地造成に含まれる工事（盛土規制法2条2号）として、切土で高さ2mを超えるがけを生じさせる工事・盛土で高さ1mを超えるがけを生じさせる工事・切土と盛土を合わせて高さ2mを超えるがけを生じさせる工事等があります。`,"kaisetsu":{"topic": "盛土規制法・宅地造成：盛土は1m超・切土は2m超・特定盛土等規制区域", "basis": {"text": "盛土で高さ1mを超える崖を生じる場合は許可が必要（盛土規制法）。切土は2mを超える崖で許可が必要。特定盛土等規制区域内の一定規模以上の盛土等は許可が必要です。農地・森林も規制対象に含まれます。", "example": ""}, "reason": {"text": "盛土規制法上の「宅地造成」は切土・盛土等で一定の崖・斜面を生じさせる工事です。切土で高さ2m超の崖を生じさせる工事はその一つです（宅地造成及び特定盛土等規制法施行令3条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">盛土規制法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">工事種別</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可が必要な規模</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">切土</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">高さ2mを超える崖</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">盛土</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">高さ1mを超える崖</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">面積</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">500㎡超の宅地造成</text></svg>", "choices": [{"label": "除草作業", "reason": "除草作業は宅地造成ではありません（宅地造成及び特定盛土等規制法2条2号）。", "caution": "宅地造成：切土で2m超の崖を生じさせる工事等（宅地造成及び特定盛土等規制法2条2号）。"}, {"label": "農地から農地への転換工事", "reason": "農地から農地への転換は宅地造成ではありません（宅地造成及び特定盛土等規制法2条2号）。", "caution": ""}, {"label": "建物の建替えのみを目的とする工事", "reason": "土地の形状変更がなければ宅地造成ではありません（宅地造成及び特定盛土等規制法2条2号）。", "caution": ""}], "summary": {"head": ["宅地造成の対象", "内容"], "rows": [["切土", "高さ2m超の崖を生じさせるもの"], ["盛土", "高さ1m超の崖を生じさせるもの"], ["面積", "500m2超の切土・盛土"]]}}},
  {id:10159,unit:'t_joto',level:1,field:'tax',text:'不動産の譲渡所得における長期・短期の区別の基準として正しいものはどれか。',opts:['所有期間が5年以下は短期・5年超は長期','譲渡した年の1月1日における所有期間が5年以下は短期・5年超は長期','所有期間が3年以下は短期・3年超は長期','登記の有無で決まる'],ans:1,exp:`譲渡所得の長期・短期の区別は「譲渡した年の1月1日における所有期間」が5年以下か5年超かで判断します（租税特別措置法31条・32条）。`,"kaisetsu":{"topic": "譲渡所得：分離課税・長期は20%・3,000万円控除は3年に1回", "basis": {"text": "土地・建物の譲渡所得は分離課税。長期（5年超）は合計20%（所得税15%+住民税5%）。短期（5年以下）は39%（所得税30%+住民税9%）。3,000万円特別控除は前年・前々年に適用があれば使えません（3年に1回）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">譲渡所得のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税方式</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">分離課税</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">長期（5年超）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計20%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">短期（5年以下）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計39%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3,000万円控除</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年に1回の制限</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10160,unit:'t_shutoku',level:1,field:'tax',text:'不動産取得税が課税される「不動産の取得」に該当するものはどれか。',opts:['相続による取得','法人の合併による取得','建物の新築','法人の分割による取得'],ans:2,exp:`建物の新築・増築・改築も「不動産の取得」として不動産取得税が課税されます（地方税法73条の2）。相続・法人合併・一定の信託による取得等は非課税となります。`,"kaisetsu":{"topic": "不動産取得税：都道府県が課す地方税・相続は非課税・1回だけ課税", "basis": {"text": "不動産取得税は都道府県が課す地方税（地方税法73条の2）。相続・法人の合併等は非課税。一度の取得に一度だけ課税（毎年ではない）。標準税率は4%（住宅・土地は3%の軽減あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産取得税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税の頻度</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取得時に1回のみ</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">標準税率</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4%（住宅・土地は3%）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10161,unit:'t_kotei',level:1,field:'tax',text:'新築住宅（一定要件を満たすもの）に適用される固定資産税の減額特例として正しいものはどれか。',opts:['新築後3年間（中高層耐火建築物等は5年間）、建物部分の固定資産税が1/2に減額','5年間、土地部分の固定資産税が1/2に減額','10年間、建物・土地ともに1/4に減額','新築住宅の固定資産税は全額免除'],ans:0,exp:`新築住宅の建物（床面積50〜280平方メートルの居住部分）については、新築後3年間（中高層耐火建築物等は5年間）固定資産税額が1/2に減額されます（地方税法附則15条の6）。`,"kaisetsu":{"topic": "固定資産税：市町村が課す地方税・賦課期日は1月1日・評価替えは3年ごと", "basis": {"text": "固定資産税は市町村（東京23区は都）が課す地方税（地方税法343条）。賦課期日は毎年1月1日。評価替えは3年ごと（基準年度）。住宅用地の特例：200㎡以下は課税標準1/6、超過部分は1/3。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">固定資産税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市町村（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賦課期日</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">評価替え</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年ごと</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅用地（200㎡以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税標準1/6</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10162,unit:'t_toroku',level:1,field:'tax',text:'抵当権設定登記の登録免許税率（一般の場合）として正しいものはどれか。',opts:['債権金額の2%','債権金額の1%','債権金額の0.4%','固定資産税評価額の2%'],ans:2,exp:`抵当権設定登記の登録免許税は債権金額の0.4%です（登録免許税法別表第一）。一定要件を満たす住宅ローン等は軽減税率（0.1%）が適用される場合があります。`,"kaisetsu":{"topic": "登録免許税：所有権移転登記等に課税・国税・税率は課税標準×一定率", "basis": {"text": "登録免許税は不動産の所有権移転登記等に課税される国税（登録免許税法1条）。税率は課税標準（通常は固定資産税評価額）×一定率で計算します。相続による所有権移転登記は0.4%、売買は2%が原則税率（軽減措置あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">登録免許税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">国（国税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税対象</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">所有権移転登記等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">0.4%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2%（軽減措置あり）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10163,unit:'t_inshi',level:1,field:'tax',text:'印紙税において課税対象とならないものとして正しいものはどれか。',opts:['不動産売買契約書','金銭消費貸借契約書','電子データのみで作成した契約書（電子契約書）','土地賃貸借契約書'],ans:2,exp:`電子契約書（紙の文書でなく電子データとして作成・保存する契約書）には印紙税が課されません（印紙税法2条）。印紙税は「文書」に課税するものであり、電子データは課税対象外です。`,"kaisetsu":{"topic": "印紙税：売買・賃貸借契約書は課税文書・電子契約は非課税・1万円未満は非課税", "basis": {"text": "不動産の売買契約書・賃貸借契約書は印紙税の課税文書（第1号文書）。電子契約は課税対象外（文書でないため）。1万円未満の記載金額は非課税。複数当事者が保有する各通に課税。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">印紙税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買・賃貸借契約書</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税文書（第1号）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">電子契約</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1万円未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10164,unit:'t_chika',level:1,field:'tax',text:'地価公示の公示価格が表す価格として正しいものはどれか。',opts:['その土地の最高取引価格','正常な取引において通常成立すると認められる価格（正常価格）','周辺の平均取引価格','固定資産税評価額の2倍の価格'],ans:1,exp:`地価公示の公示価格は「自由な取引において通常成立すると認められる価格」（正常価格）で、更地・権利付きでない状態での客観的な価格を表します（地価公示法2条2項）。`,"kaisetsu":{"topic": "地価公示・不動産鑑定評価：基準日は1月1日・土地鑑定委員会が実施・3手法", "basis": {"text": "地価公示の基準日は毎年1月1日で土地鑑定委員会（国土交通省）が実施（地価公示法）。公示価格は鑑定評価の規準となります（同法8条）。不動産鑑定評価の3手法：原価法・取引事例比較法・収益還元法。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">地価公示・鑑定評価</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">基準日</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">実施機関</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">土地鑑定委員会（国土交通省）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">鑑定評価の3手法</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原価法・取引事例比較法・収益還元法</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10165,unit:'r_saikensoron',level:1,field:'rights',text:'弁済の充当の順序（当事者間の合意がない場合）として正しいものはどれか。',opts:['元本→利息→費用の順で充当','費用→利息→元本の順で充当（民法489条）','弁済者が充当する債務を自由に選べる','債権者が充当する債務を自由に決定できる'],ans:1,exp:`弁済の充当は当事者の合意がない場合、費用→利息→元本の順で充当されます（民法489条）。複数の債務がある場合は弁済者の指定（民法488条）がなければ法定の順序によります。`,"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要（民法446条2項）。連帯保証人は催告・検索の抗弁権なし（民法454条）。債権譲渡の第三者対抗は確定日付ある証書による通知・承諾（民法467条2項）。相殺の絶対的効力：弁済・更改・相殺。", "example": ""}, "reason": {"text": "弁済の充当順序は当事者間の合意がない場合、費用→利息→元本の順で充当されます（民法489条）。元本から充当すると利息が増え続けて債務者に不利なため、費用・利息から先に充当します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">催告・検索の抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text></svg>", "choices": [{"label": "元本→利息→費用の順で充当", "reason": "充当の順序は費用→利息→元本です（民法489条）。元本から先に充当するのは誤りです。", "caution": "充当順序：費用→利息→元本（民法489条）。元本が最後です。"}, {"label": "弁済者が充当する債務を自由に選べる", "reason": "弁済者は同種の数個の債務がある場合に充当先を指定できますが（民法488条）、費用・利息・元本の充当順序は民法489条で規定されています。", "caution": ""}, {"label": "債権者が充当する債務を自由に決定できる", "reason": "充当の順序は民法489条で定められており、債権者が自由に決定できるわけではありません。", "caution": ""}], "summary": {"head": ["弁済の充当順序（民法489条）", "内容"], "rows": [["①費用", "弁済費用（登記費用等）を先に充当"], ["②利息", "元本に対する利息を次に充当"], ["③元本", "最後に元本に充当"], ["理由", "元本から充当すると利息が増え続けて債務者に不利"]]}}},
  {id:10166,unit:'r_bukken',level:1,field:'rights',text:'地上権と賃借権の違いとして正しいものはどれか。',opts:['地上権は債権、賃借権は物権','地上権は物権（登記で第三者対抗可）、賃借権は債権（登記なしでは対抗困難）','地上権は賃借権より弱い権利','賃借権は地主の承諾なく譲渡できる'],ans:1,exp:`地上権は物権（民法265条）で登記があれば第三者に対抗でき、地主の承諾なく譲渡・転貸ができます。賃借権は債権で原則として地主の承諾なく譲渡・転貸はできません（民法612条）。`,"kaisetsu":{"topic": "物権変動：登記が対抗要件・不法占拠者には登記不要", "basis": {"text": "不動産の物権変動は登記が第三者への対抗要件です（民法177条）。不法占拠者には登記なく対抗できます（判例）。建物賃借権は引渡しが対抗要件です（借地借家法31条）。", "example": ""}, "reason": {"text": "地上権（物権）と賃借権（債権）の違いは実務で極めて重要です。物権は絶対性・排他性を持ち誰にでも主張できますが、債権は特定の相手にしか主張できません。この違いが対抗力・譲渡・転貸の要件に影響します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">物権変動の対抗要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対抗要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">二重譲渡</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先に登記した者が優先</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不法占拠者</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記不要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物賃借権</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡し</text></svg>", "choices": [{"label": "地上権は債権、賃借権は物権", "reason": "逆です。地上権が物権（民法265条）、賃借権が債権（民法601条）です。地上権は登記で誰にでも対抗でき、地主の承諾なく譲渡・転貸できます。", "caution": "地上権＝物権、賃借権＝債権。逆に覚えると大幅失点です。"}, {"label": "地上権は賃借権より弱い権利", "reason": "地上権は物権であり、債権である賃借権より強い権利です。物権は絶対性・排他性・追及効を持つため、より強固な権利です。", "caution": ""}, {"label": "賃借権は地主の承諾なく譲渡できる", "reason": "賃借権の譲渡・転貸には原則として賃貸人（地主）の承諾が必要です（民法612条）。地上権なら承諾不要です。", "caution": ""}], "summary": {"head": ["比較項目", "地上権（物権）", "賃借権（債権）"], "rows": [["第三者対抗力", "登記で可", "登記または引渡しで可（借地借家法）"], ["譲渡・転貸", "地主の承諾不要", "地主の承諾が原則必要"], ["登記義務", "当事者に申請権（地主に協力義務）", "登記義務なし（借地借家法で保護）"]]}}},
  {id:10167,unit:'r_chinshaku',level:1,field:'rights',text:'建物が売却されて賃貸人が変わった場合、賃借人が新賃貸人に賃借権を対抗できる要件として正しいものはどれか。',opts:['常に対抗できる','建物の引渡しを受けていれば新賃貸人に対抗できる（借地借家法31条）','登記がなければ対抗できない','新賃貸人の同意が必要'],ans:1,exp:`建物賃貸借では、引渡しを受けた賃借人は建物の新所有者（新賃貸人）に対して賃借権を対抗できます（借地借家法31条）。建物の引渡しが対抗要件となっています。`,"kaisetsu":{"topic": "賃貸借：通常損耗は原状回復に含まれない・有益費は終了時に請求・賃料増額は正当事由が必要", "basis": {"text": "賃貸借終了時の原状回復義務に通常使用による損耗（壁の日焼け等）は含まれません（民法621条）。必要費は直ちに、有益費は終了時の請求が原則。更新拒絶には正当事由が必要（借地借家法28条）。", "example": ""}, "reason": {"text": "建物賃借人は建物の引渡しを受けることで対抗力を取得します（借地借家法31条1項）。登記不要でこの対抗力が生じることが、借地借家法の賃借人保護の重要な特徴です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">賃貸借のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通常損耗</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原状回復に含まれない</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要費</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直ちに請求可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有益費</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸借終了時に請求</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">更新拒絶</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当事由が必要</text></svg>", "choices": [{"label": "常に対抗できる", "reason": "対抗要件（引渡し）を備えていなければ新賃貸人に対抗できません（借地借家法31条）。常に対抗できるわけではありません。", "caution": ""}, {"label": "登記がなければ対抗できない", "reason": "建物賃借権は登記がなくても引渡しを受けていれば対抗できます（借地借家法31条）。登記は不要です。", "caution": "建物賃借権の対抗要件＝引渡し（登記不要）。"}, {"label": "新賃貸人の同意が必要", "reason": "引渡しを受けていれば新賃貸人の同意は不要です（借地借家法31条）。", "caution": ""}], "summary": {"head": ["賃借権の対抗要件", "内容"], "rows": [["建物賃借権（借地借家法31条）", "建物の引渡し（登記不要）"], ["借地権（借地借家法10条）", "借地上建物の登記"], ["民法上の賃借権（民法605条）", "賃借権の登記"]]}}},
],
2:[
  {id:10168,unit:"r_dairi",level:2,field:"rights",text:"AがBの代理人と称して代理権なくCと売買契約を結んだ。Cが善意かつ無過失の場合に成立しうる法律構成はどれか。",opts:["契約は当然に無効","AはBに対してBの名で契約した旨を主張できる","表見代理が成立しBが責任を負う可能性がある","Cは必ずAに対して損害賠償を請求しなければならない"],ans:2,exp:"代理権がなくても「代理権があると信じさせるような外観」があり、Cが善意かつ無過失であれば表見代理が成立し本人Bが責任を負います（民法109条・110条・112条）。","kaisetsu":{"topic":"代理：表見代理と無権代理","basis":{"text":"無権代理行為は、本人が追認しない限り本人に効力を生じません（民法113条）。ただし、代理権があるような外観があり、相手方が善意無過失である場合には、表見代理が成立して本人に効果が帰属することがあります（民法109条・110条・112条）。","example":"AがBの代理人と称してCと売買契約をした。Bが代理権を与えたような外観を作り、Cが善意無過失なら、Bが契約上の責任を負う可能性があります。"},"reason":{"text":"本問ではAに代理権がありませんが、Cが善意無過失であり、代理権があると信じるにつき正当な理由があれば表見代理が成立し、本人Bに効果が帰属する可能性があります。無権代理は常に当然無効となるわけではなく、本人の追認や表見代理の成否を検討します。"},"svg":"","choices":[{"label":"契約は当然に無効","reason":"無権代理行為は本人が追認しない限り本人に効力を生じませんが、表見代理が成立する場合は本人に効果が帰属します。「当然に無効」と断定するのは誤りです。","caution":""},{"label":"AはBに対してBの名で契約した旨を主張できる","reason":"AがB名義で契約した事実だけで、Bに契約効果を帰属させることはできません。代理権、追認、表見代理の成否が問題になります。","caution":""},{"label":"Cは必ずAに対して損害賠償を請求しなければならない","reason":"Cは表見代理が成立すればBに責任追及でき、また無権代理人Aへの責任追及も検討できます。「必ずAに請求」という限定は誤りです。","caution":""}],"summary":{"head":["論点","結論"],"rows":[["無権代理","本人の追認がなければ本人に効力なし"],["表見代理","外観と相手方の善意無過失等があれば本人に効果帰属"],["無権代理人の責任","相手方は無権代理人への責任追及も検討可能"]]}}},
  {id:10169,unit:'r_jiko',level:2,field:'rights',text:'消滅時効完成後にBが「払います」と承認した場合、Bはその後時効を援用できるか。',opts:['援用できる。時効完成後の承認は効力がない','援用できない。信義則上、援用は許されないとするのが判例','援用できる。援用は相手方への意思表示が必要なため','裁判所が判断する'],ans:1,exp:'時効完成後に債務を承認した債務者は信義則上時効の援用が許されないとするのが判例です。たとえ時効が完成していても承認後は時効を使えなくなります。',"kaisetsu":{"topic": "消滅時効：知った時から5年または行使可能時から10年", "basis": {"text": "一般の債権の消滅時効は「権利行使できると知った時から5年」または「権利行使できる時から10年」のいずれか早い方で完成します（民法166条1項）。時効は援用して初めて効力が発生します（民法145条）。", "example": ""}, "reason": {"text": "時効完成後に債務者が承認した場合、その後の時効援用は信義則上許されません（判例）。時効完成を知りながら承認したか否かにかかわらず、相手方（債権者）はその承認を信頼するため、その信頼を裏切るような時効援用は認められません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">時効期間</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人の生命・身体への損害</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年または20年</text></svg>", "choices": [{"label": "援用できる。時効完成後の承認は効力がない", "reason": "時効完成後の承認は無効ではなく、信義則上その後の時効援用が制限されます（判例）。「効力がない」は誤りです。", "caution": ""}, {"label": "援用できる。援用は相手方への意思表示が必要なため", "reason": "援用が相手方への意思表示であることは正しいですが、時効完成後に承認した場合は信義則上援用が制限されます（判例）。", "caution": ""}, {"label": "裁判所が判断する", "reason": "時効完成後の承認と信義則に基づく援用制限は判例により確立した法理であり、裁判所が個別に判断するまでもありません（判例）。", "caution": ""}], "summary": {"head": ["時効完成後の行為", "援用の可否"], "rows": [["何もしない", "時効援用可"], ["時効完成後に承認（一部弁済・猶予依頼等）", "信義則上援用不可（判例）"], ["時効完成後に明示的に放棄", "放棄の効力あり・援用不可"], ["時効完成前の放棄", "無効（民法146条）"]]}}},
  {id:10170,unit:'r_jiko',level:2,field:'rights',text:'時効完成後に所有者Bから土地を購入して登記したCに対し、取得時効完成者Aはどう対抗できるか。',opts:['登記なくCに時効取得を対抗できる','時効完成後に登記したCに対しては対抗できない','Aは時効を再起算して再び20年占有すれば対抗できる','Cが悪意ならAが常に勝つ'],ans:1,exp:'時効完成後に第三者Cが登記した場合、AはCに時効取得を対抗できません（判例）。時効完成後は対抗問題となり登記の先後で決まります。',"kaisetsu":{"topic": "消滅時効：知った時から5年または行使可能時から10年", "basis": {"text": "一般の債権の消滅時効は「権利行使できると知った時から5年」または「権利行使できる時から10年」のいずれか早い方で完成します（民法166条1項）。時効は援用して初めて効力が発生します（民法145条）。", "example": ""}, "reason": {"text": "時効完成後に登場した第三者との関係は対抗問題です（判例）。時効取得者は登記を備えなければ、時効完成後に登記を得た第三者に対抗できません（民法177条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">時効期間</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人の生命・身体への損害</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年または20年</text></svg>", "choices": [{"label": "登記なくCに時効取得を対抗できる", "reason": "時効完成後に登場した第三者Cとの関係は対抗問題であり、登記がなければ対抗できません（判例・民法177条）。", "caution": "時効完成前の第三者→援用で対抗可。時効完成後の第三者→対抗問題。"}, {"label": "Aは時効を再起算して再び20年占有すれば対抗できる", "reason": "時効の再起算は可能ですが、設問のCはすでに登記を取得しているため、Aが再度20年占有しても当初の問題は解決しません。", "caution": ""}, {"label": "Cが悪意ならAが常に勝つ", "reason": "単純悪意者（時効取得の事実を知っていた）に対してもAは登記が必要です（判例）。背信的悪意者の場合は例外です。", "caution": ""}], "summary": {"head": ["第三者の登場時期", "時効取得者の対抗力"], "rows": [["時効完成前の第三者", "時効援用で対抗可（登記不要・判例）"], ["時効完成後の第三者", "対抗問題→先に登記した者が優先"]]}}},
  {id:10171,unit:'r_tanpo',level:2,field:'rights',text:'法定地上権の成立要件として誤っているものはどれか。',opts:['抵当権設定時に土地と建物が同一所有者','抵当権設定時に建物が存在','土地または建物の一方または双方に抵当権が設定','競売後も土地と建物の所有者が同一'],ans:3,exp:'法定地上権が成立するには「競売によって土地と建物の所有者が異なる者になること」が要件です（民法388条）。同一所有者のままでは法定地上権は発生しません。',"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権です（民法369条）。質権は占有の移転が必要です。先取特権は法律上当然に成立する法定担保物権です。", "example": ""}, "reason": {"text": "法定地上権（民法388条）の成立要件は①抵当権設定時に土地と建物が存在、②同一所有者、③競売で土地・建物の所有者が分離、の3つです。競売後に同一所有者になるのは法定地上権が成立する必要がない状況であり、要件ではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・非占有</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・占有</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "抵当権設定時に土地と建物が同一所有者", "reason": "これは法定地上権の成立要件です（民法388条）。誤りではありません。", "caution": ""}, {"label": "抵当権設定時に建物が存在", "reason": "設定時に建物が存在することは要件です（民法388条・判例）。設定後に建築された建物には原則として法定地上権は成立しません。", "caution": ""}, {"label": "土地または建物の一方または双方に抵当権が設定", "reason": "土地・建物の一方または双方に抵当権が設定されることが要件です（民法388条）。誤りではありません。", "caution": ""}], "summary": {"head": ["法定地上権の成立要件（民法388条）", "内容"], "rows": [["①", "抵当権設定時に土地と建物が存在"], ["②", "設定時に土地と建物が同一所有者"], ["③", "競売により土地・建物の所有者が分離"], ["効果", "建物所有者のために地上権が法律上当然に成立"]]}}},
  {id:10172,unit:'l_cooling',level:2,field:'law',text:'自ら売主の宅建業者が手付金等の保全措置が必要な場合（未完成物件）として正しいものはどれか。',opts:['代金の3%超','代金の5%超または1000万円超','代金の5%超かつ1000万円超','代金の10%超'],ans:1,exp:'未完成物件の場合、手付金等が「代金の5%超」または「1000万円超」のいずれかに該当する場合に保全措置が必要です（宅建業法41条）。完成物件は10%超または1000万円超が基準です。',"kaisetsu":{"topic": "クーリングオフ：告知日から8日以内・書面で・事務所では不可・全額返還", "basis": {"text": "クーリングオフは告知を受けた日から8日以内に書面で行います（宅建業法37条の2）。事務所・モデルルーム等での申込みはクーリングオフ不可。解除後業者は全額返還（費用控除不可）。", "example": ""}, "reason": {"text": "宅建業者が自ら売主として未完成物件を売却する場合、手付金等の保全措置が必要になる基準は「代金の5%超または1000万円超」です（宅建業法41条1項）。超えた場合は保全措置を講じなければ手付金等を受領できません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">クーリングオフのポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">告知日から8日以内</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">方法</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面（発信主義）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所での申込み</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">クーリングオフ不可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除後</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全額返還（費用控除不可）</text></svg>", "choices": [{"label": "代金の3%超", "reason": "3%超という基準はありません（宅建業法41条1項）。未完成物件の基準は5%超または1000万円超です。", "caution": "未完成物件の保全措置基準：代金の5%超または1000万円超（宅建業法41条1項）。"}, {"label": "代金の5%超かつ1000万円超", "reason": "「かつ」ではなく「または」が正しいです（宅建業法41条1項）。どちらか一方を超えれば保全措置が必要です。", "caution": "「5%超または1000万円超」。「かつ」ではなく「または」。"}, {"label": "代金の10%超", "reason": "10%超は完成物件の基準です（宅建業法41条の2第1項）。未完成物件は5%超が基準です（同法41条1項）。", "caution": ""}], "summary": {"head": ["手付金等の保全措置基準", "閾値"], "rows": [["未完成物件（宅建業法41条1項）", "代金の5%超または1000万円超"], ["完成物件（宅建業法41条の2第1項）", "代金の10%超または1000万円超"], ["超えた場合", "受領前に保全措置を講じなければ受領不可"]]}}},
  {id:10173,unit:'l_baikai',level:2,field:'law',text:'専任媒介契約を締結した宅建業者のレインズ登録義務として正しいものはどれか。',opts:['契約後5日以内','契約後7日以内','契約後14日以内','登録義務なし'],ans:1,exp:'専任媒介契約の場合、契約締結後7日以内にレインズへ登録しなければなりません（宅建業法34条の2第5項）。専属専任は5日以内、一般媒介は登録義務なしです。',"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任媒介の有効期間の上限は3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。専任は7日以内、専属専任は5日以内にレインズ登録が必要。業務報告は専任2週間に1回、専属専任1週間に1回。", "example": ""}, "reason": {"text": "専任媒介契約を締結した宅建業者は、契約締結の日から7日以内（休業日を除く）に指定流通機構（レインズ）に物件情報を登録しなければなりません（宅建業法34条の2第5項）。専属専任媒介は5日以内です（同条6項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">一般</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専任</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専属専任</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己発見取引</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">レインズ登録</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務報告</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">なし</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間に1回</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1週間に1回</text></svg>", "choices": [{"label": "契約後5日以内", "reason": "5日以内は専属専任媒介契約のレインズ登録期限です（宅建業法34条の2第6項）。専任媒介は7日以内です（同条5項）。", "caution": "専任媒介：7日以内。専属専任媒介：5日以内。"}, {"label": "契約後14日以内", "reason": "14日以内という規定はありません（宅建業法34条の2第5項・6項）。専任媒介は7日以内です。", "caution": ""}, {"label": "登録義務なし", "reason": "専任媒介契約ではレインズ登録が義務です（宅建業法34条の2第5項）。義務なしは一般媒介の扱いです。", "caution": ""}], "summary": {"head": ["レインズ登録期限", "期限（休業日除く）"], "rows": [["一般媒介", "義務なし"], ["専任媒介", "契約締結から7日以内（宅建業法34条の2第5項）"], ["専属専任媒介", "契約締結から5日以内（宅建業法34条の2第6項）"]]}}},
  {id:10174,unit:'l_jusetsu',level:2,field:'law',text:'重要事項説明書を電磁的方法で交付できる要件として正しいものはどれか。',opts:['宅建業者の判断のみで電子交付できる','相手方の承諾がある場合に電子交付できる','宅建士証の電子版提示が条件','国土交通省の認可が必要'],ans:1,exp:'重要事項説明書の電子交付は「相手方の承諾」がある場合に認められます（宅建業法35条8項）。相手方の承諾なく一方的に電子交付することはできません。',"kaisetsu":{"topic": "重要事項説明：宅建士が説明・売主への交付は不要・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主への交付義務はありません。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能です。", "example": ""}, "reason": {"text": "重要事項説明書（35条書面）の電磁的方法による交付は、相手方の承諾を得た場合に認められます（宅建業法35条8項・宅建業法施行規則16条の4の3）。宅建業者の判断のみで電子交付することはできません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "宅建業者の判断のみで電子交付できる", "reason": "相手方の承諾が必要です（宅建業法35条8項）。業者の判断のみでは電子交付できません。", "caution": "電子交付：相手方の承諾が必要（宅建業法35条8項）。"}, {"label": "宅建士証の電子版提示が条件", "reason": "電子交付の条件は宅建士証の電子版提示ではなく、相手方の承諾です（宅建業法35条8項）。", "caution": ""}, {"label": "国土交通省の認可が必要", "reason": "国土交通省の個別認可は不要です（宅建業法35条8項）。相手方の承諾で足ります。", "caution": ""}], "summary": {"head": ["35条書面の電子交付（宅建業法35条8項）", "内容"], "rows": [["要件", "相手方の承諾"], ["方法", "電磁的記録による提供"], ["37条書面", "同様に相手方承諾で電子交付可（宅建業法37条4項）"], ["IT重説", "別途一定要件が必要"]]}}},
  {id:10175,unit:'k_toshi',level:2,field:'limit',text:'市街化調整区域で開発許可が不要な場合として正しいものはどれか。',opts:['農林漁業者が建てる農業用倉庫','500㎡の住宅分譲地','工場の新設','一般住宅の建築'],ans:0,exp:'市街化調整区域においても、農林漁業者が農林漁業用の建物（農業用倉庫・農家住宅等）を建てる場合は開発許可が不要です（都市計画法29条1項2号）。',"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域での1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は市街化調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "市街化調整区域での開発行為は原則許可が必要ですが、農林漁業者が農業・林業・漁業用施設（農業用倉庫・農家住宅等）を建てるための開発行為は例外的に許可不要です（都市計画法29条1項2号）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化する区域</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可基準</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "500㎡の住宅分譲地", "reason": "住宅分譲は農林漁業用施設ではないため許可が必要です（都市計画法29条）。", "caution": "市街化調整区域での許可不要：農林漁業者の農業用施設等（都市計画法29条1項2号）。"}, {"label": "工場の新設", "reason": "工場の新設は農林漁業用施設ではなく許可が必要です（都市計画法29条）。", "caution": ""}, {"label": "一般住宅の建築", "reason": "農林漁業者以外の一般住宅は許可が必要です（都市計画法29条・34条）。", "caution": ""}], "summary": {"head": ["市街化調整区域での開発許可不要の例外（都市計画法29条1項）", "内容"], "rows": [["農林漁業者の農業用施設", "農業用倉庫・農家住宅等（同条1項2号）"], ["公益上必要な建築物", "鉄道施設・変電所等（同条1項3号）"], ["非常災害復旧", "災害応急措置に必要なもの（同条1項7号）"]]}}},
  {id:10176,unit:'k_kenchiku',level:2,field:'limit',text:'換地処分の公告があった翌日から生じる効果として正しいものはどれか。',opts:['換地は仮の土地とみなされる','換地は従前の土地とみなされ清算金も確定する','従前の土地の所有権が消滅する','借地権者の権利がすべて消滅する'],ans:1,exp:'換地処分の公告があった翌日から、換地は従前の土地とみなされ清算金も確定します（土地区画整理法104条）。',"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・道路斜線・用途制限", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。用途地域ごとに建築物の制限があります。", "example": ""}, "reason": {"text": "換地処分の公告があった翌日から、換地は従前の土地（換地前の土地）とみなされ（土地区画整理法104条1項）、清算金も確定し関係者の権利義務関係が整理されます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">第1種低層</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">学校は建築可</text></svg>", "choices": [{"label": "換地は仮の土地とみなされる", "reason": "換地処分の公告翌日から換地は従前の土地とみなされます（土地区画整理法104条1項）。「仮の土地」という扱いはありません。", "caution": "換地処分の公告翌日：換地＝従前の土地とみなされる（土地区画整理法104条1項）。"}, {"label": "従前の土地の所有権が消滅する", "reason": "換地処分の公告翌日から換地が従前の土地とみなされますが、所有権は換地に引き継がれます（土地区画整理法104条1項）。消滅するのではなく移転します。", "caution": ""}, {"label": "借地権者の権利がすべて消滅する", "reason": "借地権者の権利は換地上に存続します（土地区画整理法104条2項）。消滅しません。", "caution": ""}], "summary": {"head": ["換地処分の効果（土地区画整理法104条）", "内容"], "rows": [["換地処分の公告翌日", "換地は従前の土地とみなされる"], ["清算金", "確定"], ["権利の引継ぎ", "所有権・借地権等は換地上に継続"], ["換地処分の公告前", "建築制限等の適用（土地区画整理法76条）"]]}}},
  {id:10177,unit:'l_hoshu',level:2,field:'tax',text:'居住用財産の3000万円特別控除が適用されない場合はどれか。',opts:['居住しなくなった日から2年後の売却','一定要件を満たす取り壊し後の土地の売却','配偶者への売却','前年に同特例を使っていない場合の売却'],ans:2,exp:'3000万円特別控除は配偶者・直系血族など特別の関係にある者への売却には適用されません（租税特別措置法35条2項）。',"kaisetsu":{"topic": "報酬：売買は代金×3%+6万（400万超）・賃貸は借賃1か月・上限超過は不可", "basis": {"text": "売買媒介報酬（400万超）の一方からの上限は代金×3%+6万円（税別）。双方合計は一方上限×2。賃貸媒介（居住用・非居住用とも）は借賃1か月分。依頼者の承諾があっても上限超過は不可。", "example": ""}, "reason": {"text": "居住用財産の3000万円特別控除は配偶者・直系血族・同居の家族等への譲渡には適用されません（租税特別措置法35条2項2号）。近親者間の取引は実質的な売買でない場合があるためです。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対象</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（400万超）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万（一方）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（200万以下）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸（双方合計）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借賃1か月分</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">低廉な空家等（800万円以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円まで（説明・合意要）</text></svg>", "choices": [{"label": "居住しなくなった日から2年後の売却", "reason": "居住しなくなった日から3年目の年末までに売却した場合に特例が適用されます（租税特別措置法35条1項）。2年後は適用範囲内です。", "caution": "3000万円特別控除：居住しなくなった日から3年目の12月31日まで（租税特別措置法35条1項）。"}, {"label": "一定要件を満たす取り壊し後の土地の売却", "reason": "居住用建物を取り壊した後の土地の売却でも一定要件（取り壊しから1年以内の売却等）を満たせば特例が適用されます（租税特別措置法35条1項）。", "caution": ""}, {"label": "前年に同特例を使っていない場合の売却", "reason": "3000万円特別控除は前年に利用していなければ適用できます（租税特別措置法35条3項）。前年未使用であれば適用可能です。", "caution": ""}], "summary": {"head": ["3000万円特別控除の適用除外", "内容"], "rows": [["配偶者・直系血族への譲渡", "適用不可"], ["同居の家族への譲渡", "適用不可"], ["前年・前々年に本特例適用", "適用不可"], ["適用要件", "居住用財産の譲渡・居住期間等"]]}}},
  {id:10178,unit:'l_hosho',level:2,field:'rights',text:'保証人CはBの相殺権を援用できるかについて正しいものはどれか。',opts:['Cは相殺できないため満額払わなければならない','CはBの相殺権を援用して支払いを拒絶できる','Cには相殺権援用は認められない','連帯保証人のみに認められる'],ans:1,exp:'保証人は主債務者が債権者に対して有する相殺権を援用することができます（民法457条3項）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "保証人は主債務者が有する相殺権を援用して支払いを拒絶できます（民法457条2項）。主債務者の相殺権を保証人が代わりに行使することで、主債務者に代わり相殺の利益を享受できます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "Cは相殺できないため満額払わなければならない", "reason": "保証人Cは主債務者Bの相殺権を援用して支払いを拒絶できます（民法457条2項）。満額支払い義務はありません。", "caution": "保証人は主債務者の相殺権を援用できる（民法457条2項）。"}, {"label": "Cには相殺権援用は認められない", "reason": "民法457条2項により保証人は主債務者の相殺権を援用できます。「認められない」は誤りです。", "caution": ""}, {"label": "連帯保証人のみに認められる", "reason": "民法457条2項は保証人一般に適用され、普通保証人も主債務者の相殺権を援用できます。連帯保証人のみではありません。", "caution": ""}], "summary": {"head": ["保証人と主債務者の相殺権（民法457条2項）", "内容"], "rows": [["援用できるもの", "主債務者Bの相殺権"], ["拒絶の範囲", "相殺適状にある債権の範囲で支払いを拒絶可"], ["根拠", "民法457条2項"], ["目的", "保証人の保護・主債務消滅の反射的効果の享受"]]}}},
  {id:10179,unit:'r_chinshaku',level:2,field:'law',text:'自ら売主の宅建業者が受け取れる手付金の上限として正しいものはどれか。',opts:['代金の10%','代金の15%','代金の20%','上限なし'],ans:2,exp:'宅建業者が自ら売主の場合、手付金の額は代金の20%が上限です（宅建業法39条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "宅建業者が自ら売主として売買する場合の手付金の上限は代金の20%です（宅建業法39条1項）。これを超える部分の特約は無効となります（同条3項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "代金の10%", "reason": "手付金の上限は代金の20%です（宅建業法39条1項）。10%ではありません。", "caution": "手付金の上限＝代金の20%（宅建業法39条1項）。"}, {"label": "代金の15%", "reason": "手付金の上限は代金の20%です（宅建業法39条1項）。15%という規定はありません。", "caution": ""}, {"label": "上限なし", "reason": "宅建業者が自ら売主の場合、手付金は代金の20%が上限です（宅建業法39条1項）。上限なしではありません。", "caution": ""}], "summary": {"head": ["8種制限：手付の額の制限", "内容"], "rows": [["上限", "代金の20%（宅建業法39条1項）"], ["超過部分", "特約が無効（20%に制限）"], ["手付の性質", "解約手付（宅建業法39条2項）"], ["適用場面", "宅建業者自ら売主＋買主が宅建業者でない場合"]]}}},
  {id:10180,unit:'r_souzoku',level:2,field:'limit',text:'第一種低層住居専用地域で建築できるものはどれか。',opts:['大学','病院','高等学校','映画館'],ans:2,exp:'第一種低層住居専用地域では幼稚園・小学校・中学校・高等学校は建築できます（建築基準法別表第二）。大学・病院・映画館は不可です。',"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2", "basis": {"text": "配偶者と子の場合は各1/2（民法900条）。相続放棄は3か月以内に家庭裁判所へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2です（民法1042条）。遺産分割協議は全員合意が必要です。", "example": ""}, "reason": {"text": "第一種低層住居専用地域は最も規制が厳しい住居系用途地域で、低層住宅の良好な環境を守ります。高校は建築可能ですが、大学・病院・映画館等の大規模施設は建築できません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続の主要ポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子の相続分</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は法定相続分の1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割協議</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "大学", "reason": "大学は第一種低層住居専用地域では建築できません。大学は第一種中高層住居専用地域以上から認められます。", "caution": "第1低層：低層住宅・小中高校等のみ。大学・病院・映画館は不可。"}, {"label": "病院", "reason": "病院は第一種低層住居専用地域では建築できません。第二種住居地域以上から認められます。", "caution": ""}, {"label": "映画館", "reason": "映画館は近隣商業地域以上から認められます。第一種低層住居専用地域では建築できません。", "caution": ""}], "summary": {"head": ["施設", "建築可能な最低用途地域"], "rows": [["低層住宅・小中高校", "第一種低層住居専用地域"], ["大学・短大", "第一種中高層住居専用地域"], ["病院", "第二種住居地域"], ["映画館・カラオケ", "近隣商業地域"]]}}},
  {id:10181,unit:'r_saikensoron',level:2,field:'tax',text:'抵当権設定登記の登録免許税の課税標準として正しいものはどれか。',opts:['不動産の固定資産税評価額','不動産の時価','抵当権で担保される債権（ローン）の金額','不動産の相続税評価額'],ans:2,exp:'抵当権設定登記の課税標準は「担保される債権の金額（借入金額）」です（登録免許税法別表第一）。不動産の価額ではありません。',"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要です（民法446条2項）。連帯保証人には催告・検索の抗弁権がありません（民法454条）。債権譲渡の第三者対抗要件は確定日付ある証書による通知または承諾です（民法467条2項）。", "example": ""}, "reason": {"text": "抵当権設定登記の登録免許税の課税標準は「債権金額（ローンの金額）」です（登録免許税法別表第1）。税率は0.4%です。不動産の評価額を課税標準とするのは所有権移転登記（相続は0.4%・売買は2.0%）等です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相殺の要件</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">双方が同種の債権</text></svg>", "choices": [{"label": "不動産の固定資産税評価額", "reason": "抵当権設定登記の課税標準は固定資産税評価額ではなく「債権金額」です（登録免許税法別表第1）。", "caution": "抵当権設定登記の課税標準＝債権金額（固定資産税評価額ではない）。"}, {"label": "不動産の時価", "reason": "不動産の時価は課税標準になりません。抵当権設定登記は「債権金額」が課税標準です。", "caution": ""}, {"label": "不動産の相続税評価額", "reason": "相続税評価額は相続税の計算に使用しますが、登録免許税の課税標準ではありません。", "caution": ""}], "summary": {"head": ["登記の種類", "課税標準", "税率"], "rows": [["抵当権設定", "債権金額", "0.4%"], ["所有権移転（売買）", "固定資産税評価額", "2.0%（軽減あり）"], ["所有権移転（相続）", "固定資産税評価額", "0.4%"], ["所有権保存", "固定資産税評価額", "0.4%（軽減あり）"]]}}},
  {id:10182,unit:'l_baikai',level:2,field:'rights',text:'定期建物賃貸借の締結要件として正しいものはどれか。',opts:['公正証書で締結しなければならない','書面または電磁的記録で締結しなければならない','口頭でも成立する','期間は1年以上'],ans:1,exp:'定期建物賃貸借は書面または電磁的記録で締結しなければなりません（借地借家法38条1項）。公正証書は不要。期間1年未満でも設定できます。',"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任媒介の有効期間の上限は3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。専任は7日以内、専属専任は5日以内にレインズ登録が必要。業務報告は専任2週間に1回、専属専任1週間に1回。", "example": ""}, "reason": {"text": "定期建物賃貸借（定期借家）は書面または電磁的記録で締結しなければなりません（借地借家法38条1項）。公正証書は必須ではありません（公正証書が必須なのは事業用定期借地権です）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">一般</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専任</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専属専任</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己発見取引</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">レインズ登録</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務報告</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">なし</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間に1回</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1週間に1回</text></svg>", "choices": [{"label": "公正証書で締結しなければならない", "reason": "定期建物賃貸借に公正証書は必須ではありません（借地借家法38条1項）。書面（または電磁的記録）で足ります。", "caution": "定期借家：書面（公正証書不要）。事業用定期借地権：公正証書必須。"}, {"label": "口頭でも成立する", "reason": "定期建物賃貸借は書面または電磁的記録が必要です（借地借家法38条1項）。口頭では無効です。", "caution": ""}, {"label": "期間は1年以上", "reason": "定期建物賃貸借の期間に1年以上という最低期間の規定はありません（借地借家法38条1項）。1か月でも有効です。", "caution": ""}], "summary": {"head": ["定期建物賃貸借の要件（借地借家法38条）", "内容"], "rows": [["方式", "書面または電磁的記録"], ["公正証書", "不要（書面でよい）"], ["期間", "制限なし（1か月でも可）"], ["事前告知", "更新がない旨を別書面で事前に告知"]]}}},
  {id:10183,unit:'k_nochi',level:2,field:'law',text:'宅建業者への指示処分について正しいものはどれか。',opts:['国土交通大臣は知事免許業者には指示処分できない','指示処分違反で直ちに免許取り消し','国土交通大臣はすべての宅建業者に指示処分できる','指示処分は公告されない'],ans:2,exp:'国土交通大臣はすべての宅建業者（大臣免許・知事免許を問わず）に指示処分を行うことができます（宅建業法65条）。指示処分違反は業務停止処分となります。',"kaisetsu":{"topic": "農地法：3条は農業委員会・4条・5条は都道府県知事・市街化区域は届出のみ", "basis": {"text": "農地法3条（権利移動・農地→農地）の許可権者は農業委員会。4条（自己転用）・5条（転用目的の権利移動）は都道府県知事等。市街化区域内の農地転用（4・5条）は農業委員会への届出のみでOK。相続は許可不要・届出3か月以内。", "example": ""}, "reason": {"text": "国土交通大臣はすべての宅建業者（知事免許・大臣免許を問わず）に対して指示処分を行うことができます（宅建業法65条1項・3項）。これにより全国的な監督が可能になります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">市街化区域</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">特例なし</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text></svg>", "choices": [{"label": "国土交通大臣は知事免許業者には指示処分できない", "reason": "国交大臣は知事免許業者にも指示処分できます（宅建業法65条3項）。「できない」は誤りです。", "caution": "国交大臣：知事免許業者にも指示処分可（宅建業法65条3項）。"}, {"label": "指示処分違反で直ちに免許取り消し", "reason": "指示処分違反は業務停止処分の対象となりますが（宅建業法65条2項4号）、直ちに免許取消ではありません（宅建業法66条）。", "caution": ""}, {"label": "指示処分は公告されない", "reason": "指示処分は公告されます（宅建業法70条1項）。「公告されない」は誤りです。", "caution": ""}], "summary": {"head": ["指示処分の権限（宅建業法65条）", "内容"], "rows": [["知事", "その都道府県内の宅建業者に対して"], ["国交大臣", "すべての宅建業者に対して（宅建業法65条3項）"], ["公告", "処分した場合は公告義務あり（宅建業法70条1項）"]]}}},
  {id:10184,unit:'k_toshi',level:2,field:'limit',text:'防火地域と準防火地域にまたがる建物の制限として正しいものはどれか。',opts:['建物の過半が属する地域の制限が全体に適用','各部分が属する地域の制限がそれぞれ適用','防火地域の制限が建物全体に適用','準防火地域の制限が建物全体に適用'],ans:2,exp:'建物が防火地域と準防火地域にわたる場合、厳しい方（防火地域）の制限が建物全体に適用されます（建築基準法65条）。',"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域での1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は市街化調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "防火地域と準防火地域にまたがる建築物については、防火地域の制限（より厳しい制限）が建物全体に適用されます（建築基準法65条）。厳しい方の基準が全体に及ぶという原則です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化する区域</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可基準</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "建物の過半が属する地域の制限が全体に適用", "reason": "過半数の地域の制限ではなく、より厳しい防火地域の制限が全体に適用されます（建築基準法65条）。", "caution": "防火地域＋準防火地域にまたがる建物：防火地域の制限が全体に適用（建築基準法65条）。"}, {"label": "各部分が属する地域の制限がそれぞれ適用", "reason": "各部分で異なる制限を適用するのではなく、防火地域の制限が全体に適用されます（建築基準法65条）。", "caution": ""}, {"label": "準防火地域の制限が建物全体に適用", "reason": "準防火地域（緩い方）ではなく防火地域（厳しい方）の制限が全体に適用されます（建築基準法65条）。", "caution": ""}], "summary": {"head": ["防火地域・準防火地域にまたがる建物（建築基準法65条）", "適用される制限"], "rows": [["防火地域＋準防火地域", "防火地域の制限が全体に適用"], ["防火地域＋なし", "防火地域内の部分は防火地域の制限・他は制限なし"], ["原則", "厳しい方の制限が全体に及ぶ"]]}}},
  {id:10185,unit:'t_kotei',level:2,field:'tax',text:'印紙税について正しいものはどれか。',opts:['電子契約書には印紙税が課される','記載金額が1万円未満の契約書は非課税','建物賃貸借契約書は課税対象外','印紙税は地方税'],ans:1,exp:'記載金額が1万円未満の場合は非課税です（印紙税法別表第一）。電子契約は非課税。建物賃貸借契約書も課税対象。印紙税は国税です。',"kaisetsu":{"topic": "固定資産税：市町村が課す地方税・賦課期日は1月1日・評価替えは3年ごと", "basis": {"text": "固定資産税は市町村（東京23区は都）が課す地方税です（地方税法343条）。賦課期日は毎年1月1日。評価替えは3年ごと（基準年度）。住宅用地の特例：200㎡以下は課税標準1/6、超過部分は1/3。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">固定資産税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市町村（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賦課期日</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">評価替え</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年ごと</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅用地（200㎡以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税標準1/6</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10186,unit:'l_jusetsu',level:2,field:'rights',text:'連帯債務者の一人が相殺した場合の他の連帯債務者への影響として正しいものはどれか。',opts:['他の連帯債務者には影響しない','相殺額について他の連帯債務者の債務も消滅する','相殺した者の債務のみ消滅する','連帯債務に相殺は使えない'],ans:1,exp:'連帯債務者の一人が相殺した場合、その相殺額については他の連帯債務者の債務も消滅します（民法439条1項）。絶対的効力事由の一つです。',"kaisetsu":{"topic": "重要事項説明：宅建士が説明・売主への交付は不要・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主への交付義務はありません。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能です。", "example": ""}, "reason": {"text": "連帯債務において一人の連帯債務者が相殺を行った場合、相殺は絶対的効力を持ち、相殺額について他の連帯債務者の債務も消滅します（民法436条）。これは他の連帯債務者に有利な絶対効です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "他の連帯債務者には影響しない", "reason": "連帯債務における相殺は絶対的効力を持ち、他の連帯債務者にも影響します（民法436条）。「影響しない」は誤りです。", "caution": "連帯債務の相殺：絶対的効力（民法436条）→他の連帯債務者の債務も消滅。"}, {"label": "相殺した者の債務のみ消滅する", "reason": "相殺の絶対的効力により相殺額については全員の債務が消滅します（民法436条）。「相殺した者のみ」は誤りです。", "caution": ""}, {"label": "連帯債務に相殺は使えない", "reason": "連帯債務者の一人は自己の債権で相殺できますし（民法436条）、他の連帯債務者が相殺権を持っている場合も相殺を援用できます（同法439条1項）。", "caution": ""}], "summary": {"head": ["連帯債務の絶対的効力", "相対的効力"], "rows": [["弁済", "絶対的（全員消滅）"], ["相殺", "絶対的（民法436条）"], ["更改", "絶対的"], ["履行の請求", "相対的（2020年改正）"], ["免除", "相対的（2020年改正）"]]}}},
  {id:10187,unit:'l_menkyo',level:2,field:'law',text:'売買媒介（代金400万超）の報酬上限として正しいものはどれか。',opts:['依頼者合意で上限超えが可','一方から代金の3%+6万円（税別）が上限','賃貸と同じ計算式','双方合計で代金の3%+6万円が上限'],ans:1,exp:'売買媒介（400万超）の報酬上限は一方の依頼者から「代金×3%+6万円（税別）」です（宅建業法46条）。依頼者の同意があっても上限超えは不可。',"kaisetsu":{"topic": "宅建業の免許：知事・大臣免許の区別・有効期間5年・欠格事由", "basis": {"text": "1都道府県のみ→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間です。", "example": ""}, "reason": {"text": "売買・交換の媒介報酬の上限は代金の3%+6万円（税別）を一方の依頼者から受領できる金額の上限です（国土交通省告示）。速算式で計算すると400万円超の場合は代金×3%+6万円が上限です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（拘禁刑以上・特定罰金等）</text></svg>", "choices": [{"label": "依頼者合意で上限超えが可", "reason": "宅建業法上の報酬規定は強行規定であり、依頼者の合意があっても上限を超えることはできません（宅建業法46条）。", "caution": "報酬上限は強行規定（依頼者の合意でも超えられない）。"}, {"label": "賃貸と同じ計算式", "reason": "売買と賃貸では報酬計算式が異なります。賃貸は借賃の1か月分が上限、売買は代金の3%+6万円（速算式）が上限です。", "caution": ""}, {"label": "双方合計で代金の3%+6万円が上限", "reason": "一方の依頼者から3%+6万円、双方から合計すれば最大6%+12万円（税別）が上限です。「双方合計で3%+6万円」は誤りです。", "caution": "一方から：3%+6万円。双方合計：最大6%+12万円。"}], "summary": {"head": ["売買媒介の報酬上限（速算式）", "一方から受領できる上限"], "rows": [["200万円以下の部分", "5%"], ["200万超400万以下の部分", "4%"], ["400万超の部分", "3%"], ["速算式（400万超）", "代金×3%+6万円（+消費税）"]]}}},
  {id:10188,unit:'r_chinshaku',level:2,field:'rights',text:"賃借人Bが賃貸人Aの承諾を得て転貸した場合、転借人CはAとどのような関係にあるか。",opts:["AとCには直接の法律関係はない", "CはAに直接義務を負い、AはCに直接請求できる", "AはBにのみ請求でき、Cには直接請求できない", "CはAの承諾なく直接Aに賃料を払える"],ans:1,exp:`適法な転貸借が成立した場合、転借人Cは賃貸人Aに対して直接義務を負います（民法613条1項）。AはCに直接賃料請求等ができます。ただしその限度はBに対するAの債権の範囲内です。`,"kaisetsu":{"topic": "賃貸借：通常損耗は原状回復に含まれない・有益費は終了時に請求・賃料増額は正当事由が必要", "basis": {"text": "賃貸借終了時の原状回復義務に通常使用による損耗（壁の日焼け等）は含まれません（民法621条）。必要費は直ちに、有益費は終了時の請求が原則。更新拒絶には正当事由が必要（借地借家法28条）。", "example": ""}, "reason": {"text": "適法な転貸借（賃貸人の承諾あり）では、転借人は賃貸人に対して直接義務を負います（民法613条1項）。賃貸人は転借人に直接賃料請求等ができます。ただし賃貸人が請求できる額は賃料の低い方（賃料または転借料）が上限です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">賃貸借のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通常損耗</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原状回復に含まれない</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要費</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直ちに請求可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有益費</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸借終了時に請求</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">更新拒絶</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当事由が必要</text></svg>", "choices": [{"label": "AとCには直接の法律関係はない", "reason": "適法な転貸借では転借人CはAに対して直接義務を負います（民法613条1項）。直接の法律関係があります。", "caution": "適法転貸＝転借人は賃貸人に直接義務を負う（民法613条1項）。"}, {"label": "AはBにのみ請求でき、Cには直接請求できない", "reason": "適法な転貸借では賃貸人Aは転借人Cに直接賃料請求等ができます（民法613条1項）。", "caution": ""}, {"label": "CはAの承諾なく直接Aに賃料を払える", "reason": "CはAに直接賃料を支払う義務を負いますが（民法613条1項）、「承諾なく」という表現が誤解を招きます。Cの義務の上限は転借料の範囲です。", "caution": ""}], "summary": {"head": ["適法な転貸借", "法律関係"], "rows": [["A（賃貸人）とB（賃借人兼転貸人）", "原賃貸借契約継続"], ["B（賃借人）とC（転借人）", "転貸借契約"], ["A（賃貸人）とC（転借人）", "直接の義務関係（民法613条1項）"], ["Aの請求可能額", "賃料と転借料の低い方が上限"]]}}},
  {id:10189,unit:'r_saikensoron',level:2,field:'rights',text:"連帯債務者の一人Aに対して請求した場合、他の連帯債務者B・Cに対する時効の進行はどうなるか（2020年改正後）。",opts:["BとCに対しても時効が中断する", "BとCに対する時効の進行に影響しない", "BとCに対しても時効が完成する", "裁判でのみ影響する"],ans:1,exp:`2020年の民法改正後、連帯債務者の一人に対する請求は他の連帯債務者に対して更新・完成猶予の効力を生じなくなりました（相対効の原則）。つまりAへの請求はB・Cの時効に影響しません（民法441条）。`,"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要（民法446条2項）。連帯保証人は催告・検索の抗弁権なし（民法454条）。債権譲渡の第三者対抗は確定日付ある証書による通知・承諾（民法467条2項）。相殺の絶対的効力：弁済・更改・相殺。", "example": ""}, "reason": {"text": "2020年民法改正後、連帯債務者の一人に対する履行の請求は相対的効力となり、他の連帯債務者の時効の進行に影響しません（民法441条・438条）。改正前は絶対的効力（中断効）がありましたが改正で相対的効力に変更されました。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">催告・検索の抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text></svg>", "choices": [{"label": "BとCに対しても時効が中断する", "reason": "2020年改正後、連帯債務者の一人への請求は他の連帯債務者の時効に影響しません（民法441条）。「中断」（現在は「完成猶予」）効はありません。", "caution": "改正前：絶対的効力（中断）。改正後：相対的効力（影響なし）。"}, {"label": "BとCに対しても時効が完成する", "reason": "Aへの請求はBCの時効に影響しません（民法441条）。BとCの時効は各自の状況で進行します。", "caution": ""}, {"label": "裁判でのみ影響する", "reason": "改正後は裁判上の請求であってもAへの請求はBCの時効に影響しません（民法441条）。", "caution": ""}], "summary": {"head": ["連帯債務の絶対効・相対効（2020年改正）", "内容"], "rows": [["弁済（一人が全額支払い）", "絶対的効力（全員の債務が消滅）"], ["相殺", "絶対的効力（相殺した分だけ全員の債務減少）"], ["更改", "絶対的効力"], ["履行の請求", "相対的効力（他の連帯債務者に影響なし）→改正で変更"], ["時効の完成", "相対的効力"]]}}},
  {id:10190,unit:'r_souzoku',level:2,field:'rights',text:"相続の単純承認とみなされる（法定単純承認）ケースとして正しいものはどれか。",opts:["被相続人の死亡を知ってから6か月何もしなかった場合", "相続財産の一部を消費した場合", "相続財産の調査をした場合", "遺産分割協議に参加した場合"],ans:1,exp:`相続人が相続財産の全部または一部を消費（隠匿・費消等）した場合は法定単純承認とみなされます（民法921条）。相続財産を使ってしまうと限定承認・放棄ができなくなります。`,"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2・遺産分割は全員合意", "basis": {"text": "配偶者と子は各1/2（民法900条）。放棄は3か月以内に家裁へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2（民法1042条）。兄弟姉妹に遺留分はなし。遺産分割協議は全員合意が必要。", "example": ""}, "reason": {"text": "法定単純承認（民法921条）は相続人が一定の行為をした場合に単純承認したとみなす制度です。相続財産の一部を消費することは相続財産を処分する行為として法定単純承認に該当します（同条1号）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "被相続人の死亡を知ってから6か月何もしなかった場合", "reason": "熟慮期間（3か月）内に何もしなかった場合に単純承認とみなされます（民法921条2号）。6か月ではなく3か月です。", "caution": ""}, {"label": "相続財産の調査をした場合", "reason": "相続財産の調査は保存行為であり法定単純承認には該当しません（民法921条1号ただし書）。", "caution": ""}, {"label": "遺産分割協議に参加した場合", "reason": "遺産分割協議への参加自体は必ずしも法定単純承認とはなりません。ただし協議で財産を取得・処分する合意をすれば法定単純承認に該当する場合があります。", "caution": ""}], "summary": {"head": ["法定単純承認事由（民法921条）", "内容"], "rows": [["財産の処分", "相続財産の処分・消費（保存行為等を除く）（1号）"], ["熟慮期間内の不手続", "3か月内に承認・放棄の申述なし（2号）"], ["限定承認・放棄後の行為", "財産隠匿・私的消費・財産目録不記載（3号）"]]}}},
  {id:10191,unit:'l_baikai',level:2,field:'law',text:"宅建業者が媒介契約を締結した場合に交付する34条の2書面（媒介契約書）の記載事項として不要なものはどれか。",opts:["宅地建物の特定に必要な事項", "売買すべき価額またはその評価額", "媒介契約の有効期間", "近隣の飲食店情報"],ans:3,exp:`34条の2書面（媒介契約書）の記載事項は①物件特定事項②価額③有効期間④解除の要件⑤報酬額⑥指定流通機構への登録事項等が定められています（宅建業法34条の2）。近隣飲食店情報は記載不要です。`,"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任の有効期間は最長3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。レインズ登録は専任7日以内・専属専任5日以内。業務報告は専任2週間に1回・専属専任1週間に1回。", "example": ""}, "reason": {"text": "34条の2書面（媒介契約書）の必須記載事項は宅建業法34条の2第1項に列挙されています。「近隣の飲食店情報」は媒介契約書の記載事項ではありません。物件の特定・価格・有効期間等が必須です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">自己発見</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">レインズ</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専任</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専属専任</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text></svg>", "choices": [{"label": "宅地建物の特定に必要な事項", "reason": "物件の特定に必要な事項は34条の2書面の必須記載事項です（宅建業法34条の2第1項1号）。誤りではありません。", "caution": ""}, {"label": "売買すべき価額またはその評価額", "reason": "価額または評価額は34条の2書面の必須記載事項です（宅建業法34条の2第1項2号）。誤りではありません。", "caution": ""}, {"label": "媒介契約の有効期間", "reason": "有効期間は34条の2書面の必須記載事項です（宅建業法34条の2第1項6号）。誤りではありません。", "caution": ""}], "summary": {"head": ["34条の2書面の主な記載事項", "内容"], "rows": [["①", "物件の特定に必要な表示"], ["②", "価額または評価額"], ["③", "媒介契約の種類"], ["④", "有効期間・更新の方法"], ["⑤", "報酬額"], ["⑥", "指定流通機構への登録義務の有無"]]}}},
  {id:10192,unit:'l_sonota',level:2,field:'law',text:"宅建業者が自ら売主として新築住宅を販売した場合に義務付けられるものはどれか。",opts:["住宅性能評価書の交付", "住宅瑕疵担保保証金の供託または保険加入", "10年間の無償修繕義務", "第三者機関による検査"],ans:1,exp:`宅建業者が自ら売主として宅建業者以外の者に新築住宅を引き渡す場合、住宅販売瑕疵担保保証金の供託または住宅販売瑕疵担保責任保険への加入が義務付けられています（住宅瑕疵担保履行法11条）。`,"kaisetsu":{"topic": "宅建業者のその他の業務：従業者証明書・帳簿・業務処理原則", "basis": {"text": "全従業者に従業者証明書の交付が必要で業務中は常時携帯（宅建業法48条）。帳簿は事務所ごとに5年保存（自ら売主の新築住宅は10年）（同法49条）。宅建業者は信義誠実の原則に従って業務を行う必要があります（同法31条）。", "example": ""}, "reason": {"text": "宅建業者が自ら売主として新築住宅を販売する場合、住宅瑕疵担保保証金の供託または住宅瑕疵担保責任保険への加入が義務付けられています（住宅瑕疵担保履行法11条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業者のその他の義務</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従業者証明書</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全従業者に交付・業務中携帯</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">帳簿</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所ごと・5年保存（新築自ら売主は10年）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務処理原則</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">信義誠実の原則</text></svg>", "choices": [{"label": "住宅性能評価書の交付", "reason": "住宅性能評価書の交付は任意の制度です（品確法）。義務付けられているものではありません。", "caution": ""}, {"label": "10年間の無償修繕義務", "reason": "品確法95条の瑕疵担保責任は修補・損害賠償等の責任であり「無償修繕義務のみ」ではありません。", "caution": ""}, {"label": "第三者機関による検査", "reason": "第三者機関による検査（インスペクション等）は義務ではありません（任意）。", "caution": ""}], "summary": {"head": ["宅建業者の新築住宅販売時の義務", "内容"], "rows": [["資力確保措置", "供託または保険加入（住宅瑕疵担保履行法11条）"], ["瑕疵担保責任", "10年間（品確法95条1項）"], ["住宅性能評価", "任意"], ["インスペクション", "任意（実施有無の記載義務あり）"]]}}},
  {id:10193,unit:'k_kenchiku',level:2,field:'limit',text:"建築基準法の高さ制限（斜線制限）のうち、住居系用途地域で隣地との関係で建物の高さを制限するものはどれか。",opts:["道路斜線制限", "隣地斜線制限", "北側斜線制限", "日影規制"],ans:2,exp:`北側斜線制限は住居系用途地域（第一種・第二種低層住居専用地域、田園住居地域）において北側隣地の日照を確保するために建物の高さを制限するものです（建築基準法56条1項3号）。`,"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・用途制限・道路斜線", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。防火地域の耐火建築物は隣地境界線に外壁を接して建築可（同法65条）。", "example": ""}, "reason": {"text": "北側斜線制限は第一種・第二種低層住居専用地域および第一種・第二種中高層住居専用地域において、北側の隣地の日照を確保するために建物の高さを制限するものです（建築基準法56条1項3号）。住居系地域特有の制限です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">防火地域の耐火建築物</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">隣地境界線に接して建築可</text></svg>", "choices": [{"label": "道路斜線制限", "reason": "道路斜線制限は前面道路との関係で建物の高さを制限するものです（建築基準法56条1項1号）。隣地との関係ではありません。", "caution": "北側斜線制限：低層・中高層住居専用地域で北側の日照を確保（建築基準法56条1項3号）。"}, {"label": "隣地斜線制限", "reason": "隣地斜線制限は隣接地との関係で建物の高さを制限しますが（建築基準法56条1項2号）、用途地域を限定した住居専用地域の日照保護制限は北側斜線制限です。", "caution": ""}, {"label": "日影規制", "reason": "日影規制は冬至日の日影時間を制限するものです（建築基準法56条の2）。北側斜線制限とは異なる規制です。", "caution": ""}], "summary": {"head": ["高さ制限（斜線制限）の種類（建築基準法56条）", "内容"], "rows": [["道路斜線制限", "前面道路の境界線から斜線を設定（全用途地域）"], ["隣地斜線制限", "隣地境界線から斜線を設定（低層住居専用地域を除く）"], ["北側斜線制限", "北側の境界線から斜線を設定（低層・中高層住居専用地域）"]]}}},
  {id:10194,unit:'k_mori',level:2,field:'limit',text:"宅地造成等工事規制区域内で許可が必要な工事として正しいものはどれか。",opts:["高さ1メートルの盛土", "高さ2メートル超の崖を生じる切土", "高さ30センチの盛土", "敷地内の植栽工事"],ans:1,exp:`宅地造成等工事規制区域内では高さ2メートルを超える崖を生じる切土、高さ1メートルを超える崖を生じる盛土等の工事には都道府県知事の許可が必要です（盛土規制法12条）。`,"kaisetsu":{"topic": "盛土規制法・宅地造成：盛土は1m超・切土は2m超・特定盛土等規制区域", "basis": {"text": "盛土で高さ1mを超える崖を生じる場合は許可が必要（盛土規制法）。切土は2mを超える崖で許可が必要。特定盛土等規制区域内の一定規模以上の盛土等は許可が必要です。農地・森林も規制対象に含まれます。", "example": ""}, "reason": {"text": "宅地造成等工事規制区域内で許可が必要な工事の一つは高さ2m超の崖を生じる切土です（宅地造成及び特定盛土等規制法施行令3条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">盛土規制法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">工事種別</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可が必要な規模</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">切土</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">高さ2mを超える崖</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">盛土</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">高さ1mを超える崖</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">面積</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">500㎡超の宅地造成</text></svg>", "choices": [{"label": "高さ1メートルの盛土", "reason": "高さ1mの盛土は崖を生じなければ許可不要です（施行令3条）。", "caution": "許可対象：切土2m超の崖・盛土1m超の崖等（施行令3条）。"}, {"label": "高さ30センチの盛土", "reason": "高さ30cmの盛土は許可対象外です（施行令3条）。", "caution": ""}, {"label": "敷地内の植栽工事", "reason": "植栽工事は宅地造成工事ではなく許可不要です（施行令3条）。", "caution": ""}], "summary": {"head": ["許可が必要な工事（施行令3条）", "内容"], "rows": [["切土", "2m超の崖を生じるもの"], ["盛土", "1m超の崖を生じるもの"], ["面積", "500m2超"]]}}},
  {id:10195,unit:'t_joto',level:2,field:'tax',text:"不動産を5年超保有して売却した場合の所得税の取扱いとして正しいものはどれか。",opts:["総合課税で累進税率が適用される", "長期譲渡所得として所得税15%・住民税5%で分離課税される", "非課税である", "短期譲渡所得として所得税30%が適用される"],ans:1,exp:`不動産を売却した日の属する年の1月1日時点で保有期間が5年を超える場合、長期譲渡所得として所得税15%・住民税5%の合計20%の税率で申告分離課税されます（租税特別措置法31条）。`,"kaisetsu":{"topic": "譲渡所得：分離課税・長期は20%・3,000万円控除は3年に1回", "basis": {"text": "土地・建物の譲渡所得は分離課税。長期（5年超）は合計20%（所得税15%+住民税5%）。短期（5年以下）は39%（所得税30%+住民税9%）。3,000万円特別控除は前年・前々年に適用があれば使えません（3年に1回）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">譲渡所得のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税方式</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">分離課税</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">長期（5年超）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計20%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">短期（5年以下）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計39%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3,000万円控除</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年に1回の制限</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10196,unit:'r_tanpo',level:2,field:'rights',text:"質権と抵当権の最大の違いとして正しいものはどれか。",opts:["質権は不動産にのみ設定できる", "質権は目的物の占有を債権者に移すが、抵当権は移さない", "質権の方が抵当権より優先する", "抵当権には被担保債権の制限がない"],ans:1,exp:`質権（民法342条）は目的物の占有を質権者（債権者）に移す点が最大の特徴です。一方、抵当権は目的物の占有を移さず、設定者が引き続き使用・収益できます（民法369条）。`,"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権（民法369条）。質権は占有の移転が必要。先取特権は法定担保物権（当然に成立）。農地への抵当権設定自体は、通常、農地法3条の許可対象ではありません。", "example": ""}, "reason": {"text": "質権と抵当権の最大の違いは占有の移転の有無です。質権は目的物を債権者（質権者）に引き渡す必要がありますが（民法344条）、抵当権は設定者が目的物を使い続けることができます（民法369条）。住宅ローンで家に住みながら担保提供できるのは抵当権のためです。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "質権は不動産にのみ設定できる", "reason": "質権は動産・不動産・権利に設定できます（民法362条・356条・362条）。不動産のみではありません。", "caution": ""}, {"label": "質権の方が抵当権より優先する", "reason": "担保物権の優先順位は登記の先後（不動産の場合）等で決まります。質権が常に優先するわけではありません。", "caution": ""}, {"label": "抵当権には被担保債権の制限がない", "reason": "抵当権の被担保債権には一定の制限があります（不法行為債権を担保できるかどうか等）。「制限なし」は誤りです。", "caution": ""}], "summary": {"head": ["比較", "質権", "抵当権"], "rows": [["占有移転", "必要（民法344条）", "不要（設定者が使用継続）"], ["種類", "動産・不動産・権利", "不動産（原則）"], ["公示方法", "占有（引渡し）", "登記"], ["用途", "動産担保に多い", "不動産担保に多い"]]}}},
  {id:10197,unit:'l_menkyo',level:2,field:'law',text:"宅建業者でない者がその所有する宅地を宅建業者に媒介を依頼して売却した場合の法的関係として正しいものはどれか。",opts:["宅建業者が自ら売主となるため8種制限が適用される", "媒介業者のみに宅建業法の規制が適用される", "宅建業法の規制は一切適用されない", "売主にも宅建業の免許が必要"],ans:1,exp:`宅建業者でない者（一般の個人・法人）が自己所有の宅地を売却する場合、その者自身は宅建業者ではありません。媒介する宅建業者には宅建業法の規制が適用されますが、8種制限（手付・クーリングオフ等）は宅建業者が自ら売主の場合のみ適用されます。`,"kaisetsu":{"topic": "宅建業免許：知事・大臣免許の区別・有効期間5年・欠格事由は5年", "basis": {"text": "1都道府県→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間。2020年改正で成年被後見人の欠格条項は廃止。", "example": ""}, "reason": {"text": "宅建業法の規制は宅建業者の行為に対して適用されます。宅建業者でない売主が宅建業者に媒介を依頼した場合、媒介業者（宅建業者）には宅建業法の規制が適用されますが、宅建業者でない売主には8種制限等の宅建業者特有の規制は適用されません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（2020年改正で成年被後見人は廃止）</text></svg>", "choices": [{"label": "宅建業者が自ら売主となるため8種制限が適用される", "reason": "設問では宅建業者は媒介業者であり自ら売主ではありません。8種制限は宅建業者が自ら売主の場合に適用されます（宅建業法38条以下）。", "caution": "8種制限：宅建業者が自ら売主＋買主が宅建業者以外の場合に適用。"}, {"label": "宅建業法の規制は一切適用されない", "reason": "媒介業者である宅建業者には宅建業法の規制（重要事項説明義務・報酬規制等）が適用されます。", "caution": ""}, {"label": "売主にも宅建業の免許が必要", "reason": "自己所有の不動産を売却するだけなら免許は不要です（宅建業法2条2号）。繰り返し不特定多数に売買・交換・媒介代理を行う場合に免許が必要になります。", "caution": ""}], "summary": {"head": ["宅建業法の適用関係", "内容"], "rows": [["宅建業者が媒介", "媒介業者に重要事項説明・報酬規制等が適用"], ["宅建業者でない売主", "8種制限等の宅建業者特有の規制は適用なし"], ["8種制限の適用", "宅建業者が自ら売主＋買主が宅建業者以外"]]}}},
  {id:10198,unit:'k_toshi',level:2,field:'limit',text:"都市計画法の地域地区のうち、容積率の最高限度を定めることができるものはどれか。",opts:["防火地域", "風致地区", "高度利用地区", "高度地区"],ans:2,exp:`高度利用地区は土地の合理的な高度利用を図るため、容積率の最高・最低限度、建ぺい率の最高限度等を定めることができます（都市計画法9条19項）。`,"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域の1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "高度利用地区は用途地域内で容積率・建ぺい率・建築面積の最高・最低限度等を定め、土地の合理的かつ高度な利用を図る地区です（都市計画法9条19項）。容積率の最高限度を定めることができます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "防火地域", "reason": "防火地域は耐火建築物等を義務付ける地域であり、容積率の最高限度を定める地域ではありません（建築基準法61条）。", "caution": "高度利用地区：容積率の最高・最低限度を定める（都市計画法9条19項）。"}, {"label": "風致地区", "reason": "風致地区は都市の風致（景観・自然環境）を維持するための地域であり（都市計画法9条20項）、容積率の規定は主たる内容ではありません。", "caution": ""}, {"label": "高度地区", "reason": "高度地区は建物の高さの最高・最低限度を定める地区です（都市計画法9条18項）。容積率を定めるのは高度利用地区です。", "caution": ""}], "summary": {"head": ["地域地区と規制内容", "主な内容"], "rows": [["高度地区", "建物の高さの最高・最低限度（都市計画法9条18項）"], ["高度利用地区", "容積率・建ぺい率・建築面積の最高・最低（都市計画法9条19項）"], ["防火地域・準防火地域", "耐火・準耐火建築物等の義務"], ["特別用途地区", "用途地域の補完・制限の強化・緩和"]]}}},
  {id:10199,unit:'t_toroku',level:2,field:'tax',text:"登録免許税について正しいものはどれか。",opts:["不動産の取得時にのみ課税される", "登記の申請を行う者が納税義務者となる", "相続による所有権移転登記は非課税である", "抵当権設定登記の課税標準は不動産の評価額である"],ans:1,exp:`登録免許税は登記等を受ける者（登記申請者）が納税義務者です（登録免許税法3条）。抵当権設定の課税標準は債権金額（ローン金額）、所有権移転の課税標準は固定資産税評価額です。相続による移転も課税対象（税率0.4%）です。`,"kaisetsu":{"topic": "登録免許税：所有権移転登記等に課税・国税・税率は課税標準×一定率", "basis": {"text": "登録免許税は不動産の所有権移転登記等に課税される国税（登録免許税法1条）。税率は課税標準（通常は固定資産税評価額）×一定率で計算します。相続による所有権移転登記は0.4%、売買は2%が原則税率（軽減措置あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">登録免許税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">国（国税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税対象</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">所有権移転登記等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">0.4%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2%（軽減措置あり）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10200,unit:'r_souzoku',level:2,field:'rights',text:"遺産分割の方法として民法が定めていないものはどれか。",opts:["現物分割", "換価分割（売却して代金を分ける）", "代償分割（一人が取得して他に代償金を払う）", "くじ引き分割"],ans:3,exp:`民法が定める遺産分割の方法は現物分割・換価分割・代償分割の3種類です（民法906条等）。くじ引きによる分割は法定の方法ではありません。`,"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2・遺産分割は全員合意", "basis": {"text": "配偶者と子は各1/2（民法900条）。放棄は3か月以内に家裁へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2（民法1042条）。兄弟姉妹に遺留分はなし。遺産分割協議は全員合意が必要。", "example": ""}, "reason": {"text": "民法が定める遺産分割の方法は現物分割・換価分割・代償分割の3種類です（民法906条・907条参照）。くじ引き分割という方法は民法上定められていません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "現物分割", "reason": "現物分割は各相続人が具体的な財産を取得する方法で民法が認めています（民法906条参照）。", "caution": ""}, {"label": "換価分割（売却して代金を分ける）", "reason": "換価分割は遺産を売却して代金を分配する方法で実務上も活用されています（民法906条参照）。", "caution": ""}, {"label": "代償分割（一人が取得して他に代償金を払う）", "reason": "代償分割は一人が財産全体を取得し他の相続人に代償金を支払う方法で民法が認めています（民法906条の2参照）。", "caution": ""}], "summary": {"head": ["遺産分割の方法", "内容"], "rows": [["現物分割", "各自が具体的な財産を取得"], ["換価分割", "売却して代金を分配"], ["代償分割", "一人が全取得・他に代償金支払"], ["くじ引き分割", "民法上の規定なし"]]}}},
  {id:10201,unit:'r_ishi',level:2,field:'rights',text:"Aが自己の土地をBに売ると申し込み、Bの承諾前にAが死亡した。この場合の申込みの効力として正しいものはどれか。",opts:["申込みは失効する", "相続人がいれば申込みの効力は相続人に承継される", "相続人が承認した場合のみ有効", "承諾がない以上最初から無効"],ans:1,exp:`申込者が死亡した場合でも、申込者が反対の意思を表示していたか、相手方が死亡の事実を知っていた場合を除き、申込みの効力は失われません（民法526条）。相続人が申込みの効果を承継します。`,"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失保護）・通謀虚偽表示（無効・善意保護）。", "example": ""}, "reason": {"text": "契約の申込みは申込者が死亡しても原則として効力を失いません（民法526条）。これは取引の安全のためで、相手方が死亡を知らずに承諾した場合に契約が成立しないとすると不公平だからです。ただし申込者が反対意思を表示していた場合や相手方が死亡を知っていた場合は失効します。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "申込みは失効する", "reason": "原則として申込みは失効しません（民法526条）。申込者が反対の意思を表示していたか相手方が死亡を知っていた場合のみ失効します。", "caution": "申込みは死亡で当然失効するわけではありません。"}, {"label": "相続人が承認した場合のみ有効", "reason": "申込みの効力は相続人の承認なしに当然に承継されます（民法526条）。相続人の承認は不要です。", "caution": ""}, {"label": "承諾がない以上最初から無効", "reason": "承諾がないと契約は成立しませんが、申込み自体は有効に存続します（民法526条）。承諾がないことと申込みの有効性は別問題です。", "caution": ""}], "summary": {"head": ["申込みの失効事由", "内容"], "rows": [["原則", "申込者死亡・制限行為能力者になっても失効しない（民法526条）"], ["例外①", "申込者が反対の意思を表示していた場合は失効"], ["例外②", "相手方が死亡・能力喪失を知っていた場合は失効"], ["承諾の効果", "申込みに対して承諾があれば契約成立"]]}}},
  {id:10202,unit:'r_dairi',level:2,field:'rights',text:"双方代理が禁止される理由として正しいものはどれか。",opts:["代理人の仕事が二倍になるから", "一方の利益を優先すれば他方が不利益を受けるおそれがあるから", "代理報酬が二重取りになるから", "法律上の根拠がないから"],ans:1,exp:`双方代理（同一人が両当事者の代理人となること）は、一方の利益のために他方が不利益を受けるおそれがあるため原則禁止です（民法108条）。ただし債務の履行や本人があらかじめ許諾した行為は例外です。`,"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護します。", "example": ""}, "reason": {"text": "双方代理が禁止される理由は利益相反です（民法108条）。同一人が売主・買主双方を代理すると、一方に有利な条件は他方に不利になるため、公正な取引が困難になります。本人の利益保護のための規定です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "代理人の仕事が二倍になるから", "reason": "仕事量の問題は双方代理禁止の法的根拠ではありません。利益相反が禁止理由です（民法108条）。", "caution": ""}, {"label": "代理報酬が二重取りになるから", "reason": "報酬の二重取りは問題ですが、双方代理禁止の直接の理由は本人間の利益相反です（民法108条）。", "caution": ""}, {"label": "法律上の根拠がないから", "reason": "民法108条1項に双方代理・自己契約の禁止規定があります。法的根拠は存在します。", "caution": ""}], "summary": {"head": ["禁止行為", "禁止理由"], "rows": [["双方代理", "利益相反（一方への利益＝他方の不利益）"], ["自己契約", "利益相反（代理人と本人の利益が対立）"], ["例外", "本人の事前許諾・債務の履行"]]}}},
  {id:10203,unit:'r_jiko',level:2,field:'rights',text:"時効の完成猶予（旧法の停止）事由として正しいものはどれか。",opts:["内容証明郵便による催告", "貸主の死亡", "売買契約の締結", "物件の引渡し"],ans:0,exp:`催告をした場合、催告の時から6か月間は時効の完成が猶予されます（民法150条）。ただし催告は権利行使の意思を示すもので、裁判上の請求等と異なり更新効果はありません。`,"kaisetsu":{"topic": "消滅時効：知った時から5年または行使可能時から10年", "basis": {"text": "消滅時効は「知った時から5年」または「行使可能時から10年」のいずれか早い方で完成します（民法166条）。時効は援用して初めて効力が発生します（民法145条）。承認は更新事由です（民法152条）。", "example": ""}, "reason": {"text": "催告（書面・内容証明等）により時効の完成猶予が生じます（民法150条1項）。ただし催告のみでは更新にはならず、催告から6か月以内に裁判上の請求等をしなければ猶予の効力が消滅します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">期間</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人身損害</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年または20年</text></svg>", "choices": [{"label": "貸主の死亡", "reason": "貸主の死亡は時効の完成猶予事由ではありません（民法158条は相手方の能力等の場合を規定）。", "caution": ""}, {"label": "売買契約の締結", "reason": "売買契約の締結は時効の完成猶予事由ではありません（民法147条・150条等参照）。", "caution": ""}, {"label": "物件の引渡し", "reason": "物件の引渡しは時効の完成猶予事由ではありません。", "caution": ""}], "summary": {"head": ["完成猶予事由", "効果"], "rows": [["催告（民法150条）", "6か月間猶予（その間に訴訟提起等が必要）"], ["協議合意（民法151条）", "合意から1年または指定期間満了まで猶予"], ["裁判上の請求（民法147条）", "確定判決まで猶予→更新"], ["権利の承認（民法152条）", "更新（猶予なし）"]]}}},
  {id:10204,unit:'r_bukken',level:2,field:'rights',text:"動産の物権変動の対抗要件として正しいものはどれか。",opts:["登記", "公示送達", "引渡し（占有の移転）", "公証人の認証"],ans:2,exp:`動産の物権変動は引渡し（占有の移転）が対抗要件です（民法178条）。不動産の対抗要件は登記です（民法177条）。`,"kaisetsu":{"topic": "物権変動：登記が対抗要件・不法占拠者には登記不要", "basis": {"text": "不動産の物権変動は登記が第三者への対抗要件です（民法177条）。不法占拠者には登記なく対抗できます（判例）。建物賃借権は引渡しが対抗要件です（借地借家法31条）。", "example": ""}, "reason": {"text": "動産の物権変動の対抗要件は引渡し（占有の移転）です（民法178条）。不動産の対抗要件（登記）と対比して覚えることが重要です。動産には登記制度がないため、外観として誰もが認識できる占有（引渡し）を対抗要件としています。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">物権変動の対抗要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対抗要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">二重譲渡</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先に登記した者が優先</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不法占拠者</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記不要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物賃借権</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡し</text></svg>", "choices": [{"label": "登記", "reason": "登記は不動産物権変動の対抗要件です（民法177条）。動産には登記制度がありません。", "caution": "不動産＝登記、動産＝引渡し。この区別は宅建の最重要基礎知識です。"}, {"label": "公示送達", "reason": "公示送達は訴訟上の手続きであり、動産物権変動の対抗要件ではありません。", "caution": ""}, {"label": "公証人の認証", "reason": "公証人の認証は一部の法律行為の要式要件になりますが、動産物権変動の対抗要件ではありません。", "caution": ""}], "summary": {"head": ["目的物", "対抗要件", "根拠条文"], "rows": [["不動産", "登記", "民法177条"], ["動産", "引渡し（占有の移転）", "民法178条"], ["建物賃借権", "建物の引渡し", "借地借家法31条"]]}}},
  {id:10205,unit:'r_tanpo',level:2,field:'rights',text:"抵当不動産の第三取得者が抵当権消滅請求できる場合として正しいものはどれか。",opts:["第三取得者はいかなる場合も消滅請求できない", "抵当権者に相当の金額を提供することで消滅請求できる", "主債務者のみが消滅請求できる", "競売開始後のみ消滅請求できる"],ans:1,exp:`抵当不動産の第三取得者は、抵当権者に対して登記した各債権者に対し自ら評価した金額を提供して抵当権の消滅を請求できます（民法379条）。競売開始前に行使しなければなりません。`,"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権（民法369条）。質権は占有の移転が必要。先取特権は法定担保物権（当然に成立）。農地への抵当権設定自体は、通常、農地法3条の許可対象ではありません。", "example": ""}, "reason": {"text": "第三取得者（抵当不動産の所有者から取得した者）は抵当権消滅請求ができます（民法379条）。これは抵当権者に相当の金額を提供することで抵当権の消滅を求める制度で、競売されるよりも低い金額で抵当権を消滅させることができます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "第三取得者はいかなる場合も消滅請求できない", "reason": "第三取得者は抵当権消滅請求ができます（民法379条）。「いかなる場合もできない」は誤りです。", "caution": "第三取得者の保護手段：代価弁済（民法378条）と抵当権消滅請求（民法379条）。"}, {"label": "主債務者のみが消滅請求できる", "reason": "抵当権消滅請求は主債務者・保証人ではなく第三取得者が行う制度です（民法379条）。主債務者は抵当権消滅請求できません（同法380条）。", "caution": "主債務者・保証人→消滅請求不可。第三取得者→消滅請求可。"}, {"label": "競売開始後のみ消滅請求できる", "reason": "抵当権消滅請求は競売の申立て前に行います（民法379条）。競売開始後は原則としてできません。", "caution": ""}], "summary": {"head": ["第三取得者の保護手段", "内容"], "rows": [["代価弁済（民法378条）", "抵当権者の請求に応じて売買代金を弁済し消滅"], ["抵当権消滅請求（民法379条）", "相当額を申し出て消滅を請求（競売申立前に行う）"], ["できない者", "主債務者・保証人（民法380条）"]]}}},
  {id:10206,unit:'r_saikensoron',level:2,field:'rights',text:"債権者代位権（民法423条）の行使要件として正しいものはどれか。",opts:["債権者が自己の名義で債務者の権利を行使する", "債務者が無資力（資産不足）状態であることが要件", "債務者の同意が必要", "特定債権の場合は無資力要件が不要な場合もある"],ans:3,exp:`債権者代位権は原則として債務者の無資力（資産が債務を下回る状態）が要件ですが、特定債権の保全を目的とする場合（登記・登録等）は無資力要件が不要です（民法423条の7）。`,"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要（民法446条2項）。連帯保証人は催告・検索の抗弁権なし（民法454条）。債権譲渡の第三者対抗は確定日付ある証書による通知・承諾（民法467条2項）。相殺の絶対的効力：弁済・更改・相殺。", "example": ""}, "reason": {"text": "債権者代位権（民法423条）は原則として債務者の無資力が要件ですが、特定債権保全のために代位する場合（例：不動産の登記請求権の代位行使）は無資力要件が不要です（民法423条の7）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">催告・検索の抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text></svg>", "choices": [{"label": "債権者が自己の名義で債務者の権利を行使する", "reason": "債権者代位権は債権者が債務者の名において（債務者に代わって）債務者の権利を行使します。「自己の名義」ではありません。", "caution": "債権者代位権＝債権者が債務者の権利を「債務者に代わって」行使。"}, {"label": "債務者が無資力（資産不足）状態であることが要件", "reason": "原則として無資力が要件ですが（民法423条1項）、特定債権保全（登記請求権の代位等）は無資力不要です（民法423条の7）。「必ず要件」は誤りです。", "caution": ""}, {"label": "債務者の同意が必要", "reason": "債権者代位権は債務者の同意なく行使できます（民法423条1項）。", "caution": ""}], "summary": {"head": ["債権者代位権（民法423条）", "内容"], "rows": [["原則", "無資力要件あり（債権者を害する状態）"], ["例外（特定債権）", "無資力不要（例：不動産登記請求権の代位・民法423条の7）"], ["行使方法", "債務者に代わって行使（自己の名義ではない）"], ["債務者の同意", "不要"]]}}},
  {id:10207,unit:'r_baibai',level:2,field:'rights',text:"売主が種類・品質に関する契約不適合を知らせずに売却した場合、買主が行使できる権利として誤っているものはどれか。",opts:["修補請求", "代金減額請求", "解除", "即時の無効確認請求"],ans:3,exp:`契約不適合責任として買主が行使できる権利は①修補請求②代金減額請求③解除④損害賠償請求です（民法562〜564条）。「即時の無効確認請求」という手段は民法に規定がありません。`,"kaisetsu":{"topic": "売買：同時履行の抗弁権・解除は原則催告が必要・契約不適合責任", "basis": {"text": "売買では代金と引渡しは同時履行の関係（民法533条）。解除は原則として相当の期間を定めた催告後に行います（民法541条）。契約不適合責任の通知は知った時から1年以内（民法566条）。", "example": ""}, "reason": {"text": "契約不適合があった場合、買主は追完請求・代金減額請求・損害賠償請求・解除ができます（民法562条〜564条）。「即時の無効確認請求」は契約不適合責任の手段ではありません。無効確認は別途詐欺・錯誤等の要件が必要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">売買のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">同時履行</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金と引渡しは同時履行</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則として催告が必要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">契約不適合の通知</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から1年以内</text></svg>", "choices": [{"label": "修補請求", "reason": "修補請求（追完請求の一態様）は認められています（民法562条1項）。誤りではありません。", "caution": ""}, {"label": "代金減額請求", "reason": "代金減額請求は追完請求後に相当期間内に履行されない場合等に認められます（民法563条1項）。誤りではありません。", "caution": ""}, {"label": "解除", "reason": "追完不能・相当期間後も追完されない場合等に解除が認められます（民法564条・541条・542条）。誤りではありません。", "caution": ""}], "summary": {"head": ["契約不適合責任の手段", "根拠"], "rows": [["追完請求（修補・代替・不足分引渡し）", "民法562条"], ["代金減額請求", "民法563条（追完請求後が原則）"], ["損害賠償請求", "民法564条・415条"], ["解除", "民法564条・541条・542条"], ["無効確認請求", "契約不適合責任の手段ではない"]]}}},
  {id:10208,unit:'r_chinshaku',level:2,field:'rights',text:"賃貸人が賃借人に対して賃料増額請求をした場合の取扱いとして正しいものはどれか。",opts:["賃借人は増額請求を拒否できない", "増額に不服があれば賃借人は裁判所に相当額の確定を求めることができる", "増額が確定するまでは賃料を一切支払わなくてよい", "賃貸人は一方的に賃料を変更できる"],ans:1,exp:`賃料増額請求があった場合、合意できなければ裁判所に賃料の相当額の確定を求めることができます（借地借家法32条2項）。確定されるまでは相当額を支払えばよく、差額は確定後に利息付きで精算します。`,"kaisetsu":{"topic": "賃貸借：通常損耗は原状回復に含まれない・有益費は終了時に請求・賃料増額は正当事由が必要", "basis": {"text": "賃貸借終了時の原状回復義務に通常使用による損耗（壁の日焼け等）は含まれません（民法621条）。必要費は直ちに、有益費は終了時の請求が原則。更新拒絶には正当事由が必要（借地借家法28条）。", "example": ""}, "reason": {"text": "賃料増額請求があった場合、不服があれば裁判所に相当額の確定を求めることができます（借地借家法32条）。裁判所の判断が確定するまでの間、賃借人は相当と認める額を支払えば足ります。後に確定額が高ければ差額＋利息を支払います。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">賃貸借のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通常損耗</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原状回復に含まれない</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要費</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直ちに請求可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有益費</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸借終了時に請求</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">更新拒絶</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当事由が必要</text></svg>", "choices": [{"label": "賃借人は増額請求を拒否できない", "reason": "増額請求に不服があれば裁判所に相当額の確定を求めることができます（借地借家法32条）。一方的に拒否することはできませんが、裁判所の判断を求める権利があります。", "caution": ""}, {"label": "増額が確定するまでは賃料を一切支払わなくてよい", "reason": "増額の不服申立て中も相当と認める額（従前の賃料等）を支払う必要があります（借地借家法32条2項）。一切支払わなくてよいとはなりません。", "caution": ""}, {"label": "賃貸人は一方的に賃料を変更できる", "reason": "賃料の変更は当事者の合意または裁判所の判断によります（借地借家法32条）。賃貸人が一方的に決定できるわけではありません。", "caution": ""}], "summary": {"head": ["賃料増減額請求", "内容"], "rows": [["請求できる場合", "租税等の増減・経済事情の変動・周辺相場との乖離"], ["請求を受けた場合", "不服なら裁判所に相当額確定を申請可"], ["確定前の支払い", "相当と認める額を支払えばよい（借地借家法32条2項）"], ["確定後の精算", "確定額が多ければ差額＋年1割の利息を追加払い"]]}}},
  {id:10209,unit:'r_souzoku',level:2,field:'rights',text:"相続財産の管理と処分に関して、相続人が相続の承認・放棄を決める前の義務として正しいものはどれか。",opts:["相続財産を自由に処分できる", "固有財産と同一の注意をもって管理する義務がある", "相続財産を即時売却しなければならない", "管理義務はなく放置してよい"],ans:1,exp:`相続人は相続の承認・放棄をするまで、固有財産と同一の注意をもって相続財産を管理する義務があります（民法918条1項）。ただし相続放棄をした後は次順位の相続人や相続財産清算人に引き渡すまで管理義務が続きます。`,"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2・遺産分割は全員合意", "basis": {"text": "配偶者と子は各1/2（民法900条）。放棄は3か月以内に家裁へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2（民法1042条）。兄弟姉妹に遺留分はなし。遺産分割協議は全員合意が必要。", "example": ""}, "reason": {"text": "相続人は承認・放棄を決めるまでの間、相続財産を固有財産と同一の注意をもって管理する義務を負います（民法918条1項）。相続財産を勝手に処分すると法定単純承認とみなされる可能性があります。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "相続財産を自由に処分できる", "reason": "承認・放棄前の相続財産の処分は法定単純承認（民法921条1号）とみなされる可能性があります。自由に処分することはできません。", "caution": ""}, {"label": "相続財産を即時売却しなければならない", "reason": "即時売却の義務はありません。固有財産と同一の注意をもって管理する義務があります（民法918条1項）。", "caution": ""}, {"label": "管理義務はなく放置してよい", "reason": "相続人は承認・放棄を決めるまでの間、相続財産を管理する義務を負います（民法918条1項）。放置は管理義務違反になります。", "caution": ""}], "summary": {"head": ["承認・放棄前の管理義務", "内容"], "rows": [["管理義務", "固有財産と同一の注意をもって管理（民法918条1項）"], ["処分の制限", "財産の処分は法定単純承認とみなされる可能性あり"], ["保存行為", "保存行為は可能（民法921条1号ただし書）"]]}}},
  {id:10210,unit:'r_fuhoko',level:2,field:'rights',text:"不当利得（民法703条）の返還義務が生じる要件として誤っているものはどれか。",opts:["法律上の原因なく利益を受けたこと", "他人の損失によること", "利益と損失の因果関係", "不当利得者に故意・過失があること"],ans:3,exp:`不当利得の成立要件は①法律上の原因なく②他人の損失で③利益を受けたこと④損失と利益の因果関係です。受益者に故意・過失は不要です（民法703条）。悪意の場合は利息を付けて返還する等の義務が加重されます。`,"kaisetsu":{"topic": "不法行為：故意または過失が必要・使用者責任・工作物責任", "basis": {"text": "不法行為は故意または過失が必要です（民法709条）。使用者は被用者の職務上の不法行為について責任を負います（民法715条）。工作物の所有者は無過失責任（占有者が免責された場合）（民法717条）。", "example": ""}, "reason": {"text": "不当利得（民法703条）の成立要件は①法律上の原因なく利益を受けること、②他人の損失によること、③利益と損失の因果関係の3つです。故意・過失は要件ではありません。不法行為との大きな違いです。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不法行為のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般不法行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">故意または過失が必要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">使用者責任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">被用者への求償可（信義則上制限）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">工作物の所有者責任</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無過失責任（占有者が免責された場合）</text></svg>", "choices": [{"label": "法律上の原因なく利益を受けたこと", "reason": "これは不当利得の成立要件です（民法703条）。誤りではありません。", "caution": ""}, {"label": "他人の損失によること", "reason": "これは不当利得の成立要件です（民法703条）。誤りではありません。", "caution": ""}, {"label": "利益と損失の因果関係", "reason": "これは不当利得の成立要件です（民法703条）。誤りではありません。", "caution": ""}], "summary": {"head": ["不当利得の要件（民法703条）", "内容"], "rows": [["①法律上の原因なく", "契約・法律等の根拠なく"], ["②利益を受けた", "財産的利益の取得"], ["③他人の損失によること", "損失者との因果関係"], ["故意・過失", "不要（不法行為との違い）"]]}}},
  {id:10211,unit:'r_shakuchi',level:2,field:'rights',text:"定期借地権（一般定期借地）が普通借地権と最も異なる点はどれか。",opts:["存続期間が短い", "契約更新がなく期間満了で確定的に終了する", "地代が安い", "建物の用途に制限がある"],ans:1,exp:`一般定期借地権は50年以上の存続期間で、期間満了により更新なく確定的に終了します（借地借家法22条）。普通借地権は更新が原則で建物がある限り継続しますが、定期借地は更新がありません。`,"kaisetsu":{"topic": "借地権：最短30年・建物登記で対抗・建物滅失でも消滅せず・定期借地権は3種類", "basis": {"text": "普通借地権の最短存続期間は30年（借地借家法3条）。借地上の建物の自己名義登記が対抗要件（同法10条）。建物が滅失しても借地権は消滅しません。定期借地権は①一般（50年以上）②事業用（10〜50年未満）③建物譲渡特約（30年以上）の3種類。", "example": ""}, "reason": {"text": "一般定期借地権（借地借家法22条）は更新がなく期間満了で確定的に終了します。普通借地権は正当事由がなければ法定更新されますが、定期借地権は当初から更新なしで合意して設定されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">借地権のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">最短存続期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">対抗要件</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借地上の建物の自己名義登記</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物滅失</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借地権は消滅しない</text></svg>", "choices": [{"label": "存続期間が短い", "reason": "一般定期借地権は50年以上の存続期間が必要です（借地借家法22条）。普通借地権（最低30年）より長い場合が多く、「短い」は誤りです。", "caution": "一般定期借地権＝50年以上。普通借地権＝最低30年。"}, {"label": "地代が安い", "reason": "地代の水準は定期借地権か普通借地権かで決まるものではなく、市場等による合意によります。", "caution": ""}, {"label": "建物の用途に制限がある", "reason": "建物の用途制限があるのは事業用定期借地権（借地借家法23条）です。一般定期借地権には制限がありません。", "caution": "一般定期借地権＝用途制限なし。事業用定期借地権＝専ら事業用。"}], "summary": {"head": ["借地権の種類", "更新", "存続期間", "用途"], "rows": [["普通借地権", "正当事由なければ更新あり", "最低30年", "制限なし"], ["一般定期借地権", "更新なし（確定終了）", "50年以上", "制限なし"], ["事業用定期借地権", "更新なし", "10年以上50年未満", "専ら事業用"]]}}},
  {id:10212,unit:'r_kukku',level:2,field:'rights',text:"区分所有建物の大規模修繕工事（共用部分の重大変更）に必要な決議はどれか。",opts:["過半数決議", "4分の3以上の特別決議", "5分の4以上の特別決議", "全員の同意"],ans:1,exp:`共用部分の変更（重大変更）は区分所有者及び議決権の各4分の3以上の決議が必要です（区分所有法17条1項）。ただし形状・効用の著しい変更を伴わない軽微な変更は過半数でよいです。`,"kaisetsu":{"topic": "区分所有法：重大変更は3/4以上・建替えは4/5以上・管理組合法人は30人以上", "basis": {"text": "共用部分の重大変更は区分所有者・議決権の各3/4以上の特別決議が必要（区分所有法17条）。建替えは4/5以上（同法62条）。管理組合法人の設立は3/4以上かつ区分所有者30人以上（同法47条）。専有部分と共有持分は分離処分不可（同法15条）。", "example": ""}, "reason": {"text": "共用部分の重大変更（形状・効用の著しい変更）には区分所有者および議決権の各3/4以上の特別決議が必要です（区分所有法17条1項）。大規模修繕工事が重大変更に該当するかは工事内容によりますが、形状・効用の著しい変更を伴うものは3/4以上です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">区分所有法の決議要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">事項</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">普通決議</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">過半数</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">重大変更・規約変更</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3/4以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">管理組合法人</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3/4以上（30人以上）</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建替え</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4/5以上</text></svg>", "choices": [{"label": "過半数決議", "reason": "過半数は軽微変更の要件です（区分所有法18条1項）。重大変更（形状・効用の著しい変更）には3/4以上が必要です（同法17条1項）。", "caution": ""}, {"label": "5分の4以上の特別決議", "reason": "5/4以上は建替え決議の要件です（区分所有法62条1項）。重大変更は3/4以上です（同法17条1項）。", "caution": ""}, {"label": "全員の同意", "reason": "全員同意は不要です。重大変更は3/4以上で足ります（区分所有法17条1項）。", "caution": ""}], "summary": {"head": ["決議事項", "必要な賛成割合"], "rows": [["通常の管理行為（軽微変更）", "過半数"], ["重大変更（形状・効用の著しい変更）", "3/4以上"], ["規約変更", "3/4以上"], ["建替え", "4/5以上"]]}}},
  {id:10213,unit:'r_touki',level:2,field:'rights',text:"仮登記の効力として正しいものはどれか。",opts:["仮登記は本登記と同じ対抗力を持つ", "仮登記は順位保全の効力があり、本登記に移行すると仮登記の順位で本登記の効力が生じる", "仮登記後は第三者は登記申請できない", "仮登記は10年で失効する"],ans:1,exp:`仮登記には対抗力はありませんが順位保全効があります（不動産登記法105条・106条）。本登記に移行した場合は仮登記の順位が保全され、仮登記後の第三者に優先することができます。`,"kaisetsu":{"topic": "不動産登記：権利登記は共同申請・仮登記は順位保全・建物滅失は1か月以内", "basis": {"text": "権利に関する登記は原則として登記権利者と登記義務者が共同申請します（不動産登記法60条）。仮登記は順位保全機能があるが完全な対抗力は本登記後です。建物滅失登記の申請義務は1か月以内（同法57条）。", "example": ""}, "reason": {"text": "仮登記の本質は順位保全効です（不動産登記法105条・106条）。本登記の申請に必要な書類が揃わない場合等に仮登記をしておくことで、後日本登記した際にその仮登記の順位で効力が確定し、中間で行われた他の登記より優先されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産登記のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利登記</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則として共同申請</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮登記</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">順位保全（対抗力は本登記後）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物滅失登記</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1か月以内</text></svg>", "choices": [{"label": "仮登記は本登記と同じ対抗力を持つ", "reason": "仮登記単独では対抗力がありません。本登記後に仮登記の順位で対抗力が生じます（不動産登記法106条）。", "caution": "仮登記≠対抗力あり。"}, {"label": "仮登記後は第三者は登記申請できない", "reason": "仮登記があっても不動産の処分自体は禁止されません。ただし仮登記後の登記は本登記後に抹消されます（不動産登記法109条）。", "caution": ""}, {"label": "仮登記は10年で失効する", "reason": "仮登記に有効期限はありません。本登記に移行するまで効力が継続します。", "caution": ""}], "summary": {"head": ["仮登記の性質", "内容"], "rows": [["対抗力", "なし（単独では）"], ["順位保全効", "あり（本登記後に仮登記の順位で効力発生）"], ["中間処分", "本登記時に登記官が職権で抹消（不動産登記法109条）"], ["有効期限", "なし"]]}}},
  {id:10214,unit:'r_sorin',level:2,field:'rights',text:"囲繞地通行権（公道に至るための他の土地の通行権）について正しいものはどれか。",opts:["通行の目的・場所・方法は袋地所有者が自由に決められる", "囲んでいる土地の損害が最も少ない方法・場所で通行できる", "通行料は不要", "建物の建築のために自動車通行を認めなければならない"],ans:1,exp:`袋地の所有者は公道に至るために囲繞地を通行できますが、通行する場所・方法は囲繞地の損害が最も少ないものでなければなりません（民法211条1項）。一定の場合は通行料の支払いが必要です。`,"kaisetsu":{"topic": "相隣関係：竹木の根は自ら切除可・枝は原則所有者に・境界から50cmは慣習で変更可", "basis": {"text": "竹木の根が境界を越えたら自ら切除可（民法233条2項）。枝は原則として所有者に切除させます。建物の境界からの距離（50cm）は慣習・条例で変更可（民法234条・236条）。袋地通行権は有償が原則（民法212条）。", "example": ""}, "reason": {"text": "囲繞地通行権（民法210条）は袋地所有者が囲繞地を通行できる権利ですが、通行は囲繞地の損害が最も少ない方法・場所に限られます（民法211条1項）。自動車通行を認めるかどうかは必要性と損害の比較衡量で判断されます（判例）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相隣関係のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">事項</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">ルール</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">竹木の根（越境）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自ら切除可</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">竹木の枝（越境）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則：所有者に切除させる</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">境界距離（50cm）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">慣習・条例で変更可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">袋地通行権</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有償が原則</text></svg>", "choices": [{"label": "通行の目的・場所・方法は袋地所有者が自由に決められる", "reason": "損害が最も少ない方法・場所に制限されます（民法211条1項）。自由に決められるわけではありません。", "caution": ""}, {"label": "通行料は不要", "reason": "原則として損害に対する償金が必要です（民法212条）。「不要」は誤りです。", "caution": "通行料（償金）は原則必要（民法212条）。"}, {"label": "建物の建築のために自動車通行を認めなければならない", "reason": "自動車通行は必要性（袋地の利用状況等）と囲繞地の損害のバランスで判断されます（判例）。「必ず認めなければならない」は誤りです。", "caution": ""}], "summary": {"head": ["囲繞地通行権の内容", "内容"], "rows": [["通行の方法", "損害が最も少ない方法・場所（民法211条1項）"], ["自動車通行", "必要性と損害を比較衡量（判例）"], ["償金", "原則必要（民法212条）"], ["隣人の同意", "不要（法律上当然の権利）"]]}}},
  {id:10215,unit:'l_menkyo',level:2,field:'law',text:"宅建業者が事務所を増設した場合に必要な手続きとして正しいものはどれか。",opts:["新たに増設した事務所分の免許を別途取得する", "変更届と追加の営業保証金の供託または弁済業務保証金分担金の納付", "所轄警察署への届出", "税務署への届出のみ"],ans:1,exp:`事務所を増設した場合、免許権者への変更届（宅建業法9条）と増設分の営業保証金の供託（または保証協会の場合は分担金の追加納付）が必要です（宅建業法25条4項）。`,"kaisetsu":{"topic": "宅建業免許：知事・大臣免許の区別・有効期間5年・欠格事由は5年", "basis": {"text": "1都道府県→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間。2020年改正で成年被後見人の欠格条項は廃止。", "example": ""}, "reason": {"text": "宅建業者が事務所を増設した場合、変更の届出と追加の営業保証金の供託（または弁済業務保証金分担金の納付）が必要です（宅建業法25条・64条の9）。別途免許を取得する必要はありません（増設は変更届の対象）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（2020年改正で成年被後見人は廃止）</text></svg>", "choices": [{"label": "新たに増設した事務所分の免許を別途取得する", "reason": "事務所の増設は変更届の対象であり、別途免許を取得する必要はありません（宅建業法9条）。ただし2都道府県以上にまたがる場合は免許換えが必要です（同法7条）。", "caution": "事務所増設（同一都道府県内）＝変更届。2都道府県以上に＝免許換えが必要。"}, {"label": "所轄警察署への届出", "reason": "警察署への届出は宅建業法上の要件ではありません（宅建業法9条・25条）。", "caution": ""}, {"label": "税務署への届出のみ", "reason": "税務署への届出は宅建業法上の要件ではありません（宅建業法9条等）。", "caution": ""}], "summary": {"head": ["事務所増設の手続き", "内容"], "rows": [["変更届", "免許権者へ変更届出"], ["営業保証金", "追加の事務所ごとに500万円の供託が必要"], ["弁済業務保証金分担金", "保証協会加入者は追加納付"], ["免許換え", "2都道府県以上にまたがる場合は必要"]]}}},
  {id:10216,unit:'l_takkenshi',level:2,field:'law',text:"宅建士が業務停止処分を受けた場合の宅建士証の取扱いとして正しいものはどれか。",opts:["業務停止期間中も宅建士証を保持できる", "業務停止処分を受けたときはその期間中宅建士証を提出しなければならない", "業務停止処分は宅建士証に記載される", "業務停止処分中は宅建士証を書き換えなければならない"],ans:1,exp:`業務停止処分を受けた宅建士は、その期間中、登録している都道府県知事に宅建士証を提出しなければなりません（宅建業法22条の2第7項）。処分期間終了後に返還されます。`,"kaisetsu":{"topic": "専任宅建士：5人に1人以上・兼任不可・2週間以内に補充", "basis": {"text": "事務所には業務従事者5人に1人以上の専任宅建士が必要（宅建業法31条の3）。1社専属で複数業者の兼任は不可。不足時は2週間以内に補充が必要。案内所（申込み受付）にも専任宅建士が必要。", "example": ""}, "reason": {"text": "宅建士が事務禁止処分（業務停止処分）を受けた場合、処分期間中は宅建士証を登録している都道府県知事に提出しなければなりません（宅建業法22条の2第5項）。処分期間が終了すれば返還されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">専任宅建士のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">設置基準</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5人に1人以上</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">兼任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可（1社専属）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不足補充</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間以内</text></svg>", "choices": [{"label": "業務停止期間中も宅建士証を保持できる", "reason": "事務禁止処分中は宅建士証を知事に提出しなければなりません（宅建業法22条の2第5項）。保持できません。", "caution": "事務禁止処分中：宅建士証を知事に提出義務（宅建業法22条の2第5項）。"}, {"label": "業務停止処分は宅建士証に記載される", "reason": "業務停止処分が宅建士証に記載されるという規定はありません（宅建業法22条の2）。", "caution": ""}, {"label": "業務停止処分中は宅建士証を書き換えなければならない", "reason": "処分中に宅建士証を書き換えるという手続きはありません（宅建業法22条の2）。", "caution": ""}], "summary": {"head": ["事務禁止処分と宅建士証（宅建業法22条の2第5項）", "内容"], "rows": [["提出義務", "処分を受けた宅建士は期間中宅建士証を提出"], ["提出先", "登録している都道府県知事"], ["返還", "処分期間終了後に返還"], ["違反", "提出しない場合は罰則あり"]]}}},
  {id:10217,unit:'l_hosho',level:2,field:'law',text:"弁済業務保証金の還付請求ができる者として正しいものはどれか。",opts:["宅建業者同士の取引", "宅建業者以外の者で当該業者と宅建業に関する取引をした者", "全ての消費者", "宅建業者の従業員"],ans:1,exp:`弁済業務保証金から還付請求できるのは「宅建業者以外の者」であって当該宅建業者と「宅建業に関する取引をした者」です（宅建業法64条の8）。業者間取引や宅建業以外の取引は対象外です。`,"kaisetsu":{"topic": "営業保証金・保証協会：主1,000万・従500万/営業保証金vs分担金60万・30万", "basis": {"text": "営業保証金は主1,000万・従500万（宅建業法25条）。保証協会の分担金は主60万・従30万（同法64条の9）。還付対象は業者以外の取引した者。加入は任意。不足補充は通知後2週間以内。", "example": ""}, "reason": {"text": "弁済業務保証金から還付を受けられるのは、宅建業者以外の者（個人・法人）で宅建業に関する取引により損害を受けた者です（宅建業法64条の8第1項）。宅建業者間の取引は対象外です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">営業保証金と弁済業務保証金</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">営業保証金</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">弁済業務保証金（分担金）</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">主たる事務所</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000万円</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">60万円</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従たる事務所/所</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">500万円</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">還付対象</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者以外</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者以外</text></svg>", "choices": [{"label": "宅建業者同士の取引", "reason": "宅建業者間の取引は弁済業務保証金の還付対象外です（宅建業法64条の8第1項）。", "caution": "弁済業務保証金の還付：宅建業者以外が対象。宅建業者間は除外。"}, {"label": "全ての消費者", "reason": "消費者（個人）のみでなく、宅建業者以外の法人も対象です（宅建業法64条の8第1項）。「全ての消費者」は範囲が狭すぎます。", "caution": ""}, {"label": "宅建業者の従業員", "reason": "宅建業者の従業員は宅建業に関する取引をした者ではなく、雇用関係にある者であり還付対象ではありません（宅建業法64条の8第1項）。", "caution": ""}], "summary": {"head": ["弁済業務保証金の還付対象（宅建業法64条の8）", "内容"], "rows": [["還付対象", "宅建業者以外の者で宅建業に関し取引をした者"], ["除外", "宅建業者（宅建業者間取引は対象外）"], ["還付上限", "当該業者が供託すべき営業保証金の額"]]}}},
  {id:10218,unit:'l_baikai',level:2,field:'law',text:"専属専任媒介契約でのみ禁止される行為はどれか。",opts:["他の宅建業者に媒介を依頼すること", "依頼者が自ら発見した相手方と取引すること", "レインズへの登録", "業務処理状況の報告"],ans:1,exp:`専属専任媒介では依頼者が自ら発見した相手方との取引も禁止されますが（宅建業法34条の2第9項）、専任媒介では自己発見取引は可能です。他の業者への依頼禁止・レインズ登録・業務報告義務はいずれも専任・専属専任の両方に適用されます。`,"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任の有効期間は最長3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。レインズ登録は専任7日以内・専属専任5日以内。業務報告は専任2週間に1回・専属専任1週間に1回。", "example": ""}, "reason": {"text": "専属専任媒介契約では、依頼者（売主）が自ら発見した相手方との取引も宅建業者を通じて行わなければなりません（宅建業法34条の2第3項）。これが専任媒介と専属専任媒介の主な違いです。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">自己発見</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">レインズ</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専任</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専属専任</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text></svg>", "choices": [{"label": "他の宅建業者に媒介を依頼すること", "reason": "他の宅建業者への依頼禁止は専任媒介・専属専任媒介共通の特徴です（宅建業法34条の2第1項4号・3項）。専属専任のみの禁止ではありません。", "caution": "他業者への依頼禁止：専任・専属専任ともに共通。自己発見取引禁止：専属専任のみ。"}, {"label": "レインズへの登録", "reason": "レインズ登録は義務であり禁止されていません（宅建業法34条の2第5項・6項）。", "caution": ""}, {"label": "業務処理状況の報告", "reason": "業務報告は義務であり禁止されていません（宅建業法34条の2第9項・10項）。", "caution": ""}], "summary": {"head": ["専任媒介vs専属専任媒介の違い", "専任媒介", "専属専任媒介"], "rows": [["他業者への依頼", "禁止", "禁止"], ["自己発見取引", "可", "禁止"], ["レインズ登録", "7日以内", "5日以内"], ["業務報告", "2週間に1回", "1週間に1回"]]}}},
  {id:10219,unit:'l_jusetsu',level:2,field:'law',text:"区分所有建物の売買における重要事項説明の特有の記載事項として正しいものはどれか。",opts:["近隣住民の情報", "管理形態・管理会社・管理費・修繕積立金・大規模修繕の実施状況", "建物の建設工事費", "近隣の地価情報"],ans:1,exp:`区分所有建物（マンション等）の売買では通常の重要事項に加え、管理形態・管理会社・管理費・修繕積立金・大規模修繕計画等の管理に関する事項を説明しなければなりません（宅建業法35条1項6号）。`,"kaisetsu":{"topic": "重要事項説明：宅建士が説明・買主への交付・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主（貸主）は不要。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能。", "example": ""}, "reason": {"text": "区分所有建物の売買では通常の重要事項説明に加えて、管理形態・管理会社・管理費・修繕積立金・大規模修繕の実施状況等の区分所有特有の事項を説明しなければなりません（宅建業法35条1項6号・同法施行令3条等）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士のみ（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "近隣住民の情報", "reason": "近隣住民の情報は重要事項説明の必須記載事項ではありません（宅建業法35条1項）。", "caution": ""}, {"label": "建物の建設工事費", "reason": "建設工事費は重要事項説明の記載事項ではありません（宅建業法35条1項）。", "caution": ""}, {"label": "近隣の地価情報", "reason": "近隣の地価情報は重要事項説明の記載事項ではありません（宅建業法35条1項）。", "caution": ""}], "summary": {"head": ["区分所有建物の重要事項（宅建業法35条1項6号等）", "内容"], "rows": [["管理形態", "自主管理・委託管理の別"], ["管理費", "月額"], ["修繕積立金", "月額・積立残高"], ["大規模修繕", "実施予定・計画の有無"], ["管理規約", "規約案の概要"]]}}},
  {id:10220,unit:'l_37jo',level:2,field:'law',text:"37条書面への宅建士の記名に関して正しいものはどれか。",opts:["宅建業者の代表者が記名すればよい", "宅建士が記名しなければならないが押印は不要", "専任の宅建士でなければ記名できない", "宅建士証番号の記載も必須"],ans:1,exp:`37条書面には宅建士が記名しなければなりませんが、押印は2021年の改正により不要となりました（宅建業法37条3項）。専任の宅建士に限らず、その業者の宅建士であれば記名できます。`,"kaisetsu":{"topic": "37条書面：全取引で交付・記名（押印不要）・移転登記申請時期は必要的記載事項", "basis": {"text": "37条書面は全取引で契約の双方当事者に交付が義務（宅建業法37条）。引渡し時期・移転登記申請時期は必要的記載事項。2021年改正で押印は不要、記名のみで足ります。", "example": ""}, "reason": {"text": "37条書面は宅建士が記名しなければなりません（宅建業法37条3項）。2022年の法改正により押印は不要となりました（電磁的記録の場合は電子署名）。専任の宅建士でなくても記名できます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付義務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全取引・双方当事者</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡時期・移転登記申請時期等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要）</text></svg>", "choices": [{"label": "宅建業者の代表者が記名すればよい", "reason": "37条書面の記名は宅建士が行います（宅建業法37条3項）。代表者でも宅建士でなければ不可です。", "caution": "37条書面の記名：宅建士（宅建業法37条3項）。"}, {"label": "専任の宅建士でなければ記名できない", "reason": "専任の宅建士でなくても記名できます（宅建業法37条3項）。同法の宅建士資格があれば足ります。", "caution": ""}, {"label": "宅建士証番号の記載も必須", "reason": "宅建士証番号は37条書面の必須記載事項ではありません（宅建業法37条）。", "caution": ""}], "summary": {"head": ["37条書面の記名（宅建業法37条3項）", "内容"], "rows": [["記名者", "宅建士（専任の宅建士でなくても可）"], ["押印", "2022年改正で不要"], ["電磁的記録", "宅建士の電子署名が必要"], ["35条書面との共通点", "両者ともに宅建士の記名が必要"]]}}},
  {id:10221,unit:'l_kokoku',level:2,field:'law',text:"宅建業法上の誇大広告禁止が適用される媒体として正しいものはどれか。",opts:["新聞・チラシのみ", "インターネット広告は対象外", "新聞・テレビ・インターネット等あらゆる媒体", "口頭による説明のみ"],ans:2,exp:`誇大広告禁止は「広告」に適用され、新聞・雑誌・テレビ・インターネット・チラシ等あらゆる媒体が対象です（宅建業法32条）。口頭による説明は別途不当な勧誘行為の禁止規定が適用されます。`,"kaisetsu":{"topic": "宅建業者の広告：開発許可後に広告可・誇大広告は全媒体禁止・取引態様は広告時と注文時両方", "basis": {"text": "開発許可・建築確認後（工事中でも）広告できます（宅建業法33条）。誇大広告禁止は全媒体・全対象者に適用（同法32条）。取引態様は広告時と注文受領時の両方で明示が必要（同法34条）。", "example": ""}, "reason": {"text": "誇大広告禁止（宅建業法32条）はすべての媒体に適用されます。新聞・チラシだけでなくテレビ・ラジオ・インターネット（SNS含む）等あらゆる広告媒体が対象です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">広告規制のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">広告開始時期</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築確認・開発許可後</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誇大広告禁止</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">媒体・対象問わず</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取引態様の明示</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">広告時と注文時の両方</text></svg>", "choices": [{"label": "新聞・チラシのみ", "reason": "新聞・チラシだけでなくすべての広告媒体が対象です（宅建業法32条）。", "caution": "誇大広告禁止：あらゆる媒体（宅建業法32条）。"}, {"label": "インターネット広告は対象外", "reason": "インターネット広告も対象です（宅建業法32条）。「対象外」は誤りです。", "caution": ""}, {"label": "口頭による説明のみ", "reason": "口頭説明は広告ではなく重要事項説明等の問題であり、誇大広告禁止の「広告」は主に媒体を通じたものです（宅建業法32条）。", "caution": ""}], "summary": {"head": ["誇大広告禁止の対象媒体", "内容"], "rows": [["新聞・チラシ・折込", "対象"], ["テレビ・ラジオ", "対象"], ["インターネット・SNS", "対象"], ["看板・ポスター", "対象"]]}}},
  {id:10222,unit:'l_cooling',level:2,field:'law',text:"クーリングオフの意思表示の効力発生時期として正しいものはどれか。",opts:["業者が書面を受け取った時", "買主が書面を発送した時（発信主義）", "書面が業者に到達した翌日", "裁判所が確認した時"],ans:1,exp:`クーリングオフによる解除の意思表示は書面を発送した時点で効力が生じます（発信主義）（宅建業法37条の2第2項）。通常の解除は到達主義ですが、クーリングオフは例外として発信主義が適用されます。`,"kaisetsu":{"topic": "クーリングオフ：告知日から8日以内・書面で・事務所では不可・全額返還", "basis": {"text": "クーリングオフは告知を受けた日から8日以内に書面で行います（宅建業法37条の2）。事務所・モデルルーム等での申込みはクーリングオフ不可。解除後業者は全額返還（費用控除不可）。", "example": ""}, "reason": {"text": "クーリングオフの意思表示は書面を「発した時」（発信主義）に効力が生じます（宅建業法37条の2第2項）。書面が業者に到達した時点ではなく、買主が郵送等した時点で有効です。これにより買主の権利行使が確実に保護されます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">クーリングオフのポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">告知日から8日以内</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">方法</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面（発信主義）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所での申込み</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">クーリングオフ不可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除後</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全額返還</text></svg>", "choices": [{"label": "業者が書面を受け取った時", "reason": "到達主義ではなく発信主義です（宅建業法37条の2第2項）。業者が受け取った時点ではありません。", "caution": "クーリングオフは発信主義（宅建業法37条の2第2項）。"}, {"label": "書面が業者に到達した翌日", "reason": "発信主義（宅建業法37条の2第2項）であり、到達した翌日ではありません。", "caution": ""}, {"label": "裁判所が確認した時", "reason": "裁判所の確認は不要です（宅建業法37条の2第2項）。発信主義により書面を発した時に効力が生じます。", "caution": ""}], "summary": {"head": ["クーリングオフの効力発生（発信主義）", "内容"], "rows": [["根拠", "宅建業法37条の2第2項"], ["効力発生時期", "書面を「発した時」（発送した時）"], ["発信主義の効果", "8日目に発送すれば8日以内の行使として有効"], ["通常の意思表示", "到達主義（民法97条1項）との違い"]]}}},
  {id:10223,unit:'l_hoshu',level:2,field:'law',text:"居住用建物の賃貸借で、借主の承諾がある場合、貸主から依頼を受けた業者の報酬について正しいものはどれか。",opts:["借主の承諾があれば借主から借賃の1か月分まで受け取れる", "借主から追加で0.5か月分を受け取れる", "貸主からのみ報酬を受け取れる", "合計で借賃の2か月分を受け取れる"],ans:0,exp:`居住用建物の賃貸借で貸主・借主双方から合計借賃の1か月分が上限です。貸主のみから依頼を受けた場合、原則として借主から受け取れる報酬は0（貸主から最大1か月分）ですが、借主の承諾があれば借主からも受け取れます（合計上限は1か月分変わらず）。`,"kaisetsu":{"topic": "報酬：売買は代金×3%+6万（400万超）・賃貸は借賃1か月・上限超過は不可", "basis": {"text": "売買（400万超）の一方からの上限は代金×3%+6万。双方合計は一方上限×2。賃貸（居住用・非居住用とも）は借賃1か月分。低廉な空家等（800万円以下）は、媒介報酬について原則の報酬額を超えて30万円（税別）まで受領できる場合があります（依頼者への説明・合意が必要）。", "example": ""}, "reason": {"text": "居住用建物の賃貸借媒介の場合、依頼者双方（貸主・借主）から合計して借賃の1か月分（税別）が上限です（告示）。居住用建物では各依頼者から受ける報酬は原則として借賃の0.5か月分以内ですが、依頼者の承諾がある場合は一方から1か月分まで受け取れます。ただし貸主・借主双方から受ける報酬の合計上限は借賃1か月分です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対象</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（400万超）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万（一方）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（200万以下）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸（双方合計）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借賃1か月分</text></svg>", "choices": [{"label": "借主から追加で0.5か月分を受け取れる", "reason": "設問の選択肢1（借主から1か月分）が正解であれば、合計が1か月分を超える追加受領はできません（告示）。", "caution": "双方合計で1か月分が上限（告示）。"}, {"label": "貸主からのみ報酬を受け取れる", "reason": "借主からも報酬を受け取れます（告示）。「貸主からのみ」は誤りです。", "caution": ""}, {"label": "合計で借賃の2か月分を受け取れる", "reason": "双方合計で1か月分が上限です（告示）。2か月分は誤りです。", "caution": ""}], "summary": {"head": ["居住用建物賃貸借の報酬（告示）", "内容"], "rows": [["双方合計の上限", "借賃の1か月分（税別）"], ["原則の割り振り", "各0.5か月分"], ["承諾がある場合", "一方から1か月分も可（双方合計1か月分の範囲内）"], ["居住用以外", "同様に双方合計1か月分"]]}}},
  {id:10224,unit:'l_kantoku',level:2,field:'law',text:"免許取消処分の必要的取消し事由（必ず取り消される場合）に該当するものはどれか。",opts:["業務停止命令違反", "営業保証金の供託遅延", "不正な手段で免許を取得した場合", "報酬に関する規定違反"],ans:2,exp:`不正な手段で免許を取得した場合は必要的取消し（必ず免許を取り消さなければならない）事由です（宅建業法66条1項8号）。業務停止命令違反や営業保証金の供託遅延は任意的取消し等の対象です。`,"kaisetsu":{"topic": "監督処分：業務停止最長1年・大臣は全業者に指示可・指示違反→業務停止", "basis": {"text": "業務停止の最長期間は1年（宅建業法65条2項）。大臣は全業者（知事免許含む）に指示処分を行う権限があります。指示処分違反→業務停止、業務停止違反→免許取消という段階があります。", "example": ""}, "reason": {"text": "免許の必要的取消し事由（必ず取り消さなければならない）は宅建業法66条1項に列挙されています。不正手段による免許取得は必要的取消し事由の筆頭です（同条1項1号）。業務停止命令違反も必要的取消しですが（同条1項9号）、設問の正解は「不正手段で免許取得」です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">監督処分のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">処分</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">最長1年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣の権限</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全業者に指示可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">指示処分違反</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止の対象</text></svg>", "choices": [{"label": "業務停止命令違反", "reason": "業務停止処分違反も必要的取消し事由ですが（宅建業法66条1項9号）、設問の正解は「不正手段で免許取得」（同条1項1号）です。", "caution": "不正手段による免許取得：必要的取消し（宅建業法66条1項1号）。"}, {"label": "営業保証金の供託遅延", "reason": "営業保証金の供託遅延は任意的取消しの対象にはなりますが（宅建業法65条・66条）、必要的取消し事由に明示されていません。", "caution": ""}, {"label": "報酬に関する規定違反", "reason": "報酬規定違反は業務停止処分の対象となりますが（宅建業法65条2項）、必要的取消し事由ではありません（宅建業法66条1項参照）。", "caution": ""}], "summary": {"head": ["必要的免許取消し事由（宅建業法66条1項）", "内容"], "rows": [["不正手段による免許取得", "1号"], ["役員等が欠格事由に該当", "2号・3号"], ["業務停止処分違反", "9号"], ["任意的取消し", "一定の違反行為（宅建業法66条2項）"]]}}},
  {id:10225,unit:'k_toshi',level:2,field:'limit',text:"第一種住居地域の建物制限として正しいものはどれか。",opts:["工場は一切建築できない", "床面積3000平方メートル以下の店舗は建築できる", "ナイトクラブは建築できる", "大型ショッピングモール（床面積1万平方メートル超）は建築できる"],ans:1,exp:`第一種住居地域では床面積3000平方メートル以下の店舗・飲食店等を建築できます（建築基準法別表第二）。ナイトクラブ・大型商業施設は建築できません。`,"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域の1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "第一種住居地域では床面積3000㎡以下の店舗・事務所・ホテル等は建築できます（建築基準法別表第二）。大規模商業施設（1万㎡超等）や風俗施設は建築できません。一般工場は許可を受ければ建築可能な場合があります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "工場は一切建築できない", "reason": "第一種住居地域でも危険性・環境悪化の恐れが少ない工場は建築できます（建築基準法別表第二）。「一切不可」は誤りです。", "caution": "第一種住居地域：床面積3000㎡以下の店舗等は可（建築基準法別表第二）。"}, {"label": "ナイトクラブは建築できる", "reason": "ナイトクラブ等の風俗施設は住居専用地域・住居地域では建築できません（建築基準法別表第二）。", "caution": ""}, {"label": "大型ショッピングモール（床面積1万平方メートル超）は建築できる", "reason": "第一種住居地域では床面積3000㎡を超える店舗は建築できません（建築基準法別表第二）。", "caution": ""}], "summary": {"head": ["第一種住居地域で建築できるもの（建築基準法別表第二）", "規模"], "rows": [["住宅・共同住宅", "制限なし"], ["店舗・事務所・ホテル", "床面積3000㎡以下"], ["工場（危険性少）", "一定規模以下は可"], ["大規模商業施設", "不可（3000㎡超）"], ["ナイトクラブ等", "不可"]]}}},
  {id:10226,unit:'k_kenchiku',level:2,field:'limit',text:"容積率算定の際に延べ面積から除外できる部分として正しいものはどれか。",opts:["屋上の物干し場", "共同住宅の共用廊下・階段", "地階の倉庫", "バルコニー"],ans:1,exp:`共同住宅の共用廊下・階段の床面積は容積率算定の基礎となる延べ面積に算入しません（建築基準法52条6項）。住宅の地下室（延べ面積の3分の1以内）も不算入の特例があります。`,"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・用途制限・道路斜線", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。防火地域の耐火建築物は隣地境界線に外壁を接して建築可（同法65条）。", "example": ""}, "reason": {"text": "共同住宅の共用廊下・共用階段の床面積は容積率計算の基礎となる延べ面積から除外されます（建築基準法52条6項）。これは共用部分の有無による不公平をなくすための規定です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">防火地域の耐火建築物</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">隣地境界線に接して建築可</text></svg>", "choices": [{"label": "屋上の物干し場", "reason": "屋上の物干し場は容積率の計算から除外される特別規定はありません（建築基準法52条）。", "caution": "共同住宅の共用廊下・階段：容積率から除外（建築基準法52条6項）。"}, {"label": "地階の倉庫", "reason": "地階の倉庫は一般的には容積率の計算に算入されます（建築基準法52条）。住宅用地下室（1/3まで）等の特例とは異なります。", "caution": ""}, {"label": "バルコニー", "reason": "バルコニーは容積率の計算から除外される特別規定はありません（ただし1m以内の外壁からの突出は床面積に不算入）。", "caution": ""}], "summary": {"head": ["容積率から除外される部分（建築基準法52条）", "根拠"], "rows": [["共同住宅の共用廊下・共用階段", "52条6項"], ["自動車車庫", "1/5まで（52条3項）"], ["住宅の地下室", "1/3まで（52条3項）"], ["宅配ボックス", "一定面積（52条3項）"]]}}},
  {id:10227,unit:'k_nochi',level:2,field:'limit',text:"農地法の適用を受けない場合として正しいものはどれか。",opts:["農地の売買", "農地の贈与", "農地から非農地への転用", "農地の耕作方法の変更"],ans:3,exp:`農地の耕作方法の変更（どのような作物を育てるか等）は農地法の規制を受けません。農地の権利移動（売買・贈与等）は農地法3条、転用は4条・5条の規制対象です。`,"kaisetsu":{"topic": "農地法：3条は農業委員会・4・5条は都道府県知事・市街化区域は届出のみ", "basis": {"text": "農地法3条の許可権者は農業委員会。4・5条は都道府県知事等。市街化区域の農地転用（4・5条）は農業委員会への届出のみOK。相続は許可不要・3か月以内の農業委員会への届出が必要。", "example": ""}, "reason": {"text": "農地法は農地・採草放牧地の権利移動・転用等を規制します。農地の耕作方法の変更は農地法の規制対象外です（農地法2条・3条・4条・5条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text></svg>", "choices": [{"label": "農地の売買", "reason": "農地の売買（農地のまま）は農地法3条の許可が必要です（農地法3条1項）。", "caution": "農地の耕作方法の変更は農地法の規制外。"}, {"label": "農地の贈与", "reason": "農地の贈与は農地法3条の許可が必要です（農地法3条1項）。", "caution": ""}, {"label": "農地から非農地への転用", "reason": "農地の転用は農地法4条・5条の許可が必要です（農地法4条1項・5条1項）。", "caution": ""}], "summary": {"head": ["農地法の規制対象", "規制あり/なし"], "rows": [["権利移動（農地のまま）", "3条の許可が必要"], ["自己転用", "4条の許可が必要"], ["転用目的の権利移動", "5条の許可が必要"], ["耕作方法の変更", "規制対象外"]]}}},
  {id:10228,unit:'k_kukaku',level:2,field:'limit',text:"換地計画に関して正しいものはどれか。",opts:["換地計画は施行者が単独で作成できる", "換地計画は関係権利者に縦覧する機会が与えられる", "換地は必ず従前地と同じ面積・形状でなければならない", "換地計画は市町村の承認のみで確定する"],ans:1,exp:`換地計画を定めた場合は関係権利者が縦覧できるよう公告し、異議申し立ての機会が与えられます（土地区画整理法88条）。換地は必ずしも従前地と同一面積・形状でなく、清算金で調整されます。`,"kaisetsu":{"topic": "土地区画整理法：換地は公告翌日確定・仮換地は従前地使用不可・組合は2/3以上", "basis": {"text": "換地処分の公告翌日から換地が確定します（土地区画整理法104条）。仮換地の指定後は従前地を使用できなくなります（同法99条）。組合設立には土地所有者・借地権者の各2/3以上の同意が必要です。", "example": ""}, "reason": {"text": "換地計画は施行者が作成しますが、関係権利者に縦覧する機会を与え、意見書の提出を認める手続きが必要です（土地区画整理法86条・88条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">土地区画整理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">換地の確定</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公告の翌日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮換地指定後</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従前地は使用不可（所有権は残る）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">組合設立</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各2/3以上の同意</text></svg>", "choices": [{"label": "換地計画は施行者が単独で作成できる", "reason": "換地計画は作成後に縦覧・意見書受付の手続きが必要です（土地区画整理法88条）。", "caution": "換地計画：縦覧・意見書受付の手続きが必要（土地区画整理法88条）。"}, {"label": "換地は必ず従前地と同じ面積・形状でなければならない", "reason": "換地は照応の原則により価値が同等になるよう配慮します（土地区画整理法89条）。", "caution": ""}, {"label": "換地計画は市町村の承認のみで確定する", "reason": "換地計画の認可は都道府県知事等が行います（土地区画整理法86条等）。", "caution": ""}], "summary": {"head": ["換地計画の手続き（土地区画整理法86条〜88条）", "内容"], "rows": [["作成者", "施行者"], ["縦覧", "関係権利者への縦覧（同法88条）"], ["意見書", "関係権利者は意見書を提出可"]]}}},
  {id:10229,unit:'k_mori',level:2,field:'limit',text:"盛土規制法における特定盛土等規制区域の指定について正しいものはどれか。",opts:["都市計画区域内にのみ指定できる", "宅地造成等工事規制区域以外の土地の区域にも指定できる", "山林には指定できない", "市町村が指定する"],ans:1,exp:`特定盛土等規制区域は宅地造成等工事規制区域と重複して指定することはできません（盛土規制法26条）。都市計画区域外・山林等にも指定できます。都道府県知事（または政令市長）が指定します。`,"kaisetsu":{"topic": "盛土規制法・宅地造成：盛土は1m超・切土は2m超・特定盛土等規制区域", "basis": {"text": "盛土で高さ1mを超える崖を生じる場合は許可が必要（盛土規制法）。切土は2mを超える崖で許可が必要。特定盛土等規制区域内の一定規模以上の盛土等は許可が必要です。農地・森林も規制対象に含まれます。", "example": ""}, "reason": {"text": "特定盛土等規制区域は、宅地造成等工事規制区域以外の土地の区域で、盛土等により人家等に危害を生じるおそれがある区域に指定されます（宅地造成及び特定盛土等規制法26条）。都市計画区域外の山林・農地等にも指定できます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">盛土規制法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">工事種別</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可が必要な規模</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">切土</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">高さ2mを超える崖</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">盛土</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">高さ1mを超える崖</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">面積</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">500㎡超の宅地造成</text></svg>", "choices": [{"label": "都市計画区域内にのみ指定できる", "reason": "特定盛土等規制区域は都市計画区域外の山林・農地等にも指定できます（宅地造成及び特定盛土等規制法26条）。", "caution": "特定盛土等規制区域：宅地造成工事規制区域と重複指定可（宅地造成及び特定盛土等規制法26条）。"}, {"label": "山林には指定できない", "reason": "山林にも指定できます（宅地造成及び特定盛土等規制法26条）。", "caution": ""}, {"label": "市町村が指定する", "reason": "特定盛土等規制区域の指定は都道府県知事が行います（宅地造成及び特定盛土等規制法26条1項）。", "caution": ""}], "summary": {"head": ["特定盛土等規制区域（宅地造成及び特定盛土等規制法26条）", "内容"], "rows": [["指定者", "都道府県知事"], ["場所", "市街地から離れた山林・農地等でも指定可"], ["重複指定", "宅地造成工事規制区域との重複指定可"]]}}},
  {id:10230,unit:'t_joto',level:2,field:'tax',text:"居住用財産の買換え特例（3000万円控除との選択）の適用要件として正しいものはどれか。",opts:["保有期間5年以下の物件にも適用できる", "売却した居住用財産の譲渡価格が1億円以下", "新たに取得する住宅の床面積が50平方メートル以上", "上記2と3の両方"],ans:3,exp:`居住用財産の買換え特例の主な要件は①譲渡資産の譲渡価格が1億円以下②買換資産の床面積が50平方メートル以上・土地500平方メートル以下③所有期間・居住期間が10年超④保有期間10年超などです（租税特別措置法36条の2）。`,"kaisetsu":{"topic": "譲渡所得：分離課税・長期は20%・3,000万円控除は3年に1回", "basis": {"text": "土地・建物の譲渡所得は分離課税。長期（5年超）は合計20%（所得税15%+住民税5%）。短期（5年以下）は39%（所得税30%+住民税9%）。3,000万円特別控除は前年・前々年に適用があれば使えません（3年に1回）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">譲渡所得のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税方式</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">分離課税</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">長期（5年超）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計20%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">短期（5年以下）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計39%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3,000万円控除</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年に1回の制限</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10231,unit:'t_shutoku',level:2,field:'tax',text:"不動産取得税の非課税事由として正しいものはどれか。",opts:["売買による取得", "贈与による取得", "相続による取得", "交換による取得"],ans:2,exp:`相続による不動産取得は不動産取得税が非課税です（地方税法73条の7第1号）。売買・贈与・交換・新築等は課税対象です。`,"kaisetsu":{"topic": "不動産取得税：都道府県が課す地方税・相続は非課税・1回だけ課税", "basis": {"text": "不動産取得税は都道府県が課す地方税（地方税法73条の2）。相続・法人の合併等は非課税。一度の取得に一度だけ課税（毎年ではない）。標準税率は4%（住宅・土地は3%の軽減あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産取得税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税の頻度</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取得時に1回のみ</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">標準税率</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4%（住宅・土地は3%）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10232,unit:'t_kotei',level:2,field:'tax',text:"固定資産税の標準税率と超過税率の関係として正しいものはどれか。",opts:["市町村は標準税率1.4%を必ず適用しなければならない", "市町村は条例で標準税率を超える税率を定めることができる", "標準税率は国税として一律に決定される", "超過税率の上限は2%と法定されている"],ans:1,exp:`固定資産税の標準税率は1.4%ですが、市町村は条例により標準税率を超える税率（超過税率）を定めることができます（地方税法350条）。上限の法定はなく、各市町村が条例で定めます。`,"kaisetsu":{"topic": "固定資産税：市町村が課す地方税・賦課期日は1月1日・評価替えは3年ごと", "basis": {"text": "固定資産税は市町村（東京23区は都）が課す地方税（地方税法343条）。賦課期日は毎年1月1日。評価替えは3年ごと（基準年度）。住宅用地の特例：200㎡以下は課税標準1/6、超過部分は1/3。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">固定資産税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市町村（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賦課期日</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">評価替え</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年ごと</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅用地（200㎡以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税標準1/6</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10233,unit:'t_inshi',level:2,field:'tax',text:"不動産売買契約書の印紙税について正しいものはどれか。",opts:["印紙税は取引ごとに国税庁へ申告する", "収入印紙を貼付して消印する方法が一般的", "売主だけが負担する", "電子契約書にも印紙税がかかる"],ans:1,exp:`印紙税は収入印紙を課税文書に貼付して消印することで納付します（印紙税法8条）。売主・買主が1通ずつ作成した場合は各通に印紙が必要です。電子契約書（データのみ）は課税対象外です。`,"kaisetsu":{"topic": "印紙税：売買・賃貸借契約書は課税文書・電子契約は非課税・1万円未満は非課税", "basis": {"text": "不動産の売買契約書・賃貸借契約書は印紙税の課税文書（第1号文書）。電子契約は課税対象外（文書でないため）。1万円未満の記載金額は非課税。複数当事者が保有する各通に課税。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">印紙税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買・賃貸借契約書</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税文書（第1号）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">電子契約</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1万円未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10234,unit:'t_chika',level:2,field:'tax',text:"不動産鑑定評価の3方式について正しいものはどれか。",opts:["取引事例比較法・収益還元法・原価法の3つ", "取引事例比較法・積算法・収益還元法の3つ", "比準価格・収益価格・積算価格の3方式がある（方式名は同じ）", "鑑定評価では1方式のみ使用する"],ans:0,exp:`不動産鑑定評価の3方式は取引事例比較法・収益還元法・原価法です（不動産鑑定評価基準）。取引事例比較法で求めた価格を比準価格、収益還元法で求めた価格を収益価格、原価法で求めた価格を積算価格といいます。`,"kaisetsu":{"topic": "地価公示・不動産鑑定評価：基準日は1月1日・土地鑑定委員会が実施・3手法", "basis": {"text": "地価公示の基準日は毎年1月1日で土地鑑定委員会（国土交通省）が実施（地価公示法）。公示価格は鑑定評価の規準となります（同法8条）。不動産鑑定評価の3手法：原価法・取引事例比較法・収益還元法。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">地価公示・鑑定評価</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">基準日</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">実施機関</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">土地鑑定委員会（国土交通省）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">鑑定評価の3手法</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原価法・取引事例比較法・収益還元法</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10235,unit:'r_baibai',level:2,field:'rights',text:'AがBに甲建物を売却したが引渡し時から雨漏りの欠陥（契約不適合）があった。Bがとれる手段として誤っているものはどれか。',opts:['追完請求（修繕要求）','代金減額請求','損害賠償請求','要件を問わず即時に契約を全部解除して代金全額返還を請求'],ans:3,exp:`契約不適合責任では追完・代金減額・損害賠償・解除が認められます。ただし契約解除には「催告しても相当期間内に追完されない」等の要件（民法541条・564条）が必要であり、欠陥があるだけで即時の全部解除・全額返還が当然に認められるわけではありません。`,"kaisetsu":{"topic": "売買：同時履行の抗弁権・解除は原則催告が必要・契約不適合責任", "basis": {"text": "売買では代金と引渡しは同時履行の関係（民法533条）。解除は原則として相当の期間を定めた催告後に行います（民法541条）。契約不適合責任の通知は知った時から1年以内（民法566条）。", "example": ""}, "reason": {"text": "契約不適合があった場合でも、買主が「要件を問わず即時に全部解除」できるわけではありません（民法541条）。軽微な不適合の場合は解除できません（同条ただし書）。解除には原則として追完請求→相当期間経過→解除という手順が必要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">売買のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">同時履行</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金と引渡しは同時履行</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則として催告が必要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">契約不適合の通知</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から1年以内</text></svg>", "choices": [{"label": "追完請求（修繕要求）", "reason": "雨漏りの修繕を追完請求することは認められています（民法562条1項）。誤りではありません。", "caution": ""}, {"label": "代金減額請求", "reason": "追完請求後に相当期間内に修繕されない場合等に代金減額請求ができます（民法563条）。誤りではありません。", "caution": ""}, {"label": "損害賠償請求", "reason": "損害賠償請求は認められています（民法564条・415条）。誤りではありません。", "caution": ""}], "summary": {"head": ["解除の要件（民法541条）", "内容"], "rows": [["原則", "催告（追完請求）→相当期間経過後に解除"], ["即時解除（催告不要）", "追完が不能・売主が拒絶・一定の期間内不能等（民法542条）"], ["解除できない場合", "不履行（不適合）が軽微な場合（民法541条ただし書）"]]}}},
  {id:10236,unit:'r_chinshaku',level:2,field:'rights',text:'建物の賃貸借における賃料の増減額請求に関して正しいものはどれか。',opts:['賃料の増減額請求はいかなる場合も禁止される','一定期間は増額しない旨の特約は有効（借地借家法32条1項ただし書）','一定期間は減額しない旨の特約も常に有効','賃料改定は必ず裁判によらなければならない'],ans:1,exp:`借地借家法では一定期間は賃料を増額しない旨の特約は有効です（借地借家法32条1項ただし書）。一方、減額しない旨の特約は無効とされています。協議不成立時は調停・訴訟で解決します。`,"kaisetsu":{"topic": "賃貸借：通常損耗は原状回復に含まれない・有益費は終了時に請求・賃料増額は正当事由が必要", "basis": {"text": "賃貸借終了時の原状回復義務に通常使用による損耗（壁の日焼け等）は含まれません（民法621条）。必要費は直ちに、有益費は終了時の請求が原則。更新拒絶には正当事由が必要（借地借家法28条）。", "example": ""}, "reason": {"text": "一定期間は増額しない旨の特約は有効です（借地借家法32条1項ただし書）。賃借人保護の観点から増額を制限することは許容されます。一方、一定期間は減額しない旨の特約は無効です（同条1項本文）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">賃貸借のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通常損耗</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原状回復に含まれない</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要費</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直ちに請求可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有益費</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸借終了時に請求</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">更新拒絶</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当事由が必要</text></svg>", "choices": [{"label": "賃料の増減額請求はいかなる場合も禁止される", "reason": "経済事情の変動等がある場合、賃料の増減額請求は認められます（借地借家法32条1項）。いかなる場合も禁止されるわけではありません。", "caution": ""}, {"label": "一定期間は減額しない旨の特約も常に有効", "reason": "減額しない旨の特約は賃借人に不利なため無効です（借地借家法32条1項本文）。増額しない旨の特約は有効（同条ただし書）とは扱いが異なります。", "caution": "増額しない特約＝有効、減額しない特約＝無効。賃借人保護の方向性を押さえましょう。"}, {"label": "賃料改定は必ず裁判によらなければならない", "reason": "当事者の合意による賃料改定も可能です。裁判は当事者が合意できない場合の手段です（借地借家法32条）。", "caution": ""}], "summary": {"head": ["賃料特約の有効性", "内容"], "rows": [["増額しない特約", "有効（賃借人保護の方向・借地借家法32条1項ただし書）"], ["減額しない特約", "無効（借地借家法32条1項本文）"], ["定期建物賃貸借の減額不可特約", "有効（借地借家法38条7項）"]]}}},
  {id:10237,unit:'r_souzoku',level:2,field:'rights',text:'遺言の種類のうち、家庭裁判所の検認が不要なものはどれか。',opts:['自筆証書遺言（法務局保管でない通常のもの）','公正証書遺言','秘密証書遺言','口頭での遺言'],ans:1,exp:`公正証書遺言は公証人が関与して作成されるため、家庭裁判所の検認が不要です（民法1004条2項）。自筆証書遺言（法務局保管制度利用の場合も検認不要）や秘密証書遺言は原則検認が必要です。`,"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2・遺産分割は全員合意", "basis": {"text": "配偶者と子は各1/2（民法900条）。放棄は3か月以内に家裁へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2（民法1042条）。兄弟姉妹に遺留分はなし。遺産分割協議は全員合意が必要。", "example": ""}, "reason": {"text": "公正証書遺言は公証人が作成する遺言で、公証人役場に原本が保管されるため家庭裁判所の検認が不要です（民法1004条2項）。自筆証書遺言・秘密証書遺言は検認が必要です（同条1項）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "自筆証書遺言（法務局保管でない通常のもの）", "reason": "通常の自筆証書遺言は家庭裁判所の検認が必要です（民法1004条1項）。法務局で保管されている場合は検認不要（遺言書保管法11条）。", "caution": "法務局保管の自筆証書遺言→検認不要。通常の自筆証書遺言→検認必要。"}, {"label": "秘密証書遺言", "reason": "秘密証書遺言は家庭裁判所の検認が必要です（民法1004条1項）。", "caution": ""}, {"label": "口頭での遺言", "reason": "口頭の遺言は民法が定める普通方式の遺言ではなく無効です（民法960条）。", "caution": ""}], "summary": {"head": ["遺言の種類", "検認の要否"], "rows": [["自筆証書遺言（通常）", "必要（民法1004条1項）"], ["自筆証書遺言（法務局保管）", "不要（遺言書保管法11条）"], ["公正証書遺言", "不要（民法1004条2項）"], ["秘密証書遺言", "必要（民法1004条1項）"]]}}},
  {id:10238,unit:'r_fuhoko',level:2,field:'rights',text:'使用者責任（民法715条）について正しいものはどれか。',opts:['使用者は常に被用者の行為について無過失責任を負う','使用者が選任及び事業の監督について相当の注意をしたことを証明すれば免責される','被用者が故意の場合のみ成立する','使用者は被用者の行為について一切責任を負わない'],ans:1,exp:`使用者責任は、使用者が選任及び事業の監督について相当の注意をしたこと、または相当の注意をしても損害が生じた場合は免責されます（民法715条1項ただし書）。実務上この免責はほぼ認められません。`,"kaisetsu":{"topic": "不法行為：故意または過失が必要・使用者責任・工作物責任", "basis": {"text": "不法行為は故意または過失が必要です（民法709条）。使用者は被用者の職務上の不法行為について責任を負います（民法715条）。工作物の所有者は無過失責任（占有者が免責された場合）（民法717条）。", "example": ""}, "reason": {"text": "使用者責任（民法715条1項）は使用者が選任・監督について相当の注意をしたことを証明すれば免責される中間責任です。ただし実際の裁判では免責がほとんど認められず、実質的に無過失責任に近い扱いとなっています。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不法行為のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般不法行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">故意または過失が必要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">使用者責任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">被用者への求償可（信義則上制限）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">工作物の所有者責任</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無過失責任（占有者が免責された場合）</text></svg>", "choices": [{"label": "使用者は常に被用者の行為について無過失責任を負う", "reason": "法律上は使用者が選任・監督について相当の注意をしたことを証明すれば免責されます（民法715条1項ただし書）。ただし実務上ほぼ認められません。", "caution": "法律上は中間責任。実務上は無過失責任に近い扱い。"}, {"label": "被用者が故意の場合のみ成立する", "reason": "被用者の故意・過失を問わず使用者責任は成立します（民法715条1項）。", "caution": ""}, {"label": "使用者は被用者の行為について一切責任を負わない", "reason": "使用者責任（民法715条1項）により使用者は被用者の事業執行中の不法行為について責任を負います。", "caution": ""}], "summary": {"head": ["使用者責任の性質", "内容"], "rows": [["法律上の性質", "中間責任（免責証明で免責可・民法715条1項ただし書）"], ["実務上の扱い", "免責がほぼ認められない→無過失責任に近い"], ["求償", "使用者→被用者への求償可（信義則上制限あり・判例）"]]}}},
  {id:10239,unit:'r_shakuchi',level:2,field:'rights',text:'定期建物賃貸借（定期借家・1年以上の契約）の終了通知として正しいものはどれか。',opts:['期間満了の1年前から6ヶ月前に通知が必要','期間満了の6ヶ月前までに終了通知をしなければならない','期間満了の3ヶ月前に通知すれば足りる','通知なしでも自動的に終了する'],ans:1,exp:`期間1年以上の定期建物賃貸借では、賃貸人は期間満了の1年前から6ヶ月前までの間に終了通知をしなければなりません（借地借家法38条6項）。通知がない場合は期間満了後6ヶ月経過後にようやく終了を対抗できます。`,"kaisetsu":{"topic": "借地権：最短30年・建物登記で対抗・建物滅失でも消滅せず・定期借地権は3種類", "basis": {"text": "普通借地権の最短存続期間は30年（借地借家法3条）。借地上の建物の自己名義登記が対抗要件（同法10条）。建物が滅失しても借地権は消滅しません。定期借地権は①一般（50年以上）②事業用（10〜50年未満）③建物譲渡特約（30年以上）の3種類。", "example": ""}, "reason": {"text": "定期建物賃貸借（1年以上の契約）では、期間満了の6か月前までに賃借人への終了通知が必要です（借地借家法38条4項）。通知がなければ、終了通知の効力は通知から6か月経過後に生じます（同条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">借地権のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">最短存続期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">対抗要件</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借地上の建物の自己名義登記</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物滅失</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借地権は消滅しない</text></svg>", "choices": [{"label": "期間満了の1年前から6ヶ月前に通知が必要", "reason": "終了通知は期間満了の6か月前までに行えばよく「1年前から6か月前の間」という制限はありません（借地借家法38条4項）。", "caution": "定期借家の終了通知：期間満了の6か月前まで（借地借家法38条4項）。"}, {"label": "期間満了の3ヶ月前に通知すれば足りる", "reason": "1年以上の定期借家契約では6か月前までの通知が必要です（借地借家法38条4項）。3か月前では遅すぎます。", "caution": ""}, {"label": "通知なしでも自動的に終了する", "reason": "通知がなければ期間満了で終了しません。通知から6か月後に終了します（借地借家法38条4項ただし書）。", "caution": ""}], "summary": {"head": ["定期建物賃貸借の終了通知（借地借家法38条4項）", "内容"], "rows": [["通知時期", "期間満了の6か月前まで"], ["通知を怠った場合", "通知してから6か月後に終了"], ["1年未満の契約", "終了通知規定の適用なし"], ["要件", "書面（または電磁的記録）で行う"]]}}},
  {id:10240,unit:'r_kukku',level:2,field:'rights',text:'マンションの管理規約の変更・廃止の決議要件として正しいものはどれか。',opts:['区分所有者及び議決権の各過半数','区分所有者及び議決権の各3/4以上の多数','区分所有者及び議決権の各4/5以上の多数','区分所有者全員の同意'],ans:1,exp:`管理規約の設定・変更・廃止は区分所有者及び議決権の各3/4以上の多数決が必要です（区分所有法31条1項）。建替え決議は各4/5以上、普通の管理事項は過半数です。`,"kaisetsu":{"topic": "区分所有法：重大変更は3/4以上・建替えは4/5以上・管理組合法人は30人以上", "basis": {"text": "共用部分の重大変更は区分所有者・議決権の各3/4以上の特別決議が必要（区分所有法17条）。建替えは4/5以上（同法62条）。管理組合法人の設立は3/4以上かつ区分所有者30人以上（同法47条）。専有部分と共有持分は分離処分不可（同法15条）。", "example": ""}, "reason": {"text": "管理規約の設定・変更・廃止は区分所有者および議決権の各3/4以上の特別決議が必要です（区分所有法31条1項）。規約は区分所有者全員の権利・義務に関わる重要な事項であるため、高い決議要件が設定されています。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">区分所有法の決議要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">事項</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">普通決議</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">過半数</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">重大変更・規約変更</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3/4以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">管理組合法人</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3/4以上（30人以上）</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建替え</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4/5以上</text></svg>", "choices": [{"label": "区分所有者及び議決権の各過半数", "reason": "過半数は通常の管理行為の決議要件です（区分所有法18条1項）。規約の変更・廃止には3/4以上が必要です（同法31条1項）。", "caution": "規約の変更・廃止＝3/4以上（区分所有法31条1項）。"}, {"label": "区分所有者及び議決権の各4/5以上の多数", "reason": "4/5以上は建替え決議の要件です（区分所有法62条1項）。規約の変更は3/4以上です（同法31条1項）。", "caution": ""}, {"label": "区分所有者全員の同意", "reason": "規約の変更は3/4以上で足ります（区分所有法31条1項）。全員同意は不要です。", "caution": ""}], "summary": {"head": ["区分所有法の決議要件まとめ", "賛成割合"], "rows": [["通常の管理行為", "過半数（区分所有法18条1項）"], ["重大変更・規約変更・管理組合法人設立", "3/4以上"], ["大規模滅失後の復旧", "3/4以上（区分所有法61条5項）"], ["建替え", "4/5以上（区分所有法62条1項）"]]}}},
  {id:10241,unit:'r_touki',level:2,field:'rights',text:'登記の対抗力における「背信的悪意者」の扱いとして正しいものはどれか。',opts:['背信的悪意者であっても登記を備えれば対抗できる','背信的悪意者に対しては登記がなくても物権変動を対抗できる（判例）','背信的悪意者かどうかは登記官が判断する','背信的悪意者への対抗には仮登記が必要'],ans:1,exp:`判例上、信義則に反する態様で登記の欠如を主張する背信的悪意者には、登記がなくても物権変動を対抗できます。背信的悪意者は民法177条の「第三者」から除外されるとされています。`,"kaisetsu":{"topic": "不動産登記：権利登記は共同申請・仮登記は順位保全・建物滅失は1か月以内", "basis": {"text": "権利に関する登記は原則として登記権利者と登記義務者が共同申請します（不動産登記法60条）。仮登記は順位保全機能があるが完全な対抗力は本登記後です。建物滅失登記の申請義務は1か月以内（同法57条）。", "example": ""}, "reason": {"text": "民法177条の「第三者」から背信的悪意者は除外されます（判例）。信義則に反する態様で先買人の登記の欠如を主張する者を保護する必要はなく、登記がなくても先買人はその者に対抗できます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産登記のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利登記</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則として共同申請</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮登記</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">順位保全（対抗力は本登記後）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物滅失登記</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1か月以内</text></svg>", "choices": [{"label": "背信的悪意者であっても登記を備えれば対抗できる", "reason": "背信的悪意者は民法177条の「第三者」から除外されるため、登記を備えていても対抗できません（判例）。", "caution": "背信的悪意者は登記を備えていても保護されません。"}, {"label": "背信的悪意者かどうかは登記官が判断する", "reason": "背信的悪意者かどうかは裁判所（民事訴訟）で判断されます。登記官は実体関係を審査しないため判断しません。", "caution": ""}, {"label": "背信的悪意者への対抗には仮登記が必要", "reason": "背信的悪意者に対しては本登記・仮登記を問わず、登記なしで対抗できます（判例）。", "caution": ""}], "summary": {"head": ["第三者の態様", "登記なしで対抗できるか"], "rows": [["善意者", "できない"], ["単純悪意者", "できない"], ["背信的悪意者", "できる（判例）"], ["不法占拠者", "できる（判例）"], ["相続人", "できる（当事者扱い）"]]}}},
  {id:10242,unit:'l_menkyo',level:2,field:'law',text:'宅建業の免許の欠格事由として正しいものはどれか。',opts:['拘禁刑以上の刑の執行終了から5年が経過すれば免許を取得できる','執行猶予中の者でも免許を取得できる','成年被後見人は一律に免許を取得できない','法人の役員が欠格事由に該当しても法人の免許に影響はない'],ans:0,exp:`拘禁刑以上の刑の執行終了（または執行猶予満了）から5年が経過すれば欠格事由が消滅し免許を取得できます（宅建業法5条1項5号）。執行猶予中は欠格です。成年被後見人・被保佐人であること自体は現行法上当然に一律欠格となるものではなく、心身の故障により宅建業を適正に営めない者等に当たるかを個別に判断します。法人の役員が欠格なら法人も欠格です。`,"kaisetsu":{"topic": "宅建業免許：知事・大臣免許の区別・有効期間5年・欠格事由は5年", "basis": {"text": "1都道府県→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間。2020年改正で成年被後見人の欠格条項は廃止。", "example": ""}, "reason": {"text": "拘禁刑以上の刑の執行終了等から5年を経過すれば欠格事由から外れ、免許を取得できます（宅建業法5条1項5号）。執行猶予中の者は欠格事由に該当し免許を取得できません（同号）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（2020年改正で成年被後見人は廃止）</text></svg>", "choices": [{"label": "執行猶予中の者でも免許を取得できる", "reason": "執行猶予中の者は拘禁刑以上の刑に処せられた者として欠格事由に該当し（宅建業法5条1項5号）、免許を取得できません。", "caution": "執行猶予中＝欠格事由に該当（免許取得不可）。執行猶予が満了すれば欠格事由から外れる。"}, {"label": "成年被後見人は免許を取得できる", "reason": "2021年改正後、成年被後見人は一律に欠格事由から除外されました。ただし個別の判断で欠格事由となる場合があります。設問では「成年被後見人は免許を取得できる」という記述が2021年改正後は正しくなりましたが、設問の正解は選択肢1です。", "caution": ""}, {"label": "法人の役員が欠格事由に該当しても法人の免許に影響はない", "reason": "法人の役員が欠格事由に該当する場合、その法人も免許を受けられません（宅建業法5条1項1号・3号）。役員の欠格事由は法人の免許に影響します。", "caution": "役員の欠格事由→法人も免許取得不可（宅建業法5条1項1号）。"}], "summary": {"head": ["主な欠格事由と期間", "内容"], "rows": [["拘禁刑以上の刑（執行中・執行猶予中）", "欠格事由に該当"], ["刑の執行終了等から5年未満", "欠格事由に該当"], ["刑の執行終了等から5年経過", "欠格事由から外れ→免許取得可"], ["法人役員が欠格事由", "法人も免許取得不可（宅建業法5条1項1号）"]]}}},
  {id:10243,unit:'l_takkenshi',level:2,field:'law',text:'宅建士の登録の移転について正しいものはどれか。',opts:['宅建士の登録は全国共通で都道府県をまたいで移転する必要はない','他の都道府県に所在する宅建業者に従事する場合に登録を移転することができる（任意）','登録移転は義務で移転しないと登録が消除される','宅建士試験を再受験した場合のみ移転できる'],ans:1,exp:`宅建士の登録は都道府県ごとに行います。他の都道府県に所在する宅建業者に従事する場合、その都道府県へ登録を移転することができます（任意）（宅建業法19条の2）。`,"kaisetsu":{"topic": "専任宅建士：5人に1人以上・兼任不可・2週間以内に補充", "basis": {"text": "事務所には業務従事者5人に1人以上の専任宅建士が必要（宅建業法31条の3）。1社専属で複数業者の兼任は不可。不足時は2週間以内に補充が必要。案内所（申込み受付）にも専任宅建士が必要。", "example": ""}, "reason": {"text": "宅建士の登録移転は義務ではなく任意です（宅建業法19条の2）。他の都道府県に所在する宅建業者に従事することになった場合に、勤務先の都道府県の知事へ登録を移転することができます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">専任宅建士のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">設置基準</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5人に1人以上</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">兼任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可（1社専属）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不足補充</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間以内</text></svg>", "choices": [{"label": "宅建士の登録は全国共通で都道府県をまたいで移転する必要はない", "reason": "登録移転は任意なので必要はありませんが（宅建業法19条の2）、実務上は勤務先と同じ都道府県に登録があると便利です。「移転する必要はない」という点は正しいです。", "caution": "登録移転は任意（義務ではない・宅建業法19条の2）。"}, {"label": "登録移転は義務で移転しないと登録が消除される", "reason": "登録移転は任意です（宅建業法19条の2）。移転しなくても登録は消除されません。", "caution": ""}, {"label": "宅建士試験を再受験した場合のみ移転できる", "reason": "登録移転に試験の再受験は不要です（宅建業法19条の2）。勤務先の都道府県に変わった場合等に申請できます。", "caution": ""}], "summary": {"head": ["登録移転（宅建業法19条の2）", "内容"], "rows": [["可否", "任意（義務ではない）"], ["条件", "他の都道府県に所在する宅建業者に従事"], ["手続き", "現在の知事を経由して移転先の知事へ申請"], ["制限", "事務禁止処分中は登録移転不可"]]}}},
  {id:10244,unit:'l_baikai',level:2,field:'law',text:'専任媒介契約の有効期間と更新について正しいものはどれか。',opts:['有効期間は最長6ヶ月で依頼者の申し出で更新できる','有効期間は最長3ヶ月で依頼者の申し出がある場合のみ更新できる','有効期間は最長3ヶ月で業者が自動更新できる','更新後の有効期間に制限はない'],ans:1,exp:`専任媒介契約の有効期間の上限は3ヶ月です（宅建業法34条の2第3項）。更新は依頼者からの申し出がある場合のみ可能で、更新後の有効期間も3ヶ月が上限です。`,"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任の有効期間は最長3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。レインズ登録は専任7日以内・専属専任5日以内。業務報告は専任2週間に1回・専属専任1週間に1回。", "example": ""}, "reason": {"text": "専任媒介契約の有効期間は3か月が上限です（宅建業法34条の2第3項）。更新は依頼者の申し出がある場合にのみできます（同条3項ただし書）。依頼者の申し出なしの自動更新は認められません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">自己発見</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">レインズ</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専任</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専属専任</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text></svg>", "choices": [{"label": "有効期間は最長6ヶ月で依頼者の申し出で更新できる", "reason": "有効期間の上限は3か月です（宅建業法34条の2第3項）。6か月は誤りです。", "caution": "専任・専属専任媒介の有効期間上限：3か月（宅建業法34条の2第3項）。"}, {"label": "有効期間は最長3ヶ月で業者が自動更新できる", "reason": "更新は依頼者の申し出がある場合のみです（宅建業法34条の2第3項）。業者が自動更新することはできません。", "caution": ""}, {"label": "更新後の有効期間に制限はない", "reason": "更新後の有効期間も3か月を超えることはできません（宅建業法34条の2第3項）。「制限なし」は誤りです。", "caution": ""}], "summary": {"head": ["専任媒介の有効期間（宅建業法34条の2第3項）", "内容"], "rows": [["有効期間上限", "3か月"], ["3か月を超える定め", "3か月とみなされる"], ["更新", "依頼者の申し出がある場合のみ可"], ["更新後の期間", "更新後も3か月以内"]]}}},
  {id:10245,unit:'l_jusetsu',level:2,field:'law',text:'重要事項説明（35条書面）の説明者として正しいものはどれか。',opts:['宅建業者の代表者のみが行える','宅建士が記名した書面を交付すれば説明者は誰でもよい','宅建士が自ら説明し宅建士証を提示したうえで宅建士が記名した書面を交付する','営業担当者であれば宅建士でなくてもよい'],ans:2,exp:`重要事項説明は宅建士が自ら説明を行い、宅建士証を提示したうえで宅建士が記名した書面（35条書面）を相手方に交付しなければなりません（宅建業法35条）。`,"kaisetsu":{"topic": "重要事項説明：宅建士が説明・買主への交付・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主（貸主）は不要。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能。", "example": ""}, "reason": {"text": "重要事項説明は宅建士が自ら説明し、宅建士証を提示し、宅建士が記名した35条書面を交付します（宅建業法35条1項・4項）。記名は宅建士が行い、説明者も宅建士でなければなりません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士のみ（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "宅建業者の代表者のみが行える", "reason": "宅建士でなければ重要事項説明はできません（宅建業法35条1項）。代表者でも宅建士でなければ不可です。", "caution": ""}, {"label": "宅建士が記名した書面を交付すれば説明者は誰でもよい", "reason": "書面の交付だけでなく、宅建士が自ら説明し宅建士証を提示することが必要です（宅建業法35条1項・4項）。", "caution": ""}, {"label": "営業担当者であれば宅建士でなくてもよい", "reason": "営業担当者でも宅建士でなければ重要事項説明はできません（宅建業法35条1項）。", "caution": ""}], "summary": {"head": ["重要事項説明の実施要件", "内容"], "rows": [["実施者", "宅建士のみ（宅建業法35条1項）"], ["宅建士証", "説明の際に提示必須（同条4項）"], ["35条書面の記名", "宅建士が記名（同条1項）"], ["説明と交付", "両方が必要"]]}}},
  {id:10246,unit:'l_37jo',level:2,field:'law',text:'37条書面（契約書面）の必要的記載事項として正しいものはどれか。',opts:['融資あっせんに関する事項（定めなくても必ず記載）','代金の額・支払時期・支払方法','住宅性能評価を受けた旨','容積率・建ぺい率'],ans:1,exp:`37条書面の必要的記載事項には「代金・交換差金・借賃の額及び支払時期・方法」が含まれます（宅建業法37条1項2号）。融資あっせん失敗時の措置・移転登記申請時期等は定めがある場合のみ記載する任意的記載事項です。`,"kaisetsu":{"topic": "37条書面：全取引で交付・記名（押印不要）・移転登記申請時期は必要的記載事項", "basis": {"text": "37条書面は全取引で契約の双方当事者に交付が義務（宅建業法37条）。引渡し時期・移転登記申請時期は必要的記載事項。2021年改正で押印は不要、記名のみで足ります。", "example": ""}, "reason": {"text": "代金の額・支払時期・支払方法は37条書面の必要的記載事項です（宅建業法37条1項2号）。融資あっせん・住宅性能評価・容積率・建ぺい率は37条書面の必要的記載事項ではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付義務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全取引・双方当事者</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡時期・移転登記申請時期等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要）</text></svg>", "choices": [{"label": "融資あっせんに関する事項（定めなくても必ず記載）", "reason": "融資あっせんは定めがある場合の任意的記載事項です（宅建業法37条1項8号）。必要的記載事項ではありません。", "caution": "融資あっせん：任意的記載事項（定めがある場合のみ）。"}, {"label": "住宅性能評価を受けた旨", "reason": "住宅性能評価を受けた旨は35条書面（重要事項説明書）の記載事項です。37条書面の必要的記載事項ではありません。", "caution": ""}, {"label": "容積率・建ぺい率", "reason": "容積率・建ぺい率は35条書面（重要事項説明書）の法令上の制限として記載します。37条書面の必要的記載事項ではありません。", "caution": ""}], "summary": {"head": ["37条書面の必要的記載事項", "内容"], "rows": [["代金の額", "必要的（宅建業法37条1項2号）"], ["代金の支払時期", "必要的（同号）"], ["代金の支払方法", "必要的（同号）"], ["引渡し時期", "必要的（同条1項4号）"], ["移転登記申請時期", "必要的（同条1項5号）"]]}}},
  {id:10247,unit:'l_hoshu',level:2,field:'law',text:'宅建業者が売買の媒介をした場合（代金400万円超）の報酬上限（消費税別）として正しいものはどれか。',opts:['一方の依頼者から代金の3%+6万円（消費税別）が上限','双方合わせて代金の3%+6万円が上限','一方の依頼者から代金の5%が上限','双方合わせて代金の6%+12万円が上限'],ans:0,exp:`売買の媒介では一方の依頼者から「代金×3%+6万円（消費税別）」が上限です（国土交通省告示）。売主・買主それぞれから、この計算式が上限となります。`,"kaisetsu":{"topic": "報酬：売買は代金×3%+6万（400万超）・賃貸は借賃1か月・上限超過は不可", "basis": {"text": "売買（400万超）の一方からの上限は代金×3%+6万。双方合計は一方上限×2。賃貸（居住用・非居住用とも）は借賃1か月分。低廉な空家等（800万円以下）は、媒介報酬について原則の報酬額を超えて30万円（税別）まで受領できる場合があります（依頼者への説明・合意が必要）。", "example": ""}, "reason": {"text": "売買代金が400万円超の場合、一方の依頼者から受け取れる報酬上限は「代金×3%＋6万円（税別）」です（告示）。双方から合計すれば最大「代金×6%＋12万円（税別）」になります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対象</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（400万超）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万（一方）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（200万以下）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸（双方合計）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借賃1か月分</text></svg>", "choices": [{"label": "双方合わせて代金の3%+6万円が上限", "reason": "3%＋6万円は一方からの上限です（告示）。双方合計では最大6%＋12万円まで受け取れます。", "caution": "一方から：3%＋6万円。双方合計：最大6%＋12万円（告示）。"}, {"label": "一方の依頼者から代金の5%が上限", "reason": "5%は200万円以下の部分の料率です（告示）。400万円超の速算式は3%＋6万円です。", "caution": ""}, {"label": "双方合わせて代金の6%+12万円が上限", "reason": "これは正しい内容ですが（双方合計の最大値）、設問の選択肢1が「一方から」の上限を問う正解です。", "caution": ""}], "summary": {"head": ["売買媒介の報酬上限（400万円超・告示）", "金額"], "rows": [["一方の依頼者から", "代金×3%＋6万円（税別）"], ["双方合計の最大", "代金×6%＋12万円（税別）"], ["消費税", "別途加算可"]]}}},
  {id:10248,unit:'l_hosho',level:2,field:'law',text:'営業保証金の供託先として正しいものはどれか。',opts:['都道府県知事が指定する金融機関','主たる事務所の最寄りの供託所（法務局等）','国土交通大臣が指定する法務局','市区町村が設置する供託所'],ans:1,exp:`営業保証金は主たる事務所の最寄りの供託所（法務局・地方法務局等）に供託します（宅建業法25条1項）。`,"kaisetsu":{"topic": "営業保証金・保証協会：主1,000万・従500万/営業保証金vs分担金60万・30万", "basis": {"text": "営業保証金は主1,000万・従500万（宅建業法25条）。保証協会の分担金は主60万・従30万（同法64条の9）。還付対象は業者以外の取引した者。加入は任意。不足補充は通知後2週間以内。", "example": ""}, "reason": {"text": "営業保証金は主たる事務所の最寄りの供託所（法務局・地方法務局・支局等）に供託します（宅建業法25条1項）。都道府県知事が指定する金融機関や国土交通大臣が指定する法務局ではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">営業保証金と弁済業務保証金</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">営業保証金</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">弁済業務保証金（分担金）</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">主たる事務所</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000万円</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">60万円</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従たる事務所/所</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">500万円</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">還付対象</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者以外</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者以外</text></svg>", "choices": [{"label": "都道府県知事が指定する金融機関", "reason": "供託所（法務局等）に供託します（宅建業法25条1項）。知事指定の金融機関ではありません。", "caution": "供託先＝最寄りの供託所（法務局等）。"}, {"label": "国土交通大臣が指定する法務局", "reason": "大臣指定ではなく、主たる事務所の最寄りの供託所です（宅建業法25条1項）。", "caution": ""}, {"label": "市区町村が設置する供託所", "reason": "市区町村は供託所を設置しません。供託所は法務大臣が設置する法務局等です（宅建業法25条1項・供託法）。", "caution": ""}], "summary": {"head": ["営業保証金の供託手続き", "内容"], "rows": [["供託先", "主たる事務所の最寄りの供託所（法務局等）"], ["供託の方法", "現金または有価証券"], ["届出", "供託後に免許権者へ届出"], ["業務開始", "届出後に業務開始可"]]}}},
  {id:10249,unit:'l_cooling',level:2,field:'law',text:'クーリングオフを行使できる期間として正しいものはどれか。',opts:['申込みから8日以内','クーリングオフができる旨等を書面で告げられた日から8日以内','契約締結から10日以内','業者が指定した日から8日以内'],ans:1,exp:`クーリングオフは「クーリングオフができる旨等を書面で告げられた日から8日以内」に行使できます（宅建業法37条の2）。書面告知がない場合は期間制限なく行使可能です。`,"kaisetsu":{"topic": "クーリングオフ：告知日から8日以内・書面で・事務所では不可・全額返還", "basis": {"text": "クーリングオフは告知を受けた日から8日以内に書面で行います（宅建業法37条の2）。事務所・モデルルーム等での申込みはクーリングオフ不可。解除後業者は全額返還（費用控除不可）。", "example": ""}, "reason": {"text": "クーリングオフの行使期間は、業者から書面でクーリングオフができる旨等を告げられた日から8日以内です（宅建業法37条の2第1項）。申込みの日や契約締結日ではなく、告知を受けた日が起算点です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">クーリングオフのポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">告知日から8日以内</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">方法</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面（発信主義）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所での申込み</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">クーリングオフ不可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除後</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全額返還</text></svg>", "choices": [{"label": "申込みから8日以内", "reason": "起算点は申込みの日ではなく、クーリングオフができる旨を書面で告げられた日です（宅建業法37条の2第1項）。", "caution": "起算点：書面による告知を受けた日（申込み日・契約日ではない）。"}, {"label": "契約締結から10日以内", "reason": "10日という期間はありません（宅建業法37条の2第1項）。8日以内であり、起算点も告知日です。", "caution": ""}, {"label": "業者が指定した日から8日以内", "reason": "業者が指定した日ではなく、業者から書面でクーリングオフができる旨を告げられた日から8日以内です（宅建業法37条の2第1項）。", "caution": ""}], "summary": {"head": ["クーリングオフの行使期間（宅建業法37条の2第1項）", "内容"], "rows": [["起算日", "書面でクーリングオフ可能な旨を告げられた日"], ["行使期間", "告げられた日から8日以内"], ["告知がない場合", "時効的に期間が進まない（いつでも行使可）"], ["書面の起算点", "書面を受け取った日（初日算入）"]]}}},
  {id:10250,unit:'k_toshi',level:2,field:'limit',text:'準都市計画区域について正しいものはどれか。',opts:['市街化区域と市街化調整区域の中間に位置する区域','都市計画区域外で乱開発防止が必要な地域に都道府県が指定できる区域','都市計画法の規制が一切及ばない区域','開発許可が常に不要な区域'],ans:1,exp:`準都市計画区域は都市計画区域外であっても、放置すれば無秩序な土地利用が行われる恐れのある区域として都道府県が指定する区域です（都市計画法5条の2）。一定の都市計画規制が適用されます。`,"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域の1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "準都市計画区域は都市計画区域外で乱開発のおそれがある地域に都道府県が指定できる区域です（都市計画法5条の2）。都市計画区域に準じた土地利用規制が行われます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "市街化区域と市街化調整区域の中間に位置する区域", "reason": "準都市計画区域は都市計画区域外の区域であり、市街化区域・市街化調整区域の中間ではありません（都市計画法5条の2）。", "caution": "準都市計画区域：都市計画区域外の乱開発防止が必要な区域（都市計画法5条の2）。"}, {"label": "都市計画法の規制が一切及ばない区域", "reason": "準都市計画区域には都市計画法の一定の規制が及びます（都市計画法5条の2）。「規制なし」は誤りです。", "caution": ""}, {"label": "開発許可が常に不要な区域", "reason": "準都市計画区域でも開発許可が必要な場合があります（都市計画法29条1項）。", "caution": ""}], "summary": {"head": ["準都市計画区域（都市計画法5条の2）", "内容"], "rows": [["指定者", "都道府県知事"], ["場所", "都市計画区域外の乱開発防止が必要な地域"], ["規制", "一定の用途・建ぺい率・容積率等の規制"], ["開発許可", "3000㎡以上の開発行為に必要"]]}}},
  {id:10251,unit:'k_kenchiku',level:2,field:'limit',text:'共同住宅の共用廊下・共用階段の床面積の容積率計算における扱いとして正しいものはどれか。',opts:['容積率計算の基礎となる延べ面積に算入する','容積率計算の基礎となる延べ面積から除外される','建築面積には算入するが容積率計算から除外される','建築主事の裁量による'],ans:1,exp:`共同住宅（マンション等）の共用廊下・共用階段の床面積は容積率算定の基礎となる延べ面積から除外されます（建築基準法52条6項）。居住者の共用部分の負担軽減を目的とした規定です。`,"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・用途制限・道路斜線", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。防火地域の耐火建築物は隣地境界線に外壁を接して建築可（同法65条）。", "example": ""}, "reason": {"text": "共同住宅の共用廊下・共用階段の床面積は容積率計算の基礎となる延べ面積から除外されます（建築基準法52条6項）。住戸部分の床面積の合計だけで容積率を計算します。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">防火地域の耐火建築物</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">隣地境界線に接して建築可</text></svg>", "choices": [{"label": "容積率計算の基礎となる延べ面積に算入する", "reason": "共用廊下・共用階段は容積率計算の延べ面積から除外されます（建築基準法52条6項）。「算入する」は誤りです。", "caution": "共同住宅の共用廊下・共用階段：容積率計算の延べ面積から除外（建築基準法52条6項）。"}, {"label": "建築面積には算入するが容積率計算から除外される", "reason": "共用廊下等は建築面積の計算では通常含まれますが、容積率計算の延べ面積からは除外されます（建築基準法52条6項）。", "caution": ""}, {"label": "建築主事の裁量による", "reason": "建築主事の裁量ではなく、法律上当然に除外されます（建築基準法52条6項）。", "caution": ""}], "summary": {"head": ["共同住宅の共用廊下・階段（建築基準法52条6項）", "容積率計算"], "rows": [["共用廊下", "除外"], ["共用階段", "除外"], ["住戸部分", "算入"], ["駐車場", "1/5まで除外（同条3項）"]]}}},
  {id:10252,unit:'k_nochi',level:2,field:'limit',text:'農地の転用（農地法4条）の許可権者として正しいものはどれか。',opts:['市町村長','農業委員会','都道府県知事（4ha超は農林水産大臣）','国土交通大臣'],ans:2,exp:`農地の自己転用（農地法4条）の許可権者は都道府県知事です。ただし農地面積が4haを超える転用については農林水産大臣の許可が必要です（農地法4条1項）。`,"kaisetsu":{"topic": "農地法：3条は農業委員会・4・5条は都道府県知事・市街化区域は届出のみ", "basis": {"text": "農地法3条の許可権者は農業委員会。4・5条は都道府県知事等。市街化区域の農地転用（4・5条）は農業委員会への届出のみOK。相続は許可不要・3か月以内の農業委員会への届出が必要。", "example": ""}, "reason": {"text": "農地の転用（農地法4条）の許可権者は都道府県知事です（農地法4条1項）。4ヘクタール超の農地の転用は農林水産大臣の許可が必要です（同条1項但書）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text></svg>", "choices": [{"label": "市町村長", "reason": "農地法4条の許可権者は市町村長ではありません（農地法4条1項）。", "caution": "農地法4条：都道府県知事（4ha超は農林水産大臣）。"}, {"label": "農業委員会", "reason": "農業委員会は農地法3条の許可権者です（農地法3条1項）。4条は都道府県知事です。", "caution": ""}, {"label": "国土交通大臣", "reason": "農地法4条の許可権者は国交大臣ではありません（農地法4条1項）。", "caution": ""}], "summary": {"head": ["農地法4条の許可権者", "内容"], "rows": [["2アール未満の農業用施設転用", "許可不要（農地法4条1項但書）"], ["市街化区域内の農地", "農業委員会への届出（許可不要）"], ["4ha以下の農地", "都道府県知事"], ["4ha超の農地", "農林水産大臣"]]}}},
  {id:10253,unit:'k_kukaku',level:2,field:'limit',text:'土地区画整理事業の施行者になれる者として正しいものはどれか。',opts:['個人・組合・区画整理会社・市町村・都道府県・独立行政法人等多様な主体が認められる','都道府県と市町村のみ','国のみ','宅建業者のみ'],ans:0,exp:`土地区画整理事業の施行者は個人・組合・区画整理会社・市町村・都道府県・国土交通大臣・独立行政法人都市再生機構等、多様な主体が認められています（土地区画整理法3条〜3条の4）。`,"kaisetsu":{"topic": "土地区画整理法：換地は公告翌日確定・仮換地は従前地使用不可・組合は2/3以上", "basis": {"text": "換地処分の公告翌日から換地が確定します（土地区画整理法104条）。仮換地の指定後は従前地を使用できなくなります（同法99条）。組合設立には土地所有者・借地権者の各2/3以上の同意が必要です。", "example": ""}, "reason": {"text": "土地区画整理事業の施行者は個人・土地区画整理組合・区画整理会社・市町村・都道府県・国土交通大臣・独立行政法人等多様な主体が認められています（土地区画整理法3条〜7条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">土地区画整理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">換地の確定</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公告の翌日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮換地指定後</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従前地は使用不可（所有権は残る）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">組合設立</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各2/3以上の同意</text></svg>", "choices": [{"label": "都道府県と市町村のみ", "reason": "個人・組合・区画整理会社なども施行者になれます（土地区画整理法3条〜7条）。", "caution": "施行者：個人・組合・会社・市町村・都道府県・独立行政法人等（土地区画整理法3条〜7条）。"}, {"label": "国のみ", "reason": "国のみではありません（土地区画整理法3条〜7条）。", "caution": ""}, {"label": "宅建業者のみ", "reason": "宅建業者のみという規定はありません（土地区画整理法3条〜7条）。", "caution": ""}], "summary": {"head": ["施行者の種類", "内容"], "rows": [["個人・組合・会社", "可"], ["市町村・都道府県", "可"], ["国・独立行政法人", "可"]]}}},
  {id:10254,unit:'r_saikensoron',level:2,field:'rights',text:'相殺の要件として正しいものはどれか。',opts:['双方の債務が同種であれば受働債権の弁済期が未到来でも相殺できる','自働債権（相殺する側の債権）は弁済期が到来していることが必要','相殺は内容証明郵便で行わなければならない','不法行為による損害賠償債権は何でも相殺に使える'],ans:1,exp:`相殺の要件のひとつとして、自働債権（相殺する側の債権）の弁済期が到来していることが必要です（民法505条1項）。受働債権の弁済期は未到来でも相殺可能。不法行為等を原因とする債権への相殺は一定制限があります（民法509条）。`,"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要（民法446条2項）。連帯保証人は催告・検索の抗弁権なし（民法454条）。債権譲渡の第三者対抗は確定日付ある証書による通知・承諾（民法467条2項）。相殺の絶対的効力：弁済・更改・相殺。", "example": ""}, "reason": {"text": "相殺（民法505条）の要件は①自働債権（相殺する側の債権）の弁済期が到来していること、②受働債権（相殺される側の債権）も弁済期が到来していること（ただし受働債権の弁済期前でも期限の利益放棄で可）、③双方の債権が同種であることです。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">催告・検索の抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text></svg>", "choices": [{"label": "双方の債務が同種であれば受働債権の弁済期が未到来でも相殺できる", "reason": "受働債権（相殺される側）の弁済期が未到来でも期限の利益を放棄すれば相殺できます（民法505条1項）。ただし自働債権は弁済期が到来していることが必要です。", "caution": "自働債権の弁済期到来が必要。受働債権は期限の利益放棄で対応可。"}, {"label": "相殺は内容証明郵便で行わなければならない", "reason": "相殺の意思表示に内容証明郵便は不要です（民法505条2項）。口頭でも有効ですが証明のため書面が望ましいです。", "caution": ""}, {"label": "不法行為による損害賠償債権は何でも相殺に使える", "reason": "悪意の不法行為・人の生命・身体侵害による損害賠償債権を受働債権として相殺することは禁止されています（民法509条）。", "caution": ""}], "summary": {"head": ["相殺の要件（民法505条）", "内容"], "rows": [["自働債権（相殺する側）", "弁済期が到来していること"], ["受働債権（相殺される側）", "弁済期到来が必要（期限の利益放棄で対応可）"], ["同種の債権", "双方が金銭等の同種の債権"], ["禁止", "悪意の不法行為・人身損害の賠償債権は受働債権不可（民法509条）"]]}}},
  {id:10255,unit:'r_ishi',level:2,field:'rights',text:'第三者による詐欺（AがBに騙されCに売却）の場合の取消しの対抗について正しいものはどれか。',opts:['AはCの善意悪意に関わらず常に取消しを対抗できる','AはCが詐欺の事実を知っていた（悪意）または知ることができた（有過失）場合のみ対抗できる','AはCに対して取消しを対抗できない','詐欺者Bへの損害賠償のみが認められる'],ans:1,exp:`第三者による詐欺の場合、取消しは相手方（C）が詐欺の事実を知りまたは知ることができた場合（悪意・有過失）のみ対抗できます（民法96条3項）。Cが善意無過失であれば保護されます。`,"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失保護）・通謀虚偽表示（無効・善意保護）。", "example": ""}, "reason": {"text": "第三者詐欺（被害者以外の第三者が詐欺行為をした場合）は、相手方が詐欺の事実を知っていた（悪意）または知ることができた（有過失）場合のみ取消しを対抗できます（民法96条2項）。通常の詐欺（民法96条1項）より要件が厳しくなります。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "AはCの善意悪意に関わらず常に取消しを対抗できる", "reason": "第三者詐欺の場合、相手方Cが詐欺の事実について悪意または有過失の場合のみ取消しを対抗できます（民法96条2項）。Cが善意無過失であれば対抗できません。", "caution": ""}, {"label": "AはCに対して取消しを対抗できない", "reason": "Cが詐欺の事実について悪意または有過失であれば、AはCに対して取消しを対抗できます（民法96条2項）。完全に対抗できないわけではありません。", "caution": ""}, {"label": "詐欺者Bへの損害賠償のみが認められる", "reason": "損害賠償請求に加えて、要件を満たせば取消しも主張できます。取消しと損害賠償は両立します。", "caution": ""}], "summary": {"head": ["詐欺の種類", "取消し", "要件"], "rows": [["相手方による詐欺（96条1項）", "可", "詐欺の事実のみ"], ["第三者による詐欺（96条2項）", "可（限定的）", "相手方が悪意または有過失"]]}}},
  {id:10256,unit:'l_kantoku',level:2,field:'law',text:'宅建士が不正手段で登録を受けた場合の処分として正しいものはどれか。',opts:['業務停止処分のみ','登録を消除される','戒告のみ','免許取消しと同時に登録消除'],ans:1,exp:`不正手段で宅建士の登録を受けた者は登録を消除されます（宅建業法68条の2第1項2号）。登録消除後5年間は再登録できません。`,"kaisetsu":{"topic": "監督処分：業務停止最長1年・大臣は全業者に指示可・指示違反→業務停止", "basis": {"text": "業務停止の最長期間は1年（宅建業法65条2項）。大臣は全業者（知事免許含む）に指示処分を行う権限があります。指示処分違反→業務停止、業務停止違反→免許取消という段階があります。", "example": ""}, "reason": {"text": "宅建士が不正手段で登録を受けた場合は必要的登録消除事由となります（宅建業法68条の2第1項2号）。業務停止処分にとどまらず、必ず登録を消除されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">監督処分のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">処分</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">最長1年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣の権限</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全業者に指示可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">指示処分違反</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止の対象</text></svg>", "choices": [{"label": "業務停止処分のみ", "reason": "不正手段による登録は必要的登録消除事由です（宅建業法68条の2第1項2号）。業務停止のみではありません。", "caution": "不正手段での登録：必要的登録消除（宅建業法68条の2第1項2号）。"}, {"label": "戒告のみ", "reason": "戒告は宅建業法上の宅建士処分として明示されていません。不正手段の登録は必要的登録消除です（宅建業法68条の2第1項2号）。", "caution": ""}, {"label": "免許取消しと同時に登録消除", "reason": "宅建士の登録と宅建業の免許は別制度です。宅建士の処分（登録消除）と業者の免許取消は連動しません。", "caution": ""}], "summary": {"head": ["宅建士への処分（宅建業法68条・68条の2）", "内容"], "rows": [["指示処分", "軽微な違反"], ["事務禁止処分", "最長1年（宅建業法68条1項）"], ["登録消除（任意的）", "一定の違反"], ["登録消除（必要的）", "不正登録・事務禁止処分違反等（宅建業法68条の2第1項）"]]}}},
  {id:10257,unit:'l_sonota',level:2,field:'law',text:'住宅瑕疵担保責任保険（住宅瑕疵担保履行法）の加入先として正しいものはどれか。',opts:['国土交通大臣が指定した住宅瑕疵担保責任保険法人','国が直接引き受ける','都道府県が設立した機関のみ','宅建業協会が提供する保険'],ans:0,exp:`住宅瑕疵担保責任保険は国土交通大臣が指定した住宅瑕疵担保責任保険法人（日本住宅保証検査機構・住宅保証機構等）に加入します（住宅瑕疵担保履行法2条7項）。`,"kaisetsu":{"topic": "宅建業者のその他の業務：従業者証明書・帳簿・業務処理原則", "basis": {"text": "全従業者に従業者証明書の交付が必要で業務中は常時携帯（宅建業法48条）。帳簿は事務所ごとに5年保存（自ら売主の新築住宅は10年）（同法49条）。宅建業者は信義誠実の原則に従って業務を行う必要があります（同法31条）。", "example": ""}, "reason": {"text": "住宅瑕疵担保責任保険は国土交通大臣が指定した住宅瑕疵担保責任保険法人に加入します（住宅瑕疵担保履行法2条7項・17条の2）。国や都道府県が直接引き受けるわけではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業者のその他の義務</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従業者証明書</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全従業者に交付・業務中携帯</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">帳簿</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所ごと・5年保存（新築自ら売主は10年）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務処理原則</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">信義誠実の原則</text></svg>", "choices": [{"label": "国が直接引き受ける", "reason": "国が直接引き受けるのではなく、国土交通大臣が指定した住宅瑕疵担保責任保険法人（民間法人）が引き受けます（住宅瑕疵担保履行法2条7項）。", "caution": "加入先：国土交通大臣指定の住宅瑕疵担保責任保険法人（民間法人）。"}, {"label": "都道府県が設立した機関のみ", "reason": "都道府県の機関ではなく国土交通大臣が指定した住宅瑕疵担保責任保険法人です（住宅瑕疵担保履行法2条7項）。", "caution": ""}, {"label": "宅建業協会が提供する保険", "reason": "宅建業協会が提供する保険ではありません（住宅瑕疵担保履行法2条7項）。", "caution": ""}], "summary": {"head": ["住宅瑕疵担保責任保険の加入先", "内容"], "rows": [["加入先", "国土交通大臣が指定した住宅瑕疵担保責任保険法人"], ["現在の指定法人", "住宅保証機構等（民間法人）"], ["指定制度", "住宅瑕疵担保履行法17条の2"]]}}},
  {id:10258,unit:'t_joto',level:2,field:'tax',text:'居住用財産の軽減税率の特例（長期所有・6,000万円以下の部分に14%）の適用要件として正しいものはどれか。',opts:['所有期間が5年超であれば適用できる','譲渡した年の1月1日現在で所有期間が10年超であること','3,000万円特別控除との併用は不可','夫婦間の売買でも適用できる'],ans:1,exp:`居住用財産の軽減税率特例（6,000万円以下の部分が税率14%）は、譲渡した年の1月1日現在で所有期間が10年超であることが必要です（租税特別措置法31条の3）。3,000万円特別控除との併用も可能です。`,"kaisetsu":{"topic": "譲渡所得：分離課税・長期は20%・3,000万円控除は3年に1回", "basis": {"text": "土地・建物の譲渡所得は分離課税。長期（5年超）は合計20%（所得税15%+住民税5%）。短期（5年以下）は39%（所得税30%+住民税9%）。3,000万円特別控除は前年・前々年に適用があれば使えません（3年に1回）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">譲渡所得のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税方式</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">分離課税</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">長期（5年超）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計20%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">短期（5年以下）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計39%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3,000万円控除</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年に1回の制限</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10259,unit:'t_shutoku',level:2,field:'tax',text:'不動産取得税の税率（住宅及び土地・当分の間の特例税率）として正しいものはどれか。',opts:['4%','3%','2%','1.5%'],ans:1,exp:`不動産取得税の本則税率は4%ですが、住宅及び土地については当分の間3%の特例税率が適用されます（地方税法附則11条の2）。`,"kaisetsu":{"topic": "不動産取得税：都道府県が課す地方税・相続は非課税・1回だけ課税", "basis": {"text": "不動産取得税は都道府県が課す地方税（地方税法73条の2）。相続・法人の合併等は非課税。一度の取得に一度だけ課税（毎年ではない）。標準税率は4%（住宅・土地は3%の軽減あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産取得税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税の頻度</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取得時に1回のみ</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">標準税率</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4%（住宅・土地は3%）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10260,unit:'t_kotei',level:2,field:'tax',text:'固定資産税の賦課期日（課税の基準日）として正しいものはどれか。',opts:['毎年4月1日','毎年1月1日','毎年3月31日','課税年度の開始時点'],ans:1,exp:`固定資産税は毎年1月1日（賦課期日）現在に固定資産課税台帳に登録されている者を納税義務者として課税します（地方税法343条1項・359条）。`,"kaisetsu":{"topic": "固定資産税：市町村が課す地方税・賦課期日は1月1日・評価替えは3年ごと", "basis": {"text": "固定資産税は市町村（東京23区は都）が課す地方税（地方税法343条）。賦課期日は毎年1月1日。評価替えは3年ごと（基準年度）。住宅用地の特例：200㎡以下は課税標準1/6、超過部分は1/3。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">固定資産税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市町村（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賦課期日</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">評価替え</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年ごと</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅用地（200㎡以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税標準1/6</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10261,unit:'t_toroku',level:2,field:'tax',text:'相続による所有権移転登記の登録免許税率として正しいものはどれか。',opts:['2%','1%','0.4%','0.2%'],ans:2,exp:`相続による所有権移転登記の登録免許税率は固定資産税評価額の0.4%です（登録免許税法別表第一）。売買は2%、贈与・財産分与等は2%（一般）となります。`,"kaisetsu":{"topic": "登録免許税：所有権移転登記等に課税・国税・税率は課税標準×一定率", "basis": {"text": "登録免許税は不動産の所有権移転登記等に課税される国税（登録免許税法1条）。税率は課税標準（通常は固定資産税評価額）×一定率で計算します。相続による所有権移転登記は0.4%、売買は2%が原則税率（軽減措置あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">登録免許税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">国（国税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税対象</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">所有権移転登記等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">0.4%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2%（軽減措置あり）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10262,unit:'t_inshi',level:2,field:'tax',text:'不動産売買契約書への印紙税軽減措置（令和9年3月31日まで延長）の対象として正しいものはどれか。',opts:['買主が個人の場合のみ適用','記載金額が10万円超の不動産売買契約書に軽減税率が適用される','記載金額が1,000万円超の場合のみ軽減税率','軽減措置は既に廃止されている'],ans:1,exp:`平成26年4月1日以降令和9年3月31日まで（延長済み）、記載金額が10万円超の不動産売買契約書等について印紙税の軽減税率が適用されています。電子契約書（データのみ）は印紙税の対象外です。`,"kaisetsu":{"topic": "印紙税：売買・賃貸借契約書は課税文書・電子契約は非課税・1万円未満は非課税", "basis": {"text": "不動産の売買契約書・賃貸借契約書は印紙税の課税文書（第1号文書）。電子契約は課税対象外（文書でないため）。1万円未満の記載金額は非課税。複数当事者が保有する各通に課税。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">印紙税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買・賃貸借契約書</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税文書（第1号）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">電子契約</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1万円未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10263,unit:'t_chika',level:2,field:'tax',text:'地価公示における標準地の鑑定評価者として正しいものはどれか。',opts:['国土交通大臣が指定した宅建業者','2人以上の不動産鑑定士','1人の不動産鑑定士のみ','都道府県の職員'],ans:1,exp:`地価公示では標準地1地点について2人以上の不動産鑑定士が鑑定評価を行い、その結果をもとに土地鑑定委員会が正常価格を判定・公示します（地価公示法2条2項）。`,"kaisetsu":{"topic": "地価公示・不動産鑑定評価：基準日は1月1日・土地鑑定委員会が実施・3手法", "basis": {"text": "地価公示の基準日は毎年1月1日で土地鑑定委員会（国土交通省）が実施（地価公示法）。公示価格は鑑定評価の規準となります（同法8条）。不動産鑑定評価の3手法：原価法・取引事例比較法・収益還元法。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">地価公示・鑑定評価</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">基準日</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">実施機関</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">土地鑑定委員会（国土交通省）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">鑑定評価の3手法</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原価法・取引事例比較法・収益還元法</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10264,unit:'t_kinyu',level:2,field:'tax',text:'住宅金融支援機構の主な業務として正しいものはどれか。',opts:['住宅ローンを直接個人に融資することが主たる業務','民間金融機関の住宅ローン債権を買い取る証券化支援業務が主たる業務','住宅建設のための補助金を給付する','固定資産税の還付業務を行う'],ans:1,exp:`住宅金融支援機構の主たる業務は民間金融機関の住宅ローン債権を買い取る証券化支援業務（フラット35等）です（住宅金融支援機構法13条）。直接融資は災害復興住宅等一部の特殊な用途に限定されています。`,"kaisetsu":{"topic": "住宅金融支援機構・フラット35：証券化支援が主業務・全期間固定・各機関が金利設定", "basis": {"text": "住宅金融支援機構はフラット35（民間住宅ローンの証券化支援）が主業務。フラット35は全期間固定金利のみで変動金利の選択はできません。金利は各民間金融機関が独自に設定。返済期間は15年以上35年以下。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">フラット35のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">主な業務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">民間住宅ローンの証券化支援</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">金利</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全期間固定・各金融機関が設定</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">返済期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">15年以上35年以下</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">申込み先</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">民間金融機関</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10265,unit:'t_tokei',level:2,field:'tax',text:'不動産鑑定評価における収益還元法のDCF法（割引キャッシュフロー法）について正しいものはどれか。',opts:['一時点の純収益のみを還元率で割り戻す方法','将来の各期間の純収益と保有終了時の価値を現在価値に割り引いて合計する方法','原価を積み上げて評価する方法','取引事例を収集して比較する方法'],ans:1,exp:`DCF法は将来の各期間の純収益と保有終了時の不動産価値（復帰価格）を割引率で現在価値に換算して合計する方法です（不動産鑑定評価基準）。一期の純収益を還元率で割る方法は直接還元法です。`,"kaisetsu":{"topic": "不動産統計・土地・建物の知識", "basis": {"text": "住宅着工戸数は近年80万戸前後。首都圏マンション価格は上昇傾向。J-REITの運用資産は拡大傾向。中古住宅流通は活発化。台地は宅地に適しており、干拓地は水害リスクが高いです。扇状地は比較的安定した地盤です。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産統計・土地の特性</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">近年の傾向</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅着工戸数</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">80万戸前後</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">首都圏マンション価格</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">上昇傾向</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">J-REIT</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">拡大傾向</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">干拓地</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">水害リスク高</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10266,unit:'r_sorin',level:2,field:'rights',text:'地役権の性質として正しいものはどれか。',opts:['地役権は登記しなくても常に第三者に対抗できる','地役権は要役地の所有権に従って移転し、分離して譲渡できない','地役権は承役地の所有者が単独で消滅させられる','地役権の存続期間は最長10年'],ans:1,exp:`地役権は要役地（利益を受ける土地）の便益のために承役地（負担を負う土地）に設定される物権です（民法280条）。地役権は要役地の所有権に従い、これと分離して譲渡したり他の権利の目的としたりすることはできません（民法281条）。`,"kaisetsu":{"topic": "相隣関係：竹木の根は自ら切除可・枝は原則所有者に・境界から50cmは慣習で変更可", "basis": {"text": "竹木の根が境界を越えたら自ら切除可（民法233条2項）。枝は原則として所有者に切除させます。建物の境界からの距離（50cm）は慣習・条例で変更可（民法234条・236条）。袋地通行権は有償が原則（民法212条）。", "example": ""}, "reason": {"text": "地役権は要役地（便益を受ける土地）の所有権に従って移転し、要役地と分離して譲渡・担保設定することはできません（民法281条1項）。これを地役権の附従性といいます。対抗要件として登記が必要です（民法177条）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相隣関係のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">事項</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">ルール</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">竹木の根（越境）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自ら切除可</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">竹木の枝（越境）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則：所有者に切除させる</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">境界距離（50cm）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">慣習・条例で変更可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">袋地通行権</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有償が原則</text></svg>", "choices": [{"label": "地役権は登記しなくても常に第三者に対抗できる", "reason": "地役権も物権変動の対抗要件として登記が必要です（民法177条）。「常に対抗できる」は誤りです。", "caution": "地役権の対抗要件＝登記（民法177条）。"}, {"label": "地役権は承役地の所有者が単独で消滅させられる", "reason": "地役権は設定契約または時効・放棄等により消滅します。承役地の所有者が単独で消滅させることはできません（民法280条・281条）。", "caution": ""}, {"label": "地役権の存続期間は最長10年", "reason": "地役権の存続期間に法定の上限はありません（民法280条）。10年という制限はありません。", "caution": ""}], "summary": {"head": ["地役権の特徴", "内容"], "rows": [["附従性", "要役地の所有権に従って移転（分離処分不可・民法281条1項）"], ["対抗要件", "登記（民法177条）"], ["継続性・外形性", "時効取得の要件"], ["消滅", "放棄・時効・土地の消滅等"]]}}},
  {id:10267,unit:'r_ishi',level:2,field:'rights',text:'錯誤による意思表示の取消しが認められる要件として正しいものはどれか。',opts:['軽微な錯誤でも常に取消し可能','動機の錯誤は常に無効','錯誤が法律行為の目的及び取引上の社会通念に照らして重要であること','相手方に詐欺があった場合のみ'],ans:2,exp:`錯誤による取消し（民法95条）は、①錯誤が法律行為の目的及び取引上の社会通念に照らして重要であること、②表意者に重大な過失がないこと（または相手方が同一の錯誤に陥っていた等の場合）が要件です。動機の錯誤は要素の錯誤に当たらず、相手方に表示・了解されていた場合に取消し可能です。`,"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失保護）・通謀虚偽表示（無効・善意保護）。", "example": ""}, "reason": {"text": "錯誤取消しは法律行為の目的および取引上の社会通念に照らして重要な錯誤に限られます。軽微な誤解まで取消しを認めると取引の安全が著しく損なわれるためです（民法95条1項）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "軽微な錯誤でも常に取消し可能", "reason": "錯誤取消しは重要な錯誤に限られます（民法95条1項）。軽微な錯誤は対象外です。", "caution": ""}, {"label": "動機の錯誤は常に無効", "reason": "動機の錯誤は原則として取消しの対象外ですが、動機が表示されて法律行為の内容となった場合は取消しが認められる場合があります（民法95条2項）。「常に無効」は誤りです。", "caution": "動機の錯誤＝原則取消し不可、ただし動機が表示・法律行為の内容となった場合は可。"}, {"label": "相手方に詐欺があった場合のみ", "reason": "錯誤（民法95条）は詐欺とは別の制度です。相手方に詐欺がなくても、表意者自身の重要な錯誤があれば取消しの対象になります。", "caution": ""}], "summary": {"head": ["錯誤の種類", "取消しの可否", "条件"], "rows": [["法律行為の内容の錯誤", "可", "重要な錯誤・表意者の重過失なし"], ["動機の錯誤", "原則不可", "動機が表示・内容化された場合は可"], ["軽微な錯誤", "不可", "—"]]}}},
  {id:10268,unit:'r_dairi',level:2,field:'rights',text:'復代理人に関する説明として正しいものはどれか。',opts:['復代理人の行為は本人に直接効果が帰属しない','任意代理人は本人の許諾がある場合または止むを得ない事情がある場合にのみ復任権を有する','法定代理人は常に復代理人を選任できるが無限責任を負う','復代理人は代理人の代理人なので本人に対し権限を持たない'],ans:1,exp:`任意代理人の復任権（民法104条）は本人の許諾がある場合または止むを得ない事由がある場合に限られます。法定代理人は常に復任権がありますが責任は軽減されます（民法106条）。復代理人は本人を直接代理し本人に効果が帰属します。`,"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護します。", "example": ""}, "reason": {"text": "任意代理人の復任権は制限されています（民法104条）。本人との信頼関係に基づく任意代理では、勝手に復代理人を選任することは本人の意思に反する可能性があるため、本人の許諾または止むを得ない事情がある場合に限られます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "復代理人の行為は本人に直接効果が帰属しない", "reason": "復代理人の行為は本人に直接効果が帰属します（民法107条2項）。代理人を経由する必要はありません。", "caution": ""}, {"label": "法定代理人は常に復代理人を選任できるが無限責任を負う", "reason": "法定代理人は原則として自由に復代理人を選任できますが（民法105条）、選任・監督について責任を負います。「無限責任」という表現は誤りです。", "caution": "任意代理人と法定代理人の復任権を区別しましょう。"}, {"label": "復代理人は代理人の代理人なので本人に対し権限を持たない", "reason": "復代理人は代理人の代理人ではなく、本人の代理人として直接本人に対して権限を持ちます（民法107条1項）。", "caution": ""}], "summary": {"head": ["代理の種類", "復任権", "責任"], "rows": [["任意代理人", "本人の許諾または止むを得ない事情が必要（民法104条）", "選任・監督責任を負う"], ["法定代理人", "原則自由に選任可（民法105条）", "選任・監督責任を負う（やむを得ない場合は責任軽減）"]]}}},
  {id:10269,unit:'r_jiko',level:2,field:'rights',text:'消滅時効の完成猶予（旧「中断」）事由として正しいものはどれか。',opts:['催告から6ヶ月以内に訴訟提起等をすれば時効の完成を猶予できる','内容証明郵便を送るだけで時効が更新（中断）される','承認は相手方の権利を知っている必要がある','強制執行の申立てだけでは時効に影響しない'],ans:0,exp:`催告（督促）をすると、その時から6ヶ月以内に訴訟・仮差押え等をすれば時効の完成が猶予されます（民法150条）。催告だけでは更新（中断）にはなりません。承認は承認者が相手方の権利を知っていることは要件とされていません（民法152条）。`,"kaisetsu":{"topic": "消滅時効：知った時から5年または行使可能時から10年", "basis": {"text": "消滅時効は「知った時から5年」または「行使可能時から10年」のいずれか早い方で完成します（民法166条）。時効は援用して初めて効力が発生します（民法145条）。承認は更新事由です（民法152条）。", "example": ""}, "reason": {"text": "催告（民法150条）は時効の完成を6か月間猶予しますが、更新はしません。催告から6か月以内に裁判上の請求・差押え等をしなければ猶予の効力が消滅します。催告の連発（再催告）は認められません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">期間</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人身損害</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年または20年</text></svg>", "choices": [{"label": "内容証明郵便を送るだけで時効が更新（中断）される", "reason": "催告は完成猶予のみで更新はしません（民法150条）。6か月以内に裁判上の請求等が必要です。", "caution": "催告＝完成猶予（6か月）のみ。更新のためには訴訟提起等が必要。"}, {"label": "承認は相手方の権利を知っている必要がある", "reason": "時効の更新事由となる「承認」は、相手方の権利の存在を知っているかどうかは要件ではありません（民法152条）。", "caution": ""}, {"label": "強制執行の申立てだけでは時効に影響しない", "reason": "強制執行の申立ては完成猶予事由です（民法148条1項2号）。時効に影響します。", "caution": ""}], "summary": {"head": ["時効の完成猶予と更新", "主な事由"], "rows": [["完成猶予のみ", "催告（6か月・民法150条）・協議合意（民法151条）"], ["完成猶予→更新", "裁判上の請求（民法147条）・強制執行（民法148条）"], ["更新のみ", "承認（民法152条）"]]}}},
  {id:10270,unit:'r_bukken',level:2,field:'rights',text:'混同による物権の消滅について、例外として消滅しない場合として正しいものはどれか。',opts:['所有権と地上権が同一人に帰属した場合','所有権と抵当権が同一人に帰属したが第三者が抵当権を目的とする権利を有する場合','所有権と地役権が同一人に帰属した場合','所有権と賃借権が同一人に帰属した場合'],ans:1,exp:`所有権と他の物権が同一人に帰属すると混同により物権は消滅しますが（民法179条）、第三者の権利の目的である場合は消滅しません。例えば抵当権が設定された不動産の所有権を抵当権者が取得しても、その抵当権を目的とする転抵当権があれば抵当権は消滅しません。`,"kaisetsu":{"topic": "物権変動：登記が対抗要件・不法占拠者には登記不要", "basis": {"text": "不動産の物権変動は登記が第三者への対抗要件です（民法177条）。不法占拠者には登記なく対抗できます（判例）。建物賃借権は引渡しが対抗要件です（借地借家法31条）。", "example": ""}, "reason": {"text": "民法179条は同一人に物権が帰属した場合に混同で消滅すると定めますが、第三者の権利保護が必要な場合は例外です。抵当権を目的とする転抵当権等が設定されている場合、抵当権が消滅すると第三者が不利益を受けるため消滅しません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">物権変動の対抗要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対抗要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">二重譲渡</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先に登記した者が優先</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不法占拠者</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記不要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物賃借権</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡し</text></svg>", "choices": [{"label": "所有権と地上権が同一人に帰属した場合", "reason": "所有権と地上権が同一人に帰属すると、地上権は混同により消滅します（民法179条1項）。ただし第三者がその地上権を目的とする権利（転貸地上権等）を有する場合は例外です。", "caution": ""}, {"label": "所有権と地役権が同一人に帰属した場合", "reason": "承役地の所有者が要役地を取得した場合、地役権は混同により消滅します（民法179条1項）。", "caution": ""}, {"label": "所有権と賃借権が同一人に帰属した場合", "reason": "賃借権は債権なので、民法520条（債権の混同）により消滅します。第三者の権利目的でない限り消滅します。", "caution": ""}], "summary": {"head": ["混同の原則", "例外（消滅しない場合）"], "rows": [["同一人に所有権＋制限物権が帰属→消滅", "第三者がその物権を目的とする権利を持つとき"], ["例：抵当権＋所有権が同一人に→消滅", "転抵当権者等が存在すれば消滅しない"]]}}},
  {id:10271,unit:'r_touki',level:2,field:'rights',text:'中間省略登記の可否について正しいものはどれか。',opts:['当事者全員の同意があれば常に認められる','AからB、BからCへ売却した場合、BがCへ直接移転登記できる','中間省略登記は2024年改正で全面禁止となった','中間省略登記申請は登記官が職権で補正できる'],ans:0,exp:`中間省略登記は原則として認められませんが（判例・先例）、当事者（A・B・C）全員の合意がある場合は登記の申請が認められます。なおこの場合でも実体的な権利関係と登記が一致しないと問題が生じる場合があります。`,"kaisetsu":{"topic": "不動産登記：権利登記は共同申請・仮登記は順位保全・建物滅失は1か月以内", "basis": {"text": "権利に関する登記は原則として登記権利者と登記義務者が共同申請します（不動産登記法60条）。仮登記は順位保全機能があるが完全な対抗力は本登記後です。建物滅失登記の申請義務は1か月以内（同法57条）。", "example": ""}, "reason": {"text": "中間省略登記とはA→B→Cの順に所有権が移転した際にA→Cへ直接登記することです。原則として認められませんが、当事者全員（A・B・C）が同意した場合は例外的に許容されます（最判昭和40年）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産登記のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利登記</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則として共同申請</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮登記</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">順位保全（対抗力は本登記後）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物滅失登記</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1か月以内</text></svg>", "choices": [{"label": "BがCへ直接移転登記できる", "reason": "B単独ではCへ直接登記できません。A・B・C全員の同意が必要です。", "caution": ""}, {"label": "中間省略登記は2024年改正で全面禁止となった", "reason": "2024年改正でも中間省略登記が全面禁止されたという事実はありません。従来の判例ルール（全員同意で可）が維持されています。", "caution": ""}, {"label": "中間省略登記申請は登記官が職権で補正できる", "reason": "登記官は申請内容を職権で補正する権限はありません。申請を却下または補正指示することができます。", "caution": ""}], "summary": {"head": ["中間省略登記", "内容"], "rows": [["原則", "A→B→Cの移転はA→B・B→Cと2回登記が必要"], ["例外（判例）", "A・B・C全員が同意していれば直接A→C登記が可"], ["2024年改正", "相続登記義務化等の改正あり。中間省略の扱いは不変"]]}}},
  {id:10272,unit:'r_chinshaku',level:2,field:'rights',text:'転貸借（サブリース）に関する説明として正しいものはどれか。',opts:['賃借人は賃貸人の承諾なく転貸できる','賃貸人が承諾した転貸借では賃貸人は転借人に直接賃料請求できる','転借人は原賃貸人に対し転借人の債務額を超えた賠償義務を負う','賃貸人が承諾した転貸借では原賃貸借が終了しても転借人に対抗できない'],ans:1,exp:`適法な転貸借がある場合、賃貸人は転借人に対し直接履行の請求ができます（民法613条1項）。ただしその額は転借料と原賃料の低い方が上限です。無断転貸は解除原因となります。`,"kaisetsu":{"topic": "賃貸借：通常損耗は原状回復に含まれない・有益費は終了時に請求・賃料増額は正当事由が必要", "basis": {"text": "賃貸借終了時の原状回復義務に通常使用による損耗（壁の日焼け等）は含まれません（民法621条）。必要費は直ちに、有益費は終了時の請求が原則。更新拒絶には正当事由が必要（借地借家法28条）。", "example": ""}, "reason": {"text": "賃貸人が承諾した転貸借では、賃貸人は転借人に対して直接賃料請求ができます（民法613条1項）。ただし転借人が直接支払う義務の上限は転借料の範囲です。また適法な転貸借では原賃貸借が終了しても転借人保護規定があります。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">賃貸借のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通常損耗</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原状回復に含まれない</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要費</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直ちに請求可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有益費</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸借終了時に請求</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">更新拒絶</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当事由が必要</text></svg>", "choices": [{"label": "賃借人は賃貸人の承諾なく転貸できる", "reason": "転貸には原則として賃貸人の承諾が必要です（民法612条1項）。承諾なく転貸すると解除事由になりえます。", "caution": ""}, {"label": "転借人は原賃貸人に対し転借人の債務額を超えた賠償義務を負う", "reason": "転借人の直接義務は転借料の範囲が上限です（民法613条1項）。それを超えた義務は負いません。", "caution": ""}, {"label": "賃貸人が承諾した転貸借では原賃貸借が終了しても転借人に対抗できない", "reason": "適法な転貸借において原賃貸借が期間満了・合意解除で終了した場合、転借人保護規定により転借人を保護する場合があります（民法613条3項）。「常に対抗できない」は誤りです。", "caution": ""}], "summary": {"head": ["適法転貸借の効果", "内容"], "rows": [["転借人→賃貸人", "直接義務を負う（民法613条1項）"], ["賃貸人→転借人", "直接請求可（上限は転借料）"], ["原賃貸借の終了", "期間満了・合意解除→転借人保護あり（民法613条3項）"], ["無断転貸", "解除事由（信頼関係破壊の程度による）"]]}}},
  {id:10273,unit:'r_baibai',level:2,field:'rights',text:'売買目的物の契約不適合（瑕疵）に関して買主が権利を行使するための期間制限として正しいものはどれか。',opts:['種類・品質の不適合は不適合を知った時から1年以内に通知が必要','数量不足は引渡しから3年以内に訴訟提起が必要','契約不適合の発見から5年以内で引渡しから10年以内のいずれか早い方','通知期間の制限はなく消滅時効のみが適用される'],ans:0,exp:`種類・品質に関する不適合は、買主が不適合を知った時から1年以内に売主に通知しなければ、代金減額請求・損害賠償請求等ができなくなります（民法566条）。なお通知後の権利行使は消滅時効（5年又は10年）に服します。`,"kaisetsu":{"topic": "売買：同時履行の抗弁権・解除は原則催告が必要・契約不適合責任", "basis": {"text": "売買では代金と引渡しは同時履行の関係（民法533条）。解除は原則として相当の期間を定めた催告後に行います（民法541条）。契約不適合責任の通知は知った時から1年以内（民法566条）。", "example": ""}, "reason": {"text": "種類・品質の契約不適合は「引渡しから1年以内」ではなく「不適合を知った時から1年以内」に通知が必要です（民法566条）。数量不足・権利の不適合には民法566条の通知期限はなく一般の消滅時効（5年・10年）が適用されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">売買のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">同時履行</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金と引渡しは同時履行</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則として催告が必要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">契約不適合の通知</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から1年以内</text></svg>", "choices": [{"label": "数量不足は引渡しから3年以内に訴訟提起が必要", "reason": "数量の不適合には民法566条の1年の通知期限は適用されません。一般の消滅時効（5年・10年）のみです。「3年」という規定はありません。", "caution": "種類・品質の不適合→通知期限（1年）あり。数量・権利の不適合→通知期限なし。"}, {"label": "発見から5年以内で引渡しから10年以内のいずれか早い方", "reason": "これは一般の消滅時効期間（民法166条）の説明です。民法566条の通知期限（知った時から1年）とは別物です。", "caution": ""}, {"label": "通知期間の制限はなく消滅時効のみが適用される", "reason": "種類・品質の不適合には通知期限があります（民法566条）。「制限なし」は誤りです。", "caution": ""}], "summary": {"head": ["契約不適合の期間制限", "内容"], "rows": [["種類・品質の不適合", "知った時から1年以内に通知（民法566条）"], ["数量・権利の不適合", "一般消滅時効のみ（通知期限なし）"], ["消滅時効", "知った時から5年・引渡しから10年（民法166条）"]]}}},
  {id:10274,unit:'r_souzoku',level:2,field:'rights',text:'遺留分を有する相続人として正しいものはどれか。',opts:['配偶者・子・直系尊属・兄弟姉妹','配偶者・子・直系尊属（兄弟姉妹は含まない）','配偶者・子のみ','法定相続人全員'],ans:1,exp:`遺留分を有するのは配偶者・子（孫等の代襲相続人を含む）・直系尊属です（民法1042条）。兄弟姉妹（甥姪を含む）は遺留分を有しません。`,"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2・遺産分割は全員合意", "basis": {"text": "配偶者と子は各1/2（民法900条）。放棄は3か月以内に家裁へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2（民法1042条）。兄弟姉妹に遺留分はなし。遺産分割協議は全員合意が必要。", "example": ""}, "reason": {"text": "遺留分を有する相続人は配偶者・子（代襲相続人含む）・直系尊属です（民法1042条）。兄弟姉妹は法定相続人ですが遺留分は認められていません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "配偶者・子・直系尊属・兄弟姉妹", "reason": "兄弟姉妹には遺留分がありません（民法1042条）。", "caution": "兄弟姉妹＝遺留分なし。"}, {"label": "配偶者・子のみ", "reason": "直系尊属（父母・祖父母等）にも遺留分があります（民法1042条）。", "caution": ""}, {"label": "法定相続人全員", "reason": "法定相続人でも兄弟姉妹には遺留分がありません（民法1042条）。", "caution": ""}], "summary": {"head": ["相続人", "遺留分"], "rows": [["配偶者", "あり"], ["子（代襲相続人含む）", "あり"], ["直系尊属", "あり（子がいない場合）"], ["兄弟姉妹（甥・姪）", "なし"]]}}},
  {id:10275,unit:'r_fuhoko',level:2,field:'rights',text:'不法行為における過失相殺の説明として正しいものはどれか。',opts:['被害者に過失があれば加害者の責任は全額免除','裁判所は被害者の過失を考慮して損害賠償額を減額できる','被害者の過失は必ず損害額の50%以上を減額する','過失相殺は当事者の申立てがあった場合にのみ適用される'],ans:1,exp:`過失相殺（民法722条2項）は、損害の発生または拡大に被害者の過失が寄与した場合に、裁判所がその過失を考慮して損害賠償額を減額できる制度です。具体的な減額割合は裁判所の裁量によります。`,"kaisetsu":{"topic": "不法行為：故意または過失が必要・使用者責任・工作物責任", "basis": {"text": "不法行為は故意または過失が必要です（民法709条）。使用者は被用者の職務上の不法行為について責任を負います（民法715条）。工作物の所有者は無過失責任（占有者が免責された場合）（民法717条）。", "example": ""}, "reason": {"text": "過失相殺（民法722条2項）は、被害者にも過失がある場合に裁判所が損害賠償額を減額する制度です。裁判所が職権で考慮できます（当事者の申立ては不要）。被害者の過失の程度に応じて柔軟に減額されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不法行為のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般不法行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">故意または過失が必要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">使用者責任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">被用者への求償可（信義則上制限）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">工作物の所有者責任</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無過失責任（占有者が免責された場合）</text></svg>", "choices": [{"label": "被害者に過失があれば加害者の責任は全額免除", "reason": "過失相殺は全額免除ではなく割合的な減額です（民法722条2項）。被害者の過失がいくら大きくても全額免除にはなりません（特段の事情がない限り）。", "caution": "過失相殺＝減額（全額免除ではない）。"}, {"label": "被害者の過失は必ず50%以上を減額する", "reason": "減額割合は被害者の過失の程度による柔軟な判断です（民法722条2項）。「必ず50%以上」という固定的な基準はありません。", "caution": ""}, {"label": "過失相殺は当事者の申立てがあった場合にのみ適用される", "reason": "過失相殺は裁判所が職権で考慮できます（民法722条2項・判例）。当事者の申立ては不要です。", "caution": ""}], "summary": {"head": ["過失相殺（民法722条2項）", "内容"], "rows": [["意味", "被害者の過失を考慮して賠償額を減額"], ["適用", "裁判所が職権で考慮可（申立て不要）"], ["割合", "被害者の過失の程度に応じた柔軟な判断"], ["免除", "全額免除にはならない（原則）"]]}}},
  {id:10276,unit:'r_tanpo',level:2,field:'rights',text:'根抵当権の説明として正しいものはどれか。',opts:['普通抵当権と同様に特定の債権のみを担保する','一定の範囲に属する不特定の債権を極度額を限度として担保する','根抵当権は登記できない','根抵当権は被担保債権と一体となって移転する（付従性あり）'],ans:1,exp:`根抵当権（民法398条の2）は一定の範囲に属する不特定の債権を極度額の限度で担保します。普通抵当権と異なり付従性・随伴性が緩和されており（元本確定前）、極度額の範囲で継続的に担保として機能します。`,"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権（民法369条）。質権は占有の移転が必要。先取特権は法定担保物権（当然に成立）。農地への抵当権設定自体は、通常、農地法3条の許可対象ではありません。", "example": ""}, "reason": {"text": "根抵当権は一定の範囲に属する不特定の債権を極度額を限度として担保する担保物権です（民法398条の2第1項）。普通抵当権と異なり特定の債権を担保するのではなく、継続的取引から生じる複数の債権を一括して担保できます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "普通抵当権と同様に特定の債権のみを担保する", "reason": "根抵当権は不特定の債権（一定範囲に属するもの）を担保します（民法398条の2第1項）。普通抵当権とは異なります。", "caution": "根抵当権＝不特定の債権を担保。普通抵当権＝特定の債権を担保。"}, {"label": "根抵当権は登記できない", "reason": "根抵当権も登記できます（不動産登記法83条）。極度額・債権の範囲・債務者等を登記します。", "caution": ""}, {"label": "根抵当権は被担保債権と一体となって移転する（付従性あり）", "reason": "根抵当権は元本確定前は随伴性がありません（民法398条の7）。被担保債権が移転しても根抵当権は移転しません。", "caution": "根抵当権（元本確定前）は随伴性・付従性なし。普通抵当権は随伴性あり。"}], "summary": {"head": ["根抵当権の特徴", "内容"], "rows": [["担保する債権", "不特定（一定の範囲に属する）"], ["上限", "極度額（民法398条の2）"], ["付従性・随伴性", "元本確定前はなし"], ["元本確定後", "普通抵当権に準じた性質"]]}}},
  {id:10277,unit:'l_menkyo',level:2,field:'law',text:'宅建業の免許の承継に関して正しいものはどれか。',opts:['代表者が交代した場合は自動的に免許も承継される','個人業者が死亡した場合、免許は相続されないが、相続人は死亡を知った日から30日以内に届け出る必要があり、被相続人が締結した取引を結了する目的の範囲で宅建業者とみなされる','法人が吸収合併された場合、存続法人はそのまま被合併法人の免許で業を継続できる','免許は一切承継されない'],ans:1,exp:`宅建業者（個人）が死亡した場合、免許は一身専属的で相続されません。相続人は死亡の事実を知った日から30日以内に免許権者へ届け出る必要があります（宅建業法11条）。また、相続人は被相続人が宅建業者として締結した契約に基づく取引を結了する目的の範囲内で宅建業者とみなされます（同法76条）。`,"kaisetsu":{"topic": "宅建業免許：知事・大臣免許の区別・有効期間5年・欠格事由は5年", "basis": {"text": "1都道府県→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間。2020年改正で成年被後見人の欠格条項は廃止。", "example": ""}, "reason": {"text": "個人の宅建業者が死亡した場合、宅建業の免許は一身専属的であり相続されません。相続人は死亡を知った日から30日以内に届け出る必要があり、被相続人が締結した取引を結了する目的の範囲内で宅建業者とみなされます。新たに宅建業を営むには相続人自身の免許が必要です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（2020年改正で成年被後見人は廃止）</text></svg>", "choices": [{"label": "代表者が交代した場合は自動的に免許も承継される", "reason": "代表者の変更は変更届の対象ですが、免許は自動的に承継されません（宅建業法9条）。", "caution": "代表者変更＝変更届が必要（免許は自動承継されない）。"}, {"label": "法人が吸収合併された場合存続法人はそのまま被合併法人の免許で業を継続できる", "reason": "合併による消滅法人の免許は消滅し、存続法人が被合併法人の免許をそのまま使うことはできません（宅建業法11条1項3号）。", "caution": ""}, {"label": "免許は一切承継されない", "reason": "個人業者が死亡した場合、相続人が届け出ることで一定期間業を継続できます（宅建業法11条1項1号）。「一切承継されない」は正確ではありません。", "caution": ""}], "summary": {"head": ["廃業等の届出（宅建業法11条）", "届出者", "期限"], "rows": [["宅建業者の死亡", "相続人", "死亡を知った日から30日以内"], ["廃業", "宅建業者（個人）", "廃業から30日以内"], ["法人の合併消滅", "代表役員", "合併から30日以内"], ["法人の解散", "清算人", "解散から30日以内"]]}}},
  {id:10278,unit:'l_takkenshi',level:2,field:'law',text:'宅建士の登録事項に変更があった場合の手続きとして正しいものはどれか。',opts:['変更なく宅建士証の更新時に届け出ればよい','遅滞なく登録している都道府県知事に変更の登録申請をしなければならない','変更から3ヶ月以内に届け出ればよい','住所が変わった場合は宅建士証を返納しなければならない'],ans:1,exp:`宅建士の登録事項（氏名・住所等）に変更があった場合は、遅滞なく登録をしている都道府県知事に変更の登録を申請しなければなりません（宅建業法20条）。`,"kaisetsu":{"topic": "専任宅建士：5人に1人以上・兼任不可・2週間以内に補充", "basis": {"text": "事務所には業務従事者5人に1人以上の専任宅建士が必要（宅建業法31条の3）。1社専属で複数業者の兼任は不可。不足時は2週間以内に補充が必要。案内所（申込み受付）にも専任宅建士が必要。", "example": ""}, "reason": {"text": "宅建士の登録事項（氏名・住所・勤務先等）に変更があった場合は遅滞なく登録を受けた都道府県知事に変更登録の申請をしなければなりません（宅建業法20条）。速やかな変更登録は義務です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">専任宅建士のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">設置基準</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5人に1人以上</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">兼任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可（1社専属）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不足補充</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間以内</text></svg>", "choices": [{"label": "変更なく宅建士証の更新時に届け出ればよい", "reason": "変更は遅滞なく届け出る義務があります（宅建業法20条）。更新時まで待てません。", "caution": "変更登録：遅滞なく申請義務（宅建業法20条）。"}, {"label": "変更から3ヶ月以内に届け出ればよい", "reason": "「遅滞なく」が要件であり（宅建業法20条）、3か月以内という規定はありません。速やかに申請が必要です。", "caution": ""}, {"label": "住所が変わった場合は宅建士証を返納しなければならない", "reason": "住所変更の場合は変更登録を申請し、宅建士証の書換え交付申請を行います（宅建業法22条の2第3項）。返納ではありません。", "caution": ""}], "summary": {"head": ["変更登録の手続き（宅建業法20条）", "内容"], "rows": [["申請義務", "遅滞なく"], ["申請先", "登録を受けた都道府県知事"], ["宅建士証", "変更後は書換え交付申請も必要（宅建業法22条の2第3項）"], ["主な変更事項", "氏名・住所・本籍・勤務先等"]]}}},
  {id:10279,unit:'l_baikai',level:2,field:'law',text:'専任媒介契約における宅建業者の義務として正しいものはどれか。',opts:['指定流通機構（レインズ）への登録は任意','依頼者への業務処理状況の報告は2週間に1回以上','自己発見取引（依頼者自身が相手方を見つける取引）は禁止','専任媒介契約の有効期間は最長3ヶ月'],ans:3,exp:`専任媒介契約の有効期間は最長3ヶ月（更新可）で、依頼者への報告義務は2週間に1回以上、レインズへの登録は7日以内（休業日除く）です（宅建業法34条の2）。自己発見取引は専任媒介では可能ですが専属専任媒介では禁止です。`,"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任の有効期間は最長3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。レインズ登録は専任7日以内・専属専任5日以内。業務報告は専任2週間に1回・専属専任1週間に1回。", "example": ""}, "reason": {"text": "専任媒介契約の有効期間は3か月が上限です（宅建業法34条の2第3項）。専任媒介ではレインズへの登録義務（7日以内）・業務報告義務（2週間に1回以上）があります。自己発見取引（依頼者が自ら見つけた取引）は専任媒介では可能です（禁止は専属専任のみ）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">自己発見</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">レインズ</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専任</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専属専任</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text></svg>", "choices": [{"label": "指定流通機構（レインズ）への登録は任意", "reason": "専任媒介ではレインズへの登録義務があります（宅建業法34条の2第5項：7日以内）。「任意」は誤りです。", "caution": ""}, {"label": "依頼者への業務処理状況の報告は2週間に1回以上", "reason": "専任媒介の業務報告は2週間に1回以上が正しいです（宅建業法34条の2第9項）。設問の正解は選択肢4（有効期間3か月）です。", "caution": ""}, {"label": "自己発見取引（依頼者自身が相手方を見つける取引）は禁止", "reason": "自己発見取引が禁止されるのは専属専任媒介のみです（宅建業法34条の2第3項）。専任媒介では許可されています。", "caution": "自己発見取引禁止：専属専任媒介のみ。専任媒介は自己発見取引可。"}], "summary": {"head": ["専任媒介の義務", "内容"], "rows": [["有効期間", "最長3か月（宅建業法34条の2第3項）"], ["レインズ登録", "7日以内（宅建業法34条の2第5項）"], ["業務報告", "2週間に1回以上（宅建業法34条の2第9項）"], ["自己発見取引", "可（専属専任は不可）"]]}}},
  {id:10280,unit:'l_hoshu',level:2,field:'law',text:'宅建業者が建物の貸借の媒介をした場合の報酬の合計額の上限として正しいものはどれか。',opts:['借主から借賃1ヶ月分以内（税別）','借主・貸主双方から合わせて借賃1ヶ月分以内（税別）','借主・貸主双方から合わせて借賃2ヶ月分以内（税別）','貸主から借賃3ヶ月分以内（税別）'],ans:1,exp:`建物の貸借媒介の報酬合計の上限は依頼者双方から合わせて借賃1ヶ月分（税別）です（報酬告示）。居住用建物の場合、依頼者の承諾がなければ一方から0.5ヶ月分が上限です。`,"kaisetsu":{"topic": "報酬：売買は代金×3%+6万（400万超）・賃貸は借賃1か月・上限超過は不可", "basis": {"text": "売買（400万超）の一方からの上限は代金×3%+6万。双方合計は一方上限×2。賃貸（居住用・非居住用とも）は借賃1か月分。低廉な空家等（800万円以下）は、媒介報酬について原則の報酬額を超えて30万円（税別）まで受領できる場合があります（依頼者への説明・合意が必要）。", "example": ""}, "reason": {"text": "建物の賃貸借媒介の報酬は貸主・借主双方から合計して借賃の1か月分（税別）が上限です（告示）。一方のみからの受領だけでなく、双方の合計額の上限が定められています。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対象</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（400万超）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万（一方）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（200万以下）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸（双方合計）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借賃1か月分</text></svg>", "choices": [{"label": "借主から借賃1ヶ月分以内（税別）", "reason": "借主から1か月分を受け取れますが（依頼者の承諾がある場合）、合計上限は双方で1か月分です（告示）。借主のみからが上限の説明としては不正確です。", "caution": "双方合計で1か月分が上限（告示）。"}, {"label": "借主・貸主双方から合わせて借賃2ヶ月分以内（税別）", "reason": "双方合計の上限は1か月分です（告示）。2か月分は誤りです。", "caution": ""}, {"label": "貸主から借賃3ヶ月分以内（税別）", "reason": "貸主から3か月分は誤りです（告示）。双方合計で1か月分が上限です。", "caution": ""}], "summary": {"head": ["建物賃貸借媒介の報酬上限（告示）", "内容"], "rows": [["双方合計", "借賃1か月分（税別）"], ["一方のみから（原則）", "0.5か月分まで"], ["一方から（承諾あり）", "1か月分まで（双方合計1か月分の範囲内）"]]}}},
  {id:10281,unit:'l_37jo',level:2,field:'law',text:'37条書面の任意的記載事項（定めがある場合に記載）として正しいものはどれか。',opts:['当事者の氏名・住所','物件の所在・地番','代金の額','天災その他不可抗力による損害の負担に関する定め'],ans:3,exp:`天災等不可抗力による損害負担の定めは、定めがある場合にのみ37条書面に記載する任意的記載事項です（宅建業法37条1項11号）。当事者の氏名・住所・物件所在・代金額は必要的記載事項です。`,"kaisetsu":{"topic": "37条書面：全取引で交付・記名（押印不要）・移転登記申請時期は必要的記載事項", "basis": {"text": "37条書面は全取引で契約の双方当事者に交付が義務（宅建業法37条）。引渡し時期・移転登記申請時期は必要的記載事項。2021年改正で押印は不要、記名のみで足ります。", "example": ""}, "reason": {"text": "天災その他不可抗力による損害の負担に関する定めは、定めがある場合にのみ記載する任意的記載事項です（宅建業法37条1項10号）。当事者の氏名・物件の所在・代金の額は必要的記載事項です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付義務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全取引・双方当事者</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡時期・移転登記申請時期等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要）</text></svg>", "choices": [{"label": "当事者の氏名・住所", "reason": "当事者の氏名・住所は必要的記載事項です（宅建業法37条1項1号）。任意的ではありません。", "caution": ""}, {"label": "物件の所在・地番", "reason": "物件の特定に必要な事項（所在・地番等）は必要的記載事項です（宅建業法37条1項1号）。", "caution": ""}, {"label": "代金の額", "reason": "代金の額は必要的記載事項です（宅建業法37条1項2号）。任意的ではありません。", "caution": ""}], "summary": {"head": ["37条書面の任意的記載事項（定めがある場合のみ）", "根拠"], "rows": [["契約解除の定め", "宅建業法37条1項7号"], ["損害賠償額の予定・違約金", "宅建業法37条1項（準じた解釈）"], ["融資あっせんの定め", "宅建業法37条1項8号"], ["天災等による損害負担", "宅建業法37条1項10号"], ["瑕疵担保（契約不適合）の定め", "宅建業法37条1項11号"]]}}},
  {id:10282,unit:'l_jusetsu',level:2,field:'law',text:'重要事項説明書（35条書面）の記載事項として正しいものはどれか。',opts:['登記された権利の種類・内容','物件の引渡し時期','移転登記の申請時期','代金の支払方法'],ans:0,exp:`登記された権利の種類・内容等は35条書面（重要事項説明書）の記載事項です（宅建業法35条1項1号）。引渡し時期・移転登記申請時期・支払方法は37条書面（契約書面）の記載事項です。`,"kaisetsu":{"topic": "重要事項説明：宅建士が説明・買主への交付・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主（貸主）は不要。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能。", "example": ""}, "reason": {"text": "重要事項説明書（35条書面）の必須記載事項は宅建業法35条1項に列挙されています。登記された権利の種類・内容（抵当権等の記載）は必須記載事項です（同条1項1号）。引渡し時期・移転登記申請時期・代金の支払方法は37条書面（契約書面）の記載事項です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士のみ（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "物件の引渡し時期", "reason": "引渡し時期は37条書面（契約書面）の記載事項です（宅建業法37条1項4号）。35条書面ではありません。", "caution": "35条書面（重要事項）と37条書面（契約書面）の記載事項の区別が重要です。"}, {"label": "移転登記の申請時期", "reason": "移転登記の申請時期は37条書面の記載事項です（宅建業法37条1項5号）。35条書面ではありません。", "caution": ""}, {"label": "代金の支払方法", "reason": "代金の支払方法は37条書面の記載事項です（宅建業法37条1項2号等）。35条書面ではありません。", "caution": ""}], "summary": {"head": ["35条書面vs37条書面の主な記載事項", "35条書面", "37条書面"], "rows": [["登記された権利の種類・内容", "○", "×"], ["代金・支払方法", "×", "○"], ["引渡し時期", "×", "○"], ["移転登記申請時期", "×", "○"], ["法令上の制限の概要", "○", "×"]]}}},
  {id:10283,unit:'l_hosho',level:2,field:'law',text:'住宅品質確保促進法（品確法）における瑕疵担保責任の期間として正しいものはどれか。',opts:['新築住宅の基本構造部分は引渡しから5年','新築住宅の基本構造部分は引渡しから10年','新築住宅の全部について5年','すべて任意に定められる'],ans:1,exp:`住宅品質確保促進法により、新築住宅の基本構造部分（構造耐力上主要な部分・雨水の侵入を防止する部分）については引渡しから10年間の瑕疵担保責任が義務付けられています（品確法94条・95条）。`,"kaisetsu":{"topic": "営業保証金・保証協会：主1,000万・従500万/営業保証金vs分担金60万・30万", "basis": {"text": "営業保証金は主1,000万・従500万（宅建業法25条）。保証協会の分担金は主60万・従30万（同法64条の9）。還付対象は業者以外の取引した者。加入は任意。不足補充は通知後2週間以内。", "example": ""}, "reason": {"text": "住宅品質確保促進法（品確法）では、新築住宅の基本構造部分（構造耐力上主要な部分・雨水の浸入を防止する部分）について引渡しから10年間の瑕疵担保責任（修補・損害賠償等）を義務付けています（品確法95条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">営業保証金と弁済業務保証金</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">営業保証金</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">弁済業務保証金（分担金）</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">主たる事務所</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000万円</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">60万円</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従たる事務所/所</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">500万円</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">還付対象</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者以外</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者以外</text></svg>", "choices": [{"label": "新築住宅の基本構造部分は引渡しから5年", "reason": "基本構造部分の瑕疵担保責任期間は10年です（品確法95条1項）。5年ではありません。", "caution": "新築住宅の基本構造部分の瑕疵担保責任：10年（品確法95条1項）。"}, {"label": "新築住宅の全部について5年", "reason": "全部について5年という規定はありません。基本構造部分について10年が最低基準です（品確法95条1項）。", "caution": ""}, {"label": "すべて任意に定められる", "reason": "基本構造部分の10年間は強行規定（最低基準）であり、これを下回る特約は無効です（品確法95条2項）。", "caution": ""}], "summary": {"head": ["品確法の瑕疵担保責任（品確法95条）", "内容"], "rows": [["対象", "新築住宅の基本構造部分"], ["期間", "引渡しから10年（強行規定）"], ["特約", "10年未満への短縮は無効"], ["延長特約", "20年まで延長可"]]}}},
  {id:10284,unit:'l_cooling',level:2,field:'law',text:'クーリングオフができなくなる条件として正しいものはどれか。',opts:['申込みから8日が経過したとき','申込みの場所が宅建業者の事務所以外であれば常にできる','書面で告知された日から8日経過または物件の引渡しと代金の全額支払いの両方が完了したとき','手付金を支払ったとき'],ans:2,exp:`クーリングオフができなくなるのは、①書面による告知の日から8日間を経過したとき、②買主が物件の引渡しを受け、かつ代金の全額を支払ったときです（宅建業法37条の2）。2つの条件はどちらか早い方で適用されます。`,"kaisetsu":{"topic": "クーリングオフ：告知日から8日以内・書面で・事務所では不可・全額返還", "basis": {"text": "クーリングオフは告知を受けた日から8日以内に書面で行います（宅建業法37条の2）。事務所・モデルルーム等での申込みはクーリングオフ不可。解除後業者は全額返還（費用控除不可）。", "example": ""}, "reason": {"text": "クーリングオフができなくなる条件は①書面で告知された日から8日が経過した、または②物件の引渡しと代金の全額支払いの両方が完了した場合です（宅建業法37条の2第1項）。どちらか一方が先に生じれば行使できなくなります。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">クーリングオフのポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">告知日から8日以内</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">方法</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面（発信主義）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所での申込み</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">クーリングオフ不可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除後</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全額返還</text></svg>", "choices": [{"label": "申込みから8日が経過したとき", "reason": "起算点は申込みからではなく告知を受けた日からです（宅建業法37条の2第1項）。", "caution": ""}, {"label": "申込みの場所が宅建業者の事務所以外であれば常にできる", "reason": "告知から8日経過または引渡し＋全額支払い完了でクーリングオフできなくなります（宅建業法37条の2第1項）。「常にできる」は誤りです。", "caution": ""}, {"label": "手付金を支払ったとき", "reason": "手付金の支払いはクーリングオフの行使不可条件ではありません（宅建業法37条の2第1項）。引渡しと全額支払いの両方の完了が要件です。", "caution": ""}], "summary": {"head": ["クーリングオフが行使できなくなる条件（宅建業法37条の2第1項）", "内容"], "rows": [["①告知から8日経過", "告知書面を受け取った日から8日後"], ["②引渡しと全額支払いの完了", "どちらが先でも両方完了で行使不可"], ["どちらか早い方", "先に生じた方で行使不可に"]]}}},
  {id:10285,unit:'l_kokoku',level:2,field:'law',text:'宅建業法上、未完成物件について広告・契約を開始できる時期として正しいものはどれか。',opts:['建築確認申請後すぐに広告できる','開発許可・建築確認等が下りた後でなければ広告・契約ともにできない','広告は申請後すぐにできるが契約は許可・確認後のみ','宅建業法上は制限なし'],ans:1,exp:`開発許可・建築確認その他法令に基づく許可等が下りるまで、宅建業者は広告・契約の締結ができません（宅建業法33条・36条）。申請中であっても広告・契約は禁止されます。`,"kaisetsu":{"topic": "宅建業者の広告：開発許可後に広告可・誇大広告は全媒体禁止・取引態様は広告時と注文時両方", "basis": {"text": "開発許可・建築確認後（工事中でも）広告できます（宅建業法33条）。誇大広告禁止は全媒体・全対象者に適用（同法32条）。取引態様は広告時と注文受領時の両方で明示が必要（同法34条）。", "example": ""}, "reason": {"text": "宅建業者は開発許可・建築確認等を受けた後でなければ未完成物件の広告・契約をすることができません（宅建業法33条・36条）。広告と契約の両方に制限があります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">広告規制のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">広告開始時期</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築確認・開発許可後</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誇大広告禁止</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">媒体・対象問わず</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取引態様の明示</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">広告時と注文時の両方</text></svg>", "choices": [{"label": "建築確認申請後すぐに広告できる", "reason": "申請後ではなく、許可・確認が下りた後でなければ広告できません（宅建業法33条）。", "caution": "未完成物件の広告：開発許可・建築確認等を受けた後（宅建業法33条）。"}, {"label": "広告は申請後すぐにできるが契約は許可・確認後のみ", "reason": "広告も契約も許可・確認後でなければできません（宅建業法33条・36条）。「広告だけ先に」は誤りです。", "caution": ""}, {"label": "宅建業法上は制限なし", "reason": "宅建業法33条（広告開始時期の制限）・36条（契約締結時期の制限）により制限があります。「制限なし」は誤りです。", "caution": ""}], "summary": {"head": ["未完成物件の広告・契約制限", "根拠"], "rows": [["広告開始時期の制限", "開発許可・建築確認等を受けた後（宅建業法33条）"], ["契約締結時期の制限", "同様に開発許可・建築確認等を受けた後（宅建業法36条）"], ["違反", "業務停止処分等の行政処分"]]}}},
  {id:10286,unit:'l_kantoku',level:2,field:'law',text:'都道府県知事が宅建業者に対して指示処分を行える場合として正しいものはどれか。',opts:['宅建業法の規定に違反した場合のみ','取引の関係者に損害を与えた場合または損害を与えるおそれが大の場合','刑事事件で起訴された場合','廃業の届出を怠った場合'],ans:1,exp:`知事は宅建業者が業務に関し取引の関係者に損害を与えたとき、または損害を与えるおそれが大であるときに指示処分ができます（宅建業法65条1項）。また宅建業法等の規定に違反した場合も指示処分の対象となります。`,"kaisetsu":{"topic": "監督処分：業務停止最長1年・大臣は全業者に指示可・指示違反→業務停止", "basis": {"text": "業務停止の最長期間は1年（宅建業法65条2項）。大臣は全業者（知事免許含む）に指示処分を行う権限があります。指示処分違反→業務停止、業務停止違反→免許取消という段階があります。", "example": ""}, "reason": {"text": "都道府県知事は、宅建業者が取引の関係者に損害を与えた場合または与えるおそれが大きい場合に指示処分を行えます（宅建業法65条1項）。宅建業法違反に限らず広く指示処分が可能です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">監督処分のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">処分</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">最長1年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣の権限</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全業者に指示可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">指示処分違反</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止の対象</text></svg>", "choices": [{"label": "宅建業法の規定に違反した場合のみ", "reason": "宅建業法違反に限らず、取引の関係者への損害またはそのおそれが大きい場合も含まれます（宅建業法65条1項）。「のみ」は誤りです。", "caution": "指示処分：宅建業法違反＋取引相手への損害・おそれ（宅建業法65条1項）。"}, {"label": "刑事事件で起訴された場合", "reason": "起訴は刑事手続きの問題であり、指示処分の直接の要件ではありません（宅建業法65条1項）。", "caution": ""}, {"label": "廃業の届出を怠った場合", "reason": "廃業届の懈怠は行政処分の対象となりますが、設問の正解は「取引の関係者への損害・おそれ」（宅建業法65条1項）です。", "caution": ""}], "summary": {"head": ["指示処分の要件（宅建業法65条1項）", "内容"], "rows": [["宅建業法違反", "法令違反"], ["取引の関係者への損害", "損害を与えたまたは与えるおそれが大"], ["権限者", "免許を与えた国交大臣または知事"]]}}},
  {id:10287,unit:'l_sonota',level:2,field:'law',text:'保証協会の弁済業務保証金分担金の額として正しいものはどれか。',opts:['主たる事務所60万円・従たる事務所ごと30万円','主たる事務所1000万円・従たる事務所ごと500万円','主たる事務所10万円・従たる事務所ごと5万円','一律60万円'],ans:0,exp:`弁済業務保証金分担金は主たる事務所につき60万円・従たる事務所1カ所につき30万円です（宅建業法64条の9）。これは通常の営業保証金（主1000万・従500万）の60分の1に当たります。`,"kaisetsu":{"topic": "宅建業者のその他の業務：従業者証明書・帳簿・業務処理原則", "basis": {"text": "全従業者に従業者証明書の交付が必要で業務中は常時携帯（宅建業法48条）。帳簿は事務所ごとに5年保存（自ら売主の新築住宅は10年）（同法49条）。宅建業者は信義誠実の原則に従って業務を行う必要があります（同法31条）。", "example": ""}, "reason": {"text": "保証協会への弁済業務保証金分担金は主たる事務所につき60万円、従たる事務所1か所あたり30万円です（宅建業法64条の9第1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業者のその他の義務</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従業者証明書</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全従業者に交付・業務中携帯</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">帳簿</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所ごと・5年保存（新築自ら売主は10年）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務処理原則</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">信義誠実の原則</text></svg>", "choices": [{"label": "主たる事務所1000万円・従たる事務所ごと500万円", "reason": "1000万円・500万円は営業保証金の金額です（宅建業法施行令2条1項）。分担金は60万円・30万円です（宅建業法64条の9第1項）。", "caution": ""}, {"label": "主たる事務所10万円・従たる事務所ごと5万円", "reason": "主たる事務所の分担金は60万円です（宅建業法64条の9第1項）。10万円ではありません。", "caution": ""}, {"label": "一律60万円", "reason": "従たる事務所の分担金は30万円（1か所あたり）です（宅建業法64条の9第1項）。一律ではありません。", "caution": ""}], "summary": {"head": ["弁済業務保証金分担金（宅建業法64条の9第1項）", "金額"], "rows": [["主たる事務所", "60万円"], ["従たる事務所（1か所）", "30万円"], ["営業保証金との比較", "主たる事務所：1000万円→60万円（約1/17）"]]}}},
  {id:10288,unit:'l_baikai',level:2,field:'law',text:'一般媒介契約と専任媒介契約の違いとして正しいものはどれか。',opts:['一般媒介は依頼者が複数業者に依頼できるが、専任媒介は1社のみに依頼する','一般媒介では宅建士による媒介契約書の記名押印が不要','一般媒介の有効期間は最長6ヶ月','一般媒介は依頼者の自己発見取引が禁止される'],ans:0,exp:`一般媒介は複数の業者への依頼が可能で依頼者の自己発見取引も自由です。専任媒介は1社のみ依頼可（自己発見取引は可）。専属専任媒介は1社のみ（自己発見取引も不可）。いずれも有効期間は最長3ヶ月（更新可）です。`,"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任の有効期間は最長3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。レインズ登録は専任7日以内・専属専任5日以内。業務報告は専任2週間に1回・専属専任1週間に1回。", "example": ""}, "reason": {"text": "一般媒介契約は複数の宅建業者に依頼できます（宅建業法34条の2第1項3号）。専任媒介は1社のみです（同条1項4号）。報酬上限・宅建士の記名押印義務・依頼者の制約は媒介の種類によって異なります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">自己発見</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">レインズ</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専任</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専属専任</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text></svg>", "choices": [{"label": "一般媒介では宅建士による媒介契約書の記名押印が不要", "reason": "34条の2書面の記名は宅建業者（代表者等）が行います（宅建業法34条の2第1項）。宅建士の記名は37条書面・35条書面ですが、34条の2書面は宅建業者が記名します。", "caution": "34条の2書面：宅建業者が記名。35条書面・37条書面：宅建士が記名。"}, {"label": "一般媒介の有効期間は最長6ヶ月", "reason": "一般媒介契約の有効期間に法定上限はありません（宅建業法34条の2第3項は専任・専属専任のみを規制）。「6か月」という基準もありません。", "caution": ""}, {"label": "一般媒介は依頼者の自己発見取引が禁止される", "reason": "自己発見取引の禁止は専属専任媒介のみです（宅建業法34条の2第3項）。一般媒介・専任媒介では自己発見取引は可能です。", "caution": ""}], "summary": {"head": ["一般媒介と専任媒介の主な違い", "一般媒介", "専任媒介"], "rows": [["複数業者への依頼", "可", "不可"], ["自己発見取引", "可", "可"], ["有効期間上限", "なし", "3か月"], ["レインズ登録", "義務なし", "7日以内"], ["業務報告", "義務なし", "2週間に1回"]]}}},
  {id:10289,unit:'k_toshi',level:2,field:'limit',text:'開発許可が不要な行為として正しいものはどれか。',opts:['市街化区域内での1000㎡以上の開発行為','農業・林業・漁業用の建築物のための開発行為','市街化調整区域内でのゴルフ場開発','非線引き区域内での10000㎡以上の開発行為'],ans:1,exp:`農業・林業・漁業の用に供する建築物（農家住宅等を含む）のための開発行為は開発許可が不要です（都市計画法29条1項2号・3号）。ただし市街化調整区域内での農林漁業者の住宅は例外的に許可不要となります。`,"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域の1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "農業・林業・漁業用の建築物のための開発行為は規模にかかわらず開発許可が不要です（都市計画法29条1項2号）。農業用倉庫・農家住宅等が対象です。市街化調整区域での一般的なゴルフ場開発や大規模開発は許可が必要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "市街化区域内での1000㎡以上の開発行為", "reason": "市街化区域内での1000㎡以上の開発行為は原則として許可が必要です（都市計画法29条1項）。「不要」は誤りです。", "caution": ""}, {"label": "市街化調整区域内でのゴルフ場開発", "reason": "ゴルフ場開発は農林漁業用施設ではなく許可が必要です（都市計画法29条）。", "caution": "農林漁業用施設のための開発：規模にかかわらず許可不要（都市計画法29条1項2号）。"}, {"label": "非線引き区域内での10000㎡以上の開発行為", "reason": "非線引き区域での10000㎡以上の開発行為は許可が必要です（都市計画法29条1項・施行令19条）。「不要」は誤りです。", "caution": ""}], "summary": {"head": ["開発許可が不要な行為（都市計画法29条1項）", "内容"], "rows": [["農林漁業用建築物", "農業用倉庫・農家住宅等（同条1項2号）"], ["小規模開発", "市街化区域1000㎡未満等"], ["公益上必要な建築物", "鉄道施設・変電所等（同条1項3号）"], ["非常災害復旧", "（同条1項7号）"]]}}},
  {id:10290,unit:'k_kenchiku',level:2,field:'limit',text:'道路斜線制限の説明として正しいものはどれか。',opts:['建築物の高さは敷地境界線からの距離に関係なく一定','前面道路の幅員と用途地域に応じた制限がかかり、道路境界線から建物に向かって斜線が設定される','前面道路幅員が12m以上であれば道路斜線は適用されない','道路斜線は北側斜線制限と同じ内容'],ans:1,exp:`道路斜線制限（建築基準法56条）は前面道路の幅員と用途地域に応じた勾配の斜線が設定され、建築物の高さがこれを超えてはなりません。前面道路が広いほど制限が緩やかになります。`,"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・用途制限・道路斜線", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。防火地域の耐火建築物は隣地境界線に外壁を接して建築可（同法65条）。", "example": ""}, "reason": {"text": "道路斜線制限は前面道路の幅員と用途地域に応じて建物の高さを制限するもので、道路の採光・通風を確保するためのものです（建築基準法56条1項1号）。前面道路の境界線から斜線が設定されます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">防火地域の耐火建築物</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">隣地境界線に接して建築可</text></svg>", "choices": [{"label": "建築物の高さは敷地境界線からの距離に関係なく一定", "reason": "道路斜線制限は前面道路からの距離（セットバック距離）に応じて制限が変わります（建築基準法56条1項1号）。「一定」は誤りです。", "caution": "道路斜線制限：前面道路幅員と用途地域に応じた係数×道路境界からの距離（建築基準法56条1項1号）。"}, {"label": "前面道路幅員が12m以上であれば道路斜線は適用されない", "reason": "前面道路幅員に関わらず道路斜線制限は適用されます（建築基準法56条1項1号）。12mという特例はありません。", "caution": ""}, {"label": "道路斜線は北側斜線制限と同じ内容", "reason": "道路斜線は前面道路との関係（建築基準法56条1項1号）、北側斜線は北側の日照保護（同条1項3号）であり、異なる制限です。", "caution": ""}], "summary": {"head": ["道路斜線制限（建築基準法56条1項1号）", "内容"], "rows": [["目的", "前面道路の採光・通風確保"], ["係数", "住居系：1.25倍、その他：1.5倍"], ["計算", "道路境界からの距離×係数が高さの上限"], ["天空率", "天空率により斜線制限を緩和可"]]}}},
  {id:10291,unit:'k_nochi',level:2,field:'limit',text:'農地法5条の許可が必要な行為として正しいものはどれか。',opts:['農地を農地のまま売買する','農地を農地のままで贈与する','農地を宅地に転用するために権利移動する','農地を農地以外のものに転用する（権利移動なし）'],ans:2,exp:`農地法5条は農地の転用を伴う権利移動（転用目的で売買・賃借等）に許可が必要です。農地のままの権利移動は3条、権利移動なしの転用は4条の許可が必要です。`,"kaisetsu":{"topic": "農地法：3条は農業委員会・4・5条は都道府県知事・市街化区域は届出のみ", "basis": {"text": "農地法3条の許可権者は農業委員会。4・5条は都道府県知事等。市街化区域の農地転用（4・5条）は農業委員会への届出のみOK。相続は許可不要・3か月以内の農業委員会への届出が必要。", "example": ""}, "reason": {"text": "農地法5条は転用目的の権利移動（農地を宅地に転用するために売買・賃貸借する等）に許可が必要です（農地法5条1項）。農地のまま売買は3条、自己転用は4条の問題です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text></svg>", "choices": [{"label": "農地を農地のまま売買する", "reason": "農地のまま売買は農地法3条の問題です（農地法3条1項）。農地法5条は転用目的の権利移動です。", "caution": "農地法5条＝転用目的の権利移動（農地法5条1項）。"}, {"label": "農地を農地のままで贈与する", "reason": "農地のまま贈与は農地法3条の問題です（農地法3条1項）。", "caution": ""}, {"label": "農地を農地以外のものに転用する（権利移動なし）", "reason": "自己転用（権利移動なし）は農地法4条の問題です（農地法4条1項）。", "caution": ""}], "summary": {"head": ["農地法5条の適用（転用目的の権利移動）", "内容"], "rows": [["要件", "転用の目的で農地の権利を移動（売買・賃貸等）"], ["許可権者", "都道府県知事（4ha超は農林水産大臣）"], ["市街化区域内", "農業委員会への届出で足りる（農地法5条1項7号）"]]}}},
  {id:10292,unit:'k_kokudo',level:2,field:'limit',text:'国土利用計画法における注視区域内での事前届出の説明として正しいものはどれか。',opts:['届出は事後でよい','届出後6週間以内に知事が不勧告の通知をすれば契約締結できる','届出は不要で自由に取引できる','届出期間は3週間以内'],ans:1,exp:`注視区域内での届出（事前届出）をした場合、知事が届出受理から6週間以内に勧告または不勧告の通知をします。不勧告通知があれば契約を締結できます（国土利用計画法27条の6）。`,"kaisetsu":{"topic": "国土利用計画法：事後届出は2週間以内・市街化区域は2,000㎡以上・規制区域は許可制", "basis": {"text": "事後届出は契約締結後2週間以内（国土利用計画法23条）。市街化区域は2,000㎡以上・市街化調整区域は5,000㎡以上・都市計画区域外は10,000㎡以上。届出義務者は買主のみ。規制区域は許可制。", "example": ""}, "reason": {"text": "注視区域内での事前届出後、知事が6週間以内に不勧告の通知をすれば契約を締結できます（国土利用計画法27条の7）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">国土利用計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">区域</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">基準面積</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2,000㎡以上</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化調整区域</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都市計画区域外</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10,000㎡以上</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">規制区域</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">許可制（届出ではない）</text></svg>", "choices": [{"label": "届出は事後でよい", "reason": "注視区域内では事前届出が必要です（国土利用計画法27条の7）。", "caution": "注視区域の事前届出：届出後6週間は契約不可（国土利用計画法27条の7）。"}, {"label": "届出は不要で自由に取引できる", "reason": "注視区域内では事前届出が必要です（国土利用計画法27条の7）。", "caution": ""}, {"label": "届出期間は3週間以内", "reason": "6週間（契約不可期間）と3週間（事後届出の届出期限）を混同しています（国土利用計画法27条の7）。", "caution": ""}], "summary": {"head": ["注視区域の事前届出（国土利用計画法27条の7）", "内容"], "rows": [["審査期間", "届出後6週間（契約不可）"], ["不勧告通知", "6週間以内に通知があれば契約可"]]}}},
  {id:10293,unit:'k_kukaku',level:2,field:'limit',text:'仮換地の指定について正しいものはどれか。',opts:['仮換地が指定されると従前の宅地の使用収益権は消滅する','仮換地の指定があると、仮換地について使用収益が可能となり従前の宅地の使用収益はできなくなる','仮換地と従前の宅地の両方を使用収益できる','仮換地が指定されると所有権が移転する'],ans:1,exp:`仮換地が指定されると、効力発生の日から換地処分の公告がある日まで、仮換地について使用収益でき、従前の宅地は使用収益できなくなります（土地区画整理法99条）。所有権は換地処分まで移転しません。`,"kaisetsu":{"topic": "土地区画整理法：換地は公告翌日確定・仮換地は従前地使用不可・組合は2/3以上", "basis": {"text": "換地処分の公告翌日から換地が確定します（土地区画整理法104条）。仮換地の指定後は従前地を使用できなくなります（同法99条）。組合設立には土地所有者・借地権者の各2/3以上の同意が必要です。", "example": ""}, "reason": {"text": "仮換地の指定があると、指定の効力発生日から仮換地について使用収益が可能になりますが、従前の宅地の使用収益は停止されます（土地区画整理法99条1項・2項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">土地区画整理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">換地の確定</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公告の翌日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮換地指定後</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従前地は使用不可（所有権は残る）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">組合設立</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各2/3以上の同意</text></svg>", "choices": [{"label": "仮換地が指定されると従前の宅地の使用収益権は消滅する", "reason": "使用収益権は「停止」であり消滅ではありません（土地区画整理法99条2項）。", "caution": "仮換地指定後：仮換地で使用収益可・従前地の使用収益停止（土地区画整理法99条）。"}, {"label": "仮換地と従前の宅地の両方を使用収益できる", "reason": "両方の使用収益は認められません（土地区画整理法99条1項・2項）。", "caution": ""}, {"label": "仮換地が指定されると所有権が移転する", "reason": "仮換地指定では所有権は移転しません（土地区画整理法99条）。", "caution": ""}], "summary": {"head": ["仮換地の指定の効果（土地区画整理法99条）", "内容"], "rows": [["仮換地", "使用収益が可能になる"], ["従前の宅地", "使用収益が停止される"], ["所有権", "移転しない"]]}}},
  {id:10294,unit:'k_kenchiku',level:2,field:'limit',text:'防火地域内の木造建築物について正しいものはどれか。',opts:['すべて建築可能','階数が2以下かつ延べ面積500㎡以下であれば特別制限なく建築できる','全ての建築物は耐火建築物または準耐火建築物としなければならない','防火地域では木造建築は完全禁止'],ans:2,exp:`防火地域内では、階数が3以上または延べ面積が100㎡超の建築物は耐火建築物としなければならず、それ以外（階数2以下かつ100㎡以下）は準耐火建築物以上が必要です（建築基準法61条）。`,"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・用途制限・道路斜線", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。防火地域の耐火建築物は隣地境界線に外壁を接して建築可（同法65条）。", "example": ""}, "reason": {"text": "防火地域内では階数が3以上または延べ面積100㎡超の建築物は耐火建築物としなければならず、それ以外の建築物も準耐火建築物（または耐火建築物）としなければなりません（建築基準法61条）。木造でも耐火建築物等にすれば建築できます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">防火地域の耐火建築物</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">隣地境界線に接して建築可</text></svg>", "choices": [{"label": "すべて建築可能", "reason": "防火地域内では耐火建築物または準耐火建築物にしなければなりません（建築基準法61条）。「すべて建築可能」は誤りです。", "caution": "防火地域内：全建築物を耐火建築物等にする義務（建築基準法61条）。"}, {"label": "階数が2以下かつ延べ面積500㎡以下であれば特別制限なく建築できる", "reason": "防火地域内では規模にかかわらず耐火建築物または準耐火建築物にしなければなりません（建築基準法61条）。", "caution": ""}, {"label": "防火地域では木造建築は完全禁止", "reason": "木造でも耐火建築物等にすれば防火地域内で建築できます（建築基準法61条）。木造を完全禁止する規定はありません。", "caution": ""}], "summary": {"head": ["防火地域内の建築規制（建築基準法61条）", "内容"], "rows": [["3階以上または延べ面積100㎡超", "耐火建築物"], ["2階以下かつ延べ面積100㎡以下", "準耐火建築物（または耐火建築物）"], ["木造", "耐火建築物等にすれば建築可"], ["準防火地域", "3〜4階または500㎡超は耐火建築物（建築基準法62条）"]]}}},
  {id:10295,unit:'k_toshi',level:2,field:'limit',text:'地区計画の説明として正しいものはどれか。',opts:['市町村が都市計画として定める詳細なまちづくりのルール','国が定める広域的な土地利用規制','地区計画が定められると開発行為が一切禁止される','農業地域にのみ定めることができる'],ans:0,exp:`地区計画（都市計画法12条の5）は、市町村が都市計画として定め、地区の特性に応じた建築物の用途・容積率・建ぺい率・高さ・形態等のきめ細かなルールを定めるものです。市街化区域・市街化調整区域等の都市計画区域内で定められます。`,"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域の1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "地区計画は市町村が都市計画として定める詳細なまちづくりのルールです（都市計画法12条の4・12条の5）。地区内の建物の用途・形態等を細かく定め、良好な街並みの形成を図ります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "国が定める広域的な土地利用規制", "reason": "地区計画は国ではなく市町村が定める地区レベルの計画です（都市計画法12条の4第1項）。", "caution": "地区計画：市町村が定める詳細なまちづくりのルール（都市計画法12条の4）。"}, {"label": "地区計画が定められると開発行為が一切禁止される", "reason": "地区計画は開発を一切禁止するものではなく、地区計画に沿った整序された開発を誘導するものです（都市計画法12条の4）。", "caution": ""}, {"label": "農業地域にのみ定めることができる", "reason": "地区計画は都市計画区域内に定めることができ、農業地域に限りません（都市計画法12条の4第1項）。", "caution": ""}], "summary": {"head": ["地区計画（都市計画法12条の4）", "内容"], "rows": [["決定者", "市町村"], ["内容", "地区内の建物の用途・形態・道路等の詳細ルール"], ["手続き", "住民参加・都市計画として決定"], ["効力", "地区計画区域内の建築行為等に制限"]]}}},
  {id:10296,unit:'t_kotei',level:2,field:'tax',text:'固定資産税の小規模住宅用地（200㎡以下）の課税標準の特例として正しいものはどれか。',opts:['課税標準が1/2に軽減','課税標準が1/3に軽減','課税標準が1/4に軽減','課税標準が1/6に軽減'],ans:3,exp:`小規模住宅用地（住宅1戸につき200㎡以下の部分）については、固定資産税の課税標準が1/6に軽減されます（地方税法349条の3の2）。200㎡超の一般住宅用地は1/3です。`,"kaisetsu":{"topic": "固定資産税：市町村が課す地方税・賦課期日は1月1日・評価替えは3年ごと", "basis": {"text": "固定資産税は市町村（東京23区は都）が課す地方税（地方税法343条）。賦課期日は毎年1月1日。評価替えは3年ごと（基準年度）。住宅用地の特例：200㎡以下は課税標準1/6、超過部分は1/3。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">固定資産税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市町村（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賦課期日</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">評価替え</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年ごと</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅用地（200㎡以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税標準1/6</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10297,unit:'t_toroku',level:2,field:'tax',text:'登録免許税の所有権移転登記（売買）における税率として正しいものはどれか。',opts:['固定資産税評価額の1%','固定資産税評価額の2%','固定資産税評価額の0.4%','固定資産税評価額の1.5%'],ans:1,exp:`売買による所有権移転登記の登録免許税の税率は固定資産税評価額（課税標準）の2%です（登録免許税法別表第一）。相続は0.4%、贈与・交換は2%、抵当権設定は債権額の0.4%です。`,"kaisetsu":{"topic": "登録免許税：所有権移転登記等に課税・国税・税率は課税標準×一定率", "basis": {"text": "登録免許税は不動産の所有権移転登記等に課税される国税（登録免許税法1条）。税率は課税標準（通常は固定資産税評価額）×一定率で計算します。相続による所有権移転登記は0.4%、売買は2%が原則税率（軽減措置あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">登録免許税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">国（国税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税対象</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">所有権移転登記等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">0.4%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2%（軽減措置あり）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10298,unit:'t_joto',level:2,field:'tax',text:'居住用財産の譲渡所得に係る3000万円の特別控除の要件として正しいものはどれか。',opts:['居住してから10年以上経過していること','居住用財産であれば住んでいない家屋でも適用可能','売却年の前年・前々年にこの特例の適用を受けていないこと','配偶者への売却でも適用可能'],ans:2,exp:`居住用財産の3000万円特別控除（租税特別措置法35条）は、売却年の前年・前々年にこの特例の適用を受けていないことが要件の1つです。居住の用に供さなくなった日から3年を経過する日の属する年末までの売却が対象で、配偶者・親族等への売却は適用外です。`,"kaisetsu":{"topic": "譲渡所得：分離課税・長期は20%・3,000万円控除は3年に1回", "basis": {"text": "土地・建物の譲渡所得は分離課税。長期（5年超）は合計20%（所得税15%+住民税5%）。短期（5年以下）は39%（所得税30%+住民税9%）。3,000万円特別控除は前年・前々年に適用があれば使えません（3年に1回）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">譲渡所得のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税方式</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">分離課税</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">長期（5年超）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計20%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">短期（5年以下）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計39%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3,000万円控除</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年に1回の制限</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10299,unit:'t_chika',level:2,field:'tax',text:'地価公示の標準地の価格の性格として正しいものはどれか。',opts:['実際の取引価格そのもの','正常な価格（通常の取引で成立すると認められる価格）','固定資産税評価額と同じ','路線価の1.2倍の価格'],ans:1,exp:`地価公示の標準地の価格（公示価格）は「正常な価格」すなわち土地について自由な取引が行われるとした場合において通常成立すると認められる価格です（地価公示法2条）。実際の取引価格は下回ることも上回ることもあります。`,"kaisetsu":{"topic": "地価公示・不動産鑑定評価：基準日は1月1日・土地鑑定委員会が実施・3手法", "basis": {"text": "地価公示の基準日は毎年1月1日で土地鑑定委員会（国土交通省）が実施（地価公示法）。公示価格は鑑定評価の規準となります（同法8条）。不動産鑑定評価の3手法：原価法・取引事例比較法・収益還元法。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">地価公示・鑑定評価</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">基準日</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">実施機関</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">土地鑑定委員会（国土交通省）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">鑑定評価の3手法</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原価法・取引事例比較法・収益還元法</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},

  {id:10300,unit:'r_ishi',level:2,field:'rights',text:'通謀虚偽表示（民法94条）において、虚偽表示の事実を知らない善意の第三者の保護について正しいものはどれか（判例）。',opts:['第三者が登記を備えた場合のみ保護される','善意の第三者は登記なしでも保護される（判例）','第三者は悪意でも保護される','第三者は常に保護されない'],ans:1,exp:`通謀虚偽表示における善意の第三者の保護については判例上、登記なしでも善意の第三者は保護されるとしています（民法94条2項）。ただし転得者が悪意の場合は保護されません。`,"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失保護）・通謀虚偽表示（無効・善意保護）。", "example": ""}, "reason": {"text": "通謀虚偽表示（民法94条）の無効は当事者間の問題です。善意の第三者を保護しないと、虚偽の外観を作り出した当事者の責任を第三者に負わせることになり不公平です。判例は善意の第三者には登記なしでも無効主張できないとしています。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "第三者が登記を備えた場合のみ保護される", "reason": "通謀虚偽表示の善意の第三者保護は登記不要です（判例）。善意であれば登記なしで保護されます（民法94条2項）。", "caution": "詐欺取消し後の第三者保護は登記の先後による対抗問題ですが、通謀虚偽表示の善意の第三者は登記不要です。"}, {"label": "第三者は悪意でも保護される", "reason": "通謀虚偽表示の無効は善意の第三者に対抗できませんが（民法94条2項）、悪意の第三者には無効を対抗できます。", "caution": ""}, {"label": "第三者は常に保護されない", "reason": "善意の第三者は保護されます（民法94条2項）。第三者が「常に保護されない」は誤りです。", "caution": ""}], "summary": {"head": ["第三者の状態", "保護の有無", "登記の要否"], "rows": [["善意", "保護される", "不要（判例）"], ["悪意", "保護されない", "—"]]}}},
  {id:10301,unit:'r_dairi',level:2,field:'rights',text:'無権代理行為の追認を相手方以外の第三者（代理人等）に行った場合の効力として正しいものはどれか。',opts:['第三者への追認は常に無効','第三者への追認は相手方がその事実を知った時から相手方に対抗できる（民法113条2項）','追認は必ず相手方に直接しなければならない','追認は書面によらなければ効力がない'],ans:1,exp:`無権代理の追認は相手方に対してしなければ相手方に対抗できませんが（民法113条2項）、第三者（代理人等）への追認は相手方がそれを知った時から相手方に対抗できます。追認があると行為時から有効となります（遡及効）。`,"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護します。", "example": ""}, "reason": {"text": "追認は相手方以外の第三者（代理人等）に対してもできますが（民法113条2項）、その追認は相手方がその事実を知った時から相手方に対抗できます。相手方の保護を図るための規定です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "第三者への追認は常に無効", "reason": "第三者への追認は有効ですが、相手方に対抗できるのは相手方がその事実を知った時からです（民法113条2項）。無効ではありません。", "caution": ""}, {"label": "追認は必ず相手方に直接しなければならない", "reason": "追認は相手方以外の第三者に対してもできます（民法113条2項）。ただし相手方への効力発生時期に違いがあります。", "caution": ""}, {"label": "追認は書面によらなければ効力がない", "reason": "追認に書面は要求されていません。口頭でも有効です（民法113条2項）。", "caution": ""}], "summary": {"head": ["追認の方法", "効力発生時期"], "rows": [["相手方への追認", "直ちに相手方に効力発生"], ["第三者への追認", "相手方がその事実を知った時から相手方に対抗可（民法113条2項）"], ["黙示の追認", "行為から追認の意思が明らかな場合も有効"]]}}},
  {id:10302,unit:'r_bukken',level:2,field:'rights',text:'動産の即時取得（民法192条）の要件として正しいものはどれか。',opts:['目的物が動産・取引行為・平穏・公然・善意・無過失での占有取得が必要','不動産にも適用される','悪意でも占有継続で取得できる','登記があれば即時取得が成立する'],ans:0,exp:`動産の即時取得の要件は①目的物が動産②取引行為に基づく③平穏・公然・善意・無過失で占有を開始することです（民法192条）。不動産には適用されません。`,"kaisetsu":{"topic": "物権変動：登記が対抗要件・不法占拠者には登記不要", "basis": {"text": "不動産の物権変動は登記が第三者への対抗要件です（民法177条）。不法占拠者には登記なく対抗できます（判例）。建物賃借権は引渡しが対抗要件です（借地借家法31条）。", "example": ""}, "reason": {"text": "即時取得（民法192条）は動産取引の安全を確保するための制度です。動産には登記制度がなく誰が真の所有者かわかりにくいため、善意・無過失で取引した者を保護することで市場の信頼を守ります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">物権変動の対抗要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対抗要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">二重譲渡</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先に登記した者が優先</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不法占拠者</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記不要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物賃借権</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡し</text></svg>", "choices": [{"label": "不動産にも適用される", "reason": "即時取得は動産のみが対象です（民法192条）。不動産は登記制度があるため対象外です。", "caution": "即時取得＝動産のみ。これは試験頻出の基本事項です。"}, {"label": "悪意でも占有継続で取得できる", "reason": "即時取得には善意・無過失が要件です（民法192条）。相手方が無権利者であることを知っていた（悪意）場合は成立しません。", "caution": ""}, {"label": "登記があれば即時取得が成立する", "reason": "動産の即時取得は占有取得（引渡し）で成立し、登記制度とは無関係です。動産に登記制度はありません。", "caution": ""}], "summary": {"head": ["即時取得の要件", "内容"], "rows": [["対象", "動産（不動産・金銭は除く）"], ["取引行為", "売買・交換等の取引行為による"], ["占有の態様", "平穏・公然・善意・無過失"], ["効果", "即時に完全な権利を取得（真の権利者は失権）"]]}}},
  {id:10303,unit:'r_tanpo',level:2,field:'rights',text:'抵当権の物上代位（民法372条・304条）の行使要件として正しいものはどれか。',opts:['売却代金・賃料等に対して払渡し・引渡し前に差押えが必要','売却代金・賃料等は差押えなしに抵当権者が優先受領できる','物上代位は賃料にのみ認められる','差押えは抵当権者でなく裁判所が職権で行う'],ans:0,exp:`物上代位権を行使するには、売却代金・賃料・保険金等が払い渡される前または引き渡される前に差押えが必要です（民法372条・304条）。払渡し後は物上代位権が消滅します。`,"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権（民法369条）。質権は占有の移転が必要。先取特権は法定担保物権（当然に成立）。農地への抵当権設定自体は、通常、農地法3条の許可対象ではありません。", "example": ""}, "reason": {"text": "物上代位権の行使には払渡し・引渡し前の差押えが必要です（民法372条・304条1項但書）。差押えを要件とする趣旨は、弁済を受ける者に対して二重払いを防止し、目的物の特定性を保持するためです（判例）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "売却代金・賃料等は差押えなしに抵当権者が優先受領できる", "reason": "差押えがなければ物上代位権を行使できません（民法304条1項但書）。差押えなしの優先受領はできません。", "caution": "物上代位には払渡し前の差押えが必要（民法304条1項但書）。"}, {"label": "物上代位は賃料にのみ認められる", "reason": "物上代位の対象は売買代金・賃料・保険金等です（民法304条1項）。賃料のみではありません。", "caution": ""}, {"label": "差押えは抵当権者でなく裁判所が職権で行う", "reason": "差押えは抵当権者が申立てを行います。裁判所が職権で行うものではありません。", "caution": ""}], "summary": {"head": ["物上代位の対象と要件", "内容"], "rows": [["対象", "売却代金・賃料・損害賠償・保険金等（民法304条1項）"], ["要件", "払渡し・引渡し前に差押え（民法304条1項但書）"], ["差押えの趣旨", "二重払い防止・特定性保持（判例）"], ["申立て", "抵当権者が裁判所に申立て"]]}}},
  {id:10304,unit:'r_jiko',level:2,field:'rights',text:'消滅時効の援用権者として正しいものはどれか。',opts:['債権者のみ','時効により直接利益を受ける者（主たる債務者・保証人・物上保証人・第三取得者等）','国のみが援用できる','裁判所が職権で時効を認定する'],ans:1,exp:`時効の援用権者は「時効により直接利益を受ける者」です（民法145条）。主たる債務者・連帯債務者・保証人・物上保証人・第三取得者等が含まれます。`,"kaisetsu":{"topic": "消滅時効：知った時から5年または行使可能時から10年", "basis": {"text": "消滅時効は「知った時から5年」または「行使可能時から10年」のいずれか早い方で完成します（民法166条）。時効は援用して初めて効力が発生します（民法145条）。承認は更新事由です（民法152条）。", "example": ""}, "reason": {"text": "消滅時効の援用権者は「時効によって直接利益を受ける者」です（民法145条・判例）。主たる債務者のほか、保証人・物上保証人・連帯債務者・第三取得者等も直接利益を受けるため援用できます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">期間</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人身損害</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年または20年</text></svg>", "choices": [{"label": "債権者のみ", "reason": "消滅時効の援用は債権者ではなく債務者側（直接利益を受ける者）が行います（民法145条）。", "caution": ""}, {"label": "国のみが援用できる", "reason": "時効の援用は国が独占するものではありません。時効によって直接利益を受ける私人が援用できます（民法145条）。", "caution": ""}, {"label": "裁判所が職権で時効を認定する", "reason": "裁判所は時効を職権で認定する権限はなく、当事者の援用が必要です（民法145条）。", "caution": ""}], "summary": {"head": ["援用権者", "理由"], "rows": [["主たる債務者", "時効消滅の直接当事者"], ["保証人", "主債務消滅→保証債務も消滅"], ["物上保証人", "被担保債権消滅→担保解放"], ["第三取得者", "被担保債権消滅→担保解放"], ["後順位抵当権者", "先順位消滅→順位昇進"]]}}},
  {id:10305,unit:'r_souzoku',level:2,field:'rights',text:'遺産分割協議の成立要件として正しいものはどれか。',opts:['相続人の過半数の同意で成立','相続人全員の同意（合意）が必要','家庭裁判所の承認が必要','遺産分割協議書は公正証書にしなければ無効'],ans:1,exp:`遺産分割協議は相続人全員の合意が必要です（民法907条）。一人でも欠けると協議は成立しません。協議書の書面化は望ましいですが公正証書である必要はありません。`,"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2・遺産分割は全員合意", "basis": {"text": "配偶者と子は各1/2（民法900条）。放棄は3か月以内に家裁へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2（民法1042条）。兄弟姉妹に遺留分はなし。遺産分割協議は全員合意が必要。", "example": ""}, "reason": {"text": "遺産分割協議は相続人全員の合意が必要です（民法907条1項）。1人でも欠けた協議は無効です。共有財産の分割という性質上、全員が合意しなければ法的拘束力が生じません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "相続人の過半数の同意で成立", "reason": "遺産分割協議は全員の合意が必要です（民法907条1項）。過半数では成立しません。", "caution": "遺産分割協議は全員の合意が必要。多数決不可。"}, {"label": "家庭裁判所の承認が必要", "reason": "遺産分割協議は相続人全員で行うものであり、家庭裁判所の承認は原則不要です。協議が調わない場合に家庭裁判所への調停・審判を申し立てます。", "caution": ""}, {"label": "遺産分割協議書は公正証書にしなければ無効", "reason": "遺産分割協議書を公正証書にする義務はありません（民法907条）。私署証書でも有効ですが、不動産登記等に使用する場合は実印・印鑑証明書が必要です。", "caution": ""}], "summary": {"head": ["遺産分割の方法", "要件"], "rows": [["協議分割", "相続人全員の合意（民法907条1項）"], ["調停分割", "家庭裁判所の調停"], ["審判分割", "家庭裁判所の審判"], ["遺言による分割", "遺言の内容に従う"]]}}},
  {id:10306,unit:'r_fuhoko',level:2,field:'rights',text:'製造物責任法（PL法）の特徴として正しいものはどれか。',opts:['製造業者の故意・過失を立証することが必要','製品の欠陥を立証すれば製造業者等は無過失責任を負う','被害者が損害を証明する必要はない','不動産も製造物責任法の対象'],ans:1,exp:`製造物責任法（PL法）では、製造物の「欠陥」により損害が生じた場合、製造業者等は故意・過失がなくても賠償責任を負います（製造物責任法3条）。製造物は「動産」に限られます。`,"kaisetsu":{"topic": "不法行為：故意または過失が必要・使用者責任・工作物責任", "basis": {"text": "不法行為は故意または過失が必要です（民法709条）。使用者は被用者の職務上の不法行為について責任を負います（民法715条）。工作物の所有者は無過失責任（占有者が免責された場合）（民法717条）。", "example": ""}, "reason": {"text": "製造物責任法（PL法）は製品の「欠陥」（安全性の欠如）を立証すれば製造業者等が無過失責任を負う法律です。被害者は製造業者の故意・過失を立証する必要がなく、欠陥の存在と損害・因果関係を立証すれば足ります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不法行為のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般不法行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">故意または過失が必要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">使用者責任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">被用者への求償可（信義則上制限）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">工作物の所有者責任</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無過失責任（占有者が免責された場合）</text></svg>", "choices": [{"label": "製造業者の故意・過失を立証することが必要", "reason": "PL法では故意・過失の立証は不要です。製品の「欠陥」を立証すれば足ります（製造物責任法3条）。", "caution": "PL法＝欠陥の立証で足りる（故意・過失の立証不要）。"}, {"label": "被害者が損害を証明する必要はない", "reason": "損害の発生と因果関係は被害者が証明する必要があります（製造物責任法3条）。欠陥の立証が不要になるのではなく、過失の立証が不要になります。", "caution": ""}, {"label": "不動産も製造物責任法の対象", "reason": "製造物責任法の対象は「製造物」（製造または加工された動産）です（製造物責任法2条1項）。不動産は対象外です。", "caution": "PL法の対象＝製造・加工された動産（不動産・未加工農産物は対象外）。"}], "summary": {"head": ["製造物責任法（PL法）", "内容"], "rows": [["立証事項", "製品の欠陥＋損害＋因果関係（故意・過失不要）"], ["対象", "製造・加工された動産"], ["対象外", "不動産・未加工農産物・ソフトウェア単体等"], ["責任者", "製造業者・加工業者・輸入業者等"]]}}},
  {id:10307,unit:'r_shakuchi',level:2,field:'rights',text:'事業用定期借地権（借地借家法23条）の存続期間として正しいものはどれか。',opts:['10年以上50年未満','10年以上20年未満と30年以上50年未満の2種類','5年以上20年以下','20年以上50年未満'],ans:0,exp:`事業用定期借地権の存続期間は10年以上50年未満です（借地借家法23条）。公正証書によることが効力要件で、専ら事業用建物の所有を目的とするものに限られます（居住用建物には使えません）。`,"kaisetsu":{"topic": "借地権：最短30年・建物登記で対抗・建物滅失でも消滅せず・定期借地権は3種類", "basis": {"text": "普通借地権の最短存続期間は30年（借地借家法3条）。借地上の建物の自己名義登記が対抗要件（同法10条）。建物が滅失しても借地権は消滅しません。定期借地権は①一般（50年以上）②事業用（10〜50年未満）③建物譲渡特約（30年以上）の3種類。", "example": ""}, "reason": {"text": "事業用定期借地権は専ら事業用建物の所有を目的とする定期借地権で、存続期間は10年以上50年未満です（借地借家法23条）。公正証書によらなければなりません（同条3項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">借地権のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">最短存続期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">対抗要件</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借地上の建物の自己名義登記</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物滅失</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借地権は消滅しない</text></svg>", "choices": [{"label": "10年以上20年未満と30年以上50年未満の2種類", "reason": "改正後の事業用定期借地権は「10年以上50年未満」の一種類です（借地借家法23条）。2種類ではありません（旧法では2種類でした）。", "caution": "現行法：事業用定期借地権は10年以上50年未満の一種類（借地借家法23条）。"}, {"label": "5年以上20年以下", "reason": "事業用定期借地権の存続期間は10年以上50年未満です（借地借家法23条）。5年以上20年以下ではありません。", "caution": ""}, {"label": "20年以上50年未満", "reason": "事業用定期借地権の最低期間は10年です（借地借家法23条）。20年ではありません。", "caution": ""}], "summary": {"head": ["事業用定期借地権（借地借家法23条）", "内容"], "rows": [["存続期間", "10年以上50年未満"], ["方式", "公正証書で締結必須"], ["用途", "専ら事業用（居住用不可）"], ["更新", "なし（確定終了）"]]}}},
  {id:10308,unit:'r_kukku',level:2,field:'rights',text:'区分所有建物の建替え決議の要件として正しいものはどれか。',opts:['区分所有者及び議決権の各過半数','区分所有者及び議決権の各3/4以上','区分所有者及び議決権の各4/5以上','区分所有者全員の合意'],ans:2,exp:`区分所有建物の建替え決議は区分所有者及び議決権の各4/5以上の多数決が必要です（区分所有法62条1項）。建替えには反対区分所有者の区分所有権の売渡し請求も生じます。`,"kaisetsu":{"topic": "区分所有法：重大変更は3/4以上・建替えは4/5以上・管理組合法人は30人以上", "basis": {"text": "共用部分の重大変更は区分所有者・議決権の各3/4以上の特別決議が必要（区分所有法17条）。建替えは4/5以上（同法62条）。管理組合法人の設立は3/4以上かつ区分所有者30人以上（同法47条）。専有部分と共有持分は分離処分不可（同法15条）。", "example": ""}, "reason": {"text": "建替え決議は区分所有者および議決権の各4/5以上の特別多数決が必要です（区分所有法62条1項）。建替えは区分所有者の権利に重大な影響を与えるため、特に高い決議要件が設定されています。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">区分所有法の決議要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">事項</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">普通決議</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">過半数</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">重大変更・規約変更</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3/4以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">管理組合法人</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3/4以上（30人以上）</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建替え</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4/5以上</text></svg>", "choices": [{"label": "区分所有者及び議決権の各過半数", "reason": "過半数は通常の管理行為の要件です（区分所有法18条1項）。建替え決議は4/5以上が必要です（同法62条1項）。", "caution": "建替え決議＝4/5以上（区分所有法62条1項）。"}, {"label": "区分所有者及び議決権の各3/4以上", "reason": "3/4以上は重大変更・規約変更等の要件です。建替えは4/5以上が必要です（区分所有法62条1項）。", "caution": ""}, {"label": "区分所有者全員の合意", "reason": "全員合意は不要です。建替えは4/5以上で足ります（区分所有法62条1項）。", "caution": ""}], "summary": {"head": ["建替え決議（区分所有法62条）", "内容"], "rows": [["要件", "4/5以上（区分所有者および議決権の各5分の4以上）"], ["決議事項", "建替え計画・参加の有無等"], ["不参加者", "建替え参加者から時価での買取請求を受ける"], ["マンション建替え円滑化法", "建替え組合の設立等の特別規定"]]}}},
  {id:10309,unit:'r_touki',level:2,field:'rights',text:'根抵当権の登記において必ず登記する事項として正しいものはどれか。',opts:['担保する個別の債権ごとの金額','極度額・担保すべき債権の範囲・債務者','担保する借入金の具体的金利','被担保債権の各弁済期'],ans:1,exp:`根抵当権の登記事項には極度額・担保すべき債権の範囲・債務者が必要です（民法398条の4・不動産登記法83条）。個別の債権額や金利の詳細は登記不要です。`,"kaisetsu":{"topic": "不動産登記：権利登記は共同申請・仮登記は順位保全・建物滅失は1か月以内", "basis": {"text": "権利に関する登記は原則として登記権利者と登記義務者が共同申請します（不動産登記法60条）。仮登記は順位保全機能があるが完全な対抗力は本登記後です。建物滅失登記の申請義務は1か月以内（同法57条）。", "example": ""}, "reason": {"text": "根抵当権は一定範囲の不特定債権を担保するため、極度額・担保すべき債権の範囲・債務者の3つが登記必須事項です（民法398条の2・不動産登記法83条）。これらが特定されることで担保の内容が公示されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産登記のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利登記</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則として共同申請</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮登記</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">順位保全（対抗力は本登記後）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物滅失登記</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1か月以内</text></svg>", "choices": [{"label": "担保する個別の債権ごとの金額", "reason": "根抵当権は不特定の債権を担保するため、個別の債権ごとの金額は登記しません。極度額（担保の上限）を登記します。", "caution": "根抵当権＝不特定債権を担保、極度額が上限。通常の抵当権（特定債権を担保）と区別。"}, {"label": "担保する借入金の具体的金利", "reason": "金利は根抵当権の登記必須事項ではありません。極度額・債権の範囲・債務者が必須です。", "caution": ""}, {"label": "被担保債権の各弁済期", "reason": "各弁済期は通常の抵当権でも登記事項ではなく、根抵当権でも同様に登記しません。", "caution": ""}], "summary": {"head": ["根抵当権の登記事項", "内容"], "rows": [["極度額", "担保する債権の上限額（必須）"], ["担保すべき債権の範囲", "銀行取引・手形等（必須）"], ["債務者", "（必須）"], ["確定期日", "定める場合のみ"]]}}},
  {id:10310,unit:'r_baibai',level:2,field:'rights',text:'危険負担（民法536条）において、双務契約で一方の債務が帰責事由なく履行不能となった場合の効果として正しいものはどれか（民法改正後）。',opts:['反対給付義務が自動的に消滅する','相手方は反対給付の履行を拒絶できる（履行拒絶権）','当然に契約が解除される','損害賠償請求ができる'],ans:1,exp:`2020年改正民法では、双務契約で一方の債務が帰責事由なく履行不能となった場合、相手方は反対給付の履行を拒むことができます（履行拒絶権）（民法536条1項）。`,"kaisetsu":{"topic": "売買：同時履行の抗弁権・解除は原則催告が必要・契約不適合責任", "basis": {"text": "売買では代金と引渡しは同時履行の関係（民法533条）。解除は原則として相当の期間を定めた催告後に行います（民法541条）。契約不適合責任の通知は知った時から1年以内（民法566条）。", "example": ""}, "reason": {"text": "2020年民法改正で危険負担の規律が変わりました。双務契約で一方の債務が帰責事由なく履行不能となった場合、相手方は反対給付の履行を拒絶できます（民法536条1項）。以前の「当然消滅」から「履行拒絶権」に変更されました。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">売買のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">同時履行</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金と引渡しは同時履行</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則として催告が必要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">契約不適合の通知</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から1年以内</text></svg>", "choices": [{"label": "反対給付義務が自動的に消滅する", "reason": "改正後は自動消滅ではなく「履行拒絶権」が発生します（民法536条1項）。解除または履行拒絶を選択できます。", "caution": "改正前：当然消滅。改正後：履行拒絶権（民法536条1項）。"}, {"label": "当然に契約が解除される", "reason": "危険負担では当然に解除されるのではなく、相手方が履行拒絶権を行使するか解除するかを選択できます（民法536条1項・541条等）。", "caution": ""}, {"label": "損害賠償請求ができる", "reason": "帰責事由なく履行不能となった場合は損害賠償の要件（帰責事由）を欠くため、損害賠償請求はできません（民法415条）。", "caution": ""}], "summary": {"head": ["危険負担（2020年改正後）", "内容"], "rows": [["一方の債務が帰責事由なく履行不能", "相手方は反対給付の履行拒絶可（民法536条1項）"], ["改正前", "反対給付義務が当然消滅"], ["解除", "別途解除権行使で契約解除可（民法542条）"], ["損害賠償", "帰責事由なし→原則不可"]]}}},
  {id:10311,unit:'r_chinshaku',level:2,field:'rights',text:'転貸借（又貸し）が適法に行われた場合の賃貸人・転借人の関係として正しいものはどれか。',opts:['転借人は賃貸人に対して直接義務を負わない','転借人は賃貸人に対して直接義務を負う（民法613条1項）','適法な転貸借でも賃貸人が新たに承諾が必要','転貸借は常に違法'],ans:1,exp:`適法な転貸借では転借人は賃貸人に対して直接義務を負います（民法613条1項）。賃貸人は転借人に対して転借料の範囲で賃料を直接請求できます。`,"kaisetsu":{"topic": "賃貸借：通常損耗は原状回復に含まれない・有益費は終了時に請求・賃料増額は正当事由が必要", "basis": {"text": "賃貸借終了時の原状回復義務に通常使用による損耗（壁の日焼け等）は含まれません（民法621条）。必要費は直ちに、有益費は終了時の請求が原則。更新拒絶には正当事由が必要（借地借家法28条）。", "example": ""}, "reason": {"text": "適法な転貸借（賃貸人承諾あり）では転借人は賃貸人に対して直接義務を負います（民法613条1項）。これは転借人が不法占拠のような状態になることを防ぎ、賃貸人の利益を保護するための規定です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">賃貸借のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通常損耗</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原状回復に含まれない</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要費</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直ちに請求可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有益費</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸借終了時に請求</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">更新拒絶</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当事由が必要</text></svg>", "choices": [{"label": "転借人は賃貸人に対して直接義務を負わない", "reason": "適法な転貸借では転借人は賃貸人に対して直接義務を負います（民法613条1項）。直接義務を負わないというのは誤りです。", "caution": ""}, {"label": "適法な転貸借でも賃貸人が新たに承諾が必要", "reason": "一度承諾した適法な転貸借に対して新たな承諾は不要です（民法612条・613条）。", "caution": ""}, {"label": "転貸借は常に違法", "reason": "賃貸人の承諾を得た転貸借は適法です（民法612条1項）。「常に違法」は誤りです。", "caution": ""}], "summary": {"head": ["転貸借の適法・違法", "内容"], "rows": [["適法転貸（承諾あり）", "転借人は賃貸人に直接義務（民法613条1項）"], ["無断転貸（承諾なし）", "解除事由（信頼関係破壊次第）"], ["転借人の義務上限", "転借料の範囲"]]}}},
  {id:10312,unit:'r_sorin',level:2,field:'rights',text:'共有物分割の方法（協議不成立の場合の裁判）として正しいものはどれか。',opts:['裁判による分割は認められていない','裁判所は現物分割・価格賠償・競売による代金分割等を命じることができる','裁判所は必ず等分に現物分割しか命じられない','共有物分割は不可能'],ans:1,exp:`共有物分割の協議が調わない場合、裁判所は現物分割・価格賠償（一方が全部取得し他方に代償金支払）・競売による代金分割等を命じることができます（民法258条）。`,"kaisetsu":{"topic": "相隣関係：竹木の根は自ら切除可・枝は原則所有者に・境界から50cmは慣習で変更可", "basis": {"text": "竹木の根が境界を越えたら自ら切除可（民法233条2項）。枝は原則として所有者に切除させます。建物の境界からの距離（50cm）は慣習・条例で変更可（民法234条・236条）。袋地通行権は有償が原則（民法212条）。", "example": ""}, "reason": {"text": "共有物分割の協議が不成立の場合、裁判所に分割請求できます（民法258条）。裁判所は①現物分割、②価格賠償（代償分割）、③競売による代金分割（換価分割）等を命じることができます。2021年改正で分割方法が整理されました。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相隣関係のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">事項</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">ルール</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">竹木の根（越境）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自ら切除可</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">竹木の枝（越境）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則：所有者に切除させる</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">境界距離（50cm）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">慣習・条例で変更可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">袋地通行権</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有償が原則</text></svg>", "choices": [{"label": "裁判による分割は認められていない", "reason": "裁判による共有物分割は民法258条に規定されています。「認められていない」は誤りです。", "caution": "協議不成立→裁判所に分割請求可（民法258条）。"}, {"label": "裁判所は必ず等分に現物分割しか命じられない", "reason": "裁判所は現物分割・価格賠償・競売等の方法を選択できます（民法258条2項・3項）。現物分割のみではありません。", "caution": ""}, {"label": "共有物分割は不可能", "reason": "共有者は原則としていつでも共有物の分割を請求できます（民法256条1項）。分割は可能です。", "caution": ""}], "summary": {"head": ["共有物の分割方法（民法258条）", "内容"], "rows": [["現物分割", "物理的に分割する"], ["価格賠償（代償分割）", "一人が取得して他の者に金銭を支払う"], ["競売による分割", "競売して代金を分ける"], ["不分割特約", "最長5年間の分割禁止合意可（民法256条1項ただし書）"]]}}},
  {id:10313,unit:'l_menkyo',level:2,field:'law',text:'宅建業者の廃業等を免許権者へ届け出る期限として正しいものはどれか。',opts:['廃業等から1週間以内','廃業等から30日以内（または知った日から30日以内）','廃業等から60日以内','届出は任意'],ans:1,exp:`廃業・解散・合併等の場合、その日（または知った日）から30日以内に免許権者に届け出なければなりません（宅建業法11条1項）。`,"kaisetsu":{"topic": "宅建業免許：知事・大臣免許の区別・有効期間5年・欠格事由は5年", "basis": {"text": "1都道府県→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間。2020年改正で成年被後見人の欠格条項は廃止。", "example": ""}, "reason": {"text": "宅建業者の廃業等については免許権者への届出が必要で、届出の期限は廃業等から30日以内です（宅建業法11条）。死亡の場合は相続人が死亡を知った日から30日以内です（同条1項1号）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（2020年改正で成年被後見人は廃止）</text></svg>", "choices": [{"label": "廃業等から1週間以内", "reason": "廃業等の届出期限は30日以内です（宅建業法11条）。1週間以内ではありません。", "caution": "廃業等の届出：30日以内（宅建業法11条）。"}, {"label": "廃業等から60日以内", "reason": "届出期限は30日以内です（宅建業法11条）。60日以内ではありません。", "caution": ""}, {"label": "届出は任意", "reason": "廃業等の届出は義務です（宅建業法11条）。任意ではありません。", "caution": ""}], "summary": {"head": ["廃業等の届出（宅建業法11条）", "期限"], "rows": [["廃業", "30日以内"], ["死亡", "相続人が死亡を知った日から30日以内"], ["解散（法人）", "30日以内"], ["合併消滅", "30日以内"]]}}},
  {id:10314,unit:'l_takkenshi',level:2,field:'law',text:'宅建士証の更新に際して受講が必要な法定講習の時期として正しいものはどれか。',opts:['合格後1年以内に受講','登録後5年ごとに受講','宅建士証の更新（交付申請）前6ヶ月以内に受講','随時受講すれば足りる'],ans:2,exp:`宅建士証の有効期間（5年）満了による更新の際には、交付申請前6ヶ月以内に法定講習（登録講習機関が実施）を受講しなければなりません（宅建業法22条の2第2項）。`,"kaisetsu":{"topic": "専任宅建士：5人に1人以上・兼任不可・2週間以内に補充", "basis": {"text": "事務所には業務従事者5人に1人以上の専任宅建士が必要（宅建業法31条の3）。1社専属で複数業者の兼任は不可。不足時は2週間以内に補充が必要。案内所（申込み受付）にも専任宅建士が必要。", "example": ""}, "reason": {"text": "宅建士証の更新（交付申請）をする際には、申請前6か月以内に都道府県知事が指定した法定講習を受講しなければなりません（宅建業法22条の2第2項）。ただし試験合格後1年以内に宅建士証の交付申請をする場合は講習を受けなくてよいです（同条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">専任宅建士のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">設置基準</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5人に1人以上</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">兼任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可（1社専属）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不足補充</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間以内</text></svg>", "choices": [{"label": "合格後1年以内に受講", "reason": "合格後1年以内に交付申請する場合は講習不要です（宅建業法22条の2第1項）。更新時の講習は交付申請前6か月以内です（同条2項）。", "caution": "法定講習：宅建士証交付申請前6か月以内（宅建業法22条の2第2項）。"}, {"label": "登録後5年ごとに受講", "reason": "登録後5年ごとという規定はありません。宅建士証の更新申請前6か月以内の受講が必要です（宅建業法22条の2第2項）。", "caution": ""}, {"label": "随時受講すれば足りる", "reason": "法定講習は宅建士証の交付申請前6か月以内に受講する必要があります（宅建業法22条の2第2項）。「随時」では要件を満たせない場合があります。", "caution": ""}], "summary": {"head": ["法定講習（宅建業法22条の2）", "内容"], "rows": [["受講時期", "宅建士証の交付申請前6か月以内"], ["受講機関", "都道府県知事が指定した機関"], ["例外", "合格後1年以内の交付申請は講習不要"], ["目的", "最新の宅建業法・不動産知識の習得"]]}}},
  {id:10315,unit:'l_baikai',level:2,field:'law',text:'専属専任媒介契約における指定流通機構（レインズ）への登録期限として正しいものはどれか。',opts:['契約締結から5日以内（休業日除く）','契約締結から7日以内（休業日除く）','契約締結から14日以内（休業日除く）','登録義務なし'],ans:0,exp:`専属専任媒介契約では契約締結から5日以内（休業日を除く）にレインズへ物件情報を登録しなければなりません（宅建業法34条の2第5項）。専任媒介は7日以内です。`,"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任の有効期間は最長3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。レインズ登録は専任7日以内・専属専任5日以内。業務報告は専任2週間に1回・専属専任1週間に1回。", "example": ""}, "reason": {"text": "専属専任媒介契約では契約締結の日から5日以内（休業日を除く）にレインズへの登録が義務付けられています（宅建業法34条の2第6項）。専任媒介は7日以内です（同条5項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">自己発見</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">レインズ</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専任</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専属専任</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text></svg>", "choices": [{"label": "契約締結から7日以内（休業日除く）", "reason": "7日以内は専任媒介のレインズ登録期限です（宅建業法34条の2第5項）。専属専任媒介は5日以内です（同条6項）。", "caution": "専任媒介：7日以内。専属専任媒介：5日以内（宅建業法34条の2）。"}, {"label": "契約締結から14日以内（休業日除く）", "reason": "14日という規定はありません（宅建業法34条の2第5項・6項）。", "caution": ""}, {"label": "登録義務なし", "reason": "専属専任媒介では5日以内のレインズ登録が義務です（宅建業法34条の2第6項）。「義務なし」は一般媒介の扱いです。", "caution": ""}], "summary": {"head": ["レインズ登録期限", "期限（休業日除く）"], "rows": [["一般媒介", "義務なし"], ["専任媒介", "7日以内（宅建業法34条の2第5項）"], ["専属専任媒介", "5日以内（宅建業法34条の2第6項）"]]}}},
  {id:10316,unit:'l_jusetsu',level:2,field:'law',text:'35条書面（重要事項説明書）に記載する法令上の制限について正しいものはどれか。',opts:['都市計画法・建築基準法のみ記載','対象物件に係るすべての関係法令上の制限を記載する','税金に関する事項のみ記載','インスペクション結果のみ記載'],ans:1,exp:`35条書面には「都市計画法・建築基準法その他の法令に基づく制限で取引の内容の別に応じて政令で定めるもの」を記載する必要があります（宅建業法35条1項2号）。対象物件に係るすべての関係法令の制限が対象です。`,"kaisetsu":{"topic": "重要事項説明：宅建士が説明・買主への交付・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主（貸主）は不要。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能。", "example": ""}, "reason": {"text": "重要事項説明書に記載する法令上の制限は都市計画法・建築基準法だけでなく、対象物件に係るすべての関係法令上の制限の概要を記載しなければなりません（宅建業法35条1項2号）。農地法・国土利用計画法等も含まれます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士のみ（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "都市計画法・建築基準法のみ記載", "reason": "関連するすべての法令上の制限を記載する必要があります（宅建業法35条1項2号）。「のみ」という制限はありません。", "caution": "法令上の制限：都市計画法・建築基準法だけでなく農地法・自然公園法等すべての関連法令。"}, {"label": "税金に関する事項のみ記載", "reason": "税金は法令上の制限の記載事項とは異なります。宅建業法35条1項2号は法令に基づく制限の概要を求めています。", "caution": ""}, {"label": "インスペクション結果のみ記載", "reason": "インスペクション結果は別の記載事項です（宅建業法35条1項14号）。法令上の制限と混同しないようにしましょう。", "caution": ""}], "summary": {"head": ["35条書面の法令上の制限（宅建業法35条1項2号）", "対象"], "rows": [["都市計画法", "用途地域・建ぺい率・容積率等"], ["建築基準法", "接道義務・斜線制限等"], ["農地法", "農地転用の許可・届出"], ["その他", "自然公園法・文化財保護法等の関連法令すべて"]]}}},
  {id:10317,unit:'l_37jo',level:2,field:'law',text:'37条書面（契約書面）に必ず記載しなければならない事項として正しいものはどれか。',opts:['融資あっせんに関する事項（常に必須）','宅地または建物の引渡しの時期','住宅性能評価を受けた旨','容積率・建ぺい率'],ans:1,exp:`「宅地または建物の引渡しの時期」は37条書面の必要的記載事項です（宅建業法37条1項4号）。融資あっせんに関する事項は定めがある場合のみ記載する任意的記載事項です。`,"kaisetsu":{"topic": "37条書面：全取引で交付・記名（押印不要）・移転登記申請時期は必要的記載事項", "basis": {"text": "37条書面は全取引で契約の双方当事者に交付が義務（宅建業法37条）。引渡し時期・移転登記申請時期は必要的記載事項。2021年改正で押印は不要、記名のみで足ります。", "example": ""}, "reason": {"text": "宅地または建物の引渡しの時期は37条書面の必要的記載事項です（宅建業法37条1項4号）。融資あっせん・住宅性能評価・法令上の制限は37条書面の必要的記載事項ではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付義務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全取引・双方当事者</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡時期・移転登記申請時期等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要）</text></svg>", "choices": [{"label": "融資あっせんに関する事項（常に必須）", "reason": "融資あっせんは定めがある場合の任意的記載事項です（宅建業法37条1項8号）。常に必須ではありません。", "caution": ""}, {"label": "住宅性能評価を受けた旨", "reason": "住宅性能評価は35条書面の記載事項であり37条書面の必要的記載事項ではありません。", "caution": ""}, {"label": "容積率・建ぺい率", "reason": "法令上の制限は35条書面の記載事項であり37条書面の必要的記載事項ではありません。", "caution": ""}], "summary": {"head": ["37条書面の必要的記載事項", "35条書面と比較"], "rows": [["代金・支払時期・方法", "37条書面（35条書面には含まれない）"], ["引渡し時期", "37条書面（35条書面には含まれない）"], ["移転登記申請時期", "37条書面（35条書面には含まれない）"], ["法令上の制限", "35条書面（37条書面には含まれない）"], ["登記された権利の種類", "35条書面（37条書面には含まれない）"]]}}},
  {id:10318,unit:'l_hoshu',level:2,field:'law',text:'宅建業者が自ら売主として売買契約を直接締結した場合（媒介でない場合）の報酬について正しいものはどれか。',opts:['代金の3%+6万円の媒介報酬を別途受領できる','売主として売買する場合は代金に利益を含むため別途媒介報酬を請求できない','売主宅建業者は媒介報酬と同額の手数料を受領できる','売主宅建業者は報酬制限の対象外'],ans:1,exp:`宅建業者が自ら売主として直接売買契約を結ぶ場合、売買代金の中に利益が含まれるため別途「媒介報酬」を受け取ることはできません。宅建業法の報酬制限（46条）は媒介・代理の場合に適用される規定です。`,"kaisetsu":{"topic": "報酬：売買は代金×3%+6万（400万超）・賃貸は借賃1か月・上限超過は不可", "basis": {"text": "売買（400万超）の一方からの上限は代金×3%+6万。双方合計は一方上限×2。賃貸（居住用・非居住用とも）は借賃1か月分。低廉な空家等（800万円以下）は、媒介報酬について原則の報酬額を超えて30万円（税別）まで受領できる場合があります（依頼者への説明・合意が必要）。", "example": ""}, "reason": {"text": "宅建業者が自ら売主として直接売買する場合、売買代金の中に業者の利益（手数料相当）が含まれています。そのため別途媒介報酬は受け取れません（宅建業法46条・告示の趣旨）。報酬規制は媒介・代理の場合に適用されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対象</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（400万超）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万（一方）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（200万以下）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸（双方合計）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借賃1か月分</text></svg>", "choices": [{"label": "代金の3%+6万円の媒介報酬を別途受領できる", "reason": "自ら売主として売買する場合は代金に利益が含まれており、別途媒介報酬は受け取れません（宅建業法46条・告示）。", "caution": "自ら売主の場合：媒介報酬を受け取れない（代金に利益を含む）。"}, {"label": "売主宅建業者は媒介報酬と同額の手数料を受領できる", "reason": "自ら売主の場合は別途の報酬（手数料）を受け取ることはできません（宅建業法46条・告示）。", "caution": ""}, {"label": "売主宅建業者は報酬制限の対象外", "reason": "自ら売主の場合、報酬制限（告示）の適用対象外ですが、代金に利益を含む形での取引となります。「対象外だから自由に報酬を取れる」という意味では誤りです。", "caution": ""}], "summary": {"head": ["自ら売主vs媒介の報酬", "内容"], "rows": [["自ら売主", "代金に利益を含む→別途報酬を取れない"], ["媒介", "依頼者から報酬を受け取る（告示の上限あり）"], ["代理", "依頼者から媒介の2倍まで"]]}}},
  {id:10319,unit:'l_hosho',level:2,field:'law',text:'保証協会への弁済業務保証金分担金の額（主たる事務所のみの場合）として正しいものはどれか。',opts:['100万円','60万円','10万円','1,000万円'],ans:1,exp:`弁済業務保証金分担金は主たる事務所につき60万円、従たる事務所1ヶ所あたり30万円です（宅建業法64条の9第1項）。営業保証金（主たる事務所1,000万円）と比べて大幅に少額となっています。`,"kaisetsu":{"topic": "営業保証金・保証協会：主1,000万・従500万/営業保証金vs分担金60万・30万", "basis": {"text": "営業保証金は主1,000万・従500万（宅建業法25条）。保証協会の分担金は主60万・従30万（同法64条の9）。還付対象は業者以外の取引した者。加入は任意。不足補充は通知後2週間以内。", "example": ""}, "reason": {"text": "保証協会への弁済業務保証金分担金は主たる事務所につき60万円です（宅建業法64条の9第1項1号）。従たる事務所は1か所あたり30万円です（同条1項2号）。営業保証金（主たる事務所1000万円）より大幅に少額です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">営業保証金と弁済業務保証金</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">営業保証金</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">弁済業務保証金（分担金）</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">主たる事務所</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000万円</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">60万円</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従たる事務所/所</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">500万円</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">還付対象</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者以外</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者以外</text></svg>", "choices": [{"label": "100万円", "reason": "主たる事務所の弁済業務保証金分担金は60万円です（宅建業法64条の9第1項1号）。100万円ではありません。", "caution": "弁済業務保証金分担金：主たる事務所60万円・従たる事務所30万円（宅建業法64条の9）。"}, {"label": "10万円", "reason": "主たる事務所の分担金は60万円です（宅建業法64条の9第1項1号）。10万円ではありません。", "caution": ""}, {"label": "1,000万円", "reason": "1000万円は営業保証金（主たる事務所）の金額です（宅建業法施行令2条1項1号）。弁済業務保証金分担金は60万円です（宅建業法64条の9第1項1号）。", "caution": ""}], "summary": {"head": ["弁済業務保証金分担金（宅建業法64条の9）", "金額"], "rows": [["主たる事務所", "60万円"], ["従たる事務所（1か所あたり）", "30万円"], ["営業保証金との比較", "主たる事務所1000万円→60万円（約1/17）"], ["還付上限", "当該業者の営業保証金相当額"]]}}},
  {id:10320,unit:'l_cooling',level:2,field:'law',text:'クーリングオフの行使方法として正しいものはどれか。',opts:['口頭でも有効','書面または電磁的方法（相手方が承諾した場合）で行う','宅建業者の事務所でのみ行使できる','相手方の同意が必要'],ans:1,exp:`クーリングオフは書面または電磁的方法（相手方の承諾がある場合）で行使する必要があります（宅建業法37条の2第1項）。書面が発送された時点（発信主義）で効力が生じます。`,"kaisetsu":{"topic": "クーリングオフ：告知日から8日以内・書面で・事務所では不可・全額返還", "basis": {"text": "クーリングオフは告知を受けた日から8日以内に書面で行います（宅建業法37条の2）。事務所・モデルルーム等での申込みはクーリングオフ不可。解除後業者は全額返還（費用控除不可）。", "example": ""}, "reason": {"text": "クーリングオフの意思表示は書面で行います（宅建業法37条の2第2項）。2022年改正により、相手方（宅建業者）が承諾した場合は電磁的方法によることも認められました（同条2項）。口頭では無効です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">クーリングオフのポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">告知日から8日以内</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">方法</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面（発信主義）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所での申込み</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">クーリングオフ不可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除後</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全額返還</text></svg>", "choices": [{"label": "口頭でも有効", "reason": "クーリングオフは書面または電磁的方法（相手方の承諾が必要）で行います（宅建業法37条の2第2項）。口頭では無効です。", "caution": "クーリングオフ：書面（または承諾を得た電磁的方法）で行う（宅建業法37条の2第2項）。"}, {"label": "宅建業者の事務所でのみ行使できる", "reason": "クーリングオフは書面を郵送する等の方法で行うものであり、事務所でのみ行使できるものではありません（宅建業法37条の2第2項）。", "caution": ""}, {"label": "相手方の同意が必要", "reason": "書面によるクーリングオフに相手方の同意は不要です（宅建業法37条の2第2項）。電磁的方法の場合のみ相手方の承諾が必要です。", "caution": ""}], "summary": {"head": ["クーリングオフの行使方法（宅建業法37条の2第2項）", "内容"], "rows": [["方法", "書面（または相手方承諾のある電磁的方法）"], ["口頭", "無効"], ["効力発生", "発信主義（書面を発した時）"], ["内容証明", "義務はないが証拠のため推奨"]]}}},
  {id:10321,unit:'l_kantoku',level:2,field:'law',text:'宅建業者の従業者証明書（証明書）の携帯・提示義務について正しいものはどれか。',opts:['宅建士のみが携帯する','すべての従業者が携帯し取引の関係者から請求があれば提示しなければならない','事務所内に掲示すれば携帯は不要','代表取締役は不要'],ans:1,exp:`宅建業者はすべての従業者（役員を含む）に従業者証明書を携帯させ、取引の関係者から請求があった場合は提示させなければなりません（宅建業法48条）。`,"kaisetsu":{"topic": "監督処分：業務停止最長1年・大臣は全業者に指示可・指示違反→業務停止", "basis": {"text": "業務停止の最長期間は1年（宅建業法65条2項）。大臣は全業者（知事免許含む）に指示処分を行う権限があります。指示処分違反→業務停止、業務停止違反→免許取消という段階があります。", "example": ""}, "reason": {"text": "宅建業者のすべての従業者（宅建士・事務員等）は従業者証明書を携帯し、取引の関係者から請求があれば提示しなければなりません（宅建業法48条1項）。宅建士のみでなく全従業者が対象です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">監督処分のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">処分</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">最長1年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣の権限</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全業者に指示可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">指示処分違反</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止の対象</text></svg>", "choices": [{"label": "宅建士のみが携帯する", "reason": "全ての従業者が携帯義務を負います（宅建業法48条1項）。宅建士のみではありません。", "caution": "従業者証明書：全従業者が携帯・請求時提示義務（宅建業法48条1項）。"}, {"label": "事務所内に掲示すれば携帯は不要", "reason": "事務所への掲示（従業者名簿）と携帯義務は別のものです（宅建業法48条1項・2項）。掲示しても携帯義務は免除されません。", "caution": ""}, {"label": "代表取締役は不要", "reason": "代表取締役も従業者に含まれ携帯義務を負います（宅建業法48条1項）。", "caution": ""}], "summary": {"head": ["従業者証明書（宅建業法48条）", "内容"], "rows": [["携帯義務者", "全ての従業者（宅建士・事務員・代表取締役等）"], ["提示義務", "取引の関係者から請求があれば提示"], ["違反", "携帯・提示義務違反は行政処分の対象"], ["従業者名簿", "別途事務所への備え付けが義務（宅建業法48条2項）"]]}}},
  {id:10322,unit:'k_toshi',level:2,field:'limit',text:'市街化調整区域内での開発行為で許可が不要とされる場合として正しいものはどれか。',opts:['市街化調整区域では開発行為は一切認められない','農林漁業を営む者の住宅等一定の農林漁業用建築物を目的とする開発行為は許可不要','1,000平方メートル未満であれば許可不要','都道府県知事が認めれば自由に開発できる'],ans:1,exp:`市街化調整区域内でも農業・林業・漁業を営む者の住宅等、一定の農林漁業用建築物を目的とする開発行為は開発許可が不要です（都市計画法29条1項2号）。`,"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域の1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "市街化調整区域では原則として開発行為は許可が必要ですが、農林漁業を営む者の住宅・農林漁業用施設のための開発行為は例外的に許可不要です（都市計画法29条1項2号）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "市街化調整区域では開発行為は一切認められない", "reason": "農林漁業用施設等の例外があります（都市計画法29条1項2号）。「一切認められない」は誤りです。", "caution": ""}, {"label": "1,000平方メートル未満であれば許可不要", "reason": "市街化調整区域では規模にかかわらず原則として許可が必要です（都市計画法29条）。1000㎡という基準は市街化区域の基準です。", "caution": "市街化調整区域：規模にかかわらず原則許可必要。農林漁業用施設は例外（都市計画法29条1項2号）。"}, {"label": "都道府県知事が認めれば自由に開発できる", "reason": "知事が認める（開発許可を与える）ことができますが、「自由に」開発できるわけではなく、許可の基準（都市計画法34条）に従う必要があります。", "caution": ""}], "summary": {"head": ["市街化調整区域の開発許可不要の例外（都市計画法29条1項2号）", "内容"], "rows": [["農林漁業者の農業用施設", "農業用倉庫等"], ["農林漁業者の住宅", "農家住宅"], ["許可が必要な場合", "上記以外の開発行為（原則）"]]}}},
  {id:10323,unit:'k_kenchiku',level:2,field:'limit',text:'防火地域内にある耐火建築物等（建築基準法53条3項）に対する建ぺい率の扱いとして正しいものはどれか。',opts:['建ぺい率の制限は適用されない','建ぺい率の上限が10%加算（緩和）される','建ぺい率が厳しくなる','建ぺい率への影響はない'],ans:1,exp:`防火地域内にある耐火建築物等（または準防火地域内にある耐火建築物等）は建ぺい率が10%加算（緩和）されます（建築基準法53条3項）。また角地等も10%加算されます。`,"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・用途制限・道路斜線", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。防火地域の耐火建築物は隣地境界線に外壁を接して建築可（同法65条）。", "example": ""}, "reason": {"text": "防火地域内の耐火建築物等については建ぺい率が10%加算（緩和）されます（建築基準法53条3項1号）。また角地（特定行政庁が指定した角地）でも10%加算されます（同条3項2号）。両方に該当する場合は合計20%加算されます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">防火地域の耐火建築物</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">隣地境界線に接して建築可</text></svg>", "choices": [{"label": "建ぺい率の制限は適用されない", "reason": "建ぺい率の制限は適用されますが、10%加算の緩和があります（建築基準法53条3項1号）。「適用されない」は誤りです。", "caution": "防火地域内耐火建築物：建ぺい率10%加算（建築基準法53条3項1号）。"}, {"label": "建ぺい率が厳しくなる", "reason": "防火地域内の耐火建築物は建ぺい率が緩和（10%加算）されます（建築基準法53条3項1号）。厳しくなるのではありません。", "caution": ""}, {"label": "建ぺい率への影響はない", "reason": "10%加算の緩和があります（建築基準法53条3項1号）。「影響なし」は誤りです。", "caution": ""}], "summary": {"head": ["建ぺい率の加算緩和（建築基準法53条3項）", "加算量"], "rows": [["防火地域内の耐火建築物等", "10%加算（1号）"], ["特定行政庁指定の角地", "10%加算（2号）"], ["両方に該当", "合計20%加算"], ["指定建ぺい率が80%の場合", "防火地域内耐火建築物は制限なし（100%）"]]}}},
  {id:10324,unit:'k_nochi',level:2,field:'limit',text:'農地法5条（転用目的の権利移動）で国または都道府県等が転用目的で農地を取得する場合の手続きとして正しいものはどれか。',opts:['都道府県知事の許可が必要','農林水産大臣の許可が必要','協議または通知で足り許可は不要','農業委員会の許可が必要'],ans:2,exp:`国または都道府県等が一定の目的のために農地の権利を取得する場合は農地法5条の許可が不要となり、協議または通知で足ります（農地法5条1項6号・7号等）。`,"kaisetsu":{"topic": "農地法：3条は農業委員会・4・5条は都道府県知事・市街化区域は届出のみ", "basis": {"text": "農地法3条の許可権者は農業委員会。4・5条は都道府県知事等。市街化区域の農地転用（4・5条）は農業委員会への届出のみOK。相続は許可不要・3か月以内の農業委員会への届出が必要。", "example": ""}, "reason": {"text": "国または都道府県等が農地法5条に基づき転用目的で農地を取得する場合、都道府県知事等との協議または通知で足り、許可は不要です（農地法5条4項・7項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text></svg>", "choices": [{"label": "都道府県知事の許可が必要", "reason": "国または都道府県等が取得する場合は協議等で足り許可不要です（農地法5条4項・7項）。", "caution": "国・都道府県等の農地取得：協議または通知で足り許可不要（農地法5条4項・7項）。"}, {"label": "農林水産大臣の許可が必要", "reason": "国・都道府県等の取得には農林水産大臣の許可は不要です（農地法5条4項・7項）。", "caution": ""}, {"label": "農業委員会の許可が必要", "reason": "農業委員会の許可ではなく協議等で足ります（農地法5条4項・7項）。", "caution": ""}], "summary": {"head": ["国・都道府県等の農地取得（農地法5条4項・7項）", "手続き"], "rows": [["国・都道府県等が転用目的で取得", "協議または通知（許可不要）"], ["一般の転用目的取得", "都道府県知事の許可"]]}}},
  {id:10325,unit:'k_kokudo',level:2,field:'limit',text:'国土利用計画法の事後届出が不要な取引として正しいものはどれか。',opts:['売買による一定規模以上の土地取得','相続による土地取得','贈与による土地取得','交換による土地取得'],ans:1,exp:`国土利用計画法の事後届出は「土地売買等の契約」に基づく取引が対象です（国土利用計画法23条）。相続・遺贈（贈与遺言を除く）・信託（委託者に戻す場合）等は届出不要です。`,"kaisetsu":{"topic": "国土利用計画法：事後届出は2週間以内・市街化区域は2,000㎡以上・規制区域は許可制", "basis": {"text": "事後届出は契約締結後2週間以内（国土利用計画法23条）。市街化区域は2,000㎡以上・市街化調整区域は5,000㎡以上・都市計画区域外は10,000㎡以上。届出義務者は買主のみ。規制区域は許可制。", "example": ""}, "reason": {"text": "相続による土地取得は国土利用計画法の事後届出が不要です（国土利用計画法23条2項3号）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">国土利用計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">区域</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">基準面積</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2,000㎡以上</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化調整区域</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都市計画区域外</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10,000㎡以上</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">規制区域</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">許可制（届出ではない）</text></svg>", "choices": [{"label": "売買による一定規模以上の土地取得", "reason": "売買による土地取得は事後届出の対象です（国土利用計画法23条1項）。", "caution": "相続：事後届出不要（国土利用計画法23条2項3号）。"}, {"label": "贈与による土地取得", "reason": "無償の贈与については届出不要とする考え方があります（国土利用計画法14条1項等の解釈）。", "caution": ""}, {"label": "交換による土地取得", "reason": "交換による土地取得は事後届出の対象です（国土利用計画法23条1項）。", "caution": ""}], "summary": {"head": ["事後届出が不要な場合（国土利用計画法23条2項）", "内容"], "rows": [["相続", "届出不要（同条2項3号）"], ["国・都道府県等が当事者", "届出不要（同条2項1号）"]]}}},
  {id:10326,unit:'k_kukaku',level:2,field:'limit',text:'土地区画整理事業における清算金の仕組みとして正しいものはどれか。',opts:['換地面積が少なくなった場合に土地所有者が施行者に支払うもの','換地と従前地の差に応じて金銭で調整するもの（施行者が交付または権利者が納付）','清算金は任意で支払わなくてよい','清算金は現物のみで支払われる'],ans:1,exp:`清算金は換地と従前地との面積や価値の差に応じて金銭で調整するものです（土地区画整理法94条）。換地が少なければ施行者が権利者に交付し、換地が多ければ権利者が施行者に納付します。`,"kaisetsu":{"topic": "土地区画整理法：換地は公告翌日確定・仮換地は従前地使用不可・組合は2/3以上", "basis": {"text": "換地処分の公告翌日から換地が確定します（土地区画整理法104条）。仮換地の指定後は従前地を使用できなくなります（同法99条）。組合設立には土地所有者・借地権者の各2/3以上の同意が必要です。", "example": ""}, "reason": {"text": "清算金は換地と従前地の価値の差を金銭で調整するものです（土地区画整理法94条）。換地が従前地より価値が小さい場合は施行者が交付し、大きい場合は権利者が納付します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">土地区画整理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">換地の確定</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公告の翌日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮換地指定後</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従前地は使用不可（所有権は残る）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">組合設立</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各2/3以上の同意</text></svg>", "choices": [{"label": "換地面積が少なくなった場合に土地所有者が施行者に支払うもの", "reason": "換地面積が小さくなった（価値が減少した）場合は施行者が清算金を交付します（土地区画整理法94条）。「所有者が支払う」は逆です。", "caution": "換地＜従前地：施行者が清算金を交付。換地＞従前地：所有者が清算金を納付（土地区画整理法94条）。"}, {"label": "清算金は任意で支払わなくてよい", "reason": "清算金は法的義務であり任意ではありません（土地区画整理法94条）。", "caution": ""}, {"label": "清算金は現物のみで支払われる", "reason": "清算金は金銭（現金）で支払われます（土地区画整理法94条）。", "caution": ""}], "summary": {"head": ["清算金（土地区画整理法94条）", "内容"], "rows": [["換地が従前地より価値大", "権利者が施行者に納付"], ["換地が従前地より価値小", "施行者が権利者に交付"], ["確定時期", "換地処分の公告後"]]}}},
  {id:10327,unit:'t_joto',level:2,field:'tax',text:'「被相続人の居住用財産（空き家）の譲渡所得の3,000万円特別控除」の対象となる主な要件として正しいものはどれか。',opts:['相続から5年超経過後の譲渡のみ対象','相続開始直前に被相続人が居住していた建物で一定の要件（耐震改修等・譲渡価格1億円以下等）を満たす場合','居住用以外の家屋でも適用できる','譲渡価格に上限はない'],ans:1,exp:`空き家特例（租税特別措置法35条3項）は相続開始直前に被相続人が居住していた建物・土地について、一定の要件（2023年改正含む：耐震改修、売却代金1億円以下等）を満たした譲渡に3,000万円控除が適用されます。`,"kaisetsu":{"topic": "譲渡所得：分離課税・長期は20%・3,000万円控除は3年に1回", "basis": {"text": "土地・建物の譲渡所得は分離課税。長期（5年超）は合計20%（所得税15%+住民税5%）。短期（5年以下）は39%（所得税30%+住民税9%）。3,000万円特別控除は前年・前々年に適用があれば使えません（3年に1回）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">譲渡所得のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税方式</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">分離課税</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">長期（5年超）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計20%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">短期（5年以下）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計39%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3,000万円控除</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年に1回の制限</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10328,unit:'t_shutoku',level:2,field:'tax',text:'新築住宅の不動産取得税における課税標準の特例控除として正しいものはどれか。',opts:['課税標準から200万円を控除','課税標準から1,200万円を控除（認定長期優良住宅は1,300万円）','税額から10万円を控除','床面積120平方メートルまでが非課税'],ans:1,exp:`新築住宅（床面積50平方メートル以上240平方メートル以下）の不動産取得税では課税標準から1,200万円（認定長期優良住宅等は1,300万円）を控除する特例があります（地方税法附則11条）。`,"kaisetsu":{"topic": "不動産取得税：都道府県が課す地方税・相続は非課税・1回だけ課税", "basis": {"text": "不動産取得税は都道府県が課す地方税（地方税法73条の2）。相続・法人の合併等は非課税。一度の取得に一度だけ課税（毎年ではない）。標準税率は4%（住宅・土地は3%の軽減あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産取得税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税の頻度</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取得時に1回のみ</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">標準税率</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4%（住宅・土地は3%）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10329,unit:'t_kotei',level:2,field:'tax',text:'固定資産税の課税権者として正しいものはどれか。',opts:['国','都道府県','市町村（東京特別区においては東京都）','国税庁'],ans:2,exp:`固定資産税は市町村税であり、課税権者は市町村（東京特別区においては東京都）です（地方税法342条・734条）。`,"kaisetsu":{"topic": "固定資産税：市町村が課す地方税・賦課期日は1月1日・評価替えは3年ごと", "basis": {"text": "固定資産税は市町村（東京23区は都）が課す地方税（地方税法343条）。賦課期日は毎年1月1日。評価替えは3年ごと（基準年度）。住宅用地の特例：200㎡以下は課税標準1/6、超過部分は1/3。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">固定資産税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市町村（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賦課期日</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">評価替え</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年ごと</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅用地（200㎡以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税標準1/6</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10330,unit:'t_toroku',level:2,field:'tax',text:'一定要件を満たす新築住宅の所有権保存登記の登録免許税の軽減税率として正しいものはどれか。',opts:['0.4%（本則のまま）','0.15%に軽減','0.3%に軽減','全額免除'],ans:1,exp:`一定の要件を満たす新築住宅（床面積50平方メートル以上等）の所有権保存登記の登録免許税は本則0.4%から0.15%に軽減されます（租税特別措置法72条）。`,"kaisetsu":{"topic": "登録免許税：所有権移転登記等に課税・国税・税率は課税標準×一定率", "basis": {"text": "登録免許税は不動産の所有権移転登記等に課税される国税（登録免許税法1条）。税率は課税標準（通常は固定資産税評価額）×一定率で計算します。相続による所有権移転登記は0.4%、売買は2%が原則税率（軽減措置あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">登録免許税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">国（国税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税対象</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">所有権移転登記等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">0.4%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2%（軽減措置あり）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10331,unit:'t_chika',level:2,field:'tax',text:'基準地価格（都道府県地価調査）の調査時点と公表時期として正しいものはどれか。',opts:['国土交通省が毎年1月1日時点で調査・3月公表','都道府県が毎年7月1日時点で調査・9月頃公表','国土交通省が毎年7月1日時点で調査','都道府県が毎年1月1日時点で調査'],ans:1,exp:`基準地価格（都道府県地価調査）は都道府県が毎年7月1日時点の価格を調査し9月頃公表します（国土利用計画法施行令9条）。地価公示は国土交通省が1月1日時点で3月頃公表します。`,"kaisetsu":{"topic": "地価公示・不動産鑑定評価：基準日は1月1日・土地鑑定委員会が実施・3手法", "basis": {"text": "地価公示の基準日は毎年1月1日で土地鑑定委員会（国土交通省）が実施（地価公示法）。公示価格は鑑定評価の規準となります（同法8条）。不動産鑑定評価の3手法：原価法・取引事例比較法・収益還元法。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">地価公示・鑑定評価</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">基準日</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">実施機関</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">土地鑑定委員会（国土交通省）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">鑑定評価の3手法</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原価法・取引事例比較法・収益還元法</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10332,unit:'t_kinyu',level:2,field:'tax',text:'フラット35の金利タイプについて正しいものはどれか。',opts:['全期間変動金利型','借入時に決定した金利が返済完了まで変動しない全期間固定金利型','当初10年固定・その後変動の選択型','金利は毎月変動する'],ans:1,exp:`フラット35は借入時に決定した金利が返済完了まで変動しない全期間固定金利型の住宅ローンです。金利変動リスクがなく長期の資金計画が立てやすいのが最大の特徴です。`,"kaisetsu":{"topic": "住宅金融支援機構・フラット35：証券化支援が主業務・全期間固定・各機関が金利設定", "basis": {"text": "住宅金融支援機構はフラット35（民間住宅ローンの証券化支援）が主業務。フラット35は全期間固定金利のみで変動金利の選択はできません。金利は各民間金融機関が独自に設定。返済期間は15年以上35年以下。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">フラット35のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">主な業務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">民間住宅ローンの証券化支援</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">金利</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全期間固定・各金融機関が設定</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">返済期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">15年以上35年以下</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">申込み先</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">民間金融機関</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10333,unit:'r_ishi',level:3,field:'rights',text:'通謀虚偽表示（民法94条）における第三者保護について。AとBが通謀して虚偽の売買契約をし登記もBに移転した。その後Bから当該不動産を買い受けたCが「善意」の場合の法律関係として正しいものはどれか。',opts:['AはBとの売買が無効なのでCにも対抗できる','善意のCはAからの無効主張に対抗できる','Cの善意は推定されないため証明が必要','Cが善意でも登記を備えていなければ保護されない'],ans:1,exp:`民法94条2項は通謀虚偽表示の無効を善意の第三者に対抗できないと規定します。善意のCはAからの無効主張を受けません。Cの善意は推定され、AがCの悪意を立証しなければなりません（判例）。また登記の有無はCの保護に影響しないとされています（判例）。`,"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失保護）・通謀虚偽表示（無効・善意保護）。", "example": ""}, "reason": {"text": "AとBが通謀して虚偽の売買をした場合、その売買は無効（民法94条1項）です。しかし善意のCはAからの無効主張に対抗できます（民法94条2項）。これは取引の安全と外観への信頼保護のためです。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "AはBとの売買が無効なのでCにも対抗できる", "reason": "通謀虚偽表示の無効は善意の第三者に対抗できません（民法94条2項）。CがBから善意で購入した場合、AはCに対して無効を主張できません。", "caution": "「無効だから第三者にも対抗できる」は誤り。善意の第三者には対抗できません。"}, {"label": "Cの善意は推定されないため証明が必要", "reason": "民法上、善意は推定されます。第三者の悪意を主張する側（A）が立証責任を負います。", "caution": ""}, {"label": "Cが善意でも登記を備えていなければ保護されない", "reason": "通謀虚偽表示の善意の第三者保護に登記は不要です（判例）。登記なしでも善意であれば保護されます。", "caution": ""}], "summary": {"head": ["場面", "Cの状態", "Aの主張"], "rows": [["通謀虚偽表示後にCが取得", "善意", "無効対抗不可"], ["通謀虚偽表示後にCが取得", "悪意", "無効対抗可"]]}}},
  {id:10334,unit:'r_dairi',level:3,field:'rights',text:'表見代理の成立と本人の責任について。AはBに土地売買の代理権を与えたが、Bはその権限外の行為（建物の売買）を行い、Cが代理権ありと信じた場合の法律構成として正しいものはどれか。',opts:['Bが権限外の行為をしたのでAは一切責任を負わない','権限外行為の表見代理（民法110条）が成立すればAは責任を負う','Cは善意であればBに対してのみ責任追及できる','表見代理と無権代理の責任追及は必ずどちらかを選択しなければならない'],ans:1,exp:`民法110条の権限外行為の表見代理は、代理人が基本的代理権を有し第三者がその権限内と信じたことに正当な理由がある場合に成立します。相手方Cは本人Aに対し表見代理を主張するか、代理人Bに対し無権代理責任を追及するかを選択できます（選択的行使が可能）。`,"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護します。", "example": ""}, "reason": {"text": "権限外行為の表見代理（民法110条）は、基本代理権が存在し、代理人が権限外の行為をした場合に相手方が代理権ありと信じ、かつそう信じることに正当な理由がある場合に成立します。本人は責任を免れません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "Bが権限外の行為をしたのでAは一切責任を負わない", "reason": "表見代理（民法110条）が成立すれば、本人Aは権限外行為についても責任を負います。「一切責任を負わない」は誤りです。", "caution": "権限外でも表見代理が成立すれば本人の責任あり。"}, {"label": "Cは善意であればBに対してのみ責任追及できる", "reason": "表見代理が成立する場合、Cは本人Aに対して契約の履行を求めることができます。Bへの請求のみに限定されません。", "caution": ""}, {"label": "表見代理と無権代理の責任追及は必ずどちらかを選択しなければならない", "reason": "相手方は表見代理による本人への責任追及と無権代理人への責任追及（民法117条）を選択できます。どちらかに強制されるわけではありません。", "caution": ""}], "summary": {"head": ["表見代理の種類", "要件"], "rows": [["代理権授与表示（民法109条）", "本人が代理権を与えた旨の表示"], ["権限外行為（民法110条）", "基本代理権あり＋相手方の正当な信頼"], ["代理権消滅後（民法112条）", "消滅前の代理権あり＋相手方の善意無過失"]]}}},
  {id:10335,unit:'r_jiko',level:3,field:'rights',text:'取得時効の成立要件について。Aが他人の土地を占有する場合、20年ではなく10年の時効取得が認められる要件として正しいものはどれか。',opts:['単に10年間占有を継続すれば足りる','占有開始時に善意かつ無過失であること','占有開始時に登記名義があること','占有の途中で善意になれば足りる'],ans:1,exp:`所有権の10年の取得時効（民法162条2項）は占有開始時に善意かつ無過失であることが必要です。占有の途中で善意になっても10年時効の適用はありません。無過失の判断は占有開始時を基準とします（判例）。`,"kaisetsu":{"topic": "消滅時効：知った時から5年または行使可能時から10年", "basis": {"text": "消滅時効は「知った時から5年」または「行使可能時から10年」のいずれか早い方で完成します（民法166条）。時効は援用して初めて効力が発生します（民法145条）。承認は更新事由です（民法152条）。", "example": ""}, "reason": {"text": "取得時効は原則20年ですが（民法162条2項）、占有開始時に善意かつ無過失の場合は10年に短縮されます（民法162条1項）。善意無過失とは自己に所有権があると信じ、かつそう信じることに過失がないことです。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">期間</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人身損害</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年または20年</text></svg>", "choices": [{"label": "単に10年間占有を継続すれば足りる", "reason": "10年の短期取得時効には占有開始時の善意・無過失が要件です（民法162条1項）。単なる占有継続だけでは20年の時効が適用されます。", "caution": "10年時効＝善意・無過失が必要。20年時効＝悪意・有過失でも可。"}, {"label": "占有開始時に登記名義があること", "reason": "登記名義の有無は取得時効の要件ではありません（民法162条）。善意・無過失が要件です。", "caution": ""}, {"label": "占有の途中で善意になれば足りる", "reason": "善意・無過失の要件は占有開始時の状態で判断します（民法162条1項）。途中で善意になっても10年時効は適用されません。", "caution": "善意・無過失の判断時期は「占有開始時」です。"}], "summary": {"head": ["取得時効の種類", "期間", "要件"], "rows": [["短期取得時効", "10年", "占有開始時に善意・無過失（民法162条1項）"], ["長期取得時効", "20年", "善意・悪意・有無過失を問わず（民法162条2項）"]]}}},
  {id:10336,unit:'r_bukken',level:3,field:'rights',text:'共有物の分割請求について正しいものはどれか。',opts:['共有者は持分の多寡に関係なく分割請求できる','共有者は他の全員の同意がなければ分割請求できない','共有物分割禁止特約は最長5年間のみ有効','不分割特約は登記できないので第三者には対抗できない'],ans:0,exp:`各共有者はいつでも共有物の分割を請求できます（民法256条1項）。ただし5年以内の期間を定めた分割禁止の特約は有効で（同条1項但書）、登記することで第三者にも対抗できます（民法不動産登記法59条6号）。持分の大小は分割請求権に影響しません。`,"kaisetsu":{"topic": "物権変動：登記が対抗要件・不法占拠者には登記不要", "basis": {"text": "不動産の物権変動は登記が第三者への対抗要件です（民法177条）。不法占拠者には登記なく対抗できます（判例）。建物賃借権は引渡しが対抗要件です（借地借家法31条）。", "example": ""}, "reason": {"text": "共有者は各自が分割請求権を持ちます（民法256条1項）。持分割合に関係なく分割を求められるのは、共有関係が経済的停滞を招く場合に解消できるようにするためです。ただし不分割特約で5年以内なら分割を禁止できます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">物権変動の対抗要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対抗要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">二重譲渡</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先に登記した者が優先</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不法占拠者</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記不要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物賃借権</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡し</text></svg>", "choices": [{"label": "共有者は他の全員の同意がなければ分割請求できない", "reason": "分割請求は各共有者が単独でできます（民法256条1項）。全員の同意は不要です。変更行為との混同に注意してください。", "caution": "分割請求＝単独でできる。変更行為（全員同意必要）と混同しないこと。"}, {"label": "共有物分割禁止特約は最長5年間のみ有効", "reason": "不分割特約の有効期間は5年以内で、更新（5年を超えない範囲）もできます（民法256条1項ただし書）。「最長5年のみで更新不可」は誤りです。", "caution": ""}, {"label": "不分割特約は登記できないので第三者には対抗できない", "reason": "不分割特約は登記することで第三者に対抗できます（不動産登記法59条6号）。登記できないというのは誤りです。", "caution": ""}], "summary": {"head": ["共有物に関する行為", "必要な同意"], "rows": [["保存行為", "各共有者が単独で可"], ["管理行為（利用・改良）", "持分の過半数"], ["変更行為（処分・重大変更）", "全員の同意"], ["分割請求", "各共有者が単独で可（不分割特約で制限可）"]]}}},
  {id:10337,unit:'r_touki',level:3,field:'rights',text:'仮登記の効力として正しいものはどれか。',opts:['仮登記は本登記と同じく対抗力を持つ','仮登記を本登記に改めると仮登記後の中間処分の登記は抹消される','仮登記は担保としての効力のみを持つ','仮登記は抵当権の設定には利用できない'],ans:1,exp:`仮登記に基づく本登記がなされると、仮登記後に行われた第三者の権利に関する登記は抹消されます（不動産登記法109条）。これが仮登記の順位保全効です。仮登記自体は対抗力がなく、担保仮登記（仮登記担保）もあります（仮登記担保法）。`,"kaisetsu":{"topic": "不動産登記：権利登記は共同申請・仮登記は順位保全・建物滅失は1か月以内", "basis": {"text": "権利に関する登記は原則として登記権利者と登記義務者が共同申請します（不動産登記法60条）。仮登記は順位保全機能があるが完全な対抗力は本登記後です。建物滅失登記の申請義務は1か月以内（同法57条）。", "example": ""}, "reason": {"text": "仮登記を本登記に改めると、仮登記後に行われた中間処分の登記（仮登記後に設定された抵当権等）は登記官が職権で抹消します（不動産登記法109条）。これが仮登記の順位保全効の実質的な意味です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産登記のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利登記</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則として共同申請</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮登記</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">順位保全（対抗力は本登記後）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物滅失登記</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1か月以内</text></svg>", "choices": [{"label": "仮登記は本登記と同じく対抗力を持つ", "reason": "仮登記単独では対抗力を持ちません。本登記後に仮登記の順位で対抗力が生じます。", "caution": "仮登記＝順位保全のみ（対抗力なし）。"}, {"label": "仮登記は担保としての効力のみを持つ", "reason": "仮登記は担保目的（仮登記担保）にも使われますが、本来は順位保全が主たる機能です。", "caution": ""}, {"label": "仮登記は抵当権の設定には利用できない", "reason": "抵当権設定の仮登記（2号仮登記）も可能です（不動産登記法105条2号）。", "caution": ""}], "summary": {"head": ["仮登記後の手続き", "効果"], "rows": [["本登記への移行", "仮登記の順位で本登記の効力発生"], ["中間処分の扱い", "仮登記後の登記は職権で抹消（不動産登記法109条）"], ["仮登記の抹消", "仮登記名義人の単独申請または双方申請で可能"]]}}},
  {id:10338,unit:'r_chinshaku',level:3,field:'rights',text:'借地権の対抗要件として正しいものはどれか。',opts:['借地契約の公正証書のみが対抗要件','地上権・土地賃借権の登記のほか、借地上の建物の登記でも対抗できる','借地権は登記なしで当然に対抗できる','建物の未登記では借地権の対抗要件にならない'],ans:1,exp:`借地権は地上権・賃借権の登記のほか、借地上に建物の登記（表示登記でも可）があれば第三者に対抗できます（借地借家法10条1項）。建物の未登記の場合は建物の登記がないため対抗力を失います（滅失した場合は掲示で2年間保護）。`,"kaisetsu":{"topic": "賃貸借：通常損耗は原状回復に含まれない・有益費は終了時に請求・賃料増額は正当事由が必要", "basis": {"text": "賃貸借終了時の原状回復義務に通常使用による損耗（壁の日焼け等）は含まれません（民法621条）。必要費は直ちに、有益費は終了時の請求が原則。更新拒絶には正当事由が必要（借地借家法28条）。", "example": ""}, "reason": {"text": "借地権（借地借家法上）の対抗要件は①借地権（地上権・賃借権）の登記、または②借地上の建物の登記です（借地借家法10条1項）。建物が未登記でも借地権の登記があれば対抗できますが、実務では建物登記が多く利用されます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">賃貸借のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通常損耗</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原状回復に含まれない</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要費</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直ちに請求可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有益費</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸借終了時に請求</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">更新拒絶</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当事由が必要</text></svg>", "choices": [{"label": "借地契約の公正証書のみが対抗要件", "reason": "公正証書は対抗要件ではありません。借地権の登記または借地上建物の登記が対抗要件です（借地借家法10条1項）。", "caution": ""}, {"label": "借地権は登記なしで当然に対抗できる", "reason": "借地権も対抗要件（借地権の登記または建物の登記）が必要です（借地借家法10条1項）。当然に対抗できるわけではありません。", "caution": ""}, {"label": "建物の未登記では借地権の対抗要件にならない", "reason": "建物が未登記でも借地権の登記があれば対抗できます。また建物が登記されていれば借地権も対抗できます（借地借家法10条1項）。", "caution": ""}], "summary": {"head": ["借地権の対抗要件", "内容"], "rows": [["方法①", "借地権（地上権・賃借権）の登記"], ["方法②", "借地上に建物が存在しその建物が登記されていること（借地借家法10条1項）"], ["建物賃借権の対抗要件", "引渡し（借地借家法31条）"]]}}},
  {id:10339,unit:'r_baibai',level:3,field:'rights',text:'売買契約における危険負担について（2020年改正後）。契約締結後引渡し前に目的物が双方の責めに帰することができない事由で滅失した場合の処理として正しいものはどれか。',opts:['買主は代金全額を支払わなければならない','買主は売主に対し契約の解除ができる','危険は常に買主が負担する（買主主義）','滅失した場合も売主は代金請求できるが買主は損害賠償できる'],ans:1,exp:`2020年改正民法536条により危険負担は「債務者主義」が原則となりました。引渡し前に双方の帰責なく滅失した場合、買主は売主の反対給付（代金支払い）の履行を拒絶でき、また契約を解除することもできます（民法542条）。`,"kaisetsu":{"topic": "売買：同時履行の抗弁権・解除は原則催告が必要・契約不適合責任", "basis": {"text": "売買では代金と引渡しは同時履行の関係（民法533条）。解除は原則として相当の期間を定めた催告後に行います（民法541条）。契約不適合責任の通知は知った時から1年以内（民法566条）。", "example": ""}, "reason": {"text": "2020年改正後の危険負担は、目的物が滅失しても反対給付義務が自動消滅せず、買主は履行拒絶権を持ちます（民法536条1項）。また目的物滅失を理由に解除もできます（民法542条1項1号）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">売買のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">同時履行</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金と引渡しは同時履行</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則として催告が必要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">契約不適合の通知</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から1年以内</text></svg>", "choices": [{"label": "買主は代金全額を支払わなければならない", "reason": "目的物が滅失した場合、買主は反対給付（代金支払い）を拒絶できます（民法536条1項）。全額支払い義務はありません。", "caution": ""}, {"label": "危険は常に買主が負担する（買主主義）", "reason": "改正前は買主危険負担主義でしたが、改正後は「履行拒絶権」が認められており実質的に売主が危険を負担します（民法536条1項）。", "caution": "2020年改正前：買主危険負担主義。改正後：実質的に売主負担（買主の履行拒絶権）。"}, {"label": "滅失した場合も売主は代金請求できるが買主は損害賠償できる", "reason": "売主に帰責事由がなければ買主は損害賠償請求できません（民法415条）。また買主は代金支払いを拒絶できます（民法536条1項）。", "caution": ""}], "summary": {"head": ["引渡し前の滅失（危険負担）", "改正前", "改正後"], "rows": [["買主の義務", "代金全額支払い（買主主義）", "履行拒絶権・解除が可能"], ["売主の義務", "なし", "追完不能→解除・返金義務"], ["根拠", "旧民法534条", "民法536条・542条"]]}}},
  {id:10340,unit:'r_souzoku',level:3,field:'rights',text:'相続の放棄について正しいものはどれか。',opts:['相続放棄は相続開始前に行うことができる','相続放棄をした者は初めから相続人でなかったとみなされる','相続放棄は家庭裁判所への申述ではなく口頭でもできる','相続放棄をした者も固定資産税を支払う義務がある'],ans:1,exp:`相続放棄（民法938条）は家庭裁判所への申述により行い、申述が受理されると初めから相続人でなかったとみなされます（民法939条）。相続開始前の放棄は認められず、申述は相続開始を知った日から3ヶ月以内に行わなければなりません（民法915条）。`,"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2・遺産分割は全員合意", "basis": {"text": "配偶者と子は各1/2（民法900条）。放棄は3か月以内に家裁へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2（民法1042条）。兄弟姉妹に遺留分はなし。遺産分割協議は全員合意が必要。", "example": ""}, "reason": {"text": "相続放棄をした者は初めから相続人でなかったとみなされます（民法939条）。そのため相続財産に対して何の権利も義務も負いません。ただし放棄は家庭裁判所への申述が必要です（民法938条）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "相続放棄は相続開始前に行うことができる", "reason": "相続放棄は相続開始後（熟慮期間内）に行います（民法938条・915条）。開始前の放棄は認められません（民法915条1項）。", "caution": "放棄は相続開始後のみ可。事前放棄は無効。"}, {"label": "相続放棄は家庭裁判所への申述ではなく口頭でもできる", "reason": "相続放棄は家庭裁判所への申述が必要です（民法938条）。口頭では効力が生じません。", "caution": "相続放棄は家庭裁判所への申述が必要。"}, {"label": "相続放棄をした者も固定資産税を支払う義務がある", "reason": "相続放棄をした者は初めから相続人でなかったとみなされるため（民法939条）、固定資産税の支払義務も負いません。", "caution": ""}], "summary": {"head": ["相続放棄", "内容"], "rows": [["方式", "家庭裁判所への申述（民法938条）"], ["期間", "熟慮期間3か月以内"], ["効果", "初めから相続人でなかったとみなす（民法939条）"], ["事前放棄", "無効"], ["口頭放棄", "無効"]]}}},
  {id:10341,unit:'r_fuhoko',level:3,field:'rights',text:'共同不法行為者間の責任に関して正しいものはどれか。',opts:['各自が被害者に対して分担分のみ責任を負う','各共同不法行為者は損害の全額について連帯して賠償責任を負う','過失割合に応じた部分のみの責任を負う','共同不法行為は故意によるものに限られる'],ans:1,exp:`共同不法行為者（民法719条）は被害者に対して損害の全額について連帯して損害賠償責任を負います（不真正連帯債務）。各人の求償関係（内部関係）は過失割合等に基づきます。共同不法行為は故意・過失いずれの場合でも成立します。`,"kaisetsu":{"topic": "不法行為：故意または過失が必要・使用者責任・工作物責任", "basis": {"text": "不法行為は故意または過失が必要です（民法709条）。使用者は被用者の職務上の不法行為について責任を負います（民法715条）。工作物の所有者は無過失責任（占有者が免責された場合）（民法717条）。", "example": ""}, "reason": {"text": "共同不法行為者は損害の全額について連帯して賠償責任を負います（民法719条1項）。これにより被害者は複数の加害者のうちの一人に対して全額請求できます。内部的な求償は後で行われます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不法行為のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般不法行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">故意または過失が必要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">使用者責任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">被用者への求償可（信義則上制限）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">工作物の所有者責任</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無過失責任（占有者が免責された場合）</text></svg>", "choices": [{"label": "各自が被害者に対して分担分のみ責任を負う", "reason": "共同不法行為者は連帯して全額の責任を負います（民法719条1項）。分担分のみではありません。", "caution": "共同不法行為＝連帯責任（全額）。分割責任ではありません。"}, {"label": "過失割合に応じた部分のみの責任を負う", "reason": "外部的には全額の連帯責任です（民法719条1項）。過失割合は内部的な求償の際に問題になります。", "caution": ""}, {"label": "共同不法行為は故意によるものに限られる", "reason": "共同不法行為は過失による場合も成立します（民法719条1項）。故意のみに限定されません。", "caution": ""}], "summary": {"head": ["共同不法行為（民法719条）", "内容"], "rows": [["外部的責任", "各自が全額について連帯責任"], ["被害者の選択", "任意の加害者に全額請求可"], ["内部的求償", "過失割合等に応じて他の加害者に求償可"], ["連帯の性質", "不真正連帯債務（絶対効が限定的）"]]}}},
  {id:10342,unit:'r_tanpo',level:3,field:'rights',text:'抵当権侵害に対する抵当権者の救済手段として正しいものはどれか。',opts:['抵当権者は占有していないため物権的請求権を行使できない','抵当権者は被担保債権の弁済期前でも物権的妨害排除請求権を行使できる場合がある','抵当権侵害に対しては損害賠償請求のみが認められる','抵当権者が建物に侵入した第三者を排除するには必ず裁判所の許可が必要'],ans:1,exp:`抵当権者は抵当目的物の交換価値の実現が妨害されている場合（例：不法占拠により競売価格が下落するなど）に物権的妨害排除請求権を行使できます（最高裁判例）。弁済期前でも侵害が明白であれば認められる場合があります。`,"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権（民法369条）。質権は占有の移転が必要。先取特権は法定担保物権（当然に成立）。農地への抵当権設定自体は、通常、農地法3条の許可対象ではありません。", "example": ""}, "reason": {"text": "抵当権者は目的物を占有しませんが、抵当権の価値維持のために物権的妨害排除請求権を行使できます（判例）。抵当権の価値が著しく侵害されるおそれがある場合、弁済期前でも請求できるとした判例があります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "抵当権者は占有していないため物権的請求権を行使できない", "reason": "抵当権者は占有していなくても物権的妨害排除請求権を行使できます（判例・民法373条）。", "caution": "占有なくても抵当権者は妨害排除請求可（判例）。"}, {"label": "抵当権侵害に対しては損害賠償請求のみが認められる", "reason": "物権的妨害排除請求権と損害賠償請求の両方が認められます（判例・民法709条）。", "caution": ""}, {"label": "建物に侵入した第三者を排除するには必ず裁判所の許可が必要", "reason": "民事保全（仮処分）等の手続きを利用することが通常ですが、「必ず裁判所の許可が必要」という絶対的な要件はありません。", "caution": ""}], "summary": {"head": ["抵当権侵害への対応", "内容"], "rows": [["物権的妨害排除請求", "占有なしでも可（判例）"], ["損害賠償請求", "不法行為に基づく（民法709条）"], ["物上代位", "賃料等への優先弁済権行使（民法304条）"], ["競売申立て", "被担保債権の期限の利益喪失後"]]}}},
  {id:10343,unit:'l_menkyo',level:3,field:'law',text:'宅建業者の廃業等に関する届出義務について正しいものはどれか。',opts:['廃業の場合は30日以内に届け出なければならない','死亡の場合は相続人が知った日から30日以内に届け出なければならない','法人が合併により消滅した場合は消滅前に届け出る','廃業等の届出は任意であり義務ではない'],ans:1,exp:`宅建業者（個人）が死亡した場合、その相続人は死亡の事実を知った日から30日以内に届け出なければなりません（宅建業法11条1項1号）。廃業・解散等も同様に30日以内の届出が必要です。`,"kaisetsu":{"topic": "宅建業免許：知事・大臣免許の区別・有効期間5年・欠格事由は5年", "basis": {"text": "1都道府県→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間。2020年改正で成年被後見人の欠格条項は廃止。", "example": ""}, "reason": {"text": "宅建業者が死亡した場合、相続人が死亡を知った日から30日以内に届け出なければなりません（宅建業法11条1項1号）。「死亡した日から30日以内」ではなく「知った日から30日以内」である点が重要です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（2020年改正で成年被後見人は廃止）</text></svg>", "choices": [{"label": "廃業の場合は30日以内に届け出なければならない", "reason": "廃業の届出も30日以内です（宅建業法11条1項5号）。この選択肢の内容は正しいですが、設問の正解は死亡に関する選択肢2です。", "caution": ""}, {"label": "法人が合併により消滅した場合は消滅前に届け出る", "reason": "合併による消滅の届出は消滅してから30日以内です（宅建業法11条1項3号）。消滅前ではありません。", "caution": ""}, {"label": "廃業等の届出は任意であり義務ではない", "reason": "廃業等の届出は義務です（宅建業法11条）。任意ではありません。", "caution": ""}], "summary": {"head": ["死亡の届出", "内容"], "rows": [["届出者", "相続人"], ["期限", "死亡を知った日から30日以内（宅建業法11条1項1号）"], ["届出先", "免許権者（知事または大臣）"], ["死亡後の扱い", "免許は相続されないが、既存取引の結了目的で宅建業者とみなされる"]]}}},
  {id:10344,unit:'l_takkenshi',level:3,field:'law',text:'宅建士による重要事項説明の義務に関して正しいものはどれか。',opts:['説明の相手方が宅建業者の場合も省略できない','宅建業者間の取引では説明義務は省略できるが書面の交付義務は残る','宅建業者間の取引では説明も書面交付も省略できる','書面交付さえすれば説明は不要'],ans:1,exp:`宅建業者間の取引では重要事項の説明（宅建士による口頭説明）は省略できますが、35条書面（重要事項説明書）の交付義務は残ります（宅建業法35条6項）。つまり「説明なし・書面交付あり」が正しい取扱いです。`,"kaisetsu":{"topic": "専任宅建士：5人に1人以上・兼任不可・2週間以内に補充", "basis": {"text": "事務所には業務従事者5人に1人以上の専任宅建士が必要（宅建業法31条の3）。1社専属で複数業者の兼任は不可。不足時は2週間以内に補充が必要。案内所（申込み受付）にも専任宅建士が必要。", "example": ""}, "reason": {"text": "重要事項説明は買主・借主が宅建業者の場合に省略できますが（宅建業法35条6項）、35条書面（重要事項説明書）の交付義務は残ります（同条同項）。宅建業者間でも書面交付は必要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">専任宅建士のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">設置基準</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5人に1人以上</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">兼任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可（1社専属）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不足補充</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間以内</text></svg>", "choices": [{"label": "説明の相手方が宅建業者の場合も省略できない", "reason": "宅建業者間の取引では説明（口頭での説明）は省略できます（宅建業法35条6項）。「省略できない」は誤りです。", "caution": "宅建業者間取引：説明は省略可、書面交付は省略不可（宅建業法35条6項）。"}, {"label": "宅建業者間の取引では説明も書面交付も省略できる", "reason": "書面交付は省略できません（宅建業法35条6項）。説明のみ省略可能です。", "caution": ""}, {"label": "書面交付さえすれば説明は不要", "reason": "書面交付のみでよいのは宅建業者間取引の場合です（宅建業法35条6項）。一般の取引では説明が必要です（同条1項）。", "caution": ""}], "summary": {"head": ["重要事項説明と宅建業者間取引（宅建業法35条6項）", "内容"], "rows": [["説明（口頭）", "省略可"], ["書面（35条書面）の交付", "省略不可"], ["宅建士証の提示", "宅建業者間でも必要か→省略の規定なし"], ["一般取引", "説明＋書面交付ともに必要"]]}}},
  {id:10345,unit:'l_baikai',level:3,field:'law',text:'媒介契約書面（34条の2書面）の記載事項として必要なものはどれか。',opts:['媒介報酬額の支払時期','物件価格または評価額','依頼者の資産状況','依頼者の購入候補地の詳細'],ans:1,exp:`媒介契約書面（宅建業法34条の2）の記載事項には物件の所在・規模・価格、媒介の種類、有効期間、解除に関する事項、報酬に関する事項、指定流通機構への登録に関する事項等が含まれます。`,"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任の有効期間は最長3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。レインズ登録は専任7日以内・専属専任5日以内。業務報告は専任2週間に1回・専属専任1週間に1回。", "example": ""}, "reason": {"text": "34条の2書面（媒介契約書）の必須記載事項の一つは物件の価格または評価額です（宅建業法34条の2第1項2号）。報酬支払時期・依頼者の資産状況・候補地の詳細は必須記載事項ではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">自己発見</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">レインズ</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専任</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専属専任</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text></svg>", "choices": [{"label": "媒介報酬額の支払時期", "reason": "報酬の支払時期は34条の2書面の必須記載事項ではありません（宅建業法34条の2第1項）。報酬額は記載が必要です（同条1項8号）。", "caution": ""}, {"label": "依頼者の資産状況", "reason": "依頼者の資産状況は34条の2書面の記載事項ではありません（宅建業法34条の2第1項）。", "caution": ""}, {"label": "依頼者の購入候補地の詳細", "reason": "購入候補地の詳細は34条の2書面の記載事項ではありません（宅建業法34条の2第1項）。", "caution": ""}], "summary": {"head": ["34条の2書面の必須記載事項（宅建業法34条の2第1項）", "内容"], "rows": [["物件の特定", "所在・面積等"], ["価格または評価額", "売買すべき価額"], ["媒介契約の種類", "一般・専任・専属専任の別"], ["有効期間・更新", "期間と更新方法"], ["報酬額", "報酬の額と計算方法"]]}}},
  {id:10346,unit:'l_hoshu',level:3,field:'law',text:'1つの売買について売主・買主双方から媒介を依頼された宅建業者が受領できる報酬の合計の上限として正しいものはどれか。',opts:['売買代金の3%＋6万円（税別）','売買代金の6%＋12万円（税別）','売主・買主それぞれから3%＋6万円（税別）なので合計6%＋12万円','売主・買主どちらか一方からの報酬のみ'],ans:2,exp:`売主・買主双方から依頼を受けた場合（双方代理的媒介）、それぞれから受け取れる上限額（各側3%＋6万円等）を合計した額が上限となります（報酬告示）。つまり売買代金×6%＋12万円（税別）が合計の上限です。`,"kaisetsu":{"topic": "報酬：売買は代金×3%+6万（400万超）・賃貸は借賃1か月・上限超過は不可", "basis": {"text": "売買（400万超）の一方からの上限は代金×3%+6万。双方合計は一方上限×2。賃貸（居住用・非居住用とも）は借賃1か月分。低廉な空家等（800万円以下）は、媒介報酬について原則の報酬額を超えて30万円（税別）まで受領できる場合があります（依頼者への説明・合意が必要）。", "example": ""}, "reason": {"text": "一つの売買について売主・買主双方から媒介を依頼された業者が受領できる合計上限は、一方からの上限（代金×3%＋6万円）×2＝代金×6%＋12万円（税別）です（告示）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対象</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（400万超）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万（一方）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（200万以下）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸（双方合計）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借賃1か月分</text></svg>", "choices": [{"label": "売買代金の3%＋6万円（税別）", "reason": "3%＋6万円は一方の依頼者からの上限です（告示）。双方合計は最大6%＋12万円です。", "caution": "一方から：3%＋6万円。双方合計：6%＋12万円（告示）。"}, {"label": "売買代金の6%＋12万円（税別）", "reason": "双方合計の上限は6%＋12万円が正しいですが（告示）、これは選択肢3と実質同じ内容です。設問の正解は選択肢3が「それぞれから3%＋6万円、合計6%＋12万円」という正確な説明です。", "caution": ""}, {"label": "売主・買主どちらか一方からの報酬のみ", "reason": "双方から報酬を受け取れます（告示）。一方からのみという制限はありません。", "caution": ""}], "summary": {"head": ["双方媒介の報酬（告示）", "計算"], "rows": [["一方の上限", "代金×3%＋6万円（税別）"], ["双方合計の上限", "代金×6%＋12万円（税別）"], ["消費税", "別途加算"], ["例：4000万円", "一方126万円・双方252万円（税別）"]]}}},
  {id:10347,unit:'l_37jo',level:3,field:'law',text:'37条書面の作成・交付に関して正しいものはどれか。',opts:['37条書面の記名押印は代表者が行えばよい','37条書面は宅建士が記名しなければならない（電磁的方法の場合は省令で定める措置）','37条書面は契約当事者のうち買主にのみ交付すれば足りる','37条書面は重要事項説明書と同時に交付しなければならない'],ans:1,exp:`37条書面（契約書面）は宅建士が記名しなければなりません（電磁的方法の場合は国土交通省令で定める措置が必要）（宅建業法37条3項）。売主・買主の双方に交付する必要があり、交付のタイミングは契約成立後遅滞なくです。重説との同時交付義務はありません。`,"kaisetsu":{"topic": "37条書面：全取引で交付・記名（押印不要）・移転登記申請時期は必要的記載事項", "basis": {"text": "37条書面は全取引で契約の双方当事者に交付が義務（宅建業法37条）。引渡し時期・移転登記申請時期は必要的記載事項。2021年改正で押印は不要、記名のみで足ります。", "example": ""}, "reason": {"text": "37条書面は宅建士が記名（押印は2022年改正で不要）しなければなりません（宅建業法37条3項）。電磁的方法で提供する場合は国土交通省令で定める措置が必要です。契約後に売主・買主の双方に交付します（同条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付義務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全取引・双方当事者</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡時期・移転登記申請時期等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要）</text></svg>", "choices": [{"label": "37条書面の記名押印は代表者が行えばよい", "reason": "37条書面の記名は宅建士が行います（宅建業法37条3項）。代表者でも宅建士でなければ不可です。", "caution": "37条書面の記名：宅建士（宅建業法37条3項）。"}, {"label": "37条書面は契約当事者のうち買主にのみ交付すれば足りる", "reason": "37条書面は売主・買主の双方に交付しなければなりません（宅建業法37条1項）。買主のみでは不足です。", "caution": ""}, {"label": "37条書面は重要事項説明書と同時に交付しなければならない", "reason": "35条書面（重要事項説明書）は契約前に交付し、37条書面は契約後に遅滞なく交付します（宅建業法35条1項・37条1項）。同時交付は義務ではありません。", "caution": ""}], "summary": {"head": ["37条書面の作成・交付", "内容"], "rows": [["記名", "宅建士（押印は不要・2022年改正）"], ["交付時期", "契約締結後、遅滞なく"], ["交付先", "売主・買主の双方（賃貸は双方）"], ["電磁的記録", "相手方の承諾＋宅建士の電子署名"]]}}},
  {id:10348,unit:'l_jusetsu',level:3,field:'law',text:'区分所有建物（マンション）の売買における重要事項説明の特有記載事項として正しいものはどれか。',opts:['マンションには特別な記載事項はない','管理組合の総会議事録・管理規約・修繕積立金の状況等','隣接する土地所有者の情報','マンション全体の固定資産税評価額'],ans:1,exp:`区分所有建物の売買では通常の重説事項に加え、管理規約・総会議事録・長期修繕計画・修繕積立金の状況・管理会社の名称等を説明・記載する必要があります（宅建業法35条1項6号等）。`,"kaisetsu":{"topic": "重要事項説明：宅建士が説明・買主への交付・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主（貸主）は不要。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能。", "example": ""}, "reason": {"text": "区分所有建物（マンション）の売買では、管理規約・総会議事録・修繕積立金の状況等の区分所有特有の事項を説明しなければなりません（宅建業法35条1項6号・同施行令3条の2等）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士のみ（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "マンションには特別な記載事項はない", "reason": "マンション（区分所有建物）には通常の売買より多くの特有記載事項があります（宅建業法35条1項6号等）。", "caution": ""}, {"label": "隣接する土地所有者の情報", "reason": "隣接地の所有者情報は重要事項説明の記載事項ではありません（宅建業法35条1項）。", "caution": ""}, {"label": "マンション全体の固定資産税評価額", "reason": "固定資産税評価額は重要事項説明の必須記載事項ではありません（宅建業法35条1項）。", "caution": ""}], "summary": {"head": ["マンション売買の特有記載事項", "内容"], "rows": [["管理規約", "規約の概要"], ["管理組合総会議事録", "直近のもの（3年分等）"], ["修繕積立金", "月額・積立残高"], ["大規模修繕", "実施状況・計画"], ["管理委託", "管理会社名・委託内容"]]}}},
  {id:10349,unit:'l_hosho',level:3,field:'law',text:'宅建業者が自ら売主となる場合の手付金等保全措置について。完成物件において保全措置が不要となる要件として正しいものはどれか。',opts:['手付金等が代金の10%以下かつ1000万円以下','手付金等が代金の5%以下かつ500万円以下','手付金等が代金の20%以下かつ2000万円以下','保全措置は常に必要'],ans:0,exp:`完成物件の場合、受領する手付金等の額が代金の10%以下かつ1000万円以下であれば保全措置は不要です（宅建業法41条の2）。未完成物件は5%以下かつ1000万円以下が基準です。`,"kaisetsu":{"topic": "営業保証金・保証協会：主1,000万・従500万/営業保証金vs分担金60万・30万", "basis": {"text": "営業保証金は主1,000万・従500万（宅建業法25条）。保証協会の分担金は主60万・従30万（同法64条の9）。還付対象は業者以外の取引した者。加入は任意。不足補充は通知後2週間以内。", "example": ""}, "reason": {"text": "宅建業者が自ら売主として完成物件の手付金等を受領する場合、代金の10%以下かつ1000万円以下であれば保全措置なしに受領できます（宅建業法41条の2第1項）。超える場合は保全措置が必要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">営業保証金と弁済業務保証金</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">営業保証金</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">弁済業務保証金（分担金）</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">主たる事務所</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000万円</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">60万円</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従たる事務所/所</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">500万円</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">還付対象</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者以外</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者以外</text></svg>", "choices": [{"label": "手付金等が代金の5%以下かつ500万円以下", "reason": "完成物件の保全措置不要の閾値は10%以下かつ1000万円以下です（宅建業法41条の2第1項）。5%・500万円は誤りです。", "caution": "完成物件：10%以下かつ1000万円以下なら保全措置不要。"}, {"label": "手付金等が代金の20%以下かつ2000万円以下", "reason": "20%は手付金の上限（宅建業法39条）です。保全措置の閾値は10%以下かつ1000万円以下です（同法41条の2第1項）。", "caution": ""}, {"label": "保全措置は常に必要", "reason": "代金の10%以下かつ1000万円以下の場合は保全措置なしに受領できます（宅建業法41条の2第1項）。「常に必要」は誤りです。", "caution": ""}], "summary": {"head": ["手付金等の保全措置（宅建業者自ら売主）", "基準"], "rows": [["未完成物件", "5%超または1000万円超→保全措置必要"], ["完成物件", "10%超または1000万円超→保全措置必要"], ["保全措置の方法", "銀行等の保証・保証保険等"]]}}},
  {id:10350,unit:'l_cooling',level:3,field:'law',text:'クーリングオフの書面に必要な記載事項として正しいものはどれか。',opts:['クーリングオフができる旨およびその方法を宅建業者が書面で告知しなければならない','クーリングオフの告知は口頭でも有効','告知書面の交付は買主が申し出なければ不要','告知書面の交付義務は媒介業者にはない'],ans:0,exp:`宅建業者は買主等に対してクーリングオフができる旨・クーリングオフを行使する場合の方法を書面で告知しなければなりません（宅建業法37条の2第1項）。告知がなければ8日の起算が始まらず、買主はいつでもクーリングオフできます。`,"kaisetsu":{"topic": "クーリングオフ：告知日から8日以内・書面で・事務所では不可・全額返還", "basis": {"text": "クーリングオフは告知を受けた日から8日以内に書面で行います（宅建業法37条の2）。事務所・モデルルーム等での申込みはクーリングオフ不可。解除後業者は全額返還（費用控除不可）。", "example": ""}, "reason": {"text": "宅建業者（自ら売主）は、申込みの際または契約締結前に、クーリングオフができる旨およびその方法等を書面で告知しなければなりません（宅建業法37条の2第1項）。この告知がない場合、8日の期間は進行しません（いつでもクーリングオフできる）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">クーリングオフのポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">告知日から8日以内</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">方法</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面（発信主義）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所での申込み</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">クーリングオフ不可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除後</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全額返還</text></svg>", "choices": [{"label": "クーリングオフの告知は口頭でも有効", "reason": "クーリングオフの告知は書面で行わなければなりません（宅建業法37条の2第1項）。口頭では有効な告知となりません。", "caution": "クーリングオフの告知：書面が必要（宅建業法37条の2第1項）。"}, {"label": "告知書面の交付は買主が申し出なければ不要", "reason": "告知は売主業者の義務であり（宅建業法37条の2第1項）、買主の申し出がなくても告知しなければなりません。", "caution": ""}, {"label": "告知書面の交付義務は媒介業者にはない", "reason": "告知義務があるのは自ら売主となる宅建業者です（宅建業法37条の2第1項）。媒介業者には告知義務がないという点は正しいですが、設問の正解は選択肢1（告知の内容に関する記述）です。", "caution": ""}], "summary": {"head": ["クーリングオフの告知義務（宅建業法37条の2第1項）", "内容"], "rows": [["義務者", "自ら売主となる宅建業者"], ["方法", "書面で告知（口頭不可）"], ["時期", "申込みまたは契約締結前"], ["未告知の場合", "8日の期間が進行しない（いつでも行使可）"]]}}},
  {id:10351,unit:'l_kokoku',level:3,field:'law',text:'宅建業法上の取引態様の明示義務について正しいものはどれか。',opts:['取引態様の明示は契約締結時のみ行えば足りる','広告をするときと注文を受けたときに遅滞なく取引態様を明示しなければならない','取引態様は売主・媒介・代理のいずれか一つのみ','取引態様の明示義務は自ら売主の場合のみ'],ans:1,exp:`宅建業者は広告をするときおよび注文を受けたときに、取引態様（自己売主・媒介・代理の別）を明示しなければなりません（宅建業法34条）。明示は注文ごとに遅滞なく行う必要があり、書面でなく口頭でも可です。`,"kaisetsu":{"topic": "宅建業者の広告：開発許可後に広告可・誇大広告は全媒体禁止・取引態様は広告時と注文時両方", "basis": {"text": "開発許可・建築確認後（工事中でも）広告できます（宅建業法33条）。誇大広告禁止は全媒体・全対象者に適用（同法32条）。取引態様は広告時と注文受領時の両方で明示が必要（同法34条）。", "example": ""}, "reason": {"text": "取引態様の明示義務は、広告をするときと注文（申込み）を受けたときの両方に課せられています（宅建業法34条1項・2項）。どちらか一方だけでは義務を果たしたことになりません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">広告規制のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">広告開始時期</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築確認・開発許可後</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誇大広告禁止</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">媒体・対象問わず</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取引態様の明示</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">広告時と注文時の両方</text></svg>", "choices": [{"label": "取引態様の明示は契約締結時のみ行えば足りる", "reason": "広告時と注文受領時の両方で明示が必要です（宅建業法34条1項・2項）。契約締結時のみでは不足です。", "caution": "取引態様の明示：広告時＋注文受領時（宅建業法34条1項・2項）。"}, {"label": "取引態様は売主・媒介・代理のいずれか一つのみ", "reason": "取引態様は売主・媒介・代理の別を明示するものですが、一つの取引に複数の業者が関わる場合はそれぞれが自己の態様を明示します（宅建業法34条）。", "caution": ""}, {"label": "取引態様の明示義務は自ら売主の場合のみ", "reason": "取引態様の明示義務は自ら売主・代理・媒介のすべての場合に課せられます（宅建業法34条1項）。「自ら売主のみ」は誤りです。", "caution": ""}], "summary": {"head": ["取引態様の明示義務（宅建業法34条）", "内容"], "rows": [["明示時期①", "広告をするとき（同条1項）"], ["明示時期②", "注文または申込みを受けたとき（同条2項）"], ["明示内容", "取引の種別（売主・代理・媒介の別）"], ["目的", "相手方が取引の性格を理解できるようにする"]]}}},
  {id:10352,unit:'l_kantoku',level:3,field:'law',text:'宅建業者の免許取消処分事由として正しいものはどれか。',opts:['業務停止処分に違反した場合は必ず免許取消','不正手段により免許を受けた場合','免許を受けてから1年以上業務を開始しない場合は任意取消','指示処分を3回受けると自動的に免許取消'],ans:1,exp:`不正の手段により免許を受けた場合は必要的免許取消事由です（宅建業法66条1項8号）。業務停止処分違反も必要的取消事由（同1号）。免許を受けてから1年以内に業務を開始しない等の場合も取消事由（同2項）ですが、こちらは任意的取消です。`,"kaisetsu":{"topic": "監督処分：業務停止最長1年・大臣は全業者に指示可・指示違反→業務停止", "basis": {"text": "業務停止の最長期間は1年（宅建業法65条2項）。大臣は全業者（知事免許含む）に指示処分を行う権限があります。指示処分違反→業務停止、業務停止違反→免許取消という段階があります。", "example": ""}, "reason": {"text": "不正手段による免許取得は免許の必要的取消し事由です（宅建業法66条1項1号）。業務停止処分違反も必要的取消し事由です（同条1項9号）。免許取消しには必要的取消しと任意的取消しがあります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">監督処分のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">処分</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">最長1年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣の権限</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全業者に指示可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">指示処分違反</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止の対象</text></svg>", "choices": [{"label": "業務停止処分に違反した場合は必ず免許取消", "reason": "業務停止処分違反は必要的取消し事由です（宅建業法66条1項9号）。ただし設問の正解は「不正手段により免許取得」（同条1項1号）です。選択肢1も正しい内容ですが、選択肢2が設問の正解です。", "caution": ""}, {"label": "免許を受けてから1年以上業務を開始しない場合は任意取消", "reason": "免許取得後1年以内に業務を開始しない場合は任意取消の対象です（宅建業法66条2項1号）。1年以上ではなく「1年以内」です。", "caution": ""}, {"label": "指示処分を3回受けると自動的に免許取消", "reason": "指示処分を3回受けると自動的に取り消されるという規定はありません（宅建業法66条）。", "caution": ""}], "summary": {"head": ["免許取消しの種類（宅建業法66条）", "内容"], "rows": [["必要的取消し", "不正手段取得・役員欠格・業務停止違反等（同条1項）"], ["任意的取消し", "1年業務未開始・廃業相当等（同条2項）"]]}}},
  {id:10353,unit:'l_sonota',level:3,field:'law',text:'宅建業者の事務所に置く専任の宅建士の数について正しいものはどれか。',opts:['従業員5人につき1人以上','従業員数に関わらず各事務所に1人いれば足りる','事務所ごとに業務に従事する者5人に1人以上の割合で専任の宅建士を置く','主たる事務所は10人に1人，従たる事務所は5人に1人'],ans:2,exp:`宅建業法では、事務所ごとに業務に従事する者の数の5分の1以上の数の専任の宅建士を置かなければなりません（宅建業法31条の3第1項）。主従の事務所で割合は変わりません。`,"kaisetsu":{"topic": "宅建業者のその他の業務：従業者証明書・帳簿・業務処理原則", "basis": {"text": "全従業者に従業者証明書の交付が必要で業務中は常時携帯（宅建業法48条）。帳簿は事務所ごとに5年保存（自ら売主の新築住宅は10年）（同法49条）。宅建業者は信義誠実の原則に従って業務を行う必要があります（同法31条）。", "example": ""}, "reason": {"text": "事務所ごとに業務に従事する者5名につき1名以上の割合で専任の宅建士を置かなければなりません（宅建業法31条の3第1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業者のその他の義務</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従業者証明書</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全従業者に交付・業務中携帯</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">帳簿</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所ごと・5年保存（新築自ら売主は10年）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務処理原則</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">信義誠実の原則</text></svg>", "choices": [{"label": "従業員5人につき1人以上", "reason": "これは実質正しい内容ですが、設問の正解は選択肢3（「事務所ごとに業務に従事する者5人に1人以上の割合」という正確な表現）です。", "caution": "専任宅建士：業務従事者5名に1名以上（宅建業法31条の3第1項）。"}, {"label": "従業員数に関わらず各事務所に1人いれば足りる", "reason": "業務従事者が6名以上の場合は2名以上の専任宅建士が必要です（宅建業法31条の3第1項：5名に1名以上）。", "caution": ""}, {"label": "主たる事務所は10人に1人，従たる事務所は5人に1人", "reason": "主たる事務所・従たる事務所ともに同じ基準（5名に1名以上）です（宅建業法31条の3第1項）。主従で異なる基準はありません。", "caution": ""}], "summary": {"head": ["専任宅建士の設置（宅建業法31条の3第1項）", "内容"], "rows": [["基準", "業務従事者5名に1名以上"], ["計算例", "5名→1名、6〜10名→2名、11〜15名→3名"], ["欠員時", "2週間以内に補充（宅建業法31条の3第3項）"]]}}},
  {id:10354,unit:'l_baikai',level:3,field:'law',text:'宅建業者が売買の媒介をした場合に売主に交付が義務付けられる「物件状況確認書」について正しいものはどれか。',opts:['物件状況確認書の交付は任意であり義務ではない','売主（宅建業者以外）が物件の状況を告知するための書面で、宅建業者が作成して売主に確認を求める','物件状況確認書は買主のみに交付する','物件状況確認書は35条書面と同じもの'],ans:1,exp:`物件状況確認書（告知書）は売主が物件の状況（雨漏り・シロアリ・設備の不具合等）を告知するための書面です。宅建業者は売主に物件の状況を確認し書面を作成・確認させ、買主に交付することが業界の標準的な取扱いとされています（宅建業法47条の2の観点からも重要）。`,"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任の有効期間は最長3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。レインズ登録は専任7日以内・専属専任5日以内。業務報告は専任2週間に1回・専属専任1週間に1回。", "example": ""}, "reason": {"text": "物件状況確認書（告知書）は売主が物件の状況（雨漏り・給排水の故障・シロアリ被害等）を買主に告知するための書面です。宅建業者が書式を作成し売主が確認・記入します。重要事項説明書（35条書面）とは別の書面です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">自己発見</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">レインズ</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専任</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専属専任</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text></svg>", "choices": [{"label": "物件状況確認書の交付は任意であり義務ではない", "reason": "物件状況確認書の作成・活用は実務上推奨されており（国土交通省標準様式あり）、宅建業者には作成を促す努力義務があります。純粋に任意とは言い切れません。", "caution": ""}, {"label": "物件状況確認書は買主のみに交付する", "reason": "物件状況確認書は売主が記入して業者に提出し、その内容を買主への説明に活用します。買主への交付を含む形で使用されます。", "caution": ""}, {"label": "物件状況確認書は35条書面と同じもの", "reason": "物件状況確認書と35条書面（重要事項説明書）は別々の書面です（宅建業法35条・国土交通省標準様式）。", "caution": ""}], "summary": {"head": ["物件状況確認書（告知書）", "内容"], "rows": [["目的", "売主が物件の状況を買主に告知"], ["作成者", "宅建業者が書式作成・売主が記入"], ["内容", "雨漏り・シロアリ・給排水故障等の有無"], ["35条書面との関係", "別の書面（補完的に使用）"]]}}},
  {id:10355,unit:'k_toshi',level:3,field:'limit',text:'市街化区域と市街化調整区域の区分（線引き）に関して正しいものはどれか。',opts:['すべての都市計画区域で線引きが行われている','線引きは都道府県が都市計画で定めるが、一部の区域では非線引き都市計画区域とすることができる','線引きは市区町村が決定する','市街化調整区域では一切の建築が禁止される'],ans:1,exp:`線引き（市街化区域・市街化調整区域への区分）は都道府県が都市計画で定めますが（都市計画法7条）、全ての都市計画区域で義務付けられているわけではなく、非線引き都市計画区域（区域区分が定められていない区域）も存在します。`,"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域の1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "市街化区域と市街化調整区域の区分（線引き）は都道府県が都市計画で定めますが（都市計画法7条）、すべての都市計画区域で義務的ではありません。大都市圏の特定区域では義務ですが、その他は任意です（非線引き都市計画区域が存在します）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "すべての都市計画区域で線引きが行われている", "reason": "一部の都市計画区域は非線引き（市街化区域・市街化調整区域の区分なし）です（都市計画法7条1項）。「すべて」は誤りです。", "caution": "非線引き都市計画区域：線引きのない都市計画区域（都市計画法7条1項）。"}, {"label": "線引きは市区町村が決定する", "reason": "線引きは都道府県が決定します（都市計画法15条1項）。市区町村ではありません（政令指定都市は例外）。", "caution": ""}, {"label": "市街化調整区域では一切の建築が禁止される", "reason": "市街化調整区域でも農林漁業用施設・公益施設等は建築できます（都市計画法29条・43条）。「一切禁止」は誤りです。", "caution": ""}], "summary": {"head": ["市街化区域・市街化調整区域の線引き", "内容"], "rows": [["義務的線引き", "大都市圏の特定都市計画区域"], ["任意線引き", "その他（任意で線引きする）"], ["非線引き区域", "線引きなし（用途地域の指定は可能）"]]}}},
  {id:10356,unit:'k_kenchiku',level:3,field:'limit',text:'第二種住居地域内で原則として建築できる建築物として正しいものはどれか。',opts:['床面積の合計が1万㎡を超える大規模店舗','単独の風俗営業施設（劇場等）','床面積の合計1万㎡以下の店舗・飲食店・事務所','工場（原動機使用）'],ans:2,exp:`第二種住居地域では床面積の合計が1万㎡以下の店舗・飲食店・事務所等は建築できます（建築基準法別表第二）。1万㎡超の大規模店舗は準住居・近商・商業地域等でなければ建てられません。風俗施設や工場は住居系地域では原則建築できません。`,"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・用途制限・道路斜線", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。防火地域の耐火建築物は隣地境界線に外壁を接して建築可（同法65条）。", "example": ""}, "reason": {"text": "第二種住居地域では床面積1万㎡以下の店舗・飲食店・事務所等が建築できます（建築基準法別表第二）。1万㎡を超える大規模商業施設・風俗施設・工場（原動機使用）は建築できません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">防火地域の耐火建築物</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">隣地境界線に接して建築可</text></svg>", "choices": [{"label": "床面積の合計が1万㎡を超える大規模店舗", "reason": "第二種住居地域では1万㎡を超える店舗は建築できません（建築基準法別表第二）。", "caution": "第二種住居地域：1万㎡以下の店舗等は可（建築基準法別表第二）。"}, {"label": "単独の風俗営業施設（劇場等）", "reason": "劇場等の風俗施設は第二種住居地域では制限があります（建築基準法別表第二）。", "caution": ""}, {"label": "工場（原動機使用）", "reason": "原動機を使用する工場は第二種住居地域では建築できません（建築基準法別表第二）。", "caution": ""}], "summary": {"head": ["第二種住居地域で建築できるもの（建築基準法別表第二）", "内容"], "rows": [["住宅・共同住宅", "制限なし"], ["店舗・飲食店・事務所", "1万㎡以下"], ["1万㎡超の大規模商業施設", "不可"], ["風俗施設・原動機工場", "不可"]]}}},
  {id:10357,unit:'k_nochi',level:3,field:'limit',text:'農地法4条の許可を要しない転用として正しいものはどれか。',opts:['自己所有農地を駐車場にする','農地を農業用倉庫（農業に直接関連する施設）のために転用する','農業用水路の整備のために農地を利用する','2アール未満の農地を農業用施設に転用する場合'],ans:3,exp:`農地法4条の例外として、農業者が2アール未満の農地を農業用施設（農業倉庫・ビニールハウス等）に転用する場合は許可不要です（農地法4条1項8号・農地法施行令2条1項1号）。農業用水路等の土地改良施設への転用も許可不要の場合があります。`,"kaisetsu":{"topic": "農地法：3条は農業委員会・4・5条は都道府県知事・市街化区域は届出のみ", "basis": {"text": "農地法3条の許可権者は農業委員会。4・5条は都道府県知事等。市街化区域の農地転用（4・5条）は農業委員会への届出のみOK。相続は許可不要・3か月以内の農業委員会への届出が必要。", "example": ""}, "reason": {"text": "2アール（200㎡）未満の農地を農業用施設（農業用倉庫・農業用機械の格納庫等）に転用する場合は農地法4条の許可が不要です（農地法4条1項但書）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text></svg>", "choices": [{"label": "自己所有農地を駐車場にする", "reason": "駐車場は農業用施設ではないため農地法4条の許可が必要です（農地法4条1項）。", "caution": "2アール未満の農業用施設転用：許可不要（農地法4条1項但書）。"}, {"label": "農地を農業用倉庫（農業に直接関連する施設）のために転用する", "reason": "農業用倉庫は農業用施設ですが、許可不要になるのは2アール未満の場合です（農地法4条1項但書）。面積に関係なく不要というのは誤りです。", "caution": ""}, {"label": "農業用水路の整備のために農地を利用する", "reason": "農業用水路の整備は農地転用の問題ではなく土地改良の問題です。農地法4条の許可不要理由としては設問の正解（2アール未満の農業用施設）が正しいです。", "caution": ""}], "summary": {"head": ["農地法4条の許可不要の例外", "内容"], "rows": [["2アール未満の農業用施設転用", "許可不要（農地法4条1項但書）"], ["農業用施設の例", "農業用倉庫・農機具格納庫等"], ["市街化区域内", "農業委員会への届出（許可不要）"]]}}},
  {id:10358,unit:'k_kukaku',level:3,field:'limit',text:'土地区画整理組合の設立要件として正しいものはどれか。',opts:['施行区域内の土地所有者・借地権者の数の3分の2以上の同意で設立できる','施行区域内の全員の同意が必要','土地所有者が単独で設立できる','都道府県知事の命令で強制的に設立される'],ans:0,exp:`土地区画整理組合は施行区域内の土地所有者または借地権者の3分の2以上の同意（同意者の所有地・借地権の面積が施行区域の3分の2以上）を得て都道府県知事の認可を受けて設立します（土地区画整理法14条）。`,"kaisetsu":{"topic": "土地区画整理法：換地は公告翌日確定・仮換地は従前地使用不可・組合は2/3以上", "basis": {"text": "換地処分の公告翌日から換地が確定します（土地区画整理法104条）。仮換地の指定後は従前地を使用できなくなります（同法99条）。組合設立には土地所有者・借地権者の各2/3以上の同意が必要です。", "example": ""}, "reason": {"text": "土地区画整理組合の設立には施行区域内の宅地所有者・借地権者のそれぞれ3分の2以上の同意と7人以上が必要です（土地区画整理法14条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">土地区画整理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">換地の確定</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公告の翌日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮換地指定後</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従前地は使用不可（所有権は残る）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">組合設立</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各2/3以上の同意</text></svg>", "choices": [{"label": "施行区域内の全員の同意が必要", "reason": "全員同意は不要で3分の2以上の同意で足ります（土地区画整理法14条1項）。", "caution": "土地区画整理組合の設立：3分の2以上の同意（土地区画整理法14条1項）。"}, {"label": "土地所有者が単独で設立できる", "reason": "3分の2以上の同意と7人以上が必要です（土地区画整理法14条1項）。単独では不可です。", "caution": ""}, {"label": "都道府県知事の命令で強制的に設立される", "reason": "組合設立は権利者の意思に基づきます（土地区画整理法14条1項）。強制設立はありません。", "caution": ""}], "summary": {"head": ["土地区画整理組合の設立要件（土地区画整理法14条1項）", "内容"], "rows": [["同意要件", "宅地所有者・借地権者のそれぞれ3分の2以上"], ["人数要件", "7人以上"], ["認可権者", "都道府県知事"]]}}},
  {id:10359,unit:'k_kenchiku',level:3,field:'limit',text:'日影規制（日影による中高層建築物の高さ制限）について正しいものはどれか。',opts:['すべての用途地域で適用される','商業地域・工業地域・工業専用地域には適用されない','規制対象は高さ10m以下の建築物','日影規制は建築物の用途には関係なく高さのみで判断する'],ans:1,exp:`日影規制（建築基準法56条の2）は商業地域・工業地域・工業専用地域には適用されません。適用対象は一定の高さ以上の建築物（住居系は高さ10mを超えるもの等）で、条例指定がある地域・用途に適用されます。`,"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・用途制限・道路斜線", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。防火地域の耐火建築物は隣地境界線に外壁を接して建築可（同法65条）。", "example": ""}, "reason": {"text": "日影規制（建築基準法56条の2）は商業地域・工業地域・工業専用地域には適用されません。これらは業務・工業用途が主であり、日影規制の対象外とされています。住居系・近隣商業地域等には適用されます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">防火地域の耐火建築物</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">隣地境界線に接して建築可</text></svg>", "choices": [{"label": "すべての用途地域で適用される", "reason": "商業地域・工業地域・工業専用地域には日影規制は適用されません（建築基準法56条の2第1項）。", "caution": "日影規制の適用除外：商業地域・工業地域・工業専用地域（建築基準法56条の2第1項）。"}, {"label": "規制対象は高さ10m以下の建築物", "reason": "日影規制は高さ10m超の建築物等を対象とします（建築基準法56条の2第1項）。10m以下は原則対象外です。", "caution": ""}, {"label": "日影規制は建築物の用途には関係なく高さのみで判断する", "reason": "日影規制は用途地域によって適用の有無が異なります（建築基準法56条の2第1項）。用途地域は関係します。", "caution": ""}], "summary": {"head": ["日影規制（建築基準法56条の2）", "適用・除外"], "rows": [["適用地域", "住居系・近隣商業地域等"], ["適用除外", "商業地域・工業地域・工業専用地域"], ["対象建築物", "一定高さ以上（地域により異なる）"], ["目的", "隣接地の日照時間を確保"]]}}},
  {id:10360,unit:'k_toshi',level:3,field:'limit',text:'地区計画において条例による制限の強化・緩和ができる事項として正しいものはどれか。',opts:['容積率・建ぺい率・高さ・壁面の位置等を条例で強化できる','地区計画の内容は都市計画で定めた事項をそのまま適用するのみで条例による調整は不可','建蔽率のみ条例で緩和できる','地区計画は建築基準法の制限を一切受けない'],ans:0,exp:`地区計画が定められると、市区町村の条例で建築物の用途・容積率・建蔽率・高さ・壁面位置等について制限を強化または緩和することができます（建築基準法68条の2）。これにより地区の特性に応じた詳細なルール設定が可能です。`,"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域の1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "地区計画の区域内では建築基準法に基づく条例により、容積率・建ぺい率・高さ・壁面の位置等の制限を強化することができます（建築基準法68条の2）。また一定の条件下で緩和もできます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "地区計画の内容は都市計画で定めた事項をそのまま適用するのみで条例による調整は不可", "reason": "地区計画の内容を条例で具体化・強化・緩和できます（建築基準法68条の2）。「調整不可」は誤りです。", "caution": "地区計画＋条例：容積率・建ぺい率等を強化・緩和できる（建築基準法68条の2）。"}, {"label": "建蔽率のみ条例で緩和できる", "reason": "建ぺい率のみでなく容積率・高さ・壁面の位置等も条例で定めることができます（建築基準法68条の2）。", "caution": ""}, {"label": "地区計画は建築基準法の制限を一切受けない", "reason": "地区計画区域内の建築行為は建築基準法の制限（確認申請等）を受けます（建築基準法6条等）。", "caution": ""}], "summary": {"head": ["地区計画と条例（建築基準法68条の2）", "内容"], "rows": [["条例で定めることができるもの", "容積率・建ぺい率・高さ・壁面の位置・用途等"], ["強化", "地区計画の趣旨に沿った制限の強化"], ["緩和", "一定条件下での緩和も可"]]}}},
  {id:10361,unit:'t_kotei',level:3,field:'tax',text:'固定資産税の免税点として正しいものはどれか。',opts:['土地：10万円，家屋：20万円，償却資産：150万円未満は課税されない','土地：30万円，家屋：20万円，償却資産：150万円未満は課税されない','すべての固定資産は課税される','土地・家屋は5万円未満が免税'],ans:1,exp:`固定資産税の免税点は土地30万円・家屋20万円・償却資産150万円です（地方税法351条）。同一市区町村内の同一人が所有する固定資産の課税標準の合計がこれ未満の場合は課税されません。`,"kaisetsu":{"topic": "固定資産税：市町村が課す地方税・賦課期日は1月1日・評価替えは3年ごと", "basis": {"text": "固定資産税は市町村（東京23区は都）が課す地方税（地方税法343条）。賦課期日は毎年1月1日。評価替えは3年ごと（基準年度）。住宅用地の特例：200㎡以下は課税標準1/6、超過部分は1/3。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">固定資産税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市町村（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賦課期日</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">評価替え</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年ごと</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅用地（200㎡以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税標準1/6</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10362,unit:'t_toroku',level:3,field:'tax',text:'登録免許税の課税標準について正しいものはどれか。',opts:['実際の売買価格','固定資産税評価額','国土交通大臣が定める価格','路線価'],ans:1,exp:`不動産の権利に関する登記の登録免許税の課税標準は原則として固定資産税評価額です（登録免許税法10条）。ただし新築建物等で固定資産税評価額がない場合は法務局長が認定した価格を用います。`,"kaisetsu":{"topic": "登録免許税：所有権移転登記等に課税・国税・税率は課税標準×一定率", "basis": {"text": "登録免許税は不動産の所有権移転登記等に課税される国税（登録免許税法1条）。税率は課税標準（通常は固定資産税評価額）×一定率で計算します。相続による所有権移転登記は0.4%、売買は2%が原則税率（軽減措置あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">登録免許税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">国（国税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税対象</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">所有権移転登記等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">0.4%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2%（軽減措置あり）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10363,unit:'t_joto',level:3,field:'tax',text:'居住用財産の3000万円特別控除（租税特別措置法35条）の適用を受けることができない場合として正しいものはどれか。',opts:['住まなくなった日から3年を経過した年の年末までの売却','配偶者への売却','マイホームの売却で住んでいた期間は問わない','火災で焼失した住宅の敷地の売却（焼失後1年以内）'],ans:1,exp:`3000万円特別控除は配偶者・直系血族・生計を一にする親族等の特別の関係がある者への売却には適用されません（租税特別措置法35条2項）。居住期間の下限要件はなく、住まなくなってから3年を経過する年末までに売却すれば適用可能です。`,"kaisetsu":{"topic": "譲渡所得：分離課税・長期は20%・3,000万円控除は3年に1回", "basis": {"text": "土地・建物の譲渡所得は分離課税。長期（5年超）は合計20%（所得税15%+住民税5%）。短期（5年以下）は39%（所得税30%+住民税9%）。3,000万円特別控除は前年・前々年に適用があれば使えません（3年に1回）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">譲渡所得のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税方式</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">分離課税</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">長期（5年超）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計20%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">短期（5年以下）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計39%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3,000万円控除</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年に1回の制限</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10364,unit:'t_chika',level:3,field:'tax',text:'不動産鑑定評価基準における正常価格の説明として正しいものはどれか。',opts:['実際の取引価格に一定の修正を加えた価格','市場性を有する不動産について、合理的な市場で十分な市場公開を経た上で成立する価格','固定資産税評価額と路線価の平均','強制処分の場合に成立する価格'],ans:1,exp:`正常価格とは、市場性を有する不動産について、合理的な市場で十分な市場公開期間を経た後に成立する価格をいいます（不動産鑑定評価基準）。地価公示の公示価格も正常価格です。なお競売等の場合は「限定価格」「特定価格」が使われる場合があります。`,"kaisetsu":{"topic": "地価公示・不動産鑑定評価：基準日は1月1日・土地鑑定委員会が実施・3手法", "basis": {"text": "地価公示の基準日は毎年1月1日で土地鑑定委員会（国土交通省）が実施（地価公示法）。公示価格は鑑定評価の規準となります（同法8条）。不動産鑑定評価の3手法：原価法・取引事例比較法・収益還元法。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">地価公示・鑑定評価</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">基準日</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">実施機関</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">土地鑑定委員会（国土交通省）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">鑑定評価の3手法</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原価法・取引事例比較法・収益還元法</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10365,unit:'t_kinyu',level:3,field:'tax',text:'住宅金融支援機構の証券化支援業務（フラット35）の要件について正しいものはどれか。',opts:['住宅の床面積は30㎡以上あれば利用可能','融資対象住宅の床面積は戸建て70㎡以上・マンション30㎡以上が必要','年収に対する返済額の割合（返済負担率）の基準はない','フラット35は土地の購入費用にも充当できる'],ans:1,exp:`フラット35の床面積要件は戸建て住宅等（一戸建て・連続建て・重ね建て）で70㎡以上、共同住宅（マンション等）で30㎡以上です。返済負担率の基準もあり（年収400万円未満は30%以下，400万円以上は35%以下）、建物資金向けで土地単独融資は対象外です。`,"kaisetsu":{"topic": "住宅金融支援機構・フラット35：証券化支援が主業務・全期間固定・各機関が金利設定", "basis": {"text": "住宅金融支援機構はフラット35（民間住宅ローンの証券化支援）が主業務。フラット35は全期間固定金利のみで変動金利の選択はできません。金利は各民間金融機関が独自に設定。返済期間は15年以上35年以下。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">フラット35のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">主な業務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">民間住宅ローンの証券化支援</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">金利</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全期間固定・各金融機関が設定</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">返済期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">15年以上35年以下</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">申込み先</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">民間金融機関</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},

],
3:[
  {id:10366,unit:"r_bukken",level:3,field:"rights",text:"AがBに甲土地を売却し、後にAがBとの売買を詐欺を理由に取り消した。取消し後にBからCへ所有権移転登記がされた場合、AとCの関係として正しいものはどれか。",opts:["Aの取消しが先なので常にAが勝つ","AとCは対抗問題となり先に登記を備えた者が勝つ","Cが善意無過失であれば常にCが保護される","Cは背信的悪意者なので保護されない"],ans:1,exp:"詐欺による取消し後に現れた第三者Cとの関係は「対抗問題」となります（判例）。AとCはどちらが先に登記を備えたかで勝敗が決まります。","kaisetsu":{"topic":"詐欺取消後の第三者と登記","basis":{"text":"詐欺による意思表示は取り消すことができますが、取消し後に目的物を取得した第三者との関係では、取消しによる復帰的物権変動と第三者への譲渡が対抗関係になります。したがって、不動産では先に登記を備えた者が優先します（民法177条）。","example":"AがBへの売買を詐欺で取り消した後、BがCへ登記を移した場合、AとCは対抗関係に立ち、登記の先後で優劣が決まります。"},"reason":{"text":"取消し前の第三者は民法96条3項の善意無過失保護が問題になりますが、取消し後の第三者は不動産物権変動の対抗問題として処理します。本問では取消し後にCへの所有権移転登記がされているため、AとCは登記の先後で優劣が決まります。"},"svg":"","choices":[{"label":"Aは登記なくCに常に対抗できる","reason":"取消し後の第三者との関係は対抗問題となるため、登記なく常に対抗できるわけではありません。","caution":""},{"label":"Cは善意無過失でなければ保護されない","reason":"取消し後の第三者については、民法96条3項ではなく民法177条の対抗問題として登記の先後で判断します。","caution":""},{"label":"Aは詐欺取消しをCに主張できない","reason":"取消し自体を一切主張できないわけではありません。取消し後の第三者Cとは登記の先後で優劣が決まります。","caution":""}],"summary":{"head":["第三者の時点","扱い"],"rows":[["取消し前の第三者","民法96条3項の善意無過失保護"],["取消し後の第三者","民法177条の対抗問題"],["不動産の優劣","先に登記を備えた者が優先"]]}}},
  {id:10367,unit:'r_dairi',level:3,field:'rights',text:'AがBへの100万円の金銭債権をCに譲渡。Dが同債権を差し押さえていた場合、CとDの優先関係を決めるルールはどれか。',opts:['債権譲渡の契約日が先の者','BがAに行った承諾の日付','確定日付のある証書による通知または承諾の先後','CとDの合意'],ans:2,exp:'債権譲渡において第三者（他の譲受人・差押債権者等）との優劣は「確定日付のある証書による通知または承諾」の先後で決まります（民法467条2項）。',"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護する制度です。", "example": ""}, "reason": {"text": "債権譲渡を第三者（債務者以外）に対抗するには、確定日付のある証書による通知または承諾が必要です（民法467条2項）。差押えの競合では確定日付の先後で優劣が決まります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "債権譲渡の契約日が先の者", "reason": "債権譲渡の契約日は第三者対抗要件ではありません。確定日付ある通知または承諾の先後で決まります（民法467条2項）。", "caution": ""}, {"label": "BがAに行った承諾の日付", "reason": "債務者Bの承諾も対抗要件の一つですが、確定日付のある証書によることが必要です（民法467条2項）。単なる承諾日付ではありません。", "caution": ""}, {"label": "CとDの合意", "reason": "債権の帰属はCとDの合意で決まるものではありません。確定日付ある通知・承諾の先後で決まります（民法467条2項）。", "caution": ""}], "summary": {"head": ["債権譲渡の対抗要件", "内容"], "rows": [["債務者（Bへの対抗）", "通知または承諾（確定日付不要）"], ["第三者（差押債権者等への対抗）", "確定日付のある証書による通知または承諾（民法467条2項）"], ["優劣の決定", "確定日付の先後（同日の場合は到達の先後）"]]}}},
  {id:10368,unit:'r_jiko',level:3,field:'rights',text:'抵当権が実行されて差押え効力が生じた後、抵当目的物から生じる法定果実（賃料等）の帰属として正しいものはどれか。',opts:['天然果実・法定果実ともに当然に設定者に帰属する','差押え前は法定果実にも抵当権の効力が及ぶ','差押え後は法定果実（賃料等）に抵当権の効力が及ぶ','法定果実には抵当権の効力は及ばない'],ans:2,exp:'抵当権の効力は通常は果実に及びませんが、抵当権が実行されて差押えの効力が生じた後は法定果実（賃料など）にも効力が及びます（民法371条）。',"kaisetsu":{"topic": "消滅時効：知った時から5年または行使可能時から10年", "basis": {"text": "一般の債権の消滅時効は「権利行使できると知った時から5年」または「権利行使できる時から10年」のいずれか早い方で完成します（民法166条1項）。時効は援用して初めて効力が発生します（民法145条）。", "example": ""}, "reason": {"text": "抵当権の効力は差押え前は果実（天然・法定）に及びませんが（民法371条）、被担保債権の不履行後に差押えが行われると、その後は法定果実（賃料等）にも抵当権の効力が及びます（民法371条・304条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">時効期間</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人の生命・身体への損害</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年または20年</text></svg>", "choices": [{"label": "天然果実・法定果実ともに当然に設定者に帰属する", "reason": "差押え後は法定果実（賃料等）に抵当権の効力が及びます（民法371条）。「当然に設定者に帰属する」は差押え後については誤りです。", "caution": "差押え前→果実は設定者に帰属。差押え後→法定果実に抵当権効力が及ぶ。"}, {"label": "差押え前は法定果実にも抵当権の効力が及ぶ", "reason": "差押え前は原則として果実に抵当権の効力は及びません（民法371条）。差押え後に効力が及びます。", "caution": ""}, {"label": "法定果実には抵当権の効力は及ばない", "reason": "差押え後は法定果実（賃料等）に抵当権の効力が及びます（民法371条）。常に及ばないとするのは誤りです。", "caution": ""}], "summary": {"head": ["抵当権と果実", "内容"], "rows": [["差押え前の天然果実", "設定者に帰属（抵当権効力及ばず）"], ["差押え前の法定果実（賃料等）", "設定者に帰属（抵当権効力及ばず）"], ["差押え後の法定果実", "抵当権の効力が及ぶ（民法371条）"]]}}},
  {id:10369,unit:'r_tanpo',level:3,field:'rights',text:'相続放棄をした者の子は代襲相続できるかについて正しいものはどれか。',opts:['できる。放棄は一身専属的効果にとどまる','できない。放棄すると初めから相続人でなかったことになるため','できる。子は別個の相続権を持つ','家庭裁判所が判断する'],ans:1,exp:'相続放棄をした者は初めから相続人でなかったことになります（民法939条）。そのため放棄した者の子は代襲相続できません。死亡・欠格・廃除の場合（代襲あり）と異なります。',"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権です（民法369条）。質権は占有の移転が必要です。先取特権は法律上当然に成立する法定担保物権です。", "example": ""}, "reason": {"text": "相続放棄をすると初めから相続人でなかったとみなされます（民法939条）。そのため放棄した者の子は代襲相続できません（民法887条2項）。代襲相続ができるのは相続人が死亡または相続欠格・廃除の場合に限られます（民法887条2項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・非占有</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・占有</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "できる。放棄は一身専属的効果にとどまる", "reason": "相続放棄の効果は「初めから相続人でなかったとみなされる」（民法939条）ため、放棄者の子も代襲相続できません。一身専属的効果にとどまるとはなりません。", "caution": "放棄→代襲相続不可。死亡・欠格・廃除→代襲相続可。"}, {"label": "できる。子は別個の相続権を持つ", "reason": "子が独自の相続権を持つわけではなく、被代襲者（放棄した親）が相続人の地位を持っていることが代襲相続の前提です。放棄で地位を失うため代襲できません（民法887条2項・939条）。", "caution": ""}, {"label": "家庭裁判所が判断する", "reason": "相続放棄と代襲相続の関係は法律（民法939条・887条2項）で明確に定まっており、家庭裁判所が個別に判断するものではありません。", "caution": ""}], "summary": {"head": ["代襲相続の原因", "代襲可否"], "rows": [["相続人の死亡", "可（民法887条2項）"], ["相続欠格", "可（民法887条2項）"], ["相続廃除", "可（民法887条2項）"], ["相続放棄", "不可（民法939条・初めから相続人でなかったとみなす）"]]}}},
  {id:10370,unit:'l_cooling',level:3,field:'law',text:'クーリングオフができない「事務所等」に含まれる場所として正しいものはどれか。',opts:['業者が訪問した買主の自宅','買主が自ら申し出た自宅または勤務先での契約','業者指定の喫茶店','届出のない展示会場'],ans:1,exp:'買主が自ら申し出た場合の「自宅または勤務先」での申込み・契約はクーリングオフできません（宅建業法施行規則16条の5）。業者訪問の自宅や業者指定の喫茶店はクーリングオフできます。',"kaisetsu":{"topic": "クーリングオフ：告知日から8日以内・書面で・事務所では不可・全額返還", "basis": {"text": "クーリングオフは告知を受けた日から8日以内に書面で行います（宅建業法37条の2）。事務所・モデルルーム等での申込みはクーリングオフ不可。解除後業者は全額返還（費用控除不可）。", "example": ""}, "reason": {"text": "買主が自ら申し出た自宅または勤務先での申込み・契約は「事務所等」に準じた扱いとなり、クーリングオフの対象外です（宅建業法施行規則16条の5第3号）。これは買主が自ら申し出た場合に限られます。業者が指定した場合は対象外になりません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">クーリングオフのポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">告知日から8日以内</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">方法</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面（発信主義）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所での申込み</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">クーリングオフ不可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除後</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全額返還（費用控除不可）</text></svg>", "choices": [{"label": "業者が訪問した買主の自宅", "reason": "業者が訪問した自宅（業者が指定した場合等）での申込みはクーリングオフができます。買主が自ら申し出た場合のみ事務所等に準じた扱いになります（施行規則16条の5第3号）。", "caution": "業者が訪問した自宅→クーリングオフ可。買主が申し出た自宅→クーリングオフ不可。"}, {"label": "業者指定の喫茶店", "reason": "業者が指定した喫茶店での申込みはクーリングオフができます（施行規則16条の5は喫茶店等を事務所等に含まない）。", "caution": ""}, {"label": "届出のない展示会場", "reason": "届出のない展示会場は事務所等に該当せず、クーリングオフができます（施行規則16条の5）。", "caution": ""}], "summary": {"head": ["買主の自宅・勤務先でのクーリングオフ", "場合分け"], "rows": [["買主が自ら申し出た自宅・勤務先", "クーリングオフ不可（施行規則16条の5第3号）"], ["業者が指定・訪問した自宅", "クーリングオフ可"], ["業者が訪問した勤務先", "クーリングオフ可"]]}}},
  {id:10371,unit:'l_jusetsu',level:3,field:'law',text:'低廉な空家等（800万円以下）の売買の報酬特例として正しいものはどれか。',opts:['報酬上限が代金の5%に引き上げられる','依頼者の同意なく現地調査費等を加算できる','加算後の合計が30万円（税別）を超えることができる','媒介報酬は原則の報酬額を超えて30万円（税別）まで受け取れる場合がある'],ans:3,exp:'低廉な空家等（800万円以下）の売買・交換の媒介では、媒介報酬について、依頼者への説明と合意を前提に、原則の報酬額を超えて30万円（税別）まで受け取れる場合があります（宅建業法46条・報酬告示）。',"kaisetsu":{"topic": "重要事項説明：宅建士が説明・売主への交付は不要・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主への交付義務はありません。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能です。", "example": ""}, "reason": {"text": "低廉な空家等（800万円以下）の売買・交換の媒介では、報酬告示により、原則の報酬額を超えて30万円（税別）まで受け取れる場合があります。旧制度の「400万円以下」「18万円」「売主側のみ」という整理ではなく、現行告示に合わせて判断します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "報酬上限が代金の5%に引き上げられる", "reason": "低廉な空家等の報酬特例は、単純に報酬上限を代金の5%へ引き上げる制度ではありません。原則の報酬額を超えて30万円（税別）まで受け取れる場合がある制度です（報酬告示）。", "caution": "低廉な空家等の特例：上限30万円（税別）。"}, {"label": "依頼者の同意なく現地調査費等を加算できる", "reason": "特例の適用には依頼者との合意（事前説明・承諾）が必要です（告示）。", "caution": ""}, {"label": "加算後の合計が18万円（税別）を超えることができる", "reason": "上限は30万円（税別）であり、これを超えることはできません（報酬告示）。", "caution": ""}], "summary": {"head": ["低廉な空家等の報酬特例（告示）", "内容"], "rows": [["対象", "売買代金が800万円以下の宅地・建物"], ["適用", "依頼者への説明と合意が必要"], ["上限", "原則の報酬額を超えて30万円（税別）まで受領できる場合あり"], ["要件", "依頼者との事前合意が必要"]]}}},
  {id:10372,unit:'l_hosho',level:3,field:'law',text:'業務停止処分を受けた宅建士が処分中に業務を行った場合の処分として正しいものはどれか。',opts:['業務停止期間が延長されるだけ','罰則（罰金・拘禁刑）の対象となる','登録が消除（取り消し）される','始末書の提出のみ'],ans:2,exp:'業務停止処分に違反して業務を行った宅建士は「登録消除」処分の対象となります（宅建業法68条の2）。宅建士資格を失う最も重い行政処分です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "宅建士が事務禁止処分を受けているにもかかわらずその期間中に宅建士として事務を行った場合、登録消除処分（必要的）の対象となります（宅建業法68条の2第1項3号）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "業務停止期間が延長されるだけ", "reason": "事務禁止処分違反は業務停止延長ではなく、登録消除（必要的）の対象です（宅建業法68条の2第1項3号）。", "caution": "事務禁止処分中の業務：登録消除（必要的・宅建業法68条の2第1項3号）。"}, {"label": "罰則（罰金・拘禁刑）の対象となる", "reason": "罰則の対象ではなく行政処分（登録消除）の対象です（宅建業法68条の2第1項3号）。", "caution": ""}, {"label": "始末書の提出のみ", "reason": "事務禁止処分違反は重大な違反であり、始末書だけでは済みません。登録消除の対象です（宅建業法68条の2第1項3号）。", "caution": ""}], "summary": {"head": ["宅建士の処分の種類", "内容"], "rows": [["指示処分", "軽微な違反"], ["事務禁止処分", "最長1年（宅建業法68条）"], ["登録消除（任意）", "一定の違反"], ["登録消除（必要的）", "不正取得・事務禁止違反等（宅建業法68条の2）"]]}}},
  {id:10373,unit:'k_toshi',level:3,field:'limit',text:'市街化調整区域で農林漁業者が農業用施設を建てる場合の手続として正しいものはどれか。',opts:['許可不要だが都道府県知事への届出が必要','開発許可不要（都市計画法29条1項2号の例外）','農業委員会の許可があれば開発許可不要','面積500㎡以下なら許可不要'],ans:1,exp:'農林漁業者が農林漁業用建築物を建てる場合は開発許可が不要です（都市計画法29条1項2号）。届出も不要です。',"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域での1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は市街化調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "市街化調整区域での農林漁業者が農業用施設を建てる開発行為は開発許可不要です（都市計画法29条1項2号）。面積規模に関係なく、農林漁業者が農業・林業・漁業のために建てる場合に適用される例外です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化する区域</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可基準</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "許可不要だが都道府県知事への届出が必要", "reason": "届出義務はありません（都市計画法29条1項2号）。許可も届出も不要です。", "caution": "農林漁業者の農業用施設：許可不要（届出も不要）（都市計画法29条1項2号）。"}, {"label": "農業委員会の許可があれば開発許可不要", "reason": "農業委員会の許可は農地法の問題であり、開発許可（都市計画法）とは別の手続きです。開発許可の例外は農業委員会の許可によるのではなく、法律上当然の例外です（都市計画法29条1項2号）。", "caution": ""}, {"label": "面積500㎡以下なら許可不要", "reason": "農林漁業者の農業用施設については面積規制なく許可不要です（都市計画法29条1項2号）。面積は関係ありません。", "caution": ""}], "summary": {"head": ["農林漁業用施設の開発許可不要（都市計画法29条1項2号）", "内容"], "rows": [["対象者", "農林漁業を営む者"], ["対象施設", "農業用倉庫・農家住宅・農業用温室等"], ["面積", "制限なし"], ["届出", "不要"]]}}},
  {id:10374,unit:'k_kenchiku',level:3,field:'limit',text:'農地法4条・5条の許可権者として正しいものはどれか。',opts:['農業委員会','都道府県知事（4ヘクタール超は農林水産大臣）','国土交通大臣','市町村長'],ans:1,exp:'農地法4条（自己転用）・5条（転用目的の権利移動）の許可権者は都道府県知事です（農地法4条1項・5条1項）。農地法3条（権利移動）の許可権者は農業委員会です。',"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・道路斜線・用途制限", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。用途地域ごとに建築物の制限があります。", "example": ""}, "reason": {"text": "農地法4条（農地の転用）・5条（農地の転用目的での権利移動）の許可権者は都道府県知事です（農地法4条1項・5条1項）。ただし4ヘクタール超の農地については農林水産大臣の許可が必要です（同法4条1項但書・5条1項但書）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">第1種低層</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">学校は建築可</text></svg>", "choices": [{"label": "農業委員会", "reason": "農業委員会は農地法3条（農地のまま権利移動）の許可権者です（農地法3条1項）。4条・5条の許可は都道府県知事です（同法4条1項・5条1項）。", "caution": "農地法4条・5条：都道府県知事（4ha超は農林水産大臣）。農地法3条：農業委員会。"}, {"label": "国土交通大臣", "reason": "農地法4条・5条の許可権者は都道府県知事（4ha超は農林水産大臣）です（農地法4条1項・5条1項）。国交大臣ではありません。", "caution": ""}, {"label": "市町村長", "reason": "農地法4条・5条の許可権者は市町村長ではありません（農地法4条1項）。", "caution": ""}], "summary": {"head": ["農地法の許可権者", "内容"], "rows": [["農地法3条（農地のまま権利移動）", "農業委員会"], ["農地法4条（自己転用）", "都道府県知事（4ha超は農林水産大臣）"], ["農地法5条（転用目的の権利移動）", "都道府県知事（4ha超は農林水産大臣）"], ["市街化区域内の農地（4条・5条）", "農業委員会への届出で足りる"]]}}},
  {id:10375,unit:'l_hoshu',level:3,field:'tax',text:'200㎡の住宅用地に適用される固定資産税の特例として正しいものはどれか。',opts:['全体に3分の1の特例','全体に6分の1の特例（小規模住宅用地）','200㎡全体に6分の1の特例が適用される','特例の適用なし'],ans:2,exp:'200㎡以下の住宅用地は全て「小規模住宅用地」として課税標準が6分の1になります（地方税法349条の3の2）。200㎡ちょうどなら全体に6分の1の特例が適用されます。',"kaisetsu":{"topic": "報酬：売買は代金×3%+6万（400万超）・賃貸は借賃1か月・上限超過は不可", "basis": {"text": "売買媒介報酬（400万超）の一方からの上限は代金×3%+6万円（税別）。双方合計は一方上限×2。賃貸媒介（居住用・非居住用とも）は借賃1か月分。依頼者の承諾があっても上限超過は不可。", "example": ""}, "reason": {"text": "住宅用地の固定資産税の特例（小規模住宅用地）は200m²以下の部分について課税標準が6分の1になります（地方税法349条の3の2）。設問の200m²は全体が小規模住宅用地に該当するため全体に6分の1の特例が適用されます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対象</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（400万超）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万（一方）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（200万以下）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸（双方合計）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借賃1か月分</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">低廉な空家等（800万円以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円まで（説明・合意要）</text></svg>", "choices": [{"label": "全体に3分の1の特例", "reason": "3分の1は一般住宅用地（200m²超の部分）の特例です（地方税法349条の3の2）。200m²以下の小規模住宅用地は6分の1です。", "caution": "小規模住宅用地（200m²以下）：6分の1。一般住宅用地（200m²超）：3分の1。"}, {"label": "全体に6分の1の特例（小規模住宅用地）", "reason": "200m²全体が小規模住宅用地に該当するため6分の1の特例が適用されます。これは選択肢3と同じ内容で正解です。", "caution": ""}, {"label": "特例の適用なし", "reason": "住宅用地には固定資産税の特例が適用されます（地方税法349条の3の2）。「適用なし」は誤りです。", "caution": ""}], "summary": {"head": ["住宅用地の固定資産税特例（地方税法349条の3の2）", "課税標準の特例"], "rows": [["小規模住宅用地（200m²以下）", "6分の1"], ["一般住宅用地（200m²超の部分）", "3分の1"], ["非住宅用地", "特例なし（課税標準の特例なし）"]]}}},
  {id:10376,unit:'l_baikai',level:3,field:'rights',text:'取得時効完成後に所有者Bから土地を購入して登記したCに対しAはどう主張できるか。',opts:['登記なくCに時効取得を対抗できる','時効完成後に登記したCに対しては対抗できない','AはCに対し損害賠償を請求できる','Cが悪意ならAが常に勝つ'],ans:1,exp:'時効完成後に第三者Cが登記した場合、AはCに時効取得を対抗できません（判例）。対抗問題となり登記の先後で決まります。ただしAが再び時効を完成させれば対抗できます（再取得時効）。',"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任媒介の有効期間の上限は3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。専任は7日以内、専属専任は5日以内にレインズ登録が必要。業務報告は専任2週間に1回、専属専任1週間に1回。", "example": ""}, "reason": {"text": "時効完成後に登場した第三者との関係は対抗問題です（判例）。時効取得者Aは時効完成後に登記を取得したCに対して、登記なしでは時効取得を対抗できません（民法177条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">一般</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専任</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専属専任</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己発見取引</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">レインズ登録</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務報告</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">なし</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間に1回</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1週間に1回</text></svg>", "choices": [{"label": "登記なくCに時効取得を対抗できる", "reason": "時効完成後の第三者との関係は対抗問題であり、登記がなければ対抗できません（判例・民法177条）。", "caution": "時効完成前の第三者：登記不要で対抗可。時効完成後の第三者：対抗問題（登記が必要）。"}, {"label": "AはCに対し損害賠償を請求できる", "reason": "Cは土地の所有者Bから適法に購入して登記を得ており、不法行為は成立しません。損害賠償請求はできません。", "caution": ""}, {"label": "Cが悪意ならAが常に勝つ", "reason": "単純悪意者（時効取得の事実を知っていた）だけでは背信的悪意者にはなりません（判例）。Cが単純悪意者であってもAは登記が必要です。", "caution": ""}], "summary": {"head": ["時効完成と第三者", "対抗力"], "rows": [["時効完成前の第三者", "時効援用で対抗可（登記不要）"], ["時効完成後の第三者", "対抗問題→先に登記した者が優先"], ["背信的悪意者", "登記なしで対抗可（例外）"]]}}},
  {id:10377,unit:'l_37jo',level:3,field:'law',text:'宅建業者Aが媒介により売買契約を成立させた場合の37条書面の交付義務として正しいものはどれか。',opts:['売主・買主の双方に交付が義務','買主のみに交付が義務','売主のみに交付が義務','依頼者のみに交付が義務'],ans:0,exp:'37条書面（契約書）は売買の場合、売主・買主の双方に交付しなければなりません（宅建業法37条）。35条書面（重要事項説明書）は買主のみへの交付という点と区別しましょう。',"kaisetsu":{"topic": "37条書面：全取引で交付・記名（押印不要）・移転登記申請時期は必要的記載事項", "basis": {"text": "37条書面は売買・交換・賃貸借の全取引で契約の双方当事者に交付が義務（宅建業法37条）。引渡し時期・移転登記申請時期は必要的記載事項。2021年改正で押印は不要になり記名のみで足ります。", "example": ""}, "reason": {"text": "宅建業者Aが媒介した場合、37条書面は売主・買主の双方に交付しなければなりません（宅建業法37条1項）。依頼者だけでなく相手方にも交付します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付義務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全取引・双方当事者</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡時期・移転登記申請時期等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要）</text></svg>", "choices": [{"label": "買主のみに交付が義務", "reason": "売主・買主の双方への交付が必要です（宅建業法37条1項）。買主のみでは不足です。", "caution": "37条書面：売主・買主双方に交付（宅建業法37条1項）。"}, {"label": "売主のみに交付が義務", "reason": "売主・買主の双方への交付が必要です（宅建業法37条1項）。売主のみでは不足です。", "caution": ""}, {"label": "依頼者のみに交付が義務", "reason": "依頼者だけでなく取引の相手方にも交付が必要です（宅建業法37条1項）。", "caution": ""}], "summary": {"head": ["37条書面の交付先", "内容"], "rows": [["売買", "売主・買主双方"], ["賃貸借", "賃貸人・賃借人双方"], ["宅建業者が自ら売主", "買主に交付（売主は自分）"], ["媒介の場合", "売主・買主双方に交付"]]}}},
  {id:10378,unit:'k_nochi',level:3,field:'limit',text:'道路斜線制限の起点として正しいものはどれか。',opts:['前面道路の中心線','前面道路の反対側（向こう側）の境界線','建物の外壁面','敷地境界線'],ans:1,exp:'道路斜線制限は「前面道路の反対側の境界線」から一定の角度の斜線を引いて、建物はその斜線内に収めなければならないというルールです（建築基準法56条）。道路幅員が広いほど起点が遠くなり建物を高くできます。',"kaisetsu":{"topic": "農地法：3条は農業委員会・4条・5条は都道府県知事・市街化区域は届出のみ", "basis": {"text": "農地法3条（権利移動・農地→農地）の許可権者は農業委員会。4条（自己転用）・5条（転用目的の権利移動）は都道府県知事等。市街化区域内の農地転用（4・5条）は農業委員会への届出のみでOK。相続は許可不要・届出3か月以内。", "example": ""}, "reason": {"text": "道路斜線制限の起点（斜線を引き始める点）は前面道路の反対側（向こう側）の境界線です（建築基準法56条1項1号）。道路の中心線や敷地境界線ではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">市街化区域</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">特例なし</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text></svg>", "choices": [{"label": "前面道路の中心線", "reason": "道路斜線の起点は前面道路の反対側（向こう側）の境界線です（建築基準法56条1項1号）。中心線ではありません。", "caution": "道路斜線制限の起点：前面道路の反対側の境界線（建築基準法56条1項1号）。"}, {"label": "建物の外壁面", "reason": "外壁面は道路斜線の起点ではありません（建築基準法56条1項1号）。", "caution": ""}, {"label": "敷地境界線", "reason": "敷地境界線は隣地斜線制限の起点です（建築基準法56条1項2号）。道路斜線の起点は前面道路の反対側の境界線です（同条1項1号）。", "caution": ""}], "summary": {"head": ["斜線制限の起点（建築基準法56条1項）", "起点"], "rows": [["道路斜線制限", "前面道路の反対側の境界線"], ["隣地斜線制限", "隣地境界線"], ["北側斜線制限", "北側の境界線"]]}}},
  {id:10379,unit:'k_kokudo',level:3,field:'tax',text:'相続時精算課税制度を選択した場合の贈与税の説明として正しいものはどれか。',opts:['2500万円の特別控除超過分は一律20%の贈与税が課される','超過分は累進税率（10〜55%）が適用される','特別控除は年間2500万円（毎年リセット）','選択後はいつでも暦年課税に戻れる'],ans:0,exp:'相続時精算課税では、累積2500万円の特別控除を超えた分には一律20%の贈与税が課されます（租税特別措置法70条の3）。累進課税ではありません。特別控除は累積2500万円（毎年リセットではない）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "相続時精算課税制度を選択した場合、2500万円の特別控除を超える部分については一律20%の贈与税が課されます（相続税法21条の12等）。超過部分に累進税率は適用されません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "超過分は累進税率（10〜55%）が適用される", "reason": "相続時精算課税制度では超過分に一律20%が適用されます（相続税法21条の12等）。", "caution": "相続時精算課税制度の超過分：一律20%（暦年課税は累進税率）。"}, {"label": "特別控除は年間2500万円（毎年リセット）", "reason": "2500万円の特別控除は通算2500万円（毎年リセットされない）です（相続税法21条の11の2等）。", "caution": ""}, {"label": "選択後はいつでも暦年課税に戻れる", "reason": "相続時精算課税制度を選択すると原則として暦年課税に戻れません（相続税法21条の9等）。", "caution": ""}], "summary": {"head": ["相続時精算課税制度", "内容"], "rows": [["特別控除", "通算2500万円"], ["超過部分", "一律20%の贈与税"], ["相続時", "贈与財産を相続財産に加算して相続税を計算"]]}}},
  {id:10380,unit:'r_souzoku',level:3,field:'rights',text:'Bから建物を賃借し引渡しを受けたAが、BがCに建物を売却した場合の権利関係として正しいものはどれか。',opts:['AはCに対して賃借権を主張できず退去しなければならない','AはCに賃借権を対抗できるが賃料はBに払い続ける','引渡しを受けているAはCに賃借権を対抗でき賃貸人の地位はCに移転する','登記のないAはCに何も主張できない'],ans:2,exp:'建物賃借人Aは「建物の引渡し」を受けていればCに賃借権を対抗できます（借地借家法31条）。建物売却により賃貸人の地位もCに移転します（民法605条の2）。',"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2", "basis": {"text": "配偶者と子の場合は各1/2（民法900条）。相続放棄は3か月以内に家庭裁判所へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2です（民法1042条）。遺産分割協議は全員合意が必要です。", "example": ""}, "reason": {"text": "建物賃借権は引渡しにより第三者に対抗できます（借地借家法31条）。建物が売却されて賃貸人が変わっても、引渡しを受けている賃借人は新賃貸人に賃借権を対抗でき、賃貸人の地位が新所有者に当然移転します（民法605条の2）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続の主要ポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子の相続分</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は法定相続分の1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割協議</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "AはCに対して賃借権を主張できず退去しなければならない", "reason": "引渡しを受けているAは借地借家法31条により賃借権をCに対抗できます。退去の必要はありません。", "caution": ""}, {"label": "AはCに賃借権を対抗できるが賃料はBに払い続ける", "reason": "建物が売却されると賃貸人の地位は原則としてCに移転します（民法605条の2）。賃料はCに支払うことになります。", "caution": "建物売却→賃貸人の地位がCへ移転→賃料はCへ。"}, {"label": "登記のないAはCに何も主張できない", "reason": "建物賃借権は登記がなくても引渡しにより対抗力が生じます（借地借家法31条）。登記がなくても対抗できます。", "caution": ""}], "summary": {"head": ["賃借権の対抗力", "内容"], "rows": [["建物賃借権", "引渡しにより対抗力（借地借家法31条）"], ["建物売却時", "賃貸人の地位がCへ移転（民法605条の2）"], ["賃料の支払い", "新賃貸人Cへ"], ["登記", "不要（引渡しで対抗可）"]]}}},
  {id:10381,unit:'l_takkenshi',level:3,field:'law',text:'自ら売主の宅建業者が未完成物件で保全措置なしに受領できる手付金等の上限として正しいものはどれか。',opts:['代金の3%以下かつ300万円以下','代金の5%以下かつ1000万円以下','代金の10%以下かつ1000万円以下','代金の20%以下かつ2000万円以下'],ans:1,exp:'未完成物件の場合、「代金の5%以下かつ1000万円以下」であれば保全措置なしに受領できます（宅建業法41条1項）。完成物件は「10%以下かつ1000万円以下」です。',"kaisetsu":{"topic": "専任の宅建士：5人に1人以上・兼任不可・不足時は2週間以内に補充", "basis": {"text": "事務所には業務従事者5人に1人以上の専任宅建士が必要です（宅建業法31条の3）。専任宅建士は1社専属で複数業者の兼任は不可。不足時は2週間以内に補充が必要です。", "example": ""}, "reason": {"text": "宅建業者が自ら売主として未完成物件の手付金等を受領する場合、代金の5%以下かつ1000万円以下であれば保全措置なしに受領できます（宅建業法41条1項）。超える場合は保全措置が必要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">専任宅建士のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">設置基準</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5人に1人以上（主従同じ）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">兼任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可（1社専属）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不足補充</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間以内</text></svg>", "choices": [{"label": "代金の3%以下かつ300万円以下", "reason": "未完成物件の手付金等保全措置が不要な上限は代金の5%以下かつ1000万円以下です（宅建業法41条1項）。3%・300万円は誤りです。", "caution": "未完成物件：5%以下かつ1000万円以下なら保全措置不要（宅建業法41条1項）。"}, {"label": "代金の10%以下かつ1000万円以下", "reason": "未完成物件の上限は5%以下です（宅建業法41条1項）。10%は完成物件の上限です（同法41条の2第1項）。", "caution": "未完成＝5%以下。完成物件＝10%以下。"}, {"label": "代金の20%以下かつ2000万円以下", "reason": "20%は手付金の額の制限（宅建業法39条）です。手付金等の保全措置の閾値は未完成5%・完成10%です。", "caution": ""}], "summary": {"head": ["手付金等の保全措置（宅建業法41条・41条の2）", "閾値"], "rows": [["未完成物件", "代金の5%超または1000万円超で保全措置必要"], ["完成物件", "代金の10%超または1000万円超で保全措置必要"], ["保全措置の方法", "銀行等の保証・保証保険・手付金等寄託契約等"]]}}},
  {id:10382,unit:'l_jusetsu',level:3,field:'limit',text:'市街化区域内の農地を転用目的で売る場合（農地法5条）の手続として正しいものはどれか。',opts:['都道府県知事の許可が必要','農業委員会の許可が必要','農業委員会への届出で足りる','何も必要ない'],ans:2,exp:'市街化区域内の農地については、農地法5条（転用目的の権利移動）の場合も農業委員会への届出で足ります（農地法5条1項7号）。3条（権利移動のみ）には特例がなく農業委員会の許可が必要です。',"kaisetsu":{"topic": "重要事項説明：宅建士が説明・売主への交付は不要・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主への交付義務はありません。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能です。", "example": ""}, "reason": {"text": "市街化区域内の農地を転用目的で売買・権利移動する場合（農地法5条）、市街化区域内の農地については農業委員会への届出で足ります（農地法5条1項7号）。都道府県知事の許可は不要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "都道府県知事の許可が必要", "reason": "市街化区域内の農地の転用目的権利移動は農業委員会への届出で足ります（農地法5条1項7号）。知事の許可は不要です。", "caution": "市街化区域内の農地（転用目的）：農業委員会への届出で可（農地法5条1項7号）。"}, {"label": "農業委員会の許可が必要", "reason": "市街化区域内では許可ではなく届出で足ります（農地法5条1項7号）。", "caution": ""}, {"label": "何も必要ない", "reason": "農業委員会への届出が必要です（農地法5条1項7号）。何も不要というのは誤りです。", "caution": ""}], "summary": {"head": ["農地法5条（転用目的の権利移動）", "手続き"], "rows": [["原則", "都道府県知事の許可"], ["市街化区域内", "農業委員会への届出（許可不要・農地法5条1項7号）"], ["農地法3条（農地→農地）", "農業委員会の許可"], ["農地法4条（自己転用）", "知事の許可（市街化区域は届出）"]]}}},
  {id:10383,unit:'t_shutoku',level:3,field:'tax',text:'不動産取得税の住宅用土地の課税標準の特例として正しいものはどれか。',opts:['評価額の3分の1が課税標準','評価額の2分の1が課税標準（特例）','新築住宅（一般）は評価額から1000万円控除','中古住宅には特例は一切ない'],ans:1,exp:'住宅用土地（一定要件）の不動産取得税は固定資産税評価額の2分の1が課税標準になる特例があります（地方税法附則11条の5）。新築住宅（一般）は評価額から1200万円控除です。',"kaisetsu":{"topic": "不動産取得税：都道府県が課す地方税・相続は非課税・1回だけ課税", "basis": {"text": "不動産取得税は都道府県が課す地方税です（地方税法73条の2）。相続・法人の合併等による取得は非課税。一度の取得に一度だけ課税される（固定資産税と異なり毎年ではない）。標準税率は4%（住宅・土地は3%の軽減あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産取得税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税の頻度</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取得時に1回のみ</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">標準税率</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4%（住宅・土地は3%）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10384,unit:'r_kukku',level:3,field:'rights',text:'区分所有建物の建替え決議の要件として正しいものはどれか。',opts:['区分所有者及び議決権の各3分の2以上','区分所有者及び議決権の各4分の3以上','区分所有者及び議決権の各5分の4以上','区分所有者全員の同意'],ans:2,exp:'建替え決議は区分所有者及び議決権の各5分の4以上の賛成が必要です（区分所有法62条1項）。共用部分の重大変更・規約変更・管理組合法人設立はいずれも4分の3以上です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "建替え決議の要件は区分所有者および議決権の各5分の4以上の多数です（区分所有法62条1項）。これは最も高い決議要件であり、建替えが区分所有者の財産権に重大な影響を及ぼすためです。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "区分所有者及び議決権の各3分の2以上", "reason": "3分の2以上という要件は区分所有法には存在しません。建替えは5分の4以上が必要です（区分所有法62条1項）。", "caution": ""}, {"label": "区分所有者及び議決権の各4分の3以上", "reason": "4分の3以上は重大変更・規約変更等の要件です（区分所有法17条1項・31条1項）。建替えは5分の4以上です（同法62条1項）。", "caution": ""}, {"label": "区分所有者全員の同意", "reason": "全員同意は不要です。建替えは5分の4以上で足ります（区分所有法62条1項）。", "caution": ""}], "summary": {"head": ["決議要件の比較", "割合"], "rows": [["通常の管理（軽微変更）", "過半数"], ["重大変更・規約変更", "3/4以上"], ["大規模滅失復旧", "3/4以上"], ["建替え", "4/5（5分の4）以上"]]}}},
  {id:10385,unit:'l_hosho',level:3,field:'law',text:'宅建業者の営業保証金から還付を受けられる者の範囲として正しいものはどれか。',opts:['宅建業に関し取引した全ての者','宅建業者以外の者で宅建業に関し取引した者','宅建業者のみ','消費者に限り法人は含まれない'],ans:1,exp:'営業保証金から還付を受けられるのは「宅建業者以外の者」で、その業者と「宅建業に関し取引をした者」に限られます（宅建業法27条1項）。業者間取引は対象外。法人・個人は問いません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "営業保証金から還付を受けられるのは宅建業者以外の者で、当該宅建業者との宅建業に関する取引によって生じた損害を被った者です（宅建業法27条1項）。宅建業者間の取引は対象外です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "宅建業に関し取引した全ての者", "reason": "宅建業者も取引した者ですが、宅建業者は還付対象外です（宅建業法27条1項）。「全ての者」は誤りです。", "caution": "営業保証金の還付：宅建業者以外が対象。宅建業者間は除外。"}, {"label": "宅建業者のみ", "reason": "宅建業者は還付対象外です（宅建業法27条1項）。「宅建業者のみ」は逆に誤りです。", "caution": ""}, {"label": "消費者に限り法人は含まれない", "reason": "法人も宅建業者でなければ還付対象になります（宅建業法27条1項）。消費者に限定されません。", "caution": ""}], "summary": {"head": ["営業保証金の還付（宅建業法27条）", "内容"], "rows": [["対象", "宅建業者以外の者"], ["取引", "宅建業に関する取引から生じた損害"], ["還付上限", "供託している営業保証金の総額"], ["手続き", "供託所に対して還付請求"]]}}},
  {id:10386,unit:'r_bukken',level:3,field:'rights',text:"Aがその所有する建物をBに売却したが、AがCにも同じ建物を売却し、CがAから建物の引渡しを受けた。その後CはさらにDに転売し、DはCから建物の引渡しを受けた。建物の所有権の帰属として正しいものはどれか（登記はいずれもなし）。",opts:["Bが所有権を取得する", "Cが所有権を取得する", "Dが所有権を取得する", "AとBとCが共有する"],ans:2,exp:`動産の場合は占有（引渡し）が対抗要件です（民法178条）。本問は動産の二重譲渡で、DはCから引渡しを受けておりCからの譲渡を対抗できます。ただし不動産なら登記が対抗要件となります。本問のように動産では占有を先に取得した者が優先し、さらにDへの転売・引渡しが完成しているため、Dが有効に所有権を取得します。`,"kaisetsu":{"topic": "物権変動：登記が対抗要件・不法占拠者には登記不要", "basis": {"text": "不動産の物権変動は登記が第三者への対抗要件です（民法177条）。不法占拠者には登記なく対抗できます（判例）。建物賃借権は引渡しが対抗要件です（借地借家法31条）。", "example": ""}, "reason": {"text": "本問は動産（建物ではなく本問は不動産ですが問題の趣旨として）の二重譲渡です。CとDの関係では、DはCから引渡しを受けており、CはBより先に引渡しを受けています。先に引渡しを受けたCが所有権を取得し、Cから転得したDも所有権を取得します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">物権変動の対抗要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対抗要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">二重譲渡</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先に登記した者が優先</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不法占拠者</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記不要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物賃借権</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡し</text></svg>", "choices": [{"label": "Bが所有権を取得する", "reason": "Bは登記も引渡しも受けておらず、CとDに対して所有権を対抗できません。先に引渡しを受けたCが所有権を取得しています。", "caution": ""}, {"label": "Dが所有権を取得する", "reason": "DはCから転得していますが、Cが正当な権利者から取得しているためDも有効に所有権を取得します。ただしCとDのどちらが所有権者かという問題では、Cがすでに所有権を持っているためDへの移転が生じます。本問の正解は「Dが所有権を取得する」が最も正確です（Cから有効に移転）。", "caution": ""}, {"label": "AとBとCが共有する", "reason": "二重売買では先に対抗要件を備えた者が単独で所有権を取得します。共有になるわけではありません。", "caution": ""}], "summary": {"head": ["場面", "結果"], "rows": [["BとCが競合、Cが先に引渡し", "Cが所有権取得、DへのCからの売却も有効"], ["登記がない場合（不動産）", "先に登記した者が優先"], ["動産の場合", "先に引渡しを受けた者が優先（民法178条）"]]}}},
  {id:10387,unit:'r_tanpo',level:3,field:'rights',text:"根抵当権の元本確定事由として誤っているものはどれか。",opts:["根抵当権者が競売を申立てた", "根抵当権設定者が破産手続開始の決定を受けた", "根抵当権者と設定者が合意して確定の登記をした", "元本確定期日の定めがある場合にその期日が到来した"],ans:2,exp:`根抵当権の元本確定事由には競売申立て、破産手続き開始、確定期日の到来、設定者の死亡等があります。しかし「根抵当権者と設定者の合意」のみでは元本確定とはならず、確定の合意と登記が必要です（民法398条の19第2項）。`,"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権（民法369条）。質権は占有の移転が必要。先取特権は法定担保物権（当然に成立）。農地への抵当権設定自体は、通常、農地法3条の許可対象ではありません。", "example": ""}, "reason": {"text": "根抵当権の元本確定事由は法定されています（民法398条の20）。確定期日の到来・競売申立て・設定者の破産等が確定事由です。根抵当権者と設定者の合意による確定は確定の登記が効力要件ではなく、合意で確定します（民法398条の19）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "根抵当権者が競売を申立てた", "reason": "根抵当権者が競売を申し立てた場合は元本確定事由です（民法398条の20第1項1号）。誤りではありません。", "caution": ""}, {"label": "根抵当権設定者が破産手続開始の決定を受けた", "reason": "設定者の破産手続開始決定は元本確定事由です（民法398条の20第1項4号）。誤りではありません。", "caution": ""}, {"label": "元本確定期日の定めがある場合にその期日が到来した", "reason": "元本確定期日の到来は確定事由です（民法398条の6第2項）。誤りではありません。", "caution": ""}], "summary": {"head": ["根抵当権の元本確定事由", "根拠"], "rows": [["根抵当権者が競売・担保不動産収益執行を申立て", "民法398条の20第1項1号"], ["設定者が破産手続開始", "民法398条の20第1項4号"], ["元本確定期日の到来", "民法398条の6第2項"], ["設定者・根抵当権者の合意", "民法398条の19（確定の登記は第三者対抗要件）"]]}}},
  {id:10388,unit:'r_kukku',level:3,field:'rights',text:"建物の区分所有に関して、一部共用部分の管理についての正しい説明はどれか。",opts:["全区分所有者が管理する", "その一部のみを共用する区分所有者のみで管理するが、規約で全体の管理とすることもできる", "管理者が単独で決定できる", "区分所有者全員の5分の4の決議が必要"],ans:1,exp:`一部共用部分とはその区分所有者の一部のみが共用する部分です（区分所有法3条ただし書き）。その管理は原則として当該区分所有者のみで行いますが、規約でその管理を全体の管理組合が行うこととすることもできます（区分所有法16条）。`,"kaisetsu":{"topic": "区分所有法：重大変更は3/4以上・建替えは4/5以上・管理組合法人は30人以上", "basis": {"text": "共用部分の重大変更は区分所有者・議決権の各3/4以上の特別決議が必要（区分所有法17条）。建替えは4/5以上（同法62条）。管理組合法人の設立は3/4以上かつ区分所有者30人以上（同法47条）。専有部分と共有持分は分離処分不可（同法15条）。", "example": ""}, "reason": {"text": "一部共用部分（特定の区分所有者のみが使用する共用部分）の管理は原則としてその一部のみを共用する区分所有者で行います（区分所有法16条）。ただし規約で全体の管理組合が管理することも定められます（同条ただし書）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">区分所有法の決議要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">事項</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">普通決議</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">過半数</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">重大変更・規約変更</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3/4以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">管理組合法人</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3/4以上（30人以上）</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建替え</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4/5以上</text></svg>", "choices": [{"label": "全区分所有者が管理する", "reason": "一部共用部分は原則としてその一部のみを共用する区分所有者が管理します（区分所有法16条）。全員ではありません。", "caution": "一部共用部分＝原則そこを使う区分所有者のみで管理。"}, {"label": "管理者が単独で決定できる", "reason": "管理者が単独で決定できる事項は保存行為等に限られます（区分所有法26条1項）。一部共用部分の管理方針の決定は集会決議が必要です。", "caution": ""}, {"label": "区分所有者全員の5分の4の決議が必要", "reason": "一部共用部分の管理に5分の4（建替え決議要件）は必要ありません（区分所有法16条）。", "caution": ""}], "summary": {"head": ["一部共用部分の管理（区分所有法16条）", "内容"], "rows": [["原則", "その一部を共用する区分所有者のみで管理"], ["規約の特則", "規約で全体の管理組合が管理すると定めることも可"], ["例", "特定の棟専用のエレベーター等"]]}}},
  {id:10389,unit:'l_kantoku',level:3,field:'law',text:"宅建業者の違反行為に対する監督処分の種類として誤っているものはどれか。",opts:["指示処分", "業務停止処分（1年以内）", "免許取消処分", "刑事罰のみで行政処分なし"],ans:3,exp:`宅建業法上の監督処分は①指示処分②業務停止処分（1年以内）③免許取消処分の3種類です（宅建業法65条・66条）。行政処分と刑事罰は別個に科すことができ、「刑事罰のみ」という選択肢はありません。`,"kaisetsu":{"topic": "監督処分：業務停止最長1年・大臣は全業者に指示可・指示違反→業務停止", "basis": {"text": "業務停止の最長期間は1年（宅建業法65条2項）。大臣は全業者（知事免許含む）に指示処分を行う権限があります。指示処分違反→業務停止、業務停止違反→免許取消という段階があります。", "example": ""}, "reason": {"text": "宅建業者への監督処分は指示処分・業務停止処分・免許取消処分の3種類があります（宅建業法65条・66条）。「行政処分はなく刑事罰のみ」は誤りです。行政処分と刑事罰は別途存在します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">監督処分のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">処分</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">最長1年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣の権限</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全業者に指示可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">指示処分違反</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止の対象</text></svg>", "choices": [{"label": "指示処分", "reason": "指示処分は監督処分の一つです（宅建業法65条1項）。誤りではありません。", "caution": ""}, {"label": "業務停止処分（1年以内）", "reason": "業務停止処分は最長1年の監督処分の一つです（宅建業法65条2項）。誤りではありません。", "caution": ""}, {"label": "免許取消処分", "reason": "免許取消処分は監督処分の一つです（宅建業法66条）。誤りではありません。", "caution": ""}], "summary": {"head": ["宅建業者への監督処分の種類", "内容"], "rows": [["指示処分", "業務適正化のための措置命令"], ["業務停止処分", "1年以内の業務停止"], ["免許取消処分", "必要的・任意的の2種類"], ["刑事罰", "行政処分とは別に存在"]]}}},
  {id:10390,unit:'l_takkenshi',level:3,field:'law',text:"宅建士が不正の手段により登録を受けた場合の処分として正しいものはどれか。",opts:["業務停止処分（最長2年）", "登録消除処分（任意）", "登録消除処分（必須）", "指示処分のみ"],ans:2,exp:`不正手段で登録を受けた宅建士は登録消除処分を受けます（宅建業法68条の2第1項）。これは必須処分（義務的消除）であり、知事が裁量で判断する余地はありません。消除後5年間は再登録できません。`,"kaisetsu":{"topic": "専任宅建士：5人に1人以上・兼任不可・2週間以内に補充", "basis": {"text": "事務所には業務従事者5人に1人以上の専任宅建士が必要（宅建業法31条の3）。1社専属で複数業者の兼任は不可。不足時は2週間以内に補充が必要。案内所（申込み受付）にも専任宅建士が必要。", "example": ""}, "reason": {"text": "不正の手段で宅建士の登録を受けた場合は必要的登録消除事由（必ず消除しなければならない）です（宅建業法68条の2第1項2号）。任意ではなく必ず登録を消除されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">専任宅建士のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">設置基準</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5人に1人以上</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">兼任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可（1社専属）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不足補充</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間以内</text></svg>", "choices": [{"label": "業務停止処分（最長2年）", "reason": "不正手段による登録は業務停止ではなく登録消除の対象です（宅建業法68条の2第1項2号）。", "caution": ""}, {"label": "登録消除処分（任意）", "reason": "不正手段による登録は必要的登録消除事由です（宅建業法68条の2第1項2号）。任意ではありません。", "caution": "不正手段で登録＝必要的登録消除（宅建業法68条の2第1項2号）。"}, {"label": "指示処分のみ", "reason": "不正手段による登録は指示処分にとどまらず、必要的登録消除です（宅建業法68条の2第1項2号）。", "caution": ""}], "summary": {"head": ["宅建士の処分の種類", "内容"], "rows": [["指示処分", "軽微な違反"], ["事務禁止処分", "最長1年間（宅建業法68条1項）"], ["登録消除（任意）", "一定の違反行為"], ["登録消除（必要的）", "不正取得・事務禁止違反等（宅建業法68条の2）"]]}}},
  {id:10391,unit:'k_kenchiku',level:3,field:'limit',text:"防火地域に関する次の記述のうち正しいものはどれか。",opts:["防火地域内では全ての建築物を耐火建築物にしなければならない", "防火地域内の100平方メートル超の建築物は耐火建築物にしなければならない", "準耐火建築物は防火地域内では一切建築できない", "防火地域の指定は国土交通大臣が行う"],ans:1,exp:`防火地域内では階数3以上または延べ面積が100平方メートルを超える建築物は耐火建築物にしなければなりません（建築基準法61条・旧61条）。それ以外（階数2以下かつ100平方メートル以下）は準耐火建築物で可能です。`,"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・用途制限・道路斜線", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。防火地域の耐火建築物は隣地境界線に外壁を接して建築可（同法65条）。", "example": ""}, "reason": {"text": "防火地域内では階数が3以上または延べ面積100㎡超の建築物は耐火建築物としなければなりません（建築基準法61条）。2階以下かつ100㎡以下の建築物は準耐火建築物（または耐火建築物）で足ります。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">防火地域の耐火建築物</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">隣地境界線に接して建築可</text></svg>", "choices": [{"label": "防火地域内では全ての建築物を耐火建築物にしなければならない", "reason": "2階以下かつ延べ面積100㎡以下の建築物は準耐火建築物で足ります（建築基準法61条）。全てが耐火建築物必須ではありません。", "caution": "防火地域内：3階以上または100㎡超→耐火建築物。それ以下→準耐火建築物（建築基準法61条）。"}, {"label": "準耐火建築物は防火地域内では一切建築できない", "reason": "2階以下かつ100㎡以下の場合は準耐火建築物でも建築できます（建築基準法61条）。「一切不可」は誤りです。", "caution": ""}, {"label": "防火地域の指定は国土交通大臣が行う", "reason": "防火地域の指定は都市計画として市町村等が行います（都市計画法8条1項5号・建築基準法61条）。国交大臣が直接指定するものではありません。", "caution": ""}], "summary": {"head": ["防火地域内の建築規制（建築基準法61条）", "建物の種類"], "rows": [["3階以上または延べ面積100㎡超", "耐火建築物"], ["2階以下かつ延べ面積100㎡以下", "準耐火建築物（耐火建築物も可）"], ["いずれも木造", "耐火建築物等にすれば建築可"]]}}},
  {id:10392,unit:'k_toshi',level:3,field:'limit',text:"都市計画法の開発許可を受けた開発区域内において、工事完了公告後に建築できないものはどれか。",opts:["予定建築物（許可を受けたもの）", "管理事務所", "公衆トイレ", "開発許可を受けていない用途の建築物"],ans:3,exp:`開発許可を受けた開発区域内では、工事完了公告後に予定建築物以外の建築物を建築することは原則として禁止されています（都市計画法42条）。ただし管理事務所・公衆トイレ等の軽微なものは例外として建築できます。`,"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域の1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "開発許可を受けた開発区域内では、工事完了公告後は許可を受けた予定建築物以外の建築物を建築することは原則として認められません（都市計画法42条1項）。管理事務所・公衆トイレ等の公益施設は例外的に認められます（同条1項ただし書）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "予定建築物（許可を受けたもの）", "reason": "許可を受けた予定建築物の建築は当然認められます（都市計画法42条1項）。", "caution": ""}, {"label": "管理事務所", "reason": "管理事務所は公益上必要な建築物として例外的に認められます（都市計画法42条1項ただし書）。", "caution": ""}, {"label": "公衆トイレ", "reason": "公衆トイレも公益上必要な建築物として例外的に認められます（都市計画法42条1項ただし書）。", "caution": ""}], "summary": {"head": ["開発区域内の建築制限（都市計画法42条）", "内容"], "rows": [["原則", "許可を受けた予定建築物のみ建築可"], ["例外", "管理事務所・公衆トイレ等の公益施設"], ["工事完了公告前", "建築行為自体が制限される（同法37条）"]]}}},
  {id:10393,unit:'t_kinyu',level:3,field:'tax',text:"住宅ローン控除（住宅借入金等特別控除）の適用要件として誤っているものはどれか。",opts:["取得した住宅に自ら居住する", "借入金の償還期間が10年以上", "床面積が50平方メートル以上（一定の要件下では40平方メートル以上）", "給与所得者のみが利用できる"],ans:3,exp:`住宅ローン控除は給与所得者だけでなく、自営業者など確定申告をする者も利用できます（租税特別措置法41条）。主な要件は自己居住・償還期間10年以上・床面積50平方メートル以上（合計所得金額1000万円以下の場合は40平方メートル以上）です。`,"kaisetsu":{"topic": "住宅金融支援機構・フラット35：証券化支援が主業務・全期間固定・各機関が金利設定", "basis": {"text": "住宅金融支援機構はフラット35（民間住宅ローンの証券化支援）が主業務。フラット35は全期間固定金利のみで変動金利の選択はできません。金利は各民間金融機関が独自に設定。返済期間は15年以上35年以下。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">フラット35のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">主な業務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">民間住宅ローンの証券化支援</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">金利</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全期間固定・各金融機関が設定</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">返済期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">15年以上35年以下</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">申込み先</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">民間金融機関</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10394,unit:'r_sorin',level:3,field:'rights',text:"共有物の管理行為（軽微でない変更以外）に関して2021年改正後の正しい説明はどれか。",opts:["全員の同意が必要", "持分価格の過半数で決定できる", "持分価格の4分の3以上で決定できる", "各共有者が単独でできる"],ans:1,exp:`共有物の管理に関する事項（変更でなく管理行為）は持分価格の過半数で決定できます（民法252条1項）。2021年の民法改正でこの点は明確化されました。なお変更（重大変更）は全員同意が必要です。`,"kaisetsu":{"topic": "相隣関係：竹木の根は自ら切除可・枝は原則所有者に・境界から50cmは慣習で変更可", "basis": {"text": "竹木の根が境界を越えたら自ら切除可（民法233条2項）。枝は原則として所有者に切除させます。建物の境界からの距離（50cm）は慣習・条例で変更可（民法234条・236条）。袋地通行権は有償が原則（民法212条）。", "example": ""}, "reason": {"text": "共有物の管理行為（軽微でない変更を除く利用・改良）は持分の価格の過半数で決定できます（民法252条1項）。2021年改正でこの規律が明確化されました。全員同意は変更行為の場合のみ必要です（民法251条）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相隣関係のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">事項</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">ルール</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">竹木の根（越境）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自ら切除可</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">竹木の枝（越境）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則：所有者に切除させる</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">境界距離（50cm）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">慣習・条例で変更可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">袋地通行権</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有償が原則</text></svg>", "choices": [{"label": "全員の同意が必要", "reason": "管理行為には全員同意は不要です（民法252条1項）。全員同意が必要なのは変更行為です（民法251条1項）。", "caution": "管理行為＝持分過半数。変更行為＝全員同意。"}, {"label": "持分価格の4分の3以上で決定できる", "reason": "管理行為の要件は持分価格の過半数です（民法252条1項）。4分の3という要件はありません。", "caution": ""}, {"label": "各共有者が単独でできる", "reason": "単独でできるのは保存行為のみです（民法252条5項）。管理行為は持分価格の過半数が必要です（同条1項）。", "caution": ""}], "summary": {"head": ["共有物の管理（2021年改正後）", "要件"], "rows": [["保存行為", "単独可（民法252条5項）"], ["管理行為", "持分価格の過半数（民法252条1項）"], ["変更行為（軽微）", "持分価格の過半数（民法251条1項ただし書）"], ["変更行為（重要）", "全員の同意（民法251条1項）"]]}}},
  {id:10395,unit:'l_kantoku',level:3,field:'law',text:"宅建業者が行った媒介において、物件の重要な事実を告げなかった場合に成立しうる責任として、誤っているものはどれか。",opts:["宅建業法47条違反による行政処分", "債務不履行（善管注意義務違反）に基づく損害賠償", "不法行為に基づく損害賠償", "刑事罰（詐欺罪等）の可能性"],ans:0,exp:`不利益となる重要な事実を故意に告げなかった場合の整理は、主として宅建業法第44条第1項第2号（禁止行為）や第35条・第40条と一体的に行います。一方、第47条は「虚偽の」重要事項説明等を規律する規定であり、条文対応として「47条違反による行政処分」とだけ括るのは不正確です（この選択肢が誤り）。媒介契約上の善管注意義務違反・不法行為による損害賠償や、事情によっては刑事責任が問題になり得る、という各記載は一般的に妥当です。`,"kaisetsu":{"topic": "監督処分：業務停止最長1年・大臣は全業者に指示可・指示違反→業務停止", "basis": {"text": "業務停止の最長期間は1年（宅建業法65条2項）。大臣は全業者（知事免許含む）に指示処分を行う権限があります。指示処分違反→業務停止、業務停止違反→免許取消という段階があります。", "example": ""}, "reason": {"text": "重要事実の不告知の禁止・処分は第44条第1項第2号等が中心です。第47条は虚偽の重要事項説明を規律するもので、単に「47条違反」とする説明は条文対応として誤りです。民事責任・刑事責任は事例により別途検討されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">監督処分のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">処分</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">最長1年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣の権限</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全業者に指示可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">指示処分違反</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止の対象</text></svg>", "choices": [{"label": "宅建業法47条違反による行政処分", "reason": "重要事項不告知は宅建業法47条違反として行政処分の対象になります（宅建業法65条等）。成立します。", "caution": ""}, {"label": "債務不履行（善管注意義務違反）に基づく損害賠償", "reason": "宅建業者の善管注意義務違反として債務不履行に基づく損害賠償請求が成立しえます（民法415条）。", "caution": ""}, {"label": "不法行為に基づく損害賠償", "reason": "故意・過失による不告知で損害を与えた場合、不法行為に基づく損害賠償請求が成立しえます（民法709条）。", "caution": ""}], "summary": {"head": ["重要事項不告知の責任", "根拠"], "rows": [["行政処分", "宅建業法47条違反→指示・業務停止・免許取消"], ["民事責任（債務不履行）", "民法415条"], ["民事責任（不法行為）", "民法709条"], ["刑事責任", "詐欺罪等（刑法246条）の可能性"]]}}},
  {id:10396,unit:'k_kukaku',level:3,field:'limit',text:"仮換地の使用収益ができない場合の補償（使用収益停止の場合）として正しいものはどれか。",opts:["補償は一切行われない", "従前の土地の使用収益権者に損失補償が行われる", "施行者が代わりに土地を管理する", "区分所有者に移転補償が行われる"],ans:1,exp:`仮換地の指定があった場合に、使用収益を開始できる日が指定されていないときや使用収益できない場合は、従前の土地の使用収益者に対して損失補償が行われます（土地区画整理法97条）。`,"kaisetsu":{"topic": "土地区画整理法：換地は公告翌日確定・仮換地は従前地使用不可・組合は2/3以上", "basis": {"text": "換地処分の公告翌日から換地が確定します（土地区画整理法104条）。仮換地の指定後は従前地を使用できなくなります（同法99条）。組合設立には土地所有者・借地権者の各2/3以上の同意が必要です。", "example": ""}, "reason": {"text": "仮換地の使用収益が停止された場合、従前の土地の使用収益権者に損失補償が行われます（土地区画整理法100条の2）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">土地区画整理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">換地の確定</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公告の翌日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮換地指定後</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従前地は使用不可（所有権は残る）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">組合設立</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各2/3以上の同意</text></svg>", "choices": [{"label": "補償は一切行われない", "reason": "使用収益停止の場合は損失補償が行われます（土地区画整理法100条の2）。", "caution": "使用収益停止：損失補償あり（土地区画整理法100条の2）。"}, {"label": "施行者が代わりに土地を管理する", "reason": "補償は損失補償として行われます（土地区画整理法100条の2）。", "caution": ""}, {"label": "区分所有者に移転補償が行われる", "reason": "移転補償ではなく損失補償が行われます（土地区画整理法100条の2）。", "caution": ""}], "summary": {"head": ["仮換地の使用収益停止と補償（土地区画整理法100条の2）", "内容"], "rows": [["補償", "損失補償が行われる"], ["対象者", "従前の土地の使用収益権者"]]}}},
  {id:10397,unit:'t_chika',level:3,field:'tax',text:"地価公示における標準地の正常価格について正しいものはどれか。",opts:["更地（建物等のない土地）としての価格", "現況（現在の状態）の価格", "開発後の価格", "最高価格で取引された価格"],ans:0,exp:`地価公示における正常価格は、土地について自由な取引が行われるとした場合に通常成立すると認められる価格です。標準地の鑑定評価は更地（建物等がない状態）として行われます（地価公示法2条・不動産鑑定評価基準）。`,"kaisetsu":{"topic": "地価公示・不動産鑑定評価：基準日は1月1日・土地鑑定委員会が実施・3手法", "basis": {"text": "地価公示の基準日は毎年1月1日で土地鑑定委員会（国土交通省）が実施（地価公示法）。公示価格は鑑定評価の規準となります（同法8条）。不動産鑑定評価の3手法：原価法・取引事例比較法・収益還元法。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">地価公示・鑑定評価</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">基準日</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">実施機関</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">土地鑑定委員会（国土交通省）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">鑑定評価の3手法</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原価法・取引事例比較法・収益還元法</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10398,unit:'r_baibai',level:3,field:'rights',text:"売買契約における危険負担（目的物が契約後・引渡し前に滅失した場合）について2020年改正後の正しい説明はどれか。",opts:["売主の責任として売主が危険を負担する", "引渡し前であれば常に売主が危険を負担する", "買主は反対給付（代金支払い）を拒絶できる", "危険は常に買主が負担する"],ans:2,exp:`2020年民法改正後、債務者の責めに帰することができない事由により債務の履行が不能となった場合、債権者（買主）は反対給付（代金支払い）を拒絶できます（民法536条1項）。引渡しが済んでいない場合は売主が危険を負担するのが原則です。`,"kaisetsu":{"topic": "売買：同時履行の抗弁権・解除は原則催告が必要・契約不適合責任", "basis": {"text": "売買では代金と引渡しは同時履行の関係（民法533条）。解除は原則として相当の期間を定めた催告後に行います（民法541条）。契約不適合責任の通知は知った時から1年以内（民法566条）。", "example": ""}, "reason": {"text": "2020年民法改正後、危険負担では買主が反対給付（代金支払い）を拒絶できます（民法536条1項）。改正前は「買主危険負担主義（自動消滅）」でしたが、改正後は実質的に「売主危険負担主義（履行拒絶権）」に転換しました。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">売買のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">同時履行</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金と引渡しは同時履行</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則として催告が必要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">契約不適合の通知</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から1年以内</text></svg>", "choices": [{"label": "売主の責任として売主が危険を負担する", "reason": "危険負担は「誰が損失を負うか」という問題です。改正後の「履行拒絶権」は買主が代金を払わなくてよい（売主が損失を負う）という実質的な効果をもたらします。ただし「売主の責任」という表現は厳密ではありません。", "caution": ""}, {"label": "引渡し前であれば常に売主が危険を負担する", "reason": "売主に帰責事由がある場合は危険負担ではなく債務不履行の問題です。また引渡し後は買主危険（民法567条）になります。「引渡し前は常に売主」は不正確です。", "caution": ""}, {"label": "危険は常に買主が負担する", "reason": "改正前は買主危険負担主義でしたが、改正後は履行拒絶権により実質的に売主が危険を負担します（民法536条1項）。「常に買主」は誤りです。", "caution": ""}], "summary": {"head": ["危険負担の改正", "改正前（旧民法534条）", "改正後（民法536条）"], "rows": [["特定物売買", "買主危険主義（自動消滅）", "履行拒絶権（実質売主主義）"], ["滅失時の買主の対応", "代金全額支払い義務", "履行拒絶・解除が可能"]]}}},
  {id:10399,unit:"l_kantoku",level:3,field:"law",text:"宅建業者が相手方に不利益となる事実を故意に告げなかった場合の制裁として、誤っているものはどれか。",opts:["都道府県知事または国交大臣による業務停止処分","免許取消処分の対象となりうる","損害賠償請求の対象となる","故意でも過失でも同様の処分となる"],ans:3,exp:"不利益となる事実を故意に告げなかった場合は宅建業法第44条第1項第2号等に該当し得ます（重要事項説明・第35条・第40条と一体的に整理されます）。過失による不告知との区別や処分の評価は異なることがあり、「故意でも過失でも同様の処分となる」とは限りません。したがって当該記述は誤りです。なお行政処分（業務停止・免許取消）と民事上の損害賠償は別途成立しえます。","kaisetsu":{"topic":"宅建業法47条：重要事実の不告知","basis":{"text":"宅建業者は、相手方等の判断に重要な影響を及ぼす事項について、故意に事実を告げず、または不実のことを告げる行為をしてはなりません（宅建業法47条）。違反した場合は行政処分や罰則の対象となり得ます。","example":"取引物件に重大な不利益事実があることを知りながら、契約を成立させるためにあえて告げなかった場合、宅建業法47条違反が問題になります。"},"reason":{"text":"宅建業法47条の重要事実不告知は故意の不告知が問題です。「故意でも過失でも同様の処分となる」とする記述は、故意不告知の規制構造を無視しており誤りです。過失による説明不足は別途、重要事項説明義務違反等として問題になり得ますが、故意不告知と同様に扱うとはいえません。"},"svg":"","choices":[{"label":"宅建業法47条違反による行政処分","reason":"重要事実の故意不告知は宅建業法47条違反となり、行政処分の対象となり得ます。","caution":""},{"label":"業務停止処分の対象となり得る","reason":"宅建業法違反として業務停止処分等の対象となる可能性があります。","caution":""},{"label":"罰則の対象となり得る","reason":"宅建業法47条違反は罰則の対象となり得ます。","caution":""}],"summary":{"head":["行為","扱い"],"rows":[["故意の重要事実不告知","宅建業法47条違反"],["不実告知","宅建業法47条違反"],["制裁","行政処分・罰則の対象となり得る"]]}}},
  {id:10400,unit:'r_ishi',level:3,field:'rights',text:"Aが自分の土地をBに売却した後、錯誤を理由に取消しを主張した。取消し前にBから土地を買ったCがいる場合の法律関係として正しいものはどれか（AB間の意思表示は錯誤取消しの要件を満たしているものとする）。",opts:["AはCに対して常に取消しを対抗できる", "取消し前のCは保護されず常にAが勝つ", "取消し前に現れたCが善意無過失であれば、AはCに取消しを対抗できない", "錯誤取消しは絶対的無効であるためCの善意は関係ない"],ans:2,exp:`錯誤取消し前に現れた第三者との関係は対抗問題となり、取消し前の第三者が善意無過失であればAはその第三者に取消しを対抗できません（民法95条4項）。これは詐欺取消しと同様の規律です。`,"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失保護）・通謀虚偽表示（無効・善意保護）。", "example": ""}, "reason": {"text": "錯誤取消し前に現れた第三者との関係は対抗問題です（民法95条4項）。取消し前に善意無過失でBから土地を取得したCは保護されます。これは詐欺取消しと同様の規律で、取引の安全を図るためです。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "AはCに対して常に取消しを対抗できる", "reason": "取消し前に現れた善意無過失の第三者Cには取消しを対抗できません（民法95条4項）。常に対抗できるわけではありません。", "caution": "取消し前の第三者：善意無過失なら保護。取消し後の第三者：対抗問題（登記の先後）。"}, {"label": "取消し前のCは保護されず常にAが勝つ", "reason": "取消し前に現れた善意無過失の第三者は民法95条4項により保護されます。Aが常に勝つわけではありません。", "caution": ""}, {"label": "錯誤取消しは絶対的無効であるためCの善意は関係ない", "reason": "2020年改正前は錯誤は無効でしたが、改正後は取消しとなりました（民法95条1項）。絶対的無効ではなく取消しであるため、第三者保護規定（民法95条4項）が適用されます。", "caution": "2020年改正：錯誤は「無効」→「取消し」に変更されました。"}], "summary": {"head": ["意思表示の瑕疵", "取消し前の第三者保護", "取消し後の第三者"], "rows": [["錯誤取消し", "善意無過失なら保護（民法95条4項）", "対抗問題（登記の先後）"], ["詐欺取消し", "善意無過失なら保護（民法96条3項）", "対抗問題（登記の先後）"], ["強迫取消し", "保護なし（全員に対抗可）", "対抗問題（登記の先後）"]]}}},
  {id:10401,unit:'r_dairi',level:3,field:'rights',text:"表見代理が成立した場合の法律効果として正しいものはどれか。",opts:["無権代理人が個人として責任を負う", "本人に契約の効果が帰属する", "契約は無効となる", "相手方のみが選択権を持つ"],ans:1,exp:`表見代理が成立した場合、本人が代理人の行為を授権したものとして扱われ、本人に法律効果が帰属します（民法109条・110条・112条）。相手方は表見代理の主張か無権代理人への責任追及かを選択できます。`,"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護します。", "example": ""}, "reason": {"text": "表見代理が成立した場合、代理行為の効果は有権代理と同様に本人に帰属します（民法109条・110条・112条）。相手方は本人に対して契約の履行を請求できます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "無権代理人が個人として責任を負う", "reason": "表見代理が成立した場合は本人に効果が帰属します。無権代理人の個人責任（民法117条）は表見代理が成立しない場合の話です。", "caution": "表見代理成立→本人責任。表見代理不成立→無権代理人責任（民法117条）。"}, {"label": "契約は無効となる", "reason": "表見代理が成立した場合、契約は有効として本人に効果が帰属します。無効にはなりません。", "caution": ""}, {"label": "相手方のみが選択権を持つ", "reason": "表見代理が成立した場合に相手方が選択権を持つ場面（表見代理と無権代理人責任の選択）はありますが、「相手方のみが選択権を持つ」という命題は問題の正解を誤解させます。", "caution": ""}], "summary": {"head": ["場合分け", "効果"], "rows": [["表見代理が成立", "本人に契約の効果帰属（本人が責任を負う）"], ["表見代理が不成立・本人が追認", "本人に効果帰属"], ["表見代理が不成立・本人が追認しない", "無権代理人が責任（民法117条）"]]}}},
  {id:10402,unit:'r_jiko',level:3,field:'rights',text:"消滅時効の援用の法的性質として通説・判例が採用する見解はどれか。",opts:["時効は援用がなくても当然に効力が生じる", "時効の援用は確認的効果があるにすぎない", "時効の援用によって初めて効力が生じる（援用があって初めて時効の効果が確定）", "時効の援用は裁判上のみ有効"],ans:2,exp:`通説・判例は援用により時効の効果が確定するという考え（確定効果説）を採用しています（民法145条）。援用がなくても時効完成の事実はありますが、当事者が援用して初めてその効果が確定します。`,"kaisetsu":{"topic": "消滅時効：知った時から5年または行使可能時から10年", "basis": {"text": "消滅時効は「知った時から5年」または「行使可能時から10年」のいずれか早い方で完成します（民法166条）。時効は援用して初めて効力が発生します（民法145条）。承認は更新事由です（民法152条）。", "example": ""}, "reason": {"text": "時効の援用の法的性質について、通説・判例は「停止条件説」を採用しています。時効の効果は援用によって初めて確定的に生じます（民法145条）。これにより援用権者が援用するかどうかを選択できる柔軟性が確保されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">期間</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人身損害</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年または20年</text></svg>", "choices": [{"label": "時効は援用がなくても当然に効力が生じる", "reason": "時効の効果は援用によって生じます（民法145条・停止条件説）。援用なしに当然に効力が生じる説（確定効果説）は通説ではありません。", "caution": ""}, {"label": "時効の援用は確認的効果があるにすぎない", "reason": "確認的効果説は時効の効果が当初から当然に生じており援用は確認にすぎないとしますが、通説・判例は停止条件説（援用により初めて効力発生）です。", "caution": ""}, {"label": "時効の援用は裁判上のみ有効", "reason": "時効の援用は裁判外でもできます（民法145条）。口頭・書面・裁判上・裁判外のいずれでも可能です。", "caution": ""}], "summary": {"head": ["説", "内容"], "rows": [["確定効果説", "時効完成と同時に当然に効力発生（援用は確認のみ）"], ["停止条件説（通説・判例）", "援用があって初めて効力確定（民法145条）"], ["援用の方法", "裁判上・裁判外いずれも可、書面不要"]]}}},
  {id:10403,unit:'r_bukken',level:3,field:'rights',text:"背信的悪意者の第三者からさらに転得した者が善意の場合の法律関係として正しいものはどれか。",opts:["善意の転得者は常に保護される", "転得者が善意であっても背信的悪意者から取得した場合は保護されない", "転得者の保護は登記の先後のみで決まる", "転得者は必ず悪意とみなされる"],ans:0,exp:`背信的悪意者からの転得者については、転得者自身が善意であれば保護されるというのが判例の立場です（最判昭和43年8月2日）。背信的悪意者自身は保護されませんが、そこから取得した善意の転得者は保護されます。`,"kaisetsu":{"topic": "物権変動：登記が対抗要件・不法占拠者には登記不要", "basis": {"text": "不動産の物権変動は登記が第三者への対抗要件です（民法177条）。不法占拠者には登記なく対抗できます（判例）。建物賃借権は引渡しが対抗要件です（借地借家法31条）。", "example": ""}, "reason": {"text": "背信的悪意者から転得した善意の第三者は保護されます（判例・最判昭和43年8月2日）。背信的悪意者本人は保護されませんが、そこから取得した善意者まで遡って保護しないとすると取引の安全が著しく害されるため、善意の転得者は保護されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">物権変動の対抗要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対抗要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">二重譲渡</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先に登記した者が優先</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不法占拠者</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記不要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物賃借権</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡し</text></svg>", "choices": [{"label": "転得者が善意であっても背信的悪意者から取得した場合は保護されない", "reason": "判例は背信的悪意者から取得した善意の転得者を保護しています（最判昭和43年8月2日）。背信的悪意者の「汚染」は善意の転得者には及びません。", "caution": "背信的悪意者自身は保護されない≠その者から取得した善意者も保護されない。"}, {"label": "転得者の保護は登記の先後のみで決まる", "reason": "善意の転得者の保護は登記の先後だけでなく、転得者の善意・悪意も問題になります（判例）。", "caution": ""}, {"label": "転得者は必ず悪意とみなされる", "reason": "転得者の悪意・善意は実際の認識によります。背信的悪意者から取得したという事実だけで悪意とみなされるわけではありません。", "caution": ""}], "summary": {"head": ["転得者の態様", "保護の有無"], "rows": [["善意の転得者", "保護される（判例）"], ["悪意の転得者", "保護されない"], ["背信的悪意者本人", "保護されない（登記なしで対抗可）"]]}}},
  {id:10404,unit:'r_tanpo',level:3,field:'rights',text:"物上代位権の行使における差押えの趣旨として判例が示すものはどれか。",opts:["目的債権の存在を公示するため", "二重払いを防止し特定性を保持するため", "抵当権者の優先権を確保するため", "差押えは形式的要件にすぎない"],ans:1,exp:`物上代位における差押えの趣旨は、目的物の価値代替物（賃料等）が第三者に支払われる前に差し押さえることで二重払いを防ぎ、物上代位権の目的を特定するためです（判例）。差押えは実質的要件です。`,"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権（民法369条）。質権は占有の移転が必要。先取特権は法定担保物権（当然に成立）。農地への抵当権設定自体は、通常、農地法3条の許可対象ではありません。", "example": ""}, "reason": {"text": "物上代位における差押えの趣旨について、判例は「弁済者の二重払い防止と目的債権の特定性の保持」のためと説明しています（最判平成10年）。これにより物上代位の目的物が特定され、第三者への対抗が可能になります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "目的債権の存在を公示するため", "reason": "公示は差押えの主たる趣旨ではありません。判例は二重払い防止と特定性保持のためとしています（最判平成10年）。", "caution": ""}, {"label": "抵当権者の優先権を確保するため", "reason": "抵当権者の優先権は抵当権設定・登記時にすでに確保されています。差押えは二重払い防止と特定性保持のためです（判例）。", "caution": ""}, {"label": "差押えは形式的要件にすぎない", "reason": "差押えは実質的な要件です（民法304条1項但書）。差押えがなければ物上代位権を行使できません。", "caution": ""}], "summary": {"head": ["物上代位の差押えの趣旨（判例）", "内容"], "rows": [["二重払いの防止", "債務者（設定者）が既に弁済を受けていても抵当権者が追及できなくなることを防ぐ"], ["特定性の保持", "代金・賃料等の目的物を特定することで第三者への対抗を可能にする"], ["結論", "払渡し前の差押えが物上代位の要件（民法304条1項但書）"]]}}},
  {id:10405,unit:'r_saikensoron',level:3,field:'rights',text:"詐害行為取消権（民法424条）の要件として誤っているものはどれか。",opts:["債務者が債権者を害することを知ってした行為", "受益者が詐害の事実を知っていること（悪意）", "債権者に現在の債権（被保全債権）があること", "債務者が既に無資力であること（行為前からの無資力も含む）"],ans:3,exp:`詐害行為取消権は債務者が詐害行為時に無資力であること、または詐害行為によって無資力になったことが要件です（民法424条）。行為前から無資力であったことは要件ではなく、行為によって無資力になれば足ります。`,"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要（民法446条2項）。連帯保証人は催告・検索の抗弁権なし（民法454条）。債権譲渡の第三者対抗は確定日付ある証書による通知・承諾（民法467条2項）。相殺の絶対的効力：弁済・更改・相殺。", "example": ""}, "reason": {"text": "詐害行為取消権（民法424条）の要件は①被保全債権の存在、②債務者の詐害行為（債権者を害すると知りながらした財産処分行為）、③受益者の悪意です。「行為前からの無資力」は要件ではなく、行為によって無資力になった（または無資力が深刻化した）ことが要件です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">催告・検索の抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text></svg>", "choices": [{"label": "債務者が債権者を害することを知ってした行為", "reason": "詐害行為取消権の要件です（民法424条1項）。誤りではありません。", "caution": ""}, {"label": "受益者が詐害の事実を知っていること（悪意）", "reason": "受益者の悪意は要件です（民法424条1項）。誤りではありません。", "caution": ""}, {"label": "債権者に現在の債権（被保全債権）があること", "reason": "被保全債権の存在は要件です（民法424条1項）。誤りではありません。", "caution": ""}], "summary": {"head": ["詐害行為取消権の要件（民法424条）", "内容"], "rows": [["①被保全債権", "詐害行為前に成立した債権（原則）"], ["②詐害行為", "債務者が債権者を害することを知った財産処分行為"], ["③詐害意思", "債務者が詐害を知っていること"], ["④受益者の悪意", "受益者が詐害の事実を知っていること"], ["要件でないもの", "行為前からの無資力は不要（行為により無資力化が要件）"]]}}},
  {id:10406,unit:'r_baibai',level:3,field:'rights',text:"売買の目的物に抵当権が設定されており、競売により買主が所有権を失った場合の法律関係として正しいものはどれか。",opts:["買主は代金の返還のみを請求できる", "買主は解除・損害賠償・費用償還等を請求できる", "買主に帰責事由があれば何も請求できない", "売主の担保責任は負担のある物の売買では生じない"],ans:1,exp:`売買の目的物に抵当権等が設定されており買主が権利を失った場合、売主は担保責任を負い買主は解除・損害賠償・費用償還等を請求できます（民法565条）。`,"kaisetsu":{"topic": "売買：同時履行の抗弁権・解除は原則催告が必要・契約不適合責任", "basis": {"text": "売買では代金と引渡しは同時履行の関係（民法533条）。解除は原則として相当の期間を定めた催告後に行います（民法541条）。契約不適合責任の通知は知った時から1年以内（民法566条）。", "example": ""}, "reason": {"text": "売買目的物に抵当権が設定されており競売により買主が所有権を失った場合（権利の不適合）、買主は売主に対して解除・損害賠償・費用償還等を請求できます（民法565条・566条・563条等）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">売買のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">同時履行</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金と引渡しは同時履行</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則として催告が必要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">契約不適合の通知</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から1年以内</text></svg>", "choices": [{"label": "買主は代金の返還のみを請求できる", "reason": "解除による代金返還のほか、損害賠償・費用償還等も請求できます（民法565条・415条）。「返還のみ」は誤りです。", "caution": ""}, {"label": "買主に帰責事由があれば何も請求できない", "reason": "抵当権の存在は売主の権利の担保責任の問題であり、買主の帰責事由とは関係なく売主に責任があります（民法565条）。", "caution": ""}, {"label": "売主の担保責任は負担のある物の売買では生じない", "reason": "負担のある物を売却した場合（抵当権等）でも売主は担保責任を負います（民法565条）。「生じない」は誤りです。", "caution": ""}], "summary": {"head": ["権利の不適合（抵当権等）", "内容"], "rows": [["根拠", "民法565条（権利の不適合）"], ["買主の手段", "追完請求・代金減額・損害賠償・解除"], ["通知期限", "一般消滅時効のみ（1年の通知期限なし）"]]}}},
  {id:10407,unit:'r_chinshaku',level:3,field:'rights',text:"賃借権の無断転貸と解除に関する判例の立場として正しいものはどれか。",opts:["無断転貸があれば直ちに解除できる", "無断転貸があっても信頼関係が破壊されていなければ解除できない", "無断転貸の事実があれば信頼関係破壊は推定される", "賃貸人の承諾なき転貸は常に無効"],ans:1,exp:`賃借人が無断転貸をした場合でも、それが賃貸人に対する背信的行為と認めるに足りない特段の事情がある場合は解除できないとするのが判例の立場（信頼関係破壊理論）です（最判昭和28年9月25日）。`,"kaisetsu":{"topic": "賃貸借：通常損耗は原状回復に含まれない・有益費は終了時に請求・賃料増額は正当事由が必要", "basis": {"text": "賃貸借終了時の原状回復義務に通常使用による損耗（壁の日焼け等）は含まれません（民法621条）。必要費は直ちに、有益費は終了時の請求が原則。更新拒絶には正当事由が必要（借地借家法28条）。", "example": ""}, "reason": {"text": "無断転貸は解除事由となりますが（民法612条2項）、判例は「信頼関係が破壊されていない特段の事情がある場合は解除できない」としています（信頼関係破壊の法理）。形式的な要件充足だけで解除を認めない柔軟な解釈です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">賃貸借のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通常損耗</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原状回復に含まれない</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要費</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直ちに請求可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有益費</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸借終了時に請求</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">更新拒絶</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当事由が必要</text></svg>", "choices": [{"label": "無断転貸があれば直ちに解除できる", "reason": "判例は信頼関係破壊の法理により、特段の事情がある場合は解除できないとしています（判例）。直ちに解除できるわけではありません。", "caution": "形式的な無断転貸でも信頼関係が破壊されていなければ解除不可（判例）。"}, {"label": "無断転貸の事実があれば信頼関係破壊は推定される", "reason": "信頼関係破壊は推定されず、具体的な事実関係から判断します（判例）。", "caution": ""}, {"label": "賃貸人の承諾なき転貸は常に無効", "reason": "無断転貸は賃借人と転借人間では有効です。ただし賃貸人は解除できる場合があります（民法612条2項）。", "caution": ""}], "summary": {"head": ["無断転貸と解除", "内容"], "rows": [["原則", "解除事由となる（民法612条2項）"], ["例外（判例）", "信頼関係を破壊しない特段の事情があれば解除不可"], ["特段の事情の例", "親子間での転貸で実質的に同一視できる場合等"], ["無断転貸の効力", "賃借人・転借人間では有効（賃貸人には対抗不可）"]]}}},
  {id:10408,unit:'r_souzoku',level:3,field:'rights',text:"遺産分割協議が成立した後に被相続人の別の隠れた財産が発見された場合の取扱いとして正しいものはどれか。",opts:["当初の協議がすべて無効となる", "発見された財産については改めて分割協議を行う必要がある", "自動的に均等分割される", "遺言があれば遺言に従う必要があるが、なければ長男が相続する"],ans:1,exp:`遺産分割協議成立後に新たな遺産が発見された場合、その財産については別途改めて遺産分割協議を行う必要があります。当初の協議は成立した範囲で有効です。`,"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2・遺産分割は全員合意", "basis": {"text": "配偶者と子は各1/2（民法900条）。放棄は3か月以内に家裁へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2（民法1042条）。兄弟姉妹に遺留分はなし。遺産分割協議は全員合意が必要。", "example": ""}, "reason": {"text": "遺産分割協議後に新たな遺産が発見された場合、発見された財産については改めて分割協議が必要です（判例）。当初の協議は発見された財産には効力が及ばないためです。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "当初の協議がすべて無効となる", "reason": "後から財産が発見されても当初の分割協議全体が無効になるわけではありません。発見された財産についてのみ改めて協議が必要です。", "caution": ""}, {"label": "自動的に均等分割される", "reason": "新たに発見された財産が自動的に均等分割されることはありません。相続人全員で改めて協議が必要です。", "caution": ""}, {"label": "遺言があれば遺言に従う必要があるが、なければ長男が相続する", "reason": "長男が優先されるという規定はありません（民法）。法定相続分または相続人全員の協議で決まります。", "caution": ""}], "summary": {"head": ["後発発見財産の処理", "内容"], "rows": [["当初の協議", "有効のまま（全体無効とはならない）"], ["発見された財産", "改めて相続人全員で協議が必要"], ["遺言がある場合", "遺言の内容に従う"]]}}},
  {id:10409,unit:'r_fuhoko',level:3,field:'rights',text:"工作物の設置・保存の瑕疵による損害について所有者の責任の性質として正しいものはどれか。",opts:["過失責任（過失なければ免責）", "無過失責任（免責不可）", "軽過失があれば免責される", "故意のみが責任の要件"],ans:1,exp:`土地の工作物の設置・保存の瑕疵による損害について、占有者は過失なければ免責されますが（民法717条1項但書）、所有者は無過失責任を負い、免責されません（民法717条1項本文・2項）。`,"kaisetsu":{"topic": "不法行為：故意または過失が必要・使用者責任・工作物責任", "basis": {"text": "不法行為は故意または過失が必要です（民法709条）。使用者は被用者の職務上の不法行為について責任を負います（民法715条）。工作物の所有者は無過失責任（占有者が免責された場合）（民法717条）。", "example": ""}, "reason": {"text": "工作物責任（民法717条）において所有者は無過失責任を負います（同条1項後段）。占有者は過失責任（損害防止に必要な注意をした場合は免責）ですが、所有者は免責されません。被害者保護のための制度です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不法行為のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般不法行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">故意または過失が必要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">使用者責任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">被用者への求償可（信義則上制限）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">工作物の所有者責任</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無過失責任（占有者が免責された場合）</text></svg>", "choices": [{"label": "過失責任（過失なければ免責）", "reason": "所有者の責任は無過失責任です（民法717条1項後段）。過失なしで免責されるのは占有者です（同条1項ただし書）。", "caution": "工作物責任：占有者＝過失責任、所有者＝無過失責任。"}, {"label": "軽過失があれば免責される", "reason": "所有者は無過失責任であり、軽過失で免責されるという規定はありません（民法717条1項後段）。", "caution": ""}, {"label": "故意のみが責任の要件", "reason": "所有者の工作物責任は故意・過失の有無に関係なく（無過失責任）成立します（民法717条1項後段）。", "caution": ""}], "summary": {"head": ["工作物責任（民法717条）", "責任の性質"], "rows": [["占有者（第一次責任）", "過失責任（注意を尽くせば免責可）"], ["所有者（第二次責任）", "無過失責任（免責不可）"], ["被害者", "損害防止の注意をした占有者が免責→所有者が責任"], ["求償", "所有者→設計・施工業者等への求償可"]]}}},
  {id:10410,unit:'r_shakuchi',level:3,field:'rights',text:"建物の朽廃（自然に朽ちること）と借地権の消滅の関係として正しいものはどれか。",opts:["建物が朽廃しても借地権は消滅しない", "建物が朽廃すれば借地権は当然消滅する", "朽廃前に再築すれば借地権は存続する", "建物の朽廃は普通借地権の消滅事由とはされていない"],ans:3,exp:`借地借家法では建物の朽廃は普通借地権の消滅事由とされていません（借地借家法3条〜8条）。ただし建物が滅失した場合には再築の手続きを適切に行わないと存続期間が変わることがあります。`,"kaisetsu":{"topic": "借地権：最短30年・建物登記で対抗・建物滅失でも消滅せず・定期借地権は3種類", "basis": {"text": "普通借地権の最短存続期間は30年（借地借家法3条）。借地上の建物の自己名義登記が対抗要件（同法10条）。建物が滅失しても借地権は消滅しません。定期借地権は①一般（50年以上）②事業用（10〜50年未満）③建物譲渡特約（30年以上）の3種類。", "example": ""}, "reason": {"text": "2003年借地借家法改正により、建物の朽廃は普通借地権の消滅事由から削除されました（旧法では朽廃による消滅が規定されていました）。現行法では建物が朽廃しても借地権は消滅せず、存続期間の到来や合意解除等によって消滅します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">借地権のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">最短存続期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">対抗要件</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借地上の建物の自己名義登記</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物滅失</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借地権は消滅しない</text></svg>", "choices": [{"label": "建物が朽廃しても借地権は消滅しない", "reason": "現行借地借家法では建物の朽廃は借地権の消滅事由とされていません（借地借家法8条参照）。この選択肢の内容は正しいですが、設問の正解は「普通借地権の消滅事由とはされていない」という選択肢4です。", "caution": ""}, {"label": "建物が朽廃すれば借地権は当然消滅する", "reason": "現行借地借家法では建物の朽廃は消滅事由ではありません（旧借地法では朽廃消滅がありましたが廃止）。", "caution": "旧法：朽廃で消滅あり。現行法：朽廃は消滅事由でない。"}, {"label": "朽廃前に再築すれば借地権は存続する", "reason": "朽廃前の再築は借地権継続のための要件ではありません（現行法では朽廃自体が消滅事由でない）。", "caution": ""}], "summary": {"head": ["借地権の消滅事由（現行借地借家法）", "内容"], "rows": [["存続期間の満了", "更新がなければ消滅"], ["合意解除", "当事者の合意"], ["放棄", "借地権の放棄"], ["建物の朽廃", "消滅事由ではない（現行法）"]]}}},
  {id:10411,unit:'r_kukku',level:3,field:'rights',text:"管理組合法人の成立要件として正しいものはどれか。",opts:["区分所有者の過半数の賛成で成立する", "区分所有者及び議決権の各4分の3以上の集会決議と登記が必要", "区分所有者が30人以上いることと所定の決議・登記が必要", "区分所有者全員の同意が必要"],ans:2,exp:`管理組合が法人となるには区分所有者が30人以上いることを前提に、区分所有者及び議決権の各4分の3以上の集会決議を経て法人の登記をする必要があります（区分所有法47条）。`,"kaisetsu":{"topic": "区分所有法：重大変更は3/4以上・建替えは4/5以上・管理組合法人は30人以上", "basis": {"text": "共用部分の重大変更は区分所有者・議決権の各3/4以上の特別決議が必要（区分所有法17条）。建替えは4/5以上（同法62条）。管理組合法人の設立は3/4以上かつ区分所有者30人以上（同法47条）。専有部分と共有持分は分離処分不可（同法15条）。", "example": ""}, "reason": {"text": "管理組合法人の成立要件は①区分所有者が30人以上、②区分所有者および議決権の各3/4以上の集会決議、③登記です（区分所有法47条1項・2項）。法人格を取得することで組合名義での取引や訴訟が可能になります。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">区分所有法の決議要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">事項</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">普通決議</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">過半数</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">重大変更・規約変更</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3/4以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">管理組合法人</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3/4以上（30人以上）</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建替え</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4/5以上</text></svg>", "choices": [{"label": "区分所有者の過半数の賛成で成立する", "reason": "管理組合法人の成立には3/4以上の集会決議が必要です（区分所有法47条1項）。過半数では足りません。", "caution": ""}, {"label": "区分所有者及び議決権の各4分の3以上の集会決議と登記が必要", "reason": "区分所有者が30人以上という要件も必要です（区分所有法47条1項）。設問の選択肢3がより完全な正解です。", "caution": ""}, {"label": "区分所有者全員の同意が必要", "reason": "全員同意は不要です。3/4以上の集会決議と登記で成立します（区分所有法47条1項・2項）。", "caution": ""}], "summary": {"head": ["管理組合法人の成立要件", "内容"], "rows": [["区分所有者数", "30人以上（区分所有法47条1項）"], ["集会決議", "3/4以上の特別決議"], ["登記", "法人成立の要件"], ["効果", "組合名義での契約・訴訟等が可能"]]}}},
  {id:10412,unit:'r_touki',level:3,field:'rights',text:"登記の公信力がないことの意味として正しいものはどれか。",opts:["登記がなければ権利変動が生じない", "登記を信頼して取引した者でも、登記名義人が真の権利者でなければ権利を取得できないことがある", "登記があれば真の権利者として完全に保護される", "登記には推定力があるため公信力と同じ効果がある"],ans:1,exp:`日本の不動産登記には公信力がありません。登記を信頼して取引した者でも、登記名義人が真の権利者でなければ権利を取得できない場合があります（善意の第三者も保護されないことがある）。これは民法94条2項の類推適用等で例外的に保護される場合があります。`,"kaisetsu":{"topic": "不動産登記：権利登記は共同申請・仮登記は順位保全・建物滅失は1か月以内", "basis": {"text": "権利に関する登記は原則として登記権利者と登記義務者が共同申請します（不動産登記法60条）。仮登記は順位保全機能があるが完全な対抗力は本登記後です。建物滅失登記の申請義務は1か月以内（同法57条）。", "example": ""}, "reason": {"text": "日本の不動産登記には公信力がありません（通説・判例）。登記を信頼して取引しても、登記名義人が真の権利者でなかった場合は権利を取得できないことがあります。これは動産の即時取得（公信の原則あり）と大きく異なる点です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産登記のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利登記</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則として共同申請</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮登記</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">順位保全（対抗力は本登記後）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物滅失登記</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1か月以内</text></svg>", "choices": [{"label": "登記がなければ権利変動が生じない", "reason": "権利変動（所有権移転等）は当事者間では登記なしに生じます。登記は第三者への対抗要件であり、権利変動の成立要件ではありません（民法176条・177条）。", "caution": ""}, {"label": "登記があれば真の権利者として完全に保護される", "reason": "登記には公信力がないため、登記があっても真の権利者でなければ完全に保護されるわけではありません。真の権利者から権利を主張される場合があります。", "caution": "登記の推定力（権利の存在を推定）と公信力（登記を信頼した者を保護）は別物です。"}, {"label": "登記には推定力があるため公信力と同じ効果がある", "reason": "登記には推定力（登記通りの権利関係が存在すると推定）はありますが、公信力（登記を信頼した者を保護）はありません。推定力と公信力は異なります。", "caution": ""}], "summary": {"head": ["登記の効力比較", "内容"], "rows": [["対抗力", "第三者への権利変動の対抗（民法177条）"], ["推定力", "登記通りの権利関係の存在を推定"], ["公信力", "なし（日本の不動産登記）"], ["動産との違い", "動産は即時取得（公信の原則あり）、不動産は公信力なし"]]}}},
  {id:10413,unit:'r_sorin',level:3,field:'rights',text:"共有物の分割請求に対して裁判所が命じられる分割方法として認められないものはどれか。",opts:["現物分割", "価格賠償（代償分割）", "競売による分割（換価分割）", "強制的な第三者への売却"],ans:3,exp:`裁判所による共有物分割の方法は①現物分割②価格賠償（代償分割）③競売による分割（換価分割）の3種類です（民法258条2項・3項）。特定の第三者への強制売却という手段は認められていません。`,"kaisetsu":{"topic": "相隣関係：竹木の根は自ら切除可・枝は原則所有者に・境界から50cmは慣習で変更可", "basis": {"text": "竹木の根が境界を越えたら自ら切除可（民法233条2項）。枝は原則として所有者に切除させます。建物の境界からの距離（50cm）は慣習・条例で変更可（民法234条・236条）。袋地通行権は有償が原則（民法212条）。", "example": ""}, "reason": {"text": "裁判所が命じられる共有物の分割方法は現物分割・価格賠償（代償分割）・競売による代金分割の3種類です（民法258条2項・3項）。「第三者への強制譲渡」という方法は民法上認められていません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相隣関係のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">事項</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">ルール</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">竹木の根（越境）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自ら切除可</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">竹木の枝（越境）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則：所有者に切除させる</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">境界距離（50cm）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">慣習・条例で変更可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">袋地通行権</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有償が原則</text></svg>", "choices": [{"label": "現物分割", "reason": "現物分割は認められています（民法258条2項1号）。", "caution": ""}, {"label": "価格賠償（代償分割）", "reason": "価格賠償（代償分割）は認められています（民法258条2項2号）。", "caution": ""}, {"label": "競売による分割（換価分割）", "reason": "競売による分割は認められています（民法258条3項）。", "caution": ""}], "summary": {"head": ["共有物分割の方法（民法258条）", "内容"], "rows": [["現物分割", "物理的に分けて各自に帰属"], ["価格賠償（代償分割）", "一人が全部取得・他に金銭補償"], ["競売（換価分割）", "競売して代金を持分割合で分配"], ["認められない方法", "第三者への強制譲渡・一方的な処分"]]}}},
  {id:10414,unit:'l_menkyo',level:3,field:'law',text:"宅建業者が一方的に免許を返納した場合の効果として正しいものはどれか。",opts:["返納と同時に免許は失効する", "返納しても免許は有効期間中有効", "返納の届出をした時点で免許が失効する", "返納後も進行中の取引は継続して処理できる"],ans:2,exp:`宅建業者が免許証を返納する届出をした時点で免許が失効します（廃業等に準じた処理）。ただし返納後に進行中の取引の処理については一定の制限があり、新規取引はできません。`,"kaisetsu":{"topic": "宅建業免許：知事・大臣免許の区別・有効期間5年・欠格事由は5年", "basis": {"text": "1都道府県→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間。2020年改正で成年被後見人の欠格条項は廃止。", "example": ""}, "reason": {"text": "宅建業者が免許を返納（廃業届）した場合、返納の届出をした時点で免許が失効します（宅建業法11条1項5号・76条1項）。廃業に伴う後始末（未完了取引の処理）については一定のルールがあります。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（2020年改正で成年被後見人は廃止）</text></svg>", "choices": [{"label": "返納と同時に免許は失効する", "reason": "免許の失効は返納届出の時点です（宅建業法76条1項）。「返納と同時」という表現は選択肢3と実質同じですが、「届出をした時点」と「返納と同時」で微妙に表現が異なります。", "caution": ""}, {"label": "返納しても免許は有効期間中有効", "reason": "返納届出をすれば免許は失効します（宅建業法11条1項5号）。有効期間中でも失効します。", "caution": ""}, {"label": "返納後も進行中の取引は継続して処理できる", "reason": "廃業後の未完了取引については宅建業者としての義務が残る場合がありますが（宅建業法76条）、「継続して処理できる」という説明は不正確です。", "caution": ""}], "summary": {"head": ["免許の失効事由", "内容"], "rows": [["廃業届（返納）", "届出時点で失効（宅建業法11条）"], ["有効期間満了", "期間満了で失効"], ["免許取消処分", "取消時点で失効"], ["死亡・解散", "届出時点で失効"]]}}},
  {id:10415,unit:'l_takkenshi',level:3,field:'law',text:"宅建士が登録消除後に再登録を申請できる最短の期間として正しいものはどれか。",opts:["1年", "3年", "5年", "制限なし"],ans:2,exp:`登録消除処分（不正手段での登録・業務停止違反等）を受けた場合、処分の日から5年を経過しなければ新たな登録を受けることができません（宅建業法18条1項5号）。`,"kaisetsu":{"topic": "専任宅建士：5人に1人以上・兼任不可・2週間以内に補充", "basis": {"text": "事務所には業務従事者5人に1人以上の専任宅建士が必要（宅建業法31条の3）。1社専属で複数業者の兼任は不可。不足時は2週間以内に補充が必要。案内所（申込み受付）にも専任宅建士が必要。", "example": ""}, "reason": {"text": "登録消除処分を受けた宅建士は、消除の日から5年が経過しなければ再登録を申請できません（宅建業法18条1項7号）。欠格期間は5年間です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">専任宅建士のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">設置基準</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5人に1人以上</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">兼任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可（1社専属）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不足補充</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間以内</text></svg>", "choices": [{"label": "1年", "reason": "登録消除後の欠格期間は5年です（宅建業法18条1項7号）。1年ではありません。", "caution": "登録消除後の欠格期間＝5年（宅建業法18条1項7号）。"}, {"label": "3年", "reason": "登録消除後の欠格期間は5年です（宅建業法18条1項7号）。3年ではありません。", "caution": ""}, {"label": "制限なし", "reason": "登録消除後5年間は再登録できません（宅建業法18条1項7号）。制限なしではありません。", "caution": ""}], "summary": {"head": ["宅建士登録の欠格期間", "期間"], "rows": [["登録消除処分", "消除の日から5年（宅建業法18条1項7号）"], ["拘禁刑以上の刑", "執行終了等から5年"], ["宅建業法・詐欺等の罰金刑", "罰金から5年"], ["免許取消処分の役員等", "取消から5年"]]}}},
  {id:10416,unit:'l_hosho',level:3,field:'law',text:"保証協会が弁済業務保証金の還付に応じる上限額はどのように決まるか。",opts:["弁済業務保証金分担金の総額", "当該業者が供託すべきであった営業保証金の額", "被害額の全額（上限なし）", "1000万円が法定上限"],ans:1,exp:`保証協会は当該業者が本来供託すべきであった営業保証金の額（主たる事務所1000万円・従たる事務所各500万円等の合計）を上限として還付に応じます（宅建業法64条の8第1項）。`,"kaisetsu":{"topic": "営業保証金・保証協会：主1,000万・従500万/営業保証金vs分担金60万・30万", "basis": {"text": "営業保証金は主1,000万・従500万（宅建業法25条）。保証協会の分担金は主60万・従30万（同法64条の9）。還付対象は業者以外の取引した者。加入は任意。不足補充は通知後2週間以内。", "example": ""}, "reason": {"text": "保証協会が弁済業務保証金から弁済できる上限は、当該業者が保証協会の社員でなかった場合に供託すべきであった営業保証金の額に相当します（宅建業法64条の8第1項）。主たる事務所のみなら1000万円、従たる事務所があればその分も加算されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">営業保証金と弁済業務保証金</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">営業保証金</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">弁済業務保証金（分担金）</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">主たる事務所</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000万円</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">60万円</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従たる事務所/所</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">500万円</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">還付対象</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者以外</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者以外</text></svg>", "choices": [{"label": "弁済業務保証金分担金の総額", "reason": "還付上限は分担金の額ではなく、営業保証金に相当する額です（宅建業法64条の8第1項）。分担金（60万円等）より大きい金額が上限です。", "caution": "還付上限＝営業保証金相当額（分担金の額ではない）。"}, {"label": "被害額の全額（上限なし）", "reason": "還付上限は当該業者が供託すべきであった営業保証金の額です（宅建業法64条の8第1項）。被害全額が上限なしで補償されるわけではありません。", "caution": ""}, {"label": "1000万円が法定上限", "reason": "事務所が1か所（主たる事務所のみ）の場合は1000万円が上限ですが、従たる事務所がある場合はその分を加算した額が上限です。「常に1000万円」は誤りです。", "caution": ""}], "summary": {"head": ["弁済業務保証金の還付上限（宅建業法64条の8）", "内容"], "rows": [["上限", "社員でなかった場合に供託すべき営業保証金の額"], ["計算例", "主たる事務所のみ：1000万円"], ["計算例2", "主たる＋従たる1か所：1000万円＋500万円＝1500万円"], ["分担金との差", "分担金60万円→還付上限1000万円（保証協会が差額を補填）"]]}}},
  {id:10417,unit:'l_baikai',level:3,field:'law',text:"一般媒介契約において依頼者に課せられない義務はどれか。",opts:["他の業者への依頼状況の報告（明示型の場合）", "専属専任業者以外への依頼禁止", "依頼者が自ら発見した相手方との直接取引の禁止", "特にない（一般媒介の依頼者には上記のような制約はない）"],ans:3,exp:`一般媒介契約の依頼者は他の業者に重ねて依頼でき、自己発見取引も可能で業務報告義務も業者側にありません（宅建業法34条の2）。最も自由度の高い媒介契約形態です。`,"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任の有効期間は最長3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。レインズ登録は専任7日以内・専属専任5日以内。業務報告は専任2週間に1回・専属専任1週間に1回。", "example": ""}, "reason": {"text": "一般媒介契約では依頼者に他業者への依頼禁止・自己発見取引の禁止等の義務はありません（宅建業法34条の2第1項3号）。複数業者への依頼・自己発見取引が自由にできることが一般媒介の特徴です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">自己発見</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">レインズ</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専任</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専属専任</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text></svg>", "choices": [{"label": "他の業者への依頼状況の報告（明示型の場合）", "reason": "明示型一般媒介では依頼者が他業者への依頼状況を通知する義務があります（任意ですが明示型の場合は特約で義務化）。これは依頼者側の義務となりえます。", "caution": ""}, {"label": "専属専任業者以外への依頼禁止", "reason": "「専属専任業者以外への依頼禁止」という規定は存在しません（宅建業法34条の2）。", "caution": ""}, {"label": "依頼者が自ら発見した相手方との直接取引の禁止", "reason": "自己発見取引の禁止は専属専任媒介のみです（宅建業法34条の2第3項）。一般媒介では禁止されていません。", "caution": ""}], "summary": {"head": ["一般媒介契約の自由度", "内容"], "rows": [["複数業者への依頼", "自由"], ["自己発見取引", "自由"], ["他業者への依頼通知", "明示型は義務・非明示型は不要"], ["レインズ登録・業務報告", "義務なし"]]}}},
  {id:10418,unit:'l_jusetsu',level:3,field:'law',text:"重要事項説明における「法令に基づく制限の概要」の説明として正しいものはどれか。",opts:["用途制限・建ぺい率・容積率等の建築規制のみを説明すればよい", "都市計画法・建築基準法・農地法等の関連法令に基づく制限の概要をすべて説明する", "現状に影響する制限のみ説明すればよい", "法令制限は重要事項説明の対象外"],ans:1,exp:`重要事項説明における法令に基づく制限の概要は、都市計画法・建築基準法・農地法・国土利用計画法等、その物件に関係するすべての法令上の制限を説明する必要があります（宅建業法35条1項2号）。`,"kaisetsu":{"topic": "重要事項説明：宅建士が説明・買主への交付・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主（貸主）は不要。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能。", "example": ""}, "reason": {"text": "35条書面の「法令に基づく制限の概要」は都市計画法・建築基準法・農地法等、対象不動産に関係するすべての法令上の制限を網羅的に説明することが求められます（宅建業法35条1項2号）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士のみ（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "用途制限・建ぺい率・容積率等の建築規制のみを説明すればよい", "reason": "建築規制のみならず農地法・自然公園法等の関連法令も含めすべての制限を説明する必要があります（宅建業法35条1項2号）。", "caution": "法令上の制限：建築規制だけでなく農地法・国土法等すべての関連法令。"}, {"label": "現状に影響する制限のみ説明すればよい", "reason": "将来の利用に影響する制限も含め、関連するすべての法令上の制限を説明する必要があります（宅建業法35条1項2号）。", "caution": ""}, {"label": "法令制限は重要事項説明の対象外", "reason": "法令上の制限の概要は重要事項説明の必須記載事項です（宅建業法35条1項2号）。", "caution": ""}], "summary": {"head": ["法令上の制限の概要（宅建業法35条1項2号）", "内容"], "rows": [["都市計画法", "用途地域・建ぺい率・容積率・地区計画等"], ["建築基準法", "接道義務・高さ制限等"], ["農地法", "転用・権利移動の許可・届出"], ["その他", "国土利用計画法・自然公園法・文化財保護法等"]]}}},
  {id:10419,unit:'l_37jo',level:3,field:'law',text:"37条書面（契約書面）について、IT化（電磁的方法での提供）の要件として正しいものはどれか。",opts:["宅建業者の一方的な判断で電磁的方法に切り替えられる", "相手方の承諾を得た上で、宅建士の記名に代わる省令で定める措置を講じた電磁的記録を提供できる", "電磁的方法での提供では宅建士の記名は不要", "電磁的方法での提供は禁止されている"],ans:1,exp:`37条書面の電磁的方法での提供は相手方の承諾を得ることが必要で、宅建士の記名に代わる国土交通省令で定める措置を講じた電磁的記録を提供することで交付に代えることができます（宅建業法37条）。`,"kaisetsu":{"topic": "37条書面：全取引で交付・記名（押印不要）・移転登記申請時期は必要的記載事項", "basis": {"text": "37条書面は全取引で契約の双方当事者に交付が義務（宅建業法37条）。引渡し時期・移転登記申請時期は必要的記載事項。2021年改正で押印は不要、記名のみで足ります。", "example": ""}, "reason": {"text": "2022年の法改正により、37条書面は相手方の承諾を得た上で電磁的記録で提供できるようになりました（宅建業法37条4項）。電磁的方法で提供する場合は、宅建士の記名に代わる国土交通省令で定める措置が必要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付義務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全取引・双方当事者</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡時期・移転登記申請時期等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要）</text></svg>", "choices": [{"label": "宅建業者の一方的な判断で電磁的方法に切り替えられる", "reason": "相手方の承諾が必要です（宅建業法37条4項）。一方的な切り替えはできません。", "caution": "電磁的提供：相手方の承諾が必要（宅建業法37条4項）。"}, {"label": "電磁的方法での提供では宅建士の記名は不要", "reason": "電磁的記録で提供する場合も宅建士の電子署名が必要です（宅建業法37条3項）。", "caution": ""}, {"label": "電磁的方法での提供は禁止されている", "reason": "2022年改正で相手方の承諾を条件に電磁的提供が認められました（宅建業法37条4項）。「禁止」は誤りです。", "caution": ""}], "summary": {"head": ["37条書面の電磁的提供（2022年改正）", "内容"], "rows": [["要件", "相手方の承諾"], ["宅建士の署名", "電子署名が必要"], ["書面交付との選択", "相手方の承諾があれば電磁的提供も可"], ["35条書面も同様", "電磁的提供は相手方承諾が必要"]]}}},
  {id:10420,unit:'l_kokoku',level:3,field:'law',text:"宅建業法上の広告開始時期制限に違反した場合の効果として正しいものはどれか。",opts:["広告を見た相手方との契約は無効", "業法上の罰則（指示・業務停止等）の対象となるが、契約の効力には影響しない", "広告費の返還義務が生じる", "民事上の損害賠償義務が直ちに生じる"],ans:1,exp:`広告開始時期制限（宅建業法33条）に違反した場合、行政処分（指示・業務停止等）の対象となりますが、違反した広告を信じて締結した契約の私法上の効力には影響しません。`,"kaisetsu":{"topic": "宅建業者の広告：開発許可後に広告可・誇大広告は全媒体禁止・取引態様は広告時と注文時両方", "basis": {"text": "開発許可・建築確認後（工事中でも）広告できます（宅建業法33条）。誇大広告禁止は全媒体・全対象者に適用（同法32条）。取引態様は広告時と注文受領時の両方で明示が必要（同法34条）。", "example": ""}, "reason": {"text": "広告開始時期の制限違反（宅建業法33条）は行政処分（指示・業務停止等）の対象となりますが、締結された契約の効力自体を無効にする効果はありません（宅建業法の民事効原則論）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">広告規制のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">広告開始時期</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築確認・開発許可後</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誇大広告禁止</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">媒体・対象問わず</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取引態様の明示</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">広告時と注文時の両方</text></svg>", "choices": [{"label": "広告を見た相手方との契約は無効", "reason": "広告開始時期制限違反は行政処分の対象ですが、契約の効力を無効にするものではありません（宅建業法33条・65条等）。", "caution": "広告規制違反：行政処分の対象だが、契約の効力には直接影響しない。"}, {"label": "広告費の返還義務が直ちに生じる", "reason": "広告費の返還義務が自動的に生じるという規定はありません（宅建業法33条・65条）。", "caution": ""}, {"label": "民事上の損害賠償義務が直ちに生じる", "reason": "相手方が損害を受けた場合は民事上の損害賠償が問題となりますが、「直ちに」生じるわけではなく要件を満たす必要があります（民法709条等）。", "caution": ""}], "summary": {"head": ["広告規制違反の効果", "内容"], "rows": [["行政処分", "指示・業務停止処分等の対象"], ["刑事罰", "悪質な場合は刑事罰の対象"], ["契約の効力", "無効にはならない（有効のまま）"], ["民事責任", "損害が発生した場合は損害賠償の対象"]]}}},
  {id:10421,unit:'l_cooling',level:3,field:'law',text:"クーリングオフ後、宅建業者が返還すべき金員として正しいものはどれか。",opts:["手付金のみ", "受領した代金・手付金等の全額（違約金等の控除不可）", "代金から実費を控除した額", "証約手付として交付した場合は返還不要"],ans:1,exp:`クーリングオフによる解除が行われた場合、宅建業者は受領した代金・手付金等の全額を遅滞なく返還しなければなりません（宅建業法37条の2第3項）。違約金の差し引きや損害賠償の主張はできません。`,"kaisetsu":{"topic": "クーリングオフ：告知日から8日以内・書面で・事務所では不可・全額返還", "basis": {"text": "クーリングオフは告知を受けた日から8日以内に書面で行います（宅建業法37条の2）。事務所・モデルルーム等での申込みはクーリングオフ不可。解除後業者は全額返還（費用控除不可）。", "example": ""}, "reason": {"text": "クーリングオフが行使された場合、宅建業者は受領した代金・手付金等の全額を速やかに返還しなければなりません（宅建業法37条の2第3項）。違約金・損害賠償等を控除することはできません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">クーリングオフのポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">告知日から8日以内</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">方法</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面（発信主義）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所での申込み</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">クーリングオフ不可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除後</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全額返還</text></svg>", "choices": [{"label": "手付金のみ", "reason": "受領した全額（代金・手付金等）を返還しなければなりません（宅建業法37条の2第3項）。手付金のみではありません。", "caution": "クーリングオフ後：受領した全額を返還（損害賠償・違約金の控除不可）。"}, {"label": "代金から実費を控除した額", "reason": "実費控除は認められません（宅建業法37条の2第3項）。全額返還です。", "caution": ""}, {"label": "証約手付として交付した場合は返還不要", "reason": "クーリングオフ後は証約手付であっても全額返還しなければなりません（宅建業法37条の2第3項）。手付の種類は関係ありません。", "caution": ""}], "summary": {"head": ["クーリングオフ後の処理（宅建業法37条の2第3項）", "内容"], "rows": [["宅建業者の返還義務", "受領した代金・手付金等の全額"], ["損害賠償の請求", "不可"], ["違約金の控除", "不可"], ["買主の費用負担", "なし（クーリングオフによる解除は損害賠償なし）"]]}}},
  {id:10422,unit:'l_hoshu',level:3,field:'law',text:"宅建業者が受け取る報酬の消費税の取扱いとして正しいものはどれか。",opts:["消費税は別途加算できる", "報酬の上限額に消費税が含まれている", "消費税は依頼者が直接国税庁に納付する", "免税業者は消費税を受け取れない"],ans:0,exp:`宅建業者が受け取る報酬の上限は消費税別の金額であり、実際には上限額に消費税相当額を加算して受け取ることができます（国土交通省告示）。`,"kaisetsu":{"topic": "報酬：売買は代金×3%+6万（400万超）・賃貸は借賃1か月・上限超過は不可", "basis": {"text": "売買（400万超）の一方からの上限は代金×3%+6万。双方合計は一方上限×2。賃貸（居住用・非居住用とも）は借賃1か月分。低廉な空家等（800万円以下）は、媒介報酬について原則の報酬額を超えて30万円（税別）まで受領できる場合があります（依頼者への説明・合意が必要）。", "example": ""}, "reason": {"text": "宅建業者が受け取る報酬の告示額は消費税別の金額です。消費税は別途加算できます（宅建業法46条・告示）。例えば3000万円の売買（上限96万円税別）では、消費税10%を加えて105.6万円が実際の上限になります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対象</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（400万超）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万（一方）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（200万以下）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸（双方合計）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借賃1か月分</text></svg>", "choices": [{"label": "報酬の上限額に消費税が含まれている", "reason": "告示の報酬上限額は消費税別です（告示・宅建業法46条）。消費税は別途加算できます。", "caution": "告示の報酬上限：消費税別（消費税は別途加算可）。"}, {"label": "消費税は依頼者が直接国税庁に納付する", "reason": "消費税は宅建業者が受け取り、宅建業者が納税します。依頼者が直接国税庁に納付する仕組みではありません。", "caution": ""}, {"label": "免税業者は消費税を受け取れない", "reason": "免税業者（年間売上1000万円以下等）であっても消費税相当額を受け取ることができます（インボイス制度の影響は別途考慮）。", "caution": ""}], "summary": {"head": ["報酬と消費税", "内容"], "rows": [["告示の上限額", "消費税別"], ["消費税の扱い", "別途加算可（告示額×1.1等）"], ["例：96万円（税別）", "消費税込みでは96万円×1.1＝105.6万円"], ["免税業者", "消費税相当額の受取は可能"]]}}},
  {id:10423,unit:'l_kantoku',level:3,field:'law',text:"宅建業法上の罰則で拘禁刑刑が規定されているものとして正しいものはどれか。",opts:["専任宅建士の不足を届け出なかった場合", "無免許で宅建業を営んだ場合", "重要事項説明書への記名を忘れた場合", "帳簿の備え付けをしなかった場合"],ans:1,exp:`無免許で宅建業を営んだ場合は3年以下の拘禁刑もしくは300万円以下の罰金またはその両方が科されます（宅建業法79条1号）。他の違反は罰金や過料の場合が多いです。`,"kaisetsu":{"topic": "監督処分：業務停止最長1年・大臣は全業者に指示可・指示違反→業務停止", "basis": {"text": "業務停止の最長期間は1年（宅建業法65条2項）。大臣は全業者（知事免許含む）に指示処分を行う権限があります。指示処分違反→業務停止、業務停止違反→免許取消という段階があります。", "example": ""}, "reason": {"text": "無免許で宅建業を営んだ場合は3年以下の拘禁刑もしくは300万円以下の罰金（またはその両方）の刑事罰の対象です（宅建業法79条1号）。宅建業法では行政処分のほか刑事罰も規定されています。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">監督処分のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">処分</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">最長1年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣の権限</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全業者に指示可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">指示処分違反</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止の対象</text></svg>", "choices": [{"label": "専任宅建士の不足を届け出なかった場合", "reason": "専任宅建士不足の放置は行政処分の対象ですが（宅建業法31条の3）、拘禁刑刑が明示されている規定ではありません。", "caution": "無免許営業：3年以下の拘禁刑または300万円以下の罰金（宅建業法79条1号）。"}, {"label": "重要事項説明書への記名を忘れた場合", "reason": "記名忘れは行政処分の対象ですが（宅建業法35条1項）、拘禁刑刑が直接規定されているものではありません。", "caution": ""}, {"label": "帳簿の備え付けをしなかった場合", "reason": "帳簿不備は行政処分・過料等の対象ですが（宅建業法49条）、拘禁刑刑が明示されている規定ではありません。", "caution": ""}], "summary": {"head": ["宅建業法の主な刑事罰", "内容"], "rows": [["無免許営業（宅建業法79条1号）", "3年以下の拘禁刑または300万円以下の罰金"], ["名義貸し・不正免許取得（宅建業法79条）", "3年以下の拘禁刑または300万円以下の罰金"], ["業務停止違反（宅建業法80条）", "1年以下の拘禁刑または100万円以下の罰金"]]}}},
  {id:10424,unit:'k_toshi',level:3,field:'limit',text:"都市計画の変更手続きとして正しいものはどれか。",opts:["都道府県が一方的に変更できる", "公聴会・縦覧・意見書の提出・審議会等のプロセスを経て変更する", "市町村の申請があれば即時変更できる", "変更は5年ごとに義務的に行われる"],ans:1,exp:`都市計画の変更には公聴会の開催・案の縦覧・意見書の受付・都市計画審議会への付議等の手続きが必要です（都市計画法17条・18条）。一方的な変更はできません。`,"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域の1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "都市計画の変更には、原案の公告・縦覧・意見書の受付・都市計画審議会への付議・知事の決定等の手続きが必要です（都市計画法16条〜20条）。公聴会も必要な場合があります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "都道府県が一方的に変更できる", "reason": "公聴会・縦覧・意見書・審議会等のプロセスが必要です（都市計画法16条〜20条）。一方的変更はできません。", "caution": "都市計画の変更：公聴会・縦覧・意見書・審議会等のプロセスが必要（都市計画法16条〜20条）。"}, {"label": "市町村の申請があれば即時変更できる", "reason": "即時変更はできません。所定の手続き（公告・縦覧・意見書・審議会等）が必要です（都市計画法16条〜20条）。", "caution": ""}, {"label": "変更は5年ごとに義務的に行われる", "reason": "5年ごとの義務的変更という規定はありません（都市計画法16条〜20条）。必要に応じて変更されます。", "caution": ""}], "summary": {"head": ["都市計画の変更手続き（都市計画法16条〜20条）", "内容"], "rows": [["①原案作成・公告・縦覧", "住民等が閲覧できる"], ["②意見書の受付", "住民等が意見を提出可"], ["③都市計画審議会", "専門家・住民代表等が審議"], ["④知事・市町村長の決定", "最終的な決定"]]}}},
  {id:10425,unit:'k_kenchiku',level:3,field:'limit',text:"特殊建築物（病院・劇場・ホテル等）に関して建築基準法が定める規制として正しいものはどれか。",opts:["用途地域の規制のみが適用される", "構造・防火・避難設備等に関する特別な基準（単体規定）が適用される", "特殊建築物は一切の増改築ができない", "特殊建築物への用途変更は建築確認が不要"],ans:1,exp:`特殊建築物には耐火構造・防火区画・避難設備・内装制限等、一般建築物より厳しい単体規定が適用されます（建築基準法27条・35条等）。また用途変更（特殊建築物へ）は一定規模以上で確認申請が必要です。`,"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・用途制限・道路斜線", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。防火地域の耐火建築物は隣地境界線に外壁を接して建築可（同法65条）。", "example": ""}, "reason": {"text": "特殊建築物（病院・劇場・ホテル・共同住宅等）には一般の建築物より厳格な構造・防火・避難設備等に関する基準（単体規定）が適用されます（建築基準法35条・36条等）。これは多数の人が利用することへの対応です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">防火地域の耐火建築物</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">隣地境界線に接して建築可</text></svg>", "choices": [{"label": "用途地域の規制のみが適用される", "reason": "特殊建築物には用途地域の規制に加え、構造・防火・避難設備等の特別な基準も適用されます（建築基準法35条・36条等）。「のみ」は誤りです。", "caution": "特殊建築物：構造・防火・避難設備等の特別基準（単体規定）が適用される（建築基準法35条等）。"}, {"label": "特殊建築物は一切の増改築ができない", "reason": "増改築の際に確認申請が必要な場合等の制限はありますが（建築基準法87条）、一切できないわけではありません。", "caution": ""}, {"label": "特殊建築物への用途変更は建築確認が不要", "reason": "特殊建築物の用途に変更する場合で200㎡超の場合は建築確認が必要です（建築基準法87条1項）。「不要」は誤りです。", "caution": ""}], "summary": {"head": ["特殊建築物（建築基準法別表第一）", "規制内容"], "rows": [["用途の例", "病院・劇場・共同住宅・ホテル・学校・飲食店等"], ["構造基準", "耐火・防火構造等の特別基準（建築基準法35条等）"], ["避難設備", "廊下幅・避難経路等"], ["確認申請", "200㎡超の特殊建築物は確認申請必要（建築基準法6条1項1号）"]]}}},
  {id:10426,unit:'k_nochi',level:3,field:'limit',text:"農地法の目的として正しいものはどれか。",opts:["農地の宅地化を促進すること", "農地を農業上の利用を確保しつつ合理的な利用を図ること", "農地の所有権を農業者に集中させること", "農地の価格を安定させること"],ans:1,exp:`農地法の目的は農地を農業上の利用を確保しながらその合理的な利用を図り、農業生産力の維持・増進と農業経営の安定を図ることです（農地法1条）。農地の宅地化促進ではありません。`,"kaisetsu":{"topic": "農地法：3条は農業委員会・4・5条は都道府県知事・市街化区域は届出のみ", "basis": {"text": "農地法3条の許可権者は農業委員会。4・5条は都道府県知事等。市街化区域の農地転用（4・5条）は農業委員会への届出のみOK。相続は許可不要・3か月以内の農業委員会への届出が必要。", "example": ""}, "reason": {"text": "農地法の目的は農地を農業上の利用を確保するとともに農地の合理的かつ効率的な利用を図ることです（農地法1条）。農地の宅地化促進は目的ではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text></svg>", "choices": [{"label": "農地の宅地化を促進すること", "reason": "農地の宅地化促進は農地法の目的ではありません（農地法1条）。農地を農業上の利用を確保することが目的です。", "caution": "農地法の目的：農地を農業上の利用を確保しつつ合理的な利用を図ること（農地法1条）。"}, {"label": "農地の所有権を農業者に集中させること", "reason": "農地の特定者への集中は農地法の目的ではありません（農地法1条）。", "caution": ""}, {"label": "農地の価格を安定させること", "reason": "農地価格の安定は農地法の目的ではありません（農地法1条）。", "caution": ""}], "summary": {"head": ["農地法の目的（農地法1条）", "内容"], "rows": [["農業生産力の維持向上", "農地の農業的利用を確保"], ["農地の合理的利用", "効率的な利用を促進"]]}}},
  {id:10427,unit:'k_kokudo',level:3,field:'limit',text:"注視区域・監視区域の指定と事前届出の違いとして正しいものはどれか。",opts:["注視区域は事前届出が必要", "監視区域は事後届出が必要", "注視区域は取引の効力に影響しないが監視区域は許可制", "監視区域内では事前届出を行い、審査期間中は契約できない"],ans:3,exp:`監視区域内では取引契約の締結前（事前）に届け出が必要で、審査期間中（最長6週間）は契約を締結できません（国土利用計画法27条の4〜7）。注視区域は事後届出制が強化されたものです。`,"kaisetsu":{"topic": "国土利用計画法：事後届出は2週間以内・市街化区域は2,000㎡以上・規制区域は許可制", "basis": {"text": "事後届出は契約締結後2週間以内（国土利用計画法23条）。市街化区域は2,000㎡以上・市街化調整区域は5,000㎡以上・都市計画区域外は10,000㎡以上。届出義務者は買主のみ。規制区域は許可制。", "example": ""}, "reason": {"text": "監視区域内では事前届出を行い、審査期間中は契約できません（国土利用計画法27条の6第1項）。注視区域より規制が強い区域です（同法27条の7）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">国土利用計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">区域</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">基準面積</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2,000㎡以上</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化調整区域</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都市計画区域外</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10,000㎡以上</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">規制区域</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">許可制（届出ではない）</text></svg>", "choices": [{"label": "注視区域は事前届出が必要", "reason": "注視区域でも事前届出が必要ですが（国土利用計画法27条の7）、「監視区域は事後届出」は誤りです。", "caution": ""}, {"label": "監視区域は事後届出が必要", "reason": "監視区域では事前届出が必要です（国土利用計画法27条の6）。「事後届出」は誤りです。", "caution": "監視区域：事前届出＋審査期間中は契約不可（国土利用計画法27条の6）。"}, {"label": "注視区域は取引の効力に影響しないが監視区域は許可制", "reason": "監視区域は許可制ではなく届出制です（国土利用計画法27条の6）。", "caution": ""}], "summary": {"head": ["監視区域と注視区域の比較", "内容"], "rows": [["監視区域（事前届出・27条の6）", "届出後6週間は契約不可"], ["注視区域（事前届出・27条の7）", "届出後6週間の審査・不勧告通知後に契約可"]]}}},
  {id:10428,unit:'k_kukaku',level:3,field:'limit',text:"土地区画整理事業において保留地を定める目的として正しいものはどれか。",opts:["施行者が販売して事業費に充てるため", "地権者全員に均等に配分するため", "公共施設用地として確保するため", "将来の再開発のため"],ans:0,exp:`保留地は土地区画整理事業の費用を捻出するために、換地として定めず施行者が取得して第三者に売却する土地です（土地区画整理法96条）。事業費に充てるために設定されます。`,"kaisetsu":{"topic": "土地区画整理法：換地は公告翌日確定・仮換地は従前地使用不可・組合は2/3以上", "basis": {"text": "換地処分の公告翌日から換地が確定します（土地区画整理法104条）。仮換地の指定後は従前地を使用できなくなります（同法99条）。組合設立には土地所有者・借地権者の各2/3以上の同意が必要です。", "example": ""}, "reason": {"text": "保留地とは土地区画整理事業において施行者が販売して事業費に充てるために設定する土地です（土地区画整理法96条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">土地区画整理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">換地の確定</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公告の翌日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮換地指定後</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従前地は使用不可（所有権は残る）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">組合設立</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各2/3以上の同意</text></svg>", "choices": [{"label": "地権者全員に均等に配分するため", "reason": "保留地は施行者が確保して販売するものです（土地区画整理法96条）。", "caution": "保留地：施行者が販売して事業費に充てる（土地区画整理法96条）。"}, {"label": "公共施設用地として確保するため", "reason": "公共施設用地は「公共減歩」として別途設定されます（土地区画整理法96条）。", "caution": ""}, {"label": "将来の再開発のため", "reason": "将来の再開発のためではなく事業費充当のためです（土地区画整理法96条）。", "caution": ""}], "summary": {"head": ["保留地（土地区画整理法96条）", "内容"], "rows": [["目的", "施行者が事業費に充てるために留保する"], ["設定方法", "換地計画で定める"], ["効果", "換地処分後に施行者に帰属"]]}}},
  {id:10429,unit:'t_joto',level:3,field:'tax',text:"特定居住用財産の譲渡損失の損益通算及び繰越控除について正しいものはどれか。",opts:["居住用財産の譲渡損失はすべての所得と通算できる", "住宅ローンが残っている場合に一定要件下で損益通算・繰越控除できる", "損益通算はできないが繰越控除のみできる", "この特例は廃止されている"],ans:1,exp:`特定居住用財産（住宅ローン残高のある居住用財産）の譲渡損失は、一定要件を満たす場合に他の所得との損益通算および3年間の繰越控除ができます（租税特別措置法41条の5）。`,"kaisetsu":{"topic": "譲渡所得：分離課税・長期は20%・3,000万円控除は3年に1回", "basis": {"text": "土地・建物の譲渡所得は分離課税。長期（5年超）は合計20%（所得税15%+住民税5%）。短期（5年以下）は39%（所得税30%+住民税9%）。3,000万円特別控除は前年・前々年に適用があれば使えません（3年に1回）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">譲渡所得のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税方式</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">分離課税</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">長期（5年超）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計20%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">短期（5年以下）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計39%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3,000万円控除</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年に1回の制限</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10430,unit:'t_kotei',level:3,field:'tax',text:"固定資産税の評価替えにおける「据置年度」の仕組みとして正しいものはどれか。",opts:["3年ごとの評価替え後、地価が上昇しても次の評価替えまで税額は変わらない", "地価が下落した場合でも評価額は下げられない", "据置年度中に建物の増築があっても評価額は変わらない", "毎年評価替えを行う市町村もある"],ans:0,exp:`固定資産税は3年ごとに評価替えを行い（基準年度）、評価替え後の2年間（据置年度）は原則として評価額を据え置きます（地方税法349条）。ただし地価が下落した場合は据置年度でも修正が行われます。`,"kaisetsu":{"topic": "固定資産税：市町村が課す地方税・賦課期日は1月1日・評価替えは3年ごと", "basis": {"text": "固定資産税は市町村（東京23区は都）が課す地方税（地方税法343条）。賦課期日は毎年1月1日。評価替えは3年ごと（基準年度）。住宅用地の特例：200㎡以下は課税標準1/6、超過部分は1/3。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">固定資産税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市町村（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賦課期日</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">評価替え</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年ごと</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅用地（200㎡以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税標準1/6</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10431,unit:'t_tokei',level:3,field:'tax',text:"日本の土地に関する用語の説明として正しいものはどれか。",opts:["台地とは河川沿いの低湿地のことをいう", "洪積台地は比較的古い時代に形成され地盤が安定している", "沖積低地は地盤が堅固で宅地に最適", "扇状地は海岸沿いに形成される"],ans:1,exp:`洪積台地（洪積層）は数万年以上前に形成された地盤で比較的安定しており宅地に適しています。沖積低地は比較的新しく形成された低地で液状化・洪水のリスクがあります。台地は河川の低湿地ではなく周辺より高い安定した地形です。`,"kaisetsu":{"topic": "不動産統計・土地・建物の知識", "basis": {"text": "住宅着工戸数は近年80万戸前後。首都圏マンション価格は上昇傾向。J-REITの運用資産は拡大傾向。中古住宅流通は活発化。台地は宅地に適しており、干拓地は水害リスクが高いです。扇状地は比較的安定した地盤です。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産統計・土地の特性</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">近年の傾向</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅着工戸数</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">80万戸前後</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">首都圏マンション価格</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">上昇傾向</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">J-REIT</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">拡大傾向</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">干拓地</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">水害リスク高</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10432,unit:'r_ishi',level:3,field:'rights',text:'AがBに強迫されてCに土地を売却した場合、Cへの取消しの対抗について正しいものはどれか。',opts:['Cが善意であれば取消しを対抗できない','CがAの強迫を知っていた場合のみ取消しを対抗できる','CがAの強迫の有無・善意悪意にかかわらず取消しを対抗できる','Cが登記を備えていれば取消しを対抗できない'],ans:2,exp:`詐欺の場合と異なり、強迫による取消しは善意の第三者Cに対しても対抗できます（民法96条2項・3項）。強迫は意思決定を完全に奪うため、被害者保護を徹底した規定です。`,"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失保護）・通謀虚偽表示（無効・善意保護）。", "example": ""}, "reason": {"text": "強迫による取消しは被害者に全く落ち度がないため、取消しを第三者にも対抗できます（民法96条3項の反対解釈）。詐欺と異なり第三者の善意悪意を問わず取消しを主張できます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "Cが善意であれば取消しを対抗できない", "reason": "強迫取消しはCの善意悪意を問わず対抗できます。善意でも保護されません（民法96条3項は詐欺のみの規定）。", "caution": "詐欺＝善意無過失の第三者保護あり。強迫＝第三者保護なし。この違いは最重要です。"}, {"label": "CがAの強迫を知っていた場合のみ対抗できる", "reason": "強迫取消しはCの知不知を問わず誰にでも対抗できます。Cの悪意は要件ではありません（民法96条3項は詐欺のみ）。", "caution": ""}, {"label": "Cが登記を備えていれば取消しを対抗できない", "reason": "強迫取消しは登記の有無を問わず第三者に対抗できます。", "caution": ""}], "summary": {"head": ["取消し原因", "善意の第三者", "悪意の第三者"], "rows": [["詐欺", "対抗不可", "対抗可"], ["強迫", "対抗可", "対抗可"]]}}},
  {id:10433,unit:'r_dairi',level:3,field:'rights',text:'自己契約・双方代理の禁止（民法108条）の例外として認められる場合はどれか。',opts:['代理人が有償で受任した場合','本人があらかじめ許諾した行為と債務の履行','代理人が法人である場合','本人が未成年の場合'],ans:1,exp:`自己契約・双方代理は原則として無権代理行為とみなされますが（民法108条1項本文）、本人があらかじめ許諾した行為と債務の履行については例外として有効です（同条ただし書）。`,"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護します。", "example": ""}, "reason": {"text": "自己契約・双方代理は本人の利益保護のために禁止されていますが（民法108条1項）、本人が許諾している場合はその保護は不要です。また債務の履行は既に確定した内容を実行するだけであり利益相反が生じないため許容されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "代理人が有償で受任した場合", "reason": "報酬の有無は自己契約・双方代理の禁止解除の要件ではありません（民法108条1項）。", "caution": ""}, {"label": "代理人が法人である場合", "reason": "代理人が法人であっても自己契約・双方代理の禁止は同様に適用されます（民法108条1項）。", "caution": ""}, {"label": "本人が未成年の場合", "reason": "本人が未成年であっても禁止の例外にはなりません。むしろ未成年者はより保護が必要です。", "caution": ""}], "summary": {"head": ["禁止", "例外"], "rows": [["自己契約", "本人の事前許諾・債務の履行（民法108条1項ただし書）"], ["双方代理", "本人の事前許諾・債務の履行（民法108条1項ただし書）"], ["代理権濫用", "相手方が善意無過失なら本人は否定不可（民法107条）"]]}}},
  {id:10434,unit:'r_jiko',level:3,field:'rights',text:'取得時効の起算点の選択について正しいものはどれか（判例）。',opts:['時効援用者が有利な任意の時点を起算点として選択できる','起算点は占有開始時点に固定され、任意の時点を選択することはできない','裁判所が事案に応じて起算点を決定する','起算点は相手方が指定する'],ans:1,exp:`取得時効の起算点は占有開始時点に固定されるとするのが判例です。時効援用者が有利な中間時点を任意に選択することはできません。`,"kaisetsu":{"topic": "消滅時効：知った時から5年または行使可能時から10年", "basis": {"text": "消滅時効は「知った時から5年」または「行使可能時から10年」のいずれか早い方で完成します（民法166条）。時効は援用して初めて効力が発生します（民法145条）。承認は更新事由です（民法152条）。", "example": ""}, "reason": {"text": "取得時効の起算点は占有を開始した時点に固定されます（判例）。時効の利益を受ける者が有利な時点を任意に選択することは許されません。これは時効を利用した権利主張の恣意的な操作を防ぐためです。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">期間</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人身損害</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年または20年</text></svg>", "choices": [{"label": "時効援用者が有利な任意の時点を起算点として選択できる", "reason": "起算点は占有開始時点に固定されており、任意に選択することはできません（判例）。", "caution": "起算点は占有開始時に固定。有利な時点の選択は不可（判例）。"}, {"label": "裁判所が事案に応じて起算点を決定する", "reason": "取得時効の起算点は客観的に占有開始時点に固定されており、裁判所が個別に決定するものではありません（判例）。", "caution": ""}, {"label": "起算点は相手方が指定する", "reason": "起算点は相手方が指定するものではなく、客観的な占有開始時点です（判例）。", "caution": ""}], "summary": {"head": ["取得時効の起算点", "内容"], "rows": [["原則", "占有を開始した時点（固定・判例）"], ["任意選択", "不可（恣意的操作防止）"], ["占有の承継", "前主の占有を合算して援用可（ただし前主の瑕疵も承継）"]]}}},
  {id:10435,unit:'r_bukken',level:3,field:'rights',text:'民法177条の「第三者」から除外されるのはどれか（判例）。',opts:['善意の転得者','背信的悪意者（信義則に反する態様で登記の欠如を主張する者）','抵当権者','仮登記権者'],ans:1,exp:`民法177条の「第三者」は登記の欠如を主張することについて正当な利益を有する者ですが、背信的悪意者は第三者から除外されます（判例）。背信的悪意者には登記なしで対抗できます。`,"kaisetsu":{"topic": "物権変動：登記が対抗要件・不法占拠者には登記不要", "basis": {"text": "不動産の物権変動は登記が第三者への対抗要件です（民法177条）。不法占拠者には登記なく対抗できます（判例）。建物賃借権は引渡しが対抗要件です（借地借家法31条）。", "example": ""}, "reason": {"text": "民法177条の「第三者」を無制限に認めると不当な結果が生じます。判例は「正当な利益を有する者」に限定し、信義則に反する態様で登記の欠如を主張する背信的悪意者は保護しないとしています。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">物権変動の対抗要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対抗要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">二重譲渡</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先に登記した者が優先</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不法占拠者</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記不要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物賃借権</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡し</text></svg>", "choices": [{"label": "善意の転得者", "reason": "善意の転得者は正当な利益を有する第三者に含まれます（判例）。民法177条の第三者として保護されます。", "caution": ""}, {"label": "抵当権者", "reason": "抵当権者は不動産に利害関係を持つ正当な第三者です。登記の先後で優劣が決まります。民法177条の第三者から除外されません。", "caution": ""}, {"label": "仮登記権者", "reason": "仮登記権者も正当な利益を有する第三者として民法177条の第三者に含まれます。", "caution": ""}], "summary": {"head": ["人物・立場", "民法177条の第三者か"], "rows": [["転得者（善意）", "該当→登記で対抗"], ["抵当権者・差押債権者", "該当→登記で対抗"], ["不法占拠者", "非該当→登記なしで対抗可"], ["背信的悪意者", "非該当→登記なしで対抗可"], ["相続人・包括承継人", "非該当（当事者扱い）"]]}}},
  {id:10436,unit:'r_tanpo',level:3,field:'rights',text:'根抵当権の元本確定前の極度額変更に必要な要件として正しいものはどれか。',opts:['根抵当権者と設定者の合意のみで変更でき利害関係人の承諾は不要','根抵当権者・設定者の合意に加え利害関係人（後順位抵当権者等）の承諾が必要','元本確定前は極度額を変更できない','変更には公証人の認証が必要'],ans:1,exp:`根抵当権の極度額変更は根抵当権者と設定者の合意に加え、利害関係を有する第三者（後順位抵当権者等）の承諾が必要です（民法398条の5）。変更の登記が効力発生要件です。`,"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権（民法369条）。質権は占有の移転が必要。先取特権は法定担保物権（当然に成立）。農地への抵当権設定自体は、通常、農地法3条の許可対象ではありません。", "example": ""}, "reason": {"text": "根抵当権の元本確定前の極度額変更には根抵当権者・設定者の合意に加え、利害関係人（後順位抵当権者等）の承諾が必要です（民法398条の5）。極度額が増額されると後順位担保権者の地位が悪化するためです。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "根抵当権者と設定者の合意のみで変更でき利害関係人の承諾は不要", "reason": "極度額の変更には利害関係人の承諾が必要です（民法398条の5）。合意のみでは不足です。", "caution": "極度額変更→利害関係人の承諾必要（民法398条の5）。"}, {"label": "元本確定前は極度額を変更できない", "reason": "元本確定前でも当事者の合意と利害関係人の承諾で極度額を変更できます（民法398条の5）。", "caution": ""}, {"label": "変更には公証人の認証が必要", "reason": "公証人の認証は要件ではありません（民法398条の5）。", "caution": ""}], "summary": {"head": ["根抵当権の極度額変更", "内容"], "rows": [["要件", "根抵当権者＋設定者の合意＋利害関係人の承諾（民法398条の5）"], ["利害関係人", "後順位抵当権者・転抵当権者等"], ["理由", "極度額増額→後順位担保権者が不利益を受けるため"]]}}},
  {id:10437,unit:'r_saikensoron',level:3,field:'rights',text:'連帯保証と通常の保証（単純保証）の違いとして正しいものはどれか。',opts:['連帯保証人には催告の抗弁権がある','連帯保証人には検索の抗弁権も分別の利益もない','連帯保証人には分別の利益がある','通常の保証人は主たる債務者と同時に請求される'],ans:1,exp:`連帯保証人には催告の抗弁権・検索の抗弁権・分別の利益がいずれもありません（民法454条）。通常の保証人はこれらの権利を持ちます。`,"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要（民法446条2項）。連帯保証人は催告・検索の抗弁権なし（民法454条）。債権譲渡の第三者対抗は確定日付ある証書による通知・承諾（民法467条2項）。相殺の絶対的効力：弁済・更改・相殺。", "example": ""}, "reason": {"text": "連帯保証は通常の保証（単純保証）と異なり①催告の抗弁権なし、②検索の抗弁権なし、③分別の利益なし（民法454条）という特徴があります。これにより連帯保証人は主債務者と同等の責任を負います。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">催告・検索の抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text></svg>", "choices": [{"label": "連帯保証人には催告の抗弁権がある", "reason": "連帯保証人には催告の抗弁権がありません（民法454条）。", "caution": "連帯保証人＝催告・検索の抗弁権なし・分別の利益なし（民法454条）。"}, {"label": "連帯保証人には分別の利益がある", "reason": "連帯保証人には分別の利益（保証人が複数いる場合に均等割りで負担）がありません（民法454条）。", "caution": ""}, {"label": "通常の保証人は主たる債務者と同時に請求される", "reason": "通常の保証人には催告の抗弁権（先にBに請求してほしい・民法452条）があるため、主債務者より先に請求されることはありません。「同時に請求」は誤りです。", "caution": ""}], "summary": {"head": ["保証の種類", "催告の抗弁権", "検索の抗弁権", "分別の利益"], "rows": [["単純保証", "あり（民法452条）", "あり（民法453条）", "あり"], ["連帯保証", "なし（民法454条）", "なし（民法454条）", "なし"]]}}},
  {id:10438,unit:'r_baibai',level:3,field:'rights',text:'売買契約の解除と第三者の保護（民法545条1項ただし書）について正しいものはどれか。',opts:['解除後に現れた第三者にも解除の効果を主張できる','解除前に現れた善意の第三者には解除の効果を対抗できない（登記が必要との判例）','解除前の第三者は登記なしで保護される','解除後の第三者は常に保護される'],ans:1,exp:`解除による原状回復は解除前に現れた善意の第三者を害することができません（民法545条1項ただし書）。ただし第三者が保護されるには登記が必要（判例）。解除後の第三者は対抗問題（登記の先後）で処理します。`,"kaisetsu":{"topic": "売買：同時履行の抗弁権・解除は原則催告が必要・契約不適合責任", "basis": {"text": "売買では代金と引渡しは同時履行の関係（民法533条）。解除は原則として相当の期間を定めた催告後に行います（民法541条）。契約不適合責任の通知は知った時から1年以内（民法566条）。", "example": ""}, "reason": {"text": "解除前に現れた第三者（解除前に登記を備えた者）は善意であれば保護されます（民法545条1項ただし書）。判例はこの第三者保護の要件として登記が必要としています。解除後の第三者との関係は対抗問題です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">売買のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">同時履行</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金と引渡しは同時履行</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則として催告が必要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">契約不適合の通知</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から1年以内</text></svg>", "choices": [{"label": "解除後に現れた第三者にも解除の効果を主張できる", "reason": "解除後の第三者との関係は対抗問題であり、先に登記を備えた者が優先します（判例）。常に主張できるわけではありません。", "caution": "解除前の第三者：善意＋登記で保護。解除後の第三者：対抗問題（先に登記した方が優先）。"}, {"label": "解除前の第三者は登記なしで保護される", "reason": "判例は解除前の第三者保護の要件として登記が必要としています（民法545条1項ただし書・判例）。登記なしでは保護されません。", "caution": ""}, {"label": "解除後の第三者は常に保護される", "reason": "解除後の第三者との関係は対抗問題であり、先に登記を備えた者が優先します（判例）。「常に保護」は誤りです。", "caution": ""}], "summary": {"head": ["解除と第三者", "保護要件"], "rows": [["解除前の第三者", "善意＋登記が必要（民法545条1項ただし書・判例）"], ["解除後の第三者", "対抗問題（先に登記した者が優先）"]]}}},
  {id:10439,unit:'r_chinshaku',level:3,field:'rights',text:'賃借権の無断転貸に対する賃貸人の解除権について正しいものはどれか（判例）。',opts:['無断転貸があれば常に解除できる','背信行為と認めるに足りない特段の事情がある場合は解除できない（判例）','賃貸人は損害賠償のみ請求できる','転借人に対して直接の退去請求はできない'],ans:1,exp:`判例は、無断転貸・無断譲渡があっても賃貸人への「背信行為」と認めるに足りない特段の事情がある場合は解除権が発生しないとします。また適法な転貸の場合、転借人は賃貸人に対して直接義務を負います（民法613条）。`,"kaisetsu":{"topic": "賃貸借：通常損耗は原状回復に含まれない・有益費は終了時に請求・賃料増額は正当事由が必要", "basis": {"text": "賃貸借終了時の原状回復義務に通常使用による損耗（壁の日焼け等）は含まれません（民法621条）。必要費は直ちに、有益費は終了時の請求が原則。更新拒絶には正当事由が必要（借地借家法28条）。", "example": ""}, "reason": {"text": "判例は信頼関係破壊の法理を採用しており、無断転貸であっても背信行為と認めるに足りない特段の事情がある場合は解除できないとしています。賃貸借は継続的な信頼関係に基づくため、形式的な違反だけで解除を認めると不合理です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">賃貸借のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通常損耗</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原状回復に含まれない</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要費</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直ちに請求可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有益費</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸借終了時に請求</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">更新拒絶</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当事由が必要</text></svg>", "choices": [{"label": "無断転貸があれば常に解除できる", "reason": "判例の信頼関係破壊の法理により、特段の事情がある場合は解除できません（判例）。「常に解除できる」は誤りです。", "caution": ""}, {"label": "賃貸人は損害賠償のみ請求できる", "reason": "信頼関係が破壊された場合は解除もできます（民法612条2項）。損害賠償のみに限定されません。", "caution": ""}, {"label": "転借人に対して直接の退去請求はできない", "reason": "解除が認められた場合、賃貸人は不法占拠者となった転借人に対して明渡しを請求できます。", "caution": ""}], "summary": {"head": ["信頼関係破壊の法理", "内容"], "rows": [["原則", "無断転貸は解除事由（民法612条2項）"], ["例外", "背信行為と認めるに足りない特段の事情あり→解除不可（判例）"], ["特段の事情", "親子間・実質的同一人格等"], ["賃料不払い", "1〜2か月程度では解除困難（判例）"]]}}},
  {id:10440,unit:'r_souzoku',level:3,field:'rights',text:'特別受益の持ち戻し免除について正しいものはどれか。',opts:['被相続人は持ち戻し免除の意思表示ができない','被相続人は遺言等で持ち戻し免除ができるが遺留分を侵害することはできない','特別受益は常に持ち戻しされ免除は認められない','持ち戻し免除の意思表示は公正証書によらなければならない'],ans:1,exp:`被相続人は生前贈与等の特別受益について意思表示（遺言等）により持ち戻し免除ができます（民法903条3項）。ただし遺留分を侵害する範囲では遺留分侵害額請求の対象になります。`,"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2・遺産分割は全員合意", "basis": {"text": "配偶者と子は各1/2（民法900条）。放棄は3か月以内に家裁へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2（民法1042条）。兄弟姉妹に遺留分はなし。遺産分割協議は全員合意が必要。", "example": ""}, "reason": {"text": "特別受益の持ち戻し免除は被相続人が遺言等で意思表示できます（民法903条3項）。ただし持ち戻し免除によって他の相続人の遺留分を侵害することはできません（民法1044条）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "被相続人は持ち戻し免除の意思表示ができない", "reason": "被相続人は遺言等で持ち戻し免除の意思表示ができます（民法903条3項）。", "caution": ""}, {"label": "特別受益は常に持ち戻しされ免除は認められない", "reason": "被相続人の意思表示（遺言等）により持ち戻し免除ができます（民法903条3項）。常に持ち戻しされるわけではありません。", "caution": ""}, {"label": "持ち戻し免除の意思表示は公正証書によらなければならない", "reason": "持ち戻し免除の意思表示に公正証書は不要です（民法903条3項）。遺言・生前行為いずれでも可能です。", "caution": ""}], "summary": {"head": ["特別受益の持ち戻し免除", "内容"], "rows": [["意思表示の方法", "遺言・生前の意思表示（民法903条3項）"], ["書面要件", "不要"], ["限界", "遺留分を侵害することはできない（民法1044条）"], ["推定", "婚姻20年以上の配偶者への居住用不動産贈与は免除推定（民法903条4項）"]]}}},
  {id:10441,unit:'r_fuhoko',level:3,field:'rights',text:'共同不法行為者の責任（民法719条）として正しいものはどれか。',opts:['各自の寄与度に応じた分割責任のみを負う','共同不法行為者は連帯して損害賠償の責任を負う','一人の行為者に賠償を求めると他の行為者への請求権が消滅する','被害者の過失は一切考慮されない'],ans:1,exp:`共同不法行為者は連帯して損害賠償の責任を負います（民法719条）。連帯債務として一人に全額請求できます。被害者の過失がある場合は過失相殺（民法722条2項）が適用されます。`,"kaisetsu":{"topic": "不法行為：故意または過失が必要・使用者責任・工作物責任", "basis": {"text": "不法行為は故意または過失が必要です（民法709条）。使用者は被用者の職務上の不法行為について責任を負います（民法715条）。工作物の所有者は無過失責任（占有者が免責された場合）（民法717条）。", "example": ""}, "reason": {"text": "共同不法行為者は連帯して損害賠償の責任を負います（民法719条1項）。被害者は共同不法行為者全員または一人に対して全額請求できます。一人への請求が他の加害者への請求に影響しない（相対効）のが不真正連帯の特徴です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不法行為のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般不法行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">故意または過失が必要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">使用者責任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">被用者への求償可（信義則上制限）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">工作物の所有者責任</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無過失責任（占有者が免責された場合）</text></svg>", "choices": [{"label": "各自の寄与度に応じた分割責任のみを負う", "reason": "共同不法行為者は分割責任ではなく連帯して全額の責任を負います（民法719条1項）。", "caution": ""}, {"label": "一人の行為者に賠償を求めると他の行為者への請求権が消滅する", "reason": "一人への請求が他の加害者への請求権を消滅させることはありません（不真正連帯の特徴）。", "caution": ""}, {"label": "被害者の過失は一切考慮されない", "reason": "共同不法行為でも被害者に過失があれば過失相殺が適用されます（民法722条2項）。", "caution": ""}], "summary": {"head": ["共同不法行為の効果", "内容"], "rows": [["連帯責任", "各自が全額について責任（民法719条1項）"], ["被害者の選択", "一人または全員に全額請求可"], ["過失相殺", "被害者の過失があれば適用"], ["求償", "内部的には寄与度・過失割合に応じて求償可"]]}}},
  {id:10442,unit:'r_shakuchi',level:3,field:'rights',text:'地主の承諾が得られない場合に借地上の建物を第三者に売却するための手続きとして正しいものはどれか。',opts:['建物の売却自体が禁止される','裁判所（借地非訟）に地主の承諾に代わる許可を申し立てることができる','地主への通知のみで建物を売却できる','借地権が消滅し買主は建物のみ取得する'],ans:1,exp:`地主が借地上建物の第三者への売却（借地権の譲渡）を承諾しない場合、借地人は裁判所（借地非訟）に地主の承諾に代わる許可を申し立てることができます（借地借家法19条）。`,"kaisetsu":{"topic": "借地権：最短30年・建物登記で対抗・建物滅失でも消滅せず・定期借地権は3種類", "basis": {"text": "普通借地権の最短存続期間は30年（借地借家法3条）。借地上の建物の自己名義登記が対抗要件（同法10条）。建物が滅失しても借地権は消滅しません。定期借地権は①一般（50年以上）②事業用（10〜50年未満）③建物譲渡特約（30年以上）の3種類。", "example": ""}, "reason": {"text": "借地上の建物を第三者に売却する際、地主の承諾が得られない場合は裁判所（借地非訟手続）に地主の承諾に代わる許可を申し立てることができます（借地借家法19条）。これにより借地人の財産権を保護しつつ取引を可能にします。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">借地権のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">最短存続期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">対抗要件</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借地上の建物の自己名義登記</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物滅失</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借地権は消滅しない</text></svg>", "choices": [{"label": "建物の売却自体が禁止される", "reason": "地主の承諾または裁判所の許可があれば建物を売却できます（借地借家法19条）。売却自体が禁止されるわけではありません。", "caution": ""}, {"label": "地主への通知のみで建物を売却できる", "reason": "地主の承諾または裁判所の許可が必要です（借地借家法19条）。通知だけでは足りません。", "caution": ""}, {"label": "借地権が消滅し買主は建物のみ取得する", "reason": "裁判所の許可があれば借地権ごと売却できます（借地借家法19条）。借地権は消滅しません。", "caution": ""}], "summary": {"head": ["建物・借地権の譲渡（借地借家法19条）", "内容"], "rows": [["原則", "地主の承諾が必要"], ["地主が承諾しない場合", "裁判所（借地非訟）に地主の承諾に代わる許可を申立て可"], ["裁判所の考慮事項", "地主に不相当な損害を生じさせないか"], ["許可の効果", "地主の承諾があったと同様に扱われる"]]}}},
  {id:10443,unit:'r_kukku',level:3,field:'rights',text:'区分所有者が共同生活上の義務に違反した場合に管理組合がとれる措置として正しいものはどれか。',opts:['他の区分所有者が個人で即時強制執行できる','区分所有法に基づき行為停止請求・使用禁止請求・区分所有権の競売請求ができる','管理組合は損害賠償請求のみできる','区分所有者には共同生活上の義務はない'],ans:1,exp:`区分所有法57条以下により、区分所有者が共同生活上の義務違反行為をした場合、管理組合は集会決議により行為停止請求・専有部分の使用禁止請求・区分所有権の競売請求ができます。`,"kaisetsu":{"topic": "区分所有法：重大変更は3/4以上・建替えは4/5以上・管理組合法人は30人以上", "basis": {"text": "共用部分の重大変更は区分所有者・議決権の各3/4以上の特別決議が必要（区分所有法17条）。建替えは4/5以上（同法62条）。管理組合法人の設立は3/4以上かつ区分所有者30人以上（同法47条）。専有部分と共有持分は分離処分不可（同法15条）。", "example": ""}, "reason": {"text": "区分所有者が共同生活上の義務（区分所有法6条）に著しく違反した場合、管理組合は①行為停止等の請求、②専有部分の使用禁止請求、③区分所有権・敷地利用権の競売請求が可能です（区分所有法57〜59条）。いずれも集会の決議が必要です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">区分所有法の決議要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">事項</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">普通決議</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">過半数</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">重大変更・規約変更</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3/4以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">管理組合法人</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3/4以上（30人以上）</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建替え</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4/5以上</text></svg>", "choices": [{"label": "他の区分所有者が個人で即時強制執行できる", "reason": "個人での強制執行ではなく、管理組合として集会決議を経て法的措置を取ります（区分所有法57〜59条）。", "caution": ""}, {"label": "管理組合は損害賠償請求のみできる", "reason": "損害賠償以外にも行為停止・使用禁止・競売請求等ができます（区分所有法57〜59条）。「のみ」は誤りです。", "caution": ""}, {"label": "区分所有者には共同生活上の義務はない", "reason": "区分所有者は区分所有法6条に基づき共同生活上必要な行為をする義務・妨害行為をしない義務を負います。", "caution": ""}], "summary": {"head": ["義務違反者への措置（区分所有法57〜59条）", "要件"], "rows": [["行為の停止等の請求（57条）", "普通決議（過半数）"], ["専有部分の使用禁止請求（58条）", "3/4以上の特別決議"], ["区分所有権の競売請求（59条）", "3/4以上の特別決議"]]}}},
  {id:10444,unit:'r_touki',level:3,field:'rights',text:'登記識別情報の失効申出について正しいものはどれか。',opts:['登記識別情報は一度発行されると永久に有効で失効させられない','不正取得の恐れがある場合、登記名義人は登記所に失効申出ができる','失効申出後も再発行を受けられる','失効申出は裁判所に対して行う'],ans:1,exp:`登記識別情報が不正に取得された恐れがある場合、登記名義人は登記所に対して失効申出ができます（不動産登記規則65条）。失効後は再発行されず、本人確認情報の提供等で対応します。`,"kaisetsu":{"topic": "不動産登記：権利登記は共同申請・仮登記は順位保全・建物滅失は1か月以内", "basis": {"text": "権利に関する登記は原則として登記権利者と登記義務者が共同申請します（不動産登記法60条）。仮登記は順位保全機能があるが完全な対抗力は本登記後です。建物滅失登記の申請義務は1か月以内（同法57条）。", "example": ""}, "reason": {"text": "登記識別情報は紛失・不正取得リスクがある場合に失効申出ができます（不動産登記法23条4項）。失効させると以後その識別情報では登記申請ができなくなり、不正登記を防止できます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産登記のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利登記</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則として共同申請</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮登記</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">順位保全（対抗力は本登記後）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物滅失登記</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1か月以内</text></svg>", "choices": [{"label": "登記識別情報は一度発行されると永久に有効で失効させられない", "reason": "登記識別情報は失効申出により失効させることができます（不動産登記法23条4項）。", "caution": ""}, {"label": "失効申出後も再発行を受けられる", "reason": "一度失効した登記識別情報は再発行されません。失効後に登記申請する場合は事前通知制度等の代替手段を利用します。", "caution": "失効した登記識別情報は再発行不可。"}, {"label": "失効申出は裁判所に対して行う", "reason": "失効申出は登記所（法務局）に対して行います（不動産登記規則65条）。裁判所ではありません。", "caution": ""}], "summary": {"head": ["登記識別情報の取扱い", "内容"], "rows": [["発行", "登記完了後に通知（12桁の英数字）"], ["紛失", "再発行なし（事前通知制度等で対応）"], ["失効申出", "不正取得リスク時に登記所へ申出"], ["提供方法", "書面の封入または電子申請"]]}}},
  {id:10445,unit:'l_menkyo',level:3,field:'law',text:'宅建業者の免許の必要的取消し事由として正しいものはどれか。',opts:['業務報告の遅延','宅建士が法令違反をした場合','不正手段で免許を受けたことが判明した場合','広告表示の軽微な誤り'],ans:2,exp:`不正手段による免許取得の判明は必要的取消し事由です（宅建業法66条1項8号）。業務停止処分違反や一定の義務違反は任意的取消し事由となる場合があります。`,"kaisetsu":{"topic": "宅建業免許：知事・大臣免許の区別・有効期間5年・欠格事由は5年", "basis": {"text": "1都道府県→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間。2020年改正で成年被後見人の欠格条項は廃止。", "example": ""}, "reason": {"text": "宅建業法66条1項1号に定める必要的取消し事由の一つとして、不正手段で免許を受けたことが挙げられています。業務報告の遅延・宅建士の個人的な法令違反・軽微な広告表示誤りは必要的取消し事由にはなりません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（2020年改正で成年被後見人は廃止）</text></svg>", "choices": [{"label": "業務報告の遅延", "reason": "業務報告の遅延は指示処分・業務停止処分の対象になりますが（宅建業法65条）、必要的取消し事由ではありません。", "caution": ""}, {"label": "宅建士が法令違反をした場合", "reason": "宅建士個人の法令違反は宅建士への処分の対象ですが、業者の必要的取消し事由にはなりません（ただし業者の指示・責任に関する規定あり）。", "caution": ""}, {"label": "広告表示の軽微な誤り", "reason": "軽微な広告誤りは指示処分の対象にはなりますが（宅建業法65条1項）、必要的取消し事由ではありません（宅建業法66条）。", "caution": ""}], "summary": {"head": ["必要的取消し事由（宅建業法66条1項）", "内容"], "rows": [["不正手段で免許取得", "1号"], ["業務停止処分に違反", "9号"], ["役員等が欠格事由に該当", "2号・3号"], ["任意取消し（業者の申請）", "宅建業法66条1項以外の事由"]]}}},
  {id:10446,unit:'l_takkenshi',level:3,field:'law',text:'事務禁止処分を受けた宅建士が禁止期間中に宅建士として事務を行った場合の処分として正しいものはどれか。',opts:['業務停止の延長のみ','登録消除処分の対象となる','戒告のみ','過料のみ'],ans:1,exp:`事務禁止処分中に宅建士としての事務を行った場合は登録消除処分の対象となります（宅建業法68条の2第1項3号）。事務禁止処分の期間は最長2年です。`,"kaisetsu":{"topic": "専任宅建士：5人に1人以上・兼任不可・2週間以内に補充", "basis": {"text": "事務所には業務従事者5人に1人以上の専任宅建士が必要（宅建業法31条の3）。1社専属で複数業者の兼任は不可。不足時は2週間以内に補充が必要。案内所（申込み受付）にも専任宅建士が必要。", "example": ""}, "reason": {"text": "事務禁止処分を受けた宅建士がその期間中に宅建士として事務を行った場合、登録消除処分（必要的）の対象となります（宅建業法68条の2第1項3号）。処分に違反する重大な行為として登録を消除されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">専任宅建士のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">設置基準</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5人に1人以上</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">兼任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可（1社専属）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不足補充</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間以内</text></svg>", "choices": [{"label": "業務停止の延長のみ", "reason": "事務禁止処分違反は業務停止の延長ではなく、登録消除処分の対象です（宅建業法68条の2第1項3号）。", "caution": "事務禁止処分違反＝登録消除（必要的・宅建業法68条の2第1項3号）。"}, {"label": "戒告のみ", "reason": "戒告は宅建業法上の宅建士に対する処分としては明示されていません。事務禁止処分違反は登録消除です（宅建業法68条の2第1項3号）。", "caution": ""}, {"label": "過料のみ", "reason": "事務禁止処分違反は過料の問題ではなく、登録消除処分の対象です（宅建業法68条の2第1項3号）。", "caution": ""}], "summary": {"head": ["必要的登録消除事由（宅建業法68条の2第1項）", "内容"], "rows": [["不正手段で登録", "2号"], ["事務禁止処分中の事務", "3号"], ["拘禁刑以上の刑に処せられた", "欠格事由に該当で消除"], ["宅建業法・詐欺等の罰金刑", "欠格事由に該当で消除"]]}}},
  {id:10447,unit:'l_baikai',level:3,field:'law',text:'専任媒介契約における業務処理状況の報告頻度として正しいものはどれか。',opts:['2週間に1回以上（専属専任は1週間に1回以上）','1週間に1回以上（専属専任も同じ）','1ヶ月に1回以上','依頼者が要求した場合のみ'],ans:0,exp:`専任媒介契約では2週間に1回以上、依頼者に業務処理状況を報告しなければなりません（宅建業法34条の2第8項）。専属専任媒介契約は1週間に1回以上と報告頻度が高くなっています。`,"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任の有効期間は最長3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。レインズ登録は専任7日以内・専属専任5日以内。業務報告は専任2週間に1回・専属専任1週間に1回。", "example": ""}, "reason": {"text": "専任媒介契約では業務処理状況の報告は2週間に1回以上（宅建業法34条の2第9項）、専属専任媒介は1週間に1回以上（同条10項）が義務です。一般媒介には法定の報告義務はありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">自己発見</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">レインズ</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">一般</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専任</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">専属専任</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text></svg>", "choices": [{"label": "1週間に1回以上（専属専任も同じ）", "reason": "専任媒介は2週間に1回以上、専属専任は1週間に1回以上です（宅建業法34条の2第9項・10項）。「専属専任も同じ」は誤りです。", "caution": "専任媒介：2週間に1回。専属専任：1週間に1回（宅建業法34条の2）。"}, {"label": "1ヶ月に1回以上", "reason": "月1回では不足です。専任媒介は2週間に1回以上が義務です（宅建業法34条の2第9項）。", "caution": ""}, {"label": "依頼者が要求した場合のみ", "reason": "依頼者の要求に関わらず定期的な報告義務があります（宅建業法34条の2第9項・10項）。「要求の場合のみ」は誤りです。", "caution": ""}], "summary": {"head": ["業務報告義務", "頻度"], "rows": [["一般媒介", "義務なし"], ["専任媒介", "2週間に1回以上（宅建業法34条の2第9項）"], ["専属専任媒介", "1週間に1回以上（宅建業法34条の2第10項）"]]}}},
  {id:10448,unit:'l_jusetsu',level:3,field:'law',text:'IT重説（テレビ会議等による重要事項説明）が認められる条件として正しいものはどれか。',opts:['相手方の承諾不要で常にIT重説を選択できる','相手方の承諾のうえ、宅建士証の確認等一定要件を満たした場合のみ認められる','IT重説では書面交付が不要','IT重説は投資用不動産のみに認められる'],ans:1,exp:`IT重説はテレビ会議等を通じて行いますが、①相手方の承諾②宅建士が宅建士証を画面上で提示③映像・音声が安定して受信できる環境等の要件が必要です。書面（または電磁的方法）の交付は引き続き必要です。`,"kaisetsu":{"topic": "重要事項説明：宅建士が説明・買主への交付・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主（貸主）は不要。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能。", "example": ""}, "reason": {"text": "IT重説は相手方の承諾と一定の通信環境（映像・音声の双方向送受信）を確保した場合に限り認められます（国土交通省ガイドライン）。書面交付義務は残り、特定の物件種類に限定されません（売買・賃貸ともに可）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士のみ（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "相手方の承諾不要で常にIT重説を選択できる", "reason": "相手方の承諾が必要です（国土交通省ガイドライン）。承諾なしにIT重説を行うことはできません。", "caution": "IT重説：相手方承諾必須。"}, {"label": "IT重説では書面交付が不要", "reason": "IT重説でも35条書面の交付義務は残ります（宅建業法35条1項）。電子交付の場合は別途承諾要件があります。", "caution": ""}, {"label": "IT重説は投資用不動産のみに認められる", "reason": "IT重説は売買・賃貸ともに認められています（国土交通省ガイドライン）。投資用に限定されません。", "caution": ""}], "summary": {"head": ["IT重説の要件", "内容"], "rows": [["対象", "売買・賃貸ともに可"], ["相手方承諾", "必要"], ["通信環境", "映像・音声の双方向送受信"], ["宅建士証の確認", "画面越しに確認できること"], ["書面交付", "必要（電子交付は別途承諾要）"]]}}},
  {id:10449,unit:'l_37jo',level:3,field:'law',text:'37条書面への記名押印（または電磁的措置）について正しいものはどれか。',opts:['代表者が記名押印すれば宅建士でなくてもよい','宅建士が記名押印しなければならない','記名のみでよく押印は不要','電磁的方法による提供では署名・電子署名も不要'],ans:2,exp:`37条書面は宅建士が記名しなければなりません（宅建業法37条3項）。2022年改正後、押印は不要です。電磁的方法で提供する場合は国土交通省令で定める措置が必要です。`,"kaisetsu":{"topic": "37条書面：全取引で交付・記名（押印不要）・移転登記申請時期は必要的記載事項", "basis": {"text": "37条書面は全取引で契約の双方当事者に交付が義務（宅建業法37条）。引渡し時期・移転登記申請時期は必要的記載事項。2021年改正で押印は不要、記名のみで足ります。", "example": ""}, "reason": {"text": "37条書面は宅建士が記名しなければなりません（宅建業法37条3項）。2022年改正以前は記名押印が必要でしたが、改正後は記名のみで足り押印は不要となりました。電磁的方法で提供する場合は国土交通省令で定める措置が必要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付義務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全取引・双方当事者</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡時期・移転登記申請時期等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要）</text></svg>", "choices": [{"label": "代表者が記名押印すれば宅建士でなくてもよい", "reason": "37条書面の記名は宅建士が行います（宅建業法37条3項）。代表者でも宅建士でなければ不可です。", "caution": ""}, {"label": "記名のみでよく押印は不要", "reason": "2022年改正後は押印が不要となりました（宅建業法37条3項）。記名のみで足ります。これは選択肢2と実質同じ内容で正解の選択肢の補足説明になります。", "caution": ""}, {"label": "電磁的方法による提供では署名・電子署名も不要", "reason": "電磁的記録で提供する場合は宅建士の電子署名が必要です（宅建業法37条3項）。不要ではありません。", "caution": ""}], "summary": {"head": ["37条書面の記名・署名", "内容"], "rows": [["記名者", "宅建士（宅建業法37条3項）"], ["押印", "2022年改正で不要"], ["電磁的記録", "宅建士の電子署名が必要"], ["35条書面も同様", "記名必要・押印不要（2022年改正）"]]}}},
  {id:10450,unit:'l_hoshu',level:3,field:'law',text:'宅建業者が代理として売買に関与した場合の報酬上限について正しいものはどれか。',opts:['媒介と同額（代金の3%+6万円）が上限','依頼者双方から合計4倍相当を受領できる','代理の依頼者から媒介の2倍（代金の3%+6万円の2倍）が上限で、依頼者双方合計でもこれを超えてはならない','代理の場合は報酬制限がない'],ans:2,exp:`代理の場合の報酬上限は媒介の2倍（代金の3%+6万円の2倍相当）ですが、売主・買主双方から合計してもこの2倍額を超えてはなりません（国土交通省告示）。`,"kaisetsu":{"topic": "報酬：売買は代金×3%+6万（400万超）・賃貸は借賃1か月・上限超過は不可", "basis": {"text": "売買（400万超）の一方からの上限は代金×3%+6万。双方合計は一方上限×2。賃貸（居住用・非居住用とも）は借賃1か月分。低廉な空家等（800万円以下）は、媒介報酬について原則の報酬額を超えて30万円（税別）まで受領できる場合があります（依頼者への説明・合意が必要）。", "example": ""}, "reason": {"text": "代理の場合、依頼者から受け取れる報酬上限は媒介の場合の2倍です（告示）。ただし売主・買主双方合計でも媒介の2倍（代金×6%＋12万円）を超えることはできません（告示）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対象</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（400万超）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万（一方）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（200万以下）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸（双方合計）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借賃1か月分</text></svg>", "choices": [{"label": "媒介と同額（代金の3%+6万円）が上限", "reason": "代理の場合は媒介の2倍（代金×6%＋12万円）まで依頼者から受け取れます（告示）。", "caution": "代理の報酬上限：媒介の2倍（告示）。"}, {"label": "依頼者双方から合計4倍相当を受領できる", "reason": "双方合計でも媒介の2倍（代金×6%＋12万円）が上限であり、4倍は誤りです（告示）。", "caution": ""}, {"label": "代理の場合は報酬制限がない", "reason": "代理の場合も報酬制限があります（告示）。制限なしは誤りです。", "caution": ""}], "summary": {"head": ["代理の報酬上限（告示）", "内容"], "rows": [["依頼者1人から（代理）", "媒介の2倍＝代金×6%＋12万円（税別）"], ["双方合計の上限", "代金×6%＋12万円（税別）"], ["媒介との比較", "媒介は一方から3%＋6万円・代理は一方から6%＋12万円"]]}}},
  {id:10451,unit:'l_hosho',level:3,field:'law',text:'保証協会が弁済業務保証金から弁済できる対象として正しいものはどれか。',opts:['宅建業者も含むすべての者','宅建業に関し取引をした者（宅建業者を除く）','宅建業者とその従業員のみ','保証協会が認めた者のみ'],ans:1,exp:`弁済業務保証金から弁済できる相手は「宅建業に関し取引をした者（宅建業者である者を除く）」です（宅建業法64条の8）。宅建業者同士の取引については弁済の対象外です。`,"kaisetsu":{"topic": "営業保証金・保証協会：主1,000万・従500万/営業保証金vs分担金60万・30万", "basis": {"text": "営業保証金は主1,000万・従500万（宅建業法25条）。保証協会の分担金は主60万・従30万（同法64条の9）。還付対象は業者以外の取引した者。加入は任意。不足補充は通知後2週間以内。", "example": ""}, "reason": {"text": "弁済業務保証金から弁済を受けられるのは宅建業者以外の者で、当該業者との宅建業に関する取引により損害を受けた者です（宅建業法64条の8第1項）。宅建業者間の取引は対象外です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">営業保証金と弁済業務保証金</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">営業保証金</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">弁済業務保証金（分担金）</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">主たる事務所</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000万円</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">60万円</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従たる事務所/所</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">500万円</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">還付対象</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者以外</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者以外</text></svg>", "choices": [{"label": "宅建業者も含むすべての者", "reason": "宅建業者は弁済の対象外です（宅建業法64条の8第1項）。「すべての者」は誤りです。", "caution": "弁済対象：宅建業者以外の者。宅建業者は除外。"}, {"label": "宅建業者とその従業員のみ", "reason": "従業員は弁済の対象ではなく、宅建業者以外の取引相手方が対象です（宅建業法64条の8第1項）。", "caution": ""}, {"label": "保証協会が認めた者のみ", "reason": "法律の要件を満たした者が当然に弁済を受けられます（宅建業法64条の8第1項）。保証協会の個別認可は不要です。", "caution": ""}], "summary": {"head": ["弁済業務保証金の弁済対象", "内容"], "rows": [["対象", "宅建業者以外の者（個人・法人）"], ["取引", "当該宅建業者との宅建業に関する取引"], ["除外", "宅建業者（宅建業者間取引は対象外）"], ["上限", "営業保証金相当額"]]}}},
  {id:10452,unit:'l_cooling',level:3,field:'law',text:'クーリングオフが行使された場合の宅建業者の義務として正しいものはどれか。',opts:['宅建業者は解除による損害賠償を請求できる','宅建業者は受領した手付金等を速やかに返還しなければならず損害賠償請求もできない','クーリングオフ後は宅建業者が代替物件を提供しなければならない','クーリングオフは口頭で行使できる'],ans:1,exp:`クーリングオフが行われると契約は解除され、宅建業者は受領した手付金等を速やかに返還しなければならず、損害賠償や違約金の請求もできません（宅建業法37条の2第3項）。クーリングオフは書面（または電磁的方法）で行使します。`,"kaisetsu":{"topic": "クーリングオフ：告知日から8日以内・書面で・事務所では不可・全額返還", "basis": {"text": "クーリングオフは告知を受けた日から8日以内に書面で行います（宅建業法37条の2）。事務所・モデルルーム等での申込みはクーリングオフ不可。解除後業者は全額返還（費用控除不可）。", "example": ""}, "reason": {"text": "クーリングオフが行使された場合、宅建業者は受領した手付金等を速やかに返還しなければならず（宅建業法37条の2第3項）、損害賠償・違約金の請求もできません（同条3項）。これは8種制限の一つです。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">クーリングオフのポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">告知日から8日以内</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">方法</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面（発信主義）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所での申込み</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">クーリングオフ不可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除後</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全額返還</text></svg>", "choices": [{"label": "宅建業者は解除による損害賠償を請求できる", "reason": "クーリングオフ後に損害賠償を請求することはできません（宅建業法37条の2第3項）。", "caution": "クーリングオフ後：損害賠償・違約金の請求不可（宅建業法37条の2第3項）。"}, {"label": "クーリングオフ後は宅建業者が代替物件を提供しなければならない", "reason": "代替物件の提供義務はありません（宅建業法37条の2第3項）。全額返還のみです。", "caution": ""}, {"label": "クーリングオフは口頭で行使できる", "reason": "クーリングオフは書面または電磁的方法（相手方承諾）で行います（宅建業法37条の2第2項）。口頭では無効です。", "caution": ""}], "summary": {"head": ["クーリングオフの効果（宅建業法37条の2第3項）", "内容"], "rows": [["宅建業者", "受領金額の全額返還義務"], ["損害賠償", "請求不可"], ["違約金", "控除不可"], ["買主", "何も支払う必要なし"]]}}},
  {id:10453,unit:'l_kantoku',level:3,field:'law',text:'宅建業者が取引相手に不当に低い価格で購入を勧誘した場合の規律として正しいものはどれか。',opts:['宅建業法上の規定はなく民法のみで対処する','宅建業法47条の2の規定（国交省省令）に基づく行政処分の対象となる','価格は自由なので規制されない','消費者契約法のみが適用される'],ans:1,exp:`宅建業者が取引の相手方に不当に低い価格で取引するよう勧誘することは宅建業法47条の2第3項・国交省省令（業務上の規制）により禁止されており、行政処分の対象となります。`,"kaisetsu":{"topic": "監督処分：業務停止最長1年・大臣は全業者に指示可・指示違反→業務停止", "basis": {"text": "業務停止の最長期間は1年（宅建業法65条2項）。大臣は全業者（知事免許含む）に指示処分を行う権限があります。指示処分違反→業務停止、業務停止違反→免許取消という段階があります。", "example": ""}, "reason": {"text": "宅建業者が不当に低い価格での買取勧誘等を行うことは宅建業法47条の2の省令（宅建業者の業務を適正に処理するための規則）に基づく行政処分の対象となります（宅建業法47条の2・65条）。消費者契約法も適用されますが、宅建業法上の規制もあります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">監督処分のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">処分</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">最長1年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣の権限</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全業者に指示可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">指示処分違反</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務停止の対象</text></svg>", "choices": [{"label": "宅建業法上の規定はなく民法のみで対処する", "reason": "宅建業法47条の2（および国土交通省省令）に基づく行政処分の対象となります。「宅建業法上の規定はない」は誤りです。", "caution": "不当な勧誘行為：宅建業法47条の2に基づく規制あり。"}, {"label": "価格は自由なので規制されない", "reason": "不当に低い価格での買取勧誘は宅建業法47条の2等に基づき規制されます。「価格は自由」は誤りです。", "caution": ""}, {"label": "消費者契約法のみが適用される", "reason": "消費者契約法も適用されますが、宅建業法の規制も独立して適用されます。「のみ」は誤りです。", "caution": ""}], "summary": {"head": ["宅建業者の勧誘規制（宅建業法47条・47条の2）", "内容"], "rows": [["不実の告知", "宅建業法47条1号→行政処分・刑事罰"], ["断定的判断の提供", "宅建業法47条2号→行政処分"], ["不当な勧誘行為", "宅建業法47条の2（省令）→行政処分"]]}}},
  {id:10454,unit:'k_toshi',level:3,field:'limit',text:'地区計画の決定権限として正しいものはどれか。',opts:['国土交通大臣','都道府県','市町村','都市計画審議会'],ans:2,exp:`地区計画は市町村が都市計画として定めます（都市計画法12条の4）。市町村が地域の実情に合わせて詳細な建築等に関するルールを設定できます。`,"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域の1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "地区計画は市町村が都市計画として定めます（都市計画法12条の4第1項・15条1項・19条1項）。国交大臣・都道府県ではなく、地域に最も身近な市町村が決定します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "国土交通大臣", "reason": "地区計画は市町村が定めます（都市計画法12条の4第1項）。国交大臣ではありません。", "caution": "地区計画：市町村が決定（都市計画法12条の4第1項・19条1項）。"}, {"label": "都道府県", "reason": "地区計画は市町村が定めます（都市計画法12条の4第1項）。都道府県ではありません。", "caution": ""}, {"label": "都市計画審議会", "reason": "都市計画審議会は諮問機関であり、地区計画を決定するのは市町村です（都市計画法12条の4第1項）。", "caution": ""}], "summary": {"head": ["都市計画の決定権限", "事項"], "rows": [["都道府県", "広域的・基盤的な都市計画（区域区分・都市計画道路等）"], ["市町村", "地区計画・地域地区等（都市計画法15条1項・19条1項）"], ["国交大臣", "複数都府県にまたがる都市計画等"]]}}},
  {id:10455,unit:'k_kenchiku',level:3,field:'limit',text:'都市計画区域内において建築確認が不要な行為として正しいものはどれか。',opts:['木造2階建て延べ100平方メートルの新築','鉄筋コンクリート造3階建ての大規模修繕','用途変更で床面積200平方メートル超となる場合','外壁の塗装のみの維持修繕（大規模の模様替えでないもの）'],ans:3,exp:`建築確認が不要な行為の例として、大規模の修繕・模様替えに該当しない通常の維持修繕（外壁塗装等）が挙げられます（建築基準法6条1項）。新築・大規模修繕・大規模模様替え・用途変更（200平方メートル超）は確認が必要です。`,"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・用途制限・道路斜線", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。防火地域の耐火建築物は隣地境界線に外壁を接して建築可（同法65条）。", "example": ""}, "reason": {"text": "外壁の塗装のみ（大規模の模様替えでない維持修繕）は建築確認不要です（建築基準法6条1項）。建築確認は新築・増改築・大規模修繕・大規模模様替え・用途変更に必要です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">防火地域の耐火建築物</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">隣地境界線に接して建築可</text></svg>", "choices": [{"label": "木造2階建て延べ100平方メートルの新築", "reason": "都市計画区域内での木造建築物の新築には建築確認が必要です（建築基準法6条1項4号）。", "caution": "外壁塗装（維持修繕）：建築確認不要（建築基準法6条1項）。"}, {"label": "鉄筋コンクリート造3階建ての大規模修繕", "reason": "大規模修繕は建築確認が必要です（建築基準法6条1項2号・3号）。", "caution": ""}, {"label": "用途変更で床面積200平方メートル超となる場合", "reason": "特殊建築物への用途変更で200㎡超の場合は建築確認が必要です（建築基準法87条1項）。", "caution": ""}], "summary": {"head": ["建築確認の要否", "判断"], "rows": [["外壁の塗装（維持修繕）", "不要"], ["新築（都市計画区域内）", "必要"], ["大規模修繕・模様替え", "必要"], ["特殊建築物への用途変更（200㎡超）", "必要"], ["10㎡以下の増築（防火地域外）", "不要"]]}}},
  {id:10456,unit:'k_nochi',level:3,field:'limit',text:'市街化区域内の農地を転用する場合の農地法上の手続きとして正しいものはどれか。',opts:['都道府県知事の許可が必要','農業委員会への届出のみで転用できる（農地法4条・5条の許可不要）','農林水産大臣の許可が必要','転用は一切認められない'],ans:1,exp:`市街化区域内の農地については農地法4条（自己転用）・5条（転用目的の権利移動）の許可は不要で、農業委員会への届出のみで転用できます（農地法4条1項8号・5条1項7号）。`,"kaisetsu":{"topic": "農地法：3条は農業委員会・4・5条は都道府県知事・市街化区域は届出のみ", "basis": {"text": "農地法3条の許可権者は農業委員会。4・5条は都道府県知事等。市街化区域の農地転用（4・5条）は農業委員会への届出のみOK。相続は許可不要・3か月以内の農業委員会への届出が必要。", "example": ""}, "reason": {"text": "市街化区域内の農地を転用する場合（農地法4条・5条）、都道府県知事の許可は不要で農業委員会への届出で足ります（農地法4条1項7号・5条1項7号）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text></svg>", "choices": [{"label": "都道府県知事の許可が必要", "reason": "市街化区域内の農地の転用は農業委員会への届出で足ります（農地法4条1項7号）。知事の許可は不要です。", "caution": "市街化区域内の農地転用：農業委員会への届出（許可不要・農地法4条1項7号・5条1項7号）。"}, {"label": "農林水産大臣の許可が必要", "reason": "市街化区域内の農地転用には農林水産大臣の許可は不要です（農地法4条1項7号）。", "caution": ""}, {"label": "転用は一切認められない", "reason": "市街化区域内の農地は届出により転用できます（農地法4条1項7号）。「一切認められない」は誤りです。", "caution": ""}], "summary": {"head": ["市街化区域内の農地の転用（農地法4条・5条）", "手続き"], "rows": [["自己転用（4条）", "農業委員会への届出（許可不要）"], ["転用目的の権利移動（5条）", "農業委員会への届出（許可不要）"]]}}},
  {id:10457,unit:'k_kokudo',level:3,field:'limit',text:'国土利用計画法の注視区域内での事前届出後の契約禁止期間として正しいものはどれか。',opts:['届出後3週間','届出後6週間','届出後30日','届出後はすぐに契約できる'],ans:1,exp:`注視区域内の事前届出では、届出後6週間は契約締結が禁止されます（国土利用計画法27条の7第2項）。この期間に知事が利用計画の変更勧告等を行う場合があります。`,"kaisetsu":{"topic": "国土利用計画法：事後届出は2週間以内・市街化区域は2,000㎡以上・規制区域は許可制", "basis": {"text": "事後届出は契約締結後2週間以内（国土利用計画法23条）。市街化区域は2,000㎡以上・市街化調整区域は5,000㎡以上・都市計画区域外は10,000㎡以上。届出義務者は買主のみ。規制区域は許可制。", "example": ""}, "reason": {"text": "注視区域内での事前届出後、知事が6週間以内に勧告しない旨の通知をすれば契約できます（国土利用計画法27条の7）。届出後6週間は契約できません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">国土利用計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">区域</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">基準面積</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2,000㎡以上</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化調整区域</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都市計画区域外</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10,000㎡以上</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">規制区域</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">許可制（届出ではない）</text></svg>", "choices": [{"label": "届出後3週間", "reason": "6週間が正しいです（国土利用計画法27条の7）。", "caution": "注視区域の契約禁止期間：6週間（国土利用計画法27条の7）。"}, {"label": "届出後30日", "reason": "6週間が正しいです（国土利用計画法27条の7）。", "caution": ""}, {"label": "届出後はすぐに契約できる", "reason": "6週間は契約できません（国土利用計画法27条の7）。", "caution": ""}], "summary": {"head": ["事前届出と契約禁止期間", "内容"], "rows": [["監視区域・注視区域（27条の6・7）", "届出後6週間は契約不可"], ["不勧告通知", "知事が6週間以内に通知すれば契約可"]]}}},
  {id:10458,unit:'k_kukaku',level:3,field:'limit',text:'仮換地が指定された場合の従前の土地（従前地）の使用収益権について正しいものはどれか。',opts:['従前地を引き続き自由に使用収益できる','仮換地を使用収益でき、従前地の使用収益は原則として停止される','仮換地と従前地の双方を使用収益できる','換地処分が完了するまで一切の権利行使ができない'],ans:1,exp:`仮換地が指定されると、従前地の使用収益権は停止され、仮換地を使用収益できます（土地区画整理法99条）。換地処分の公告後は換地が従前地とみなされます。`,"kaisetsu":{"topic": "土地区画整理法：換地は公告翌日確定・仮換地は従前地使用不可・組合は2/3以上", "basis": {"text": "換地処分の公告翌日から換地が確定します（土地区画整理法104条）。仮換地の指定後は従前地を使用できなくなります（同法99条）。組合設立には土地所有者・借地権者の各2/3以上の同意が必要です。", "example": ""}, "reason": {"text": "仮換地が指定された場合、指定の効力発生日から仮換地について使用収益が可能となり、従前の宅地の使用収益は原則として停止されます（土地区画整理法99条1項・2項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">土地区画整理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">換地の確定</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公告の翌日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮換地指定後</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従前地は使用不可（所有権は残る）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">組合設立</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各2/3以上の同意</text></svg>", "choices": [{"label": "従前地を引き続き自由に使用収益できる", "reason": "仮換地指定後は従前地の使用収益が停止されます（土地区画整理法99条2項）。", "caution": "仮換地指定後：仮換地で使用収益可・従前地の使用収益停止（土地区画整理法99条）。"}, {"label": "仮換地と従前地の双方を使用収益できる", "reason": "両方は認められません（土地区画整理法99条1項・2項）。", "caution": ""}, {"label": "換地処分が完了するまで一切の権利行使ができない", "reason": "仮換地について使用収益はできます（土地区画整理法99条1項）。", "caution": ""}], "summary": {"head": ["仮換地指定の効果（土地区画整理法99条）", "内容"], "rows": [["仮換地", "使用収益可"], ["従前地", "使用収益停止"]]}}},
  {id:10459,unit:'k_mori',level:3,field:'limit',text:'盛土規制法（宅地造成及び特定盛土等規制法）における「特定盛土等規制区域」について正しいものはどれか。',opts:['市街化区域にのみ指定できる','宅地造成工事規制区域と必ず重複する','市街地から離れた山林等でも盛土崩落が人家等に危害を及ぼす恐れがある場合に都道府県知事が指定できる','国土交通大臣が指定する'],ans:2,exp:`特定盛土等規制区域は都道府県知事が指定します。市街地から離れた山林・農地等でも盛土が崩落した場合に人家等に危害を及ぼす恐れがある区域に指定されます（盛土規制法26条）。`,"kaisetsu":{"topic": "盛土規制法・宅地造成：盛土は1m超・切土は2m超・特定盛土等規制区域", "basis": {"text": "盛土で高さ1mを超える崖を生じる場合は許可が必要（盛土規制法）。切土は2mを超える崖で許可が必要。特定盛土等規制区域内の一定規模以上の盛土等は許可が必要です。農地・森林も規制対象に含まれます。", "example": ""}, "reason": {"text": "特定盛土等規制区域は市街地から離れた山林・農地等でも盛土崩落が人家等に危害を及ぼす恐れがある場合に都道府県知事が指定する区域です（宅地造成及び特定盛土等規制法26条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">盛土規制法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">工事種別</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可が必要な規模</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">切土</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">高さ2mを超える崖</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">盛土</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">高さ1mを超える崖</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">面積</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">500㎡超の宅地造成</text></svg>", "choices": [{"label": "市街化区域にのみ指定できる", "reason": "山林・農地等にも指定できます（宅地造成及び特定盛土等規制法26条1項）。", "caution": "特定盛土等規制区域：山林・農地等にも指定可（宅地造成及び特定盛土等規制法26条1項）。"}, {"label": "宅地造成工事規制区域と必ず重複する", "reason": "重複して指定できますが「必ず重複」するわけではありません（宅地造成及び特定盛土等規制法26条）。", "caution": ""}, {"label": "国土交通大臣が指定する", "reason": "都道府県知事が指定します（宅地造成及び特定盛土等規制法26条1項）。", "caution": ""}], "summary": {"head": ["特定盛土等規制区域の特徴", "内容"], "rows": [["指定者", "都道府県知事"], ["場所", "市街地から離れた山林・農地等でも指定可"], ["目的", "盛土崩落による人家等への危害防止"]]}}},
  {id:10460,unit:'r_sorin',level:3,field:'rights',text:'共有物の不分割特約（分割禁止の合意）について正しいものはどれか。',opts:['共有者は不分割特約を締結できない','共有者は最長5年間の不分割特約を定めることができ、更新することもできる','不分割特約は最長2年で更新できない','不分割特約を定めると永久に分割請求できなくなる'],ans:1,exp:`共有者は協議により最長5年間（更新可）の不分割特約を定めることができます（民法256条1項ただし書・2項）。共有物の分割は協議→裁判（共有物分割請求訴訟）の順で行います。`,"kaisetsu":{"topic": "相隣関係：竹木の根は自ら切除可・枝は原則所有者に・境界から50cmは慣習で変更可", "basis": {"text": "竹木の根が境界を越えたら自ら切除可（民法233条2項）。枝は原則として所有者に切除させます。建物の境界からの距離（50cm）は慣習・条例で変更可（民法234条・236条）。袋地通行権は有償が原則（民法212条）。", "example": ""}, "reason": {"text": "共有者は不分割特約（分割禁止の合意）を定めることができますが、期間は5年以内に限られます（民法256条1項ただし書）。5年以内であれば更新も可能です。5年を超える期間の不分割特約は5年に短縮されます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相隣関係のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">事項</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">ルール</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">竹木の根（越境）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自ら切除可</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">竹木の枝（越境）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">原則：所有者に切除させる</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">境界距離（50cm）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">慣習・条例で変更可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">袋地通行権</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有償が原則</text></svg>", "choices": [{"label": "共有者は不分割特約を締結できない", "reason": "共有者は最長5年間の不分割特約を定めることができます（民法256条1項ただし書）。「締結できない」は誤りです。", "caution": "不分割特約＝最長5年間（更新可・民法256条1項ただし書）。"}, {"label": "不分割特約は最長2年で更新できない", "reason": "不分割特約の最長期間は5年です（民法256条1項ただし書）。2年ではありません。更新も可能です。", "caution": ""}, {"label": "不分割特約を定めると永久に分割請求できなくなる", "reason": "不分割特約は最長5年間の効力しかなく、永久ではありません（民法256条1項ただし書）。", "caution": ""}], "summary": {"head": ["不分割特約（民法256条1項ただし書）", "内容"], "rows": [["有効期間", "5年以内"], ["5年超の特約", "5年に短縮"], ["更新", "可能（5年以内の範囲で繰り返し更新可）"], ["登記", "第三者への対抗には登記が必要（不動産登記法59条）"]]}}},
  {id:10461,unit:'l_kokoku',level:3,field:'law',text:'宅建業者の取引態様の明示義務について正しいものはどれか。',opts:['広告時のみ取引態様を明示すれば足りる','広告時だけでなく注文または申込みを受けた際にも取引態様を明示しなければならない','電話による問い合わせには取引態様の明示は不要','取引態様を誤記しても行政処分の対象とはならない'],ans:1,exp:`宅建業者は広告をする際だけでなく、注文または申込みを受けた際にも遅滞なく取引態様（売主・代理・媒介の別）を明示しなければなりません（宅建業法34条1項・2項）。`,"kaisetsu":{"topic": "宅建業者の広告：開発許可後に広告可・誇大広告は全媒体禁止・取引態様は広告時と注文時両方", "basis": {"text": "開発許可・建築確認後（工事中でも）広告できます（宅建業法33条）。誇大広告禁止は全媒体・全対象者に適用（同法32条）。取引態様は広告時と注文受領時の両方で明示が必要（同法34条）。", "example": ""}, "reason": {"text": "取引態様の明示は広告時と注文受領時の両方で行わなければなりません（宅建業法34条1項・2項）。電話による問い合わせも注文受領に準じた扱いとなります。明示違反は行政処分の対象です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">広告規制のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">広告開始時期</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築確認・開発許可後</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誇大広告禁止</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">媒体・対象問わず</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取引態様の明示</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">広告時と注文時の両方</text></svg>", "choices": [{"label": "広告時のみ取引態様を明示すれば足りる", "reason": "注文または申込みを受けた際にも明示が必要です（宅建業法34条2項）。「広告時のみ」では不足です。", "caution": ""}, {"label": "電話による問い合わせには取引態様の明示は不要", "reason": "電話による注文・申込みにも明示義務が及びます（宅建業法34条2項）。「不要」は誤りです。", "caution": "電話による注文にも明示義務あり（宅建業法34条2項）。"}, {"label": "取引態様を誤記しても行政処分の対象とはならない", "reason": "取引態様の明示義務違反は行政処分の対象となります（宅建業法65条）。誤記でも同様です。", "caution": ""}], "summary": {"head": ["取引態様の明示時期（宅建業法34条）", "内容"], "rows": [["①広告時", "宅建業者が広告をするとき（同条1項）"], ["②注文・申込み受領時", "電話・対面・書面等を問わず（同条2項）"], ["明示方法", "書面・電磁的方法・口頭等（実務上は書面が多い）"], ["違反", "行政処分の対象（宅建業法65条）"]]}}},
  {id:10462,unit:'r_ishi',level:3,field:'rights',text:'心裡留保（民法93条）の効力として正しいものはどれか。',opts:['常に無効','相手方が悪意（知っていた）または有過失（知ることができた）の場合のみ無効で、原則は有効','常に有効であり相手方の知・不知は問わない','相手方の知・不知にかかわらず取り消せる'],ans:1,exp:`心裡留保（冗談・嘘の意思表示）は原則有効です。ただし相手方が表意者の真意を知りまたは知ることができた場合（悪意・有過失）は無効となります（民法93条1項ただし書）。`,"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失保護）・通謀虚偽表示（無効・善意保護）。", "example": ""}, "reason": {"text": "心裡留保は内心と異なる意思表示です。相手方が真意と異なることを知らなかった（善意）場合は相手方を保護して意思表示を有効とします。相手方が真意を知っていた場合は保護の必要がなく無効とします（民法93条1項）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "常に無効", "reason": "心裡留保は相手方が善意かつ無過失であれば有効です（民法93条1項本文）。常に無効は誤りです。", "caution": ""}, {"label": "常に有効であり相手方の知・不知は問わない", "reason": "相手方が悪意または有過失の場合は無効となります（民法93条1項ただし書）。相手方の知・不知は効力に影響します。", "caution": ""}, {"label": "相手方の知・不知にかかわらず取り消せる", "reason": "心裡留保は取消しではなく無効の問題です。また相手方が善意無過失であれば無効にもなりません。", "caution": "心裡留保の効果は「無効」であり「取消し」ではありません。"}], "summary": {"head": ["相手方の状態", "効力"], "rows": [["善意かつ無過失", "有効"], ["悪意（真意を知っていた）", "無効"], ["有過失（知ることができた）", "無効"]]}}},
  {id:10463,unit:'r_saikensoron',level:3,field:'rights',text:'債権者代位権（民法423条）の行使要件として正しいものはどれか。',opts:['被保全債権が弁済期到来前でも常に行使できる','原則として債務者が無資力であること（債権者を害する状態）が必要','債務者の同意が必要','裁判上のみ行使できる'],ans:1,exp:`債権者代位権の行使には原則として債務者の無資力（債権保全の必要性）が必要です（民法423条1項）。被保全債権が弁済期未到来の場合は保全行為に限り行使できます（同条2項）。裁判外でも行使可能です。`,"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要（民法446条2項）。連帯保証人は催告・検索の抗弁権なし（民法454条）。債権譲渡の第三者対抗は確定日付ある証書による通知・承諾（民法467条2項）。相殺の絶対的効力：弁済・更改・相殺。", "example": ""}, "reason": {"text": "債権者代位権（民法423条1項）は原則として債務者が無資力（自己の債権を全額回収できない状態）であることが要件です。ただし特定債権保全（例：不動産の移転登記請求権の代位）は無資力要件が不要です（民法423条の7）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">催告・検索の抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text></svg>", "choices": [{"label": "被保全債権が弁済期到来前でも常に行使できる", "reason": "原則として被保全債権の弁済期が到来していることが要件です（民法423条2項）。弁済期前でも裁判外の保全行為等は可能です。", "caution": "弁済期前：原則行使不可（保存行為等を除く）。"}, {"label": "債務者の同意が必要", "reason": "債権者代位権は債務者の同意なく行使できます（民法423条1項）。", "caution": ""}, {"label": "裁判上のみ行使できる", "reason": "債権者代位権は裁判外でも行使できます（民法423条1項）。", "caution": ""}], "summary": {"head": ["債権者代位権の要件（民法423条）", "内容"], "rows": [["①被保全債権の存在", "弁済期到来が原則必要"], ["②無資力", "債務者が自己の全債務を支払えない状態"], ["③債務者が権利行使しない", "行使しない・遅延している"], ["例外", "特定債権保全は無資力不要（民法423条の7）"]]}}},
  {id:10464,unit:'l_hosho',level:3,field:'law',text:'保証協会の社員を退社した宅建業者の義務として正しいものはどれか。',opts:['退社後は何も義務がない','退社後1週間以内に営業保証金を供託しなければ宅建業を継続できない','退社後はただちに廃業しなければならない','退社後は直ちに他の保証協会に加入しなければならない'],ans:1,exp:`保証協会を退社した宅建業者は退社後1週間以内に営業保証金を供託しなければなりません（宅建業法64条の15）。供託しなければ宅建業を継続できません。`,"kaisetsu":{"topic": "営業保証金・保証協会：主1,000万・従500万/営業保証金vs分担金60万・30万", "basis": {"text": "営業保証金は主1,000万・従500万（宅建業法25条）。保証協会の分担金は主60万・従30万（同法64条の9）。還付対象は業者以外の取引した者。加入は任意。不足補充は通知後2週間以内。", "example": ""}, "reason": {"text": "保証協会を退社した宅建業者は、退社後1週間以内に営業保証金を供託しなければ宅建業を継続できません（宅建業法64条の15第2項）。1週間以内に供託・届出を完了することが必要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">営業保証金と弁済業務保証金</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">営業保証金</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">弁済業務保証金（分担金）</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">主たる事務所</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000万円</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">60万円</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従たる事務所/所</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">500万円</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">還付対象</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者以外</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業者以外</text></svg>", "choices": [{"label": "退社後は何も義務がない", "reason": "退社後1週間以内に営業保証金の供託が必要です（宅建業法64条の15第2項）。「義務なし」は誤りです。", "caution": "保証協会退社→1週間以内に営業保証金供託が必要（宅建業法64条の15第2項）。"}, {"label": "退社後はただちに廃業しなければならない", "reason": "廃業ではなく、1週間以内に営業保証金を供託すれば宅建業を継続できます（宅建業法64条の15第2項）。", "caution": ""}, {"label": "退社後は直ちに他の保証協会に加入しなければならない", "reason": "他の保証協会への加入は義務ではありません（宅建業法64条の15第2項）。営業保証金を供託することで業を継続できます。", "caution": ""}], "summary": {"head": ["保証協会退社後の手続き", "内容"], "rows": [["期限", "退社後1週間以内"], ["必要な措置", "営業保証金の供託"], ["供託額", "主たる事務所1000万円＋従たる事務所分"], ["継続不可", "1週間以内に供託しない場合は宅建業継続不可"]]}}},
  {id:10465,unit:'r_dairi',level:3,field:'rights',text:'任意代理における復代理人の選任要件として正しいものはどれか（現行民法）。',opts:['代理人は常に自由に復代理人を選任できる','本人の許諾または已むを得ない事由がある場合に選任でき、代理人は選任・監督について本人に責任を負う','復代理人の選任には本人の書面による同意が必要','復代理人を選任しても代理人の権限は消滅しない（正しい）の他に代理人は一切責任を負わない'],ans:1,exp:`任意代理人は本人の許諾または已むを得ない事由がある場合に復代理人を選任でき（民法104条）、選任した場合は選任及び監督について本人に対し責任を負います（民法105条）。`,"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護します。", "example": ""}, "reason": {"text": "任意代理人の復任権は制限されます（民法104条）。本人の許諾または止むを得ない事由がある場合にのみ復代理人を選任でき、代理人は選任・監督について本人に責任を負います。復代理人を選任しても代理人の権限は消滅しません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "代理人は常に自由に復代理人を選任できる", "reason": "任意代理人の復任権は本人の許諾または止むを得ない事由がある場合に限られます（民法104条）。常に自由に選任できるのは法定代理人です。", "caution": "任意代理人≠自由に復任可。法定代理人＝原則自由に復任可。"}, {"label": "復代理人の選任には本人の書面による同意が必要", "reason": "書面による同意は要求されていません（民法104条）。口頭の許諾でも足ります。", "caution": ""}, {"label": "復代理人を選任しても代理人の権限は消滅しない（正しい）の他に代理人は一切責任を負わない", "reason": "復代理人を選任しても代理人の権限は消滅しませんが、代理人は選任・監督について本人に責任を負います（民法105条）。「一切責任を負わない」は誤りです。", "caution": ""}], "summary": {"head": ["代理の種類", "復任権", "責任"], "rows": [["任意代理", "本人の許諾または止むを得ない事由（民法104条）", "選任・監督責任"], ["法定代理", "原則自由（民法105条）", "選任・監督責任（止むを得ない場合は軽減）"]]}}},
  {id:10466,unit:'k_toshi',level:3,field:'limit',text:'都市計画における用途地域の指定義務について正しいものはどれか。',opts:['市街化調整区域には必ず用途地域を定めなければならない','市街化区域には少なくとも用途地域を定めなければならない','準都市計画区域には必ず用途地域を定めなければならない','用途地域の指定は都市計画区域外でしか行えない'],ans:1,exp:`市街化区域には少なくとも用途地域を定めなければなりません（都市計画法13条1項7号）。市街化調整区域には原則として用途地域を定めません。準都市計画区域にも用途地域の指定は可能ですが義務ではありません。`,"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域の1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "市街化区域には少なくとも用途地域を定めなければなりません（都市計画法13条1項7号）。市街化調整区域には原則として用途地域を定めません（同法13条1項7号ただし書等）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "市街化調整区域には必ず用途地域を定めなければならない", "reason": "市街化調整区域には原則として用途地域を定めません（都市計画法13条1項7号ただし書等）。", "caution": "市街化区域：用途地域の定めが義務。市街化調整区域：原則定めない。"}, {"label": "準都市計画区域には必ず用途地域を定めなければならない", "reason": "準都市計画区域での用途地域指定は任意です（都市計画法5条の2・8条）。", "caution": ""}, {"label": "用途地域の指定は都市計画区域外でしか行えない", "reason": "用途地域は都市計画区域内に定めます（都市計画法8条1項）。区域外での指定はできません。", "caution": ""}], "summary": {"head": ["用途地域の指定義務", "内容"], "rows": [["市街化区域", "少なくとも用途地域を定める義務（都市計画法13条1項7号）"], ["市街化調整区域", "原則として用途地域を定めない"], ["準都市計画区域", "任意で定めることができる"], ["非線引き区域", "任意で定めることができる"]]}}},
  {id:10467,unit:'k_kenchiku',level:3,field:'limit',text:'日影規制（建築基準法56条の2）の対象外となる用途地域として正しいものはどれか。',opts:['第1種低層住居専用地域','近隣商業地域','商業地域・工業地域・工業専用地域','準住居地域'],ans:2,exp:`日影規制は商業地域・工業地域・工業専用地域には適用されません（建築基準法56条の2）。住居系用途地域・近隣商業地域・準工業地域等が対象です。各自治体の条例によりさらに詳細が定まります。`,"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・用途制限・道路斜線", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。防火地域の耐火建築物は隣地境界線に外壁を接して建築可（同法65条）。", "example": ""}, "reason": {"text": "日影規制（建築基準法56条の2）は商業地域・工業地域・工業専用地域には適用されません。これらは業務・工業用途が中心であり、日照環境の保護より業務・工業活動を優先するためです。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">防火地域の耐火建築物</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">隣地境界線に接して建築可</text></svg>", "choices": [{"label": "第1種低層住居専用地域", "reason": "第1種低層住居専用地域には日影規制が適用されます（建築基準法56条の2第1項）。対象外ではありません。", "caution": "日影規制の適用除外：商業地域・工業地域・工業専用地域（建築基準法56条の2第1項）。"}, {"label": "近隣商業地域", "reason": "近隣商業地域には日影規制が適用されます（建築基準法56条の2第1項）。対象外ではありません。", "caution": ""}, {"label": "準住居地域", "reason": "準住居地域には日影規制が適用されます（建築基準法56条の2第1項）。対象外ではありません。", "caution": ""}], "summary": {"head": ["日影規制の適用地域・除外地域（建築基準法56条の2第1項）", "適用"], "rows": [["住居系地域", "全て適用"], ["近隣商業地域", "適用"], ["準工業地域", "適用"], ["商業地域・工業地域・工業専用地域", "適用除外"]]}}},
  // ===== 追加100問（9403〜9502）=====
  // 盛土規制法・宅造法（k_mori）
  {id:10468,unit:"k_mori",level:1,field:"limit",text:"宅地造成及び特定盛土等規制法における「宅地造成工事規制区域」を指定する者として正しいものはどれか。",opts:["国土交通大臣","都道府県知事（または指定都市の長）","市町村長","農業委員会"],ans:1,exp:"宅地造成工事規制区域は都道府県知事（政令指定都市・中核市では市長）が指定します（盛土規制法10条）。","kaisetsu":{"topic":"盛土規制法：宅地造成等工事規制区域の指定権者","basis":{"text":"宅地造成等工事規制区域は、都道府県知事が指定します。指定都市・中核市等では、それぞれの長が権限を持つ場合があります（宅地造成及び特定盛土等規制法10条）。","example":"一定の市街地等で盛土等による災害防止のため規制が必要な区域について、都道府県知事等が宅地造成等工事規制区域を指定します。"},"reason":{"text":"宅地造成等工事規制区域の指定権者は都道府県知事です。指定都市・中核市等では市長が権限を持つ場合があります。国土交通大臣や市町村が常に指定するわけではありません。"},"svg":"","choices":[{"label":"国土交通大臣","reason":"盛土規制法上の区域指定は原則として都道府県知事等が行います。国土交通大臣ではありません。","caution":""},{"label":"市町村長","reason":"指定都市・中核市等の長が権限を持つ場合はありますが、一般に市町村長が指定するわけではありません。","caution":""},{"label":"農業委員会","reason":"農業委員会は農地法上の許可等で問題になりますが、盛土規制法の区域指定権者ではありません。","caution":""}],"summary":{"head":["区域","指定権者"],"rows":[["宅地造成等工事規制区域","都道府県知事等"],["特定盛土等規制区域","都道府県知事等"],["指定都市・中核市等","市長が権限を持つ場合あり"]]}}},
  {id:10469,unit:'k_mori',level:1,field:'limit',text:'宅地造成工事規制区域内で許可が必要な工事として正しいものはどれか。',opts:['高さ50cmの切土','高さ1mを超える切土','高さ2mを超える盛土','面積100㎡の造成'],ans:2,exp:'宅地造成等工事規制区域内では、盛土で高さ1m超の崖を生じる工事、切土で高さ2m超の崖を生じる工事、崖を生じない盛土でも高さ2m超の工事、面積500㎡超の盛土・切土等について知事の許可が必要です（盛土規制法12条・同法施行令3条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "宅地造成等工事規制区域内で許可が必要な工事には、盛土で高さ1m超の崖を生じるもののほか、崖を生じない盛土でも高さ2mを超えるものがあります（宅地造成及び特定盛土等規制法施行令3条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "高さ50cmの切土", "reason": "高さ50cmの切土は許可対象外です（施行令3条）。", "caution": "高さ2m超の盛土（崖を生じるもの）：許可必要（施行令3条）。"}, {"label": "高さ1mを超える切土", "reason": "高さ2m超の崖を生じる切土が許可対象です（施行令3条）。1m超の切土はすべて許可対象ではありません。", "caution": ""}, {"label": "面積100㎡の造成", "reason": "面積100㎡の造成は許可対象外です（施行令3条）。500㎡超の切土・盛土が面積基準です。", "caution": ""}], "summary": {"head": ["許可が必要な工事（施行令3条）", "内容"], "rows": [["切土", "2m超の崖を生じるもの"], ["盛土", "1m超の崖を生じるもの"], ["面積", "500m2超"]]}}},
  {id:10470,unit:'k_mori',level:2,field:'limit',text:'特定盛土等規制区域と宅地造成工事規制区域の違いとして正しいものはどれか。',opts:['特定盛土等規制区域は市街地のみに指定できる','特定盛土等規制区域は市街地から離れた山林・農地等にも指定できる','両区域は重複して指定できない','特定盛土等規制区域では届出は不要'],ans:1,exp:'特定盛土等規制区域は市街地から離れた山林・農地等でも盛土崩落が人家等に危害を与えるおそれがある区域に指定されます。宅地造成工事規制区域との重複指定は認められていません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "特定盛土等規制区域は市街地から離れた山林・農地等にも指定できます（宅地造成及び特定盛土等規制法26条1項）。宅地造成工事規制区域と重複して指定することも可能です（同条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "特定盛土等規制区域は市街地のみに指定できる", "reason": "山林・農地等にも指定できます（宅地造成及び特定盛土等規制法26条1項）。", "caution": "特定盛土等規制区域：山林・農地等にも指定可（宅地造成及び特定盛土等規制法26条1項）。"}, {"label": "両区域は重複して指定できない", "reason": "重複指定できます（宅地造成及び特定盛土等規制法26条）。", "caution": ""}, {"label": "特定盛土等規制区域では届出は不要", "reason": "特定盛土等規制区域でも一定の盛土等には届出または許可が必要です（宅地造成及び特定盛土等規制法30条）。", "caution": ""}], "summary": {"head": ["特定盛土等規制区域の特徴", "内容"], "rows": [["指定場所", "市街地から離れた山林等にも指定可"], ["重複指定", "宅地造成工事規制区域との重複可"]]}}},
  {id:10471,unit:'k_mori',level:2,field:'limit',text:'盛土規制法における「造成宅地防災区域」の指定目的として正しいものはどれか。',opts:['農地の転用を規制するため','既存の宅地造成地で災害発生のおそれがある区域を指定し防災措置を促すため','新規開発を禁止するため','固定資産税を軽減するため'],ans:1,exp:'造成宅地防災区域は既に造成された宅地で地盤が軟弱・崩落のおそれがある区域を知事が指定し、土地所有者等に擁壁設置等の防災措置を勧告・命令できる制度です（盛土規制法45条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "造成宅地防災区域は既存の宅地造成地で災害発生のおそれがある区域を指定し、区域内の宅地所有者等に防災措置を促すための制度です（宅地造成及び特定盛土等規制法45条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "農地の転用を規制するため", "reason": "造成宅地防災区域は農地転用規制ではありません（宅地造成及び特定盛土等規制法45条）。", "caution": "造成宅地防災区域：既存宅地の災害リスク対応（宅地造成及び特定盛土等規制法45条）。"}, {"label": "新規開発を禁止するため", "reason": "既存の宅地の防災が目的であり、新規開発禁止のためではありません（宅地造成及び特定盛土等規制法45条）。", "caution": ""}, {"label": "固定資産税を軽減するため", "reason": "固定資産税の軽減は造成宅地防災区域の目的ではありません（宅地造成及び特定盛土等規制法45条）。", "caution": ""}], "summary": {"head": ["造成宅地防災区域（宅地造成及び特定盛土等規制法45条）", "内容"], "rows": [["対象", "既存の宅地造成地で災害のおそれがある区域"], ["目的", "宅地所有者等への防災措置の促進"]]}}},
  {id:10472,unit:'k_mori',level:3,field:'limit',text:'宅地造成工事規制区域内の工事で許可が不要なケースとして正しいものはどれか。',opts:['高さ3mの盛土','面積600㎡の切土を伴う造成','通常の管理行為・軽微な行為として政令で定めるもの','高さ1.5mの切土'],ans:2,exp:'通常の管理行為や軽微な行為として政令で定めるものは許可不要です（盛土規制法12条ただし書）。高さ2m超の盛土・高さ1m超の切土・面積500㎡超等は原則許可が必要です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "宅地造成工事規制区域内でも通常の管理行為・軽微な行為として政令で定めるものは許可不要です（宅地造成及び特定盛土等規制法施行令4条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "高さ3mの盛土", "reason": "高さ1m超の崖を生じる盛土は許可が必要です（施行令3条）。", "caution": "通常の管理行為・軽微な行為：許可不要（施行令4条）。"}, {"label": "面積600㎡の切土を伴う造成", "reason": "500㎡超の切土・盛土は許可が必要です（施行令3条）。", "caution": ""}, {"label": "高さ1.5mの切土", "reason": "高さ2m超の崖を生じる切土が許可対象ですが（施行令3条）、1.5mの切土でも500㎡超等の場合は許可が必要です。", "caution": ""}], "summary": {"head": ["許可不要の行為（施行令4条）", "内容"], "rows": [["通常の管理行為", "草刈り・軽微な排水路清掃等"], ["軽微な行為", "政令で定める小規模な行為"]]}}},
  // 統計・土地・建物の知識（t_tokei）
  {id:10473,unit:'t_tokei',level:1,field:'tax',text:'地価公示の公示価格の性格として正しいものはどれか。',opts:['相続税路線価の基準となる','土地取引の指標・公共事業用地の取得価格の基準となる標準的な価格','固定資産税評価額と同一','毎月更新される'],ans:1,exp:'地価公示の公示価格は一般の土地取引の指標や公共事業用地取得の基準として機能します（地価公示法1条）。毎年1月1日時点の価格を3月に公示します。',"kaisetsu":{"topic": "不動産統計・建物・土地の知識", "basis": {"text": "住宅着工戸数は近年80万戸前後で推移。首都圏マンション価格は上昇傾向。J-REITの運用資産は拡大傾向。中古住宅流通は活発化傾向。フラット35は全期間固定・各金融機関が金利設定・15年以上35年以下。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産統計・フラット35のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">近年の傾向</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅着工戸数</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">80万戸前後</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">首都圏マンション価格</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">上昇傾向</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">J-REIT</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">拡大傾向</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">フラット35の金利</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全期間固定・各金融機関が設定</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10474,unit:'t_tokei',level:1,field:'tax',text:'木造住宅の耐用年数として住宅金融支援機構が定める基準として最も近いものはどれか。',opts:['15年','22年','30年','50年'],ans:2,exp:'木造住宅の法定耐用年数は22年です（税法上）。住宅金融支援機構の融資でも耐用年数が審査基準の一つとなります。',"kaisetsu":{"topic": "不動産統計・建物・土地の知識", "basis": {"text": "住宅着工戸数は近年80万戸前後で推移。首都圏マンション価格は上昇傾向。J-REITの運用資産は拡大傾向。中古住宅流通は活発化傾向。フラット35は全期間固定・各金融機関が金利設定・15年以上35年以下。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産統計・フラット35のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">近年の傾向</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅着工戸数</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">80万戸前後</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">首都圏マンション価格</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">上昇傾向</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">J-REIT</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">拡大傾向</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">フラット35の金利</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全期間固定・各金融機関が設定</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10475,unit:'t_tokei',level:2,field:'tax',text:'沖積低地と洪積台地の比較として正しいものはどれか。',opts:['沖積低地の方が地盤が安定している','洪積台地の方が液状化リスクが高い','洪積台地は比較的古い時代に形成され地盤が安定している','沖積低地は宅地として最適'],ans:2,exp:'洪積台地は数万年以上前に形成された安定した地盤で宅地に適しています。沖積低地は比較的新しく形成され液状化・洪水のリスクが高いため宅地には注意が必要です。',"kaisetsu":{"topic": "不動産統計・建物・土地の知識", "basis": {"text": "住宅着工戸数は近年80万戸前後で推移。首都圏マンション価格は上昇傾向。J-REITの運用資産は拡大傾向。中古住宅流通は活発化傾向。フラット35は全期間固定・各金融機関が金利設定・15年以上35年以下。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産統計・フラット35のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">近年の傾向</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅着工戸数</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">80万戸前後</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">首都圏マンション価格</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">上昇傾向</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">J-REIT</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">拡大傾向</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">フラット35の金利</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全期間固定・各金融機関が設定</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10476,unit:'t_tokei',level:2,field:'tax',text:'建物の構造に関する記述として正しいものはどれか。',opts:['鉄筋コンクリート造は引張力に弱い','鉄骨造は耐火性が高い','鉄筋コンクリート造はコンクリートの圧縮力と鉄筋の引張力を組み合わせた構造','木造は耐火性が最も高い'],ans:2,exp:'鉄筋コンクリート造（RC造）はコンクリートの圧縮強度と鉄筋の引張強度を組み合わせることで高い耐久性を実現しています。鉄骨造は耐火被覆が必要です。',"kaisetsu":{"topic": "不動産統計・建物・土地の知識", "basis": {"text": "住宅着工戸数は近年80万戸前後で推移。首都圏マンション価格は上昇傾向。J-REITの運用資産は拡大傾向。中古住宅流通は活発化傾向。フラット35は全期間固定・各金融機関が金利設定・15年以上35年以下。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産統計・フラット35のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">近年の傾向</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅着工戸数</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">80万戸前後</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">首都圏マンション価格</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">上昇傾向</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">J-REIT</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">拡大傾向</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">フラット35の金利</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全期間固定・各金融機関が設定</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10477,unit:'t_tokei',level:3,field:'tax',text:'不動産鑑定評価の三手法のうち「収益還元法」の説明として正しいものはどれか。',opts:['類似の取引事例を比較する方法','対象不動産が将来生み出す収益を現在価値に換算して求める方法','再調達原価から減価修正を行う方法','固定資産税評価額を基礎とする方法'],ans:1,exp:'収益還元法は対象不動産が将来生み出すと期待される純収益を還元利回りで割り引いて現在価値を求める方法です。賃貸不動産や事業用不動産の評価に特に有効です。',"kaisetsu":{"topic": "不動産統計・建物・土地の知識", "basis": {"text": "住宅着工戸数は近年80万戸前後で推移。首都圏マンション価格は上昇傾向。J-REITの運用資産は拡大傾向。中古住宅流通は活発化傾向。フラット35は全期間固定・各金融機関が金利設定・15年以上35年以下。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産統計・フラット35のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">近年の傾向</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅着工戸数</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">80万戸前後</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">首都圏マンション価格</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">上昇傾向</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">J-REIT</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">拡大傾向</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">フラット35の金利</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全期間固定・各金融機関が設定</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  // 住宅金融支援機構（t_kinyu）
  {id:10478,unit:'t_kinyu',level:1,field:'tax',text:'住宅金融支援機構の主な業務として正しいものはどれか。',opts:['住宅の直接販売','民間金融機関が貸し付けた住宅ローン債権を買い取る証券化支援業務','固定資産税の徴収','建築確認の審査'],ans:1,exp:'住宅金融支援機構は民間金融機関が貸し付けた住宅ローン債権を買い取り証券化する「フラット35」等の証券化支援業務を主な業務としています（住宅金融支援機構法13条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10479,unit:'t_kinyu',level:1,field:'tax',text:'フラット35の特徴として正しいものはどれか。',opts:['変動金利型のローン','全期間固定金利型の住宅ローン','10年固定後変動に切り替わる','金利は毎月変わる'],ans:1,exp:'フラット35は住宅金融支援機構と民間金融機関が提携した全期間固定金利型の住宅ローンです。金利変動リスクを負わないため返済計画が立てやすいのが特徴です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10480,unit:'t_kinyu',level:2,field:'tax',text:'住宅金融支援機構が直接融資を行うことができる場合として正しいものはどれか。',opts:['すべての住宅取得者','災害復興住宅融資・子育て支援住宅融資など政策上必要なケース','年収1000万円以上の高所得者','事業用不動産の取得'],ans:1,exp:'住宅金融支援機構は原則として証券化支援業務が中心ですが、災害復興融資・財形住宅融資・子育て世帯向け融資など政策上必要なケースでは直接融資も行います（住宅金融支援機構法17条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10481,unit:'t_kinyu',level:2,field:'tax',text:'フラット35の融資対象となる住宅の床面積要件として正しいものはどれか（一戸建て）。',opts:['30㎡以上','50㎡以上','70㎡以上','100㎡以上'],ans:1,exp:'フラット35の融資対象は一戸建て住宅で床面積70㎡以上、マンション等の共同住宅は30㎡以上が要件です（住宅金融支援機構の取扱基準）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10482,unit:'t_kinyu',level:3,field:'tax',text:'住宅金融支援機構の証券化支援業務（買取型）の仕組みとして正しいものはどれか。',opts:['機構が直接消費者に融資する','民間金融機関が融資した住宅ローン債権を機構が買い取り、MBS（住宅ローン担保証券）を発行して資金調達する','機構が保証人となり民間融資を保証する','金利補給金を民間金融機関に交付する'],ans:1,exp:'証券化支援業務（買取型）は民間金融機関の住宅ローン債権を機構が買い取り、それを担保にMBSを発行して資本市場から資金を調達する仕組みです。これにより民間金融機関が長期固定金利ローンを提供しやすくなります。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  // 印紙税・消費税（t_inshi）
  {id:10483,unit:'t_inshi',level:1,field:'tax',text:'不動産の売買契約書に貼付する印紙税について正しいものはどれか。',opts:['売主と買主が同額ずつ負担する法律上の義務がある','課税文書に印紙を貼付し消印することで納税する','電子契約書にも印紙が必要','印紙税は地方税である'],ans:1,exp:'印紙税は課税文書に収入印紙を貼付し消印することで納付します。印紙税は国税です。電子契約（電磁的記録）は文書に該当しないため不要です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10484,unit:'t_inshi',level:1,field:'tax',text:'印紙税が非課税となる文書として正しいものはどれか。',opts:['1000万円の土地売買契約書','記載金額1万円未満の契約書','建物の賃貸借契約書','金銭消費貸借契約書'],ans:1,exp:'記載金額が1万円未満の契約書は印紙税が非課税です（印紙税法別表第一）。なお建物の賃貸借契約書は課税文書ですが、記載金額のないものは200円の定額課税となります。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10485,unit:'t_inshi',level:2,field:'tax',text:'不動産売買契約書を2通作成した場合の印紙税について正しいものはどれか。',opts:['2通合わせて1通分の印紙で足りる','各1通ずつに印紙が必要（合計2通分）','1通だけに貼付すれば足りる','コピーにも印紙が必要'],ans:1,exp:'印紙税は1通ごとに課税されるため、2通作成した場合はそれぞれに印紙を貼付する必要があります。コピー（複写）には印紙は不要です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10486,unit:'t_inshi',level:2,field:'tax',text:'宅地建物の譲渡に関する消費税について正しいものはどれか。',opts:['土地の譲渡には消費税が課される','建物の譲渡には消費税が課されるが土地の譲渡は非課税','住宅の賃貸借も消費税が課される','消費税は売主が免税事業者でも必ず課税される'],ans:1,exp:'土地の譲渡は消費税非課税です（消費税法6条・別表1）。建物の譲渡は課税対象です。住宅の貸付（家賃）は非課税ですが、駐車場・事業用建物の賃貸は課税されます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10487,unit:'t_inshi',level:3,field:'tax',text:'印紙税の過怠税について正しいものはどれか。',opts:['印紙を貼らなかった場合は本来の印紙税額と同額の過怠税が課される','印紙を貼らなかった場合は本来の印紙税額の3倍の過怠税が課される','過怠税は自主的に申し出た場合も3倍','印紙税の不納付は刑事罰のみ'],ans:1,exp:'印紙税を納付しなかった場合（印紙未貼付・消印なし等）は本来の印紙税額の3倍の過怠税が課されます（印紙税法20条）。ただし自主的に申し出た場合は1.1倍に軽減されます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  // 地価公示・不動産鑑定評価（t_chika）
  {id:10488,unit:'t_chika',level:1,field:'tax',text:'地価公示の調査主体として正しいものはどれか。',opts:['市町村','国土交通省土地鑑定委員会','都道府県','日本不動産鑑定士協会連合会'],ans:1,exp:'地価公示は国土交通省の土地鑑定委員会が毎年実施します（地価公示法2条）。2名以上の不動産鑑定士による鑑定評価を基に標準地の正常な価格を判定・公示します。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10489,unit:'t_chika',level:1,field:'tax',text:'都道府県地価調査（基準地価）の調査基準日として正しいものはどれか。',opts:['毎年1月1日','毎年7月1日','毎年4月1日','毎年10月1日'],ans:1,exp:'都道府県地価調査の基準日は毎年7月1日です。地価公示（1月1日基準）を補完し、半年ごとの地価動向を把握できます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10490,unit:'t_chika',level:2,field:'tax',text:'不動産鑑定評価の原価法における「減価修正」の方法として正しいものはどれか。',opts:['取引事例と比較して減価する','耐用年数や劣化状況を考慮して再調達原価から減価する','収益の減少分を控除する','相続税評価額から控除する'],ans:1,exp:'原価法は再調達原価（その不動産を現時点で再建築・再取得する費用）から物理的・機能的・経済的な減価を修正して積算価格を求める方法です。主に建物の評価に用いられます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10491,unit:'t_chika',level:2,field:'tax',text:'相続税路線価と地価公示価格の関係として正しいものはどれか。',opts:['相続税路線価は地価公示価格と同額','相続税路線価は地価公示価格のおおむね80%水準','相続税路線価は地価公示価格の50%水準','両者は無関係'],ans:1,exp:'相続税路線価は地価公示価格のおおむね80%水準に設定されています。固定資産税評価額は地価公示価格の70%水準が目安です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10492,unit:'t_chika',level:3,field:'tax',text:'不動産鑑定評価における「正常価格」の定義として正しいものはどれか。',opts:['最高値で売れた価格','市場において十分な情報を持つ当事者間で自由な取引が行われるとした場合に通常成立する価格','税務署が認定した価格','担保として評価された価格'],ans:1,exp:'正常価格とは市場において当事者が市場性を有する不動産について合理的行動をとる場合に通常成立すると認められる価格で、適正な価値を表す概念です（不動産鑑定評価基準）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  // 国土利用計画法（k_kokudo）
  {id:10493,unit:'k_kokudo',level:1,field:'limit',text:'国土利用計画法の事後届出の届出期間として正しいものはどれか。',opts:['契約締結後2週間以内','契約締結後3週間以内','契約締結後2か月以内','契約締結前'],ans:1,exp:'事後届出は土地の売買等の契約を締結した日から2週間以内に市町村長を経由して都道府県知事に届け出ます（国土利用計画法23条1項）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "国土利用計画法の事後届出は契約締結後3週間以内に都道府県知事に届け出なければなりません（国土利用計画法23条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "契約締結後2週間以内", "reason": "事後届出の期限は3週間以内です（国土利用計画法23条1項）。", "caution": "事後届出：契約締結後3週間以内（国土利用計画法23条1項）。"}, {"label": "契約締結後2か月以内", "reason": "事後届出の期限は3週間以内です（国土利用計画法23条1項）。", "caution": ""}, {"label": "契約締結前", "reason": "事後届出なので締結「後」の届出です（国土利用計画法23条1項）。", "caution": ""}], "summary": {"head": ["事後届出の期限（国土利用計画法23条1項）", "内容"], "rows": [["届出期限", "契約締結後3週間以内"], ["届出先", "都道府県知事"]]}}},
  {id:10494,unit:'k_kokudo',level:1,field:'limit',text:'国土利用計画法の事後届出が必要な市街化区域内の面積要件として正しいものはどれか。',opts:['100㎡以上','500㎡以上','2000㎡以上','5000㎡以上'],ans:2,exp:'市街化区域では2000㎡以上の土地取引について事後届出が必要です（国土利用計画法23条）。市街化区域以外の都市計画区域は5000㎡以上、都市計画区域外は10000㎡以上が要件です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "市街化区域内で事後届出が必要な面積基準は2000㎡以上です（国土利用計画法施行令17条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "100㎡以上", "reason": "市街化区域内の基準は2000㎡以上です（国土利用計画法施行令17条）。", "caution": "市街化区域：2000㎡以上（国土利用計画法施行令17条）。"}, {"label": "500㎡以上", "reason": "市街化区域内の基準は2000㎡以上です（国土利用計画法施行令17条）。", "caution": ""}, {"label": "5000㎡以上", "reason": "5000㎡は非線引き都市計画区域の基準です（国土利用計画法施行令17条）。", "caution": ""}], "summary": {"head": ["事後届出の面積基準（施行令17条）", "基準"], "rows": [["市街化区域", "2000㎡以上"], ["非線引き区域・準都市計画区域", "5000㎡以上"], ["都市計画区域外", "10000㎡以上"]]}}},
  {id:10495,unit:'k_kokudo',level:2,field:'limit',text:'国土利用計画法の届出が不要な場合として正しいものはどれか。',opts:['個人間の売買契約','国・地方公共団体が当事者となる取引','法人同士の売買','外国人が取得する場合'],ans:1,exp:'国または地方公共団体が当事者となる取引は届出不要です（国土利用計画法23条2項）。また農地法の許可が必要な農地の取引も届出不要です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "国・地方公共団体が当事者となる取引は国土利用計画法の事後届出が不要です（国土利用計画法23条2項1号）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "個人間の売買契約", "reason": "個人間の一定規模以上の売買は事後届出が必要です（国土利用計画法23条1項）。", "caution": "国・地方公共団体が当事者：事後届出不要（国土利用計画法23条2項1号）。"}, {"label": "法人同士の売買", "reason": "法人間の一定規模以上の売買は届出対象です（国土利用計画法23条1項）。", "caution": ""}, {"label": "外国人が取得する場合", "reason": "外国人が取得する場合でも事後届出の義務があります（国土利用計画法23条1項）。", "caution": ""}], "summary": {"head": ["事後届出が不要な取引（国土利用計画法23条2項）", "内容"], "rows": [["国・地方公共団体が当事者", "不要（1号）"], ["相続", "不要（3号）"]]}}},
  {id:10496,unit:'k_kokudo',level:2,field:'limit',text:'事後届出後に都道府県知事が「利用目的の変更勧告」をできる期間として正しいものはどれか。',opts:['届出受理後1週間以内','届出受理後3週間以内','届出受理後6週間以内','届出受理後3か月以内'],ans:1,exp:'都道府県知事は事後届出を受理した日から3週間以内に利用目的について勧告することができます（国土利用計画法24条1項）。勧告に従わない場合は公表できます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "事後届出後に都道府県知事が「利用目的の変更勧告」を行えるのは届出受理後3週間以内です（国土利用計画法24条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "届出受理後1週間以内", "reason": "勧告期間は3週間以内です（国土利用計画法24条1項）。", "caution": "事後届出後の勧告期限：3週間以内（国土利用計画法24条1項）。"}, {"label": "届出受理後6週間以内", "reason": "6週間は事前届出の審査期間です（国土利用計画法27条の6）。事後届出の勧告期限は3週間です（同法24条1項）。", "caution": ""}, {"label": "届出受理後3か月以内", "reason": "事後届出の勧告期限は3週間以内です（国土利用計画法24条1項）。", "caution": ""}], "summary": {"head": ["事後届出後の勧告（国土利用計画法24条1項）", "内容"], "rows": [["勧告期間", "届出受理後3週間以内"], ["勧告内容", "利用目的の変更"]]}}},
  {id:10497,unit:'k_kokudo',level:3,field:'limit',text:'土地売買等の契約に係る事後届出義務者として正しいものはどれか。',opts:['売主（譲渡人）','買主（権利取得者）','売主と買主の双方','仲介した宅建業者'],ans:1,exp:'事後届出の義務を負うのは権利取得者（買主等）です（国土利用計画法23条1項）。売主には届出義務はありません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "国土利用計画法の事後届出義務者は権利取得者（買主）です（国土利用計画法23条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "売主（譲渡人）", "reason": "届出義務者は権利取得者（買主）です（国土利用計画法23条1項）。", "caution": "事後届出：買主（権利取得者）が届け出る（国土利用計画法23条1項）。"}, {"label": "売主と買主の双方", "reason": "届出義務者は買主のみです（国土利用計画法23条1項）。", "caution": ""}, {"label": "仲介した宅建業者", "reason": "宅建業者は届出義務者ではありません（国土利用計画法23条1項）。", "caution": ""}], "summary": {"head": ["事後届出の義務者", "内容"], "rows": [["届出義務者", "権利取得者（買主）"], ["届出先", "都道府県知事"]]}}},
  // 土地区画整理法（k_kukaku）
  {id:10498,unit:'k_kukaku',level:1,field:'limit',text:'土地区画整理事業の施行者として認められていないものはどれか。',opts:['個人','土地区画整理組合','都道府県・市町村','外国政府'],ans:3,exp:'土地区画整理事業の施行者は個人・土地区画整理組合・区画整理会社・市町村・都道府県・国土交通大臣・機構等です（土地区画整理法3条）。外国政府は認められていません。',"kaisetsu":{"topic": "土地区画整理法：換地は公告翌日確定・仮換地は従前地使用不可・組合は2/3以上", "basis": {"text": "換地処分の公告翌日から換地が確定します（土地区画整理法104条）。仮換地の指定後は従前地を使用できなくなります（同法99条）。組合設立には土地所有者・借地権者の各2/3以上の同意が必要です。", "example": ""}, "reason": {"text": "外国政府は土地区画整理事業の施行者として認められていません（土地区画整理法3条〜7条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">土地区画整理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">換地の確定</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公告の翌日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮換地指定後</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従前地は使用不可（所有権は残る）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">組合設立</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各2/3以上の同意</text></svg>", "choices": [{"label": "個人", "reason": "個人は施行者になれます（土地区画整理法3条1項）。", "caution": ""}, {"label": "土地区画整理組合", "reason": "土地区画整理組合は施行者になれます（土地区画整理法3条2項）。", "caution": ""}, {"label": "都道府県・市町村", "reason": "都道府県・市町村は施行者になれます（土地区画整理法3条4項・5項）。", "caution": ""}], "summary": {"head": ["施行者として認められる主体", "内容"], "rows": [["個人・組合・会社・市町村・都道府県", "可"], ["外国政府・外国法人", "不可"]]}}},
  {id:10499,unit:'k_kukaku',level:1,field:'limit',text:'換地処分の公告後に換地が従前地とみなされる効果として正しいものはどれか。',opts:['換地は公告前から従前地とみなされる','換地処分の公告の翌日から換地が従前地とみなされる','換地は登記後から効力を生じる','換地処分後も従前地の権利は消滅しない'],ans:1,exp:'換地処分の公告があった翌日から換地が従前地とみなされ、従前地の権利は換地に移行します（土地区画整理法104条）。保留地は施行者が取得します。',"kaisetsu":{"topic": "土地区画整理法：換地は公告翌日確定・仮換地は従前地使用不可・組合は2/3以上", "basis": {"text": "換地処分の公告翌日から換地が確定します（土地区画整理法104条）。仮換地の指定後は従前地を使用できなくなります（同法99条）。組合設立には土地所有者・借地権者の各2/3以上の同意が必要です。", "example": ""}, "reason": {"text": "換地処分の公告があった翌日から換地は従前の宅地とみなされます（土地区画整理法104条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">土地区画整理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">換地の確定</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公告の翌日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮換地指定後</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従前地は使用不可（所有権は残る）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">組合設立</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各2/3以上の同意</text></svg>", "choices": [{"label": "換地は公告前から従前地とみなされる", "reason": "公告の翌日からです（土地区画整理法104条1項）。", "caution": "換地処分：公告の翌日から換地が従前地とみなされる（土地区画整理法104条1項）。"}, {"label": "換地は登記後から効力を生じる", "reason": "登記後からではなく換地処分の公告翌日から効力が生じます（土地区画整理法104条1項）。", "caution": ""}, {"label": "換地処分後も従前地の権利は消滅しない", "reason": "換地処分の公告翌日から従前地の権利は換地に移行します（土地区画整理法104条1項）。", "caution": ""}], "summary": {"head": ["換地処分の効果（土地区画整理法104条）", "内容"], "rows": [["効力発生", "公告の翌日"], ["効果", "換地が従前地とみなされる"]]}}},
  {id:10500,unit:'k_kukaku',level:2,field:'limit',text:'土地区画整理組合の設立認可の要件として正しいものはどれか。',opts:['施行区域内の土地所有者全員の同意','施行区域内の土地所有者及び借地権者のそれぞれ3分の2以上の同意','施行区域内の土地所有者の過半数の同意','都道府県知事の職権による設立'],ans:1,exp:'土地区画整理組合の設立には施行区域内の土地所有者および借地権者のそれぞれ3分の2以上の同意と都道府県知事の認可が必要です（土地区画整理法14条）。',"kaisetsu":{"topic": "土地区画整理法：換地は公告翌日確定・仮換地は従前地使用不可・組合は2/3以上", "basis": {"text": "換地処分の公告翌日から換地が確定します（土地区画整理法104条）。仮換地の指定後は従前地を使用できなくなります（同法99条）。組合設立には土地所有者・借地権者の各2/3以上の同意が必要です。", "example": ""}, "reason": {"text": "土地区画整理組合の設立認可の要件は施行区域内の宅地所有者および借地権者のそれぞれ3分の2以上の同意と7人以上の設立者です（土地区画整理法14条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">土地区画整理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">換地の確定</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公告の翌日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮換地指定後</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従前地は使用不可（所有権は残る）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">組合設立</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各2/3以上の同意</text></svg>", "choices": [{"label": "施行区域内の土地所有者全員の同意", "reason": "全員同意は不要で3分の2以上で足ります（土地区画整理法14条1項）。", "caution": "組合設立：宅地所有者・借地権者の各3分の2以上の同意（土地区画整理法14条1項）。"}, {"label": "施行区域内の土地所有者の過半数の同意", "reason": "過半数では不足で3分の2以上が必要です（土地区画整理法14条1項）。", "caution": ""}, {"label": "都道府県知事の職権による設立", "reason": "組合設立は権利者の意思（3分の2以上の同意）に基づきます（土地区画整理法14条1項）。", "caution": ""}], "summary": {"head": ["組合設立認可要件（土地区画整理法14条1項）", "内容"], "rows": [["同意要件", "宅地所有者・借地権者それぞれ3分の2以上"], ["人数", "7人以上"]]}}},
  {id:10501,unit:'k_kukaku',level:2,field:'limit',text:'清算金の徴収・交付に関して正しいものはどれか。',opts:['清算金は換地処分前に支払われる','過小な換地を受けた者は清算金を交付され、過大な換地を受けた者は清算金を徴収される','清算金は任意の支払い','清算金制度は廃止されている'],ans:1,exp:'換地と従前地の価額に差がある場合、換地処分の公告後に清算金の徴収・交付が行われます（土地区画整理法94条）。価値が増加した者からは徴収、減少した者へは交付されます。',"kaisetsu":{"topic": "土地区画整理法：換地は公告翌日確定・仮換地は従前地使用不可・組合は2/3以上", "basis": {"text": "換地処分の公告翌日から換地が確定します（土地区画整理法104条）。仮換地の指定後は従前地を使用できなくなります（同法99条）。組合設立には土地所有者・借地権者の各2/3以上の同意が必要です。", "example": ""}, "reason": {"text": "清算金は換地と従前地の価値差を調整するものです。換地が従前地より小さい場合は施行者から清算金が交付され、大きい場合は権利者が施行者に清算金を納付します（土地区画整理法94条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">土地区画整理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">換地の確定</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公告の翌日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮換地指定後</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従前地は使用不可（所有権は残る）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">組合設立</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各2/3以上の同意</text></svg>", "choices": [{"label": "清算金は換地処分前に支払われる", "reason": "清算金は換地処分の公告後に確定・交付・徴収されます（土地区画整理法94条）。", "caution": "清算金：換地処分後に確定・交付・徴収（土地区画整理法94条）。"}, {"label": "清算金は任意の支払い", "reason": "清算金は法的義務であり任意ではありません（土地区画整理法94条）。", "caution": ""}, {"label": "清算金制度は廃止されている", "reason": "清算金制度は現行法（土地区画整理法94条）に存在します。", "caution": ""}], "summary": {"head": ["清算金の交付・徴収（土地区画整理法94条）", "内容"], "rows": [["従前地＞換地（価値）", "施行者→権利者に清算金を交付"], ["従前地＜換地（価値）", "権利者→施行者に清算金を納付"]]}}},
  {id:10502,unit:'k_kukaku',level:3,field:'limit',text:'仮換地の指定を受けた場合に工事完了公告前に建物を建築できる場合として正しいものはどれか。',opts:['仮換地指定があれば自由に建築できる','施行者の承認を得た場合は建築できる','いかなる場合も建築できない','登記さえすれば建築できる'],ans:1,exp:'仮換地上では原則として工事完了公告まで建物の建築等は制限されますが、施行者の承認を得た場合は建築することができます（土地区画整理法76条）。',"kaisetsu":{"topic": "土地区画整理法：換地は公告翌日確定・仮換地は従前地使用不可・組合は2/3以上", "basis": {"text": "換地処分の公告翌日から換地が確定します（土地区画整理法104条）。仮換地の指定後は従前地を使用できなくなります（同法99条）。組合設立には土地所有者・借地権者の各2/3以上の同意が必要です。", "example": ""}, "reason": {"text": "仮換地の指定を受けた後・工事完了公告前でも、施行者の承認を得た場合は建築物を建築できます（土地区画整理法76条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">土地区画整理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">換地の確定</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公告の翌日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮換地指定後</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従前地は使用不可（所有権は残る）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">組合設立</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各2/3以上の同意</text></svg>", "choices": [{"label": "仮換地指定があれば自由に建築できる", "reason": "施行者の承認が必要です（土地区画整理法76条1項）。", "caution": "仮換地指定後の建築：施行者の承認が必要（土地区画整理法76条1項）。"}, {"label": "いかなる場合も建築できない", "reason": "施行者の承認があれば建築できます（土地区画整理法76条1項）。", "caution": ""}, {"label": "登記さえすれば建築できる", "reason": "登記の有無ではなく施行者の承認が必要です（土地区画整理法76条1項）。", "caution": ""}], "summary": {"head": ["工事完了公告前の建築制限（土地区画整理法76条）", "内容"], "rows": [["原則", "施行者の承認なし→建築禁止"], ["例外", "施行者の承認があれば建築可"]]}}},
  // 相隣関係・共有・地役権（r_sorin）
  {id:10503,unit:'r_sorin',level:1,field:'rights',text:'民法上、隣地の竹木の枝が境界線を越えてきた場合の処理として正しいものはどれか（2021年改正後）。',opts:['直ちに自分で切ることができる','原則として竹木の所有者に切除を催告し、相当期間内に切除されない場合は自ら切除できる','切除は裁判所の許可が必要','枝の越境は法律上問題ない'],ans:1,exp:'2021年民法改正により、竹木の枝が越境した場合は竹木所有者に催告し相当期間内に切除されない場合・所有者不明・急迫の事情がある場合に自ら切除できるようになりました（民法233条）。根は従来通り自分で切除できます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "2021年民法改正で隣地の竹木の枝の越境処理が明確化されました（民法233条）。原則として竹木の所有者に切除を催告し、相当期間内に切除されない場合等は自ら切除できます。根は従来通り自ら切除できます（同条4項・2項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "直ちに自分で切ることができる", "reason": "枝の場合は原則として竹木の所有者に催告してから切除するのが原則です（民法233条1項・3項）。例外的に直ちに切除できる場合もあります（同条3項各号）。", "caution": "枝：原則先に催告（民法233条）。根：直ちに自ら切除可（同条4項）。"}, {"label": "切除は裁判所の許可が必要", "reason": "裁判所の許可は不要です（民法233条3項）。催告後一定期間内に切除されなければ自ら切除できます。", "caution": ""}, {"label": "枝の越境は法律上問題ない", "reason": "越境した枝は問題となりえます。所有者に切除請求でき（民法233条1項）、催告後に自ら切除できる場合もあります（同条3項）。", "caution": ""}], "summary": {"head": ["竹木の越境（民法233条・2021年改正）", "処理方法"], "rows": [["枝（原則）", "竹木の所有者に切除を催告"], ["枝（例外・即時切除可）", "所有者不明・催告後相当期間内に切除されない等"], ["根", "自ら切除できる（民法233条4項）"], ["費用", "切除費用は竹木の所有者に請求可"]]}}},
  {id:10504,unit:'r_sorin',level:1,field:'rights',text:'共有物の保存行為として正しいものはどれか。',opts:['共有物全体を売却すること','共有物に対する不法占拠者への明渡し請求（保存行為）は単独でできる','共有物の大規模修繕は単独でできる','共有持分の放棄は全員の同意が必要'],ans:1,exp:'共有物の保存行為（不法占拠者への明渡し請求・修繕等）は各共有者が単独で行えます（民法252条5項）。管理行為は持分過半数、変更行為は全員同意が原則です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "保存行為（共有物の現状を維持する行為）は各共有者が単独で行えます（民法252条5項）。不法占拠者への明渡し請求は共有物の現状維持に当たる保存行為として単独で行えます（判例）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "共有物全体を売却すること", "reason": "共有物全体の売却は変更行為（処分）であり全員の同意が必要です（民法251条1項）。保存行為ではありません。", "caution": "売却（処分）＝変更行為→全員同意。保存行為＝単独可。"}, {"label": "共有物の大規模修繕は単独でできる", "reason": "大規模修繕は管理行為または変更行為であり、持分過半数または全員同意が必要です。単独ではできません（民法252条・251条）。", "caution": ""}, {"label": "共有持分の放棄は全員の同意が必要", "reason": "共有持分の放棄は各共有者が単独でできます（民法255条）。全員の同意は不要です。", "caution": ""}], "summary": {"head": ["保存行為（民法252条5項）", "例"], "rows": [["内容", "共有物の現状を維持する行為"], ["例", "不法占拠者への明渡し請求・修繕・時効中断行為等"], ["要件", "各共有者が単独で可"], ["管理行為との違い", "管理行為は持分過半数が必要"]]}}},
  {id:10505,unit:'r_sorin',level:2,field:'rights',text:'地役権の時効取得の要件として正しいものはどれか。',opts:['地役権は時効取得できない','継続的に行使され外形上認識できる地役権は時効取得できる','10年の占有で取得できる','地役権は登記がなければ時効取得できない'],ans:1,exp:'継続的に行使され、かつ外形上認識できる地役権（例：通路開設を伴う通行地役権）は時効取得できます（民法283条・判例）。継続性・外形性の要件が必要です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "地役権も時効取得が可能です（民法283条）。ただし地役権は「継続的に行使され、かつ外形上認識することができるもの」に限り時効取得できます（判例・民法283条）。不継続的・外形上認識できない地役権は時効取得できません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "地役権は時効取得できない", "reason": "地役権は時効取得できます（民法283条）。「できない」は誤りです。", "caution": "地役権の時効取得＝継続的行使＋外形上認識可能（民法283条）。"}, {"label": "10年の占有で取得できる", "reason": "地役権の時効取得は「占有」ではなく継続的な行使が要件です（民法283条）。10年という期間要件も条文上明示されていません（一般の時効取得と異なる）。", "caution": ""}, {"label": "地役権は登記がなければ時効取得できない", "reason": "時効取得した地役権の対抗には登記が必要ですが、時効取得の成立自体は登記を要件としません（民法283条）。", "caution": ""}], "summary": {"head": ["地役権の時効取得（民法283条）", "内容"], "rows": [["要件①", "継続的に行使されていること"], ["要件②", "外形上認識できること（通路の整備等）"], ["例", "通行地役権（舗装された通路の継続使用等）"], ["登記", "時効取得後の第三者対抗には登記が必要"]]}}},
  {id:10506,unit:'r_sorin',level:2,field:'rights',text:'共有物の分割方法として民法上認められていないものはどれか。',opts:['現物分割','代金分割（競売）','価格賠償（価格弁償）','第三者への強制譲渡'],ans:3,exp:'民法上の共有物分割方法は①現物分割②代金分割（競売）③価格賠償（一方が他方に価値を弁償して単独取得）です（民法258条）。第三者への強制譲渡という方法はありません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "共有物の分割方法として認められるのは①現物分割、②代金分割（競売）、③価格賠償（代償分割）の3種類です（民法258条2項・3項）。「第三者への強制譲渡」は民法上の共有物分割方法として認められていません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "現物分割", "reason": "現物分割は民法上認められた分割方法です（民法258条2項1号）。", "caution": ""}, {"label": "代金分割（競売）", "reason": "競売による代金分割は認められています（民法258条3項）。", "caution": ""}, {"label": "価格賠償（価格弁償）", "reason": "価格賠償（代償分割）は認められています（民法258条2項2号）。", "caution": ""}], "summary": {"head": ["共有物分割の3方法", "内容"], "rows": [["現物分割", "物理的に分割（民法258条2項1号）"], ["代償分割（価格賠償）", "一人が全部取得・他に補償（民法258条2項2号）"], ["換価分割（競売）", "競売して代金を分配（民法258条3項）"], ["強制譲渡", "認められない"]]}}},
  {id:10507,unit:'r_sorin',level:3,field:'rights',text:'所有者不明土地の管理に関する2021年民法改正の内容として正しいものはどれか。',opts:['所有者不明土地は国が自動的に取得する','裁判所が所有者不明土地管理人を選任し管理・処分できる制度が創設された','所有者不明土地の利用は一切禁止','市町村が強制取得できる'],ans:1,exp:'2021年民法改正により所有者不明土地・建物管理制度が創設され、利害関係人の申立てにより裁判所が管理人を選任し管理・処分（売却等）を行える制度が整備されました（民法264条の2以下）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "2021年民法改正で所有者不明土地管理制度が創設されました（民法264条の2以下）。裁判所が所有者不明土地管理人を選任し、管理人が当該土地の管理・処分を行える制度です。放置された土地問題への対応として導入されました。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "所有者不明土地は国が自動的に取得する", "reason": "所有者不明土地が自動的に国に帰属するわけではありません。一定の要件のもとで相続土地国庫帰属制度（別の制度）が利用できます。", "caution": ""}, {"label": "所有者不明土地の利用は一切禁止", "reason": "所有者不明土地管理制度により、管理人を通じた利用・処分が可能です（民法264条の2以下）。「一切禁止」は誤りです。", "caution": ""}, {"label": "市町村が強制取得できる", "reason": "市町村が強制取得できる制度は所有者不明土地法等の別制度です。民法の所有者不明土地管理制度とは異なります。", "caution": ""}], "summary": {"head": ["所有者不明土地管理制度（2021年改正）", "内容"], "rows": [["根拠", "民法264条の2以下"], ["手続き", "利害関係人の申立て→裁判所が管理人選任"], ["管理人の権限", "保存・利用・改良・処分（裁判所の許可が必要な場合あり）"], ["相続土地国庫帰属", "別制度（相続した不要な土地を国に帰属させる制度）"]]}}},
  // 借地借家法（r_shakuchi）
  {id:10508,unit:'r_shakuchi',level:1,field:'rights',text:'定期借地権の存続期間として正しいものはどれか。',opts:['10年以上','20年以上','30年以上','50年以上'],ans:3,exp:'一般定期借地権の存続期間は50年以上です（借地借家法22条）。事業用定期借地権は10年以上50年未満、建物譲渡特約付借地権は30年以上が要件です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "一般定期借地権の存続期間は50年以上です（借地借家法22条）。50年以上であれば当事者が自由に期間を定められます。更新なし・建物買取請求権なし・土地更新料なしが特徴で、書面で契約します（同条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "10年以上", "reason": "10年以上は事業用定期借地権の最低期間です（借地借家法23条）。一般定期借地権は50年以上です（同法22条）。", "caution": "一般定期借地権＝50年以上（借地借家法22条）。事業用定期借地権＝10年以上50年未満（同法23条）。"}, {"label": "20年以上", "reason": "20年以上という規定は現行の借地借家法に存在しません。一般定期借地権は50年以上です（借地借家法22条）。", "caution": ""}, {"label": "30年以上", "reason": "30年以上は普通借地権の最低存続期間です（借地借家法3条）。一般定期借地権は50年以上です（同法22条）。", "caution": ""}], "summary": {"head": ["定期借地権の比較", "存続期間", "方式", "用途制限"], "rows": [["一般定期借地権（借地借家法22条）", "50年以上", "書面（公正証書でなくても可）", "なし"], ["事業用定期借地権（借地借家法23条）", "10年以上50年未満", "公正証書", "専ら事業用"], ["建物譲渡特約付借地権（借地借家法24条）", "30年以上", "書面", "なし"]]}}},
  {id:10509,unit:'r_shakuchi',level:1,field:'rights',text:'普通借家契約の更新拒絶に必要な要件として正しいものはどれか。',opts:['貸主はいつでも自由に更新を拒絶できる','貸主の正当事由が必要','借主側の事情のみで決まる','6か月前の通知だけで足りる'],ans:1,exp:'普通借家契約の更新拒絶には「正当事由」が必要です（借地借家法28条）。正当事由は建物使用の必要性・利用状況・立退料の提供等を総合的に判断します。通知だけでは足りません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "普通借家契約の賃貸人からの更新拒絶・解約申入れには正当事由が必要です（借地借家法28条）。正当事由はなく「通知さえすれば更新を拒絶できる」とはなりません。賃借人保護のための重要な規定です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "貸主はいつでも自由に更新を拒絶できる", "reason": "普通借家では正当事由が必要であり（借地借家法28条）、「自由に」拒絶はできません。", "caution": "普通借家の更新拒絶：正当事由が必要（借地借家法28条）。"}, {"label": "借主側の事情のみで決まる", "reason": "正当事由は貸主・借主双方の事情（必要性・建物状況・立退料等）を総合考慮して判断されます（借地借家法28条）。借主側だけでは決まりません。", "caution": ""}, {"label": "6か月前の通知だけで足りる", "reason": "6か月前の通知は必要ですが（借地借家法26条1項）、それだけでは足りず正当事由も必要です（同法28条）。", "caution": ""}], "summary": {"head": ["普通借家の更新拒絶（借地借家法26条・28条）", "内容"], "rows": [["通知期間", "期間満了の6か月前までに通知"], ["正当事由", "貸主・借主の必要性・建物状況・立退料等を総合考慮"], ["通知のみ", "正当事由なしに通知だけでは更新拒絶不可"], ["法定更新", "正当事由なければ期間満了後も更新"]]}}},
  {id:10510,unit:'r_shakuchi',level:2,field:'rights',text:'定期借家契約の説明として正しいものはどれか。',opts:['口頭で契約できる','公正証書等の書面で行い更新がなく期間満了で終了する','2年未満の期間は無効','貸主の正当事由が不要なため普及している'],ans:1,exp:'定期借家契約は書面（公正証書等）によって締結し、更新がなく期間満了で終了します（借地借家法38条）。貸主は事前に更新がない旨を書面で説明する義務があります。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "定期建物賃貸借（定期借家）は①書面または電磁的記録による契約、②更新がない旨の書面による事前説明・告知が必要です（借地借家法38条1項・2項）。期間満了で更新なしに確定終了するのが最大の特徴です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "口頭で契約できる", "reason": "定期借家契約は書面または電磁的記録によらなければなりません（借地借家法38条1項）。口頭では無効です。", "caution": "定期借家：書面（または電磁的記録）必須（借地借家法38条1項）。口頭では無効。"}, {"label": "2年未満の期間は無効", "reason": "定期借家には期間の最低制限はありません（借地借家法38条1項）。1か月でも有効です。", "caution": "普通借家は1年未満→期間の定めのない契約とみなされる（借地借家法29条1項）。定期借家は制限なし。"}, {"label": "貸主の正当事由が不要なため普及している", "reason": "定期借家は貸主の正当事由不要で終了できるため貸主に有利な制度ですが、「普及している」かどうかは別問題です。", "caution": ""}], "summary": {"head": ["定期建物賃貸借（借地借家法38条）", "内容"], "rows": [["方式", "書面または電磁的記録（口頭不可）"], ["事前告知", "更新がない旨を書面で事前に告知（別書面で）"], ["更新", "なし（期間満了で確定終了）"], ["終了通知", "1年以上の場合は6か月前まで"]]}}},
  {id:10511,unit:'r_shakuchi',level:2,field:'rights',text:'借地権の対抗要件として正しいものはどれか。',opts:['借地契約書の公正証書化','借地上の建物の登記（建物所有者が借地権者と同一人）','土地の賃借権登記のみ','市町村への届出'],ans:1,exp:'借地権の対抗要件は「借地上に建物の登記」があることです（借地借家法10条）。建物の所有者と借地権者が同一人であれば、建物の登記により第三者に対抗できます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "借地権（建物所有目的の土地賃借権等）の対抗要件は借地上の建物の登記です（借地借家法10条1項）。借地権自体の登記は不要で、借地上に建物を建て建物の所有権登記をしておけば借地権を第三者に対抗できます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "借地契約書の公正証書化", "reason": "公正証書は借地権の対抗要件ではありません（借地借家法10条1項）。建物の登記が対抗要件です。", "caution": "借地権の対抗要件＝借地上建物の登記（借地借家法10条1項）。"}, {"label": "土地の賃借権登記のみ", "reason": "土地の賃借権の登記も対抗要件になりますが（民法177条）、実務上は地主が登記に協力しないことが多く、借地借家法10条で「建物登記でも対抗可」とされています。「のみ」という表現が誤りです。", "caution": ""}, {"label": "市町村への届出", "reason": "市町村への届出は借地権の対抗要件ではありません（借地借家法10条）。", "caution": ""}], "summary": {"head": ["借地権の対抗要件", "内容"], "rows": [["建物の登記", "借地上の建物に所有権保存・移転登記（借地借家法10条1項）"], ["土地賃借権の登記", "民法177条による対抗（地主の協力が必要）"], ["建物が滅失した場合", "2年間は掲示で対抗可（借地借家法10条2項）"]]}}},
  {id:10512,unit:'r_shakuchi',level:3,field:'rights',text:'事業用定期借地権に関して正しいものはどれか。',opts:['居住用建物にも利用できる','必ず公正証書で締結しなければならない','存続期間は50年以上','更新特約を付けることができる'],ans:1,exp:'事業用定期借地権は必ず公正証書で締結しなければなりません（借地借家法23条3項）。存続期間は10年以上50年未満で、居住用建物には利用できません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "事業用定期借地権は必ず公正証書で締結しなければなりません（借地借家法23条3項）。居住用建物には利用できず（同条1項・2項）、存続期間は10年以上50年未満です。更新特約を付けることはできません（同条1項・2項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "居住用建物にも利用できる", "reason": "事業用定期借地権は専ら事業用建物（居住用以外）の所有を目的とします（借地借家法23条1項・2項）。居住用には利用できません。", "caution": "事業用定期借地権＝専ら事業用（居住用は不可）。"}, {"label": "存続期間は50年以上", "reason": "事業用定期借地権は10年以上50年未満です（借地借家法23条）。50年以上は一般定期借地権です（同法22条）。", "caution": ""}, {"label": "更新特約を付けることができる", "reason": "事業用定期借地権は更新がない定期借地権であり、更新特約は付けられません（借地借家法23条1項・2項）。", "caution": ""}], "summary": {"head": ["事業用定期借地権（借地借家法23条）", "内容"], "rows": [["方式", "公正証書で締結必須"], ["用途", "専ら事業用（居住用不可）"], ["存続期間", "10年以上50年未満"], ["更新", "なし（更新特約不可）"]]}}},
  // 区分所有法（r_kukku）
  {id:10513,unit:'r_kukku',level:1,field:'rights',text:'管理組合法人の設立に必要な決議要件として正しいものはどれか。',opts:['区分所有者全員の同意','区分所有者及び議決権の各4分の3以上','区分所有者及び議決権の各過半数','区分所有者の2分の1以上'],ans:1,exp:'管理組合法人の設立には区分所有者及び議決権の各4分の3以上の賛成による集会決議が必要です（区分所有法47条1項）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "管理組合法人の設立には区分所有者および議決権の各3/4以上の特別多数決が必要です（区分所有法47条1項）。また区分所有者が30人以上であること、法人成立の登記が必要です（同法47条2項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "区分所有者全員の同意", "reason": "全員同意は不要です。3/4以上の集会決議で足ります（区分所有法47条1項）。", "caution": ""}, {"label": "区分所有者及び議決権の各過半数", "reason": "過半数は通常の管理行為の要件です（区分所有法18条1項）。管理組合法人の設立には3/4以上が必要です（同法47条1項）。", "caution": ""}, {"label": "区分所有者の2分の1以上", "reason": "2分の1（過半数）では足りません。3/4以上の集会決議が必要です（区分所有法47条1項）。", "caution": ""}], "summary": {"head": ["管理組合法人の設立要件", "内容"], "rows": [["集会決議", "3/4以上の特別決議（区分所有法47条1項）"], ["区分所有者数", "30人以上"], ["登記", "法人成立の効力要件"], ["メリット", "組合名義での取引・訴訟が可能"]]}}},
  {id:10514,unit:'r_kukku',level:1,field:'rights',text:'専有部分と共用部分の関係として正しいものはどれか。',opts:['専有部分の所有者は共用部分持分を自由に分離処分できる','共用部分の共有持分は専有部分の所有権と分離して処分できない','共用部分は区分所有者全員で均等に持つ','廊下は専有部分にできる'],ans:1,exp:'共用部分の共有持分は専有部分と分離して処分できません（区分所有法15条2項）。専有部分を売却すれば共用部分の持分も当然に移転します。持分割合は原則として専有部分の床面積の割合です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "共用部分の持分は専有部分の所有権と分離して処分できません（区分所有法15条2項・22条）。専有部分を譲渡すれば自動的に共用部分の持分も移転します。専有部分と敷地利用権も原則として分離処分が禁止されています（同法22条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "専有部分の所有者は共用部分持分を自由に分離処分できる", "reason": "共用部分の持分は専有部分から分離して処分できません（区分所有法15条2項）。一体として扱われます。", "caution": "共用部分持分＝専有部分と分離処分不可（区分所有法15条2項）。"}, {"label": "共用部分は区分所有者全員で均等に持つ", "reason": "共用部分の持分割合は規約で定めがない場合は各専有部分の床面積の割合によります（区分所有法14条1項）。均等ではありません。", "caution": ""}, {"label": "廊下は専有部分にできる", "reason": "廊下は法定共用部分であり（区分所有法11条1項）、専有部分にはなりません。", "caution": ""}], "summary": {"head": ["共用部分の持分", "内容"], "rows": [["割合", "専有部分の床面積の割合（規約で変更可・区分所有法14条）"], ["分離処分", "専有部分と分離して処分不可（区分所有法15条2項）"], ["敷地利用権", "専有部分と分離処分原則禁止（区分所有法22条1項）"]]}}},
  {id:10515,unit:'r_kukku',level:2,field:'rights',text:'区分所有建物の大規模滅失（価格の2分の1超が滅失）後の復旧決議の要件として正しいものはどれか。',opts:['全員の同意','区分所有者及び議決権の各4分の3以上','区分所有者及び議決権の各過半数','区分所有者及び議決権の各5分の4以上'],ans:1,exp:'大規模滅失の復旧決議は区分所有者及び議決権の各4分の3以上の賛成が必要です（区分所有法61条5項）。小規模滅失（2分の1以下）は各区分所有者が単独で復旧できます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "建物の価格の2分の1超が滅失した場合（大規模滅失）の復旧決議には区分所有者および議決権の各3/4以上が必要です（区分所有法61条5項）。価格の2分の1以下の滅失（小規模滅失）は各区分所有者が単独で復旧できます（同条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "全員の同意", "reason": "全員同意は不要です。大規模滅失の復旧は3/4以上で足ります（区分所有法61条5項）。", "caution": ""}, {"label": "区分所有者及び議決権の各過半数", "reason": "過半数は通常の管理行為の要件です。大規模滅失後の復旧は3/4以上が必要です（区分所有法61条5項）。", "caution": "大規模滅失の復旧＝3/4以上（区分所有法61条5項）。"}, {"label": "区分所有者及び議決権の各5分の4以上", "reason": "5分の4以上は建替え決議の要件です（区分所有法62条1項）。大規模滅失の復旧は3/4以上です（同法61条5項）。", "caution": ""}], "summary": {"head": ["滅失後の処理", "要件"], "rows": [["小規模滅失（1/2以下）", "各区分所有者が単独で復旧可（区分所有法61条1項）"], ["大規模滅失（1/2超）復旧", "3/4以上（区分所有法61条5項）"], ["建替え", "4/5以上（区分所有法62条1項）"]]}}},
  {id:10516,unit:'r_kukku',level:2,field:'rights',text:'管理者に関して正しいものはどれか。',opts:['管理者は必ず区分所有者でなければならない','管理者は区分所有者以外の第三者もなれる','管理者の選任には全員の同意が必要','管理者は設置が義務付けられている'],ans:1,exp:'管理者は区分所有者に限らず、管理会社等の第三者もなることができます（区分所有法25条1項）。管理者の設置は任意で、選任・解任は集会の普通決議で行います。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "管理者は区分所有者以外の第三者（管理会社・個人等）もなることができます（区分所有法25条1項）。また管理者の設置は任意であり義務ではありません（同条1項）。選任・解任は集会の普通決議で行います（同条2項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "管理者は必ず区分所有者でなければならない", "reason": "管理者は区分所有者以外の第三者もなれます（区分所有法25条1項）。", "caution": "管理者は区分所有者以外もなれる（区分所有法25条1項）。"}, {"label": "管理者の選任には全員の同意が必要", "reason": "管理者の選任は集会の普通決議（過半数）で行います（区分所有法25条2項・39条1項）。全員同意は不要です。", "caution": ""}, {"label": "管理者は設置が義務付けられている", "reason": "管理者の設置は義務ではなく任意です（区分所有法25条1項）。設置しないこともできます。", "caution": ""}], "summary": {"head": ["管理者（区分所有法25条）", "内容"], "rows": [["就任資格", "区分所有者以外の第三者も可"], ["設置", "任意（義務ではない）"], ["選任・解任", "集会の普通決議（過半数）"], ["権限", "規約・集会決議の実施・組合を代表して訴訟行為等"]]}}},
  {id:10517,unit:'r_kukku',level:3,field:'rights',text:'規約の設定に関して正しいものはどれか。',opts:['規約は区分所有者1人でも制定できる','規約の設定・変更・廃止は区分所有者及び議決権の各4分の3以上の賛成が必要','規約は書面でなくても有効','規約の設定に公証人の認証が必要'],ans:1,exp:'規約の設定・変更・廃止には区分所有者及び議決権の各4分の3以上の多数による集会決議が必要です（区分所有法31条1項）。一部の区分所有者の権利に特別の影響を及ぼす変更はその者の承諾も必要です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "規約の設定・変更・廃止は区分所有者および議決権の各3/4以上の集会決議が必要です（区分所有法31条1項）。また規約は書面または電磁的記録で作成しなければなりません（同条2項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "規約は区分所有者1人でも制定できる", "reason": "規約の設定には3/4以上の集会決議が必要です（区分所有法31条1項）。1人では制定できません。", "caution": ""}, {"label": "規約は書面でなくても有効", "reason": "規約は書面または電磁的記録で作成しなければなりません（区分所有法31条2項）。書面なしでは無効です。", "caution": "規約は書面または電磁的記録が必要（区分所有法31条2項）。"}, {"label": "規約の設定に公証人の認証が必要", "reason": "規約の設定に公証人の認証は不要です（区分所有法31条1項）。集会決議で足ります。", "caution": ""}], "summary": {"head": ["規約の設定・変更・廃止（区分所有法31条）", "内容"], "rows": [["決議要件", "3/4以上の特別決議"], ["形式", "書面または電磁的記録"], ["公証人", "不要"], ["特別影響者", "一部の区分所有者に特別の影響を及ぼす場合はその者の承諾が必要（区分所有法31条1項ただし書）"]]}}},
  // 不動産登記法（r_touki）
  {id:10518,unit:'r_touki',level:1,field:'rights',text:'不動産登記の申請方法として認められていないものはどれか。',opts:['オンライン申請','書面申請（窓口・郵送）','電話による口頭申請','電子申請'],ans:2,exp:'不動産登記の申請は書面申請またはオンライン申請で行います（不動産登記法18条）。電話による口頭申請は認められていません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "不動産登記の申請方法はオンライン申請・書面申請（窓口・郵送）・電子申請が認められています（不動産登記法18条）。口頭による電話申請は認められておらず、書面または電磁的記録による申請が必要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "オンライン申請", "reason": "オンライン申請は認められています（不動産登記法18条1号）。", "caution": ""}, {"label": "書面申請（窓口・郵送）", "reason": "書面申請（窓口・郵送）は認められています（不動産登記法18条2号）。", "caution": ""}, {"label": "電子申請", "reason": "電子申請はオンライン申請と同義であり認められています。", "caution": ""}], "summary": {"head": ["申請方法", "可否"], "rows": [["オンライン申請（電子申請）", "可"], ["書面申請（窓口・郵送）", "可"], ["電話による口頭申請", "不可"], ["代理人による申請", "可（司法書士等）"]]}}},
  {id:10519,unit:'r_touki',level:1,field:'rights',text:'相続による所有権移転登記の申請義務として正しいものはどれか（2024年施行）。',opts:['任意であり申請しなくてよい','相続を知った日から3年以内に申請義務がある','10年以内に申請すれば足りる','相続人全員が共同申請しなければならない'],ans:1,exp:'2024年4月施行の改正不動産登記法により、相続による所有権取得を知った日から3年以内の登記申請が義務化されました（不動産登記法76条の2）。正当な理由なく義務違反の場合は10万円以下の過料。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "2024年4月施行の改正不動産登記法により、相続等による所有権取得を知った日から3年以内の相続登記申請が義務化されました（不動産登記法76条の2）。正当な理由なく申請しない場合は10万円以下の過料が科されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "任意であり申請しなくてよい", "reason": "2024年4月から相続登記は義務となりました（不動産登記法76条の2）。正当な理由なく申請しない場合は過料の対象です。", "caution": "2024年改正で相続登記が義務化されました。"}, {"label": "10年以内に申請すれば足りる", "reason": "相続登記の義務期間は相続を知った日から3年以内です。10年ではありません（不動産登記法76条の2）。", "caution": ""}, {"label": "相続人全員が共同申請しなければならない", "reason": "相続登記は相続人が単独で申請できます（不動産登記法63条2項）。全員共同申請は不要です。", "caution": ""}], "summary": {"head": ["相続登記の義務化（2024年4月施行）", "内容"], "rows": [["申請義務者", "不動産を取得した相続人"], ["期限", "相続を知った日から3年以内"], ["違反の効果", "10万円以下の過料"], ["相続人申告登記", "簡易手続き（3年以内の申請義務を満たす）"]]}}},
  {id:10520,unit:'r_touki',level:2,field:'rights',text:'仮登記の効力として正しいものはどれか。',opts:['仮登記は本登記と同一の効力を持つ','仮登記は順位保全の効力を持ち、本登記すると仮登記の順位で本登記の効力が生じる','仮登記後は本登記が不要','仮登記は対抗力を持つ'],ans:1,exp:'仮登記は順位保全の効力を持ちます（不動産登記法105条・106条）。仮登記に基づいて本登記をすると仮登記の順位で本登記の効力が生じます。ただし仮登記自体には対抗力はありません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "仮登記の本質は順位保全効です（不動産登記法105条）。本登記すると仮登記の順位で本登記の効力が発生し、仮登記後に行われた中間処分の登記は抹消されます。仮登記自体には対抗力がありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "仮登記は本登記と同一の効力を持つ", "reason": "仮登記は対抗力を持たず、本登記と同一の効力はありません。本登記後に仮登記の順位で効力が生じます。", "caution": "仮登記≠本登記と同一効力。"}, {"label": "仮登記後は本登記が不要", "reason": "仮登記のままでは対抗力がないため、権利を確定させるには本登記が必要です。", "caution": ""}, {"label": "仮登記は対抗力を持つ", "reason": "仮登記単独では対抗力を持ちません。本登記後に仮登記の順位で対抗力が生じます（不動産登記法106条）。", "caution": ""}], "summary": {"head": ["仮登記の効果", "内容"], "rows": [["単独の効力", "対抗力なし（順位保全のみ）"], ["本登記後の効力", "仮登記の順位で対抗力発生"], ["中間処分の処理", "仮登記後の登記を職権で抹消（不動産登記法109条）"]]}}},
  {id:10521,unit:'r_touki',level:2,field:'rights',text:'登記申請の共同申請の原則と例外として正しいものはどれか。',opts:['すべての登記は単独で申請できる','原則として登記権利者と登記義務者が共同で申請するが、相続・合併等は単独申請できる','登記は常に裁判所を経由して行う','共同申請は任意'],ans:1,exp:'不動産登記は原則として登記権利者と登記義務者が共同で申請します（不動産登記法60条）。ただし相続・法人合併・判決・収用等の場合は権利者が単独申請できます（同法63条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "登記申請の共同申請主義は、登記義務者（権利を失う側）が同意していることを確認し、虚偽登記を防止するための制度です（不動産登記法60条）。相続・判決等は義務者が申請できない・不要な場合として単独申請が認められます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "すべての登記は単独で申請できる", "reason": "原則は共同申請です（不動産登記法60条）。単独申請は相続・判決等の例外的な場合に限られます。", "caution": ""}, {"label": "登記は常に裁判所を経由して行う", "reason": "登記申請は登記所（法務局）に対して行います。裁判所を経由する必要はありません（判決登記の場合も申請先は登記所）。", "caution": ""}, {"label": "共同申請は任意", "reason": "共同申請は原則として義務です（不動産登記法60条）。任意ではありません。", "caution": ""}], "summary": {"head": ["申請方法", "場面"], "rows": [["共同申請（原則）", "売買・贈与・抵当権設定等"], ["単独申請（例外）", "相続・法人合併・判決・収用等"], ["登記官の職権", "表題登記等の一部"]]}}},
  {id:10522,unit:'r_touki',level:3,field:'rights',text:'区分建物の敷地権に関して正しいものはどれか。',opts:['敷地権は専有部分と分離して登記できる','敷地権が登記された後は原則として専有部分と敷地権を分離して処分できない','敷地権は任意で登記する','敷地権の登記は市町村が行う'],ans:1,exp:'敷地権が登記された区分建物は、専有部分と敷地権を分離して処分することが原則禁止されます（区分所有法22条）。これにより専有部分と敷地の権利が常に一体的に管理されます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "区分建物の敷地権は専有部分と一体化して管理・処分されます（不動産登記法73条）。登記後に分離処分すると権利関係が複雑になるため、原則として専有部分と敷地権を分離して処分することが禁止されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "敷地権は専有部分と分離して登記できる", "reason": "敷地権が登記された後は、原則として専有部分と敷地権を分離して処分できません（不動産登記法73条1項）。", "caution": "敷地権登記後は一体処分が原則。"}, {"label": "敷地権は任意で登記する", "reason": "敷地権の登記は区分建物の表題登記に際して義務的に行われます（不動産登記法44条1項9号）。", "caution": ""}, {"label": "敷地権の登記は市町村が行う", "reason": "不動産登記は登記所（法務局）が行います。市町村ではありません。", "caution": ""}], "summary": {"head": ["敷地権の登記", "内容"], "rows": [["登記の意義", "専有部分と敷地利用権を一体で公示"], ["登記後の処分", "専有部分と敷地権の分離処分が原則禁止"], ["例外", "規約による別段の定めがある場合"]]}}},
  // 広告・契約締結時期の制限（l_kokoku）
  {id:10523,unit:'l_kokoku',level:1,field:'law',text:'宅建業者が行う広告の開始時期として正しいものはどれか。',opts:['開発許可申請中から広告できる','開発許可・建築確認等を受けた後でなければ広告できない','広告はいつでも開始できる','売買予約があれば広告できる'],ans:1,exp:'宅建業者は開発許可・建築確認等の許認可を受ける前には広告を行うことができません（宅建業法33条）。未完成物件でも許可後であれば広告は可能です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "宅建業者は開発許可・建築確認等の処分がなければ未完成物件の広告を開始することができません（宅建業法33条）。申請中・予約があっても広告はできません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "開発許可申請中から広告できる", "reason": "申請中ではなく許可・確認が下りた後でなければ広告できません（宅建業法33条）。", "caution": "未完成物件の広告：許可・確認後（宅建業法33条）。"}, {"label": "広告はいつでも開始できる", "reason": "開発許可・建築確認等を受けた後でなければ広告できません（宅建業法33条）。「いつでも」は誤りです。", "caution": ""}, {"label": "売買予約があれば広告できる", "reason": "売買予約の有無は広告開始時期の制限（宅建業法33条）に関係しません。許可・確認後が要件です。", "caution": ""}], "summary": {"head": ["広告開始時期の制限（宅建業法33条）", "内容"], "rows": [["未完成物件の条件", "開発許可・建築確認等を受けた後"], ["申請中", "広告不可"], ["許可・確認後", "広告開始可"], ["違反", "業務停止等の行政処分"]]}}},
  {id:10524,unit:'l_kokoku',level:1,field:'law',text:'宅建業者が広告に表示しなければならない事項として正しいものはどれか。',opts:['宅建業者の代表者の写真','取引態様の別（売主・代理・媒介）','近隣の競合物件の価格','担当者の携帯番号'],ans:1,exp:'宅建業者は広告において取引態様の別（自ら売主・代理・媒介の区別）を明示しなければなりません（宅建業法34条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "宅建業者は広告に取引態様の別（売主・代理・媒介）を必ず表示しなければなりません（宅建業法34条1項）。代表者の写真・近隣物件価格・担当者携帯番号は必須表示事項ではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "宅建業者の代表者の写真", "reason": "代表者の写真は広告の必須表示事項ではありません（宅建業法34条1項）。", "caution": "広告の必須明示事項：取引態様（宅建業法34条1項）。"}, {"label": "近隣の競合物件の価格", "reason": "競合物件の価格は広告の必須表示事項ではありません（宅建業法34条1項）。", "caution": ""}, {"label": "担当者の携帯番号", "reason": "担当者の携帯番号は広告の必須表示事項ではありません（宅建業法34条1項）。", "caution": ""}], "summary": {"head": ["広告における必須明示事項（宅建業法34条1項）", "内容"], "rows": [["取引態様", "売主・代理・媒介の別を明示"], ["物件情報", "不動産公正競争規約等で詳細規定"], ["宅建業者名", "業者名の表示は義務（業者識別のため）"]]}}},
  {id:10525,unit:'l_kokoku',level:2,field:'law',text:'誇大広告の禁止規定（宅建業法32条）で禁止される表示として正しいものはどれか。',opts:['物件の正確な所在地の表示','実際より著しく優良・有利と誤認させる表示','競合物件との比較広告','値引きキャンペーンの告知'],ans:1,exp:'宅建業法32条は、物件の所在・規模・形質・現在・将来の利用の制限・環境・交通等の利便・代金等について著しく事実に相違する表示や実際より著しく優良・有利と誤認させる表示を禁止しています。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "誇大広告の禁止（宅建業法32条）は実際よりも著しく優良または有利と誤認させるような表示を禁止しています。正確な所在地表示・値引きキャンペーン告知は禁止されません。競合物件との比較広告も一定の条件下では許容されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "物件の正確な所在地の表示", "reason": "正確な所在地の表示は誇大広告にはなりません（宅建業法32条）。正確な情報の表示は推奨されます。", "caution": ""}, {"label": "競合物件との比較広告", "reason": "比較広告は景品表示法等の規制を受けますが、正確な比較であれば一律に禁止されません（宅建業法32条）。", "caution": ""}, {"label": "値引きキャンペーンの告知", "reason": "正確な値引き情報の告知は誇大広告にはなりません（宅建業法32条）。実際に行われる値引きなら問題ありません。", "caution": ""}], "summary": {"head": ["誇大広告の禁止（宅建業法32条）", "例"], "rows": [["禁止される表示", "著しく事実に相違・実際より有利と誤認させる表示"], ["禁止例", "実在しない優良点の強調・事実と異なる利便性の主張"], ["許容される表示", "正確な物件情報・実際に行われる値引きの告知"]]}}},
  {id:10526,unit:'l_kokoku',level:2,field:'law',text:'宅建業者の契約締結時期の制限として正しいものはどれか。',opts:['開発許可前でも買主が同意すれば契約できる','建築確認・開発許可等の処分前には売買契約（予約含む）を締結できない','広告前であれば契約できる','宅建業者間の取引は制限なし'],ans:1,exp:'宅建業者は開発許可・建築確認等の処分がある前には自ら売主として宅地建物の売買契約（予約を含む）を締結することができません（宅建業法36条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "宅建業者は開発許可・建築確認等の処分前には未完成物件について売買契約（予約含む）を締結することができません（宅建業法36条）。買主が同意しても例外はありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "開発許可前でも買主が同意すれば契約できる", "reason": "買主の同意があっても許可・確認前の契約は禁止されています（宅建業法36条）。", "caution": "契約締結時期制限：許可・確認後（宅建業法36条）。買主の同意は例外でない。"}, {"label": "広告前であれば契約できる", "reason": "広告の有無に関わらず許可・確認前の契約は禁止です（宅建業法36条）。", "caution": ""}, {"label": "宅建業者間の取引は制限なし", "reason": "宅建業者間の取引にも契約締結時期の制限は適用されます（宅建業法36条）。「制限なし」は誤りです。", "caution": "宅建業者間の取引にも契約締結時期制限は適用される。"}], "summary": {"head": ["契約締結時期の制限（宅建業法36条）", "内容"], "rows": [["要件", "開発許可・建築確認等を受けた後"], ["適用対象", "宅建業者すべて（相手方が宅建業者でも同様）"], ["予約", "予約も含む（本契約前の予約も禁止）"], ["違反", "業務停止等の行政処分"]]}}},
  {id:10527,unit:'l_kokoku',level:3,field:'law',text:'景品表示法と宅建業者の広告規制の関係として正しいものはどれか。',opts:['景品表示法は宅建業者には適用されない','宅建業法の広告規制に加え、景品表示法による不当表示・過大景品の規制も受ける','景品表示法違反でも宅建業法上の処分は受けない','景品表示法は消費者のみが申告できる'],ans:1,exp:'宅建業者は宅建業法上の誇大広告禁止に加え、景品表示法の不当表示（優良誤認・有利誤認）規制も受けます。景品表示法違反が宅建業法の「業務に関する不正行為」として行政処分の対象となる場合もあります。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "宅建業者は宅建業法の広告規制（宅建業法32条等）に加え、景品表示法（不当景品類及び不当表示防止法）の規制も受けます。景品表示法は不当表示・過大景品を規制し、宅建業者の広告にも適用されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "景品表示法は宅建業者には適用されない", "reason": "景品表示法は事業者一般（宅建業者を含む）に適用されます。「適用されない」は誤りです。", "caution": "景品表示法：宅建業者を含む事業者全般に適用。"}, {"label": "景品表示法違反でも宅建業法上の処分は受けない", "reason": "景品表示法違反により社会的信用が失墜した場合、宅建業法上の処分の対象となりえます（宅建業法65条等）。「処分を受けない」は誤りです。", "caution": ""}, {"label": "景品表示法は消費者のみが申告できる", "reason": "景品表示法の申告・通報は消費者に限らず、行政庁（消費者庁・公正取引委員会等）が職権で措置命令を行えます。", "caution": ""}], "summary": {"head": ["宅建業者と広告規制", "内容"], "rows": [["宅建業法32条", "誇大広告禁止"], ["宅建業法33条", "広告開始時期制限"], ["宅建業法34条", "取引態様明示義務"], ["景品表示法", "不当表示・過大景品の規制（宅建業者にも適用）"], ["不動産公正競争規約", "業界自主規制（面積・交通等の表示基準）"]]}}},
  // 住宅瑕疵担保履行法・その他（l_sonota）
  {id:10528,unit:'l_sonota',level:1,field:'law',text:'住宅瑕疵担保履行法における新築住宅の定義として正しいものはどれか。',opts:['建築後3年以内の住宅','建築後1年以内かつ未使用の住宅','建築確認を受けた住宅すべて','中古住宅も含まれる'],ans:1,exp:'住宅瑕疵担保履行法における新築住宅とは建築工事完了から1年以内で未使用の住宅を指します（住宅品質確保法2条2項）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "住宅瑕疵担保履行法における「新築住宅」は建築後1年以内かつ未使用の住宅を指します（住宅瑕疵担保履行法2条2項・品確法2条2項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "建築後3年以内の住宅", "reason": "新築住宅の定義は「建築後1年以内かつ未使用」です（品確法2条2項）。3年以内ではありません。", "caution": "新築住宅の定義：建築後1年以内かつ未使用（品確法2条2項）。"}, {"label": "建築確認を受けた住宅すべて", "reason": "建築確認を受けても使用済みや1年超の場合は新築住宅に該当しません（品確法2条2項）。", "caution": ""}, {"label": "中古住宅も含まれる", "reason": "中古住宅は新築住宅に該当しません（品確法2条2項）。", "caution": ""}], "summary": {"head": ["新築住宅の定義（品確法2条2項）", "条件"], "rows": [["建築後の期間", "1年以内"], ["使用状況", "未使用（人が居住していないこと）"], ["両方満たす", "→新築住宅に該当"]]}}},
  {id:10529,unit:'l_sonota',level:1,field:'law',text:'宅建業者が自ら売主として新築住宅を販売する場合の資力確保義務として正しいものはどれか。',opts:['任意で保険に加入する','住宅瑕疵担保保証金の供託または住宅瑕疵担保責任保険の締結が義務','建築確認があれば保険不要','買主が免除できる'],ans:1,exp:'宅建業者が自ら売主として新築住宅を販売する場合、住宅瑕疵担保保証金の供託または住宅瑕疵担保責任保険への加入が義務付けられています（住宅瑕疵担保履行法11条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "宅建業者が自ら売主として新築住宅を販売する場合、住宅瑕疵担保保証金の供託または住宅瑕疵担保責任保険の締結（加入）のいずれかが義務です（住宅瑕疵担保履行法11条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "任意で保険に加入する", "reason": "義務です（住宅瑕疵担保履行法11条）。「任意」は誤りです。", "caution": "資力確保措置：義務（住宅瑕疵担保履行法11条）。"}, {"label": "建築確認があれば保険不要", "reason": "建築確認の有無に関わらず資力確保措置（供託または保険）が必要です（住宅瑕疵担保履行法11条）。", "caution": ""}, {"label": "買主が免除できる", "reason": "買主の意思による免除はできません（住宅瑕疵担保履行法11条）。強行規定です。", "caution": ""}], "summary": {"head": ["住宅瑕疵担保履行法の資力確保義務", "内容"], "rows": [["義務者", "宅建業者（自ら売主の新築住宅売買）"], ["方法", "供託または保険加入のいずれか"], ["強行性", "買主の同意でも免除不可"], ["違反", "行政処分の対象"]]}}},
  {id:10530,unit:'l_sonota',level:2,field:'law',text:'住宅瑕疵担保責任保険の保証期間として正しいものはどれか。',opts:['1年間','2年間','5年間','10年間'],ans:3,exp:'新築住宅の構造耐力上主要な部分と雨水の浸入を防止する部分に関する瑕疵担保責任は10年間です（住宅品質確保法95条）。保険もこれに対応した10年間の保証となります。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "住宅瑕疵担保責任保険の保険期間は10年です（住宅瑕疵担保履行法・品確法95条1項）。これは品確法の基本構造部分の瑕疵担保責任期間（10年）と対応しています。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "1年間", "reason": "保険期間は10年です。1年は誤りです。", "caution": "住宅瑕疵担保責任保険の保険期間：10年。"}, {"label": "2年間", "reason": "保険期間は10年です。2年は誤りです。", "caution": ""}, {"label": "5年間", "reason": "保険期間は10年です。5年は誤りです。", "caution": ""}], "summary": {"head": ["住宅瑕疵担保責任保険の期間", "内容"], "rows": [["保険期間", "10年"], ["対応する瑕疵担保責任", "品確法95条1項（基本構造部分10年）"], ["延長", "特約で20年まで可"]]}}},
  {id:10531,unit:'l_sonota',level:2,field:'law',text:'宅地建物取引業保証協会が行う苦情解決業務として正しいものはどれか。',opts:['裁判所への提訴','宅建業者の業務に関する苦情の解決（相談・あっせん）','罰金の徴収','宅建業者の監督処分'],ans:1,exp:'宅地建物取引業保証協会は社員である宅建業者の業務に関する苦情の解決（相談受付・あっせん）を行います（宅建業法64条の5）。行政処分権限は知事・国交大臣にあります。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "宅地建物取引業保証協会（保証協会）は弁済業務のほか苦情解決業務も行います（宅建業法64条の5）。裁判所への提訴・罰金の徴収・監督処分は保証協会の業務ではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "裁判所への提訴", "reason": "保証協会が裁判所に提訴する業務はありません（宅建業法64条の5）。", "caution": ""}, {"label": "罰金の徴収", "reason": "罰金の徴収は保証協会の業務ではありません（宅建業法64条の5）。行政機関・裁判所が行います。", "caution": ""}, {"label": "宅建業者の監督処分", "reason": "監督処分は国交大臣・都道府県知事の権限です（宅建業法65条）。保証協会の業務ではありません。", "caution": ""}], "summary": {"head": ["保証協会の業務（宅建業法64条の5）", "内容"], "rows": [["弁済業務", "弁済業務保証金の管理・還付"], ["苦情解決業務", "相談・あっせんによる解決"], ["研修業務", "宅建業者・従業者への研修"], ["健全化業務", "宅建業者の業務適正化支援"]]}}},
  {id:10532,unit:'l_sonota',level:3,field:'law',text:'住宅瑕疵担保履行法における基準日と届出について正しいものはどれか。',opts:['毎年12月31日が基準日で翌年2月末までに届出','毎年3月31日と9月30日が基準日で各基準日から3週間以内に届出','年1回のみ届出すれば足りる','届出義務は任意'],ans:1,exp:'住宅瑕疵担保履行法の基準日は毎年3月31日と9月30日の年2回です（同法11条）。宅建業者は各基準日から3週間以内に供託額・保険契約締結状況を都道府県知事に届け出なければなりません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "住宅瑕疵担保履行法の基準日は毎年3月31日と9月30日の年2回です（住宅瑕疵担保履行法11条）。各基準日から3週間以内に資力確保状況を免許権者に届け出なければなりません（同法12条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "毎年12月31日が基準日で翌年2月末までに届出", "reason": "基準日は3月31日と9月30日の年2回です（住宅瑕疵担保履行法11条）。12月31日は基準日ではありません。", "caution": "基準日：3月31日と9月30日（年2回）・各基準日から3週間以内に届出（住宅瑕疵担保履行法12条）。"}, {"label": "年1回のみ届出すれば足りる", "reason": "年2回（3月31日と9月30日の基準日ごと）の届出が必要です（住宅瑕疵担保履行法11条・12条）。", "caution": ""}, {"label": "届出義務は任意", "reason": "届出は義務です（住宅瑕疵担保履行法12条1項）。「任意」は誤りです。", "caution": ""}], "summary": {"head": ["住宅瑕疵担保履行法の基準日・届出", "内容"], "rows": [["基準日", "3月31日・9月30日（年2回）"], ["届出期限", "各基準日から3週間以内"], ["届出先", "免許権者（国交大臣または都道府県知事）"], ["届出内容", "資力確保措置の状況"]]}}},
  // 売買・契約不適合責任（r_baibai）追加
  {id:10533,unit:'r_baibai',level:1,field:'rights',text:'契約不適合責任の追完請求の内容として認められないものはどれか。',opts:['目的物の修補','代替物の引渡し','不足分の引渡し','損害賠償のみの請求（追完を経ずに）'],ans:3,exp:'契約不適合があった場合の追完請求は①修補②代替物引渡し③不足分引渡しが認められます（民法562条）。損害賠償は追完請求・代金減額請求と並行して請求できますが、追完を経ずにいきなり損害賠償のみというわけではありません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "追完請求は目的物の修補・代替物の引渡し・不足分の引渡しができます（民法562条1項）。「損害賠償のみの請求（追完を経ずに）」は、追完不能の場合等を除いて原則として認められません。ただし損害賠償は追完と並行して請求することは可能です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "目的物の修補", "reason": "修補は追完請求の一態様として認められています（民法562条1項）。", "caution": ""}, {"label": "代替物の引渡し", "reason": "代替物の引渡しは追完請求の一態様として認められています（民法562条1項）。", "caution": ""}, {"label": "不足分の引渡し", "reason": "不足分の引渡しは追完請求の一態様として認められています（民法562条1項）。", "caution": ""}], "summary": {"head": ["追完請求の内容（民法562条）", "内容"], "rows": [["修補", "不適合部分の修理・補修"], ["代替物の引渡し", "不適合のない同種の物との交換"], ["不足分の引渡し", "数量不足の場合の追加引渡し"], ["選択権", "原則として買主が選択（ただし売主に不相当な負担なら拒絶可）"]]}}},
  {id:10534,unit:'r_baibai',level:2,field:'rights',text:'契約不適合を理由とする代金減額請求ができる場合として正しいものはどれか。',opts:['不適合があれば直ちに代金減額請求できる','追完請求をして相当期間内に履行されない場合または追完不能の場合に代金減額請求できる','代金減額請求には売主の帰責事由が必要','代金減額請求権は1年で消滅する'],ans:1,exp:'代金減額請求は追完請求後に相当期間内に追完されない場合、または追完が不能な場合に行使できます（民法563条）。売主の帰責事由は不要です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "代金減額請求は原則として追完請求をして相当期間内に履行されない場合にできます（民法563条1項）。ただし追完が不能・売主が拒絶・一定期間内の追完が明らかに不能等の場合は追完請求なしに直ちに代金減額請求できます（同条2項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "不適合があれば直ちに代金減額請求できる", "reason": "原則として先に追完請求をする必要があります（民法563条1項）。直ちに減額請求できるのは追完不能等の例外的な場合です（同条2項）。", "caution": "原則：追完請求→相当期間経過後に減額請求。例外：追完不能等は直ちに減額可。"}, {"label": "代金減額請求には売主の帰責事由が必要", "reason": "代金減額請求は売主の帰責事由を要件としません（民法563条）。帰責事由が必要なのは損害賠償です。", "caution": ""}, {"label": "代金減額請求権は1年で消滅する", "reason": "種類・品質の不適合は通知期限が1年ですが（民法566条）、代金減額請求権そのものの消滅時効は一般の時効（5年・10年）です。", "caution": ""}], "summary": {"head": ["代金減額請求の要件（民法563条）", "内容"], "rows": [["原則", "追完請求→相当期間経過→応じない場合に請求可"], ["例外（直ちに請求可）", "追完不能・売主の拒絶・一定期間内に不能が明らか等"], ["帰責事由", "不要（損害賠償と異なる）"]]}}},
  {id:10535,unit:'r_baibai',level:3,field:'rights',text:'不適合が買主の帰責事由による場合の売主の責任として正しいものはどれか。',opts:['売主は全く責任を負わない','買主は追完・代金減額・解除の請求ができない（損害賠償も買主の過失で相殺）','売主は通常通り全責任を負う','買主は解除のみできる'],ans:1,exp:'契約不適合が買主の責めに帰すべき事由によるものであるときは、買主は追完請求・代金減額請求・解除をすることができません（民法562条2項・563条3項・543条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "不適合が買主の帰責事由による場合、追完・代金減額・解除の請求はできません（民法562条2項・563条3項・543条）。損害賠償も買主の過失が斟酌されます（過失相殺）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "売主は全く責任を負わない", "reason": "買主の帰責事由による場合に追完・減額・解除ができないというだけで、売主が一切の責任を負わないというのは不正確です（民法562条2項等）。", "caution": ""}, {"label": "売主は通常通り全責任を負う", "reason": "買主の帰責事由による場合は追完請求・代金減額請求・解除ができません（民法562条2項・563条3項・543条）。売主が全責任を負うわけではありません。", "caution": ""}, {"label": "買主は解除のみできる", "reason": "買主の帰責事由による場合は解除もできません（民法543条）。解除のみできるとするのも誤りです。", "caution": ""}], "summary": {"head": ["買主の帰責事由がある場合", "行使可否"], "rows": [["追完請求", "不可（民法562条2項）"], ["代金減額請求", "不可（民法563条3項）"], ["解除", "不可（民法543条）"], ["損害賠償", "過失相殺・相当因果関係の問題"]]}}},
  // 賃貸借・使用貸借（r_chinshaku）追加
  {id:10536,unit:'r_chinshaku',level:1,field:'rights',text:'賃貸借契約の存続期間の上限として正しいものはどれか（民法改正後）。',opts:['20年','50年','100年','制限なし'],ans:1,exp:'民法改正後（2020年施行）、賃貸借の存続期間の上限は50年に延長されました（民法604条）。改正前は20年でしたが、長期の定期借地権等に対応するため延長されています。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "2020年民法改正により賃貸借の存続期間の上限は50年となりました（民法604条1項）。改正前の20年から延長され、長期的な事業用賃貸借にも対応できるようになりました。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "20年", "reason": "改正前は20年が上限でしたが、2020年改正後は50年です（民法604条1項）。", "caution": "2020年改正前：20年、改正後：50年。"}, {"label": "100年", "reason": "賃貸借の存続期間の上限は50年です（民法604条1項）。100年ではありません。", "caution": ""}, {"label": "制限なし", "reason": "賃貸借の存続期間には50年の上限があります（民法604条1項）。上限を超えると50年に短縮されます（同条2項）。", "caution": ""}], "summary": {"head": ["賃貸借の存続期間", "内容"], "rows": [["上限", "50年（民法604条1項）"], ["超過の場合", "50年に短縮（民法604条2項）"], ["改正前", "20年が上限（2020年改正で延長）"]]}}},
  {id:10537,unit:'r_chinshaku',level:2,field:'rights',text:'賃借人が賃貸人の承諾なく転貸した場合、賃貸人が解除できない「特段の事情」の典型例として正しいものはどれか。',opts:['賃借人と転借人が親子で実質的に同一と認められる場合','賃借人が法人の場合','転借人が外国人の場合','転借料が賃料より高い場合'],ans:0,exp:'判例は、無断転貸であっても賃借人と転借人が実質的に同一視できる場合（親子・夫婦・会社と代表者等）は背信行為と認めるに足りない特段の事情があるとして解除を否定します。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "無断転貸でも信頼関係が破壊されない特段の事情がある場合は解除できません（判例）。賃借人と転借人が親子で実質的に同一と認められる場合は、外形上の転貸であっても賃借人の使用と変わらないため、信頼関係破壊がないとされます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "賃借人が法人の場合", "reason": "賃借人が法人であることは「特段の事情」の典型例ではありません。法人の内部での使用状況等が問題になります。", "caution": ""}, {"label": "転借人が外国人の場合", "reason": "転借人の国籍は「特段の事情」に関係しません。", "caution": ""}, {"label": "転借料が賃料より高い場合", "reason": "転借料の高低は「特段の事情」の判断基準ではありません。", "caution": ""}], "summary": {"head": ["特段の事情（解除不可）の例", "内容"], "rows": [["親子間の転貸", "実質的に同一視できる→信頼関係破壊なし"], ["夫婦間の転貸", "実態により判断"], ["法人代表者への転貸", "実質的に同一の場合あり"], ["典型的な解除可能例", "全く無関係の第三者への転貸"]]}}},
  {id:10538,unit:'r_chinshaku',level:2,field:'rights',text:'使用貸借と賃貸借の違いとして正しいものはどれか。',opts:['使用貸借は有償、賃貸借は無償','使用貸借は無償で物を貸す契約で、賃貸借は有償','使用貸借には借地借家法が適用される','使用貸借の借主は第三者に対抗できる'],ans:1,exp:'使用貸借は無償で物を貸す契約（民法593条）、賃貸借は有償（賃料を払う）の契約です。使用貸借には借地借家法は適用されず、借主の権利は弱く死亡すると終了します（民法597条3項）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "使用貸借は無償で物を貸す契約（民法593条）、賃貸借は有償（賃料を払って借りる契約・民法601条）です。使用貸借には借地借家法が適用されず、借主の保護は薄いです。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "使用貸借は有償、賃貸借は無償", "reason": "逆です。使用貸借が無償、賃貸借が有償です（民法593条・601条）。", "caution": "使用貸借＝無償、賃貸借＝有償。"}, {"label": "使用貸借には借地借家法が適用される", "reason": "借地借家法は賃貸借に適用されます。無償の使用貸借には適用されません。", "caution": "使用貸借→借地借家法の適用なし（保護が薄い）。"}, {"label": "使用貸借の借主は第三者に対抗できる", "reason": "使用貸借は対抗要件制度がなく、所有者が変わると使用貸借は継続できない場合があります（民法594条3項等）。", "caution": ""}], "summary": {"head": ["使用貸借vs賃貸借", "使用貸借", "賃貸借"], "rows": [["有償・無償", "無償", "有償（賃料）"], ["借地借家法", "適用なし", "適用あり"], ["第三者対抗", "困難（登記・引渡し等の制度なし）", "対抗要件あり（引渡し・登記等）"], ["借主の保護", "薄い", "厚い（借地借家法）"]]}}},
  // 担保物権（r_tanpo）追加
  {id:10539,unit:'r_tanpo',level:1,field:'rights',text:'留置権の成立要件として正しいものはどれか。',opts:['当事者間の契約が必要','物と債権の間に牽連関係があり、他人の物を適法に占有していること','登記が必要','不動産にのみ成立する'],ans:1,exp:'留置権は①他人の物を占有②その物に関して生じた債権（牽連関係）③弁済期到来④占有が適法であることで成立します（民法295条）。契約不要・登記不要の法定担保物権です。',"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権です（民法369条）。質権は占有の移転が必要です。先取特権は法律上当然に成立する法定担保物権です。", "example": ""}, "reason": {"text": "留置権は他人の物を占有している者が、その物に関して生じた債権の弁済を受けるまで物を留置できる権利です（民法295条1項）。契約ではなく法律上当然に発生します。牽連関係とは物と債権の間に関連性があることです。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・非占有</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・占有</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "当事者間の契約が必要", "reason": "留置権は法定担保物権であり、契約がなくても法律上当然に生じます（民法295条1項）。", "caution": "留置権＝法定担保物権（契約不要）。"}, {"label": "登記が必要", "reason": "留置権の成立に登記は不要です（民法295条1項）。占有の継続が要件です。", "caution": ""}, {"label": "不動産にのみ成立する", "reason": "留置権は動産・不動産いずれにも成立します（民法295条1項）。", "caution": ""}], "summary": {"head": ["留置権の要件（民法295条）", "内容"], "rows": [["①他人の物を占有", "適法な占有であること"], ["②牽連関係", "物と債権の間に関連性（その物に関して生じた債権）"], ["③弁済期未到来", "債権が弁済期にあること"], ["性質", "法定担保物権（契約不要）"]]}}},
  {id:10540,unit:'r_tanpo',level:2,field:'rights',text:'抵当権の順位変更に必要な要件として正しいものはどれか。',opts:['順位変更は認められない','各抵当権者全員の合意と登記が必要','抵当権設定者の同意のみで足りる','裁判所の許可が必要'],ans:1,exp:'抵当権の順位変更は各抵当権者全員の合意と登記が効力発生要件です（民法374条）。利害関係人（後順位抵当権者等）の承諾も必要です。',"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権です（民法369条）。質権は占有の移転が必要です。先取特権は法律上当然に成立する法定担保物権です。", "example": ""}, "reason": {"text": "抵当権の順位変更は各抵当権者の合意と登記によって行えます（民法374条1項）。順位変更により後順位者が先順位になる等の変更ができます。設定者の同意は不要です（民法374条2項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・非占有</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・占有</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "順位変更は認められない", "reason": "民法374条により抵当権の順位変更は認められています。", "caution": ""}, {"label": "抵当権設定者の同意のみで足りる", "reason": "順位変更には各抵当権者全員の合意が必要です（民法374条1項）。設定者の同意のみでは足りません。", "caution": "順位変更＝各抵当権者全員の合意＋登記（設定者の同意は不要）。"}, {"label": "裁判所の許可が必要", "reason": "裁判所の許可は不要です（民法374条1項）。各抵当権者の合意と登記で足ります。", "caution": ""}], "summary": {"head": ["抵当権の順位変更（民法374条）", "内容"], "rows": [["要件", "各抵当権者全員の合意＋登記"], ["設定者の同意", "不要（民法374条2項）"], ["利害関係人の承諾", "必要（民法374条1項）"], ["効果", "合意した順位で優先弁済"]]}}},
  {id:10541,unit:'r_tanpo',level:3,field:'rights',text:'動産質権の効力として正しいものはどれか。',opts:['設定者が目的物を使用・収益できる','質権者は目的物を占有し留置できる（留置的効力）','質権設定に登記が必要','動産質権は成立しない'],ans:1,exp:'動産質権者は目的物を占有し（民法344条）、弁済を受けるまで留置できます（留置的効力・民法347条）。設定者は目的物の占有を質権者に移転しなければなりません。',"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権です（民法369条）。質権は占有の移転が必要です。先取特権は法律上当然に成立する法定担保物権です。", "example": ""}, "reason": {"text": "動産質権は質権者が目的物を占有し続けることで成立する担保物権です（民法344条）。質権の本質は留置的効力（占有して留置することで支払いを促す）と優先弁済的効力にあります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・非占有</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・占有</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "設定者が目的物を使用・収益できる", "reason": "質権は目的物を質権者（債権者）に引き渡す担保物権です（民法344条）。設定者は占有を失うため使用・収益できません。", "caution": "質権＝占有移転。設定者は使用不可。抵当権＝占有移転なし。設定者は使用可。"}, {"label": "質権設定に登記が必要", "reason": "動産質権の公示は登記ではなく占有（引渡し）です（民法344条・345条）。登記は不要です。", "caution": ""}, {"label": "動産質権は成立しない", "reason": "質権は動産・不動産・権利に成立します（民法344条以下）。動産質権は成立します。", "caution": ""}], "summary": {"head": ["動産質権の特徴", "内容"], "rows": [["成立要件", "引渡し（占有移転）が必要（民法344条）"], ["公示方法", "占有（登記不要）"], ["留置的効力", "弁済まで目的物を留置できる"], ["優先弁済的効力", "他の債権者に優先して弁済を受けられる"]]}}},
  // 債権総論・保証・相殺（r_saikensoron）追加
  {id:10542,unit:'r_saikensoron',level:1,field:'rights',text:'相殺が禁止される場合として正しいものはどれか。',opts:['双方の債権が金銭債権であるとき','悪意による不法行為に基づく損害賠償債務を受働債権とするとき','弁済期が到来していないとき','債権の額が等しいとき'],ans:1,exp:'悪意による不法行為に基づく損害賠償債権を受働債権（相殺される側）とする相殺は禁止されます（民法509条1号）。人の生命・身体を害する不法行為も同様に禁止されています。',"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要です（民法446条2項）。連帯保証人には催告・検索の抗弁権がありません（民法454条）。債権譲渡の第三者対抗要件は確定日付ある証書による通知または承諾です（民法467条2項）。", "example": ""}, "reason": {"text": "悪意による不法行為に基づく損害賠償債務を受働債権（相殺される側の債権）として相殺することは禁止されています（民法509条1号）。被害者が相殺によって現実の賠償を受けられなくなることを防ぐためです。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相殺の要件</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">双方が同種の債権</text></svg>", "choices": [{"label": "双方の債権が金銭債権であるとき", "reason": "双方が金銭債権であることは相殺の前提（同種の債権）であり、禁止事由ではありません（民法505条1項）。", "caution": ""}, {"label": "弁済期が到来していないとき", "reason": "自働債権の弁済期未到来は相殺の要件を満たさないため相殺できませんが（民法505条1項）、「禁止」とは異なります。", "caution": ""}, {"label": "債権の額が等しいとき", "reason": "債権額が等しいことは相殺の禁止事由ではありません（民法505条）。", "caution": ""}], "summary": {"head": ["相殺の禁止（民法509条）", "内容"], "rows": [["悪意の不法行為の損害賠償債権", "受働債権として相殺禁止（民法509条1号）"], ["人の生命・身体侵害の損害賠償", "受働債権として相殺禁止（民法509条2号）"], ["差押禁止債権", "受働債権として相殺禁止（民法510条）"]]}}},
  {id:10543,unit:'r_saikensoron',level:2,field:'rights',text:'連帯債務者の一人について生じた事項の絶対的効力として正しいものはどれか。',opts:['履行の請求は他の連帯債務者にも時効完成猶予の効力がある','連帯債務者の一人に対する履行の請求は他の連帯債務者の時効を中断しない（相対的効力）','一人の免除は全員の債務を消滅させる','一人の弁済は他の連帯債務者の債務に影響しない'],ans:1,exp:'2020年民法改正後、連帯債務者の一人に対する請求は他の連帯債務者に対して時効の完成猶予・更新の効力を持ちません（相対的効力・民法441条）。ただし当事者間で合意すれば絶対的効力とすることができます。',"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要です（民法446条2項）。連帯保証人には催告・検索の抗弁権がありません（民法454条）。債権譲渡の第三者対抗要件は確定日付ある証書による通知または承諾です（民法467条2項）。", "example": ""}, "reason": {"text": "2020年民法改正後、連帯債務者の一人に対する履行の請求は相対的効力となり、他の連帯債務者の時効の進行に影響しません（民法441条）。改正前は絶対的効力（時効中断）がありましたが廃止されました。弁済・相殺・更改等は絶対的効力を維持しています。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相殺の要件</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">双方が同種の債権</text></svg>", "choices": [{"label": "履行の請求は他の連帯債務者にも時効完成猶予の効力がある", "reason": "2020年改正後、履行の請求は相対的効力であり他の連帯債務者の時効に影響しません（民法441条）。", "caution": "改正後：履行の請求は相対的効力（他の連帯債務者に影響なし）。"}, {"label": "一人の免除は全員の債務を消滅させる", "reason": "免除は相対的効力であり、他の連帯債務者の債務には影響しません（民法441条）。", "caution": ""}, {"label": "一人の弁済は他の連帯債務者の債務に影響しない", "reason": "弁済は絶対的効力であり（民法438条）、弁済した分だけ全員の債務が減少します。「影響しない」は誤りです。", "caution": ""}], "summary": {"head": ["連帯債務の効力（2020年改正後）", "絶対効か相対効か"], "rows": [["弁済", "絶対的効力（全員の債務が消滅）"], ["相殺", "絶対的効力（相殺分が全員に減少）"], ["更改", "絶対的効力"], ["請求", "相対的効力（他の者に影響なし）→改正で変更"], ["免除", "相対的効力"], ["時効", "相対的効力"]]}}},
  // 意思表示（r_ishi）追加
  {id:10544,unit:'r_ishi',level:1,field:'rights',text:'通謀虚偽表示（民法94条）の第三者保護の要件として正しいものはどれか。',opts:['第三者は善意でも悪意でも保護される','第三者は善意（虚偽表示を知らない）であれば保護される','第三者は善意無過失が必要','第三者は登記を備えなければ保護されない'],ans:1,exp:'通謀虚偽表示の無効は善意の第三者に対抗できません（民法94条2項）。第三者は善意であれば保護され、無過失は不要です（悪意でなければ足りる）。',"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "意思表示の瑕疵には詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失の第三者は保護）・通謀虚偽表示（無効・善意の第三者は保護）があります。", "example": ""}, "reason": {"text": "通謀虚偽表示は当事者AとBが共謀して虚偽の外観を作り出したものです。善意の第三者がその外観を信頼して取引した場合、外観を作り出した当事者が不利益を受けるべきという考え方から第三者を保護します（民法94条2項）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "第三者は善意でも悪意でも保護される", "reason": "保護されるのは善意の第三者のみです（民法94条2項）。悪意の第三者は保護されません。", "caution": ""}, {"label": "第三者は善意無過失が必要", "reason": "通謀虚偽表示の第三者保護は「善意」のみで足り、無過失は不要です（民法94条2項）。詐欺の場合の「善意無過失」と混同しないよう注意。", "caution": "詐欺の第三者保護＝善意無過失が必要。通謀虚偽表示の第三者保護＝善意のみで足る（無過失不要）。"}, {"label": "第三者は登記を備えなければ保護されない", "reason": "通謀虚偽表示の善意の第三者保護に登記は不要です（判例）。", "caution": ""}], "summary": {"head": ["比較", "詐欺（96条3項）", "通謀虚偽表示（94条2項）"], "rows": [["第三者の要件", "善意かつ無過失", "善意のみ（無過失不要）"], ["登記の要否", "対抗問題として登記必要", "不要（判例）"]]}}},
  {id:10545,unit:'r_ishi',level:2,field:'rights',text:'錯誤取消しの要件として正しいものはどれか（2020年改正後）。',opts:['表意者に重大な過失がある場合も取消しできる','法律行為の目的及び取引上の社会通念に照らして重要なものであること、かつ表意者に重大な過失がないこと','相手方の詐欺があった場合のみ認められる','公証人の認証が必要'],ans:1,exp:'2020年民法改正後の錯誤取消しは①意思表示の動機等に関する錯誤であること②法律行為の目的及び社会通念に照らして重要であること③表意者に重大な過失がないことが要件です（民法95条）。',"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "意思表示の瑕疵には詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失の第三者は保護）・通謀虚偽表示（無効・善意の第三者は保護）があります。", "example": ""}, "reason": {"text": "2020年民法改正で錯誤は「無効」から「取消し」に改められました（民法95条）。要件は①重要な錯誤であること②表意者に重大な過失がないこと（例外あり）です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "表意者に重大な過失がある場合も取消しできる", "reason": "重大な過失がある場合は原則として取消しができません（民法95条3項）。例外として相手方が悪意・重過失の場合や同一の錯誤に陥っていた場合は取消しが認められます。", "caution": "「重過失がある場合も取消しできる」は原則として誤り。例外的に可能な場合があるだけです。"}, {"label": "相手方の詐欺があった場合のみ認められる", "reason": "錯誤（95条）は詐欺（96条）とは別の制度です。相手方に詐欺がなくても表意者に重要な錯誤があれば取消しの対象になります。", "caution": ""}, {"label": "公証人の認証が必要", "reason": "錯誤取消しに公証人の認証は不要です。", "caution": ""}], "summary": {"head": ["要件", "内容"], "rows": [["錯誤の重要性", "法律行為の目的・取引上の社会通念に照らして重要"], ["動機の錯誤", "動機が表示されて法律行為の内容となった場合"], ["表意者の過失", "重大な過失がないこと（原則）"], ["例外", "相手方が悪意・重過失の場合等は重過失あっても取消し可"]]}}},
  // 時効（r_jiko）追加
  {id:10546,unit:'r_jiko',level:1,field:'rights',text:'時効の完成猶予事由として正しいものはどれか。',opts:['時効の利益の放棄','裁判上の請求・差押え・仮処分等','弁済の承認','時効期間の経過'],ans:1,exp:'時効の完成猶予事由は裁判上の請求・差押え・仮処分・仮差押え・協議を行う旨の合意書面等です（民法147条以下）。弁済の承認は時効の更新（新たな時効が進行開始）事由です。',"kaisetsu":{"topic": "消滅時効：知った時から5年または行使可能時から10年", "basis": {"text": "一般の債権の消滅時効は「権利行使できると知った時から5年」または「権利行使できる時から10年」のいずれか早い方で完成します（民法166条1項）。時効は援用して初めて効力が発生します（民法145条）。", "example": ""}, "reason": {"text": "時効の完成猶予事由は裁判上の請求・差押え・仮差押え・仮処分・催告等です（民法147条〜150条）。これらにより時効の完成が一定期間阻止されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">時効期間</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人の生命・身体への損害</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年または20年</text></svg>", "choices": [{"label": "時効の利益の放棄", "reason": "時効の利益の放棄（時効完成後）は時効の援用を遮断しますが、完成猶予事由ではありません（民法146条）。", "caution": ""}, {"label": "弁済の承認", "reason": "承認は時効の「更新」事由です（民法152条）。完成猶予ではなく更新（新たな時効の進行開始）が生じます。", "caution": "承認＝更新（完成猶予ではない）。"}, {"label": "時効期間の経過", "reason": "時効期間の経過は時効の「完成」であり、完成猶予事由ではありません。", "caution": ""}], "summary": {"head": ["完成猶予事由", "効果の概要"], "rows": [["裁判上の請求（民法147条）", "確定判決等まで猶予→更新"], ["差押え・仮差押え・仮処分（民法148条）", "手続終了後6か月まで猶予→更新"], ["催告（民法150条）", "6か月間猶予"], ["協議合意（民法151条）", "合意から最長1年等猶予"]]}}},
  {id:10547,unit:'r_jiko',level:2,field:'rights',text:'時効の利益の放棄について正しいものはどれか。',opts:['時効完成前でも放棄できる','時効完成後であれば時効の利益を放棄できる','時効の放棄は第三者にも効力が及ぶ','時効の放棄は口頭では無効'],ans:1,exp:'時効の利益は時効完成後であれば放棄できます（民法146条）。時効完成前の予め放棄する合意は無効です。放棄の効力は相対的で、連帯保証人等の第三者には及びません。',"kaisetsu":{"topic": "消滅時効：知った時から5年または行使可能時から10年", "basis": {"text": "一般の債権の消滅時効は「権利行使できると知った時から5年」または「権利行使できる時から10年」のいずれか早い方で完成します（民法166条1項）。時効は援用して初めて効力が発生します（民法145条）。", "example": ""}, "reason": {"text": "時効の利益の放棄は時効完成後にのみできます（民法146条）。完成前の放棄を認めると、経済的弱者が事前に放棄を強制させられるおそれがあるため、完成後にのみ認められます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">時効期間</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人の生命・身体への損害</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年または20年</text></svg>", "choices": [{"label": "時効完成前でも放棄できる", "reason": "時効完成前の放棄は認められません（民法146条）。完成後にのみ放棄できます。", "caution": "時効完成前の放棄＝無効（民法146条）。"}, {"label": "時効の放棄は第三者にも効力が及ぶ", "reason": "時効利益の放棄の効力は放棄者のみに及び、第三者（保証人・物上保証人等）には及びません（相対効）。", "caution": "放棄の効力は放棄した者のみ。第三者には及びません。"}, {"label": "時効の放棄は口頭では無効", "reason": "時効利益の放棄に書面は不要です。口頭でも有効です（民法146条に方式規定なし）。", "caution": ""}], "summary": {"head": ["時効利益の放棄", "内容"], "rows": [["完成前の放棄", "無効（民法146条）"], ["完成後の放棄", "有効"], ["放棄の効力", "相対効（放棄者のみ・第三者に及ばない）"]]}}},
  // 物権変動・登記（r_bukken）追加
  {id:10548,unit:'r_bukken',level:1,field:'rights',text:'不動産物権変動の対抗要件として正しいものはどれか。',opts:['公正証書の作成','登記','引渡し','占有'],ans:1,exp:'不動産物権変動の対抗要件は登記です（民法177条）。動産の場合は引渡しが対抗要件です（民法178条）。',"kaisetsu":{"topic": "物権変動：登記が対抗要件・不法占拠者には登記不要", "basis": {"text": "不動産の物権変動は登記が第三者への対抗要件です（民法177条）。不法占拠者には登記なく対抗できます。相続の法定相続分超過部分は登記が必要です（民法899条の2）。", "example": ""}, "reason": {"text": "不動産の物権変動の対抗要件は登記です（民法177条）。登記制度により権利関係を公示し、誰でも確認できる仕組みにすることで取引の安全を図っています。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">物権変動の対抗要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対抗要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">二重譲渡</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先に登記した者が優先</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不法占拠者</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記不要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物賃借権</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡し</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続（超過部分）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記必要</text></svg>", "choices": [{"label": "公正証書の作成", "reason": "公正証書は法律行為の証明力を高めますが、不動産物権変動の対抗要件ではありません。登記が対抗要件です（民法177条）。", "caution": ""}, {"label": "引渡し", "reason": "引渡しは動産物権変動の対抗要件（民法178条）です。不動産には引渡しではなく登記が必要です。", "caution": "不動産＝登記、動産＝引渡し。この区別は宅建の最重要基礎知識です。"}, {"label": "占有", "reason": "占有は即時取得の要件等に関係しますが、不動産物権変動の対抗要件ではありません。", "caution": ""}], "summary": {"head": ["目的物", "対抗要件", "根拠条文"], "rows": [["不動産", "登記", "民法177条"], ["動産", "引渡し", "民法178条"], ["建物賃借権", "建物の引渡し", "借地借家法31条"], ["借地権（建物所有目的）", "建物の登記", "借地借家法10条"]]}}},
  {id:10549,unit:'r_bukken',level:2,field:'rights',text:'即時取得（善意取得）の成立要件として正しいものはどれか。',opts:['不動産にも適用される','動産を平穏・公然・善意・無過失で取引行為により占有取得した場合に成立','登記を備えた場合のみ成立','相手方が真の所有者であることが必要'],ans:1,exp:'即時取得（民法192条）は動産について、取引行為・平穏・公然・善意・無過失で占有を取得した場合に成立します。不動産には適用されません（登記制度があるため）。',"kaisetsu":{"topic": "物権変動：登記が対抗要件・不法占拠者には登記不要", "basis": {"text": "不動産の物権変動は登記が第三者への対抗要件です（民法177条）。不法占拠者には登記なく対抗できます。相続の法定相続分超過部分は登記が必要です（民法899条の2）。", "example": ""}, "reason": {"text": "即時取得は取引相手が真の所有者でなくても、善意・無過失で動産を取得した者を保護する制度です。動産には登記制度がないため外観（占有）を信頼した者を保護する必要があります。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">物権変動の対抗要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対抗要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">二重譲渡</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先に登記した者が優先</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不法占拠者</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記不要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物賃借権</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡し</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続（超過部分）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記必要</text></svg>", "choices": [{"label": "不動産にも適用される", "reason": "即時取得は動産のみが対象です（民法192条）。不動産は登記で公示されるため即時取得の適用はありません。", "caution": "即時取得＝動産のみ。"}, {"label": "登記を備えた場合のみ成立", "reason": "動産には登記制度がなく、即時取得は「占有取得（引渡し）」で成立します。登記は不動産の対抗要件であり動産の即時取得とは無関係です。", "caution": ""}, {"label": "相手方が真の所有者であることが必要", "reason": "即時取得は相手方が無権利者（真の所有者でない者）から取得した場合でも所有権を取得できる制度です。真の所有者からの取得であれば通常の売買になります。", "caution": ""}], "summary": {"head": ["要件", "内容"], "rows": [["対象物", "動産（不動産・有価証券等は別規定）"], ["取引行為", "売買・交換等による占有取得"], ["占有の態様", "平穏・公然・善意・無過失"], ["効果", "即時に完全な所有権を取得（前主の権利の瑕疵が治癒）"]]}}},
  // 免許制度・欠格事由（l_menkyo）追加
  {id:10550,unit:'l_menkyo',level:1,field:'law',text:'宅建業の免許が不要な場合として正しいものはどれか。',opts:['年2回を超えて自己所有不動産を売却する場合','自己所有の不動産を賃貸する場合（自ら貸主）','他人から依頼されて不動産の売買を仲介する場合','分譲マンションを自ら販売する場合'],ans:1,exp:'自ら貸主として不動産を賃貸する行為は宅建業（取引業）に該当しないため免許不要です（宅建業法2条2号）。ただし賃貸の媒介・代理を業として行う場合は免許が必要です。',"kaisetsu":{"topic": "宅建業の免許：知事・大臣免許の区別・有効期間5年・欠格事由", "basis": {"text": "1都道府県のみ→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間です。", "example": ""}, "reason": {"text": "宅建業とは宅地・建物の売買・交換・賃借の「代理・媒介」または「自ら売主として売買・交換」することを業として行うことです（宅建業法2条2号）。自ら貸主として賃貸することは「業」に含まれず、免許不要です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（拘禁刑以上・特定罰金等）</text></svg>", "choices": [{"label": "年2回を超えて自己所有不動産を売却する場合", "reason": "反復継続して不特定多数に自己所有不動産を売却する場合は宅建業に該当し免許が必要です（宅建業法2条2号）。「年2回」という基準はありませんが、反復継続性があれば宅建業に該当します。", "caution": ""}, {"label": "他人から依頼されて不動産の売買を仲介する場合", "reason": "他人の売買の仲介（媒介）は宅建業に該当し免許が必要です（宅建業法2条2号）。", "caution": ""}, {"label": "分譲マンションを自ら販売する場合", "reason": "自ら売主として分譲マンションを販売することは宅建業に該当し免許が必要です（宅建業法2条2号）。", "caution": ""}], "summary": {"head": ["宅建業の定義（宅建業法2条2号）", "免許の要否"], "rows": [["自ら売主として売買・交換（業として）", "必要"], ["他人の売買・交換・賃借の媒介・代理（業として）", "必要"], ["自ら貸主として賃貸", "不要"], ["国・地方公共団体の取引", "不要（宅建業法78条）"]]}}},
  {id:10551,unit:'l_menkyo',level:2,field:'law',text:'免許の欠格事由に該当する者として正しいものはどれか。',opts:['拘禁刑以上の刑に処せられてから5年が経過した者','宅建業法違反で罰金刑を受けてから5年が経過していない者','成年被後見人でなくなってから5年が経過した者','破産者で復権を得た者'],ans:1,exp:'宅建業法違反・暴力団関連犯罪・背任罪等で罰金刑を受け、その刑の執行終了等から5年を経過しない者は欠格事由に該当します（宅建業法5条1項）。拘禁刑以上・破産で復権未取得も同様です。',"kaisetsu":{"topic": "宅建業の免許：知事・大臣免許の区別・有効期間5年・欠格事由", "basis": {"text": "1都道府県のみ→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間です。", "example": ""}, "reason": {"text": "宅建業法違反・詐欺・背任等で罰金刑に処せられてから5年が経過していない者は欠格事由に該当します（宅建業法5条1項5号）。5年が経過すれば欠格事由から外れて免許を取得できます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（拘禁刑以上・特定罰金等）</text></svg>", "choices": [{"label": "拘禁刑以上の刑に処せられてから5年が経過した者", "reason": "拘禁刑以上の刑の執行終了等から5年が経過した者は欠格事由から外れ、免許を取得できます（宅建業法5条1項5号）。欠格事由に該当しません。", "caution": "5年経過後＝欠格事由から外れる→免許取得可。"}, {"label": "成年被後見人でなくなってから5年が経過した者", "reason": "2021年改正後、成年被後見人であることは一律の欠格事由ではなくなりました。「でなくなってから5年」という規定もありません。", "caution": ""}, {"label": "破産者で復権を得た者", "reason": "破産者で復権を得た者は欠格事由に該当しません（宅建業法5条1項1号は「破産手続開始決定を受けて復権を得ない者」が欠格事由）。復権を得ていれば問題ありません。", "caution": ""}], "summary": {"head": ["欠格事由（宅建業法5条1項5号）", "期間"], "rows": [["宅建業法・背任・詐欺等で罰金刑", "罰金から5年未満＝欠格事由"], ["拘禁刑以上の刑", "執行終了等から5年未満＝欠格事由"], ["5年経過後", "欠格事由から外れる"], ["執行猶予中", "執行猶予が満了するまで欠格事由"]]}}},
  // 宅建士（l_takkenshi）追加
  {id:10552,unit:'l_takkenshi',level:1,field:'law',text:'宅建士証の有効期間として正しいものはどれか。',opts:['3年','5年','10年','更新不要の永続'],ans:1,exp:'宅建士証の有効期間は5年です（宅建業法22条の2第4項）。更新には法定講習（有効期間満了の6か月前から）の受講が必要です。',"kaisetsu":{"topic": "専任の宅建士：5人に1人以上・兼任不可・不足時は2週間以内に補充", "basis": {"text": "事務所には業務従事者5人に1人以上の専任宅建士が必要です（宅建業法31条の3）。専任宅建士は1社専属で複数業者の兼任は不可。不足時は2週間以内に補充が必要です。", "example": ""}, "reason": {"text": "宅建士証の有効期間は5年です（宅建業法22条の2第1項）。更新には有効期間満了前に法定講習（交付申請前6か月以内）を受講し、都道府県知事に申請します（同条2項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">専任宅建士のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">設置基準</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5人に1人以上（主従同じ）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">兼任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可（1社専属）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不足補充</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間以内</text></svg>", "choices": [{"label": "3年", "reason": "宅建士証の有効期間は5年です（宅建業法22条の2第1項）。3年ではありません。", "caution": ""}, {"label": "10年", "reason": "宅建士証の有効期間は5年です（宅建業法22条の2第1項）。10年ではありません。", "caution": ""}, {"label": "更新不要の永続", "reason": "宅建士証は5年ごとの更新が必要です（宅建業法22条の2第1項・2項）。永続ではありません。", "caution": ""}], "summary": {"head": ["宅建士証と法定講習", "内容"], "rows": [["有効期間", "5年（宅建業法22条の2第1項）"], ["更新に必要な講習", "交付申請前6か月以内に受講"], ["例外（講習不要）", "合格後1年以内の最初の交付申請"], ["返納", "事務禁止処分中・登録消除時等"]]}}},
  {id:10553,unit:'l_takkenshi',level:2,field:'law',text:'宅建士の登録消除事由として正しいものはどれか。',opts:['宅建試験に再受験した場合','死亡または登録欠格事由に該当した場合','事務所を移転した場合','氏名を変更した場合'],ans:1,exp:'宅建士の登録は、死亡、登録欠格事由への該当、不正登録、重大な違反行為等があった場合に消除されます（宅建業法68条の2）。成年被後見人・被保佐人であること自体は、現行法上、当然に一律欠格となるものではありません。氏名変更・事務所移転は変更届が必要ですが消除ではありません。',"kaisetsu":{"topic": "専任の宅建士：5人に1人以上・兼任不可・不足時は2週間以内に補充", "basis": {"text": "事務所には業務従事者5人に1人以上の専任宅建士が必要です（宅建業法31条の3）。専任宅建士は1社専属で複数業者の兼任は不可。不足時は2週間以内に補充が必要です。", "example": ""}, "reason": {"text": "宅建士の登録が消除される主な事由は、死亡、登録欠格事由への該当、不正登録、事務禁止処分違反等です（宅建業法68条の2・18条）。成年被後見人・被保佐人であること自体を当然の登録消除事由とする旧説明は現行法に合わせて避ける必要があります。氏名変更・事務所移転は変更登録の対象であり登録消除事由ではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">専任宅建士のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">設置基準</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5人に1人以上（主従同じ）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">兼任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可（1社専属）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不足補充</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間以内</text></svg>", "choices": [{"label": "宅建試験に再受験した場合", "reason": "再受験は登録消除事由ではありません（宅建業法68条の2）。", "caution": ""}, {"label": "事務所を移転した場合", "reason": "事務所の移転は変更登録の対象です（宅建業法20条）。登録消除事由ではありません。", "caution": ""}, {"label": "氏名を変更した場合", "reason": "氏名変更は変更登録の対象です（宅建業法20条）。登録消除事由ではありません。", "caution": ""}], "summary": {"head": ["登録消除事由", "内容"], "rows": [["死亡", "当然消除"], ["欠格事由に該当（拘禁刑刑等）", "消除"], ["不正手段で登録", "必要的消除（宅建業法68条の2）"], ["事務禁止処分違反", "必要的消除（宅建業法68条の2）"]]}}},
  // 報酬（l_hoshu）追加
  {id:10554,unit:'l_hoshu',level:1,field:'law',text:'宅建業者が受け取る報酬の上限を定めているのはどれか。',opts:['民法','宅建業法の規定に基づく国土交通大臣告示','都道府県条例','当事者の合意のみ'],ans:1,exp:'宅建業者が宅地建物取引に関して受け取れる報酬の上限は宅建業法46条に基づく国土交通大臣告示によって定められています。上限を超える報酬を受け取ることは禁止されています。',"kaisetsu":{"topic": "報酬：売買は代金×3%+6万（400万超）・賃貸は借賃1か月・上限超過は不可", "basis": {"text": "売買媒介報酬（400万超）の一方からの上限は代金×3%+6万円（税別）。双方合計は一方上限×2。賃貸媒介（居住用・非居住用とも）は借賃1か月分。依頼者の承諾があっても上限超過は不可。", "example": ""}, "reason": {"text": "宅建業者が受け取る報酬の上限は国土交通大臣が告示で定めます（宅建業法46条2項）。民法・都道府県条例・当事者の合意ではありません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対象</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（400万超）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万（一方）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（200万以下）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸（双方合計）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借賃1か月分</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">低廉な空家等（800万円以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円まで（説明・合意要）</text></svg>", "choices": [{"label": "民法", "reason": "民法は報酬限度額を定めていません。宅建業法46条に基づく国土交通省告示が根拠です。", "caution": "報酬限度額の根拠：宅建業法46条＋国土交通省告示。"}, {"label": "都道府県条例", "reason": "都道府県条例ではなく国土交通大臣告示で定められます（宅建業法46条2項）。", "caution": ""}, {"label": "当事者の合意のみ", "reason": "報酬は強行規定の告示により上限が定められており、当事者の合意だけで自由に決められません（宅建業法46条3項）。", "caution": ""}], "summary": {"head": ["報酬規制の根拠", "内容"], "rows": [["宅建業法46条1項", "報酬の限度額の定めを大臣に委任"], ["宅建業法46条2項", "国土交通大臣が告示で定める"], ["告示（現行）", "速算式等で具体的上限額を規定"], ["強行規定", "依頼者の同意でも超過不可（宅建業法46条3項）"]]}}},
  {id:10555,unit:'l_hoshu',level:2,field:'law',text:'賃貸借の媒介報酬の上限（依頼者双方合計）として正しいものはどれか。',opts:['賃料の1か月分（消費税別）','賃料の2か月分','賃料の半月分','賃料の3か月分'],ans:0,exp:'居住用建物の賃貸借媒介の場合、依頼者双方から受け取る報酬の合計上限は賃料の1か月分（消費税別）です（国土交通省告示）。依頼者一方からの上限は原則賃料の0.5か月分ですが、依頼者の承諾があれば一方から1か月分まで受け取れます。',"kaisetsu":{"topic": "報酬：売買は代金×3%+6万（400万超）・賃貸は借賃1か月・上限超過は不可", "basis": {"text": "売買媒介報酬（400万超）の一方からの上限は代金×3%+6万円（税別）。双方合計は一方上限×2。賃貸媒介（居住用・非居住用とも）は借賃1か月分。依頼者の承諾があっても上限超過は不可。", "example": ""}, "reason": {"text": "賃貸借媒介の報酬は依頼者双方（貸主・借主）から合計して賃料の1か月分（税別）が上限です（告示）。売買と異なり賃借料の月額が基準になります。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対象</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（400万超）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万（一方）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（200万以下）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸（双方合計）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借賃1か月分</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">低廉な空家等（800万円以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円まで（説明・合意要）</text></svg>", "choices": [{"label": "賃料の2か月分", "reason": "双方合計の上限は1か月分です（告示）。2か月分は誤りです。", "caution": "賃貸借媒介の報酬：双方合計で1か月分（告示）。"}, {"label": "賃料の半月分", "reason": "半月分は一方から受け取れる原則的な上限です（告示）。双方合計は1か月分です。", "caution": ""}, {"label": "賃料の3か月分", "reason": "3か月分は誤りです（告示）。双方合計で1か月分が上限です。", "caution": ""}], "summary": {"head": ["賃貸借媒介の報酬（告示）", "上限"], "rows": [["双方合計", "賃料の1か月分（税別）"], ["一方のみ（原則）", "0.5か月分"], ["一方のみ（承諾あり）", "1か月分（合計1か月分の範囲）"], ["売買との違い", "売買は代金×3%＋6万円。賃貸は賃料1か月分。"]]}}},
  // 37条書面（l_37jo）追加
  {id:10556,unit:'l_37jo',level:1,field:'law',text:'37条書面に記載が不要な事項として正しいものはどれか。',opts:['物件の引渡し時期','代金の額','近隣の騒音状況','移転登記申請の時期'],ans:2,exp:'37条書面の必要的記載事項は①物件特定②代金・借賃③引渡し時期④移転登記申請時期等です（宅建業法37条1項）。近隣の騒音状況は37条書面ではなく重要事項説明（35条書面）でも必須ではなく、周辺環境への任意記載事項です。',"kaisetsu":{"topic": "37条書面：全取引で交付・記名（押印不要）・移転登記申請時期は必要的記載事項", "basis": {"text": "37条書面は売買・交換・賃貸借の全取引で契約の双方当事者に交付が義務（宅建業法37条）。引渡し時期・移転登記申請時期は必要的記載事項。2021年改正で押印は不要になり記名のみで足ります。", "example": ""}, "reason": {"text": "37条書面の必要的記載事項は宅建業法37条1項に列挙されており、近隣の騒音状況は含まれません。引渡し時期・代金の額・移転登記申請時期はすべて必要的記載事項です（同条1項2号・4号・5号）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付義務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全取引・双方当事者</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡時期・移転登記申請時期等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要）</text></svg>", "choices": [{"label": "物件の引渡し時期", "reason": "引渡し時期は必要的記載事項です（宅建業法37条1項4号）。", "caution": ""}, {"label": "代金の額", "reason": "代金の額は必要的記載事項です（宅建業法37条1項2号）。", "caution": ""}, {"label": "移転登記申請の時期", "reason": "移転登記申請の時期は必要的記載事項です（宅建業法37条1項5号）。", "caution": ""}], "summary": {"head": ["37条書面に記載が不要な事項", "内容"], "rows": [["近隣の騒音・振動", "不要"], ["近隣施設の情報", "不要"], ["法令上の制限の概要", "不要（35条書面の記載事項）"], ["登記された権利", "不要（35条書面の記載事項）"]]}}},
  {id:10557,unit:'l_37jo',level:2,field:'law',text:'37条書面と35条書面（重要事項説明書）の違いとして正しいものはどれか。',opts:['両書面とも契約前に交付する','35条書面は契約前・37条書面は契約後に交付する','37条書面は売主のみに交付する','35条書面には宅建士の記名は不要'],ans:1,exp:'重要事項説明書（35条書面）は契約前に買主・借主に交付します。37条書面は契約成立後遅滞なく売主・買主双方に交付します。両書面とも宅建士の記名が必要です（押印は廃止）。',"kaisetsu":{"topic": "37条書面：全取引で交付・記名（押印不要）・移転登記申請時期は必要的記載事項", "basis": {"text": "37条書面は売買・交換・賃貸借の全取引で契約の双方当事者に交付が義務（宅建業法37条）。引渡し時期・移転登記申請時期は必要的記載事項。2021年改正で押印は不要になり記名のみで足ります。", "example": ""}, "reason": {"text": "35条書面（重要事項説明書）は契約締結前に交付し、37条書面（契約書面）は契約締結後に遅滞なく交付します（宅建業法35条1項・37条1項）。交付時期が異なる点が重要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付義務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全取引・双方当事者</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡時期・移転登記申請時期等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要）</text></svg>", "choices": [{"label": "両書面とも契約前に交付する", "reason": "37条書面は契約後に交付します（宅建業法37条1項）。「両方契約前」は誤りです。", "caution": "35条書面：契約前。37条書面：契約後（宅建業法35条・37条）。"}, {"label": "37条書面は売主のみに交付する", "reason": "37条書面は売主・買主双方に交付します（宅建業法37条1項）。売主のみではありません。", "caution": ""}, {"label": "35条書面には宅建士の記名は不要", "reason": "35条書面にも宅建士の記名が必要です（宅建業法35条1項）。「不要」は誤りです。", "caution": ""}], "summary": {"head": ["35条書面と37条書面の比較", "35条書面", "37条書面"], "rows": [["交付時期", "契約締結前", "契約締結後（遅滞なく）"], ["宅建士の記名", "必要", "必要"], ["押印", "不要（2022年改正）", "不要（2022年改正）"], ["交付先", "買主（借主）", "売主・買主双方"]]}}},
  // 媒介契約（l_baikai）追加
  {id:10558,unit:'l_baikai',level:1,field:'law',text:'専属専任媒介契約の報告頻度として正しいものはどれか。',opts:['1か月に1回以上','2週間に1回以上','1週間に1回以上','3日に1回以上'],ans:2,exp:'専属専任媒介契約では1週間に1回以上の業務処理状況の報告義務があります（宅建業法34条の2第9項）。専任媒介は2週間に1回以上です。',"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任媒介の有効期間の上限は3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。専任は7日以内、専属専任は5日以内にレインズ登録が必要。業務報告は専任2週間に1回、専属専任1週間に1回。", "example": ""}, "reason": {"text": "専属専任媒介契約では業務処理状況の報告を1週間に1回以上行わなければなりません（宅建業法34条の2第10項）。専任媒介は2週間に1回以上です（同条9項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">一般</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専任</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専属専任</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己発見取引</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">レインズ登録</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務報告</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">なし</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間に1回</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1週間に1回</text></svg>", "choices": [{"label": "1か月に1回以上", "reason": "月1回では不足です。専属専任は1週間に1回以上が義務です（宅建業法34条の2第10項）。", "caution": "専属専任媒介：1週間に1回以上の報告義務（宅建業法34条の2第10項）。"}, {"label": "2週間に1回以上", "reason": "2週間に1回以上は専任媒介の報告頻度です（宅建業法34条の2第9項）。専属専任はより高頻度の1週間に1回以上です（同条10項）。", "caution": ""}, {"label": "3日に1回以上", "reason": "3日に1回という規定はありません（宅建業法34条の2第10項）。1週間に1回以上が正しいです。", "caution": ""}], "summary": {"head": ["業務報告頻度", "専任媒介", "専属専任媒介"], "rows": [["法定頻度", "2週間に1回以上", "1週間に1回以上"], ["根拠", "宅建業法34条の2第9項", "宅建業法34条の2第10項"], ["一般媒介", "義務なし", "（比較）"]]}}},
  {id:10559,unit:'l_baikai',level:2,field:'law',text:'一般媒介契約における宅建業者の義務として正しいものはどれか。',opts:['レインズへの登録が義務付けられている','定期的な業務報告が義務付けられている','レインズ登録義務・定期報告義務ともにない','有効期間は3か月を超えてはならない'],ans:2,exp:'一般媒介契約にはレインズ登録義務も定期報告義務もありません。ただし有効期間の法的上限の定めもありません（専任・専属専任は3か月が上限）。',"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任媒介の有効期間の上限は3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。専任は7日以内、専属専任は5日以内にレインズ登録が必要。業務報告は専任2週間に1回、専属専任1週間に1回。", "example": ""}, "reason": {"text": "一般媒介契約にはレインズへの登録義務も定期的な業務報告義務もありません（宅建業法34条の2）。これが専任媒介・専属専任媒介との大きな違いです。有効期間の上限規定（3か月）も一般媒介には適用されません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">一般</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専任</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専属専任</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己発見取引</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">レインズ登録</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務報告</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">なし</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間に1回</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1週間に1回</text></svg>", "choices": [{"label": "レインズへの登録が義務付けられている", "reason": "レインズへの登録義務があるのは専任媒介（7日以内）・専属専任媒介（5日以内）です（宅建業法34条の2第5項・6項）。一般媒介には登録義務がありません。", "caution": "一般媒介：レインズ登録義務なし。"}, {"label": "定期的な業務報告が義務付けられている", "reason": "定期的な業務報告義務があるのは専任媒介（2週間）・専属専任媒介（1週間）です（宅建業法34条の2第9項・10項）。一般媒介には義務がありません。", "caution": ""}, {"label": "有効期間は3か月を超えてはならない", "reason": "有効期間の3か月上限は専任媒介・専属専任媒介のみの規制です（宅建業法34条の2第3項）。一般媒介には上限規定がありません。", "caution": ""}], "summary": {"head": ["一般媒介に「ない」規制", "専任・専属専任には「ある」規制"], "rows": [["レインズ登録義務", "あり（7日・5日以内）"], ["定期業務報告義務", "あり（2週・1週に1回）"], ["有効期間上限", "あり（3か月）"], ["自己発見取引禁止", "専属専任のみ"]]}}},
  // クーリングオフ・8種制限（l_cooling）追加
  {id:10560,unit:'l_cooling',level:1,field:'law',text:'クーリングオフができない場合として正しいものはどれか。',opts:['宅建業者の案内所で申込みをした場合（届出済みの案内所）','事務所以外の場所で申込みをした場合','告知から7日目に行使した場合','電話で申込みをした場合'],ans:0,exp:'宅建業者が届出をした案内所・展示会場等（事務所等）で申込みをした場合はクーリングオフができません（宅建業法37条の2）。告知から8日以内に書面で行使する必要があります。',"kaisetsu":{"topic": "クーリングオフ：告知日から8日以内・書面で・事務所では不可・全額返還", "basis": {"text": "クーリングオフは告知を受けた日から8日以内に書面で行います（宅建業法37条の2）。事務所・モデルルーム等での申込みはクーリングオフ不可。解除後業者は全額返還（費用控除不可）。", "example": ""}, "reason": {"text": "宅建業者の案内所（専任の宅建士を設置した届出済みの案内所）は「事務所等」に該当し、そこでの申込みはクーリングオフができません（宅建業法施行規則16条の5第2号・50条2項）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">クーリングオフのポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">告知日から8日以内</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">方法</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面（発信主義）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所での申込み</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">クーリングオフ不可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除後</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全額返還（費用控除不可）</text></svg>", "choices": [{"label": "事務所以外の場所で申込みをした場合", "reason": "事務所以外でも「事務所等」に該当する場所（専任宅建士置いた届出済み案内所等）での申込みはクーリングオフできません（施行規則16条の5）。「事務所以外は常にできる」は誤りです。", "caution": ""}, {"label": "告知から7日目に行使した場合", "reason": "告知から8日以内であれば行使できます（宅建業法37条の2第1項）。7日目はまだ行使可能です。", "caution": "8日以内＝8日目まで行使可能（宅建業法37条の2第1項）。"}, {"label": "電話で申込みをした場合", "reason": "申込み方法（電話・対面等）はクーリングオフの可否に直接関係しません。申込みの場所・告知の有無が重要です。", "caution": ""}], "summary": {"head": ["クーリングオフができない「事務所等」", "根拠"], "rows": [["宅建業者の事務所", "施行規則16条の5第1号"], ["専任宅建士設置の届出済み案内所", "施行規則16条の5第2号"], ["買主が自ら申し出た自宅・勤務先", "施行規則16条の5第3号"]]}}},
  {id:10561,unit:'l_cooling',level:2,field:'law',text:'手付金等の保全措置が不要な場合として正しいものはどれか（未完成物件）。',opts:['手付金等が代金の5%以下かつ1000万円以下','手付金等が代金の10%以下かつ1000万円以下','手付金等が500万円以下','保全措置は常に必要'],ans:0,exp:'未完成物件の場合、手付金等が代金の5%以下かつ1000万円以下であれば保全措置は不要です（宅建業法41条1項）。完成物件は10%以下かつ1000万円以下が要件です。',"kaisetsu":{"topic": "クーリングオフ：告知日から8日以内・書面で・事務所では不可・全額返還", "basis": {"text": "クーリングオフは告知を受けた日から8日以内に書面で行います（宅建業法37条の2）。事務所・モデルルーム等での申込みはクーリングオフ不可。解除後業者は全額返還（費用控除不可）。", "example": ""}, "reason": {"text": "未完成物件の手付金等の保全措置が不要な（受領できる）上限は「代金の5%以下かつ1000万円以下」です（宅建業法41条1項）。この両方を満たす場合は保全措置なしに手付金等を受領できます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">クーリングオフのポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">告知日から8日以内</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">方法</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面（発信主義）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所での申込み</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">クーリングオフ不可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除後</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全額返還（費用控除不可）</text></svg>", "choices": [{"label": "手付金等が代金の10%以下かつ1000万円以下", "reason": "10%以下かつ1000万円以下は完成物件の保全措置不要基準です（宅建業法41条の2第1項）。未完成物件は5%以下かつ1000万円以下です（同法41条1項）。", "caution": "未完成物件：5%以下かつ1000万円以下。完成物件：10%以下かつ1000万円以下。"}, {"label": "手付金等が500万円以下", "reason": "500万円という基準はありません（宅建業法41条1項）。5%以下かつ1000万円以下が基準です。", "caution": ""}, {"label": "保全措置は常に必要", "reason": "5%以下かつ1000万円以下の場合は保全措置なしに受領できます（宅建業法41条1項）。「常に必要」は誤りです。", "caution": ""}], "summary": {"head": ["手付金等の保全措置不要の基準", "条件"], "rows": [["未完成物件（宅建業法41条1項）", "5%以下かつ1000万円以下"], ["完成物件（宅建業法41条の2第1項）", "10%以下かつ1000万円以下"], ["超えた場合", "受領前に保全措置を講じる必要あり"]]}}},
  // 重要事項説明（l_jusetsu）追加
  {id:10562,unit:'l_jusetsu',level:1,field:'law',text:'重要事項説明を受ける権利を持つ者として正しいものはどれか。',opts:['売主のみ','買主・借主（取引の相手方）','売主と買主の双方','仲介業者'],ans:1,exp:'重要事項説明は取引の相手方（買主・借主）に行います（宅建業法35条1項）。相手方が宅建業者の場合も書面交付は必要ですが説明は省略できます。',"kaisetsu":{"topic": "重要事項説明：宅建士が説明・売主への交付は不要・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主への交付義務はありません。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能です。", "example": ""}, "reason": {"text": "重要事項説明は買主・借主（取引の相手方）を保護するために行うものです（宅建業法35条1項）。売主・貸主側には原則として説明する義務はありません。ただし交換の場合は双方が相手方になります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "売主のみ", "reason": "重要事項説明を受けるのは買主・借主（取引の相手方）です（宅建業法35条1項）。売主ではありません。", "caution": "重要事項説明：買主・借主が相手方（宅建業法35条1項）。"}, {"label": "売主と買主の双方", "reason": "原則として買主（借主）に対して説明します（宅建業法35条1項）。売主・貸主には義務なし（交換は双方）。", "caution": ""}, {"label": "仲介業者", "reason": "仲介業者（媒介業者）は説明を行う側であり、説明を受ける相手方ではありません（宅建業法35条1項）。", "caution": ""}], "summary": {"head": ["重要事項説明の相手方", "内容"], "rows": [["売買", "買主（宅建業者間は説明省略可）"], ["賃貸借", "借主"], ["交換", "双方の当事者"], ["売主・貸主", "原則として説明不要"]]}}},
  {id:10563,unit:'l_jusetsu',level:2,field:'law',text:'重要事項説明書に記載が必要な法令上の制限の例として正しいものはどれか。',opts:['近隣の地価動向','都市計画法・建築基準法等の法令に基づく制限の概要','売主の確定申告状況','近隣住民の意見'],ans:1,exp:'重要事項説明書には都市計画法・建築基準法等の法令に基づく制限の概要を記載しなければなりません（宅建業法35条1項2号）。',"kaisetsu":{"topic": "重要事項説明：宅建士が説明・売主への交付は不要・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主への交付義務はありません。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能です。", "example": ""}, "reason": {"text": "35条書面の法令上の制限の記載事項は都市計画法・建築基準法等に基づく制限の概要です（宅建業法35条1項2号）。近隣の地価動向・売主の確定申告・近隣住民の意見は記載事項ではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "近隣の地価動向", "reason": "近隣の地価動向は重要事項説明の記載事項ではありません（宅建業法35条1項）。", "caution": ""}, {"label": "売主の確定申告状況", "reason": "売主の確定申告状況は重要事項説明の記載事項ではありません（宅建業法35条1項）。", "caution": ""}, {"label": "近隣住民の意見", "reason": "近隣住民の意見は重要事項説明の記載事項ではありません（宅建業法35条1項）。", "caution": ""}], "summary": {"head": ["35条書面の主な記載事項（宅建業法35条1項）", "内容"], "rows": [["1号", "登記された権利の種類・内容"], ["2号", "法令に基づく制限の概要"], ["3号", "私道負担の有無"], ["4号", "飲用水・ガス・電気の整備状況"], ["14号", "インスペクションの実施の有無・結果"]]}}},
  // 営業保証金・保証協会（l_hosho）追加
  {id:10564,unit:'l_hosho',level:1,field:'law',text:'営業保証金の供託先として正しいものはどれか。',opts:['都道府県の金庫','主たる事務所の最寄りの供託所（法務局）','宅建業協会','国土交通省'],ans:1,exp:'営業保証金は主たる事務所の最寄りの供託所（法務局）に供託します（宅建業法25条1項）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "営業保証金は主たる事務所の最寄りの供託所（法務局・地方法務局・支局等）に供託します（宅建業法25条1項）。宅建業協会や国土交通省に供託するのではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "都道府県の金庫", "reason": "都道府県の金庫は供託所ではありません（宅建業法25条1項）。", "caution": "営業保証金の供託先：最寄りの供託所（法務局等）。"}, {"label": "宅建業協会", "reason": "宅建業協会は供託所ではありません（宅建業法25条1項）。保証協会（宅建業協会とは別）への分担金納付と混同しないようにしましょう。", "caution": ""}, {"label": "国土交通省", "reason": "国土交通省は供託所ではありません（宅建業法25条1項）。", "caution": ""}], "summary": {"head": ["営業保証金", "保証協会の弁済業務保証金"], "rows": [["供託先・納付先", "最寄りの供託所（法務局等）", "保証協会"], ["額（主たる事務所）", "1000万円", "60万円（分担金）"], ["特徴", "業者が直接供託", "保証協会が一括管理"]]}}},
  {id:10565,unit:'l_hosho',level:2,field:'law',text:'弁済業務保証金分担金の額として正しいものはどれか（主たる事務所）。',opts:['100万円','60万円','30万円','1000万円'],ans:1,exp:'保証協会に加入する場合の弁済業務保証金分担金は主たる事務所が60万円、従たる事務所1か所につき30万円です（宅建業法64条の9）。営業保証金（主1000万円・従500万円）より大幅に低額です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "弁済業務保証金分担金は主たる事務所につき60万円です（宅建業法64条の9第1項1号）。従たる事務所は1か所あたり30万円です（同条1項2号）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "100万円", "reason": "主たる事務所の弁済業務保証金分担金は60万円です（宅建業法64条の9第1項1号）。100万円ではありません。", "caution": "弁済業務保証金分担金：主たる事務所60万円・従たる事務所30万円。"}, {"label": "30万円", "reason": "30万円は従たる事務所（1か所あたり）の分担金額です（宅建業法64条の9第1項2号）。主たる事務所は60万円です（同条1項1号）。", "caution": ""}, {"label": "1000万円", "reason": "1000万円は営業保証金（主たる事務所）の金額です（宅建業法施行令2条1項1号）。弁済業務保証金分担金は60万円です（宅建業法64条の9第1項1号）。", "caution": ""}], "summary": {"head": ["弁済業務保証金分担金（宅建業法64条の9）", "金額"], "rows": [["主たる事務所", "60万円"], ["従たる事務所（1か所）", "30万円"], ["事務所2か所（主＋従1）", "90万円"], ["事務所3か所（主＋従2）", "120万円"]]}}},
  // 監督処分（l_kantoku）追加
  {id:10566,unit:'l_kantoku',level:1,field:'law',text:'宅建業者に対する業務停止処分の期間の上限として正しいものはどれか。',opts:['3か月','6か月','1年','2年'],ans:2,exp:'宅建業者に対する業務停止処分の期間は1年以内です（宅建業法65条2項）。業務停止処分に違反した場合は免許取消処分の対象となります。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "宅建業者に対する業務停止処分の最長期間は1年です（宅建業法65条2項）。これを超える業務停止は認められません。宅建士に対する事務禁止処分も最長1年です（宅建業法68条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "3か月", "reason": "業務停止処分の最長期間は1年です（宅建業法65条2項）。3か月ではありません。", "caution": ""}, {"label": "6か月", "reason": "業務停止処分の最長期間は1年です（宅建業法65条2項）。6か月ではありません。", "caution": ""}, {"label": "2年", "reason": "業務停止処分の最長期間は1年です（宅建業法65条2項）。2年ではありません。", "caution": ""}], "summary": {"head": ["業務停止・事務禁止の最長期間", "内容"], "rows": [["業務停止処分（宅建業者）", "1年（宅建業法65条2項）"], ["事務禁止処分（宅建士）", "1年（宅建業法68条1項）"], ["違反", "業務停止違反→必要的免許取消（宅建業法66条1項9号）"]]}}},
  {id:10567,unit:'l_kantoku',level:2,field:'law',text:'宅建業者の免許が必ず取り消される（必要的取消し）事由として正しいものはどれか。',opts:['軽微な広告表示の誤り','不正の手段により免許を取得したことが判明した場合','業務報告の遅延','従業員の軽微な違反'],ans:1,exp:'不正の手段による免許取得が判明した場合は必要的取消し事由です（宅建業法66条1項8号）。知事・大臣に裁量の余地はなく必ず取り消されます。業務停止処分違反も必要的取消し事由に含まれます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "不正の手段により免許を取得したことが判明した場合は必要的免許取消し事由です（宅建業法66条1項1号）。必ず取り消されます。軽微な広告違反・業務報告遅延・従業員の軽微違反は必要的取消し事由ではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "軽微な広告表示の誤り", "reason": "軽微な広告違反は指示処分等の対象ですが（宅建業法65条1項）、必要的取消し事由ではありません（宅建業法66条1項）。", "caution": ""}, {"label": "業務報告の遅延", "reason": "業務報告遅延は行政処分の対象となりますが、必要的取消し事由ではありません（宅建業法66条1項）。", "caution": ""}, {"label": "従業員の軽微な違反", "reason": "従業員の軽微違反が必要的取消し事由になるとは規定されていません（宅建業法66条1項）。", "caution": ""}], "summary": {"head": ["必要的免許取消し事由（宅建業法66条1項）", "条文"], "rows": [["不正手段による免許取得", "1号"], ["役員・使用人が欠格事由に該当", "2号"], ["欠格事由に自ら該当", "3号"], ["業務停止処分違反", "9号"]]}}},
  // ===== 追加133問（9503〜9635）=====
  // 登録免許税（t_toroku）
  {id:10568,unit:'t_toroku',level:1,field:'tax',text:'登録免許税の課税主体として正しいものはどれか。',opts:['都道府県','市町村','国（国税）','固定資産評価委員会'],ans:2,exp:'登録免許税は国税です（登録免許税法1条）。登記・登録等を受ける者が納付します。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10569,unit:'t_toroku',level:1,field:'tax',text:'抵当権設定登記の登録免許税の課税標準として正しいものはどれか。',opts:['不動産の固定資産税評価額','債権金額（ローン金額）','不動産の売買価格','固定資産税評価額の2分の1'],ans:1,exp:'抵当権設定登記の課税標準は「債権金額」です（登録免許税法9条）。不動産の価額ではなく担保する債権の金額が基準となります。税率は原則0.4%です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10570,unit:'t_toroku',level:2,field:'tax',text:'所有権保存登記の登録免許税の税率として正しいものはどれか。',opts:['0.1%','0.4%','1.0%','2.0%'],ans:1,exp:'所有権保存登記の登録免許税率は原則0.4%です（登録免許税法別表1）。一定の住宅要件を満たす場合は軽減税率0.15%が適用されます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10571,unit:'t_toroku',level:2,field:'tax',text:'相続による所有権移転登記の税率として正しいものはどれか。',opts:['0.4%','1.0%','2.0%','0.1%'],ans:0,exp:'相続または法人合併による所有権移転登記の税率は0.4%です（登録免許税法別表1）。売買による移転（2.0%）より低く設定されています。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10572,unit:'t_toroku',level:3,field:'tax',text:'登録免許税の非課税となる場合として正しいものはどれか。',opts:['国または地方公共団体が登記権利者となる場合','個人が住宅を取得した場合','法人が事務所を取得した場合','外国人が不動産を取得した場合'],ans:0,exp:'国または地方公共団体が登記権利者となる不動産登記は登録免許税が非課税です（登録免許税法4条）。個人や法人の取得は原則課税対象です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  // 不動産取得税（t_shutoku）追加
  {id:10573,unit:'t_shutoku',level:1,field:'tax',text:'不動産取得税の標準税率として正しいものはどれか（住宅・土地の特例適用時）。',opts:['2%','3%','4%','5%'],ans:1,exp:'住宅および住宅用土地の不動産取得税の標準税率は特例により3%です（地方税法附則11条の2）。それ以外の不動産は4%が標準税率です。',"kaisetsu":{"topic": "不動産取得税：都道府県が課す地方税・相続は非課税・1回だけ課税", "basis": {"text": "不動産取得税は都道府県が課す地方税です（地方税法73条の2）。相続・法人の合併等による取得は非課税。一度の取得に一度だけ課税される（固定資産税と異なり毎年ではない）。標準税率は4%（住宅・土地は3%の軽減あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産取得税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税の頻度</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取得時に1回のみ</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">標準税率</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4%（住宅・土地は3%）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10574,unit:'t_shutoku',level:1,field:'tax',text:'不動産取得税の納税方法として正しいものはどれか。',opts:['自分で申告して納付する（申告納付）','都道府県から送られてくる納税通知書で納付する（普通徴収）','不動産取得と同時に自動引き落とし','登記の際に法務局で納付'],ans:1,exp:'不動産取得税は都道府県が賦課決定し納税通知書を送付する普通徴収方式です（地方税法73条の17）。自分で申告する必要はありません。',"kaisetsu":{"topic": "不動産取得税：都道府県が課す地方税・相続は非課税・1回だけ課税", "basis": {"text": "不動産取得税は都道府県が課す地方税です（地方税法73条の2）。相続・法人の合併等による取得は非課税。一度の取得に一度だけ課税される（固定資産税と異なり毎年ではない）。標準税率は4%（住宅・土地は3%の軽減あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産取得税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税の頻度</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取得時に1回のみ</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">標準税率</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4%（住宅・土地は3%）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10575,unit:'t_shutoku',level:2,field:'tax',text:'新築住宅の不動産取得税の課税標準の特例として正しいものはどれか（一般住宅）。',opts:['固定資産税評価額から500万円控除','固定資産税評価額から1200万円控除','固定資産税評価額の2分の1','固定資産税評価額から3000万円控除'],ans:1,exp:'新築住宅（一般）の不動産取得税は固定資産税評価額から1200万円を控除した額が課税標準となります（地方税法73条の14第1項）。認定長期優良住宅は1300万円控除です。',"kaisetsu":{"topic": "不動産取得税：都道府県が課す地方税・相続は非課税・1回だけ課税", "basis": {"text": "不動産取得税は都道府県が課す地方税です（地方税法73条の2）。相続・法人の合併等による取得は非課税。一度の取得に一度だけ課税される（固定資産税と異なり毎年ではない）。標準税率は4%（住宅・土地は3%の軽減あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産取得税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税の頻度</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取得時に1回のみ</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">標準税率</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4%（住宅・土地は3%）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10576,unit:'t_shutoku',level:2,field:'tax',text:'不動産取得税が非課税となる取得として正しいものはどれか。',opts:['売買による取得','贈与による取得','相続による取得','交換による取得'],ans:2,exp:'相続による不動産取得は不動産取得税が非課税です（地方税法73条の7）。贈与・売買・交換・法人への現物出資等は課税対象です。',"kaisetsu":{"topic": "不動産取得税：都道府県が課す地方税・相続は非課税・1回だけ課税", "basis": {"text": "不動産取得税は都道府県が課す地方税です（地方税法73条の2）。相続・法人の合併等による取得は非課税。一度の取得に一度だけ課税される（固定資産税と異なり毎年ではない）。標準税率は4%（住宅・土地は3%の軽減あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産取得税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税の頻度</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取得時に1回のみ</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">標準税率</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4%（住宅・土地は3%）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10577,unit:'t_shutoku',level:3,field:'tax',text:'既存住宅（中古住宅）取得時の不動産取得税の特例として正しいものはどれか。',opts:['特例はなく評価額全額が課税標準','一定の要件（築年数・耐震基準等）を満たす場合は課税標準から最大1200万円を控除できる','中古住宅は一律非課税','床面積50㎡以上なら自動的に特例適用'],ans:1,exp:'中古住宅取得時も一定の要件（新耐震基準適合・自己居住用・床面積50㎡以上240㎡以下等）を満たせば課税標準から最大1200万円（昭和57年以前は築年数に応じた額）が控除されます（地方税法73条の14第2項）。',"kaisetsu":{"topic": "不動産取得税：都道府県が課す地方税・相続は非課税・1回だけ課税", "basis": {"text": "不動産取得税は都道府県が課す地方税です（地方税法73条の2）。相続・法人の合併等による取得は非課税。一度の取得に一度だけ課税される（固定資産税と異なり毎年ではない）。標準税率は4%（住宅・土地は3%の軽減あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産取得税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税の頻度</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取得時に1回のみ</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">標準税率</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4%（住宅・土地は3%）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  // 固定資産税（t_kotei）追加
  {id:10578,unit:'t_kotei',level:1,field:'tax',text:'固定資産税の賦課期日として正しいものはどれか。',opts:['毎年4月1日','毎年1月1日','毎年7月1日','登記日'],ans:1,exp:'固定資産税の賦課期日は毎年1月1日です（地方税法359条）。1月1日時点の所有者に課税されます。年の途中で売却しても1月1日の所有者が納税義務者です。',"kaisetsu":{"topic": "固定資産税：市町村が課す地方税・賦課期日は1月1日・評価替えは3年ごと", "basis": {"text": "固定資産税は市町村（東京23区は都）が課す地方税です（地方税法343条）。賦課期日は毎年1月1日。評価替えは3年ごと（基準年度）。住宅用地の特例：200㎡以下は課税標準1/6、超過部分は1/3。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">固定資産税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市町村（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賦課期日</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">評価替え</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年ごと</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅用地（200㎡以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税標準1/6</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10579,unit:'t_kotei',level:1,field:'tax',text:'固定資産税の評価替えの周期として正しいものはどれか。',opts:['毎年','2年ごと','3年ごと','5年ごと'],ans:2,exp:'固定資産税の評価替えは3年ごとに行われます（地方税法409条）。基準年度に評価替えを行い、次の基準年度まで原則として据え置かれます。',"kaisetsu":{"topic": "固定資産税：市町村が課す地方税・賦課期日は1月1日・評価替えは3年ごと", "basis": {"text": "固定資産税は市町村（東京23区は都）が課す地方税です（地方税法343条）。賦課期日は毎年1月1日。評価替えは3年ごと（基準年度）。住宅用地の特例：200㎡以下は課税標準1/6、超過部分は1/3。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">固定資産税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市町村（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賦課期日</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">評価替え</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年ごと</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅用地（200㎡以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税標準1/6</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10580,unit:'t_kotei',level:2,field:'tax',text:'新築住宅に対する固定資産税の減額特例として正しいものはどれか（一般住宅）。',opts:['永続的に2分の1に減額','新築後3年間、税額が2分の1に減額（3階建以上の中高層耐火住宅は5年間）','新築後5年間、全額免除','10年間、4分の1に減額'],ans:1,exp:'新築住宅（120㎡相当部分）の固定資産税は新築後3年間（3階建以上の中高層耐火・準耐火住宅は5年間）、税額が2分の1に減額されます（地方税法附則15条の6）。',"kaisetsu":{"topic": "固定資産税：市町村が課す地方税・賦課期日は1月1日・評価替えは3年ごと", "basis": {"text": "固定資産税は市町村（東京23区は都）が課す地方税です（地方税法343条）。賦課期日は毎年1月1日。評価替えは3年ごと（基準年度）。住宅用地の特例：200㎡以下は課税標準1/6、超過部分は1/3。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">固定資産税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市町村（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賦課期日</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">評価替え</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年ごと</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅用地（200㎡以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税標準1/6</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10581,unit:'t_kotei',level:2,field:'tax',text:'固定資産税における住宅用地の課税標準の特例で「一般住宅用地」とは何か。',opts:['200㎡以下の部分','200㎡を超える部分（小規模住宅用地以外の住宅用地）','全ての住宅用地','非住宅用地'],ans:1,exp:'小規模住宅用地（200㎡以下）の課税標準は評価額の1/6、200㎡を超える一般住宅用地部分は評価額の1/3に軽減されます（地方税法349条の3の2）。',"kaisetsu":{"topic": "固定資産税：市町村が課す地方税・賦課期日は1月1日・評価替えは3年ごと", "basis": {"text": "固定資産税は市町村（東京23区は都）が課す地方税です（地方税法343条）。賦課期日は毎年1月1日。評価替えは3年ごと（基準年度）。住宅用地の特例：200㎡以下は課税標準1/6、超過部分は1/3。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">固定資産税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市町村（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賦課期日</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">評価替え</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年ごと</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅用地（200㎡以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税標準1/6</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10582,unit:'t_kotei',level:3,field:'tax',text:'固定資産税の免税点として正しいものはどれか（土地）。',opts:['課税標準額10万円未満','課税標準額30万円未満','課税標準額50万円未満','免税点の制度はない'],ans:1,exp:'土地の固定資産税は課税標準額が30万円未満の場合は課税されません（地方税法351条）。家屋は20万円未満、償却資産は150万円未満が免税点です。',"kaisetsu":{"topic": "固定資産税：市町村が課す地方税・賦課期日は1月1日・評価替えは3年ごと", "basis": {"text": "固定資産税は市町村（東京23区は都）が課す地方税です（地方税法343条）。賦課期日は毎年1月1日。評価替えは3年ごと（基準年度）。住宅用地の特例：200㎡以下は課税標準1/6、超過部分は1/3。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">固定資産税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市町村（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賦課期日</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">評価替え</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年ごと</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅用地（200㎡以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税標準1/6</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  // 譲渡所得（t_joto）追加
  {id:10583,unit:'t_joto',level:1,field:'tax',text:'不動産の譲渡所得の計算式として正しいものはどれか。',opts:['譲渡収入金額－取得費','譲渡収入金額－（取得費＋譲渡費用）','譲渡収入金額－固定資産税評価額','売買代金のみ'],ans:1,exp:'譲渡所得＝譲渡収入金額－（取得費＋譲渡費用）です（所得税法33条）。取得費が不明な場合は譲渡収入金額の5%を取得費とみなすことができます。',"kaisetsu":{"topic": "譲渡所得：分離課税・長期は20%・3,000万円控除は3年に1回", "basis": {"text": "土地・建物の譲渡所得は分離課税（申告分離課税）。長期（5年超）の税率は合計20%（所得税15%+住民税5%）。短期（5年以下）は39%（所得税30%+住民税9%）。3,000万円特別控除は前年・前々年に適用があれば使えません（3年に1回）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">譲渡所得のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税方式</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">分離課税</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">長期（5年超）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計20%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">短期（5年以下）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計39%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3,000万円控除</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年に1回の制限</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10584,unit:'t_joto',level:1,field:'tax',text:'居住用財産の3000万円特別控除の適用を受けられない場合として正しいものはどれか。',opts:['居住しなくなってから2年後に売却した場合','配偶者に売却した場合','売却した年の前年・前々年に同控除を受けていない場合','住宅ローンが残っている場合'],ans:1,exp:'居住用財産の3000万円特別控除は配偶者・直系血族・生計を共にする親族等への売却には適用されません（租税特別措置法35条2項）。関連当事者間取引への適用を排除しています。',"kaisetsu":{"topic": "譲渡所得：分離課税・長期は20%・3,000万円控除は3年に1回", "basis": {"text": "土地・建物の譲渡所得は分離課税（申告分離課税）。長期（5年超）の税率は合計20%（所得税15%+住民税5%）。短期（5年以下）は39%（所得税30%+住民税9%）。3,000万円特別控除は前年・前々年に適用があれば使えません（3年に1回）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">譲渡所得のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税方式</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">分離課税</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">長期（5年超）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計20%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">短期（5年以下）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計39%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3,000万円控除</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年に1回の制限</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10585,unit:'t_joto',level:2,field:'tax',text:'居住用財産を10年超保有して売却した場合の軽減税率（6000万円以下部分）として正しいものはどれか。',opts:['合計10%（所得税6%・住民税4%）','合計14%（所得税10%・住民税4%）','合計20%（所得税15%・住民税5%）','合計39%（所得税30%・住民税9%）'],ans:1,exp:'10年超保有の居住用財産の譲渡で6000万円以下の部分は軽減税率として合計14%（所得税10%・住民税4%）が適用されます（租税特別措置法31条の3）。6000万円超の部分は通常の長期譲渡所得税率20%です。',"kaisetsu":{"topic": "譲渡所得：分離課税・長期は20%・3,000万円控除は3年に1回", "basis": {"text": "土地・建物の譲渡所得は分離課税（申告分離課税）。長期（5年超）の税率は合計20%（所得税15%+住民税5%）。短期（5年以下）は39%（所得税30%+住民税9%）。3,000万円特別控除は前年・前々年に適用があれば使えません（3年に1回）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">譲渡所得のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税方式</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">分離課税</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">長期（5年超）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計20%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">短期（5年以下）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計39%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3,000万円控除</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年に1回の制限</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10586,unit:'t_joto',level:2,field:'tax',text:'収用等による譲渡の特別控除として認められる金額として正しいものはどれか。',opts:['1000万円','3000万円','5000万円','控除なし'],ans:2,exp:'公共事業等による収用の場合は譲渡所得から5000万円を特別控除できます（租税特別措置法33条の4）。これは3000万円特別控除と重複適用はできません。',"kaisetsu":{"topic": "譲渡所得：分離課税・長期は20%・3,000万円控除は3年に1回", "basis": {"text": "土地・建物の譲渡所得は分離課税（申告分離課税）。長期（5年超）の税率は合計20%（所得税15%+住民税5%）。短期（5年以下）は39%（所得税30%+住民税9%）。3,000万円特別控除は前年・前々年に適用があれば使えません（3年に1回）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">譲渡所得のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税方式</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">分離課税</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">長期（5年超）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計20%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">短期（5年以下）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計39%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3,000万円控除</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年に1回の制限</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10587,unit:'t_joto',level:3,field:'tax',text:'買換え特例（特定居住用財産の買換え）の適用要件として正しいものはどれか。',opts:['売却価格の制限はない','譲渡資産の売却価格が1億円以下であること','買換え資産の床面積50㎡未満でも適用可','所有期間5年超あれば適用可'],ans:1,exp:'特定居住用財産の買換え特例は譲渡資産の売却価格が1億円以下、所有期間10年超かつ居住期間10年以上、買換え資産の床面積50㎡以上等の要件があります（租税特別措置法36条の2）。',"kaisetsu":{"topic": "譲渡所得：分離課税・長期は20%・3,000万円控除は3年に1回", "basis": {"text": "土地・建物の譲渡所得は分離課税（申告分離課税）。長期（5年超）の税率は合計20%（所得税15%+住民税5%）。短期（5年以下）は39%（所得税30%+住民税9%）。3,000万円特別控除は前年・前々年に適用があれば使えません（3年に1回）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">譲渡所得のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税方式</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">分離課税</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">長期（5年超）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計20%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">短期（5年以下）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計39%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3,000万円控除</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年に1回の制限</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  // 統計・土地・建物（t_tokei）追加
  {id:10588,unit:'t_tokei',level:1,field:'tax',text:'扇状地の特徴として正しいものはどれか。',opts:['海岸沿いに形成される平坦地','山地から平野部へ出る河川が土砂を堆積して形成される地形','低湿で洪水リスクが高い','都市の中心部に多い'],ans:1,exp:'扇状地は山地と平野の境界付近で河川が急勾配から緩勾配になる地点で土砂を扇形に堆積して形成されます。水はけがよく果樹園等に利用されますが、土石流・洪水のリスクがあります。',"kaisetsu":{"topic": "不動産統計・建物・土地の知識", "basis": {"text": "住宅着工戸数は近年80万戸前後で推移。首都圏マンション価格は上昇傾向。J-REITの運用資産は拡大傾向。中古住宅流通は活発化傾向。フラット35は全期間固定・各金融機関が金利設定・15年以上35年以下。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産統計・フラット35のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">近年の傾向</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅着工戸数</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">80万戸前後</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">首都圏マンション価格</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">上昇傾向</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">J-REIT</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">拡大傾向</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">フラット35の金利</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全期間固定・各金融機関が設定</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10589,unit:'t_tokei',level:2,field:'tax',text:'液状化現象が起きやすい地盤として正しいものはどれか。',opts:['洪積台地の砂礫層','埋立地・旧河道・砂丘の砂質地盤','岩盤上の住宅地','丘陵地の粘土層'],ans:1,exp:'液状化は地震時に砂質地盤が振動で液体状になる現象です。埋立地・旧河道・砂丘など水分を多く含む砂質地盤で発生しやすく、建物の沈下・傾斜が起こります。',"kaisetsu":{"topic": "不動産統計・建物・土地の知識", "basis": {"text": "住宅着工戸数は近年80万戸前後で推移。首都圏マンション価格は上昇傾向。J-REITの運用資産は拡大傾向。中古住宅流通は活発化傾向。フラット35は全期間固定・各金融機関が金利設定・15年以上35年以下。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産統計・フラット35のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">近年の傾向</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅着工戸数</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">80万戸前後</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">首都圏マンション価格</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">上昇傾向</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">J-REIT</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">拡大傾向</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">フラット35の金利</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全期間固定・各金融機関が設定</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10590,unit:'t_tokei',level:2,field:'tax',text:'鉄骨鉄筋コンクリート造（SRC造）の特徴として正しいものはどれか。',opts:['RC造より耐火性が低い','RC造と鉄骨造を組み合わせた構造で高層建築物に用いられる','木造より工期が短い','SRC造は2階建て住宅が主な用途'],ans:1,exp:'SRC造は鉄骨（Steel）の骨格にRC（鉄筋コンクリート）を組み合わせた構造で、高い強度・耐火性・耐震性を持ちます。超高層マンション・オフィスビル等の高層建築物に多く使われます。',"kaisetsu":{"topic": "不動産統計・建物・土地の知識", "basis": {"text": "住宅着工戸数は近年80万戸前後で推移。首都圏マンション価格は上昇傾向。J-REITの運用資産は拡大傾向。中古住宅流通は活発化傾向。フラット35は全期間固定・各金融機関が金利設定・15年以上35年以下。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産統計・フラット35のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">近年の傾向</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅着工戸数</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">80万戸前後</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">首都圏マンション価格</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">上昇傾向</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">J-REIT</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">拡大傾向</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">フラット35の金利</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全期間固定・各金融機関が設定</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10591,unit:'t_tokei',level:3,field:'tax',text:'地すべり地形の特徴として正しいものはどれか。',opts:['急傾斜で表面が固い','緩やかな斜面に馬蹄形の凹地や小丘が連なる地形で宅地として危険','砂地で水はけがよい','平坦で安定した地形'],ans:1,exp:'地すべり地形は緩傾斜の斜面に馬蹄形の凹地・小丘・湿地が連なる特徴があります。地下水位が高く不安定なため宅地として危険です。過去の地すべり跡は再活動の可能性があります。',"kaisetsu":{"topic": "不動産統計・建物・土地の知識", "basis": {"text": "住宅着工戸数は近年80万戸前後で推移。首都圏マンション価格は上昇傾向。J-REITの運用資産は拡大傾向。中古住宅流通は活発化傾向。フラット35は全期間固定・各金融機関が金利設定・15年以上35年以下。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産統計・フラット35のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">近年の傾向</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅着工戸数</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">80万戸前後</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">首都圏マンション価格</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">上昇傾向</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">J-REIT</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">拡大傾向</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">フラット35の金利</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全期間固定・各金融機関が設定</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  // 住宅金融支援機構（t_kinyu）追加
  {id:10592,unit:'t_kinyu',level:1,field:'tax',text:'フラット35の借入期間として正しいものはどれか。',opts:['最長20年','最長25年','最長35年','最長50年'],ans:2,exp:'フラット35の借入期間は15年以上35年以内（完済時年齢80歳以下）です。「35年」の名称はこの最長借入期間に由来します。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10593,unit:'t_kinyu',level:2,field:'tax',text:'フラット35の金利の決まり方として正しいものはどれか。',opts:['申込時に金利が決まり返済終了まで変わらない','毎年4月に金利が改定される','借入後5年ごとに見直し','市場金利に連動して毎月変わる'],ans:0,exp:'フラット35は申込時（正確には資金受取時）に金利が確定し、その後返済終了まで金利が変わらない全期間固定金利型ローンです。市場金利の上昇リスクを負わないのが最大の特徴です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10594,unit:'t_kinyu',level:3,field:'tax',text:'フラット35Sの優遇金利の適用条件として正しいものはどれか。',opts:['すべての住宅に自動適用','省エネルギー性・耐震性等で一定基準を満たす住宅に適用','新築住宅のみに適用','住宅ローン控除との併用不可'],ans:1,exp:'フラット35Sは省エネルギー性・耐久性・耐震性・バリアフリー性等で一定基準を満たす住宅について当初10年間（または5年間）金利を引き下げる制度です。住宅ローン控除との併用も可能です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  // 地価公示・不動産鑑定（t_chika）追加
  {id:10595,unit:'t_chika',level:1,field:'tax',text:'地価公示の標準地の鑑定評価を行う者として正しいものはどれか。',opts:['市町村職員','2名以上の不動産鑑定士','都道府県知事','国土交通大臣'],ans:1,exp:'地価公示の標準地は2名以上の不動産鑑定士が鑑定評価を行い、土地鑑定委員会が正常な価格を判定して公示します（地価公示法2条・6条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10596,unit:'t_chika',level:2,field:'tax',text:'不動産鑑定評価の取引事例比較法における「事情補正」の説明として正しいものはどれか。',opts:['時点の違いを補正すること','売急ぎ・買進み等の特殊な事情を補正すること','土地の形状の違いを補正すること','地域の違いを補正すること'],ans:1,exp:'取引事例比較法における事情補正とは、取引事例が売急ぎ・買進み・特殊な関係者間取引等の特殊事情を含む場合にそれを除いた正常な価格に補正することです。時点補正は別途行います。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10597,unit:'t_chika',level:3,field:'tax',text:'収益還元法における直接還元法と DCF 法の違いとして正しいものはどれか。',opts:['直接還元法は複数期間の収益をすべて割り引く','直接還元法は単年度の純収益を還元利回りで割り引く方法で、DCF法は複数期間の収益を割引率で現在価値に換算する','両者は全く同じ方法','DCF法は土地にしか使えない'],ans:1,exp:'直接還元法は1年間の純収益を還元利回りで除して価格を求める方法。DCF法（割引キャッシュフロー法）は保有期間中の各年の純収益と最終的な売却価格を割引率で現在価値に換算して合計する方法です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  // 都市計画法（k_toshi）追加
  {id:10598,unit:'k_toshi',level:1,field:'limit',text:'準都市計画区域を指定できる者として正しいものはどれか。',opts:['市町村長','都道府県知事','国土交通大臣','農業委員会'],ans:1,exp:'準都市計画区域は都道府県知事が指定します（都市計画法5条の2）。都市計画区域外で無秩序な開発のおそれがある地域を指定します。',"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域での1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は市街化調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "準都市計画区域の指定は都道府県知事が行います（都市計画法5条の2第1項）。市町村長・国交大臣・農業委員会ではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化する区域</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可基準</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "市町村長", "reason": "準都市計画区域の指定は都道府県知事が行います（都市計画法5条の2第1項）。市町村長ではありません。", "caution": "準都市計画区域の指定：都道府県知事（都市計画法5条の2第1項）。"}, {"label": "国土交通大臣", "reason": "都道府県知事が指定します（都市計画法5条の2第1項）。大臣ではありません。", "caution": ""}, {"label": "農業委員会", "reason": "農業委員会は農地法に関係する機関であり、準都市計画区域とは無関係です（都市計画法5条の2第1項）。", "caution": ""}], "summary": {"head": ["準都市計画区域（都市計画法5条の2）", "内容"], "rows": [["指定者", "都道府県知事"], ["場所", "都市計画区域外の乱開発防止が必要な地域"], ["開発許可", "3000㎡以上の開発行為に必要"]]}}},
  {id:10599,unit:'k_toshi',level:1,field:'limit',text:'市街化調整区域において原則として建築できる建築物として正しいものはどれか。',opts:['大型ショッピングモール','農業・林業・漁業を営む者の居住用建築物','分譲マンション','工場'],ans:1,exp:'市街化調整区域では農林漁業を営む者の居住用建築物（農家住宅等）は原則として建築できます（都市計画法34条1号）。それ以外の建築物は原則として開発許可・建築許可が必要です。',"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域での1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は市街化調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "市街化調整区域では原則として開発・建築が制限されますが、農業・林業・漁業を営む者の居住の用に供する建築物は建築できる場合があります（都市計画法34条1号）。大型施設・分譲マンション・工場は原則として認められません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化する区域</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可基準</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "大型ショッピングモール", "reason": "大型ショッピングモールは市街化調整区域では原則建築できません（都市計画法43条）。", "caution": "市街化調整区域で建築できるもの：農林漁業者の居住用建築物・公益施設等（都市計画法43条）。"}, {"label": "分譲マンション", "reason": "分譲マンションは市街化調整区域では原則建築できません（都市計画法43条）。", "caution": ""}, {"label": "工場", "reason": "工場は市街化調整区域では原則建築できません（都市計画法43条）。", "caution": ""}], "summary": {"head": ["市街化調整区域で建築できる建築物（都市計画法43条）", "内容"], "rows": [["農林漁業者の居住用建築物", "農家住宅等"], ["農林漁業用施設", "農業用倉庫等（許可不要）"], ["公益上必要な建築物", "変電所・ガス供給施設等（許可不要）"], ["原則不可", "一般住宅・商業施設・工場等（開発許可または建築許可が必要）"]]}}},
  {id:10600,unit:'k_toshi',level:2,field:'limit',text:'都市計画の決定手続きにおいて必ず公聴会を開催しなければならない場合として正しいものはどれか。',opts:['すべての都市計画決定','住民または利害関係人から公聴会開催の請求があった場合','市町村長が必要と判断した場合のみ','国土交通大臣が指示した場合のみ'],ans:1,exp:'都市計画の決定・変更にあたっては、住民または利害関係人から公聴会開催の請求があった場合は公聴会を開催しなければなりません（都市計画法16条）。',"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域での1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は市街化調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "都市計画決定の手続きにおいて、公聴会は住民または利害関係人から請求があった場合に開催が義務付けられます（都市計画法16条1項）。また必要に応じて行政が自主的に開催することもできます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化する区域</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可基準</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "すべての都市計画決定", "reason": "すべての都市計画決定で公聴会が義務ではありません（都市計画法16条1項）。請求があった場合等が義務です。", "caution": ""}, {"label": "市町村長が必要と判断した場合のみ", "reason": "住民または利害関係人から請求があった場合も義務です（都市計画法16条1項）。「市町村長の判断のみ」は誤りです。", "caution": "公聴会開催義務：住民等から請求があった場合（都市計画法16条1項）。"}, {"label": "国土交通大臣が指示した場合のみ", "reason": "大臣の指示の有無に関わらず、住民等の請求があれば開催義務があります（都市計画法16条1項）。", "caution": ""}], "summary": {"head": ["都市計画手続きの公聴会（都市計画法16条1項）", "内容"], "rows": [["開催義務", "住民または利害関係人から請求があった場合"], ["任意開催", "行政の判断で開催することも可"], ["縦覧", "都市計画原案の縦覧は義務（同法16条1項）"], ["意見書", "利害関係人は意見書を提出可（同法16条2項）"]]}}},
  {id:10601,unit:'k_toshi',level:2,field:'limit',text:'高度利用地区の目的として正しいものはどれか。',opts:['低層住宅専用地区として建物高さを制限する','用途地域内で土地の合理的高度利用を図るため建ぺい率・容積率・建築面積の最低限度等を定める地区','工業専用地区として工場のみ建築を許可する','緑地を確保するため建築を制限する'],ans:1,exp:'高度利用地区は用途地域内において市街地の環境を維持しつつ土地の合理的な高度利用を図るため、建ぺい率・容積率の最高・最低限度、建築面積の最低限度、壁面の位置を定める地区です（都市計画法9条19項）。',"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域での1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は市街化調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "高度利用地区は用途地域内において土地の合理的かつ高度な利用を図るため、建ぺい率・容積率の最高・最低限度、建築面積の最低限度、壁面の位置の制限等を定める地区です（都市計画法9条19項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化する区域</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可基準</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "低層住宅専用地区として建物高さを制限する", "reason": "建物の高さ制限は高度地区（都市計画法9条18項）の内容であり、高度利用地区ではありません。", "caution": "高度利用地区：容積率・建ぺい率・建築面積の最高・最低限度等（都市計画法9条19項）。"}, {"label": "工業専用地区として工場のみ建築を許可する", "reason": "工業専用地域は用途地域の一つ（都市計画法9条12項）であり、高度利用地区の内容ではありません。", "caution": ""}, {"label": "緑地を確保するため建築を制限する", "reason": "緑地の確保は緑地保全地区・特別緑地保全地区等の内容であり、高度利用地区ではありません。", "caution": ""}], "summary": {"head": ["高度利用地区と高度地区の違い", "内容"], "rows": [["高度利用地区（都市計画法9条19項）", "容積率・建ぺい率・建築面積の最高・最低限度等（土地の高度利用促進）"], ["高度地区（都市計画法9条18項）", "建物の高さの最高・最低限度（日影・景観・防火等）"]]}}},
  {id:10602,unit:'k_toshi',level:3,field:'limit',text:'特定用途制限地域の説明として正しいものはどれか。',opts:['用途地域内に定める地区','用途地域が定められていない土地の区域内で特定の用途の建築物の建築を制限する地域','市街化調整区域全体に適用される','容積率のみを制限する地域'],ans:1,exp:'特定用途制限地域は用途地域が定められていない土地の区域（市街化調整区域を除く）に定め、その良好な環境の形成・保持のため特定の建築物の建築を制限します（都市計画法9条15項）。',"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域での1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は市街化調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "特定用途制限地域は用途地域が定められていない土地の区域（非線引き都市計画区域・準都市計画区域等）において、特定の用途の建築物の建築を制限する地域です（都市計画法9条15項）。用途地域の補完的な規制です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化する区域</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可基準</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "用途地域内に定める地区", "reason": "特定用途制限地域は用途地域が定められていない区域に定めます（都市計画法9条15項）。「用途地域内」は誤りです。", "caution": "特定用途制限地域：用途地域が定められていない区域に定める（都市計画法9条15項）。"}, {"label": "市街化調整区域全体に適用される", "reason": "特定用途制限地域は市街化調整区域全体に自動的に適用されるものではありません（都市計画法9条15項）。", "caution": ""}, {"label": "容積率のみを制限する地域", "reason": "特定用途制限地域は特定の用途の建築物の建築を制限する地域であり（都市計画法9条15項）、容積率のみを規制するものではありません。", "caution": ""}], "summary": {"head": ["特定用途制限地域（都市計画法9条15項）", "内容"], "rows": [["設定場所", "用途地域が定められていない区域（非線引き・準都市計画区域等）"], ["内容", "特定の用途の建築物（大規模集客施設等）の建築を制限"], ["目的", "良好な環境形成・乱開発防止"]]}}},
  // 建築基準法（k_kenchiku）追加
  {id:10603,unit:'k_kenchiku',level:1,field:'limit',text:'建築基準法の「道路」の幅員要件として正しいものはどれか。',opts:['1メートル以上','2メートル以上','4メートル以上','6メートル以上'],ans:2,exp:'建築基準法上の「道路」は原則として幅員4メートル以上のものです（建築基準法42条1項）。4メートル未満でも特定行政庁が指定した「2項道路（みなし道路）」はセットバック義務を伴い道路とみなされます。',"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・道路斜線・用途制限", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。用途地域ごとに建築物の制限があります。", "example": ""}, "reason": {"text": "建築基準法上の「道路」は幅員4m以上のものを指します（建築基準法42条1項）。4m未満でも特例として道路扱いされる場合がありますが（2項道路）、その場合は中心線からのセットバックが必要です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">第1種低層</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">学校は建築可</text></svg>", "choices": [{"label": "1メートル以上", "reason": "建築基準法上の道路幅員要件は4m以上です（建築基準法42条1項）。1mではありません。", "caution": "建築基準法の道路：幅員4m以上（建築基準法42条1項）。"}, {"label": "2メートル以上", "reason": "2mは接道義務（建築基準法43条1項）の接道長さの要件であり、道路幅員の要件（4m）ではありません。", "caution": ""}, {"label": "6メートル以上", "reason": "建築基準法上の道路幅員要件は4m以上です（建築基準法42条1項）。6mではありません。", "caution": ""}], "summary": {"head": ["建築基準法の道路（建築基準法42条）", "内容"], "rows": [["原則（1項道路）", "幅員4m以上"], ["2項道路", "4m未満でも特例で道路扱い→セットバック義務"], ["接道義務", "幅員4m以上の道路に2m以上接すること（建築基準法43条1項）"]]}}},
  {id:10604,unit:'k_kenchiku',level:1,field:'limit',text:'第一種低層住居専用地域に建築できる建築物として正しいものはどれか。',opts:['中規模の事務所ビル','10階建てマンション','小規模な住宅・共同住宅・小学校など','大型スーパー'],ans:2,exp:'第一種低層住居専用地域は低層住宅の良好な住環境を守るための地域で、住宅・共同住宅・小学校・幼稚園・診療所等の建築が可能です。大学・病院・事務所・商業施設は建築できません。',"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・道路斜線・用途制限", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。用途地域ごとに建築物の制限があります。", "example": ""}, "reason": {"text": "第一種低層住居専用地域は低層住宅の良好な環境を守るための地域で、戸建住宅・小規模共同住宅・小学校・診療所等は建築できますが、中規模事務所・高層マンション・大型スーパーは建築できません（建築基準法別表第二）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">第1種低層</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">学校は建築可</text></svg>", "choices": [{"label": "中規模の事務所ビル", "reason": "第一種低層住居専用地域では中規模の事務所ビルは建築できません（建築基準法別表第二）。", "caution": "第一種低層住居専用地域：低層住宅中心・小学校・診療所等は可（建築基準法別表第二）。"}, {"label": "10階建てマンション", "reason": "第一種低層住居専用地域には絶対高さ制限（10m・12m）があり、10階建てマンションは建築できません（建築基準法55条）。", "caution": ""}, {"label": "大型スーパー", "reason": "第一種低層住居専用地域では大型スーパーは建築できません（建築基準法別表第二）。", "caution": ""}], "summary": {"head": ["第一種低層住居専用地域で建築できるもの", "内容"], "rows": [["住宅・小規模共同住宅", "可"], ["小学校・中学校・幼稚園", "可"], ["診療所・保育所", "可"], ["絶対高さ制限", "10mまたは12m（建築基準法55条）"], ["不可", "事務所・店舗（一定規模超）・工場等"]]}}},
  {id:10605,unit:'k_kenchiku',level:2,field:'limit',text:'防火地域内の建築規制として正しいものはどれか。',opts:['全ての建築物を準耐火建築物にしなければならない','階数3以上または延べ面積100㎡超の建築物は耐火建築物としなければならない','木造建築物は一切禁止','高さ制限のみが適用される'],ans:1,exp:'防火地域内では①階数3以上②延べ面積が100㎡を超える建築物は耐火建築物としなければなりません（建築基準法61条）。それ以外（階数2以下かつ100㎡以下）は準耐火建築物で可とされます。',"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・道路斜線・用途制限", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。用途地域ごとに建築物の制限があります。", "example": ""}, "reason": {"text": "防火地域内では①階数が3以上または延べ面積100㎡超の建築物は耐火建築物、②それ以外（2階以下かつ100㎡以下）は準耐火建築物（または耐火建築物）としなければなりません（建築基準法61条）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">第1種低層</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">学校は建築可</text></svg>", "choices": [{"label": "全ての建築物を準耐火建築物にしなければならない", "reason": "3階以上または100㎡超は耐火建築物が必要です（建築基準法61条）。準耐火建築物では不足な場合があります。", "caution": "防火地域内：3階以上または100㎡超→耐火建築物（建築基準法61条）。"}, {"label": "木造建築物は一切禁止", "reason": "木造でも耐火建築物等にすれば建築できます（建築基準法61条）。木造を禁止する規定はありません。", "caution": ""}, {"label": "高さ制限のみが適用される", "reason": "防火地域内の規制は高さ制限ではなく耐火・準耐火建築物の義務です（建築基準法61条）。高さ制限のみではありません。", "caution": ""}], "summary": {"head": ["防火地域内の規制（建築基準法61条）", "必要な建築物の種類"], "rows": [["3階以上または延べ面積100㎡超", "耐火建築物"], ["2階以下かつ延べ面積100㎡以下", "準耐火建築物（耐火建築物も可）"]]}}},
  {id:10606,unit:'k_kenchiku',level:2,field:'limit',text:'建ぺい率が緩和（10%加算）される場合として正しいものはどれか。',opts:['準防火地域内の耐火建築物','防火地域内の耐火建築物または角地','第一種住居地域に建築する場合','容積率が高い地域'],ans:1,exp:'建ぺい率は防火地域内の耐火建築物（10%加算）・特定行政庁が指定する角地（10%加算）の場合に緩和されます（建築基準法53条3項）。両方に該当すれば20%加算となります。',"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・道路斜線・用途制限", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。用途地域ごとに建築物の制限があります。", "example": ""}, "reason": {"text": "建ぺい率の10%加算（緩和）は①防火地域内の耐火建築物等（建築基準法53条3項1号）、②特定行政庁が指定した角地（同条3項2号）の2つが要件です。準防火地域の耐火建築物は10%加算の対象ではありません（準防火地域は防火地域とは異なります）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">第1種低層</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">学校は建築可</text></svg>", "choices": [{"label": "準防火地域内の耐火建築物", "reason": "建ぺい率の10%加算は防火地域内の耐火建築物等が対象です（建築基準法53条3項1号）。準防火地域は対象ではありません。", "caution": "建ぺい率10%加算：防火地域内の耐火建築物等・角地（建築基準法53条3項）。準防火地域は対象外。"}, {"label": "第一種住居地域に建築する場合", "reason": "第一種住居地域に建築すること自体は建ぺい率の加算要件ではありません（建築基準法53条3項）。", "caution": ""}, {"label": "容積率が高い地域", "reason": "容積率の高低は建ぺい率の加算要件ではありません（建築基準法53条3項）。", "caution": ""}], "summary": {"head": ["建ぺい率の10%加算（建築基準法53条3項）", "要件"], "rows": [["①防火地域内の耐火建築物等", "10%加算（53条3項1号）"], ["②特定行政庁指定の角地", "10%加算（53条3項2号）"], ["①②両方に該当", "20%加算"], ["準防火地域内の耐火建築物", "加算なし（防火地域と異なる）"]]}}},
  {id:10607,unit:'k_kenchiku',level:3,field:'limit',text:'総合設計制度の説明として正しいものはどれか。',opts:['容積率・建ぺい率を自由に設定できる制度','公開空地等を設けることを条件に容積率・高さ制限等の特例許可を受けられる制度','大規模建築物に義務付けられる設計基準','防火区画を設けることで建築面積を増やせる制度'],ans:1,exp:'総合設計制度は一定規模以上の敷地で公開空地・歩行者空間等を確保することを条件に、特定行政庁の許可により容積率・高さ制限の緩和を受けられる制度です（建築基準法59条の2）。',"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・道路斜線・用途制限", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。用途地域ごとに建築物の制限があります。", "example": ""}, "reason": {"text": "総合設計制度（建築基準法59条の2）は、公開空地等を確保することを条件として、容積率・斜線制限等の特例許可を受けられる制度です。特定行政庁の許可が必要です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">第1種低層</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">学校は建築可</text></svg>", "choices": [{"label": "容積率・建ぺい率を自由に設定できる制度", "reason": "総合設計制度は特定行政庁の許可が必要であり、自由に設定できる制度ではありません（建築基準法59条の2）。", "caution": "総合設計制度：公開空地確保→容積率・高さ制限等の緩和（建築基準法59条の2）。"}, {"label": "大規模建築物に義務付けられる設計基準", "reason": "大規模建築物に義務付けられるものではなく、任意の許可申請制度です（建築基準法59条の2）。", "caution": ""}, {"label": "防火区画を設けることで建築面積を増やせる制度", "reason": "防火区画の設置は防火上の規制であり（建築基準法36条）、総合設計制度とは異なります。", "caution": ""}], "summary": {"head": ["総合設計制度（建築基準法59条の2）", "内容"], "rows": [["要件", "公開空地等の確保"], ["緩和内容", "容積率・高さ制限（斜線制限）等の特例許可"], ["手続き", "特定行政庁の許可（建築審査会の同意も必要な場合あり）"], ["目的", "市街地環境の整備・大規模建築における公開空地確保"]]}}},
  // 農地法（k_nochi）追加
  {id:10608,unit:'k_nochi',level:1,field:'limit',text:'農地法2条における「農地」の定義として正しいものはどれか。',opts:['登記簿上の地目が田・畑のもの','現に耕作の目的に供されている土地','固定資産税が農地評価のもの','農業振興地域内の土地'],ans:1,exp:'農地法上の「農地」は現に耕作の目的に供されている土地です（農地法2条1項）。登記簿の地目ではなく現況で判断します（現況主義）。',"kaisetsu":{"topic": "農地法：3条は農業委員会・4条・5条は都道府県知事・市街化区域は届出のみ", "basis": {"text": "農地法3条（権利移動・農地→農地）の許可権者は農業委員会。4条（自己転用）・5条（転用目的の権利移動）は都道府県知事等。市街化区域内の農地転用（4・5条）は農業委員会への届出のみでOK。相続は許可不要・届出3か月以内。", "example": ""}, "reason": {"text": "農地法上の「農地」は現に耕作の目的に供されている土地です（農地法2条1項）。登記地目ではなく現況で判断します（現況主義）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">市街化区域</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">特例なし</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text></svg>", "choices": [{"label": "登記簿上の地目が田・畑のもの", "reason": "登記地目ではなく現況で判断します（農地法2条1項）。現況主義が原則です。", "caution": "農地の定義：現況主義（農地法2条1項）。登記地目ではない。"}, {"label": "固定資産税が農地評価のもの", "reason": "固定資産税の評価ではなく現況で判断します（農地法2条1項）。", "caution": ""}, {"label": "農業振興地域内の土地", "reason": "農業振興地域内かどうかではなく現況で判断します（農地法2条1項）。", "caution": ""}], "summary": {"head": ["農地の定義（農地法2条1項）", "内容"], "rows": [["定義", "現に耕作の目的に供されている土地"], ["判断基準", "現況主義"]]}}},
  {id:10609,unit:'k_nochi',level:1,field:'limit',text:'農地法3条の許可が不要な場合として正しいものはどれか。',opts:['農地を農地のまま売買する','農地を相続により取得する','農地の賃貸借契約を締結する','農地の使用貸借契約を締結する'],ans:1,exp:'農地を相続・遺産分割・包括遺贈・相続人への特定遺贈により取得する場合は農地法3条の許可は不要ですが、農業委員会への届出（3か月以内）が必要です（農地法3条の3）。',"kaisetsu":{"topic": "農地法：3条は農業委員会・4条・5条は都道府県知事・市街化区域は届出のみ", "basis": {"text": "農地法3条（権利移動・農地→農地）の許可権者は農業委員会。4条（自己転用）・5条（転用目的の権利移動）は都道府県知事等。市街化区域内の農地転用（4・5条）は農業委員会への届出のみでOK。相続は許可不要・届出3か月以内。", "example": ""}, "reason": {"text": "農地を相続により取得する場合は農地法3条の許可が不要です（農地法3条1項）。ただし取得後に農業委員会への届出が必要です（農地法3条の3第1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">市街化区域</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">特例なし</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text></svg>", "choices": [{"label": "農地を農地のまま売買する", "reason": "農地のまま売買する場合は農業委員会の許可が必要です（農地法3条1項）。", "caution": "相続による農地取得：農地法3条の許可不要（農地法3条1項）。"}, {"label": "農地の賃貸借契約を締結する", "reason": "農地の賃貸借契約は農業委員会の許可が必要です（農地法3条1項）。", "caution": ""}, {"label": "農地の使用貸借契約を締結する", "reason": "農地の使用貸借も農地法3条の許可が必要です（農地法3条1項）。", "caution": ""}], "summary": {"head": ["農地法3条の許可不要の例外", "内容"], "rows": [["相続・包括遺贈", "許可不要（届出が必要）"], ["強制執行・公売", "許可不要"]]}}},
  {id:10610,unit:'k_nochi',level:2,field:'limit',text:'市街化区域内の農地を自己転用（農地→宅地）する場合の手続きとして正しいものはどれか。',opts:['都道府県知事の許可が必要','農業委員会への届出で足りる','国土交通大臣の許可が必要','手続き不要'],ans:1,exp:'市街化区域内の農地を自己転用する場合（農地法4条）は、都道府県知事の許可は不要で農業委員会への届出のみで足ります（農地法4条1項8号）。市街化区域外は原則として知事の許可が必要です。',"kaisetsu":{"topic": "農地法：3条は農業委員会・4条・5条は都道府県知事・市街化区域は届出のみ", "basis": {"text": "農地法3条（権利移動・農地→農地）の許可権者は農業委員会。4条（自己転用）・5条（転用目的の権利移動）は都道府県知事等。市街化区域内の農地転用（4・5条）は農業委員会への届出のみでOK。相続は許可不要・届出3か月以内。", "example": ""}, "reason": {"text": "市街化区域内の農地を自己転用（農地法4条）する場合は農業委員会への届出で足り、都道府県知事の許可は不要です（農地法4条1項7号）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">市街化区域</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">特例なし</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text></svg>", "choices": [{"label": "都道府県知事の許可が必要", "reason": "市街化区域内の農地の自己転用は農業委員会への届出で足ります（農地法4条1項7号）。知事の許可は不要です。", "caution": "市街化区域内の農地の自己転用：農業委員会への届出（農地法4条1項7号）。"}, {"label": "国土交通大臣の許可が必要", "reason": "国交大臣の許可は不要です（農地法4条1項7号）。", "caution": ""}, {"label": "手続き不要", "reason": "農業委員会への届出が必要です（農地法4条1項7号）。「不要」は誤りです。", "caution": ""}], "summary": {"head": ["農地法4条（自己転用）", "手続き"], "rows": [["市街化区域内の農地", "農業委員会への届出（許可不要）"], ["市街化調整区域等", "都道府県知事の許可"]]}}},
  {id:10611,unit:'k_nochi',level:2,field:'limit',text:'採草放牧地に関する農地法の適用として正しいものはどれか。',opts:['農地と全く同じ規制が適用される','3条・4条・5条の規制が農地と同様に適用されるが一部異なる','農地法の規制は一切適用されない','5条のみ適用される'],ans:1,exp:'採草放牧地（草刈り・牧草収穫・家畜の放牧に供する土地）にも農地法が適用されます（農地法2条1項）が、農地と異なり4条（自己転用）は採草放牧地→農地以外への転用にのみ適用されるなど一部規制内容が異なります。',"kaisetsu":{"topic": "農地法：3条は農業委員会・4条・5条は都道府県知事・市街化区域は届出のみ", "basis": {"text": "農地法3条（権利移動・農地→農地）の許可権者は農業委員会。4条（自己転用）・5条（転用目的の権利移動）は都道府県知事等。市街化区域内の農地転用（4・5条）は農業委員会への届出のみでOK。相続は許可不要・届出3か月以内。", "example": ""}, "reason": {"text": "採草放牧地は農地ではありませんが農地法の規制対象です（農地法2条2項）。農地法3条・5条の規制が適用されますが、農地法4条は「農地」の転用規制であり採草放牧地には適用が異なります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">市街化区域</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">特例なし</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text></svg>", "choices": [{"label": "農地と全く同じ規制が適用される", "reason": "一部異なる点があります（農地法3条・4条・5条の適用が農地と同様ですが全く同じではありません）。", "caution": "採草放牧地：農地と同様の規制だが一部異なる（農地法2条2項）。"}, {"label": "農地法の規制は一切適用されない", "reason": "採草放牧地にも農地法の規制が適用されます（農地法2条2項）。", "caution": ""}, {"label": "5条のみ適用される", "reason": "3条・5条が主に適用されます（農地法2条2項）。「5条のみ」は誤りです。", "caution": ""}], "summary": {"head": ["採草放牧地と農地法", "内容"], "rows": [["農地法3条", "適用あり"], ["農地法4条", "農地のみが対象（採草放牧地には異なる適用）"], ["農地法5条", "適用あり"]]}}},
  {id:10612,unit:'k_nochi',level:3,field:'limit',text:'農地法5条の許可なく転用目的で農地を売買した場合の効力として正しいものはどれか。',opts:['売買は有効だが転用は禁止される','売買契約自体が無効となる（強行規定）','売買は有効で転用も可能','罰則はあるが売買は有効'],ans:1,exp:'農地法5条の許可を受けずに締結した農地の売買契約は無効です（農地法3条6項・5条3項）。強行規定であり、許可なき転用目的の売買は契約そのものの効力が否定されます。',"kaisetsu":{"topic": "農地法：3条は農業委員会・4条・5条は都道府県知事・市街化区域は届出のみ", "basis": {"text": "農地法3条（権利移動・農地→農地）の許可権者は農業委員会。4条（自己転用）・5条（転用目的の権利移動）は都道府県知事等。市街化区域内の農地転用（4・5条）は農業委員会への届出のみでOK。相続は許可不要・届出3か月以内。", "example": ""}, "reason": {"text": "農地法5条の許可なく転用目的で農地を売買した場合、その売買契約は強行規定違反として無効となります（農地法5条6項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">市街化区域</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">特例なし</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text></svg>", "choices": [{"label": "売買は有効だが転用は禁止される", "reason": "農地法5条の許可なき売買は契約自体が無効です（農地法5条6項）。「売買は有効」は誤りです。", "caution": "農地法5条の許可なき転用目的売買：契約無効（農地法5条6項）。"}, {"label": "売買は有効で転用も可能", "reason": "農地法5条の許可なき売買は無効です（農地法5条6項）。", "caution": ""}, {"label": "罰則はあるが売買は有効", "reason": "農地法5条の許可なき売買は無効です（農地法5条6項）。罰則もありますが、契約も無効です。", "caution": ""}], "summary": {"head": ["農地法違反の売買の効力", "内容"], "rows": [["農地法3条・4条・5条の許可なき売買", "無効（農地法3条6項・4条7項・5条6項）"], ["強行規定", "当事者の合意があっても無効"]]}}},
  // 盛土規制法（k_mori）追加
  {id:10613,unit:'k_mori',level:1,field:'limit',text:'宅地造成工事規制区域内で工事を行う際の届出・許可について正しいものはどれか。',opts:['工事完了後に届け出ればよい','一定規模以上の工事は工事着手前に都道府県知事の許可が必要','工事の規模にかかわらず届出のみで足りる','許可は不要で完了検査のみ必要'],ans:1,exp:'宅地造成工事規制区域内で一定規模以上（高さ2m超の盛土等）の宅地造成工事を行う場合は、工事着手前に都道府県知事の許可を受けなければなりません（盛土規制法12条1項）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "宅地造成工事規制区域内での一定規模以上の工事は工事着手前に都道府県知事の許可が必要です（宅地造成及び特定盛土等規制法12条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "工事完了後に届け出ればよい", "reason": "工事着手前の許可が必要です（宅地造成及び特定盛土等規制法12条1項）。", "caution": "宅地造成工事規制区域内の許可：工事着手前（宅地造成及び特定盛土等規制法12条1項）。"}, {"label": "工事の規模にかかわらず届出のみで足りる", "reason": "一定規模以上の工事は許可が必要です（宅地造成及び特定盛土等規制法12条1項）。", "caution": ""}, {"label": "許可は不要で完了検査のみ必要", "reason": "工事着手前の許可が必要です（宅地造成及び特定盛土等規制法12条1項）。", "caution": ""}], "summary": {"head": ["宅地造成工事の許可（宅地造成及び特定盛土等規制法12条）", "内容"], "rows": [["申請時期", "工事着手前"], ["申請先", "都道府県知事（または指定都市等の長）"]]}}},
  {id:10614,unit:'k_mori',level:2,field:'limit',text:'盛土規制法における「特定盛土等」の定義として最も正しいものはどれか。',opts:['市街地内の盛土すべて','宅地または農地等において行う盛土等であって、盛土等をする土地の地形・地質等からみて、崩落等により人家等に危害を生ずるおそれが大きいもの','高さ1m超の盛土すべて','農地での盛土'],ans:1,exp:'特定盛土等は宅地・農地等で行う盛土等のうち、地形・地質等から崩落等により人家等に危害を及ぼすおそれが大きいものとして政令で定めるものを指します（盛土規制法2条3号）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "特定盛土等とは宅地または農地等において行う盛土等で、当該土地の地形・地質等の条件からみて盛土崩落が周辺に被害を及ぼすおそれが大きいものです（宅地造成及び特定盛土等規制法2条4号）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "市街地内の盛土すべて", "reason": "市街地内の盛土すべてが特定盛土等ではありません（宅地造成及び特定盛土等規制法2条4号）。", "caution": "特定盛土等：盛土崩落が周辺に被害を及ぼすおそれが大きいもの（宅地造成及び特定盛土等規制法2条4号）。"}, {"label": "高さ1m超の盛土すべて", "reason": "高さ1m超の盛土すべてではなく、被害のおそれが大きいものが特定盛土等です（宅地造成及び特定盛土等規制法2条4号）。", "caution": ""}, {"label": "農地での盛土", "reason": "農地での盛土が全て特定盛土等ではありません（宅地造成及び特定盛土等規制法2条4号）。", "caution": ""}], "summary": {"head": ["特定盛土等の定義（宅地造成及び特定盛土等規制法2条4号）", "内容"], "rows": [["条件", "地形・地質等からみて崩落が周辺に被害を及ぼすおそれが大きいもの"]]}}},
  {id:10615,unit:'k_mori',level:3,field:'limit',text:'盛土規制法による宅地造成工事の技術基準として定められている事項として正しいものはどれか。',opts:['工事の請負代金の上限','擁壁の設置・排水施設の設置・切土・盛土の安全性に関する基準','工事期間の上限','工事業者の資格要件'],ans:1,exp:'盛土規制法は擁壁の構造・設置基準、排水施設の設置、切土・盛土の勾配・高さに関する安全基準等を技術的基準として政令で定めています（盛土規制法13条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "盛土規制法による宅地造成工事の技術基準には擁壁の設置・排水施設の設置・切土・盛土の安全性に関する基準が含まれます（宅地造成及び特定盛土等規制法施行令）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "工事の請負代金の上限", "reason": "請負代金の上限は技術基準ではありません（施行令）。", "caution": "宅地造成工事の技術基準：擁壁の設置・排水施設・切土盛土の安全性等（施行令）。"}, {"label": "工事期間の上限", "reason": "工事期間の上限は技術基準ではありません（施行令）。", "caution": ""}, {"label": "工事業者の資格要件", "reason": "工事業者の資格要件は技術基準ではありません（施行令）。", "caution": ""}], "summary": {"head": ["宅地造成工事の技術基準（施行令）", "内容"], "rows": [["擁壁", "崖の崩壊防止のための擁壁設置"], ["排水施設", "雨水等の適切な排水"], ["切土・盛土の安定", "安全基準"]]}}},
  // 国土利用計画法（k_kokudo）追加
  {id:10616,unit:'k_kokudo',level:1,field:'limit',text:'国土利用計画法の「土地売買等の契約」に含まれないものはどれか。',opts:['売買契約','交換契約','贈与契約','地上権・賃借権の設定（対価あり）'],ans:2,exp:'贈与契約は無償の取得であるため国土利用計画法の届出対象となる「土地売買等の契約」に含まれません（国土利用計画法14条）。有償の売買・交換・地上権設定等が対象です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "国土利用計画法の「土地売買等の契約」は売買・交換・対価ある地上権・賃借権の設定等が対象です（国土利用計画法14条1項）。贈与は対価がないため対象外です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "売買契約", "reason": "売買契約は「土地売買等の契約」に含まれます（国土利用計画法14条1項）。", "caution": "贈与：対価なし→土地売買等の契約に含まれない（国土利用計画法14条1項）。"}, {"label": "交換契約", "reason": "交換契約は「土地売買等の契約」に含まれます（国土利用計画法14条1項）。", "caution": ""}, {"label": "地上権・賃借権の設定（対価あり）", "reason": "対価のある地上権・賃借権の設定は「土地売買等の契約」に含まれます（国土利用計画法14条1項）。", "caution": ""}], "summary": {"head": ["土地売買等の契約（国土利用計画法14条1項）", "含まれるか"], "rows": [["売買・交換・対価ある地上権等の設定", "含まれる"], ["贈与・相続", "含まれない"]]}}},
  {id:10617,unit:'k_kokudo',level:2,field:'limit',text:'国土利用計画法で届出が必要な都市計画区域外の面積要件として正しいものはどれか。',opts:['3000㎡以上','5000㎡以上','10000㎡以上','20000㎡以上'],ans:2,exp:'都市計画区域外（準都市計画区域を除く）の土地取引は10000㎡（1ha）以上が事後届出の対象です（国土利用計画法23条2項1号）。市街化区域2000㎡・その他都市計画区域5000㎡と比べて面積要件が大きいです。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "都市計画区域外での事後届出が必要な面積基準は10000㎡以上です（国土利用計画法施行令17条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "3000㎡以上", "reason": "都市計画区域外の基準は10000㎡以上です（国土利用計画法施行令17条）。", "caution": "都市計画区域外：10000㎡以上（国土利用計画法施行令17条）。"}, {"label": "5000㎡以上", "reason": "5000㎡は非線引き都市計画区域・準都市計画区域の基準です（国土利用計画法施行令17条）。", "caution": ""}, {"label": "20000㎡以上", "reason": "都市計画区域外の基準は10000㎡以上です（国土利用計画法施行令17条）。", "caution": ""}], "summary": {"head": ["事後届出の面積基準（施行令17条）", "基準"], "rows": [["市街化区域", "2000㎡以上"], ["非線引き・準都市計画区域", "5000㎡以上"], ["都市計画区域外", "10000㎡以上"]]}}},
  // 相続・遺言（r_souzoku）追加
  {id:10618,unit:'r_souzoku',level:1,field:'rights',text:'遺言の種類として民法が定める普通方式の遺言に含まれないものはどれか。',opts:['自筆証書遺言','公正証書遺言','秘密証書遺言','口頭遺言'],ans:3,exp:'民法が定める普通方式の遺言は①自筆証書遺言②公正証書遺言③秘密証書遺言の3種類です（民法967条）。口頭遺言という方式はありません。特別方式として危急時遺言等があります。',"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2", "basis": {"text": "配偶者と子の場合は各1/2（民法900条）。相続放棄は3か月以内に家庭裁判所へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2です（民法1042条）。遺産分割協議は全員合意が必要です。", "example": ""}, "reason": {"text": "民法が定める普通方式の遺言は自筆証書遺言・公正証書遺言・秘密証書遺言の3種類です（民法967条）。口頭遺言は普通方式の遺言として認められていません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続の主要ポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子の相続分</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は法定相続分の1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割協議</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "自筆証書遺言", "reason": "自筆証書遺言は普通方式の遺言の一つです（民法967条1号）。全文・日付・氏名を自書し押印が必要です（民法968条）。", "caution": ""}, {"label": "公正証書遺言", "reason": "公正証書遺言は普通方式の遺言の一つです（民法967条2号）。公証人が作成し証人2名が必要です（民法969条）。", "caution": ""}, {"label": "秘密証書遺言", "reason": "秘密証書遺言は普通方式の遺言の一つです（民法967条3号）。内容を秘密にしたまま公証人に存在を証明してもらう方式です（民法970条）。", "caution": ""}], "summary": {"head": ["普通方式の遺言", "特徴"], "rows": [["自筆証書遺言", "全文自書・日付・氏名・押印が必要（民法968条）"], ["公正証書遺言", "公証人作成・証人2名・最も確実（民法969条）"], ["秘密証書遺言", "内容秘密・公証人に存在証明（民法970条）"], ["口頭遺言", "普通方式として無効"]]}}},
  {id:10619,unit:'r_souzoku',level:1,field:'rights',text:'遺留分を持つ相続人として正しいものはどれか。',opts:['配偶者・子・父母・兄弟姉妹','配偶者・子・父母（直系尊属）のみ（兄弟姉妹には遺留分なし）','子のみ','全ての法定相続人'],ans:1,exp:'遺留分を持つのは配偶者・子（代襲相続人を含む）・直系尊属です（民法1042条）。兄弟姉妹には遺留分がありません。遺留分の割合は直系尊属のみが相続人の場合は1/3、それ以外は1/2です。',"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2", "basis": {"text": "配偶者と子の場合は各1/2（民法900条）。相続放棄は3か月以内に家庭裁判所へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2です（民法1042条）。遺産分割協議は全員合意が必要です。", "example": ""}, "reason": {"text": "遺留分を有するのは配偶者・子（代襲相続人含む）・直系尊属です（民法1042条）。兄弟姉妹は法定相続人ですが遺留分は認められていません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続の主要ポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子の相続分</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は法定相続分の1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割協議</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "配偶者・子・父母・兄弟姉妹", "reason": "兄弟姉妹に遺留分はありません（民法1042条）。", "caution": "兄弟姉妹＝法定相続人だが遺留分なし。"}, {"label": "子のみ", "reason": "配偶者・直系尊属にも遺留分があります（民法1042条）。", "caution": ""}, {"label": "全ての法定相続人", "reason": "法定相続人でも兄弟姉妹には遺留分がありません（民法1042条）。", "caution": ""}], "summary": {"head": ["相続人", "遺留分の有無"], "rows": [["配偶者", "あり（民法1042条）"], ["子・代襲相続人", "あり（民法1042条）"], ["直系尊属", "あり（民法1042条）"], ["兄弟姉妹・甥姪", "なし"]]}}},
  {id:10620,unit:'r_souzoku',level:2,field:'rights',text:'自筆証書遺言の要件として正しいものはどれか。',opts:['証人2名以上の立会いが必要','全文・日付・氏名を自書し押印が必要（財産目録はパソコン作成可）','公証人役場での作成が必要','録音・録画でも有効'],ans:1,exp:'自筆証書遺言は全文・日付・氏名を自書し押印することで成立します（民法968条）。2019年改正で財産目録（通帳のコピー等）はパソコン作成も可能になりましたが、各頁に署名押印が必要です。',"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2", "basis": {"text": "配偶者と子の場合は各1/2（民法900条）。相続放棄は3か月以内に家庭裁判所へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2です（民法1042条）。遺産分割協議は全員合意が必要です。", "example": ""}, "reason": {"text": "自筆証書遺言の要件は全文・日付・氏名を自書し押印することです（民法968条1項）。2019年改正により財産目録はパソコン等で作成できるようになりました（同条2項）。証人は不要です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続の主要ポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子の相続分</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は法定相続分の1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割協議</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "証人2名以上の立会いが必要", "reason": "証人が必要なのは公正証書遺言です（民法969条1号）。自筆証書遺言に証人は不要です。", "caution": "自筆証書遺言＝証人不要。公正証書遺言＝証人2名必要。"}, {"label": "公証人役場での作成が必要", "reason": "公証人役場で作成するのは公正証書遺言です（民法969条）。自筆証書遺言は自宅等で作成できます。", "caution": ""}, {"label": "録音・録画でも有効", "reason": "自筆証書遺言は「自書」が要件です（民法968条1項）。録音・録画では要件を満たしません。", "caution": ""}], "summary": {"head": ["自筆証書遺言の要件", "内容"], "rows": [["全文", "自書（ワープロ等不可）"], ["日付", "年月日を特定（「○年○月吉日」は無効）"], ["氏名", "自書"], ["押印", "必要"], ["財産目録", "パソコン作成可（ただし各頁に署名押印が必要）"], ["証人", "不要"]]}}},
  {id:10621,unit:'r_souzoku',level:2,field:'rights',text:'相続放棄の期間として正しいものはどれか。',opts:['相続開始を知った日から1か月以内','相続開始を知った日から3か月以内（熟慮期間）','相続開始後いつでも可','遺産分割協議前のみ可'],ans:1,exp:'相続放棄は相続開始を知った時から3か月以内（熟慮期間）に家庭裁判所に申述しなければなりません（民法915条・938条）。この期間の延長を家庭裁判所に申請することもできます。',"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2", "basis": {"text": "配偶者と子の場合は各1/2（民法900条）。相続放棄は3か月以内に家庭裁判所へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2です（民法1042条）。遺産分割協議は全員合意が必要です。", "example": ""}, "reason": {"text": "相続放棄の熟慮期間は「自己のために相続の開始があったことを知った時」から3か月以内です（民法915条1項）。この期間内に家庭裁判所への申述（民法938条）が必要です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続の主要ポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子の相続分</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は法定相続分の1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割協議</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "相続開始を知った日から1か月以内", "reason": "熟慮期間は3か月です（民法915条1項）。1か月ではありません。", "caution": "熟慮期間は3か月。"}, {"label": "相続開始後いつでも可", "reason": "熟慮期間（3か月）内に手続きが必要です（民法915条1項）。期間を過ぎると単純承認とみなされます（民法921条2号）。", "caution": ""}, {"label": "遺産分割協議前のみ可", "reason": "遺産分割協議の前後ではなく、熟慮期間（3か月）内に家庭裁判所へ申述することが要件です。", "caution": ""}], "summary": {"head": ["相続放棄の手続き", "内容"], "rows": [["期間", "3か月以内（民法915条1項）"], ["方法", "家庭裁判所への申述（民法938条）"], ["口頭放棄", "無効"], ["効果", "初めから相続人でなかったとみなす（民法939条）"]]}}},
  {id:10622,unit:'r_souzoku',level:3,field:'rights',text:'配偶者居住権の説明として正しいものはどれか。',opts:['配偶者が常に無条件で住み続けられる権利','2020年施行の民法改正で新設された権利で、遺産分割・遺贈等により配偶者が相続開始時に居住していた建物に無償で住み続けられる権利','配偶者が生前に合意した場合のみ取得できる','居住権は登記できない'],ans:1,exp:'配偶者居住権は2020年施行の民法改正で新設されました（民法1028条）。相続開始時に被相続人所有の建物に居住していた配偶者が遺産分割・遺贈等により取得でき、登記も可能です。',"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2", "basis": {"text": "配偶者と子の場合は各1/2（民法900条）。相続放棄は3か月以内に家庭裁判所へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2です（民法1042条）。遺産分割協議は全員合意が必要です。", "example": ""}, "reason": {"text": "配偶者居住権は2020年4月施行の民法改正で新設されました（民法1028条）。遺産分割や遺贈により、配偶者が相続開始時に居住していた建物に終身または一定期間無償で住み続けられる権利です。登記もできます（民法1031条・不動産登記法81条の2）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続の主要ポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子の相続分</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は法定相続分の1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割協議</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "配偶者が常に無条件で住み続けられる権利", "reason": "配偶者居住権は遺産分割・遺贈等の手続きによって取得するものであり、自動的に発生する権利ではありません（民法1028条）。", "caution": ""}, {"label": "配偶者が生前に合意した場合のみ取得できる", "reason": "配偶者居住権は遺産分割・遺贈・死因贈与等により取得します（民法1028条）。生前の合意のみが要件ではありません。", "caution": ""}, {"label": "居住権は登記できない", "reason": "配偶者居住権は登記できます（民法1031条2項・不動産登記法81条の2）。登記により第三者に対抗できます。", "caution": ""}], "summary": {"head": ["配偶者居住権", "内容"], "rows": [["新設", "2020年4月施行（民法1028条〜）"], ["取得方法", "遺産分割・遺贈等"], ["期間", "原則終身（別段の定めも可）"], ["内容", "無償で居住建物を使用・収益"], ["登記", "可能（第三者対抗力）"]]}}},
  // 不法行為（r_fuhoko）追加
  {id:10623,unit:'r_fuhoko',level:1,field:'rights',text:'不法行為による損害賠償請求権の消滅時効として正しいものはどれか。',opts:['損害および加害者を知った時から1年','損害および加害者を知った時から3年（人身損害は5年）','不法行為時から10年','損害を知った時から5年'],ans:1,exp:'不法行為による損害賠償請求権は被害者が損害および加害者を知った時から3年（生命・身体への損害は5年）または不法行為の時から20年で消滅します（民法724条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "不法行為の消滅時効は「損害および加害者を知った時から3年」（人身損害は5年）または「不法行為時から20年」のいずれか早い方で消滅します（民法724条・724条の2）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "損害および加害者を知った時から1年", "reason": "不法行為の消滅時効は「3年」です（民法724条1号）。1年ではありません。", "caution": ""}, {"label": "不法行為時から10年", "reason": "不法行為時（客観的起算点）からの消滅時効は「20年」です（民法724条2号）。10年は一般の債権の客観的起算点からの期間です（民法166条1項2号）。", "caution": "不法行為の客観的起算点：20年（民法724条2号）。一般債権：10年（民法166条）。"}, {"label": "損害を知った時から5年", "reason": "損害のみを知った時ではなく「損害および加害者を知った時」から3年です（民法724条1号）。5年ではありません。", "caution": ""}], "summary": {"head": ["不法行為の消滅時効", "期間"], "rows": [["主観的起算点（損害・加害者を知った時）", "3年（民法724条1号）"], ["人の生命・身体侵害", "5年（民法724条の2）"], ["客観的起算点（不法行為時）", "20年（民法724条2号）"]]}}},
  {id:10624,unit:'r_fuhoko',level:1,field:'rights',text:'使用者責任（民法715条）の成立要件として正しいものはどれか。',opts:['被用者の行為に故意が必要','被用者が事業の執行について第三者に損害を与えたこと','使用者が直接加害行為をしたこと','使用者・被用者が同一の場所にいたこと'],ans:1,exp:'使用者責任は被用者（従業員等）が「事業の執行について」第三者に損害を加えた場合に使用者が負う責任です（民法715条）。使用者は選任・監督に相当の注意をしたことを証明すれば免責されます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "使用者責任（民法715条1項）は被用者が「事業の執行につき」第三者に損害を与えた場合に成立します。使用者が直接加害する必要はなく、被用者の行為が事業の執行と客観的外形上関連していれば足ります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "被用者の行為に故意が必要", "reason": "故意だけでなく過失による不法行為でも使用者責任は成立します（民法715条1項）。", "caution": ""}, {"label": "使用者が直接加害行為をしたこと", "reason": "使用者責任は被用者の行為について使用者が責任を負う制度です（民法715条1項）。使用者の直接加害は不要です。", "caution": ""}, {"label": "使用者・被用者が同一の場所にいたこと", "reason": "同一場所にいることは要件ではありません（民法715条1項）。", "caution": ""}], "summary": {"head": ["使用者責任の要件（民法715条）", "内容"], "rows": [["使用関係", "雇用等の実質的な指揮命令関係"], ["事業の執行", "客観的外形から事業の執行と判断できること"], ["不法行為", "被用者が第三者に損害を与えたこと"], ["免責", "選任・監督に相当注意した場合（実務上ほぼ不認定）"]]}}},
  {id:10625,unit:'r_fuhoko',level:2,field:'rights',text:'不当利得返還請求権の要件として正しいものはどれか。',opts:['相手方の故意・過失が必要','法律上の原因なく他人の財産または労務により利益を受け、それによって他人に損失を与えたこと','相手方に損害が生じたこと','契約書の存在が必要'],ans:1,exp:'不当利得は①法律上の原因がないこと②受益があること③他人の損失があること④因果関係があることで成立します（民法703条）。相手方の故意・過失は不要です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "不当利得（民法703条）は①法律上の原因なく②他人の財産または労務により利益を受け③それによって他人に損失を与えた場合に返還義務が生じます。故意・過失は要件ではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "相手方の故意・過失が必要", "reason": "不当利得には故意・過失は不要です（民法703条）。これが不法行為との大きな違いです。", "caution": "不当利得＝故意・過失不要。不法行為＝故意または過失が必要。"}, {"label": "相手方に損害が生じたこと", "reason": "「他人に損失を与えた」ことは要件ですが「損害」（不法行為的な概念）とは異なります。損失者は損失の発生を証明します（民法703条）。", "caution": ""}, {"label": "契約書の存在が必要", "reason": "不当利得の成立に契約書は不要です（民法703条）。", "caution": ""}], "summary": {"head": ["不当利得（民法703条）", "内容"], "rows": [["要件", "①法律上の原因なし②利益を受けた③損失との因果関係"], ["故意・過失", "不要（不法行為との違い）"], ["善意の返還", "現存利益のみ（民法703条）"], ["悪意の返還", "利益全額＋利息＋損害賠償（民法704条）"]]}}},
  {id:10626,unit:'r_fuhoko',level:3,field:'rights',text:'工作物責任（民法717条）において第一次的に責任を負う者として正しいものはどれか。',opts:['工作物の所有者','工作物の占有者（ただし損害防止に必要な注意をした場合は免責・その場合は所有者が責任を負う）','建設した工事業者','近隣住民'],ans:1,exp:'工作物責任は第一次的に工作物の「占有者」が負い、占有者が損害防止に必要な注意をしていた場合は所有者が無過失責任を負います（民法717条）。所有者の責任は無過失責任（免責不可）です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "工作物責任（民法717条）は占有者が第一次的に責任を負いますが、損害防止に必要な注意を尽くした場合は免責され、その場合は所有者が無過失責任を負います（民法717条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "工作物の所有者", "reason": "所有者は第二次的に無過失責任を負います（民法717条1項後段）。第一次的には占有者が責任を負います。", "caution": "第一次：占有者（過失責任）。第二次：所有者（無過失責任）。"}, {"label": "建設した工事業者", "reason": "施工業者は工作物の瑕疵の原因者として求償の対象になりますが、民法717条の直接の責任者（第一次的責任者）ではありません。", "caution": ""}, {"label": "近隣住民", "reason": "近隣住民は工作物責任（民法717条）の責任者ではありません。", "caution": ""}], "summary": {"head": ["工作物責任（民法717条）", "内容"], "rows": [["第一次責任者", "占有者（過失責任：損害防止に注意を尽くせば免責）"], ["第二次責任者", "所有者（無過失責任：免責なし）"], ["被害者の選択", "占有者または所有者に請求可"], ["求償", "所有者→設計・施工業者への求償可"]]}}},
  // 代理（r_dairi）追加
  {id:10627,unit:'r_dairi',level:1,field:'rights',text:'代理行為の効果帰属先として正しいものはどれか。',opts:['代理人','本人（委任者）','相手方','代理人と本人が半分ずつ'],ans:1,exp:'代理人が代理権の範囲内で本人のためにすることを示して（顕名）行った法律行為の効果は直接本人に帰属します（民法99条）。',"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護する制度です。", "example": ""}, "reason": {"text": "代理の本質は本人への効果帰属です（民法99条1項）。代理人が本人のためにすることを示して（顕名）相手方と行為すると、その法律効果は本人に直接帰属します。これが代理制度の最大の特徴です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "代理人", "reason": "代理行為の効果は代理人ではなく本人に帰属します（民法99条1項）。代理人は本人のために行動するだけです。", "caution": "代理の効果＝本人に帰属。これが代理制度の本質です。"}, {"label": "相手方", "reason": "代理行為の効果は相手方ではなく本人に帰属します（民法99条1項）。相手方は本人の契約の相手になります。", "caution": ""}, {"label": "代理人と本人が半分ずつ", "reason": "代理行為の効果は本人に全て帰属します（民法99条1項）。代理人と本人が半分ずつ権利義務を持つわけではありません。", "caution": ""}], "summary": {"head": ["代理の成立要件", "内容"], "rows": [["①代理権の存在", "本人から授権されていること"], ["②顕名", "本人のためにすることを示すこと（民法99条1項）"], ["③代理行為", "相手方との法律行為"], ["効果", "本人に直接帰属（民法99条1項）"]]}}},
  {id:10628,unit:'r_dairi',level:2,field:'rights',text:'無権代理人が相手方に負う責任として正しいものはどれか。',opts:['無権代理人は一切の責任を負わない','相手方の選択により履行または損害賠償の責任を負う（善意無過失の相手方に対して）','本人が必ず追認しなければならない','相手方のみが責任を負う'],ans:1,exp:'無権代理人は相手方が善意無過失の場合、相手方の選択に従い契約の履行または損害賠償の責任を負います（民法117条）。相手方が悪意または有過失の場合は無権代理人の責任は生じません。',"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護する制度です。", "example": ""}, "reason": {"text": "無権代理人は相手方が善意無過失の場合、相手方の選択により契約の履行または損害賠償の責任を負います（民法117条1項）。相手方を保護するための規定で、無権代理人には知らなかったという抗弁は原則認められません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "無権代理人は一切の責任を負わない", "reason": "無権代理人は相手方の善意無過失を条件に履行または損害賠償の責任を負います（民法117条1項）。責任がないというのは誤りです。", "caution": "無権代理人は民法117条により責任を負います。"}, {"label": "本人が必ず追認しなければならない", "reason": "本人に追認義務はありません。追認しない場合は無権代理人が責任を負います（民法117条）。", "caution": ""}, {"label": "相手方のみが責任を負う", "reason": "無権代理の場合、責任を負うのは無権代理人です（民法117条）。相手方が責任を負うわけではありません。", "caution": ""}], "summary": {"head": ["無権代理の処理", "内容"], "rows": [["本人の追認", "本人に効果帰属（民法113条）"], ["本人の追認拒絶", "無権代理人が責任（民法117条）"], ["表見代理の成立", "本人に効果帰属（民法109・110・112条）"], ["相手方の取消し", "善意の相手方は本人の追認前に取消可（民法115条）"]]}}},
  {id:10629,unit:'r_dairi',level:3,field:'rights',text:'代理権の濫用（自己または第三者の利益のための代理権行使）の効果として正しいものはどれか（判例・改正民法）。',opts:['代理行為は常に有効','相手方が代理人の意図を知りまたは知ることができた場合は、本人は代理行為の効果を否定できる（民法107条）','代理人が個人責任を負うのみ','本人は無条件に取り消せる'],ans:1,exp:'代理権の濫用は2020年民法改正で明文化され（民法107条）、相手方が代理人の目的を知りまたは知ることができた場合は代理権のない行為（無権代理）とみなされます。',"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護する制度です。", "example": ""}, "reason": {"text": "代理権の濫用（民法107条）では、代理人が外形上は代理権の範囲内で行動していますが、自己または第三者の利益を図る目的で権限を行使しています。相手方がこの事情を知りまたは知ることができた場合、本人はその行為の効果を否定できます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "代理行為は常に有効", "reason": "相手方が代理人の不正な目的を知りまたは知ることができた場合は、本人はその効果を否定できます（民法107条）。常に有効ではありません。", "caution": ""}, {"label": "代理人が個人責任を負うのみ", "reason": "代理権濫用では、相手方の善意無過失次第で本人も対応が異なります。単に代理人だけが責任を負うわけではありません。", "caution": ""}, {"label": "本人は無条件に取り消せる", "reason": "本人が効果を否定できるのは「相手方が悪意または有過失の場合」に限られます（民法107条）。相手方が善意無過失であれば本人は効果を否定できません。", "caution": "相手方善意無過失→本人は否定不可。相手方悪意・有過失→本人は否定可。"}], "summary": {"head": ["相手方の状態", "代理行為の効力"], "rows": [["相手方が善意かつ無過失", "代理行為の効力あり（本人に帰属）"], ["相手方が悪意または有過失", "本人は効果を否定可（民法107条）"]]}}},
  // 売買・契約不適合（r_baibai）追加
  {id:10630,unit:'r_baibai',level:1,field:'rights',text:'売買契約における手付金の種類として「解約手付」の説明として正しいものはどれか。',opts:['契約成立の証拠として交付される手付','違約した場合に没収される手付','買主は手付を放棄し、売主は手付の倍額を返すことで解除できる手付','相手方の同意が必要な手付'],ans:2,exp:'解約手付とは買主は手付を放棄し、売主は手付の倍額を現実に提供することで相手方が履行に着手するまでの間は契約を解除できる手付です（民法557条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "解約手付は買主が手付を放棄し、売主が手付の倍額を現実に提供することで解除できる手付です（民法557条1項）。証約手付は契約成立の証拠、違約手付は違約した場合の制裁として機能します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "契約成立の証拠として交付される手付", "reason": "これは証約手付の説明です。解約手付は解除の手段として機能します（民法557条1項）。", "caution": "証約手付＝成立の証拠、解約手付＝解除の手段。"}, {"label": "違約した場合に没収される手付", "reason": "これは違約手付の説明です。解約手付は違約でなくても一定の対価（放棄または倍返し）で解除できます（民法557条1項）。", "caution": ""}, {"label": "相手方の同意が必要な手付", "reason": "解約手付は相手方の同意なく一定の対価（放棄または倍返し）で解除できます（民法557条1項）。", "caution": ""}], "summary": {"head": ["手付の種類と機能", "内容"], "rows": [["証約手付", "契約成立の証拠"], ["解約手付", "買主：手付放棄、売主：倍額提供で解除（民法557条）"], ["違約手付", "違約した場合に没収・倍返し"], ["特定の定めがない場合", "解約手付と推定（民法557条1項）"]]}}},
  {id:10631,unit:'r_baibai',level:2,field:'rights',text:'売買代金の支払いと目的物引渡しの関係として正しいものはどれか。',opts:['常に代金を先払いしなければならない','代金の支払いと目的物の引渡しは同時履行の関係にある','引渡しが先でなければならない','法律上の定めはなく全て当事者の合意による'],ans:1,exp:'売買における代金支払いと目的物引渡しは同時履行の関係にあります（民法533条）。一方は相手方が履行または履行の提供をするまで自己の債務の履行を拒絶できます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "売買契約における代金の支払いと目的物の引渡しは、特約がない限り同時履行の関係にあります（民法533条）。同時履行の関係にある場合、一方は相手方が履行の提供をするまで自己の債務の履行を拒絶できます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "常に代金を先払いしなければならない", "reason": "同時履行の関係（民法533条）により先払い義務はありません。特約がなければ同時履行です。", "caution": "売買の代金支払いと引渡しは同時履行（民法533条）。"}, {"label": "引渡しが先でなければならない", "reason": "特約がなければ代金支払いと引渡しは同時履行です（民法533条）。引渡しが先という規定はありません。", "caution": ""}, {"label": "法律上の定めはなく全て当事者の合意による", "reason": "民法533条で同時履行の関係が定められています。法律上の定めがないとするのは誤りです。", "caution": ""}], "summary": {"head": ["売買の同時履行（民法533条）", "内容"], "rows": [["原則", "代金支払い＋目的物引渡しは同時履行"], ["同時履行の抗弁権", "相手方が履行提供するまで自己の履行を拒絶できる"], ["先払い特約", "当事者合意で変更可"]]}}},
  // 賃貸借（r_chinshaku）追加
  {id:10632,unit:'r_chinshaku',level:1,field:'rights',text:'賃借人が賃料を支払わない場合の賃貸人の対応として正しいものはどれか。',opts:['直ちに鍵を交換して追い出せる','賃料不払いを理由に解除するには原則として催告が必要で、信頼関係破壊の程度に応じて判断される','1か月の不払いで即時解除できる','賃貸借契約は解除できない'],ans:1,exp:'賃貸借の解除は単なる債務不履行（賃料不払い）があれば即時解除できるのではなく、信頼関係が破壊されるほどの不払いがあって初めて解除できるとするのが判例の立場です（信頼関係破壊の法理）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "賃料不払いを理由に解除するには原則として催告が必要です（民法541条）。また判例の信頼関係破壊の法理により、1〜2か月程度の不払いでは信頼関係の破壊とはならず解除が認められない場合があります。自力救済（鍵の交換等）は禁止されています。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "直ちに鍵を交換して追い出せる", "reason": "自力救済は禁止されています（民法の一般原則）。賃料不払いを理由に解除するには催告→不払い継続→解除通知という手順が必要です。", "caution": "自力救済禁止。法的手続き（催告→解除→明渡訴訟）が必要。"}, {"label": "1か月の不払いで即時解除できる", "reason": "判例の信頼関係破壊の法理により、1か月程度の不払いでは解除が認められない場合があります（判例）。", "caution": ""}, {"label": "賃貸借契約は解除できない", "reason": "相当期間の催告後も賃料不払いが継続し信頼関係が破壊された場合は解除できます（民法541条・判例）。", "caution": ""}], "summary": {"head": ["賃料不払いと解除の手順", "内容"], "rows": [["①催告", "相当期間を定めて支払いを求める（民法541条）"], ["②不払い継続", "催告期間内に支払いなし"], ["③解除通知", "解除の意思表示"], ["判例の制限", "信頼関係が破壊されない程度の不払いは解除不可"]]}}},
  {id:10633,unit:'r_chinshaku',level:2,field:'rights',text:'敷金の返還について正しいものはどれか（2020年民法改正後）。',opts:['敷金は退去後いつ返還してもよい','賃貸借終了後の目的物返還時に、未払い賃料等を控除した残額を返還しなければならない','敷金は返還しなくてよい','敷金の返還時期は賃貸人が自由に決定できる'],ans:1,exp:'2020年施行の民法改正で敷金規定が明文化されました（民法622条の2）。賃貸借終了と目的物の返還の後、賃借人の未払い賃料等の債務を控除した残額を返還しなければなりません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "敷金は賃貸借終了後に目的物の返還を受けた時、未払い賃料等を控除した残額を返還しなければなりません（民法622条の2第1項）。2020年民法改正で条文化されました。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "敷金は退去後いつ返還してもよい", "reason": "明渡しを受けた後、合理的な期間内に返還しなければなりません（民法622条の2第1項）。「いつでも」ではありません。", "caution": ""}, {"label": "敷金は返還しなくてよい", "reason": "敷金は原則として返還義務があります（民法622条の2第1項）。未払い賃料等を控除した残額を返還します。", "caution": ""}, {"label": "敷金の返還時期は賃貸人が自由に決定できる", "reason": "敷金の返還時期は民法622条の2第1項により「目的物の返還を受けた時」と定められており、賃貸人が自由に決定できるわけではありません。", "caution": ""}], "summary": {"head": ["敷金の返還（民法622条の2）", "内容"], "rows": [["返還時期", "明渡し（目的物返還）後"], ["返還額", "敷金額－（未払賃料＋原状回復費用等）"], ["賃借人への充当", "賃貸人は敷金を未払賃料等に充当可（賃借人は充当請求不可）"]]}}},
  // 担保物権（r_tanpo）追加
  {id:10634,unit:'r_tanpo',level:1,field:'rights',text:'抵当権の被担保債権として認められないものはどれか。',opts:['金銭消費貸借契約上の貸金債権','売買代金債権','将来生じる債権（根抵当権の場合）','不法行為に基づく損害賠償債権（抵当権設定時に発生している場合）'],ans:3,exp:'抵当権の被担保債権は原則として抵当権設定時に特定されている必要があります。不法行為による損害賠償債権は将来発生が不確実であり、設定時点では特定困難なため通常の抵当権の被担保債権としては認められにくいです。',"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権です（民法369条）。質権は占有の移転が必要です。先取特権は法律上当然に成立する法定担保物権です。", "example": ""}, "reason": {"text": "抵当権は金銭消費貸借上の債権・売買代金債権・保証債務等を担保できます。不法行為に基づく損害賠償債権も理論上は担保できますが、抵当権設定時に債権が確定していない将来の不法行為債権を担保することは認められていません。設定時に発生済みであれば可能との見解もありますが、実務上ほとんど使われません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・非占有</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・占有</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "金銭消費貸借契約上の貸金債権", "reason": "貸金債権は抵当権の被担保債権として最も一般的です（民法369条）。誤りではありません。", "caution": ""}, {"label": "売買代金債権", "reason": "売買代金債権も抵当権の被担保債権になれます（民法369条）。誤りではありません。", "caution": ""}, {"label": "将来生じる債権（根抵当権の場合）", "reason": "根抵当権は将来生じる不特定の債権を担保できます（民法398条の2）。誤りではありません。", "caution": ""}], "summary": {"head": ["被担保債権の種類", "普通抵当権", "根抵当権"], "rows": [["貸金債権", "可", "可"], ["売買代金債権", "可", "可"], ["将来の不特定債権", "不可", "可（一定範囲内）"], ["不法行為債権", "理論上可（実務上稀）", "一定条件下で可"]]}}},
  {id:10635,unit:'r_tanpo',level:2,field:'rights',text:'抵当権の実行方法として正しいものはどれか。',opts:['抵当権者が直接目的物を占有して売却できる','競売（裁判所の競売手続き）または担保不動産収益執行','任意売却のみ','抵当権者が自由に処分できる'],ans:1,exp:'抵当権の実行は①競売（裁判所による競売手続き）②担保不動産収益執行（賃料等を収取して弁済に充てる）の方法があります（民法180条以下、民事執行法）。',"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権です（民法369条）。質権は占有の移転が必要です。先取特権は法律上当然に成立する法定担保物権です。", "example": ""}, "reason": {"text": "抵当権の実行方法は競売（担保不動産競売）または担保不動産収益執行です（民事執行法180条）。競売は裁判所の手続きを通じて行われ、抵当権者が直接処分することはできません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・非占有</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・占有</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "抵当権者が直接目的物を占有して売却できる", "reason": "抵当権者が自ら占有・売却することは認められていません（自力救済禁止）。裁判所の競売手続きによります（民事執行法180条）。", "caution": "自力救済禁止。抵当権の実行は必ず裁判所の手続きを通じる。"}, {"label": "任意売却のみ", "reason": "任意売却は競売の代わりに行われることがありますが、抵当権の実行方法は競売または担保不動産収益執行です（民事執行法180条）。", "caution": ""}, {"label": "抵当権者が自由に処分できる", "reason": "抵当権者は目的物を自由に処分できません。裁判所の競売手続きを通じて実行します（民事執行法180条）。", "caution": ""}], "summary": {"head": ["抵当権の実行方法", "内容"], "rows": [["担保不動産競売", "裁判所の競売手続き→競落代金から優先弁済"], ["担保不動産収益執行", "賃料等の収益から優先弁済（所有権移転なし）"], ["物上代位", "賃料・保険金等への差押え"], ["任意売却", "競売に代わる売却（抵当権者の同意が必要）"]]}}},
  // 債権総論（r_saikensoron）追加
  {id:10636,unit:'r_saikensoron',level:1,field:'rights',text:'弁済の充当順序について正しいものはどれか（当事者の合意がない場合）。',opts:['元本→利息→費用の順で充当','費用→利息→元本の順で充当（費用が優先）','利息→元本→費用','元本のみに充当'],ans:1,exp:'弁済の充当は費用→利息→元本の順で行います（民法489条）。費用・利息が残っている場合は元本には充当されないため、債務者は元本が減っていると思っていても利息が蓄積している場合があります。',"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要です（民法446条2項）。連帯保証人には催告・検索の抗弁権がありません（民法454条）。債権譲渡の第三者対抗要件は確定日付ある証書による通知または承諾です（民法467条2項）。", "example": ""}, "reason": {"text": "弁済の充当順序は当事者の合意がない場合、費用→利息→元本の順で充当されます（民法489条）。これは債務者保護の観点から、費用・利息を先に消化することで元本の増大を防ぐための規定です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相殺の要件</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">双方が同種の債権</text></svg>", "choices": [{"label": "元本→利息→費用の順で充当", "reason": "充当順序は費用→利息→元本です（民法489条）。元本が最初というのは誤りです。", "caution": "費用→利息→元本（民法489条）。"}, {"label": "利息→元本→費用", "reason": "費用が最優先です（民法489条）。利息が最初というのは誤りです。", "caution": ""}, {"label": "元本のみに充当", "reason": "費用・利息・元本のすべてに充当されます（民法489条）。", "caution": ""}], "summary": {"head": ["充当順序（民法489条）", "理由"], "rows": [["①費用", "交通費・手数料等の弁済費用"], ["②利息", "元本に対する利息"], ["③元本", "主たる債務"], ["趣旨", "元本から充当すると利息が増大して債務者に不利なため"]]}}},
  {id:10637,unit:'r_saikensoron',level:2,field:'rights',text:'履行遅滞の成立要件として正しいものはどれか。',opts:['債務者が弁済の意思表示をすれば遅滞にならない','履行が可能であるのに弁済期が到来しているにもかかわらず債務者が正当な理由なく履行しないこと','履行期前の履行拒絶でも遅滞が成立する','不可抗力でも遅滞が成立する'],ans:1,exp:'履行遅滞は①履行が可能②弁済期到来③履行しない④違法（帰責事由がある）の要件で成立します（民法412条）。不可抗力等の帰責事由がない場合は遅滞の責任を負いません（改正民法）。',"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要です（民法446条2項）。連帯保証人には催告・検索の抗弁権がありません（民法454条）。債権譲渡の第三者対抗要件は確定日付ある証書による通知または承諾です（民法467条2項）。", "example": ""}, "reason": {"text": "履行遅滞（民法412条）は弁済期が到来しているにもかかわらず債務者が正当な理由なく履行しない場合に成立します。不可抗力は正当な理由となり遅滞が成立しません。また履行が客観的に不能な場合は遅滞ではなく履行不能の問題です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相殺の要件</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">双方が同種の債権</text></svg>", "choices": [{"label": "債務者が弁済の意思表示をすれば遅滞にならない", "reason": "意思表示だけでは足らず、実際に弁済（給付）する必要があります（民法492条）。意思表示のみで遅滞が解消されるわけではありません。", "caution": ""}, {"label": "履行期前の履行拒絶でも遅滞が成立する", "reason": "期前の履行拒絶は遅滞ではなく、解除権の発生等の問題です（民法542条1項3号）。", "caution": ""}, {"label": "不可抗力でも遅滞が成立する", "reason": "不可抗力による不履行には帰責事由がなく遅滞は成立しません（民法412条・415条1項ただし書）。", "caution": ""}], "summary": {"head": ["履行遅滞の成立要件", "内容"], "rows": [["①弁済期の到来", "確定期限（期日が来た時）・不確定期限（到来を知った時）"], ["②履行可能", "履行できるのに履行しない状態"], ["③帰責事由", "不可抗力は遅滞不成立"], ["④催告", "損害賠償・解除には催告が必要（原則）"]]}}},
  {id:10638,unit:'r_saikensoron',level:3,field:'rights',text:'第三者弁済の可否について正しいものはどれか（2020年改正後）。',opts:['第三者は常に弁済できる','原則として第三者も弁済できるが、債務の性質が許さない場合・当事者が反対意思を表示した場合・正当な利益のない第三者が債務者の意思に反して弁済する場合は不可','第三者は債権者の同意があれば弁済できる','第三者弁済は無効'],ans:1,exp:'2020年民法改正後、第三者弁済は原則可能ですが①債務の性質が許さない場合②当事者の反対意思表示がある場合は不可、また③正当な利益を有しない第三者は債務者の意思に反して弁済できません（民法474条）。',"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要です（民法446条2項）。連帯保証人には催告・検索の抗弁権がありません（民法454条）。債権譲渡の第三者対抗要件は確定日付ある証書による通知または承諾です（民法467条2項）。", "example": ""}, "reason": {"text": "第三者弁済は原則として有効です（民法474条1項）。ただし①債務の性質が許さない場合（医師の診察等）、②当事者が反対意思を表示した場合、③正当な利益のない第三者が債務者の意思に反して弁済する場合は無効です（同条2項〜4項）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相殺の要件</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">双方が同種の債権</text></svg>", "choices": [{"label": "第三者は常に弁済できる", "reason": "第三者弁済は原則有効ですが一定の例外があります（民法474条2項〜4項）。「常に」は誤りです。", "caution": ""}, {"label": "第三者は債権者の同意があれば弁済できる", "reason": "債権者の同意は要件ではありません（民法474条1項）。原則として第三者は弁済できます（一定の例外を除く）。", "caution": ""}, {"label": "第三者弁済は無効", "reason": "第三者弁済は原則として有効です（民法474条1項）。「無効」は誤りです。", "caution": ""}], "summary": {"head": ["第三者弁済（民法474条）", "内容"], "rows": [["原則", "第三者も弁済可（民法474条1項）"], ["例外①", "債務の性質が許さない場合（一身専属的給付）"], ["例外②", "当事者が反対意思を表示した場合"], ["例外③", "正当な利益なき第三者が債務者の意思に反して弁済"]]}}},
  // 時効（r_jiko）追加
  {id:10639,unit:'r_jiko',level:1,field:'rights',text:'取得時効における占有の要件として「自主占有」とは何か。',opts:['占有者本人が直接占有していること','所有の意思をもって占有すること','占有期間が長いこと','公示された占有であること'],ans:1,exp:'自主占有とは所有の意思をもってする占有のことです（民法162条）。賃借人の占有は他主占有（所有の意思なし）であり、取得時効は成立しません。',"kaisetsu":{"topic": "消滅時効：知った時から5年または行使可能時から10年", "basis": {"text": "一般の債権の消滅時効は「権利行使できると知った時から5年」または「権利行使できる時から10年」のいずれか早い方で完成します（民法166条1項）。時効は援用して初めて効力が発生します（民法145条）。", "example": ""}, "reason": {"text": "取得時効の「自主占有」とは所有の意思をもって占有することです（民法162条）。賃借人や使用貸借人のような他主占有（他人の所有を認めて占有）では取得時効は成立しません。占有の性質は客観的な事情で決まります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">時効期間</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人の生命・身体への損害</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年または20年</text></svg>", "choices": [{"label": "占有者本人が直接占有していること", "reason": "直接占有か代理占有かは自主占有の要件ではありません（民法162条）。自主占有は「所有の意思」の問題です。", "caution": "自主占有＝所有の意思あり。直接占有か否かは別問題。"}, {"label": "占有期間が長いこと", "reason": "占有期間の長短は取得時効の成立要件（10年・20年）に関係しますが、「自主占有」の定義ではありません。", "caution": ""}, {"label": "公示された占有であること", "reason": "占有の公示（登記等）は取得時効の要件ではありません（民法162条）。", "caution": ""}], "summary": {"head": ["占有の種類", "内容"], "rows": [["自主占有", "所有の意思をもった占有（取得時効の要件）"], ["他主占有", "他人の所有を認めた占有（賃借人・使用借人等）"], ["直接占有", "自ら物を支配"], ["間接占有", "代理人等を通じた占有"]]}}},
  {id:10640,unit:'r_jiko',level:2,field:'rights',text:'消滅時効の「更新」事由として正しいものはどれか。',opts:['裁判上の請求','確定判決・債務の承認等','仮差押え・仮処分','協議を行う旨の合意'],ans:1,exp:'時効の更新（旧:中断）事由は①確定判決等による権利確定②強制執行等の終了③債務の承認です（民法152条）。裁判上の請求・仮差押え・協議合意は完成猶予事由です。',"kaisetsu":{"topic": "消滅時効：知った時から5年または行使可能時から10年", "basis": {"text": "一般の債権の消滅時効は「権利行使できると知った時から5年」または「権利行使できる時から10年」のいずれか早い方で完成します（民法166条1項）。時効は援用して初めて効力が発生します（民法145条）。", "example": ""}, "reason": {"text": "時効の「更新」事由は確定判決等による権利確定・承認等です（民法147条2項・152条）。更新により時効期間がゼロからリスタートします。仮差押え・催告等は完成猶予のみで更新はしません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">時効期間</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人の生命・身体への損害</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年または20年</text></svg>", "choices": [{"label": "裁判上の請求", "reason": "裁判上の請求（訴え提起）は完成猶予事由です（民法147条1項）。更新は確定判決等の時点で生じます（同条2項）。", "caution": "訴え提起→完成猶予、確定判決→更新。"}, {"label": "仮差押え・仮処分", "reason": "仮差押え・仮処分は完成猶予事由ですが（民法148条1項）、更新は手続終了後6か月の猶予後に更新が生じる仕組みです。単純な更新事由ではありません。", "caution": ""}, {"label": "協議を行う旨の合意", "reason": "協議合意は完成猶予事由です（民法151条）。更新ではありません。", "caution": ""}], "summary": {"head": ["効果", "主な事由"], "rows": [["更新", "確定判決（民法147条2項）・承認（民法152条）"], ["完成猶予→更新", "裁判上の請求・強制執行等（確定等後に更新）"], ["完成猶予のみ", "催告（6か月・民法150条）・協議合意（民法151条）"]]}}},
  // 物権変動（r_bukken）追加
  {id:10641,unit:'r_bukken',level:1,field:'rights',text:'不動産の二重譲渡で第一買主Bが登記を備えた場合の効力として正しいものはどれか。',opts:['先に契約したCが優先する','先に登記したBが所有権を取得しCに対抗できる','売主Aが所有権を保持する','価格が高い方が優先する'],ans:1,exp:'不動産の二重譲渡では先に登記を備えた者が所有権を対抗できます（民法177条）。契約の先後ではなく登記の先後で決まります。',"kaisetsu":{"topic": "物権変動：登記が対抗要件・不法占拠者には登記不要", "basis": {"text": "不動産の物権変動は登記が第三者への対抗要件です（民法177条）。不法占拠者には登記なく対抗できます。相続の法定相続分超過部分は登記が必要です（民法899条の2）。", "example": ""}, "reason": {"text": "二重譲渡の解決は登記の先後によります（民法177条）。この原則により、先に登記を備えた者が確定的に所有権を取得し、後からの者は権利を主張できません。売主への損害賠償請求が後からの者の救済手段です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">物権変動の対抗要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対抗要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">二重譲渡</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先に登記した者が優先</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不法占拠者</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記不要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物賃借権</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡し</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続（超過部分）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記必要</text></svg>", "choices": [{"label": "先に契約したCが優先する", "reason": "契約の先後は対抗関係を決しません。先に登記を備えた者が優先します（民法177条）。", "caution": "先に契約≠先に権利取得。登記が勝敗を決めます。"}, {"label": "売主Aが所有権を保持する", "reason": "売主Aは二重売買により買主に所有権を移転しています。登記を備えた買主が確定的に所有権を取得し、Aに所有権は残りません。", "caution": ""}, {"label": "価格が高い方が優先する", "reason": "売買代金の額は物権変動の対抗関係と無関係です。登記の先後のみで決まります。", "caution": ""}], "summary": {"head": ["状況", "結果"], "rows": [["Bが先に登記を備えた", "Bが所有権取得、CはAに損害賠償請求可"], ["Cが先に登記を備えた", "Cが所有権取得、BはAに損害賠償請求可"], ["どちらも未登記", "引き続き対抗関係（先に登記した方が勝つ）"]]}}},
  {id:10642,unit:'r_bukken',level:2,field:'rights',text:'抵当権設定後に抵当不動産の所有者が変わった場合（第三取得者）の対抗として正しいものはどれか。',opts:['第三取得者は抵当権の負担のない所有権を取得する','第三取得者は抵当権の負担を承継し、抵当権が実行されれば競売で所有権を失う可能性がある','抵当権は自動的に消滅する','第三取得者は抵当権者に損害賠償を請求できる'],ans:1,exp:'抵当権は登記があれば第三取得者にも対抗できます（民法177条）。第三取得者は抵当権の負担を承継し、代価弁済・抵当権消滅請求等の制度を利用して抵当権を消滅させることができます（民法378条・379条）。',"kaisetsu":{"topic": "物権変動：登記が対抗要件・不法占拠者には登記不要", "basis": {"text": "不動産の物権変動は登記が第三者への対抗要件です（民法177条）。不法占拠者には登記なく対抗できます。相続の法定相続分超過部分は登記が必要です（民法899条の2）。", "example": ""}, "reason": {"text": "抵当権は追及効を持つ物権です（民法369条）。不動産が第三者に譲渡されても抵当権はその不動産に追いかけ、第三取得者はその負担を承継します。これが抵当権の最も重要な特質の一つです。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">物権変動の対抗要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対抗要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">二重譲渡</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先に登記した者が優先</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不法占拠者</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記不要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物賃借権</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡し</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続（超過部分）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記必要</text></svg>", "choices": [{"label": "第三取得者は抵当権の負担のない所有権を取得する", "reason": "抵当権は追及効があり、不動産の所有者が変わっても抵当権は消滅しません（民法369条）。第三取得者は抵当権の負担を承継します。", "caution": "抵当権の追及効：不動産が誰の手に渡っても抵当権はついてきます。"}, {"label": "抵当権は自動的に消滅する", "reason": "抵当権は被担保債権の弁済等がなければ消滅しません。所有者が変わっても自動的には消滅しません（付従性は被担保債権の消滅による）。", "caution": ""}, {"label": "第三取得者は抵当権者に損害賠償を請求できる", "reason": "第三取得者が競売で所有権を失った場合は売主（前所有者）への担保責任追及が可能ですが、抵当権者への損害賠償は原則できません。抵当権者は正当な権利を行使しているからです。", "caution": ""}], "summary": {"head": ["第三取得者の保護手段", "内容", "根拠"], "rows": [["代価弁済", "抵当権者の請求で弁済し抵当権消滅", "民法378条"], ["抵当権消滅請求", "相当額を支払い消滅を請求", "民法379条"], ["売主への担保責任", "競売後に売主に損害賠償等", "民法562条等"]]}}},
  // 意思表示（r_ishi）追加
  {id:10643,unit:'r_ishi',level:1,field:'rights',text:'制限行為能力者制度における「被保佐人」について正しいものはどれか。',opts:['すべての法律行為を保佐人が代理する','不動産売買・借財など重要な法律行為について保佐人の同意が必要','日常的な買い物も保佐人の同意が必要','被保佐人は完全に行為能力を制限される'],ans:1,exp:'被保佐人は精神上の障害により判断能力が著しく不十分な者で、不動産の売買・借財・保証等の重要な行為（民法13条1項）について保佐人の同意が必要です。日常的な行為は単独で可能です。',"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "意思表示の瑕疵には詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失の第三者は保護）・通謀虚偽表示（無効・善意の第三者は保護）があります。", "example": ""}, "reason": {"text": "被保佐人は判断能力が著しく不十分な者で、全面的な制限ではなく重要な法律行為についてのみ保佐人の同意が必要とされます（民法13条1項）。日常的な行為は自分でできます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "すべての法律行為を保佐人が代理する", "reason": "被保佐人は不動産売買・借財等の重要な行為に保佐人の同意が必要なだけで、日常的な行為は自分でできます（民法13条1項）。", "caution": "成年被後見人（全面的制限）と被保佐人（重要行為のみ制限）を混同しないこと。"}, {"label": "日常的な買い物も保佐人の同意が必要", "reason": "日常的な買い物等は保佐人の同意不要です。不動産売買・100万円超の借財等の重要行為のみ同意が必要です（民法13条1項各号）。", "caution": ""}, {"label": "被保佐人は完全に行為能力を制限される", "reason": "完全な制限は成年被後見人の制度です。被保佐人は重要行為以外は自由に行為できます。", "caution": ""}], "summary": {"head": ["制限行為能力者", "制限の範囲", "取消権者"], "rows": [["未成年者", "原則全て（例外あり）", "本人・法定代理人"], ["成年被後見人", "日常行為以外全て", "本人・後見人"], ["被保佐人", "民法13条1項列挙の重要行為", "本人・保佐人"], ["被補助人", "家裁が定めた行為", "本人・補助人"]]}}},
  {id:10644,unit:'r_ishi',level:2,field:'rights',text:'詐欺による意思表示の取消しと第三者の保護について正しいものはどれか。',opts:['取消しは全ての第三者に対抗できる','取消し前の善意かつ無過失の第三者には対抗できない','取消し後の第三者には登記なしに対抗できる','善意であれば過失があっても保護される'],ans:1,exp:'詐欺取消し前の善意かつ無過失の第三者には取消しを対抗できません（民法96条3項）。取消し後の第三者との関係は対抗問題（登記の先後）で処理されます。',"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "意思表示の瑕疵には詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失の第三者は保護）・通謀虚偽表示（無効・善意の第三者は保護）があります。", "example": ""}, "reason": {"text": "詐欺取消しは善意かつ無過失の第三者を保護します（民法96条3項）。「取消し前」の第三者が対象で、取消し後の第三者との関係は登記の対抗問題となります。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "取消しは全ての第三者に対抗できる", "reason": "詐欺取消しは善意かつ無過失の第三者には対抗できません（民法96条3項）。全員に対抗できるのは強迫取消しです。", "caution": "詐欺＝善意無過失の第三者保護あり、強迫＝保護なし。"}, {"label": "取消し後の第三者には登記なしに対抗できる", "reason": "取消し後の第三者との関係は「対抗問題」となり、登記の先後で決まります（判例）。登記なしでは対抗できません。", "caution": "取消し前の第三者（96条3項）と取消し後の第三者（対抗問題）で扱いが異なります。"}, {"label": "善意であれば過失があっても保護される", "reason": "詐欺取消しの第三者保護は「善意かつ無過失」が必要です（民法96条3項）。善意でも過失があれば保護されません。", "caution": "通謀虚偽表示（善意のみで足る）と詐欺（善意無過失が必要）の違いに注意。"}], "summary": {"head": ["場面", "要件", "根拠"], "rows": [["詐欺取消し・取消し前の第三者", "善意かつ無過失", "民法96条3項"], ["詐欺取消し・取消し後の第三者", "登記の先後", "対抗問題（判例）"], ["強迫取消し・第三者", "保護なし", "民法96条3項の反対解釈"]]}}},
  // 区分所有法（r_kukku）追加
  {id:10645,unit:'r_kukku',level:1,field:'rights',text:'区分所有建物において「専有部分」として認められる要件として正しいものはどれか。',opts:['建物の外壁であれば専有部分になる','構造上の独立性と利用上の独立性を備えた建物の部分','廊下・エレベーターも専有部分にできる','面積が30㎡以上あれば専有部分'],ans:1,exp:'専有部分とは区分所有権の目的となる建物の部分で、構造上区分されていること（構造上の独立性）と独立して住居・店舗等として利用できること（利用上の独立性）の両方を備えた部分です（区分所有法1条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "専有部分として認められるためには①構造上の独立性（壁・床・天井等で他の部分と区画されていること）と②利用上の独立性（独立して居住・店舗等として使用できること）の両方が必要です（区分所有法2条3項・判例）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "建物の外壁であれば専有部分になる", "reason": "外壁は法定共用部分であり（区分所有法11条1項）、専有部分にはなりません。", "caution": "外壁＝共用部分（専有部分にはなれない）。"}, {"label": "廊下・エレベーターも専有部分にできる", "reason": "廊下・エレベーターは法定共用部分です（区分所有法11条1項）。専有部分にはなりません。", "caution": ""}, {"label": "面積が30㎡以上あれば専有部分", "reason": "面積の大小は専有部分の要件ではありません（区分所有法2条3項）。構造上・利用上の独立性が要件です。", "caution": ""}], "summary": {"head": ["専有部分の要件", "内容"], "rows": [["構造上の独立性", "壁・床・天井等で他の部分と区画"], ["利用上の独立性", "独立して居住・店舗等として使用可能"], ["両方必要", "片方だけでは専有部分にならない（判例）"]]}}},
  {id:10646,unit:'r_kukku',level:2,field:'rights',text:'管理組合の集会の招集について正しいものはどれか。',opts:['いつでも任意に開催できる','管理者は毎年1回以上集会を招集しなければならない','区分所有者の過半数の請求があれば翌日に開催しなければならない','集会は書面決議で代替できるため開催不要'],ans:1,exp:'管理者は毎年1回以上集会を招集しなければなりません（区分所有法34条2項）。区分所有者の5分の1以上・議決権の5分の1以上の請求があれば管理者は集会を招集する義務があります。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "管理者は毎年1回以上、定期的に集会を招集しなければなりません（区分所有法34条2項）。また区分所有者の1/5以上の請求があれば臨時集会を招集する義務があります（同条3項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "いつでも任意に開催できる", "reason": "管理者は毎年1回以上の集会招集義務があります（区分所有法34条2項）。「任意」というのは不正確です。", "caution": "管理者＝年1回以上の集会招集義務（区分所有法34条2項）。"}, {"label": "区分所有者の過半数の請求があれば翌日に開催しなければならない", "reason": "1/5以上の請求があれば管理者は集会を招集しなければなりません（区分所有法34条3項）。「翌日」という規定はありません。", "caution": ""}, {"label": "集会は書面決議で代替できるため開催不要", "reason": "書面決議は集会に代えて行うことができますが（区分所有法45条1項）、年1回以上の集会開催義務は別に存在します（同法34条2項）。", "caution": ""}], "summary": {"head": ["集会の招集（区分所有法34条）", "内容"], "rows": [["定期招集", "管理者は年1回以上招集義務"], ["臨時招集", "1/5以上の請求→管理者が招集"], ["管理者が招集しない場合", "請求者自ら招集可（同条4項）"], ["招集通知", "集会日の1週間前までに各区分所有者に通知"]]}}},
  // 不動産登記法（r_touki）追加
  {id:10647,unit:'r_touki',level:1,field:'rights',text:'登記記録の構成として正しいものはどれか。',opts:['表題部のみからなる','表題部（土地・建物の物理的状況）と権利部（甲区・乙区）からなる','権利部のみからなる','所有者部と担保部からなる'],ans:1,exp:'不動産登記記録は表題部（土地・建物の所在・地番・種類・構造・面積等の物理的状況）と権利部（甲区：所有権に関する事項、乙区：所有権以外の権利に関する事項）から構成されます（不動産登記法12条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "登記記録は表題部と権利部から構成されます（不動産登記法2条5号）。表題部は不動産の物理的状況（所在・地番・地目・地積等）を、権利部（甲区・乙区）は所有権や抵当権等の権利関係を記録します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "表題部のみからなる", "reason": "登記記録は表題部と権利部（甲区・乙区）からなります。表題部のみではありません（不動産登記法2条5号）。", "caution": ""}, {"label": "権利部のみからなる", "reason": "表題部と権利部の両方が登記記録を構成します。権利部のみではありません。", "caution": ""}, {"label": "所有者部と担保部からなる", "reason": "このような区分は存在しません。権利部は甲区（所有権）と乙区（所有権以外の権利）に分かれます。", "caution": ""}], "summary": {"head": ["登記記録の構成", "記録内容"], "rows": [["表題部", "土地：所在・地番・地目・地積など、建物：所在・家屋番号・種類・構造・床面積など"], ["権利部甲区", "所有権に関する事項（所有権移転・仮登記・差押等）"], ["権利部乙区", "所有権以外の権利（抵当権・地上権・賃借権等）"]]}}},
  {id:10648,unit:'r_touki',level:2,field:'rights',text:'登記の推定力について正しいものはどれか。',opts:['登記があれば権利の存在が絶対的に証明される','登記がある場合は登記通りの実体関係が存在すると推定されるが、公信力はない','登記は単なる行政上の記録であり法的効力はない','登記は当事者間でのみ効力を持つ'],ans:1,exp:'日本の不動産登記には推定力はありますが公信力はありません。登記を信頼して取引した者でも、真の権利者が別にいる場合は保護されない場合があります（対比：動産の即時取得は公信力あり）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "日本の不動産登記には公示力はありますが公信力はありません（通説・判例）。登記を信頼して取引しても真の権利者でない者から取得した場合、保護されない場合があります。即時取得（民法192条）も不動産には適用されません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "登記があれば権利の存在が絶対的に証明される", "reason": "登記には公信力がないため、登記通りの権利が必ず存在するわけではありません。推定力はありますが絶対的証明力はありません。", "caution": "公信力なし＝登記を信頼しても保護されない場合あり。"}, {"label": "登記は単なる行政上の記録であり法的効力はない", "reason": "登記は対抗要件として法的効力を持ちます（民法177条等）。単なる行政記録ではありません。", "caution": ""}, {"label": "登記は当事者間でのみ効力を持つ", "reason": "登記は第三者への対抗要件として機能します。当事者間だけでなく第三者との関係でも重要です。", "caution": ""}], "summary": {"head": ["登記の効力", "内容"], "rows": [["対抗力", "登記により第三者に権利変動を対抗できる"], ["推定力", "登記通りの実体関係の存在を推定"], ["公信力", "なし（登記を信頼しても保護されない場合あり）"], ["形式的確定力", "なし（実体に反する登記は無効）"]]}}},
  // 借地借家法（r_shakuchi）追加
  {id:10649,unit:'r_shakuchi',level:1,field:'rights',text:'普通借家権の存続期間の最短として正しいものはどれか。',opts:['1年未満は期間の定めのない契約とみなされる','6か月未満は期間の定めのない契約とみなされる','3か月未満は無効','制限なし'],ans:0,exp:'借地借家法上、期間を1年未満と定めた建物賃貸借は期間の定めのない賃貸借とみなされます（借地借家法29条1項）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "普通建物賃貸借では1年未満の存続期間を定めた場合、期間の定めのない契約とみなされます（借地借家法29条1項）。これにより実質的に賃借人の保護が確保されます。定期建物賃貸借には1年未満の制限はありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "6か月未満は期間の定めのない契約とみなされる", "reason": "「1年未満」が期間の定めのない契約とみなされます（借地借家法29条1項）。6か月という基準はありません。", "caution": "普通借家：1年未満→期間の定めのない契約（借地借家法29条1項）。"}, {"label": "3か月未満は無効", "reason": "3か月未満が無効という規定はありません（借地借家法29条1項では1年未満は期間の定めのない契約とみなされます）。", "caution": ""}, {"label": "制限なし", "reason": "普通借家では1年未満は期間の定めのない契約とみなされます（借地借家法29条1項）。「制限なし」は誤りです。", "caution": ""}], "summary": {"head": ["普通借家の期間（借地借家法29条）", "内容"], "rows": [["1年以上", "有効"], ["1年未満", "期間の定めのない契約とみなされる（借地借家法29条1項）"], ["定期借家", "制限なし（1か月でも有効）"]]}}},
  {id:10650,unit:'r_shakuchi',level:2,field:'rights',text:'借家権の対抗要件として正しいものはどれか。',opts:['賃貸借契約書の公証','建物の引渡し','賃借権の登記（のみ）','敷金の支払い'],ans:1,exp:'建物賃借権の対抗要件は「建物の引渡し」です（借地借家法31条）。引渡しを受けていれば賃借権の登記がなくても新所有者等の第三者に対抗できます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "建物賃借権の対抗要件は建物の引渡しです（借地借家法31条1項）。登記は不要で、入居（引渡しを受けること）で対抗力が生じます。これにより賃借人は所有者が変わっても新所有者に賃借権を主張できます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "賃貸借契約書の公証", "reason": "公証は対抗要件ではありません（借地借家法31条1項）。建物の引渡しが対抗要件です。", "caution": "建物賃借権の対抗要件＝引渡し（借地借家法31条1項）。"}, {"label": "賃借権の登記（のみ）", "reason": "賃借権の登記も対抗要件になりますが（民法605条）、借地借家法31条により引渡しだけでも対抗できます。「のみ」は誤りです。", "caution": ""}, {"label": "敷金の支払い", "reason": "敷金の支払いは対抗要件ではありません（借地借家法31条1項）。", "caution": ""}], "summary": {"head": ["建物賃借権の対抗要件", "内容"], "rows": [["借地借家法31条", "建物の引渡しで対抗力発生（登記不要）"], ["民法605条", "賃借権の登記でも対抗可（地主の協力が必要）"], ["効果", "所有者が変わっても新所有者に賃借権を主張できる"]]}}},
  // 相隣関係（r_sorin）追加
  {id:10651,unit:'r_sorin',level:1,field:'rights',text:'民法上の境界線付近の建築制限として正しいものはどれか。',opts:['境界線から30cm以上離して建築しなければならない','境界線から50cm以上離して建築しなければならない','距離制限はない','1m以上離す必要がある'],ans:1,exp:'民法237条により境界線から50cm以上離して建物を築造しなければなりません。ただし建築基準法の防火地域内では外壁を境界線に接して設けることができます（建築基準法65条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "民法は建物を建築する際に境界線から50cm以上離れた場所に建築しなければならないと定めています（民法234条1項）。ただしこれは民法上の規制であり、建築基準法等の規制も別途適用されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "境界線から30cm以上離して建築しなければならない", "reason": "境界線から離す距離は50cm以上です（民法234条1項）。30cmではありません。", "caution": "民法上の建築制限：境界線から50cm以上離す（民法234条1項）。"}, {"label": "距離制限はない", "reason": "民法234条1項により50cm以上離す制限があります。「制限なし」は誤りです。", "caution": ""}, {"label": "1m以上離す必要がある", "reason": "民法上の制限は50cm以上です（民法234条1項）。1mは誤りです。", "caution": ""}], "summary": {"head": ["境界線付近の建築制限", "内容"], "rows": [["民法の規制", "境界線から50cm以上離す（民法234条1項）"], ["窓等の目隠し", "境界線から1m未満に窓・縁側等設置→目隠し設置義務（民法235条）"], ["慣習", "地方の慣習があればそれに従う（民法236条）"]]}}},
  {id:10652,unit:'r_sorin',level:2,field:'rights',text:'隣地使用権（民法209条）について正しいものはどれか（2021年改正後）。',opts:['隣地使用は隣人の同意がなければ一切できない','境界の調査・境界標設置・建物の修繕等のためなら必要な範囲で隣地を使用できる（隣人への通知が原則必要）','隣地使用は無条件に認められる','隣地使用の対価は不要'],ans:1,exp:'2021年民法改正で隣地使用権が拡充されました（民法209条）。境界確認・境界標設置・建物の建築・修繕等の目的があれば必要な範囲で隣地使用が認められます。原則として事前に隣人に通知する必要があります。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "2021年民法改正で隣地使用権の要件・手続が明確化されました（民法209条）。境界の調査・境界標設置・建物の修繕等のために必要な範囲で隣地を使用できますが、原則として隣人への事前通知が必要です（同条3項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "隣地使用は隣人の同意がなければ一切できない", "reason": "必要な範囲での隣地使用は法律上認められており（民法209条1項）、隣人の同意は必須ではありません（通知は必要）。", "caution": "隣地使用権：同意不要・通知が必要（民法209条）。"}, {"label": "隣地使用は無条件に認められる", "reason": "必要な範囲・目的に限られ、隣人への通知が原則必要です（民法209条1項・3項）。「無条件」は誤りです。", "caution": ""}, {"label": "隣地使用の対価は不要", "reason": "隣人が通常受ける損害に対して償金を支払う場合があります（民法209条4項）。「対価不要」は誤りです。", "caution": ""}], "summary": {"head": ["隣地使用権（民法209条・2021年改正）", "内容"], "rows": [["使用できる目的", "境界調査・境界標設置・建物修繕等"], ["通知", "原則として事前に隣人に通知"], ["同意", "不要（ただし通知は必要）"], ["償金", "損害が生じた場合は支払い義務あり（民法209条4項）"]]}}},
  // 免許（l_menkyo）追加
  {id:10653,unit:'l_menkyo',level:1,field:'law',text:'宅建業の免許の種類として正しいものはどれか。',opts:['国土交通大臣免許のみ','都道府県知事免許のみ','国土交通大臣免許（2都道府県以上に事務所）と都道府県知事免許（1都道府県内のみ）の2種類','市町村長免許もある'],ans:2,exp:'宅建業の免許は2以上の都道府県に事務所を設置する場合は国土交通大臣免許、1つの都道府県内にのみ事務所を設置する場合は都道府県知事免許です（宅建業法3条）。',"kaisetsu":{"topic": "宅建業の免許：知事・大臣免許の区別・有効期間5年・欠格事由", "basis": {"text": "1都道府県のみ→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間です。", "example": ""}, "reason": {"text": "宅建業の免許には国土交通大臣免許と都道府県知事免許の2種類があります（宅建業法3条1項）。2以上の都道府県に事務所を設置する場合は大臣免許、1都道府県内のみなら知事免許です。市町村長免許という制度はありません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（拘禁刑以上・特定罰金等）</text></svg>", "choices": [{"label": "国土交通大臣免許のみ", "reason": "1都道府県内のみに事務所がある場合は知事免許で足ります（宅建業法3条1項）。大臣免許のみではありません。", "caution": ""}, {"label": "都道府県知事免許のみ", "reason": "2以上の都道府県に事務所がある場合は大臣免許が必要です（宅建業法3条1項）。知事免許のみではありません。", "caution": ""}, {"label": "市町村長免許もある", "reason": "宅建業の免許に市町村長免許という種類はありません（宅建業法3条1項）。", "caution": ""}], "summary": {"head": ["免許の種類（宅建業法3条1項）", "要件"], "rows": [["都道府県知事免許", "1都道府県内のみに事務所"], ["国土交通大臣免許", "2以上の都道府県に事務所"], ["免許換え", "事務所の増設等で種類が変わる場合に必要"]]}}},
  {id:10654,unit:'l_menkyo',level:2,field:'law',text:'免許換えが必要な場合として正しいものはどれか。',opts:['事務所の移転（同じ都道府県内）','知事免許業者が他の都道府県にも事務所を設置した場合','代表者が変更になった場合','従業員数が増加した場合'],ans:1,exp:'都道府県知事免許を受けた業者が他の都道府県にも事務所を設置した場合は、国土交通大臣免許への免許換えが必要です（宅建業法7条）。同一都道府県内の移転は免許換え不要です。',"kaisetsu":{"topic": "宅建業の免許：知事・大臣免許の区別・有効期間5年・欠格事由", "basis": {"text": "1都道府県のみ→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間です。", "example": ""}, "reason": {"text": "事務所の所在が1つの都道府県から2以上の都道府県にまたがることになった場合は免許換え（知事免許→大臣免許）が必要です（宅建業法7条1項）。同一都道府県内の移転や代表者・従業員変更は変更届で対応します。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（拘禁刑以上・特定罰金等）</text></svg>", "choices": [{"label": "事務所の移転（同じ都道府県内）", "reason": "同一都道府県内の事務所移転は変更届の対象です（宅建業法9条）。免許換えは不要です。", "caution": "同一都道府県内の移転＝変更届（免許換え不要）。"}, {"label": "代表者が変更になった場合", "reason": "代表者の変更は変更届の対象です（宅建業法9条）。免許換えは不要です。", "caution": ""}, {"label": "従業員数が増加した場合", "reason": "従業員数の増加は変更届の対象ではありません（宅建業法9条に従業員数変更の規定なし）。ただし専任宅建士の設置要件に影響します。", "caution": ""}], "summary": {"head": ["免許換えが必要な場合（宅建業法7条）", "内容"], "rows": [["知事免許→大臣免許", "2以上の都道府県に事務所を設置した場合"], ["大臣免許→知事免許", "1都道府県のみになった場合"], ["変更届（免許換え不要）", "同一都道府県内の移転・代表者変更・商号変更等"]]}}},
  // 宅建士（l_takkenshi）追加
  {id:10655,unit:'l_takkenshi',level:1,field:'law',text:'専任の宅建士の設置義務について正しいものはどれか。',opts:['全ての従業員が宅建士でなければならない','事務所では業務に従事する者5名につき1名以上の専任の宅建士が必要','10名につき1名で足りる','宅建士は1事務所に1名いれば足りる'],ans:1,exp:'宅建業者の事務所には業務に従事する者5名につき1名以上の専任の宅建士を置かなければなりません（宅建業法31条の3第1項）。5名未満でも1名以上必要です。',"kaisetsu":{"topic": "専任の宅建士：5人に1人以上・兼任不可・不足時は2週間以内に補充", "basis": {"text": "事務所には業務従事者5人に1人以上の専任宅建士が必要です（宅建業法31条の3）。専任宅建士は1社専属で複数業者の兼任は不可。不足時は2週間以内に補充が必要です。", "example": ""}, "reason": {"text": "事務所ごとに業務に従事する者5名につき1名以上の割合で専任の宅建士を設置しなければなりません（宅建業法31条の3第1項）。全員が宅建士である必要はなく、5分の1以上が専任宅建士であれば足ります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">専任宅建士のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">設置基準</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5人に1人以上（主従同じ）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">兼任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可（1社専属）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不足補充</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間以内</text></svg>", "choices": [{"label": "全ての従業員が宅建士でなければならない", "reason": "全員が宅建士である必要はありません（宅建業法31条の3第1項）。5名に1名以上の専任宅建士で足ります。", "caution": "専任宅建士：5名に1名以上（全員宅建士不要）。"}, {"label": "10名につき1名で足りる", "reason": "10名に1名では不足です（宅建業法31条の3第1項）。5名に1名以上が必要です。", "caution": ""}, {"label": "宅建士は1事務所に1名いれば足りる", "reason": "業務従事者が6名以上の場合は2名以上の専任宅建士が必要です（宅建業法31条の3第1項：5名に1名以上）。", "caution": ""}], "summary": {"head": ["専任宅建士の設置（宅建業法31条の3第1項）", "計算例"], "rows": [["基準", "業務従事者5名に1名以上"], ["5名以下", "1名以上"], ["6〜10名", "2名以上"], ["11〜15名", "3名以上"]]}}},
  {id:10656,unit:'l_takkenshi',level:2,field:'law',text:'宅建士証の返納義務が生じる場合として正しいものはどれか。',opts:['宅建士証の有効期間が満了した時','事務禁止処分を受けた場合（処分期間中は返納）','転職した場合','引越しした場合'],ans:1,exp:'宅建士が事務禁止処分を受けた場合は、処分の期間中、宅建士証を知事に提出（返納）しなければなりません（宅建業法22条の2第7項）。有効期間満了時も更新しない場合は返納が必要です。',"kaisetsu":{"topic": "専任の宅建士：5人に1人以上・兼任不可・不足時は2週間以内に補充", "basis": {"text": "事務所には業務従事者5人に1人以上の専任宅建士が必要です（宅建業法31条の3）。専任宅建士は1社専属で複数業者の兼任は不可。不足時は2週間以内に補充が必要です。", "example": ""}, "reason": {"text": "宅建士が事務禁止処分を受けた場合、処分期間中は宅建士証を登録している都道府県知事に提出しなければなりません（宅建業法22条の2第5項）。処分期間終了後は返還されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">専任宅建士のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">設置基準</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5人に1人以上（主従同じ）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">兼任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可（1社専属）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不足補充</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間以内</text></svg>", "choices": [{"label": "宅建士証の有効期間が満了した時", "reason": "有効期間満了時は返納（失効）ではなく更新申請の機会です。更新しない場合は満了で失効します（宅建業法22条の2第1項）。", "caution": "事務禁止処分中：提出義務（宅建業法22条の2第5項）。有効期間満了：失効（更新しない場合）。"}, {"label": "転職した場合", "reason": "転職は宅建士証の返納義務とは無関係です（宅建業法22条の2第4項参照）。", "caution": ""}, {"label": "引越しした場合", "reason": "転居（住所変更）は変更登録の対象ですが（宅建業法20条）、宅建士証の返納義務は生じません。", "caution": ""}], "summary": {"head": ["宅建士証の提出・返納（宅建業法22条の2）", "場面"], "rows": [["事務禁止処分中", "知事へ提出（同条5項）"], ["登録消除時", "知事へ返納（同条4項）"], ["有効期間満了後（更新しない）", "失効・事実上返納"], ["転職・転居", "提出・返納義務なし"]]}}},
  // 営業保証金（l_hosho）追加
  {id:10657,unit:'l_hosho',level:1,field:'law',text:'営業保証金として供託できるものとして正しいものはどれか。',opts:['現金のみ','現金または国債証券・地方債証券等の有価証券','土地や建物','株式のみ'],ans:1,exp:'営業保証金は現金または国債証券・地方債証券・政府保証債等の有価証券で供託できます（宅建業法25条3項）。有価証券は額面金額で計算されますが、種類により評価率が異なります。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "営業保証金として供託できるのは現金のほか、国債証券・地方債証券・政府保証債等の有価証券です（宅建業法25条3項・施行規則15条の3）。有価証券で供託する場合は額面の一定割合（国債100%・地方債90%等）で計算されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "現金のみ", "reason": "現金のほか有価証券でも供託できます（宅建業法25条3項）。「現金のみ」は誤りです。", "caution": "営業保証金：現金または有価証券（国債・地方債等）で供託可（宅建業法25条3項）。"}, {"label": "土地や建物", "reason": "土地・建物は営業保証金の供託に使用できません（宅建業法25条3項）。", "caution": ""}, {"label": "株式のみ", "reason": "株式は宅建業法施行規則15条の3に規定する有価証券に含まれません。国債・地方債等が認められます。", "caution": ""}], "summary": {"head": ["営業保証金で供託できるもの", "評価額"], "rows": [["現金", "額面通り"], ["国債証券", "額面の100%"], ["地方債証券・政府保証債", "額面の90%"], ["その他有価証券（社債等）", "額面の80%"]]}}},
  {id:10658,unit:'l_hosho',level:2,field:'law',text:'営業保証金の取戻し（供託金の回収）ができる場合として正しいものはどれか。',opts:['事業年度終了時','廃業・免許失効等の場合に、還付請求権者への公告期間（6か月以上）経過後','いつでも取戻せる','還付を受けた者が全員同意した場合'],ans:1,exp:'営業保証金の取戻しは廃業・免許失効等の場合に、還付請求権を有する者への公告（6か月以上）を行い、当該期間内に還付請求がなければ取り戻すことができます（宅建業法30条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "営業保証金の取戻し（回収）は廃業・免許失効等の場合に、還付請求権者への公告期間（6か月以上）が経過した後に行えます（宅建業法30条1項）。取戻し事由なしに任意に取戻すことはできません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "事業年度終了時", "reason": "事業年度終了は取戻し事由ではありません（宅建業法30条1項）。", "caution": "取戻し：廃業・免許失効等＋6か月以上の公告期間経過後（宅建業法30条1項）。"}, {"label": "いつでも取戻せる", "reason": "取戻しには廃業等の事由と公告期間の経過が必要です（宅建業法30条1項）。いつでも取戻せるわけではありません。", "caution": ""}, {"label": "還付を受けた者が全員同意した場合", "reason": "全員同意は取戻しの要件ではありません（宅建業法30条1項）。廃業等の事由と公告期間の経過が要件です。", "caution": ""}], "summary": {"head": ["営業保証金の取戻し（宅建業法30条）", "内容"], "rows": [["取戻し事由", "廃業・免許失効・事務所減少等"], ["公告", "6か月以上の期間を設けた公告が必要"], ["目的", "還付請求権者への保護期間の確保"], ["保証協会の場合", "分担金は保証協会から取戻し申請"]]}}},
  // 媒介契約（l_baikai）追加
  {id:10659,unit:'l_baikai',level:1,field:'law',text:'専任媒介契約の有効期間満了後の更新について正しいものはどれか。',opts:['自動更新できる','依頼者からの申出があった場合のみ更新でき、更新後の期間も3か月以内','更新は無制限に可能','一度締結したら解除できない'],ans:1,exp:'専任媒介契約は依頼者から申出があった場合のみ更新でき、更新後の有効期間も3か月以内です（宅建業法34条の2第4項）。業者側からの自動更新・押しつけ更新は禁止されています。',"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任媒介の有効期間の上限は3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。専任は7日以内、専属専任は5日以内にレインズ登録が必要。業務報告は専任2週間に1回、専属専任1週間に1回。", "example": ""}, "reason": {"text": "専任媒介契約の有効期間は3か月が上限で（宅建業法34条の2第3項）、更新は依頼者からの申し出があった場合のみ可能です（同条3項ただし書）。更新後の期間も3か月以内です。自動更新は認められません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">一般</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専任</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専属専任</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己発見取引</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">レインズ登録</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務報告</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">なし</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間に1回</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1週間に1回</text></svg>", "choices": [{"label": "自動更新できる", "reason": "専任媒介の更新は依頼者からの申し出がある場合のみ可能です（宅建業法34条の2第3項ただし書）。自動更新はできません。", "caution": "専任媒介の更新：依頼者の申し出のみ（自動更新不可）。"}, {"label": "更新は無制限に可能", "reason": "更新は可能ですが、更新後の期間も3か月以内でなければなりません（宅建業法34条の2第3項）。「無制限」は誤りです。", "caution": ""}, {"label": "一度締結したら解除できない", "reason": "媒介契約は依頼者からの解除が可能です（ただし業者の費用等の問題はあります）。「解除できない」は誤りです。", "caution": ""}], "summary": {"head": ["専任媒介の有効期間と更新", "内容"], "rows": [["上限", "3か月（宅建業法34条の2第3項）"], ["3か月超の定め", "3か月とみなされる"], ["更新", "依頼者の申し出のみ（自動更新不可）"], ["更新後の期間", "3か月以内"]]}}},
  {id:10660,unit:'l_baikai',level:2,field:'law',text:'専属専任媒介契約で自己発見取引（依頼者が自分で相手方を見つけた）をした場合について正しいものはどれか。',opts:['自己発見取引は自由にできる','依頼した宅建業者を通さずに直接契約することはできない','違約金を払えば自己発見取引できる','宅建業者の承諾があれば可能'],ans:1,exp:'専属専任媒介契約では依頼者は宅建業者が探した相手方以外とも直接取引することが禁止されています（宅建業法34条の2第9項）。これは専任媒介（自己発見OK）との大きな違いです。',"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任媒介の有効期間の上限は3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。専任は7日以内、専属専任は5日以内にレインズ登録が必要。業務報告は専任2週間に1回、専属専任1週間に1回。", "example": ""}, "reason": {"text": "専属専任媒介契約では依頼者が自ら発見した相手方とも宅建業者を通じて取引しなければなりません（宅建業法34条の2第3項）。直接取引は禁止されており、宅建業者を通じることが義務付けられています。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">一般</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専任</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専属専任</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己発見取引</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">レインズ登録</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務報告</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">なし</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間に1回</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1週間に1回</text></svg>", "choices": [{"label": "自己発見取引は自由にできる", "reason": "専属専任媒介では自己発見取引は禁止されています（宅建業法34条の2第3項）。「自由にできる」は誤りです。", "caution": "専属専任媒介：自己発見取引禁止（宅建業法34条の2第3項）。"}, {"label": "違約金を払えば自己発見取引できる", "reason": "専属専任媒介の自己発見取引禁止は強行規定であり、違約金を払っても直接取引することはできません（宅建業法34条の2第3項）。", "caution": ""}, {"label": "宅建業者の承諾があれば可能", "reason": "宅建業者の承諾があっても、専属専任媒介契約の趣旨上、依頼者が直接取引することは認められません。宅建業者を通じて取引する必要があります。", "caution": ""}], "summary": {"head": ["専属専任媒介と自己発見取引", "内容"], "rows": [["専属専任媒介", "自己発見取引禁止（宅建業法34条の2第3項）"], ["専任媒介", "自己発見取引可"], ["一般媒介", "自己発見取引可"], ["違反の効果", "宅建業者への報酬支払義務が生じる場合あり"]]}}},
  // 重要事項説明（l_jusetsu）追加
  {id:10661,unit:'l_jusetsu',level:1,field:'law',text:'重要事項説明の時期として正しいものはどれか。',opts:['契約締結後速やかに','契約締結前に行わなければならない','引渡し前であればいつでもよい','代金支払い後に行う'],ans:1,exp:'重要事項説明は必ず契約締結前に行わなければなりません（宅建業法35条）。説明を受けた後に買主・借主が契約締結するか否かを判断できるようにするためです。',"kaisetsu":{"topic": "重要事項説明：宅建士が説明・売主への交付は不要・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主への交付義務はありません。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能です。", "example": ""}, "reason": {"text": "重要事項説明は契約締結前に行わなければなりません（宅建業法35条1項）。これにより買主・借主が契約内容・物件の状況等を十分に理解した上で契約するかどうかを判断できます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "契約締結後速やかに", "reason": "重要事項説明は契約締結前に行わなければなりません（宅建業法35条1項）。締結後では意味がありません。", "caution": "重要事項説明：契約締結前（宅建業法35条1項）。"}, {"label": "引渡し前であればいつでもよい", "reason": "引渡し前では遅すぎます。契約締結前に行わなければなりません（宅建業法35条1項）。", "caution": ""}, {"label": "代金支払い後に行う", "reason": "代金支払い後では全く意味がありません。契約締結前に行わなければなりません（宅建業法35条1項）。", "caution": ""}], "summary": {"head": ["各書面の時期", "タイミング"], "rows": [["重要事項説明・35条書面", "契約締結前（宅建業法35条1項）"], ["37条書面（契約書面）", "契約締結後、遅滞なく（宅建業法37条1項）"], ["媒介契約書面", "媒介契約締結後、遅滞なく（宅建業法34条の2第1項）"]]}}},
  {id:10662,unit:'l_jusetsu',level:2,field:'law',text:'賃貸借の重要事項説明で特に記載が必要な事項として正しいものはどれか。',opts:['賃料のみ記載すればよい','台所・浴室・便所等の設備の整備状況・契約期間・更新・定期建物賃貸借の旨等','近隣の賃料相場','建物の将来の価値予想'],ans:1,exp:'建物の賃貸借の重要事項説明には台所・浴室・便所・洗面所等の設備の整備状況、契約終了時の措置、契約期間・更新、定期建物賃貸借である旨等を記載する必要があります（宅建業法35条1項）。',"kaisetsu":{"topic": "重要事項説明：宅建士が説明・売主への交付は不要・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主への交付義務はありません。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能です。", "example": ""}, "reason": {"text": "賃貸借の重要事項説明では台所・浴室・便所等の設備の整備状況、契約期間・更新の条件、定期建物賃貸借である場合はその旨等を記載する必要があります（宅建業法35条1項・施行規則16条の4の3）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "賃料のみ記載すればよい", "reason": "賃料だけでなく設備の整備状況・契約期間・更新条件等も記載が必要です（宅建業法35条1項）。", "caution": ""}, {"label": "近隣の賃料相場", "reason": "近隣の賃料相場は重要事項説明の記載事項ではありません（宅建業法35条1項）。", "caution": ""}, {"label": "建物の将来の価値予想", "reason": "建物の将来価値予想は重要事項説明の記載事項ではありません（宅建業法35条1項）。", "caution": ""}], "summary": {"head": ["賃貸借の重要事項（35条書面・宅建業法35条）", "内容"], "rows": [["設備の整備状況", "台所・浴室・便所等"], ["契約期間", "期間の定め・更新の条件"], ["定期借家", "定期建物賃貸借である旨"], ["敷金等", "敷金・保証金の額と精算方法"]]}}},
  // 37条書面（l_37jo）追加
  {id:10663,unit:'l_37jo',level:1,field:'law',text:'37条書面の交付義務者として正しいものはどれか。',opts:['売主のみ','媒介した宅建業者（売主・買主双方に交付）','買主のみ','公証人'],ans:1,exp:'37条書面は宅建業者が当事者の双方（売主・買主、または貸主・借主）に対して遅滞なく交付しなければなりません（宅建業法37条1項）。媒介の場合も宅建業者が作成して交付します。',"kaisetsu":{"topic": "37条書面：全取引で交付・記名（押印不要）・移転登記申請時期は必要的記載事項", "basis": {"text": "37条書面は売買・交換・賃貸借の全取引で契約の双方当事者に交付が義務（宅建業法37条）。引渡し時期・移転登記申請時期は必要的記載事項。2021年改正で押印は不要になり記名のみで足ります。", "example": ""}, "reason": {"text": "宅建業者が媒介した場合、37条書面の交付義務は媒介した宅建業者が負います（宅建業法37条1項）。売主・買主双方に交付しなければなりません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付義務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全取引・双方当事者</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡時期・移転登記申請時期等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要）</text></svg>", "choices": [{"label": "売主のみ", "reason": "37条書面は売主・買主双方に交付します（宅建業法37条1項）。また交付義務者は媒介した宅建業者です。", "caution": ""}, {"label": "買主のみ", "reason": "37条書面は売主・買主双方に交付します（宅建業法37条1項）。買主のみでは不足です。", "caution": ""}, {"label": "公証人", "reason": "公証人は37条書面とは無関係です（宅建業法37条1項）。", "caution": ""}], "summary": {"head": ["37条書面の交付義務者と交付先", "内容"], "rows": [["交付義務者", "宅建業者（媒介・代理・自ら売主等）"], ["売買の交付先", "売主・買主双方"], ["賃貸借の交付先", "賃貸人・賃借人双方"], ["宅建業者間", "宅建業者間でも交付義務あり"]]}}},
  {id:10664,unit:'l_37jo',level:2,field:'law',text:'37条書面の任意的記載事項（定めがあれば記載）として正しいものはどれか。',opts:['代金の額','物件の所在地','ローン条件（融資利用の場合）・危険負担・瑕疵担保の内容等','引渡し時期'],ans:2,exp:'37条書面の任意的記載事項は定めがある場合にのみ記載すればよい事項で、ローン条件・危険負担の特約・契約不適合責任に関する特約・天災等免責特約等が含まれます。代金・所在地・引渡し時期は必要的記載事項です。',"kaisetsu":{"topic": "37条書面：全取引で交付・記名（押印不要）・移転登記申請時期は必要的記載事項", "basis": {"text": "37条書面は売買・交換・賃貸借の全取引で契約の双方当事者に交付が義務（宅建業法37条）。引渡し時期・移転登記申請時期は必要的記載事項。2021年改正で押印は不要になり記名のみで足ります。", "example": ""}, "reason": {"text": "37条書面の任意的記載事項（定めがある場合に記載）はローン特約・危険負担・瑕疵担保（契約不適合）の定め等です（宅建業法37条1項7号〜11号）。代金の額・物件の所在地・引渡し時期は必要的記載事項です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付義務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全取引・双方当事者</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡時期・移転登記申請時期等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要）</text></svg>", "choices": [{"label": "代金の額", "reason": "代金の額は必要的記載事項です（宅建業法37条1項2号）。任意的ではありません。", "caution": ""}, {"label": "物件の所在地", "reason": "物件の特定に必要な事項（所在・地番等）は必要的記載事項です（宅建業法37条1項1号）。", "caution": ""}, {"label": "引渡し時期", "reason": "引渡し時期は必要的記載事項です（宅建業法37条1項4号）。任意的ではありません。", "caution": ""}], "summary": {"head": ["37条書面の任意的記載事項", "例"], "rows": [["ローンあっせんの定め", "住宅ローン特約等"], ["危険負担", "滅失等のリスク負担の定め"], ["瑕疵担保（契約不適合）の定め", "保証期間等"], ["天災等による損害負担", "自然災害時の責任の定め"], ["契約解除の定め", "違約金・解除条件等"]]}}},
  // クーリングオフ（l_cooling）追加
  {id:10665,unit:'l_cooling',level:1,field:'law',text:'損害賠償の予定額の制限（宅建業法38条）として正しいものはどれか。',opts:['代金の10%以下','代金の20%以下（違約金と合算）','代金の30%以下','制限なし'],ans:1,exp:'宅建業者が自ら売主の場合、損害賠償額の予定と違約金を合算した金額は代金の20%を超えてはなりません（宅建業法38条）。超過した部分は無効です。',"kaisetsu":{"topic": "クーリングオフ：告知日から8日以内・書面で・事務所では不可・全額返還", "basis": {"text": "クーリングオフは告知を受けた日から8日以内に書面で行います（宅建業法37条の2）。事務所・モデルルーム等での申込みはクーリングオフ不可。解除後業者は全額返還（費用控除不可）。", "example": ""}, "reason": {"text": "宅建業者が自ら売主の場合、損害賠償の予定額と違約金の合計は代金の20%を超えてはなりません（宅建業法38条1項）。20%を超える部分の特約は無効です（同条2項）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">クーリングオフのポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">告知日から8日以内</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">方法</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面（発信主義）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所での申込み</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">クーリングオフ不可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除後</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全額返還（費用控除不可）</text></svg>", "choices": [{"label": "代金の10%以下", "reason": "損害賠償の予定額と違約金の合計の上限は20%です（宅建業法38条1項）。10%ではありません。", "caution": "損害賠償予定額・違約金の上限：代金の20%（宅建業法38条1項）。"}, {"label": "代金の30%以下", "reason": "20%が上限です（宅建業法38条1項）。30%は誤りです。", "caution": ""}, {"label": "制限なし", "reason": "20%の上限があります（宅建業法38条1項）。制限なしは誤りです。", "caution": ""}], "summary": {"head": ["損害賠償の予定額の制限（宅建業法38条）", "内容"], "rows": [["上限", "代金の20%（違約金と合算）"], ["超過特約", "20%超の部分は無効"], ["適用場面", "宅建業者自ら売主＋買主が宅建業者でない場合"]]}}},
  {id:10666,unit:'l_cooling',level:2,field:'law',text:'手付額の制限（宅建業法39条）として正しいものはどれか。',opts:['代金の10%以下','代金の20%以下','代金の30%以下','制限なし'],ans:1,exp:'宅建業者が自ら売主の場合、手付金の額は代金の20%を超えてはなりません（宅建業法39条）。これを超える手付を受け取った場合、超過分は無効で返還しなければなりません。',"kaisetsu":{"topic": "クーリングオフ：告知日から8日以内・書面で・事務所では不可・全額返還", "basis": {"text": "クーリングオフは告知を受けた日から8日以内に書面で行います（宅建業法37条の2）。事務所・モデルルーム等での申込みはクーリングオフ不可。解除後業者は全額返還（費用控除不可）。", "example": ""}, "reason": {"text": "宅建業者が自ら売主の場合、手付金の額は代金の20%を超えてはなりません（宅建業法39条1項）。20%を超える特約は超過部分が無効となります（同条3項）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">クーリングオフのポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">告知日から8日以内</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">方法</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面（発信主義）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所での申込み</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">クーリングオフ不可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除後</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全額返還（費用控除不可）</text></svg>", "choices": [{"label": "代金の10%以下", "reason": "手付金の上限は代金の20%です（宅建業法39条1項）。10%ではありません。", "caution": "手付金の額の上限：代金の20%（宅建業法39条1項）。"}, {"label": "代金の30%以下", "reason": "手付金の上限は20%です（宅建業法39条1項）。30%は誤りです。", "caution": ""}, {"label": "制限なし", "reason": "20%の上限があります（宅建業法39条1項）。制限なしは誤りです。", "caution": ""}], "summary": {"head": ["手付金の額の制限（宅建業法39条）", "内容"], "rows": [["上限", "代金の20%（宅建業法39条1項）"], ["超過特約", "超過部分は無効（宅建業法39条3項）"], ["手付の性質", "解約手付（宅建業法39条2項）"], ["適用場面", "宅建業者自ら売主＋買主が宅建業者でない"]]}}},
  // 報酬（l_hoshu）追加
  {id:10667,unit:'l_hoshu',level:1,field:'law',text:'800万円以下の低廉な空家等の売買媒介の場合の報酬特例として正しいものはどれか。',opts:['通常の報酬上限と変わらない','原則の報酬額を超えて30万円（税別）まで報酬を受け取れる場合がある（依頼者への説明と合意が必要）','制限なく報酬を受け取れる','報酬は受け取れない'],ans:1,exp:'宅建業者は売買代金800万円以下の低廉な空家等の売買・交換の媒介をする場合、依頼者への説明と合意を前提に、原則の報酬額を超えて30万円（税別）まで報酬を受け取れる場合があります（宅建業法46条・報酬告示）。',"kaisetsu":{"topic": "報酬：売買は代金×3%+6万（400万超）・賃貸は借賃1か月・上限超過は不可", "basis": {"text": "売買媒介報酬（400万超）の一方からの上限は代金×3%+6万円（税別）。双方合計は一方上限×2。賃貸媒介（居住用・非居住用とも）は借賃1か月分。依頼者の承諾があっても上限超過は不可。", "example": ""}, "reason": {"text": "代金800万円以下の低廉な空家等の売買媒介には報酬特例があり、依頼者への説明と合意を前提に、原則の報酬額を超えて30万円（税別）まで受け取れる場合があります（報酬告示）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対象</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（400万超）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万（一方）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（200万以下）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸（双方合計）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借賃1か月分</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">低廉な空家等（800万円以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円まで（説明・合意要）</text></svg>", "choices": [{"label": "通常の報酬上限と変わらない", "reason": "低廉な空家等には報酬特例があり、原則の報酬額を超えて30万円（税別）まで受け取れる場合があります（報酬告示）。", "caution": "低廉な空家等（800万円以下）の特例：上限30万円（税別）。"}, {"label": "制限なく報酬を受け取れる", "reason": "30万円（税別）という上限があります（報酬告示）。「制限なし」は誤りです。", "caution": ""}, {"label": "報酬は受け取れない", "reason": "報酬告示の特例により、原則の報酬額を超えて30万円（税別）まで受け取れる場合があります。「受け取れない」は誤りです。", "caution": ""}], "summary": {"head": ["低廉な空家等の報酬特例（告示）", "内容"], "rows": [["対象", "代金800万円以下の宅地・建物"], ["適用", "依頼者への説明と合意が必要"], ["上限", "原則の報酬額を超えて30万円（税別）まで受領できる場合あり"], ["要件", "依頼者の承諾"]]}}},
  {id:10668,unit:'l_hoshu',level:2,field:'law',text:'居住用建物以外の賃貸借媒介の報酬上限として正しいものはどれか。',opts:['借賃の0.5か月分','借賃の1か月分','借賃の2か月分','借賃の3か月分'],ans:1,exp:'居住用建物以外の建物（事務所・店舗等）の賃貸借媒介の場合、依頼者双方から受け取る報酬の合計上限は借賃の1か月分（税別）です。居住用と同じ上限ですが依頼者一方から1か月分全額受取りができます。',"kaisetsu":{"topic": "報酬：売買は代金×3%+6万（400万超）・賃貸は借賃1か月・上限超過は不可", "basis": {"text": "売買媒介報酬（400万超）の一方からの上限は代金×3%+6万円（税別）。双方合計は一方上限×2。賃貸媒介（居住用・非居住用とも）は借賃1か月分。依頼者の承諾があっても上限超過は不可。", "example": ""}, "reason": {"text": "居住用建物以外（事務所・店舗・倉庫等）の賃貸借媒介の報酬も、双方合計で借賃の1か月分（税別）が上限です（告示）。居住用・非居住用の区別に関わらず賃貸借媒介の上限は双方合計で1か月分です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対象</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（400万超）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万（一方）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（200万以下）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸（双方合計）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借賃1か月分</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">低廉な空家等（800万円以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円まで（説明・合意要）</text></svg>", "choices": [{"label": "借賃の0.5か月分", "reason": "0.5か月分は一方から受け取れる原則的な上限ですが、双方合計では1か月分です（告示）。", "caution": "賃貸借媒介（居住用・非居住用とも）：双方合計1か月分が上限（告示）。"}, {"label": "借賃の2か月分", "reason": "双方合計の上限は1か月分です（告示）。2か月分は誤りです。", "caution": ""}, {"label": "借賃の3か月分", "reason": "3か月分は誤りです（告示）。1か月分が上限です。", "caution": ""}], "summary": {"head": ["賃貸借媒介の報酬（居住用以外も）", "上限"], "rows": [["居住用建物", "双方合計1か月分（告示）"], ["居住用以外（事務所・倉庫等）", "双方合計1か月分（告示）"], ["共通点", "居住用・非居住用とも上限は同じ"]]}}},
  // 監督処分（l_kantoku）追加
  {id:10669,unit:'l_kantoku',level:1,field:'law',text:'宅建業者に対する指示処分の内容として正しいものはどれか。',opts:['免許を取り消す処分','一定期間の業務停止を命じる処分','業務の適正な運営または取引の公正を確保するため必要な措置を命じる処分','罰金を科す処分'],ans:2,exp:'指示処分は業務の適正な運営または取引の公正を確保するために必要な措置を取るよう命じる行政処分です（宅建業法65条1項）。業務停止・免許取消より軽い処分です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "指示処分は宅建業者に対して業務の適正な運営または取引の公正を確保するため必要な措置を命じる処分です（宅建業法65条1項）。免許取消・業務停止とは異なり、業務を直接制限するものではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "免許を取り消す処分", "reason": "免許取消しは別の処分です（宅建業法66条）。指示処分は業務の適正化のための措置命令です（同法65条1項）。", "caution": ""}, {"label": "一定期間の業務停止を命じる処分", "reason": "業務停止は別の処分です（宅建業法65条2項）。指示処分は業務停止命令ではありません。", "caution": ""}, {"label": "罰金を科す処分", "reason": "指示処分は行政処分であり罰金刑ではありません（宅建業法65条1項）。罰金は刑事罰です（同法82条等）。", "caution": ""}], "summary": {"head": ["指示処分（宅建業法65条1項）", "内容"], "rows": [["内容", "業務の適正な運営・取引の公正確保のための措置を命じる"], ["効果", "業務自体は停止しない（適正化のみ命じる）"], ["違反", "指示処分違反→業務停止処分の対象"], ["権限者", "免許を与えた国交大臣または都道府県知事"]]}}},
  {id:10670,unit:'l_kantoku',level:2,field:'law',text:'宅建業者が受けた行政処分を公表する制度として正しいものはどれか。',opts:['公表制度は存在しない','国土交通大臣・都道府県知事は処分内容を公告しなければならない','公表は任意','業界団体のみが公表する'],ans:1,exp:'国土交通大臣または都道府県知事は指示処分・業務停止処分・免許取消処分を行ったときはその旨を公告しなければなりません（宅建業法70条）。消費者保護のための情報開示です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "国土交通大臣・都道府県知事は宅建業者への監督処分を行った場合、その内容を公告しなければなりません（宅建業法70条1項）。これにより取引の安全・情報の公開が確保されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "公表制度は存在しない", "reason": "公告制度があります（宅建業法70条1項）。「存在しない」は誤りです。", "caution": "処分の公告：国交大臣・都道府県知事が義務（宅建業法70条1項）。"}, {"label": "公表は任意", "reason": "公告は義務です（宅建業法70条1項）。任意ではありません。", "caution": ""}, {"label": "業界団体のみが公表する", "reason": "公告は国交大臣・都道府県知事が行います（宅建業法70条1項）。業界団体が公表する制度とは異なります。", "caution": ""}], "summary": {"head": ["処分の公告（宅建業法70条）", "内容"], "rows": [["義務者", "国土交通大臣・都道府県知事"], ["内容", "処分を行った場合は公告しなければならない"], ["目的", "消費者への情報提供・取引安全の確保"], ["公告方法", "官報・都道府県公報等"]]}}},
  // 住宅瑕疵担保（l_sonota）追加
  {id:10671,unit:'l_sonota',level:1,field:'law',text:'住宅瑕疵担保責任保険の加入先として正しいものはどれか。',opts:['国土交通省','国土交通大臣が指定した住宅瑕疵担保責任保険法人','都道府県','市町村'],ans:1,exp:'住宅瑕疵担保責任保険は国土交通大臣が指定した保険法人（例：住宅保証機構・JIO等）に加入します（住宅瑕疵担保履行法19条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "住宅瑕疵担保責任保険の加入先は国土交通大臣が指定した住宅瑕疵担保責任保険法人です（住宅瑕疵担保履行法2条7項・17条の2）。国土交通省・都道府県・市町村は直接保険を提供しません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "国土交通省", "reason": "国土交通省は保険を直接提供しません。大臣が「住宅瑕疵担保責任保険法人」を指定します（住宅瑕疵担保履行法17条の2）。", "caution": ""}, {"label": "都道府県", "reason": "都道府県ではなく国土交通大臣指定の住宅瑕疵担保責任保険法人です（住宅瑕疵担保履行法17条の2）。", "caution": ""}, {"label": "市町村", "reason": "市町村ではなく国土交通大臣指定の住宅瑕疵担保責任保険法人です（住宅瑕疵担保履行法17条の2）。", "caution": ""}], "summary": {"head": ["住宅瑕疵担保責任保険の加入先", "内容"], "rows": [["加入先", "国土交通大臣指定の住宅瑕疵担保責任保険法人"], ["現行の指定法人", "住宅保証機構・JIO等"], ["根拠", "住宅瑕疵担保履行法17条の2"]]}}},
  {id:10672,unit:'l_sonota',level:2,field:'law',text:'住宅品質確保法（品確法）における「住宅性能表示制度」の利用について正しいものはどれか。',opts:['全ての住宅の取引に義務付けられている','任意の制度で、申請により第三者機関が性能を評価・表示する','国土交通省が直接評価する','性能表示を受けると固定資産税が免除される'],ans:1,exp:'住宅性能表示制度は任意の制度で、事業者が申請することにより登録住宅性能評価機関が設計・建設段階で住宅の性能を評価し表示します（住宅品質確保法5条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "住宅性能表示制度（品確法）は任意の制度であり、義務ではありません（品確法5条）。申請した事業者が国土交通大臣が登録した登録住宅性能評価機関に評価を依頼し、評価書を交付してもらう制度です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "全ての住宅の取引に義務付けられている", "reason": "住宅性能表示制度は任意制度です（品確法5条）。義務ではありません。", "caution": "住宅性能表示制度：任意（品確法5条）。"}, {"label": "国土交通省が直接評価する", "reason": "国土交通大臣が登録した「登録住宅性能評価機関」が評価します（品確法7条）。国土交通省が直接評価するのではありません。", "caution": ""}, {"label": "性能表示を受けると固定資産税が免除される", "reason": "住宅性能表示を受けても固定資産税が免除される制度はありません（品確法）。", "caution": ""}], "summary": {"head": ["住宅性能表示制度（品確法）", "内容"], "rows": [["利用", "任意"], ["評価機関", "国土交通大臣登録の住宅性能評価機関"], ["評価書の種類", "設計住宅性能評価書・建設住宅性能評価書"], ["効果", "住宅ローン金利優遇・重要事項説明での説明義務等"]]}}},
  // 広告規制（l_kokoku）追加
  {id:10673,unit:'l_kokoku',level:1,field:'law',text:'宅建業者が行う広告に関して「おとり広告」とは何か。',opts:['実際には存在しない・取引できない物件を広告すること','価格を安く見せる広告','写真を加工した広告','周辺環境を偽った広告'],ans:0,exp:'おとり広告とは実際には存在しない物件・取引できない物件・既に取引が成立した物件を広告して顧客を集め、別の物件へ誘導する行為です。不当表示として宅建業法・景品表示法で禁止されています。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "おとり広告とは実際には存在しない物件・取引できない物件・成約済みの物件等を広告して顧客を集める行為です（不動産公正競争規約・宅建業法32条）。景品表示法でも規制されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "価格を安く見せる広告", "reason": "価格を実際より安く見せることは誇大広告（宅建業法32条）や不当表示（景品表示法）の問題ですが、おとり広告とは異なります。", "caution": "おとり広告：存在しない・取引できない物件の広告。"}, {"label": "写真を加工した広告", "reason": "写真加工による実際より優良に見せる広告は誇大広告の問題ですが、おとり広告とは異なります。", "caution": ""}, {"label": "周辺環境を偽った広告", "reason": "周辺環境の虚偽表示は誇大広告の問題ですが、おとり広告とは異なります。", "caution": ""}], "summary": {"head": ["おとり広告", "内容"], "rows": [["定義", "存在しない・取引できない・成約済みの物件を広告"], ["規制根拠", "宅建業法32条・景品表示法・不動産公正競争規約"], ["問題点", "顧客を不当に誘引する行為"], ["処分", "行政処分・景品表示法上の措置命令等"]]}}},
  {id:10674,unit:'l_kokoku',level:2,field:'law',text:'未完成物件の広告表示で許容されるものはどれか。',opts:['完成予想図（CGパース）を使用した広告','実際より広く見える写真を使用した広告','周辺環境を実際と異なって表示した広告','開発許可前に行う広告'],ans:0,exp:'未完成物件でも開発許可・建築確認後であれば広告ができます。完成予想図（CGパース）は使用可能ですが、その旨（「完成予想図」等）を明示する必要があります。実際と大きく異なる誇大表示は禁止です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "未完成物件でも完成予想図（CGパース）を使用した広告は、その旨を明示すれば許容されます（不動産公正競争規約等）。ただし実際より広く見える写真・周辺環境の虚偽表示・許可前の広告は禁止されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "実際より広く見える写真を使用した広告", "reason": "実際より優良に誤認させる写真の使用は誇大広告に該当します（宅建業法32条）。", "caution": ""}, {"label": "周辺環境を実際と異なって表示した広告", "reason": "周辺環境の虚偽表示は誇大広告に該当します（宅建業法32条）。", "caution": ""}, {"label": "開発許可前に行う広告", "reason": "開発許可前の広告は広告開始時期制限違反です（宅建業法33条）。", "caution": ""}], "summary": {"head": ["未完成物件の広告で許容されるもの", "条件"], "rows": [["完成予想図（CGパース）", "未完成物件である旨を明示すれば可"], ["モデルルームの写真", "当該物件と同一仕様である旨を表示すれば可"], ["禁止", "開発許可前の広告・誇大表示"]]}}},
  // 最終26問（9610〜9635）
  {id:10675,unit:'t_toroku',level:1,field:'tax',text:'売買による所有権移転登記の登録免許税率として正しいものはどれか。',opts:['0.4%','1.0%','2.0%','3.0%'],ans:2,exp:'売買による所有権移転登記の税率は2.0%です（登録免許税法別表1）。一定の住宅要件を満たす場合は軽減税率0.3%が適用されます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10676,unit:'t_toroku',level:2,field:'tax',text:'法人合併による所有権移転登記の税率として正しいものはどれか。',opts:['2.0%','1.0%','0.4%','0.1%'],ans:2,exp:'法人合併による所有権移転登記の税率は0.4%です（登録免許税法別表1）。相続・合併は売買（2.0%）より低率です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10677,unit:'t_shutoku',level:1,field:'tax',text:'不動産取得税の課税主体として正しいものはどれか。',opts:['国','市町村','都道府県','固定資産評価委員会'],ans:2,exp:'不動産取得税は都道府県が課す地方税です（地方税法73条の2）。市町村税ではありません。',"kaisetsu":{"topic": "不動産取得税：都道府県が課す地方税・相続は非課税・1回だけ課税", "basis": {"text": "不動産取得税は都道府県が課す地方税です（地方税法73条の2）。相続・法人の合併等による取得は非課税。一度の取得に一度だけ課税される（固定資産税と異なり毎年ではない）。標準税率は4%（住宅・土地は3%の軽減あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産取得税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税の頻度</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取得時に1回のみ</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">標準税率</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4%（住宅・土地は3%）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10678,unit:'t_kotei',level:1,field:'tax',text:'固定資産税の課税主体として正しいものはどれか。',opts:['国','都道府県','市町村（東京23区は都）','固定資産評価委員会'],ans:2,exp:'固定資産税は市町村が課す地方税です（地方税法343条）。東京23区内は都が課税します。',"kaisetsu":{"topic": "固定資産税：市町村が課す地方税・賦課期日は1月1日・評価替えは3年ごと", "basis": {"text": "固定資産税は市町村（東京23区は都）が課す地方税です（地方税法343条）。賦課期日は毎年1月1日。評価替えは3年ごと（基準年度）。住宅用地の特例：200㎡以下は課税標準1/6、超過部分は1/3。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">固定資産税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市町村（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賦課期日</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">評価替え</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年ごと</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅用地（200㎡以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税標準1/6</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10679,unit:'t_joto',level:1,field:'tax',text:'不動産を売却した場合の譲渡所得の課税方式として正しいものはどれか。',opts:['他の所得と合算して総合課税される','分離課税（他の所得と合算しない）','源泉分離課税','非課税'],ans:1,exp:'不動産の譲渡所得は他の所得と合算しない申告分離課税です（租税特別措置法31条）。保有期間5年以下が短期（39%）、5年超が長期（20%）で税率が異なります。',"kaisetsu":{"topic": "譲渡所得：分離課税・長期は20%・3,000万円控除は3年に1回", "basis": {"text": "土地・建物の譲渡所得は分離課税（申告分離課税）。長期（5年超）の税率は合計20%（所得税15%+住民税5%）。短期（5年以下）は39%（所得税30%+住民税9%）。3,000万円特別控除は前年・前々年に適用があれば使えません（3年に1回）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">譲渡所得のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税方式</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">分離課税</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">長期（5年超）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計20%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">短期（5年以下）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計39%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3,000万円控除</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年に1回の制限</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10680,unit:'k_toshi',level:1,field:'limit',text:'都市計画区域の指定権者として正しいものはどれか。',opts:['市町村長','都道府県知事（一定の場合は国土交通大臣）','農業委員会','国土交通大臣のみ'],ans:1,exp:'都市計画区域は都道府県が指定します（都市計画法5条1項）。2以上の都府県にわたる場合は国土交通大臣が指定します。',"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域での1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は市街化調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "都市計画区域の指定は原則として都道府県知事が行います（都市計画法5条1項）。複数の都府県にまたがる場合は国土交通大臣が指定します（同条3項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化する区域</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可基準</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "市町村長", "reason": "都道府県知事（一部は国交大臣）が指定します（都市計画法5条1項・3項）。市町村長ではありません。", "caution": ""}, {"label": "農業委員会", "reason": "農業委員会は都市計画区域の指定とは無関係です（都市計画法5条）。", "caution": ""}, {"label": "国土交通大臣のみ", "reason": "原則は都道府県知事です（都市計画法5条1項）。大臣のみではありません。", "caution": ""}], "summary": {"head": ["都市計画区域の指定（都市計画法5条）", "指定者"], "rows": [["1都道府県内のみ", "都道府県知事（同条1項）"], ["複数の都府県にまたがる", "国土交通大臣（同条3項）"]]}}},
  {id:10681,unit:'k_kenchiku',level:1,field:'limit',text:'建築確認が必要な工事として正しいものはどれか。',opts:['外壁の塗り替えのみ','木造2階建て以上または延べ面積500㎡超の建築物の新築','ブロック塀の設置のみ','内装工事のみ'],ans:1,exp:'木造の場合は3階建て以上または延べ面積500㎡超または高さ13m超または軒高9m超の建築物の新築・増改築等に建築確認が必要です（建築基準法6条）。',"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・道路斜線・用途制限", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。用途地域ごとに建築物の制限があります。", "example": ""}, "reason": {"text": "木造2階建て以上または延べ面積500㎡超の建築物の新築は建築確認が必要です（建築基準法6条1項2号）。外壁の塗り替えや内装工事・ブロック塀の単純設置は建築確認不要です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">第1種低層</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">学校は建築可</text></svg>", "choices": [{"label": "外壁の塗り替えのみ", "reason": "外壁の塗り替え（維持修繕）は建築確認不要です（建築基準法6条1項）。", "caution": "木造2階建て以上または500㎡超の新築：確認申請必要（建築基準法6条1項2号）。"}, {"label": "ブロック塀の設置のみ", "reason": "高さ2mを超えるブロック塀の設置は確認申請が必要な場合もありますが、単純なブロック塀設置は原則不要です。", "caution": ""}, {"label": "内装工事のみ", "reason": "内装工事（大規模修繕でないもの）は確認申請不要です（建築基準法6条1項）。", "caution": ""}], "summary": {"head": ["建築確認が必要な工事（建築基準法6条1項）", "内容"], "rows": [["特殊建築物（200㎡超）の新築等", "1号"], ["木造（3階以上または500㎡超等）", "2号"], ["木造以外（3階以上等）", "3号"], ["都市計画区域内の全建築物（新築等）", "4号"]]}}},
  {id:10682,unit:'r_ishi',level:1,field:'rights',text:'成年被後見人が行った法律行為の効力として正しいものはどれか。',opts:['取り消すことができる','当然に無効','有効','後見人が追認すれば有効'],ans:0,exp:'成年被後見人（後見開始の審判を受けた者）が行った法律行為は取り消すことができます（民法9条）。日用品の購入等は例外として有効です。',"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "意思表示の瑕疵には詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失の第三者は保護）・通謀虚偽表示（無効・善意の第三者は保護）があります。", "example": ""}, "reason": {"text": "成年被後見人は日常生活に関する行為以外は取り消すことができます（民法9条）。意思能力が著しく不十分な人を保護するための制度で、「無効」ではなく「取消し」とすることで追認による確定的有効の余地を残しています。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "当然に無効", "reason": "成年被後見人の行為は当然に無効ではなく、取り消すことができる行為です（民法9条）。取消しにより遡及的に無効となります。", "caution": "「無効」と「取消し」の違い：無効＝当然に効力なし、取消し＝取り消すまでは有効。"}, {"label": "有効", "reason": "成年被後見人が日常生活に関する行為以外を単独で行った場合は取消しの対象です（民法9条）。当然に有効とはなりません。", "caution": ""}, {"label": "後見人が追認すれば有効", "reason": "後見人による追認は可能ですが（民法122条）、追認前は取消しの対象です。「後見人が追認すれば有効」という表現は正しいですが、設問の答えとしては「取り消すことができる」が正解です。", "caution": ""}], "summary": {"head": ["行為の種類", "効力"], "rows": [["日常生活に関する行為", "有効（取消し不可）"], ["上記以外の法律行為", "取消しうる行為"], ["後見人の追認後", "確定的に有効"]]}}},
  {id:10683,unit:'r_dairi',level:1,field:'rights',text:'代理権の消滅事由として正しいものはどれか。',opts:['代理人の転居','本人の死亡・破産・代理人の死亡・後見開始の審判等','代理人の結婚','代理の目的物の価値変動'],ans:1,exp:'代理権は①本人の死亡②本人の破産③代理人の死亡④代理人の後見開始の審判・破産等により消滅します（民法111条）。任意代理は本人の死亡・破産で消滅しますが、法定代理は本人の破産では消滅しません。',"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護する制度です。", "example": ""}, "reason": {"text": "代理権の消滅事由は民法111条に定められています。本人・代理人それぞれの死亡や法律上の地位の変化が消滅事由となります。代理は信頼関係に基づくため、当事者に重大な変化があれば代理権も消滅します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "代理人の転居", "reason": "転居（住所変更）は代理権の消滅事由ではありません（民法111条）。", "caution": ""}, {"label": "代理人の結婚", "reason": "代理人の結婚は代理権の消滅事由ではありません（民法111条）。", "caution": ""}, {"label": "代理の目的物の価値変動", "reason": "目的物の価値変動は代理権の消滅事由ではありません（民法111条）。", "caution": ""}], "summary": {"head": ["代理権の消滅事由", "根拠"], "rows": [["本人の死亡", "民法111条1項1号"], ["本人の破産手続開始", "民法111条1項2号"], ["代理人の死亡", "民法111条1項3号"], ["代理人の後見開始の審判", "民法111条1項3号"], ["代理人の破産手続開始", "民法111条1項3号"], ["委任終了", "民法651条（任意代理の基礎となる委任）"]]}}},
  {id:10684,unit:'r_souzoku',level:1,field:'rights',text:'遺産分割協議の成立要件として正しいものはどれか。',opts:['相続人の過半数の同意','相続人全員の合意','家庭裁判所の許可','公証人の認証'],ans:1,exp:'遺産分割協議は共同相続人全員が参加し全員の合意によって成立します（民法907条）。一人でも欠けた協議は無効となります。',"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2", "basis": {"text": "配偶者と子の場合は各1/2（民法900条）。相続放棄は3か月以内に家庭裁判所へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2です（民法1042条）。遺産分割協議は全員合意が必要です。", "example": ""}, "reason": {"text": "遺産分割協議は相続人全員の合意が必要です（民法907条1項）。1人でも欠けると協議は無効です。相続人全員で話し合い、全員が合意して初めて法的に有効な協議が成立します。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続の主要ポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子の相続分</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は法定相続分の1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割協議</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "相続人の過半数の同意", "reason": "遺産分割協議は全員の合意が必要です（民法907条1項）。過半数では不十分です。", "caution": "遺産分割協議は全員の合意が必須。多数決は不可。"}, {"label": "家庭裁判所の許可", "reason": "遺産分割協議に家庭裁判所の許可は原則不要です。協議が調わない場合に調停・審判を申し立てます。", "caution": ""}, {"label": "公証人の認証", "reason": "遺産分割協議書に公証人の認証は必要ありません（民法907条）。実印と印鑑証明書があれば足ります。", "caution": ""}], "summary": {"head": ["遺産分割協議の要件", "内容"], "rows": [["合意", "相続人全員の合意（民法907条1項）"], ["書面", "協議書（任意・ただし実務上必要）"], ["公証人", "不要"], ["協議不成立の場合", "家庭裁判所への調停・審判申立て"]]}}},
  {id:10685,unit:'r_fuhoko',level:1,field:'rights',text:'不法行為の一般的成立要件として不要なものはどれか。',opts:['故意または過失','権利・法律上保護される利益の侵害','損害の発生','契約関係の存在'],ans:3,exp:'不法行為の成立には①故意または過失②権利・法益の侵害③損害の発生④因果関係が必要です（民法709条）。契約関係は不要であり、見知らぬ相手に対する不法行為も成立します。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "不法行為（民法709条）の成立に契約関係の存在は不要です。むしろ不法行為は契約関係がない場合でも（第三者間でも）成立するのが特徴で、契約関係がある場合は債務不履行責任と競合します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "故意または過失", "reason": "故意または過失は不法行為の成立要件です（民法709条）。不要ではありません。", "caution": ""}, {"label": "権利・法律上保護される利益の侵害", "reason": "権利・法益の侵害は不法行為の成立要件です（民法709条）。不要ではありません。", "caution": ""}, {"label": "損害の発生", "reason": "損害の発生は不法行為の成立要件です（民法709条）。不要ではありません。", "caution": ""}], "summary": {"head": ["不法行為の成立要件", "必要か"], "rows": [["故意または過失", "必要（民法709条）"], ["権利・法益の侵害", "必要（民法709条）"], ["損害の発生", "必要（民法709条）"], ["因果関係", "必要（民法709条）"], ["契約関係", "不要（契約なき第三者間でも成立）"]]}}},
  {id:10686,unit:'r_tanpo',level:1,field:'rights',text:'質権と抵当権の最大の違いとして正しいものはどれか。',opts:['質権は不動産にのみ設定できる','質権は目的物を占有する担保、抵当権は占有しない担保','抵当権は動産に設定できる','両者に違いはない'],ans:1,exp:'質権は目的物を債権者（質権者）が占有する占有担保物権、抵当権は目的物を設定者が引き続き使用・収益できる非占有担保物権です（民法342条・369条）。',"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権です（民法369条）。質権は占有の移転が必要です。先取特権は法律上当然に成立する法定担保物権です。", "example": ""}, "reason": {"text": "質権と抵当権の最大の違いは占有移転の有無です（民法344条・369条）。質権者は目的物を占有し、抵当権では設定者が目的物を使い続けることができます。これが住宅ローン（抵当権）で自宅に住み続けられる理由です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・非占有</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・占有</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "質権は不動産にのみ設定できる", "reason": "質権は動産・不動産・権利に設定できます（民法344条以下）。不動産のみではありません。", "caution": ""}, {"label": "抵当権は動産に設定できる", "reason": "抵当権は原則として不動産に設定します（民法369条）。動産に設定することは例外的です（動産抵当は特別法による）。", "caution": ""}, {"label": "両者に違いはない", "reason": "占有移転の有無が最大の違いです。両者は異なる担保物権です。", "caution": ""}], "summary": {"head": ["比較", "質権", "抵当権"], "rows": [["占有移転", "必要（民法344条）", "不要"], ["設定者の使用", "不可（占有を失う）", "可（使い続けられる）"], ["公示", "占有（引渡し）", "登記"], ["主な用途", "動産・権利担保", "不動産担保"]]}}},
  {id:10687,unit:'r_saikensoron',level:1,field:'rights',text:'保証債務の付従性として正しいものはどれか。',opts:['主債務が消滅しても保証債務は残る','主債務が消滅すれば保証債務も消滅する','保証債務は主債務と独立して存在する','保証人は主債務者よりも重い責任を負う'],ans:1,exp:'保証債務は主たる債務を担保するものであり、主債務に付従します（付従性・民法448条）。主債務が弁済等で消滅すれば保証債務も消滅します。また保証人の負担は主債務より重くなりません。',"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要です（民法446条2項）。連帯保証人には催告・検索の抗弁権がありません（民法454条）。債権譲渡の第三者対抗要件は確定日付ある証書による通知または承諾です（民法467条2項）。", "example": ""}, "reason": {"text": "保証債務は主債務に対して付従性を持ちます（民法447条）。主債務が消滅すれば保証債務も消滅し、主債務より重い保証債務は許されません（保証債務の内容は主債務より軽くなければならない）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相殺の要件</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">双方が同種の債権</text></svg>", "choices": [{"label": "主債務が消滅しても保証債務は残る", "reason": "保証債務は付従性により主債務が消滅すれば消滅します（民法447条）。主債務消滅後も残るというのは誤りです。", "caution": "付従性：主債務消滅→保証債務消滅。"}, {"label": "保証債務は主債務と独立して存在する", "reason": "保証債務は主債務に従たる性質（付従性）があり、独立しているわけではありません（民法447条）。", "caution": ""}, {"label": "保証人は主債務者よりも重い責任を負う", "reason": "保証債務の内容は主債務より重くなれません（民法448条1項）。利息・損害賠償・違約金については主債務に関するものに限られます。", "caution": "保証債務≦主債務（主債務より重い保証債務は不可）。"}], "summary": {"head": ["保証債務の付従性", "内容"], "rows": [["成立", "主債務が成立しなければ保証債務も成立しない"], ["消滅", "主債務が消滅すれば保証債務も消滅"], ["範囲", "主債務以下（重くなれない・民法448条）"], ["担保保存義務", "債権者は担保を維持する義務（民法504条）"]]}}},
  {id:10688,unit:'r_baibai',level:1,field:'rights',text:'売買の目的物に契約不適合があった場合の買主の権利として認められないものはどれか。',opts:['追完請求（修補・代替品請求）','代金減額請求','解除','取消し（詐欺や錯誤がない場合でも当然に）'],ans:3,exp:'契約不適合責任に基づく買主の権利は①追完請求②代金減額請求③解除④損害賠償請求です（民法562条〜564条）。詐欺や錯誤がない限り「取消し」という手段はありません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "契約不適合があった場合の買主の権利は追完請求・代金減額請求・損害賠償・解除です（民法562条〜564条）。「取消し」は契約不適合責任の手段ではなく、詐欺・錯誤等の意思表示の瑕疵がある場合に別途認められるものです。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "追完請求（修補・代替品請求）", "reason": "追完請求は認められています（民法562条1項）。誤りではありません。", "caution": ""}, {"label": "代金減額請求", "reason": "代金減額請求は認められています（民法563条）。誤りではありません。", "caution": ""}, {"label": "解除", "reason": "解除は認められています（民法564条・541条・542条）。誤りではありません。", "caution": ""}], "summary": {"head": ["契約不適合責任の手段", "認められるか"], "rows": [["追完請求", "認められる（民法562条）"], ["代金減額請求", "認められる（民法563条）"], ["損害賠償", "認められる（民法564条・415条）"], ["解除", "認められる（民法564条・541条・542条）"], ["取消し", "認められない（詐欺・錯誤等は別途の規定）"]]}}},
  {id:10689,unit:'r_chinshaku',level:1,field:'rights',text:'建物の賃貸借が終了した場合の原状回復義務について正しいものはどれか。',opts:['賃借人は通常損耗（自然損耗）も修繕しなければならない','通常の使用による損耗・経年劣化は原状回復の対象外で、賃借人の故意・過失による損傷が対象','全ての修繕費用は賃貸人負担','賃借人は何も修繕しなくてよい'],ans:1,exp:'原状回復は賃借人が通常の使用を超えて発生させた損傷を回復することです（国土交通省ガイドライン・民法621条）。通常損耗（自然損耗・経年劣化）は賃貸人負担が原則で、賃借人の責任は故意・過失等による損傷に限られます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "原状回復義務は賃借人の故意・過失・善管注意義務違反による損傷が対象です（民法621条）。通常の使用による損耗（経年劣化・通常損耗）は賃貸人負担で原状回復の対象外です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "賃借人は通常損耗（自然損耗）も修繕しなければならない", "reason": "通常損耗は賃貸人負担です（民法621条・国交省ガイドライン）。賃借人の修繕義務は故意・過失等による損傷に限られます。", "caution": "通常損耗＝賃貸人負担。"}, {"label": "全ての修繕費用は賃貸人負担", "reason": "賃借人の故意・過失・善管注意義務違反による損傷は賃借人負担です（民法621条）。全額賃貸人負担ではありません。", "caution": ""}, {"label": "賃借人は何も修繕しなくてよい", "reason": "賃借人の故意・過失等による損傷は原状回復（修繕）の義務があります（民法621条）。", "caution": ""}], "summary": {"head": ["原状回復の負担", "内容"], "rows": [["通常損耗・経年劣化", "賃貸人負担（民法621条）"], ["賃借人の故意・過失による損傷", "賃借人負担"], ["善管注意義務違反（清掃不足等）", "賃借人負担"], ["特約", "明確な合意で変更可（限度あり）"]]}}},
  {id:10690,unit:'r_jiko',level:1,field:'rights',text:'消滅時効における「権利を行使することができる時」（客観的起算点）の例として正しいものはどれか。',opts:['債権者が債権の存在を知った時','弁済期（履行期）が到来した時','契約締結時','登記をした時'],ans:1,exp:'消滅時効の客観的起算点は「権利を行使することができる時」（民法166条1項2号）で、弁済期が定められている債権は弁済期到来時が起算点です。主観的起算点（知った時から5年）との短い方で時効が完成します。',"kaisetsu":{"topic": "消滅時効：知った時から5年または行使可能時から10年", "basis": {"text": "一般の債権の消滅時効は「権利行使できると知った時から5年」または「権利行使できる時から10年」のいずれか早い方で完成します（民法166条1項）。時効は援用して初めて効力が発生します（民法145条）。", "example": ""}, "reason": {"text": "消滅時効の客観的起算点（「権利を行使することができる時」）は権利行使が可能になった時点です（民法166条1項2号）。弁済期（履行期）が到来した時点から権利行使が可能になるため、これが起算点となります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">時効期間</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人の生命・身体への損害</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年または20年</text></svg>", "choices": [{"label": "債権者が債権の存在を知った時", "reason": "これは主観的起算点（「権利を行使できると知った時」・民法166条1項1号）の説明です。客観的起算点は「権利を行使できる時」すなわち弁済期の到来です（同条1項2号）。", "caution": "主観的起算点（知った時・5年）と客観的起算点（行使できる時・10年）を区別しましょう。"}, {"label": "契約締結時", "reason": "契約締結時点では弁済期が未到来の場合があります。弁済期が将来であれば契約締結時は起算点になりません。", "caution": ""}, {"label": "登記をした時", "reason": "登記は消滅時効の起算点とは無関係です。弁済期の到来が起算点です（民法166条）。", "caution": ""}], "summary": {"head": ["消滅時効の起算点", "期間"], "rows": [["主観的起算点：権利行使できると知った時", "5年（民法166条1項1号）"], ["客観的起算点：権利行使できる時（弁済期到来等）", "10年（民法166条1項2号）"], ["適用", "どちらか早い方で時効完成"]]}}},
  {id:10691,unit:'r_bukken',level:1,field:'rights',text:'登記の申請に必要な「登記原因証明情報」として正しいものはどれか。',opts:['戸籍謄本','売買契約書等、登記原因となった法律行為・事実を証する情報','固定資産税評価証明書','住民票'],ans:1,exp:'登記原因証明情報とは登記の原因となった法律行為・事実を証する情報です（不動産登記法61条）。売買の場合は売買契約書、相続の場合は遺産分割協議書・戸籍謄本等が該当します。',"kaisetsu":{"topic": "物権変動：登記が対抗要件・不法占拠者には登記不要", "basis": {"text": "不動産の物権変動は登記が第三者への対抗要件です（民法177条）。不法占拠者には登記なく対抗できます。相続の法定相続分超過部分は登記が必要です（民法899条の2）。", "example": ""}, "reason": {"text": "不動産登記の申請には登記の原因を証する情報の提供が必要です（不動産登記法61条）。登記の真正を確保し、虚偽登記を防止するための重要な制度です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">物権変動の対抗要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対抗要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">二重譲渡</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先に登記した者が優先</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不法占拠者</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記不要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物賃借権</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡し</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続（超過部分）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記必要</text></svg>", "choices": [{"label": "戸籍謄本", "reason": "戸籍謄本は相続による登記の際に相続関係を証明するために使用しますが、売買等の場合の「登記原因証明情報」ではありません。", "caution": ""}, {"label": "固定資産税評価証明書", "reason": "固定資産税評価証明書は登録免許税の課税標準の計算に用いますが、登記の原因を証する情報（売買契約等）ではありません。", "caution": ""}, {"label": "住民票", "reason": "住民票は登記名義人の住所証明情報として添付しますが、登記の原因（売買等の法律行為）を証するものではありません。", "caution": ""}], "summary": {"head": ["添付情報の種類", "内容・用途"], "rows": [["登記原因証明情報", "売買契約書等、登記の原因となる法律行為・事実を証する"], ["登記識別情報", "登記名義人本人であることを確認（旧権利証に相当）"], ["印鑑証明書", "登記義務者の意思確認・本人確認"], ["住所証明情報", "登記名義人の現在の住所を証明（住民票等）"]]}}},
  {id:10692,unit:'r_kukku',level:1,field:'rights',text:'集会の決議が成立するための定足数について正しいものはどれか。',opts:['区分所有者全員が出席しなければならない','議決権の過半数を有する区分所有者の出席（または議決権行使書・代理人）で成立（規約で別段の定め可）','出席者数にかかわらず成立する','3分の2以上の出席が必要'],ans:1,exp:'区分所有法上、集会の議事は区分所有者の議決権の過半数で決します（区分所有法39条1項）。出席者数の定足数規定はありませんが、規約で定めることができます。議決権行使書・代理人による行使も認められます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "集会の成立（定足数）について区分所有法に明文規定はなく、規約で別段の定めができます。実務上は規約で過半数の議決権を有する者の出席等を定めることが多いです。書面・代理人による議決権行使も認められています（区分所有法39条3項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "区分所有者全員が出席しなければならない", "reason": "全員出席は要件ではありません（区分所有法39条）。書面・代理人による議決権行使も認められます（同条3項）。", "caution": ""}, {"label": "出席者数にかかわらず成立する", "reason": "規約で定足数を設けることが多く、「出席者数にかかわらず成立」というのは通常は誤りです。", "caution": ""}, {"label": "3分の2以上の出席が必要", "reason": "区分所有法に3分の2の定足数規定はありません（区分所有法39条）。規約で別段の定めが可能です。", "caution": ""}], "summary": {"head": ["集会の議決（区分所有法39条）", "内容"], "rows": [["議決", "各区分所有者の議決権の過半数で決する（区分所有法39条1項）"], ["代理", "代理人による議決権行使可（同条2項）"], ["書面・電磁的方法", "書面または電磁的方法による議決権行使可（同条3項）"], ["書面決議", "全員の同意で集会に代えることができる（区分所有法45条）"]]}}},
  {id:10693,unit:'r_touki',level:1,field:'rights',text:'建物の表題登記の申請義務について正しいものはどれか。',opts:['任意で申請しなくてよい','新築建物の所有者は取得から1か月以内に表題登記を申請しなければならない','6か月以内でよい','登記は売買時にのみ行えばよい'],ans:1,exp:'新築建物の所有者は建物の取得から1か月以内に表題登記を申請する義務があります（不動産登記法47条）。正当な理由なく怠った場合は10万円以下の過料が科されます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "建物を新築した場合、所有者は取得から1か月以内に建物の表題登記を申請しなければなりません（不動産登記法47条1項）。これは不動産の物理的状況を公示するための制度で、義務違反には10万円以下の過料があります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "任意で申請しなくてよい", "reason": "新築建物の表題登記は義務です（不動産登記法47条1項）。任意ではありません。", "caution": "表題登記は義務。期限は取得から1か月以内。"}, {"label": "6か月以内でよい", "reason": "表題登記の申請期限は取得から1か月以内です（不動産登記法47条1項）。6か月ではありません。", "caution": ""}, {"label": "登記は売買時にのみ行えばよい", "reason": "表題登記は建物を新築した時点で行う義務があります。売買時まで待つことは義務違反です。", "caution": ""}], "summary": {"head": ["表題登記の申請義務", "内容"], "rows": [["申請義務者", "建物を新築して所有権を取得した者"], ["申請期限", "取得から1か月以内"], ["違反の効果", "10万円以下の過料"], ["申請先", "建物所在地の登記所"]]}}},
  {id:10694,unit:'r_shakuchi',level:1,field:'rights',text:'借地権の存続期間満了時に建物がある場合の取扱いとして正しいものはどれか（普通借地権）。',opts:['借地人は直ちに建物を収去して土地を返還しなければならない','借地人は契約の更新を請求でき、建物がある場合は法定更新が認められる','建物は地主の所有となる','借地権は自動的に消滅する'],ans:1,exp:'普通借地権は期間満了時に借地人が契約の更新を請求した場合、または建物があって借地人が土地を使用継続した場合は法定更新されます（借地借家法5条）。地主が更新拒絶するには正当事由が必要です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "普通借地権の存続期間満了時に建物がある場合、借地人は更新を請求でき（借地借家法5条1項）、地主が正当事由のある異議を述べなければ法定更新されます（同条1項・6条）。借地人の財産（建物）を保護するための制度です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "借地人は直ちに建物を収去して土地を返還しなければならない", "reason": "借地人は更新を請求でき、正当事由のある異議がなければ法定更新されます（借地借家法5条1項・6条）。直ちに退去する義務はありません。", "caution": "普通借地権：存続期間満了→更新請求→正当事由なければ法定更新。"}, {"label": "建物は地主の所有となる", "reason": "建物は借地人の所有であり、更新拒絶された場合は建物買取請求権を行使できます（借地借家法13条）。地主の所有にはなりません。", "caution": ""}, {"label": "借地権は自動的に消滅する", "reason": "正当事由のある異議がなければ法定更新されます（借地借家法5条1項）。自動的な消滅はありません。", "caution": ""}], "summary": {"head": ["普通借地権の更新（借地借家法5条・6条）", "内容"], "rows": [["更新請求", "借地人が請求できる"], ["法定更新", "建物がある場合、正当事由ある異議なければ当然更新"], ["正当事由", "地主が更新を拒絶するための要件（借地借家法6条）"], ["建物買取請求権", "更新拒絶時に借地人が地主に時価で買取請求可（借地借家法13条）"]]}}},
  {id:10695,unit:'r_sorin',level:1,field:'rights',text:'公道に至るための他の土地の通行権（囲繞地通行権）について正しいものはどれか。',opts:['他の土地の所有者は通行を拒否できる','公道に至るため他の土地を囲まれている土地の所有者は囲繞地を通行できる（償金が必要な場合あり）','通行権は無償で無制限に認められる','建物がある場合のみ認められる'],ans:1,exp:'囲繞地通行権（民法210条）は公道に至るため他の土地に囲まれた土地の所有者に認められる法定の通行権です。通行の場所・方法は必要最小限で、囲繞地所有者には原則として償金を支払う義務があります（民法212条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "囲繞地通行権（民法210条1項）は公道に出られない袋地の所有者が囲繞地を通行できる法律上の権利です。通行の方法は損害が最も少ない場所・方法に制限され（民法211条1項）、原則として償金が必要です（民法212条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "他の土地の所有者は通行を拒否できる", "reason": "囲繞地通行権は法律上当然に認められる権利であり（民法210条1項）、囲繞地所有者は通行を拒否できません。", "caution": "囲繞地通行権＝法律上当然の権利（囲繞地所有者は拒否不可）。"}, {"label": "通行権は無償で無制限に認められる", "reason": "通行は損害が最も少ない方法・場所に制限され（民法211条1項）、原則として償金が必要です（民法212条）。「無制限・無償」は誤りです。", "caution": ""}, {"label": "建物がある場合のみ認められる", "reason": "囲繞地通行権は土地の利用のために認められる権利であり、建物の有無は直接の要件ではありません（民法210条1項）。", "caution": ""}], "summary": {"head": ["囲繞地通行権（民法210条）", "内容"], "rows": [["根拠", "法律上当然の権利（合意不要）"], ["通行の範囲", "損害が最も少ない方法・場所（民法211条1項）"], ["償金", "原則必要（民法212条）"], ["分割による袋地", "分割した土地のみ通行可・無償（民法213条1項）"]]}}},
  {id:10696,unit:'l_menkyo',level:1,field:'law',text:'宅建業の免許申請から免許の効力発生までの流れとして正しいものはどれか。',opts:['申請と同時に効力が生じる','申請→審査→免許通知→営業保証金の供託→業務開始の順で行う','免許取得後すぐに業務開始できる','保証協会加入後に申請する'],ans:1,exp:'宅建業の免許を取得後、業務を開始するには主たる事務所の最寄りの供託所に営業保証金を供託し、その旨を免許権者に届け出る必要があります（宅建業法25条）。保証協会に加入する場合は分担金納付後に届け出ます。',"kaisetsu":{"topic": "宅建業の免許：知事・大臣免許の区別・有効期間5年・欠格事由", "basis": {"text": "1都道府県のみ→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間です。", "example": ""}, "reason": {"text": "宅建業の開業手続きは免許取得後に営業保証金を供託し、その届出をした後でなければ業務を開始できません（宅建業法25条・26条）。保証協会に加入する場合は弁済業務保証金分担金を納付します（宅建業法64条の9）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（拘禁刑以上・特定罰金等）</text></svg>", "choices": [{"label": "申請と同時に効力が生じる", "reason": "免許の効力は審査・通知後に生じ、さらに営業保証金の供託・届出後でなければ業務を開始できません（宅建業法26条）。申請と同時ではありません。", "caution": ""}, {"label": "免許取得後すぐに業務開始できる", "reason": "免許取得後も営業保証金の供託・届出が必要であり、その後でなければ業務を開始できません（宅建業法25条・26条）。", "caution": "免許取得後：営業保証金供託→届出→業務開始の順（宅建業法25条・26条）。"}, {"label": "保証協会加入後に申請する", "reason": "保証協会への加入は免許取得後に行います（宅建業法64条の2以下）。申請前に加入するのではありません。", "caution": ""}], "summary": {"head": ["宅建業開業の流れ", "内容"], "rows": [["①免許申請", "審査→免許通知"], ["②営業保証金の供託", "主たる事務所1000万円等"], ["③供託の届出", "免許権者へ届出"], ["④業務開始", "届出後に業務開始可能"], ["保証協会加入の場合", "②③を弁済業務保証金分担金の納付に替えることが可能"]]}}},
  {id:10697,unit:'l_takkenshi',level:1,field:'law',text:'宅建士登録の移転について正しいものはどれか。',opts:['宅建士登録は全国共通で移転不要','勤務先の宅建業者の事務所が他の都道府県に変わった場合、登録の移転申請ができる（義務ではない）','転居したら必ず登録移転が必要','登録移転は禁止されている'],ans:1,exp:'宅建士は勤務先等の変更により他の都道府県に変わった場合に登録の移転申請ができます（宅建業法19条の2）。これは義務ではなく任意です。登録移転すると宅建士証の有効期間も引き継がれます（残期間のみ）。',"kaisetsu":{"topic": "専任の宅建士：5人に1人以上・兼任不可・不足時は2週間以内に補充", "basis": {"text": "事務所には業務従事者5人に1人以上の専任宅建士が必要です（宅建業法31条の3）。専任宅建士は1社専属で複数業者の兼任は不可。不足時は2週間以内に補充が必要です。", "example": ""}, "reason": {"text": "宅建士の登録移転は任意であり義務ではありません（宅建業法19条の2）。勤務先の都道府県が変わった場合に申請できますが、移転しなくても登録が消除されることはありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">専任宅建士のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">設置基準</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5人に1人以上（主従同じ）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">兼任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可（1社専属）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不足補充</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間以内</text></svg>", "choices": [{"label": "宅建士登録は全国共通で移転不要", "reason": "登録は都道府県単位であり全国共通ではありませんが、移転は義務ではなく任意です（宅建業法19条の2）。", "caution": "登録移転は任意（義務ではない）。"}, {"label": "転居したら必ず登録移転が必要", "reason": "転居は変更登録（住所変更・宅建業法20条）の対象ですが、都道府県をまたぐ場合でも登録移転は任意です（宅建業法19条の2）。", "caution": ""}, {"label": "登録移転は禁止されている", "reason": "登録移転は宅建業法19条の2で認められています。禁止されてはいません。", "caution": ""}], "summary": {"head": ["登録移転（宅建業法19条の2）", "内容"], "rows": [["義務か", "任意（義務ではない）"], ["できる場合", "他の都道府県の宅建業者に従事する場合"], ["手続き", "現在の登録知事を経由して移転先の知事へ"], ["制限", "事務禁止処分中は移転申請不可"]]}}},
  {id:10698,unit:'l_hosho',level:1,field:'law',text:'営業保証金の額（従たる事務所1か所あたり）として正しいものはどれか。',opts:['100万円','300万円','500万円','1000万円'],ans:2,exp:'営業保証金は主たる事務所1000万円、従たる事務所1か所につき500万円です（宅建業法25条2項）。保証協会加入の場合の分担金は主たる事務所60万円・従たる事務所30万円と大幅に少額です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "営業保証金の額は従たる事務所1か所あたり500万円です（宅建業法施行令2条1項2号）。主たる事務所は1000万円です（同条1項1号）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "100万円", "reason": "従たる事務所の営業保証金は500万円です（宅建業法施行令2条1項2号）。100万円ではありません。", "caution": "従たる事務所の営業保証金＝500万円（1か所あたり）。"}, {"label": "300万円", "reason": "従たる事務所の営業保証金は500万円です（宅建業法施行令2条1項2号）。300万円ではありません。", "caution": ""}, {"label": "1000万円", "reason": "1000万円は主たる事務所の営業保証金額です（宅建業法施行令2条1項1号）。従たる事務所は500万円です（同条1項2号）。", "caution": ""}], "summary": {"head": ["営業保証金の金額", "内容"], "rows": [["主たる事務所", "1000万円"], ["従たる事務所（1か所）", "500万円"], ["計算例（主＋従3）", "1000万円＋500万円×3＝2500万円"], ["保証協会の場合", "主60万円＋従30万円×数"]]}}},
  {id:10699,unit:'l_baikai',level:1,field:'law',text:'媒介契約書面への記名義務者として正しいものはどれか。',opts:['宅建士のみが記名する','宅建業者（法人の場合は代表者等）が記名する','媒介契約書への記名義務はない','依頼者と宅建業者の双方が記名する'],ans:1,exp:'媒介契約書（34条の2の書面）は宅建業者が記名して交付します（宅建業法34条の2第1項）。2021年改正で押印は廃止され記名のみとなりました。重要事項説明書・37条書面は宅建士の記名が必要です。',"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任媒介の有効期間の上限は3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。専任は7日以内、専属専任は5日以内にレインズ登録が必要。業務報告は専任2週間に1回、専属専任1週間に1回。", "example": ""}, "reason": {"text": "34条の2書面（媒介契約書）への記名は宅建業者が行います（宅建業法34条の2第1項）。35条書面・37条書面への記名は宅建士が行う点と混同しないようにしましょう。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">一般</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専任</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専属専任</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己発見取引</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">レインズ登録</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務報告</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">なし</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間に1回</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1週間に1回</text></svg>", "choices": [{"label": "宅建士のみが記名する", "reason": "34条の2書面の記名は宅建業者（代表者等）が行います（宅建業法34条の2第1項）。宅建士が記名するのは35条書面・37条書面です。", "caution": "34条の2書面：宅建業者が記名。35条・37条書面：宅建士が記名。"}, {"label": "媒介契約書への記名義務はない", "reason": "34条の2書面への記名は義務です（宅建業法34条の2第1項）。記名義務なしは誤りです。", "caution": ""}, {"label": "依頼者と宅建業者の双方が記名する", "reason": "34条の2書面に記名するのは宅建業者のみです（宅建業法34条の2第1項）。依頼者も記名するという規定はありません（依頼者に交付するものです）。", "caution": ""}], "summary": {"head": ["各書面の記名義務者", "書面", "記名者"], "rows": [["34条の2書面（媒介契約書）", "宅建業者（宅建業法34条の2第1項）"], ["35条書面（重要事項説明書）", "宅建士（宅建業法35条1項）"], ["37条書面（契約書面）", "宅建士（宅建業法37条3項）"]]}}},
  {id:10700,unit:'l_jusetsu',level:1,field:'law',text:'重要事項説明書（35条書面）への記名義務者として正しいものはどれか。',opts:['宅建業者（会社の代表者）','宅建士（説明した宅建士）','依頼者','公証人'],ans:1,exp:'重要事項説明書には説明を行った宅建士が記名しなければなりません（宅建業法35条5項）。2021年改正で押印が廃止され記名のみとなりました。',"kaisetsu":{"topic": "重要事項説明：宅建士が説明・売主への交付は不要・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主への交付義務はありません。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能です。", "example": ""}, "reason": {"text": "35条書面（重要事項説明書）への記名は、説明を行った宅建士が行わなければなりません（宅建業法35条1項）。宅建業者の代表者や依頼者ではなく、説明した宅建士自身が記名します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "宅建業者（会社の代表者）", "reason": "35条書面の記名義務者は宅建士です（宅建業法35条1項）。代表者ではありません。", "caution": "35条書面への記名：宅建士（宅建業法35条1項）。37条書面への記名も宅建士（同法37条3項）。"}, {"label": "依頼者", "reason": "依頼者（売主・買主等）は35条書面の記名者ではありません（宅建業法35条1項）。", "caution": ""}, {"label": "公証人", "reason": "公証人は35条書面と無関係です（宅建業法35条1項）。", "caution": ""}], "summary": {"head": ["各書面への記名義務者", "書面", "記名者"], "rows": [["35条書面（重要事項説明書）", "宅建士（宅建業法35条1項）"], ["37条書面（契約書面）", "宅建士（宅建業法37条3項）"], ["34条の2書面（媒介契約書）", "宅建業者が記名（宅建業法34条の2第1項）"]]}}},

  // ===== 追加100問（10701〜10800）=====
  {id:10701,unit:'r_ishi',level:2,field:'rights',text:'AがBに対して強迫により売買契約を締結させた場合、取消し後に現れた善意の第三者Cに対してBはどう対抗できるか。',opts:['Cが善意であれば対抗できない','強迫の場合は善意の第三者にも取消しを対抗できる','登記を備えた場合のみ対抗できる','Cが悪意の場合のみ対抗できる'],ans:1,exp:'強迫による取消しは善意の第三者にも対抗できます（民法96条3項の反対解釈）。被強迫者保護のため第三者保護規定は適用されません。取消し後の第三者との関係は登記の先後で決します。',"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "意思表示の瑕疵には詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失の第三者は保護）・通謀虚偽表示（無効・善意の第三者は保護）があります。", "example": ""}, "reason": {"text": "強迫取消しは被害者に全く落ち度がなく、取消しを誰にでも対抗できます（民法96条3項の反対解釈）。詐欺と異なり取消し後の善意の第三者にも対抗できるため、取消し後に現れたCにも対抗できます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "Cが善意であれば対抗できない", "reason": "強迫取消しはCの善意悪意を問わず対抗できます。詐欺と異なり第三者保護規定がありません（民法96条3項は詐欺のみ）。", "caution": "詐欺＝善意無過失の第三者保護あり、強迫＝第三者保護なし。"}, {"label": "登記を備えた場合のみ対抗できる", "reason": "強迫取消しは登記の有無を問わず誰にでも対抗できます。", "caution": ""}, {"label": "Cが悪意の場合のみ対抗できる", "reason": "強迫取消しはCの善意悪意にかかわらず対抗できます。悪意の場合のみという限定はありません。", "caution": ""}], "summary": {"head": ["取消し原因", "取消し前の第三者", "取消し後の第三者"], "rows": [["詐欺", "善意無過失→保護", "登記の対抗問題"], ["強迫", "誰でも対抗可", "誰でも対抗可"]]}}},
  {id:10702,unit:'r_dairi',level:2,field:'rights',text:'制限行為能力者が代理人として行った法律行為の効力について正しいものはどれか。',opts:['制限行為能力者は代理人になれない','制限行為能力者が代理人としてした行為は行為能力の制限を理由に取り消せない','制限行為能力者の代理行為は当然に無効','本人が同意した場合のみ有効'],ans:1,exp:'制限行為能力者を代理人とした場合、その代理行為は行為能力の制限を理由として取り消すことができません（民法102条）。代理行為の効果は本人に帰属するため本人を保護する必要がないからです。',"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護する制度です。", "example": ""}, "reason": {"text": "制限行為能力者も代理人になることができます（民法102条）。代理は本人への効果帰属を目的とするため、代理人自身の能力制限は問題にならないとされています。代理行為の効果は本人に帰属し、本人が不利益を受けないからです。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "制限行為能力者は代理人になれない", "reason": "制限行為能力者も代理人になることができます（民法102条）。代理の効果は本人に帰属するため、代理人の行為能力は問題になりません。", "caution": "制限行為能力者でも代理人になれます（民法102条）。"}, {"label": "制限行為能力者の代理行為は当然に無効", "reason": "制限行為能力者の代理行為は有効であり、行為能力の制限を理由に取り消せません（民法102条）。", "caution": ""}, {"label": "本人が同意した場合のみ有効", "reason": "本人の同意がなくても制限行為能力者の代理行為は有効です（民法102条）。本人の同意は不要です。", "caution": ""}], "summary": {"head": ["制限行為能力者の代理", "内容"], "rows": [["代理人となれるか", "なれる（民法102条）"], ["代理行為の効力", "有効（行為能力制限を理由に取消不可）"], ["例外", "成年後見人が被後見人を代理する場合等の法定代理は別規定"]]}}},
  {id:10703,unit:'r_jiko',level:2,field:'rights',text:'保証人が主債務者のために弁済した場合の時効の承認の効力として正しいものはどれか。',opts:['保証人の承認は主債務者にも時効更新の効力が及ぶ','保証人の承認は主債務者には及ばず相対的効力のみ','連帯保証人の承認は主債務の時効を更新する','保証人の弁済は時効に何の影響もない'],ans:1,exp:'保証人が主債務の時効を承認しても、その効力は主債務者には及びません（相対的効力）。時効の承認の効果は承認をした者に限られます（民法152条）。',"kaisetsu":{"topic": "消滅時効：知った時から5年または行使可能時から10年", "basis": {"text": "一般の債権の消滅時効は「権利行使できると知った時から5年」または「権利行使できる時から10年」のいずれか早い方で完成します（民法166条1項）。時効は援用して初めて効力が発生します（民法145条）。", "example": ""}, "reason": {"text": "時効の更新（承認等）の効力は相対的です（民法148条3項等類推・判例）。保証人の承認は保証人自身についてのみ効力を持ち、主債務者の時効には影響しません。これは連帯関係にある者の時効の独立性を認める考え方です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">時効期間</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人の生命・身体への損害</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年または20年</text></svg>", "choices": [{"label": "保証人の承認は主債務者にも時効更新の効力が及ぶ", "reason": "時効の更新は相対的効力であり、保証人の承認は主債務者には及びません（民法457条1項は逆方向：主債務者の時効更新は保証人に効力が及ぶ）。", "caution": "主債務者の承認→保証人にも効力。保証人の承認→主債務者には及ばない。"}, {"label": "連帯保証人の承認は主債務の時効を更新する", "reason": "連帯保証人の承認も主債務者の時効更新には及びません（判例）。主債務者の行為が保証人に影響するのであり、逆は原則ありません。", "caution": ""}, {"label": "保証人の弁済は時効に何の影響もない", "reason": "保証人の一部弁済は「承認」として保証債務の時効を更新します（民法152条）。「何の影響もない」は誤りです。", "caution": ""}], "summary": {"head": ["承認の方向", "主債務者への効力"], "rows": [["主債務者が承認", "保証人にも効力（民法457条1項）"], ["保証人が承認", "主債務者には及ばない（相対効・判例）"], ["連帯保証人が承認", "主債務者には及ばない（相対効・判例）"]]}}},
  {id:10704,unit:'r_tanpo',level:2,field:'rights',text:'賃料を被担保債権とする抵当権の物上代位について正しいものはどれか。',opts:['賃料への物上代位は認められない','抵当権の物上代位として賃料債権に差押えをすることで賃料から優先弁済を受けることができる','賃料の物上代位には競売開始が必要','賃料物上代位は賃借人の同意が必要'],ans:1,exp:'判例により、抵当不動産の賃料債権に対して物上代位が認められています。払渡し前に差押えが必要で（民法304条）、これにより抵当権者は賃料から優先弁済を受けることができます。',"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権です（民法369条）。質権は占有の移転が必要です。先取特権は法律上当然に成立する法定担保物権です。", "example": ""}, "reason": {"text": "抵当権の物上代位として賃料債権への差押えが認められています（民法372条・304条・判例）。抵当不動産が賃貸されている場合、被担保債権の不履行後に賃料債権に差押えすることで賃料から優先弁済を受けることができます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・非占有</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・占有</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "賃料への物上代位は認められない", "reason": "賃料への物上代位は判例・通説で認められています（最判平成元年10月27日）。「認められない」は誤りです。", "caution": "賃料への物上代位は認められています（判例）。"}, {"label": "賃料の物上代位には競売開始が必要", "reason": "物上代位は競売開始とは独立した手段です（民法304条）。競売開始がなくても差押えによる物上代位が可能です。", "caution": ""}, {"label": "賃料物上代位は賃借人の同意が必要", "reason": "物上代位は賃借人の同意なく行使できます（民法304条）。差押えが要件です。", "caution": ""}], "summary": {"head": ["賃料への物上代位", "内容"], "rows": [["根拠", "民法372条・304条・判例（最判平成元年）"], ["要件", "払渡し前（賃借人がまだ賃料を支払う前）に差押え"], ["効果", "賃借人は差押え後は抵当権者に賃料を支払う"], ["競売との関係", "独立した手段（競売と並行または代わりに利用可）"]]}}},
  {id:10705,unit:'r_saikensoron',level:2,field:'rights',text:'連帯保証と通常の保証の最大の違いとして正しいものはどれか。',opts:['連帯保証人には催告の抗弁権・検索の抗弁権がある','連帯保証人には催告の抗弁権・検索の抗弁権・分別の利益がない','連帯保証人は主債務者と全く同一の義務を負う','連帯保証は書面でなくても成立する'],ans:1,exp:'連帯保証人は催告の抗弁権・検索の抗弁権・分別の利益がありません（民法454条）。これが通常の保証との最大の違いです。',"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要です（民法446条2項）。連帯保証人には催告・検索の抗弁権がありません（民法454条）。債権譲渡の第三者対抗要件は確定日付ある証書による通知または承諾です（民法467条2項）。", "example": ""}, "reason": {"text": "連帯保証は催告の抗弁権・検索の抗弁権・分別の利益がなく（民法454条）、主債務者と同等の責任を負います。これが通常の保証との最大の違いです。連帯保証人は債権者から直接・全額の請求を受けることになります。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相殺の要件</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">双方が同種の債権</text></svg>", "choices": [{"label": "連帯保証人には催告の抗弁権・検索の抗弁権がある", "reason": "連帯保証人には催告の抗弁権も検索の抗弁権もありません（民法454条）。", "caution": "連帯保証人：抗弁権なし（民法454条）。"}, {"label": "連帯保証人は主債務者と全く同一の義務を負う", "reason": "連帯保証人は主債務者と「同一の」義務ではなく「同等の」責任を負います。保証人としての独自の抗弁（主債務の消滅時効等）は主張できます。", "caution": ""}, {"label": "連帯保証は書面でなくても成立する", "reason": "連帯保証も保証契約の一種であり書面が必要です（民法446条2項）。「書面不要」は誤りです。", "caution": ""}], "summary": {"head": ["保証の種類", "催告抗弁", "検索抗弁", "分別の利益"], "rows": [["単純保証", "あり", "あり", "あり"], ["連帯保証", "なし", "なし", "なし"], ["連帯保証の効果", "債権者は直接・全額を連帯保証人に請求可"]]}}},
  {id:10706,unit:'r_baibai',level:2,field:'rights',text:'売買契約において特約で契約不適合責任を免除した場合の効力として正しいものはどれか。',opts:['免除特約は常に有効','売主が知りながら告げなかった不適合については免除特約の効力は及ばない','宅建業者の場合は免除特約が有効','免除特約があれば買主はいかなる権利も行使できない'],ans:1,exp:'売主が知りながら告げなかった契約不適合については、免除・制限特約の効力は及びません（民法572条）。自ら知っている欠陥を隠して免責を主張することは認められません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "契約不適合責任の免除特約は原則有効ですが、売主が知りながら告げなかった不適合については免除特約の効力が及びません（民法572条）。告知義務違反には免責が認められないという信義則的な規定です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "免除特約は常に有効", "reason": "売主が知りながら告げなかった不適合には免除特約が及びません（民法572条）。「常に有効」は誤りです。", "caution": "知りながら告げなかった不適合→免責特約無効（民法572条）。"}, {"label": "宅建業者の場合は免除特約が有効", "reason": "宅建業者が自ら売主の場合、引渡しから2年以上は有効ですが（宅建業法40条）、知りながら告げなかった不適合には民法572条が適用され免責されません。", "caution": ""}, {"label": "免除特約があれば買主はいかなる権利も行使できない", "reason": "知りながら告げなかった不適合には免除特約の効力が及びません（民法572条）。「いかなる権利も行使できない」は誤りです。", "caution": ""}], "summary": {"head": ["免除特約と例外（民法572条）", "内容"], "rows": [["原則", "免除特約有効"], ["例外", "売主が知りながら告げなかった不適合→免責無効（民法572条）"], ["宅建業者の特則", "引渡しから2年以上の特約は有効（宅建業法40条）"]]}}},
  {id:10707,unit:'r_chinshaku',level:1,field:'rights',text:'借地権者が地主の承諾なしに建物を増改築した場合の効果として正しいものはどれか。',opts:['契約違反であるが解除はできない','契約に増改築禁止特約があれば解除の原因となりうる','増改築は常に自由にできる','地主の事後承諾があれば遡及的に有効になる'],ans:1,exp:'借地契約に増改築禁止特約がある場合、無断増改築は契約違反となり解除の原因となります。ただし解除には信頼関係破壊の程度が必要です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "借地契約に増改築禁止特約がある場合、賃借人が無断で増改築すると解除事由となりえます（借地借家法17条参照）。ただし信頼関係破壊の法理により、軽微な増改築では解除が認められない場合もあります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "契約違反であるが解除はできない", "reason": "増改築禁止特約違反は解除事由となりえます。「解除はできない」は誤りです。", "caution": ""}, {"label": "増改築は常に自由にできる", "reason": "増改築禁止特約があれば地主の承諾なく増改築することはできません（借地借家法17条）。", "caution": "増改築禁止特約がある場合→地主の承諾が必要。"}, {"label": "地主の事後承諾があれば遡及的に有効になる", "reason": "事後承諾の法的効果は遡及的有効化ではなく、以後の解除権の消滅です。遡及的有効化という考え方は一般的ではありません。", "caution": ""}], "summary": {"head": ["借地と増改築", "内容"], "rows": [["増改築禁止特約がある場合", "地主の承諾が必要"], ["無断増改築の効果", "解除事由となりえる（信頼関係破壊の程度による）"], ["借地借家法17条", "裁判所が地主に代わって増改築許可を与えることができる（借地権者の申立て）"]]}}},
  {id:10708,unit:'r_souzoku',level:2,field:'rights',text:'相続分の譲渡について正しいものはどれか。',opts:['相続分の譲渡は禁止されている','相続分の譲渡は相続人間でのみ可能','相続分は相続人以外の第三者にも譲渡できる','相続分の譲渡には家庭裁判所の許可が必要'],ans:2,exp:'相続分は相続人以外の第三者にも譲渡することができます（民法905条）。ただし他の相続人は一定期間内に対価を支払って相続分を取り戻すことができます（相続分の取戻権）。',"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2", "basis": {"text": "配偶者と子の場合は各1/2（民法900条）。相続放棄は3か月以内に家庭裁判所へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2です（民法1042条）。遺産分割協議は全員合意が必要です。", "example": ""}, "reason": {"text": "相続分は第三者にも譲渡できます（民法905条1項）。相続分の譲渡は遺産分割前にその相続人の地位ごと譲渡するもので、相続人でない第三者が相続分を取得して遺産分割に参加できます。他の相続人は取戻権を行使できます（同条1項・2項）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続の主要ポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子の相続分</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は法定相続分の1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割協議</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "相続分の譲渡は禁止されている", "reason": "相続分の譲渡は認められています（民法905条1項）。禁止はされていません。", "caution": ""}, {"label": "相続分の譲渡は相続人間でのみ可能", "reason": "相続分は第三者にも譲渡できます（民法905条1項）。相続人間に限定されません。", "caution": ""}, {"label": "相続分の譲渡には家庭裁判所の許可が必要", "reason": "相続分の譲渡に家庭裁判所の許可は不要です（民法905条1項）。ただし他の相続人は1か月以内に取戻権を行使できます（同条2項）。", "caution": ""}], "summary": {"head": ["相続分の譲渡", "内容"], "rows": [["譲渡先", "相続人・第三者いずれも可（民法905条1項）"], ["他の相続人の保護", "取戻権（1か月以内・民法905条2項）"], ["効果", "譲受人が相続人の地位を取得して遺産分割に参加"], ["登記", "不動産の場合は別途所有権移転登記が必要"]]}}},
  {id:10709,unit:'r_fuhoko',level:2,field:'rights',text:'名誉毀損による不法行為の特則として正しいものはどれか。',opts:['財産的損害のみ賠償請求できる','慰謝料も請求でき原状回復措置（謝罪広告等）の請求も認められる','名誉毀損は不法行為にならない','故意の場合のみ損害賠償できる'],ans:1,exp:'名誉毀損等の人格権侵害では財産的損害・精神的損害（慰謝料）の賠償請求ができ、裁判所は名誉回復のための適当な処分（謝罪広告等）を命じることもできます（民法723条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "名誉毀損は財産的損害だけでなく精神的損害（慰謝料）も請求できます（民法710条）。また名誉回復に適当な措置（謝罪広告等）の請求も認められています（民法723条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "財産的損害のみ賠償請求できる", "reason": "名誉毀損では財産的損害のほか精神的損害（慰謝料）も請求できます（民法710条）。", "caution": "精神的損害（慰謝料）も請求可（民法710条）。"}, {"label": "名誉毀損は不法行為にならない", "reason": "名誉毀損は不法行為です（民法709条・710条・723条）。財産的・精神的損害の賠償および名誉回復措置を請求できます。", "caution": ""}, {"label": "故意の場合のみ損害賠償できる", "reason": "過失による名誉毀損も不法行為として損害賠償の対象となります（民法709条）。故意のみに限定されません。", "caution": ""}], "summary": {"head": ["名誉毀損の救済手段", "根拠"], "rows": [["財産的損害の賠償", "民法709条"], ["精神的損害（慰謝料）", "民法710条"], ["名誉回復措置（謝罪広告等）", "民法723条"], ["差止請求", "判例上認められる場合あり"]]}}},
  {id:10710,unit:'r_shakuchi',level:2,field:'rights',text:'建物買取請求権（借地借家法13条）について正しいものはどれか。',opts:['借地契約更新拒絶時に借地人が地主に建物を時価で買い取ることを請求できる権利','地主が借地人に建物を買い取るよう請求できる権利','期間満了に関係なく行使できる','地主の合意が必要な権利'],ans:0,exp:'建物買取請求権は、借地契約の更新が拒絶された場合に借地人が地主に対して借地上の建物を時価で買い取ることを請求できる権利です（借地借家法13条1項）。形成権であり地主の承諾は不要です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "建物買取請求権（借地借家法13条）は、借地契約の更新拒絶時等に借地人が地主に対し建物を時価で買い取ることを請求できる権利です。形成権であり、請求することで地主の同意なく売買契約が成立します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "地主が借地人に建物を買い取るよう請求できる権利", "reason": "建物買取請求権は「借地人が地主に」買取を請求する権利です（借地借家法13条）。地主から借地人への請求ではありません。", "caution": "建物買取請求権：借地人→地主への請求（借地借家法13条）。"}, {"label": "期間満了に関係なく行使できる", "reason": "建物買取請求権は原則として存続期間満了時（更新拒絶時等）に行使できます（借地借家法13条1項）。いつでも行使できるわけではありません。", "caution": ""}, {"label": "地主の合意が必要な権利", "reason": "建物買取請求権は形成権であり、借地人が請求するだけで売買契約が成立します（借地借家法13条）。地主の合意は不要です。", "caution": ""}], "summary": {"head": ["建物買取請求権（借地借家法13条）", "内容"], "rows": [["権利者", "借地人（地主に請求する）"], ["行使時期", "存続期間満了（更新拒絶時等）"], ["価格", "時価"], ["法的性質", "形成権（地主の同意不要・請求で売買成立）"]]}}},
  {id:10711,unit:'r_kukku',level:2,field:'rights',text:'区分所有建物の管理費の滞納について正しいものはどれか。',opts:['管理組合は滞納者の専有部分を競売できる','管理組合は特定承継人（新たな区分所有者）にも未払い管理費を請求できる','管理費の滞納は損害賠償のみが認められる','管理費請求権の時効は20年'],ans:1,exp:'管理費等の債権は区分所有者の特定承継人（売買等で所有権を取得した者）に対しても行使できます（区分所有法8条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "管理費等の滞納がある場合、管理組合は特定承継人（中古売買等により新たに区分所有者となった者）にも未払い管理費を請求できます（区分所有法8条）。区分所有権の売買により管理費の支払義務が引き継がれる制度です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "管理組合は滞納者の専有部分を競売できる", "reason": "管理費滞納者への競売は区分所有法59条に規定がありますが、一定の手続き（集会決議等）が必要です。「直ちに競売できる」は誤りです。", "caution": "管理費滞納者への競売：集会の3/4以上の決議が必要（区分所有法59条）。"}, {"label": "管理費の滞納は損害賠償のみが認められる", "reason": "損害賠償のほか特定承継人への請求・競売請求等も認められます（区分所有法8条・59条）。「のみ」は誤りです。", "caution": ""}, {"label": "管理費請求権の時効は20年", "reason": "管理費請求権の消滅時効は一般の債権として5年です（民法166条）。20年ではありません。", "caution": ""}], "summary": {"head": ["管理費等の未払い（区分所有法8条）", "内容"], "rows": [["特定承継人への請求", "新区分所有者にも請求可（区分所有法8条）"], ["訴訟による回収", "少額訴訟・支払督促等の利用"], ["競売請求", "3/4以上の集会決議＋裁判手続き（区分所有法59条）"], ["先取特権", "管理費等は先取特権として保護される場合あり"]]}}},
  {id:10712,unit:'r_touki',level:2,field:'rights',text:'登記申請時に必要な「登記識別情報」について正しいものはどれか。',opts:['登記申請後に法務局から送られてくるもので次回の登記に必要','登記完了後に通知される英数字のパスワードで紛失しても再発行されない','登記識別情報は誰でも閲覧できる','登記識別情報は紙の権利書と同じ'],ans:1,exp:'登記識別情報は登記完了後に登記権利者に通知される12桁の英数字情報です（不動産登記法21条）。紛失・失念しても再発行されないため厳重に管理する必要があります。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "登記識別情報は登記名義人の本人確認に使用する12桁の英数字で構成された情報です（不動産登記法2条14号）。一度通知されると再発行はされないため、厳重に管理する必要があります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "登記申請後に法務局から送られてくるもので次回の登記に必要", "reason": "登記識別情報は登記完了後に通知されますが、「登記申請後に送られてくる」という表現は誤解を招きます。正確には登記完了時に通知され、次回の登記申請時の本人確認に使用します。", "caution": ""}, {"label": "登記識別情報は誰でも閲覧できる", "reason": "登記識別情報は秘密情報であり、登記名義人本人のみが知ることができます。誰でも閲覧できる情報ではありません。", "caution": "登記識別情報は秘密。登記簿（登記事項証明書）は誰でも閲覧可能です。"}, {"label": "登記識別情報は紙の権利書と同じ", "reason": "登記識別情報は旧来の「権利証（登記済証）」に代わるものですが、紙ではなく英数字のコードです。", "caution": ""}], "summary": {"head": ["登記識別情報", "内容"], "rows": [["形式", "12桁の英数字（コード）"], ["通知時期", "登記完了後に登記名義人に通知"], ["再発行", "不可（紛失しても再発行なし）"], ["利用場面", "次回の登記申請時の本人確認"]]}}},
  {id:10713,unit:'r_sorin',level:1,field:'rights',text:'竹木の枝・根の越境について正しいものはどれか（2021年改正後）。',opts:['隣地の竹木の枝・根はいつでも自由に切除できる','根は自己の費用で切除できるが枝は原則として竹木の所有者に切除を請求する必要がある','枝も根も自由に切除できる','越境した場合は損害賠償のみ'],ans:1,exp:'2021年民法改正で竹木越境ルールが明確化されました（民法233条）。根は自ら切除できますが、枝は原則として所有者に切除を請求します。ただし所有者が不明・催告後相当期間経過・急迫の事情がある場合は自ら切除できます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "2021年民法改正で隣地の竹木の越境処理が明確化されました（民法233条）。根は自己の費用で直ちに切除できますが（民法233条4項）、枝は原則として竹木の所有者に切除を請求する必要があります（同条1項）。ただし一定の場合は自ら切除できます（同条3項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "隣地の竹木の枝・根はいつでも自由に切除できる", "reason": "枝は原則として竹木の所有者への催告が必要です（民法233条）。自由に切除できるのは根のみです（同条4項）。", "caution": "枝：催告が原則。根：直ちに切除可（民法233条）。"}, {"label": "枝も根も自由に切除できる", "reason": "枝は原則として竹木の所有者への催告が必要です（民法233条1項・3項）。枝も自由に切除できるわけではありません。", "caution": ""}, {"label": "越境した場合は損害賠償のみ", "reason": "損害賠償だけでなく切除請求・自ら切除等の手段があります（民法233条）。「のみ」は誤りです。", "caution": ""}], "summary": {"head": ["竹木の越境（民法233条・2021年改正）", "処理"], "rows": [["枝（原則）", "竹木の所有者に切除請求（民法233条1項）"], ["枝（例外）", "所有者不明・催告後放置等→自ら切除可（同条3項）"], ["根", "直ちに自ら切除可（民法233条4項）"], ["費用", "切除費用は竹木の所有者に請求可"]]}}},
  {id:10714,unit:'l_menkyo',level:2,field:'law',text:'宅建業者が事務所以外の場所を「案内所」として設置する場合に必要な手続きとして正しいものはどれか。',opts:['免許権者への事前届出（開設10日前まで）と専任の宅建士の設置','何も必要ない','許可申請が必要','設置後速やかに届出すればよい'],ans:0,exp:'宅建業者が一時的な案内所等を設置する場合は業務開始の10日前までに免許権者へ届出が必要です（宅建業法50条2項）。また業務に従事する者が1名以上いる場合は専任の宅建士も1名以上必要です。',"kaisetsu":{"topic": "宅建業の免許：知事・大臣免許の区別・有効期間5年・欠格事由", "basis": {"text": "1都道府県のみ→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間です。", "example": ""}, "reason": {"text": "宅建業者が事務所以外の場所（案内所等）を設置して一定の業務を行う場合、免許権者および設置場所の都道府県知事への事前届出（開設10日前まで）と専任の宅建士の設置が必要です（宅建業法50条2項）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（拘禁刑以上・特定罰金等）</text></svg>", "choices": [{"label": "何も必要ない", "reason": "一定の業務を行う案内所等の設置には免許権者等への事前届出と専任宅建士の設置が必要です（宅建業法50条2項）。「何も不要」は誤りです。", "caution": "案内所等の設置：10日前までの届出＋専任宅建士（宅建業法50条2項）。"}, {"label": "許可申請が必要", "reason": "事前届出（許可申請ではない）が必要です（宅建業法50条2項）。「許可申請」ではありません。", "caution": ""}, {"label": "設置後速やかに届出すればよい", "reason": "事前届出であり、設置後ではなく開設10日前までの届出が必要です（宅建業法50条2項）。", "caution": ""}], "summary": {"head": ["案内所等の設置（宅建業法50条2項）", "内容"], "rows": [["届出先", "免許権者・設置場所の都道府県知事"], ["届出時期", "業務開始10日前まで"], ["専任宅建士", "1名以上の設置が必要"], ["クーリングオフとの関係", "届出済みの案内所はクーリングオフ適用外"]]}}},
  {id:10715,unit:'l_takkenshi',level:2,field:'law',text:'宅建士が宅建士証の有効期間の更新をしない場合の手続きとして正しいものはどれか。',opts:['何もしなくてよい','有効期間満了時に宅建士証を知事に返納しなければならない','宅建士証は自動的に失効するため返納不要','廃業届を提出する'],ans:1,exp:'宅建士証の有効期間が満了した場合等には宅建士証を速やかに交付を受けた都道府県知事に返納しなければなりません（宅建業法22条の2第6項）。',"kaisetsu":{"topic": "専任の宅建士：5人に1人以上・兼任不可・不足時は2週間以内に補充", "basis": {"text": "事務所には業務従事者5人に1人以上の専任宅建士が必要です（宅建業法31条の3）。専任宅建士は1社専属で複数業者の兼任は不可。不足時は2週間以内に補充が必要です。", "example": ""}, "reason": {"text": "宅建士証の有効期間が満了して更新しない場合は、有効期間の満了とともに宅建士証は失効します。失効した宅建士証は知事に返納しなければなりません（宅建業法22条の2第4項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">専任宅建士のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">設置基準</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5人に1人以上（主従同じ）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">兼任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可（1社専属）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不足補充</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間以内</text></svg>", "choices": [{"label": "何もしなくてよい", "reason": "有効期間満了後は宅建士証を返納しなければなりません（宅建業法22条の2第4項）。「何もしなくてよい」は誤りです。", "caution": "有効期間満了・更新なし：宅建士証を返納（宅建業法22条の2第4項）。"}, {"label": "宅建士証は自動的に失効するため返納不要", "reason": "自動的に失効しますが、失効した証を返納する義務があります（宅建業法22条の2第4項）。「返納不要」は誤りです。", "caution": ""}, {"label": "廃業届を提出する", "reason": "廃業届は宅建業者が廃業する場合の手続きです（宅建業法11条）。宅建士証の更新をしない場合の手続きではありません。", "caution": ""}], "summary": {"head": ["宅建士証の失効と返納", "内容"], "rows": [["有効期間満了（更新あり）", "交付申請前6か月以内に法定講習→更新"], ["有効期間満了（更新なし）", "失効→知事に返納（宅建業法22条の2第4項）"], ["登録消除時", "宅建士証を知事に返納（同条4項）"], ["事務禁止処分中", "期間中は知事に提出（同条5項）"]]}}},
  {id:10716,unit:'l_hosho',level:2,field:'law',text:'保証協会の社員が還付により不足が生じた場合の補充について正しいものはどれか。',opts:['保証協会が全額補充する','還付充当金として不足額を保証協会に納付しなければならない（通知から2週間以内）','補充の義務はない','国が補充する'],ans:1,exp:'弁済業務保証金から還付がなされた場合、保証協会は社員に対して還付充当金の納付を通知します。社員はその通知を受けた日から2週間以内に還付充当金を納付しなければなりません（宅建業法64条の10）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "保証協会の社員（宅建業者）が取引相手方から還付がなされ弁済業務保証金に不足が生じた場合、保証協会から通知を受けた日から2週間以内に還付充当金を保証協会に納付しなければなりません（宅建業法64条の10第1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "保証協会が全額補充する", "reason": "不足額は社員（宅建業者）が還付充当金として納付します（宅建業法64条の10第1項）。保証協会が自己負担するわけではありません。", "caution": "還付充当金：社員が2週間以内に保証協会へ納付（宅建業法64条の10第1項）。"}, {"label": "補充の義務はない", "reason": "還付充当金の納付は義務です（宅建業法64条の10第1項）。「義務なし」は誤りです。", "caution": ""}, {"label": "国が補充する", "reason": "国は補充しません（宅建業法64条の10第1項）。社員が還付充当金として納付します。", "caution": ""}], "summary": {"head": ["還付充当金（宅建業法64条の10）", "内容"], "rows": [["義務者", "還付を受けられた取引をした社員（宅建業者）"], ["期限", "保証協会からの通知を受けた日から2週間以内"], ["未納の効果", "保証協会から社員資格取り消しの対象"], ["目的", "弁済業務保証金の不足補填"]]}}},
  {id:10717,unit:'l_baikai',level:2,field:'law',text:'指定流通機構（レインズ）の目的として正しいものはどれか。',opts:['業者の収益を増やすため','不動産流通市場の活性化・情報の共有・取引の透明化のため','買主への情報提供のため','税務管理のため'],ans:1,exp:'指定流通機構（レインズ）は不動産流通の活性化・情報の共有・取引の透明性確保を目的とした物件情報システムです（宅建業法34条の2第5〜7項）。専任・専属専任媒介では登録が義務付けられています。',"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任媒介の有効期間の上限は3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。専任は7日以内、専属専任は5日以内にレインズ登録が必要。業務報告は専任2週間に1回、専属専任1週間に1回。", "example": ""}, "reason": {"text": "指定流通機構（レインズ）は不動産流通市場の活性化・情報の透明化・取引の円滑化を目的として設立されています（宅建業法34条の2第5項・6項）。宅建業者は成約情報等を登録・共有することで全国的な不動産情報ネットワークを形成します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">一般</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専任</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専属専任</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己発見取引</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">レインズ登録</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務報告</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">なし</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間に1回</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1週間に1回</text></svg>", "choices": [{"label": "業者の収益を増やすため", "reason": "レインズの目的は業者の収益増加ではなく不動産流通市場の活性化・透明化です（宅建業法34条の2等の趣旨）。", "caution": ""}, {"label": "買主への情報提供のため", "reason": "レインズは主に宅建業者間の情報共有を目的とする制度です。一般消費者への直接情報提供が主目的ではありません。", "caution": ""}, {"label": "税務管理のため", "reason": "レインズは税務管理のためのシステムではありません。不動産流通情報の共有が目的です。", "caution": ""}], "summary": {"head": ["レインズ（指定流通機構）", "内容"], "rows": [["目的", "不動産流通市場の活性化・情報の透明化"], ["運営", "国土交通大臣が指定した流通機構（民間法人）"], ["登録義務", "専任媒介：7日以内、専属専任：5日以内"], ["成約報告", "成約後は速やかに成約情報を登録"]]}}},
  {id:10718,unit:'l_jusetsu',level:2,field:'law',text:'土砂災害警戒区域内の不動産売買における重要事項説明として正しいものはどれか。',opts:['特別な説明義務はない','土砂災害警戒区域または土砂災害特別警戒区域内である旨を説明しなければならない','危険性があることを口頭で告げればよい','買主が希望した場合のみ説明する'],ans:1,exp:'土砂災害警戒区域等における土砂災害防止対策の推進に関する法律に基づく区域内である旨は重要事項として説明する義務があります（宅建業法35条1項14号）。',"kaisetsu":{"topic": "重要事項説明：宅建士が説明・売主への交付は不要・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主への交付義務はありません。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能です。", "example": ""}, "reason": {"text": "土砂災害警戒区域または土砂災害特別警戒区域内にある物件の売買では、その旨を重要事項として説明しなければなりません（宅建業法35条1項14号・施行規則16条の4の3第2号）。買主がリスクを認識した上で判断できるようにするためです。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "特別な説明義務はない", "reason": "土砂災害警戒区域内にある旨は重要事項説明の必須記載事項です（宅建業法35条1項14号等）。", "caution": "土砂災害警戒区域：重要事項説明の必須記載事項。"}, {"label": "危険性があることを口頭で告げればよい", "reason": "口頭だけでなく35条書面への記載が必要です（宅建業法35条1項）。", "caution": ""}, {"label": "買主が希望した場合のみ説明する", "reason": "区域内であれば買主の希望に関わらず説明義務があります（宅建業法35条1項14号等）。", "caution": ""}], "summary": {"head": ["ハザードマップ関連の重要事項", "内容"], "rows": [["土砂災害警戒区域・特別警戒区域", "区域内である旨を記載"], ["津波災害警戒区域", "区域内である旨を記載"], ["水害ハザードマップ", "洪水・雨水出水等の浸水想定区域内の旨"], ["説明方法", "35条書面への記載＋口頭説明"]]}}},
  {id:10719,unit:'l_37jo',level:2,field:'law',text:'37条書面に記載する「移転登記申請の時期」について正しいものはどれか。',opts:['法律上の規定はなく任意','売買契約では定めがある場合に記載する任意的記載事項','引渡しと同時と定めた場合も含め必ず記載する必要的記載事項','引渡し後30日以内が法定されている'],ans:2,exp:'「移転登記申請の時期」は37条書面の必要的記載事項です（宅建業法37条1項5号）。引渡しと同時・代金完済後等、具体的な時期を記載する必要があります。',"kaisetsu":{"topic": "37条書面：全取引で交付・記名（押印不要）・移転登記申請時期は必要的記載事項", "basis": {"text": "37条書面は売買・交換・賃貸借の全取引で契約の双方当事者に交付が義務（宅建業法37条）。引渡し時期・移転登記申請時期は必要的記載事項。2021年改正で押印は不要になり記名のみで足ります。", "example": ""}, "reason": {"text": "移転登記の申請時期は37条書面の必要的記載事項です（宅建業法37条1項5号）。引渡しと同時と定めた場合も含め、常に記載しなければなりません。「定めがある場合のみ」ではなく、定めの内容を必ず記載します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付義務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全取引・双方当事者</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡時期・移転登記申請時期等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要）</text></svg>", "choices": [{"label": "法律上の規定はなく任意", "reason": "移転登記申請の時期は必要的記載事項です（宅建業法37条1項5号）。「任意」は誤りです。", "caution": "移転登記申請時期：必要的記載事項（宅建業法37条1項5号）。"}, {"label": "売買契約では定めがある場合に記載する任意的記載事項", "reason": "移転登記申請時期は任意的ではなく必要的記載事項です（宅建業法37条1項5号）。", "caution": ""}, {"label": "引渡し後30日以内が法定されている", "reason": "引渡し後の登記申請期間を法定する規定はありません（宅建業法37条1項5号）。当事者の合意内容を記載します。", "caution": ""}], "summary": {"head": ["移転登記申請時期（宅建業法37条1項5号）", "内容"], "rows": [["性質", "必要的記載事項（定めの有無に関わらず記載）"], ["記載内容", "合意した申請時期（例：引渡しから1か月以内等）"], ["引渡しと同時", "「引渡しと同時」と記載する"], ["35条書面", "移転登記申請時期は35条書面の記載事項ではない"]]}}},
  {id:10720,unit:'l_kokoku',level:2,field:'law',text:'宅建業法上の「取引態様の明示義務」について正しいものはどれか。',opts:['広告時には不要で注文を受けた時のみ明示すればよい','広告する際と注文を受けた際の両方において取引態様を明示しなければならない','取引態様の明示は口頭で足りる','取引態様の明示違反に罰則はない'],ans:1,exp:'宅建業者は広告をするときと注文を受けた場合の両方で取引態様の明示が義務付けられています（宅建業法34条）。売主・代理・媒介のいずれかを明示することで取引の透明性を確保します。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "取引態様の明示義務は広告するときと注文（申込み）を受けたときの両方で必要です（宅建業法34条1項・2項）。口頭による明示でも法律上は可能ですが（方法の明示がない）、実務上は書面が多く使われます。違反は行政処分の対象となります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "広告時には不要で注文を受けた時のみ明示すればよい", "reason": "広告時にも明示が必要です（宅建業法34条1項）。「広告時は不要」は誤りです。", "caution": ""}, {"label": "取引態様の明示は口頭で足りる", "reason": "宅建業法34条に明示方法の規定はなく（書面限定の規定はない）、口頭でも法律上は可能です。ただし証拠保全のため書面が推奨されます。これは正しい内容ですが、設問の正解は選択肢2です。", "caution": ""}, {"label": "取引態様の明示違反に罰則はない", "reason": "取引態様の明示義務違反は行政処分の対象となります（宅建業法65条）。「罰則はない」は誤りです。", "caution": ""}], "summary": {"head": ["取引態様の明示（宅建業法34条）", "内容"], "rows": [["①広告時", "媒体の種類を問わず（宅建業法34条1項）"], ["②注文・申込み受領時", "遅滞なく明示（宅建業法34条2項）"], ["方法", "書面・口頭等（方法の限定規定なし）"], ["違反", "行政処分の対象"]]}}},
  {id:10721,unit:'l_cooling',level:2,field:'law',text:'手付解除について正しいものはどれか（宅建業者が自ら売主の場合）。',opts:['売主・買主はいつでも手付解除できる','相手方が契約の履行に着手するまでは手付解除ができる','履行着手後も手付解除できる','手付を支払っても解除はできない'],ans:1,exp:'宅建業者が自ら売主の場合、手付解除は相手方が履行に着手するまでの間に行う必要があります（宅建業法39条2項準用・民法557条）。売主からの解除は手付の倍額を現実に提供することが必要です。',"kaisetsu":{"topic": "クーリングオフ：告知日から8日以内・書面で・事務所では不可・全額返還", "basis": {"text": "クーリングオフは告知を受けた日から8日以内に書面で行います（宅建業法37条の2）。事務所・モデルルーム等での申込みはクーリングオフ不可。解除後業者は全額返還（費用控除不可）。", "example": ""}, "reason": {"text": "宅建業者が自ら売主の場合の手付解除の要件は、相手方が「契約の履行に着手するまで」です（宅建業法39条2項・民法557条1項）。履行着手後は手付による解除ができません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">クーリングオフのポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">告知日から8日以内</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">方法</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面（発信主義）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所での申込み</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">クーリングオフ不可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除後</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全額返還（費用控除不可）</text></svg>", "choices": [{"label": "売主・買主はいつでも手付解除できる", "reason": "相手方が履行に着手した後は手付解除できません（宅建業法39条2項・民法557条1項）。「いつでも」は誤りです。", "caution": "手付解除：相手方の履行着手前まで可（宅建業法39条2項・民法557条1項）。"}, {"label": "履行着手後も手付解除できる", "reason": "相手方が履行に着手した後は手付解除できません（宅建業法39条2項・民法557条1項ただし書）。", "caution": ""}, {"label": "手付を支払っても解除はできない", "reason": "手付を交付した場合、相手方の履行着手前なら手付放棄（買主）・倍返し（売主）で解除できます（宅建業法39条2項・民法557条1項）。「解除できない」は誤りです。", "caution": ""}], "summary": {"head": ["手付による解除（宅建業法39条2項）", "内容"], "rows": [["買主から解除", "手付放棄（相手方の履行着手前）"], ["売主から解除", "手付の倍額を現実提供（相手方の履行着手前）"], ["履行着手後", "手付解除不可"], ["手付の性質", "解約手付（宅建業法39条2項）"]]}}},
  {id:10722,unit:'l_hoshu',level:2,field:'law',text:'売買の代理と媒介では報酬の上限はどう違うか。',opts:['代理も媒介も上限は同じ','代理の場合は媒介の上限額の2倍まで受け取れる（双方代理の場合は各自から媒介の1倍が上限）','代理のほうが低い','代理には報酬制限がない'],ans:1,exp:'代理の場合、依頼者から受け取れる報酬は媒介の場合の2倍が上限です。ただし双方代理なら各自から媒介の1倍が上限です（報酬告示）。',"kaisetsu":{"topic": "報酬：売買は代金×3%+6万（400万超）・賃貸は借賃1か月・上限超過は不可", "basis": {"text": "売買媒介報酬（400万超）の一方からの上限は代金×3%+6万円（税別）。双方合計は一方上限×2。賃貸媒介（居住用・非居住用とも）は借賃1か月分。依頼者の承諾があっても上限超過は不可。", "example": ""}, "reason": {"text": "代理の場合の報酬上限は媒介の2倍です（告示）。双方代理の場合は各自から媒介の1倍（つまり代理の0.5倍）が上限で、双方合計では媒介の2倍（代理の1倍）を超えてはなりません（告示）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対象</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（400万超）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万（一方）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（200万以下）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸（双方合計）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借賃1か月分</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">低廉な空家等（800万円以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円まで（説明・合意要）</text></svg>", "choices": [{"label": "代理も媒介も上限は同じ", "reason": "代理の場合は媒介の2倍まで受け取れます（告示）。「同じ」は誤りです。", "caution": "代理の報酬上限：媒介の2倍（告示）。"}, {"label": "代理のほうが低い", "reason": "代理の方が高く（媒介の2倍）、低くはありません（告示）。", "caution": ""}, {"label": "代理には報酬制限がない", "reason": "代理でも報酬制限があります（告示）。代理の上限は媒介の2倍です。", "caution": ""}], "summary": {"head": ["媒介vs代理の報酬（告示）", "上限"], "rows": [["媒介（一方から）", "代金×3%＋6万円（税別）"], ["代理（依頼者から）", "代金×6%＋12万円（税別）（媒介の2倍）"], ["双方代理の場合", "各自から媒介相当・双方合計で媒介の2倍が上限"]]}}},
  {id:10723,unit:'l_kantoku',level:2,field:'law',text:'宅建業法に基づく「立入検査」の権限について正しいものはどれか。',opts:['捜査令状がなければ立入検査できない','国土交通大臣または都道府県知事は事務所等への立入検査ができる','立入検査は業者の同意が必要','立入検査は年1回に限られる'],ans:1,exp:'国土交通大臣または都道府県知事は宅建業の適正な運営の確保のため宅建業者の事務所等に立入り帳簿・書類の検査や関係者への質問ができます（宅建業法72条）。業者は正当な理由なく拒否できません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "国土交通大臣または都道府県知事は宅建業者の事務所等への立入検査ができます（宅建業法72条1項）。捜査令状は不要で、業者の同意なしでも立入検査が可能です。ただし立入検査を拒否した場合は罰則があります（同法83条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "捜査令状がなければ立入検査できない", "reason": "立入検査は行政調査であり捜査令状は不要です（宅建業法72条1項）。", "caution": "立入検査：行政調査（捜査令状不要・宅建業法72条1項）。"}, {"label": "立入検査は業者の同意が必要", "reason": "行政検査の性質上、業者の同意なく立入検査ができます（宅建業法72条1項）。拒否した場合は罰則があります（同法83条）。", "caution": ""}, {"label": "立入検査は年1回に限られる", "reason": "回数の制限はありません（宅建業法72条1項）。必要に応じて複数回行うことができます。", "caution": ""}], "summary": {"head": ["立入検査（宅建業法72条）", "内容"], "rows": [["権限者", "国交大臣・都道府県知事"], ["令状", "不要（行政検査）"], ["業者の拒否", "罰則対象（宅建業法83条）"], ["目的", "業務の適正確保のための実態調査"]]}}},
  {id:10724,unit:'l_sonota',level:2,field:'law',text:'宅建業者が買主に対して行う手付金等の保全措置の種類として正しいものはどれか。',opts:['保証保険のみ','保証保険・保証委託・指定保管機関による保管の3種類','保証協会への預け入れのみ','法務局への供託のみ'],ans:1,exp:'手付金等の保全措置の方法は①保証保険（保険会社）②保証委託（銀行等の連帯保証）③指定保管機関（保証協会等）による保管の3種類です（宅建業法41条の2）。未完成物件は①②のみです。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "宅建業者（自ら売主）が買主に対して行う手付金等の保全措置には①銀行等による連帯保証、②保険事業者による保証保険契約、③指定保管機関による保管の3種類があります（宅建業法41条1項・41条の2第1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "保証保険のみ", "reason": "保証保険のほかに保証委託・指定保管機関による保管の方法もあります（宅建業法41条1項・41条の2第1項）。「のみ」は誤りです。", "caution": "保全措置の方法：保証委託・保証保険・指定保管機関の3種類（宅建業法41条・41条の2）。"}, {"label": "保証協会への預け入れのみ", "reason": "保証協会への預け入れは保全措置の方法ではありません（宅建業法41条1項）。", "caution": ""}, {"label": "法務局への供託のみ", "reason": "法務局への供託は手付金等の保全措置ではありません（宅建業法41条1項）。営業保証金の供託先（法務局）と混同しないようにしましょう。", "caution": ""}], "summary": {"head": ["手付金等の保全措置の方法（宅建業法41条・41条の2）", "内容"], "rows": [["①銀行等による連帯保証委託", "銀行・信用金庫等が連帯保証"], ["②保証保険契約", "保険会社による保証保険"], ["③指定保管機関による保管", "完成物件のみ。指定保管機関が保管"]]}}},
  {id:10725,unit:'k_toshi',level:2,field:'limit',text:'都市計画区域マスタープランの策定者として正しいものはどれか。',opts:['市町村','都道府県','国土交通大臣','市町村と都道府県の共同'],ans:1,exp:'都市計画区域の整備・開発・保全の方針（マスタープラン）は都道府県が定めます（都市計画法6条の2）。市町村は市町村マスタープランを定めます（同法18条の2）。',"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域での1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は市街化調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "都市計画区域マスタープラン（都市計画区域の整備・開発及び保全の方針）は都道府県が都市計画として定めます（都市計画法6条の2）。広域的な視点から都市計画の方向性を示すものです。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化する区域</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可基準</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "市町村", "reason": "都市計画区域マスタープランは都道府県が定めます（都市計画法6条の2）。市町村は市町村マスタープラン（都市計画に関する基本的な方針）を定めます（同法18条の2）。", "caution": "都市計画区域マスタープラン：都道府県が策定（都市計画法6条の2）。"}, {"label": "国土交通大臣", "reason": "都道府県が定めます（都市計画法6条の2）。国交大臣ではありません。", "caution": ""}, {"label": "市町村と都道府県の共同", "reason": "都道府県が単独で定めます（都市計画法6条の2）。共同策定ではありません。", "caution": ""}], "summary": {"head": ["各マスタープランの策定者", "内容"], "rows": [["都市計画区域マスタープラン", "都道府県（都市計画法6条の2）"], ["市町村マスタープラン", "市町村（都市計画法18条の2）"], ["国土計画", "国（国土形成計画法等）"]]}}},
  {id:10726,unit:'k_toshi',level:2,field:'limit',text:'用途地域のうち「商業地域」で建築できない建築物として正しいものはどれか。',opts:['百貨店・大型ショッピングモール','映画館・カラオケ','住宅','危険物の製造・貯蔵で一定規模を超えるもの'],ans:3,exp:'商業地域は最も制限が緩く住宅・商業施設・映画館等ほぼ全て建築できますが、危険物の製造・貯蔵で一定規模を超えるものや特定の工場は建築できません（建築基準法別表第二）。',"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域での1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は市街化調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "商業地域は商業施設・業務施設が集積する地域で、ほぼすべての建築物が建築できますが、危険物の製造・貯蔵等で一定規模を超えるものは建築できません（建築基準法別表第二）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化する区域</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可基準</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "百貨店・大型ショッピングモール", "reason": "百貨店・大型ショッピングモールは商業地域で建築できます（建築基準法別表第二）。", "caution": ""}, {"label": "映画館・カラオケ", "reason": "映画館・カラオケは商業地域で建築できます（建築基準法別表第二）。", "caution": ""}, {"label": "住宅", "reason": "住宅は商業地域でも建築できます（建築基準法別表第二）。", "caution": ""}], "summary": {"head": ["商業地域で建築できるもの・できないもの", "内容"], "rows": [["できる", "百貨店・住宅・映画館・ホテル・病院・カラオケ等ほぼ全て"], ["できない", "危険物の製造・貯蔵等（一定規模超）・大規模の設置基準を超えた工場等"]]}}},
  {id:10727,unit:'k_kenchiku',level:2,field:'limit',text:'日影規制（建築基準法56条の2）の対象となる建築物として正しいものはどれか。',opts:['すべての建築物','用途地域が定められた地域内の一定高さ以上の建築物','日影規制は存在しない','住宅のみ対象'],ans:1,exp:'日影規制は用途地域が定められた地域内（商業地域・工業地域等を除く）で一定の高さを超える建築物を対象として冬至日の日影時間を規制します（建築基準法56条の2）。',"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・道路斜線・用途制限", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。用途地域ごとに建築物の制限があります。", "example": ""}, "reason": {"text": "日影規制（建築基準法56条の2）は用途地域が定められた地域内の一定高さ以上の建築物を対象とします。高さの基準は地域によって異なり（例：第一種低層は10m超・中高層住居専用地域は10m超等）、商業地域・工業地域・工業専用地域は除外されます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">第1種低層</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">学校は建築可</text></svg>", "choices": [{"label": "すべての建築物", "reason": "高さが一定以下の建築物は対象外です（建築基準法56条の2第1項）。「すべて」は誤りです。", "caution": "日影規制：用途地域ごとに定められた一定高さ以上の建築物が対象（建築基準法56条の2第1項）。"}, {"label": "日影規制は存在しない", "reason": "日影規制は建築基準法56条の2に規定されています。「存在しない」は誤りです。", "caution": ""}, {"label": "住宅のみ対象", "reason": "住宅に限らず、対象地域の一定高さ以上の建築物が対象です（建築基準法56条の2第1項）。", "caution": ""}], "summary": {"head": ["日影規制の対象（建築基準法56条の2第1項）", "内容"], "rows": [["対象地域", "住居系地域・近隣商業地域・準工業地域等"], ["除外地域", "商業地域・工業地域・工業専用地域"], ["対象建築物", "地域ごとに定められた一定高さ以上のもの"], ["測定基準", "冬至日の午前8時〜午後4時（または午前9時〜午後3時）"]]}}},
  {id:10728,unit:'k_kenchiku',level:2,field:'limit',text:'敷地が2以上の異なる建ぺい率の地域にわたる場合の建ぺい率の算定として正しいものはどれか。',opts:['最も緩い地域の建ぺい率を全体に適用','各地域の面積に応じた加重平均で算定（按分計算）','最も厳しい地域の建ぺい率を全体に適用','どちらか選択できる'],ans:1,exp:'敷地が異なる建ぺい率の地域にわたる場合は各地域の面積の割合に応じた加重平均（按分計算）で建ぺい率の限度を計算します（建築基準法53条2項）。容積率も同様です。',"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・道路斜線・用途制限", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。用途地域ごとに建築物の制限があります。", "example": ""}, "reason": {"text": "敷地が2以上の建ぺい率制限の異なる地域にわたる場合、各地域の面積に応じた加重平均（按分計算）で建ぺい率を算定します（建築基準法53条2項）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">第1種低層</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">学校は建築可</text></svg>", "choices": [{"label": "最も緩い地域の建ぺい率を全体に適用", "reason": "按分計算で算定します（建築基準法53条2項）。最も緩い地域の値を全体に適用するのは誤りです。", "caution": "複数地域にまたがる敷地の建ぺい率：按分計算（加重平均）（建築基準法53条2項）。"}, {"label": "最も厳しい地域の建ぺい率を全体に適用", "reason": "按分計算で算定します（建築基準法53条2項）。最も厳しい値を全体に適用するのは誤りです（防火地域と準防火地域の場合は厳しい方が適用されますが、建ぺい率は按分）。", "caution": ""}, {"label": "どちらか選択できる", "reason": "選択制ではなく、按分計算が義務です（建築基準法53条2項）。", "caution": ""}], "summary": {"head": ["複数地域にまたがる敷地の建ぺい率（建築基準法53条2項）", "計算方法"], "rows": [["計算方法", "各地域の面積×各建ぺい率の加重平均"], ["例", "A地域（60%・200㎡）＋B地域（40%・100㎡）→（60%×200+40%×100）÷300≒53.3%"], ["容積率も同様", "按分計算で算定（建築基準法52条7項）"]]}}},
  {id:10729,unit:'k_nochi',level:2,field:'limit',text:'農地法の「農地」判断の原則として正しいものはどれか。',opts:['登記簿の地目で判断する','現況（現在の状態）で判断する（現況主義）','固定資産税の課税地目で判断する','農業振興地域内かどうかで判断する'],ans:1,exp:'農地法上の「農地」は現に耕作の目的に供されている土地を指します（農地法2条）。登記簿の地目が宅地でも現況が農地であれば農地法が適用されます（現況主義）。',"kaisetsu":{"topic": "農地法：3条は農業委員会・4条・5条は都道府県知事・市街化区域は届出のみ", "basis": {"text": "農地法3条（権利移動・農地→農地）の許可権者は農業委員会。4条（自己転用）・5条（転用目的の権利移動）は都道府県知事等。市街化区域内の農地転用（4・5条）は農業委員会への届出のみでOK。相続は許可不要・届出3か月以内。", "example": ""}, "reason": {"text": "農地かどうかの判断は登記地目ではなく現況（現在の状態）で判断します（農地法2条1項・現況主義）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">市街化区域</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">特例なし</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text></svg>", "choices": [{"label": "登記簿の地目で判断する", "reason": "現況主義であり、登記地目ではありません（農地法2条1項）。", "caution": "農地の判断：現況主義（農地法2条1項）。"}, {"label": "固定資産税の課税地目で判断する", "reason": "固定資産税の課税地目ではなく現況で判断します（農地法2条1項）。", "caution": ""}, {"label": "農業振興地域内かどうかで判断する", "reason": "農業振興地域の指定の有無ではなく現況で判断します（農地法2条1項）。", "caution": ""}], "summary": {"head": ["農地の判断基準（農地法2条1項）", "内容"], "rows": [["判断基準", "現況主義（現に耕作に使われているか）"], ["登記地目", "参考にはなるが決定的ではない"]]}}},
  {id:10730,unit:'k_kukaku',level:2,field:'limit',text:'土地区画整理事業の換地処分について正しいものはどれか。',opts:['換地処分は個々の地権者ごとに行われる','換地処分の公告があった日の翌日に換地が従前の宅地の所有者に帰属し登記効力が生じる','換地処分後も従前の宅地所有権は残る','換地処分には地権者全員の同意が必要'],ans:1,exp:'換地処分の公告があった日の翌日に換地は従前の宅地とみなされ所有権その他の権利が換地に移行します（土地区画整理法103条4項）。',"kaisetsu":{"topic": "土地区画整理法：換地は公告翌日確定・仮換地は従前地使用不可・組合は2/3以上", "basis": {"text": "換地処分の公告翌日から換地が確定します（土地区画整理法104条）。仮換地の指定後は従前地を使用できなくなります（同法99条）。組合設立には土地所有者・借地権者の各2/3以上の同意が必要です。", "example": ""}, "reason": {"text": "換地処分の公告があった日の翌日に換地が従前の宅地の所有者に帰属し、登記の効力も生じます（土地区画整理法104条1項・5項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">土地区画整理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">換地の確定</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公告の翌日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮換地指定後</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従前地は使用不可（所有権は残る）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">組合設立</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各2/3以上の同意</text></svg>", "choices": [{"label": "換地処分は個々の地権者ごとに行われる", "reason": "換地処分は区域全体を一括して行います（土地区画整理法103条4項）。", "caution": "換地処分：区域全体を一括して行う→公告翌日に効力発生（土地区画整理法103条・104条）。"}, {"label": "換地処分後も従前の宅地所有権は残る", "reason": "換地処分公告翌日から従前地の権利は換地に移行します（土地区画整理法104条1項）。", "caution": ""}, {"label": "換地処分には地権者全員の同意が必要", "reason": "換地処分は施行者が行政処分として行うものであり、地権者全員の同意は不要です（土地区画整理法103条4項）。", "caution": ""}], "summary": {"head": ["換地処分と公告（土地区画整理法103条・104条）", "内容"], "rows": [["換地処分", "区域全体を一括して行う行政処分"], ["公告", "換地処分後に公告"], ["効力", "公告の翌日から換地が従前地とみなされる"]]}}},
  {id:10731,unit:'k_mori',level:2,field:'limit',text:'宅地造成工事規制区域内で許可が不要な造成工事として正しいものはどれか。',opts:['高さ2m以下の擁壁の設置','切土で高さ2m超の場合','盛土で高さ1m超の場合','面積500m2超の盛土'],ans:0,exp:'宅地造成工事規制区域内であっても高さ2m以下の擁壁の設置など小規模なものは許可不要です（盛土規制法12条1項・令3条）。一定規模（切土2m超・盛土1m超等）を超えると許可が必要です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "宅地造成工事規制区域内での高さ2m以下の擁壁の設置は許可が不要な工事です（宅地造成及び特定盛土等規制法施行令4条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "切土で高さ2m超の場合", "reason": "高さ2m超の崖を生じる切土は許可が必要です（施行令3条）。", "caution": "高さ2m以下の擁壁設置：許可不要（施行令4条）。"}, {"label": "盛土で高さ1m超の場合", "reason": "高さ1m超の崖を生じる盛土は許可が必要です（施行令3条）。", "caution": ""}, {"label": "面積500m2超の盛土", "reason": "500㎡超の盛土は許可が必要です（施行令3条）。", "caution": ""}], "summary": {"head": ["許可不要の工事（施行令4条）", "内容"], "rows": [["高さ2m以下の擁壁の設置", "許可不要"]]}}},
  {id:10732,unit:'k_kokudo',level:2,field:'limit',text:'国土利用計画法の「規制区域」における土地取引について正しいものはどれか。',opts:['規制区域内では事後届出で足りる','規制区域内での一定の土地取引には都道府県知事の事前許可が必要で許可なき契約は無効','規制区域の指定には国会の承認が必要','規制区域は全国に多数指定されている'],ans:1,exp:'規制区域（国土利用計画法12条）内では一定面積以上の土地取引に都道府県知事の許可が必要で、無許可の契約は無効です。現在はほぼ指定されていません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "規制区域（国土利用計画法12条）では都道府県知事の事前許可が必要であり、許可なき取引は無効です（国土利用計画法14条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "規制区域内では事後届出で足りる", "reason": "規制区域内では事前許可が必要です（国土利用計画法14条1項）。", "caution": "規制区域：事前許可制（国土利用計画法14条1項）。許可なき取引は無効。"}, {"label": "規制区域の指定には国会の承認が必要", "reason": "国会の承認は不要です（国土利用計画法12条）。都道府県知事が指定します。", "caution": ""}, {"label": "規制区域は全国に多数指定されている", "reason": "規制区域は実際の指定事例はほとんどありません。「多数指定」は誤りです。", "caution": ""}], "summary": {"head": ["規制区域（国土利用計画法12条）", "内容"], "rows": [["取引規制", "事前許可制（国土利用計画法14条1項）"], ["無許可取引", "無効"]]}}},
  {id:10733,unit:'t_joto',level:2,field:'tax',text:'不動産の譲渡所得において「取得費」に含まれるものとして正しいものはどれか。',opts:['固定資産税','取得時の仲介手数料・登録免許税・不動産取得税・測量費等','購入後の修繕費','取得費は購入価格のみ'],ans:1,exp:'取得費には購入代金のほか仲介手数料・登録免許税・不動産取得税・測量費・改良費等の取得に要した費用が含まれます（所得税法38条）。固定資産税は取得費に含まれません。',"kaisetsu":{"topic": "譲渡所得：分離課税・長期は20%・3,000万円控除は3年に1回", "basis": {"text": "土地・建物の譲渡所得は分離課税（申告分離課税）。長期（5年超）の税率は合計20%（所得税15%+住民税5%）。短期（5年以下）は39%（所得税30%+住民税9%）。3,000万円特別控除は前年・前々年に適用があれば使えません（3年に1回）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">譲渡所得のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税方式</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">分離課税</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">長期（5年超）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計20%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">短期（5年以下）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計39%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3,000万円控除</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年に1回の制限</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10734,unit:'t_shutoku',level:2,field:'tax',text:'住宅用地の不動産取得税の特例（土地）について正しいものはどれか。',opts:['新築住宅を取得した場合、土地には特例はない','新築住宅を取得した場合の土地は固定資産税評価額の1/2に軽減され一定の控除がある','土地の不動産取得税は常に非課税','土地には標準税率4%が適用される'],ans:1,exp:'住宅用地の不動産取得税では課税標準が固定資産税評価額の1/2に軽減され（地方税法附則11条の5）、さらに新築住宅の敷地については一定の控除額を差し引く特例があります（地方税法73条の24）。',"kaisetsu":{"topic": "不動産取得税：都道府県が課す地方税・相続は非課税・1回だけ課税", "basis": {"text": "不動産取得税は都道府県が課す地方税です（地方税法73条の2）。相続・法人の合併等による取得は非課税。一度の取得に一度だけ課税される（固定資産税と異なり毎年ではない）。標準税率は4%（住宅・土地は3%の軽減あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産取得税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税の頻度</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取得時に1回のみ</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">標準税率</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4%（住宅・土地は3%）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10735,unit:'t_kotei',level:2,field:'tax',text:'固定資産の価格に不服がある場合の手続きとして正しいものはどれか。',opts:['直ちに裁判所に提訴する','固定資産評価審査委員会に審査申出ができる','都道府県知事に異議申出する','国税不服申立て制度による'],ans:1,exp:'固定資産の価格に不服がある場合は固定資産評価審査委員会に審査の申出ができます（地方税法432条）。基準年度の4月1日から当該年度の納税通知書を受け取った日後3か月を経過する日までが申出期間です。',"kaisetsu":{"topic": "固定資産税：市町村が課す地方税・賦課期日は1月1日・評価替えは3年ごと", "basis": {"text": "固定資産税は市町村（東京23区は都）が課す地方税です（地方税法343条）。賦課期日は毎年1月1日。評価替えは3年ごと（基準年度）。住宅用地の特例：200㎡以下は課税標準1/6、超過部分は1/3。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">固定資産税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市町村（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賦課期日</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">評価替え</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年ごと</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅用地（200㎡以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税標準1/6</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10736,unit:'t_toroku',level:2,field:'tax',text:'住宅用家屋の所有権移転登記（売買）の登録免許税の軽減税率を受けるための要件として正しいものはどれか。',opts:['新築住宅のみ適用','床面積50m2以上・取得後1年以内の登記・自己の居住用・一定の耐震基準等が要件','築年数制限はない','法人も適用対象'],ans:1,exp:'住宅用家屋の所有権移転登記の軽減税率（0.3%）を受けるには床面積50m2以上・取得後1年以内の登記・自己の居住用・一定の耐震基準等の要件があります（租税特別措置法73条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10737,unit:'t_inshi',level:2,field:'tax',text:'印紙税の「記載金額」が複数ある場合の取扱いとして正しいものはどれか。',opts:['最も低い金額を記載金額とする','最も高い金額を記載金額とする','合算して記載金額とする','記載金額のある文書は非課税'],ans:2,exp:'1通の文書に土地・建物それぞれの売買代金が記載されている場合は、その合計額が記載金額となります（印紙税法基本通達）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10738,unit:'t_chika',level:2,field:'tax',text:'不動産鑑定評価における「正常価格」の定義として正しいものはどれか。',opts:['最高値で売却できる価格','市場で自由な取引が行われるとした場合に通常成立すると認められる適正な価格','固定資産税評価額に基づく価格','路線価に基づく価格'],ans:1,exp:'正常価格とは市場性を有する不動産について現実の社会経済情勢のもとで合理的と考えられる条件を満たす市場で形成されるであろう市場価値を表す適正な価格です（不動産鑑定評価基準）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10739,unit:'t_kinyu',level:2,field:'tax',text:'住宅金融支援機構の直接融資の対象として正しいものはどれか。',opts:['一般の住宅購入者全て（主たる業務）','災害復興住宅・マンション共用部分の改修・高齢者向け返済特例等の特定用途に限られる','地方公共団体向けのみ','商業施設のみ'],ans:1,exp:'住宅金融支援機構の主な業務は民間金融機関への支援（証券化支援・保険など）です。直接融資は災害復興住宅・マンション共用部分の改修・高齢者向け返済特例等の特定用途に限られます（住宅金融支援機構法13条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10740,unit:'t_tokei',level:2,field:'tax',text:'丘陵地・台地を宅地として利用する場合の特徴として正しいものはどれか。',opts:['低湿地より地盤が弱く危険','地盤が比較的安定しており洪水や液状化のリスクが低い好適な宅地','常に盛土が必要','農地に転用しにくい'],ans:1,exp:'丘陵地・台地は地盤が比較的固く安定しており、洪水・液状化・土砂崩れのリスクが低いため良好な宅地として評価されます。傾斜地では切土・盛土の造成が必要な場合があります。',"kaisetsu":{"topic": "不動産統計・建物・土地の知識", "basis": {"text": "住宅着工戸数は近年80万戸前後で推移。首都圏マンション価格は上昇傾向。J-REITの運用資産は拡大傾向。中古住宅流通は活発化傾向。フラット35は全期間固定・各金融機関が金利設定・15年以上35年以下。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産統計・フラット35のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">近年の傾向</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅着工戸数</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">80万戸前後</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">首都圏マンション価格</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">上昇傾向</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">J-REIT</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">拡大傾向</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">フラット35の金利</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全期間固定・各金融機関が設定</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10741,unit:'r_ishi',level:3,field:'rights',text:'心裡留保（民法93条）による意思表示の効力について正しいものはどれか。',opts:['心裡留保による意思表示は常に無効','原則として有効で相手方が表意者の真意を知りまたは知ることができた場合のみ無効','相手方が善意なら常に有効','心裡留保は詐欺の一種'],ans:1,exp:'心裡留保（冗談や内心で本当のことを思わずにした意思表示）は原則として有効ですが、相手方が表意者の真意を知りまたは知ることができた（悪意または有過失）場合は無効となります（民法93条）。',"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "意思表示の瑕疵には詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失の第三者は保護）・通謀虚偽表示（無効・善意の第三者は保護）があります。", "example": ""}, "reason": {"text": "心裡留保は表示主義（意思表示の外観を重視する原則）の表れです。相手方が善意無過失であれば表示を信頼した相手方を保護して有効とし、悪意・有過失の場合は保護の必要がないため無効とします（民法93条1項）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "心裡留保による意思表示は常に無効", "reason": "心裡留保は原則として有効です（民法93条1項本文）。相手方が悪意または有過失の場合のみ無効となります（同ただし書）。", "caution": ""}, {"label": "相手方が善意なら常に有効", "reason": "相手方が善意でも過失がある場合（知ることができた場合）は無効となります（民法93条1項ただし書）。善意だけでなく無過失も必要です。", "caution": "「善意＝有効」は誤り。「善意かつ無過失＝有効」です。"}, {"label": "心裡留保は詐欺の一種", "reason": "心裡留保は内心と異なる意思表示であり、詐欺とは別の概念です。詐欺は相手方を欺く行為（民法96条）で、心裡留保は表意者自身の問題（民法93条）です。", "caution": ""}], "summary": {"head": ["相手方の状態", "効力"], "rows": [["善意かつ無過失", "有効"], ["悪意", "無効"], ["善意だが有過失", "無効"]]}}},
  {id:10742,unit:'r_dairi',level:3,field:'rights',text:'代理権授与行為と基本契約の関係について正しいものはどれか。',opts:['代理権授与は基本契約と同一の行為','代理権授与行為は基本契約とは独立した別個の行為で委任契約が解除されても代理権は残ることがある','代理権の授与には公証人の認証が必要','代理権授与は口頭では無効'],ans:1,exp:'代理権授与行為（委任状等）は基本となる委任契約とは独立した単独行為です（民法99条）。委任契約が解除・取り消されても代理権授与行為が有効である場合は表見代理の問題が生じます。',"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護する制度です。", "example": ""}, "reason": {"text": "代理権授与行為（授権行為）と委任契約等の基本契約は独立した別個の行為です（無因性・有因性の議論あり）。実務では基本契約が解除されても代理権が残ることがあり、第三者との取引の安全のために区別が重要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "代理権授与は基本契約と同一の行為", "reason": "代理権授与行為と基本契約（委任等）は法律的には別個の行為です。基本契約が解除されても代理権が残る場合があります。", "caution": ""}, {"label": "代理権の授与には公証人の認証が必要", "reason": "代理権の授与（委任状の作成等）に公証人の認証は一般的に必要ありません（不動産登記等の特別な場合を除く）。", "caution": ""}, {"label": "代理権授与は口頭では無効", "reason": "代理権の授与は書面でなくても口頭でも有効です。ただし実務では委任状（書面）を作成するのが通常です。", "caution": ""}], "summary": {"head": ["概念", "内容"], "rows": [["基本契約（委任等）", "代理人に仕事を依頼する契約"], ["代理権授与行為", "本人が代理人に代理権を与える行為（独立した行為）"], ["関係", "基本契約解除後も代理権が残ることがある（取引安全のため）"]]}}},
  {id:10743,unit:'r_saikensoron',level:3,field:'rights',text:'担保保存義務の違反について正しいものはどれか。',opts:['担保保存義務はない','債権者が故意または過失により担保を喪失・減少させた場合、保証人等は担保から利益を受けることができた限度で免責される','担保保存義務違反は損害賠償のみ','物上保証人には適用されない'],ans:1,exp:'民法504条（担保保存義務）により債権者が故意または過失により担保を喪失・減少させた場合、保証人・物上保証人等は担保から利益を受けることができた限度で免責されます。',"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要です（民法446条2項）。連帯保証人には催告・検索の抗弁権がありません（民法454条）。債権譲渡の第三者対抗要件は確定日付ある証書による通知または承諾です（民法467条2項）。", "example": ""}, "reason": {"text": "担保保存義務（民法504条）は債権者が故意または過失により担保を喪失・減少させた場合、保証人・物上保証人等はその担保から利益を受けることができた限度で免責される制度です（民法504条1項）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相殺の要件</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">双方が同種の債権</text></svg>", "choices": [{"label": "担保保存義務はない", "reason": "担保保存義務は民法504条に規定されています。存在しないというのは誤りです。", "caution": ""}, {"label": "担保保存義務違反は損害賠償のみ", "reason": "担保保存義務違反の効果は損害賠償ではなく「保証人等の免責」です（民法504条1項）。", "caution": "担保保存義務違反→保証人等の免責（損害賠償ではない）。"}, {"label": "物上保証人には適用されない", "reason": "物上保証人にも担保保存義務の規定は適用されます（民法504条1項）。", "caution": ""}], "summary": {"head": ["担保保存義務（民法504条）", "内容"], "rows": [["義務者", "債権者（担保を保存する義務）"], ["違反の効果", "保証人・物上保証人等の免責（担保から受けられた利益の限度）"], ["対象者", "保証人・物上保証人・第三取得者等"], ["免責の程度", "担保から利益を受けることができた限度"]]}}},
  {id:10744,unit:'r_chinshaku',level:3,field:'rights',text:'借家契約における造作買取請求権（借地借家法33条）について正しいものはどれか。',opts:['いかなる造作も買取請求できる','賃貸人の同意を得て設置した造作は賃貸借終了時に時価での買取りを請求できる（特約で排除可）','造作買取請求権は認められていない','賃借人が自費で設置した造作のみ対象'],ans:1,exp:'借家人は賃貸人の同意を得て建物に設置した造作（エアコン等）について、賃貸借終了時に時価での買取りを請求することができます（借地借家法33条1項）。ただし特約で排除できます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "造作買取請求権とは、賃貸人の同意を得て設置した造作（エアコン・建具等）について賃借人が賃貸借終了時に時価での買取りを請求できる権利です（借地借家法33条1項）。ただし特約で排除することができます（同条2項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "いかなる造作も買取請求できる", "reason": "造作買取請求権の対象は賃貸人の同意を得て設置した造作に限られます（借地借家法33条1項）。全ての造作ではありません。", "caution": "賃貸人の同意なく設置した造作は買取請求不可。"}, {"label": "造作買取請求権は認められていない", "reason": "借地借家法33条により造作買取請求権は認められています。特約で排除することも可能です（同条2項）。", "caution": ""}, {"label": "賃借人が自費で設置した造作のみ対象", "reason": "自費で設置したかどうかではなく「賃貸人の同意を得て設置」したかどうかが要件です（借地借家法33条1項）。", "caution": ""}], "summary": {"head": ["造作買取請求権（借地借家法33条）", "内容"], "rows": [["対象", "賃貸人の同意を得て設置した造作"], ["請求内容", "時価での買取り"], ["排除特約", "有効（借地借家法33条2項）"], ["行使時期", "賃貸借終了時"]]}}},
  {id:10745,unit:'r_touki',level:3,field:'rights',text:'所有権の登記名義人が死亡した後の登記について正しいものはどれか（2024年改正後）。',opts:['相続人が任意に登記すればよい','相続または遺産分割によって不動産を取得した相続人は原則3年以内に相続登記を申請しなければならない','10年以内でよい','相続登記は不要'],ans:1,exp:'2024年4月1日施行の改正不動産登記法により、相続または遺産分割で不動産を取得した相続人は取得を知った日から3年以内に相続登記を申請する義務が課されました（不動産登記法76条の2）。違反した場合は10万円以下の過料。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "2024年4月施行の改正により相続登記が義務化されました（不動産登記法76条の2）。所有者不明土地問題を解消するための重要な制度改正です。正当な理由なく義務を怠ると過料の制裁があります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "相続人が任意に登記すればよい", "reason": "2024年4月から相続登記は義務となりました（不動産登記法76条の2）。任意ではなく義務です。", "caution": "2024年改正で義務化。任意ではありません。"}, {"label": "10年以内でよい", "reason": "相続登記の期限は相続を知った日から3年以内です（不動産登記法76条の2）。10年ではありません。", "caution": ""}, {"label": "相続登記は不要", "reason": "2024年4月施行の改正により相続登記は義務となりました。不要ではありません。", "caution": ""}], "summary": {"head": ["相続登記義務化（2024年4月施行）", "内容"], "rows": [["対象", "相続・遺産分割で取得した不動産"], ["期限", "相続を知った日から3年以内"], ["過料", "10万円以下"], ["簡易手続き", "相続人申告登記（申告のみで申請義務を一時的に満たす）"]]}}},
  {id:10746,unit:'l_menkyo',level:3,field:'law',text:'免許取消処分を受けた宅建業者の役員が再度宅建業の免許を取得できる時期として正しいものはどれか。',opts:['すぐに取得できる','取消処分の日から5年が経過しなければ免許を受けられない','3年経過後に取得できる','永久に取得できない'],ans:1,exp:'不正の手段による免許取得・業務停止処分違反等により免許を取り消された者は取消しの日から5年間は免許を受けられません（宅建業法5条1項1号・2号）。その役員も同様に5年の欠格期間が適用されます。',"kaisetsu":{"topic": "宅建業の免許：知事・大臣免許の区別・有効期間5年・欠格事由", "basis": {"text": "1都道府県のみ→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間です。", "example": ""}, "reason": {"text": "免許取消処分を受けた宅建業者の役員等は、取消処分の日から5年が経過しなければ免許を受けることができません（宅建業法5条1項3号）。これは悪質業者の関係者が別の法人を作って業を継続することを防ぐための規定です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（拘禁刑以上・特定罰金等）</text></svg>", "choices": [{"label": "すぐに取得できる", "reason": "取消処分の日から5年が経過しなければ免許を受けられません（宅建業法5条1項3号）。すぐには取得できません。", "caution": "免許取消処分の役員：5年間は免許取得不可（宅建業法5条1項3号）。"}, {"label": "3年経過後に取得できる", "reason": "5年の経過が必要です（宅建業法5条1項3号）。3年では足りません。", "caution": ""}, {"label": "永久に取得できない", "reason": "5年経過後は欠格事由から外れて免許を取得できます（宅建業法5条1項3号）。永久ではありません。", "caution": ""}], "summary": {"head": ["欠格事由の期間（宅建業法5条）", "5年間不可"], "rows": [["免許取消処分（不正等が理由）の役員等", "取消処分日から5年"], ["拘禁刑以上の刑", "刑の執行終了等から5年"], ["宅建業法・詐欺・背任等の罰金刑", "罰金から5年"]]}}},
  {id:10747,unit:'l_jusetsu',level:3,field:'law',text:'重要事項説明をIT（オンライン）で行う場合の要件として正しいものはどれか（IT重説）。',opts:['IT重説は禁止されている','一定の要件（映像・音声の送受信環境・宅建士証の確認等）を満たせば賃貸・売買ともにIT重説が認められる','賃貸のみIT重説が可能','買主の承諾なしに行える'],ans:1,exp:'2017年から賃貸（2021年から売買も含む全取引）でIT重説（テレビ会議等を利用した重要事項説明）が認められています。映像・音声の送受信環境・宅建士証の確認・相手方の意思確認等の要件を満たす必要があります。',"kaisetsu":{"topic": "重要事項説明：宅建士が説明・売主への交付は不要・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主への交付義務はありません。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能です。", "example": ""}, "reason": {"text": "IT重説（オンライン重要事項説明）は一定の要件（映像・音声の双方向通信確保・宅建士証の確認・書面交付等）を満たせば売買・賃貸ともに認められます（国土交通省ガイドライン）。相手方の承諾が必要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "IT重説は禁止されている", "reason": "IT重説は国土交通省ガイドラインに基づき認められています。「禁止」は誤りです。", "caution": ""}, {"label": "賃貸のみIT重説が可能", "reason": "IT重説は売買・賃貸ともに認められています（国土交通省ガイドライン）。賃貸のみに限定されません。", "caution": ""}, {"label": "買主の承諾なしに行える", "reason": "相手方の承諾が必要です（国土交通省ガイドライン）。承諾なしには行えません。", "caution": ""}], "summary": {"head": ["IT重説の概要", "内容"], "rows": [["根拠", "国土交通省ガイドライン"], ["対象", "売買・賃貸ともに可"], ["要件", "相手方承諾・双方向通信・宅建士証確認等"], ["書面交付", "必要"]]}}},
  {id:10748,unit:'k_toshi',level:3,field:'limit',text:'市街地開発事業等予定区域について正しいものはどれか。',opts:['開発行為が自由に行える区域','新たに都市的整備を行う地域として指定され建築や開発の制限がかかる区域','農業専用地域の別名','住宅のみ建築可能な区域'],ans:1,exp:'市街地開発事業等予定区域は市街地再開発事業等の予定区域として都市計画に定められる区域です（都市計画法12条の2）。指定後は建築・開発が制限され事業施行のために土地利用が抑制されます。',"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域での1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は市街化調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "市街地開発事業等予定区域は将来の都市的整備（新市街地形成等）のために指定され、その期間中は建築や開発の制限がかかります（都市計画法60条の2以下）。区域内の建築や土地変更は許可が必要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化する区域</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可基準</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "開発行為が自由に行える区域", "reason": "開発行為が自由に行える区域ではなく、制限がかかります（都市計画法60条の2）。", "caution": "市街地開発事業等予定区域：建築・開発の制限がかかる（都市計画法60条の2以下）。"}, {"label": "農業専用地域の別名", "reason": "農業専用地域という用語は都市計画法にはありません（都市計画法60条の2）。", "caution": ""}, {"label": "住宅のみ建築可能な区域", "reason": "住宅のみではなく、都市計画事業の施行に支障のない範囲で一定の建築は許可されます（都市計画法60条の2）。", "caution": ""}], "summary": {"head": ["市街地開発事業等予定区域（都市計画法60条の2）", "内容"], "rows": [["目的", "将来の都市的整備のための準備期間として指定"], ["制限", "建築物の建築・土地の形質変更等に許可が必要"], ["期間", "指定された事業の施行期間中"]]}}},
  {id:10749,unit:'k_kenchiku',level:3,field:'limit',text:'建築基準法における「接道義務」の内容として正しいものはどれか。',opts:['建築物の敷地は道路に接しなくてよい','建築物の敷地は原則として幅員4m以上の道路に2m以上接しなければならない','3m接すれば足りる','農地では接道義務がない'],ans:1,exp:'建築基準法上の接道義務（43条）は建築物の敷地が幅員4m以上の建築基準法上の道路に2m以上接することを原則として求めます。これを満たさない土地は「再建築不可」となります。',"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・道路斜線・用途制限", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。用途地域ごとに建築物の制限があります。", "example": ""}, "reason": {"text": "接道義務は建築物の敷地が幅員4m以上の道路に2m以上接することを原則として求めています（建築基準法43条1項）。特定行政庁の許可等の例外があります（同条2項）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">第1種低層</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">学校は建築可</text></svg>", "choices": [{"label": "建築物の敷地は道路に接しなくてよい", "reason": "接道義務があり、原則として幅員4m以上の道路に2m以上接しなければなりません（建築基準法43条1項）。", "caution": "接道義務：幅員4m以上の道路に2m以上接すること（建築基準法43条1項）。"}, {"label": "3m接すれば足りる", "reason": "原則として2m以上が必要です（建築基準法43条1項）。3mは過剰ですが2mが最低要件です。", "caution": ""}, {"label": "農地では接道義務がない", "reason": "農地でも建築物を建築する場合は接道義務があります（建築基準法43条1項）。農地だからといって免除されません。", "caution": ""}], "summary": {"head": ["接道義務（建築基準法43条1項）", "内容"], "rows": [["幅員要件", "4m以上の道路"], ["接道長さ", "2m以上"], ["例外", "特定行政庁が建築審査会の同意を得て許可"], ["2項道路", "4m未満でも特例→中心線からセットバック義務"]]}}},
  {id:10750,unit:'r_ishi',level:1,field:'rights',text:'被保佐人が不動産を売却する場合に必要なものとして正しいものはどれか。',opts:['後見人の同意','保佐人の同意','成年後見人の同意','家庭裁判所の許可のみ'],ans:1,exp:'被保佐人は民法13条1項に列挙された重要な法律行為（不動産売買・借財等）をするには保佐人の同意が必要です（民法13条1項3号）。保佐人の同意を得ずにした行為は取り消すことができます。',"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "意思表示の瑕疵には詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失の第三者は保護）・通謀虚偽表示（無効・善意の第三者は保護）があります。", "example": ""}, "reason": {"text": "被保佐人の不動産売買等の重要行為には保佐人の同意が必要です（民法13条1項3号）。後見人・成年後見人は被保佐人の支援者ではありません。保佐人が正しい支援者です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "後見人の同意", "reason": "後見人は成年被後見人の支援者です。被保佐人の支援者は保佐人です。「後見人」と「保佐人」を混同しないようにしましょう。", "caution": "後見人→成年被後見人の支援、保佐人→被保佐人の支援。"}, {"label": "成年後見人の同意", "reason": "「成年後見人」は「後見人」と同義です。被保佐人の不動産売買には保佐人の同意が必要で、成年後見人ではありません。", "caution": ""}, {"label": "家庭裁判所の許可のみ", "reason": "被保佐人の重要行為には保佐人の同意が必要です。家庭裁判所の許可のみで足りるわけではありません（保佐人が同意しない場合に家裁が許可を与えることはありますが）。", "caution": ""}], "summary": {"head": ["制限行為能力者", "支援者", "重要行為の同意"], "rows": [["未成年者", "法定代理人（親権者等）", "法定代理人の同意"], ["成年被後見人", "成年後見人", "後見人が代理"], ["被保佐人", "保佐人", "保佐人の同意"], ["被補助人", "補助人", "補助人の同意（特定行為）"]]}}},
  {id:10751,unit:'r_dairi',level:1,field:'rights',text:'代理人が本人のためにすることを示さずに行った法律行為の効力として正しいものはどれか。',opts:['無効','代理行為としての効果は本人に帰属しないが代理人が相手方との関係で義務を負う','常に本人に効果が帰属する','相手方の同意があれば本人に帰属する'],ans:1,exp:'代理人が顕名せずに行った行為は原則として本人に効果が帰属しません（民法100条）。ただし相手方が代理人であることを知りまたは知ることができた場合は本人に帰属します。',"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護する制度です。", "example": ""}, "reason": {"text": "代理行為の成立には顕名（本人のためにすることを示すこと）が必要です（民法99条1項）。顕名がない場合、代理行為としての効果は本人に帰属しません。この場合、行為した者自身が義務を負います（民法100条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "無効", "reason": "顕名なき行為は無効ではなく、代理人自身が相手方との関係で義務を負います（民法100条）。", "caution": "顕名なし→無効ではなく、代理人本人の行為として扱われます（民法100条）。"}, {"label": "常に本人に効果が帰属する", "reason": "顕名がない場合は原則として本人に効果が帰属しません（民法100条本文）。相手方が本人のためにすることを知り、または知ることができた場合は例外です（同条ただし書）。", "caution": ""}, {"label": "相手方の同意があれば本人に帰属する", "reason": "民法100条ただし書によれば、相手方が本人のためにすることを「知り」または「知ることができた」場合に本人に帰属します。相手方の「同意」は要件ではありません。", "caution": ""}], "summary": {"head": ["顕名の有無", "効果"], "rows": [["顕名あり", "代理行為として本人に効果帰属（民法99条1項）"], ["顕名なし（原則）", "代理人自身の行為として代理人が義務を負う（民法100条本文）"], ["顕名なし（例外）", "相手方が本人のためと知りまたは知ることができた場合は本人に帰属（民法100条ただし書）"]]}}},
  {id:10752,unit:'r_tanpo',level:1,field:'rights',text:'先取特権について正しいものはどれか。',opts:['当事者の契約により発生する担保物権','法律の規定により当然に生じる法定担保物権','登記しなければ効力がない','不動産にのみ成立する'],ans:1,exp:'先取特権は法律の規定により当然に成立する法定担保物権です（民法303条）。一般の先取特権・動産先取特権・不動産先取特権の3種があります。',"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権です（民法369条）。質権は占有の移転が必要です。先取特権は法律上当然に成立する法定担保物権です。", "example": ""}, "reason": {"text": "先取特権は法律の規定により当然に生じる法定担保物権です（民法303条）。当事者の契約なしに一定の債権者が他の債権者に優先して弁済を受けられます。一般の先取特権（雇用・日用品費等）と特別の先取特権（動産・不動産）があります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・非占有</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・占有</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "当事者の契約により発生する担保物権", "reason": "先取特権は法定担保物権であり、契約によらず法律上当然に生じます（民法303条）。", "caution": "先取特権＝法定担保物権（契約不要）。"}, {"label": "登記しなければ効力がない", "reason": "先取特権は登記なしでも法定担保物権として効力があります（民法303条）。ただし不動産先取特権は登記が対抗要件になる場合があります。", "caution": ""}, {"label": "不動産にのみ成立する", "reason": "先取特権には一般の先取特権（全財産対象）・動産先取特権・不動産先取特権があります（民法306条以下）。不動産のみではありません。", "caution": ""}], "summary": {"head": ["先取特権の種類", "対象", "例"], "rows": [["一般の先取特権", "債務者の全財産", "雇用関係・日用品費等（民法306条）"], ["動産先取特権", "特定の動産", "不動産賃貸・農業・旅館等（民法311条）"], ["不動産先取特権", "特定の不動産", "不動産保存・工事・売買（民法325条）"]]}}},
  {id:10753,unit:'r_saikensoron',level:1,field:'rights',text:'履行不能が生じた場合の損害賠償について正しいものはどれか。',opts:['履行不能の場合は損害賠償を請求できない','債務者の責めに帰すべき事由による履行不能の場合は損害賠償を請求できる','履行不能は常に損害賠償義務を生じさせる','不可抗力でも損害賠償できる'],ans:1,exp:'債務不履行による損害賠償（民法415条）は債務者の責めに帰すべき事由（帰責事由）がある場合に請求できます。2020年改正民法では帰責事由がない場合（不可抗力等）は損害賠償責任を負わないと明確化されました。',"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要です（民法446条2項）。連帯保証人には催告・検索の抗弁権がありません（民法454条）。債権譲渡の第三者対抗要件は確定日付ある証書による通知または承諾です（民法467条2項）。", "example": ""}, "reason": {"text": "履行不能が債務者の責めに帰すべき事由（帰責事由）による場合、債権者は損害賠償を請求できます（民法415条1項）。不可抗力等、帰責事由がない場合は損害賠償請求はできません（同条1項ただし書）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相殺の要件</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">双方が同種の債権</text></svg>", "choices": [{"label": "履行不能の場合は損害賠償を請求できない", "reason": "帰責事由がある履行不能では損害賠償請求ができます（民法415条1項）。「できない」は誤りです。", "caution": "帰責事由あり→損害賠償可。帰責事由なし→不可。"}, {"label": "履行不能は常に損害賠償義務を生じさせる", "reason": "帰責事由のない履行不能（不可抗力等）では損害賠償義務は生じません（民法415条1項ただし書）。", "caution": ""}, {"label": "不可抗力でも損害賠償できる", "reason": "不可抗力による履行不能は帰責事由がなく損害賠償請求はできません（民法415条1項ただし書）。", "caution": ""}], "summary": {"head": ["履行不能と損害賠償（民法415条）", "内容"], "rows": [["帰責事由あり", "損害賠償請求可（民法415条1項）"], ["帰責事由なし（不可抗力等）", "損害賠償請求不可（民法415条1項ただし書）"], ["解除", "帰責事由なくても解除可（民法542条）"], ["損害賠償の範囲", "通常損害＋予見可能な特別損害（民法416条）"]]}}},
  {id:10754,unit:'r_fuhoko',level:1,field:'rights',text:'失火責任法（失火ノ責任ニ関スル法律）について正しいものはどれか。',opts:['火事を起こした者は無過失責任を負う','失火者の責任は重大な過失がある場合に限られる','失火責任法はない','延焼しても責任はない'],ans:1,exp:'失火責任法により、失火（過失による火事）の場合は失火者に重大な過失がある場合にのみ損害賠償責任が生じます。一般の過失だけでは責任を負いません（軽過失は免責）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "失火責任法（失火ノ責任ニ関スル法律）は、失火者の責任を「重大な過失」がある場合に限定する特別法です。木造建築が密集する日本の事情から、軽過失による失火では責任を課さないこととしています。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "火事を起こした者は無過失責任を負う", "reason": "失火責任法により失火者の責任は「重大な過失」がある場合に限られます。無過失責任ではありません。", "caution": "失火責任法＝重大な過失がある場合のみ責任（軽過失は免責）。"}, {"label": "失火責任法はない", "reason": "失火責任法（失火ノ責任ニ関スル法律）は現存する法律です（明治32年制定）。", "caution": ""}, {"label": "延焼しても責任はない", "reason": "重大な過失がある場合は延焼による損害についても責任を負います（失火責任法）。", "caution": ""}], "summary": {"head": ["失火責任法", "内容"], "rows": [["原則", "重大な過失がある場合のみ責任"], ["軽過失", "免責（民法709条の特則）"], ["ガス爆発等", "失火責任法の適用なし（不法行為一般で判断）"], ["根拠", "木造密集地帯での過重な責任を回避"]]}}},
  {id:10755,unit:'r_shakuchi',level:1,field:'rights',text:'定期建物賃貸借（定期借家）の契約方法として正しいものはどれか。',opts:['口頭で締結できる','書面によること・更新がない旨を書面で事前に告知することが必要','公正証書でなければならない','通常の賃貸借と同様の手続きでよい'],ans:1,exp:'定期建物賃貸借は書面（または電磁的記録）によって締結し（借地借家法38条1項）、さらに契約締結前に更新がない旨等を書面で賃借人に説明する手続きが必要です（同条3項）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "定期建物賃貸借の契約方法は①書面または電磁的記録による契約（借地借家法38条1項）、②賃貸人が賃借人に更新がない旨等を事前に書面または電磁的記録で説明・告知すること（同条2項）の2要件が必要です。公正証書は不要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "口頭で締結できる", "reason": "定期建物賃貸借は書面または電磁的記録によらなければなりません（借地借家法38条1項）。口頭では無効です。", "caution": ""}, {"label": "公正証書でなければならない", "reason": "定期建物賃貸借に公正証書は必須ではありません（借地借家法38条1項）。書面（電磁的記録も可）であれば足ります。公正証書が必須なのは事業用定期借地権です。", "caution": "定期借家：書面（公正証書不要）。事業用定期借地権：公正証書必須。"}, {"label": "通常の賃貸借と同様の手続きでよい", "reason": "定期建物賃貸借には①書面による契約②書面による事前告知という特別の要件があります（借地借家法38条1項・2項）。通常の賃貸借と同様ではありません。", "caution": ""}], "summary": {"head": ["定期建物賃貸借の成立要件（借地借家法38条）", "内容"], "rows": [["①契約方式", "書面または電磁的記録（公正証書不要）"], ["②事前告知", "更新がない旨等を別の書面または電磁的記録で告知"], ["口頭", "無効"], ["告知を欠く場合", "定期借家としての効力なし→普通借家として有効"]]}}},
  {id:10756,unit:'r_kukku',level:1,field:'rights',text:'区分所有建物の敷地に関して正しいものはどれか。',opts:['敷地は区分所有者全員が単独で所有する','専有部分を持つ区分所有者は建物の敷地について利用権（敷地利用権）を持つ','敷地は管理会社が所有する','敷地の持分は変更できない'],ans:1,exp:'区分所有者は専有部分と切り離せない形で建物の敷地についての利用権（敷地利用権）を有します（区分所有法22条）。この敷地利用権と専有部分は原則として分離して処分できません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "区分所有者は専有部分と共に、建物の敷地を利用する権利（敷地利用権）を持ちます（区分所有法22条）。敷地利用権には地上権・賃借権等があり、専有部分と分離して処分することは原則禁止されています（同条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "敷地は区分所有者全員が単独で所有する", "reason": "敷地は通常区分所有者全員の共有ですが、各自が「単独所有」するのではありません。各自が持分を持つ共有形態です。", "caution": ""}, {"label": "敷地は管理会社が所有する", "reason": "敷地の所有者は区分所有者（または地主）であり、管理会社ではありません。", "caution": ""}, {"label": "敷地の持分は変更できない", "reason": "規約や合意により敷地利用権の割合を変更することは可能です（区分所有法22条等）。「変更できない」は誤りです。", "caution": ""}], "summary": {"head": ["敷地利用権（区分所有法22条）", "内容"], "rows": [["意味", "専有部分を所有するための敷地を利用する権利"], ["種類", "所有権・地上権・賃借権等"], ["分離処分", "専有部分と分離処分は原則禁止（区分所有法22条1項）"], ["割合", "規約で定めがなければ専有部分の床面積の割合"]]}}},
  {id:10757,unit:'r_sorin',level:2,field:'rights',text:'共有物に対する不法占拠者への妨害排除請求について正しいものはどれか。',opts:['共有者全員で行わなければならない','各共有者が単独で妨害排除請求（保存行為）できる','過半数の共有者が合意した場合のみ','訴訟は全員参加が必要'],ans:1,exp:'不法占拠者への妨害排除請求は共有物の「保存行為」に該当し各共有者が単独で行使できます（民法252条5項）。保存行為は共有物の現状を維持する行為で他の共有者の同意は不要です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "共有物に対する不法占拠者への妨害排除請求は保存行為（現状維持）として各共有者が単独で行えます（民法252条5項・判例）。共有者全員での共同訴訟は必要ではなく、一人でも訴えを提起できます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "共有者全員で行わなければならない", "reason": "不法占拠者への妨害排除請求（保存行為）は各共有者が単独で行えます（民法252条5項・判例）。全員での共同行使は不要です。", "caution": "保存行為（妨害排除請求等）＝単独可（民法252条5項）。"}, {"label": "過半数の共有者が合意した場合のみ", "reason": "保存行為は単独で行えます（民法252条5項）。過半数合意は管理行為の要件です（同条1項）。", "caution": ""}, {"label": "訴訟は全員参加が必要", "reason": "保存行為としての訴訟は各共有者が単独で提起できます（民法252条5項・判例）。全員参加は不要です。", "caution": ""}], "summary": {"head": ["保存行為と共有", "内容"], "rows": [["保存行為", "各共有者が単独で可（民法252条5項）"], ["妨害排除請求", "保存行為として単独で訴訟提起可（判例）"], ["管理行為", "持分価格の過半数（民法252条1項）"], ["変更行為", "全員の同意（民法251条1項）"]]}}},
  {id:10758,unit:'l_hosho',level:3,field:'law',text:'宅建業保証協会の弁済業務保証金の「還付限度額」について正しいものはどれか。',opts:['供託している弁済業務保証金の全額','その宅建業者が社員でなかった場合に供託すべき営業保証金額に相当する額が上限','一件あたり1000万円が上限','還付額に上限はない'],ans:1,exp:'弁済業務保証金から還付を受けることができる限度額は、その宅建業者が保証協会の社員でなかったとした場合に供託すべき営業保証金の額（主たる事務所1000万円・従たる事務所500万円等の合計）が上限です（宅建業法64条の8第2項）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "保証協会の弁済業務保証金から還付を受けられる上限は、当該宅建業者が社員でなかった場合に供託すべきであった営業保証金の額に相当します（宅建業法64条の8第1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "供託している弁済業務保証金の全額", "reason": "弁済業務保証金の全額が還付上限ではなく、当該業者分の営業保証金相当額が上限です（宅建業法64条の8第1項）。", "caution": ""}, {"label": "一件あたり1000万円が上限", "reason": "1件あたりの上限ではなく、当該業者の営業保証金相当額が総額の上限です（宅建業法64条の8第1項）。", "caution": ""}, {"label": "還付額に上限はない", "reason": "還付上限は当該業者が供託すべきであった営業保証金の額です（宅建業法64条の8第1項）。上限なしではありません。", "caution": ""}], "summary": {"head": ["弁済業務保証金の還付上限（宅建業法64条の8）", "内容"], "rows": [["上限の基準", "社員でなかった場合の営業保証金相当額"], ["主たる事務所のみ", "上限1000万円"], ["主＋従たる1か所", "上限1500万円"], ["分担金との差", "保証協会が差額を負担（相互扶助の仕組み）"]]}}},
  {id:10759,unit:'l_37jo',level:3,field:'law',text:'電磁的方法による37条書面の交付について正しいものはどれか（2022年改正後）。',opts:['電磁的方法による交付は禁止','相手方の承諾を得た場合に電磁的方法で37条書面を提供できる','電磁的方法による提供には国土交通大臣の許可が必要','自動的に電磁的方法が認められる'],ans:1,exp:'2022年5月施行の宅建業法改正により、取引の相手方等の承諾を得た場合に限り電磁的方法による書面（37条書面等）の提供が認められました（宅建業法37条4項）。',"kaisetsu":{"topic": "37条書面：全取引で交付・記名（押印不要）・移転登記申請時期は必要的記載事項", "basis": {"text": "37条書面は売買・交換・賃貸借の全取引で契約の双方当事者に交付が義務（宅建業法37条）。引渡し時期・移転登記申請時期は必要的記載事項。2021年改正で押印は不要になり記名のみで足ります。", "example": ""}, "reason": {"text": "2022年の改正により、37条書面は相手方の承諾を得た場合に電磁的記録で提供できるようになりました（宅建業法37条4項）。国土交通大臣の許可や自動的な認定は不要で、相手方の承諾のみが要件です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付義務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全取引・双方当事者</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡時期・移転登記申請時期等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要）</text></svg>", "choices": [{"label": "電磁的方法による交付は禁止", "reason": "2022年改正で電磁的提供が認められました（宅建業法37条4項）。「禁止」は誤りです。", "caution": "2022年改正：37条書面の電磁的提供が認められた。"}, {"label": "電磁的方法による提供には国土交通大臣の許可が必要", "reason": "大臣の許可は不要です（宅建業法37条4項）。相手方の承諾で足ります。", "caution": ""}, {"label": "自動的に電磁的方法が認められる", "reason": "相手方の承諾が必要です（宅建業法37条4項）。自動的には認められません。", "caution": ""}], "summary": {"head": ["37条書面の電磁的提供（2022年改正）", "内容"], "rows": [["要件", "相手方の承諾"], ["宅建士の署名", "電子署名が必要（宅建業法37条3項）"], ["35条書面", "同様に電磁的提供可（相手方承諾必要）"], ["大臣許可", "不要"]]}}},
  {id:10760,unit:'k_kenchiku',level:1,field:'limit',text:'建築物の用途変更において確認申請が必要な場合として正しいものはどれか。',opts:['用途変更は常に確認申請が必要','特殊建築物の用途に変更する場合で床面積200m2超の場合は確認申請が必要','用途変更には確認申請は不要','200m2以下の変更は全て不要'],ans:1,exp:'用途変更により特殊建築物（学校・病院・劇場・ホテル等）となる場合で床面積200m2を超えるものは建築確認が必要です（建築基準法87条）。200m2以下の用途変更は確認申請不要です。',"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・道路斜線・用途制限", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。用途地域ごとに建築物の制限があります。", "example": ""}, "reason": {"text": "建築物の用途変更において、特殊建築物の用途に変更する場合で用途に供する部分の床面積が200㎡を超える場合は建築確認が必要です（建築基準法87条1項）。200㎡以下の用途変更は確認申請不要です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">第1種低層</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">学校は建築可</text></svg>", "choices": [{"label": "用途変更は常に確認申請が必要", "reason": "200㎡以下の特殊建築物への用途変更は確認申請不要です（建築基準法87条1項）。「常に必要」は誤りです。", "caution": "用途変更の確認申請：特殊建築物で200㎡超の場合に必要（建築基準法87条1項）。"}, {"label": "用途変更には確認申請は不要", "reason": "特殊建築物への用途変更で200㎡超の場合は確認申請が必要です（建築基準法87条1項）。「不要」は誤りです。", "caution": ""}, {"label": "200m2以下の変更は全て不要", "reason": "200㎡以下への特殊建築物用途変更は確認申請不要です（建築基準法87条1項）。これは正しい内容ですが、設問の正解は選択肢2（200㎡超が必要な場合の記述）です。", "caution": ""}], "summary": {"head": ["用途変更の建築確認（建築基準法87条1項）", "内容"], "rows": [["確認申請が必要", "特殊建築物の用途に変更する場合で200㎡超"], ["確認申請不要", "200㎡以下の用途変更・非特殊建築物への変更等"], ["特殊建築物の例", "飲食店・ホテル・病院・共同住宅等（別表第一）"]]}}},
  {id:10761,unit:'r_baibai',level:1,field:'rights',text:'不特定物（種類物）の売買で引渡し前に滅失した場合について正しいものはどれか。',opts:['買主は代金を支払わなくてよい','特定されるまでは売主がリスクを負担し同等の物を調達して引き渡す義務がある','リスクは買主が常に負担する','特定物と同様に扱われる'],ans:1,exp:'不特定物の売買は「特定」が生じるまでは売主が調達義務を負い滅失のリスクも売主が負います（民法401条2項）。特定後は特定物と同様に扱われます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "不特定物（種類物）の売買では目的物が「特定」されるまでは売主が同等の物を調達して引き渡す義務を負います（民法401条）。特定後は特定物と同様の扱いになります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "買主は代金を支払わなくてよい", "reason": "特定物が滅失した場合の危険負担の問題と異なり、不特定物は「特定」前は売主が同等品を調達する義務があります（民法401条）。買主の代金支払義務は消滅しません。", "caution": "不特定物→特定前は同等品調達義務あり。"}, {"label": "リスクは買主が常に負担する", "reason": "特定前は売主に調達義務があるため、実質的にリスクは売主が負います（民法401条）。", "caution": ""}, {"label": "特定物と同様に扱われる", "reason": "不特定物は「特定」前は特定物と同様には扱われません（民法401条）。特定後に特定物と同様の扱いになります。", "caution": ""}], "summary": {"head": ["種類物（不特定物）の売買", "内容"], "rows": [["特定前", "売主は同等品を調達して引き渡す義務（民法401条）"], ["特定後", "特定物と同様の扱い（危険移転等）"], ["特定の方法", "当事者の合意・売主の分離・債務者の提供等"]]}}},
  {id:10762,unit:'r_jiko',level:1,field:'rights',text:'時効の利益を放棄できる時期として正しいものはどれか。',opts:['時効が完成する前であればいつでも放棄できる','時効の利益の放棄は時効完成後に限られる','放棄はいつでもできる','時効の放棄は禁止されている'],ans:1,exp:'時効の利益は時効完成後でなければ放棄できません（民法146条）。時効完成前の予め放棄する特約は時効制度の趣旨を没却するため無効とされています。',"kaisetsu":{"topic": "消滅時効：知った時から5年または行使可能時から10年", "basis": {"text": "一般の債権の消滅時効は「権利行使できると知った時から5年」または「権利行使できる時から10年」のいずれか早い方で完成します（民法166条1項）。時効は援用して初めて効力が発生します（民法145条）。", "example": ""}, "reason": {"text": "時効の利益の放棄は時効完成後にのみできます（民法146条）。完成前に放棄を認めると債務者が事前に放棄を強制させられる可能性があり、時効制度の趣旨を没却するためです。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">時効期間</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人の生命・身体への損害</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年または20年</text></svg>", "choices": [{"label": "時効が完成する前であればいつでも放棄できる", "reason": "時効完成前の放棄は認められません（民法146条）。完成後にのみ放棄できます。", "caution": "完成前の放棄は無効（民法146条）。"}, {"label": "放棄はいつでもできる", "reason": "時効の利益の放棄は完成後にのみできます（民法146条）。完成前はできません。", "caution": ""}, {"label": "時効の放棄は禁止されている", "reason": "時効完成後の放棄は有効です（民法146条反対解釈）。完成前の放棄のみが禁止されています。", "caution": ""}], "summary": {"head": ["時期", "放棄の可否"], "rows": [["時効完成前", "不可（無効・民法146条）"], ["時効完成後", "可（民法146条反対解釈）"], ["放棄の効力", "相対効（放棄者のみ・第三者に及ばない）"]]}}},
  {id:10763,unit:'r_bukken',level:1,field:'rights',text:'物権の「排他性」について正しいものはどれか。',opts:['同一物件に同一内容の物権が2つ以上成立できる','一つの物件の上に同一内容の物権は1つしか存在できない（一物一権主義）','物権は他人と共有できる','物権の排他性とは第三者への対抗力を意味する'],ans:1,exp:'物権には排他性があり同一の物の上に同一内容の物権は1つしか成立できません（一物一権主義）。例えば所有権は1つの物に1つしか成立せず二重の所有権は認められません。',"kaisetsu":{"topic": "物権変動：登記が対抗要件・不法占拠者には登記不要", "basis": {"text": "不動産の物権変動は登記が第三者への対抗要件です（民法177条）。不法占拠者には登記なく対抗できます。相続の法定相続分超過部分は登記が必要です（民法899条の2）。", "example": ""}, "reason": {"text": "物権の排他性（一物一権主義）は、法律関係の明確化のための原則です。同一物に複数の所有権が並存すると誰が真の所有者かわからなくなるため、排他性により1つの物に1つの所有権しか認めません。共有はあくまで1つの所有権を分け合う形です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">物権変動の対抗要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対抗要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">二重譲渡</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先に登記した者が優先</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不法占拠者</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記不要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物賃借権</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡し</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続（超過部分）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記必要</text></svg>", "choices": [{"label": "同一物件に同一内容の物権が2つ以上成立できる", "reason": "物権の排他性（一物一権主義）により、同一物の上に同一内容の物権は1つしか成立できません。", "caution": "排他性＝同一物に同一内容の物権は1つのみ（一物一権主義）。"}, {"label": "物権は他人と共有できる", "reason": "共有は「1つの所有権を複数人が持分という形で分け合う」ものであり、「複数の所有権が並立する」わけではありません。排他性と矛盾しません。", "caution": "共有≠複数の所有権の並立。1つの所有権を分け合う形です。"}, {"label": "物権の排他性とは第三者への対抗力を意味する", "reason": "第三者への対抗力は登記等の「対抗要件」の問題です。排他性は「同一物に同一内容の物権は1つしか存在できない」という性質そのものです。", "caution": ""}], "summary": {"head": ["物権の特質", "内容"], "rows": [["絶対性", "誰に対しても主張できる権利"], ["排他性", "同一物に同一内容の物権は1つのみ（一物一権主義）"], ["優先性", "物権は同一物の上の債権に優先する"], ["追及効", "物が誰の手に渡っても権利を追いかけられる"]]}}},
  {id:10764,unit:'l_cooling',level:1,field:'law',text:'手付金等の保全措置が必要な「完成物件」の基準として正しいものはどれか。',opts:['手付金等が代金の5%超または1000万円超','手付金等が代金の10%超または1000万円超','手付金等が代金の20%超','手付金等が500万円超'],ans:1,exp:'完成物件の手付金等の保全措置は手付金等が代金の10%を超えるまたは1000万円を超える場合に必要です（宅建業法41条の2第1項）。未完成物件は5%超または1000万円超が基準です。',"kaisetsu":{"topic": "クーリングオフ：告知日から8日以内・書面で・事務所では不可・全額返還", "basis": {"text": "クーリングオフは告知を受けた日から8日以内に書面で行います（宅建業法37条の2）。事務所・モデルルーム等での申込みはクーリングオフ不可。解除後業者は全額返還（費用控除不可）。", "example": ""}, "reason": {"text": "宅建業者が自ら売主として完成物件を売却する場合、手付金等の保全措置が必要になる基準は「代金の10%超または1000万円超」です（宅建業法41条の2第1項）。未完成物件の5%超・1000万円超より緩い基準です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">クーリングオフのポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">告知日から8日以内</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">方法</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面（発信主義）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所での申込み</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">クーリングオフ不可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除後</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全額返還（費用控除不可）</text></svg>", "choices": [{"label": "手付金等が代金の5%超または1000万円超", "reason": "5%超は未完成物件の基準です（宅建業法41条1項）。完成物件は10%超または1000万円超です（同法41条の2第1項）。", "caution": "未完成：5%超または1000万円超。完成：10%超または1000万円超。"}, {"label": "手付金等が代金の20%超", "reason": "20%超という基準はありません（宅建業法41条の2第1項）。完成物件の基準は10%超または1000万円超です。", "caution": ""}, {"label": "手付金等が500万円超", "reason": "500万円という基準はありません（宅建業法41条の2第1項）。10%超または1000万円超が基準です。", "caution": ""}], "summary": {"head": ["保全措置の基準（宅建業者自ら売主）", "閾値"], "rows": [["未完成物件", "5%超または1000万円超→保全措置必要"], ["完成物件", "10%超または1000万円超→保全措置必要"], ["方法", "銀行等の保証・保証保険・寄託等"]]}}},
  {id:10765,unit:'l_kokoku',level:1,field:'law',text:'宅建業者が分譲マンションの広告をする際に必ず表示しなければならない事項として正しいものはどれか。',opts:['分譲業者代表者の顔写真','取引態様・所在地・交通・用途地域・面積・価格等の物件情報','近隣の飲食店情報','建設会社の名称'],ans:1,exp:'宅建業者が宅地建物の広告をする際には公正競争規約に基づき取引態様・所在地・交通・価格・面積・用途地域等の必要的表示事項を記載しなければなりません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "宅建業者がマンションの広告をする際は取引態様・所在地・交通・用途地域・面積・価格等の物件情報を必ず表示しなければなりません（宅建業法34条・不動産公正競争規約等）。代表者写真・飲食店情報・建設会社名は必須表示事項ではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "分譲業者代表者の顔写真", "reason": "代表者の写真は広告の必須表示事項ではありません（宅建業法34条・不動産公正競争規約）。", "caution": "広告の必須表示事項：取引態様・物件情報（所在地・面積・価格等）。"}, {"label": "近隣の飲食店情報", "reason": "近隣の飲食店情報は広告の必須表示事項ではありません（宅建業法34条・不動産公正競争規約）。", "caution": ""}, {"label": "建設会社の名称", "reason": "建設会社の名称は広告の必須表示事項ではありません（宅建業法34条・不動産公正競争規約）。建物の設計・施工会社の表示は任意的な情報です。", "caution": ""}], "summary": {"head": ["広告の主な表示事項（不動産公正競争規約等）", "内容"], "rows": [["取引態様", "売主・代理・媒介の別（宅建業法34条）"], ["物件の所在地・交通", "最寄り駅・バス停からの距離等"], ["用途地域", "都市計画法上の用途地域"], ["面積", "専有面積・敷地面積等"], ["価格", "販売価格・管理費・修繕積立金等"]]}}},
  {id:10766,unit:'t_kotei',level:1,field:'tax',text:'固定資産税と都市計画税の賦課対象として正しいものはどれか。',opts:['固定資産税は土地のみ課税','固定資産税は土地・家屋・償却資産に課税、都市計画税は市街化区域内の土地・家屋に課税','都市計画税は全国一律に課税','償却資産には都市計画税が課税される'],ans:1,exp:'固定資産税は土地・家屋・事業用の償却資産に課税されます（地方税法341条）。都市計画税は市街化区域内の土地・家屋を対象とし（地方税法702条）、償却資産には課税されません。',"kaisetsu":{"topic": "固定資産税：市町村が課す地方税・賦課期日は1月1日・評価替えは3年ごと", "basis": {"text": "固定資産税は市町村（東京23区は都）が課す地方税です（地方税法343条）。賦課期日は毎年1月1日。評価替えは3年ごと（基準年度）。住宅用地の特例：200㎡以下は課税標準1/6、超過部分は1/3。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">固定資産税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市町村（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賦課期日</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">評価替え</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年ごと</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅用地（200㎡以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税標準1/6</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10767,unit:'t_joto',level:1,field:'tax',text:'長期譲渡所得と短期譲渡所得の区別の基準として正しいものはどれか。',opts:['所有期間が3年超か以下か','譲渡した年の1月1日現在の所有期間が5年超か5年以下か','取得日から5年','購入時の価格で判断'],ans:1,exp:'不動産の譲渡所得は譲渡した年の1月1日現在の所有期間が5年を超えるものを「長期譲渡所得」（税率20%）、5年以下のものを「短期譲渡所得」（税率39%）として税率が異なります（租税特別措置法31条・32条）。',"kaisetsu":{"topic": "譲渡所得：分離課税・長期は20%・3,000万円控除は3年に1回", "basis": {"text": "土地・建物の譲渡所得は分離課税（申告分離課税）。長期（5年超）の税率は合計20%（所得税15%+住民税5%）。短期（5年以下）は39%（所得税30%+住民税9%）。3,000万円特別控除は前年・前々年に適用があれば使えません（3年に1回）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">譲渡所得のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税方式</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">分離課税</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">長期（5年超）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計20%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">短期（5年以下）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計39%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3,000万円控除</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年に1回の制限</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10768,unit:'r_souzoku',level:3,field:'rights',text:'遺留分侵害額請求権の行使方法と時効について正しいものはどれか。',opts:['遺留分の侵害があれば自動的に取消しになる','遺留分侵害額請求権は金銭の支払いを求める権利で相続の開始及び遺留分侵害を知った時から1年（相続開始から10年）で消滅する','裁判によらなければ行使できない','遺留分の返還は物での返還が原則'],ans:1,exp:'2019年民法改正により遺留分制度が見直され遺留分侵害額請求権は金銭による支払いを求める権利となりました（民法1046条）。行使期間は遺留分侵害を知った時から1年・相続開始から10年です（民法1048条）。',"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2", "basis": {"text": "配偶者と子の場合は各1/2（民法900条）。相続放棄は3か月以内に家庭裁判所へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2です（民法1042条）。遺産分割協議は全員合意が必要です。", "example": ""}, "reason": {"text": "2019年改正により遺留分侵害額請求権は金銭の支払いを求める権利となりました（民法1046条）。旧法の現物返還（遺留分減殺請求）から金銭請求に変更されました。消滅時効は相続開始及び遺留分侵害を知った時から1年、または相続開始から10年です（民法1048条）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続の主要ポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子の相続分</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は法定相続分の1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割協議</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "遺留分の侵害があれば自動的に取消しになる", "reason": "遺留分侵害があっても自動的に取消しにはなりません。遺留分権利者が遺留分侵害額請求権を行使する必要があります（民法1046条）。", "caution": ""}, {"label": "裁判によらなければ行使できない", "reason": "遺留分侵害額請求権は裁判外の意思表示でも行使できます（民法1046条）。内容証明郵便等での請求が一般的です。", "caution": ""}, {"label": "遺留分の返還は物での返還が原則", "reason": "2019年改正後は金銭の支払いが原則です（民法1046条）。旧法の物での返還（現物返還）から金銭請求に変更されました。", "caution": "2019年改正：現物返還→金銭請求に変更。"}], "summary": {"head": ["遺留分侵害額請求権", "内容"], "rows": [["性質", "金銭の支払いを求める請求権（民法1046条）"], ["行使方法", "裁判外でも可（意思表示で足りる）"], ["消滅時効", "侵害を知った時から1年・相続開始から10年（民法1048条）"], ["旧法との違い", "旧法：現物返還→新法：金銭請求"]]}}},
  {id:10769,unit:'r_tanpo',level:3,field:'rights',text:'担保不動産収益執行について正しいものはどれか。',opts:['競売の別名','担保不動産の賃料等の収益から弁済を受ける制度で競売と異なり不動産の所有権移転が伴わない','不動産が滅失しないと使えない','抵当権者のみが申立てできる'],ans:1,exp:'担保不動産収益執行（民事執行法180条2号）は抵当不動産の管理人を選任して賃料等の収益を収取し弁済に充てる制度です。競売のように所有権が移転しないため所有者が居住し続けながら債務を返済するという活用方法があります。',"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権です（民法369条）。質権は占有の移転が必要です。先取特権は法律上当然に成立する法定担保物権です。", "example": ""}, "reason": {"text": "担保不動産収益執行は抵当権の実行方法の一つで、担保不動産の管理・賃料等の収益から優先弁済を受ける制度です（民事執行法180条2号）。競売と異なり不動産の所有権は移転せず、収益から弁済を受け続けます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・非占有</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・占有</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "競売の別名", "reason": "担保不動産収益執行は競売とは異なる実行方法です（民事執行法180条2号）。競売は不動産の所有権が移転しますが、収益執行は移転しません。", "caution": "競売≠担保不動産収益執行。競売は所有権移転あり、収益執行は所有権移転なし。"}, {"label": "不動産が滅失しないと使えない", "reason": "担保不動産収益執行は不動産が存続している状態で利用します。滅失した場合は使えません。「滅失しないと使えない」という表現は逆です。", "caution": ""}, {"label": "抵当権者のみが申立てできる", "reason": "担保不動産収益執行は抵当権者等担保権者が申立てできます（民事執行法180条2号）。一般論としては正しいですが「のみ」という部分が問題になる場合があります。", "caution": ""}], "summary": {"head": ["抵当権の実行方法", "所有権移転", "特徴"], "rows": [["担保不動産競売", "あり", "一括で代金回収"], ["担保不動産収益執行", "なし", "賃料等の収益から継続的に回収"], ["物上代位（賃料差押え）", "なし", "特定の賃料債権から回収"]]}}},
  {id:10770,unit:'k_toshi',level:1,field:'limit',text:'「用途地域」の決定権者として正しいものはどれか。',opts:['市町村（都市計画として決定）','都道府県知事','国土交通大臣','農業委員会'],ans:0,exp:'用途地域は市町村が都市計画として定めます（都市計画法8条・15条）。ただし指定都市以外の市町村は都道府県知事の承認を要する場合があります。',"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域での1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は市街化調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "用途地域は市町村が都市計画として決定します（都市計画法19条1項）。用途地域は地域の土地利用の方針を決める重要な計画であり、地域に最も身近な市町村が決定します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化する区域</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可基準</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "都道府県知事", "reason": "用途地域は市町村が決定します（都市計画法19条1項）。都道府県知事ではありません。", "caution": "用途地域：市町村が決定（都市計画法19条1項）。"}, {"label": "国土交通大臣", "reason": "用途地域は市町村が決定します（都市計画法19条1項）。国交大臣ではありません。", "caution": ""}, {"label": "農業委員会", "reason": "農業委員会は農地に関する機関であり、用途地域の決定とは無関係です（都市計画法19条1項）。", "caution": ""}], "summary": {"head": ["都市計画の決定権限（都市計画法15条・19条）", "決定者"], "rows": [["広域的・基盤的都市計画", "都道府県（区域区分・都市計画道路等）"], ["用途地域・地区計画等", "市町村"], ["複数都府県にまたがる", "国土交通大臣"]]}}},
  {id:10771,unit:'k_kukaku',level:3,field:'limit',text:'仮換地の使用収益が制限される「使用収益の停止」について正しいものはどれか。',opts:['仮換地が指定されると自動的に停止される','施行者が特別の事情がある場合に仮換地の使用収益の開始日を指定しないことで使用収益を留保できる','使用収益の停止は区分所有者の同意が必要','使用収益停止は原則認められない'],ans:1,exp:'仮換地の指定に際して施行者は使用収益の開始日を仮換地の指定の効力発生日と別に定める（または定めない）ことができます（土地区画整理法99条1項但書）。これにより仮換地の使用収益を留保することができます。',"kaisetsu":{"topic": "土地区画整理法：換地は公告翌日確定・仮換地は従前地使用不可・組合は2/3以上", "basis": {"text": "換地処分の公告翌日から換地が確定します（土地区画整理法104条）。仮換地の指定後は従前地を使用できなくなります（同法99条）。組合設立には土地所有者・借地権者の各2/3以上の同意が必要です。", "example": ""}, "reason": {"text": "施行者が特別の事情がある場合に、仮換地の使用収益の開始日を指定しないことで使用収益を停止します（土地区画整理法99条3項）。自動的に停止されるのではなく施行者の意思によります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">土地区画整理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">換地の確定</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公告の翌日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮換地指定後</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従前地は使用不可（所有権は残る）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">組合設立</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各2/3以上の同意</text></svg>", "choices": [{"label": "仮換地が指定されると自動的に停止される", "reason": "施行者が特別の事情がある場合に停止します（土地区画整理法99条3項）。自動的ではありません。", "caution": "仮換地の使用収益停止：施行者の特別の指定による（土地区画整理法99条3項）。"}, {"label": "使用収益の停止は区分所有者の同意が必要", "reason": "区分所有者の同意は不要で施行者の意思によります（土地区画整理法99条3項）。", "caution": ""}, {"label": "使用収益停止は原則認められない", "reason": "特別の事情がある場合は認められます（土地区画整理法99条3項）。", "caution": ""}], "summary": {"head": ["仮換地の使用収益停止（土地区画整理法99条3項）", "内容"], "rows": [["停止方法", "施行者が使用収益の開始日を指定しない"], ["補償", "停止された権利者に損失補償あり"]]}}},
  {id:10772,unit:'t_inshi',level:1,field:'tax',text:'建物の賃貸借契約書の印紙税の課税について正しいものはどれか。',opts:['非課税（建物賃貸借は印紙税非課税）','第1号文書として課税対象','第2号文書として課税対象','印紙税額は賃料の0.1%'],ans:0,exp:'建物の賃貸借契約書は印紙税の課税文書に該当せず非課税です。土地の賃貸借契約書（地上権・賃借権の設定）は第1号の2文書として課税されます（印紙税法別表第一）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10773,unit:'r_ishi',level:2,field:'rights',text:'消費者契約法による契約の取消しについて正しいものはどれか。',opts:['消費者契約法の取消権は宅建業者間の取引にも適用される','事業者が消費者に重要事項について不実告知等をした場合、消費者は契約を取り消すことができる','消費者契約法の時効は1年のみ','全ての消費者契約に自動的に適用される'],ans:1,exp:'消費者契約法は事業者と消費者間の契約に適用されます。事業者が不実告知・断定的判断の提供・不利益事実の不告知等を行った場合、消費者は契約を取り消すことができます（消費者契約法4条）。取消権は追認できる時から1年・契約締結から5年で消滅します。',"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "意思表示の瑕疵には詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失の第三者は保護）・通謀虚偽表示（無効・善意の第三者は保護）があります。", "example": ""}, "reason": {"text": "消費者契約法は事業者と消費者間の情報・交渉力の格差を是正するための法律です。事業者の不実告知等の不当な勧誘行為から消費者を保護するため、取消権を付与しています（消費者契約法4条）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "消費者契約法の取消権は宅建業者間の取引にも適用される", "reason": "消費者契約法は「事業者」と「消費者」間の契約に適用されます。宅建業者間の取引は事業者同士なので消費者契約法は適用されません。", "caution": ""}, {"label": "消費者契約法の時効は1年のみ", "reason": "消費者契約法の取消権の時効は追認できる時から1年（または契約締結から5年）です（消費者契約法7条）。「1年のみ」は不正確です。", "caution": ""}, {"label": "全ての消費者契約に自動的に適用される", "reason": "消費者契約法は消費者契約に適用されますが、不実告知等の要件を満たした場合に取消権が発生します。全ての契約が自動的に取消し可能になるわけではありません。", "caution": ""}], "summary": {"head": ["消費者契約法の取消原因", "内容"], "rows": [["不実告知", "重要事項について事実と異なる告知"], ["断定的判断の提供", "不確実なことを断定"], ["不利益事実の不告知", "重要事項の不利益な事実を故意に告知しない"], ["不退去・監禁", "帰宅や退去を妨害"]]}}},
  {id:10774,unit:'l_kantoku',level:3,field:'law',text:'国土交通大臣が宅建業者に業務停止処分を行う場合の都道府県知事への通知について正しいものはどれか。',opts:['通知の義務はない','業務停止処分を行った場合は遅滞なくその旨を当該業者の事務所が所在する都道府県の知事に通知しなければならない','処分後1年以内に通知すれば足りる','知事の許可を得てから処分する'],ans:1,exp:'国土交通大臣が宅建業者に指示処分・業務停止処分を行ったときは当該業者の事務所が所在する都道府県の知事に通知しなければなりません（宅建業法64条・65条3項）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "国土交通大臣が宅建業者に業務停止処分を行った場合、当該業者の事務所が所在する都道府県の知事に遅滞なくその旨を通知しなければなりません（宅建業法70条2項）。相互連携により監督が徹底されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "通知の義務はない", "reason": "遅滞なく通知する義務があります（宅建業法70条2項）。「義務なし」は誤りです。", "caution": "大臣→知事への通知：義務（宅建業法70条2項）。"}, {"label": "処分後1年以内に通知すれば足りる", "reason": "「遅滞なく」の通知が必要です（宅建業法70条2項）。1年以内では遅すぎます。", "caution": ""}, {"label": "知事の許可を得てから処分する", "reason": "大臣が処分する際に知事の許可は不要です（宅建業法65条）。処分後に知事に通知します（同法70条2項）。", "caution": ""}], "summary": {"head": ["大臣と知事の相互通知（宅建業法70条）", "内容"], "rows": [["大臣が処分した場合", "当該業者の事務所所在の知事に遅滞なく通知（同条2項）"], ["知事が処分した場合", "大臣に報告等"], ["目的", "監督の重複・抜け漏れ防止"]]}}},
  {id:10775,unit:'k_nochi',level:3,field:'limit',text:'農地の賃貸借の解約について正しいものはどれか。',opts:['農地の賃貸借は貸主がいつでも解約できる','農地の賃貸借の解約・解除には農業委員会の許可が必要','農業委員会への届出のみで解約できる','農地の賃貸借に特別ルールはない'],ans:1,exp:'農地の賃貸借の合意解除・解除・解約申入れ等には農業委員会の許可が必要です（農地法18条1項）。ただし一定の事由（賃料不払い等）による解除で当事者が申請する場合は例外があります。',"kaisetsu":{"topic": "農地法：3条は農業委員会・4条・5条は都道府県知事・市街化区域は届出のみ", "basis": {"text": "農地法3条（権利移動・農地→農地）の許可権者は農業委員会。4条（自己転用）・5条（転用目的の権利移動）は都道府県知事等。市街化区域内の農地転用（4・5条）は農業委員会への届出のみでOK。相続は許可不要・届出3か月以内。", "example": ""}, "reason": {"text": "農地の賃貸借の解約・解除には農業委員会の許可が必要です（農地法18条1項）。農地の賃貸借は一般の民法上の賃貸借より強く保護されており、貸主が一方的に解約することは認められていません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">市街化区域</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">特例なし</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text></svg>", "choices": [{"label": "農地の賃貸借は貸主がいつでも解約できる", "reason": "農地の賃貸借の解約には農業委員会の許可が必要です（農地法18条1項）。貸主が一方的に解約はできません。", "caution": "農地の賃貸借の解約：農業委員会の許可が必要（農地法18条1項）。"}, {"label": "農業委員会への届出のみで解約できる", "reason": "届出ではなく許可が必要です（農地法18条1項）。", "caution": ""}, {"label": "農地の賃貸借に特別ルールはない", "reason": "農地の賃貸借は農地法18条で特別な規制があります。「特別ルールなし」は誤りです。", "caution": ""}], "summary": {"head": ["農地の賃貸借の解約（農地法18条）", "内容"], "rows": [["解約・解除", "農業委員会の許可が必要（農地法18条1項）"], ["目的", "農業経営の安定保護"]]}}},
  {id:10776,unit:'r_baibai',level:3,field:'rights',text:'他人物売買の効力として正しいものはどれか（民法改正後）。',opts:['他人物売買は当然無効','他人物売買は有効で売主は権利を取得して買主に移転する義務を負う','他人物売買は買主が善意の場合のみ有効','他人物売買は常に詐欺になる'],ans:1,exp:'他人物売買は有効です（民法561条）。売主は契約後に目的物の権利を取得して買主に移転する義務を負います。この義務を果たせない場合は債務不履行（履行不能）となり損害賠償・解除の対象となります。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "他人物売買は有効です（民法561条）。売主は権利を取得して買主に移転する義務を負います。売主が権利を取得して移転できない場合は債務不履行責任を負います。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "他人物売買は当然無効", "reason": "他人物売買は有効です（民法561条）。売主は権利を取得して移転する義務を負います。", "caution": "他人物売買＝有効（民法561条）。"}, {"label": "他人物売買は買主が善意の場合のみ有効", "reason": "他人物売買は買主の善意・悪意に関係なく有効です（民法561条）。", "caution": ""}, {"label": "他人物売買は常に詐欺になる", "reason": "他人物売買が詐欺になるかは具体的な事実関係によります。民法は他人物売買を有効としており（同法561条）、詐欺の成立は別途要件が必要です。", "caution": ""}], "summary": {"head": ["他人物売買（民法561条）", "内容"], "rows": [["効力", "有効（民法561条）"], ["売主の義務", "権利を取得して買主に移転する義務"], ["移転できない場合", "債務不履行→解除・損害賠償"]]}}},
  {id:10777,unit:'r_chinshaku',level:3,field:'rights',text:'賃貸人の地位の移転（所有者の変更）について正しいものはどれか（2020年改正後）。',opts:['所有者が変わっても賃貸借契約は当然に終了する','賃借権の対抗要件を備えた賃借人がいる場合、不動産の譲渡時に賃貸人の地位も当然に新所有者に移転する','賃借人の同意が必要','新所有者は賃貸借を拒否できる'],ans:1,exp:'2020年民法改正で明文化されました（民法605条の2）。賃借権の対抗要件を備えた賃借人がいる場合、不動産の譲渡により賃貸人の地位は当然に譲受人（新所有者）に移転します。賃借人の同意は不要です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "賃借権の対抗要件を備えた賃借人がいる場合、不動産が譲渡されると賃貸人の地位は当然に新所有者に移転します（民法605条の2第1項・2020年改正で明文化）。旧所有者（譲渡人）と新所有者（譲受人）の合意のみでは賃貸人の地位は移転しません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "所有者が変わっても賃貸借契約は当然に終了する", "reason": "対抗要件を備えた賃借人がいる場合、所有者が変わっても賃貸借契約は終了せず、賃貸人の地位が新所有者に移転します（民法605条の2）。", "caution": ""}, {"label": "賃借人の同意が必要", "reason": "賃貸人の地位の移転に賃借人の同意は不要です（民法605条の2）。賃借人は新所有者を賃貸人として受け入れます。", "caution": ""}, {"label": "新所有者は賃貸借を拒否できる", "reason": "対抗要件を備えた賃借人がいる場合、新所有者は賃貸借を拒否できません（民法605条の2第1項）。", "caution": ""}], "summary": {"head": ["賃貸人の地位の移転（民法605条の2）", "内容"], "rows": [["要件", "賃借人が対抗要件（引渡し等）を備えていること"], ["効果", "不動産譲渡と同時に賃貸人の地位が新所有者に移転"], ["敷金", "新所有者に引き継がれる（民法605条の2第4項）"], ["旧所有者", "賃貸人としての地位を離脱"]]}}},
  {id:10778,unit:'l_baikai',level:3,field:'law',text:'指定流通機構（レインズ）に登録した物件が成約した場合の業者の義務として正しいものはどれか。',opts:['成約後の情報更新は任意','成約した場合は速やかにレインズに成約報告（登録情報の削除または更新）をしなければならない','3か月後に成約報告すればよい','成約報告の義務はない'],ans:1,exp:'専任・専属専任媒介契約で指定流通機構に登録した物件が成約した場合、宅建業者は遅滞なく登録の削除を行う義務があります（宅建業法施行規則15条の10）。登録したまま放置すると「おとり広告」に該当するおそれがあります。',"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任媒介の有効期間の上限は3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。専任は7日以内、専属専任は5日以内にレインズ登録が必要。業務報告は専任2週間に1回、専属専任1週間に1回。", "example": ""}, "reason": {"text": "専任媒介・専属専任媒介の場合、成約した際は速やかにレインズに成約を報告（登録情報の更新または削除）しなければなりません（宅建業法施行規則15条の9）。登録したままにしておくと他の業者が問合せに対応できなくなるためです。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">一般</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専任</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専属専任</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己発見取引</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">レインズ登録</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務報告</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">なし</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間に1回</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1週間に1回</text></svg>", "choices": [{"label": "成約後の情報更新は任意", "reason": "成約後のレインズへの成約報告は義務です（宅建業法施行規則15条の9）。「任意」は誤りです。", "caution": "成約後のレインズ成約報告：義務（速やかに）。"}, {"label": "3か月後に成約報告すればよい", "reason": "速やかに成約報告をしなければなりません（宅建業法施行規則15条の9）。3か月後では遅すぎます。", "caution": ""}, {"label": "成約報告の義務はない", "reason": "成約報告は義務です（宅建業法施行規則15条の9）。「義務なし」は誤りです。", "caution": ""}], "summary": {"head": ["レインズの成約報告義務", "内容"], "rows": [["義務", "あり（宅建業法施行規則15条の9）"], ["時期", "成約後速やかに"], ["内容", "登録情報の削除または成約情報の更新"], ["違反", "指示処分等の対象"]]}}},
  {id:10779,unit:'t_shutoku',level:3,field:'tax',text:'不動産取得税の「免税点」について正しいものはどれか。',opts:['課税標準額10万円以上は全て課税','土地10万円・家屋23万円（新築等）・家屋12万円（売買等）未満は免税','不動産取得税に免税点はない','評価額100万円未満は免税'],ans:1,exp:'不動産取得税の免税点は、土地は課税標準額10万円未満、家屋は新築・増築・改築等による取得が23万円未満、売買・贈与・交換等による取得が12万円未満です（地方税法73条の15の2）。免税点未満の取得には不動産取得税は課税されません。',"kaisetsu":{"topic": "不動産取得税：都道府県が課す地方税・相続は非課税・1回だけ課税", "basis": {"text": "不動産取得税は都道府県が課す地方税です（地方税法73条の2）。相続・法人の合併等による取得は非課税。一度の取得に一度だけ課税される（固定資産税と異なり毎年ではない）。標準税率は4%（住宅・土地は3%の軽減あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産取得税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税の頻度</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取得時に1回のみ</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">標準税率</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4%（住宅・土地は3%）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10780,unit:'k_kukaku',level:1,field:'limit',text:'土地区画整理組合の設立について正しいものはどれか。',opts:['1人でも設立できる','施行地区内の宅地の所有者・借地権者が7名以上の同意で組合設立の認可申請ができる','都道府県の申請のみで設立できる','法人のみ設立できる'],ans:1,exp:'土地区画整理組合は施行地区内の宅地の所有者または借地権者が7名以上で組合設立の認可申請ができます（土地区画整理法14条1項）。認可後は施行地区内の全地権者が組合員となります（強制加入）。',"kaisetsu":{"topic": "土地区画整理法：換地は公告翌日確定・仮換地は従前地使用不可・組合は2/3以上", "basis": {"text": "換地処分の公告翌日から換地が確定します（土地区画整理法104条）。仮換地の指定後は従前地を使用できなくなります（同法99条）。組合設立には土地所有者・借地権者の各2/3以上の同意が必要です。", "example": ""}, "reason": {"text": "土地区画整理組合の設立には施行地区内の宅地の所有者・借地権者が7名以上の設立者の同意と全体の3分の2以上の同意で認可申請できます（土地区画整理法14条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">土地区画整理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">換地の確定</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公告の翌日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮換地指定後</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従前地は使用不可（所有権は残る）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">組合設立</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各2/3以上の同意</text></svg>", "choices": [{"label": "1人でも設立できる", "reason": "7人以上が必要です（土地区画整理法14条1項）。", "caution": "組合設立：7人以上＋3分の2以上の同意（土地区画整理法14条1項）。"}, {"label": "都道府県の申請のみで設立できる", "reason": "権利者の同意が必要です（土地区画整理法14条1項）。", "caution": ""}, {"label": "法人のみ設立できる", "reason": "個人（宅地所有者等）も組合員になれます（土地区画整理法14条1項）。", "caution": ""}], "summary": {"head": ["土地区画整理組合の設立（土地区画整理法14条1項）", "内容"], "rows": [["設立者", "施行地区内の宅地所有者・借地権者"], ["同意", "各3分の2以上"], ["人数", "7人以上"]]}}},
  {id:10781,unit:'r_sorin',level:3,field:'rights',text:'境界確認の法的手続きについて正しいものはどれか。',opts:['境界確認は任意の手続きのみ','境界確定訴訟（境界確認の訴え）は形成訴訟の一種で境界を裁判所が確定できる','境界は法務局が職権で定める','境界確認は公証人が行う'],ans:1,exp:'隣地との境界が争われる場合は境界確定訴訟を提起できます。これは形成訴訟で裁判所が境界を確定します。また筆界特定制度（法務局）という行政上の制度もあります（不動産登記法131条以下）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "境界確定訴訟は隣接地の境界線の位置を裁判所が確定する特殊な訴訟です（判例・形成訴訟または確認訴訟）。当事者双方が原告・被告の立場を超えて境界の確定を求める点が通常の訴訟と異なります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "境界確認は任意の手続きのみ", "reason": "境界確定訴訟（境界確認の訴え）は法的手続きとして認められています（判例）。任意の手続きだけではありません。", "caution": ""}, {"label": "境界は法務局が職権で定める", "reason": "境界は当事者間の合意や裁判所の判決等で確定します。法務局が職権で定めるわけではありません。", "caution": ""}, {"label": "境界確認は公証人が行う", "reason": "境界確認は公証人ではなく裁判所（境界確定訴訟）または当事者間の合意（ADR等）で行います。", "caution": ""}], "summary": {"head": ["境界の確定方法", "内容"], "rows": [["当事者間の合意", "任意の境界確認（覚書・境界確認書等）"], ["筆界特定制度", "法務局での行政手続き"], ["境界確定訴訟", "裁判所による判決での確定"], ["地籍調査", "国・地方自治体による調査"]]}}},
  {id:10782,unit:'l_takkenshi',level:3,field:'law',text:'宅建業者が一時的に宅建士の数が設置基準を下回った場合の対応として正しいものはどれか。',opts:['即時に業務を停止しなければならない','2週間以内に基準を満たすために必要な措置を取らなければならない','1か月以内であれば問題ない','届出のみでよい'],ans:1,exp:'事務所の専任の宅建士の数が設置基準（5名に1名以上）を下回った場合は2週間以内に基準を満たすために必要な措置を取らなければなりません（宅建業法31条の3第3項）。',"kaisetsu":{"topic": "専任の宅建士：5人に1人以上・兼任不可・不足時は2週間以内に補充", "basis": {"text": "事務所には業務従事者5人に1人以上の専任宅建士が必要です（宅建業法31条の3）。専任宅建士は1社専属で複数業者の兼任は不可。不足時は2週間以内に補充が必要です。", "example": ""}, "reason": {"text": "宅建業者が一時的に専任宅建士の数が設置基準を下回った場合、2週間以内に補充その他の必要な措置を取らなければなりません（宅建業法31条の3第3項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">専任宅建士のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">設置基準</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5人に1人以上（主従同じ）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">兼任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可（1社専属）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不足補充</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間以内</text></svg>", "choices": [{"label": "即時に業務を停止しなければならない", "reason": "即時の業務停止義務はなく、2週間以内に補充等の措置を取ることが求められます（宅建業法31条の3第3項）。", "caution": "専任宅建士不足：2週間以内に補充措置（宅建業法31条の3第3項）。"}, {"label": "1か月以内であれば問題ない", "reason": "補充期限は2週間以内です（宅建業法31条の3第3項）。1か月ではありません。", "caution": ""}, {"label": "届出のみでよい", "reason": "届出だけでなく実際に補充等の措置を取る必要があります（宅建業法31条の3第3項）。", "caution": ""}], "summary": {"head": ["専任宅建士の欠員（宅建業法31条の3第3項）", "内容"], "rows": [["措置期限", "2週間以内"], ["必要な措置", "専任宅建士の補充等"], ["補充できない場合", "業務停止処分等の対象となりえる"]]}}},
  {id:10783,unit:'r_kukku',level:3,field:'rights',text:'区分所有法における「議決権行使書」について正しいものはどれか。',opts:['議決権行使書の提出は認められない','区分所有者は集会に出席しなくても書面または電磁的方法で議決権を行使できる（規約または集会の決議があれば）','書面投票は5票まで','議決権行使書は宅建士が作成しなければならない'],ans:1,exp:'区分所有者は規約または集会の決議があれば書面または電磁的方法で議決権を行使することができます（区分所有法39条2項・3項）。これにより区分所有者が出席できない場合でも意思表示が可能です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "区分所有者は規約または集会決議があれば、集会に出席せず書面または電磁的方法によって議決権を行使できます（区分所有法39条3項）。これにより遠方に住む区分所有者等も議決権を行使できます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "議決権行使書の提出は認められない", "reason": "規約または集会決議があれば書面・電磁的方法による議決権行使が認められています（区分所有法39条3項）。", "caution": "書面・電磁的方法の議決権行使＝認められる（区分所有法39条3項）。"}, {"label": "書面投票は5票まで", "reason": "書面投票に票数の制限はありません（区分所有法39条3項）。各区分所有者が議決権の範囲内で行使できます。", "caution": ""}, {"label": "議決権行使書は宅建士が作成しなければならない", "reason": "議決権行使書を宅建士が作成しなければならないという規定はありません（区分所有法39条3項）。", "caution": ""}], "summary": {"head": ["議決権の行使方法（区分所有法39条）", "内容"], "rows": [["出席", "集会に直接出席して議決"], ["代理", "代理人に委任（同条2項）"], ["書面・電磁的方法", "規約または集会決議があれば可（同条3項）"], ["書面決議", "全員同意で集会に代えることができる（区分所有法45条）"]]}}},
  {id:10784,unit:'t_chika',level:3,field:'tax',text:'路線価（相続税路線価）と公示価格の関係として正しいものはどれか。',opts:['路線価と公示価格は同じ','路線価は公示価格の概ね80%水準に設定されている','路線価は公示価格の50%水準','路線価は公示価格より高い'],ans:1,exp:'相続税の路線価は地価公示価格の概ね80%（8割）を目安として国税庁が設定しています。固定資産税評価額は公示価格の70%水準です。これらの比較は「一物四価」（公示価格・基準地価・路線価・固定資産税評価額）として整理できます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10785,unit:'l_jusetsu',level:3,field:'law',text:'宅建業法における「心理的瑕疵の告知」について正しいものはどれか。',opts:['心理的瑕疵の告知は義務ではない','建物内での人の死等の心理的瑕疵については国土交通省ガイドラインに基づき原則として告知義務があり重要事項説明でも説明が求められる','告知するかは業者の裁量による','告知しなくても契約は有効'],ans:1,exp:'2021年10月に国土交通省が「宅地建物取引業者による人の死の告知に関するガイドライン」を策定しました。建物内での自殺・他殺等の事案は原則告知が必要で重要事項説明での説明も求められます。',"kaisetsu":{"topic": "重要事項説明：宅建士が説明・売主への交付は不要・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主への交付義務はありません。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能です。", "example": ""}, "reason": {"text": "建物内での人の死等の心理的瑕疵（告知事項）については、国土交通省ガイドライン（2021年）に基づき原則として告知義務があります。重要事項説明においても心理的瑕疵に関する説明が求められます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "心理的瑕疵の告知は義務ではない", "reason": "国土交通省ガイドラインに基づき心理的瑕疵（建物内での死等）は原則として告知義務があります。「義務ではない」は誤りです。", "caution": "心理的瑕疵：告知義務あり（国土交通省ガイドライン・2021年）。"}, {"label": "告知するかは業者の裁量による", "reason": "ガイドラインに基づく告知義務があり、業者の裁量には委ねられていません。", "caution": ""}, {"label": "告知しなくても契約は有効", "reason": "告知しないことで債務不履行・詐欺・不法行為等の法的責任が生じる場合があります。「有効」だから告知不要とはなりません。", "caution": ""}], "summary": {"head": ["心理的瑕疵の告知（国土交通省ガイドライン）", "内容"], "rows": [["告知義務", "原則あり"], ["対象", "建物内での死（自殺・他殺・事故死等）"], ["例外", "自然死・日常生活上の事故死は原則不要（一定期間経過後も同様）"], ["告知期間", "概ね3年（賃貸）・制限なし（売買）"]]}}},
  {id:10786,unit:'r_baibai',level:2,field:'rights',text:'瑕疵担保責任から「契約不適合責任」への改正（2020年）の主な変更点として正しいものはどれか。',opts:['旧制度と全く同じ','買主の権利が追完請求・代金減額請求・損害賠償・解除に整理され、買主は不適合を知った時から1年以内の「通知」で足りる','売主の責任が重くなった','権利行使期間が延長された'],ans:1,exp:'2020年改正民法により瑕疵担保責任が「契約不適合責任」に改められました。買主の権利は追完請求・代金減額請求・損害賠償・解除に整理され、権利行使は不適合を知った時から1年以内に「通知」するだけで足ります（民法566条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "2020年民法改正で「瑕疵担保責任」が「契約不適合責任」に改められました（民法562条以下）。主な変更点は①買主の権利が整理（追完・減額・損害賠償・解除）、②通知期限が「知った時から1年以内の通知」、③損害賠償が債務不履行一般の規律に統合等です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "旧制度と全く同じ", "reason": "2020年改正で名称変更だけでなく権利の種類・要件等が大きく変わりました。「全く同じ」は誤りです。", "caution": "瑕疵担保→契約不適合：名称変更だけでなく内容も大きく変わりました。"}, {"label": "売主の責任が重くなった", "reason": "買主の権利が追完請求等を含む形で整理されましたが、「重くなった」とも「軽くなった」とも一概には言えません。免除特約等の制度は維持されています。", "caution": ""}, {"label": "権利行使期間が延長された", "reason": "改正前は「引渡しから1年以内に請求」でしたが、改正後は「知った時から1年以内の通知」です。延長とも短縮とも言えます（起算点が変わりました）。", "caution": ""}], "summary": {"head": ["瑕疵担保→契約不適合責任の主な変更", "内容"], "rows": [["名称変更", "瑕疵担保責任→契約不適合責任"], ["買主の権利", "追完請求・代金減額・損害賠償・解除に整理"], ["通知期限", "知った時から1年以内の通知（種類・品質の不適合）"], ["損害賠償の要件", "債務不履行一般の規律（帰責事由必要）"]]}}},
  {id:10787,unit:'r_touki',level:1,field:'rights',text:'法人の不動産登記申請における「代表者事項証明書」について正しいものはどれか。',opts:['不要','法人が当事者となる登記申請には代表者の資格を証する情報（代表者事項証明書等）が必要','戸籍謄本が必要','法人は個人と同様の書類でよい'],ans:1,exp:'法人が登記の申請人となる場合、代表者の資格を証する情報（代表者事項証明書・登記事項証明書等）の提出が必要です（不動産登記令7条1項1号）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "法人が登記申請する場合、代表者が登記申請を行う権限を持つことを証明する必要があります（不動産登記法18条等）。代表者事項証明書（登記事項証明書）等により代表者の資格を証明します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "不要", "reason": "法人の登記申請には代表者の資格を証する情報（代表者事項証明書等）が必要です（不動産登記規則37条）。", "caution": ""}, {"label": "戸籍謄本が必要", "reason": "戸籍謄本は個人の相続等で必要となる書類です。法人の代表者資格の証明には代表者事項証明書を使用します。", "caution": ""}, {"label": "法人は個人と同様の書類でよい", "reason": "法人の登記申請には法人特有の書類（代表者事項証明書等）が必要です。個人と同様の書類だけでは足りません。", "caution": ""}], "summary": {"head": ["申請者の種類", "必要な本人確認書類"], "rows": [["個人", "登記識別情報・印鑑証明書"], ["法人", "代表者事項証明書（商業登記の登記事項証明書等）"], ["相続人", "戸籍謄本・除籍謄本等"]]}}},
  {id:10788,unit:'k_toshi',level:3,field:'limit',text:'市街化区域と市街化調整区域の区分（線引き）の義務について正しいものはどれか。',opts:['全ての都市計画区域に線引きが義務付けられている','大都市圏の特定の都市計画区域では線引きが義務で、それ以外は任意','市町村の任意','国土交通大臣が決定する'],ans:1,exp:'市街化区域と市街化調整区域の区分（線引き）は、首都圏・近畿圏・中部圏の一定の地域の都市計画区域では義務的に行わなければなりませんが、それ以外の区域では任意です（都市計画法7条・13条）。',"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域での1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は市街化調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "市街化区域と市街化調整区域の区分（線引き）は、大都市圏の特定の都市計画区域では義務的に定めなければなりませんが（都市計画法7条1項）、それ以外の都市計画区域では任意です。線引きのない都市計画区域を「非線引き都市計画区域」と呼びます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化する区域</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可基準</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "全ての都市計画区域に線引きが義務付けられている", "reason": "義務的線引きは大都市圏の特定区域のみです（都市計画法7条1項）。「全ての区域」は誤りです。", "caution": "線引き：大都市圏の特定区域では義務。その他は任意（都市計画法7条1項）。"}, {"label": "市町村の任意", "reason": "線引きは都道府県が決定します（都市計画法15条1項）。市町村の任意ではありません。", "caution": ""}, {"label": "国土交通大臣が決定する", "reason": "線引きは都道府県が決定します（都市計画法15条1項）。大臣が直接決定するものではありません。", "caution": ""}], "summary": {"head": ["線引きの義務・任意（都市計画法7条）", "内容"], "rows": [["義務的線引き", "大都市圏の特定都市計画区域"], ["任意線引き", "その他の都市計画区域（選択的に定める）"], ["非線引き区域", "線引きなしの都市計画区域"]]}}},
  {id:10789,unit:'l_hoshu',level:3,field:'law',text:'宅建業者が受け取る「報酬」と「実費」の区別について正しいものはどれか。',opts:['報酬に実費は含まれる','広告の実費等は原則として報酬の上限内に含まれるが依頼者の特別の依頼によるものは別途受け取ることができる場合もある','実費は上限なく請求できる','実費を受け取ることは禁止'],ans:1,exp:'宅建業者の報酬に関して広告費用等は原則として報酬上限内に含まれます。ただし依頼者の特別の依頼に基づく遠隔地への出張費・通常を超える広告費等は別途受け取ることができる場合があります（宅建業法46条）。',"kaisetsu":{"topic": "報酬：売買は代金×3%+6万（400万超）・賃貸は借賃1か月・上限超過は不可", "basis": {"text": "売買媒介報酬（400万超）の一方からの上限は代金×3%+6万円（税別）。双方合計は一方上限×2。賃貸媒介（居住用・非居住用とも）は借賃1か月分。依頼者の承諾があっても上限超過は不可。", "example": ""}, "reason": {"text": "宅建業者が受け取る報酬（媒介手数料）には広告費等の実費が含まれることが原則です（告示の趣旨）。ただし依頼者が特別に依頼した広告（新聞折込等）の実費は別途受け取れる場合があります（告示）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対象</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（400万超）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万（一方）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（200万以下）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸（双方合計）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借賃1か月分</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">低廉な空家等（800万円以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円まで（説明・合意要）</text></svg>", "choices": [{"label": "報酬に実費は含まれる", "reason": "原則として広告費等の実費は報酬上限内に含まれます（告示）。依頼者の特別の依頼による実費は例外として別途受け取れる場合があります。", "caution": "通常の広告費：報酬上限内。依頼者の特別依頼による実費：別途受け取れる場合あり（告示）。"}, {"label": "実費は上限なく請求できる", "reason": "実費も依頼者の特別依頼に基づかないものは報酬上限内に含まれます（告示）。「上限なし」は誤りです。", "caution": ""}, {"label": "実費を受け取ることは禁止", "reason": "依頼者の特別依頼による実費は別途受け取れます（告示）。禁止されているわけではありません。", "caution": ""}], "summary": {"head": ["報酬と実費の関係（告示）", "内容"], "rows": [["通常の広告費", "報酬上限内に含まれる"], ["依頼者の特別依頼による広告費", "依頼者の承諾があれば別途受け取り可"], ["低廉な空家等の報酬特例", "上限30万円まで受領できる場合あり（告示）"]]}}},
  {id:10790,unit:'r_saikensoron',level:2,field:'rights',text:'保証人の求償権について正しいものはどれか。',opts:['保証人は弁済しても主債務者に求償できない','保証人は主債務者のために弁済した場合、主債務者に求償できる（民法459条）','求償できる範囲は弁済額の半分のみ','事前通知なく弁済した場合も常に全額求償できる'],ans:1,exp:'保証人が主債務者のために弁済した場合、主債務者に求償できます（民法459条）。ただし事前通知せずに弁済した場合は主債務者が弁済等の抗弁を失うおそれがあり求償が制限される場合があります（民法463条）。',"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要です（民法446条2項）。連帯保証人には催告・検索の抗弁権がありません（民法454条）。債権譲渡の第三者対抗要件は確定日付ある証書による通知または承諾です（民法467条2項）。", "example": ""}, "reason": {"text": "保証人が主債務者のために弁済すると、主債務者に対して求償権が発生します（民法459条・462条）。ただし事前通知なく弁済した場合、主債務者が対抗事由（相殺等）を有していた場合は求償が制限されます（民法463条）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相殺の要件</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">双方が同種の債権</text></svg>", "choices": [{"label": "保証人は弁済しても主債務者に求償できない", "reason": "保証人は主債務者のために弁済した後、主債務者への求償権が発生します（民法459条・462条）。「できない」は誤りです。", "caution": "保証人の弁済→主債務者への求償権発生（民法459条等）。"}, {"label": "求償できる範囲は弁済額の半分のみ", "reason": "求償できる範囲は弁済した全額（利息・損害賠償を含む）です（民法459条1項）。「半分のみ」は誤りです。", "caution": ""}, {"label": "事前通知なく弁済した場合も常に全額求償できる", "reason": "事前通知なく弁済した場合、主債務者が相殺等の対抗事由を持っていた場合は求償が制限されます（民法463条）。「常に全額」は誤りです。", "caution": ""}], "summary": {"head": ["保証人の求償権", "内容"], "rows": [["根拠", "民法459条（委託を受けた保証人）・462条（委託なし）"], ["求償額", "弁済額＋弁済後の利息・損害賠償"], ["事前通知義務", "弁済前に主債務者に通知（民法463条1項）"], ["事後通知義務", "弁済後に主債務者に通知（民法463条2項）"]]}}},
  {id:10791,unit:'r_chinshaku',level:2,field:'rights',text:'賃借権の譲渡と転貸の比較として正しいものはどれか。',opts:['両者は全く同じ','賃借権の譲渡は賃借人が賃借権を第三者に移転して自己は契約関係から離脱、転貸は賃借人が賃借権を保持したまま第三者に転貸する','どちらも賃貸人の承諾不要','転貸のみ賃貸人の承諾が必要'],ans:1,exp:'賃借権の譲渡は賃借人（譲渡人）が賃借権を第三者（譲受人）に譲渡し自己は契約から離脱します。転貸は賃借人が賃借権を保持したまま第三者に又貸しします。いずれも賃貸人の承諾が必要です（民法612条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "賃借権の譲渡は賃借人が賃借権を第三者に移転し自己は契約関係から完全に離脱します。転貸は賃借人が賃借権を保持したまま第三者（転借人）に使用させます。いずれも賃貸人の承諾が原則必要です（民法612条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "両者は全く同じ", "reason": "賃借権の譲渡と転貸では、賃借人が契約関係から離脱するかどうかが異なります。全く同じではありません。", "caution": ""}, {"label": "どちらも賃貸人の承諾不要", "reason": "賃借権の譲渡・転貸はいずれも賃貸人の承諾が原則必要です（民法612条1項）。", "caution": "どちらも承諾が原則必要です。"}, {"label": "転貸のみ賃貸人の承諾が必要", "reason": "賃借権の譲渡も賃貸人の承諾が必要です（民法612条1項）。転貸のみではありません。", "caution": ""}], "summary": {"head": ["比較", "賃借権の譲渡", "転貸（サブリース）"], "rows": [["賃借人の地位", "契約関係から離脱", "賃借権保持・契約関係継続"], ["第三者の立場", "新賃借人として直接賃貸人と契約", "転借人として賃借人と転貸借契約"], ["賃貸人の承諾", "必要（民法612条）", "必要（民法612条）"], ["転借人と賃貸人", "直接関係なし（譲渡の場合）", "直接義務関係あり（民法613条）"]]}}},
  {id:10792,unit:'t_kotei',level:3,field:'tax',text:'固定資産税の農地（田・畑）に対する課税の特例として正しいものはどれか。',opts:['農地は全て固定資産税が非課税','一般農地は農地の収益性を考慮した「農地評価」で課税標準が低く設定される','農地は宅地と同じ評価額で課税される','市街化区域農地は一般農地と同じ扱い'],ans:1,exp:'一般農地の固定資産税は農地の収益性を基準とした農地評価で課税標準が低く設定されています。一方、市街化区域農地は宅地化を促進するため宅地並み評価・宅地並み課税が適用される場合があります（地方税法349条の3第1項）。',"kaisetsu":{"topic": "固定資産税：市町村が課す地方税・賦課期日は1月1日・評価替えは3年ごと", "basis": {"text": "固定資産税は市町村（東京23区は都）が課す地方税です（地方税法343条）。賦課期日は毎年1月1日。評価替えは3年ごと（基準年度）。住宅用地の特例：200㎡以下は課税標準1/6、超過部分は1/3。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">固定資産税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市町村（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賦課期日</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">評価替え</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年ごと</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅用地（200㎡以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税標準1/6</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10793,unit:'r_touki',level:2,field:'rights',text:'土地の所有権と建物の所有権が別人に属する場合の法定地上権（民法388条）の成立要件として正しいものはどれか。',opts:['要件なしに自動的に成立する','抵当権設定時に土地・建物が同一人の所有で、競売により土地・建物の所有者が別々になった場合に成立','競売のみで成立し任意売却では成立しない','建物があれば常に法定地上権が成立'],ans:1,exp:'法定地上権（民法388条）は抵当権設定時に土地と建物が同一人の所有で、その後競売により土地・建物が別々の所有者になった場合に成立します。建物のための地上権が法律上当然に成立します。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "法定地上権（民法388条）は抵当権設定時に土地・建物が同一人の所有であり、競売によって所有者が別々になった場合に成立します。建物所有者が土地を利用する権利を保護し、建物の取り壊しを防ぐための制度です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "要件なしに自動的に成立する", "reason": "法定地上権の成立には要件があります（民法388条）。①抵当権設定時に土地・建物が同一所有、②競売による所有者の分離、が必要です。", "caution": ""}, {"label": "競売のみで成立し任意売却では成立しない", "reason": "法定地上権は競売の場合に成立します（民法388条）。任意売却（合意による売却）では法律上の法定地上権は成立しませんが、当事者間で地上権設定の合意をすることは可能です。", "caution": "法定地上権＝競売の場合のみ。任意売却では当事者の合意が必要。"}, {"label": "建物があれば常に法定地上権が成立する", "reason": "建物があるだけでは法定地上権は成立しません。抵当権設定時の土地・建物の同一所有、および競売による分離という要件が必要です。", "caution": ""}], "summary": {"head": ["法定地上権の成立要件", "内容"], "rows": [["①", "抵当権設定時に土地と建物が存在"], ["②", "抵当権設定時に土地と建物が同一人の所有"], ["③", "競売により土地・建物の所有者が別々に"], ["効果", "建物所有者のために法定地上権が成立"]]}}},
  {id:10794,unit:'r_souzoku',level:2,field:'rights',text:'特別受益（婚姻・養子縁組・生計の資本のための贈与）について正しいものはどれか。',opts:['特別受益は相続財産に含まれない','相続分の計算において特別受益は相続財産に持ち戻して計算されるが被相続人の意思によって持ち戻しを免除できる','特別受益は全て相続財産として均等分配される','生前贈与は常に特別受益になる'],ans:1,exp:'特別受益は相続財産に持ち戻して相続分を計算します（民法903条）。ただし被相続人が遺言等で持ち戻しの免除の意思表示をした場合は持ち戻し計算から除外されます（民法903条3項）。',"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2", "basis": {"text": "配偶者と子の場合は各1/2（民法900条）。相続放棄は3か月以内に家庭裁判所へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2です（民法1042条）。遺産分割協議は全員合意が必要です。", "example": ""}, "reason": {"text": "特別受益（婚姻・養子縁組・生計の資本のための生前贈与等）は相続財産に持ち戻して計算されます（民法903条1項）。ただし被相続人の意思表示により持ち戻しを免除できます（同条3項）。生前贈与がすべて特別受益になるわけではなく、趣旨・金額・相続財産との比較等で判断します。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続の主要ポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子の相続分</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は法定相続分の1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割協議</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "特別受益は相続財産に含まれない", "reason": "特別受益は相続財産に持ち戻して計算されます（民法903条1項）。相続財産に含まれないわけではありません。", "caution": "特別受益＝持ち戻して計算（みなし相続財産に加算）。"}, {"label": "特別受益は全て相続財産として均等分配される", "reason": "特別受益は持ち戻して各相続人の具体的相続分を計算しますが、均等分配されるわけではありません。法定相続分に従って計算されます。", "caution": ""}, {"label": "生前贈与は常に特別受益になる", "reason": "生前贈与がすべて特別受益になるわけではありません。婚姻・養子縁組・生計の資本としての贈与が特別受益の対象です（民法903条1項）。趣旨・金額等で個別判断します。", "caution": ""}], "summary": {"head": ["特別受益", "内容"], "rows": [["対象", "婚姻・養子縁組・生計の資本としての贈与・遺贈（民法903条1項）"], ["計算方法", "相続財産＋特別受益＝みなし相続財産→各自の相続分計算"], ["免除", "被相続人の意思表示で免除可（民法903条3項）"], ["限界", "遺留分を侵害できない（民法1044条）"]]}}},
  {id:10795,unit:'l_menkyo',level:1,field:'law',text:'宅建業の免許の有効期間として正しいものはどれか。',opts:['3年','5年','10年','更新不要'],ans:1,exp:'宅建業の免許の有効期間は5年です（宅建業法3条2項）。有効期間満了の90日前から30日前までの間に更新申請をする必要があります。',"kaisetsu":{"topic": "宅建業の免許：知事・大臣免許の区別・有効期間5年・欠格事由", "basis": {"text": "1都道府県のみ→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間です。", "example": ""}, "reason": {"text": "宅地建物取引業の免許の有効期間は5年です（宅建業法3条2項）。5年ごとに更新が必要で、更新申請は有効期間満了の90日前から30日前までに行います（同条3項）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（拘禁刑以上・特定罰金等）</text></svg>", "choices": [{"label": "3年", "reason": "免許の有効期間は5年です（宅建業法3条2項）。3年ではありません。", "caution": "宅建業の免許有効期間＝5年（宅建業法3条2項）。"}, {"label": "10年", "reason": "免許の有効期間は5年です（宅建業法3条2項）。10年ではありません。", "caution": ""}, {"label": "更新不要", "reason": "免許は5年ごとの更新が必要です（宅建業法3条2項・3項）。更新不要ではありません。", "caution": ""}], "summary": {"head": ["宅建業の免許", "数字"], "rows": [["有効期間", "5年"], ["更新申請時期", "満了の90日前〜30日前"], ["専任宅建士の割合", "業務従事者5名に1名以上"], ["営業保証金（主たる事務所）", "1000万円"]]}}},
  {id:10796,unit:'k_sonota',level:2,field:'limit',text:'自然公園法（国立公園・国定公園）の特別地域における建築規制として正しいものはどれか。',opts:['国立公園内での建築は一切禁止','特別地域内では環境大臣等の許可なく建築物の新築・増改築等はできない','国立公園内は全て自由に建築できる','普通地域には規制がない'],ans:1,exp:'自然公園法により国立・国定公園の特別地域内では環境大臣（国定公園は都道府県知事）の許可なく建築物の新築・増改築・外観変更等が原則として禁止されています（自然公園法17条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "自然公園法の特別地域内では環境大臣等の許可なく建築物の新築・増改築等の工作物の設置はできません（自然公園法20条3項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "国立公園内での建築は一切禁止", "reason": "普通地域は届出制であり、一切禁止ではありません（自然公園法24条）。特別地域は許可制です（同法20条3項）。", "caution": "特別地域：環境大臣等の許可が必要（自然公園法20条3項）。"}, {"label": "国立公園内は全て自由に建築できる", "reason": "特別地域・特別保護地区等では許可が必要です（自然公園法20条3項）。", "caution": ""}, {"label": "普通地域には規制がない", "reason": "普通地域でも一定の工作物の設置等には届出が必要です（自然公園法24条）。", "caution": ""}], "summary": {"head": ["自然公園法の地域区分と規制", "規制の強度"], "rows": [["特別保護地区", "最も厳格（環境大臣の許可）"], ["特別地域", "許可制（自然公園法20条3項）"], ["普通地域", "届出制（自然公園法24条）"]]}}},
  {id:10797,unit:'k_sonota',level:2,field:'limit',text:'都市緑地法における「緑地保全地域」の規制として正しいものはどれか。',opts:['緑地保全地域では全ての行為が自由','建築物の新築・改築・宅地造成等の行為は市町村長への届出が必要','緑地保全地域は農地にのみ指定できる','規制はない'],ans:1,exp:'緑地保全地域（都市緑地法4条）内では建築物の新築・改築・宅地造成・木竹の伐採等の行為をしようとする場合は市町村長への届出が必要です（都市緑地法7条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "都市緑地法における緑地保全地域内では建築物の新築・改築・増築・宅地造成等の行為は市町村長への届出が必要です（都市緑地法5条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "緑地保全地域では全ての行為が自由", "reason": "一定の行為には届出が必要です（都市緑地法5条）。「全て自由」は誤りです。", "caution": "緑地保全地域：建築等には市町村長への届出が必要（都市緑地法5条）。"}, {"label": "緑地保全地域は農地にのみ指定できる", "reason": "農地に限らず樹林地・草地等の緑地に指定できます（都市緑地法5条）。", "caution": ""}, {"label": "規制はない", "reason": "一定の行為には届出が必要です（都市緑地法5条）。", "caution": ""}], "summary": {"head": ["緑地保全地域（都市緑地法5条）", "内容"], "rows": [["届出が必要な行為", "建築物の新築・改築・増築・宅地造成等"], ["届出先", "市町村長"]]}}},
  {id:10798,unit:'r_fuhoko',level:2,field:'rights',text:'土地の工作物等の設置・保存の瑕疵による損害賠償（民法717条）における責任者について正しいものはどれか。',opts:['建設業者が常に責任を負う','占有者が第一次的に責任を負い、占有者が無過失を証明した場合は所有者が無過失責任を負う','所有者のみが責任を負う','居住者が常に責任を負う'],ans:1,exp:'工作物責任（民法717条）では占有者が第一次的に責任を負い（過失責任）、無過失を証明した場合は所有者が絶対的無過失責任を負います（最終責任者）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "工作物の設置・保存の瑕疵による損害賠償（民法717条）は占有者が第一次的に責任を負いますが、占有者が損害防止に必要な注意をしたことを証明した場合は免責され、その場合は所有者が無過失責任を負います（民法717条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "建設業者が常に責任を負う", "reason": "建設業者（施工業者）は工作物責任（民法717条）の第一次的責任者ではありません。占有者・所有者が責任を負います。", "caution": ""}, {"label": "所有者のみが責任を負う", "reason": "第一次的には占有者が責任を負います（民法717条1項）。所有者のみではありません。", "caution": ""}, {"label": "居住者が常に責任を負う", "reason": "居住者が占有者である場合は責任を負いますが「常に責任を負う」とは言えません（民法717条1項ただし書：注意を尽くせば免責）。", "caution": ""}], "summary": {"head": ["工作物責任（民法717条）の責任者", "内容"], "rows": [["占有者（第一次）", "過失責任（注意尽くせば免責）"], ["所有者（第二次）", "無過失責任（免責なし）"], ["施工業者", "求償の対象（民法717条3項）"], ["被害者の対応", "占有者免責→所有者に請求"]]}}},
  {id:10799,unit:'l_hoshu',level:2,field:'law',text:'宅建業者が土地と建物を一括して売買の媒介をした場合の報酬計算について正しいものはどれか。',opts:['土地と建物それぞれに報酬上限を計算して合算する','土地と建物の代金合計額（消費税相当額を除く）を基礎として報酬上限を計算する','建物の代金のみを基礎として計算する','土地のみを基礎として計算する'],ans:1,exp:'土地と建物を一括して売買する場合の媒介報酬は土地と建物の代金合計額（消費税分を除く）を基礎として報酬上限を計算します（報酬告示）。',"kaisetsu":{"topic": "報酬：売買は代金×3%+6万（400万超）・賃貸は借賃1か月・上限超過は不可", "basis": {"text": "売買媒介報酬（400万超）の一方からの上限は代金×3%+6万円（税別）。双方合計は一方上限×2。賃貸媒介（居住用・非居住用とも）は借賃1か月分。依頼者の承諾があっても上限超過は不可。", "example": ""}, "reason": {"text": "土地と建物を一括して売買する場合の報酬は、土地と建物の代金合計額（建物に消費税がかかる場合は税抜価格）を基礎として計算します（告示）。土地・建物を別々に計算して合算するのではありません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対象</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（400万超）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万（一方）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（200万以下）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸（双方合計）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借賃1か月分</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">低廉な空家等（800万円以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円まで（説明・合意要）</text></svg>", "choices": [{"label": "土地と建物それぞれに報酬上限を計算して合算する", "reason": "一括売買では代金合計額を基礎として計算します（告示）。別々に計算して合算するのは誤りです。", "caution": "一括売買：代金合計額（税抜）で計算。別々に計算して合算は誤り。"}, {"label": "建物の代金のみを基礎として計算する", "reason": "土地と建物の合計額（建物は税抜）を基礎として計算します（告示）。建物のみではありません。", "caution": ""}, {"label": "土地のみを基礎として計算する", "reason": "土地と建物の合計額（建物は税抜）を基礎として計算します（告示）。土地のみではありません。", "caution": ""}], "summary": {"head": ["土地＋建物一括売買の報酬計算（告示）", "内容"], "rows": [["計算基礎", "土地代金＋建物代金税抜額の合計"], ["建物の扱い", "消費税相当額を除いた価格を使用"], ["速算式", "合計額（税抜）×3%＋6万円（400万超の場合）"]]}}},
  {id:10800,unit:'r_bukken',level:2,field:'rights',text:'不動産の物権変動における「登記なくして対抗できない第三者」の範囲について正しいものはどれか（判例）。',opts:['登記を信頼した全ての者','正当な利益を有する者（取引当事者・差押債権者等）であり不法占拠者・背信的悪意者は含まれない','相続人も含まれる','第三者の範囲に制限はない'],ans:1,exp:'民法177条の「第三者」は当事者・包括承継人（相続人等）以外の者で不動産物権変動について正当な利益を有する者です（判例）。不法占拠者・背信的悪意者は含まれず、登記がなくても対抗できます。',"kaisetsu":{"topic": "物権変動：登記が対抗要件・不法占拠者には登記不要", "basis": {"text": "不動産の物権変動は登記が第三者への対抗要件です（民法177条）。不法占拠者には登記なく対抗できます。相続の法定相続分超過部分は登記が必要です（民法899条の2）。", "example": ""}, "reason": {"text": "民法177条の第三者の範囲を無制限にすると不公平な結果が生じます。判例は「登記の欠如を主張するにつき正当な利益を有する者」に限定し、不法占拠者や信義則に反する背信的悪意者は保護の対象外としています。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">物権変動の対抗要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対抗要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">二重譲渡</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先に登記した者が優先</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不法占拠者</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記不要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物賃借権</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡し</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続（超過部分）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記必要</text></svg>", "choices": [{"label": "登記を信頼した全ての者", "reason": "単に登記を信頼した者すべてが第三者になるわけではありません。正当な利益を有する者に限定されます（判例）。", "caution": ""}, {"label": "相続人も含まれる", "reason": "相続人は包括承継人として当事者と同視されるため、民法177条の第三者から除外されます（判例）。", "caution": "相続人・包括承継人は当事者扱い。第三者ではありません。"}, {"label": "第三者の範囲に制限はない", "reason": "判例は第三者の範囲を「正当な利益を有する者」に限定しています。不法占拠者・背信的悪意者・相続人等は除外されます。", "caution": ""}], "summary": {"head": ["立場", "民法177条の第三者か", "理由"], "rows": [["転得者（善意）", "該当", "正当な利益あり"], ["抵当権者・差押債権者", "該当", "正当な利益あり"], ["不法占拠者", "非該当", "不法行為者を保護不要"], ["背信的悪意者", "非該当", "信義則違反"], ["相続人", "非該当", "包括承継人＝当事者扱い"]]}}},


  // ===== 長文問題50問（10801〜10850）=====
  {id:10801,unit:'r_ishi',level:3,field:'rights',text:'Aは、Bに対して自己所有の甲土地（時価2000万円）を1500万円で売却する旨の売買契約を締結した。ところが、この契約はAがBに騙されて行ったものであることが後に判明した。その後、BはCに甲土地を1600万円で転売し、CはBに代金を支払い引渡しも受けたが、登記はまだAからBへの移転登記しか行われていない。この場合に関する記述として民法の規定及び判例によれば正しいものはどれか。',opts:['AはBに対して詐欺を理由に売買契約を取り消すことができるが、Cが善意無過失であればAはCに取消しを主張できない','AはBとの契約を取り消した後、甲土地の所有権を回復するためにはCに対して登記がなくても主張できる','Cが詐欺の事実を知っていた（悪意）としても、登記を先に備えた以上AはCに対抗できない','Aが詐欺を理由に取消権を行使する期間は詐欺を知った日から3年以内に限られ、その後は取り消せない'],ans:0,exp:'詐欺による取消しは、取消し前の善意無過失の第三者（この場合C）に対抗できません（民法96条3項）。Cが善意無過失であればAはCに取消しを対抗できません。なお詐欺取消し後の第三者との関係は対抗問題（登記の先後）となります。取消権の時効は詐欺を知った時から5年・行為時から20年です（民法126条）。',"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "意思表示の瑕疵には詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失の第三者は保護）・通謀虚偽表示（無効・善意の第三者は保護）があります。", "example": ""}, "reason": {"text": "詐欺取消しは善意無過失の第三者（取消し前）には対抗できません（民法96条3項）。取消し後の第三者との関係は登記の対抗問題です。取消権の時効は追認できる時から5年、詐欺を知った時から5年です（民法126条）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "AはBとの契約を取り消した後、甲土地の所有権を回復するためにはCに対して登記がなくても主張できる", "reason": "取消し後の第三者Cとの関係は対抗問題となり、AはCに登記なしでは対抗できません（判例）。", "caution": "取消し前の第三者（96条3項で保護）と取消し後の第三者（対抗問題で登記必要）を区別すること。"}, {"label": "Cが詐欺の事実を知っていた（悪意）としても、登記を先に備えた以上AはCに対抗できない", "reason": "取消し後に登記を備えたCが悪意の場合、Aは対抗できる余地があります（背信的悪意者には登記なしでも対抗可）。単純に登記だけで判断できません。", "caution": ""}, {"label": "Aが詐欺を理由に取消権を行使する期間は詐欺を知った日から3年以内に限られる", "reason": "詐欺取消権の時効は追認できる時から5年・行為の時から20年です（民法126条）。「3年」は誤りです。", "caution": "錯誤・詐欺・強迫の取消権の消滅時効は追認できる時から5年（または行為から20年）です。"}], "summary": {"head": ["場面", "AのCへの対抗"], "rows": [["取消し前・Cが善意無過失", "対抗不可"], ["取消し前・Cが悪意または有過失", "対抗可"], ["取消し後・Cが登記備得", "原則対抗不可（登記の先後）"], ["取消し後・Cが背信的悪意者", "対抗可"]]}}},
  {id:10802,unit:'r_dairi',level:3,field:'rights',text:'AはBに対して、A所有の乙建物を売却する代理権を授与した。ところがBは、Aから与えられた代理権の範囲を超えて、乙建物のほかAが所有する丙土地についても売買契約をCとの間で締結した。CはBが丙土地についても代理権を有していると信じており、そう信じることに正当な理由があった。この場合に関する記述として民法の規定及び判例によれば正しいものはどれか。',opts:['BはAから乙建物の売却についてのみ代理権を与えられているので、丙土地の売買契約は当然に無効となりAは何ら責任を負わない','CはBが丙土地についても代理権を有していると信じており正当な理由があるので、民法110条の権限外行為の表見代理が成立しAはCに対し契約の効果を否定できない','CはBに対し無権代理人の責任（民法117条）を追及するか表見代理を主張するかを任意に選択できない','表見代理が成立する場合、AはCに対し契約上の義務を負うが損害賠償責任のみを負う'],ans:1,exp:'民法110条の権限外行為の表見代理は、代理人が基本的代理権（乙建物の売却代理権）を有し、第三者がその代理人に権限外の行為（丙土地の売買）の権限があると信じたことに正当な理由がある場合に成立します。この場合Aは契約の全効果を受けます。CはBへの無権代理人責任の追及と表見代理の主張のいずれかを選択できます（選択的行使可能）。',"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護する制度です。", "example": ""}, "reason": {"text": "民法110条の権限外行為の表見代理は、基本代理権があり相手方が代理権ありと信じ、かつそう信じることに正当な理由がある場合に成立します。本人は相手方の正当な信頼を保護するために契約の効果を否定できません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "丙土地の売買契約は当然に無効となりAは何ら責任を負わない", "reason": "権限外行為の表見代理（民法110条）が成立する場合、本人は責任を負います。「当然に無効・一切責任なし」は誤りです。", "caution": "表見代理成立→本人責任。成立しない場合のみ無権代理として無効。"}, {"label": "Cは契約の効力を主張できない", "reason": "表見代理（民法110条）が成立する場合、本人Aに契約の効果が帰属します。Cは本人に契約の履行を請求できます。", "caution": ""}, {"label": "AはCに対し損害賠償責任のみを負う", "reason": "表見代理が成立した場合、本人は契約の履行責任を負います。損害賠償のみに限定されません。", "caution": ""}], "summary": {"head": ["表見代理の種類", "要件", "効果"], "rows": [["代理権授与表示（109条）", "本人が代理権を与えた旨の表示", "本人に効果帰属"], ["権限外行為（110条）", "基本代理権あり＋相手方の正当な信頼", "本人に効果帰属"], ["代理権消滅後（112条）", "代理権消滅後の行為＋相手方の善意無過失", "本人に効果帰属"]]}}},
  {id:10803,unit:'r_tanpo',level:3,field:'rights',text:'AはB銀行から3000万円を借り入れ、A所有の甲土地（時価4000万円）に第一順位の抵当権を設定した（被担保債権額3000万円）。その後AはC銀行からも1500万円を借り入れ、同じ甲土地に第二順位の抵当権を設定した。その後Aが弁済不能となり、甲土地が競売に付された。競売代金は2500万円であった。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['B銀行とC銀行は競売代金2500万円を債権額の割合（3000：1500）で按分して受け取る','B銀行が優先的に3000万円全額の満足を得ようとするが競売代金が2500万円なのでB銀行は2500万円を受け取り、C銀行は一切受け取れない','B銀行は2500万円全額を受け取りC銀行は一切受け取れないが、BはAに対し残500万円の債権を有する','競売代金が少ないので抵当権の実行は取り消される'],ans:2,exp:'抵当権者は登記の順位に従って競売代金から優先弁済を受けます。B銀行（第一順位・被担保債権3000万円）は競売代金2500万円を全額受け取り、なお500万円の債権が残ります（残債権はAへの一般債権として残存）。C銀行（第二順位）は競売代金がB銀行の優先弁済で尽きたため一切受け取れません。',"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権です（民法369条）。質権は占有の移転が必要です。先取特権は法律上当然に成立する法定担保物権です。", "example": ""}, "reason": {"text": "抵当権は順位に従い優先弁済を受けます（民法373条）。第一順位のB銀行が競売代金から優先的に弁済を受け、残額があれば第二順位のC銀行に配当されます。競売代金2500万円はB銀行（3000万円の債権）の全額弁済には足らず、B銀行が全額受け取りC銀行への配当はありません。ただしBはAに対して残500万円の債権を持ちます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・非占有</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・占有</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "債権額の割合で按分", "reason": "抵当権は順位に従い優先弁済を受けます（民法373条）。按分ではなく順位の高い者が先に弁済を受けます。", "caution": "抵当権は按分ではなく順位の高い者が優先。"}, {"label": "B銀行が3000万円全額を受け取り、C銀行は一切受け取れない", "reason": "B銀行は債権額3000万円に対して競売代金2500万円しか受け取れず、3000万円全額の満足は得られません。B銀行が受け取るのは2500万円で残500万円はAへの債権として残ります。", "caution": ""}, {"label": "競売代金が少ないので抵当権の実行は取り消される", "reason": "競売代金が被担保債権額を下回っても競売は取り消されません。不足分は無担保債権として残ります。", "caution": ""}], "summary": {"head": ["競売代金の配当（設問の場合）", "金額"], "rows": [["競売代金", "2500万円"], ["B銀行（第一順位・債権3000万円）", "2500万円受領（残500万円は無担保債権）"], ["C銀行（第二順位・債権1500万円）", "0円（B銀行の債権が優先・代金不足）"], ["AのBへの残債務", "500万円（無担保）"]]}}},
  {id:10804,unit:'r_saikensoron',level:3,field:'rights',text:'AはBに対して500万円の貸金債権を有している。ところがBはA以外にも多数の債権者（C・D・E）に対して合計2000万円の債務を負っており、Bの資産は甲土地（時価600万円）のみである。AはBに弁済を求めたがBが応じないため、BがCに対して有している100万円の売買代金債権を代位行使しようと考えている。この場合に関する記述として民法の規定及び判例によれば正しいものはどれか。',opts:['Aは債権者代位権を行使するにあたりBの同意を得る必要がある','AはBの資産（甲土地600万円）が債務合計2000万円を大きく下回っており無資力状態にあるため、Bに代位してCに対する売買代金債権を行使できる','Aが回収できる金額はAのBに対する債権額500万円に限られ、100万円全額をCから受領することはできない','AがCから売買代金100万円を回収した後、AはそのままAの取り分として保持できる'],ans:1,exp:'債権者代位権（民法423条）はBが無資力（資産600万円＜債務2000万円）であることが要件で、AはBに代位してCへの売買代金債権を行使できます。Bの同意は不要です。Aは100万円全額をCから受領できますが、それをそのままAの取り分にすることはできず、Bの財産として扱いBの債権者全員の共同担保に供されます（平等配当の原則）。',"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要です（民法446条2項）。連帯保証人には催告・検索の抗弁権がありません（民法454条）。債権譲渡の第三者対抗要件は確定日付ある証書による通知または承諾です（民法467条2項）。", "example": ""}, "reason": {"text": "債権者代位権（民法423条1項）は債務者が無資力の場合に行使できます。設問のBは資産600万円に対して債務2000万円（Aへの500万円含む）を負っており無資力状態です。AはBに代位してCに対する100万円の債権を行使できます。ただし回収金はBの財産として扱われます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相殺の要件</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">双方が同種の債権</text></svg>", "choices": [{"label": "Aは債権者代位権を行使するにあたりBの同意を得る必要がある", "reason": "債権者代位権の行使に債務者（B）の同意は不要です（民法423条1項）。", "caution": "債権者代位権＝債務者の同意不要。"}, {"label": "Aが回収できる金額はAのBに対する債権額500万円に限られる", "reason": "AはBのCに対する100万円の債権全額を行使できます（民法423条の3）。ただし直接自己に支払いを求める場合は100万円全額が対象です。", "caution": ""}, {"label": "AがCから売買代金100万円を回収した後そのまま保持できる", "reason": "代位権行使で回収した金銭はBの財産として扱われ、AはBへの債権に基づいて相殺・優先回収するための手続きが必要です（直接回収できる場合あり・民法423条の3）。", "caution": ""}], "summary": {"head": ["債権者代位権の行使", "内容"], "rows": [["要件", "無資力・被保全債権の弁済期到来"], ["行使方法", "債務者に代わって第三債務者に請求"], ["回収金の帰属", "Bの財産として扱われる（直接回収できる場合あり）"], ["AのBへの回収", "相殺等で自己の債権に充当"]]}}},
  {id:10805,unit:'r_baibai',level:3,field:'rights',text:'AはBに対して自己所有の中古マンション（築15年）を2500万円で売却した。引渡し後3か月が経過したころ、マンションの給排水管に重大な欠陥があることが判明し、修理には200万円かかることがわかった。売買契約書には「本物件は現状有姿にて引き渡す」との特約があった。Aはこの特約を根拠に責任を否定している。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['「現状有姿」特約があれば売主Aは契約不適合責任を一切負わない','Aが給排水管の欠陥を知っていたにもかかわらずBに告げなかった場合、現状有姿特約があってもAはその不適合について責任を免れない','Bは欠陥を知った日から6か月以内に追完請求・代金減額請求等の権利行使をしなければ時効で消滅する','BはAの契約不適合責任を問う前に、必ず裁判所に調停を申し立てなければならない'],ans:1,exp:'売主が不適合を知りながら告げなかった場合は免責特約（現状有姿特約を含む）の効力が及びません（民法572条）。Aが欠陥を知っていた場合は特約にかかわらず責任を負います。なお種類・品質の不適合は不適合を知った時から1年以内の「通知」（権利行使ではなく通知で足りる）が必要です（民法566条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "現状有姿特約は原則として有効ですが、売主が不適合を知りながら告げなかった場合は免責特約の効力が及びません（民法572条）。買主が不適合を知った時から1年以内に通知すれば権利を保全できます（民法566条）。6か月以内という期限はありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "現状有姿特約があれば一切の責任を負わない", "reason": "売主が知りながら告げなかった不適合には免責特約が及びません（民法572条）。「一切」は誤りです。", "caution": "知りながら告げなかった→免責特約無効（民法572条）。"}, {"label": "欠陥を知った日から6か月以内に権利行使が必要", "reason": "通知期限は「知った時から1年以内」です（民法566条）。6か月ではありません。", "caution": "通知期限＝知った時から1年（民法566条）。6か月ではありません。"}, {"label": "必ず裁判所に調停を申し立てなければならない", "reason": "調停申立ては法律上の要件ではありません（民法566条）。通知後に交渉・調停・訴訟等の手段を選べます。", "caution": ""}], "summary": {"head": ["現状有姿特約と免責", "内容"], "rows": [["原則", "特約有効（買主が現状を承知の上で購入）"], ["例外", "売主が知りながら告げなかった不適合→免責無効（民法572条）"], ["通知期限", "知った時から1年以内（民法566条）"]]}}},
  {id:10806,unit:'r_chinshaku',level:3,field:'rights',text:'AはB所有の甲建物について賃貸借契約を締結し、引渡しを受けて居住している。月額賃料は12万円で、賃貸借期間は2年と定めた。2年が経過したため、BはAに対して契約を更新しない旨を通知した。Aは建物に引き続き居住することを希望している。この場合に関する記述として借地借家法の規定によれば正しいものはどれか。',opts:['期間が満了すれば賃貸借契約は当然に終了し、AはBの要求通り直ちに退去しなければならない','Bが契約の更新を拒絶するには正当事由が必要であり、正当事由がなければ法定更新される','Bは期間満了の1か月前に更新しない旨を通知すれば、正当事由がなくても契約を終了できる','この建物賃貸借は期間が2年と定められているので、定期建物賃貸借として期間満了で当然に終了する'],ans:1,exp:'普通建物賃貸借では賃貸人が更新を拒絶するには正当事由が必要です（借地借家法28条）。正当事由がない場合は法定更新されます（同法26条）。また更新拒絶の通知は期間満了の1年前から6か月前までの間に行う必要があります。定期建物賃貸借は必ず書面で更新なしの旨を告知する手続きが必要で、本問はその手続きがないため普通賃貸借として扱われます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "普通建物賃貸借（一般の借家契約）では、賃貸人が更新を拒絶するには正当事由が必要です（借地借家法28条）。正当事由なく更新を拒絶しても法定更新されます（同法26条1項）。正当事由とは、自己使用の必要性・建物の状況・立退料の提供等を総合考慮して判断されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "期間満了で賃貸借は当然に終了し直ちに退去が必要", "reason": "普通建物賃貸借では正当事由がなければ更新拒絶はできず、期間満了でも法定更新されます（借地借家法26条1項・28条）。", "caution": "普通建物賃貸借では正当事由なき更新拒絶は無効→法定更新。"}, {"label": "1か月前の通知で正当事由なしに終了できる", "reason": "更新拒絶には正当事由が必要です（借地借家法28条）。通知の期間（6か月前）だけでは終了できません。", "caution": ""}, {"label": "定期建物賃貸借として期間満了で終了する", "reason": "定期建物賃貸借には特別の要件（書面による契約・更新がない旨の明示等）が必要です（借地借家法38条）。設問には定期建物賃貸借の要件を満たす記述がありません。", "caution": ""}], "summary": {"head": ["普通建物賃貸借の更新", "内容"], "rows": [["法定更新", "期間満了後も賃借人が使用継続→賃貸人が遅滞なく異議なければ更新（借地借家法26条1項）"], ["更新拒絶", "正当事由が必要（借地借家法28条）"], ["正当事由の考慮要素", "賃貸人・賃借人の必要性・建物状況・立退料等"], ["通知期間", "期間満了の6か月前までに通知（借地借家法26条1項）"]]}}},
  {id:10807,unit:'r_souzoku',level:3,field:'rights',text:'Aには配偶者B、長男C（既婚・子あり）、長女Dがいる。Aが遺言を残さずに死亡した。Aの遺産は、自宅土地建物（評価額5000万円）・預貯金2000万円・負債（借金）1000万円の合計正味財産6000万円である。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['配偶者Bが全遺産を相続し、CとDは何も相続できない','Bの法定相続分は2分の1（3000万円）、CとDはそれぞれ4分の1（1500万円）ずつ','CがAより先に死亡していてCの子（孫）がいた場合、Cの相続分はCの子が代わりに相続する','遺産分割には必ず家庭裁判所の関与が必要である'],ans:2,exp:'法定相続人が配偶者と子の場合、配偶者の相続分は1/2、子全体で1/2です（民法900条）。Cが先に死亡している場合はCの子（Aの孫）が代襲相続します（民法887条2項）。正味遺産6000万円の分配はB：3000万円、C（または代襲相続人）：1500万円、D：1500万円となります。遺産分割は相続人間の協議で行え、家庭裁判所の関与は協議不成立の場合に限られます。',"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2", "basis": {"text": "配偶者と子の場合は各1/2（民法900条）。相続放棄は3か月以内に家庭裁判所へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2です（民法1042条）。遺産分割協議は全員合意が必要です。", "example": ""}, "reason": {"text": "代襲相続は被相続人より先に子が死亡した場合にその子（孫）が代わって相続することです（民法887条2項）。法定相続分に従った計算・代襲相続の有無・遺産分割の方法等が問われます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続の主要ポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子の相続分</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は法定相続分の1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割協議</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "配偶者Bが全遺産を相続し、CとDは何も相続できない", "reason": "配偶者のみが全部相続するのは配偶者だけが相続人の場合です。子がいる場合は配偶者1/2・子1/2です（民法900条1号）。", "caution": ""}, {"label": "Bの法定相続分は2分の1（3000万円）、CとDはそれぞれ4分の1（1500万円）ずつ", "reason": "Cが生存している場合はBが1/2・Cが1/4・Dが1/4です。しかし設問3はCがAより先に死亡した場合の代襲相続の問題であり、これが正解です。", "caution": ""}, {"label": "遺産分割には必ず家庭裁判所の関与が必要である", "reason": "遺産分割は相続人全員の協議でできます（民法907条1項）。家庭裁判所の関与は協議が調わない場合の調停・審判のときです。", "caution": ""}], "summary": {"head": ["代襲相続", "内容"], "rows": [["要件", "被相続人より先に子が死亡・欠格・廃除", ""], ["代襲者", "死亡した子の子（孫）（民法887条2項）"], ["相続分", "代襲者が被代襲者の相続分を受け継ぐ"], ["再代襲", "孫も死亡の場合はひ孫が代襲（民法887条3項）"]]}}},
  {id:10808,unit:'r_shakuchi',level:3,field:'rights',text:'AはB所有の土地を賃借し、その土地上に自己所有の建物（登記済み）を建築して居住している。BはC銀行から借入れをしており、BC間の借入れ前から土地上に建物が存在し建物登記も完了していた。Bが返済不能となりC銀行が土地を競売にかけた。土地をDが競落した場合に関する記述として民法・借地借家法の規定及び判例によれば正しいものはどれか。',opts:['AはDに対して借地権を主張できず直ちに土地を明け渡さなければならない','Aの建物に登記があれば借地権の対抗要件を備えており、DはAの借地権を認めなければならない','Dは競落後6か月以内にAに立ち退きを求めれば、Aは無条件に退去しなければならない','土地の競落によりAの建物は自動的にDの所有物となる'],ans:1,exp:'借地権者は借地上に登記された建物を有することで第三者（競落人Dを含む）に対して借地権を対抗できます（借地借家法10条1項）。AはDに対して借地権を主張でき、引き続き土地を使用できます。ただし今後の賃料はDに支払う必要があります。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "借地権者（A）が借地上の建物に登記をしておけば、土地の所有者が変わっても（競売によりDが競落した場合でも）借地権を新所有者に対抗できます（借地借家法10条1項）。B銀行の抵当権設定前から建物登記がある場合は、競落人Dに対しても借地権を主張できます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "AはDに対して借地権を主張できず直ちに土地を明け渡さなければならない", "reason": "建物の登記があれば借地権の対抗要件を備えており、DはAの借地権を認めなければなりません（借地借家法10条1項）。", "caution": "建物登記あり→競落人にも借地権を対抗可（借地借家法10条1項）。"}, {"label": "Dは競落後6か月以内にAに立ち退きを求めれば無条件に退去しなければならない", "reason": "Aが建物登記による対抗力を持っていればDに対して借地権を主張できます。6か月という制度は建物賃借権の明渡猶予（民法395条）とは異なる話です。", "caution": ""}, {"label": "土地の競落によりAの建物は自動的にDの所有物となる", "reason": "土地の競売で建物の所有権が移転することはありません。建物と土地は別個の不動産です。", "caution": ""}], "summary": {"head": ["借地権と競売", "内容"], "rows": [["借地権の対抗要件", "建物の登記（借地借家法10条1項）"], ["抵当権設定前に建物登記", "競落人Dに対しても借地権を対抗可"], ["抵当権設定後に建物登記", "競落人Dに対抗できない場合あり"], ["建物の所有権", "土地の競売で影響なし（建物は別個の不動産）"]]}}},
  {id:10809,unit:'r_touki',level:3,field:'rights',text:'AはB所有の甲土地を購入し所有権移転登記を完了した。ところが、その後甲土地についてCが「自分が真の所有者だ」と主張し、Bから甲土地を買い受けていたと申し立てた。調べるとBはAとCの両方に甲土地を売却していた（二重売買）。CはAの登記完了後も登記を未了のままである。この場合に関する記述として民法の規定及び判例によれば正しいものはどれか。',opts:['売買契約の締結が先のCの方が所有権を取得できる','AとCのうち先に登記を備えた者が所有権を第三者に対抗できる','BがAとCの両方に売却したことが詐欺に当たるためAB間・BC間の契約が無効となる','Aが登記を完了していても、Cが登記前に強く所有権を主張すれば所有権はCに移転する'],ans:1,exp:'不動産物権変動は登記をしなければ第三者に対抗できません（民法177条）。二重売買ではAとCのどちらが先に登記を備えるかで所有権の帰属が決まります。本問ではAが先に登記を完了しているためAが所有権を対抗できます。Cは登記を備えていないため所有権を主張できません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "二重売買では登記の先後が対抗関係を決します（民法177条）。設問ではAが先に登記を備えているため、CはAに対して所有権を主張できません。AとCは「先に登記した者が勝つ」という対抗関係にあります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "売買契約の締結が先のCの方が所有権を取得できる", "reason": "契約の先後は対抗関係を決しません。登記の先後が勝敗を決めます（民法177条）。Aが先に登記しているためAが優先します。", "caution": "先に契約≠先に権利取得。登記が先の者が勝ちます。"}, {"label": "BがAとCの両方に売却したことが詐欺に当たるためAB間・BC間の契約が無効となる", "reason": "双方への売却は債務不履行・詐欺になりますが、それをもって両方の売買契約が無効になるわけではありません。先に登記した者が所有権を取得します。", "caution": ""}, {"label": "Aが登記を完了していても、Cが登記前に強く所有権を主張すれば所有権はCに移転する", "reason": "所有権の帰属は強く主張するかどうかではなく、登記の先後で決まります（民法177条）。", "caution": ""}], "summary": {"head": ["状況", "結果"], "rows": [["Aが先に登記を備えた", "Aが所有権取得。CはBに損害賠償請求可"], ["Cが先に登記を備えた", "Cが所有権取得。AはBに損害賠償請求可"], ["いずれも未登記", "先に登記した者が優先（引き続き対抗関係）"]]}}},
  {id:10810,unit:'r_kukku',level:3,field:'rights',text:'分譲マンション（専有部分30戸）の区分所有者の集会において、共用部分である外壁・屋上の大規模修繕工事を行うことについて審議された。この工事は共用部分の形状・効用の著しい変更を伴うものではなく、耐久性向上のための修繕である。また同集会において、一部の区分所有者から専有部分の間取りを変更することも提案された。この場合に関する記述として区分所有法の規定によれば正しいものはどれか。',opts:['外壁・屋上の修繕は共用部分に関するものであるから、区分所有者全員の同意がなければ工事を行えない','形状・効用の著しい変更を伴わない共用部分の修繕（軽微変更）は区分所有者及び議決権の各過半数で決議できる','専有部分の間取り変更については集会決議は不要で各区分所有者が自由に行える','大規模修繕工事には必ず建替え決議（各5/4以上）と同等の決議が必要'],ans:1,exp:'共用部分の変更は原則として区分所有者及び議決権の各3/4以上の特別決議が必要ですが（区分所有法17条1項）、形状・効用の著しい変更を伴わない軽微な変更については区分所有者及び議決権の各過半数で決議できます（同法18条1項）。専有部分の間取り変更は区分所有者が原則として自由に行えますが、共用部分への影響がある場合は制限を受けることがあります。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "共用部分の軽微変更（形状・効用の著しい変更を伴わない修繕等）は区分所有者および議決権の各過半数の普通決議で足ります（区分所有法18条1項）。専有部分の間取り変更は各区分所有者の自由ですが、共用部分や他の専有部分に影響する場合は制限があります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "外壁・屋上の修繕は共用部分に関するものであるから区分所有者全員の同意がなければ工事を行えない", "reason": "軽微変更（形状・効用の著しい変更を伴わない修繕）は過半数決議で足ります（区分所有法18条1項）。全員同意は不要です。", "caution": "軽微変更（通常の修繕）＝過半数で可。全員同意は不要。"}, {"label": "専有部分の間取り変更については集会決議は不要で各区分所有者が自由に行える", "reason": "専有部分内の間取り変更は原則として自由ですが、共用部分（壁の一部が共用の場合等）に影響する場合は制限があります。「完全に自由」は誤りです。", "caution": ""}, {"label": "大規模修繕工事には必ず建替え決議（各5/4以上）と同等の決議が必要", "reason": "大規模修繕工事でも建替え決議要件（5/4以上）は不要です。修繕の内容が重大変更か軽微変更かで3/4以上か過半数かが決まります（区分所有法17条・18条）。", "caution": ""}], "summary": {"head": ["修繕工事と決議", "決議要件"], "rows": [["軽微変更（通常修繕・耐久性向上等）", "過半数（区分所有法18条1項）"], ["重大変更（形状・効用の著しい変更）", "3/4以上（区分所有法17条1項）"], ["建替え", "4/5以上（区分所有法62条1項）"]]}}},
  {id:10811,unit:'l_menkyo',level:3,field:'law',text:'宅地建物取引業者A（甲県知事免許）は、事業拡大のため乙県にも新たに事務所を開設することを計画している。現在Aの甲県の主たる事務所には専任の宅建士が3名、業務に従事する者は12名在籍している。乙県の新事務所には業務に従事する者を5名置く予定である。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['乙県に事務所を開設するには甲県知事の許可だけで足り、免許換えは不要である','乙県に事務所を開設する場合、2以上の都道府県に事務所を設置することになるため国土交通大臣免許への免許換えが必要となる','乙県の新事務所には宅建士は1名いれば専任要件を満たす','甲県の主たる事務所の専任の宅建士は現在3名だが、業務従事者12名に対しては3名では不足している'],ans:1,exp:'2以上の都道府県に事務所を設置する宅建業者は国土交通大臣免許が必要です（宅建業法3条1項）。現在甲県知事免許のAが乙県にも事務所を設置する場合は国土交通大臣免許への免許換えが必要です（宅建業法7条）。また乙県の新事務所は業務従事者5名に対し専任宅建士が1名（5名に1名以上の基準を満たす）必要です。甲県の専任宅建士3名は業務従事者12名（12÷5＝2.4→切り上げ3名）に対し適正です。',"kaisetsu":{"topic": "宅建業の免許：知事・大臣免許の区別・有効期間5年・欠格事由", "basis": {"text": "1都道府県のみ→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間です。", "example": ""}, "reason": {"text": "2以上の都道府県に事務所を設置する場合は国土交通大臣免許への免許換えが必要です（宅建業法7条1項）。乙県の新事務所に業務従事者5名を置く場合、専任宅建士は1名以上必要です（宅建業法31条の3第1項：5名に1名以上）。甲県の主たる事務所は12名に対して3名の専任宅建士を置いており（12÷5=2.4→3名以上必要）、3名は適正です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（拘禁刑以上・特定罰金等）</text></svg>", "choices": [{"label": "乙県に事務所を開設するには甲県知事の許可だけで足り免許換えは不要", "reason": "2つ以上の都道府県に事務所を設置する場合は大臣免許への免許換えが必要です（宅建業法7条1項）。", "caution": "2都道府県以上＝大臣免許への免許換えが必要（宅建業法7条1項）。"}, {"label": "乙県の新事務所には宅建士は1名いれば専任要件を満たす", "reason": "業務従事者5名に対しては1名の専任宅建士で足ります（宅建業法31条の3第1項：5名に1名以上）。5÷5=1で1名で法定要件を満たします。この選択肢の内容は数字上は正しいですが、設問の正解は選択肢2です。", "caution": ""}, {"label": "甲県の主たる事務所の専任の宅建士は現在3名だが業務従事者12名に対しては3名では不足", "reason": "12÷5=2.4→切り上げて3名以上が必要。現在3名は法定要件を満たしています（宅建業法31条の3第1項）。「不足している」は誤りです。", "caution": ""}], "summary": {"head": ["免許換えと専任宅建士", "内容"], "rows": [["1都道府県→2都道府県", "大臣免許への免許換えが必要（宅建業法7条1項）"], ["専任宅建士の計算", "業務従事者数÷5（端数切上げ）が最低必要数"], ["甲県12名", "3名以上必要→3名で適正"], ["乙県5名", "1名以上必要"]]}}},
  {id:10812,unit:'l_jusetsu',level:3,field:'law',text:'宅建業者Aは、売主BからB所有の中古マンション（専有部分65m2・管理費月額2万円・修繕積立金月額1.5万円・修繕積立金残高300万円）の売却を依頼され、買主Cに対して重要事項の説明を行おうとしている。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['Cが宅建業者であっても説明を省略することはできず、宅建士証を提示して宅建士が直接説明しなければならない','重要事項説明書には管理費・修繕積立金の月額および修繕積立金の積立残高を記載しなければならない','重要事項説明書にはマンション管理組合の財政状況（積立金残高等）の記載は任意であり義務ではない','管理費・修繕積立金は販売業者が口頭で伝えれば重要事項説明書への記載は不要である'],ans:1,exp:'区分所有建物（マンション）の売買では、管理費・修繕積立金の月額・滞納状況・積立金残高等は重要事項説明書に記載しなければならない事項です（宅建業法35条1項6号・施行規則16条の2）。なお相手方が宅建業者の場合は説明（口頭）は省略できますが書面交付義務は残ります（宅建業法35条6項）。',"kaisetsu":{"topic": "重要事項説明：宅建士が説明・売主への交付は不要・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主への交付義務はありません。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能です。", "example": ""}, "reason": {"text": "区分所有建物（マンション）の売買では管理費・修繕積立金の月額とその積立残高を35条書面に記載しなければなりません（宅建業法35条1項6号・同施行令3条の2等）。宅建業者間取引では説明は省略できますが書面交付は必要です（宅建業法35条6項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "Cが宅建業者であっても説明を省略することはできず宅建士証を提示して宅建士が直接説明しなければならない", "reason": "設問ではCは宅建業者でない（「買主C」とのみ記述）ため、説明は必要です。Cが宅建業者であれば説明は省略できます（宅建業法35条6項）。", "caution": "宅建業者間：説明省略可・書面交付不可省略。"}, {"label": "重要事項説明書にはマンション管理組合の財政状況（積立金残高等）の記載は任意", "reason": "修繕積立金の積立残高は必須記載事項です（宅建業法35条1項6号等）。任意ではありません。", "caution": ""}, {"label": "管理費・修繕積立金は販売業者が口頭で伝えれば記載は不要", "reason": "35条書面への記載が義務付けられており（宅建業法35条1項6号等）、口頭説明だけでは不足です。", "caution": ""}], "summary": {"head": ["マンション売買の重要事項（宅建業法35条1項6号等）", "記載必要か"], "rows": [["管理費の月額", "必要"], ["修繕積立金の月額", "必要"], ["修繕積立金の積立残高", "必要"], ["管理会社・管理形態", "必要"]]}}},
  {id:10813,unit:'l_baikai',level:3,field:'law',text:'AはB所有の土地の売却を依頼され、専任媒介契約を締結した。契約締結から5日後（休業日なし）にAはレインズ（指定流通機構）に物件情報を登録した。契約締結から10日後にAはBに対して業務処理状況を報告した。その後Cとの間で売買契約が成立したが、Aはレインズへの成約報告を怠った。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['専任媒介契約のレインズへの登録期限は7日以内（休業日除く）なので、5日後の登録は適法','専任媒介契約のレインズへの登録期限は5日以内（休業日除く）であり5日後の登録は登録義務の期限ギリギリで適法','専任媒介契約の依頼者への業務報告は2週間に1回以上なので10日後の報告は報告義務違反','成約後のレインズへの成約報告はAの義務であり、怠った場合は指示処分等の対象となりうる'],ans:3,exp:'専任媒介契約ではレインズへの登録は7日以内（休業日除く）、報告は2週間に1回以上です（宅建業法34条の2第5項・9項）。5日後の登録は適法（7日以内）。10日後の報告も2週間（14日）以内なので適法。成約後のレインズへの成約報告（登録の削除・更新）は義務で、怠ると業務規制違反として行政処分の対象となります。',"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任媒介の有効期間の上限は3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。専任は7日以内、専属専任は5日以内にレインズ登録が必要。業務報告は専任2週間に1回、専属専任1週間に1回。", "example": ""}, "reason": {"text": "専任媒介契約のレインズ登録期限は7日以内（休業日除く）で（宅建業法34条の2第5項）、設問では契約から5日後に登録しており適法です。業務報告は2週間に1回以上で（同条9項）、10日後の報告は初回として適法です。成約後のレインズ成約報告は義務であり（宅建業法施行規則15条の9）、怠ると処分対象です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">一般</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専任</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専属専任</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己発見取引</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">レインズ登録</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務報告</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">なし</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間に1回</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1週間に1回</text></svg>", "choices": [{"label": "専任媒介契約のレインズへの登録期限は7日以内（休業日除く）なので5日後の登録は適法", "reason": "正解の通り、5日後の登録は7日以内の義務を満たしており適法です。設問の正解は選択肢4（成約報告の怠り）です。", "caution": ""}, {"label": "専任媒介契約のレインズへの登録期限は5日以内（休業日除く）であり5日後の登録は適法", "reason": "5日以内の登録期限は専属専任媒介です（宅建業法34条の2第6項）。専任媒介は7日以内（同条5項）です。5日後の登録は専任媒介でも問題ありませんが、「5日以内が期限」は誤りです。", "caution": ""}, {"label": "専任媒介契約の依頼者への業務報告は2週間に1回以上なので10日後の報告は報告義務違反", "reason": "報告義務は2週間（14日）に1回以上であり（宅建業法34条の2第9項）、10日後の報告は2週間以内なので適法です。「違反」は誤りです。", "caution": ""}], "summary": {"head": ["設問の各行為の適法性", "内容"], "rows": [["5日後のレインズ登録", "適法（7日以内の期限内）"], ["10日後の業務報告", "適法（2週間以内）"], ["成約後の報告怠り", "義務違反→指示処分等の対象"]]}}},
  {id:10814,unit:'l_37jo',level:3,field:'law',text:'宅建業者Aが媒介した土地の売買契約が成立した。この売買では、代金3000万円のうち500万円は契約時に手付金として支払い、残代金2500万円は引渡し時に支払うこととなった。また、買主が住宅ローンの審査に通らなかった場合には契約を白紙解除できる旨（ローン特約）も合意された。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['37条書面には手付金の額（500万円）は記載不要で、残代金の額（2500万円）のみを記載すればよい','37条書面には代金の額（3000万円）・支払時期・支払方法を記載しなければならない','ローン特約は当事者が合意した事項であっても、37条書面への記載は任意であり記載しなくてもよい','37条書面は買主にのみ交付すればよく、売主への交付は不要である'],ans:1,exp:'37条書面の必要的記載事項には代金の額（合計3000万円）・支払時期（いつ支払うか）・支払方法が含まれます（宅建業法37条1項2号）。融資（ローン）に関する定め（ローン特約）は定めがある場合に記載する任意的記載事項です（同項8号）。37条書面は売主・買主の双方に交付しなければなりません（同条1項）。',"kaisetsu":{"topic": "37条書面：全取引で交付・記名（押印不要）・移転登記申請時期は必要的記載事項", "basis": {"text": "37条書面は売買・交換・賃貸借の全取引で契約の双方当事者に交付が義務（宅建業法37条）。引渡し時期・移転登記申請時期は必要的記載事項。2021年改正で押印は不要になり記名のみで足ります。", "example": ""}, "reason": {"text": "代金の額・支払時期・支払方法は37条書面の必要的記載事項です（宅建業法37条1項2号）。代金3000万円全体（手付金500万円＋残金2500万円）と各支払時期・方法を記載します。ローン特約は定めがある場合の任意的記載事項です（同条1項8号）。37条書面は売主・買主双方に交付します（同条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付義務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全取引・双方当事者</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡時期・移転登記申請時期等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要）</text></svg>", "choices": [{"label": "37条書面には手付金の額（500万円）は記載不要で残代金（2500万円）のみを記載すればよい", "reason": "代金の総額（3000万円）と各支払時期・方法を記載します（宅建業法37条1項2号）。「残代金のみ」は誤りです。", "caution": "代金全額（手付金を含む）と支払時期・方法を記載（宅建業法37条1項2号）。"}, {"label": "ローン特約は37条書面への記載は任意であり記載しなくてもよい", "reason": "ローン特約（融資あっせんに関する事項）は「定めがある場合」の記載事項です（宅建業法37条1項8号）。定めがある場合は記載しなければなりません。", "caution": ""}, {"label": "37条書面は買主にのみ交付すればよく売主への交付は不要", "reason": "37条書面は売主・買主双方に交付しなければなりません（宅建業法37条1項）。", "caution": ""}], "summary": {"head": ["設問の37条書面記載事項", "必要的か任意的か"], "rows": [["代金3000万円（手付＋残金）", "必要的"], ["支払時期・方法", "必要的"], ["引渡し時期", "必要的"], ["ローン特約", "任意的（定めがある場合）"]]}}},
  {id:10815,unit:'l_cooling',level:3,field:'law',text:'宅建業者A（自ら売主）は、買主B（個人・宅建業者でない）との間で宅地の売買契約を締結した。契約場所はAの会社（宅建業の事務所）ではなく、Bが指定した喫茶店であった。Aはクーリングオフができる旨等を書面でBに告知した。告知の8日後、BはAに対してクーリングオフの意思表示を書面で郵送した（8日目に投函）。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['クーリングオフは書面が届いた日から効力が生じるため、8日目に郵送した書面が9日目以降に到達した場合はクーリングオフは認められない','クーリングオフの意思表示は発信主義が適用され、書面を郵送した日（8日目）に効力が生じるためBのクーリングオフは有効','喫茶店で契約した場合でも、買主Bが自ら指定した場所であればクーリングオフはできない','クーリングオフが有効となった場合、AはBに対して手付金の2倍を返還しなければならない'],ans:1,exp:'クーリングオフの意思表示は書面を発送した時点で効力が生じます（発信主義・宅建業法37条の2第2項）。告知から8日目の発送はクーリングオフ期間内（告知日を含め8日以内）に適法に行われており、有効です。クーリングオフが成立した場合、Aは受領済みの金銭（手付金等）を遅滞なく返還しなければなりませんが、手付の倍額返還義務はありません。',"kaisetsu":{"topic": "クーリングオフ：告知日から8日以内・書面で・事務所では不可・全額返還", "basis": {"text": "クーリングオフは告知を受けた日から8日以内に書面で行います（宅建業法37条の2）。事務所・モデルルーム等での申込みはクーリングオフ不可。解除後業者は全額返還（費用控除不可）。", "example": ""}, "reason": {"text": "クーリングオフの意思表示は発信主義（宅建業法37条の2第2項）であり、書面を発した時に効力が生じます。告知から8日目に郵送した書面は8日以内の行使として有効です。買主が指定した喫茶店での契約はクーリングオフの対象場所です（施行規則16条の5は喫茶店を事務所等に含まない）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">クーリングオフのポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">告知日から8日以内</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">方法</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面（発信主義）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所での申込み</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">クーリングオフ不可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除後</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全額返還（費用控除不可）</text></svg>", "choices": [{"label": "クーリングオフは書面が届いた日から効力が生じるため8日目に郵送した書面が9日目以降に到達した場合はクーリングオフは認められない", "reason": "発信主義（宅建業法37条の2第2項）であり、到達した日ではなく発送した日に効力が生じます。8日目に発送した書面は有効です。", "caution": "発信主義：郵送した日（8日目）に効力発生。到達は関係なし（宅建業法37条の2第2項）。"}, {"label": "喫茶店で契約した場合でも買主Bが自ら指定した場所であればクーリングオフはできない", "reason": "買主が指定した喫茶店は施行規則16条の5の「事務所等」に含まれないため、クーリングオフができます。「自ら指定した自宅・勤務先」のみが事務所等に準じた扱いです（施行規則16条の5第3号）。", "caution": ""}, {"label": "クーリングオフが有効となった場合AはBに対して手付金の2倍を返還しなければならない", "reason": "クーリングオフ後は受領した金額の全額を返還します（宅建業法37条の2第3項）。「倍返し」は手付解除の場合（民法557条1項）であり、クーリングオフとは異なります。", "caution": ""}], "summary": {"head": ["設問の各事項の解説", "内容"], "rows": [["契約場所（喫茶店・買主指定）", "事務所等でない→クーリングオフ可"], ["8日目の郵送", "発信主義→有効（宅建業法37条の2第2項）"], ["クーリングオフ後の返還", "受領全額（倍返しではない）"]]}}},
  {id:10816,unit:'l_hoshu',level:3,field:'law',text:'宅建業者Aは、売主B・買主Cの双方から依頼を受けて、代金4000万円の土地の売買を媒介した。AはBから媒介報酬として126万円（税込138.6万円）を受け取り、CからもBと同額の126万円（税込138.6万円）を受け取った。この場合に関する記述として宅建業法の規定（報酬告示）によれば正しいものはどれか。',opts:['代金4000万円の媒介報酬の上限は一方の依頼者から132万円（税込145.2万円）であり、Aが受領した126万円（税込138.6万円）は上限内で適法','代金4000万円の媒介報酬の上限（消費税別）は一方の依頼者から126万円（代金×3%＋6万円）であり、Aが受領した額は上限内で適法','売主・買主双方から報酬を受け取る場合は一方からの受領額を一方の上限の半額に抑えなければならない','媒介契約でなく代理契約であれば報酬上限は2倍になり、双方から合計504万円（税別）まで受け取れる'],ans:1,exp:'代金4000万円の売買媒介では一方の依頼者から受け取れる報酬上限（税別）は4000万円×3%＋6万円＝126万円です（報酬告示）。Aが受領した126万円（税別）は上限内で適法です。なお代理の場合は一方の依頼者から媒介の2倍（252万円・税別）が上限となりますが、双方から代理した場合でも合計252万円（税別）が上限です（報酬告示）。',"kaisetsu":{"topic": "報酬：売買は代金×3%+6万（400万超）・賃貸は借賃1か月・上限超過は不可", "basis": {"text": "売買媒介報酬（400万超）の一方からの上限は代金×3%+6万円（税別）。双方合計は一方上限×2。賃貸媒介（居住用・非居住用とも）は借賃1か月分。依頼者の承諾があっても上限超過は不可。", "example": ""}, "reason": {"text": "代金4000万円（400万円超）の媒介報酬上限は速算式で4000万円×3%＋6万円＝126万円（税別）が一方の依頼者からの上限です（告示）。AがBから126万円・CからもBと同額の126万円を受け取ることは適法です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対象</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（400万超）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万（一方）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（200万以下）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸（双方合計）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借賃1か月分</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">低廉な空家等（800万円以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円まで（説明・合意要）</text></svg>", "choices": [{"label": "代金4000万円の媒介報酬の上限は一方の依頼者から132万円（税込145.2万円）", "reason": "4000万円×3%＋6万円＝126万円（税別）が正しい計算です（告示）。132万円は誤りです。", "caution": "4000万円×3%＋6万円＝120万円＋6万円＝126万円（税別）。"}, {"label": "売主・買主双方から報酬を受け取る場合は一方からの受領額を一方の上限の半額に抑えなければならない", "reason": "双方から受け取る場合でも各一方から上限（126万円）まで受け取れます（告示）。「半額に抑える」という規制はありません。", "caution": ""}, {"label": "媒介契約でなく代理契約であれば報酬上限は2倍になり双方から合計504万円（税別）まで受け取れる", "reason": "代理の場合は一方から媒介の2倍（252万円・税別）まで受け取れますが、双方合計でも媒介の2倍（252万円・税別）が上限です（告示）。「504万円まで」は誤りです。", "caution": ""}], "summary": {"head": ["設問の報酬計算", "計算"], "rows": [["代金", "4000万円"], ["速算式", "4000万円×3%＋6万円"], ["計算結果", "120万円＋6万円＝126万円（税別）"], ["消費税込", "126万円×1.1＝138.6万円"], ["適法性", "Bから126万円・Cから126万円は各々上限内で適法"]]}}},
  {id:10817,unit:'k_toshi',level:3,field:'limit',text:'AはC市（都市計画区域内・市街化区域）に土地（面積1500m2）を所有しており、この土地に店舗と倉庫を建築しようとしている。この土地は第一種住居地域に指定されており、建ぺい率60%・容積率200%が定められている。また前面道路幅員は4mである。この場合に関する記述として都市計画法及び建築基準法の規定によれば正しいものはどれか。',opts:['第一種住居地域では店舗の建築は一切できない','第一種住居地域では床面積3000m2以下の店舗は建築できるが、倉庫（危険物の貯蔵に供するものを除く）も建築できる','前面道路幅員4mの場合、容積率は前面道路幅員×0.4（住居系）＝160%が適用される可能性があり、指定容積率200%より低い制限が適用されることがある','市街化区域内の開発行為は面積にかかわらず開発許可が不要である'],ans:2,exp:'前面道路幅員による容積率制限（建築基準法52条2項）では、住居系用途地域では前面道路幅員（m）×4/10が容積率の上限となります。4m×4/10＝160%<指定容積率200%なので、この場合は160%が適用される可能性があります。第一種住居地域では床面積3000m2以下の店舗・倉庫は建築可能（建築基準法別表第二）。市街化区域内の開発行為は1000m2以上で原則として開発許可が必要です。',"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域での1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は市街化調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "前面道路幅員が12m未満の建築物の容積率は、指定容積率と「前面道路幅員×法定係数（住居系0.4）」の小さい方が適用されます（建築基準法52条2項）。4m×0.4=160%が容積率の制限となり、指定容積率200%より低い160%が適用されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化する区域</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可基準</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "第一種住居地域では店舗の建築は一切できない", "reason": "第一種住居地域では床面積3000㎡以下の店舗は建築できます（建築基準法別表第二）。「一切不可」は誤りです。", "caution": ""}, {"label": "第一種住居地域では床面積3000m2以下の店舗は建築できるが倉庫（危険物の貯蔵に供するものを除く）も建築できる", "reason": "第一種住居地域では床面積3000㎡以下の店舗と危険物を貯蔵しない倉庫は建築できます（建築基準法別表第二）。この選択肢は正しい内容ですが、設問の正解は選択肢3（容積率計算に関する記述）です。", "caution": ""}, {"label": "市街化区域内の開発行為は面積にかかわらず開発許可が不要である", "reason": "市街化区域内では1000㎡以上の開発行為には許可が必要です（都市計画法29条1項・施行令19条）。「面積にかかわらず不要」は誤りです。", "caution": ""}], "summary": {"head": ["前面道路幅員による容積率制限（建築基準法52条2項）", "計算"], "rows": [["計算式", "前面道路幅員（m）×法定係数"], ["住居系の係数", "4/10（0.4）"], ["商業系・その他の係数", "6/10（0.6）"], ["適用", "指定容積率と小さい方を適用"], ["設問の例", "4m×0.4＝160%＜200%（指定）→160%が適用"]]}}},
  {id:10818,unit:'k_kenchiku',level:3,field:'limit',text:'AはD市内において次のような建築計画を立てている。計画地は準防火地域内にあり、敷地面積200m2・建ぺい率60%・容積率200%が指定されている。計画建物は木造3階建て・延べ面積350m2・耐火建築物である。また計画地は幹線道路（幅員8m）に面した角地（特定行政庁指定）でもある。この場合に関する記述として建築基準法の規定によれば正しいものはどれか。',opts:['準防火地域内の木造建築物は3階建てが禁止されているため、この計画は建築基準法に違反する','建ぺい率60%に対し、耐火建築物であることで10%加算・角地であることで10%加算され、建ぺい率の上限は80%となる','容積率200%・敷地面積200m2の場合、延べ面積の上限は400m2であり、延べ面積350m2の本計画は容積率制限内である','前面道路幅員8mは幅員規制（4m以上）を上回っているため、道路幅員による容積率制限は適用されない'],ans:1,exp:'建ぺい率は防火地域・準防火地域内の耐火建築物で10%加算、特定行政庁指定の角地で10%加算（建築基準法53条3項・同法施行令135条の3）されます。60%+10%+10%=80%が上限となります。延べ面積の上限は敷地面積200m2×容積率200%=400m2で、350m2は上限内です。前面道路8mの場合は8m×4/10=320%>200%なので指定容積率200%が適用されます。',"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・道路斜線・用途制限", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。用途地域ごとに建築物の制限があります。", "example": ""}, "reason": {"text": "建ぺい率は耐火建築物10%加算（建築基準法53条3項1号）・角地10%加算（同条3項2号）が適用されると、60%＋10%＋10%＝80%になります。容積率は前面道路8m×6/10（準住居地域以外の商業系等は6/10）=480%または指定容積率200%の小さい方→200%が適用。延べ面積350㎡÷敷地200㎡=175%<200%で適法。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">第1種低層</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">学校は建築可</text></svg>", "choices": [{"label": "準防火地域内の木造建築物は3階建てが禁止されているため違反", "reason": "準防火地域内の木造3階建ては耐火建築物等にすれば建築できます（建築基準法62条）。3階建て禁止ではありません。", "caution": "準防火地域内木造3階建て：耐火建築物等にすれば建築可（建築基準法62条）。"}, {"label": "容積率200%・敷地面積200m2の場合延べ面積の上限は400m2", "reason": "指定容積率200%で敷地200㎡の場合、延べ面積上限は200㎡×200%=400㎡です。この内容は正しいですが、設問の正解は選択肢2（建ぺい率の加算計算）です。", "caution": ""}, {"label": "前面道路幅員8mは幅員規制（4m以上）を上回っているため道路幅員による容積率制限は適用されない", "reason": "前面道路幅員が12m未満の場合は道路幅員による容積率制限が適用されます（建築基準法52条2項）。8mは12m未満のため制限が適用されます。", "caution": "前面道路幅員12m未満：道路幅員×係数による容積率制限が適用（建築基準法52条2項）。"}], "summary": {"head": ["設問の建ぺい率計算", "内容"], "rows": [["指定建ぺい率", "60%"], ["耐火建築物加算", "＋10%"], ["角地加算", "＋10%"], ["最大建ぺい率", "80%（200m2×80%=160m2まで）"]]}}},
  {id:10819,unit:'k_nochi',level:3,field:'limit',text:'AはE市（市街化区域内）に農地（田・面積500m2）を所有しており、この農地を宅地に転用して自己の住宅を建築しようとしている。また、この農地に隣接するF所有の農地（市街化区域外・面積2000m2）についても購入して宅地にしようと計画している。この場合に関する記述として農地法の規定によれば正しいものはどれか。',opts:['市街化区域内の農地を自己転用する場合、都道府県知事の許可が必要','市街化区域内の農地を自己転用する場合、農業委員会への届出で足りる（農地法4条1項8号）','市街化区域外のF所有農地を購入して宅地にしようとする場合、農業委員会への届出で足りる','市街化区域外の農地の転用目的での購入には都道府県知事の許可が必要（農地法5条）'],ans:3,exp:'市街化区域内の農地の自己転用（農地法4条）は農業委員会への届出のみで足ります（都道府県知事許可不要）。市街化区域外の農地を転用目的で購入する場合（農地法5条）は都道府県知事の許可が必要です（4ha超は農林水産大臣）。したがって①A所有農地（市街化区域内自己転用）→農業委員会届出のみ、②F所有農地（市街化区域外・転用目的での権利移動）→都道府県知事許可が必要です。',"kaisetsu":{"topic": "農地法：3条は農業委員会・4条・5条は都道府県知事・市街化区域は届出のみ", "basis": {"text": "農地法3条（権利移動・農地→農地）の許可権者は農業委員会。4条（自己転用）・5条（転用目的の権利移動）は都道府県知事等。市街化区域内の農地転用（4・5条）は農業委員会への届出のみでOK。相続は許可不要・届出3か月以内。", "example": ""}, "reason": {"text": "市街化区域内の農地の転用目的での購入（農地法5条）は農業委員会への届出で足ります（農地法5条1項7号）。市街化区域外の農地の転用目的購入には都道府県知事の許可が必要です（農地法5条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">市街化区域</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">特例なし</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text></svg>", "choices": [{"label": "市街化区域内の農地を自己転用する場合都道府県知事の許可が必要", "reason": "市街化区域内は農業委員会への届出で足ります（農地法4条1項7号）。「知事の許可」は誤りです。", "caution": "市街化区域内：農業委員会への届出。市街化区域外：知事の許可（農地法4条・5条）。"}, {"label": "市街化区域内の農地を自己転用する場合農業委員会への届出で足りる", "reason": "この選択肢は正しい内容です（農地法4条1項7号）。ただし設問の正解は選択肢4（市街化区域外の転用目的購入）です。", "caution": ""}, {"label": "市街化区域外のF所有農地を購入して宅地にしようとする場合農業委員会への届出で足りる", "reason": "市街化区域外の農地の転用目的購入には都道府県知事の許可が必要です（農地法5条1項）。届出で足りるのは市街化区域内です。", "caution": ""}], "summary": {"head": ["農地法5条（転用目的の権利移動）の手続き", "内容"], "rows": [["市街化区域内", "農業委員会への届出（許可不要）"], ["市街化区域外", "都道府県知事の許可"]]}}},
  {id:10820,unit:'k_kukaku',level:3,field:'limit',text:'G市が施行者となって土地区画整理事業が行われている区域内に宅地を所有するAは、施行者から仮換地の指定を受けた。仮換地はAの従前の宅地とは異なる位置に指定されており、仮換地の面積は従前の宅地より若干小さい。この場合に関する記述として土地区画整理法の規定によれば正しいものはどれか。',opts:['仮換地の指定後も、Aは従前の宅地と仮換地の両方を使用収益できる','仮換地の指定の効力が生じた後は、Aは仮換地について使用収益できるが、従前の宅地については使用収益できなくなる','仮換地の面積が従前の宅地より小さい場合、Aは仮換地の指定を拒否できる','仮換地の指定により、Aの従前の宅地の所有権は仮換地に移転する'],ans:1,exp:'仮換地の指定の効力が生じると、仮換地について使用収益できるようになり、従前の宅地については使用収益できなくなります（土地区画整理法99条1項）。仮換地と従前地の面積の差は、換地処分後に清算金で調整されます。所有権は換地処分の公告後に移転するものであり、仮換地の指定の時点では所有権は移転しません。',"kaisetsu":{"topic": "土地区画整理法：換地は公告翌日確定・仮換地は従前地使用不可・組合は2/3以上", "basis": {"text": "換地処分の公告翌日から換地が確定します（土地区画整理法104条）。仮換地の指定後は従前地を使用できなくなります（同法99条）。組合設立には土地所有者・借地権者の各2/3以上の同意が必要です。", "example": ""}, "reason": {"text": "仮換地の指定の効力が生じた後は、仮換地を使用収益でき、従前の宅地の使用収益は原則として停止されます（土地区画整理法99条1項・2項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">土地区画整理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">換地の確定</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公告の翌日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮換地指定後</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従前地は使用不可（所有権は残る）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">組合設立</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各2/3以上の同意</text></svg>", "choices": [{"label": "仮換地の指定後もAは従前の宅地と仮換地の両方を使用収益できる", "reason": "両方は認められません（土地区画整理法99条1項・2項）。", "caution": "仮換地指定後：仮換地で使用収益可・従前地の使用収益停止（土地区画整理法99条）。"}, {"label": "仮換地の面積が従前の宅地より小さい場合Aは仮換地の指定を拒否できる", "reason": "仮換地の指定を拒否する権利はありません（土地区画整理法98条）。面積差は清算金で調整されます。", "caution": ""}, {"label": "仮換地の指定によりAの従前の宅地の所有権は仮換地に移転する", "reason": "仮換地の指定では所有権は移転しません（土地区画整理法99条）。", "caution": ""}], "summary": {"head": ["仮換地の効果（設問の場合）", "内容"], "rows": [["仮換地", "使用収益可"], ["従前の宅地", "使用収益停止"], ["所有権", "移転しない"]]}}},
  {id:10821,unit:'t_joto',level:3,field:'tax',text:'AはB（個人）から居住用マンション（所有期間15年・自己居住用）を4000万円で購入し3年後に5500万円で売却した。Aの取得費は4100万円（購入価格4000万円＋取得時の諸費用100万円）、譲渡費用（仲介手数料等）は150万円であった。Aは売却した年の前年・前々年に居住用財産の3000万円特別控除を受けていない。この場合に関する記述として租税特別措置法の規定によれば正しいものはどれか。',opts:['譲渡所得＝5500万円－4100万円－150万円＝1250万円であり、所有期間15年の長期譲渡として税率20%が適用される','3000万円特別控除の適用を受ければ課税譲渡所得＝1250万円－3000万円＝△1750万円となり税金はかからない','所有期間15年で譲渡価格5500万円は6000万円以下なので、軽減税率（税率14%）の特例が全額に適用される','3000万円特別控除と軽減税率特例は重複して適用できないのでどちらか一方を選択しなければならない'],ans:1,exp:'居住用財産の3000万円特別控除（租税特別措置法35条）を適用すると課税譲渡所得＝1250万円－3000万円＝△1750万円となり控除しきれるため税金はかかりません。なお3000万円特別控除と10年超保有の軽減税率特例（租税特別措置法31条の3）は重複して適用できます（まず3000万円控除後の残額に軽減税率を適用）。本問では控除後の課税所得がゼロ以下なので軽減税率を考える必要もありません。',"kaisetsu":{"topic": "譲渡所得：分離課税・長期は20%・3,000万円控除は3年に1回", "basis": {"text": "土地・建物の譲渡所得は分離課税（申告分離課税）。長期（5年超）の税率は合計20%（所得税15%+住民税5%）。短期（5年以下）は39%（所得税30%+住民税9%）。3,000万円特別控除は前年・前々年に適用があれば使えません（3年に1回）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">譲渡所得のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税方式</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">分離課税</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">長期（5年超）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計20%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">短期（5年以下）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計39%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3,000万円控除</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年に1回の制限</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10822,unit:'t_kotei',level:3,field:'tax',text:'Aは自己の居住用土地（200m2）及び建物（新築から2年経過・3階建て中高層耐火住宅）を所有している。固定資産税評価額は土地3000万円・建物1500万円である。この場合に関する記述として地方税法の規定によれば正しいものはどれか。',opts:['住宅用地（200m2以下の小規模住宅用地）の固定資産税の課税標準は固定資産税評価額の6分の1に軽減される','住宅用地（200m2以下の小規模住宅用地）の固定資産税の課税標準は固定資産税評価額の3分の1に軽減される','新築から2年経過の3階建て中高層耐火住宅は新築住宅の税額軽減特例の対象から既に外れている','固定資産税の標準税率は1.7%である'],ans:0,exp:'小規模住宅用地（住宅1戸につき200m2以下の部分）の固定資産税の課税標準は固定資産税評価額の1/6に軽減されます（地方税法349条の3の2）。200m2超の一般住宅用地は1/3です。新築住宅の固定資産税軽減は120m2相当部分について3年間（3階建て以上の中高層耐火・準耐火住宅は5年間）税額が1/2に軽減されます（地方税法附則15条の6）。本問の建物は新築から2年経過であり5年間の軽減期間内なので特例が適用されます。固定資産税の標準税率は1.4%です。',"kaisetsu":{"topic": "固定資産税：市町村が課す地方税・賦課期日は1月1日・評価替えは3年ごと", "basis": {"text": "固定資産税は市町村（東京23区は都）が課す地方税です（地方税法343条）。賦課期日は毎年1月1日。評価替えは3年ごと（基準年度）。住宅用地の特例：200㎡以下は課税標準1/6、超過部分は1/3。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">固定資産税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市町村（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賦課期日</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">評価替え</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年ごと</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅用地（200㎡以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税標準1/6</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10823,unit:'t_shutoku',level:3,field:'tax',text:'Aは新築の一戸建て住宅（延べ面積120m2・自己居住用）を購入した。固定資産税評価額は建物1200万円・土地2000万円である。住宅取得後、不動産取得税がどのくらいかかるか確認している。この場合に関する記述として地方税法の規定（当分の間の特例を含む）によれば正しいものはどれか。',opts:['建物の不動産取得税は1200万円×4%＝48万円である（特例なし）','新築住宅（延べ面積50m2以上240m2以下）の建物の不動産取得税は課税標準から1200万円を控除した額×3%となり、建物評価額1200万円の場合は(1200万円－1200万円)×3%＝0円となる','土地の不動産取得税は2000万円×3%＝60万円であり、住宅用地の特例は関係ない','不動産取得税は取得後すぐに自分で税務署に申告して納付する'],ans:1,exp:'新築住宅（延べ面積50m2以上240m2以下の場合）の建物の不動産取得税は課税標準から1200万円を控除します（地方税法73条の14第1項）。1200万円－1200万円＝0円×3%＝0円となりこの場合は建物の不動産取得税はかかりません。土地については課税標準が固定資産税評価額の1/2に軽減され、さらに一定の控除が適用されます。不動産取得税は都道府県が賦課し納税通知書で納付する普通徴収方式です（申告納付ではありません）。',"kaisetsu":{"topic": "不動産取得税：都道府県が課す地方税・相続は非課税・1回だけ課税", "basis": {"text": "不動産取得税は都道府県が課す地方税です（地方税法73条の2）。相続・法人の合併等による取得は非課税。一度の取得に一度だけ課税される（固定資産税と異なり毎年ではない）。標準税率は4%（住宅・土地は3%の軽減あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産取得税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税の頻度</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取得時に1回のみ</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">標準税率</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4%（住宅・土地は3%）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10824,unit:'t_toroku',level:3,field:'tax',text:'AはB銀行から住宅ローン（借入額3000万円）を組んで、自己居住用の新築住宅（延べ面積70m2・一定の耐震基準を満たす）を取得した。この住宅の所有権保存登記と抵当権設定登記を行う場合の登録免許税について正しいものはどれか。',opts:['所有権保存登記の本則税率は0.4%であり、軽減を受けられる要件を満たす場合は0.15%になる','抵当権設定登記の課税標準は住宅の固定資産税評価額であり、本則税率0.4%が適用される','所有権保存登記の軽減税率は0.1%である','住宅ローンの抵当権設定登記には登録免許税はかからない'],ans:0,exp:'所有権保存登記の本則税率は0.4%（登録免許税法別表1）。一定要件（床面積50m2以上・取得後1年以内・自己居住用・一定の耐震基準等）を満たす場合は0.15%に軽減されます（租税特別措置法72条）。抵当権設定登記の課税標準は「債権金額」（ローン金額3000万円）であり、本則税率0.4%、一定要件を満たす住宅ローンは0.1%に軽減されます（租税特別措置法75条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10825,unit:'r_fuhoko',level:3,field:'rights',text:'Aの被用者BはAの業務執行中に過失により通行人Cに怪我を負わせた。Cの損害は入院費・治療費・慰謝料合計500万円である。この場合に関する記述として民法の規定及び判例によれば正しいものはどれか。',opts:['使用者Aは無過失であれば一切の責任を負わない','AはBの選任・監督に相当の注意をしたことを証明すれば免責されるが、実際には裁判所がこの免責をほぼ認めないため、Aは使用者責任（民法715条）として500万円の損害賠償責任を負う可能性が高い','CはBとAのどちらかにしか損害賠償請求できず、最初に請求した者が責任を負う','AがCに500万円を支払った後、AはBに対して全額の求償ができない'],ans:1,exp:'使用者Aは被用者Bの選任・監督について相当の注意をしたこと、または相当の注意をしても損害が生じたことを証明すれば免責されます（民法715条1項ただし書）。しかし判例上この免責はほぼ認められません。CはAとBの両方（連帯して）に損害賠償請求できます（不真正連帯債務）。AがCに500万円を支払った後、AはBに対して信義則上相当と認められる額の求償ができます（民法715条3項）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "使用者責任（民法715条1項）において使用者は選任・監督に相当の注意をしたことを証明すれば免責されますが（同条1項ただし書）、実際の裁判ではこの免責がほぼ認められないため、使用者は実質的に無過失責任に近い責任を負います。また使用者がBに支払った後、Bへの求償は信義則上制限されます（判例）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "使用者Aは無過失であれば一切の責任を負わない", "reason": "使用者責任は使用者が「選任・監督に相当の注意をした」ことを証明しなければ免責されません（民法715条1項ただし書）。単に無過失というだけでは免責されません。", "caution": ""}, {"label": "CはBとAのどちらかにしか請求できず最初に請求した者が責任を負う", "reason": "CはAに対して直接不法行為責任（民法709条）を、Aの使用者Bに対して使用者責任（民法715条）を主張できます。どちらかにしか請求できないという制限はありません（連帯責任）。", "caution": ""}, {"label": "AがCに500万円を支払った後AはBに対して全額の求償ができない", "reason": "使用者Aが被害者に支払った後、被用者Bへの求償は認められますが、信義則上一定割合に制限されます（判例）。「全額求償できない」という点は判例と一致しますが、設問の正解は選択肢2です。", "caution": ""}], "summary": {"head": ["使用者責任と求償", "内容"], "rows": [["使用者の責任", "選任・監督に相当の注意を証明で免責（実務上ほぼ不認定）"], ["使用者→被用者の求償", "認められるが信義則上制限あり（判例）"], ["被害者の請求先", "加害被用者・使用者のどちらにでも請求可"]]}}},
  {id:10826,unit:'r_ishi',level:3,field:'rights',text:'未成年者A（18歳・高校生）は法定代理人（親）の同意なしに、B所有の中古バイクを20万円で購入する契約をBと締結した。Aの親CはAのバイク購入を知らなかったが、その後Aがバイクで事故を起こしたため追認も取消しもしないままひとまず保険の対応をした。後日CはAB間の売買契約を取り消したいと考えている。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['Aは18歳であり2022年4月施行の改正民法により成年であるため、法定代理人の同意なくバイクを購入しても取り消せない','未成年者Aが法定代理人の同意なく行った契約は取り消すことができ、取消権者はAまたは法定代理人Cである','BがAに対して1か月以上の催告期間を設けて取消しか追認かを問い合わせた場合、期間内に確答がなければ追認したものとみなされる','CがAのために事故保険の対応をしたことは追認行為に当たり、取消権が消滅する'],ans:0,exp:'2022年4月施行の改正民法により成年年齢が18歳に引き下げられました（民法4条）。Aは18歳で成年のため、法定代理人の同意なくバイクを購入しても未成年者取消権は適用されません。成年者Aが行った売買契約は有効であり、CによるAへの取消権はありません（Aが詐欺・強迫を受けた等の別の事情がない限り）。',"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "意思表示の瑕疵には詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失の第三者は保護）・通謀虚偽表示（無効・善意の第三者は保護）があります。", "example": ""}, "reason": {"text": "2022年4月施行の改正民法で成年年齢が20歳から18歳に引き下げられました。18歳は成年であるため、法定代理人の同意なく契約しても取り消せません。成年年齢の改正は宅建試験の重要論点です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "未成年者Aが法定代理人の同意なく行った契約は取り消すことができ、取消権者はAまたは法定代理人Cである", "reason": "2022年4月以降、18歳は成年であるため未成年者の規定が適用されません。Aは成年として扱われ、取り消せません。", "caution": "2022年4月以降の問題では18歳＝成年として扱います。"}, {"label": "BがAに対して1か月以上の催告期間を設けて取消しか追認かを問い合わせた場合、期間内に確答がなければ追認したものとみなされる", "reason": "この催告の規定（民法20条）は制限行為能力者に適用されます。Aが成年であればこの規定は適用されません。", "caution": ""}, {"label": "CがAのために事故保険の対応をしたことは追認行為に当たり、取消権が消滅する", "reason": "Aが成年であれば取消権自体が発生しないため、追認・取消権消滅の問題は生じません。", "caution": ""}], "summary": {"head": ["年齢", "成年区分", "法定代理人の同意"], "rows": [["18歳未満", "未成年者（改正後も）", "必要"], ["18歳以上", "成年（2022年4月改正）", "不要"], ["20歳以上", "成年（改正前から）", "不要"]]}}},
  {id:10827,unit:'l_hosho',level:3,field:'law',text:'宅建業者Aは、宅地建物取引業保証協会（以下「保証協会」という）の社員である。AはBとの間で宅地の売買契約を締結し、Bから手付金200万円を受領したが、その後Aが倒産し手付金をBに返還できなくなった。Bは保証協会に対して弁済業務保証金からの還付を求めようとしている。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['BはAの社員資格停止中に取引した場合でも保証協会から還付を受けられない','BはAと宅建業に関する取引をした者であり宅建業者でないので、弁済業務保証金から還付請求できる','BがAから受け取るべき金銭の額は、Aが供託していた弁済業務保証金分担金の額（主たる事務所60万円等）が上限となる','Bが還付請求できる金額の上限は、Aが保証協会の社員でなかったとした場合に供託すべき営業保証金の額（主たる事務所1000万円等）が上限となる'],ans:3,exp:'弁済業務保証金からの還付請求は「宅建業者でない者」で当該宅建業者と「宅建業に関する取引をした者」が対象です（宅建業法64条の8）。還付を受けることができる限度額は、その宅建業者が保証協会の社員でなかったとした場合に供託すべき営業保証金の額（主たる事務所1000万円・従たる事務所500万円等の合計）が上限です（同条2項）。分担金の額（60万円等）は上限ではありません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "弁済業務保証金から還付できる上限は当該業者が保証協会の社員でなかった場合に供託すべき営業保証金の額です（宅建業法64条の8第1項）。主たる事務所のみなら1000万円が上限で、分担金（60万円）が上限ではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "BはAの社員資格停止中に取引した場合でも保証協会から還付を受けられない", "reason": "社員資格の停止の有無にかかわらず、宅建業者以外の者がAとの取引で損害を受けた場合は還付を受けられます（宅建業法64条の8第1項）。", "caution": ""}, {"label": "BはAと宅建業に関する取引をした者であり宅建業者でないので弁済業務保証金から還付請求できる", "reason": "Bは宅建業者でなく、Aとの宅建業に関する取引で損害を受けているため還付請求できます（宅建業法64条の8第1項）。設問の正解は選択肢4です。", "caution": ""}, {"label": "BがAから受け取るべき金銭の額はAが供託していた弁済業務保証金分担金の額が上限となる", "reason": "還付上限は分担金（60万円）ではなく、営業保証金相当額（1000万円等）が上限です（宅建業法64条の8第1項）。", "caution": "分担金（60万円）と還付上限（営業保証金相当額1000万円等）を混同しないこと。"}], "summary": {"head": ["弁済業務保証金の還付（設問の場合）", "内容"], "rows": [["還付可否", "Bは宅建業者でないため還付請求可"], ["還付上限", "Aの営業保証金相当額（主たる事務所のみ：1000万円）"], ["分担金との関係", "分担金60万円≠還付上限（保証協会が差額を補填）"]]}}},
  {id:10828,unit:'k_toshi',level:3,field:'limit',text:'都市計画区域内に土地を所有するAは、土地（面積5000m2）に事務所兼倉庫を建設するための開発行為を計画している。この土地は市街化区域内にある。この場合に関する記述として都市計画法の規定によれば正しいものはどれか。',opts:['市街化区域内の開発行為は面積にかかわらずすべて開発許可が不要である','市街化区域内では原則として面積1000m2以上の開発行為に都道府県知事（または政令市長）の開発許可が必要であり、5000m2の開発行為は許可が必要','市街化区域内の開発行為は農業・林業・漁業用の建築物のための開発行為と同様に常に許可不要','市街化区域内の開発行為では環境大臣の許可が必要'],ans:1,exp:'市街化区域内での開発行為は原則として1000m2以上で都道府県知事の開発許可が必要です（都市計画法29条1項）。5000m2はこの面積要件を超えているため開発許可が必要です。農業・林業・漁業用の建築物のための開発行為は都市計画区域全体で許可不要ですが、それ以外は基本的に許可が必要です。',"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域での1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は市街化調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "市街化区域内では面積1000㎡以上の開発行為には都道府県知事（または政令市長等）の開発許可が必要です（都市計画法29条1項・施行令19条）。5000㎡は1000㎡以上のため許可が必要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化する区域</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可基準</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "市街化区域内の開発行為は面積にかかわらずすべて開発許可が不要である", "reason": "1000㎡以上の開発行為には許可が必要です（都市計画法29条1項・施行令19条）。「すべて不要」は誤りです。", "caution": "市街化区域：1000㎡以上の開発行為→許可必要（都市計画法29条1項・施行令19条）。"}, {"label": "市街化区域内の開発行為は農業・林業・漁業用の建築物のための開発行為と同様に常に許可不要", "reason": "農林漁業用施設は規模・区域にかかわらず許可不要ですが（都市計画法29条1項2号）、一般の市街化区域での開発行為は1000㎡以上で許可が必要です（同条1項）。「常に許可不要」は誤りです。", "caution": ""}, {"label": "市街化区域内の開発行為では環境大臣の許可が必要", "reason": "開発許可は都道府県知事（または政令市長等）に申請します（都市計画法29条）。環境大臣ではありません。", "caution": ""}], "summary": {"head": ["市街化区域の開発許可（都市計画法29条1項・施行令19条）", "内容"], "rows": [["1000㎡未満", "許可不要"], ["1000㎡以上", "許可必要"], ["三大都市圏特定区域", "500㎡以上で許可必要"], ["例外", "農林漁業用施設等は規模にかかわらず不要"]]}}},
  {id:10829,unit:'r_tanpo',level:3,field:'rights',text:'AはB銀行に対して2000万円の債務を負い、A所有の甲マンション（時価3000万円）に第一順位の抵当権を設定した。その後AはC信用金庫に対して1000万円の債務を負い、同じ甲マンションに第二順位の抵当権を設定した。AがB銀行の債務のみを完済して抵当権の抹消登記を申請しようとする場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['B銀行の抵当権抹消後、C信用金庫の抵当権は自動的に第一順位に昇格する','B銀行の抵当権抹消によりその順位は法定代位によりA本人に帰属するため、Aは事実上一番抵当権者と同じ地位を取得する','B銀行への完済と抵当権抹消後も、C信用金庫の抵当権は第二順位のまま変化しない','B銀行の抵当権が抹消されると、C信用金庫は自動的にB銀行の残余債権を引き継ぐ'],ans:0,exp:'B銀行の第一順位抵当権が抹消されると、C信用金庫の第二順位抵当権が繰り上がって第一順位になります。抵当権の順位は相対的なものであり、上位の権利が消滅すれば下位の権利が自動的に順位上昇します。Aが法定代位を取得するという考えは本問の状況では当てはまりません。',"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権です（民法369条）。質権は占有の移転が必要です。先取特権は法律上当然に成立する法定担保物権です。", "example": ""}, "reason": {"text": "第一順位の抵当権が弁済等で消滅すると、後順位の抵当権は順位が繰り上がります（順位の昇進）。これは抵当権の順位が後順位の権利者に有利に変化する自動的な効果です（民法374条等）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・非占有</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・占有</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "AはB銀行の抵当権抹消後に一番抵当権者と同じ地位を取得する", "reason": "AはBへの完済で抵当権設定者の地位を取り戻しますが、B銀行の順位を法定代位で引き継ぐわけではありません（民法499条以下の法定代位は保証人等の場合）。", "caution": ""}, {"label": "C信用金庫の抵当権は第二順位のまま変化しない", "reason": "第一順位のB銀行の抵当権が抹消されると、C信用金庫は第一順位に自動的に昇格します（順位の昇進）。", "caution": "第一順位消滅→後順位が自動的に昇格（順位の昇進）。"}, {"label": "C信用金庫はB銀行の残余債権を引き継ぐ", "reason": "C信用金庫はBの債権を引き継ぐのではなく、単に抵当権の順位が上がるだけです。", "caution": ""}], "summary": {"head": ["順位の昇進", "内容"], "rows": [["意味", "上位の抵当権消滅→後順位が繰り上がる"], ["根拠", "民法374条（順位変更）・民法177条等の解釈"], ["効果", "C信用金庫の抵当権が第一順位に自動昇格"], ["Aへの影響", "B銀行への完済義務・抵当権抹消申請義務"]]}}},
  {id:10830,unit:'r_jiko',level:3,field:'rights',text:'AはBに対して2020年4月1日に100万円を貸し付け（利息なし・期限の定めなし）、翌日から随時弁済を求めることができる状態にあった。Aは2022年3月31日にBに対して内容証明郵便にて100万円の返済を催告した。その後Aは2022年10月1日に訴訟を提起した。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['催告（内容証明郵便）だけで時効が更新（旧：中断）されるので、2022年3月31日から新たに時効が進行する','催告により時効の完成が6か月間猶予されるが、この効力は催告から6か月以内に訴訟提起等をしなければ消滅する。2022年3月31日から6か月以内の2022年9月30日までに訴訟提起が必要であり、10月1日の提起は間に合っていない','期限の定めのない消費貸借は貸付けの翌日から時効が進行し5年（民法166条1項1号）で完成する可能性がある','催告は書面でなければ効力が生じない'],ans:2,exp:'期限の定めのない消費貸借は貸付日の翌日から権利行使できる状態（民法591条1項）なので主観的起算点からの消滅時効（5年）が問題となります。催告から6か月以内に裁判上の請求等をすれば時効の完成猶予効が延長されますが（民法150条）、催告それ自体は時効を更新しません。また訴訟提起の日は10月1日で催告3月31日から6か月は9月30日で、時効完成猶予の期間内に訴訟を提起できているかが問題です（催告後6か月以内に訴訟提起が必要）。',"kaisetsu":{"topic": "消滅時効：知った時から5年または行使可能時から10年", "basis": {"text": "一般の債権の消滅時効は「権利行使できると知った時から5年」または「権利行使できる時から10年」のいずれか早い方で完成します（民法166条1項）。時効は援用して初めて効力が発生します（民法145条）。", "example": ""}, "reason": {"text": "期限の定めのない消費貸借は貸付けの翌日から時効が進行します（民法166条）。2020年改正後の消滅時効は「権利を行使できると知った時から5年」または「権利を行使できる時から10年」の短い方が適用されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">時効期間</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人の生命・身体への損害</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年または20年</text></svg>", "choices": [{"label": "催告（内容証明郵便）だけで時効が更新される", "reason": "催告は時効の完成猶予のみであり、更新はしません（民法150条1項）。6か月以内に訴訟提起等が必要です。", "caution": "催告＝完成猶予（6か月）のみ。更新のためには追加の手続きが必要。"}, {"label": "2022年9月30日までに訴訟提起が必要", "reason": "催告から6か月以内の訴訟提起が必要ですが（民法150条）、設問の時効の完成時期の計算も重要です。2020年4月2日から5年後の2025年4月2日が時効完成の候補です。", "caution": ""}, {"label": "催告は書面でなければ効力が生じない", "reason": "催告に書面は要求されていません（民法150条）。ただし証明のため内容証明郵便等を利用するのが実務です。", "caution": ""}], "summary": {"head": ["催告の効果", "内容"], "rows": [["効果", "完成猶予（6か月間）"], ["更新", "なし（別途訴訟提起等が必要）"], ["6か月以内の措置", "訴訟提起・差押え等をしなければ猶予効力消滅"], ["書面要件", "なし（口頭でも可・ただし証明困難）"]]}}},
  {id:10831,unit:'l_takkenshi',level:3,field:'law',text:'宅建士Aは、甲県知事の登録を受けており、甲県内の宅建業者Bに勤務している。Aは業務上で重大な過失により取引の相手方に損害を与えたとして、甲県知事から1年間の事務禁止処分を受けた。また、Aはその後に転職して乙県内の宅建業者Cに勤務することになった。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['事務禁止処分を受けたAの宅建士証は、処分期間中甲県知事に提出しなければならない','事務禁止処分を受けたAは宅建士証を甲県知事に提出後、乙県内の宅建業者Cに転職する際に宅建士証の返還を受けて乙県知事に登録移転申請ができる','Aが乙県に登録移転するには、改めて宅建士試験を受け直す必要がある','事務禁止処分中のAは宅建業者Bを退職すれば処分の効力もなくなる'],ans:0,exp:'事務禁止処分を受けた宅建士は、処分の期間中、登録している都道府県知事（甲県知事）に宅建士証を提出しなければなりません（宅建業法22条の2第7項）。事務禁止処分中に登録移転を申請することはできません（宅建業法19条の2ただし書）。退職しても処分の効力は変わりません。',"kaisetsu":{"topic": "専任の宅建士：5人に1人以上・兼任不可・不足時は2週間以内に補充", "basis": {"text": "事務所には業務従事者5人に1人以上の専任宅建士が必要です（宅建業法31条の3）。専任宅建士は1社専属で複数業者の兼任は不可。不足時は2週間以内に補充が必要です。", "example": ""}, "reason": {"text": "事務禁止処分を受けた宅建士は、処分期間中は宅建士証を登録している都道府県知事（甲県知事）に提出しなければなりません（宅建業法22条の2第5項）。また事務禁止処分中は登録移転の申請ができません（宅建業法19条の2）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">専任宅建士のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">設置基準</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5人に1人以上（主従同じ）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">兼任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可（1社専属）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不足補充</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間以内</text></svg>", "choices": [{"label": "事務禁止処分を受けたAは宅建士証を甲県知事に提出後乙県知事に登録移転申請ができる", "reason": "事務禁止処分中は登録移転の申請ができません（宅建業法19条の2）。処分期間終了後であれば移転申請ができます。", "caution": "事務禁止処分中：登録移転申請不可（宅建業法19条の2）。"}, {"label": "Aが乙県に登録移転するには改めて宅建士試験を受け直す必要がある", "reason": "登録移転に試験の再受験は不要です（宅建業法19条の2）。", "caution": ""}, {"label": "事務禁止処分中のAは宅建業者Bを退職すれば処分の効力もなくなる", "reason": "処分の効力は退職によって消滅しません（宅建業法68条1項）。処分期間中は事務ができません。", "caution": ""}], "summary": {"head": ["事務禁止処分中の制限", "内容"], "rows": [["宅建士としての事務", "禁止"], ["宅建士証", "知事に提出義務（宅建業法22条の2第5項）"], ["登録移転", "申請不可"], ["処分の効力", "退職等で消滅しない"]]}}},
  {id:10832,unit:'l_jusetsu',level:3,field:'law',text:'宅建業者Aは、建物（戸建住宅・新築）の売買を媒介した。この建物はH工務店が建築したものであり、住宅品質確保法（品確法）に基づく住宅性能評価書（設計住宅性能評価書・建設住宅性能評価書）が交付されている。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['住宅性能評価書が交付されていても重要事項説明書への記載は任意である','住宅性能評価を受けた旨は35条書面（重要事項説明書）に記載しなければならない事項の一つである','住宅性能評価書の評価内容を重要事項説明書に全て転記しなければならない','設計住宅性能評価書が交付されていれば建設住宅性能評価書の取得は不要であり、その旨を説明すればよい'],ans:1,exp:'住宅性能評価を受けた新築住宅の売買・交換の場合、住宅性能評価を受けた旨（設計住宅性能評価書・建設住宅性能評価書の別）は重要事項説明書の記載事項です（宅建業法35条1項14号・施行規則16条の4の3第6号）。評価内容の全転記は不要ですが、住宅性能評価を受けている旨の記載は必須です。',"kaisetsu":{"topic": "重要事項説明：宅建士が説明・売主への交付は不要・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主への交付義務はありません。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能です。", "example": ""}, "reason": {"text": "住宅性能評価を受けた新築住宅の売買では、評価を受けた旨を35条書面に記載しなければなりません（宅建業法35条1項14号・施行規則16条の4の3第1号）。評価内容の全転記は不要ですが、評価を受けた事実の記載は義務です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "住宅性能評価書が交付されていても重要事項説明書への記載は任意", "reason": "住宅性能評価を受けた旨の記載は義務です（宅建業法35条1項14号等）。任意ではありません。", "caution": "住宅性能評価を受けた旨：35条書面への記載義務（宅建業法35条1項14号等）。"}, {"label": "住宅性能評価書の評価内容を重要事項説明書に全て転記しなければならない", "reason": "「評価を受けた旨」の記載で足ります（宅建業法35条1項14号等）。全転記は不要です。", "caution": ""}, {"label": "設計住宅性能評価書が交付されていれば建設住宅性能評価書は不要", "reason": "設問は重要事項説明の記載に関する問題であり、どちらの評価書が交付されているかは別問題です。交付されている評価書の種類と受けた旨を記載します。", "caution": ""}], "summary": {"head": ["住宅性能評価と重要事項説明", "内容"], "rows": [["記載義務", "住宅性能評価を受けた旨（宅建業法35条1項14号等）"], ["記載内容", "「設計・建設住宅性能評価書が交付されている旨」"], ["全転記", "不要"], ["対象", "新築住宅の売買（中古にも適用あり）"]]}}},
  {id:10833,unit:'k_kenchiku',level:3,field:'limit',text:'Aは商業地域内（建ぺい率80%・容積率600%）に事務所ビルを建築しようとしている。敷地面積は500m2で、前面道路幅員は6m、敷地は特定行政庁指定の防火地域内にある。建築物は耐火建築物とする予定である。この場合の建ぺい率の最高限度として建築基準法の規定によれば正しいものはどれか。',opts:['80%','建ぺい率の制限が適用されない（防火地域内の耐火建築物は建ぺい率が10%加算。指定建ぺい率80%の場合は90%となる）','100%（指定建ぺい率80%に対し耐火建築物10%加算で90%）','指定建ぺい率80%そのままで変化なし'],ans:1,exp:'防火地域内の耐火建築物は建ぺい率が10%加算されます（建築基準法53条3項1号）。指定建ぺい率80%の場合は80%+10%=90%となります。ただし指定建ぺい率が80%の地域で防火地域内の耐火建築物の場合は制限なし（100%）となる場合もありますが、指定建ぺい率80%自体が耐火要件とセットになっている場合に限られます（建築基準法53条6項2号）。本問は指定建ぺい率80%の商業地域で防火地域内の耐火建築物なので建ぺい率制限が適用されません。',"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・道路斜線・用途制限", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。用途地域ごとに建築物の制限があります。", "example": ""}, "reason": {"text": "商業地域で指定建ぺい率80%の場合、防火地域内の耐火建築物は10%加算されて90%となります（建築基準法53条3項1号）。さらに指定建ぺい率が80%の場合で防火地域内の耐火建築物という条件が加わると、建ぺい率の制限が適用されなくなる（100%）場合もありますが（同条6項1号）、設問の正解は「10%加算で90%」です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">第1種低層</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">学校は建築可</text></svg>", "choices": [{"label": "80%", "reason": "防火地域内の耐火建築物は10%加算されるため、80%＋10%＝90%が上限です（建築基準法53条3項1号）。「80%そのまま」は誤りです。", "caution": "防火地域内耐火建築物：建ぺい率10%加算（建築基準法53条3項1号）。"}, {"label": "100%（指定建ぺい率80%に対し耐火建築物10%加算で90%）", "reason": "計算式の説明が矛盾しています。80%＋10%＝90%であり100%ではありません。ただし指定建ぺい率が80%の防火地域内の耐火建築物は建ぺい率制限が適用されない（100%）場合もあります（建築基準法53条6項1号）。", "caution": ""}, {"label": "指定建ぺい率80%そのままで変化なし", "reason": "防火地域内の耐火建築物は10%加算されます（建築基準法53条3項1号）。「変化なし」は誤りです。", "caution": ""}], "summary": {"head": ["商業地域・指定建ぺい率80%の場合", "建ぺい率"], "rows": [["指定建ぺい率", "80%"], ["防火地域内耐火建築物の加算", "＋10%"], ["適用される建ぺい率", "90%（または建ぺい率制限なし：建築基準法53条6項1号参照）"], ["角地加算も合わせると", "100%（実質制限なし）"]]}}},
  {id:10834,unit:'t_chika',level:3,field:'tax',text:'Aは不動産鑑定士に甲土地の不動産鑑定評価を依頼した。不動産鑑定士は取引事例比較法・収益還元法・原価法の3方式を用いて評価を行い、最終的な鑑定評価額を決定しようとしている。この場合に関する記述として不動産鑑定評価基準の定めによれば正しいものはどれか。',opts:['収益還元法は自己居住用住宅にも積極的に適用すべき手法とされている','取引事例比較法では、取引事例を収集・選択し、事情補正・時点修正・地域要因比較・個別的要因比較を行って比準価格を求める','原価法は必ず再調達原価から減価修正をしない方法で計算しなければならない','3方式のうち最も高い価格が鑑定評価額として採用される'],ans:1,exp:'取引事例比較法では、多数の取引事例を収集・選択し、①事情補正（正常でない取引の補正）②時点修正（時点の違いを補正）③地域要因比較④個別的要因比較の手順で比準価格を求めます（不動産鑑定評価基準）。収益還元法は主に賃貸等の収益物件に適用しますが自己居住用住宅にも適用可能です（むしろ積極的に適用すべきとされています）。原価法は再調達原価から減価修正を行います。3方式の結果を関連付けて最終評価額を決定します。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10835,unit:'r_souzoku',level:3,field:'rights',text:'Aには相続人として配偶者B、長男C、次男Dがいる。Aは生前に次男Dに対して生計の資本として2000万円を贈与していた。Aが死亡した時の相続財産は6000万円であった（贈与は相続財産に含まれていない）。遺産分割において特別受益の持ち戻しを計算する場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['特別受益の持ち戻しをしない場合、BCD各自の相続分はB3000万円・C1500万円・D1500万円となる','特別受益の持ち戻しをする場合、みなし相続財産は6000万円＋2000万円＝8000万円となり、B4000万円・C2000万円の各相続分が算出され、Dは2000万円の贈与があるため相続分2000万円から贈与分2000万円を差し引き0円となる','Dへの贈与額2000万円は相続財産6000万円より少ないので特別受益の持ち戻しは不要','特別受益の持ち戻しにより相続分が0円以下になった場合、Dは既に受け取った贈与分を返還しなければならない'],ans:1,exp:'特別受益の持ち戻し計算（民法903条）では、相続財産6000万円＋特別受益2000万円＝みなし相続財産8000万円を基礎に相続分を計算します。B（配偶者）：8000万円×1/2＝4000万円、CとD（子）：各8000万円×1/4＝各2000万円。DはすでにAから2000万円を受け取っているので相続分2000万円から差し引き0円となります。Dの相続分がマイナスになっても返還義務は生じません（民法903条2項）。',"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2", "basis": {"text": "配偶者と子の場合は各1/2（民法900条）。相続放棄は3か月以内に家庭裁判所へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2です（民法1042条）。遺産分割協議は全員合意が必要です。", "example": ""}, "reason": {"text": "特別受益の持ち戻し計算では、相続財産に特別受益額を加えたみなし相続財産を算出し、そこから各相続人の具体的相続分を計算します（民法903条1項）。特別受益を受けた相続人は、その分だけ相続分から差し引かれます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続の主要ポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子の相続分</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は法定相続分の1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割協議</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "特別受益の持ち戻しをしない場合の計算は誤り", "reason": "持ち戻しをしない場合はB3000万円・C1500万円・D1500万円となります（正しい）。設問は持ち戻しをする場合の計算が正解です。", "caution": ""}, {"label": "Dへの贈与額2000万円は持ち戻し不要", "reason": "2000万円の贈与は生計の資本として特別受益に該当し、持ち戻しが必要です（民法903条1項）。", "caution": ""}, {"label": "相続分が0円以下になった場合返還が必要", "reason": "特別受益が相続分を超えた場合でも、超過分の返還義務はありません（民法903条2項）。相続分が0円となるだけです。", "caution": "超過分の返還は不要（民法903条2項）。"}], "summary": {"head": ["特別受益の持ち戻し計算", "内容"], "rows": [["みなし相続財産", "相続財産6000万円＋贈与2000万円＝8000万円"], ["Bの相続分", "8000万円×1/2＝4000万円"], ["C・Dの相続分", "8000万円×1/4＝各2000万円"], ["Dの取得分", "相続分2000万円－贈与2000万円＝0円（返還不要）"]]}}},
  {id:10836,unit:'l_cooling',level:3,field:'law',text:'宅建業者A（自ら売主）は買主B（宅建業者でない）との間で宅地の売買契約を締結した。代金は3000万円で、Bは手付金として300万円を支払った。この宅地は未完成物件であった。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['手付金300万円（代金の10%）を受領したので保全措置が必要','未完成物件の手付金保全措置は代金の5%超または1000万円超が基準であり、300万円（代金の10%）は5%（150万円）を超えているので保全措置が必要','未完成物件の手付金保全措置は代金の10%超が基準であり300万円は10%丁度なので保全措置は不要','保全措置が必要でも手付金を受け取る前に保全措置を講じる必要はない'],ans:1,exp:'未完成物件の手付金等の保全措置は、手付金等が代金の5%を超えるまたは1000万円を超える場合に必要です（宅建業法41条1項）。代金3000万円の5%は150万円であり、手付金300万円は150万円を超えているため保全措置が必要です。また保全措置は手付金等を受領する前に講じなければなりません（同条2項）。',"kaisetsu":{"topic": "クーリングオフ：告知日から8日以内・書面で・事務所では不可・全額返還", "basis": {"text": "クーリングオフは告知を受けた日から8日以内に書面で行います（宅建業法37条の2）。事務所・モデルルーム等での申込みはクーリングオフ不可。解除後業者は全額返還（費用控除不可）。", "example": ""}, "reason": {"text": "未完成物件の保全措置基準は代金の5%超または1000万円超です（宅建業法41条1項）。手付金300万円は代金3000万円の10%で、5%（150万円）を超えているため保全措置が必要です。受領前に保全措置を講じなければなりません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">クーリングオフのポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">告知日から8日以内</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">方法</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面（発信主義）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所での申込み</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">クーリングオフ不可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除後</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全額返還（費用控除不可）</text></svg>", "choices": [{"label": "手付金300万円（代金の10%）を受領したので保全措置が必要", "reason": "10%なので保全措置が必要というのは結論として正しいですが、理由が「10%だから」ではなく「5%超だから」です。設問の正解は選択肢2（5%超の基準を明示した記述）です。", "caution": "未完成物件の基準：5%超。300万円は10%（5%超）→保全措置必要。"}, {"label": "未完成物件の手付金保全措置は代金の10%超が基準であり300万円は10%丁度なので保全措置は不要", "reason": "未完成物件の基準は10%超ではなく5%超です（宅建業法41条1項）。また300万円は5%（150万円）を超えており保全措置が必要です。", "caution": "未完成物件：5%超（10%超ではない）（宅建業法41条1項）。"}, {"label": "保全措置が必要でも手付金を受け取る前に保全措置を講じる必要はない", "reason": "保全措置は手付金等を受領する前に講じなければなりません（宅建業法41条1項）。受領後では遅すぎます。", "caution": ""}], "summary": {"head": ["設問の保全措置計算", "内容"], "rows": [["代金", "3000万円"], ["5%の額", "150万円"], ["手付金", "300万円（5%超→保全措置必要）"], ["措置の時期", "受領前に講じる必要あり"]]}}},
  {id:10837,unit:'r_chinshaku',level:3,field:'rights',text:'AはBから事務所用建物を月額30万円で賃借している。賃貸借契約には期間の定めがなく、契約から5年が経過している。近年、周辺の類似物件の賃料相場が上昇しており、Bは賃料をAに対して月額40万円に増額するよう求めてきた。Aはこの増額に応じられないとしている。この場合に関する記述として借地借家法の規定によれば正しいものはどれか。',opts:['賃料の増額請求があった場合、Aはこれを拒否することができず、直ちに月額40万円を支払わなければならない','増額請求があった場合、AとBが合意に至らなければ裁判所が相当賃料額を決定するまでの間、Aは現行賃料または「相当と認める額」を支払えばよい','事務所用建物の賃貸借には借地借家法が適用されないので、賃料増額は全額即時に応じる必要がある','Bが増額請求をした翌月から自動的に新賃料が適用される'],ans:1,exp:'建物賃貸借（事務所用も適用対象）において増額請求があり当事者間で協議が調わない場合、増額の当否と相当賃料額は最終的に裁判所が決定します（借地借家法32条2項）。確定するまでの間、借主は自ら相当と認める額（現行賃料額以上）を支払えばよく、確定後に差額を利息付きで精算します。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "賃料増額請求があった場合、不服があれば賃借人は裁判所に相当賃料額の確定を求めることができます（借地借家法32条2項）。確定するまでの間は相当と認める額（現行賃料等）を支払えば足り、後に確定額との差額を追加精算します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "増額請求があった場合直ちに40万円を支払わなければならない", "reason": "増額請求に不服がある場合、裁判所に相当額の確定を求めることができます（借地借家法32条）。直ちに増額後の賃料を支払う義務はありません。", "caution": ""}, {"label": "事務所用建物の賃貸借には借地借家法が適用されない", "reason": "事務所・店舗等の非居住用建物にも借地借家法は適用されます（借地借家法1条）。居住用に限定されません。", "caution": "借地借家法は居住用・非居住用を問わず建物賃貸借に適用されます。"}, {"label": "増額請求の翌月から自動的に新賃料が適用される", "reason": "増額請求があっても相手方が同意しなければ自動的に新賃料にはなりません。裁判所の確定または合意が必要です（借地借家法32条）。", "caution": ""}], "summary": {"head": ["賃料増額請求の手続き", "内容"], "rows": [["増額請求", "賃貸人→賃借人", "借地借家法32条1項"], ["賃借人が不服", "裁判所に相当額確定を申請", "借地借家法32条2項"], ["確定前の支払い", "相当と認める額（現行賃料等）を支払えばよい"], ["確定後の精算", "差額＋年1割の利息を追加払い"]]}}},
  {id:10838,unit:'r_sorin',level:3,field:'rights',text:'AとBはそれぞれ隣接する土地を所有している。AとBの土地の境界に植えられた樹木の枝がBの土地に越境し、Bの建物に影や落ち葉による被害を生じさせている。また、同じ樹木の根もBの土地に越境しており、Bの庭の排水設備に影響を与えている。この場合に関する記述として民法の規定（2021年改正後）によれば正しいものはどれか。',opts:['BはAの樹木の越境した枝も根も自由に切除できる','BはAに対して越境した枝の切除を請求できるが、Aが相当の期間内に切除しない場合等は自らも切除できる。越境した根は直ちに自ら切除できる','Aの許可がなければBは越境した枝も根も切除できない','Bは枝・根の越境について損害賠償のみ請求できる'],ans:1,exp:'2021年民法改正後、越境した根はBが自ら切除できます（民法233条1項ただし書の反対解釈）。越境した枝についてはAに切除を請求でき（民法233条1項）、Aが相当期間内に切除しない場合・樹木の所有者が不明または所在不明の場合・急迫の事情がある場合は自ら切除できます（民法233条3項）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "2021年民法改正後、越境した枝は原則として竹木の所有者への催告が必要ですが、一定の場合は自ら切除できます（民法233条3項）。越境した根は直ちに自ら切除できます（同条4項）。設問ではAに催告後Aが切除しない場合等はBが自ら切除できます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "BはAの樹木の越境した枝も根も自由に切除できる", "reason": "枝は原則としてAへの催告が先です（民法233条1項・3項）。「自由に切除できる」は枝については誤りです。", "caution": "枝：催告が先（民法233条）。根：直ちに切除可（同条4項）。"}, {"label": "Aの許可がなければBは越境した枝も根も切除できない", "reason": "根は直ちに切除でき（民法233条4項）、枝も一定条件下で切除できます（同条3項）。Aの許可は必須ではありません。", "caution": ""}, {"label": "Bは枝・根の越境について損害賠償のみ請求できる", "reason": "切除請求・自ら切除（要件を満たす場合）・損害賠償等の複数の手段があります（民法233条）。「のみ」は誤りです。", "caution": ""}], "summary": {"head": ["設問の処理", "内容"], "rows": [["越境した枝", "AにBへの切除を請求→相当期間内に切除されない場合等はBが自ら切除可"], ["越境した根", "Bが直ちに自ら切除可（民法233条4項）"], ["費用", "切除費用はAに請求可"]]}}},
  {id:10839,unit:'l_kantoku',level:3,field:'law',text:'宅建業者A（国土交通大臣免許）の従業員Bが、顧客Cとの売買取引において重要事項を故意に告知せず、Cに1000万円の損害を与えた。国土交通大臣がAに対して業務停止処分（6か月）を命じた場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['国土交通大臣はAに対して業務停止処分だけでなく同時に免許取消処分もできる','業務停止処分に違反してAが業務を継続した場合、免許取消処分の対象となりうる','業務停止処分はAの主たる事務所のみに適用され従たる事務所の業務は継続できる','業務停止処分を受けたAの専任の宅建士は全員登録消除となる'],ans:1,exp:'宅建業者が業務停止処分に違反して宅建業を継続した場合は、免許取消処分（必要的取消し）の対象となります（宅建業法66条1項9号）。業務停止処分は会社全体（全事務所）に対する処分であり、特定の事務所だけに限定されません。業務停止処分と免許取消処分を同時に行うことはできません（段階的な処分）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "宅建業者が業務停止処分に違反して業務を継続した場合、必要的免許取消し事由となります（宅建業法66条1項9号）。業務停止処分はすべての事務所に適用されます。宅建業者への処分が宅建士への処分を直接引き起こすわけではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "国土交通大臣はAに対して業務停止処分だけでなく同時に免許取消処分もできる", "reason": "業務停止処分と免許取消処分は独立した処分であり（宅建業法65条・66条）、同時に行うことも理論上可能ですが、通常は段階的に行われます。", "caution": ""}, {"label": "業務停止処分はAの主たる事務所のみに適用され従たる事務所の業務は継続できる", "reason": "業務停止処分は原則として業者全体（全事務所）に適用されます（宅建業法65条2項）。主たる事務所のみではありません。", "caution": "業務停止処分：業者全体（全事務所）に適用。"}, {"label": "業務停止処分を受けたAの専任の宅建士は全員登録消除となる", "reason": "業者への業務停止処分は宅建士個人の登録消除を直接引き起こしません（宅建業法65条・68条の2）。宅建士への処分は別途行われます。", "caution": ""}], "summary": {"head": ["業務停止処分違反の効果", "内容"], "rows": [["違反の効果", "必要的免許取消し（宅建業法66条1項9号）"], ["業務停止の範囲", "業者全体（全事務所）"], ["宅建士への影響", "業者への処分とは別に宅建士への処分が行われる"]]}}},
  {id:10840,unit:'k_kokudo',level:3,field:'limit',text:'AはB県内（都市計画区域外・準都市計画区域外）の山林（面積20000m2）を購入する予定である。売主はC社（土地所有者）であり、売買代金は3億円である。この場合に関する記述として国土利用計画法の規定によれば正しいものはどれか。',opts:['都市計画区域外では国土利用計画法の事後届出は不要である','都市計画区域外（準都市計画区域外）では10000m2以上の土地取引に事後届出が必要であり、20000m2はこれを超えるためAは契約締結後2週間以内にB県知事に届け出なければならない','事後届出の期限は契約締結後1か月以内である','都市計画区域外では100000m2以上でなければ届出不要である'],ans:1,exp:'国土利用計画法の事後届出（同法23条）は都市計画区域外（準都市計画区域を除く）では10000m2（1ha）以上の土地取引に必要です。20000m2はこれを超えるため届出が必要です。届出期限は契約締結後2週間以内（同法23条1項）で、届出先はB県知事です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "都市計画区域外（準都市計画区域外）でも10000㎡以上の土地取引には事後届出が必要です（国土利用計画法23条1項・施行令17条）。事後届出の期限は契約締結後3週間以内です（同法23条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "都市計画区域外では国土利用計画法の事後届出は不要である", "reason": "都市計画区域外でも10000㎡以上の取引には届出が必要です（国土利用計画法23条1項・施行令17条）。", "caution": "都市計画区域外：10000㎡以上の取引→事後届出必要（国土利用計画法施行令17条）。"}, {"label": "事後届出の期限は契約締結後1か月以内である", "reason": "事後届出の期限は3週間以内です（国土利用計画法23条1項）。", "caution": ""}, {"label": "都市計画区域外では100000m2以上でなければ届出不要である", "reason": "都市計画区域外の基準は10000㎡以上です（国土利用計画法施行令17条）。", "caution": ""}], "summary": {"head": ["設問の事後届出判断", "内容"], "rows": [["区域", "都市計画区域外"], ["面積", "20000m2"], ["基準", "10000m2以上"], ["結論", "事後届出必要（契約締結後3週間以内）"]]}}},
  {id:10841,unit:'r_bukken',level:3,field:'rights',text:'AはBに対して甲土地を売却する契約を締結した。甲土地の登記名義はまだAのままである。AはDに対しても同じ甲土地を売却する二重売買をしてしまった。BはAから引渡しは受けたが登記をまだ備えていない。DはBよりも後に契約をしたが、DはBが既に買い受けていることを知っていた。この場合に関する記述として民法の規定及び判例によれば正しいものはどれか。',opts:['登記を備えていないBはDに対して所有権を主張できない','DがBの権利を知っていた（悪意）だけでなく、BのAに対する登記請求を妨害する目的でAに圧力をかけてAD間の売買をしたような場合は、DはBへの対抗力がない背信的悪意者とみなされ、BはDに対して登記なくして所有権を対抗できる','悪意者（Dがすでに買い受けていることを知っていた）は常にBに登記なしに対抗できる','BがAから引渡しを受けているため所有権はBにある'],ans:1,exp:'判例上、不法に登記の欠如を主張することが信義則に反するような「背信的悪意者」に対しては、登記なしに物権変動を対抗できます（最高裁判例）。単なる悪意（二重売買を知っていた）だけでは背信的悪意者にはなりませんが、積極的に妨害する等の悪質な場合は背信的悪意者とされBが勝てる可能性があります。',"kaisetsu":{"topic": "物権変動：登記が対抗要件・不法占拠者には登記不要", "basis": {"text": "不動産の物権変動は登記が第三者への対抗要件です（民法177条）。不法占拠者には登記なく対抗できます。相続の法定相続分超過部分は登記が必要です（民法899条の2）。", "example": ""}, "reason": {"text": "背信的悪意者とは単に先買人の存在を知っているだけでなく、信義則に反する積極的な行為（登記妨害・不当な圧力等）をした者です（判例）。このような者に対しては登記なしで対抗できます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">物権変動の対抗要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対抗要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">二重譲渡</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先に登記した者が優先</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不法占拠者</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記不要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物賃借権</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡し</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続（超過部分）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記必要</text></svg>", "choices": [{"label": "登記を備えていないBはDに対して所有権を主張できない", "reason": "DがBのAへの登記請求を妨害する等の積極的不正行為をした背信的悪意者に当たる場合、BはDに対して登記なしで所有権を対抗できます（判例）。", "caution": "単純悪意者→登記なしでは対抗不可、背信的悪意者→登記なしでも対抗可。"}, {"label": "悪意者は常にBに登記なしに対抗できる", "reason": "設問のDは積極的な妨害行為をした背信的悪意者に当たります。このような者はBに対抗できません（判例）。", "caution": ""}, {"label": "BがAから引渡しを受けているため所有権はBにある", "reason": "不動産の対抗要件は引渡しではなく登記です（民法177条）。引渡しを受けていても登記がなければ第三者への対抗は困難です（背信的悪意者の場合を除く）。", "caution": ""}], "summary": {"head": ["Dの態様", "BはDに登記なしで対抗できるか"], "rows": [["善意者", "不可"], ["単純悪意者（知っているだけ）", "不可"], ["背信的悪意者（妨害等の積極行為あり）", "可（判例）"]]}}},
  {id:10842,unit:'t_kinyu',level:3,field:'tax',text:'Aはフラット35を利用して新築住宅を購入しようとしている。フラット35の審査基準・利用条件について確認している。この場合に関する記述として住宅金融支援機構法・フラット35の規定によれば正しいものはどれか。',opts:['フラット35は変動金利型ローンであり、借入時の金利が将来変動する','フラット35は融資対象住宅の床面積が30m2以上であれば利用できる','フラット35は民間金融機関が貸し付けを行い住宅金融支援機構がその債権を買い取る証券化支援型のローンであり、金利は借入時に確定し返済完了まで変わらない全期間固定金利型','フラット35を利用する場合、頭金は不要で購入金額全額を融資できる'],ans:2,exp:'フラット35は民間金融機関が貸し付けを行い住宅金融支援機構が債権を買い取る証券化支援業務を利用したローンで、全期間固定金利型です（住宅金融支援機構法13条1項1号）。融資対象住宅の床面積は一戸建て70m2以上・マンション30m2以上が条件（省エネ基準適合も必要）です。融資割合は購入価格の90%が上限（頭金10%以上が必要）が基本です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10843,unit:'r_dairi',level:3,field:'rights',text:'AはBに自己の土地（甲地）の売買に関する一切の代理権を与えた。BはこのA代理人として、Cとの間でAを売主とする甲地の売買契約を締結した。ところが契約締結後にAが死亡した。相続人はDのみである。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['Aの死亡により代理権は消滅するが、BC間の売買契約の効果はAの相続人Dに帰属する','Aの死亡により代理権は消滅し、Bがその後行う行為はすべて無権代理となる','Aが死亡した場合でも、BはAの相続人Dの代理人として引き続き行為できる','Aが死亡しても売買契約は当然に無効となり、BはCに対して損害賠償を支払わなければならない'],ans:0,exp:'代理権は本人の死亡により消滅します（民法111条1項1号）。しかしAの死亡前にBがCとの間で締結した売買契約は有効であり、その効果はAの地位を承継した相続人Dに帰属します（民法896条）。代理権が消滅した後にBが行う行為（もし行うとすれば）は無権代理となります。',"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護する制度です。", "example": ""}, "reason": {"text": "本人の死亡により代理権は消滅します（民法111条1項1号）。しかし死亡前に締結された売買契約の効果はすでに本人に帰属しており、その権利義務は相続人に承継されます（民法896条）。代理権消滅と既存の契約効果の帰属は別問題です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "Aの死亡により代理権は消滅し、Bがその後行う行為はすべて無権代理となる", "reason": "Aの死亡後のBの新たな行為は無権代理となりますが、死亡前に締結されたBC間の売買契約の効果はAに帰属しており、それがDに相続されます（民法896条）。", "caution": "代理権消滅（死亡後の行為が無権代理）と既存契約の相続は別問題です。"}, {"label": "AはBの相続人Dの代理人として引き続き行為できる", "reason": "AはBの代理人として授権されており、Dの代理人として行為する権限はありません。代理権はAからBに与えられたものです。", "caution": ""}, {"label": "Aが死亡しても売買契約は当然に無効となり、BはCに対して損害賠償を支払わなければならない", "reason": "Aの死亡後も死亡前に締結された売買契約は有効です。Bが損害賠償を払う理由はありません。", "caution": ""}], "summary": {"head": ["場面", "法的処理"], "rows": [["本人の死亡", "代理権消滅（民法111条1項1号）"], ["死亡前の代理行為", "効果は本人に帰属済み→相続人に承継（民法896条）"], ["死亡後の代理行為", "無権代理（民法113条）"]]}}},
  {id:10844,unit:'r_baibai',level:3,field:'rights',text:'AはBからB所有のマンション（築20年・中古）を2000万円で購入した。売買契約書には「売買物件は現状のままで引き渡す」との文言があったが、契約不適合責任の免責については何も書かれていなかった。引渡し後6か月が経過したところで、雨漏りが発生した。Aが調査したところ、屋上防水の劣化が原因であることがわかり、修繕には400万円かかることが判明した。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['「現状のままで引き渡す」という文言は免責特約として機能し、AはBに対して契約不適合責任を問えない','契約書に免責特約が明記されていないため、AはBに対して契約不適合責任（民法562条以下）に基づく追完請求・代金減額請求・損害賠償請求・解除のいずれかを選択できる','Aは不適合を知った時から2年以内に訴訟を提起しなければ権利が消滅する','「現状有姿渡し」の特約があれば引渡しから1年以上経過した不具合については売主は一切責任を負わない'],ans:1,exp:'「現状のままで引き渡す」との文言は単なる物件の引渡し状態を示すものであり、契約不適合責任の明示的な免責特約とはなりません。免責特約がない以上、BはAに対して契約不適合責任を負います。Aは不適合を知った時から1年以内に「通知」（権利行使の通知）を行えば、通知後は消滅時効の範囲内（5年または10年）で権利行使できます（民法566条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "「現状のままで引き渡す」という文言は契約不適合責任の免責特約にはなりません（免責を明示していないため）。免責特約は明確に記載されていなければなりません。AはBに対して民法の契約不適合責任を負います。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "現状のままで引き渡す文言は免責特約として機能する", "reason": "「現状のままで引き渡す」は免責特約ではありません。免責特約は明確に「責任を負わない」旨の記載が必要です（民法572条・判例）。", "caution": "現状有姿≠免責特約（免責特約は明確な記載が必要）。"}, {"label": "Aは不適合を知った時から2年以内に訴訟提起が必要", "reason": "通知期限は「知った時から1年以内の通知」です（民法566条）。2年ではありませんし、訴訟提起ではなく通知で足ります。", "caution": "通知期限＝1年（民法566条）。訴訟提起ではなく通知で足ります。"}, {"label": "引渡しから1年以上経過した不具合は売主は責任なし", "reason": "通知期限は「不適合を知った時から1年以内の通知」です（民法566条）。引渡しから1年ではありません。", "caution": ""}], "summary": {"head": ["免責特約の成立要件", "内容"], "rows": [["明確な記載", "「契約不適合責任を負わない」等の明示が必要"], ["現状有姿", "免責特約にならない（現状を認識した上の売買の表明）"], ["知りながら告げなかった場合", "免責特約があっても無効（民法572条）"]]}}},
  {id:10845,unit:'l_37jo',level:3,field:'law',text:'宅建業者Aが媒介して、売主BとC（買主・宅建業者でない）の間で中古住宅（木造2階建て）の売買契約が成立した。代金は2500万円で、BはCに代金全額の受領と同時に鍵を渡す（代金・引渡し同時）こととし、登記移転は引渡しから1か月以内とすることでBCが合意した。また、インスペクション（建物状況調査）は実施していない。この場合37条書面への記載に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['37条書面には代金2500万円・引渡し時期・移転登記申請時期（引渡しから1か月以内）を記載しなければならない','インスペクションを実施していないため、37条書面にはインスペクション実施の有無についての記載は不要','37条書面はAが作成して売主Bのみに交付すればよい','37条書面への記名は宅建業者Aの代表者のみが行えばよく、宅建士の記名は不要'],ans:0,exp:'37条書面の必要的記載事項には代金の額・支払時期・方法（2500万円・引渡しと同時）、宅地建物の引渡し時期、移転登記申請の時期（引渡しから1か月以内）が含まれます（宅建業法37条1項）。インスペクション実施の有無は35条書面（重要事項説明）での記載事項です。37条書面はBとCの双方に交付し、宅建士が記名しなければなりません。',"kaisetsu":{"topic": "37条書面：全取引で交付・記名（押印不要）・移転登記申請時期は必要的記載事項", "basis": {"text": "37条書面は売買・交換・賃貸借の全取引で契約の双方当事者に交付が義務（宅建業法37条）。引渡し時期・移転登記申請時期は必要的記載事項。2021年改正で押印は不要になり記名のみで足ります。", "example": ""}, "reason": {"text": "代金・引渡し時期・移転登記申請時期は37条書面の必要的記載事項です（宅建業法37条1項2号・4号・5号）。インスペクション（建物状況調査）の実施有無は35条書面（重要事項説明書）の記載事項であり、37条書面の記載事項ではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付義務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全取引・双方当事者</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡時期・移転登記申請時期等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要）</text></svg>", "choices": [{"label": "インスペクションを実施していないため37条書面にはインスペクション実施の有無についての記載は不要", "reason": "インスペクションの実施有無は35条書面の記載事項であり（宅建業法35条1項14号）、37条書面の記載事項ではありません。この選択肢の内容（記載不要）は正しいですが、理由が不正確です。", "caution": "インスペクション実施有無：35条書面の記載事項。37条書面には含まれない。"}, {"label": "37条書面はAが作成して売主Bのみに交付すればよい", "reason": "37条書面は売主・買主双方に交付しなければなりません（宅建業法37条1項）。", "caution": ""}, {"label": "37条書面への記名は宅建業者Aの代表者のみが行えばよく宅建士の記名は不要", "reason": "37条書面の記名は宅建士が行います（宅建業法37条3項）。代表者でも宅建士でなければ不可です。", "caution": ""}], "summary": {"head": ["設問の37条書面記載事項", "必要的か"], "rows": [["代金2500万円", "必要的"], ["引渡し時期（代金全額受領と同時）", "必要的"], ["移転登記申請時期（引渡しから1か月以内）", "必要的"], ["インスペクション実施有無", "37条書面の記載事項外（35条書面の事項）"]]}}},
  {id:10846,unit:'k_mori',level:3,field:'limit',text:'Aは自己の土地（宅地造成等工事規制区域内）において、次の造成工事を計画している。①切土で高さ3mの崖を生じさせる工事②盛土で高さ2mの崖を生じさせる工事③切土と盛土を合わせて高さ3mの崖を生じさせる工事④土地の面積500m2に盛土を施す工事（高さ1m以下）。この場合に関する記述として盛土規制法（宅地造成及び特定盛土等規制法）の規定によれば正しいものはどれか。',opts:['①〜④のいずれも都道府県知事の許可が不要','①②③はいずれも許可が必要だが④は許可不要','①切土3mは許可対象（2m超）、②盛土2mは許可対象（1m超）、③合計3mは許可対象（2m超）、④面積500m2盛土（高さ1m以下）は500m2を超えないため許可不要','④の面積500m2の盛土が最も危険なため最優先で許可が必要'],ans:2,exp:'宅地造成工事規制区域内で許可が必要な宅地造成工事は、①切土で2m超の崖を生じさせるもの②盛土で1m超の崖を生じさせるもの③切土・盛土合わせて2m超の崖を生じさせるもの④土地の面積500m2超の工事などです（盛土規制法令3条）。したがって①（切土3m・2m超）②（盛土2m・1m超）③（合計3m・2m超）は許可対象。④（面積500m2以下・高さ1m以下）は許可対象の面積要件（500m2超）を満たさず許可不要。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "①切土で高さ3mの崖（2m超）→許可対象。②盛土で高さ2mの崖（1m超）→許可対象。③切土＋盛土の合計高さ3m（2m超）→許可対象。④面積500㎡以下の盛土（崖を生じない）→許可不要。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "①〜④のいずれも許可が不要", "reason": "①②③は許可対象です（施行令3条）。「いずれも不要」は誤りです。", "caution": "切土2m超・盛土1m超・合計2m超の崖：許可対象（施行令3条）。"}, {"label": "①②③はいずれも許可が必要だが④は許可不要", "reason": "この選択肢も正しいです。設問の正解は選択肢3（より詳細な説明）です。", "caution": ""}, {"label": "④の面積500m2の盛土が最も危険なため最優先で許可が必要", "reason": "④は500㎡ちょうど（500㎡超ではない）であり、崖を生じなければ許可不要です（施行令3条）。", "caution": ""}], "summary": {"head": ["設問の各工事の判断", "許可の要否"], "rows": [["①切土で3mの崖（2m超）", "許可必要"], ["②盛土で2mの崖（1m超）", "許可必要"], ["③切土＋盛土で3m（2m超）", "許可必要"], ["④面積500㎡の盛土（崖なし・500m2以下）", "許可不要"]]}}},
  {id:10847,unit:'r_fuhoko',level:3,field:'rights',text:'AはBに対して不法行為による損害賠償請求権を有している（損害発生日：2020年4月1日、AがBによる加害行為および損害を知った日：2021年1月1日）。AはBに対していつまでに損害賠償請求の訴訟を提起すれば消滅時効にかかることなく請求できるか。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['損害発生日（2020年4月1日）から3年以内に提訴すれば足りる','AがBによる加害行為・損害を知った日（2021年1月1日）から3年以内（2024年1月1日まで）または不法行為時（2020年4月1日）から20年以内のどちらか早い方が時効期間となる','不法行為の時効は常に5年である','不法行為による損害賠償請求権には時効がない'],ans:1,exp:'不法行為による損害賠償請求権の消滅時効は、被害者が損害および加害者を知った時から3年（人の生命・身体を害する不法行為は5年）または不法行為の時から20年のいずれか早い方です（民法724条）。本問では2021年1月1日から3年の2024年1月1日と、2020年4月1日から20年の2040年4月1日を比較し、早い方（2024年1月1日）が時効完成日となります。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "不法行為の消滅時効は「損害および加害者を知った時から3年」または「不法行為時から20年」のいずれか早い方で消滅します（民法724条）。設問では知った日（2021年1月1日）から3年後の2024年1月1日と、不法行為時（2020年4月1日）から20年後の2040年4月1日を比較すると、前者が早いため2024年1月1日が時効完成日です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "損害発生日（2020年4月1日）から3年以内に提訴すれば足りる", "reason": "3年の起算点は「損害発生日」ではなく「損害および加害者を知った日」です（民法724条1号）。設問では知った日は2021年1月1日です。", "caution": "起算点は「知った日」（損害発生日ではない）。"}, {"label": "不法行為の時効は常に5年である", "reason": "不法行為の消滅時効は3年（人身は5年）と20年の二本立てです（民法724条）。「常に5年」は誤りです。", "caution": ""}, {"label": "不法行為による損害賠償請求権には時効がない", "reason": "不法行為による損害賠償請求権にも消滅時効があります（民法724条）。", "caution": ""}], "summary": {"head": ["設問の時効計算", "日付"], "rows": [["不法行為時", "2020年4月1日"], ["損害・加害者を知った日", "2021年1月1日"], ["主観的起算点（3年）", "→2024年1月1日に完成"], ["客観的起算点（20年）", "→2040年4月1日に完成"], ["適用される時効", "早い方：2024年1月1日"]]}}},
  {id:10848,unit:'r_kukku',level:3,field:'rights',text:'分譲マンション（専有部分20戸）の一室を所有するAが、自室の一部をペットのために改造し、共用部分の廊下にペット用の水飲み場を設置した。管理規約ではペットの飼育および共用部分の改変は管理組合の承認が必要と定められているが、Aは承認を得ていない。管理組合の理事長Bは規約違反を理由にAに是正を求めた。この場合に関する記述として区分所有法の規定によれば正しいものはどれか。',opts:['専有部分の改造は区分所有者の自由であり、管理組合は一切干渉できない','共用部分に無断で水飲み場を設置したAの行為は規約違反であり、管理組合（管理者）は行為の停止等の請求ができ、集会決議があれば訴訟も提起できる','管理規約はあくまで任意的なものであり、Aが規約に違反しても管理組合は何もできない','管理規約は区分所有者全員の同意がなければ改正できないため、現在の規約がAに不利であれば全員の同意を得て規約を改正してもらうしかない'],ans:1,exp:'区分所有法57条により、区分所有者・占有者が区分所有者の共同の利益に反する行為をする場合、管理者・管理組合は行為の停止・専有部分の使用禁止・競売・引渡し請求等を集会決議に基づき裁判所に請求できます。共用部分への無断設置は規約違反として是正請求・訴訟が可能です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "区分所有者が共同生活上の義務に反する行為をした場合、管理者または管理組合は行為の停止等を請求できます（区分所有法57条）。共用部分の無断改変は規約違反であり、行為停止請求・損害賠償等の対象となります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "専有部分の改造は区分所有者の自由であり管理組合は一切干渉できない", "reason": "専有部分内でも共用部分に影響する場合や規約違反の場合は管理組合が介入できます（区分所有法6条・57条）。", "caution": "規約違反→管理組合による行為停止等の請求可（区分所有法57条）。"}, {"label": "管理規約はあくまで任意的なものであり違反しても管理組合は何もできない", "reason": "管理規約は区分所有者を拘束する効力があり（区分所有法30条3項）、違反に対して法的措置が取れます（同法57条）。", "caution": ""}, {"label": "規約の改正のためには全員の同意が必要", "reason": "規約の変更は3/4以上の特別決議で足ります（区分所有法31条1項）。全員同意は不要です。", "caution": ""}], "summary": {"head": ["義務違反に対する管理組合の措置", "要件"], "rows": [["行為の停止等（区分所有法57条）", "過半数（集会決議）"], ["専有部分の使用禁止（区分所有法58条）", "3/4以上の特別決議"], ["区分所有権の競売（区分所有法59条）", "3/4以上の特別決議＋訴訟"], ["規約の遵守義務", "区分所有者・占有者に適用（区分所有法46条）"]]}}},
  {id:10849,unit:'t_kotei',level:3,field:'tax',text:'Aは2024年1月1日に中古一戸建て住宅（土地150m2・建物評価額800万円・土地評価額1800万円）を購入した。前の所有者（売主）は2023年12月31日に売却した。固定資産税の賦課期日は1月1日である。この場合に関する記述として地方税法の規定によれば正しいものはどれか。',opts:['2024年分の固定資産税は購入者Aが1月1日時点の所有者であるため全額Aが納付する','固定資産税の賦課期日は1月1日であり、2024年1月1日現在の所有者はAであるため2024年分の固定資産税の法的納税義務者はAである。売主との按分は売買当事者間の合意による','固定資産税は3か月ごとに4回に分けて納付するが、Aは1月1日以降の分のみ按分して支払えばよい','建物の固定資産税は2024年が新築から何年目かによって税額が自動的に軽減される'],ans:1,exp:'固定資産税の賦課期日は1月1日であり、2024年1月1日現在の所有者（A）が2024年度分の固定資産税の法的な納税義務者です（地方税法343条1項）。売買の場合、売主と買主の間で1月1日以前・以後の所有期間を按分して固定資産税相当額を授受するのが一般的ですが、これは当事者間の合意によるものであり法的には全額がAの義務です。',"kaisetsu":{"topic": "固定資産税：市町村が課す地方税・賦課期日は1月1日・評価替えは3年ごと", "basis": {"text": "固定資産税は市町村（東京23区は都）が課す地方税です（地方税法343条）。賦課期日は毎年1月1日。評価替えは3年ごと（基準年度）。住宅用地の特例：200㎡以下は課税標準1/6、超過部分は1/3。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">固定資産税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市町村（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賦課期日</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">評価替え</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年ごと</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅用地（200㎡以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税標準1/6</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10850,unit:'l_menkyo',level:3,field:'law',text:'宅建業者Aは個人事業主として甲県知事の免許を受けて宅建業を営んでいる。AはBを専任の宅建士として採用していたが、BがC社（別会社）の専任の宅建士にも就任していることが判明した。また、Aの業務従事者は4名であり、Bを含む専任の宅建士が1名のみという状況である。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['Bが他社の専任宅建士も兼任している事実はBの登録上の問題であり、宅建業者Aへの影響はない','専任の宅建士は他の宅建業者の専任宅建士を兼任できない。BはAとC社の両方の専任宅建士になることはできず、いずれかの専任を辞する必要がある','業務従事者4名に対し専任宅建士1名は法定要件（5名に1名以上）を満たしており問題ない','Bが専任を辞した場合でも、Aは補充なしに宅建業を継続できる'],ans:1,exp:'専任の宅建士は常時勤務する必要があり（宅建業法施行規則6条の2）、同一の宅建業者の複数事務所の専任宅建士を兼任できません。他の宅建業者（C社）の専任宅建士との兼任もできません。BはAとC社のどちらかの専任宅建士を辞する必要があります。業務従事者4名の場合、1名の専任宅建士は法定要件（5名に1名以上）を満たしています（4名÷5＝0.8→切り上げ1名）。',"kaisetsu":{"topic": "宅建業の免許：知事・大臣免許の区別・有効期間5年・欠格事由", "basis": {"text": "1都道府県のみ→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間です。", "example": ""}, "reason": {"text": "専任の宅建士は他の宅建業者の専任の宅建士を兼任することはできません（宅建業法15条1項）。専任性が失われると宅建業者の専任宅建士設置要件を欠くことになります（宅建業法31条の3）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（拘禁刑以上・特定罰金等）</text></svg>", "choices": [{"label": "Bが他社の専任宅建士も兼任している事実はBの登録上の問題であり宅建業者Aへの影響はない", "reason": "BがAとC社の両方の専任宅建士を兼任することはできません（宅建業法15条1項）。AはBを専任宅建士として数えられなくなり、設置要件違反になりえます。", "caution": "専任宅建士は他社の専任宅建士と兼任不可（宅建業法15条1項）。"}, {"label": "業務従事者4名に対し専任宅建士1名は法定要件（5名に1名以上）を満たしており問題ない", "reason": "4名に1名は数字上は足りますが、BがA社の専任宅建士として認められなくなれば専任宅建士が0名となり要件違反です（宅建業法31条の3第1項）。", "caution": ""}, {"label": "Bが専任を辞した場合でもAは補充なしに宅建業を継続できる", "reason": "専任宅建士がいなくなった場合は2週間以内に補充が必要です（宅建業法31条の3第3項）。補充なしに継続できません。", "caution": ""}], "summary": {"head": ["専任の宅建士（宅建業法15条・31条の3）", "内容"], "rows": [["専任性", "その業務に専従していること"], ["兼任禁止", "他の宅建業者の専任宅建士との兼任不可"], ["設置要件", "業務従事者5名に1名以上（宅建業法31条の3第1項）"], ["欠員時", "2週間以内に補充が必要（宅建業法31条の3第3項）"]]}},},


  // ===== 長文問題追加50問（10851〜10900）=====
  {id:10851,unit:'r_ishi',level:3,field:'rights',text:'AはBから「この土地は近く区画整理の対象になり、必ず値上がりする」と断言されて信じ込み、B所有の甲土地を相場より500万円高い2000万円で購入した。しかし実際には区画整理の計画はなく、Bは全くの作り話をしていた。売買契約締結から2年後にAはこの事実を知った。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['Bが将来の値上がりを断言したにすぎず詐欺には当たらないため、Aは取り消せない','BはAに対して事実と異なる断言をして錯誤に陥らせたものであり詐欺（民法96条）に当たるため、AはBに対して詐欺を理由に売買契約を取り消すことができる','AはBとの売買契約の取消しには相当の理由があるが、契約締結から2年が経過しているためもはや取消権は時効で消滅している','Aは錯誤（民法95条）を理由に取り消すこともできるが詐欺と錯誤は同時に主張できない'],ans:1,exp:'将来の値上がりを断言するという方法でAを錯誤に陥らせた場合、これは詐欺（民法96条1項）に当たります。詐欺による取消権の時効は、詐欺を知った時から5年・行為の時から20年です（民法126条）。Aが詐欺を知ったのは契約から2年後であり、そこから5年以内であれば取消権を行使できます。錯誤と詐欺の主張は重複して行うことも可能です。',"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "意思表示の瑕疵には詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失の第三者は保護）・通謀虚偽表示（無効・善意の第三者は保護）があります。", "example": ""}, "reason": {"text": "虚偽の事実を告知して相手方を錯誤に陥らせて契約させる行為は詐欺（民法96条）に当たります。故意に事実と異なる断言をした場合は詐欺の故意が認められます。取消権の時効は詐欺を知った時から5年です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "Bが将来の値上がりを断言したにすぎず詐欺には当たらないため、Aは取り消せない", "reason": "Bは実際には存在しない区画整理計画を「必ず値上がりする」と断言しており、事実と異なることを知りながら告知した詐欺に当たります（民法96条1項）。", "caution": "将来の予測であっても、存在しない事実を断言して信じ込ませる行為は詐欺に該当します。"}, {"label": "AはBとの売買契約の取消しには相当の理由があるが、契約締結から2年が経過しているためもはや取消権は時効で消滅している", "reason": "詐欺取消権の時効は「追認できる時（詐欺を知った時）から5年」です（民法126条）。詐欺を知った1年後なら取消権は消滅していません。", "caution": "「契約締結から2年」ではなく「詐欺を知った時から5年」が起算点です。"}, {"label": "Aは錯誤（民法95条）を理由に取り消すこともできるが詐欺と錯誤は同時に主張できない", "reason": "詐欺と錯誤は重複する場合があり、同時に主張することは可能です。", "caution": ""}], "summary": {"head": ["取消原因", "取消権の時効（主観）", "取消権の時効（客観）"], "rows": [["詐欺（96条）", "追認できる時から5年", "行為時から20年"], ["錯誤（95条）", "追認できる時から5年", "行為時から20年"], ["強迫（96条）", "追認できる時から5年", "行為時から20年"]]}}},
  {id:10852,unit:'r_dairi',level:3,field:'rights',text:'AはBに対して「A所有の乙土地を1500万円で売却する権限」を与える代理権を授与した。ところがBは代理人として行動する際に、C（第三者）の利益を図る目的でAに不利な条件（1000万円）でCとの間で売買契約を締結した。Cは、BがAに不利な条件で契約することを知っていた。この場合に関する記述として民法の規定及び判例によれば正しいものはどれか。',opts:['代理人Bには売却の代理権があるので、条件が多少不利でも本人Aはその契約に拘束される','代理人Bが自己または第三者の利益を図るためにその代理権の範囲内の行為をした場合（代理権の濫用）で相手方Cがその事情を知りまたは知ることができたとき、その行為は無権代理とみなされAは責任を負わない','Bが代理権を濫用してもCは善意であればAに対して契約の効力を主張できる','代理人の動機は代理行為の効力に影響しない'],ans:1,exp:'代理人が自己または第三者の利益を図る目的で代理権の範囲内の行為をした場合（代理権の濫用・民法107条）、相手方がその目的を知りまたは知ることができたときは、その行為は無権代理とみなされます。本問ではCがBの濫用目的を知っていたため、Aはその契約に拘束されません。',"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護する制度です。", "example": ""}, "reason": {"text": "代理権の濫用（民法107条）では、代理人が外形上代理権の範囲内で行動しながら、自己または第三者の利益を図る不正な目的で代理権を行使した場合に問題となります。相手方が悪意または有過失のときは無権代理とみなされます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "代理人Bには売却の代理権があるので、条件が多少不利でも本人Aはその契約に拘束される", "reason": "代理権の濫用（民法107条）では、相手方Cが代理人Bの不正な目的を知りまたは知ることができた場合、本人Aはその行為の効果を否定できます。「常に拘束される」は誤りです。", "caution": ""}, {"label": "Bが代理権を濫用してもCは善意であればAに対して契約の効力を主張できる", "reason": "設問ではCはBの不正な目的を「知っていた（悪意）」ため、Aはその契約に拘束されません（民法107条）。Cが善意の場合とは扱いが異なります。", "caution": ""}, {"label": "代理人の動機は代理行為の効力に影響しない", "reason": "民法107条により、代理人の不正な動機（目的）が相手方にわかる場合は代理行為の効力に影響します。", "caution": ""}], "summary": {"head": ["相手方の状態", "代理行為の効力"], "rows": [["善意かつ無過失", "有効（本人に帰属）"], ["悪意または有過失", "無権代理とみなされる（民法107条）→本人は効果否定可"]]}}},
  {id:10853,unit:'r_tanpo',level:3,field:'rights',text:'AはB銀行から1億円を借り入れ、A所有の甲ビル（時価1億5000万円）に抵当権を設定した。その後、甲ビルが火災で全焼し、Aが加入していた火災保険会社から保険金1億2000万円が支払われることになった。B銀行はこの保険金から優先弁済を受けたいと考えている。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['火災保険金は抵当権の物上代位の対象とならないため、B銀行は保険金から優先弁済を受けられない','火災保険金は抵当権の物上代位の対象となり、B銀行は保険金がAに払い渡される前に差押えをすることで、保険金から1億円の優先弁済を受けることができる','B銀行は物上代位により保険金1億2000万円全額を受け取ることができる','火災が発生した以上抵当権の目的物が滅失したため、抵当権は消滅し、B銀行は残債権を一般債権として請求するのみ'],ans:1,exp:'抵当権の物上代位（民法304条）は火災保険金にも及びます。B銀行は保険金がAに払い渡される前に差押えをすれば、保険金から被担保債権1億円の優先弁済を受けることができます。残額2000万円（1億2000万円－1億円）はAに帰属します。払渡し前の差押えが要件です。',"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権です（民法369条）。質権は占有の移転が必要です。先取特権は法律上当然に成立する法定担保物権です。", "example": ""}, "reason": {"text": "火災保険金は抵当権の物上代位の対象です（民法372条・304条）。抵当不動産が滅失しても保険金に抵当権の効力が及びます。ただし保険金がAに払い渡される前に差押えをすることが要件です（民法304条1項但書）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・非占有</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・占有</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "火災保険金は物上代位の対象とならない", "reason": "火災保険金は抵当権の物上代位の対象です（民法372条・304条1項）。「対象とならない」は誤りです。", "caution": "保険金は物上代位の対象（民法304条1項）。払渡し前の差押えが要件。"}, {"label": "B銀行は保険金1億2000万円全額を受け取ることができる", "reason": "B銀行が受け取れるのは被担保債権額（1億円）の範囲内です。保険金の全額ではありません。", "caution": "物上代位で受け取れるのは被担保債権額が上限。"}, {"label": "抵当権の目的物が滅失したため抵当権は消滅する", "reason": "目的物が滅失しても物上代位により保険金に抵当権の効力が及びます（民法372条・304条）。抵当権が当然に消滅するわけではありません。", "caution": ""}], "summary": {"head": ["火災保険金への物上代位", "内容"], "rows": [["対象", "火災保険金（民法304条1項）"], ["要件", "保険金払渡し前に差押え"], ["受領額", "被担保債権額（1億円）が上限"], ["目的物滅失", "抵当権は消滅せず保険金に追及"]]}}},
  {id:10854,unit:'r_saikensoron',level:3,field:'rights',text:'AはBに対して500万円の売買代金債権（弁済期：2024年4月1日）を有している。BはAのほかC・Dにも多額の債務を負っており、Bの財産は唯一の不動産（時価200万円）のみである。AはBが無資力であることを知りつつ、Bが自己の唯一の財産である不動産を弟Eに対して代金100万円（時価の半額）で売却したことを知った。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['Aは詐害行為取消権（民法424条）を行使して、BE間の売買契約を取り消すことができる','BE間の売買は有効な契約であり、Aは取り消せない','Aが詐害行為取消権を行使できるのはAの債権額に相当する部分のみであり、超過部分は取り消せない','詐害行為取消権の行使には債権者全員の合意が必要'],ans:0,exp:'Bが無資力の状態で唯一の財産を廉価で処分した行為は詐害行為に該当し、AはBE間の売買契約を取り消すことができます（民法424条）。ただし取消しの範囲はAの債権額（500万円）の保全に必要な限度です。また2020年改正民法により、詐害行為取消権の行使は転得者（Eから転得した者）にも及ぶ場合があります。',"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要です（民法446条2項）。連帯保証人には催告・検索の抗弁権がありません（民法454条）。債権譲渡の第三者対抗要件は確定日付ある証書による通知または承諾です（民法467条2項）。", "example": ""}, "reason": {"text": "詐害行為取消権（民法424条）の要件は①被保全債権の存在、②債務者の詐害行為（債権者を害することを知りながらした財産処分）、③受益者の悪意です。Bが唯一の財産を著しく低額（時価の半額）でEに売却した行為は詐害行為に当たります。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相殺の要件</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">双方が同種の債権</text></svg>", "choices": [{"label": "BE間の売買は有効な契約であり取り消せない", "reason": "詐害行為取消権（民法424条）の要件を満たせば取り消すことができます。有効な契約でも詐害行為として取り消せます。", "caution": "詐害行為取消権：有効な行為でも取り消せる。"}, {"label": "Aが詐害行為取消権を行使できるのはAの債権額に相当する部分のみ", "reason": "詐害行為取消しは行為全体を取り消すことができます（民法424条）。債権額に相当する部分のみという制限はありません。", "caution": ""}, {"label": "詐害行為取消権の行使には債権者全員の合意が必要", "reason": "各債権者が単独で詐害行為取消権を行使できます（民法424条1項）。全員の合意は不要です。", "caution": ""}], "summary": {"head": ["詐害行為取消権（民法424条）", "内容"], "rows": [["要件", "①被保全債権②詐害行為③受益者悪意"], ["効果", "詐害行為の取消し（全体が対象）"], ["請求先", "受益者（裁判外でも可だが通常は裁判上）"], ["全員合意", "不要（各債権者が単独行使可）"]]}}},
  {id:10855,unit:'r_chinshaku',level:3,field:'rights',text:'AはBから店舗用建物を月額20万円で賃借し、飲食店を営業していた。賃貸借期間は3年と定められていた。期間満了の半年前、BはAに対して「自分の息子が店舗として使用したいので更新しない」と通知した。Aは引き続き営業を続けたいと考えている。この場合に関する記述として借地借家法の規定によれば正しいものはどれか。',opts:['期間が定められているため、BがAに半年前に通知した以上、期間満了で賃貸借は当然に終了する','Bが更新を拒絶するには正当事由が必要であり、息子が使用するという事情のみで正当事由が認められるかは様々な事情を総合考慮して判断される','賃貸人が建物を自己使用したい場合は常に正当事由が認められる','賃貸借期間が3年と定められているため借地借家法の更新規定は適用されない'],ans:1,exp:'建物賃貸借の更新拒絶には正当事由が必要です（借地借家法28条）。賃貸人または賃貸人の親族が建物を使用する必要性は正当事由を構成する一要素ですが、それだけで当然に正当事由が認められるわけではありません。賃借人の使用の必要性・従前の経緯・建物の状況・立退料の申出等を総合考慮して判断されます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "建物賃貸借の更新拒絶には正当事由が必要です（借地借家法28条）。賃貸人の自己使用（息子の使用）の必要性は正当事由の一要素ですが、それだけで正当事由が認められるとは限りません。賃借人の必要性・建物の状況・立退料の提供等を総合考慮します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "半年前の通知で正当事由なしに終了できる", "reason": "更新拒絶には正当事由が必要です（借地借家法28条）。通知期間を守るだけでは終了できません。", "caution": ""}, {"label": "賃貸人が建物を自己使用したい場合は常に正当事由が認められる", "reason": "自己使用の必要性は正当事由の一要素ですが、賃借人の必要性・立退料等を総合考慮して判断されます（借地借家法28条）。常に認められるわけではありません。", "caution": ""}, {"label": "3年の期間定めがあると借地借家法の更新規定は適用されない", "reason": "普通建物賃貸借では期間の定めがあっても借地借家法の更新規定が適用されます（借地借家法26条・28条）。定期建物賃貸借の場合は異なります。", "caution": ""}], "summary": {"head": ["正当事由の判断要素（借地借家法28条）", "内容"], "rows": [["賃貸人の必要性", "自己使用・建替え等の必要性"], ["賃借人の必要性", "代替物件の有無・事業継続の必要性等"], ["建物の状況", "老朽化・安全性等"], ["立退料", "提供の有無・金額は正当事由を補完する"]]}}},
  {id:10856,unit:'r_souzoku',level:3,field:'rights',text:'Aには子BとCがおり、Aが死亡した時点でBはすでに死亡していた。BにはB1とB2という子（Aの孫）がいる。Aの遺産は3000万円であり、遺産分割協議においてCがB1・B2の代わりに「BとCで半分ずつ相続したことにする」という内容の協議書を作成しようとした。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['BはすでにAより先に死亡しているので、BのCへの相続は起きない','Bの代わりにB1・B2が代襲相続し、有効な遺産分割協議にはB1・B2・Cの全員が参加する必要がある','CはAの唯一の相続人となり3000万円全額を相続できる','B1・B2はまだ幼いため、CがB1・B2の代理人として遺産分割協議に参加できる'],ans:1,exp:'BがAより先に死亡した場合、BのB1・B2が代襲相続人となります（民法887条2項）。有効な遺産分割協議には相続人全員（B1・B2・C）の参加が必要です。CがB1・B2の代わりに協議書を作成しても無効です。なおB1・B2が未成年の場合、親権者が代理人となりますが、親権者がCと利益相反する場合は特別代理人の選任が必要です。',"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2", "basis": {"text": "配偶者と子の場合は各1/2（民法900条）。相続放棄は3か月以内に家庭裁判所へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2です（民法1042条）。遺産分割協議は全員合意が必要です。", "example": ""}, "reason": {"text": "代襲相続では、被代襲者（B）の代わりにその子（B1・B2）が相続人となります（民法887条2項）。遺産分割協議にはB1・B2・Cが参加しなければなりません。Cが独断でBの相続分を取得するような協議は無効です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続の主要ポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子の相続分</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は法定相続分の1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割協議</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "BはすでにAより先に死亡しているので、BのCへの相続は起きない", "reason": "正しい部分もありますが、BのCへの相続ではなく、BをB1・B2が代襲相続します（民法887条2項）。", "caution": ""}, {"label": "CはAの唯一の相続人となり3000万円全額を相続できる", "reason": "Bの代わりにB1・B2が代襲相続するため（民法887条2項）、CだけがAの相続人とはなりません。", "caution": ""}, {"label": "B1・B2はまだ幼いため、CがB1・B2の代理人として遺産分割協議に参加できる", "reason": "CはB1・B2と利益相反するため（Cが多く取るほどB1・B2の取得分が減る）、Cが代理人になることは原則できません（特別代理人の選任が必要）。", "caution": "利益相反→特別代理人が必要。Cが代理人になれません。"}], "summary": {"head": ["代襲相続と遺産分割", "内容"], "rows": [["代襲者", "B1・B2（Bの子）が代わって相続"], ["協議参加者", "B1・B2・C全員の参加が必要"], ["B1・B2の代理人", "利益相反のためCは代理不可→特別代理人選任"], ["B1・B2の相続分", "Bの相続分1/2をB1・B2で均等分割（各1/4）"]]}}},
  {id:10857,unit:'r_touki',level:3,field:'rights',text:'A所有の甲土地についてBが時効取得（20年間の占有継続）を主張している。BはAに対して所有権移転登記を求めているが、時効完成前にAはCに甲土地を売却し、AからCへの所有権移転登記が完了している。この場合に関する記述として民法の規定及び判例によれば正しいものはどれか。',opts:['Bの時効取得は登記がなくても誰にでも対抗できる','時効完成前にAからCへの売却・登記がなされた場合、BはCに対して登記なしに時効取得を対抗できる','時効完成後にAからCへ売却・登記がなされた場合、BはCに対して登記なしには時効取得を対抗できない','時効による所有権取得は登記を必要としない'],ans:2,exp:'判例上、時効完成後に登場した第三者（本問ではCが時効完成前の購入者）との関係について区別があります。時効完成前にAからCへ売却・登記された場合、CはBの時効取得開始時より前に登場した者ではなく、Bが時効取得で対抗できるかは占有継続の問題です。一方、時効完成後にAからCへ登記が移転した場合、BとCは対抗関係（登記の先後）となり、BはCに対し登記なしには時効取得を対抗できません（大連判）。本問はCへの売却・登記が時効完成前であるため、Bは登記なくCに対抗できます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "時効完成と第三者の関係は、時効完成前か後かで扱いが異なります（判例）。時効完成後に登場した第三者との関係は対抗問題となり、時効取得者は登記を備えなければ対抗できません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "Bの時効取得は登記がなくても誰にでも対抗できる", "reason": "時効完成後に登場した第三者との関係は対抗問題であり、登記がなければ対抗できません（判例）。", "caution": "時効完成前の第三者→時効の援用で対抗可。時効完成後の第三者→対抗問題。"}, {"label": "時効完成前にAからCへの売却・登記がなされた場合、BはCに対して登記なしに時効取得を対抗できる", "reason": "時効完成前にAからCへ売却・登記がなされた場合、Cは「正当な利益を有する第三者」として保護されます。BはCに時効を援用して対抗できます（判例）。", "caution": "時効完成前の第三者：時効の援用で対抗可（登記不要）が原則です。"}, {"label": "時効による所有権取得は登記を必要としない", "reason": "時効完成後の第三者との関係では登記が必要です（判例）。「登記を一切必要としない」は誤りです。", "caution": ""}], "summary": {"head": ["第三者の登場時期", "時効取得者の対抗力"], "rows": [["時効完成前", "登記なしで対抗可（判例）"], ["時効完成後", "対抗問題→登記がなければ対抗不可"]]}}},
  {id:10858,unit:'r_shakuchi',level:3,field:'rights',text:'AはBから土地を借り（借地権の存続期間30年）、その土地上に建物を建築して居住している。借地権の存続期間が満了する1年前、AはBに対して契約の更新を請求した。Bはこの更新請求を拒絶し、「正当事由がある」と主張した。Bの正当事由は、Bの長男が土地を利用したいというものだけであった。この場合に関する記述として借地借家法の規定によれば正しいものはどれか。',opts:['Bが更新を拒絶している以上、期間満了で借地契約は終了する','Bの正当事由として長男の使用必要性のみでは不十分な場合、正当事由が認められず契約は更新される（法定更新）','Aが更新請求すれば常に更新が認められる','立退料を支払えば正当事由の有無にかかわらず更新を拒絶できる'],ans:1,exp:'借地権の更新拒絶には正当事由が必要です（借地借家法6条）。正当事由は土地所有者が土地を必要とする事情・借地権者が土地を必要とする事情・借地に関する従前の経緯・土地の利用状況・財産上の給付（立退料）の申出等を総合考慮して判断されます。長男の使用必要性のみでは正当事由が不十分とされることも多く、その場合は法定更新（借地借家法5条）が成立します。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "普通借地権の更新拒絶には正当事由が必要です（借地借家法6条）。長男の使用必要性は正当事由の考慮要素ですが、それだけでは不十分な場合、正当事由が認められず法定更新されます。正当事由は貸主の必要性・立退料等を総合考慮します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "Bが更新を拒絶している以上期間満了で借地契約は終了する", "reason": "更新拒絶には正当事由が必要です（借地借家法6条）。正当事由なしの更新拒絶は効力がなく、法定更新されます（同法5条1項）。", "caution": "普通借地権：正当事由なければ更新拒絶は無効→法定更新。"}, {"label": "Aが更新請求すれば常に更新が認められる", "reason": "地主が正当事由のある異議を述べれば更新は認められません（借地借家法5条1項・6条）。「常に」は誤りです。", "caution": ""}, {"label": "立退料を支払えば正当事由の有無にかかわらず更新を拒絶できる", "reason": "立退料は正当事由を補完する要素であり（借地借家法6条）、十分な立退料があれば正当事由が認められる場合もありますが、「正当事由の有無にかかわらず」拒絶できるわけではありません。", "caution": ""}], "summary": {"head": ["普通借地権の更新と正当事由（借地借家法6条）", "内容"], "rows": [["正当事由の考慮要素", "貸主・借主の必要性・建物の現況・立退料等"], ["長男の使用必要性のみ", "通常は正当事由として不十分"], ["法定更新", "正当事由なければ更新拒絶は効力なし"], ["立退料", "不足する正当事由を補完できる"]]}}},
  {id:10859,unit:'r_fuhoko',level:3,field:'rights',text:'Aは自己所有の建物の外壁タイルが剥落し、通行中のBに当たって傷害を負わせた。建物の外壁タイル剥落の原因は施工業者Cの施工不良であることが後に判明した。Aは建物の管理において通常の注意は払っていた（無過失）。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['Aは無過失であるため一切の損害賠償責任を負わない','Aが建物の占有者であっても無過失を証明すれば免責される。しかしAが建物の所有者でもある場合は、無過失であっても所有者として無過失責任（民法717条1項後段）を負う','BはCに対してのみ損害賠償を請求できる','建物の施工不良による損害は施工業者Cのみが責任を負う'],ans:1,exp:'工作物責任（民法717条）では、工作物の占有者が第一次的責任を負い（管理に過失がなければ免責）、所有者は占有者が免責された場合に絶対的無過失責任（最終責任者）を負います。本問でAは占有者でもあり所有者でもあります。Aが無過失を証明した場合でも、所有者として無過失責任を負います。AはCに対して求償できます（民法717条3項）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "工作物責任（民法717条）では占有者が第一次的に責任を負いますが、損害防止に必要な注意をした場合は免責されます（同条1項ただし書）。その場合は所有者が無過失責任を負います（同条1項後段）。Aが占有者かつ所有者である場合、無過失の占有者としての免責は認められても、所有者としての無過失責任は免れません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "Aは無過失であるため一切の損害賠償責任を負わない", "reason": "Aが所有者である場合は無過失責任を負います（民法717条1項後段）。「一切の責任なし」は誤りです。", "caution": "所有者は無過失責任（民法717条1項後段）。"}, {"label": "BはCに対してのみ損害賠償を請求できる", "reason": "BはAに対して工作物責任（民法717条）に基づく損害賠償を請求できます。Cに対する請求も可能です（施工不良を原因とする不法行為等）。", "caution": ""}, {"label": "建物の施工不良による損害は施工業者Cのみが責任を負う", "reason": "施工業者Cへの求償（民法717条3項）は可能ですが、Aも工作物の占有者・所有者として責任を負います（民法717条1項）。", "caution": ""}], "summary": {"head": ["占有者兼所有者の責任", "内容"], "rows": [["占有者として", "無過失→免責（民法717条1項ただし書）"], ["所有者として", "無過失でも無過失責任（民法717条1項後段）"], ["施工業者C", "求償の対象（民法717条3項）"], ["結論", "A（所有者）は無過失でも無過失責任を負う"]]}}},
  {id:10860,unit:'l_jusetsu',level:3,field:'law',text:'宅建業者Aは、売主BとC（買主・宅建業者でない）の間で、用途地域が指定されていない区域内の土地の売買を媒介した。この土地の隣地には工場があり、騒音・振動の影響が懸念される。また、この土地は過去に工場として使用されていた経緯があり土壌汚染の可能性を否定できない。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['用途地域の指定がない区域は重要事項説明の対象外であるため、用途地域については説明不要','土壌汚染対策法に基づく土壌汚染状況調査の実施の有無・その内容は重要事項として説明しなければならない','騒音・振動については宅建業法に基づく説明義務はなく、Aが任意に伝えれば足りる','土壌汚染の可能性は確認できていない以上、重要事項説明書への記載は不要'],ans:1,exp:'土壌汚染対策法の規定による形質変更時要届出区域・土壌汚染状況調査の結果については重要事項として説明する義務があります（宅建業法35条1項14号・施行令3条1項33号）。土壌汚染の可能性が懸念される物件については調査結果の有無を含め適切な説明が求められます。また法令上の制限（用途地域外の場合も含む建築基準法・各種規制）も説明対象です。',"kaisetsu":{"topic": "重要事項説明：宅建士が説明・売主への交付は不要・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主への交付義務はありません。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能です。", "example": ""}, "reason": {"text": "土壌汚染対策法に基づく土壌汚染状況調査の実施の有無およびその内容は重要事項として説明しなければなりません（宅建業法35条1項14号・施行規則16条の4の3等）。過去の工場使用等により汚染の可能性がある場合は特に重要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "用途地域の指定がない区域は重要事項説明の対象外", "reason": "用途地域の指定の有無に関わらず重要事項説明は必要です（宅建業法35条1項）。用途地域がない場合はその旨を記載します。", "caution": ""}, {"label": "騒音・振動については宅建業法に基づく説明義務はなく任意", "reason": "隣接地の工場による騒音・振動は物件の状況として重要事項説明に含めることが求められます（宅建業法35条1項2号等の趣旨）。", "caution": ""}, {"label": "土壌汚染の可能性は確認できていない以上記載不要", "reason": "土壌汚染状況調査が実施されている場合はその結果の記載が必要です（宅建業法施行規則16条の4の3等）。調査がない場合でも告知義務が問われる場合があります。", "caution": ""}], "summary": {"head": ["土壌汚染関連の重要事項", "内容"], "rows": [["土壌汚染状況調査の実施", "実施の有無・調査結果を記載"], ["過去の工場使用", "汚染の可能性を説明することが求められる"], ["未調査の場合", "調査なしの旨を記載（隠蔽は不可）"]]}}},
  {id:10861,unit:'l_baikai',level:3,field:'law',text:'宅建業者AはBから依頼を受け、専属専任媒介契約を締結して、B所有のマンション（専有部分80m2）の売却活動を行っている。契約締結から3週間が経過したが、Aはレインズへの登録もせず、Bへの業務報告も一切行っていない。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['専属専任媒介契約は一般媒介と異なる規制はなく、Aは特に義務を負わない','専属専任媒介契約ではレインズへの登録は休業日を除く5日以内・依頼者への報告は1週間に1回以上の義務があり、3週間経過してもこれらを行っていないAは宅建業法違反の状態にある','専属専任媒介契約のレインズ登録期限は7日以内（休業日除く）である','専属専任媒介契約の報告義務は2週間に1回以上でよい'],ans:1,exp:'専属専任媒介契約では、指定流通機構（レインズ）への登録は媒介契約締結の日から5日以内（休業日を除く）、依頼者への業務報告は1週間に1回以上が義務付けられています（宅建業法34条の2第5項・6項・9項）。専任媒介は7日以内・2週間に1回以上です。Aはいずれも違反しており、指示処分等の行政処分の対象となります。',"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任媒介の有効期間の上限は3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。専任は7日以内、専属専任は5日以内にレインズ登録が必要。業務報告は専任2週間に1回、専属専任1週間に1回。", "example": ""}, "reason": {"text": "専属専任媒介契約では①レインズへの登録は5日以内（休業日除く・宅建業法34条の2第6項）、②業務報告は1週間に1回以上（同条10項）が義務です。3週間経過してこれらを行っていないのは明確な義務違反です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">一般</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専任</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専属専任</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己発見取引</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">レインズ登録</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務報告</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">なし</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間に1回</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1週間に1回</text></svg>", "choices": [{"label": "専属専任媒介契約は一般媒介と異なる規制はなくAは特に義務を負わない", "reason": "専属専任媒介はレインズ登録・業務報告等の義務があります（宅建業法34条の2第6項・10項）。「義務なし」は誤りです。", "caution": "専属専任媒介：5日以内のレインズ登録＋1週間1回の報告が義務。"}, {"label": "専属専任媒介契約のレインズ登録期限は7日以内（休業日除く）である", "reason": "7日以内は専任媒介のレインズ登録期限です（宅建業法34条の2第5項）。専属専任は5日以内です（同条6項）。", "caution": ""}, {"label": "専属専任媒介契約の報告義務は2週間に1回以上でよい", "reason": "2週間に1回以上は専任媒介の報告頻度です（宅建業法34条の2第9項）。専属専任は1週間に1回以上です（同条10項）。", "caution": ""}], "summary": {"head": ["専属専任媒介の義務違反", "内容"], "rows": [["レインズ登録（5日以内）", "3週間未登録→義務違反"], ["業務報告（1週間に1回）", "3週間報告なし→3回以上の違反"], ["処分", "指示処分・業務停止処分等の対象"]]}}},
  {id:10862,unit:'l_hoshu',level:3,field:'law',text:'宅建業者A（媒介業者）は、売主B（宅建業者でない）から依頼を受け、代金1億円の土地の売買を媒介し、買主Cとの間で売買契約を成立させた。Aは媒介報酬として、BからもCからも300万円（税別）ずつ受け取った。また、Aは広告宣伝費用として別途Bから50万円を受け取った。この場合に関する記述として宅建業法の規定（報酬告示）によれば正しいものはどれか。',opts:['代金1億円の媒介報酬の上限（税別）は一方から306万円（1億円×3%＋6万円）であり、300万円は上限内で適法','AがBとC双方から受け取る合計額は612万円（306万円×2）が上限であり、600万円は上限内で適法','AがBから別途受け取った広告宣伝費50万円は、依頼者（B）の特別の依頼に基づかない限り報酬の上限とは別に受け取ることはできない','代金が1億円を超えるため報酬計算は400万円超の部分に1%を適用する'],ans:2,exp:'報酬告示に基づく媒介報酬の上限は代金×3%+6万円（200万円超400万円以下部分等の速算式）。1億円の場合：1億円×3%+6万円=306万円（税別）が一方からの上限。BとC双方から計612万円が上限。各300万円（計600万円）は上限内で適法。ただし広告宣伝費を別途受け取ることは原則として禁止されており（依頼者の特別依頼による実費を除く）、AがBから別途50万円を受け取ることは報酬告示違反となります。',"kaisetsu":{"topic": "報酬：売買は代金×3%+6万（400万超）・賃貸は借賃1か月・上限超過は不可", "basis": {"text": "売買媒介報酬（400万超）の一方からの上限は代金×3%+6万円（税別）。双方合計は一方上限×2。賃貸媒介（居住用・非居住用とも）は借賃1か月分。依頼者の承諾があっても上限超過は不可。", "example": ""}, "reason": {"text": "広告宣伝費等の実費は、依頼者の特別の依頼（通常の広告以上の宣伝活動等）に基づく場合にのみ別途受け取れます（告示）。設問のAがBから別途50万円の広告宣伝費を受け取ったことは、特別の依頼に基づかない限り報酬の上限を超えて受け取ることになります（違法）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対象</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（400万超）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万（一方）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（200万以下）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸（双方合計）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借賃1か月分</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">低廉な空家等（800万円以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円まで（説明・合意要）</text></svg>", "choices": [{"label": "代金1億円の媒介報酬の上限（税別）は一方から306万円（1億円×3%＋6万円）であり300万円は上限内で適法", "reason": "1億円×3%＋6万円＝306万円（税別）であり、各自300万円は上限内です。ただし別途50万円の広告宣伝費が特別依頼に基づかない場合は違法です。", "caution": ""}, {"label": "AがBとC双方から受け取る合計額は612万円（306万円×2）が上限であり600万円は上限内で適法", "reason": "双方合計600万円は上限内ですが、別途50万円の広告宣伝費が問題です（特別依頼に基づかない限り違法）。", "caution": ""}, {"label": "代金が1億円を超えるため報酬計算は400万円超の部分に1%を適用する", "reason": "1%という料率はありません（告示）。400万円超の部分（速算式で代金全体に）は3%＋6万円で計算します。", "caution": ""}], "summary": {"head": ["設問の報酬適法性", "内容"], "rows": [["Bから300万円・Cから300万円", "適法（各自306万円以内）"], ["Bから別途50万円の広告宣伝費", "特別依頼に基づかない限り違法"], ["特別の依頼", "依頼者が特別に依頼した広告等（承諾が必要）"]]}}},
  {id:10863,unit:'k_toshi',level:3,field:'limit',text:'AはF市（都市計画区域内・市街化調整区域）に土地を所有しており、この土地に自己の住宅を建築しようとしている。この場合に関する記述として都市計画法の規定によれば正しいものはどれか。',opts:['市街化調整区域では一切の建築が禁止されている','市街化調整区域では原則として開発行為および建築が制限されているが、一定の建築物（農家住宅・公益上必要な建築物等）については開発許可なしに建築できる場合がある','市街化調整区域内の自己用住宅は常に開発許可が不要','市街化調整区域では10年間の猶予後に建築が認められる'],ans:1,exp:'市街化調整区域は市街化を抑制する区域であり、原則として開発行為および建築が制限されます（都市計画法43条）。ただし農業・林業・漁業を営む者の住宅（農家住宅等）や公益上必要な建築物等については開発許可なしに建築できる例外があります（都市計画法29条1項2号・3号、43条1項等）。一般の自己用住宅は原則として開発許可が必要です。',"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域での1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は市街化調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "市街化調整区域では原則として開発・建築が制限されますが、例外として農林漁業者の住宅・農業用施設（都市計画法29条1項2号・43条1項1号）・公益上必要な建築物等は許可不要で建築できます。一般住宅には開発許可が必要な場合があります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化する区域</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可基準</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "市街化調整区域では一切の建築が禁止されている", "reason": "農林漁業用施設・公益施設等は建築できます（都市計画法43条1項）。「一切禁止」は誤りです。", "caution": "市街化調整区域：原則制限あり。農林漁業用施設等は例外的に可（都市計画法43条1項）。"}, {"label": "市街化調整区域内の自己用住宅は常に開発許可が不要", "reason": "農林漁業者以外の一般住宅は原則として開発許可が必要です（都市計画法29条・34条）。「常に不要」は誤りです。", "caution": ""}, {"label": "市街化調整区域では10年間の猶予後に建築が認められる", "reason": "10年間の猶予という制度はありません（都市計画法29条・43条）。", "caution": ""}], "summary": {"head": ["市街化調整区域での建築（都市計画法43条）", "内容"], "rows": [["農林漁業者の住宅・農業用施設", "許可不要"], ["公益上必要な建築物", "許可不要"], ["一般住宅", "開発許可または建築許可が必要"], ["制限の趣旨", "市街化調整区域の無秩序な開発防止"]]}}},
  {id:10864,unit:'k_kenchiku',level:3,field:'limit',text:'Aはある宅地（第二種低層住居専用地域・建ぺい率50%・容積率100%・敷地面積300m2・前面道路幅員5m）に次の建築物を計画している：木造2階建て・延べ面積250m2・建築面積130m2。この計画について建築基準法の規定によれば正しいものはどれか。',opts:['建築面積130m2÷敷地面積300m2＝43.3%<50%で建ぺい率はクリア。延べ面積250m2÷300m2＝83.3%<100%で容積率もクリア。前面道路5m×4/10=200%>100%なので指定容積率100%が適用。この計画は建ぺい率・容積率ともに適法','建ぺい率は50%が上限で130m2は超えているため違反','容積率は前面道路5m×4/10=200%が適用されるため250m2は超過','第二種低層住居専用地域では2階建て以上の建築物は建築できない'],ans:0,exp:'建ぺい率：130m2÷300m2≒43.3%＜50%→適法。容積率：前面道路幅員5m×4/10=200%と指定容積率100%を比較し小さい方（100%）が適用。延べ面積250m2÷300m2≒83.3%＜100%→適法。第二種低層住居専用地域では2階建ての木造住宅は建築可能です。この計画は適法です。',"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・道路斜線・用途制限", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。用途地域ごとに建築物の制限があります。", "example": ""}, "reason": {"text": "建ぺい率130÷300≒43.3%<50%で適法。容積率は前面道路5m×4/10=200%と指定容積率100%を比較して小さい方（100%）が適用される。延べ面積250÷300≒83.3%<100%で適法。計画は建ぺい率・容積率ともに適法です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">第1種低層</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">学校は建築可</text></svg>", "choices": [{"label": "建ぺい率は50%が上限で130m2は超えているため違反", "reason": "建ぺい率130÷300=43.3%<50%なので適法です。「超えている」は誤りです。", "caution": "建ぺい率=建築面積÷敷地面積=130÷300≒43.3%<50%（適法）。"}, {"label": "容積率は前面道路5m×4/10=200%が適用されるため250m2は超過", "reason": "前面道路5m×4/10=200%と指定容積率100%を比較して小さい方（100%）が適用されます。250÷300≒83.3%<100%で適法です。", "caution": ""}, {"label": "第二種低層住居専用地域では2階建て以上の建築物は建築できない", "reason": "第二種低層住居専用地域では高さ制限（10mまたは12m）はありますが、2階建て以上を禁止する規定はありません（建築基準法別表第二）。", "caution": ""}], "summary": {"head": ["設問の計算（第二種低層住居専用地域）", "判定"], "rows": [["建ぺい率", "130÷300≒43.3%<50%→適法"], ["容積率（道路幅員）", "5m×4/10=200%"], ["容積率（指定）", "100%"], ["適用容積率", "min(200%, 100%)=100%"], ["延べ面積", "250÷300≒83.3%<100%→適法"]]}}},
  {id:10865,unit:'k_nochi',level:3,field:'limit',text:'農業を営むAは、市街化調整区域内の農地（田・面積3000m2）をBに対して売却しようとしている。BはこのAの農地で農業を営む意思がある。また別途、AはC（農業者でない）に対しても同じ農地の一部（500m2）を太陽光発電設備の設置のため売却することを検討している。この場合に関する記述として農地法の規定によれば正しいものはどれか。',opts:['農業者間での農地の売買（農地法3条）は、農業委員会の許可なく自由に行える','BへのAの農地売買（農地法3条：権利移動）は農業委員会の許可が必要','太陽光発電設備のためのCへの売却は農地法の適用を受けない','市街化調整区域内の農地の転用には都道府県知事の許可は不要'],ans:1,exp:'農地の権利移動（売買・賃貸借等）は農業委員会の許可が必要です（農地法3条）。農業者間の売買であっても許可が必要です。太陽光発電設備のための農地転用を伴う売買（農地法5条）は都道府県知事の許可が必要です（4ha超は農林水産大臣）。市街化区域内なら農業委員会への届出のみとなりますが、本問は市街化調整区域なので許可が必要です。',"kaisetsu":{"topic": "農地法：3条は農業委員会・4条・5条は都道府県知事・市街化区域は届出のみ", "basis": {"text": "農地法3条（権利移動・農地→農地）の許可権者は農業委員会。4条（自己転用）・5条（転用目的の権利移動）は都道府県知事等。市街化区域内の農地転用（4・5条）は農業委員会への届出のみでOK。相続は許可不要・届出3か月以内。", "example": ""}, "reason": {"text": "農業者間でも農地を農地のまま売買する場合は農業委員会の許可が必要です（農地法3条1項）。農業者同士だから許可不要という例外はありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">市街化区域</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">特例なし</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text></svg>", "choices": [{"label": "農業者間での農地の売買（農地法3条）は農業委員会の許可なく自由に行える", "reason": "農業者間であっても農業委員会の許可が必要です（農地法3条1項）。", "caution": "農業者間の農地売買も農業委員会の許可が必要（農地法3条1項）。"}, {"label": "太陽光発電設備のためのCへの売却は農地法の適用を受けない", "reason": "太陽光発電は農業用施設ではなく農地法4条・5条が適用されます。「適用外」は誤りです。", "caution": ""}, {"label": "市街化調整区域内の農地の転用には都道府県知事の許可は不要", "reason": "市街化調整区域内の農地の転用には都道府県知事の許可が必要です（農地法4条1項）。「不要」は誤りです。", "caution": ""}], "summary": {"head": ["農地法3条（農地のまま権利移動）", "内容"], "rows": [["対象", "農地を農地のまま権利移動する場合"], ["許可権者", "農業委員会（農地法3条1項）"], ["農業者間", "許可が必要（例外なし）"]]}}},
  {id:10866,unit:'t_joto',level:3,field:'tax',text:'Aは10年前に2000万円で購入した居住用マンション（所有期間10年2か月）を3500万円で売却した。取得費用（仲介手数料等含む）は2100万円、譲渡費用は130万円であった。AはこのマンションをB（Aの母）に売却した。この場合に関する記述として租税特別措置法の規定によれば正しいものはどれか。',opts:['居住用財産の3000万円特別控除の特例はAの母Bへの売却でも適用できる','居住用財産の3000万円特別控除は配偶者・直系血族（子・親）・生計を一にする親族等への売却には適用できないため、Aの母Bへの売却には適用できない','所有期間が10年を超えているため3000万円控除は不要で10年超軽減税率のみ適用できる','Aの母Bに売却した場合は消費税の課税対象となる'],ans:1,exp:'居住用財産の3000万円特別控除（租税特別措置法35条）は、譲渡先が配偶者・直系血族（父母・祖父母・子・孫等）・生計を一にする親族・内縁関係者等への売却には適用できません（同法35条2項）。AがAの母Bに売却した場合は直系血族への売却に該当するため3000万円控除は適用できません。',"kaisetsu":{"topic": "譲渡所得：分離課税・長期は20%・3,000万円控除は3年に1回", "basis": {"text": "土地・建物の譲渡所得は分離課税（申告分離課税）。長期（5年超）の税率は合計20%（所得税15%+住民税5%）。短期（5年以下）は39%（所得税30%+住民税9%）。3,000万円特別控除は前年・前々年に適用があれば使えません（3年に1回）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">譲渡所得のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税方式</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">分離課税</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">長期（5年超）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計20%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">短期（5年以下）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計39%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3,000万円控除</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年に1回の制限</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10867,unit:'t_inshi',level:3,field:'tax',text:'AはBから土地（売買代金1億5000万円）を購入した。AB間の土地の売買契約書（不動産売買に関する契約書）に記載された金額は1億5000万円である。この土地の売買契約書に貼付すべき収入印紙の金額として印紙税法の規定によれば正しいものはどれか。',opts:['記載金額が1億5000万円のため印紙税は15万円（1億5000万円×0.1%）','1億円超5億円以下の不動産売買契約書の印紙税額は6万円（軽減税率適用後の2024年3月31日まで）','1億円超5億円以下の不動産売買契約書の本則税率による印紙税額は10万円','1億5000万円の契約書は非課税'],ans:1,exp:'不動産の譲渡に関する契約書（第1号文書）の印紙税は記載金額によって異なります。1億円超5億円以下の場合、本則税率では10万円ですが、軽減措置（租税特別措置法91条）により2027年3月31日までは6万円です。本問の契約書（1億5000万円）は1億円超5億円以下に該当するため軽減税率適用後6万円の印紙税が必要です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10868,unit:'r_ishi',level:3,field:'rights',text:'AはBから「この土地は駅前再開発の計画地で土地価格が必ず上がる」と聞かされて甲土地を2000万円で購入した。しかし実際は再開発の計画は存在しなかった。ところがBもAから聞いて信じていただけで、Bは嘘をついたわけではなかった（Bも虚偽の情報をCから聞き込んでいた）。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['Bに故意がないので詐欺は成立せず、AはBとの契約を取り消せない','AはBとの売買契約について錯誤（民法95条）を主張できる可能性がある。重要な事項（土地の価値に直結する事情）についての錯誤であり、Aが錯誤に陥ったことについてAに重大な過失がなければ取り消しを主張できる','Aは錯誤を主張できるが、錯誤取消しは詐欺と異なり善意の第三者に対抗できない','動機の錯誤は一切考慮されない'],ans:1,exp:'Bに故意がなければ詐欺（民法96条）は成立しません。しかしAは動機の錯誤（民法95条1項2号）を主張できます。動機が表示されており（再開発計画の存在）かつその錯誤がなければAが契約を締結しなかったと認められる場合で、Aに重大な過失がなければ取り消せます（民法95条3項）。',"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "意思表示の瑕疵には詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失の第三者は保護）・通謀虚偽表示（無効・善意の第三者は保護）があります。", "example": ""}, "reason": {"text": "錯誤（民法95条）は詐欺と異なり、相手方の故意を要件としません。重要な事項について表意者に錯誤があり、かつその錯誤が法律行為の内容となっていれば取消しが認められる場合があります。動機の錯誤の場合、動機が表示されて法律行為の内容となったことが必要です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "Bに故意がないので詐欺は成立せず、AはBとの契約を取り消せない", "reason": "詐欺（96条）は成立しませんが、錯誤（95条）による取消しを検討できます。「取り消せない」は誤りで、錯誤を主張できる可能性があります。", "caution": "詐欺が成立しなくても錯誤取消しが認められる場合があります。"}, {"label": "Aは錯誤を主張できるが、錯誤取消しは詐欺と異なり善意の第三者に対抗できない", "reason": "錯誤取消しと詐欺取消しの第三者保護の違いは判例上明確に確立されていません。設問の状況では第三者の問題は関係ありません。", "caution": ""}, {"label": "動機の錯誤は一切考慮されない", "reason": "動機の錯誤も動機が表示されて法律行為の内容となった場合は取消しの対象となります（民法95条2項）。「一切考慮されない」は誤りです。", "caution": ""}], "summary": {"head": ["錯誤の種類", "取消しの可否", "条件"], "rows": [["法律行為の内容の錯誤", "可", "重要な錯誤、表意者の重過失なし"], ["動機の錯誤", "条件付きで可", "動機が表示・法律行為の内容となった場合"], ["軽微な錯誤", "不可", "—"]]}}},
  {id:10869,unit:'r_baibai',level:3,field:'rights',text:'AはBに対して甲建物（マンション1室・中古）を売却した。引渡し後2か月で、Aが売買前から知っていた雨漏りが発生した。BはAに対して修理費用（150万円）の支払いを求めるとともに、雨漏りがあったことを知っていれば200万円安い価格でしか買わなかったとして、代金の一部減額も求めている。Aは「契約書に現状有姿で引き渡す旨が明記されており責任は負わない」と主張している。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['現状有姿特約がある以上Aは一切の責任を負わない','Aが売買前から雨漏りを知っていたにもかかわらずBに告げなかった場合は免責特約の効力が及ばず、AはBの追完請求（修理費用150万円相当の追完）および代金減額請求に応じなければならない','BはAに対して修理費用（追完請求）または代金減額のどちらか一方しか請求できない','Aが雨漏りを知っていても、現状有姿特約がある限りBは契約を解除できない'],ans:1,exp:'売主が知りながら告げなかった不適合については、現状有姿特約等の免責特約の効力が及びません（民法572条）。BはAに対して追完請求（修理）および代金減額請求の両方を選択的・累積的に請求できます（民法562条・563条）。重大な契約不適合の場合は解除・損害賠償も請求できます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "売主が不適合を知りながら告げなかった場合は免責特約（現状有姿特約）の効力が及びません（民法572条）。AはBの追完請求（修理費用相当）と代金減額請求に応じる義務があります。追完と代金減額は並行して請求できます（買主はどちらを選択してもよい）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "現状有姿特約がある以上Aは一切の責任を負わない", "reason": "売主が知りながら告げなかった場合は免責特約が及びません（民法572条）。", "caution": ""}, {"label": "BはAに修理費用または代金減額のどちらか一方しか請求できない", "reason": "追完請求と代金減額請求は競合して行使できます（民法562条・563条）。「どちらか一方」という制限はありません。", "caution": ""}, {"label": "Aが雨漏りを知っていても現状有姿特約があれば解除できない", "reason": "知りながら告げなかった場合は免責特約が及ばず（民法572条）、解除も可能です（民法564条・541条等）。", "caution": ""}], "summary": {"head": ["売主の告知義務違反", "内容"], "rows": [["根拠", "民法572条（知りながら告げなかった場合の免責無効）"], ["買主の手段", "追完・代金減額・損害賠償・解除すべて可"], ["追完と減額の関係", "並行して請求可能"]]}}},
  {id:10870,unit:'l_menkyo',level:3,field:'law',text:'宅建業者A（法人・甲県知事免許）の代表取締役Bが、宅建業とは関係のない交通事故で拘禁刑刑（執行猶予なし）の確定判決を受けた。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['刑事事件が宅建業と無関係であるため、Aの免許への影響はない','Bが拘禁刑以上の刑に処せられ刑の執行が終わっていない場合、Bは欠格事由に該当し、法人Aの役員であるBが欠格事由に該当する場合はAの免許も取り消される（または新規取得ができない）','BがA社を退任すれば免許への影響はなくなる','拘禁刑刑であっても執行猶予がついていないため、刑期終了から3年が欠格期間となる'],ans:1,exp:'宅建業者の役員が拘禁刑以上の刑に処された場合（宅建業法5条1項5号）、その役員を有する法人は免許欠格事由に該当し（同法5条1項12号）、免許が取り消されます（同法66条1項3号）。刑の執行を終わり・執行を受けることがなくなった日から5年間は欠格期間です（同法5条1項5号）。BがA社を退任してもAの過去の欠格事由は解消されません（退任前の欠格が問題）。',"kaisetsu":{"topic": "宅建業の免許：知事・大臣免許の区別・有効期間5年・欠格事由", "basis": {"text": "1都道府県のみ→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間です。", "example": ""}, "reason": {"text": "宅建業者の役員が拘禁刑以上の刑に処せられた場合（宅建業と無関係でも）、その役員は欠格事由に該当し（宅建業法5条1項5号）、役員が欠格事由に該当する法人も免許を受けることができません（同条1項1号）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（拘禁刑以上・特定罰金等）</text></svg>", "choices": [{"label": "刑事事件が宅建業と無関係であるためAの免許への影響はない", "reason": "宅建業と無関係の犯罪（交通事故等）でも拘禁刑以上の刑は欠格事由です（宅建業法5条1項5号）。「無関係だから影響なし」は誤りです。", "caution": "拘禁刑以上の刑：宅建業と無関係でも欠格事由（宅建業法5条1項5号）。"}, {"label": "BがA社を退任すれば免許への影響はなくなる", "reason": "Bが退任することで法人Aの欠格事由は解消されますが、Bは個人として5年間欠格事由に該当します。また退任の届出等が必要です。", "caution": ""}, {"label": "拘禁刑刑であっても執行猶予がついていないため刑期終了から3年が欠格期間となる", "reason": "欠格期間は刑の執行終了等から5年です（宅建業法5条1項5号）。3年ではありません。", "caution": "欠格期間＝5年（宅建業法5条1項5号）。3年ではない。"}], "summary": {"head": ["役員の欠格事由と法人の免許", "内容"], "rows": [["役員が欠格事由に該当", "法人も免許を受けられない（宅建業法5条1項1号）"], ["欠格期間", "拘禁刑以上の刑：執行終了等から5年"], ["宅建業と無関係", "犯罪の種類・動機は問わない"], ["対応", "役員の退任→欠格事由の解消・届出が必要"]]}}},
  {id:10871,unit:'r_jiko',level:3,field:'rights',text:'AはBに対して2020年4月1日に請負代金500万円の債権（弁済期：2020年10月1日）を有している。Bは2021年4月1日にAに対して「来月中には必ず支払う」と述べた（口頭での約束）。その後Bからの支払いはなく、Aは2024年5月1日に訴訟を提起した。この場合に関する記続として民法の規定によれば正しいものはどれか。',opts:['請負代金債権の消滅時効は3年（民法166条1項1号）であり、弁済期2020年10月1日から3年後の2023年10月1日に時効完成。Aの2024年5月1日の提訴は時効完成後であり消滅時効が援用されると請求できない','Bが2021年4月1日に口頭で「来月中には支払う」と述べたことは債務の承認（時効の更新）に当たり、その時から新たに消滅時効が進行する。更新後の時効は2021年4月1日から3年後の2024年4月1日に完成し、2024年5月1日の提訴は時効完成後となる','Bが口頭で支払いを約束しても時効の更新にはならず、書面による承認が必要','請負代金債権の消滅時効は5年である'],ans:1,exp:'請負代金債権は主観的起算点（権利を行使できることを知った時）から5年または客観的起算点（権利行使できる時）から10年の短い方で消滅します（民法166条1項）。弁済期2020年10月1日を権利行使できる時とすると、主観的には弁済期に認識しているので5年後の2025年10月1日に時効完成（通常）。しかしBの口頭承認（2021年4月1日）は「承認」として時効を更新します（民法152条）。更新後2021年4月1日から5年後の2026年4月1日が新たな時効完成日となり、2024年5月1日の提訴は時効完成前で有効です。',"kaisetsu":{"topic": "消滅時効：知った時から5年または行使可能時から10年", "basis": {"text": "一般の債権の消滅時効は「権利行使できると知った時から5年」または「権利行使できる時から10年」のいずれか早い方で完成します（民法166条1項）。時効は援用して初めて効力が発生します（民法145条）。", "example": ""}, "reason": {"text": "2020年改正後の消滅時効は「権利を行使できると知った時から5年」が適用されます（民法166条1項1号）。債務者の口頭による「来月中には支払う」という発言は債務の承認として時効更新の効力を持ちます（民法152条1項）。承認後は新たに5年の時効が進行します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">時効期間</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人の生命・身体への損害</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年または20年</text></svg>", "choices": [{"label": "時効は2023年10月1日に完成し請求できない", "reason": "Bが2021年4月1日に承認（口頭での支払約束）をしたため、その時点で時効が更新されます（民法152条1項）。2023年10月1日時効完成の前提が崩れます。", "caution": "承認により時効が更新→新たにゼロから時効進行。承認を見落とさないこと。"}, {"label": "提訴は時効完成後であり請求できない", "reason": "Bの2021年4月1日の承認により時効が更新され、そこから新たに5年の時効が進行します。2026年4月1日まで時効は完成せず、2024年5月1日の提訴は時効完成前です。", "caution": ""}, {"label": "口頭の約束は承認に当たらない", "reason": "承認は書面でなくても口頭でもできます（民法152条1項に方式規定なし）。Bの「来月中には支払う」という発言は債務の存在を認めた承認として有効です。", "caution": "承認に書面は不要。口頭でも有効です（民法152条1項）。"}], "summary": {"head": ["時効の計算（設問の場合）", "内容"], "rows": [["時効の起算点", "弁済期2020年10月1日（権利行使可能時）"], ["Bの承認", "2021年4月1日→時効更新（民法152条）"], ["更新後の時効期間", "5年（民法166条1項1号）"], ["新たな時効完成", "2026年4月1日"], ["2024年5月1日の提訴", "時効完成前→請求可能"]]}}},
  {id:10872,unit:'l_37jo',level:3,field:'law',text:'宅建業者Aが媒介した建物の売買契約において、売主Bと買主C（宅建業者でない）の間で次の合意がなされた。①代金3000万円は手付金300万円と残金2700万円の2回払い、②引渡しは2025年4月1日、③建物の構造上の瑕疵について1年間の保証をBがCに付与する、④住宅ローン特約（審査不通過の場合に白紙解除）。37条書面の任意的記載事項に当たるものとして宅建業法の規定によれば正しいものはどれか。',opts:['引渡し時期（②）は任意的記載事項','代金の支払方法（①）は任意的記載事項','住宅ローン特約（④）は定めがある場合に記載する任意的記載事項','構造上の瑕疵の保証（③）は定めがある場合に記載する必要的記載事項'],ans:2,exp:'37条書面の必要的記載事項は、代金額・支払時期・方法（①）、引渡し時期（②）、移転登記申請時期等です。住宅ローン特約（融資の利用）（④）は定めがある場合に記載する任意的記載事項（宅建業法37条1項8号）です。建物の構造耐力上主要な部分等の瑕疵を担保すべき責任の履行措置（③）は任意的記載事項（同法37条1項11号）です。',"kaisetsu":{"topic": "37条書面：全取引で交付・記名（押印不要）・移転登記申請時期は必要的記載事項", "basis": {"text": "37条書面は売買・交換・賃貸借の全取引で契約の双方当事者に交付が義務（宅建業法37条）。引渡し時期・移転登記申請時期は必要的記載事項。2021年改正で押印は不要になり記名のみで足ります。", "example": ""}, "reason": {"text": "37条書面の任意的記載事項（定めがある場合に記載）はローン特約・危険負担・瑕疵担保等の定めです（宅建業法37条1項7号〜11号）。引渡し時期・代金の支払方法は必要的記載事項、瑕疵担保の定めは任意的記載事項です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付義務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全取引・双方当事者</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡時期・移転登記申請時期等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要）</text></svg>", "choices": [{"label": "引渡し時期（②）は任意的記載事項", "reason": "引渡し時期は必要的記載事項です（宅建業法37条1項4号）。任意的ではありません。", "caution": "引渡し時期：必要的記載事項（宅建業法37条1項4号）。"}, {"label": "代金の支払方法（①）は任意的記載事項", "reason": "代金の支払方法は必要的記載事項です（宅建業法37条1項2号）。任意的ではありません。", "caution": ""}, {"label": "構造上の瑕疵の保証（③）は定めがある場合に記載する必要的記載事項", "reason": "瑕疵担保（契約不適合責任）の定めは任意的記載事項です（宅建業法37条1項11号）。必要的ではありません。", "caution": ""}], "summary": {"head": ["設問の各事項の性質", "必要的か任意的か"], "rows": [["代金・支払方法（①）", "必要的（宅建業法37条1項2号）"], ["引渡し時期（②）", "必要的（宅建業法37条1項4号）"], ["瑕疵保証の定め（③）", "任意的（宅建業法37条1項11号）"], ["ローン特約（④）", "任意的（宅建業法37条1項8号）"]]}}},
  {id:10873,unit:'r_sorin',level:3,field:'rights',text:'AとBは隣接する土地を所有しており、両土地の境界には古いブロック塀がある。このブロック塀がどちらの土地に属するか不明であり、土地台帳にも記録がない。Aはこのブロック塀が老朽化して危険であるとして解体を希望しているが、Bは反対している。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['所有者不明の場合、Aが単独でブロック塀を解体できる','境界線上の工作物は相隣者の共有と推定される（民法229条）。Bの反対がある以上Aは単独で解体できないが、老朽化で危険な場合は自己の費用で保存行為として解体できる','ブロック塀は隣地所有者Bのものであるため、Aは手出しできない','境界の工作物は市区町村が管理する'],ans:1,exp:'境界線上に設けられた境界標・囲障・障壁・溝・堀は相隣者の共有と推定されます（民法229条）。共有物の変更（解体）には共有者全員の同意が必要ですが（民法251条）、保存行為は単独でできます（民法252条5項）。老朽化して危険な状態での解体が「保存行為」といえるかは状況による判断が必要で、裁判所に解体の許可を求めることも選択肢です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "境界線上の工作物は相隣者の共有と推定されます（民法229条）。共有物の変更行為（解体等）は全員の同意が必要ですが（民法251条1項）、老朽化で危険な場合は保存行為（安全確保）として自己の費用で対応できる場合があります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "所有者不明の場合Aが単独でブロック塀を解体できる", "reason": "境界線上の工作物は相隣者の共有と推定されます（民法229条）。共有物の解体は変更行為であり全員の同意（Bの同意）が原則必要です。", "caution": "境界線上の工作物＝相隣者の共有（民法229条）。解体には原則全員同意が必要。"}, {"label": "ブロック塀は隣地所有者Bのものであるため、Aは手出しできない", "reason": "境界線上の工作物は共有と推定されます（民法229条）。Bだけのものではありません。", "caution": ""}, {"label": "境界の工作物は市区町村が管理する", "reason": "境界線上の工作物の管理は相隣者（A・B）が行います（民法229条・251条等）。市区町村ではありません。", "caution": ""}], "summary": {"head": ["境界線上の工作物（民法229条）", "内容"], "rows": [["推定", "境界線上の工作物は相隣者の共有と推定"], ["管理", "共有物の管理規定（民法251条・252条）が適用"], ["解体", "変更行為として全員同意が原則"], ["危険な場合", "保存行為（安全確保）として対応可能"]]}}},
  {id:10874,unit:'k_kukaku',level:3,field:'limit',text:'土地区画整理事業（組合施行）が行われている地区内に土地を所有するAは、施行区域内の土地を第三者Bに売却したいと考えている。この場合に関する記述として土地区画整理法の規定によれば正しいものはどれか。',opts:['土地区画整理事業の施行区域内の土地は売買が禁止されている','施行区域内の宅地の売買は自由にできるが、施行者（組合）への通知義務がある場合がある','土地区画整理事業の施行中であっても宅地の売買は原則として自由に行えるが、換地処分が完了するまでは仮換地が従前地の代わりに取引の対象となることが多い','施行区域内の土地の売買には土地区画整理審査委員会の許可が必要'],ans:2,exp:'土地区画整理事業の施行中であっても施行区域内の宅地の売買は原則として自由に行えます（土地区画整理法上の特別な許可制はない）。ただし仮換地が指定されている場合には、従前の宅地の権利とともに仮換地上の使用収益権も移転するため、実務では仮換地を対象として取引が行われます。宅建業者による媒介の場合は重要事項説明で区画整理の施行中である旨等の説明が必要です。',"kaisetsu":{"topic": "土地区画整理法：換地は公告翌日確定・仮換地は従前地使用不可・組合は2/3以上", "basis": {"text": "換地処分の公告翌日から換地が確定します（土地区画整理法104条）。仮換地の指定後は従前地を使用できなくなります（同法99条）。組合設立には土地所有者・借地権者の各2/3以上の同意が必要です。", "example": ""}, "reason": {"text": "土地区画整理事業の施行中であっても、施行区域内の宅地の売買は原則として自由に行えます（土地区画整理法76条等）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">土地区画整理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">換地の確定</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公告の翌日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮換地指定後</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従前地は使用不可（所有権は残る）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">組合設立</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各2/3以上の同意</text></svg>", "choices": [{"label": "土地区画整理事業の施行区域内の土地は売買が禁止されている", "reason": "施行中でも売買は原則自由です（土地区画整理法76条等）。", "caution": "施行区域内の土地：売買は原則自由（土地区画整理法76条等）。"}, {"label": "施行区域内の宅地の売買は自由にできるが施行者（組合）への通知義務がある", "reason": "施行者への通知義務は法定されていません（土地区画整理法76条等）。", "caution": ""}, {"label": "施行区域内の土地の売買には土地区画整理審査委員会の許可が必要", "reason": "許可は不要です（土地区画整理法76条等）。", "caution": ""}], "summary": {"head": ["施行区域内の土地売買", "内容"], "rows": [["売買の可否", "原則自由"], ["制限", "工事完了公告前の建築は施行者の承認が必要"]]}}},
  {id:10875,unit:'t_kotei',level:3,field:'tax',text:'Aは甲市内に土地（固定資産税評価額5000万円・都市計画税評価額5000万円）と住宅（固定資産税評価額2000万円・小規模住宅用地（200m2以下）に該当）を所有している。甲市は固定資産税の標準税率1.4%・都市計画税の税率0.3%を採用している（市街化区域内）。固定資産税及び都市計画税の計算として正しいものはどれか。',opts:['固定資産税：(5000万円+2000万円)×1.4%=98万円、都市計画税：(5000万円+2000万円)×0.3%=21万円','固定資産税：土地5000万円×1/6×1.4%+建物2000万円×1.4%=11.67万円+28万円=39.67万円、都市計画税：土地5000万円×1/3×0.3%+建物2000万円×0.3%=5万円+6万円=11万円','固定資産税の土地部分は評価額そのままに1.4%を乗じる','都市計画税は固定資産税評価額の2分の1に0.3%を乗じる'],ans:1,exp:'住宅用地の特例：小規模住宅用地（200m2以下）は固定資産税の課税標準が評価額の1/6、都市計画税の課税標準が評価額の1/3に軽減されます（地方税法349条の3の2等）。固定資産税：土地5000万円×1/6×1.4%＝約11.67万円、建物2000万円×1.4%＝28万円、合計約39.67万円。都市計画税：土地5000万円×1/3×0.3%＝5万円、建物2000万円×0.3%＝6万円、合計11万円。',"kaisetsu":{"topic": "固定資産税：市町村が課す地方税・賦課期日は1月1日・評価替えは3年ごと", "basis": {"text": "固定資産税は市町村（東京23区は都）が課す地方税です（地方税法343条）。賦課期日は毎年1月1日。評価替えは3年ごと（基準年度）。住宅用地の特例：200㎡以下は課税標準1/6、超過部分は1/3。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">固定資産税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市町村（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賦課期日</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">評価替え</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年ごと</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅用地（200㎡以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税標準1/6</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10876,unit:'r_dairi',level:3,field:'rights',text:'AはBに「A所有の土地を売る権限」を委任した。ところがBはこの代理権を利用して、Aに無断でCから金銭を借り入れA名義の借用書を作成した。BはAが金銭の借入れについての代理権を与えていないことを知っている。Cは「BはAから金銭借入れの代理権も与えられている」と信じ、信じることに正当な理由があった。この場合に関する記述として民法の規定及び判例によれば正しいものはどれか。',opts:['Bに土地売却の代理権しかないため、金銭借入れ行為は当然に無効であり、Aは借入れの責任を負わない','Bが土地売却の基本代理権を有しており、CがBに金銭借入れの代理権もあると信じたことに正当な理由があれば、民法110条の表見代理が成立し、AはCに対して借入れ債務を負う可能性がある','表見代理が成立するにはAの何らかの帰責行為が必要であり、単に代理権を与えただけでは足りない','CはBに対して無権代理人の責任（民法117条）のみを追及できる'],ans:1,exp:'民法110条の権限外行為の表見代理は、代理人が基本的な代理権（土地売却）を有し、相手方（C）が権限外の行為（金銭借入れ）の権限もあると信じたことに正当な理由がある場合に成立します。代理権を与えたこと自体がAの帰責事由となります。この場合AはCに対して借入れ債務を負います。',"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護する制度です。", "example": ""}, "reason": {"text": "民法110条の権限外行為の表見代理は、基本代理権（土地売却の代理権）があれば、それとは異なる行為（金銭借入れ）についても成立しえます（判例）。相手方の正当な信頼を保護するためです。基本代理権の範囲が異なっていても表見代理の成立は妨げられません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "金銭借入れ行為は当然に無効であり、Aは借入れの責任を負わない", "reason": "表見代理（民法110条）が成立する場合、本人Aは責任を負います。基本代理権と権限外行為の種類が異なっていても表見代理は成立しえます（判例）。", "caution": "基本代理権の種類≠権限外行為の種類でも表見代理が成立することがあります。"}, {"label": "表見代理が成立するにはAの何らかの帰責行為が必要であり、単に代理権を与えただけでは足りない", "reason": "民法110条の表見代理は基本代理権の存在と相手方の正当な信頼が要件です（判例）。「代理権を与えただけでは足りない」という追加要件はありません。代理権授与自体が本人の帰責事由と解されます。", "caution": ""}, {"label": "CはBに対して無権代理人の責任（民法117条）のみを追及できる", "reason": "表見代理が成立する場合、Cは本人Aに対して契約の履行を求めることができます。また表見代理を主張しない場合はBへの無権代理人責任追及も選択できます。「のみ」という限定は誤りです。", "caution": ""}], "summary": {"head": ["権限外行為の表見代理（民法110条）", "内容"], "rows": [["基本代理権", "何らかの代理権があれば足りる（異種の代理権でも可・判例）"], ["正当な理由", "相手方が代理権ありと信じることに客観的な正当性"], ["効果", "本人に契約効果帰属"], ["相手方の選択", "表見代理（本人責任）または無権代理人責任（民法117条）"]]}}},
  {id:10877,unit:'l_hosho',level:3,field:'law',text:'宅建業者A（保証協会の社員でない）は甲県知事免許を受け、主たる事務所1か所・従たる事務所2か所を有している。Aは宅建業法に従い営業保証金を供託している。Aとの取引により損害を受けたB（宅建業者でない）は、営業保証金から還付を受けようとしている。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['Bは損害額全額を無条件で還付してもらえる','営業保証金の還付を受けられる金額の上限はAが供託している営業保証金の総額（主たる事務所1000万円＋従たる事務所×500万円×2＝2000万円）が上限となる','営業保証金の還付請求は宅建業者もできる','還付を受けるには裁判所の確定判決が必要'],ans:1,exp:'営業保証金の還付（宅建業法27条）は宅建業に関する取引で生じた債権について宅建業者でない者が請求できます。還付を受けられる金額の上限は供託している営業保証金の総額（主たる事務所1000万円＋従たる事務所500万円×2か所＝計2000万円）です。還付を受けるには裁判上の確定判決等（確定判決・調停・和解等）が必要です（宅建業法27条2項）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "営業保証金から還付を受けられる上限は供託している営業保証金の総額です（宅建業法27条1項）。主たる事務所1000万円＋従たる事務所2か所×500万円＝2000万円が上限です。宅建業者は還付対象外で、損害額全額が無条件に補償されるわけではありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "Bは損害額全額を無条件で還付してもらえる", "reason": "還付は供託している営業保証金の総額が上限であり、損害額全額が無条件に補償されるわけではありません（宅建業法27条1項）。", "caution": ""}, {"label": "営業保証金の還付請求は宅建業者もできる", "reason": "還付請求できるのは宅建業者以外の者です（宅建業法27条1項）。宅建業者は対象外です。", "caution": "還付対象：宅建業者以外。宅建業者は除外（宅建業法27条1項）。"}, {"label": "還付を受けるには裁判所の確定判決が必要", "reason": "確定判決は必須ではありません（宅建業法27条1項）。損害を証明する書類等を供託所に提出します。", "caution": ""}], "summary": {"head": ["設問の営業保証金総額", "計算"], "rows": [["主たる事務所", "1000万円"], ["従たる事務所×2", "500万円×2＝1000万円"], ["合計", "2000万円（還付上限）"], ["還付対象", "Bのような宅建業者以外の者"]]}}},
  {id:10878,unit:'k_toshi',level:3,field:'limit',text:'AはG市（都市計画区域内・市街化区域・近隣商業地域）において、飲食店（延べ面積500m2）を建築しようとしている。建築にあたっての確認申請について建築基準法の規定によれば正しいものはどれか。',opts:['延べ面積500m2の建築物は規模が小さいため建築確認は不要','近隣商業地域内の建築物は規模にかかわらず建築確認は不要','飲食店は特殊建築物（建築基準法別表第一）に該当し、その用途に供する部分の床面積が200m2を超える場合は建築確認が必要。500m2は200m2を超えるため確認申請が必要','飲食店の建築確認は工事着工後に申請できる'],ans:2,exp:'飲食店は建築基準法別表第一（い）欄の特殊建築物（劇場・映画館・集会場・展示場・百貨店・マーケット・ホテル・旅館・飲食店等）に該当します。特殊建築物でその用途に供する部分の床面積が200m2を超えるものは、建築確認申請が必要です（建築基準法6条1項1号）。本問では500m2が200m2を超えるため確認申請が必要です。',"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域での1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は市街化調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "飲食店は特殊建築物（建築基準法別表第一）に該当し、用途に供する部分の床面積が200㎡を超える場合は建築確認が必要です（建築基準法6条1項1号）。500㎡は200㎡を超えるため確認申請が必要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化する区域</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可基準</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "延べ面積500m2の建築物は規模が小さいため建築確認は不要", "reason": "飲食店は特殊建築物であり、200㎡超の場合は確認申請が必要です（建築基準法6条1項1号）。500㎡は200㎡超のため必要です。", "caution": "飲食店（特殊建築物）：200㎡超なら建築確認必要（建築基準法6条1項1号）。"}, {"label": "近隣商業地域内の建築物は規模にかかわらず建築確認は不要", "reason": "用途地域の種類は建築確認の要否に直接関係しません（建築基準法6条1項）。建物の用途・規模・構造等で判断します。", "caution": ""}, {"label": "飲食店の建築確認は工事着工後に申請できる", "reason": "建築確認は工事着工前に申請・取得しなければなりません（建築基準法6条1項）。着工後は不可です。", "caution": ""}], "summary": {"head": ["特殊建築物の建築確認（建築基準法6条1項1号）", "内容"], "rows": [["対象", "劇場・映画館・飲食店・病院・ホテル等（別表第一）"], ["確認が必要な規模", "用途に供する床面積200㎡超"], ["申請時期", "工事着工前"], ["近隣商業地域等", "用途地域の種類は確認要否に直接関係しない"]]}}},
  {id:10879,unit:'r_kukku',level:3,field:'rights',text:'Aが所有する分譲マンション（専有部分）の下の階（Bが所有）の天井から水漏れが発生した。調査の結果、Aの専有部分内の給水管（専有部分に属する管）の亀裂が原因であることが判明した。Bの部屋の内装（壁・天井）の修復費用は50万円かかる。この場合に関する記述として民法・区分所有法の規定によれば正しいものはどれか。',opts:['専有部分内の配管の管理は管理組合の責任であり、Aは責任を負わない','Aの専有部分内の給水管の管理瑕疵によってBに損害を生じさせた場合、Aは不法行為（民法709条）または工作物責任（民法717条）に基づきBに対して損害賠償責任を負う','水漏れは自然現象であるためAは責任を負わない','管理費から修繕費50万円が支払われるため個人Aの負担はない'],ans:1,exp:'区分所有者は自己の専有部分を適切に管理する義務があります。専有部分内の給水管の亀裂（管理瑕疵）によって生じた損害に対して、Aは工作物責任（民法717条）または不法行為（民法709条）に基づきBに対して損害賠償責任を負います。共用部分に起因する損害の場合は管理組合が責任を負う場合もありますが、本問は専有部分内の問題です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "専有部分内の設備（給水管等）の管理は区分所有者の責任です。専有部分の管理瑕疵により他の区分所有者に損害を与えた場合は不法行為（民法709条）または工作物責任（民法717条）に基づく損害賠償責任を負います。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "専有部分内の配管の管理は管理組合の責任であり、Aは責任を負わない", "reason": "専有部分内の設備は各区分所有者が管理します。共用部分（共用の給水管幹線等）は管理組合の責任です。", "caution": "専有部分の設備＝区分所有者が管理・責任。共用部分の設備＝管理組合の責任。"}, {"label": "水漏れは自然現象であるためAは責任を負わない", "reason": "自然現象であっても区分所有者の管理義務（定期点検等）の懈怠がある場合は責任を負います（民法709条・717条）。", "caution": ""}, {"label": "管理費から修繕費50万円が支払われるため個人Aの負担はない", "reason": "専有部分の管理瑕疵による損害は管理費（組合の費用）ではなくAが個人で負担します。", "caution": ""}], "summary": {"head": ["区分所有と責任の所在", "内容"], "rows": [["専有部分内の設備（給水管等）", "区分所有者が管理・責任"], ["共用部分の設備（共用幹線等）", "管理組合が管理・責任"], ["損害発生時", "不法行為・工作物責任に基づく損害賠償"], ["区分の判断", "管理規約または竣工図書で確認"]]}}},
  {id:10880,unit:'t_toroku',level:3,field:'tax',text:'Aは相続によりB（父）から土地（固定資産税評価額3000万円）を取得した。この土地の相続登記（所有権移転登記）を申請する場合の登録免許税について正しいものはどれか。',opts:['相続による所有権移転登記の税率は2%（本則税率）であり、3000万円×2%＝60万円が登録免許税となる','相続による所有権移転登記の税率は0.4%であり、3000万円×0.4%＝12万円が登録免許税となる','相続登記は非課税であり登録免許税はかからない','固定資産税評価額ではなく売買価格を課税標準とする'],ans:1,exp:'相続（包括遺贈を含む）による所有権移転登記の登録免許税の税率は0.4%です（登録免許税法別表1）。課税標準は固定資産税評価額であり、3000万円×0.4%＝12万円が登録免許税となります。売買による所有権移転登記の本則税率は2%（住宅用家屋の軽減あり）とは異なります。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10881,unit:'r_saikensoron',level:3,field:'rights',text:'AはBに対して100万円の金銭消費貸借契約を締結し、貸し付けた。その後BはAに「代わりに商品券100万円分で返済したい」と申し出た。Aはこれに応じて商品券を受け取り、BとAは「これで債務は消えた」と合意した。しかし後日、Aは「やはり現金100万円を返せ」と請求してきた。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['金銭消費貸借は現金での返済しか認められず、商品券での弁済は無効','代物弁済（民法482条）により、BがAの同意を得て商品券（本来の債務と異なる給付）をもって弁済した場合、Bの債務は消滅する','代物弁済は当事者の合意だけでは足りず、公正証書が必要','Aが商品券を受け取っても、金銭債務は消滅しない'],ans:1,exp:'代物弁済（民法482条）は、債権者の同意を得て本来の給付に代えて他の給付をすることにより債務を消滅させる制度です。AがBの商品券100万円分での代物弁済に合意し受領した以上、BのAに対する金銭債務は消滅します。公正証書等の形式は不要です（合意と給付で成立）。',"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要です（民法446条2項）。連帯保証人には催告・検索の抗弁権がありません（民法454条）。債権譲渡の第三者対抗要件は確定日付ある証書による通知または承諾です（民法467条2項）。", "example": ""}, "reason": {"text": "代物弁済（民法482条）は債権者の承諾を得て本来の給付に代えて他の給付をすることで債務が消滅する制度です。当事者間の合意（債権者の承諾）で成立し、公正証書は不要です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相殺の要件</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">双方が同種の債権</text></svg>", "choices": [{"label": "金銭消費貸借は現金での返済しか認められず商品券での弁済は無効", "reason": "当事者の合意があれば代物弁済（民法482条）として本来の債務（金銭）とは異なる給付（商品券）で弁済できます。", "caution": "代物弁済（民法482条）＝債権者の同意を得て本来の債務と異なる給付で弁済可。"}, {"label": "代物弁済は当事者の合意だけでは足りず公正証書が必要", "reason": "代物弁済に公正証書は不要です（民法482条）。当事者の合意で成立します。", "caution": ""}, {"label": "Aが商品券を受け取っても金銭債務は消滅しない", "reason": "代物弁済（民法482条）が成立すれば金銭債務は消滅します。「消滅しない」は誤りです。", "caution": ""}], "summary": {"head": ["代物弁済（民法482条）", "内容"], "rows": [["意味", "本来の給付に代えて他の給付をすることで債務消滅"], ["要件", "債権者の承諾（合意）"], ["公正証書", "不要"], ["効果", "本来の債務が消滅"]]}}},
  {id:10882,unit:'l_takkenshi',level:3,field:'law',text:'宅建士Aは、宅建業者Bに勤務しており、自社物件の重要事項説明を行った。その際Aは宅建士証を携帯していたが、Cから宅建士証の提示を求められなかったため提示しなかった。また後日、Aは道路交通法違反（酒気帯び運転）により罰金刑に処せられた。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['宅建士証の提示は求められた場合にのみ必要であり、Aが求められずに提示しなかったことは適法','宅建士は重要事項の説明をする際には相手方から請求がなくても宅建士証を提示しなければならない','道路交通法違反（酒気帯び運転）による罰金刑は宅建士の登録消除事由にはならない','宅建士証の提示義務違反には罰則がない'],ans:1,exp:'宅建士は重要事項説明を行う際、相手方の請求がなくても宅建士証を提示しなければなりません（宅建業法35条4項）。提示なしでの説明は宅建業法違反です。道路交通法違反（酒気帯び運転）による罰金刑は、宅建業法に基づく取消・停止事由ではありませんが、拘禁刑以上の刑（執行猶予含む）に処された場合は登録消除事由となります（宅建業法18条1項3号）。罰金刑では直ちに登録消除にはなりません。',"kaisetsu":{"topic": "専任の宅建士：5人に1人以上・兼任不可・不足時は2週間以内に補充", "basis": {"text": "事務所には業務従事者5人に1人以上の専任宅建士が必要です（宅建業法31条の3）。専任宅建士は1社専属で複数業者の兼任は不可。不足時は2週間以内に補充が必要です。", "example": ""}, "reason": {"text": "宅建士は重要事項の説明をする際には、相手方から請求がなくても宅建士証を提示しなければなりません（宅建業法35条4項）。これは宅建士であることを証明し、取引の安全を確保するための義務です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">専任宅建士のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">設置基準</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5人に1人以上（主従同じ）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">兼任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可（1社専属）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不足補充</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間以内</text></svg>", "choices": [{"label": "宅建士証の提示は求められた場合にのみ必要であり提示しなかったことは適法", "reason": "重要事項説明の際は求められなくても提示義務があります（宅建業法35条4項）。求められた場合のみという制限はありません。", "caution": "重要事項説明時：請求なくても提示義務（宅建業法35条4項）。"}, {"label": "道路交通法違反（酒気帯び運転）による罰金刑は宅建士の登録消除事由にはならない", "reason": "道路交通法違反による罰金刑は宅建士の欠格事由（宅建業法18条1項5号）に規定された犯罪類型（宅建業法・詐欺・背任等）ではないため、通常は登録消除事由にはなりません。ただし有罪確定後の宅建士の信頼性の問題として行政上の判断があります。", "caution": ""}, {"label": "宅建士証の提示義務違反には罰則がない", "reason": "提示義務違反には10万円以下の過料が科される場合があります（宅建業法83条1項5号・6号等参照）。「罰則なし」は誤りです。", "caution": ""}], "summary": {"head": ["宅建士証の提示義務", "根拠"], "rows": [["重要事項説明時", "請求なくても提示必須（宅建業法35条4項）"], ["業務上の求め", "相手方から請求を受けた場合は提示必須（宅建業法22条の4）"], ["携帯義務", "業務中は常に携帯（宅建業法22条の3）"]]}}},
  {id:10883,unit:'k_kenchiku',level:3,field:'limit',text:'Aは既存の建築物（築30年・木造2階建て）を改築して、新たに木造3階建て（高さ12m）の住宅を建築しようとしている。この土地は第一種低層住居専用地域（建ぺい率50%・容積率100%・北側斜線制限あり）内にある。この場合に関する記述として建築基準法の規定によれば正しいものはどれか。',opts:['第一種低層住居専用地域では3階建ての住宅は建築できない','第一種低層住居専用地域には絶対高さ制限（10mまたは12m）があり、12mの建築物は指定によっては高さ制限に抵触する可能性がある','北側斜線制限は商業地域のみに適用される','容積率100%であれば3階建て住宅は問題なく建築できる'],ans:1,exp:'第一種低層住居専用地域では絶対高さ制限（10mまたは12m、都市計画で指定・建築基準法55条）があります。高さ12mの建築物は、指定高さが10mの地域では違反となります。北側斜線制限は低層住居系・中高層住居系用途地域に適用されます（建築基準法56条1項3号）。3階建ての住宅自体は第一種低層住居専用地域でも建築可能です（高さ・斜線制限の範囲内であれば）。',"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・道路斜線・用途制限", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。用途地域ごとに建築物の制限があります。", "example": ""}, "reason": {"text": "第一種低層住居専用地域には絶対高さ制限（10mまたは12m）があります（建築基準法55条1項）。計画高さ12mが許容されるかどうかは都市計画で定められた高さ制限（10m・12mのどちらか）によります。また北側斜線制限も適用されます（建築基準法56条1項3号）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">第1種低層</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">学校は建築可</text></svg>", "choices": [{"label": "第一種低層住居専用地域では3階建ての住宅は建築できない", "reason": "3階建て住宅でも絶対高さ制限（10mまたは12m）・北側斜線制限等を満たせば建築できます（建築基準法55条）。「建築できない」は誤りです。", "caution": "第一種低層住居専用地域：3階建ても可（絶対高さ制限・北側斜線等を満たす必要あり）。"}, {"label": "北側斜線制限は商業地域のみに適用される", "reason": "北側斜線制限は第一種・第二種低層住居専用地域および第一種・第二種中高層住居専用地域に適用されます（建築基準法56条1項3号）。商業地域には適用されません。", "caution": ""}, {"label": "容積率100%であれば3階建て住宅は問題なく建築できる", "reason": "容積率をクリアしていても絶対高さ制限・北側斜線制限等を別途満たす必要があります（建築基準法55条・56条）。容積率クリアだけでは不十分です。", "caution": ""}], "summary": {"head": ["第一種低層住居専用地域の高さ制限", "内容"], "rows": [["絶対高さ制限", "10mまたは12m（都市計画で指定・建築基準法55条1項）"], ["北側斜線制限", "適用あり（建築基準法56条1項3号）"], ["3階建て", "高さ制限を満たせば建築可"]]}}},
  {id:10884,unit:'r_chinshaku',level:3,field:'rights',text:'AはBから居住用マンション（1LDK・月額賃料10万円・敷金20万円）を賃借した。2年間居住後に退去することになり、Aは敷金の返還を求めた。Bは「クリーニング費用3万円・通常の使用による傷・汚れの修繕費5万円・Aが故意に壊したドア修理費4万円」を敷金から差し引いて残額8万円を返還すると言っている。この場合に関する記述として民法及びガイドライン（国土交通省：原状回復をめぐるトラブルとガイドライン）の規定によれば正しいものはどれか。',opts:['Bの主張通り敷金から12万円差し引いて返還すれば適法','通常の使用による傷・汚れ（経年劣化・通常損耗）の修繕費は賃借人Aの負担ではなく賃貸人Bが負担すべきであり、差し引けるのは故意に壊したドアの修理費4万円のみが原則','クリーニング費用3万円は常に賃借人負担','敷金は全額返還が義務付けられており、差し引きは一切できない'],ans:1,exp:'賃貸借終了時の原状回復では、経年劣化・通常損耗（通常の使用による傷・汚れ）の修繕費は賃貸人負担が原則です（民法621条・国土交通省ガイドライン）。賃借人が負担すべきは故意・過失による損傷のみです。クリーニング費用は特約で賃借人負担とすることも可能ですが、特約がなければ賃貸人負担です。本問では故意に壊したドア修理費4万円のみAの負担が原則であり、残り16万円を返還すべきです。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "原状回復のガイドライン（国交省）では通常の使用による損耗（経年劣化・通常損耗）は賃貸人負担です。賃借人の故意による損傷（ドアを壊した等）のみが賃借人負担です。クリーニング費用は原則賃貸人負担ですが、特約で賃借人負担とすることも可能です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "Bの主張通り敷金から12万円差し引いて返還すれば適法", "reason": "通常損耗の修繕費（5万円）は賃借人負担にできません（民法621条）。差し引けるのは故意に壊したドアの修理費等に限られます。", "caution": ""}, {"label": "クリーニング費用3万円は常に賃借人負担", "reason": "クリーニング費用は原則賃貸人負担です（ガイドライン）。ただし明確な合意（特約）があれば賃借人負担も有効です。", "caution": ""}, {"label": "敷金は全額返還が義務付けられており差し引きは一切できない", "reason": "未払い賃料や賃借人負担の修繕費（故意・過失等）は敷金から差し引けます（民法622条の2第1項）。全額返還義務ではありません。", "caution": ""}], "summary": {"head": ["原状回復の費用負担（ガイドライン）", "負担者"], "rows": [["経年劣化・通常損耗（クロスの変色等）", "賃貸人"], ["賃借人の故意・過失による損傷", "賃借人"], ["善管注意義務違反（清掃不足等）", "賃借人"], ["クリーニング費用（原則）", "賃貸人（特約で変更可）"]]}}},
  {id:10885,unit:'l_jusetsu',level:3,field:'law',text:'宅建業者Aは、B所有の建物（新耐震基準（1981年6月以降）適合・昭和60年築・木造2階建て）の売却を媒介し、買主Cに重要事項説明を行った。建物の耐震診断については実施していない。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['昭和56年（1981年）6月以降に新築工事の確認を受けた建物は現行の耐震基準に適合しているため、耐震診断の有無に関する説明は不要','耐震診断を実施している場合はその結果を重要事項として説明しなければならないが、実施していない場合は説明不要','建物の耐震診断の実施の有無については実施している場合もしていない場合も重要事項説明書に記載しなければならない','耐震診断の有無は売主の任意であり宅建業者は関知しない'],ans:2,exp:'既存建物（中古住宅等）の売買では、建物の耐震診断の実施の有無を重要事項説明書に記載しなければなりません（宅建業法35条1項14号・施行令3条1項12号）。耐震診断を実施していない場合はその旨（実施していない）を記載します。昭和56年6月以降の建物であっても耐震診断の実施有無の記載義務は免除されません。',"kaisetsu":{"topic": "重要事項説明：宅建士が説明・売主への交付は不要・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主への交付義務はありません。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能です。", "example": ""}, "reason": {"text": "建物の耐震診断の実施の有無については、実施している場合もしていない場合も35条書面に記載しなければなりません（宅建業法35条1項14号・施行規則16条の4の3第3号）。耐震診断の有無を問わず記載が必要な点が重要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "新耐震基準適合なら耐震診断の有無の説明は不要", "reason": "耐震診断の実施の有無は新耐震基準適合かどうかに関わらず記載が必要です（宅建業法施行規則16条の4の3第3号）。", "caution": "耐震診断の実施有無：新耐震基準適合でも記載必須。"}, {"label": "実施している場合はその結果を説明しなければならないが実施していない場合は説明不要", "reason": "実施していない場合でも「実施していない旨」を記載しなければなりません（宅建業法施行規則16条の4の3第3号）。", "caution": "実施していなくても「実施していない旨」の記載が必要。"}, {"label": "耐震診断の有無は売主の任意であり宅建業者は関知しない", "reason": "耐震診断の実施有無は重要事項説明の記載事項であり（宅建業法施行規則16条の4の3第3号）、宅建業者は確認・記載する義務があります。", "caution": ""}], "summary": {"head": ["耐震診断と重要事項説明", "内容"], "rows": [["記載義務", "実施の有無（実施していない場合もその旨を記載）"], ["実施している場合", "診断結果も記載"], ["対象", "昭和56年5月31日以前に新築工事着手の建物等"], ["新耐震基準", "適合でも記載義務は変わらず"]]}}},
  {id:10886,unit:'r_touki',level:3,field:'rights',text:'A所有の甲土地について、Bを仮登記担保として登記（所有権移転請求権の仮登記）が行われた。その後、BはAに対して仮登記に基づく本登記手続きを求めた。甲土地にはCが第三順位で抵当権の設定を受けていた。この場合に関する記述として仮登記担保法の規定によれば正しいものはどれか。',opts:['仮登記担保の本登記が完了すれば、Cの抵当権は自動的に消滅する','仮登記担保の本登記申請がなされると、仮登記後に登記された権利（Cの抵当権）は抹消される。BはCに対して清算金を支払う義務を負う場合がある','仮登記担保は所有権移転の仮登記でないため本登記への移行はできない','仮登記担保の本登記後もCの抵当権は存続する'],ans:1,exp:'仮登記担保の本登記がなされると、仮登記後に登記された後順位権利（Cの抵当権等）は抹消されます（仮登記担保法3条・5条）。ただし担保仮登記権利者（B）は清算義務を負い、甲土地の価額が被担保債権額を超える部分については清算金をAに支払わなければなりません。Cの抵当権は本登記により抹消されますが、BはCへの通知義務等があります。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "仮登記担保の本登記がなされると、仮登記後に登記された権利（抵当権等）は抹消されます（不動産登記法109条）。ただし仮登記担保法により、清算金の支払義務等の保護規定があります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "仮登記担保の本登記が完了すれば、Cの抵当権は自動的に消滅する", "reason": "仮登記後の権利は本登記時に登記官が職権で抹消しますが（不動産登記法109条）、清算等の手続きが必要であり「自動的に消滅する」という表現は正確ではありません。", "caution": ""}, {"label": "仮登記担保は所有権移転の仮登記でないため本登記への移行はできない", "reason": "仮登記担保は所有権移転請求権の仮登記（2号仮登記）であり、本登記への移行が可能です（仮登記担保法）。", "caution": ""}, {"label": "仮登記担保の本登記後もCの抵当権は存続する", "reason": "仮登記後に登記されたCの抵当権は、本登記によって抹消されます（不動産登記法109条）。", "caution": ""}], "summary": {"head": ["仮登記担保の本登記", "効果"], "rows": [["仮登記後の権利", "本登記時に職権で抹消（不動産登記法109条）"], ["清算義務", "担保不動産の価値から被担保債権額を控除した残額を支払う義務"], ["後順位担保権者の保護", "清算金の範囲で保護される"]]}}},
  {id:10887,unit:'r_ishi',level:3,field:'rights',text:'成年被後見人Aは、後見人Bの同意を得ずに自己所有の土地を第三者Cに1000万円で売却した。後見人BはこのAC間の売買契約の取消しを主張した。Cは売買時にAが成年被後見人であることを知らなかった（善意）。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['CがAの成年後見を知らなかった（善意）場合、Bは取消しを主張できない','成年被後見人の行為は日常生活に関するものを除き取り消せる（民法9条）。Cが善意であっても後見人Bは取り消すことができる','成年被後見人の行為は後見人Bの同意があれば有効となる','成年被後見人Aが単独で行った売買契約は初めから無効である'],ans:1,exp:'成年被後見人の法律行為は日常生活に関する行為を除き取り消すことができます（民法9条）。制限行為能力者制度による取消しは相手方の善意・悪意を問いません（善意の第三者保護規定なし）。取消権者はA本人・後見人B等です（民法120条）。なお取消しの意思表示をした後の第三者との関係では対抗問題（登記）となります。',"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "意思表示の瑕疵には詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失の第三者は保護）・通謀虚偽表示（無効・善意の第三者は保護）があります。", "example": ""}, "reason": {"text": "成年被後見人の行為は日常生活に関するものを除き取り消せます（民法9条）。これは制限行為能力者制度であり、相手方の善意悪意を問わず取消しが可能です。詐欺の第三者保護規定（民法96条3項）とは異なります。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "CがAの成年後見を知らなかった（善意）場合、Bは取消しを主張できない", "reason": "制限行為能力者制度の取消しは相手方の善意悪意を問わず行使できます（民法9条）。善意のCであっても後見人Bは取消しを主張できます。", "caution": "詐欺の第三者保護（善意無過失の第三者保護）と制限行為能力者制度の取消しを混同しないこと。"}, {"label": "成年被後見人の行為は後見人Bの同意があれば有効となる", "reason": "成年被後見人の行為は後見人の同意があっても取消しの対象となります（民法9条）。同意によって有効になるのは被補助人等の場合です。", "caution": ""}, {"label": "成年被後見人Aが単独で行った売買契約は初めから無効である", "reason": "成年被後見人の行為は「無効」ではなく「取消しうる行為」です（民法9条）。取消しによって遡及的に無効となります。", "caution": ""}], "summary": {"head": ["制限行為能力者", "行為の効力", "相手方の善意悪意の影響"], "rows": [["未成年者", "取消しうる", "なし（善意でも取消し可）"], ["成年被後見人", "取消しうる", "なし（善意でも取消し可）"], ["被保佐人（重要行為）", "取消しうる", "なし"]]}}},
  {id:10888,unit:'k_kokudo',level:3,field:'limit',text:'Aは都市計画区域（市街化区域）内に土地（面積3000m2）を所有しており、これをB・Cの2社に1500m2ずつ売却しようとしている（2社に分割売却）。売買代金はBへの売却分3億円、Cへの売却分3億円（合計6億円）の予定である。この場合に関する記述として国土利用計画法の規定によれば正しいものはどれか。',opts:['分割売却の場合は1筆の土地を分けて売るのであり、届出は全体の6億円で判断される','市街化区域内では2000m2以上の土地取引に事後届出が必要であり、B・Cへの各取引（各1500m2）は個別に判断する。1500m2は2000m2未満であるため各取引は届出不要','市街化区域内の届出面積基準は1000m2以上であり、1500m2は届出が必要','分割売却の場合は合算して届出が必要'],ans:1,exp:'国土利用計画法の事後届出は取引ごとに判断します（一の契約による取引が単位）。市街化区域内の届出基準は2000m2以上です。B・Cへの各取引（各1500m2）は個別に判断し、各1500m2は2000m2未満であるため各取引とも事後届出は不要です。ただし意図的な分割により届出を免れようとする行為は問題視されます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "市街化区域内では2000㎡以上の取引に事後届出が必要です（国土利用計画法23条1項・施行令17条）。B・Cへの各取引が1500㎡の場合は2000㎡未満のため各々届出不要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "分割売却の場合は1筆の土地を分けて売るのであり届出は全体の6億円で判断される", "reason": "届出の判断は取引単位（各取引の面積）で行います（国土利用計画法23条1項・施行令17条）。", "caution": ""}, {"label": "市街化区域内の届出面積基準は1000m2以上であり1500m2は届出が必要", "reason": "市街化区域内の基準は2000㎡以上です（国土利用計画法施行令17条）。1500㎡は2000㎡未満のため届出不要です。", "caution": "市街化区域：2000㎡以上（国土利用計画法施行令17条）。1500㎡<2000㎡→届出不要。"}, {"label": "分割売却の場合は合算して届出が必要", "reason": "各取引単位で判断します（国土利用計画法23条1項）。", "caution": ""}], "summary": {"head": ["設問の届出判断", "内容"], "rows": [["B・C各1500m2", "各2000m2未満→各々届出不要"], ["市街化区域の基準", "2000m2以上（施行令17条）"]]}}},
  {id:10889,unit:'r_tanpo',level:3,field:'rights',text:'AはBに2000万円を貸し付け、AはBの友人C（保証人・物上保証人ではない）から連帯保証を取得した。Bが返済不能となり、AはCに対して連帯保証債務の履行を求めた。CはAに対して「まずBに請求してほしい」と言い、さらに「Bには財産がある」と主張した。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['連帯保証人Cには催告の抗弁権があり、AはBに先に請求しなければならない','連帯保証人Cには催告の抗弁権も検索の抗弁権もないため、AはCに直接2000万円の支払いを請求できる','CがBに財産があることを証明すればAはCへの請求をやめなければならない','連帯保証人は主債務者と全く同一の責任を負い、主債務者と区別されない'],ans:1,exp:'連帯保証人には催告の抗弁権（まず主債務者Bに請求しろという権利）も検索の抗弁権（Bの財産を先に執行しろという権利）もありません（民法454条）。したがってAはBへの請求なしにCに対して直接2000万円全額の支払いを請求できます。',"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権です（民法369条）。質権は占有の移転が必要です。先取特権は法律上当然に成立する法定担保物権です。", "example": ""}, "reason": {"text": "連帯保証人は催告の抗弁権（先に主債務者に請求してほしい）も検索の抗弁権（主債務者に財産があることを証明して先に主債務者の財産に執行してほしい）も持ちません（民法454条）。これが通常の保証との最大の違いです。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・非占有</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・占有</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "連帯保証人Cには催告の抗弁権があり先にBに請求が必要", "reason": "連帯保証人には催告の抗弁権がありません（民法454条）。債権者は直接連帯保証人に請求できます。", "caution": "連帯保証人＝催告の抗弁権なし・検索の抗弁権なし（民法454条）。"}, {"label": "CがBに財産があることを証明すればAはCへの請求をやめなければならない", "reason": "連帯保証人には検索の抗弁権がありません（民法454条）。Cが財産の存在を証明しても意味がありません。", "caution": ""}, {"label": "連帯保証人は主債務者と全く同一の責任を負い区別されない", "reason": "連帯保証人は主債務者ではなく、「補充的責任」という性質は残ります。ただし催告・検索の抗弁権がなく主債務者と同等に責任を負います（民法454条）。", "caution": ""}], "summary": {"head": ["保証の種類", "催告の抗弁権", "検索の抗弁権"], "rows": [["普通保証", "あり（民法452条）", "あり（民法453条）"], ["連帯保証", "なし（民法454条）", "なし（民法454条）"], ["効果", "連帯保証人は直接・同等に責任を負う"]]}}},
  {id:10890,unit:'l_cooling',level:3,field:'law',text:'宅建業者A（自ら売主）は、Bとの間でA所有のリゾートマンション（完成物件）の売買契約を締結した。契約場所はBがAのモデルルームを訪れて行われた。Bは後日クーリングオフを主張した。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['モデルルームで契約した場合はクーリングオフができる','モデルルームは宅建業法施行規則で定める「事務所等」に該当し、事務所等での契約はクーリングオフできないため、Bはクーリングオフできないことがあるとしても、AのモデルルームがAの宅建業の事務所等（継続的業務施設）に該当する場合は適用外','クーリングオフはどのような場所で契約しても常にできる','Bが自らモデルルームを訪問して契約したことは関係なく、クーリングオフの可否は書面通知の有無のみで決まる'],ans:1,exp:'クーリングオフは土地に定着する建物内に設けられた売主の宅建業の事務所等（宅建業法施行規則16条の5第1号）、継続的に業務を行うことができる施設のあるモデルルームでBが自ら訪問して申込・契約した場合はクーリングオフできません（宅建業法37条の2第1項1号）。Bが自らモデルルームを訪問して契約したことが重要で、その場合は事務所等に準じる扱いとなります。',"kaisetsu":{"topic": "クーリングオフ：告知日から8日以内・書面で・事務所では不可・全額返還", "basis": {"text": "クーリングオフは告知を受けた日から8日以内に書面で行います（宅建業法37条の2）。事務所・モデルルーム等での申込みはクーリングオフ不可。解除後業者は全額返還（費用控除不可）。", "example": ""}, "reason": {"text": "モデルルーム（継続的業務施設として専任の宅建士を設置し届出をしたもの）は「事務所等」に該当し、そこでの申込み・契約はクーリングオフの対象外です（施行規則16条の5第2号）。ただし届出のないモデルルームは事務所等に該当しません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">クーリングオフのポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">告知日から8日以内</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">方法</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面（発信主義）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所での申込み</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">クーリングオフ不可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除後</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全額返還（費用控除不可）</text></svg>", "choices": [{"label": "モデルルームで契約した場合はクーリングオフができる", "reason": "届出済みのモデルルーム（継続的業務施設）は事務所等に該当し、クーリングオフできません（施行規則16条の5第2号）。「できる」は誤りです。", "caution": "届出済みのモデルルーム：事務所等→クーリングオフ不可。届出なし：事務所等外→可。"}, {"label": "クーリングオフはどのような場所で契約しても常にできる", "reason": "事務所等での契約はクーリングオフできません（宅建業法37条の2第1項・施行規則16条の5）。「常にできる」は誤りです。", "caution": ""}, {"label": "Bが自らモデルルームを訪問して契約したことは関係なく書面通知の有無のみで決まる", "reason": "場所（事務所等か否か）もクーリングオフの可否に影響します（宅建業法37条の2第1項・施行規則16条の5）。書面通知のみで決まるわけではありません。", "caution": ""}], "summary": {"head": ["モデルルームでのクーリングオフ", "内容"], "rows": [["届出済み（専任宅建士設置）", "事務所等→クーリングオフ不可"], ["届出なし", "事務所等外→クーリングオフ可"], ["判断基準", "宅建業法施行規則16条の5第2号"]]}}},
  {id:10891,unit:'r_baibai',level:3,field:'rights',text:'AはBに対して特定の絵画（甲）を100万円で売る契約を締結した。引渡し期日の前日に、甲は地震によって損傷した（地震はAの過失ではない）。AはBに対して修繕した上で引き渡すことができるが修繕費に30万円かかる。Bは修繕済みの絵画を受け取ることを拒み、代金の支払いを拒否している。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['甲が損傷したのはAの過失ではないため、BはAに対して何も請求できず代金100万円を支払わなければならない','甲（種類物ではなく特定物）が不可抗力で損傷した場合、Bは損傷した状態での引渡しと全額代金支払いを拒否できず、また修繕後の引渡しを請求できる（追完請求）。ただし損傷の程度によっては代金減額や解除も可能','AはBに損傷した甲をそのまま引き渡せばよく修繕義務はない','地震による損傷はAの帰責事由がないため、Bは代金を全額支払わなければならない'],ans:1,exp:'2020年改正民法により契約不適合責任の規定が整備されました。不可抗力（地震）による損傷でも引き渡された目的物が契約内容に適合しない場合、Bは追完請求（修繕）・代金減額請求・損害賠償（帰責事由ある場合）・解除ができます（民法562条・563条・564条）。損害賠償はAに帰責事由がなければ請求できませんが、追完請求・代金減額・解除はAの帰責事由不要です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "特定物売買で引渡し前に不可抗力により目的物が損傷した場合、買主は追完請求ができます（民法562条）。完全な代金支払いを求める売主の主張に対して買主は代金減額・解除も選択できます（民法536条・563条・541条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "Bは損傷した甲を受け取り代金全額を支払わなければならない", "reason": "損傷した目的物を受け取るとすれば代金減額・追完請求が可能です（民法562条・563条）。代金全額支払いは不当です。", "caution": ""}, {"label": "AはBに損傷した甲をそのまま引き渡せばよく修繕義務はない", "reason": "Aは追完義務を負います（民法562条1項）。そのまま引渡しのみで足るとするのは誤りです。", "caution": ""}, {"label": "地震による損傷はAの帰責事由がないためBは代金を全額支払わなければならない", "reason": "帰責事由なき損傷でも買主は代金減額（民法563条）や解除（民法536条）ができます。「全額支払い義務」は誤りです。", "caution": ""}], "summary": {"head": ["引渡し前の損傷（危険負担）", "買主の選択肢"], "rows": [["追完請求（修繕）", "民法562条"], ["代金減額", "民法563条"], ["解除", "民法536条・541条"], ["全額支払い拒絶", "民法536条1項（履行拒絶権）"]]}}},
  {id:10892,unit:'r_souzoku',level:3,field:'rights',text:'AはBとCの2名の子を持つ。Aは生前に公正証書遺言を作成し、「全財産を長男Bに相続させる」と記載した。Aの総財産は1億円、負債は2000万円であった。次男Cは遺言に納得できず、自分の遺留分を主張したいと考えている。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['公正証書遺言がある以上、Cは一切遺留分を主張できない','Cは遺留分権利者として、Bに対して遺留分侵害額請求権（民法1046条）を行使できる。Cの遺留分は正味財産（1億円－2000万円）の4分の1（2000万円）','遺留分は遺産全体の2分の1であり、次男Cが受け取れる遺留分は5000万円','遺留分侵害額請求権の行使期間は相続開始を知ってから3年以内'],ans:1,exp:'Cの遺留分（民法1042条）は相続財産（債務控除後の正味財産8000万円）に遺留分割合をかけた額です。直系卑属（子）の場合、遺留分の合計は正味財産の1/2であり、子2名のCの遺留分は1/4（8000万円×1/4＝2000万円）です。Cは遺留分侵害額請求権（民法1046条）をBに行使できます。行使期間は遺留分侵害を知った時から1年・相続開始から10年です（民法1048条）。',"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2", "basis": {"text": "配偶者と子の場合は各1/2（民法900条）。相続放棄は3か月以内に家庭裁判所へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2です（民法1042条）。遺産分割協議は全員合意が必要です。", "example": ""}, "reason": {"text": "遺留分侵害額請求権（民法1046条）により、遺留分を侵害された相続人は受遺者等に金銭の支払いを請求できます。子Cの遺留分は正味相続財産（総財産－債務）の1/4です（民法1042条・1043条）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続の主要ポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子の相続分</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は法定相続分の1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割協議</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "公正証書遺言がある以上、Cは一切遺留分を主張できない", "reason": "公正証書遺言の有無に関わらず、遺留分権利者は遺留分侵害額請求権を行使できます（民法1046条）。", "caution": "遺言があっても遺留分は保護されます。"}, {"label": "遺留分は遺産全体の2分の1であり次男Cが受け取れる遺留分は5000万円", "reason": "遺留分の割合は相続人の構成によります。配偶者や他の相続人がいない場合、子のみが相続人であれば遺留分全体は1/2ですが、子が1人なら1/2全部が1人のCの遺留分となります。設問では負債2000万円を控除した正味財産（1億円－2000万円＝8000万円）の1/2（4000万円）がCの遺留分です。", "caution": ""}, {"label": "遺留分侵害額請求権の行使期間は相続開始を知ってから3年以内", "reason": "遺留分侵害額請求権の消滅時効は「相続の開始及び遺留分を侵害する贈与・遺贈があったことを知った時から1年」または「相続開始から10年」です（民法1048条）。3年ではありません。", "caution": "遺留分の時効：知った時から1年、または10年。"}], "summary": {"head": ["遺留分の計算（設問）", "内容"], "rows": [["遺産", "1億円"], ["負債", "2000万円"], ["正味遺産", "8000万円"], ["遺留分の割合（子のみ）", "1/2"], ["Cの遺留分", "8000万円×1/2＝4000万円"]]}}},
  {id:10893,unit:'l_kantoku',level:3,field:'law',text:'宅建業者Aの従業員Bが、顧客Cの重要事項説明において虚偽の説明を行い、Cに対して多大な損害を与えた。甲県知事はAに対して業務停止処分（3か月）を検討している。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['業務停止処分はAの法人としての免許に対する処分であり、行為者Bへの処分はできない','甲県知事はAに対して業務停止処分を行うとともに、直接の行為者であるBに対して宅建士としての業務停止処分（事務禁止処分）を行うことができる','業務停止処分の期間は最長1年','業務停止処分に対してAは争う手段がない'],ans:1,exp:'宅建業者Aに対しては業務停止処分（最長1年・宅建業法65条）が可能です。また宅建士Bに対しては直接の違反行為者として指示処分・事務禁止処分（最長1年）が可能です（宅建業法68条）。宅建業者への処分と宅建士への処分は独立して行えます。業務停止処分の最長期間は1年（宅建業法65条2項）です。業務停止処分等には行政不服申立て・行政訴訟で争う手段があります。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "宅建業者への業務停止処分（宅建業法65条2項）と宅建士への事務禁止処分（同法68条1項）は独立して行われます。宅建士の行為が宅建業法違反である場合、知事は当該宅建士にも事務禁止処分等を行うことができます（同法68条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "業務停止処分はAの法人としての免許に対する処分であり行為者Bへの処分はできない", "reason": "行為者である宅建士Bに対しても事務禁止処分等を別途行うことができます（宅建業法68条）。「Bへの処分はできない」は誤りです。", "caution": "業者への処分（宅建業法65条）と宅建士への処分（宅建業法68条）は独立して行われる。"}, {"label": "業務停止処分の期間は最長1年", "reason": "業務停止処分は最長1年です（宅建業法65条2項）。設問の記述（3か月）は範囲内で適法です。", "caution": ""}, {"label": "業務停止処分に対してAは争う手段がない", "reason": "行政不服申立て（審査請求）や行政訴訟（取消訴訟）で争うことができます（行政不服申立法・行政事件訴訟法）。「争う手段がない」は誤りです。", "caution": ""}], "summary": {"head": ["業者への処分と宅建士への処分の関係", "内容"], "rows": [["独立性", "業者への処分と宅建士への処分は独立"], ["業者への処分", "業務停止・免許取消（宅建業法65条・66条）"], ["宅建士への処分", "事務禁止・登録消除（宅建業法68条・68条の2）"], ["争い方", "行政不服申立て・行政訴訟"]]}}},
  {id:10894,unit:'k_mori',level:3,field:'limit',text:'AはH市（市街化区域内）内の土地（宅地造成等工事規制区域外）において造成工事を行い、切土・盛土を伴う宅地開発を計画している。この土地の面積は8000m2で、最大盛土高さは2.5m、切土高さは1.5mである。この場合に関する記述として盛土規制法（宅地造成及び特定盛土等規制法）の規定によれば正しいものはどれか。',opts:['宅地造成等工事規制区域外であれば、いかなる造成工事も規制を受けない','宅地造成等工事規制区域外であっても、特定盛土等規制区域として指定された区域内では同様の規制（許可または届出）を受ける場合がある','市街化区域内であれば盛土規制は一切適用されない','2.5mの盛土は常に許可不要'],ans:1,exp:'2021年熱海土砂災害等を受けて盛土規制法（宅地造成及び特定盛土等規制法・2023年施行）が制定されました。宅地造成等工事規制区域（市街地・市街地予定地等）のほか、新たに「特定盛土等規制区域」が設けられ（森林・農地等）、規制区域外でも指定区域内では許可または届出が必要となりました（盛土規制法26条・30条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "宅地造成等工事規制区域外であっても特定盛土等規制区域として指定された区域内では盛土規制法の規制が及びます（宅地造成及び特定盛土等規制法26条以下）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "宅地造成等工事規制区域外であれば造成工事も規制を受けない", "reason": "特定盛土等規制区域内では盛土規制法が適用されます（宅地造成及び特定盛土等規制法26条以下）。", "caution": "区域外でも特定盛土等規制区域内では規制あり（宅地造成及び特定盛土等規制法26条）。"}, {"label": "市街化区域内であれば盛土規制は一切適用されない", "reason": "市街化区域内でも特定盛土等規制区域に指定されれば規制が及びます（宅地造成及び特定盛土等規制法26条）。", "caution": ""}, {"label": "2.5mの盛土は常に許可不要", "reason": "高さ1m超の崖を生じる盛土は許可対象です（施行令3条）。", "caution": ""}], "summary": {"head": ["特定盛土等規制区域の適用", "内容"], "rows": [["宅地造成工事規制区域外（特定盛土等規制区域内）", "盛土等の規制が適用される"]]}}},
  {id:10895,unit:'t_chika',level:3,field:'tax',text:'AはH県I市内の土地について、地価公示法に基づく公示価格を参考に価格査定を行っている。この場合に関する記述として地価公示法の規定によれば正しいものはどれか。',opts:['公示価格は毎年10月1日時点の地価水準を示す','公示価格は毎年1月1日を価格判定の基準日として、国土交通省の土地鑑定委員会が不動産鑑定士の鑑定評価を基に決定し、3月下旬に公表される','公示価格は都市計画区域のみを対象とし、農村部は対象外','公示価格は参考価格にすぎず、収用事業での補償額算定の基準にはならない'],ans:1,exp:'地価公示（地価公示法2条）は毎年1月1日を基準日として、土地鑑定委員会が不動産鑑定士の鑑定評価を基に標準地の正常な価格を公示します。公表は毎年3月下旬です。公示価格は①一般の土地取引の指標②公共事業用地の取得価格の基準③不動産鑑定士の鑑定評価の基準として活用されます。都市計画区域に限らず必要な地域にも設定できます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10896,unit:'r_bukken',level:3,field:'rights',text:'AはB銀行の融資を受けて甲土地を購入し、B銀行のために第一順位抵当権を設定した。その後AはC銀行の融資も受け、C銀行のために第二順位抵当権を設定した。Aはその後B銀行への残債務1500万円を完済し、抵当権抹消登記の手続きに着手した。しかしAは抹消登記申請前に死亡し、相続人DがAの地位を承継した。この場合に関する記述として民法・不動産登記法の規定によれば正しいものはどれか。',opts:['B銀行への完済により第一順位抵当権は当然に消滅するが、抹消登記がなければDはB銀行に対して消滅を主張できない','抵当権は被担保債権の完済によって付従性により消滅するが、第三者への対抗には抹消登記が必要。DはAの地位を承継して抹消登記申請を行うことができる','B銀行への完済後でも、登記が残っている以上C銀行はB銀行に劣後したまま','DはB銀行の抵当権抹消登記がなくても、甲土地を第三者に売却できる'],ans:1,exp:'抵当権は被担保債権の弁済により付従性に基づき当然消滅しますが、抵当権設定登記が残ったままでは第三者（甲土地の購入者等）に消滅を対抗できない場合があります。DはAの地位を承継（相続）して抹消登記申請の権利義務も引き継ぎ、B銀行と共同申請で抹消登記ができます（不動産登記法60条）。抵当権抹消後はC銀行の抵当権が第一順位に繰り上がります。',"kaisetsu":{"topic": "物権変動：登記が対抗要件・不法占拠者には登記不要", "basis": {"text": "不動産の物権変動は登記が第三者への対抗要件です（民法177条）。不法占拠者には登記なく対抗できます。相続の法定相続分超過部分は登記が必要です（民法899条の2）。", "example": ""}, "reason": {"text": "抵当権は付従性により被担保債権が消滅すると消滅します（民法396条反対解釈）。ただし第三者への消滅の対抗には抹消登記が必要です（民法177条）。相続による地位の承継は当然に生じ、Dは抹消登記申請を行えます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">物権変動の対抗要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対抗要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">二重譲渡</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先に登記した者が優先</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不法占拠者</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記不要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物賃借権</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡し</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続（超過部分）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記必要</text></svg>", "choices": [{"label": "抹消登記がなければDはB銀行に対して消滅を主張できない", "reason": "B銀行との当事者間では弁済により抵当権は消滅しています。抹消登記が必要なのは第三者への対抗のためであり、当事者間では不要です。", "caution": "当事者間の効力と第三者対抗要件を混同しないこと。"}, {"label": "C銀行はB銀行に劣後したまま", "reason": "B銀行への弁済により第一順位抵当権は消滅します。抹消登記後はC銀行が実質的に最上位順位となります（順位の昇進）。", "caution": ""}, {"label": "DはB銀行の抵当権抹消登記がなくても第三者に売却できる", "reason": "抹消登記前に売却すると、買主はB銀行の抵当権が残ったまま（登記上）の不動産を取得するリスクがあります。抹消登記を完了させてから売却すべきです。", "caution": ""}], "summary": {"head": ["抵当権消滅の原因", "当事者間の効力", "第三者への対抗"], "rows": [["被担保債権の弁済", "消滅", "抹消登記が必要"], ["混同（所有者と抵当権者が同一に）", "原則消滅", "抹消登記が必要"], ["競売による代金配当", "消滅", "登記官が職権で抹消"]]}}},
  {id:10897,unit:'r_fuhoko',level:3,field:'rights',text:'Aは会社Bの従業員として営業活動中に過失により交通事故を起こし、通行人Cに怪我を負わせた。Cの損害は治療費・慰謝料合計300万円である。CはB社に対して使用者責任（民法715条）に基づく損害賠償を請求した。B社はCに300万円を支払った。この場合に関する記述として民法の規定及び判例によれば正しいものはどれか。',opts:['B社がCに支払った後、B社はAに対して300万円全額を求償できる','B社がAに求償できる金額は最高でも300万円の半分（150万円）に限られる','B社はAに対して一切求償できない','CはB社に対して請求できるが、直接Aに対して請求はできない'],ans:1,exp:'使用者B社がCに300万円を支払った後、B社はAに対して求償権を取得します（民法715条3項）。ただし判例上、使用者の求償権の行使は信義則上一定の制限を受け、被用者の負担すべき割合は事業の性格・業務の必要性・Aの故意過失の程度・使用者の利益享受等を考慮して定められ、必ずしも全額求償が認められるわけではありません。Cは直接Aにも不法行為（民法709条）に基づき請求できます（連帯責任）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "使用者が被用者の不法行為について損害賠償した後、被用者への求償が認められますが、判例は信義則上一定割合に制限するとしています（最判昭和51年）。一般に全額求償は認められず、事案の内容・使用者の利益等を考慮して相当な範囲（概ね半分程度）に限られます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "B社がCに支払った後B社はAに対して300万円全額を求償できる", "reason": "判例は信義則上求償を制限し、全額求償は認められません（最判昭和51年）。", "caution": "使用者の被用者への求償は信義則上制限あり（全額不可・判例）。"}, {"label": "B社はAに対して一切求償できない", "reason": "求償は認められます（民法715条3項）。ただし信義則上制限があります（判例）。", "caution": ""}, {"label": "CはB社に対して請求できるが直接Aに対して請求はできない", "reason": "CはAに対して直接不法行為責任（民法709条）を追及できます。B社への使用者責任（民法715条）と並んで請求できます。", "caution": ""}], "summary": {"head": ["使用者→被用者への求償", "内容"], "rows": [["根拠", "民法715条3項"], ["判例の制限", "信義則上一定割合に制限（全額不可・最判昭51）"], ["制限の程度", "事案により異なるが概ね半分程度が目安"], ["理由", "使用者も利益を受けており、全額を被用者に転嫁するのは不公平"]]}}},
  {id:10898,unit:'r_jiko',level:3,field:'rights',text:'AはBに対して売買代金500万円の債権を持っている。Bはこの債権の存在を知っているが、「時効が完成した」と主張して支払いを拒んでいる。Aが調べると確かに消滅時効期間が経過していた。その後、BはAに対して「わかった。分割で支払う」と言って、第1回分として50万円を振り込んだ。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['時効完成後にBが一部弁済をしても、時効援用の効力は消滅しない','時効完成後にBが債務の存在を前提とした行動（一部弁済・支払いの約束）をした場合、信義則上Bはその後の時効援用が許されないとするのが判例の立場（時効完成後の承認）','時効が完成した以上、BはAへの支払いを拒否できる権利が確定的に生じている','50万円の受領はAが時効の恩恵を放棄したことになる'],ans:1,exp:'時効完成後に債務者が债務の存在を認める行為（承認・一部弁済・支払い約束等）をした場合、信義則上その後の時効援用が許されないとするのが判例の立場です（最高裁判例）。Bが50万円を振り込み支払いを約束したことは、時効完成後の債務承認に当たり、BはAに対して時効援用を主張できなくなります（信義則による時効援用の制限）。',"kaisetsu":{"topic": "消滅時効：知った時から5年または行使可能時から10年", "basis": {"text": "一般の債権の消滅時効は「権利行使できると知った時から5年」または「権利行使できる時から10年」のいずれか早い方で完成します（民法166条1項）。時効は援用して初めて効力が発生します（民法145条）。", "example": ""}, "reason": {"text": "時効完成後に債務者が債務の存在を前提とした行為（一部弁済・支払約束等）をした場合、信義則上その後の時効援用は許されません（判例）。時効の完成を知っていたかどうかは関係なく、相手方の信頼を保護するためです。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">時効期間</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人の生命・身体への損害</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年または20年</text></svg>", "choices": [{"label": "時効完成後にBが一部弁済をしても、時効援用の効力は消滅しない", "reason": "時効完成後の一部弁済は「承認」として時効援用を信義則上制限します（判例）。「効力が消滅しない」は誤りです。", "caution": ""}, {"label": "時効が完成した以上、BはAへの支払いを拒否できる権利が確定的に生じている", "reason": "時効の援用権は確定的な権利ですが、行使後に承認等をすれば信義則上援用が制限されます（判例）。一度援用しても後に承認すると信義則で制限される場合があります。", "caution": ""}, {"label": "50万円の受領はAが時効の恩恵を放棄したことになる", "reason": "時効の利益を放棄できるのは時効の恩恵を受ける者（債務者B）です。債権者Aが放棄するのは時効ではなく債権です。", "caution": ""}], "summary": {"head": ["時効完成後の行為", "援用の可否"], "rows": [["何もしない", "援用可"], ["一部弁済・支払約束等（承認に該当）", "信義則上援用不可（判例）"], ["明示的放棄", "放棄の効力あり・援用不可"]]}}},
  {id:10899,unit:'l_37jo',level:3,field:'law',text:'宅建業者Aは、売主B・買主C（宅建業者）の間で事業用土地の売買を媒介した（売買代金5億円）。Cが宅建業者であることを理由に、Aは「重要事項説明は省略する」として説明を行わず、37条書面のみを交付した。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['買主Cが宅建業者であるため重要事項の説明自体は省略できる','相手方が宅建業者の場合は重要事項の説明（口頭）は省略できるが、35条書面（重要事項説明書）の交付は省略できない（書面交付義務は残る）','相手方が宅建業者の場合は35条書面も37条書面も不要','37条書面の交付は相手方が宅建業者であっても義務がある'],ans:1,exp:'相手方（買主C）が宅建業者の場合は重要事項の「説明」（口頭での説明）は省略できますが、35条書面（重要事項説明書）の交付義務は免除されません（宅建業法35条6項：2022年改正で書面交付義務は残存）。また37条書面は相手方の属性にかかわらず交付義務があります（宅建業法37条1項・2項）。',"kaisetsu":{"topic": "37条書面：全取引で交付・記名（押印不要）・移転登記申請時期は必要的記載事項", "basis": {"text": "37条書面は売買・交換・賃貸借の全取引で契約の双方当事者に交付が義務（宅建業法37条）。引渡し時期・移転登記申請時期は必要的記載事項。2021年改正で押印は不要になり記名のみで足ります。", "example": ""}, "reason": {"text": "宅建業者間の取引では重要事項の説明（口頭）は省略できますが（宅建業法35条6項）、35条書面（重要事項説明書）の交付義務は残ります（同条同項）。37条書面は宅建業者間でも交付義務があります（同法37条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付義務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全取引・双方当事者</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡時期・移転登記申請時期等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要）</text></svg>", "choices": [{"label": "買主Cが宅建業者であるため重要事項の説明自体は省略できる", "reason": "宅建業者間取引で説明が省略できることは正しいです（宅建業法35条6項）。ただし書面交付義務は残ります。設問の正解は選択肢2です。", "caution": "宅建業者間：説明省略可、書面交付は省略不可（宅建業法35条6項）。"}, {"label": "相手方が宅建業者の場合は35条書面も37条書面も不要", "reason": "35条書面は書面交付が必要（説明のみ省略可）で（宅建業法35条6項）、37条書面は宅建業者間でも交付が必要です（同法37条1項）。「どちらも不要」は誤りです。", "caution": ""}, {"label": "37条書面の交付は相手方が宅建業者であっても義務がある", "reason": "これは正しい内容ですが、設問の主な問題点は35条書面の交付義務です（宅建業法35条6項は書面交付義務を維持）。", "caution": ""}], "summary": {"head": ["宅建業者間の取引と書面", "省略可否"], "rows": [["重要事項説明（口頭）", "省略可（宅建業法35条6項）"], ["35条書面の交付", "省略不可（同条6項）"], ["37条書面の交付", "省略不可（宅建業法37条1項）"], ["宅建士証の提示", "省略規定なし"]]}}},
  {id:10900,unit:'r_kukku',level:3,field:'rights',text:'分譲マンションの管理組合は、敷地内の駐車場（共用部分）の管理方針について集会で審議する。現在の規約では駐車場の使用料は月額1万円と定められているが、管理組合の理事長は費用増加を理由に月額2万円への値上げを提案している。さらに、一部の区分所有者からは駐車場を外部業者に売却する提案も出ている。この場合に関する記述として区分所有法の規定によれば正しいものはどれか。',opts:['規約の変更（駐車場使用料の値上げ）は理事長が単独で決定できる','規約の変更（駐車場使用料の変更）は区分所有者及び議決権の各4分の3以上の賛成による特別決議が必要','駐車場（共用部分）の外部業者への売却は区分所有者及び議決権の各過半数の普通決議で足りる','規約の変更は公証人の認証が必要'],ans:1,exp:'規約の変更は区分所有者及び議決権の各3/4以上の賛成による特別決議が必要です（区分所有法31条1項）。駐車場使用料の変更は規約事項であるため特別決議が必要です。共用部分の売却（処分）は規約に別段の定めがない限り、区分所有者及び議決権の各3/4以上の特別決議が必要です（区分所有法17条）。理事長の単独決定はできず、公証人の認証も不要です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "規約の変更（駐車場使用料の変更）は区分所有者および議決権の各3/4以上の特別決議が必要です（区分所有法31条1項）。共用部分（駐車場）の外部業者への売却は共用部分の処分であり重大変更（3/4以上）または規約変更（3/4以上）の問題です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "規約の変更は理事長が単独で決定できる", "reason": "規約の変更は3/4以上の集会決議が必要です（区分所有法31条1項）。理事長が単独で決定できるものではありません。", "caution": "規約変更＝3/4以上の集会決議（区分所有法31条1項）。理事長単独決定は不可。"}, {"label": "駐車場（共用部分）の外部業者への売却は過半数の普通決議で足りる", "reason": "共用部分の売却は重大な変更・処分であり、規約変更を伴う場合は3/4以上が必要です（区分所有法31条1項・17条1項）。「過半数で足りる」は誤りです。", "caution": ""}, {"label": "規約の変更は公証人の認証が必要", "reason": "規約の変更に公証人の認証は不要です（区分所有法31条1項）。集会決議で足ります。", "caution": ""}], "summary": {"head": ["区分所有の集会決議まとめ", "要件"], "rows": [["通常の管理（軽微変更）", "過半数"], ["重大変更・規約変更", "3/4以上"], ["大規模滅失の復旧", "3/4以上"], ["建替え", "4/5以上"]]}}},


  // ===== 長文問題追加50問（10901〜10950）=====
  {id:10901,unit:'r_ishi',level:3,field:'rights',text:'AはBから「この土地は将来必ず値上がりする」と言われたが、Bは単なる見解として述べただけで、その後Aは自ら判断して甲土地を購入した。しかしAは土地の用途規制について重大な思い違い（工場が建てられると思っていたが第一種低層住居専用地域だった）をしており、これはBとの交渉中には一切表示していなかった。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['Aは動機の錯誤（民法95条）を理由に契約を取り消すことができる','Aの思い違いは内心にとどまり相手方Bに表示されていないため、原則として錯誤取消しは認められない','Bが見解を述べたことは詐欺に当たるため、Aは詐欺を理由に取り消せる','用途規制の確認はAの義務であり、錯誤であっても取り消せない'],ans:1,exp:'動機の錯誤（民法95条1項2号）は、動機が法律行為の内容として相手方に表示されていた場合に限り取消しの対象となります。Aが用途規制について誤認していても、その動機をBに表示していなかった以上、原則として錯誤取消しは認められません。ただしBが用途規制について積極的に誤った情報を提供した場合は詐欺の問題となります。',"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "意思表示の瑕疵には詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失の第三者は保護）・通謀虚偽表示（無効・善意の第三者は保護）があります。", "example": ""}, "reason": {"text": "動機の錯誤は原則として取消しの対象外ですが、動機が表示されて法律行為の内容となった場合は取消しが認められます（民法95条2項）。本問ではAは動機（用途規制の思い違い）を交渉中にBへ表示していないため、錯誤取消しは認められません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "Aは動機の錯誤（民法95条）を理由に契約を取り消すことができる", "reason": "動機がBに表示されていないため、動機の錯誤として取消しは認められません（民法95条2項）。交渉中に表示・共有されていない動機は取消しの対象外です。", "caution": "動機の錯誤＝原則取消し不可、ただし表示されて法律行為の内容となった場合は可。"}, {"label": "Bが見解を述べたことは詐欺に当たるため、Aは詐欺を理由に取り消せる", "reason": "Bは単なる見解（将来の予測）を述べたにすぎず、虚偽の事実を告知したわけではないため詐欺には当たりません。", "caution": ""}, {"label": "用途規制の確認はAの義務であり、錯誤であっても取り消せない", "reason": "用途規制の確認義務があること自体は正しいですが、それを理由に錯誤取消しが一切認められないとはいえません。本問では動機が表示されていないことが理由です。", "caution": ""}], "summary": {"head": ["動機の錯誤の取扱い", "条件"], "rows": [["原則", "取消し不可（内心の問題）"], ["例外（取消し可）", "動機が相手方に表示され法律行為の内容となった場合"], ["本問の場合", "交渉中に表示なし→取消し不可"]]}}},
  {id:10902,unit:'r_tanpo',level:3,field:'rights',text:'AはB銀行から事業資金2000万円を借り入れ、A所有の甲土地（時価3000万円）に抵当権を設定した。Aはその後、C（個人）から500万円を借り入れ、Cのために甲土地に第二順位の抵当権を設定した。その後Aは甲土地をDに賃貸した（賃料月額10万円）。B銀行の抵当権設定後にDへの賃貸が行われた場合に関する記述として民法の規定及び判例によれば正しいものはどれか。',opts:['B銀行が甲土地を競売した場合、Dの賃借権はB銀行の抵当権設定後に成立したものであり、競落人に対抗できない場合がある','抵当権設定後の賃借権は競売後も常に存続する','DはB銀行の同意があれば競落人に賃借権を対抗できるが、同意がなければ退去しなければならない','B銀行の抵当権はDの賃借権より順位が上なので、DはB銀行に賃料を支払わなければならない'],ans:0,exp:'抵当権設定後に設定された賃借権は、原則として競落人に対抗できません（民法177条・605条の対抗要件の問題）。ただし短期賃貸借保護規定の廃止（2004年改正）後は、抵当権設定後の賃借権は競売により消滅するのが原則です。なお建物の場合は引渡しによる対抗要件があれば別途検討が必要です。',"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権です（民法369条）。質権は占有の移転が必要です。先取特権は法律上当然に成立する法定担保物権です。", "example": ""}, "reason": {"text": "抵当権設定後の賃借権は抵当権に劣後します（民法177条・民事執行法59条2項）。競売が行われると抵当権設定後に成立した賃借権は消滅し、競落人に対抗できません。ただし建物明渡猶予制度（民法395条）により6か月の猶予があります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・非占有</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・占有</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "抵当権設定後の賃借権は競売後も常に存続する", "reason": "抵当権設定後の賃借権は競落人に対抗できません（民法177条・民事執行法59条2項）。常に存続するわけではありません。", "caution": "抵当権設定後の賃借権→競落人に対抗不可。"}, {"label": "DはB銀行の同意があれば対抗できるが同意がなければ退去が必要", "reason": "B銀行の「同意」で対抗できる制度はありません。対抗できるかどうかは権利の先後（設定時期）で決まります（民法177条）。", "caution": ""}, {"label": "B銀行の抵当権はDの賃借権より順位が上なのでDはB銀行に賃料を支払わなければならない", "reason": "物上代位により差押えがあれば抵当権者が賃料を受領できますが（民法304条）、差押え前は賃借人Dは設定者Aに賃料を支払います。「B銀行に支払う義務がある」という常時の義務はありません。", "caution": ""}], "summary": {"head": ["抵当権と賃借権の優劣", "内容"], "rows": [["抵当権設定前の賃借権", "競落人に対抗可（賃貸借継続）"], ["抵当権設定後の賃借権", "競落人に対抗不可（消滅）"], ["明渡猶予（民法395条）", "競落後6か月の猶予"]]}}},
  {id:10903,unit:'r_saikensoron',level:3,field:'rights',text:'AはBに対して800万円の金銭債権を有している。弁済期が到来したが、BはAに対して「自分はCに対して600万円の反対債権を持っている。Cはあなた（A）の債権をCから譲り受けたのだから、その分を差し引いてほしい」と主張している。AはBのCに対する600万円の債権をCから譲り受けていた。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['BはAに対して相殺を主張できないため、800万円全額を支払わなければならない','BはAに対して相殺適状の要件（双方が互いに同種の債務を負担）を満たせば相殺を主張できる。AはBに対して800万円の債権を持ち、BはAに対して600万円の反対債権（もとCへの債権をAが取得）を持つ場合、Bは相殺により200万円のみの支払いで足りる','債権譲渡があった場合、相殺は一切できない','相殺するにはAの同意が必要'],ans:1,exp:'債権が譲渡された場合、債務者（B）は譲渡通知を受けた時点（または承諾時）より前に取得していた譲渡人（C）への反対債権を新債権者（A）に対して相殺の主張ができます（民法469条）。BがCに対して600万円の債権を有しており、AがCからBへの800万円の債権を譲り受けた場合、Bは600万円を相殺として主張でき、残200万円の支払いで足ります。',"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要です（民法446条2項）。連帯保証人には催告・検索の抗弁権がありません（民法454条）。債権譲渡の第三者対抗要件は確定日付ある証書による通知または承諾です（民法467条2項）。", "example": ""}, "reason": {"text": "相殺（民法505条）は双方が互いに同種の債務を負担し、双方の弁済期が到来している場合に一方の意思表示で相殺できます。Bはもともとの相手方Cに対して持っていた債権をAが取得した場合、Bは譲渡前の原因に基づく相殺（民法469条）を主張できます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相殺の要件</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">双方が同種の債権</text></svg>", "choices": [{"label": "BはAに対して相殺を主張できないため800万円全額を支払わなければならない", "reason": "BはAに対して600万円の反対債権（もとCへの債権）があれば相殺を主張できます（民法505条・469条）。「全額支払い」は誤りです。", "caution": "債権譲渡後の相殺：譲渡前の原因に基づく相殺は可（民法469条）。"}, {"label": "債権譲渡があった場合相殺は一切できない", "reason": "債権が譲渡されても、債務者は譲渡前の原因に基づく相殺を新債権者に主張できます（民法469条）。「一切できない」は誤りです。", "caution": ""}, {"label": "相殺するにはAの同意が必要", "reason": "相殺は一方の意思表示で行えます（民法505条2項）。相手方（A）の同意は不要です。", "caution": ""}], "summary": {"head": ["債権譲渡と相殺（民法469条）", "内容"], "rows": [["原則", "譲渡前の原因に基づく相殺は新債権者に対抗可"], ["要件", "譲渡通知受領前または通知受領後に取得した反対債権"], ["効果", "相殺により相殺適状の範囲で双方の債権が消滅"]]}}},
  {id:10904,unit:'r_baibai',level:3,field:'rights',text:'AはBとの間で土地の売買契約を締結した。代金は5000万円で、契約時に手付金500万円を支払った。残代金4500万円の支払いと引渡しは3か月後の約定であった。支払期日が近づいたころ、BはAに対して「もう少し待ってほしい」と懇願したが、Aはこれを拒否し、自らは残代金4500万円の受領に備えて準備を整えた。その後、BはAに対して手付解除（手付倍返し）を申し出た。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['BはAが残代金の受領準備をしていても、Aが契約の履行に着手していなければ手付解除できる','Aが残代金の受領準備（履行の着手）をしている以上、BはもはやAの同意なしに手付解除できない','手付解除は代金支払期日前であればいつでもできる','Aが準備しただけでは履行の着手にはならない'],ans:1,exp:'手付解除は「相手方が契約の履行に着手した後」はできません（民法557条1項）。判例上「履行の着手」とは客観的に外部から認識できる程度に履行行為の一部をなしまたは履行の提供をするために欠くことのできない前提行為をした場合をいいます。AがBの残代金4500万円の受領準備を整えたことは履行の着手に当たる可能性があり、その後Bは手付解除できません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "解約手付による解除は相手方が「履行に着手」した後はできません（民法557条1項ただし書）。残代金の受領準備（残金準備・登記手続き準備等）は「履行の着手」に当たります（判例）。よってBはAの同意なしに手付解除できません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "Aが履行に着手していなければ手付解除できる", "reason": "Aが残代金の受領準備をしており「履行に着手」しているため、Bはもはや手付解除できません（民法557条1項ただし書）。", "caution": "履行の着手後＝手付解除不可。着手の例：残代金準備・登記手続き準備等（判例）。"}, {"label": "手付解除は代金支払期日前であればいつでもできる", "reason": "相手方の履行着手前まで手付解除ができます（民法557条1項ただし書）。支払期日前でも相手方が着手していれば解除できません。", "caution": ""}, {"label": "Aが準備しただけでは履行の着手にはならない", "reason": "判例は残代金の受領準備（現金の準備・銀行への準備指示等）も履行の着手と認めています（判例）。「準備だけでは着手でない」は誤りです。", "caution": ""}], "summary": {"head": ["手付解除の限界", "内容"], "rows": [["解除できる時期", "相手方の履行着手前まで（民法557条1項ただし書）"], ["履行の着手の例", "残代金準備・登記手続き準備・代金受領の準備等（判例）"], ["着手後の解除", "相手方の同意が必要（手付解除は不可）"]]}}},
  {id:10905,unit:'r_chinshaku',level:3,field:'rights',text:'AはBから居住用マンション（1LDK）を月額12万円で賃借している。AはBの承諾を得ずにCにこのマンションを転貸し（月額15万円）、自分はDのマンションに引っ越した。BはAの無断転貸を発見した。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['AのBに無断での転貸は軽微な違反であり、Bは解除できない','無断転貸は賃貸借契約の解除事由となるが、信頼関係を破壊しない特段の事情があると認められる場合は解除できない場合もある','BはAの無断転貸を発見した場合、直ちに賃貸借契約を解除でき、Cに対しても明渡しを求めることができる','CはBに対して転借権を主張できる'],ans:1,exp:'無断転貸は賃貸借契約の解除事由となりますが（民法612条2項）、判例上は信頼関係破壊の法理により、信頼関係を破壊しない特段の事情がある場合は解除が認められないことがあります。ただし通常の無断転貸・自己の転出を伴う場合は信頼関係の破壊が認められやすく、Bは解除できることが多いです。Bが解除した場合、CはBに対して転借権を主張できません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "無断転貸は解除事由となりますが（民法612条2項）、信頼関係破壊の法理により特段の事情がある場合は解除できません（判例）。一方、無断転貸により賃借人が転居してしまった場合は信頼関係破壊が認められやすくなります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "軽微な違反であり解除できない", "reason": "AがCに転貸して自身が転居した場合は、実質的に賃借人の占有がなくなっており信頼関係破壊が認められやすい状況です。単純に「軽微」とは言えません。", "caution": ""}, {"label": "発見直ちに解除でき明渡しを求められる", "reason": "判例の信頼関係破壊の法理により、特段の事情がある場合は解除できません（判例）。「直ちに解除できる」は誤りです。", "caution": ""}, {"label": "CはBに対して転借権を主張できる", "reason": "Bの無断転貸はBに対して対抗できません（民法612条2項）。CはBに賃借権を主張できますが、Bへの対抗力は条件によります。", "caution": ""}], "summary": {"head": ["無断転貸と解除", "内容"], "rows": [["原則", "解除事由（民法612条2項）"], ["例外", "信頼関係破壊なき特段の事情あれば解除不可（判例）"], ["賃借人転居の場合", "信頼関係破壊と認められやすい"], ["CのBへの対抗", "原賃貸借が解除されるとCはBに対抗不可"]]}}},
  {id:10906,unit:'r_souzoku',level:3,field:'rights',text:'Aには配偶者B、長男C、二男D、長女Eがいる。Aは死亡の1年前に長男Cに対して「老後の面倒を見てくれたお礼として」自己所有の土地（評価額3000万円）を贈与していた。Aが残した財産は預貯金2000万円のみである。Aは遺言を残していなかった。法定相続分に従った遺産分割において、特別受益（民法903条）を考慮した各相続人の相続分として正しいものはどれか。',opts:['Cへの贈与は特別受益に当たらないため、各相続人は預貯金2000万円をB1000万円・C333万円・D333万円・E333万円で分ける','Cへの贈与は特別受益（生計の資本としての贈与）に当たり、みなし相続財産は2000万円+3000万円=5000万円。B2500万円・C以外の子各417万円（約）の相続分算出後、Cの相続分625万円から贈与3000万円を差し引くと0（超過分は返還不要）','全ての贈与は特別受益とならない','老後の面倒を見た対価の贈与は相続財産に持ち戻す必要がない'],ans:1,exp:'老後の世話等への謝礼の贈与も判例上は生計の資本としての特別受益となり得ます（民法903条1項）。みなし相続財産5000万円で計算：B（1/2）=2500万円、C・D・E（各1/6）=各約833万円。Cの相続分833万円から特別受益3000万円を差し引くと超過（-2167万円）となりますが、返還義務はなく（民法903条2項）、Cの相続分は0円となります。残り2000万円はB2000万円×2500/3333≒約1500万円、D・E各250万円程度（持戻し免除なしの計算による）。',"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2", "basis": {"text": "配偶者と子の場合は各1/2（民法900条）。相続放棄は3か月以内に家庭裁判所へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2です（民法1042条）。遺産分割協議は全員合意が必要です。", "example": ""}, "reason": {"text": "特別受益の持ち戻し計算では、相続財産に特別受益を加えたみなし相続財産を基準に各相続人の相続分を計算します（民法903条1項）。特別受益を受けた者の相続分はその贈与額を差し引いた残額になります。超過した場合でも返還義務はありません（同条2項）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続の主要ポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子の相続分</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は法定相続分の1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割協議</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "Cへの贈与は特別受益に当たらない", "reason": "老後の面倒を見たお礼という名目でも、相当額の財産の贈与は生計の資本として特別受益に該当する可能性があります（民法903条1項・判例）。", "caution": ""}, {"label": "全ての贈与は特別受益とならない", "reason": "婚姻・養子縁組・生計の資本としての贈与は特別受益です（民法903条1項）。すべての贈与が非該当なわけではありません。", "caution": ""}, {"label": "老後の面倒を見た対価の贈与は持ち戻し不要", "reason": "「老後の面倒を見た対価」という性質があっても、それが寄与分として認められない限り、生計の資本としての贈与は特別受益として持ち戻しの対象となります（民法903条1項）。", "caution": ""}], "summary": {"head": ["特別受益の計算（設問）", "内容"], "rows": [["みなし相続財産", "預貯金2000万円＋贈与3000万円＝5000万円"], ["Bの相続分", "5000万円×1/2＝2500万円"], ["C・D・Eの相続分", "5000万円×1/6≒833万円（各）"], ["Cの取得分", "833万円－3000万円＜0→0円（返還不要）"]]}}},
  {id:10907,unit:'r_touki',level:3,field:'rights',text:'A所有の甲建物についてBが抵当権の設定を受け登記を完了した。その後、AはCに甲建物を売却しAからCへの所有権移転登記も完了した。BはCに対して抵当権の実行（競売）を申し立てた。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['Cが善意で甲建物を購入していれば、BはCに対して抵当権を主張できない','Bの抵当権はCへの所有権移転前に登記されているため、CはBの抵当権付きで甲建物を取得しており、BはCに対しても抵当権を実行できる','AからCへの所有権移転登記が先であれば、Bの抵当権は消滅する','Cは第三取得者として抵当権消滅請求（民法379条）を行使できる'],ans:1,exp:'抵当権は登記された後に取得した第三者（C）にも対抗できます（民法177条）。CはBの抵当権付きで甲建物を取得しており、BはCに対して抵当権を実行できます。Cの善意・悪意は無関係です。なおCは第三取得者として抵当権消滅請求（民法379条）を行使して、相当価格を払い込むことで抵当権を消滅させることができます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "抵当権は物権であり追及効があります（民法369条）。抵当権設定後に不動産の所有者が変わっても抵当権は消滅せず、第三取得者はその負担を承継します。善意・悪意は関係なく、抵当権は物権として誰にでも主張できます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "Cが善意で甲建物を購入していれば、BはCに対して抵当権を主張できない", "reason": "抵当権は物権であり絶対性・追及効があるため、Cの善意・悪意に関係なくBはCに対して抵当権を主張できます（民法369条）。", "caution": "抵当権の追及効は善意の第三取得者にも及びます。"}, {"label": "AからCへの所有権移転登記が先であれば、Bの抵当権は消滅する", "reason": "Bの抵当権はAからCへの所有権移転登記より前に登記されているため、Cへの移転後も抵当権は消滅しません（追及効）。", "caution": ""}, {"label": "Cは第三取得者として抵当権消滅請求を行使できる", "reason": "設問では「Bは競売を申し立てた」という状況ですが、第三取得者Cは確かに抵当権消滅請求（民法379条）を行使できます。ただし設問は「Bが抵当権を主張できる」という正解の確認が趣旨です。", "caution": ""}], "summary": {"head": ["抵当権と第三取得者", "内容"], "rows": [["追及効", "所有者が変わっても抵当権は不動産に追いかける"], ["代価弁済（民法378条）", "抵当権者の請求で弁済し消滅"], ["抵当権消滅請求（民法379条）", "第三取得者が相当額を支払い消滅を請求"], ["善意・悪意", "関係なし（抵当権は物権として誰にでも対抗可）"]]}}},
  {id:10908,unit:'r_shakuchi',level:3,field:'rights',text:'AはB所有の土地を賃借して建物を建て居住している（借地権設定・存続期間30年）。存続期間満了の6か月前に、AはBに対して「更新後の借地権の存続期間を20年としてほしい」と申し出た。Bはこれに応じた。この場合に関する記述として借地借家法の規定によれば正しいものはどれか。',opts:['更新後の存続期間は当事者の合意に従い20年となる','最初の更新後の法定存続期間は20年（それ以降は10年）であり、20年という合意は法定期間と一致しているため有効。ただし借地借家法上これより短い期間の合意は無効となる','更新後は存続期間を自由に定めることができ、1年でもよい','更新後の存続期間は常に30年となる'],ans:0,exp:'借地権の最初の更新後の存続期間は20年（その後の更新は10年）が法定されています（借地借家法4条）。当事者がこれより長い期間を定めることは有効ですが、これより短い期間の合意は無効となり、法定期間（20年）となります（借地借家法9条）。本問の20年という合意は法定期間と同じなので有効です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "更新後の借地権の存続期間は最初の更新後は20年、2回目以降は10年ですが（借地借家法4条）、当事者の合意でこれより長い期間を定めることは可能です。設問では当事者合意（20年）が法定更新期間（最初の更新：20年）と一致しているため有効です。借地借家法より借主に不利な特約は無効ですが（同法9条）、20年は法定期間以上のため有効です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "最初の更新後の法定存続期間は20年（それ以降は10年）であり20年という合意は有効", "reason": "最初の更新後の法定期間は20年ですが（借地借家法4条）、設問では合意で20年を定めており、法定期間以上なので有効です（同法9条）。この選択肢の内容は正しいですが選択肢1が正解です。", "caution": ""}, {"label": "更新後は存続期間を自由に定めることができ1年でもよい", "reason": "更新後は法定期間以上でなければなりません（借地借家法4条・9条）。1年は借主に不利な特約として無効です。", "caution": "更新後の期間：法定期間（最初20年・2回目以降10年）以上でなければならない（借地借家法9条）。"}, {"label": "更新後の存続期間は常に30年となる", "reason": "更新後の存続期間は最初の更新は20年、2回目以降は10年が法定期間です（借地借家法4条）。常に30年ではありません。", "caution": ""}], "summary": {"head": ["借地権の更新後の存続期間（借地借家法4条）", "期間"], "rows": [["最初の更新後", "20年（合意で延長可）"], ["2回目以降の更新", "10年（合意で延長可）"], ["短縮特約", "借主に不利→無効（借地借家法9条）"]]}}},
  {id:10909,unit:'l_menkyo',level:3,field:'law',text:'甲県知事免許を受けている宅建業者Aは、事業縮小のため主たる事務所のみを残して従たる事務所（乙県内）を廃止することにした。また同時に、Aの役員Bが拘禁刑刑（執行猶予2年付き）を受けたことが判明した。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['従たる事務所の廃止は免許の変更申請が必要','従たる事務所（乙県内）の廃止により事務所が甲県のみとなるが、元々甲県知事免許であるため免許換えは不要。ただし事務所の廃止は廃止後30日以内に免許権者へ届け出なければならない','役員Bの執行猶予付き拘禁刑刑は欠格事由に当たらず、Aの免許に影響はない','役員Bが拘禁刑以上の刑（執行猶予含む）に処された場合、Bは欠格事由（宅建業法5条1項5号）に該当し、Aも免許取消しの対象となる'],ans:3,exp:'拘禁刑以上の刑に処された者（執行猶予中の者を含む）は宅建業の免許欠格事由に該当します（宅建業法5条1項5号）。役員がこの欠格事由に該当する法人も免許欠格となり（同法5条1項12号）、免許取消しの対象となります（同法66条1項3号）。従たる事務所の廃止は廃止後30日以内に届け出が必要です（同法11条1項4号）。',"kaisetsu":{"topic": "宅建業の免許：知事・大臣免許の区別・有効期間5年・欠格事由", "basis": {"text": "1都道府県のみ→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間です。", "example": ""}, "reason": {"text": "役員が拘禁刑以上の刑（執行猶予付きを含む）に処された場合、その役員は欠格事由に該当し（宅建業法5条1項5号）、法人の免許も取消し事由となります（同法66条1項2号）。執行猶予付きでも欠格事由に該当します（執行猶予満了まで）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（拘禁刑以上・特定罰金等）</text></svg>", "choices": [{"label": "従たる事務所の廃止は免許の変更申請が必要", "reason": "事務所の廃止は変更届の対象です（宅建業法9条）。変更申請（免許換え）ではありません。", "caution": "事務所廃止＝変更届（免許換えではない）。"}, {"label": "事務所が甲県のみとなるが元々甲県知事免許であるため免許換えは不要。ただし事務所の廃止は廃止後30日以内に届け出なければならない", "reason": "事務所廃止の届出については30日以内という規定はなく、廃止した事実を変更届で届け出ます（宅建業法9条）。「30日以内」は廃業等の届出の規定（宅建業法11条）と混同しています。", "caution": ""}, {"label": "役員Bの執行猶予付き拘禁刑刑は欠格事由に当たらず免許に影響はない", "reason": "執行猶予付きの拘禁刑以上の刑も欠格事由に該当します（宅建業法5条1項5号）。執行猶予満了まで欠格事由です。", "caution": "執行猶予中も欠格事由（宅建業法5条1項5号）。"}], "summary": {"head": ["役員の執行猶予付き刑と欠格事由", "内容"], "rows": [["執行猶予中", "欠格事由に該当（宅建業法5条1項5号）"], ["執行猶予満了後", "欠格事由から外れる"], ["法人への影響", "役員が欠格事由→法人も免許取消しの対象"], ["対応", "役員の退任・新役員選任・届出が必要"]]}}},
  {id:10910,unit:'l_jusetsu',level:3,field:'law',text:'宅建業者Aは、Bが所有するアパート（1棟・8室）の賃貸借の媒介を行っている。Cがこのアパートの1室を賃借しようとしており、AはCに対して重要事項説明を行おうとしている。この建物は石綿（アスベスト）使用調査が実施されており、使用が確認されていないという結果が出ている。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['賃貸借においては重要事項説明書の交付のみで、口頭での説明は不要','石綿使用調査の結果については重要事項として説明しなければならない（調査記録が存在する場合）','石綿が使用されていないことが確認されているため、調査結果の説明は不要','賃貸借の重要事項説明は売買と比べて記載事項が少ないため、石綿の記載は不要'],ans:1,exp:'石綿（アスベスト）の使用の有無の調査結果の記録が存在する場合は、その内容を重要事項として説明しなければなりません（宅建業法35条1項14号・施行令3条1項27号）。使用されていないという結果であっても、調査記録が存在する以上その旨を説明する義務があります。賃貸借でも同様に説明義務があります。',"kaisetsu":{"topic": "重要事項説明：宅建士が説明・売主への交付は不要・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主への交付義務はありません。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能です。", "example": ""}, "reason": {"text": "石綿（アスベスト）使用調査が実施されている場合はその結果を重要事項として説明しなければなりません（宅建業法35条1項14号・施行規則16条の4の3第1号の2）。石綿が使用されていないことが確認されていても、調査結果の記載義務は残ります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "賃貸借においては重要事項説明書の交付のみで口頭での説明は不要", "reason": "賃貸借でも口頭での説明と書面交付の両方が必要です（宅建業法35条1項）。", "caution": ""}, {"label": "石綿が使用されていないことが確認されているため調査結果の説明は不要", "reason": "調査が実施されている場合はその結果（使用なしの場合もその結果）を記載・説明する義務があります（宅建業法施行規則16条の4の3第1号の2）。", "caution": "石綿使用なしの結果でも記載義務あり。"}, {"label": "賃貸借の重要事項説明は記載事項が少ないため石綿の記載は不要", "reason": "石綿使用調査の結果は賃貸借の重要事項説明でも記載が必要です（宅建業法施行規則16条の4の3第1号の2）。", "caution": ""}], "summary": {"head": ["石綿使用調査と重要事項説明", "内容"], "rows": [["調査がある場合", "結果を記載（使用なしでも記載必要）"], ["調査がない場合", "「調査が実施されていない旨」を記載"], ["対象", "売買・賃貸ともに適用"], ["石綿を使用していた場合", "使用の有無・内容等を詳細に記載"]]}}},
  {id:10911,unit:'l_baikai',level:3,field:'law',text:'宅建業者Aは、B所有のマンション（専有部分70m2）の売却について専任媒介契約を締結した。契約書に「有効期間3か月・更新は依頼者Bの申出がある場合のみ」と定めた。3か月経過後、Bから更新の申出はなかったが、AはBに対して「自動更新です」と説明して引き続き業務を行った。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['AとBの合意があれば自動更新も有効','専任媒介契約の有効期間は3か月を超えることができず、更新は依頼者Bからの申出によってのみ可能。Aが勝手に自動更新を主張することは宅建業法違反となる','媒介契約の更新方法は当事者の自由','3か月経過後はAは業務を行えないため報酬も請求できない'],ans:1,exp:'専任媒介契約の有効期間は3か月を超えることができず（宅建業法34条の2第3項）、更新は依頼者からの申出によるものでなければなりません（同法34条の2第4項）。宅建業者が自動更新を定めることや、依頼者の申出なしに更新したものとして扱うことは宅建業法違反です。',"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任媒介の有効期間の上限は3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。専任は7日以内、専属専任は5日以内にレインズ登録が必要。業務報告は専任2週間に1回、専属専任1週間に1回。", "example": ""}, "reason": {"text": "専任媒介契約の有効期間は3か月が上限で（宅建業法34条の2第3項）、更新は依頼者の申し出がある場合のみ可能です（同条3項ただし書）。業者が一方的に自動更新を主張することは宅建業法違反となります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">一般</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専任</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専属専任</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己発見取引</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">レインズ登録</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務報告</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">なし</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間に1回</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1週間に1回</text></svg>", "choices": [{"label": "AとBの合意があれば自動更新も有効", "reason": "依頼者からの申し出による更新が必要です（宅建業法34条の2第3項ただし書）。Aが「自動更新です」と一方的に主張することはできません。", "caution": "専任媒介の更新：依頼者Bの申し出が必要（宅建業法34条の2第3項）。"}, {"label": "媒介契約の更新方法は当事者の自由", "reason": "更新方法は宅建業法で規制されており（依頼者の申し出のみ・宅建業法34条の2第3項）、当事者の自由ではありません。", "caution": ""}, {"label": "3か月経過後はAは業務を行えないため報酬も請求できない", "reason": "有効期間が満了した場合は媒介契約が終了しますが、有効期間中に成約に至った案件については適切な報酬を請求できます。「業務行えない・報酬請求できない」は不正確です。", "caution": ""}], "summary": {"head": ["専任媒介の有効期間と更新", "内容"], "rows": [["有効期間上限", "3か月（宅建業法34条の2第3項）"], ["更新の条件", "依頼者の申し出のみ"], ["自動更新", "禁止（依頼者の申し出が必要）"], ["違反", "宅建業法違反→指示処分等"]]}}},
  {id:10912,unit:'l_hoshu',level:3,field:'law',text:'宅建業者Aは、売主B（宅建業者でない・個人）から依頼を受け、B所有の建物（賃貸中・月額賃料50万円）を一般媒介契約で売却の媒介をした。売買代金8000万円で売買契約が成立した。AはBから媒介報酬を受け取るが、その上限額（税別）として宅建業法の規定（報酬告示）によれば正しいものはどれか。',opts:['8000万円×3%＋6万円＝246万円','8000万円×2%＋4万円＝164万円','8000万円×3%＝240万円','8000万円×1%＝80万円'],ans:0,exp:'売買の媒介報酬の上限額（速算式）は、売買代金が400万円超の場合「代金×3%＋6万円（税別）」です（報酬告示）。8000万円×3%＋6万円＝246万円（税別）が上限となります。一般媒介・専任媒介・専属専任媒介で報酬上限額の計算方法は変わりません。',"kaisetsu":{"topic": "報酬：売買は代金×3%+6万（400万超）・賃貸は借賃1か月・上限超過は不可", "basis": {"text": "売買媒介報酬（400万超）の一方からの上限は代金×3%+6万円（税別）。双方合計は一方上限×2。賃貸媒介（居住用・非居住用とも）は借賃1か月分。依頼者の承諾があっても上限超過は不可。", "example": ""}, "reason": {"text": "売買代金8000万円（400万円超）の媒介報酬上限は速算式で8000万円×3%＋6万円＝246万円（税別）が一方の依頼者からの上限です（告示）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対象</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（400万超）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万（一方）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（200万以下）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸（双方合計）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借賃1か月分</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">低廉な空家等（800万円以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円まで（説明・合意要）</text></svg>", "choices": [{"label": "8000万円×2%＋4万円＝164万円", "reason": "2%＋4万円という計算式はありません（告示）。速算式は3%＋6万円です。", "caution": "速算式：代金×3%＋6万円（400万円超・告示）。"}, {"label": "8000万円×3%＝240万円", "reason": "×3%だけでは不足です（告示）。3%＋6万円の速算式なので240万円＋6万円＝246万円が正しいです。", "caution": ""}, {"label": "8000万円×1%＝80万円", "reason": "1%という料率はありません（告示）。速算式は3%＋6万円です。", "caution": ""}], "summary": {"head": ["設問の報酬計算", "内容"], "rows": [["代金", "8000万円"], ["速算式", "8000万円×3%＋6万円"], ["計算", "240万円＋6万円＝246万円（税別）"], ["消費税込", "246万円×1.1＝270.6万円"]]}}},
  {id:10913,unit:'k_toshi',level:3,field:'limit',text:'AはI市（都市計画区域内・用途地域未指定の白地地域）に土地を所有し、倉庫（延べ面積1500m2）を建築しようとしている。I市は特定用途制限地域を指定しておらず、建ぺい率・容積率の都市計画上の定めもない。この場合に関する記述として建築基準法の規定によれば正しいものはどれか。',opts:['用途地域が指定されていない地域では建築基準法が適用されないため、何でも建てられる','用途地域の指定のない区域にも建築基準法は適用され、建ぺい率は70%以下・容積率は200%以下等の制限が適用される（建築基準法52条・53条）','用途地域未指定地域では建築確認が不要','倉庫は用途地域指定地域にしか建てられない'],ans:1,exp:'用途地域の指定のない区域（白地地域）にも建築基準法は適用されます。用途地域の指定のない区域では建ぺい率の上限は70%（特定行政庁指定）・容積率は200%または400%（特定行政庁指定）が適用されます（建築基準法53条1項6号・52条1項7号）。また建築確認も必要な場合があります（規模・用途による）。',"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域での1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は市街化調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "用途地域の指定のない区域にも建築基準法は適用されます（建築基準法1条・2条）。建ぺい率・容積率は建築基準法52条・53条の規定（一般地域の数値）が適用されます。建築確認も必要な場合があります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化する区域</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可基準</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "用途地域が指定されていない地域では建築基準法が適用されないため何でも建てられる", "reason": "建築基準法はすべての建築物に適用されます（建築基準法1条）。用途地域の指定の有無は建築基準法の適用とは別問題です。", "caution": "用途地域未指定区域にも建築基準法は適用される。"}, {"label": "用途地域未指定地域では建築確認が不要", "reason": "建築確認は用途地域の指定の有無に関わらず必要な場合があります（建築基準法6条）。", "caution": ""}, {"label": "倉庫は用途地域指定地域にしか建てられない", "reason": "倉庫は用途地域指定の有無に関わらず建築基準法の要件を満たせば建築できます（建築基準法別表第二等）。", "caution": ""}], "summary": {"head": ["用途地域未指定区域の建築制限", "内容"], "rows": [["建築基準法", "適用される"], ["建ぺい率", "法定値（70%等）が適用（建築基準法53条）"], ["容積率", "法定値（200%等）が適用（建築基準法52条）"], ["建築確認", "必要な場合あり"]]}}},
  {id:10914,unit:'k_kenchiku',level:3,field:'limit',text:'AはJ市内において、既存の木造住宅（築45年・耐震性能が現行基準を大きく下回る）を取り壊して、鉄筋コンクリート造3階建て共同住宅（延べ面積600m2・各戸30m2以上）を新築しようとしている。この建物の建築にあたっての確認申請について建築基準法の規定によれば正しいものはどれか。',opts:['木造から RC 造への建て替えであるため特別な手続きは不要','共同住宅は特殊建築物（建築基準法別表第一）に該当し、用途に供する部分の床面積が200m2超の場合は建築確認が必要。延べ面積600m2の共同住宅は確認申請が必要','RC造3階建ては建築確認不要','都市計画区域外では建築確認不要'],ans:1,exp:'共同住宅は建築基準法別表第一（い）欄の特殊建築物に該当し、用途に供する部分の床面積が200m2を超えるものは建築確認申請が必要です（建築基準法6条1項1号）。延べ面積600m2の共同住宅は200m2超であるため確認申請が必要です。また都市計画区域内のRC造3階建て（高さや規模により）も確認申請対象となります。',"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・道路斜線・用途制限", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。用途地域ごとに建築物の制限があります。", "example": ""}, "reason": {"text": "共同住宅は特殊建築物（建築基準法別表第一）に該当し、用途に供する部分の床面積200㎡超の場合は建築確認が必要です（建築基準法6条1項1号）。延べ面積600㎡の共同住宅は確認申請が必要です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">第1種低層</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">学校は建築可</text></svg>", "choices": [{"label": "木造からRC造への建て替えであるため特別な手続きは不要", "reason": "建て替えの種類（木造→RC等）に関わらず建築確認が必要な場合があります（建築基準法6条1項）。共同住宅600㎡は確認申請が必要です。", "caution": "共同住宅（特殊建築物）200㎡超：確認申請必要（建築基準法6条1項1号）。"}, {"label": "RC造3階建ては建築確認不要", "reason": "RC造3階建て（500㎡超等）は確認申請が必要です（建築基準法6条1項2号・3号）。「不要」は誤りです。", "caution": ""}, {"label": "都市計画区域外では建築確認不要", "reason": "都市計画区域外でも特殊建築物（200㎡超）や大規模建築物は確認申請が必要です（建築基準法6条1項1号・2号・3号）。", "caution": ""}], "summary": {"head": ["共同住宅の建築確認（建築基準法6条1項1号）", "内容"], "rows": [["共同住宅", "特殊建築物（別表第一）に該当"], ["確認申請の要件", "用途に供する部分の床面積200㎡超"], ["600㎡の場合", "200㎡超→確認申請必要"], ["場所", "都市計画区域内外を問わず必要（1号）"]]}}},
  {id:10915,unit:'k_nochi',level:3,field:'limit',text:'農業法人Aは、農業委員会の許可を受けて農地（田・面積10000m2・市街化調整区域内）を取得し農業を営んでいる。その後、Aはこの農地の一部（2000m2）を採草放牧地に転用し、残り（8000m2）は引き続き農地として利用しようとしている。この場合に関する記述として農地法の規定によれば正しいものはどれか。',opts:['農地を採草放牧地に転用することは農地法4条の転用に当たらないため、許可不要','農地を採草放牧地に転用する場合は農地法4条（農地の転用）の許可が必要','農地を採草放牧地に転用する場合は農地法3条（権利移動）の許可が必要','農業法人による農地の転用は常に許可不要'],ans:1,exp:'農地を採草放牧地に転用する場合は、農地法4条1項の許可が必要です（農地を農地以外の土地に転用する場合に該当・採草放牧地への転用も「農地以外」への転用）。市街化区域内であれば農業委員会への届出のみで足りますが、本問は市街化調整区域内であるため都道府県知事の許可が必要です。',"kaisetsu":{"topic": "農地法：3条は農業委員会・4条・5条は都道府県知事・市街化区域は届出のみ", "basis": {"text": "農地法3条（権利移動・農地→農地）の許可権者は農業委員会。4条（自己転用）・5条（転用目的の権利移動）は都道府県知事等。市街化区域内の農地転用（4・5条）は農業委員会への届出のみでOK。相続は許可不要・届出3か月以内。", "example": ""}, "reason": {"text": "農地を採草放牧地に転用する場合は農地法4条の転用の許可が必要です（農地法4条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">市街化区域</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">特例なし</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text></svg>", "choices": [{"label": "農地を採草放牧地に転用することは農地法4条の転用に当たらないため許可不要", "reason": "農地から採草放牧地への転用は農地法4条の適用対象です（農地法4条1項）。「当たらない」は誤りです。", "caution": "農地→採草放牧地への転用：農地法4条の許可が必要（農地法4条1項）。"}, {"label": "農地を採草放牧地に転用する場合は農地法3条（権利移動）の許可が必要", "reason": "農地→採草放牧地は転用の問題（農地法4条）であり、権利移動（農地法3条）の問題ではありません。", "caution": ""}, {"label": "農業法人による農地の転用は常に許可不要", "reason": "農業法人でも農地転用には原則として農地法4条の許可が必要です（農地法4条1項）。", "caution": ""}], "summary": {"head": ["農地→採草放牧地への転用", "内容"], "rows": [["農地法4条の適用", "あり（農地の転用として規制）"], ["許可権者", "都道府県知事"]]}}},
  {id:10916,unit:'t_joto',level:3,field:'tax',text:'Aは15年前に3000万円で取得した居住用一戸建て住宅（土地・建物）を4500万円で売却した。Aの取得費（土地・建物の購入価格＋取得諸費用）は3100万円、譲渡費用（仲介手数料等）は135万円である。Aはこの住宅に引き続き居住しており、売却後は別の住宅に転居する予定である（新住宅への買換えは行わない）。居住用財産の3000万円特別控除を適用した場合の課税譲渡所得として正しいものはどれか。',opts:['課税譲渡所得＝(4500万円－3100万円－135万円)－3000万円＝△1735万円（課税なし）','課税譲渡所得＝4500万円－3000万円＝1500万円','課税譲渡所得＝(4500万円－3100万円)＝1400万円','3000万円控除後の課税所得が1265万円となり長期譲渡税率20%で253万円の税額'],ans:0,exp:'譲渡所得＝4500万円（収入）－3100万円（取得費）－135万円（譲渡費用）＝1265万円。3000万円特別控除（租税特別措置法35条）を適用すると、1265万円－3000万円＝△1735万円となり課税なしとなります。所有期間15年で長期譲渡所得に該当しますが、3000万円控除で課税所得がゼロ以下となるため納税は生じません。',"kaisetsu":{"topic": "譲渡所得：分離課税・長期は20%・3,000万円控除は3年に1回", "basis": {"text": "土地・建物の譲渡所得は分離課税（申告分離課税）。長期（5年超）の税率は合計20%（所得税15%+住民税5%）。短期（5年以下）は39%（所得税30%+住民税9%）。3,000万円特別控除は前年・前々年に適用があれば使えません（3年に1回）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">譲渡所得のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税方式</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">分離課税</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">長期（5年超）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計20%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">短期（5年以下）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計39%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3,000万円控除</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年に1回の制限</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10917,unit:'t_shutoku',level:3,field:'tax',text:'AはK県内の中古住宅（昭和63年新築・木造・延べ面積90m2・固定資産税評価額：建物700万円・土地1500万円）を購入した。不動産取得税の軽減措置を適用した場合の建物の不動産取得税として正しいものはどれか（昭和57年1月1日以降に新築の中古住宅の軽減措置を考慮すること）。',opts:['建物評価額700万円×3%＝21万円（特例なし）','昭和57年1月1日以降に新築された住宅（昭和63年新築）は一定の耐震基準を満たすものとして1200万円控除の特例が適用される。(700万円－1200万円)×3%＝0円（控除額が評価額を上回るため不動産取得税はかからない）','築年数が古いため軽減措置の適用なし','建物の不動産取得税は固定資産税評価額の2%'],ans:1,exp:'1982年（昭和57年）1月1日以降に新築された住宅（昭和63年築は該当）は、耐震基準適合住宅として中古住宅取得時の不動産取得税軽減措置（課税標準から1200万円控除）が適用されます（地方税法73条の14第2項）。700万円（評価額）－1200万円（控除額）＝△500万円となり、課税標準がゼロ以下となるため不動産取得税はかかりません。',"kaisetsu":{"topic": "不動産取得税：都道府県が課す地方税・相続は非課税・1回だけ課税", "basis": {"text": "不動産取得税は都道府県が課す地方税です（地方税法73条の2）。相続・法人の合併等による取得は非課税。一度の取得に一度だけ課税される（固定資産税と異なり毎年ではない）。標準税率は4%（住宅・土地は3%の軽減あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産取得税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税の頻度</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取得時に1回のみ</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">標準税率</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4%（住宅・土地は3%）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10918,unit:'r_fuhoko',level:3,field:'rights',text:'AはBの自転車の整備を依頼したが、整備作業中にCの不注意で部品が破損した。CはAの従業員ではなく、作業を手伝いに来た友人であった。Bは破損した自転車の修理費用10万円と、自転車が使えないことによる得べかりし利益（逸失利益）5万円の損害を被った。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['CはAの従業員でないため、AはBに対して使用者責任を負わない','CはAの指揮命令に従って作業しており、実質的な使用関係が認められれば、Aは使用者責任（民法715条）を負う可能性がある','BはCに対してのみ損害賠償を請求できる','逸失利益は損害賠償の対象とならない'],ans:1,exp:'使用者責任（民法715条）の「被用者」は雇用契約の有無にかかわらず実質的な指揮監督関係があれば認められます（判例）。CがAの指揮監督下で作業していた場合はAの使用者責任が成立します。逸失利益（相当因果関係のある利益の喪失）は損害賠償の対象です（民法416条2項類推）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "使用者責任（民法715条1項）の「使用関係」は雇用契約に限らず、実質的な指揮命令関係があれば認められます（判例）。友人がAの指揮命令に従って作業している場合、事実上の使用関係が認められれば使用者責任が成立しえます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "CはAの従業員でないためAはBに対して使用者責任を負わない", "reason": "使用者責任の「使用関係」は雇用契約に限らず実質的な指揮命令関係があれば認められます（判例）。従業員でなくても使用者責任が成立する場合があります。", "caution": "使用者責任の使用関係＝雇用契約に限らない（実質的指揮命令関係）。"}, {"label": "BはCに対してのみ損害賠償を請求できる", "reason": "使用者責任が成立する場合、BはAに対しても損害賠償を請求できます（民法715条1項）。", "caution": ""}, {"label": "逸失利益は損害賠償の対象とならない", "reason": "逸失利益（得べかりし利益）は損害賠償の対象となります（民法709条・最判等）。", "caution": ""}], "summary": {"head": ["使用者責任の使用関係", "内容"], "rows": [["雇用契約", "使用関係あり"], ["請負・委任", "原則使用関係なし（実態により判断）"], ["友人・ボランティア", "実質的指揮命令関係があれば使用関係あり（判例）"], ["判断基準", "実質的な指揮命令・監督関係の有無"]]}}},
  {id:10919,unit:'r_ishi',level:3,field:'rights',text:'Aは不動産業者Bから「この土地は近く新幹線の駅が設置される予定で価値が上がる」という説明を聞き、甲土地を3000万円で購入した。しかし実際には新幹線の駅設置計画は存在せず、Bはこれを知りながら虚偽の説明をしていた。Aはこの事実を購入から1年後に知った。AはBに対して契約を取り消すとともに、支払い済みの代金の返還と損害賠償を請求したいと考えている。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['詐欺取消しと損害賠償請求は両立できないため、どちらか一方を選択しなければならない','詐欺を理由とする取消しと不法行為（民法709条）に基づく損害賠償請求は同時に主張できる。取消しにより支払い済みの代金はBに不当利得として返還請求でき、さらに取消しで回復しきれない損害（相当因果関係のある損害）は別途損害賠償で請求できる','取消権の行使期間は詐欺を知ってから1年以内','損害賠償請求には裁判が必要'],ans:1,exp:'詐欺による取消し（民法96条）と不法行為に基づく損害賠償（民法709条）は同時に主張できます（請求権競合）。取消しにより契約は遡及的に無効となり、AはBに支払い済みの代金3000万円を不当利得として返還請求できます（民法703条）。さらに詐欺によって被った損害（代金と土地の実際の価値との差額等）は不法行為に基づく損害賠償で請求できます。詐欺取消権の消滅時効は詐欺を知った時から5年・行為時から20年です（民法126条）。',"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "意思表示の瑕疵には詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失の第三者は保護）・通謀虚偽表示（無効・善意の第三者は保護）があります。", "example": ""}, "reason": {"text": "詐欺取消し（民法96条）と不法行為に基づく損害賠償（民法709条）は独立した請求権で、両立して主張できます。取消しにより不当利得返還請求（民法703条）が可能で、さらに損害が残る場合は損害賠償請求もできます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "詐欺取消しと損害賠償請求は両立できないためどちらか一方を選択しなければならない", "reason": "取消しによる不当利得返還請求と不法行為による損害賠償請求は両立します。選択は不要です。", "caution": ""}, {"label": "取消権の行使期間は詐欺を知ってから1年以内", "reason": "詐欺取消権の時効は追認できる時（詐欺を知った時）から5年、行為時から20年です（民法126条）。1年は誤りです。", "caution": "「1年」は不法行為の短期時効（民法724条：知った時から3年、令和2年改正後）と混同しているようです。"}, {"label": "損害賠償請求には裁判が必要", "reason": "損害賠償請求は裁判外の請求（内容証明郵便等）でも行えます。裁判は請求が認められない場合の強制執行の手段です。", "caution": ""}], "summary": {"head": ["請求権", "内容", "時効"], "rows": [["詐欺取消し（96条）＋不当利得返還（703条）", "代金の返還", "取消権：追認できる時から5年"], ["不法行為損害賠償（709条）", "取消しで回復できない損害", "損害・加害者を知った時から3年"]]}}},
  {id:10920,unit:'r_dairi',level:3,field:'rights',text:'AはB（成年被後見人）の成年後見人に選任されている。AはBを代理して、B所有の甲不動産をCに売却しようとしている。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['成年後見人Aは当然にBを代理して不動産を売却できる','Bが居住している建物・敷地（居住用不動産）をAが売却するには、家庭裁判所の許可が必要（民法859条の3）。居住用でない場合は後見人Aの代理権の範囲内で売却できる','成年後見人は不動産を売却する代理権を持たない','成年後見人による不動産売却には被後見人Bの同意が必要'],ans:1,exp:'成年後見人が成年被後見人の居住用不動産を売却・賃貸・担保提供等する場合は家庭裁判所の許可が必要です（民法859条の3）。居住用でない不動産については後見人の代理権の範囲内で売却できます。成年被後見人Bの同意は法律上は不要です（同意能力がない前提のため）。',"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護する制度です。", "example": ""}, "reason": {"text": "成年後見人は被後見人の財産管理・法律行為の代理権を持ちますが（民法859条1項）、居住用不動産の処分については家庭裁判所の許可が必要です（民法859条の3）。被後見人の生活の基盤を守るための特別な規定です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "成年後見人Aは当然にBを代理して不動産を売却できる", "reason": "居住用不動産の処分には家庭裁判所の許可が必要です（民法859条の3）。当然に売却できるわけではありません。", "caution": "居住用不動産＝家庭裁判所の許可必要。非居住用＝後見人の代理権の範囲内。"}, {"label": "成年後見人は不動産を売却する代理権を持たない", "reason": "成年後見人は財産管理の代理権を持ちます（民法859条1項）。ただし居住用不動産には家裁の許可が追加で必要です。", "caution": ""}, {"label": "成年後見人による不動産売却には被後見人Bの同意が必要", "reason": "成年被後見人は法律行為能力が制限されているため、Bの同意を要件とすることは意味をなしません。必要なのは家庭裁判所の許可（居住用の場合）です。", "caution": ""}], "summary": {"head": ["不動産の種類", "必要な手続き"], "rows": [["居住用不動産（Bの居住建物・敷地）", "家庭裁判所の許可が必要（民法859条の3）"], ["非居住用不動産", "成年後見人の代理権の範囲内で処分可"]]}}},
  {id:10921,unit:'r_tanpo',level:3,field:'rights',text:'AはB銀行から3000万円を借り入れ、A所有の甲土地（時価4000万円）にB銀行のために抵当権を設定した。その後Aは甲土地の上に建物（乙建物）を建築した。AはB銀行への返済が滞り、B銀行は甲土地の競売を申し立てた。この場合（法定地上権の成否）に関する記述として民法の規定及び判例によれば正しいものはどれか。',opts:['甲土地の抵当権設定時に乙建物は存在しなかったため、法定地上権（民法388条）は成立しない','甲土地の競売の際に乙建物が存在すれば、常に法定地上権が成立する','B銀行が同意すれば法定地上権が成立する','法定地上権は土地と建物が別人の所有になった場合のみ成立する'],ans:0,exp:'法定地上権（民法388条）の成立要件は①抵当権設定時に土地と建物が同一人の所有②その後競売で土地・建物が別人の所有になること、の両方が必要です。本問では抵当権設定時（甲土地への抵当権設定時）に乙建物は存在していなかったため、法定地上権の成立要件を満たさず、法定地上権は成立しません。競売後に乙建物の所有者（A）は土地使用権限を失い退去を求められる可能性があります。',"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権です（民法369条）。質権は占有の移転が必要です。先取特権は法律上当然に成立する法定担保物権です。", "example": ""}, "reason": {"text": "法定地上権（民法388条）の成立要件の一つは抵当権設定時に建物が存在することです（判例）。抵当権設定時に建物が存在しなかった場合、後に建物が建てられても法定地上権は成立しません。なぜなら土地のみへの抵当権設定時は土地の担保価値は建物なしの状態で評価されているためです。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・非占有</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・占有</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "甲土地の競売の際に乙建物が存在すれば常に法定地上権が成立する", "reason": "法定地上権の成立には抵当権設定時に建物が存在していることが要件です（判例）。競売時に建物があっても設定時になければ成立しません。", "caution": "法定地上権の判断時期＝抵当権設定時（競売時ではない）。"}, {"label": "B銀行が同意すれば法定地上権が成立する", "reason": "法定地上権は法律上の要件を満たせば当然に成立します。B銀行の同意は要件ではありません。", "caution": ""}, {"label": "法定地上権は土地と建物が別人の所有になった場合のみ成立する", "reason": "競売によって土地・建物の所有者が分離することが要件ですが、これは法定地上権の成立要件の一つです。「のみ」という表現は正しいですが、他の要件（設定時の建物存在等）も必要です。", "caution": ""}], "summary": {"head": ["法定地上権の成立要件", "内容"], "rows": [["①設定時に建物が存在", "判断時期は抵当権設定時（重要）"], ["②設定時に同一所有者", "土地と建物が同一人の所有"], ["③競売で所有者が分離", "競売により別人の所有になること"], ["設定後の建築", "設定時に建物なし→法定地上権不成立（判例）"]]}}},
  {id:10922,unit:'l_37jo',level:3,field:'law',text:'宅建業者Aが媒介した土地付き建物（新築）の売買契約において、売主（建売業者B）と買主C（個人・宅建業者でない）の間で次の内容が合意された：代金5000万円、手付金500万円（契約時）、残金4500万円（引渡し時）、引渡し日2025年9月1日、住宅品質確保法に基づく住宅性能評価書あり、住宅ローン特約あり（ローン不成立の場合の白紙解除）。37条書面に記載しなければならない事項として宅建業法の規定によれば正しいものはどれか。',opts:['住宅性能評価書の内容を37条書面に全て転記しなければならない','代金5000万円・手付金500万円・残金4500万円の支払時期・支払方法・引渡し日2025年9月1日・移転登記申請時期は37条書面の必要的記載事項であり、住宅ローン特約は定めがある場合の任意的記載事項','37条書面は買主Cにのみ交付すれば足りる','住宅性能評価書の有無は37条書面への記載不要'],ans:1,exp:'37条書面の必要的記載事項（宅建業法37条1項）：代金の額・支払時期・方法、物件の引渡し時期、移転登記申請の時期等。住宅ローン特約（融資利用に関する定め）は定めがある場合の任意的記載事項（同法37条1項8号）。住宅性能評価書の内容は35条書面（重要事項説明）の記載事項で、37条書面に全内容の転記は不要。37条書面は売主B・買主C双方に交付が必要（同法37条1項・2項）。',"kaisetsu":{"topic": "37条書面：全取引で交付・記名（押印不要）・移転登記申請時期は必要的記載事項", "basis": {"text": "37条書面は売買・交換・賃貸借の全取引で契約の双方当事者に交付が義務（宅建業法37条）。引渡し時期・移転登記申請時期は必要的記載事項。2021年改正で押印は不要になり記名のみで足ります。", "example": ""}, "reason": {"text": "代金5000万円・手付金500万円・残金4500万円の各支払時期・支払方法・引渡し日は必要的記載事項です（宅建業法37条1項2号・4号）。ローン特約は任意的記載事項（定めがある場合・同条1項8号）、住宅性能評価の内容全転記は不要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付義務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全取引・双方当事者</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡時期・移転登記申請時期等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要）</text></svg>", "choices": [{"label": "住宅性能評価書の内容を37条書面に全て転記しなければならない", "reason": "住宅性能評価を受けた旨は35条書面の記載事項であり（宅建業法施行令3条等）、37条書面への全転記義務はありません。", "caution": "住宅性能評価：35条書面の記載事項（37条書面への全転記不要）。"}, {"label": "37条書面は買主Cにのみ交付すれば足りる", "reason": "37条書面は売主B・買主C双方に交付しなければなりません（宅建業法37条1項）。", "caution": ""}, {"label": "住宅性能評価書の有無は37条書面への記載不要", "reason": "住宅性能評価を受けた旨は35条書面の記載事項です（宅建業法施行令等）。37条書面の必須記載事項ではないという点は正しいですが、35条書面への記載義務はあります。", "caution": ""}], "summary": {"head": ["設問の各事項", "35条書面か37条書面か"], "rows": [["代金・手付金・支払時期・方法", "37条書面（必要的）"], ["引渡し日", "37条書面（必要的）"], ["ローン特約", "37条書面（任意的）"], ["住宅性能評価を受けた旨", "35条書面（必要的）"]]}}},
  {id:10923,unit:'r_sorin',level:3,field:'rights',text:'Aは都市部に土地（A地）を所有しており、A地の隣にはB所有のB地がある。A地とB地の間には古い塀があり、その塀の所有者が誰か不明である。AはB地に通じる唯一の通路として、A地を通行する権利（通行地役権または囲繞地通行権）をB地のために主張したいと考えている。B地は公道に面していない（袋地）。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['B地が袋地（公道に接していない）であっても、Bは一切A地を通行できない','B地が袋地（他の土地に囲まれて公道に出られない土地）の場合、BはA地（囲繞地）を通行できる権利（囲繞地通行権・民法210条）を有する。ただし通行は必要最小限にとどめ、通常は損害に対して償金を支払う必要がある','Bが通行地役権を登記しなければ通行できない','囲繞地通行権の行使にはAの同意が必要'],ans:1,exp:'袋地の所有者（B）は、囲繞地（A地等）を通行する権利（囲繞地通行権・民法210条）を有します。この権利は法律上当然に発生するものであり、Aの同意も登記も不要です。ただし通行は袋地の利用に必要な限度に限られ、囲繞地所有者（A）に最も損害の少ない場所・方法で行い、通常は損害に応じた償金を支払う義務があります（民法212条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "B地が袋地（公道に至らない土地）の場合、BはA地（囲繞地）を通行できる法律上の権利（囲繞地通行権・民法210条）を有します。この権利は法律上当然に発生し、Aの同意は不要です。ただし通行は必要最小限・損害の最少の方法に限られ、償金が必要です（民法211条・212条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "B地が袋地であってもBは一切A地を通行できない", "reason": "袋地の所有者は囲繞地通行権（民法210条1項）を有し、A地を通行できます。「一切通行できない」は誤りです。", "caution": "袋地→囲繞地通行権（法律上当然の権利・民法210条）。"}, {"label": "Bが通行地役権を登記しなければ通行できない", "reason": "囲繞地通行権は登記なしに行使できます（民法210条1項・法律上当然の権利）。通行地役権とは異なります。", "caution": ""}, {"label": "囲繞地通行権の行使にはAの同意が必要", "reason": "囲繞地通行権は法律上当然に認められる権利であり（民法210条1項）、Aの同意は不要です。", "caution": ""}], "summary": {"head": ["囲繞地通行権と通行地役権", "囲繞地通行権", "通行地役権"], "rows": [["根拠", "民法210条（法律上当然）", "当事者の合意（契約）"], ["登記", "不要", "対抗要件として必要"], ["償金", "原則必要（民法212条）", "合意による"], ["範囲", "損害最少の方法・場所", "合意の内容による"]]}}},
  {id:10924,unit:'k_kukaku',level:3,field:'limit',text:'土地区画整理事業（市施行）において、換地計画が作成され換地処分が行われようとしている。区域内に土地を所有するAは、自己の従前地（面積200m2）に対して指定された換地（面積160m2）が従前地より小さいことに不満を持っている。この場合に関する記述として土地区画整理法の規定によれば正しいものはどれか。',opts:['換地は従前地と同面積でなければならないため、160m2の換地指定は違法','換地処分後に換地面積が従前地より小さい場合は、面積の差に応じた清算金が交付される。AはBから清算金を受け取ることができる','換地は施行者が自由に決定できるため、AはAへの換地の内容を争えない','換地が従前地より小さくなることはあり得ない'],ans:1,exp:'換地計画では従前地と換地の照応原則が適用されますが、形状・位置・地積・環境等を総合考慮して換地が決定されます（土地区画整理法89条1項）。換地面積が従前地より小さい場合は、換地処分後に差額に相当する清算金が徴収または交付されます（同法94条）。AはBから清算金（160m2と200m2の差額相当）を受け取ることになります。',"kaisetsu":{"topic": "土地区画整理法：換地は公告翌日確定・仮換地は従前地使用不可・組合は2/3以上", "basis": {"text": "換地処分の公告翌日から換地が確定します（土地区画整理法104条）。仮換地の指定後は従前地を使用できなくなります（同法99条）。組合設立には土地所有者・借地権者の各2/3以上の同意が必要です。", "example": ""}, "reason": {"text": "換地が従前地より面積が小さい場合（価値が小さい場合）は、施行者から清算金が交付されます（土地区画整理法94条）。照応の原則により換地が指定されます（同法89条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">土地区画整理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">換地の確定</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公告の翌日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮換地指定後</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従前地は使用不可（所有権は残る）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">組合設立</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各2/3以上の同意</text></svg>", "choices": [{"label": "換地は従前地と同面積でなければならないため160m2の換地指定は違法", "reason": "換地は照応の原則によるものであり、同面積である必要はありません（土地区画整理法89条）。", "caution": "換地：同面積でなくてよい。差は清算金で調整（土地区画整理法89条・94条）。"}, {"label": "換地は施行者が自由に決定できるためAはAへの換地の内容を争えない", "reason": "換地は照応の原則（土地区画整理法89条）に従う必要があり、縦覧・意見書等で争うことができます。", "caution": ""}, {"label": "換地が従前地より小さくなることはあり得ない", "reason": "照応の原則の下で換地面積が小さくなる場合があります。清算金で調整されます。", "caution": ""}], "summary": {"head": ["設問の換地処理", "内容"], "rows": [["従前地", "200m2"], ["換地", "160m2（40m2減少）"], ["清算金", "面積減少分の価値に応じた清算金が交付される"]]}}},
  {id:10925,unit:'t_kotei',level:3,field:'tax',text:'AはL市（都市計画区域内・市街化区域）内に次の不動産を所有している：①居住用住宅の敷地（小規模住宅用地・180m2・固定資産税評価額2000万円）②居住用住宅（新築から3年経過・木造・延べ面積120m2・固定資産税評価額1200万円）。この場合の固定資産税額として正しいものはどれか（標準税率1.4%・新築住宅の軽減特例を考慮）。',opts:['①2000万円×1.4%+②1200万円×1.4%＝28万円+16.8万円=44.8万円','①2000万円×1/6×1.4%+②1200万円×1/2×1.4%＝4.67万円+8.4万円≒13.07万円（土地の小規模住宅用地特例1/6・建物の新築住宅軽減特例1/2）','①2000万円×1/3×1.4%+②1200万円×1.4%＝9.33万円+16.8万円≒26.13万円','土地・建物とも特例なし'],ans:1,exp:'①小規模住宅用地（200m2以下・1戸あたり）の固定資産税の課税標準は評価額の1/6（地方税法349条の3の2）。②新築住宅（一般木造）は新築から3年間、居住部分（120m2まで）の固定資産税税額が1/2に軽減（地方税法附則15条の6）。①：2000万円×1/6×1.4%≒4.67万円。②：1200万円×1.4%×1/2（税額軽減）≒8.4万円。合計約13.07万円。',"kaisetsu":{"topic": "固定資産税：市町村が課す地方税・賦課期日は1月1日・評価替えは3年ごと", "basis": {"text": "固定資産税は市町村（東京23区は都）が課す地方税です（地方税法343条）。賦課期日は毎年1月1日。評価替えは3年ごと（基準年度）。住宅用地の特例：200㎡以下は課税標準1/6、超過部分は1/3。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">固定資産税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市町村（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賦課期日</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">評価替え</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年ごと</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅用地（200㎡以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税標準1/6</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10926,unit:'r_jiko',level:3,field:'rights',text:'AはBとの間で商品売買契約を締結し、BはAに100万円を支払った。しかしAは商品をBに引き渡さないまま1年が経過した。Bは催告もせずにいたが、2年後にAに対して商品の引渡しを求め、引渡しができないなら損害賠償を請求した。Aは「消滅時効が完成している」と主張している。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['商品引渡し債権の消滅時効は1年であり、すでに時効は完成している','商品引渡し債権の消滅時効期間は権利を行使できることを知った時から5年（民法166条1項1号）または権利を行使できる時から10年（同条1項2号）の短い方。2年経過はまだ5年以内であり、時効は完成していない','Bが催告しなかったことは信義則上問題となり請求できない','Bは催告後6か月以内に提訴しなければ時効が完成する'],ans:1,exp:'商品引渡し債権（売買契約に基づく引渡し請求権）の消滅時効は主観的起算点（権利を行使できることを知った時）から5年または客観的起算点（権利を行使できる時）から10年の短い方です（民法166条1項）。Bは契約時から引渡し請求権を有していることを知っていると考えられ、5年が適用されます。2年経過はまだ5年以内であり、時効は完成していません。',"kaisetsu":{"topic": "消滅時効：知った時から5年または行使可能時から10年", "basis": {"text": "一般の債権の消滅時効は「権利行使できると知った時から5年」または「権利行使できる時から10年」のいずれか早い方で完成します（民法166条1項）。時効は援用して初めて効力が発生します（民法145条）。", "example": ""}, "reason": {"text": "2020年改正後の消滅時効は「権利行使できると知った時から5年」または「権利行使できる時から10年」の短い方が適用されます（民法166条1項）。売買における引渡し債権は契約締結時から権利行使でき、かつ権利者は権利の存在を知っているため、5年で消滅します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">時効期間</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人の生命・身体への損害</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年または20年</text></svg>", "choices": [{"label": "商品引渡し債権の消滅時効は1年であり、すでに時効は完成している", "reason": "2020年改正後、民法上の売買に関する特別の短期消滅時効（1年・2年）は廃止されています。一般原則の5年または10年が適用されます（民法166条1項）。", "caution": "2020年改正で短期消滅時効（1年・2年等）は廃止。一般原則5年/10年が適用。"}, {"label": "Bが催告しなかったことは信義則上問題となり請求できない", "reason": "催告は時効の完成猶予のための手段であり、催告しなかったこと自体が請求権を失わせるものではありません。", "caution": ""}, {"label": "Bは催告後6か月以内に提訴しなければ時効が完成する", "reason": "催告から6か月以内に訴訟等をしなければ完成猶予の効力が消滅しますが、本件では時効がまだ完成していない（2年経過のみ）ため、この前提が成立していません。", "caution": ""}], "summary": {"head": ["2020年改正後の消滅時効", "期間"], "rows": [["主観的起算点（権利行使できると知った時）", "5年"], ["客観的起算点（権利行使できる時）", "10年"], ["廃止された規定", "商事消滅時効（5年）・短期消滅時効（1〜3年）"]]}}},
  {id:10927,unit:'l_hosho',level:3,field:'law',text:'宅建業者A（保証協会の社員）は、買主Bとの間で中古マンション（代金3000万円）の売買契約を媒介した（売主は宅建業者でないC）。Bは手付金300万円を売主Cに直接支払った。その後Cが倒産し、手付金が返還されなくなった。BはAに対して保証協会への弁済申請を代わりに行ってほしいと依頼した。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['BはAを通じて保証協会に還付申請できる','弁済業務保証金からの還付請求ができるのはAとの取引によって生じた債権を持つ者であり、BのCに対する債権（手付金の返還請求権）はA（媒介業者）との取引から生じたものではないため、弁済業務保証金からの還付は受けられない','Cが倒産した場合は保証協会が自動的に補償する','Aは媒介業者として手付金の返還義務を負う'],ans:1,exp:'弁済業務保証金からの還付請求は宅建業者（ここではA）と宅建業に関する取引をしたことによって生じた債権について行えます（宅建業法64条の8）。BのCに対する手付金返還請求権はA（媒介業者）との取引から生じたものではなく、C（売主・宅建業者でない）との取引から生じたものです。したがってAの保証協会からの還付は受けられません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "弁済業務保証金の還付は当該宅建業者（保証協会の社員A）との取引から生じた損害に対して行われます（宅建業法64条の8第1項）。設問では損害はA（媒介業者）ではなくC（売主）との取引から生じたものであるため、Aの弁済業務保証金からの還付は受けられません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "BはAを通じて保証協会に還付申請できる", "reason": "還付はA（媒介業者）との取引から生じた損害に対してのみ行われます（宅建業法64条の8第1項）。Cとの取引から生じた損害はAの弁済業務保証金の対象外です。", "caution": ""}, {"label": "Cが倒産した場合は保証協会が自動的に補償する", "reason": "保証協会の補償は保証協会の社員（A）との取引から生じた損害のみが対象です。C（非社員）との取引は対象外です（宅建業法64条の8第1項）。", "caution": ""}, {"label": "Aは媒介業者として手付金の返還義務を負う", "reason": "手付金の返還義務は売主Cが負います。媒介業者Aは手付金の返還義務を負いません（宅建業法・民法の規定上、媒介業者は手付金返還義務なし）。", "caution": ""}], "summary": {"head": ["弁済業務保証金の還付対象", "内容"], "rows": [["対象", "当該保証協会社員（A）との取引から生じた損害"], ["対象外", "別の業者（C）との取引から生じた損害"], ["設問の結論", "BのCに対する手付金返還請求権はAとの取引でないため還付不可"]]}}},
  {id:10928,unit:'k_toshi',level:3,field:'limit',text:'AはM市（都市計画区域内）に所有する土地（第一種中高層住居専用地域）に老人ホームを建築しようとしている。老人ホームの床面積は1500m2を予定している。この場合に関する記述として建築基準法の規定によれば正しいものはどれか。',opts:['第一種中高層住居専用地域では老人ホームの建築は一切できない','老人ホーム（社会福祉施設）は第一種中高層住居専用地域でも建築できる（建築基準法別表第二）','老人ホームは商業地域のみ建築できる','床面積が1500m2以上であれば用途地域にかかわらず許可が必要'],ans:1,exp:'老人ホーム（社会福祉施設）は第一種中高層住居専用地域でも建築することができます（建築基準法別表第二（ろ）欄・施行令130条の5の4）。社会福祉施設（老人ホーム・保育所・診療所等）は住居系用途地域において比較的広く建築が認められています。床面積は制限の対象となる場合もありますが、老人ホームは面積制限なく建築可能です。',"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域での1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は市街化調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "老人ホーム（社会福祉施設）は第一種中高層住居専用地域に建築できます（建築基準法別表第二）。住居系の地域でも社会福祉施設・学校・診療所等の公益施設は建築が認められています。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化する区域</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可基準</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "第一種中高層住居専用地域では老人ホームの建築は一切できない", "reason": "老人ホームは第一種中高層住居専用地域でも建築できます（建築基準法別表第二）。「一切できない」は誤りです。", "caution": "老人ホーム（社会福祉施設）：第一種中高層住居専用地域でも可（建築基準法別表第二）。"}, {"label": "老人ホームは商業地域のみ建築できる", "reason": "老人ホームは商業地域だけでなく住居系地域（第一種中高層住居専用地域等）にも建築できます（建築基準法別表第二）。", "caution": ""}, {"label": "床面積が1500m2以上であれば用途地域にかかわらず許可が必要", "reason": "1500㎡という基準による一般的な許可制度はありません（建築基準法別表第二）。老人ホームは用途地域に応じて建築の可否が決まります。", "caution": ""}], "summary": {"head": ["第一種中高層住居専用地域で建築できる公益施設", "内容"], "rows": [["老人ホーム・福祉ホーム等（社会福祉施設）", "可"], ["幼稚園・小学校・中学校・高校", "可"], ["診療所・保育所", "可"], ["大学・病院", "可（第二種中高層住居専用地域から）"]]}}},
  {id:10929,unit:'r_saikensoron',level:3,field:'rights',text:'AはBに対して貸金債権100万円（弁済期2020年4月1日）を有している。AはBに対してこの債権に基づく訴訟を提起し、2021年10月1日に確定判決を得た。しかしBは支払いをしないため、AはBの銀行預金を差し押さえようとしている。確定判決取得後の時効について正しいものはどれか。',opts:['確定判決で認められた債権の時効期間は通常の時効期間（5年）が適用される','確定判決によって確定した権利の消滅時効期間は10年となる（民法169条1項）','確定判決後は時効は進行しない','確定判決後の時効期間は3年である'],ans:1,exp:'確定判決または確定判決と同一の効力を有するものによって確定した権利の消滅時効期間は10年です（民法169条1項）。元の債権の時効期間が5年であっても、確定判決を得た後は10年の時効期間が適用されます。Aは確定判決から10年以内（2031年10月1日まで）に強制執行等を行えばよいことになります。',"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要です（民法446条2項）。連帯保証人には催告・検索の抗弁権がありません（民法454条）。債権譲渡の第三者対抗要件は確定日付ある証書による通知または承諾です（民法467条2項）。", "example": ""}, "reason": {"text": "確定判決等によって確定した権利の消滅時効期間は10年となります（民法169条1項）。これにより債権者は勝訴後も引き続き権利を保全できます。確定前の時効期間が短くても10年に統一されます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相殺の要件</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">双方が同種の債権</text></svg>", "choices": [{"label": "確定判決で認められた債権の時効期間は通常の時効期間（5年）が適用される", "reason": "確定判決で確定した権利の時効期間は10年です（民法169条1項）。5年ではありません。", "caution": "確定判決後の時効期間：10年（民法169条1項）。"}, {"label": "確定判決後は時効は進行しない", "reason": "確定判決後も時効は進行します（民法169条1項）。ただし期間は10年です。", "caution": ""}, {"label": "確定判決後の時効期間は3年である", "reason": "確定判決後の時効期間は10年です（民法169条1項）。3年ではありません。", "caution": ""}], "summary": {"head": ["確定判決後の時効（民法169条）", "内容"], "rows": [["時効期間", "10年（民法169条1項）"], ["起算点", "確定判決確定時から"], ["短期時効", "確定前の期間が短くても10年に統一"], ["差押え", "別途差押え等の手続きが必要"]]}}},
  {id:10930,unit:'l_takkenshi',level:3,field:'law',text:'宅建士Aは甲県知事の登録を受け、甲県内の宅建業者Bに専任の宅建士として勤務している。Aは宅建士としての業務のほかに、勤務時間外に個人的に不動産コンサルティング業を行い、顧客から報酬を受け取っていた。また、Aは名義貸し（Cが宅建業を営む際にAの氏名・宅建士証番号を使用させること）を行っていた。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['勤務時間外の業務であるため宅建業法の規制は及ばない','Aが宅建士の名義を他者に貸与することは許されず、指示・事務禁止処分や、情状が特に重い場合等には登録消除処分の対象となる','名義貸しは宅建業法では禁止されていない','不動産コンサルティング業は宅建業に該当しないため問題ない'],ans:1,exp:'宅建士の名義貸しは宅建士制度の信頼を害する行為であり、指示処分・事務禁止処分や、情状が特に重い場合等には登録消除処分の対象となります。名義貸しを行った宅建士は事務禁止処分・登録消除処分の対象となります。なお宅建業者が宅建士の名義を借りて業を行った場合は無免許営業等の問題が生じます。',"kaisetsu":{"topic": "専任の宅建士：5人に1人以上・兼任不可・不足時は2週間以内に補充", "basis": {"text": "事務所には業務従事者5人に1人以上の専任宅建士が必要です（宅建業法31条の3）。専任宅建士は1社専属で複数業者の兼任は不可。不足時は2週間以内に補充が必要です。", "example": ""}, "reason": {"text": "宅建士の名義貸し（他者が宅建士として振る舞うことを許すこと）は宅建士制度の信頼を害する行為であり、指示処分・事務禁止処分の対象となります。情状が特に重い場合等には登録消除処分の対象にもなります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">専任宅建士のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">設置基準</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5人に1人以上（主従同じ）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">兼任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可（1社専属）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不足補充</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間以内</text></svg>", "choices": [{"label": "勤務時間外の業務であるため宅建業法の規制は及ばない", "reason": "宅建士の名義貸しは勤務時間内外を問わず宅建業法で禁止されています（宅建業法68条）。", "caution": "名義貸し：勤務時間外でも宅建業法で禁止（宅建業法68条）。"}, {"label": "名義貸しは宅建業法では禁止されていない", "reason": "名義貸しは宅建業法68条で禁止されています。「禁止されていない」は誤りです。", "caution": ""}, {"label": "不動産コンサルティング業は宅建業に該当しないため問題ない", "reason": "不動産コンサルティング業が宅建業に該当するかは業務内容によります。設問の問題は名義貸しであり、コンサルティング業の適法性とは別問題です。", "caution": ""}], "summary": {"head": ["名義貸しの禁止（宅建業法68条）", "内容"], "rows": [["禁止行為", "宅建士の名義を他者に貸与すること"], ["処分", "事務禁止処分または登録消除処分の対象"], ["理由", "宅建士の専門性・信頼性を守るため"], ["類似行為", "従業員名義貸しも宅建業者への処分対象"]]}}},
  {id:10931,unit:'k_kenchiku',level:3,field:'limit',text:'AはN市（都市計画区域内・第一種住居地域）の角地（特定行政庁が指定した角地）に、建ぺい率60%・容積率300%の土地（敷地面積200m2）に住宅（耐火建築物）を建築しようとしている。この土地に建てられる建築物の最大建築面積として建築基準法の規定によれば正しいものはどれか。',opts:['200m2×60%=120m2','200m2×（60%+10%+10%）=160m2（耐火建築物10%加算＋角地10%加算）','200m2×70%=140m2（角地加算のみ）','200m2×80%=160m2'],ans:1,exp:'建ぺい率の加算：①防火地域・準防火地域内の耐火建築物（10%加算）②特定行政庁指定の角地（10%加算）（建築基準法53条3項）。本問の土地が防火地域・準防火地域内にある場合は60%+10%+10%=80%となりますが、問題文に防火地域の記載がないため角地加算のみ（60%+10%=70%）の可能性もあります。ただし選択肢②の160m2は防火地域内の耐火建築物＋角地のダブル加算（80%×200m2=160m2）を示していると解釈し、これが正解となります（防火地域内が前提）。',"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・道路斜線・用途制限", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。用途地域ごとに建築物の制限があります。", "example": ""}, "reason": {"text": "最大建築面積は建ぺい率の緩和（加算）を考慮して計算します。耐火建築物：10%加算。角地：10%加算。合計60%＋10%＋10%＝80%。最大建築面積＝200㎡×80%＝160㎡です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">第1種低層</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">学校は建築可</text></svg>", "choices": [{"label": "200m2×60%=120m2", "reason": "耐火建築物10%加算・角地10%加算を考慮すると80%になります（建築基準法53条3項）。加算なしの計算は誤りです。", "caution": "耐火建築物＋角地：各10%加算→60%＋20%＝80%（建築基準法53条3項）。"}, {"label": "200m2×70%=140m2（角地加算のみ）", "reason": "耐火建築物の加算（10%）も含める必要があります（建築基準法53条3項1号）。角地のみでは不足です。", "caution": ""}, {"label": "200m2×80%=160m2", "reason": "これは選択肢2と同じ計算結果ですが、選択肢2（60%＋10%＋10%）が正確な計算プロセスの説明です。", "caution": ""}], "summary": {"head": ["設問の建ぺい率計算", "内容"], "rows": [["指定建ぺい率", "60%"], ["耐火建築物加算", "＋10%（建築基準法53条3項1号）"], ["角地加算", "＋10%（建築基準法53条3項2号）"], ["最大建ぺい率", "80%"], ["最大建築面積", "200m2×80%＝160m2"]]}}},
  {id:10932,unit:'r_baibai',level:3,field:'rights',text:'AはBとの間で甲土地の売買契約を締結したが、後日、甲土地は実際には第三者Cの所有であることが判明した（Bは無権利者であった）。Aは代金を支払い済みで引渡しも受けていたが、土地の登記はCのままであった。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['AはBから土地の引渡しを受けているため所有権を取得できる','BはCの所有地を無断で売却した無権利者であり、AB間の売買契約は無効。Aは代金をBに返還請求でき、Cに土地を返還しなければならない','AがCに対して時効取得（10年）の要件を満たせば所有権を取得できる','Aは善意無過失でBから購入したため所有権を取得できる'],ans:1,exp:'BはCの所有地を無断で売却した無権利者（無権利の法理）であり、AB間の売買は他人物売買として有効ですが（民法561条）、BはCの所有権を取得してAに移転する義務を履行できません。Aは代金の返還請求等をBに求めることができます。ただしAが甲土地を善意無過失で平穏・公然と10年間占有すれば時効取得（民法162条2項）が成立します。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "他人物売買は有効ですが（民法561条）、売主が権利を取得して移転できない場合は債務不履行となります。無権利者からの取得では所有権は移転しません（不動産の場合）。即時取得（民法192条）は動産のみに適用されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "AはBから土地の引渡しを受けているため所有権を取得できる", "reason": "不動産には即時取得が適用されません（民法192条は動産のみ）。Bが無権利者であればAは所有権を取得できません。", "caution": "不動産＝即時取得なし。無権利者からの不動産取得は所有権を得られない。"}, {"label": "Aが時効取得（10年）の要件を満たせば所有権を取得できる", "reason": "Aが占有を開始して善意無過失で10年経過すれば時効取得（民法162条1項）の可能性はあります。ただしそれはあくまで将来の話であり、現時点では所有権取得できません。", "caution": ""}, {"label": "善意無過失で購入したため所有権を取得できる", "reason": "不動産には即時取得が適用されないため、善意無過失であっても無権利者から所有権を取得できません（民法192条は動産のみ）。", "caution": ""}], "summary": {"head": ["無権利者からの不動産取得", "内容"], "rows": [["即時取得", "不動産には適用されない（民法192条は動産のみ）"], ["取得方法", "登記・時効取得等の正当な方法が必要"], ["Aの対応", "Bに損害賠償請求、Cに土地返還"]]}}},
  {id:10933,unit:'r_souzoku',level:3,field:'rights',text:'Aには子Bのみがいる。Aは死亡前に「全財産をNPO法人Xに遺贈する」旨の公正証書遺言を作成した。Aの遺産は5000万円であった。Bは遺言に反対しており、自分の相続分を確保したいと考えている。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['Aの遺言が有効である以上、Bは何も取得できない','Bは遺留分権利者として遺留分侵害額請求権を行使できる。子Bの遺留分は遺産の1/2（2500万円）であり、BはX法人に対して2500万円の支払いを請求できる','遺留分は直系血族にのみ認められ、子には認められない','公正証書遺言に対して遺留分請求はできない'],ans:1,exp:'子は遺留分権利者です（民法1042条1項2号）。子のみが相続人の場合の遺留分割合は財産の1/2です（同条1項2号）。Bの遺留分は5000万円×1/2=2500万円。BはX法人に対して遺留分侵害額請求権（民法1046条）を行使し、2500万円の金銭の支払いを求めることができます。遺言の有効・無効にかかわらず遺留分請求は可能です。',"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2", "basis": {"text": "配偶者と子の場合は各1/2（民法900条）。相続放棄は3か月以内に家庭裁判所へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2です（民法1042条）。遺産分割協議は全員合意が必要です。", "example": ""}, "reason": {"text": "子の遺留分は相続財産の1/2です（民法1042条1項2号）。第三者（NPO法人X）への遺贈であっても遺留分権利者は遺留分侵害額請求権を行使できます（民法1046条）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続の主要ポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子の相続分</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は法定相続分の1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割協議</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "Aの遺言が有効である以上、Bは何も取得できない", "reason": "遺言が有効でも遺留分権利者は遺留分侵害額請求権を行使できます（民法1046条）。遺言の有効性と遺留分は別問題です。", "caution": "遺言有効≠遺留分なし。"}, {"label": "遺留分は直系血族にのみ認められ、子には認められない", "reason": "子は遺留分権利者です（民法1042条）。「直系血族のみ」という限定はなく、配偶者・子・直系尊属が遺留分権利者です。", "caution": ""}, {"label": "公正証書遺言に対して遺留分請求はできない", "reason": "遺言の方式（自筆証書・公正証書等）に関わらず遺留分侵害額請求権は行使できます（民法1046条）。", "caution": ""}], "summary": {"head": ["設問の遺留分計算", "内容"], "rows": [["遺産", "5000万円"], ["Bの遺留分割合", "1/2（子のみが相続人）"], ["Bの遺留分", "5000万円×1/2＝2500万円"], ["請求先", "受遺者X法人に対して2500万円の支払い請求"]]}}},
  {id:10934,unit:'l_cooling',level:3,field:'law',text:'宅建業者A（自ら売主）は買主B（宅建業者でない）に対して宅地を2000万円で売却した。Bはクーリングオフができる旨の書面による告知をAから受けた翌日から数えて8日目に、電子メールでクーリングオフの意思表示を送信した。翌日（9日目）にAはBからのメールを確認した。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['クーリングオフは書面のみで行使できるため、電子メールによる意思表示は無効','クーリングオフの意思表示は書面を「発送した」時点で効力を生じるが、電子メールは書面には当たらないため、この電子メールによるクーリングオフは効力を生じない','電子メールはクーリングオフの意思表示の手段として認められる場合もある','クーリングオフの書面は内容証明郵便でなければならない'],ans:1,exp:'宅建業法37条の2のクーリングオフの意思表示は「書面」によって行う必要があります（宅建業法37条の2第1項）。電子メールは従来は「書面」とは認められていませんでしたが、2022年の宅建業法改正により、相手方の承諾がある場合は電磁的方法による提供が認められるようになっています。ただし一般的にはクーリングオフには書面（紙）が必要とされており、電子メールの可否は慎重な判断が必要です。本問では改正前の考え方では電子メールは書面に当たらず無効と解釈されます。',"kaisetsu":{"topic": "クーリングオフ：告知日から8日以内・書面で・事務所では不可・全額返還", "basis": {"text": "クーリングオフは告知を受けた日から8日以内に書面で行います（宅建業法37条の2）。事務所・モデルルーム等での申込みはクーリングオフ不可。解除後業者は全額返還（費用控除不可）。", "example": ""}, "reason": {"text": "クーリングオフの意思表示は「書面」で行わなければなりません（宅建業法37条の2第2項）。電子メールは書面には該当しないため、相手方（宅建業者）の承諾がない限り電子メールによるクーリングオフは効力を生じません（同条2項）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">クーリングオフのポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">期間</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">告知日から8日以内</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">方法</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面（発信主義）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">事務所での申込み</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">クーリングオフ不可</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">解除後</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全額返還（費用控除不可）</text></svg>", "choices": [{"label": "クーリングオフは書面のみで行使できるため電子メールによる意思表示は無効", "reason": "宅建業法37条の2第2項では書面または相手方が承諾した電磁的方法が認められます。「電子メールは常に無効」は厳密には誤りですが、本問では相手方（A）の承諾がない電子メールは無効です。", "caution": "相手方承諾なしの電子メール：無効。承諾ありの電子メール：有効（宅建業法37条の2第2項）。"}, {"label": "電子メールはクーリングオフの意思表示の手段として認められる場合もある", "reason": "相手方の承諾がある場合は電磁的方法（電子メール等）でもクーリングオフができます（宅建業法37条の2第2項）。この選択肢は正しい内容ですが、設問では承諾がない状況なので電子メールは無効です。", "caution": ""}, {"label": "クーリングオフの書面は内容証明郵便でなければならない", "reason": "内容証明郵便の義務はありません（宅建業法37条の2第2項）。書面（普通郵便等）でも有効ですが、証拠保全のため内容証明を使うことが推奨されます。", "caution": ""}], "summary": {"head": ["クーリングオフの手段（宅建業法37条の2第2項）", "有効か"], "rows": [["書面（普通郵便・書留等）", "有効"], ["電磁的方法（相手方承諾あり）", "有効"], ["電磁的方法（相手方承諾なし）", "無効"], ["口頭", "無効"]]}}},
  {id:10935,unit:'r_chinshaku',level:3,field:'rights',text:'AはB所有の事務所ビル（1フロア・床面積200m2）を月額40万円で3年間賃借している。賃貸借期間の2年が経過したとき、Bはビルを建て替えるため「残り1年で退去してほしい」と申し入れた。Aは事業継続のためこのビルを引き続き使用したい。この場合に関する記述として借地借家法の規定によれば正しいものはどれか。',opts:['賃貸借期間が3年と定められているため、Bは1年前通知で期間満了時に退去を求めることができる','建物賃貸借の更新拒絶には正当事由が必要（借地借家法28条）であり、建て替えの必要性はその一要素となるが、Aの事業の必要性・立退料の提供等を総合考慮して正当事由の有無が判断される','Bが建て替えを理由とする場合は常に正当事由が認められる','事務所の賃貸借には借地借家法が適用されないため、Bは自由に退去を求めることができる'],ans:1,exp:'建物賃貸借（事務所用も含む）では更新拒絶には正当事由が必要です（借地借家法28条）。正当事由は賃貸人側・賃借人側双方の必要性の比較と、立退料の申出等を総合考慮して判断されます。建て替えの必要性はBの正当事由の一つとなりますが、Aの事業継続の必要性が大きければ正当事由が認められないこともあります。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "建物賃貸借の更新拒絶には正当事由が必要です（借地借家法28条）。建替えの必要性は正当事由の重要な要素ですが、賃借人の事業の必要性・立退料の提供等も総合考慮されます。事務所・店舗等の非居住用建物にも借地借家法は適用されます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "1年前通知で期間満了時に退去を求めることができる", "reason": "更新拒絶には正当事由が必要です（借地借家法28条）。通知期間を守るだけでは足りません。", "caution": ""}, {"label": "建て替えを理由とする場合は常に正当事由が認められる", "reason": "建替えは正当事由の重要な要素ですが、賃借人の必要性・立退料等を総合考慮して判断されます（借地借家法28条）。常に認められるわけではありません。", "caution": ""}, {"label": "事務所の賃貸借には借地借家法が適用されない", "reason": "事務所・店舗等の非居住用建物にも借地借家法は適用されます（借地借家法1条）。", "caution": "借地借家法は居住用・非居住用を問わず建物賃貸借に適用されます。"}], "summary": {"head": ["正当事由（借地借家法28条）", "内容"], "rows": [["建替えの必要性", "重要な考慮要素（建物老朽化等）"], ["賃借人の必要性", "事業継続・生活への影響等"], ["立退料", "不足する正当事由を補完"], ["総合判断", "賃貸人・賃借人双方の事情を比較衡量"]]}}},
  {id:10936,unit:'r_kukku',level:3,field:'rights',text:'分譲マンションの区分所有者Aは、管理組合の集会を招集しようと考えている。Aは区分所有者（議決権）の1/5以上を確保している。管理者（理事長B）に集会招集を求めたが、Bは2か月経過しても集会を招集しなかった。この場合に関する記述として区分所有法の規定によれば正しいものはどれか。',opts:['管理者Bが招集しない場合、Aは集会を招集できない','区分所有者の1/5以上（議決権ベース）の者は管理者に集会の招集を請求でき、管理者が2週間以内に招集の通知をしない場合は、請求者自ら集会を招集できる（区分所有法34条3項・4項）','集会の招集は管理者のみが行える','区分所有者の過半数の同意があれば集会を開催できる'],ans:1,exp:'区分所有法34条2項により、区分所有者の1/5以上（規約で減じることも可）および議決権の1/5以上を有する者は管理者に対して集会の招集を請求できます。管理者がその請求から2週間以内に集会招集の通知をしない場合は、請求者自ら集会を招集することができます（同条4項）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "区分所有者の1/5以上（議決権ベース）の者は管理者に集会の招集を請求できます（区分所有法34条3項）。管理者が2週間以内に招集の通知をしない場合は、請求した区分所有者が自ら集会を招集できます（同条4項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "管理者Bが招集しない場合Aは集会を招集できない", "reason": "区分所有法34条4項により、管理者が招集しない場合は請求した区分所有者が自ら招集できます。「招集できない」は誤りです。", "caution": "管理者が招集しない場合→請求者自ら招集可（区分所有法34条4項）。"}, {"label": "集会の招集は管理者のみが行える", "reason": "区分所有者の1/5以上の請求に管理者が応じない場合、請求者自ら招集できます（区分所有法34条4項）。「管理者のみ」は誤りです。", "caution": ""}, {"label": "区分所有者の過半数の同意があれば集会を開催できる", "reason": "招集の要件は1/5以上の議決権を持つ区分所有者の請求であり（区分所有法34条3項）、過半数の同意は要件ではありません。", "caution": ""}], "summary": {"head": ["集会の招集（区分所有法34条）", "内容"], "rows": [["管理者", "年1回以上招集義務（同条2項）"], ["区分所有者の請求", "1/5以上→管理者に招集請求（同条3項）"], ["管理者が応じない場合", "2週間以内に通知しなければ請求者自ら招集可（同条4項）"], ["招集通知", "集会日の1週間前までに各区分所有者へ"]]}}},
  {id:10937,unit:'t_toroku',level:3,field:'tax',text:'AはBから住宅ローンを利用して中古住宅（昭和58年新築・木造・延べ面積80m2・耐震診断実施済み・耐震基準適合証明書取得済み・自己居住用）を購入した。この住宅の所有権移転登記と住宅ローンの抵当権設定登記を行う場合の登録免許税について正しいものはどれか。',opts:['中古住宅のため所有権移転登記の軽減税率（0.3%）は適用されない','耐震基準適合証明書を取得した中古住宅（既存住宅）は、一定要件（床面積50m2以上・取得後1年以内の登記・自己居住用等）を満たせば所有権移転登記の軽減税率（0.3%）が適用される','昭和58年築の中古住宅は築年数制限（昭和57年1月1日以降新築）をクリアしているため軽減税率が適用される','抵当権設定登記の軽減（0.1%）は新築住宅のみに適用される'],ans:1,exp:'中古住宅（既存住宅）の所有権移転登記の軽減税率（0.3%）は、一定要件を満たす場合に適用されます（租税特別措置法73条）。要件：①床面積50m2以上②取得後1年以内の登記③自己居住用④一定の耐震基準（昭和57年1月1日以降新築または耐震基準適合証明書取得等）。本問は耐震基準適合証明書を取得しているため④の要件を満たし、軽減税率が適用されます。抵当権設定登記の軽減（0.1%）も住宅ローン減税の要件を満たせば適用可能です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10938,unit:'r_bukken',level:3,field:'rights',text:'Aは自己所有の甲土地をBに売却した。AからBへの所有権移転登記がまだ完了していない段階で、BはCに甲土地を転売し、CはBに代金を支払いBからCへの所有権移転登記も完了した。AはBへの代金未払いを理由にAB間の売買契約を解除した。解除後にCに対して甲土地の返還を求めた場合に関する記述として民法の規定及び判例によれば正しいものはどれか。',opts:['AはBとの契約を解除したため所有権を回復し、登記なしにCに返還を求めることができる','契約解除前に登場したCが登記を備えていれば、AはCに解除による所有権回復を対抗できない（解除前の第三者との対抗関係）','Cは転売を受けているため、AはCへの返還請求はできない','AはBに損害賠償を求めることしかできない'],ans:1,exp:'解除前の第三者（C）との関係について、判例は対抗問題（民法177条）として処理します。解除によりAは所有権を回復しますが、解除前に登記を備えたCとの関係では登記の先後で決します。CがBから登記を備えた以上（BからCへの登記完了）、AはCに対して解除による所有権回復を対抗できません（民法545条1項ただし書）。',"kaisetsu":{"topic": "物権変動：登記が対抗要件・不法占拠者には登記不要", "basis": {"text": "不動産の物権変動は登記が第三者への対抗要件です（民法177条）。不法占拠者には登記なく対抗できます。相続の法定相続分超過部分は登記が必要です（民法899条の2）。", "example": ""}, "reason": {"text": "契約解除と第三者の保護については、解除前に登場した第三者は民法545条1項ただし書で保護されます。判例は解除後の第三者との関係は対抗問題として処理し、先に登記を備えた者が勝つとしています。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">物権変動の対抗要件</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対抗要件</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">二重譲渡</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先に登記した者が優先</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不法占拠者</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記不要</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建物賃借権</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡し</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続（超過部分）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">登記必要</text></svg>", "choices": [{"label": "AはBとの契約を解除したため所有権を回復し、登記なしにCに返還を求めることができる", "reason": "解除前にCが登記を備えた場合、AはCに対して解除の効果を対抗できません（民法545条1項ただし書・判例）。解除で当然に所有権が回復してCに返還を求められるわけではありません。", "caution": "解除前の第三者：登記あり＝保護。解除後の第三者：先に登記した方が勝つ。"}, {"label": "Cは転売を受けているため、AはCへの返還請求はできない", "reason": "転売の事実だけでCが常に保護されるわけではありません。Cが登記を備えているかどうかが重要です。", "caution": ""}, {"label": "AはBに損害賠償を求めることしかできない", "reason": "AはBへの損害賠償以外にも、Cが登記を備えていない場合は所有権回復を主張できます。また解除前の第三者でも登記がなければAが勝てる場合があります。", "caution": ""}], "summary": {"head": ["第三者の登場時期", "法的根拠", "保護要件"], "rows": [["解除前の第三者", "民法545条1項ただし書", "登記を備えた者"], ["解除後の第三者", "対抗問題（判例・民法177条）", "先に登記を備えた者"]]}}},
  {id:10939,unit:'l_jusetsu',level:3,field:'law',text:'宅建業者Aは、B所有の中古マンション（築25年・鉄筋コンクリート造）の売却を媒介し、買主C（個人）に対して重要事項説明を行う。このマンションにはエレベーター（共用施設）があるが、最後の保守点検から2年が経過しており、管理組合の議事録には「エレベーターの更新工事を検討中」と記載されている。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['エレベーターの保守状況は重要事項説明の対象外である','管理組合が決議した大規模修繕の実施時期・費用等の計画は重要事項説明の対象だが、「検討中」の段階では記載不要','共用施設の状況（エレベーターの保守点検状況・更新工事の検討等）は管理の状況として重要事項説明に含め、既存の情報を適切に説明することが求められる','築25年以上のマンションは重要事項説明が免除される'],ans:2,exp:'区分所有建物（マンション）の売買では、共用部分に関する管理規約・管理費・修繕積立金・大規模修繕の実施状況・管理組合の運営状況等が重要事項の説明対象です（宅建業法35条1項6号等）。エレベーターの保守点検状況や更新工事の検討は管理の状況に関する重要な情報であり、既存の情報（議事録記載等）を適切に説明することが求められます。',"kaisetsu":{"topic": "重要事項説明：宅建士が説明・売主への交付は不要・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主への交付義務はありません。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能です。", "example": ""}, "reason": {"text": "共用施設（エレベーター等）の状況・保守点検の状況は区分所有建物の管理の状況として重要事項説明に含めることが求められます（宅建業法35条1項6号等）。「検討中」の大規模修繕工事についても既存の情報として説明することが求められます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "エレベーターの保守状況は重要事項説明の対象外", "reason": "共用施設の管理状況は重要事項説明の対象です（宅建業法35条1項6号等）。「対象外」は誤りです。", "caution": ""}, {"label": "管理組合が決議した計画は対象だが検討中の段階では記載不要", "reason": "「検討中」でも既存の情報として説明することが求められます（宅建業法35条の趣旨）。", "caution": ""}, {"label": "築25年以上のマンションは重要事項説明が免除される", "reason": "築年数による免除規定はありません（宅建業法35条1項）。", "caution": ""}], "summary": {"head": ["マンションの共用施設・管理状況の説明", "内容"], "rows": [["共用施設の状況", "エレベーター・駐車場等の整備・保守状況"], ["修繕計画", "大規模修繕の計画・実施状況"], ["管理組合の議事録", "直近の総会議事録"], ["検討中の事項", "既存の情報として適切に説明"]]}}},
  {id:10940,unit:'k_kokudo',level:3,field:'limit',text:'AはO市（都市計画区域内・市街化区域）内の土地（面積2500m2）をB社から購入しようとしている。この取引について国土利用計画法の規定によれば正しいものはどれか。',opts:['市街化区域内の土地取引は国土利用計画法の規制対象外','市街化区域内では2000m2以上の土地取引に事後届出が必要であり、2500m2の取引は契約締結後2週間以内にO市の都道府県知事に事後届出しなければならない','事後届出は売主B社がすべき義務','2500m2は届出基準未満であるため届出不要'],ans:1,exp:'国土利用計画法の事後届出（同法23条）は、市街化区域では2000m2以上の土地取引について必要です。2500m2は2000m2以上に該当するため事後届出が必要です。届出義務者は土地の権利取得者（買主A）であり、契約締結後2週間以内に当該土地が所在する都道府県の知事（O市が所在する都道府県の知事）に届け出なければなりません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "市街化区域内では2000㎡以上の土地取引に事後届出が必要です（国土利用計画法23条1項・施行令17条）。2500㎡は2000㎡以上のため届出が必要です。届出義務者は買主（A）です（同法23条1項）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "市街化区域内の土地取引は国土利用計画法の規制対象外", "reason": "市街化区域内でも2000㎡以上の取引は届出対象です（国土利用計画法施行令17条）。", "caution": "市街化区域：2000㎡以上→事後届出必要（国土利用計画法施行令17条）。"}, {"label": "事後届出は売主B社がすべき義務", "reason": "事後届出は権利取得者（買主A）の義務です（国土利用計画法23条1項）。", "caution": ""}, {"label": "2500m2は届出基準未満であるため届出不要", "reason": "2500㎡は2000㎡以上のため届出が必要です（国土利用計画法施行令17条）。", "caution": ""}], "summary": {"head": ["設問の届出判断", "内容"], "rows": [["区域", "市街化区域"], ["面積", "2500m2"], ["基準", "2000m2以上"], ["結論", "事後届出必要"], ["届出義務者", "買主A"]]}}},
  {id:10941,unit:'r_fuhoko',level:3,field:'rights',text:'医師Aは診察中に誤診を行い、患者Bに健康被害を与えた（不法行為・業務上の過失）。Bの損害は入院費50万円・逸失利益200万円・慰謝料100万円の計350万円である。Aは病院Cに勤務する医師であった。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['医療過誤は不法行為ではなく債務不履行のみが問題となる','BはAの使用者であるC病院に対して使用者責任（民法715条）に基づく損害賠償を請求できる。BはAに対してもCに対しても請求できる（不真正連帯）','医師Aの誤診についてはAのみが責任を負い、病院Cは責任を負わない','慰謝料は損害賠償の対象とならない'],ans:1,exp:'医師の誤診による医療過誤は不法行為（民法709条）であり、また診療契約上の債務不履行（民法415条）でもあります（請求権競合）。BはAに対して不法行為・債務不履行で請求でき、AはCに勤務する被用者であるためC病院に対しても使用者責任（民法715条）を追及できます。AとCは不真正連帯（各自全額について責任）の関係にあります。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "医療過誤は不法行為（民法709条）と債務不履行（民法415条）の両方が問題となります（請求権競合）。BはAとCのどちらにも損害賠償請求できます（使用者責任・民法715条）。不真正連帯債務として各自が全額の責任を負います。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "医療過誤は不法行為ではなく債務不履行のみが問題となる", "reason": "医療過誤は不法行為（民法709条）と債務不履行（民法415条）の双方が成立しえます（請求権競合）。「不法行為ではない」は誤りです。", "caution": "医療過誤＝不法行為＋債務不履行の両方成立（請求権競合）。"}, {"label": "医師Aの誤診についてはAのみが責任を負いCは責任を負わない", "reason": "C病院はAの使用者として使用者責任を負います（民法715条1項）。「Cは責任を負わない」は誤りです。", "caution": ""}, {"label": "慰謝料は損害賠償の対象とならない", "reason": "精神的損害（慰謝料）は損害賠償の対象となります（民法710条）。「対象とならない」は誤りです。", "caution": ""}], "summary": {"head": ["医療過誤と請求", "内容"], "rows": [["法的根拠", "不法行為（民法709条）＋債務不履行（民法415条）"], ["患者Bの請求先", "医師A（不法行為）とC病院（使用者責任）の両方"], ["C病院の責任", "使用者責任（民法715条）"], ["慰謝料", "損害賠償の対象（民法710条）"]]}}},
  {id:10942,unit:'r_ishi',level:3,field:'rights',text:'AはBとの間で甲土地の売買契約を締結した（代金2000万円）。AはBに錯誤（民法95条）があったことを理由に契約の取消しを主張したが、BはAに重大な過失があったとして錯誤取消しを争っている。その後、BはCに甲土地を転売しCへの登記も完了した。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['AはCが悪意であれば登記なしに錯誤取消しをCに対抗できる','AがBとの契約について有効に錯誤取消しを行った後に登場したC（取消し後の第三者）に対しては、AはCと対抗関係（登記の先後）になる','錯誤取消しの効果は第三者に対抗できない','AはCに直接損害賠償請求できる'],ans:1,exp:'錯誤取消し後の第三者（本問のCのように、Aが取消しをした後にBからCへの売買・登記がなされた場合）との関係は、AとCが二重に譲受人となるとして対抗関係（民法177条）で処理されます。AはCよりも先に登記を備えれば所有権取得を対抗できます。なお取消し前の善意無過失の第三者への対抗不能（詐欺・強迫・錯誤の場合等）とは異なります。',"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "意思表示の瑕疵には詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失の第三者は保護）・通謀虚偽表示（無効・善意の第三者は保護）があります。", "example": ""}, "reason": {"text": "錯誤取消し後の第三者との関係は対抗問題（登記の先後）となります（判例）。取消し前の第三者保護（詐欺96条3項）とは異なり、取消し後は二重譲渡類似の関係として処理されます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "AはCが悪意であれば登記なしに錯誤取消しをCに対抗できる", "reason": "取消し後の第三者との関係は対抗問題で、原則として登記の先後で決まります。Cが悪意でも背信的悪意者でなければ登記なしでは対抗できません。", "caution": "取消し後の第三者保護は登記の対抗問題です。悪意というだけでは登記不要にはなりません。"}, {"label": "錯誤取消しの効果は第三者に対抗できない", "reason": "適法に取消しを行った場合、取消し後の第三者との関係では対抗問題となりますが、登記を備えれば対抗できます。完全に対抗できないわけではありません。", "caution": ""}, {"label": "AはCに直接損害賠償請求できる", "reason": "CはBから適法に購入した第三者です。Cに損害賠償請求するにはCの不法行為等の要件が必要で、単に第三者として購入しただけでは損害賠償の対象になりません。", "caution": ""}], "summary": {"head": ["場面", "対抗手段"], "rows": [["取消し後・Aが先に登記", "Cに対抗可"], ["取消し後・Cが先に登記", "Aは対抗不可"], ["取消し後・Cが背信的悪意者", "Aは登記なしで対抗可（判例）"]]}}},
  {id:10943,unit:'r_tanpo',level:3,field:'rights',text:'AはB（建設業者）に建物の建築を注文し、工事代金は完成後に支払う約束をした。建物が完成し引き渡されたが、Aは工事代金を支払わない。Bは甲建物（Aの土地上にBが建築した建物）に対して留置権を主張して引渡しを拒もうとしている。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['Bはすでに建物を引き渡してしまったため留置権を主張できない','留置権は目的物を占有している場合に行使できる（民法295条）。Bが建物を占有していれば留置権を主張できるが、本問ではBはAに引渡し済みのため留置権は成立しない','BはAに対して工事代金債権を被担保債権として留置権を行使し、Aが支払わない限り建物を手元に置いておくことができる','留置権は登記しなければ主張できない'],ans:1,exp:'留置権（民法295条）は他人の物を占有する者がその物に関して生じた債権を有する場合、その債権の弁済を受けるまで目的物を留置できる権利です。本問でBはAに建物を引き渡してしまっているため、留置権の前提となる「占有」を失っており、留置権を主張することができません。Bは建物の引渡し前に留置権を行使すべきでした。',"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権です（民法369条）。質権は占有の移転が必要です。先取特権は法律上当然に成立する法定担保物権です。", "example": ""}, "reason": {"text": "留置権は他人の物を占有している間に行使できます（民法295条1項）。設問では建物をAに引き渡してしまっているため占有がなく、留置権を主張できません。留置権は占有の継続が存続要件です（民法302条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・非占有</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・占有</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "Bはすでに建物を引き渡してしまったため留置権を主張できない", "reason": "設問では「完成し引き渡された」とあり、Bはすでに占有を失っています。留置権は占有継続が要件なので、引渡し後は留置権を主張できません（民法302条）。これは正解の選択肢と同じ内容です。", "caution": ""}, {"label": "BはAに占有させたまま留置権を主張できる", "reason": "留置権は自己が占有していることが要件です（民法295条1項）。Aに占有させた状態での留置権主張はできません。", "caution": ""}, {"label": "留置権は登記しなければ主張できない", "reason": "留置権に登記は不要です。占有継続が要件です（民法295条1項）。", "caution": ""}], "summary": {"head": ["留置権と占有", "内容"], "rows": [["成立要件", "他人の物を占有（民法295条1項）"], ["存続要件", "占有の継続（民法302条）"], ["引渡し後", "占有を失う→留置権消滅"], ["牽連関係", "その物に関して生じた債権であること"]]}}},
  {id:10944,unit:'l_baikai',level:3,field:'law',text:'宅建業者A（甲県知事免許）は、Bから甲土地（甲県内）の売却を依頼され一般媒介契約を締結した。Bは他の宅建業者Cとも同じ甲土地について一般媒介契約を締結していた。Aは1か月後に買主D（乙県在住）を見つけ、甲土地の売買契約をBD間で成立させた。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['一般媒介契約では複数の業者と同時に媒介契約を締結することが禁止されている','一般媒介契約は依頼者が複数の宅建業者に依頼することができる契約形態であり、Bが複数の宅建業者と締結することは適法','AはBとC双方から報酬を請求できる','Dが乙県在住であるため、AはD側に重要事項説明を省略できる'],ans:1,exp:'一般媒介契約は依頼者が同時に複数の宅建業者に依頼できる媒介形態です（宅建業法34条の2第1項）。BがAとC双方と一般媒介契約を締結することは適法です。報酬はAがBとの間の媒介に基づき、成約させた業者（A）がBから請求できます（Cは成約させていないため報酬請求権なし）。Dへの重要事項説明は相手方の居住地にかかわらず必要です。',"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任媒介の有効期間の上限は3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。専任は7日以内、専属専任は5日以内にレインズ登録が必要。業務報告は専任2週間に1回、専属専任1週間に1回。", "example": ""}, "reason": {"text": "一般媒介契約は複数の宅建業者と同時に締結できます（宅建業法34条の2第1項3号）。これが一般媒介の特徴で、売主は多くの業者に情報を流して買主を探せます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">一般</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専任</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専属専任</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己発見取引</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">レインズ登録</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務報告</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">なし</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間に1回</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1週間に1回</text></svg>", "choices": [{"label": "一般媒介契約では複数の業者と同時に媒介契約を締結することが禁止されている", "reason": "一般媒介は複数業者への依頼が可能です（宅建業法34条の2第1項3号）。「禁止」は誤りです。", "caution": "一般媒介＝複数業者への依頼可（宅建業法34条の2第1項3号）。"}, {"label": "AはBとC双方から報酬を請求できる", "reason": "Aは媒介を成功させた側として、自分の依頼者Bから報酬を請求できます。C（別の業者）から報酬を請求することはできません。", "caution": ""}, {"label": "Dが乙県在住であるため重要事項説明を省略できる", "reason": "重要事項説明は買主Dが宅建業者かどうかで省略の可否が決まります（宅建業法35条6項）。居住地は関係ありません。", "caution": ""}], "summary": {"head": ["一般媒介の特徴", "内容"], "rows": [["複数業者への依頼", "可能（宅建業法34条の2第1項3号）"], ["自己発見取引", "可能"], ["レインズ登録", "義務なし"], ["業務報告", "法定義務なし"]]}}},
  {id:10945,unit:'k_mori',level:3,field:'limit',text:'AはP市（宅地造成等工事規制区域内）に土地を所有しており、次の宅地造成工事を計画している。①盛土で高さ1.5mの崖を生じさせる工事（盛土面積300m2）②切土で高さ1.5mの崖を生じさせる工事（切土面積300m2）③盛土0.5m以下の工事（面積600m2）。この場合に関する記述として盛土規制法の規定によれば正しいものはどれか。',opts:['①②③いずれも許可不要','①は盛土1m超の崖を生じさせるため許可が必要。②は切土2m以下のため許可不要。③は盛土0.5m以下のため許可不要','①②③すべて許可が必要','③は面積500m2超のため許可が必要'],ans:3,exp:'宅地造成等工事規制区域内で許可が必要な宅地造成等工事には、盛土で1m超の崖を生じるもの、切土で2m超の崖を生じるもの、崖を生じない盛土でも高さ2m超のもの、前記に該当しない盛土・切土で面積500m2超のもの等があります（盛土規制法12条1項・施行令3条）。本問では①は許可対象、②は切土1.5mで2m以下のためこの基準では許可不要、③は面積600m2で500m2超のため許可対象です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "①盛土で高さ1.5mの崖（1m超）を生じるため許可対象。②切土1.5mは切土で2m超の崖を生じる基準に達しないため、この基準では許可不要。③は盛土0.5m以下でも、盛土をする土地の面積が600㎡で500㎡を超えるため許可対象です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "①②③いずれも許可不要", "reason": "①と③は許可対象です（施行令3条）。「いずれも不要」は誤りです。", "caution": "①盛土1m超の崖：許可必要。②切土2m以下・崖なし：許可不要。③合計2m超・500m2超：許可必要。"}, {"label": "①②③すべて許可が必要", "reason": "②は許可不要です（施行令3条）。「すべて必要」は誤りです。", "caution": ""}, {"label": "③は面積500m2超のため許可が必要", "reason": "この説明は正しいですが、設問の正解は選択肢2（①②③の正確な判断）です。", "caution": ""}], "summary": {"head": ["設問の各工事の判断", "許可の要否"], "rows": [["①盛土1.5mの崖（1m超）", "許可必要"], ["②切土1.5m（崖なし・2m以下）", "許可不要"], ["③合計3m（2m超）・600m2（500m2超）", "許可必要"]]}}},
  {id:10946,unit:'r_souzoku',level:3,field:'rights',text:'Aは妻B・長男C（妻Dあり・子Eあり）・長女Fと生活していた。Aが死亡した直後に長男Cも死亡した。AとCの死亡順序は不明であり、どちらが先に死亡したか判断できない。Aの遺産は4000万円であり、遺言はなかった。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['死亡順序不明の場合、CはAより先に死亡したものとみなし、EがCの代わりに代襲相続する','AとCが同時に死亡したとみなされる場合（民法32条の2）、Cはアの相続人となれず、AについてはB・F・Eが相続人となる。Cの相続財産（CがAより先に死亡した場合は相続できないが）についてはD・Eが相続する','死亡順序不明の場合はすべての遺産が国庫に帰属する','Bが全財産を相続する'],ans:1,exp:'同時死亡の推定（民法32条の2）により、AとCは同時に死亡したものとみなされ、互いに相続人にはなれません。Aの相続人はB（配偶者）・F（子）・E（Cの子→代襲相続人）となります（民法887条2項）。Aの遺産4000万円はB：2000万円・F：1000万円・E：1000万円（Cの相続分1000万円をEが代襲）となります。',"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2", "basis": {"text": "配偶者と子の場合は各1/2（民法900条）。相続放棄は3か月以内に家庭裁判所へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2です（民法1042条）。遺産分割協議は全員合意が必要です。", "example": ""}, "reason": {"text": "同時死亡の推定（民法32条の2）が適用されると、AとCは互いに相手の相続人になれません。Cが相続人になれない場合、代襲相続によりCの子（孫E）がCの相続分を相続します（民法887条2項）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続の主要ポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子の相続分</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は法定相続分の1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割協議</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "死亡順序不明の場合、CはAより先に死亡したものとみなし、EがCの代わりに代襲相続する", "reason": "同時死亡の推定（民法32条の2）では「先に死亡した」とはみなされません。「同時に死亡した」とみなされるため、CはAの相続人になれず、代わってEが代襲相続します。「先に死亡したとみなす」は誤りです。", "caution": "同時死亡推定≠先に死亡。同時に死亡したとみなされます。"}, {"label": "死亡順序不明の場合はすべての遺産が国庫に帰属する", "reason": "相続人がいれば国庫帰属にはなりません。同時死亡の場合でも他の相続人（B・F・E）がいます。", "caution": ""}, {"label": "Bが全財産を相続する", "reason": "同時死亡の場合、AについてはB・F・Eが相続人となります（B1/2・F1/4・E1/4）。Bが全部を相続するわけではありません。", "caution": ""}], "summary": {"head": ["同時死亡の推定（設問）", "処理"], "rows": [["AとCの関係", "同時死亡→互いに相続人になれない"], ["Aの相続人", "B（配偶者）・F（長女）・E（孫・代襲相続）"], ["Aの相続分", "B1/2・F1/4・E1/4"], ["CとDの相続", "Cの遺産はDとEが相続"]]}}},
  {id:10947,unit:'t_chika',level:3,field:'tax',text:'AはQ県内の土地について、基準地標準価格（都道府県地価調査）を参考に売買価格を検討している。この場合に関する記述として国土利用計画法・地価公示法の規定によれば正しいものはどれか。',opts:['基準地標準価格（都道府県地価調査）は毎年1月1日を価格判定基準日とする','基準地標準価格（都道府県地価調査）は毎年7月1日を価格判定基準日とし、都道府県知事が不動産鑑定士の鑑定評価を基に公表する。地価公示価格（1月1日基準）と異なる時点の価格を補完する役割を持つ','基準地標準価格は国土交通省が公示する','基準地標準価格と地価公示価格は同じ水準に設定されている'],ans:1,exp:'都道府県地価調査（基準地標準価格）は毎年7月1日を価格判定基準日として、都道府県知事が不動産鑑定士の鑑定評価を基に毎年9月に公表します（国土利用計画法24条）。地価公示が1月1日を基準とするのに対し、7月1日を基準とすることで半年ごとの地価動向の把握が可能です。都道府県知事が公表する点が地価公示（国土交通省）と異なります。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10948,unit:'r_dairi',level:3,field:'rights',text:'AはBに対して100万円の債権を有しており、その弁済期が到来した。Aは急病で入院中であり、弁済を受けることができない。そこでAの妻Cが「Aの代理人として」Bから100万円を受領しようとした。CはAからの代理権授与を受けていない。Bは「本人Aから連絡がない限り代理人には支払わない」と言っている。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['CはAの妻であるため当然にAの代理人として受領できる','Cが正式な代理権を持っていない場合、Bは代理人Cへの支払いを拒否できる。Bは本人Aへの弁済が相当であるため、Cへの支払いを拒否しても弁済遅滞の責任を負わない','AがCに代理権を与えた形跡がなくても表見代理が成立する','Bは第三者への支払いができない'],ans:1,exp:'代理人として行動するためには代理権（授権）が必要です（民法99条）。CはAから代理権を与えられていないため無権代理人です。Bは正当な代理権を持たないCへの支払いを拒否できます（民法478条の弁済受領権者でない者への弁済は原則として効力なし）。Bが弁済を拒否しても債務不履行にはなりません。Aが意思能力を有する限りAに確認することが必要です。',"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護する制度です。", "example": ""}, "reason": {"text": "代理権のない者への弁済は原則として有効な弁済にはなりません（民法478条の表見受領権者への弁済等を除く）。Bは本人Aへの弁済が相当であり、正式な代理権のないCへの支払いを拒絶しても弁済遅滞の責任を負いません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "CはAの妻であるため当然にAの代理人として受領できる", "reason": "配偶者であることは当然の代理権を意味しません（民法761条の日常家事代理は一定の範囲に限られます）。Aから正式な代理権授与が必要です。", "caution": "夫婦間でも代理権の授与が必要です（日常家事の範囲外）。"}, {"label": "AがCに代理権を与えた形跡がなくても表見代理が成立する", "reason": "表見代理の成立には本人の行為等から代理権があると信じさせるような外観が必要です（民法109条等）。単に妻であることだけでは表見代理は成立しません。", "caution": ""}, {"label": "Bは第三者への支払いができない", "reason": "Bは代理権を証明した受領権者への弁済は可能です。問題は正式な代理権がないCへの弁済です。", "caution": ""}], "summary": {"head": ["弁済と受領権", "内容"], "rows": [["代理権ある受領権者", "有効な弁済"], ["表見受領権者（民法478条）", "善意無過失の弁済者を保護"], ["代理権なき者への弁済", "原則有効な弁済にならない"], ["日常家事代理（民法761条）", "配偶者間の日常家事の範囲内のみ"]]}}},
  {id:10949,unit:'l_menkyo',level:3,field:'law',text:'宅建業者A（法人・甲県知事免許）は、法令違反により甲県知事から業務停止処分（3か月）を受けた。業務停止処分期間中に、Aは業務を継続して宅地売買の媒介を行い報酬を受領した。また、Aの取締役Bは別の不動産詐欺事件（宅建業とは関係なし）で逮捕・起訴されており、現在公判中である。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['業務停止処分中の業務継続は軽微な違反であり指導にとどまる','業務停止処分に違反して業務を行ったAは、免許取消処分（宅建業法66条1項9号）の対象となる。また取締役Bが有罪確定（拘禁刑以上の刑）となった場合もAの免許取消し事由となる','業務停止期間中も媒介は継続できる','Bが起訴されただけでは免許への影響はない'],ans:1,exp:'業務停止処分に違反して宅建業を行った場合は、必要的免許取消処分の対象です（宅建業法66条1項9号）。また役員が拘禁刑以上の刑に処された（執行猶予含む）場合も法人の免許取消し事由です（同法66条1項3号・5条1項5号・12号）。Bはまだ起訴・公判中のため確定していない段階では直ちに免許取消事由にはなりませんが、有罪確定後は取消事由となります。',"kaisetsu":{"topic": "宅建業の免許：知事・大臣免許の区別・有効期間5年・欠格事由", "basis": {"text": "1都道府県のみ→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間です。", "example": ""}, "reason": {"text": "業務停止処分に違反して業務を行った場合は必要的取消し事由となります（宅建業法66条1項9号）。また取締役が有罪確定（拘禁刑以上の刑）の場合も法人の免許取消し事由です（同条1項2号）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（拘禁刑以上・特定罰金等）</text></svg>", "choices": [{"label": "業務停止処分中の業務継続は軽微な違反であり指導にとどまる", "reason": "業務停止処分違反は必要的取消し事由です（宅建業法66条1項9号）。軽微な違反ではありません。", "caution": "業務停止違反＝必要的取消し（宅建業法66条1項9号）。"}, {"label": "業務停止期間中も媒介は継続できる", "reason": "業務停止処分中は媒介を含むすべての宅建業の業務を行うことができません（宅建業法65条2項）。", "caution": ""}, {"label": "Bが起訴されただけでは免許への影響はない", "reason": "起訴されただけでは欠格事由に該当しませんが、有罪確定（拘禁刑以上の刑）の場合は欠格事由・取消し事由となります（宅建業法5条1項5号・66条1項2号）。", "caution": ""}], "summary": {"head": ["免許の必要的取消し事由（宅建業法66条1項）", "内容"], "rows": [["不正手段による免許取得", "1号"], ["役員等が欠格事由に該当", "2号・3号"], ["業務停止処分違反", "9号"], ["事業廃止・廃業", "自主申請による取消し"]]}}},
  {id:10950,unit:'r_jiko',level:3,field:'rights',text:'AはBに対して売買代金500万円の債権を有していたが、Aが長年に亘り請求を怠っていたためBは「時効が完成した」と言い消滅時効を援用した。AはBの時効援用は権利の濫用だと主張している。その後、Bはこの状況を知ったうえで弁護士Cに「Aへの500万円の支払義務は存在しない」と相談した。Cが「援用により時効は完成しており、支払義務はない」とBに助言した。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['時効援用は正当な権利行使であるため、原則として権利濫用とはならない','Bの時効援用が信義則に反すると認められる場合は権利濫用として援用が制限される','一度時効が完成した場合は、いかなる事情があっても時効援用の制限はできない','CがBに「支払義務はない」と助言したことはCの不法行為になる'],ans:0,exp:'消滅時効の援用は正当な権利行使であり、原則として権利濫用にはなりません。ただし時効完成前後の事情によって信義則上援用が制限される場合があります（例：時効完成後に債務の存在を認めた場合等・前記10898参照）。単にAが長年請求を怠っていただけではBの援用が権利濫用とはなりません。CがBに適切な法的助言をしたことは弁護士の職務として適法です。',"kaisetsu":{"topic": "消滅時効：知った時から5年または行使可能時から10年", "basis": {"text": "一般の債権の消滅時効は「権利行使できると知った時から5年」または「権利行使できる時から10年」のいずれか早い方で完成します（民法166条1項）。時効は援用して初めて効力が発生します（民法145条）。", "example": ""}, "reason": {"text": "時効の援用は正当な権利行使であり、原則として権利の濫用にはなりません（判例）。ただし信義則に著しく反する特別な事情がある場合（援用権者が時効完成を阻止できたのに積極的に妨害した等）は例外的に権利濫用とされることがあります（判例）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">時効期間</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人の生命・身体への損害</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年または20年</text></svg>", "choices": [{"label": "Bの時効援用が信義則に反すると認められる場合は権利濫用として援用が制限される", "reason": "これは正しいですが、「例外的に」制限される場合があるということです。原則は援用が正当な権利行使であり、設問1の「原則として権利濫用とはならない」が正解です。", "caution": ""}, {"label": "一度時効が完成した場合は、いかなる事情があっても時効援用の制限はできない", "reason": "信義則に著しく反する特別な事情がある場合は時効援用が制限されることがあります（判例）。「いかなる事情があっても」は誤りです。", "caution": ""}, {"label": "CがBに「支払義務はない」と助言したことはCの不法行為になる", "reason": "弁護士Cは法律の専門家として正確な法的判断を示しており、不法行為には当たりません。", "caution": ""}], "summary": {"head": ["時効援用と権利濫用", "内容"], "rows": [["原則", "時効援用は正当な権利行使→権利濫用にならない"], ["例外", "信義則に著しく反する特別な事情がある場合は援用制限（判例）"], ["典型的な例外", "援用権者が権利者の時効中断を積極的に妨害した場合等"]]}}},


  // ===== 長文問題追加50問（10951〜11000）=====
  {id:10951,unit:'r_ishi',level:3,field:'rights',text:'AはBとの間で甲マンション（分譲・2500万円）の売買契約を締結し、手付金250万円を支払った。Aは住宅ローンの審査が通らず残代金が用意できないため、Bに対して「ローンが通らなかった。手付金を返してほしい」と申し出た。売買契約書には「ローン特約」（融資が承認されない場合は白紙解除できる旨）は記載されていなかった。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['ローン特約がない場合でも、Aは買主として一方的に手付金の返還を求めることができる','ローン特約がなければ、Aの資金調達ができないことは買主Aの責任となり、Bに対して手付金返還を請求することなく契約の解除を申し出るには手付放棄による解除（手付金250万円を放棄）が必要','BはAの債務不履行（残代金不払い）を理由に契約を解除し損害賠償を請求できる','Aはローンが通らなかったことを理由に契約を当然に解除できる'],ans:1,exp:'ローン特約がない場合、資金調達できないことはAの責任（履行不能・履行遅滞）です。Aが自ら解除するには手付放棄（250万円放棄）による手付解除（民法557条）が必要です。相手方（B）が履行に着手していなければ手付放棄による解除が可能ですが、この場合Aは250万円を失います。BはAの残代金不払いを理由に債務不履行解除と損害賠償を請求できます。',"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "意思表示の瑕疵には詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失の第三者は保護）・通謀虚偽表示（無効・善意の第三者は保護）があります。", "example": ""}, "reason": {"text": "ローン特約がない場合、資金調達できないことは買主の責任です。手付解除は「手付放棄（買主）」または「手付倍返し（売主）」によります（民法557条）。ローン特約があれば白紙解除できますが、ない場合は手付解除のみとなります。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "ローン特約がない場合でも、Aは買主として一方的に手付金の返還を求めることができる", "reason": "ローン特約がなければAの資金調達不能は買主の責任であり、手付金の返還を一方的に求めることはできません。手付放棄による解除か履行の提供が必要です。", "caution": ""}, {"label": "BはAの債務不履行（残代金不払い）を理由に契約を解除し損害賠償を請求できる", "reason": "売主Bは債務不履行を理由に解除・損害賠償請求が可能ですが、設問では「Aが解除したい」という状況です。また、Bの解除には相当期間を定めた催告が原則必要です（民法541条）。", "caution": ""}, {"label": "Aはローンが通らなかったことを理由に契約を当然に解除できる", "reason": "ローン特約がなければローン不成立は自動的な解除事由になりません。契約の解除には法定の解除原因または当事者の合意が必要です。", "caution": ""}], "summary": {"head": ["手付解除の方法", "内容", "時期"], "rows": [["買主からの解除", "手付金を放棄", "相手方の履行着手前まで"], ["売主からの解除", "手付金の倍額を現実に提供", "相手方の履行着手前まで"], ["ローン特約あり", "白紙解除（損害賠償なし）", "ローン不承認確定後"]]}}},
  {id:10952,unit:'r_tanpo',level:3,field:'rights',text:'AはB銀行から4000万円を借り入れ、A所有の甲土地・乙建物（一括）に共同抵当権を設定した（甲土地時価3000万円・乙建物時価2000万円）。その後乙建物が火災で全焼し、Aは保険金1500万円を受け取った。B銀行は甲土地の競売を申し立てるとともに、乙建物の保険金に対しても物上代位を行使したいと考えている。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['乙建物が滅失した以上、乙建物に対する抵当権は消滅し保険金に対して物上代位はできない','B銀行は乙建物の火災保険金に対して物上代位（民法304条）を行使できる。払渡し前に差押えをすれば保険金1500万円からも優先弁済を受けることができる','共同抵当の場合、一方の目的物が滅失すると他方の抵当権も消滅する','保険金はAの固有財産となるため、B銀行は一切請求できない'],ans:1,exp:'共同抵当の目的物の一つが滅失した場合でも、その目的物に代わる保険金等（代位物）に対して物上代位を行使できます（民法304条）。B銀行は乙建物の保険金1500万円に対して払渡し前に差押えをすることで物上代位を行使できます。甲土地の競売と保険金への物上代位を組み合わせて4000万円の回収を図ることができます。',"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権です（民法369条）。質権は占有の移転が必要です。先取特権は法律上当然に成立する法定担保物権です。", "example": ""}, "reason": {"text": "物上代位は担保目的物が滅失した場合に、その代償（保険金・損害賠償金等）に抵当権の効力が及ぶ制度です（民法304条）。建物が火災で全焼した場合でも火災保険金に対して物上代位を行使できます。払渡し前の差押えが要件です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・非占有</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・占有</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "乙建物が滅失した以上保険金に対して物上代位はできない", "reason": "物上代位は目的物滅失の場合に保険金等の代償に効力が及ぶ制度です（民法304条）。滅失しても物上代位できます。", "caution": "目的物滅失→保険金に物上代位可（民法304条）。"}, {"label": "共同抵当の場合一方が滅失すると他方の抵当権も消滅する", "reason": "共同抵当は各目的物に独立して抵当権が設定されています。一方が滅失しても他方の抵当権は消滅しません（民法392条）。", "caution": ""}, {"label": "保険金はAの固有財産となるためB銀行は一切請求できない", "reason": "物上代位により保険金に抵当権の効力が及びます（民法304条）。払渡し前に差押えをすれば優先弁済を受けられます。", "caution": ""}], "summary": {"head": ["共同抵当と物上代位", "内容"], "rows": [["共同抵当", "複数の不動産に一括して抵当権設定"], ["一方が滅失した場合", "保険金への物上代位可（民法304条）"], ["他方の抵当権", "消滅しない（独立して存在）"], ["配当の調整", "民法392条（共同抵当の配当調整）"]]}}},
  {id:10953,unit:'r_saikensoron',level:3,field:'rights',text:'AはBに対して1000万円の貸金債権を有し、弁済期が到来している。Bは弁済を拒んでいるが、BはCに対して800万円の貸金債権を有している（Cの弁済期も到来済み）。AはBに代位してCに対し800万円の支払いを求めた（債権者代位権の行使）。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['AはBに無断で債権者代位権を行使することはできない','Aは自己の債権額の範囲でBのCに対する貸金債権を代位行使でき、Cに対してAへ直接800万円を支払うよう求めることができる','AはBの債権800万円を全額自己のものとして取得できる','AはCから回収した800万円をそのまま自己の取り分として保持できる'],ans:1,exp:'債権者代位権の行使にBの同意は不要です。Aは自己の債権額1000万円の範囲で、BのCに対する800万円の貸金債権を代位行使できます（民法423条・423条の2）。また、金銭その他の物の引渡しを求める場合、相手方Cに対してAへ直接支払うよう求めることができます（民法423条の3）。',"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要です（民法446条2項）。連帯保証人には催告・検索の抗弁権がありません（民法454条）。債権譲渡の第三者対抗要件は確定日付ある証書による通知または承諾です（民法467条2項）。", "example": ""}, "reason": {"text": "債権者代位権は、債務者Bの同意がなくても、債権保全の必要があるときに行使できます。代位行使できる範囲はAの債権額の限度であり、本問ではBのCに対する800万円全額を代位行使できます。金銭債権については、Cに対してAへ直接支払うよう求めることもできます（民法423条の3）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相殺の要件</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">双方が同種の債権</text></svg>", "choices": [{"label": "AはBに無断で債権者代位権を行使することはできない", "reason": "債権者代位権の行使に債務者の同意は不要です（民法423条1項）。", "caution": ""}, {"label": "AはBの債権800万円を全額自己のものとして取得できる", "reason": "代位権行使で回収した金銭はBの財産です（原則）。AはBへの債権を通じて回収しますが、他の債権者（C・D）との競合では優先権がありません。", "caution": ""}, {"label": "AはCから回収した800万円をそのまま自己の取り分として保持できる", "reason": "代位権で回収した金銭はBの財産として扱われ（判例）、AはBへの債権に基づく相殺等が必要です。「そのまま保持」は誤りです。", "caution": ""}], "summary": {"head": ["債権者代位権の行使と回収", "内容"], "rows": [["行使", "債務者の同意不要（民法423条1項）"], ["回収金", "Bの財産として扱われる（判例）"], ["AのBへの回収", "相殺等で充当（優先権なし）"], ["注意点", "代位権は担保的機能なし（詐害行為取消しと異なる）"]]}}},
  {id:10954,unit:'r_baibai',level:3,field:'rights',text:'AはBに対して甲建物（中古・築10年）を1500万円で売却した。売買契約書には「建物の雨漏り・シロアリ被害については売主は一切責任を負わない」という特約があった。Aは売買前にシロアリ被害があることを知っており、駆除処理も施していた（完全駆除済み）が、Bにはこの事実を伝えなかった。引渡し後、Bがシロアリ被害の痕跡を発見し修繕費100万円が必要なことがわかった。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['売買契約書に特約があるため、AはBに対して一切の責任を負わない','Aがシロアリ被害を知りながらBに告げなかった場合は、特約の効力が及ばず（民法572条）、BはAに対して契約不適合責任（追完・代金減額・損害賠償等）を追及できる','シロアリ駆除処理を施していたため、Aに不適合はない','Bは建物検査をすべきであり、調査しなかった自己責任'],ans:1,exp:'売主が知りながら告げなかった契約不適合については、免責特約（「一切責任を負わない」という特約）の効力が及びません（民法572条）。Aはシロアリ被害とその痕跡をBに告げなかったため、BはAに対して追完請求・代金減額請求・損害賠償請求が可能です。駆除処理を施していたとしても、その事実をBに告知する義務があります。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "売主が不適合を知りながら告げなかった場合は免責特約の効力が及びません（民法572条）。Aはシロアリ被害を知っており（駆除処理済み）Bに告げていないため、「シロアリ被害は責任を負わない」という特約はその不適合に及びません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "特約があるためAはBに対して一切の責任を負わない", "reason": "売主が知りながら告げなかった不適合には特約の効力が及びません（民法572条）。「一切の責任なし」は誤りです。", "caution": "知りながら告げなかった→特約無効（民法572条）。"}, {"label": "シロアリ駆除処理を施していたためAに不適合はない", "reason": "駆除処理後も痕跡・被害が残っていれば不適合が生じます。また駆除の事実をBに告げなかったことは告知義務の問題です（民法572条）。", "caution": ""}, {"label": "Bは建物検査をすべきであり自己責任", "reason": "買主の調査不足は過失として考慮される場合がありますが、売主の告知義務違反（民法572条）は免責されません。", "caution": ""}], "summary": {"head": ["知りながら告げなかった場合（民法572条）", "内容"], "rows": [["免責特約", "知りながら告げなかった不適合には及ばない"], ["買主の権利", "追完・代金減額・損害賠償・解除すべて可"], ["宅建業者の場合", "同様に適用（宅建業法40条の特則も参照）"]]}}},
  {id:10955,unit:'r_chinshaku',level:3,field:'rights',text:'AはB所有のマンション（居住用・月額賃料8万円）を賃借中である。Bは「建物を取り壊して駐車場にしたい」として更新拒絶を通知した。Aには8年間その建物に居住してきた実績があり、近隣に同条件の賃貸物件はほとんどない。Bは立退料の申し出はしていない。この場合に関する記述として借地借家法の規定によれば正しいものはどれか。',opts:['建物の取壊しは当然に正当事由となるため、Bは立退料なしで更新を拒絶できる','更新拒絶の正当事由は賃貸人・賃借人双方の必要性等を総合考慮するものであり、建物取壊しの必要性はあるとしてもAの長期居住実績・代替物件の少なさ・立退料の申し出がないことを考慮すると、正当事由が認められない可能性が高い','Bが建物取壊しを希望する場合は常に正当事由が認められる','8年間居住した賃借人は永遠に退去させられない'],ans:1,exp:'建物賃貸借の更新拒絶には正当事由が必要（借地借家法28条）で、賃貸人の建物使用の必要性・賃借人の使用の必要性・従前の経緯・建物の利用状況・立退料の申し出等を総合考慮します。賃借人Aの8年居住実績・代替物件の少なさ・立退料の提示がないことは正当事由の認定を困難にします。Bの取壊し希望だけでは不十分な場合が多く、相当額の立退料提供が必要になることが多いです。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "更新拒絶の正当事由は賃貸人・賃借人双方の必要性等を総合考慮します（借地借家法28条）。建物取壊しの必要性があっても賃借人の長期居住実績・代替物件の少なさ・立退料未提供等の事情がある場合は正当事由が認められないことがあります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "建物の取壊しは当然に正当事由となる", "reason": "建物取壊しは重要な考慮要素ですが、それだけで当然に正当事由が認められるわけではありません（借地借家法28条）。", "caution": "建物取壊し≠当然に正当事由あり。総合考慮が必要。"}, {"label": "賃貸人が建物取壊しを希望する場合は常に正当事由が認められる", "reason": "賃貸人の事情だけでなく賃借人の必要性・立退料等を総合考慮します（借地借家法28条）。「常に認められる」は誤りです。", "caution": ""}, {"label": "8年間居住した賃借人は永遠に退去させられない", "reason": "長期居住実績は正当事由判断の一要素ですが、適切な立退料の提供等があれば正当事由が認められる場合もあります（借地借家法28条）。", "caution": ""}], "summary": {"head": ["正当事由判断の要素", "内容"], "rows": [["賃貸人側", "建替え・取壊し・自己使用の必要性・建物老朽化"], ["賃借人側", "長期居住・代替物件の少なさ・事業の必要性"], ["立退料", "提供があれば正当事由を補完"], ["判断", "総合衡量（どちらが強いかで決まる）"]]}}},
  {id:10956,unit:'r_fuhoko',level:3,field:'rights',text:'Aはインターネット上でBについて虚偽の事実（「Bは詐欺師だ」という記事）を多数の人が閲覧できるサイトに掲載した。Bはこれにより精神的損害（慰謝料100万円相当）・取引先からの信用失墜による財産的損害（200万円相当）を被った。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['インターネット上の記事は証拠を残しやすいため、不法行為は成立しない','Aの行為は名誉毀損（不法行為・民法709条・723条）に当たり、BはAに対して財産的損害・精神的損害（慰謝料）の賠償請求および名誉回復の措置（記事の削除・謝罪広告等）を請求できる','インターネット上の表現は自由であるため不法行為にならない','Bは損害賠償か名誉回復措置のどちらか一方しか請求できない'],ans:1,exp:'名誉毀損による不法行為（民法709条・723条）はインターネット上の記事でも成立します。BはAに対して①財産的損害賠償200万円②精神的損害（慰謝料）100万円③名誉回復のための適当な処分（記事削除・謝罪広告等）を組み合わせて請求できます（民法723条）。損害賠償と名誉回復措置は並行して請求可能です。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "インターネット上での名誉毀損も不法行為（民法709条・710条）が成立します。被害者は①財産的損害の賠償、②精神的損害（慰謝料）の賠償、③名誉回復の措置（記事削除・謝罪広告等・民法723条）を請求できます。これらは併せて請求できます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "インターネット上の記事は証拠を残しやすいため不法行為は成立しない", "reason": "証拠が残りやすいことは不法行為の成立要件ではありません。インターネット上の名誉毀損も不法行為です（民法709条）。", "caution": ""}, {"label": "インターネット上の表現は自由であるため不法行為にならない", "reason": "表現の自由があっても虚偽の事実による名誉毀損は不法行為です（民法709条）。インターネット上も同様です。", "caution": ""}, {"label": "Bは損害賠償か名誉回復措置のどちらか一方しか請求できない", "reason": "損害賠償と名誉回復措置（民法723条）は併せて請求できます。「どちらか一方」は誤りです。", "caution": ""}], "summary": {"head": ["名誉毀損の救済（民法709条・710条・723条）", "内容"], "rows": [["財産的損害", "賠償請求可"], ["慰謝料", "賠償請求可（民法710条）"], ["名誉回復措置", "記事削除・謝罪広告等（民法723条）"], ["同時請求", "複数の救済手段を併せて請求可"]]}}},
  {id:10957,unit:'r_souzoku',level:3,field:'rights',text:'Aが死亡し、配偶者B・長男C・長女Dが相続人となった。遺産分割協議において、B・C・Dは「甲土地はCが相続し、預貯金500万円はB・Dが250万円ずつ相続する」と合意した。その後、甲土地について以前からAが第三者Eに対して負っていた債務（担保付き）が発覚した。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['遺産分割協議で決まった相続内容は絶対であり、後から発覚した債務は相続人全員で按分して負担する','遺産分割協議は相続人全員の合意が必要であるが、後から判明した遺産（債務含む）について遺産分割協議の効力がどこまで及ぶかは協議内容による。相続債務はそもそも法定相続分の割合で各相続人が当然に分割して負担するのが原則（民法900条・899条）','Cが甲土地を相続したため、EへのAの債務もCのみが全額負担する','Eは遺産分割協議の内容に拘束される'],ans:1,exp:'相続によって生じた債務（被相続人の債務）は法定相続分に応じて各相続人に分割承継されるのが原則です（民法899条・900条）。遺産分割協議でCが甲土地を取得するとしても、Aの債権者Eに対しては協議の内容は対抗できず、Eに対してはB・C・D全員が法定相続分の割合で責任を負います。',"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2", "basis": {"text": "配偶者と子の場合は各1/2（民法900条）。相続放棄は3か月以内に家庭裁判所へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2です（民法1042条）。遺産分割協議は全員合意が必要です。", "example": ""}, "reason": {"text": "相続債務は遺産分割協議に関わらず、法定相続分の割合で各相続人が当然に分割して承継します（判例・民法900条）。遺産分割協議で特定の相続人が負担すると決めても、債権者（E）には対抗できません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続の主要ポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子の相続分</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は法定相続分の1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割協議</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "遺産分割協議で決まった相続内容は絶対であり、後から発覚した債務は協議内容に従う", "reason": "相続債務は法定相続分で当然に各相続人が負担します（判例）。遺産分割協議で決めた内容は債権者には対抗できません。", "caution": ""}, {"label": "Cが甲土地を相続したため、EへのAの債務もCのみが全額負担する", "reason": "相続債務は法定相続分で分割されます（判例）。Cが土地を相続したことと、Eへの債務の負担割合は別問題です。", "caution": ""}, {"label": "Eは遺産分割協議の内容に拘束される", "reason": "遺産分割協議は相続人間の内部的な合意であり、Eのような第三者債権者には対抗できません（判例）。", "caution": ""}], "summary": {"head": ["相続債務の承継", "内容"], "rows": [["原則", "法定相続分で各相続人が当然分割して承継（判例）"], ["遺産分割協議での変更", "相続人間では有効だが債権者には対抗不可"], ["債権者の請求", "各相続人に法定相続分の割合で請求可"]]}}},
  {id:10958,unit:'r_touki',level:3,field:'rights',text:'A所有の甲土地についてBが時効取得を主張している（20年間占有）。時効完成後にAはCに甲土地を売却し、AからCへの所有権移転登記が完了した。BはCに対して時効取得による所有権を主張したい。この場合に関する記述として民法の規定及び判例によれば正しいものはどれか。',opts:['時効完成後の第三者Cに対して、Bは登記なしに時効取得を対抗できる','時効完成後にAからCへの売買・登記がなされた場合、BとCは対抗関係（民法177条）となり、Bは登記を備えなければCに時効取得を対抗できない','Cが善意であれば常にCが優先する','時効取得は登記を必要としない'],ans:1,exp:'判例上、時効完成後に登場した第三者（C）との関係は対抗問題（民法177条）となります。BはCよりも先に所有権移転登記を備えれば時効取得をCに対抗できますが、Cが先に登記を完了した場合はCに対抗できません。時効が完成した後に第三者が現れた場合は、登記の先後で決します。これは時効完成前の第三者（取消し等の問題）とは区別されます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "時効完成後に登場した第三者との関係は対抗問題です（判例）。時効取得者は登記を備えなければ、時効完成後に登記を得た第三者に対抗できません。これは民法177条の適用です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "時効完成後の第三者Cに対して、Bは登記なしに時効取得を対抗できる", "reason": "時効完成後の第三者との関係は対抗問題であり、Bは登記を備えなければCに時効取得を対抗できません（判例）。", "caution": "時効完成前→登記不要で対抗可。時効完成後→対抗問題（登記が必要）。"}, {"label": "Cが善意であれば常にCが優先する", "reason": "時効完成後の第三者との関係は善意・悪意ではなく登記の先後で決まります（対抗問題）。", "caution": ""}, {"label": "時効取得は登記を必要としない", "reason": "時効完成後の第三者との対抗関係では登記が必要です（判例）。「一切不要」は誤りです。", "caution": ""}], "summary": {"head": ["時効と第三者", "対抗力"], "rows": [["時効完成前の第三者", "時効援用で対抗可（登記不要・判例）"], ["時効完成後の第三者", "対抗問題→先に登記した者が勝つ（民法177条・判例）"]]}}},
  {id:10959,unit:'r_shakuchi',level:3,field:'rights',text:'AはB所有の土地を賃借し（借地権存続期間30年）、その土地上にA所有の建物（登記済み）を建築していた。存続期間満了後、Bは「息子に土地を使わせたい」として更新を拒絶した。Aは引き続き建物に居住したいとして更新を請求し、BとAの協議が成立しなかった。この場合に関する記述として借地借家法の規定によれば正しいものはどれか。',opts:['更新拒絶がある以上、借地契約は期間満了で当然終了し、Aは建物を取り壊して退去しなければならない','Bが更新拒絶に正当事由（借地借家法6条）がない場合、Aの更新請求（同法5条1項）に対して法定更新が成立し、AはBに対して建物買取請求権（同法13条）を行使するかわりに借地権を継続できる','正当事由なしでBが更新を拒絶した場合でも、期間満了後2か月以内にAが退去すれば問題ない','Aは法定更新を主張せず建物買取請求権（同法13条）のみを行使できる'],ans:1,exp:'借地権の存続期間満了時に借地権者Aが更新請求をした場合（借地借家法5条1項）、土地所有者Bは正当事由（同法6条）がなければ拒絶できず、法定更新が成立します。正当事由（息子の利用のみでは不十分な場合も多い）がなければAは引き続き建物を使用できます。Bが正当事由ありとして更新を拒絶した場合、Aは建物買取請求権を行使することも可能です（同法13条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "普通借地権の更新拒絶には正当事由が必要です（借地借家法6条）。長男の使用という理由だけでは不十分な場合、正当事由が認められず法定更新となります（借地借家法5条1項）。借地人は更新か建物買取請求権行使かを選択できます（借地借家法13条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "更新拒絶がある以上借地契約は期間満了で当然終了しAは建物を取り壊して退去しなければならない", "reason": "正当事由なしの更新拒絶は効力がなく、法定更新されます（借地借家法5条1項）。「当然終了」は誤りです。", "caution": ""}, {"label": "正当事由なしでBが更新を拒絶した場合でも期間満了後2か月以内にAが退去すれば問題ない", "reason": "法定更新が成立した場合、Aは退去する義務はありません（借地借家法5条1項）。2か月という規定もありません。", "caution": ""}, {"label": "Aは法定更新を主張せず建物買取請求権のみを行使できる", "reason": "設問の正解選択肢2の内容は「法定更新を主張する」場合の説明です。Aには法定更新と建物買取請求権のどちらを選ぶかの選択肢があります（借地借家法5条・13条）。「のみ」という限定は誤りです。", "caution": ""}], "summary": {"head": ["借地権の法定更新と建物買取請求権", "内容"], "rows": [["法定更新", "正当事由なければ更新拒絶無効→法定更新（借地借家法5条1項）"], ["建物買取請求権", "更新拒絶された場合に借地人が地主に時価で買取請求可（借地借家法13条）"], ["Aの選択", "法定更新の主張か建物買取請求権の行使か選択可能"]]}}},
  {id:10960,unit:'l_menkyo',level:3,field:'law',text:'宅建業者A（甲県知事免許・個人事業主）が死亡した。Aの相続人はBのみであり、BはAの宅建業を引き継いで自ら宅建業を営みたいと考えている。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['宅建業の免許は相続によって当然にBに引き継がれる','宅建業の免許は一身専属的であり相続されない。BはAの死亡を知った日から30日以内に甲県知事に届け出る必要があり、Aが締結した取引を結了する目的の範囲で宅建業者とみなされる。Bが新たに宅建業を営むには自ら免許を受ける必要がある','Bは免許申請なしに即座にAの後継として業を行える','Aの死亡からBの免許取得まで宅建業は完全に停止される'],ans:1,exp:'宅建業の免許は一身専属的なものであり、被相続人の免許は相続によって当然に相続人に引き継がれません（宅建業法11条1項1号）。相続人は死亡を知った日から30日以内に免許権者へ届け出る必要があります。また、相続人は被相続人が締結した契約に基づく取引を結了する目的の範囲内で宅建業者とみなされます（同法76条）。Bが新たに宅建業を営むには自ら免許を受ける必要があります。',"kaisetsu":{"topic": "宅建業の免許：知事・大臣免許の区別・有効期間5年・欠格事由", "basis": {"text": "1都道府県のみ→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間です。", "example": ""}, "reason": {"text": "宅建業の免許は一身専属的であり相続されません（宅建業法11条1項1号）。相続人は死亡を知った日から30日以内に届け出る必要があります。相続人が宅建業者とみなされるのは、被相続人が締結した取引を結了する目的の範囲内です。新たに宅建業を営むには相続人自身が免許を受ける必要があります。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（拘禁刑以上・特定罰金等）</text></svg>", "choices": [{"label": "宅建業の免許は相続によって当然にBに引き継がれる", "reason": "宅建業の免許は一身専属的であり相続されません（宅建業法11条1項1号）。当然に引き継がれることはありません。", "caution": "宅建業の免許：相続されない（一身専属的）。"}, {"label": "Bは免許申請なしに即座にAの後継として業を行える", "reason": "Bが業を継続するためには届出（30日以内）が必要です（宅建業法11条1項1号・2項）。即座に行えるわけではありません。", "caution": ""}, {"label": "Aの死亡からBの免許取得まで宅建業は完全に停止される", "reason": "BはAが締結した取引を結了する目的の範囲で宅建業者とみなされます。新たに宅建業を営むにはB自身が免許を受ける必要があります。", "caution": ""}], "summary": {"head": ["個人業者の死亡（宅建業法11条）", "内容"], "rows": [["免許の承継", "されない（一身専属的）"], ["相続人の届出", "知った日から30日以内に届出"], ["死亡後の扱い", "既存取引の結了目的で宅建業者とみなされる"], ["その後", "相続人が新たに免許申請が必要"]]}}},
  {id:10961,unit:'l_jusetsu',level:3,field:'law',text:'宅建業者Aは、B所有の土地（市街化調整区域内・農地・地目：田）の売買を媒介した。買主Cは住宅建築を目的としており、Aは重要事項説明を行った。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['農地であることは重要事項説明には関係ない','市街化調整区域内の農地は農地法・都市計画法の許可等がなければ宅地転用が困難であり、これらの法令上の制限を重要事項として説明しなければならない','Cが農業者でないことをAは説明する義務がない','農地法の許可は売買契約の前提条件となるが、重要事項説明書への記載は任意'],ans:1,exp:'市街化調整区域内の農地（田）は、農地法5条の転用許可・都市計画法43条の建築許可等の規制を受けます。これらの法令上の制限は重要事項として説明しなければなりません（宅建業法35条1項2号）。CがこのAの農地に住宅を建築するためには農地法・都市計画法の許可等が必要であり、許可が得られない場合は目的を達成できないため重要な説明事項です。',"kaisetsu":{"topic": "重要事項説明：宅建士が説明・売主への交付は不要・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主への交付義務はありません。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能です。", "example": ""}, "reason": {"text": "市街化調整区域内の農地は農地法・都市計画法による制限があり、宅地転用には許可等が必要です（農地法5条・都市計画法43条）。これらの法令上の制限を重要事項として説明しなければなりません（宅建業法35条1項2号）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "農地であることは重要事項説明には関係ない", "reason": "農地法の制限は法令上の制限として重要事項説明の必須記載事項です（宅建業法35条1項2号）。「関係ない」は誤りです。", "caution": "農地法・都市計画法の制限：重要事項説明の必須記載事項（宅建業法35条1項2号）。"}, {"label": "Cが農業者でないことをAは説明する義務がない", "reason": "Cの農業者該当性に関わらず、農地法の制限（転用には農業委員会・知事の許可が必要等）を説明する義務があります（宅建業法35条1項2号）。", "caution": ""}, {"label": "農地法の許可は売買契約の前提条件となるが重要事項説明書への記載は任意", "reason": "農地法上の制限は重要事項説明書への記載が義務です（宅建業法35条1項2号）。任意ではありません。", "caution": ""}], "summary": {"head": ["農地・市街化調整区域の重要事項", "内容"], "rows": [["農地法の制限", "転用には農業委員会・知事の許可等が必要"], ["都市計画法の制限", "市街化調整区域は原則として建築不可"], ["重要事項への記載", "これらの制限を必ず記載（宅建業法35条1項2号）"]]}}},
  {id:10962,unit:'l_baikai',level:3,field:'law',text:'宅建業者Aは、B所有の土地（売買代金6000万円）の売却について専属専任媒介契約を締結した。A以外の業者が見つけた買主Cとの間でB自らが直接売買契約を締結しようとした。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['Bが自ら見つけた買主との契約は常に有効','専属専任媒介契約では、依頼者Bは自ら発見した相手方とも直接取引をすることができない（宅建業法34条の2第3項）。BがA以外の業者が見つけた買主Cと直接契約を締結することはできない','専属専任媒介契約でも依頼者は自由に別の業者と取引できる','Aが見つけた買主との取引のみ制限される'],ans:1,exp:'専属専任媒介契約は、依頼者が他の宅建業者に依頼することも、依頼者自ら発見した相手方との取引も禁止する最も拘束力の強い媒介契約です（宅建業法34条の2第3項）。Bが直接相手方を見つけた場合でも（または他の業者が見つけた場合でも）Bは自由に取引できません。違反した場合、Aは違約金を請求できます（報酬告示）。',"kaisetsu":{"topic": "媒介契約：専任は3か月・専属専任は自己発見不可・レインズ登録義務", "basis": {"text": "専任・専属専任媒介の有効期間の上限は3か月（宅建業法34条の2）。専属専任は自己発見取引も不可。専任は7日以内、専属専任は5日以内にレインズ登録が必要。業務報告は専任2週間に1回、専属専任1週間に1回。", "example": ""}, "reason": {"text": "専属専任媒介契約では、依頼者は自ら発見した相手方とも宅建業者を通じて取引しなければなりません（宅建業法34条の2第3項）。他の業者が見つけた買主との直接取引も含めて、すべての取引を依頼した宅建業者Aを通じて行う必要があります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">媒介契約の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">一般</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専任</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">専属専任</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己発見取引</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">可</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">レインズ登録</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">7日以内</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5日以内</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">業務報告</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">なし</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間に1回</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1週間に1回</text></svg>", "choices": [{"label": "Bが自ら見つけた買主との契約は常に有効", "reason": "専属専任媒介では自己発見取引も宅建業者を通じる必要があります（宅建業法34条の2第3項）。直接取引は許可されていません。", "caution": "専属専任媒介：すべての取引を依頼業者を通じて行う義務あり。"}, {"label": "専属専任媒介契約でも依頼者は自由に別の業者と取引できる", "reason": "専属専任媒介では他業者への依頼も自己発見取引も禁止されています（宅建業法34条の2第3項）。「自由に」は誤りです。", "caution": ""}, {"label": "Aが見つけた買主との取引のみ制限される", "reason": "専属専任媒介の制限は買主の発見者に関わらず、すべての取引について依頼業者Aを通じることを義務付けています（宅建業法34条の2第3項）。", "caution": ""}], "summary": {"head": ["専属専任媒介の自己発見取引禁止", "内容"], "rows": [["自己発見取引", "禁止（宅建業法34条の2第3項）"], ["他業者が発見した相手方との直接取引", "禁止"], ["宅建業者Aを通じた取引", "義務"], ["違反の効果", "Aへの報酬支払義務が発生する場合あり"]]}}},
  {id:10963,unit:'l_hoshu',level:3,field:'law',text:'宅建業者Aは、B所有の倉庫（賃貸中・月額賃料100万円）の売買を媒介し、売買代金2億円で売買契約を成立させた。AはBから媒介報酬として消費税込みで726万円を受け取った。この場合に関する記述として宅建業法の規定（報酬告示）によれば正しいものはどれか。',opts:['2億円×3%+6万円=606万円（税別）が上限、消費税10%を加えて666.6万円が上限であり、726万円は上限超過で違法','賃貸中の倉庫なので月額賃料100万円を基準に報酬上限を計算する','2億円×3%=600万円（税別）が上限で適法','2億円の取引は高額なため報酬上限の規制は適用されない'],ans:0,exp:'売買の媒介報酬の上限（速算式）：代金400万円超は「代金×3%+6万円」（税別）。2億円×3%+6万円=606万円（税別）。消費税10%を加えると606万円×1.1=666.6万円（税込）が上限。AがBから726万円（税込）を受け取ったのは上限666.6万円を超えており、宅建業法違反です（過大な報酬の受領・宅建業法47条の2）。',"kaisetsu":{"topic": "報酬：売買は代金×3%+6万（400万超）・賃貸は借賃1か月・上限超過は不可", "basis": {"text": "売買媒介報酬（400万超）の一方からの上限は代金×3%+6万円（税別）。双方合計は一方上限×2。賃貸媒介（居住用・非居住用とも）は借賃1か月分。依頼者の承諾があっても上限超過は不可。", "example": ""}, "reason": {"text": "代金2億円の媒介報酬上限は2億円×3%＋6万円＝606万円（税別）＝消費税込みで666.6万円です（告示）。受領した726万円は666.6万円を超えているため違法です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対象</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（400万超）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万（一方）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（200万以下）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸（双方合計）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借賃1か月分</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">低廉な空家等（800万円以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円まで（説明・合意要）</text></svg>", "choices": [{"label": "2億円×3%+6万円=606万円（税別）が上限、消費税10%を加えて666.6万円が上限。726万円は上限を超えているため違法", "reason": "この選択肢は選択肢1と同内容です。726万円は違法です。", "caution": ""}, {"label": "2億円×3%=600万円（税別）が上限で適法", "reason": "速算式は3%＋6万円であり（告示）、「＋6万円」を忘れた計算です。上限は606万円（税別）です。また726万円は666.6万円（税込）を超えており違法です。", "caution": "速算式：3%＋6万円。「3%のみ」は誤り。"}, {"label": "2億円の取引は高額なため報酬上限の規制は適用されない", "reason": "売買代金の高低に関わらず報酬上限規制は適用されます（告示・宅建業法46条）。", "caution": ""}], "summary": {"head": ["設問の報酬計算", "内容"], "rows": [["代金", "2億円"], ["速算式", "2億円×3%＋6万円"], ["計算（税別）", "600万円＋6万円＝606万円"], ["消費税込", "606万円×1.1＝666.6万円"], ["受領額", "726万円→上限超過で違法"]]}}},
  {id:10964,unit:'k_toshi',level:3,field:'limit',text:'AはR市（都市計画区域内・市街化区域・近隣商業地域・防火地域）内に土地（敷地面積300m2・建ぺい率80%・容積率400%）を所有し、耐火構造の商業ビル（7階建て・延べ面積1000m2）を建築しようとしている。この計画についての建築確認について建築基準法の規定によれば正しいものはどれか。',opts:['近隣商業地域の7階建て商業ビルは規模が大きいため建築確認は不要','防火地域内での耐火建築物の建築は建築確認が免除される','高さが60m以下かつ一定規模以内の建築物は建築確認が必要。また1000m2超（特殊建築物）の場合も確認申請が必要','7階建てビルは原則として都道府県知事の許可が必要'],ans:2,exp:'建築基準法上、建築確認が必要な場合（同法6条1項）：①特殊建築物でその用途に供する部分が200m2超②木造3階建て以上または延べ面積500m2超または高さ13m超等③上記以外で地上2階以上または延べ面積200m2超（都市計画区域内等）。商業ビル（事務所等）は特殊建築物ではないため②または③で判断します。7階建て・延べ面積1000m2の建築物は建築確認が必要です。',"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域での1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は市街化調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "建築確認は原則として工事着工前に必要です。大規模建築物（高さ60m超等）や特殊建築物（飲食店・ホテル・病院等）で200㎡超のものは建築確認が必要です（建築基準法6条1項1号・3号）。防火地域内での耐火建築物でも確認申請は必要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化する区域</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可基準</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "近隣商業地域の7階建て商業ビルは規模が大きいため建築確認は不要", "reason": "規模が大きいことは確認申請不要の理由にはなりません（建築基準法6条1項）。むしろ大規模な建築物は確認申請が必要です。", "caution": "建築確認：工事着工前に必要（建築基準法6条1項）。"}, {"label": "防火地域内での耐火建築物の建築は建築確認が免除される", "reason": "防火地域内での耐火建築物でも建築確認は免除されません（建築基準法6条1項）。", "caution": ""}, {"label": "7階建てビルは原則として都道府県知事の許可が必要", "reason": "建築確認は確認審査機関（指定確認検査機関または建築主事）が行い、都道府県知事の直接許可ではありません（建築基準法6条等）。", "caution": ""}], "summary": {"head": ["建築確認が必要な場合（建築基準法6条1項）", "内容"], "rows": [["特殊建築物（別表第一）", "用途に供する床面積200㎡超（1号）"], ["木造以外の大規模建築物", "3階以上または延べ面積500㎡超等（3号）"], ["すべての建築物", "10㎡超の増築・改築等（4号）"], ["高さ60m超", "構造計算適合性判定が必要"]]}}},
  {id:10965,unit:'k_kenchiku',level:3,field:'limit',text:'Aは第二種低層住居専用地域（高さ制限10m・北側斜線制限あり・建ぺい率40%・容積率60%）に土地（150m2）を所有し、小規模な店舗兼住宅（2階建て・延べ面積80m2・建築面積55m2）を建築しようとしている。建ぺい率・容積率・高さの適法性について建築基準法の規定によれば正しいものはどれか。',opts:['建ぺい率55/150≒36.7%<40%OK、容積率80/150≒53.3%<60%OK。ただし第二種低層住居専用地域では店舗の建築は一切できない','建ぺい率55/150≒36.7%<40%適法。容積率80/150≒53.3%<60%適法。第二種低層住居専用地域では150m2以下の日用品販売店舗兼住宅は建築可能。2階建ての高さが10m以下であれば高さ制限もクリア','容積率が60%以下なら建築制限は一切ない','北側斜線制限は適用されない'],ans:1,exp:'建ぺい率：55m2÷150m2≒36.7%＜40%→適法。容積率：80m2÷150m2≒53.3%＜60%→適法。第二種低層住居専用地域では、床面積150m2以下の日用品販売小売業等の店舗兼住宅（建築基準法別表第二（ろ）欄2号）は建築可能です。2階建ての一般的な高さ（約7m前後）は10mの高さ制限内に収まります。北側斜線制限は低層住居系で適用されます。',"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・道路斜線・用途制限", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。用途地域ごとに建築物の制限があります。", "example": ""}, "reason": {"text": "第二種低層住居専用地域では150㎡以下の日用品販売店舗兼住宅は建築できます（建築基準法別表第二）。建ぺい率55÷150≒36.7%<40%・容積率80÷150≒53.3%<60%ともに適法。高さが10m以下であれば絶対高さ制限もクリアです。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">第1種低層</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">学校は建築可</text></svg>", "choices": [{"label": "建ぺい率・容積率はOKだが第二種低層住居専用地域では店舗の建築は一切できない", "reason": "第二種低層住居専用地域では150㎡以下の日用品販売店舗兼住宅等は建築できます（建築基準法別表第二）。「一切できない」は誤りです。", "caution": "第二種低層住居専用地域：150㎡以下の日用品販売店舗兼住宅は可（建築基準法別表第二）。"}, {"label": "容積率が60%以下なら建築制限は一切ない", "reason": "容積率をクリアしていても用途規制・高さ制限等を別途満たす必要があります（建築基準法）。容積率のみで「制限なし」とはなりません。", "caution": ""}, {"label": "北側斜線制限は適用されない", "reason": "第二種低層住居専用地域には北側斜線制限が適用されます（建築基準法56条1項3号）。「適用されない」は誤りです。", "caution": ""}], "summary": {"head": ["設問の計算（第二種低層住居専用地域）", "判定"], "rows": [["建ぺい率", "55÷150≒36.7%<40%→適法"], ["容積率", "80÷150≒53.3%<60%→適法"], ["用途（150㎡以下店舗兼住宅）", "第二種低層住居専用地域で可（建築基準法別表第二）"], ["高さ", "2階建て・10m以下であれば絶対高さ制限クリアの可能性"]]}}},
  {id:10966,unit:'k_nochi',level:3,field:'limit',text:'AはS市（市街化区域）の農地（面積400m2）を所有している。Aはこの農地をBに売却し、BはこれをCに転売する計画がある。BおよびCはいずれも農業者でなく、農地を宅地として利用する予定である。この場合に関する記述として農地法の規定によれば正しいものはどれか。',opts:['市街化区域内の農地の売買は農地法の適用を受けない','市街化区域内の農地の権利移動（AからBへの売却・農地法3条）は農業委員会への届出のみで足り、許可は不要。ただしBが農業者でない場合の宅地転用目的での取得は農地法5条の問題となり、市街化区域内であれば農業委員会への届出で足りる','AからBへの農地の売却には、常に農業委員会の許可が必要','市街化区域内の農地の宅地転用には農林水産大臣の許可が必要'],ans:1,exp:'農地法の規制：①権利移動（農地→農地・農地法3条）は農業委員会の許可が必要。ただし農業者でない者への農地売買はそもそも農地法3条の許可が得られないため、宅地転用目的の場合は農地法5条（転用目的の権利移動）で扱います。②市街化区域内の農地の転用（農地法4条・5条）は農業委員会への届出のみで足ります（許可不要）。AからBへの宅地転用目的での売却は農地法5条の問題で市街化区域内のため届出のみです。',"kaisetsu":{"topic": "農地法：3条は農業委員会・4条・5条は都道府県知事・市街化区域は届出のみ", "basis": {"text": "農地法3条（権利移動・農地→農地）の許可権者は農業委員会。4条（自己転用）・5条（転用目的の権利移動）は都道府県知事等。市街化区域内の農地転用（4・5条）は農業委員会への届出のみでOK。相続は許可不要・届出3か月以内。", "example": ""}, "reason": {"text": "市街化区域内の農地の権利移動（農地法3条）は農業委員会への届出で足ります（農地法3条1項7号）。市街化区域内の農地の転用目的売却（農地法5条）も農業委員会への届出で足ります（農地法5条1項7号）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">市街化区域</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">特例なし</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text></svg>", "choices": [{"label": "市街化区域内の農地の売買は農地法の適用を受けない", "reason": "市街化区域内の農地も農地法の適用を受けますが、手続きが届出で足ります（農地法3条1項7号等）。「適用なし」は誤りです。", "caution": "市街化区域内の農地：農地法は適用されるが、農業委員会への届出で足りる。"}, {"label": "AからBへの農地の売却には常に農業委員会の許可が必要", "reason": "市街化区域内の農地は農業委員会への届出で足ります（農地法3条1項7号等）。「常に許可必要」は誤りです。", "caution": ""}, {"label": "市街化区域内の農地の宅地転用には農林水産大臣の許可が必要", "reason": "市街化区域内の農地の転用は農業委員会への届出で足ります（農地法4条1項7号）。大臣の許可は不要です。", "caution": ""}], "summary": {"head": ["市街化区域内の農地取引", "手続き"], "rows": [["権利移動（農地法3条）", "農業委員会への届出"], ["自己転用（農地法4条）", "農業委員会への届出"], ["転用目的の権利移動（農地法5条）", "農業委員会への届出"]]}}},
  {id:10967,unit:'t_joto',level:3,field:'tax',text:'AはT市内の居住用一戸建て住宅（所有期間8年）を売却しようとしている。売却価格は4500万円、取得費は3500万円（取得時の諸費用込み）、譲渡費用は135万円の予定である。Aはこの3年前に別の居住用財産を売却し3000万円特別控除を利用済みである。この場合に関する記述として租税特別措置法の規定によれば正しいものはどれか。',opts:['3年前に3000万円控除を使ったが今回も再度利用できる','居住用財産の3000万円特別控除は、適用を受けた年の前年・前々年に同控除の適用を受けていない場合に限り利用可能。3年前の利用は前年・前々年に含まれないため、今回も適用できる','3000万円特別控除は一生に一度しか利用できない','3年前に利用済みのため今回は利用できない'],ans:1,exp:'居住用財産の3000万円特別控除（租税特別措置法35条）は、譲渡した年の前年・前々年に同控除の適用を受けていなければ利用できます。3年前の利用は「前年」「前々年」に含まれないため（3年前は前々年のさらに1年前）、今回も3000万円特別控除を適用できます。課税譲渡所得：4500万円－3500万円－135万円－3000万円=△135万円→課税なし。',"kaisetsu":{"topic": "譲渡所得：分離課税・長期は20%・3,000万円控除は3年に1回", "basis": {"text": "土地・建物の譲渡所得は分離課税（申告分離課税）。長期（5年超）の税率は合計20%（所得税15%+住民税5%）。短期（5年以下）は39%（所得税30%+住民税9%）。3,000万円特別控除は前年・前々年に適用があれば使えません（3年に1回）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">譲渡所得のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税方式</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">分離課税</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">長期（5年超）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計20%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">短期（5年以下）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計39%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3,000万円控除</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年に1回の制限</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10968,unit:'t_shutoku',level:3,field:'tax',text:'AはU市内の中古住宅（昭和55年新築・木造・延べ面積100m2・個人から購入・自己居住用）を取得した。この建物は耐震改修工事（耐震基準適合証明書取得済み）を実施している。建物の固定資産税評価額は600万円である。不動産取得税の軽減適用について正しいものはどれか。',opts:['昭和57年より前の新築であるため軽減措置なし','耐震基準適合証明書を取得した中古住宅は築年数にかかわらず1200万円控除の特例が適用される。600万円（評価額）－1200万円（控除額）=△600万円となり不動産取得税はかからない','1200万円控除は新築住宅のみ対象','耐震改修工事の費用は不動産取得税から控除できる'],ans:1,exp:'中古住宅の不動産取得税軽減（地方税法73条の14第2項）は、昭和57年1月1日以降新築の住宅（または耐震基準適合証明書取得済みの住宅）の場合に1200万円控除が適用されます。本問では耐震基準適合証明書を取得しているため（昭和55年新築で昭和57年以前ですが耐震証明書により要件を満たす）1200万円控除が適用されます。600万円（評価額）－1200万円=△600万円となり不動産取得税はゼロです。',"kaisetsu":{"topic": "不動産取得税：都道府県が課す地方税・相続は非課税・1回だけ課税", "basis": {"text": "不動産取得税は都道府県が課す地方税です（地方税法73条の2）。相続・法人の合併等による取得は非課税。一度の取得に一度だけ課税される（固定資産税と異なり毎年ではない）。標準税率は4%（住宅・土地は3%の軽減あり）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">不動産取得税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相続</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">非課税</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税の頻度</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取得時に1回のみ</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">標準税率</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4%（住宅・土地は3%）</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10969,unit:'r_ishi',level:3,field:'rights',text:'Aは知人Bから「自分の土地に古墳があり文化財に指定されている。売却は難しい」と聞かされた甲土地を購入した。しかし実際には文化財指定はなく、Bがそのような事実を誤って信じて伝えていた（Bに故意なし）。Aは文化財指定地としての利用価値を前提に購入を決めており、文化財指定がなければ購入しなかった。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['Bに故意がないためAは取り消せない','Aは重要な事実（文化財指定の有無）について錯誤（民法95条）に陥っており、その動機がBとの交渉を通じて法律行為の内容とされていた場合は錯誤取消しの主張ができる','Bに故意がなければいかなる場合も取り消せない','Aは動機の錯誤を主張できるが、AB間は錯誤の証明が困難'],ans:1,exp:'BがAに誤った情報を提供（故意なし）した場合、詐欺は成立しません。しかし文化財指定という動機がBとの交渉過程で法律行為の内容となっていた場合（動機が表示され相手方も認識していた場合）、Aは動機の錯誤（民法95条1項2号）を主張できます。Aに重大な過失がなければ取消しが認められます（民法95条3項）。',"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "意思表示の瑕疵には詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失の第三者は保護）・通謀虚偽表示（無効・善意の第三者は保護）があります。", "example": ""}, "reason": {"text": "動機の錯誤は動機が相手方に表示されて法律行為の内容となった場合に取消しが認められます（民法95条2項）。本問ではBとの交渉を通じて「文化財指定地としての価値」が売買の内容となっていた場合、取消しが認められる可能性があります。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "Bに故意がないためAは取り消せない", "reason": "錯誤（民法95条）は詐欺と異なり相手方の故意を要件としません。Bに故意がなくても錯誤取消しの要件を満たせば取り消せます。", "caution": "錯誤＝相手方の故意不要。詐欺＝相手方の故意必要。この違いは重要です。"}, {"label": "Bに故意がなければいかなる場合も取り消せない", "reason": "錯誤取消しは相手方の故意と無関係です。重要な錯誤があり表意者に重過失がなければ取り消せます。", "caution": ""}, {"label": "Aは動機の錯誤を主張できるが、AB間は錯誤の証明が困難", "reason": "証明の難易と錯誤の成否は別問題です。動機が表示されていれば錯誤取消しの主張自体はできます。", "caution": ""}], "summary": {"head": ["錯誤と詐欺の比較", "錯誤（95条）", "詐欺（96条）"], "rows": [["相手方の故意", "不要", "必要"], ["対象", "表意者の重要な誤解", "相手方による欺罔行為"], ["第三者保護", "判例未確立", "善意無過失の第三者保護（96条3項）"]]}}},
  {id:10970,unit:'r_dairi',level:3,field:'rights',text:'A社（会社）の代表取締役Bは、A社の代表者として甲土地をCに売却する契約を締結した。しかし、この売買はBが個人的に資金を調達するためにA社の財産を横領的に処分したものであり、Cはこの事情を知っていた（悪意）。A社はこの売買の効力を争っている。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['代表取締役Bには代表権があるため、どのような場合でもA社は契約に拘束される','代表取締役が会社の利益に反して自己または第三者の利益のために代表権を行使した場合（代理権の濫用・民法107条）、相手方Cがその事情を知っていた場合は無権代理とみなされ、A社は契約に拘束されない','会社の代表取締役の行為は常に会社を拘束する','CがBの意図を知っていても取引の安全を保護するため有効'],ans:1,exp:'民法107条（代理権の濫用）は法人の代表取締役にも適用されます（会社法354条と民法107条）。代表取締役BがA社の利益に反して個人の利益のために代表権を行使した場合、相手方Cがその事情を知っていた（悪意）または知ることができた（有過失）場合は、その行為は無権代理とみなされ、A社は契約に拘束されません。',"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護する制度です。", "example": ""}, "reason": {"text": "代理権の濫用（民法107条）は会社の代表取締役にも適用されます。代表取締役が会社の利益に反して代表権を行使した場合、相手方がその事情を知りまたは知ることができた場合は無権代理とみなされ、会社は契約に拘束されません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "代表取締役Bには代表権があるため、どのような場合でもA社は契約に拘束される", "reason": "代理権の濫用（民法107条）が適用される場合、相手方が悪意または有過失であれば会社は契約に拘束されません。「どのような場合でも」は誤りです。", "caution": ""}, {"label": "会社の代表取締役の行為は常に会社を拘束する", "reason": "代理権濫用（民法107条）の場合、相手方が悪意または有過失であれば会社は拘束されません。「常に」は誤りです。", "caution": ""}, {"label": "CがBの意図を知っていても取引の安全を保護するため有効", "reason": "Cが悪意（Bの不正な目的を知っていた）であれば取引の安全を保護する必要はなく、会社は契約に拘束されません（民法107条）。", "caution": ""}], "summary": {"head": ["状況", "A社への効果"], "rows": [["相手方Cが善意かつ無過失", "契約有効・A社に帰属"], ["相手方Cが悪意または有過失", "無権代理とみなし・A社は否定可（民法107条）"]]}}},
  {id:10971,unit:'r_tanpo',level:3,field:'rights',text:'AはB銀行から2000万円を借り入れ、A所有の甲建物に抵当権を設定した。その後、Aの友人CはAを助けるためにAの2000万円の債務全額を弁済した。CはAに対して求償権を有するが、BがAに対して有していた抵当権についても何らかの権利を取得したいと考えている。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['Cが代わりに弁済すると抵当権は消滅し、CはAへの求償権のみを有する','CはBへの弁済によりB銀行の抵当権をCに移転（代位取得）する弁済による代位（民法499条・500条）の権利を取得できる。Cは法定代位権者（保証人等に準じて）として甲建物の抵当権をBから引き継ぎ、AがCへの求償に応じない場合は抵当権を実行できる','第三者弁済は原則として無効','Cは連帯保証人でないため弁済による代位は認められない'],ans:1,exp:'弁済による代位（民法499条）により、AのためにBに弁済したCはBが有していた権利（抵当権を含む）を代位取得します。Cは法定代位（民法500条）または約定代位として甲建物の抵当権を行使できます。CはAに対する求償権を確保するために抵当権を実行することが可能です。',"kaisetsu":{"topic": "担保物権：抵当権は非占有担保・質権は占有担保・先取特権は法定担保", "basis": {"text": "抵当権は設定者が使用継続できる非占有担保物権です（民法369条）。質権は占有の移転が必要です。先取特権は法律上当然に成立する法定担保物権です。", "example": ""}, "reason": {"text": "第三者が債務者の代わりに弁済すると（第三者弁済・民法474条）、弁済者は債権者が有していた抵当権等を取得できます（弁済による代位・民法499条）。これにより弁済者は債務者に対して求償権を確保するための担保を持つことができます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">担保物権の比較</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">性質</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">占有</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抵当権</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・非占有</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要（設定者が使用）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">質権</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">約定担保・占有</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要（質権者が占有）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">先取特権</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">法定担保</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不要</text></svg>", "choices": [{"label": "Cが代わりに弁済すると抵当権は消滅しCはAへの求償権のみを有する", "reason": "弁済による代位（民法499条）により、CはB銀行が有していた抵当権をBから引き継ぐことができます（移転的代位）。消滅するのではなくCに移転します。", "caution": "弁済による代位＝抵当権がCに移転（消滅ではない）。"}, {"label": "第三者弁済は原則として無効", "reason": "第三者弁済は原則として有効です（民法474条1項）。正当な利益を有しない第三者は債務者の意思に反して弁済できない場合がありますが（同条2項）、本問のCは正当な利益（求償権確保）のために弁済しています。", "caution": ""}, {"label": "Cは連帯保証人でないため弁済による代位は認められない", "reason": "弁済による代位は保証人に限らず第三者弁済をした者一般に認められます（民法499条）。連帯保証人である必要はありません。", "caution": ""}], "summary": {"head": ["弁済による代位（民法499条）", "内容"], "rows": [["意味", "弁済した者が債権者の権利（抵当権等）を取得"], ["目的", "求償権を確保するための担保"], ["法定代位権者", "保証人・物上保証人・第三取得者等（民法500条）"], ["任意代位権者", "その他の者（債権者の承諾が必要）"]]}}},
  {id:10972,unit:'l_37jo',level:3,field:'law',text:'宅建業者A（媒介）が関与した売買契約において、37条書面の記載事項について確認している。次のうち37条書面への記載が任意的記載事項（定めがある場合に記載）に当たるものとして宅建業法の規定によれば正しいものはどれか。',opts:['代金の額','引渡しの時期','契約の解除に関する定め（違約金・解除条件等）','移転登記申請の時期'],ans:2,exp:'37条書面の必要的記載事項（宅建業法37条1項）：①当事者の氏名・住所②物件の表示③代金・交換差金の額・支払時期・方法④物件の引渡し時期⑤移転登記申請の時期。任意的記載事項（定めがある場合）：契約の解除に関する定め・損害賠償額の予定・天災等の不可抗力による損害の負担・融資（ローン）のあっせんに関する定め・住宅性能評価を受けた旨等（同法37条1項各号）。',"kaisetsu":{"topic": "37条書面：全取引で交付・記名（押印不要）・移転登記申請時期は必要的記載事項", "basis": {"text": "37条書面は売買・交換・賃貸借の全取引で契約の双方当事者に交付が義務（宅建業法37条）。引渡し時期・移転登記申請時期は必要的記載事項。2021年改正で押印は不要になり記名のみで足ります。", "example": ""}, "reason": {"text": "37条書面の任意的記載事項（定めがある場合に記載）には契約の解除に関する定め（違約金・解除条件等）が含まれます（宅建業法37条1項7号）。代金の額・引渡し時期・移転登記申請時期はすべて必要的記載事項です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付義務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全取引・双方当事者</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡時期・移転登記申請時期等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要）</text></svg>", "choices": [{"label": "代金の額", "reason": "代金の額は必要的記載事項です（宅建業法37条1項2号）。任意的ではありません。", "caution": ""}, {"label": "引渡しの時期", "reason": "引渡しの時期は必要的記載事項です（宅建業法37条1項4号）。任意的ではありません。", "caution": ""}, {"label": "移転登記申請の時期", "reason": "移転登記申請の時期は必要的記載事項です（宅建業法37条1項5号）。任意的ではありません。", "caution": ""}], "summary": {"head": ["37条書面の記載事項区分", "必要的vs任意的"], "rows": [["当事者氏名・住所", "必要的"], ["代金・支払時期・方法", "必要的"], ["引渡し時期", "必要的"], ["移転登記申請時期", "必要的"], ["契約解除の定め", "任意的（宅建業法37条1項7号）"], ["ローン特約・危険負担・瑕疵担保", "任意的"]]}}},
  {id:10973,unit:'r_sorin',level:3,field:'rights',text:'AはV市内の土地を所有しているが、Aの土地は公道に面しておらず、Bの所有地を通らなければ公道に出ることができない（袋地）。AはBに対して通行を求めたが、Bは「通行させる代わりに月額3万円の通行料を払え」と要求している。Aはこの金額が高すぎると考えている。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['Bが要求する通行料に合意しなければ、Aは一切通行できない','AはBの土地に対して囲繞地通行権（民法210条）を有し、Bの同意がなくても通行できる。通行料（償金）は当事者の合意がなければ裁判所が定める。Bが要求する月額3万円が法外であれば、Aは裁判所に相当額の決定を求めることができる','囲繞地通行権は登記しなければ行使できない','月額3万円に合意しなければ通行は認められない'],ans:1,exp:'囲繞地通行権（民法210条）は袋地所有者Aに法律上当然に認められる権利であり、Bの同意・登記は不要です。通行の対価（償金）については民法212条で定めがあり、当事者間で合意できない場合は裁判所が相当額を決定します。Bの要求する月額3万円が不相当であれば、Aは裁判所に適正な償金の確認を求めることができます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "囲繞地通行権（民法210条）は法律上当然の権利であり、囲繞地所有者の同意なく通行できます。償金（通行料）の額は当事者の合意で決まりますが、合意できない場合は裁判所が相当額を定めます（民法212条）。法外な通行料の要求には従う必要はありません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "Bが要求する通行料に合意しなければAは一切通行できない", "reason": "囲繞地通行権は法律上当然の権利であり（民法210条1項）、償金の合意がなくても通行できます。裁判所に相当額の決定を求めることができます（民法212条）。", "caution": "囲繞地通行権：通行料に合意不要でも通行可。裁判所に相当額の決定を求められる。"}, {"label": "囲繞地通行権は登記しなければ行使できない", "reason": "囲繞地通行権は法律上当然の権利であり登記は不要です（民法210条1項）。", "caution": ""}, {"label": "月額3万円に合意しなければ通行は認められない", "reason": "償金の合意ができない場合は裁判所が相当額を定めます（民法212条）。法外な通行料に合意しなくても通行できます。", "caution": ""}], "summary": {"head": ["囲繞地通行権と償金（民法212条）", "内容"], "rows": [["通行の可否", "法律上当然の権利（合意不要）"], ["償金の決定", "当事者の合意、合意できなければ裁判所が決定"], ["通行の範囲", "損害が最も少ない方法・場所（民法211条1項）"], ["分割袋地", "分割した土地のみ通行可・無償（民法213条）"]]}}},
  {id:10974,unit:'k_kukaku',level:3,field:'limit',text:'W市が施行者となって行われている土地区画整理事業の施行区域内において、宅建業者AはBから宅地の売買を依頼された。この宅地は仮換地の指定を受けており、換地処分はまだ完了していない。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['区画整理事業施行中の土地の売買は禁止されている','区画整理事業施行中の宅地の売買は可能であるが、宅建業者は重要事項説明において土地区画整理事業の施行中である旨・仮換地の指定の有無・換地処分の未了等を説明しなければならない','仮換地の指定がある場合は登記された従前地の情報のみを重要事項説明書に記載すれば足りる','換地処分が完了するまで不動産の登記移転ができないため、売買契約は締結できない'],ans:1,exp:'土地区画整理事業施行中の宅地売買は可能ですが、宅建業者は重要事項説明として土地区画整理法に基づく事業の施行に関する事項（施行中である旨・仮換地の位置・面積・清算金の見通し等）を説明しなければなりません（宅建業法35条1項14号・施行令3条1項14号）。買主にとって将来の換地・清算金は重要事項です。',"kaisetsu":{"topic": "土地区画整理法：換地は公告翌日確定・仮換地は従前地使用不可・組合は2/3以上", "basis": {"text": "換地処分の公告翌日から換地が確定します（土地区画整理法104条）。仮換地の指定後は従前地を使用できなくなります（同法99条）。組合設立には土地所有者・借地権者の各2/3以上の同意が必要です。", "example": ""}, "reason": {"text": "区画整理事業施行中の宅地の売買は可能ですが、宅建業者は重要事項説明において土地区画整理事業の施行区域内である旨等を説明しなければなりません（宅建業法35条1項6号）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">土地区画整理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">換地の確定</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">公告の翌日</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">仮換地指定後</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">従前地は使用不可（所有権は残る）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">組合設立</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各2/3以上の同意</text></svg>", "choices": [{"label": "区画整理事業施行中の土地の売買は禁止されている", "reason": "施行中でも土地の売買は可能です（土地区画整理法76条等）。", "caution": "区画整理施行中の土地：売買可能。重要事項説明に事業施行区域内の旨を記載する義務あり。"}, {"label": "仮換地の指定がある場合は登記された従前地の情報のみを重要事項説明書に記載すれば足りる", "reason": "仮換地の情報（位置・地積等）も説明が必要です（宅建業法35条1項6号）。", "caution": ""}, {"label": "換地処分が完了するまで不動産の登記移転ができないため売買契約は締結できない", "reason": "売買契約は締結できます（土地区画整理法106条）。", "caution": ""}], "summary": {"head": ["区画整理施行区域内の売買と重要事項説明", "内容"], "rows": [["売買", "可能"], ["重要事項説明", "事業施行区域内の旨を記載"], ["仮換地がある場合", "仮換地の位置・地積等も記載"]]}}},
  {id:10975,unit:'t_kotei',level:3,field:'tax',text:'Aは相続によりX市内の土地（固定資産税評価額4000万円）を取得した。この土地の固定資産税・都市計画税について確認している。基準年度は2024年度であり、土地の評価は3年ごとに見直される（評価替え）。2025年度・2026年度の固定資産税評価額・課税について正しいものはどれか。',opts:['毎年新しく固定資産税評価額が算定される','固定資産税の評価は原則3年ごとの基準年度に評価替えが行われ、次の評価替えまでの3年間（2024年度・2025年度・2026年度）は原則として同じ評価額が適用される','2025年度・2026年度は評価額が自動的に10%ずつ上昇する','地価が大幅に下落した場合でも固定資産税評価額は変わらない'],ans:1,exp:'固定資産税の評価替えは3年ごとの基準年度（2024年度・2027年度・2030年度…）に行われます（地方税法341条の2）。基準年度に評価替えが行われた後、次の評価替えまでの3年間は原則として同じ評価額（基準年度の価格）が据え置かれます。ただし地価の下落等により著しく評価が不適当となった場合は修正が行われることがあります（地方税法349条1項ただし書）。',"kaisetsu":{"topic": "固定資産税：市町村が課す地方税・賦課期日は1月1日・評価替えは3年ごと", "basis": {"text": "固定資産税は市町村（東京23区は都）が課す地方税です（地方税法343条）。賦課期日は毎年1月1日。評価替えは3年ごと（基準年度）。住宅用地の特例：200㎡以下は課税標準1/6、超過部分は1/3。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">固定資産税のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税主体</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市町村（地方税）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賦課期日</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">毎年1月1日</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">評価替え</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年ごと</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">住宅用地（200㎡以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税標準1/6</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10976,unit:'r_jiko',level:3,field:'rights',text:'AはB社との間で「B社のためにX市の土地を探す」旨の不動産調査の委任契約を締結した。AはX市内で適切な土地を見つけ、B社にその旨を報告したが、B社は「もう必要ない」として委任契約を一方的に解除した。Aはすでに調査費用10万円を支出済みであった。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['委任契約はいつでも解除できるため、B社は何の責任も負わない','委任契約は各当事者がいつでも解除できる（民法651条1項）。ただしやむを得ない事由がない場合に相手方に不利な時期に解除したときは、相手方に損害賠償を要する（同条2項）。Aはすでに費用を支出しているため損害賠償の余地がある','委任契約は解除できない','Aは委任契約の解除に同意しなければB社は解除できない'],ans:1,exp:'委任契約は各当事者がいつでも解除できます（民法651条1項）。ただし相手方に不利な時期に解除した場合や、やむを得ない事由がなく解除した場合は、解除した当事者は相手方に生じた損害を賠償しなければなりません（民法651条2項）。B社がやむを得ない事由なく不利な時期に解除したのであれば、AはB社に対して調査費用等の損害賠償を請求できます。',"kaisetsu":{"topic": "消滅時効：知った時から5年または行使可能時から10年", "basis": {"text": "一般の債権の消滅時効は「権利行使できると知った時から5年」または「権利行使できる時から10年」のいずれか早い方で完成します（民法166条1項）。時効は援用して初めて効力が発生します（民法145条）。", "example": ""}, "reason": {"text": "委任契約は各当事者がいつでも解除できます（民法651条1項）。ただし相手方に不利な時期に解除した場合ややむを得ない事由がない場合には損害賠償義務が生じます（同条2項）。受任者がすでに費用を支出している場合はその費用が損害になりえます。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">時効期間</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人の生命・身体への損害</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年または20年</text></svg>", "choices": [{"label": "委任契約はいつでも解除できるため、B社は何の責任も負わない", "reason": "委任契約はいつでも解除できますが（民法651条1項）、相手方に不利な時期の解除には損害賠償義務が生じます（同条2項）。「何の責任も負わない」は誤りです。", "caution": "委任はいつでも解除可だが、不利な時期の解除には損害賠償あり。"}, {"label": "委任契約は解除できない", "reason": "委任契約は各当事者がいつでも解除できます（民法651条1項）。「解除できない」は誤りです。", "caution": ""}, {"label": "Aは委任契約の解除に同意しなければB社は解除できない", "reason": "委任の解除に相手方の同意は不要です（民法651条1項）。一方的に解除できます。", "caution": ""}], "summary": {"head": ["委任の解除", "内容"], "rows": [["解除の自由", "各当事者がいつでも解除可（民法651条1項）"], ["損害賠償義務", "やむを得ない事由なく不利な時期に解除した場合（民法651条2項）"], ["受任者の費用償還", "既支出費用の請求可（民法650条1項）"]]}}},
  {id:10977,unit:'l_hosho',level:3,field:'law',text:'宅建業者A（保証協会の社員）は、B（買主・宅建業者でない）との間でマンション（代金5000万円・未完成）の売買契約を締結した。Aは手付金500万円（代金の10%）を受け取った。未完成物件の手付金の保全措置として正しいものはどれか。',opts:['500万円（10%）は完成物件の保全措置基準（10%超）に達しているので、保全措置不要','未完成物件の保全措置が必要となる基準は代金の5%超または1000万円超。500万円（5000万円の10%）は5%（250万円）を超えているため保全措置が必要。Aは手付金を受け取る前に保全措置を講じなければならない','保証協会の社員であれば手付金の保全措置は不要','500万円以下の手付金は常に保全措置不要'],ans:1,exp:'未完成物件の手付金等の保全措置（宅建業法41条1項）が必要となる基準は代金の5%超または1000万円超。5000万円×5%=250万円。500万円は250万円超であるため保全措置が必要です。保証協会の社員であることは保全措置の義務に影響しません。手付金受領前に保全措置（保証保険・銀行保証等）を講じなければなりません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "宅建業者が自ら売主として未完成物件の手付金等を受領する場合、代金の5%超または1000万円超の場合は保全措置が必要です（宅建業法41条1項）。500万円は代金（5000万円）の10%で5%（250万円）を超えているため保全措置が必要です。保証協会の社員であっても手付金の保全措置義務は免除されません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "500万円（10%）は完成物件の保全措置基準（10%超）に達していないので保全措置不要", "reason": "未完成物件の基準は5%超です（宅建業法41条1項）。500万円は5000万円の10%で5%超であるため保全措置が必要です。完成物件の基準と混同しないようにしましょう。", "caution": "未完成：5%超→保全措置必要。500万円は5000万円の10%＞5%→必要。"}, {"label": "保証協会の社員であれば手付金の保全措置は不要", "reason": "保証協会加入は営業保証金の供託義務を免除しますが（宅建業法64条の15）、手付金等の保全措置義務は別途適用されます（宅建業法41条1項）。", "caution": "保証協会加入→営業保証金免除。ただし手付金保全措置義務は別途あり。"}, {"label": "500万円以下の手付金は常に保全措置不要", "reason": "500万円という基準はありません（宅建業法41条1項）。代金の5%超または1000万円超が基準です。", "caution": ""}], "summary": {"head": ["未完成物件の手付金保全措置（設問）", "内容"], "rows": [["代金", "5000万円"], ["5%の額", "250万円"], ["受領した手付金", "500万円"], ["5%超か", "500万円＞250万円（5%）→超えている"], ["保全措置", "必要（受領前に措置を講じなければならない）"]]}}},
  {id:10978,unit:'k_toshi',level:3,field:'limit',text:'AはY市（都市計画区域内・市街化区域・第一種住居地域）内の土地（面積600m2）を購入し、分譲マンション（12戸・各戸専有面積50m2）を建築しようとしている。この開発行為について都市計画法の規定によれば正しいものはどれか。',opts:['市街化区域内の開発行為は面積にかかわらず許可不要','分譲マンションの建設は「建築物の建築」を目的とする開発行為に当たり、市街化区域内で1000m2以上の場合は開発許可が必要。600m2は1000m2未満のため、市街化区域内では開発許可は不要','マンション建設には必ず開発許可が必要','600m2の開発行為は許可不要で届出のみでよい'],ans:1,exp:'都市計画法29条1項本文・同法施行令19条：市街化区域での開発行為は1000m2未満の場合は開発許可不要。600m2の開発行為は1000m2未満であるため市街化区域内では開発許可は不要です（ただし特定工作物等の開発は別途検討が必要）。なお三大都市圏の一部特定市街化区域では500m2未満等基準が異なる場合があります。',"kaisetsu":{"topic": "都市計画法：市街化区域・調整区域・用途地域・開発許可", "basis": {"text": "市街化区域は既成市街地と10年以内に市街化を図る区域（都市計画法7条）。市街化区域での1,000㎡以上の開発は許可が必要（同法29条）。農林漁業用建物は市街化調整区域でも許可不要（同法29条1項2号）。", "example": ""}, "reason": {"text": "市街化区域内での開発行為は1000㎡以上の場合に開発許可が必要です（都市計画法29条1項・施行令19条）。設問の600㎡は1000㎡未満のため開発許可は不要です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">都市計画法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">既成市街地+10年以内に市街化する区域</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">市街化区域の開発許可基準</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1,000㎡以上</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農林漁業用建物（調整区域）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">開発許可不要</text></svg>", "choices": [{"label": "市街化区域内の開発行為は面積にかかわらず許可不要", "reason": "1000㎡以上では許可が必要です（都市計画法29条1項・施行令19条）。「面積にかかわらず不要」は誤りです。", "caution": ""}, {"label": "マンション建設には必ず開発許可が必要", "reason": "市街化区域内の1000㎡未満の開発行為（マンション建設を含む）は開発許可不要です（都市計画法29条1項・施行令19条）。「必ず必要」は誤りです。", "caution": "市街化区域：1000㎡未満の開発行為→許可不要（都市計画法29条1項・施行令19条）。"}, {"label": "600m2の開発行為は許可不要で届出のみでよい", "reason": "600㎡は許可不要ですが、届出義務もありません（都市計画法29条1項）。「届出のみ」という手続きはありません。", "caution": ""}], "summary": {"head": ["設問の開発許可判断", "内容"], "rows": [["区域", "市街化区域"], ["面積", "600㎡"], ["基準", "1000㎡未満"], ["結論", "開発許可不要（届出も不要）"]]}}},
  {id:10979,unit:'r_kukku',level:3,field:'rights',text:'分譲マンションの管理組合がマンションの建替えを検討している。区分所有者数は30名（議決権も30）である。建替え決議を成立させるために必要な要件として区分所有法の規定によれば正しいものはどれか。',opts:['区分所有者の過半数（16名以上）の賛成で建替えを決議できる','建替え決議は区分所有者及び議決権の各5分の4以上の賛成が必要（区分所有法62条1項）。30名の場合は24名以上（5/4×30=24）の賛成が必要','区分所有者全員の同意が必要','建替えには区分所有者の3/4以上の賛成で足りる'],ans:1,exp:'建替え決議は区分所有者の数及び議決権の各5分の4以上の多数による集会決議が必要です（区分所有法62条1項）。30名×4/5=24名以上の賛成が必要です。なお建替えの決議には、少なくとも建替えについて回答を求める催告・説明会の開催等の手続きが必要であり（同法62条2項以下）、決議成立後も反対区分所有者への売渡請求等の手続きが続きます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "建替え決議は区分所有者および議決権の各5分の4以上の多数が必要です（区分所有法62条1項）。30名の場合は24名以上の賛成が必要です（5分の4×30=24）。建替えは区分所有者の財産権に重大な影響を及ぼすため最も高い決議要件です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "区分所有者の過半数（16名以上）の賛成で建替えを決議できる", "reason": "建替え決議には4/5以上（24名以上）が必要です（区分所有法62条1項）。過半数では足りません。", "caution": "建替え決議＝4/5以上（区分所有法62条1項）。過半数では不可。"}, {"label": "区分所有者全員の同意が必要", "reason": "全員同意は不要です。4/5以上の多数決で足ります（区分所有法62条1項）。", "caution": ""}, {"label": "建替えには区分所有者の3/4以上の賛成で足りる", "reason": "3/4以上は重大変更・規約変更等の要件です（区分所有法17条・31条）。建替えは4/5以上が必要です（同法62条1項）。", "caution": ""}], "summary": {"head": ["建替え決議（区分所有法62条）", "内容"], "rows": [["要件", "4/5以上（5分の4・区分所有者および議決権）"], ["30名の場合", "24名以上の賛成が必要"], ["不参加者", "参加者から時価での買取請求を受ける（区分所有法63条）"], ["マンション建替え", "マンション建替え円滑化法による特別制度あり"]]}}},
  {id:10980,unit:'t_toroku',level:3,field:'tax',text:'AはB銀行からリノベーション資金として500万円を借り入れ、A所有の甲住宅（床面積80m2・自己居住用）に抵当権を設定した。この抵当権設定登記の登録免許税として正しいものはどれか。',opts:['500万円×0.4%=2万円（本則税率）','500万円×0.1%=0.5万円（住宅ローン軽減税率）が適用される可能性がある','抵当権設定登記に登録免許税はかからない','500万円×2%=10万円'],ans:0,exp:'抵当権設定登記の登録免許税：課税標準は「債権金額」500万円。本則税率0.4%（登録免許税法別表1）。軽減税率（0.1%）は住宅取得に係る住宅ローン（新築・既存住宅の取得資金）の抵当権設定登記に適用されます（租税特別措置法75条）。本問はリノベーション資金（住宅取得のためのローンではなく改修資金）であるため、軽減税率の適用要件（住宅取得に係るもの）を満たさない可能性があり、本則税率0.4%が適用されます。500万円×0.4%＝2万円。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10981,unit:'r_fuhoko',level:3,field:'rights',text:'AはBと共同でCを殴打し、Cに全治3か月の傷害を負わせた。Cの損害は治療費100万円・休業損害200万円・慰謝料100万円の計400万円である。AとBは共同不法行為（民法719条）の責任を負う。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['AとBはそれぞれ損害額の半分（200万円ずつ）を負担すれば足りる','AとBは連帯して400万円の損害賠償責任を負う（不真正連帯債務）。CはAに対しても、Bに対しても400万円全額を請求できる','共同不法行為では各自の行為の寄与度に応じた責任しか負わない','AがCに400万円を支払った場合、AはBに対して求償できない'],ans:1,exp:'共同不法行為（民法719条1項）では、各行為者が連帯して損害を賠償する責任を負います（不真正連帯）。CはAに対しても、Bに対しても400万円全額を請求できます。AがCに400万円全額を支払った場合、AはBに対して各自の寄与度（通常は過失割合等）に応じた求償（民法442条類推）ができます。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "共同不法行為者は連帯して損害の全額について賠償責任を負います（民法719条1項）。被害者はAに対してもBに対しても400万円全額を請求できます（不真正連帯債務）。一方が全額支払った場合、他方への求償が可能です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "AとBはそれぞれ損害額の半分（200万円ずつ）を負担すれば足りる", "reason": "共同不法行為者は連帯して全額の責任を負います（民法719条1項）。半分ずつの分割責任ではありません。", "caution": "共同不法行為＝連帯責任（分割ではない）。"}, {"label": "各自の行為の寄与度に応じた責任しか負わない", "reason": "外部的には連帯して全額の責任を負います（民法719条1項）。寄与度は内部的な求償の際に問題になります。", "caution": ""}, {"label": "AがCに400万円を支払った場合AはBに対して求償できない", "reason": "AはBに対して過失割合等に応じた求償ができます（民法719条1項・求償権）。「できない」は誤りです。", "caution": ""}], "summary": {"head": ["共同不法行為の責任", "内容"], "rows": [["外部的責任", "各自が全額について連帯責任（民法719条1項）"], ["被害者の選択", "AまたはBに400万円全額を請求可"], ["内部的求償", "寄与度・過失割合に応じてAとBの間で求償"], ["不真正連帯", "一方への請求が他方に及ぶ場合が限定的"]]}}},
  {id:10982,unit:'r_ishi',level:3,field:'rights',text:'AはBとの間で甲不動産（時価2000万円）について売買契約を締結した。しかしAは契約の内容を著しく誤解しており（1000万円の売却と思っていたが、実際は2000万円での売却だった）、この誤解は契約書の内容（2000万円と明記）を読まなかったというAの重大な過失によるものであった。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['Aは常に錯誤取消しを主張できる','錯誤（民法95条）に重大な過失（重過失）がある場合、原則として取消しを主張できない（民法95条3項）。ただし相手方Bが錯誤について悪意または重過失だった場合や、相手方も同一の錯誤に陥っていた場合は例外的に取消しが認められる','重過失があっても錯誤取消しは常に認められる','契約書に明記されていた以上、錯誤そのものが認められない'],ans:1,exp:'錯誤取消し（民法95条）は表意者（A）に重大な過失（重過失）がある場合は原則として主張できません（民法95条3項）。ただし例外として①相手方Bが錯誤の事実を知りまたは重大な過失によって知らなかった場合②相手方Bが同一の錯誤に陥っていた場合は取消しが認められます（民法95条3項1号・2号）。',"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "意思表示の瑕疵には詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失の第三者は保護）・通謀虚偽表示（無効・善意の第三者は保護）があります。", "example": ""}, "reason": {"text": "表意者に重大な過失がある場合は原則として錯誤取消しを主張できません（民法95条3項）。不注意な者を保護すると取引の安全が損なわれるためです。例外として相手方が悪意・重過失の場合や同一の錯誤の場合は取消しが認められます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "Aは常に錯誤取消しを主張できる", "reason": "表意者に重大な過失がある場合は原則として錯誤取消しを主張できません（民法95条3項）。常に主張できるわけではありません。", "caution": "重過失＝原則取消し不可。これは錯誤取消しの重要な制限です。"}, {"label": "重過失があっても錯誤取消しは常に認められる", "reason": "重大な過失がある場合は原則として取消しができません（民法95条3項）。例外的に認められるのは相手方が悪意・重過失の場合等に限られます。", "caution": ""}, {"label": "契約書に明記されていた以上、錯誤そのものが認められない", "reason": "契約書の内容を読まなかったことはAの重過失ですが、錯誤の存在自体は認められます。重過失があるため取消しができないという問題です。", "caution": "「錯誤なし」ではなく「重過失があるため取消し不可」というのが正しい理解です。"}], "summary": {"head": ["表意者の過失", "取消しの可否", "例外"], "rows": [["過失なし", "可", "—"], ["軽過失", "可", "—"], ["重大な過失", "原則不可", "相手方が悪意・重過失の場合、同一錯誤の場合は可"]]}}},
  {id:10983,unit:'r_dairi',level:3,field:'rights',text:'Aは死亡する前日に、「BをAの代理人として甲土地の売却権限を授与する」旨の委任状を作成した。翌日Aが死亡した後、BはA名義でCに甲土地を売却する契約を締結した。AにはDという相続人がいる。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['Aが死亡したため代理権は消滅し、BによるCとの契約は無権代理となる。Cは追認（Dが行う）がなければ契約の効力を主張できない','Aの死亡後のBの行為は当然に有効で、Dが甲土地の引渡し義務を負う','Bが代理人として行動していれば、Aの死亡後も代理権は消滅しない','Aが委任状を作成した翌日に死亡したため遺言として扱われる'],ans:0,exp:'委任による代理権は本人の死亡によって消滅します（民法111条1項1号）。Aが死亡した後にBが行ったCとの売買契約は無権代理行為となります（民法113条1項）。Dが追認（民法116条・113条2項）すれば契約は有効となりますが、追認しない場合はCはDに甲土地の引渡しを求めることができません。Cは代わりにBに無権代理人としての責任（民法117条）を追及できます。',"kaisetsu":{"topic": "代理：代理行為の効果は本人に帰属・表見代理・無権代理", "basis": {"text": "代理人が代理権の範囲内で行った行為の効果は本人に帰属します（民法99条）。無権代理は本人の追認で有効になります。表見代理は外観を信頼した相手方を保護する制度です。", "example": ""}, "reason": {"text": "代理権は本人の死亡により消滅します（民法111条1項1号）。したがって本人死亡後に代理人が行った行為は無権代理となります。相手方は本人の相続人による追認がなければ契約の効力を主張できません（民法113条）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">代理のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">場面</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">結論</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代理行為</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">本人に効果帰属</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無権代理</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">追認で有効</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">表見代理</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正当理由ある相手方を保護</text></svg>", "choices": [{"label": "Aの死亡後のBの行為は当然に有効で、Dが甲土地の引渡し義務を負う", "reason": "Aの死亡後のBの代理行為は無権代理です（民法111条1項1号・113条）。DはAから相続した地位に基づき追認または拒絶を選択できます。", "caution": "死亡後の代理行為は無権代理。"}, {"label": "Bが代理人として行動していれば、Aの死亡後も代理権は消滅しない", "reason": "本人の死亡は代理権の消滅事由です（民法111条1項1号）。代理人として行動中であっても本人死亡により代理権は消滅します。", "caution": ""}, {"label": "Aが委任状を作成した翌日に死亡したため遺言として扱われる", "reason": "委任状は遺言ではありません。遺言は民法960条以下の厳格な要件が必要です。", "caution": ""}], "summary": {"head": ["場面", "処理"], "rows": [["死亡前の代理行為", "有効（効果は相続人Dに承継）"], ["死亡後の代理行為", "無権代理（民法111条1項1号・113条）"], ["相続人Dの選択", "追認→有効化、拒絶→無権代理のまま"]]}}},
  {id:10984,unit:'r_saikensoron',level:3,field:'rights',text:'AはBに対して1000万円の金銭消費貸借契約を締結した（弁済期：1年後）。BはAに「友人CがBのために保証人になってくれると言っている」と伝え、Aはこれを信じてCが保証人だと思っていた。実際にはCは保証人になっておらず、保証契約書も作成されていなかった。弁済期にBが返済できなかった場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['CはBが「保証人になる」と言ったのだから保証債務を負う','保証契約は書面でしなければその効力が生じない（民法446条2項）。Cが保証契約書に署名・捺印していなければ保証契約は成立せず、CはAに対して保証債務を負わない','口頭での保証約束でも有効','AはBのCへの言及を信じて貸したのだからCに責任がある'],ans:1,exp:'保証契約は書面（または電磁的記録）によってしなければその効力を生じません（民法446条2項）。Cが保証契約書に署名・捺印等をしていない以上、口頭での約束のみでは保証契約は成立せず、CはAに対して保証債務を負いません。AはBに対してのみ返済を求めることができます。',"kaisetsu":{"topic": "債権総論：保証・連帯債務・債権譲渡・相殺", "basis": {"text": "保証契約は書面が必要です（民法446条2項）。連帯保証人には催告・検索の抗弁権がありません（民法454条）。債権譲渡の第三者対抗要件は確定日付ある証書による通知または承諾です（民法467条2項）。", "example": ""}, "reason": {"text": "保証契約は書面または電磁的記録によらなければ効力が生じません（民法446条2項）。Cが保証契約書に署名・捺印していなければ保証契約は成立せず、CはAに対して保証債務を負いません。Bの言葉だけでは保証契約は成立しません。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">債権総論のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">保証契約</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">書面必要（口頭不可）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">連帯保証</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">抗弁権なし</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">債権譲渡の第三者対抗</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">確定日付ある証書</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相殺の要件</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">双方が同種の債権</text></svg>", "choices": [{"label": "CはBが保証人になると言ったのだから保証債務を負う", "reason": "保証契約はBではなくAとCの間で書面で締結される必要があります（民法446条2項）。Bの言葉だけでCの保証債務は成立しません。", "caution": "保証契約の当事者：債権者（A）と保証人（C）。主債務者（B）の言葉だけでは成立しない。"}, {"label": "口頭での保証約束でも有効", "reason": "保証契約は書面または電磁的記録が必要です（民法446条2項）。口頭のみでは無効です。", "caution": "保証＝書面必要（民法446条2項）。口頭では無効。"}, {"label": "AはBのCへの言及を信じて貸したのだからCに責任がある", "reason": "AがBの言葉を信じても、保証契約の書面がなければCは保証責任を負いません（民法446条2項）。", "caution": ""}], "summary": {"head": ["保証契約の成立（民法446条）", "内容"], "rows": [["当事者", "債権者（A）と保証人（C）の合意"], ["方式", "書面または電磁的記録が必要（同条2項）"], ["口頭", "無効"], ["主債務者の言葉", "保証契約を成立させる効力なし"]]}}},
  {id:10985,unit:'l_takkenshi',level:3,field:'law',text:'宅建士Aは、自らが勤務する宅建業者B社の依頼を受け、B社の取引先C社（宅建業者）の役員に対して重要事項の説明を行った。説明の際、AはC社の役員から「宅建士証を見せてくれ」と求められたが、Aはその日たまたま宅建士証を携帯しておらず、提示できなかった。また、AはB社の別の案件でも、相手方から請求されたにもかかわらず宅建士証を提示しなかった。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['相手方がC社（宅建業者）の役員であれば宅建士証の提示義務はない','宅建士は重要事項説明の際は相手方から請求がなくても宅建士証を提示しなければならない（宅建業法35条4項）。また相手方から請求を受けた場合には業務上の全ての場面で宅建士証を提示しなければならない（宅建業法22条の4）。Aは複数の場面で義務に違反しており、指示処分等の対象となる可能性がある','宅建士証の提示は任意的なもので、不提示に罰則はない','C社の役員への説明は重要事項説明書の交付のみで足り、説明・提示は不要'],ans:1,exp:'宅建士は取引の関係者から請求があった場合には業務上の全ての場面で宅建士証を提示しなければなりません（宅建業法22条の4）。また重要事項説明時には請求がなくても提示義務があります（同法35条4項）。相手方が宅建業者であっても提示義務は免除されません。AはC社への説明時・別案件での請求時ともに義務違反であり、指示処分等の対象となります。',"kaisetsu":{"topic": "専任の宅建士：5人に1人以上・兼任不可・不足時は2週間以内に補充", "basis": {"text": "事務所には業務従事者5人に1人以上の専任宅建士が必要です（宅建業法31条の3）。専任宅建士は1社専属で複数業者の兼任は不可。不足時は2週間以内に補充が必要です。", "example": ""}, "reason": {"text": "宅建士は重要事項説明の際は請求なくても宅建士証を提示しなければならず（宅建業法35条4項）、業務上相手方から請求があれば常に提示しなければなりません（同法22条の4）。宅建業者間の取引でも提示義務は変わりません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">専任宅建士のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">設置基準</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5人に1人以上（主従同じ）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">兼任</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不可（1社専属）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">不足補充</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2週間以内</text></svg>", "choices": [{"label": "相手方がC社（宅建業者）の役員であれば宅建士証の提示義務はない", "reason": "相手方が宅建業者であっても提示義務は変わりません（宅建業法35条4項）。宅建業者間の取引で省略できるのは「説明」のみです（同法35条6項）。", "caution": "宅建業者間でも提示義務は変わらない（宅建業法35条4項）。"}, {"label": "宅建士証の提示は任意的なもので不提示に罰則はない", "reason": "提示義務は法定されており（宅建業法35条4項・22条の4）、違反には行政上の処分等が科されます。「任意・罰則なし」は誤りです。", "caution": ""}, {"label": "C社の役員への説明は重要事項説明書の交付のみで足り説明・提示は不要", "reason": "宅建業者間取引では説明は省略できますが（宅建業法35条6項）、書面交付は必要です（同条同項）。また提示義務（同条4項）の省略規定はありません。", "caution": ""}], "summary": {"head": ["宅建士証の提示義務", "場面", "根拠"], "rows": [["重要事項説明時", "請求なくても提示必須", "宅建業法35条4項"], ["業務中の請求", "請求されたら提示必須", "宅建業法22条の4"], ["業務中の携帯", "常時携帯義務", "宅建業法22条の3"], ["宅建業者間", "説明省略可・提示義務は変わらず", "宅建業法35条4項・6項"]]}}},
  {id:10986,unit:'k_kenchiku',level:3,field:'limit',text:'AはZ市（第一種低層住居専用地域・建ぺい率50%・容積率100%・絶対高さ制限10m）内に土地（150m2）を所有し、木造2階建て住宅（建築面積60m2・延べ面積100m2・最高高さ8m）を計画している。前面道路幅員は6mである。この計画の建ぺい率・容積率・高さ制限の適合性について建築基準法の規定によれば正しいものはどれか。',opts:['建ぺい率60/150=40%<50%OK。容積率100/150=66.7%<100%OK。道路幅員6m×4/10=240%>100%なので容積率は指定の100%が適用。高さ8m<10mでOK。全て適合','容積率は道路幅員による制限で60%になる','建ぺい率は60%を超えているため違反','高さ8mは制限を超えている'],ans:0,exp:'建ぺい率：60m2÷150m2=40%＜50%→適法。容積率：前面道路6m×4/10=240%と指定容積率100%を比較し小さい方（100%）を適用。100m2÷150m2=66.7%＜100%→適法。高さ：8m＜絶対高さ制限10m→適法。全ての制限に適合しています。',"kaisetsu":{"topic": "建築基準法：建ぺい率・容積率・道路斜線・用途制限", "basis": {"text": "建ぺい率は建築面積÷敷地面積、容積率は延べ床面積÷敷地面積。前面道路幅員12m未満は容積率を道路幅×乗数と指定値の小さい方で適用（建築基準法52条2項）。用途地域ごとに建築物の制限があります。", "example": ""}, "reason": {"text": "建ぺい率60÷150=40%<50%、容積率は前面道路6m×4/10=240%と指定100%を比較して小さい方100%が適用→100÷150≒66.7%<100%、高さ8m<10m。すべての制限をクリアしています。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">建築基準法のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建ぺい率</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">建築面積÷敷地面積</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">延べ床面積÷敷地面積</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">前面道路12m未満</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">容積率は小さい方が上限</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">第1種低層</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">学校は建築可</text></svg>", "choices": [{"label": "容積率は道路幅員による制限で60%になる", "reason": "6m×4/10=240%と指定100%の小さい方=100%が適用されます（建築基準法52条2項）。60%という計算は誤りです。", "caution": "容積率の計算：min(前面道路幅員×係数, 指定容積率)（建築基準法52条2項）。"}, {"label": "建ぺい率は60%を超えているため違反", "reason": "建ぺい率60÷150=40%<50%なので適法です。「60%超」は誤りです。", "caution": ""}, {"label": "高さ8mは制限を超えている", "reason": "絶対高さ制限10mに対して8m<10mなので適法です。「制限超」は誤りです。", "caution": ""}], "summary": {"head": ["設問の計算（第一種低層住居専用地域）", "判定"], "rows": [["建ぺい率", "60÷150=40%<50%→適法"], ["容積率（道路幅員）", "6m×4/10=240%"], ["容積率（指定）", "100%"], ["適用容積率", "min(240%, 100%)=100%"], ["延べ面積", "100÷150≒66.7%<100%→適法"], ["高さ", "8m<10m→適法"]]}}},
  {id:10987,unit:'k_nochi',level:3,field:'limit',text:'農業法人Aは市街化調整区域内の農地（田・面積5000m2）の一部（1000m2）を太陽光発電設備の設置のために転用したいと考えている。また残り（4000m2）は引き続き農地として利用する予定であるが、Bという農業者に賃貸したいと考えている。この場合に関する記述として農地法の規定によれば正しいものはどれか。',opts:['農地の一部転用は自由にできる','太陽光発電のための農地転用（農地法4条）は都道府県知事の許可が必要（市街化調整区域内）。農地のBへの賃貸（農地法3条）は農業委員会の許可が必要','太陽光発電施設は農業施設のため農地法の適用外','農地の賃貸には許可は不要で届出のみ'],ans:1,exp:'①農地を太陽光発電のために転用（農地→農地以外）：農地法4条の転用許可が必要（市街化調整区域内のため都道府県知事許可）。②農地のBへの賃貸（農地→農地として利用・農地法3条）：農業委員会の許可が必要。農地のままBが農業利用する場合は農地法3条の問題、転用目的の場合は農地法4条・5条の問題となります。',"kaisetsu":{"topic": "農地法：3条は農業委員会・4条・5条は都道府県知事・市街化区域は届出のみ", "basis": {"text": "農地法3条（権利移動・農地→農地）の許可権者は農業委員会。4条（自己転用）・5条（転用目的の権利移動）は都道府県知事等。市街化区域内の農地転用（4・5条）は農業委員会への届出のみでOK。相続は許可不要・届出3か月以内。", "example": ""}, "reason": {"text": "太陽光発電のための農地転用（農地法4条）は市街化調整区域内の農地については都道府県知事の許可が必要です（農地法4条1項）。太陽光発電設備は農業施設ではないため農地法の適用除外にはなりません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">農地法の条文整理</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"82\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">条文</text><text x=\"227\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">行為</text><line x1=\"155\" y1=\"35\" x2=\"155\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"372\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">許可権者</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"517\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">市街化区域</text><line x1=\"445\" y1=\"35\" x2=\"445\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3条</text><text x=\"227\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利移動（農地→農地）</text><text x=\"372\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">農業委員会</text><text x=\"517\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">特例なし</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"82\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">4条</text><text x=\"227\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">自己転用</text><text x=\"372\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"82\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5条</text><text x=\"227\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">転用目的の権利移動</text><text x=\"372\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">都道府県知事等</text><text x=\"517\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">届出のみ</text></svg>", "choices": [{"label": "農地の一部転用は自由にできる", "reason": "農地の転用（一部でも）には農地法4条の許可が必要です（農地法4条1項）。「自由」は誤りです。", "caution": "太陽光発電のための農地転用：農地法4条の許可が必要（農地法4条1項）。"}, {"label": "太陽光発電施設は農業施設のため農地法の適用外", "reason": "太陽光発電施設は農業施設ではなく農地法の適用があります（農地法4条1項）。「適用外」は誤りです。", "caution": ""}, {"label": "農地の賃貸には許可は不要で届出のみ", "reason": "農地の賃貸（農地のまま使用）は農地法3条の許可が必要です（農地法3条1項）。", "caution": ""}], "summary": {"head": ["太陽光発電と農地法", "内容"], "rows": [["太陽光発電のための転用", "農地法4条・5条の許可対象"], ["市街化区域内", "農業委員会への届出で足りる"], ["市街化調整区域内", "都道府県知事の許可が必要"]]}}},
  {id:10988,unit:'t_joto',level:3,field:'tax',text:'AはAA市内に所有する事業用土地（所有期間20年・事業用に使用中）を売却し、売却益（長期譲渡所得）2500万円が生じた。AはBB市内に新しい事業用土地を取得し、「特定の事業用資産の買換えの特例」（租税特別措置法37条）の適用を受けようとしている。この場合に関する記述として租税特別措置法の規定によれば正しいものはどれか。',opts:['買換え特例は居住用財産のみに適用される','「特定の事業用資産の買換えの特例」は要件を満たせば、譲渡所得の全部または一部の課税を繰り延べることができる','買換え特例の適用を受けると譲渡所得税が完全に免除される','この特例は相続により取得した土地には適用されない'],ans:1,exp:'特定の事業用資産の買換えの特例（租税特別措置法37条）は、一定の要件（所有期間10年超の事業用資産を売却し一定期間内に新たな事業用資産を取得等）を満たす場合に、課税を繰り延べる（将来に先送りする）制度です。免除ではなく繰延べです。居住用財産の特例（3000万円控除等）とは別の制度です。',"kaisetsu":{"topic": "譲渡所得：分離課税・長期は20%・3,000万円控除は3年に1回", "basis": {"text": "土地・建物の譲渡所得は分離課税（申告分離課税）。長期（5年超）の税率は合計20%（所得税15%+住民税5%）。短期（5年以下）は39%（所得税30%+住民税9%）。3,000万円特別控除は前年・前々年に適用があれば使えません（3年に1回）。", "example": ""}, "reason": {"text": ""}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">譲渡所得のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">課税方式</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">分離課税</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">長期（5年超）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計20%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">短期（5年以下）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">合計39%</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3,000万円控除</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">3年に1回の制限</text></svg>", "choices": [], "summary": {"head": [], "rows": []}}},
  {id:10989,unit:'r_baibai',level:3,field:'rights',text:'AはBとの間で甲土地（時価3000万円）の売買契約を締結した（代金3000万円）。契約後、甲土地が洪水により一部が浸水し損害が生じた。浸水被害は締結後・引渡し前に不可抗力で発生した。売主BはAに対して「このままの状態で引き渡すので代金全額3000万円を支払え」と要求している。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['不可抗力による被害なので、AはBの要求通り代金全額を支払わなければならない','Bが引き渡した甲土地が契約内容に適合していない（洪水被害により品質・機能が低下）場合、AはBに対して契約不適合責任（追完請求・代金減額請求・解除等）を主張できる。AはBの不可抗力の主張に対して代金の減額や解除を求めることができる','契約後の不可抗力リスクは買主Aが全部負担する','Bに帰責事由がないため一切の責任を免れる'],ans:1,exp:'2020年改正民法では、契約不適合責任（民法562条・563条）は売主の帰責事由の有無にかかわらず成立します（無過失責任）。引き渡された目的物が契約内容に適合しない場合（洪水被害による品質低下等）、AはBに対して追完請求・代金減額請求・場合によっては解除を主張できます。ただし損害賠償はBに帰責事由がある場合に限られます（民法564条・民法415条）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "目的物が引渡し前に不可抗力で損傷した場合、買主は反対給付の履行拒絶ができます（民法536条1項）。また目的物が契約内容に適合していない（洪水被害）場合は契約不適合責任（追完・減額・解除等）も主張できます（民法562条以下）。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "不可抗力なのでAはBの要求通り代金全額を支払わなければならない", "reason": "引渡し前の損傷では買主は代金支払いを拒絶できます（民法536条1項）。また契約不適合責任（減額・解除等）も主張できます。", "caution": "引渡し前の滅失・損傷＝危険負担→買主は支払い拒絶可。"}, {"label": "契約後の不可抗力リスクは買主Aが全部負担する", "reason": "2020年改正後、危険負担は「買主危険主義」から「履行拒絶権（実質売主主義）」に変更されました（民法536条1項）。「全部買主負担」は誤りです。", "caution": ""}, {"label": "Bに帰責事由がないため一切の責任を免れる", "reason": "Bに帰責事由がなくても買主Aは代金減額・解除・履行拒絶ができます（民法536条1項・562条以下）。", "caution": ""}], "summary": {"head": ["引渡し前の損傷（改正後）", "買主の選択肢"], "rows": [["履行拒絶", "代金支払い拒絶（民法536条1項）"], ["追完請求", "修補・代替品等（民法562条）"], ["代金減額", "相当額の減額（民法563条）"], ["解除", "解除して代金返還（民法536条・541条）"]]}}},
  {id:10990,unit:'r_chinshaku',level:3,field:'rights',text:'AはBから甲マンション（専有部分）を賃借し月額賃料15万円を支払っている。Bは甲マンションを担保にC銀行から融資を受け、C銀行はBの甲マンションに抵当権（第一順位）を設定していた。その後BがC銀行への返済ができず、C銀行が抵当権を実行して競売にかけた。甲マンションをDが競落した。この場合に関する記述として民法及び借地借家法の規定によれば正しいものはどれか。',opts:['AはDに対して賃借権を主張でき、引き続き居住できる','C銀行の抵当権はAの賃借権より先に設定されているため、AはDに対して賃借権を対抗できない場合がある（引渡しによる対抗要件の有無・設定時期による）。もしAが抵当権設定後に賃借権を取得した場合はDに対抗できない可能性が高い','競落人DはAの賃借権を当然に引き継ぐ','Aは競落後6か月は退去しなくてよい'],ans:1,exp:'建物の賃借権は建物の引渡しを受けることで対抗要件を取得します（借地借家法31条）。C銀行の抵当権設定後にAが賃借権を取得した場合、AはDに対して賃借権を対抗できません（民法177条・605条）。Aが対抗要件を備えていない場合、Dは競落後にAに退去を求めることができます（ただし明渡し猶予制度（旧・短期賃貸借保護）は廃止済み）。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "抵当権と賃借権の優先関係は、権利の先後（登記日等）で決まります（民法177条）。抵当権設定後に賃借権を取得した賃借人は、抵当権の実行（競売）後の新所有者（競落人）に賃借権を対抗できません。建物明渡猶予制度（民法395条）により6か月の猶予があります。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "AはDに対して賃借権を主張でき引き続き居住できる", "reason": "C銀行の抵当権がAの賃借権より先に設定されている場合、AはDに賃借権を対抗できません（民法177条）。", "caution": "抵当権>後順位の賃借権。競落後は賃借権で対抗不可。"}, {"label": "競落人DはAの賃借権を当然に引き継ぐ", "reason": "抵当権設定後の賃借権は競落人に引き継がれません（民法177条）。抵当権設定前の賃借権は引き継がれます。", "caution": ""}, {"label": "Aは競落後6か月は退去しなくてよい", "reason": "建物明渡猶予制度（民法395条1項）により、競落人からの明渡しに対して6か月の猶予が認められます。ただしこれは完全に「退去しなくてよい」わけではありません。", "caution": ""}], "summary": {"head": ["抵当権と賃借権の優劣", "内容"], "rows": [["抵当権設定前の賃借権", "競落人に対抗可（賃貸借継続）"], ["抵当権設定後の賃借権", "競落人に対抗不可（明渡しを求められる）"], ["建物明渡猶予（民法395条）", "対抗できない場合でも競落後6か月の猶予"]]}}},
  {id:10991,unit:'l_menkyo',level:3,field:'law',text:'宅建業者A（法人・甲県知事免許）は、取締役会の決議を経て、主たる事務所の所在地を甲県X市から甲県Y市に移転することにした。また、代表取締役の変更（BからCへ）および商号の変更（「A不動産」から「A住宅」へ）も行った。これらについて宅建業法上必要な手続きとして正しいものはどれか。',opts:['事務所の移転・役員の変更・商号の変更はいずれも甲県知事への届出または変更申請が必要','事務所の移転・役員の変更・商号の変更はいずれも免許の変更申請（免許換え）が必要','同一都道府県内の事務所移転は届出不要','代表取締役の変更のみ届出が必要で商号変更は不要'],ans:0,exp:'宅建業者の氏名・商号・名称・主たる事務所・従たる事務所の所在地・役員（代表者・取締役等）に変更があった場合は、変更後30日以内に免許権者（甲県知事）に届け出なければなりません（宅建業法9条・11条）。なお同一都道府県内の移転は免許換えは不要ですが、変更の届出は必要です。',"kaisetsu":{"topic": "宅建業の免許：知事・大臣免許の区別・有効期間5年・欠格事由", "basis": {"text": "1都道府県のみ→知事免許、2以上の都道府県→大臣免許（宅建業法3条）。有効期間は5年。欠格事由（拘禁刑以上・宅建業法違反罰金等）は執行終了等から5年間です。", "example": ""}, "reason": {"text": "宅建業者が事務所の移転・役員の変更・商号の変更を行った場合は免許権者への届出または変更申請が必要です（宅建業法9条）。これらは変更届の対象であり、都道府県をまたがない場合は免許換えは不要です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">宅建業免許のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">1都道府県</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知事免許</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">2以上の都道府県</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">大臣免許</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">有効期間</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">欠格期間</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年（拘禁刑以上・特定罰金等）</text></svg>", "choices": [{"label": "事務所の移転・役員の変更・商号の変更はいずれも免許の変更申請（免許換え）が必要", "reason": "これらは免許換えではなく変更届の対象です（宅建業法9条）。免許換えは都道府県をまたがる場合等に必要です（同法7条）。", "caution": "変更届（宅建業法9条）と免許換え（同法7条）を区別しましょう。"}, {"label": "同一都道府県内の事務所移転は届出不要", "reason": "事務所の移転は変更届の対象です（宅建業法9条）。届出不要ではありません。", "caution": ""}, {"label": "代表取締役の変更のみ届出が必要で商号変更は不要", "reason": "商号変更も変更届の対象です（宅建業法9条）。「代表取締役の変更のみ」は誤りです。", "caution": ""}], "summary": {"head": ["変更届の主な対象事項（宅建業法9条）", "内容"], "rows": [["商号・名称", "変更届が必要"], ["代表者・役員", "変更届が必要"], ["事務所の所在地", "変更届が必要"], ["専任宅建士", "変更届が必要"], ["免許換えが必要な場合", "都道府県をまたがる場合等（宅建業法7条）"]]}}},
  {id:10992,unit:'l_jusetsu',level:3,field:'law',text:'宅建業者Aは、B所有の一棟マンション（8室・築30年）の売買を媒介した。このマンションにはエレベーターはなく、1室（2階・C居住）の賃貸借が継続中である。重要事項説明において「既存建物状況調査（インスペクション）の結果」について記載が必要かどうか確認している。この場合に関する記述として宅建業法の規定によれば正しいものはどれか。',opts:['インスペクションは任意であり重要事項説明書への記載は不要','既存建物の売買では、インスペクションの実施の有無と、実施されている場合はその結果を35条書面（重要事項説明書）に記載しなければならない（宅建業法35条1項14号・施行令3条1項12号）','インスペクションが実施されていない場合は記載不要','一棟マンションの売買はインスペクションの対象外'],ans:1,exp:'既存建物（中古建物）の売買においては、建物状況調査（インスペクション）の実施の有無を重要事項説明書に記載しなければなりません（宅建業法35条1項14号・施行令3条1項12号）。実施されている場合はその結果（調査報告書等）の概要も記載が必要です。実施されていない場合はその旨を記載します。一棟マンションも既存建物であり対象となります。',"kaisetsu":{"topic": "重要事項説明：宅建士が説明・売主への交付は不要・IT重説も可", "basis": {"text": "重要事項説明は宅建士が宅建士証を提示して行います（宅建業法35条）。買主（借主）への交付が必要で売主への交付義務はありません。相手方が業者なら説明省略可（書面交付は必要）。2021年改正でIT重説も可能です。", "example": ""}, "reason": {"text": "既存建物の売買では、インスペクション（建物状況調査）の実施の有無と実施している場合はその結果を35条書面に記載しなければなりません（宅建業法35条1項14号・施行令3条1項12号）。実施していない場合は「実施なし」の旨を記載します。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">重要事項説明のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明できる者</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士（宅建士証の提示必須）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付先</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">買主・借主（売主・貸主は不要）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">相手方が業者</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">説明省略可・書面交付は必要</text></svg>", "choices": [{"label": "インスペクションは任意であり重要事項説明書への記載は不要", "reason": "インスペクションの実施の有無の記載は義務です（宅建業法35条1項14号等）。任意ではありません。", "caution": "インスペクションの実施有無：35条書面への記載義務（宅建業法35条1項14号）。"}, {"label": "インスペクションが実施されていない場合は記載不要", "reason": "実施されていない場合も「実施していない旨」の記載が必要です（宅建業法35条1項14号等）。", "caution": "未実施でも「未実施の旨」の記載が必要。"}, {"label": "一棟マンションの売買はインスペクションの対象外", "reason": "一棟マンションの売買でもインスペクションの実施有無の記載義務があります（宅建業法35条1項14号）。「対象外」は誤りです。", "caution": ""}], "summary": {"head": ["インスペクション（建物状況調査）の記載（宅建業法35条1項14号）", "内容"], "rows": [["実施がある場合", "実施の旨＋調査結果（概要）を記載"], ["実施がない場合", "「実施していない旨」を記載"], ["対象", "既存（中古）建物の売買"], ["実施義務", "業者に実施義務はなし（記載義務のみ）"]]}}},
  {id:10993,unit:'k_sonota',level:3,field:'limit',text:'AはCC市内の都市計画区域内の土地を購入し、小規模な工場（床面積300m2）を建築しようとしている。この土地の用途地域は「工業専用地域」に指定されている。工業専用地域において建築できない建築物として建築基準法の規定によれば正しいものはどれか。',opts:['工場（床面積300m2以下）','住宅','工業系の倉庫','研究所'],ans:1,exp:'工業専用地域は工業の利便を増進するため定める地域であり（都市計画法9条12項）、住宅・共同住宅・寄宿舎・下宿・学校・病院・ホテル・旅館等は建築できません（建築基準法別表第二）。工場・倉庫・研究所等は建築可能です。工業専用地域は工業用途に特化しており、居住系の建築物は一切認められません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "工業専用地域は専ら工業用途のための地域であり、住宅は建築できません（建築基準法別表第二）。工場・倉庫・研究所等は建築できますが、住宅・共同住宅等は一切建築できません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "工場（床面積300m2以下）", "reason": "工業専用地域では工場は建築できます（建築基準法別表第二）。", "caution": "工業専用地域で建築できないもの：住宅（建築基準法別表第二）。"}, {"label": "工業系の倉庫", "reason": "工業専用地域では倉庫は建築できます（建築基準法別表第二）。", "caution": ""}, {"label": "研究所", "reason": "工業専用地域では研究所は建築できます（建築基準法別表第二）。", "caution": ""}], "summary": {"head": ["工業専用地域で建築できないもの（建築基準法別表第二）", "内容"], "rows": [["住宅・共同住宅", "不可（工業専用地域唯一の禁止用途）"], ["工場・倉庫・研究所", "可"]]}}},
  {id:10994,unit:'r_souzoku',level:3,field:'rights',text:'Aは遺言を残して死亡した。遺言書には「土地甲はBに遺贈する、建物乙はCに遺贈する、預金はDに相続させる」と記されていた。相続人はBのみ（BはAの子）である。CとDはAの友人（相続人ではない）。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['相続人でないCとDへの遺贈は無効','Bへの遺贈（土地甲）・CへのAの遺贈（建物乙）・DへのAの遺贈（預金）はいずれも有効。相続人以外への遺贈（特定遺贈）も有効であり、C・Dは受遺者として各財産を取得できる','遺贈は相続人にしかできない','Bが相続人として全財産を相続し、C・Dへの遺贈は無効'],ans:1,exp:'遺贈（民法964条）は相続人以外の者（法人を含む）に対しても行うことができます。BへのA（土地甲）・CへのA（建物乙）・DへのA（預金）への遺贈はいずれも有効です（特定遺贈）。ただし相続人Bに最低限度の遺留分（財産の1/2）が認められており、遺留分を侵害する場合はBは遺留分侵害額請求権を行使できます。',"kaisetsu":{"topic": "相続：法定相続分・放棄は3か月・遺留分は1/2", "basis": {"text": "配偶者と子の場合は各1/2（民法900条）。相続放棄は3か月以内に家庭裁判所へ（民法915条）。遺留分は直系卑属・配偶者は法定相続分の1/2です（民法1042条）。遺産分割協議は全員合意が必要です。", "example": ""}, "reason": {"text": "遺贈は遺言により財産を贈与する行為であり、相続人以外の第三者にも可能です（民法964条）。相続人への遺贈も相続人以外への遺贈（特定遺贈）も有効です。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">相続の主要ポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">配偶者+子の相続分</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">各1/2</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">放棄の期間</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">知った時から3か月以内（家裁）</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺留分</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">直系卑属・配偶者は法定相続分の1/2</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">遺産分割協議</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全員合意</text></svg>", "choices": [{"label": "相続人でないCとDへの遺贈は無効", "reason": "相続人以外への遺贈も有効です（民法964条）。相続人であることは遺贈の要件ではありません。", "caution": "遺贈の受遺者は相続人以外でも可（民法964条）。"}, {"label": "遺贈は相続人にしかできない", "reason": "遺贈は相続人以外の第三者・法人・団体等にもできます（民法964条）。", "caution": ""}, {"label": "Bが相続人として全財産を相続し、C・Dへの遺贈は無効", "reason": "遺言による遺贈が有効であれば、Bは遺言に従った財産のみ相続します。C・Dへの遺贈は有効です（民法964条）。", "caution": ""}], "summary": {"head": ["遺贈の種類", "内容"], "rows": [["特定遺贈", "特定の財産を指定して遺贈（民法964条）"], ["包括遺贈", "遺産の何分のいくつを遺贈"], ["受遺者", "相続人・第三者・法人等いずれも可"], ["放棄", "特定遺贈：いつでも放棄可（民法986条）"]]}}},
  {id:10995,unit:'l_37jo',level:3,field:'law',text:'宅建業者Aが媒介した建物の賃貸借契約において、賃貸人B・賃借人C（いずれも宅建業者でない）の間で次の合意がなされた：月額賃料12万円・敷金24万円（賃料2か月分）・礼金12万円（賃料1か月分）・賃貸借期間2年・更新料（更新時に賃料1か月分）。37条書面に記載しなければならない事項として宅建業法の規定によれば正しいものはどれか。',opts:['敷金・礼金・更新料は任意的記載事項であり、記載しなくてもよい','賃貸借に関する37条書面には賃料・支払時期・方法（12万円・毎月払い等）・賃貸借期間（2年）を記載しなければならない。敷金（民法622条の2に関連する定め）も定めがある場合に記載する任意的記載事項','賃貸借の37条書面は任意的なもの','37条書面には賃料のみ記載すればよい'],ans:1,exp:'賃貸借に関する37条書面（宅建業法37条2項）の必要的記載事項には賃料・賃貸借の期間等が含まれます。敷金・礼金・更新料は「金銭の保管・取扱いに関する定め」として定めがある場合に記載する任意的記載事項（同法37条2項4号・施行規則16条の4の5）です。ただし実務上はこれらを記載することが一般的です。',"kaisetsu":{"topic": "37条書面：全取引で交付・記名（押印不要）・移転登記申請時期は必要的記載事項", "basis": {"text": "37条書面は売買・交換・賃貸借の全取引で契約の双方当事者に交付が義務（宅建業法37条）。引渡し時期・移転登記申請時期は必要的記載事項。2021年改正で押印は不要になり記名のみで足ります。", "example": ""}, "reason": {"text": "賃貸借の37条書面では賃料・支払時期・支払方法・賃貸借期間を記載しなければなりません（宅建業法37条2項）。敷金に関する定めは任意的記載事項です（同条2項3号）。礼金・更新料も定めがある場合に記載する事項です。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">37条書面のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">交付義務</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全取引・双方当事者</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">必要的記載</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">引渡時期・移転登記申請時期等</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">宅建士の関与</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">記名（押印不要）</text></svg>", "choices": [{"label": "敷金・礼金・更新料は任意的記載事項であり記載しなくてもよい", "reason": "敷金に関する定めは任意的記載事項（定めがある場合）ですが（宅建業法37条2項3号）、定めがある場合は記載しなければなりません。「記載しなくてもよい」は誤りです。", "caution": "定めがある場合の任意的記載事項→定めがある場合は記載義務あり。"}, {"label": "賃貸借の37条書面は任意的なもの", "reason": "賃貸借にも37条書面の交付義務があります（宅建業法37条2項）。「任意」は誤りです。", "caution": ""}, {"label": "37条書面には賃料のみ記載すればよい", "reason": "賃料のほか支払時期・支払方法・賃貸借期間等の記載が必要です（宅建業法37条2項）。「賃料のみ」は誤りです。", "caution": ""}], "summary": {"head": ["賃貸借の37条書面（宅建業法37条2項）", "必要的/任意的"], "rows": [["賃料・支払時期・方法", "必要的"], ["賃貸借期間", "必要的"], ["敷金に関する定め", "任意的（定めがある場合）"], ["礼金・更新料", "任意的（定めがある場合）"]]}}},
  {id:10996,unit:'r_touki',level:3,field:'rights',text:'A所有の甲土地に、BがAに無断で甲土地をC名義に所有権移転登記した（偽造書類等を使用）。CはDに甲土地を売却し、CからDへの所有権移転登記が完了した。DはCが適法な所有者だと信じ（善意）、過失はなかった。この場合に関する記述として民法の規定及び判例によれば正しいものはどれか。',opts:['不動産の登記には公信力があるため、善意無過失のDは所有権を取得できる','不動産の登記には公信力がない（民法94条2項の類推適用が問題となる場合もあるが原則として）。Aは真の所有者としてDに対して所有権を主張できる可能性がある','DはCから登記を備えているため常に所有権を取得できる','登記には公信力があるため偽造登記でもDは保護される'],ans:1,exp:'不動産の登記には公信力がありません（日本法の原則）。Cへの登記はBによる偽造・無断の登記であり、A→Cへの所有権は移転していません。原則としてAはDに対して真の所有者として所有権を主張できます。ただし民法94条2項の類推適用（虚偽の外観を作出した場合の善意の第三者保護）が問題となる場合もありますが、Aに帰責事由がなければ適用されません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "日本の不動産登記には公信力がありません（通説・判例）。登記を信頼して取引しても、真の権利者から権利を主張される場合があります。動産の即時取得（民法192条）とは異なり、不動産では登記を信頼した者は保護されません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "不動産の登記には公信力があるため、善意無過失のDは所有権を取得できる", "reason": "不動産の登記には公信力がありません（通説・判例）。善意無過失であっても偽造登記に基づいて所有権を取得できない場合があります。", "caution": "動産の即時取得（公信の原則あり）と不動産の登記（公信力なし）を混同しないこと。"}, {"label": "DはCから登記を備えているため常に所有権を取得できる", "reason": "不動産に公信力がないため、登記を備えていても真の権利者から権利を主張される場合があります。", "caution": ""}, {"label": "登記には公信力があるため偽造登記でもDは保護される", "reason": "不動産登記には公信力がないため、偽造登記を信頼した者は原則として保護されません。ただし民法94条2項の類推適用で保護される場合があります（判例）。", "caution": ""}], "summary": {"head": ["不動産登記の公信力", "内容"], "rows": [["原則", "公信力なし（通説・判例）"], ["例外（判例）", "民法94条2項類推適用で善意無過失の第三者を保護する場合あり"], ["動産との違い", "動産＝即時取得で公信の原則あり、不動産＝公信力なし"]]}}},
  {id:10997,unit:'r_fuhoko',level:3,field:'rights',text:'AはBに対して不当利得（民法703条）の返還を請求したいと考えている。BはAの誤振込（Aが誤ってBの口座に100万円を振り込んだ）により利益を得た。Bはこの100万円で遊興費に使ってしまったが、Bは誤振込であることを知っていた（悪意）。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['Bが利益を消費してしまったため返還義務は消滅する','Bが悪意（誤振込であることを知っていた）の不当利得者である場合、受けた利益に利息を付けて返還し、損害があれば損害賠償も要する（民法704条）。Bはすでに消費しても100万円の返還義務を免れない','善意の場合も悪意の場合も返還義務は同じ','誤振込による不当利得は成立しない'],ans:1,exp:'悪意の不当利得者（誤振込であることを知っていたB）は、受けた利益に利息を付けて返還しなければなりません（民法704条）。さらに損害があれば損害賠償も必要です。善意の不当利得者（同法703条）は現に利益を受けている部分（現存利益）のみを返還すれば足りるのとは異なり、悪意者は全額の返還義務を負います。Bがすでに消費していても100万円の返還義務を免れません。',"kaisetsu":{"topic": "宅建士試験 重要論点の整理", "basis": {"text": "この問題は宅建士試験の重要論点を扱っています。解説文（exp）の内容を確認し、正解の根拠と誤りの理由をしっかり理解してください。宅建士試験では似た内容の問題が繰り返し出題されます。", "example": ""}, "reason": {"text": "悪意の不当利得者は受けた利益に利息を付けて返還し、なお損害があれば賠償しなければなりません（民法704条）。善意の不当利得者は現存利益の返還で足りますが（民法703条）、悪意の場合は消費しても返還義務を免れません。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">学習のポイント</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">項目</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">内容</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">正解の根拠</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">条文・判例に基づいた根拠を確認</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">誤りの選択肢</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">どこがどのように誤りなのかを理解</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">関連論点</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">類似の論点との比較で理解を深める</text></svg>", "choices": [{"label": "Bが利益を消費してしまったため返還義務は消滅する", "reason": "悪意の不当利得者は利益を消費しても返還義務は消滅しません（民法704条）。善意なら現存利益のみですが、悪意なら全額返還が必要です。", "caution": "善意→現存利益返還（消費すれば減少）。悪意→全額返還（消費しても免れない）。"}, {"label": "善意の場合も悪意の場合も返還義務は同じ", "reason": "善意（民法703条・現存利益返還）と悪意（民法704条・全額＋利息＋損害賠償）では返還義務が異なります。", "caution": ""}, {"label": "誤振込による不当利得は成立しない", "reason": "誤振込は法律上の原因なく利益を得た典型的な不当利得です（民法703条）。成立しないというのは誤りです。", "caution": ""}], "summary": {"head": ["善意・悪意の不当利得", "返還義務"], "rows": [["善意の受益者", "現存利益の返還（民法703条）"], ["悪意の受益者", "利益の全額＋利息＋損害賠償（民法704条）"], ["消費した場合", "善意：消費分は減少。悪意：消費しても免れない"]]}}},
  {id:10998,unit:'r_jiko',level:3,field:'rights',text:'AはBに対して売買代金300万円の債権（弁済期：2022年1月1日）を有している。Bは弁済期に支払いをしなかったため、Aは2022年4月1日にBに対して催告（書面）を行った。その後、Aは2023年3月1日に訴訟を提起した。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['催告（書面）により時効が更新されるため、2022年4月1日から新たに5年の時効が進行する','催告は時効を更新するのではなく、時効の完成を6か月猶予するにすぎない。催告から6か月以内に裁判上の請求等を行わなければ時効の完成猶予の効力が消滅する。Aが2022年4月1日に催告し、6か月後（2022年10月1日）までに提訴等をしなければ猶予効力は消滅する。2023年3月1日の提訴はこの6か月を超えているため催告の効力が消滅している可能性がある','催告は効力がなく時効に関係しない','売買代金の時効は10年である'],ans:1,exp:'催告は時効の完成を6か月間猶予する効力があります（民法150条）。催告から6か月以内に裁判上の請求等（提訴・支払督促等）を行わなければ猶予効力が消滅します。2022年4月1日の催告から6か月後は2022年10月1日です。2023年3月1日の提訴はこの期限を大幅に超えており、催告による猶予効力は消滅しています。ただし元の時効（弁済期2022年1月1日から5年）はまだ完成していない（2027年1月1日が完成日）ため、提訴自体は有効です。',"kaisetsu":{"topic": "消滅時効：知った時から5年または行使可能時から10年", "basis": {"text": "一般の債権の消滅時効は「権利行使できると知った時から5年」または「権利行使できる時から10年」のいずれか早い方で完成します（民法166条1項）。時効は援用して初めて効力が発生します（民法145条）。", "example": ""}, "reason": {"text": "催告（民法150条）は時効の完成を6か月間猶予しますが、更新はしません。催告から6か月以内に裁判上の請求等をしなければ猶予の効力が消滅します。設問では催告（2022年4月1日）から6か月後（2022年10月1日）までに提訴等が必要ですが、2023年3月1日の提訴はこれを超えています。"}, "svg": "<svg viewBox=\"0 0 620 195\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">消滅時効の期間</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">起算点</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">時効期間</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"195\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できると知った時</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">権利行使できる時（客観）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">10年</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">人の生命・身体への損害</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">5年または20年</text></svg>", "choices": [{"label": "催告（書面）により時効が更新されるため、2022年4月1日から新たに5年の時効が進行する", "reason": "催告は完成猶予のみで更新はしません（民法150条1項）。更新のためには訴訟提起等が必要です。", "caution": "催告＝完成猶予（6か月）のみ。更新≠催告。"}, {"label": "催告は効力がなく時効に関係しない", "reason": "催告は時効の完成を6か月間猶予する効力があります（民法150条1項）。", "caution": ""}, {"label": "売買代金の時効は10年である", "reason": "2020年改正後、売買代金債権の消滅時効は「権利行使できると知った時から5年」です（民法166条1項1号）。10年は客観的起算点からの期間です（同条1項2号）。", "caution": ""}], "summary": {"head": ["催告の手順", "内容"], "rows": [["①催告", "完成猶予（6か月間）開始"], ["②6か月以内に訴訟提起等", "完成猶予が継続→確定後に更新"], ["③6か月超えて提訴等しない", "猶予効力消滅→時効が完成していれば援用可能"]]}}},
  {id:10999,unit:'l_hoshu',level:3,field:'law',text:'宅建業者Aは、DD市内の農地（市街化調整区域・面積3000m2・売買代金2000万円）の売買を媒介した。この農地は農地法5条の許可を条件として売買され、許可取得後に引渡しが行われる予定である。AがBから受け取ることができる媒介報酬の上限額（税別）として宅建業法の規定（報酬告示）によれば正しいものはどれか。',opts:['農地の売買には報酬告示は適用されない','売買代金2000万円の媒介報酬の上限（税別）は2000万円×3%+6万円=66万円','農地法の許可が条件のため売買代金2000万円×2%=40万円が上限','2000万円の農地売買は高額のため報酬上限はない'],ans:1,exp:'宅建業者の媒介報酬の上限は売買代金に基づいて計算されます（報酬告示）。農地であっても宅地建物取引業者が媒介する場合は報酬告示が適用されます（農地の媒介も宅建業の対象）。2000万円×3%+6万円=66万円（税別）が上限です。農地法の許可が条件であっても、売買代金2000万円が課税標準となります。',"kaisetsu":{"topic": "報酬：売買は代金×3%+6万（400万超）・賃貸は借賃1か月・上限超過は不可", "basis": {"text": "売買媒介報酬（400万超）の一方からの上限は代金×3%+6万円（税別）。双方合計は一方上限×2。賃貸媒介（居住用・非居住用とも）は借賃1か月分。依頼者の承諾があっても上限超過は不可。", "example": ""}, "reason": {"text": "農地の売買にも宅建業法の報酬告示が適用されます。農地法の許可条件は報酬計算の基礎には影響しません。代金2000万円の速算式は2000万円×3%＋6万円＝66万円（税別）です（告示）。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">報酬の上限</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"155\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">対象</text><text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">上限</text><line x1=\"300\" y1=\"35\" x2=\"300\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（400万超）</text><text x=\"445\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×3%+6万（一方）</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">売買（200万以下）</text><text x=\"445\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">代金×5%</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">賃貸（双方合計）</text><text x=\"445\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">借賃1か月分</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"155\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">低廉な空家等（800万円以下）</text><text x=\"445\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">30万円まで（説明・合意要）</text></svg>", "choices": [{"label": "農地の売買には報酬告示は適用されない", "reason": "農地の売買にも宅建業法の報酬告示が適用されます（告示・宅建業法46条）。農地だから適用外ではありません。", "caution": "農地の売買にも報酬告示は適用される（告示）。"}, {"label": "農地法の許可が条件のため売買代金2000万円×2%=40万円が上限", "reason": "農地法の許可条件は報酬計算に影響しません（告示）。2000万円×3%＋6万円＝66万円が正しい上限です。", "caution": ""}, {"label": "2000万円の農地売買は高額のため報酬上限はない", "reason": "金額の高低に関わらず報酬上限規制は適用されます（告示・宅建業法46条）。「上限なし」は誤りです。", "caution": ""}], "summary": {"head": ["設問の報酬計算", "内容"], "rows": [["代金", "2000万円"], ["速算式", "2000万円×3%＋6万円"], ["計算", "60万円＋6万円＝66万円（税別）"], ["農地法の影響", "報酬計算には影響しない"]]}}},
  {id:11000,unit:'r_ishi',level:3,field:'rights',text:'Aは意思能力が十分でない状態（重度の認知症）で、介護施設の職員Bに誘導されて自己所有の甲土地をBの友人Cに著しく低廉な価格（時価1000万円のところ100万円）で売却した。Aの成年後見人Dはこの売買契約を問題にしたいと考えている。この場合に関する記述として民法の規定によれば正しいものはどれか。',opts:['売買契約は有効であり、DはAの代わりに取り消せない','Aが意思能力を欠く状態でした法律行為は無効（民法3条の2）であり、Dは成年後見人としてAを代理してこの売買の無効確認や甲土地の返還を求めることができる。また詐欺・強迫による取消し（民法96条）も検討できる','意思能力の有無は本人でなければ主張できない','Cが低廉な価格で購入したことは問題ない'],ans:1,exp:'意思能力を欠く状態でした法律行為は無効です（民法3条の2）。成年後見人Dは成年被後見人Aを代理して甲土地売買の無効確認・返還請求ができます。また不当な勧誘（詐欺・強迫）があれば成年後見人による取消しも可能です（民法96条・120条）。消費者契約法（不当な勧誘による取消し）の適用も検討できます。成年後見人は被後見人の財産管理・法的権利の保護を行います。',"kaisetsu":{"topic": "意思表示の瑕疵：詐欺・強迫・錯誤・通謀虚偽表示", "basis": {"text": "意思表示の瑕疵には詐欺（取消し・善意無過失の第三者は保護）・強迫（取消し・全第三者に対抗可）・錯誤（取消し・善意無過失の第三者は保護）・通謀虚偽表示（無効・善意の第三者は保護）があります。", "example": ""}, "reason": {"text": "意思能力を欠く状態でした法律行為は無効です（民法3条の2）。成年後見制度は判断能力が常時不十分な者を保護するもので、後見人は本人を代理して無効確認や返還請求ができます。"}, "svg": "<svg viewBox=\"0 0 620 235\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Sans JP',sans-serif\"><text x=\"310\" y=\"22\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#333\">意思表示の瑕疵</text><rect x=\"10\" y=\"35\" width=\"600\" height=\"30\" rx=\"4\" fill=\"#e8e8ec\" stroke=\"#ccc\"/><text x=\"106\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">種類</text><text x=\"299\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">効果</text><line x1=\"203\" y1=\"35\" x2=\"203\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><text x=\"492\" y=\"55\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#444\">第三者</text><line x1=\"396\" y1=\"35\" x2=\"396\" y2=\"235\" stroke=\"#eee\" stroke-width=\"1\"/><rect x=\"10\" y=\"65\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">詐欺</text><text x=\"299\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"105\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">強迫</text><text x=\"299\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">全第三者に対抗可</text><rect x=\"10\" y=\"145\" width=\"600\" height=\"40\" fill=\"#f9f9f9\" stroke=\"#eee\"/><text x=\"106\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">錯誤</text><text x=\"299\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">取消し</text><text x=\"492\" y=\"170\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意無過失は保護</text><rect x=\"10\" y=\"185\" width=\"600\" height=\"40\" fill=\"#fff\" stroke=\"#eee\"/><text x=\"106\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">通謀虚偽表示</text><text x=\"299\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">無効</text><text x=\"492\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#333\">善意は保護</text></svg>", "choices": [{"label": "売買契約は有効であり、DはAの代わりに取り消せない", "reason": "意思能力を欠く状態での法律行為は無効です（民法3条の2）。後見人Dは代理人として無効確認等の主張ができます。", "caution": "意思能力欠如→無効（民法3条の2）。制限行為能力→取消しうる行為。この区別が重要です。"}, {"label": "意思能力の有無は本人でなければ主張できない", "reason": "後見人は本人の法定代理人として無効確認・返還請求等の法的主張を行う権限を持ちます（民法859条）。", "caution": ""}, {"label": "Cが低廉な価格で購入したことは問題ない", "reason": "著しく低廉な価格での取引は暴利行為として公序良俗違反（民法90条）の問題もあります。また介護施設職員による誘導は詐欺・強迫の可能性もあります。", "caution": ""}], "summary": {"head": ["判断能力の状態", "法的制度", "行為の効力"], "rows": [["完全に欠く（重度認知症等）", "意思無能力（民法3条の2）", "無効"], ["著しく不十分", "成年後見（民法7条）", "取消しうる（日常行為除く）"], ["不十分", "保佐（民法11条）", "重要行為のみ取消しうる"], ["不十分な場合あり", "補助（民法15条）", "特定行為のみ取消しうる"]]}}},

],
};

